def _stringify_scalar(value: object) -> str:
    unwrap = getattr(value, "unwrap_to_str", None)
    if callable(unwrap):
        return str(unwrap())
    return str(value)


def _row_column_values(raw: RawResult, column: str) -> list[str]:
    values: list[str] = []
    for row in raw:
        row_dict = dict(row) if not isinstance(row, dict) else row
        value = row_dict.get(column)
        if value is not None:
            values.append(str(value))
    return values


def _non_deleted_condition() -> Any:
    from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName
    from impl.common.l2100_sql_grammar.tree.enums import BinaryOp
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlParam
    from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp, SqlIsNull, sql_or

    deleted_col = SqlColumnRef(SqlColumnName("sys_deleted"))
    return sql_or(
        SqlIsNull(deleted_col),
        SqlBinaryOp(deleted_col, BinaryOp.EQ, SqlParam(False)),
    )


def _current_only_conditions(current_only: bool) -> list[Any]:
    if not current_only:
        return []

    from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef
    from impl.common.l2100_sql_grammar.tree.expr_ops import SqlIsNull

    return [
        SqlIsNull(SqlColumnRef(SqlColumnName("sys_valid_to_revision_id"))),
        _non_deleted_condition(),
    ]


def _branch_filter_conditions(branch_id_value: str | None) -> list[Any]:
    if branch_id_value is None:
        return []

    from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName
    from impl.common.l2100_sql_grammar.tree.enums import BinaryOp
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlParam
    from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp

    return [
        SqlBinaryOp(
            SqlColumnRef(SqlColumnName("branch_id")),
            BinaryOp.EQ,
            SqlParam(branch_id_value),
        ),
    ]


def _deleted_filter_conditions(include_deleted: bool) -> list[Any]:
    if include_deleted:
        return []
    return [_non_deleted_condition()]


# ═════════════════════════════════════════════════════════════════════
# FindObjectBranchesIntent
# ═════════════════════════════════════════════════════════════════════


class FindObjectBranchesIntent(IntentStep[list[BranchId]]):
    """L4: Find all branches containing a versioned object."""

    intent_tags = frozenset({"read", "versioned", "intent"})
    intent_cardinality = Cardinality.MANY
    intent_read_only = True

    def __init__(
        self: FindObjectBranchesIntent,
        ref_id: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        object_id: SysId,
        *,
        config: _FindObjectBranchesConfig,
    ) -> None:
        super().__init__(ref_id)
        self._model_cls = model_cls
        self._object_id = object_id
        self._config = config

    def schema_model_dependencies(self: FindObjectBranchesIntent) -> tuple[type[DatabaseObjectRow], ...]:
        """Declare the versioned model used by branch history lookup."""
        return (self._model_cls,)

    def lower(
        self: FindObjectBranchesIntent,
        ctx: object,
    ) -> Sequence[ServerPlanStep[Any]]:
        return [
            FindObjectBranchesStep(
                self.ref_id,
                self._model_cls,
                config=_FindObjectBranchesStepConfig(
                    object_id=self._object_id,
                    current_only=self._config.current_only,
                    domain=self._config.domain,
                ),
            ),
        ]


class _FindObjectBranchesStepCteRow(BaseModel):
    branch_id: BranchId


class FindObjectBranchesStep(SqlRelationPublisherStep[list[BranchId]]):
    """L0: SELECT DISTINCT branch_id FROM {sparse_table} WHERE sys_id = ?."""

    def cte_publication_contract(self: FindObjectBranchesStep) -> CtePublicationContract:
        columns = ("branch_id",)
        column_type_hints = SqlColumnTypeHints(uuid_columns=frozenset({"branch_id"}))
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        _contract_model_cls = _FindObjectBranchesStepCteRow
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=tuple(str(column) for column in columns),
            column_type_hints=column_type_hints,
            model_cls=_contract_model_cls,
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def __init__(
        self: FindObjectBranchesStep,
        ref_id: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        *,
        config: _FindObjectBranchesStepConfig,
    ) -> None:
        super().__init__(ref_id)
        self._model_cls = model_cls
        self._object_id = config.object_id
        self._object_id_value = _stringify_scalar(config.object_id)
        self._current_only = config.current_only
        self._domain = config.domain
        self._sparse_table = derive_versioned_table_names(VersionedBaseTableName(str(get_table_name(model_cls)))).sparse

    @property
    def level(self: FindObjectBranchesStep) -> int:
        return 0

    def result_cardinality(self: FindObjectBranchesStep) -> Cardinality:
        return Cardinality.MANY

    def is_read_only(self: FindObjectBranchesStep) -> bool:
        return True

    def step_tags(self: FindObjectBranchesStep) -> frozenset[str]:
        return frozenset({"read", "versioned", "grammar"})

    def tables_read(self: FindObjectBranchesStep) -> frozenset[str]:
        return frozenset({self._sparse_table})

    def tables_written(self: FindObjectBranchesStep) -> frozenset[str]:
        return frozenset()

    def compile(
        self: FindObjectBranchesStep,
        ctx: CompilationContext,
    ) -> CompiledStep[list[BranchId]]:
        from impl.common.l2050_sql_types.sql_branded_types import (
            SqlAliasName,
            SqlColumnName,
            SqlTableName,
        )
        from impl.common.l2100_sql_grammar.tree.clauses import (
            SqlFrom,
            SqlJoin,
            SqlSelectAlias,
            SqlSelectList,
            SqlTableAlias,
            SqlWhereClause,
        )
        from impl.common.l2100_sql_grammar.tree.enums import BinaryOp, JoinKind, UnaryOp
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlParam
        from impl.common.l2100_sql_grammar.tree.expr_ops import (
            SqlBinaryOp,
            SqlExists,
            SqlIsNull,
            SqlUnaryOp,
            sql_and,
            sql_or,
        )
        from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
        from impl.common.l2100_sql_grammar.tree.statements import SqlSelect

        sparse_table = SqlTableName(self._sparse_table)
        index_table = get_table_name(self._domain.revision_branch_index_model)
        sparse_alias = SqlAliasName("object_rows")
        start_alias = SqlAliasName("start_membership")
        end_alias = SqlAliasName("end_membership")
        conditions: list[Any] = [
            SqlBinaryOp(
                SqlColumnRef(SqlColumnName("sys_id"), qualifier=sparse_alias),
                BinaryOp.EQ,
