        ctx: CompilationContext,
    ) -> CompiledStep[MergeConflictView]:
        from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName, SqlTableName
        from impl.common.l2100_sql_grammar.tree.clauses import (
            SqlFrom,
            SqlSelectList,
            SqlTableAlias,
            SqlWhereClause,
        )
        from impl.common.l2100_sql_grammar.tree.enums import BinaryOp
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlParam
        from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp
        from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
        from impl.common.l2100_sql_grammar.tree.statements import SqlSelect

        conflict_id = self._conflict_id_raw
        source_table_name = _resolve_refetch_source_table_name(
            update_ref_id=self._update_ref_id,
            conflict_table=self._conflict_table,
            cte_refs=ctx.cte_refs,
        )
        source_table = SqlTableName(source_table_name)

        contract = self.cte_publication_contract()
        grammar = SqlSelect(
            SqlSelectList(
                [SqlColumnRef(SqlColumnName(column)) for column in contract.columns],
            ),
            SqlFrom(SqlTableAlias(SqlTableIdent(source_table))),
            where=SqlWhereClause(
                SqlBinaryOp(
                    SqlColumnRef(SqlColumnName("sys_id")),
                    BinaryOp.EQ,
                    SqlParam(_sys_id_bind_str(conflict_id)),
                ),
            ),
        )

        auxiliary_ctes: list[tuple[str, Any]] | None = None
        if self._update_ref_id is not None and source_table_name != self._conflict_table:
            cte_ref = ctx.cte_refs.get(self._update_ref_id)
            if isinstance(cte_ref, CteReference) and cte_ref.auxiliary_query is not None:
                auxiliary_ctes = [(cte_ref.ref_id, cte_ref.auxiliary_query)]

        __opa002_grammar_1086 = grammar
        output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(contract)
        return CompiledStep(
            grammar=__opa002_grammar_1086,
            needs_returning=True,
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
            closed_post_op=required_merge_conflict_view_post_op(str(conflict_id)),
            auxiliary_ctes=auxiliary_ctes,
        )


