def _requires_insert_from_query_permission(
    ctx: LoweringContext,
    model_cls: type[DatabaseObjectRow],
) -> bool:
    """Return whether the selected actor requires target-row INSERT checks."""
    from l4000_permissions.permission_enforcement import (
        get_query_permission_plan,
        model_has_enforcing_permission_scheme,
        model_policy_admits_everyone,
    )

    if not model_has_enforcing_permission_scheme(model_cls):
        return False
    if model_policy_admits_everyone(model_cls, action="insert"):
        return False
    insert_permission_plan = get_query_permission_plan(model_cls, action="insert")
    literal_session = ctx.session_id if isinstance(ctx.session_id, SessionId) else None
    return not (
        insert_permission_plan is not None
        and literal_session is not None
        and insert_permission_plan.bypasses_reserved_session(literal_session)
    )


