def _replacement_map(
    model_cls: type[DatabaseObjectRow],
    replacements: list[tuple[object, object]],
) -> dict[str, object]:
    from l1000_schema.schema_def import get_db_column_name

    replacement_map: dict[str, object] = {}
    for target_field, expression in replacements:
        field_name_attr = getattr(target_field, "name", None)
        field_name = field_name_attr if isinstance(field_name_attr, str) else str(target_field)
        replacement_map[get_db_column_name(model_cls, DynamicFieldName(field_name))] = expression
    return replacement_map


def _select_expr_for_target_column(
    target_column: str,
    source_model: type[DatabaseObjectRow],
    replacement_map: dict[str, object],
    *,
    qualify_source: bool = False,
) -> SqlRenderable:
    from impl.common.l2050_sql_types.sql_branded_types import SqlAliasName, SqlColumnName
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlParam
    from l1000_schema.table_utils import get_table_name

    if target_column in replacement_map:
        return _replacement_to_renderable(replacement_map[target_column], source_model)
    if _source_has_db_column(source_model, target_column):
        qualifier = SqlAliasName(get_table_name(source_model)) if qualify_source else None
        return SqlColumnRef(SqlColumnName(target_column), qualifier=qualifier)
    return SqlParam(None)


def _partitioned_ordinal_expr(
    config: _InsertFromQueryConfig,
    replacement_map: dict[str, object],
) -> SqlRenderable:
    from impl.common.l2050_sql_types.sql_branded_types import SqlAliasName, SqlColumnName, SqlFunctionName
    from impl.common.l2100_sql_grammar.domain.infra.stmt_dml_simple import SqlScalarSubquery
    from impl.common.l2100_sql_grammar.tree.clauses import SqlSelectList, SqlTableAlias
    from impl.common.l2100_sql_grammar.tree.enums import BinaryOp
    from impl.common.l2100_sql_grammar.tree.expr_compound import SqlFuncCall
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlParam
    from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp, sql_and
    from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
    from impl.common.l2100_sql_grammar.tree.statements import SqlSelect
    from l1000_schema.schema_def import get_db_column_name

    ordinal = config.partitioned_ordinal
    assert ordinal is not None
    target_alias = SqlAliasName("ordinal_target")
    ordinal_column = get_db_column_name(config.model_cls, DynamicFieldName(ordinal.target_field_name))
    predicates: list[SqlRenderable] = []
    for partition_field in ordinal.partition_fields:
        partition_column = get_db_column_name(config.model_cls, DynamicFieldName(partition_field.name))
        source_value = replacement_map.get(partition_column)
        if source_value is None:
            if not _source_has_db_column(config.source_model, partition_column):
                msg = f"partition field {partition_field.name!r} requires a source replacement"
                raise ValueError(msg)
            source_expr: SqlRenderable = SqlColumnRef(SqlColumnName(partition_column))
        else:
            source_expr = _replacement_to_renderable(source_value, config.source_model)
        predicates.append(
            SqlBinaryOp(
                SqlColumnRef(SqlColumnName(partition_column), qualifier=target_alias),
                BinaryOp.EQ,
                source_expr,
            ),
        )
    max_select = SqlSelect(
        select=SqlSelectList(
            [
                SqlFuncCall(
                    SqlFunctionName("MAX"),
                    [SqlColumnRef(SqlColumnName(ordinal_column), qualifier=target_alias)],
                ),
            ],
        ),
        from_=SqlTableAlias(SqlTableIdent(_sql_table_name(config.model_cls)), target_alias),
        where=sql_and(*predicates),
    )
    prior = SqlFuncCall(
        SqlFunctionName("COALESCE"),
        [SqlScalarSubquery(max_select), SqlParam(ordinal.start - 1)],
    )
    return SqlBinaryOp(prior, BinaryOp.ADD, SqlParam(1))


def _build_select_column_list(
    target_cols: list[str],
    source_model: type[DatabaseObjectRow],
    replacement_map: dict[str, object],
    *,
    generate_sys_id: bool = False,
    config: _InsertFromQueryConfig | None = None,
    compilation_context: CompilationContext,
    target_model: type[DatabaseObjectRow],
) -> SqlRenderable:
    from impl.common.l2070_server_plan.steps._compile_helpers import (
        cast_postgres_expr_for_db_column,
        get_write_metadata_plan_from_catalog,
    )
    from impl.common.l2100_sql_grammar.domain.infra.stmt_dml_simple import SqlColumnListFragment
    from impl.common.l2100_sql_grammar.domain.infra.expr_primitives import SqlGeneratedSysId

    write_plan = get_write_metadata_plan_from_catalog(compilation_context.planning_catalog, target_model)
    return SqlColumnListFragment(
        [
            cast_postgres_expr_for_db_column(
                backend_type=compilation_context.backend_type,
                write_plan=write_plan,
                db_column=target_col,
                expr=(
                    SqlGeneratedSysId()
                    if generate_sys_id and target_col == "sys_id" and target_col not in replacement_map
                    else _partitioned_ordinal_expr(config, replacement_map)
                    if config is not None
                    and config.partitioned_ordinal is not None
                    and target_col == config.partitioned_ordinal.target_field_name
                    else _select_expr_for_target_column(
                        target_col,
                        source_model,
                        replacement_map,
                        qualify_source=bool(getattr(config.source_query_spec, "joins", ())) if config is not None else False,
                    )
                ),
            )
            for target_col in target_cols
        ],
    )


@dataclass
class _InsertFilterSpec:
    model_cls: type[DatabaseObjectRow]
    filters: list[object]


def insert_from_query_filter_deps(exprs: Sequence[object]) -> frozenset[str]:
    """Keep every source filter dependency in the INSERT producer contract."""
    from impl.common.l2070_server_plan.steps._resolve import collect_query_spec_deps
    from l1000_schema.schema_def import DatabaseObjectRow

    return collect_query_spec_deps(_InsertFilterSpec(DatabaseObjectRow, list(exprs)))


def _build_filter_condition(
    filter_spec: object,
    source_model: type[DatabaseObjectRow],
    expr_converter: _ExpressionConverter,
) -> SqlRenderable | None:
    from l1000_schema.typed_field import Expression
    from l2060_query_builder.query_contracts import QueryFilter

    if not isinstance(filter_spec, QueryFilter):
        raise TypeError("Invalid INSERT filter; bind it to a SQL-visible source relation before INSERT planning")
    expr_obj = filter_spec.expression
    if isinstance(expr_obj, Expression):
        return expr_converter.convert(expr_obj)

    if filter_spec.column is None or filter_spec.operator is None:
        raise TypeError("INSERT filter has no declared column or supported expression")
    return expr_converter.convert(
        Expression(
            field=filter_spec.column,
            owner=source_model,
            operator=filter_spec.operator,
            value=filter_spec.value,
        )
    )


def _build_where_clause(
    exprs: list[object],
    source_model: type[DatabaseObjectRow],
    ctx: CompilationContext,
    consumed_cte_refs: list[Any] | None = None,
) -> SqlRenderable | None:
    from impl.common.l2100_sql_grammar.tree.clauses import SqlWhereClause
    from impl.common.l2100_sql_grammar.tree.expr_ops import sql_and
    from impl.common.l5200_sql_query.expression_grammar import ExpressionToGrammar

    if not exprs:
        return None

    from impl.common.l2070_server_plan.steps._compile_helpers import _resolve_server_ref_filters_to_cte

    spec = _InsertFilterSpec(source_model, list(exprs))
    conditions: list[SqlRenderable] = _resolve_server_ref_filters_to_cte(
        spec,
        ctx,
        consumed_cte_refs=consumed_cte_refs,
    )
    expr_converter = ExpressionToGrammar(source_model, compilation_context=ctx)
    for filter_spec in spec.filters:
        condition = _build_filter_condition(filter_spec, source_model, expr_converter)
        if condition is not None:
            conditions.append(condition)
    if not conditions:
        return None

    combined: SqlRenderable = conditions[0]
    for condition in conditions[1:]:
        combined = sql_and(combined, condition)
    return SqlWhereClause(combined)


def _build_order_by_items(
    order_by: list[tuple[str, str]],
    source_model: type[DatabaseObjectRow],
) -> SqlRenderable | None:
    from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName, SqlOrderDirection
    from impl.common.l2100_sql_grammar.domain.infra.stmt_dml_simple import SqlOrderByItems
    from impl.common.l2100_sql_grammar.tree.clauses import SqlOrderByItem
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef
