class _InsertFromVersionedQueryReturningIntent(IntentStep[list[Any]]):
    """Insert an exact typed projection from a versioned visible source relation."""

    intent_tags = frozenset({"write", "insert_from_query", "versioned_source", "intent"})
    intent_cardinality = Cardinality.MANY

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        config: _InsertFromVersionedQueryReturningIntentConfig,
        revision_id: ServerRef,
        domain: type[VersioningDomain],
    ) -> None:
        super().__init__(ref_id)
        self._prepared = config
        self._config = config.config
        self._revision_id = revision_id
        self._domain = domain

    def tables_read(self) -> frozenset[str]:
        return _insert_from_query_source_tables(self._config)

    def tables_written(self) -> frozenset[str]:
        from l1000_schema.table_utils import get_table_name

        return frozenset({get_table_name(self._config.model_cls)})

    def lower(self, ctx: LoweringContext) -> Sequence[ServerPlanStep[Any]]:
        from impl.common.l2070_server_plan.steps.intent_versioning_extended import (
            _lower_versioned_query_intent,
        )
        from impl.common.l2070_server_plan.steps.row_hydration import HydrateResolvedRowsStep

        projected_spec = self._prepared.projected_source_spec
        source_ref = ServerPlanRefId(f"{self.ref_id}.source")
        prepared_ref = ServerPlanRefId(f"{self.ref_id}.prepared")
        raw_ref = ServerPlanRefId(f"{self.ref_id}.raw")
        inserted_ref = ServerPlanRefId(f"{self.ref_id}.inserted")
        source_steps = _lower_versioned_query_intent(
            ref_id=source_ref,
            model_cls=self._config.source_model,
            query_spec=self._config.source_query_spec,
            revision_id=cast(Any, self._revision_id),
            domain=cast(Any, self._domain),
            after_refs=frozenset(),
            ctx=ctx,
        )
        return [
            *source_steps,
            _PrepareTargetRowsFromRelationStep(
                prepared_ref,
                config=self._config,
                source_ref=source_ref,
            ),
            _InsertPreparedRowsStep(
                raw_ref,
                model_cls=self._config.model_cls,
                rows_ref=prepared_ref,
                do_nothing_on_conflict=self._config.do_nothing_on_conflict,
            ),
            _SelectExistingPreparedRowsStep(
                inserted_ref,
                model_cls=self._config.model_cls,
                rows_ref=prepared_ref,
                after_ref=raw_ref,
            ),
            HydrateResolvedRowsStep(
                self.ref_id,
                source_ref=inserted_ref,
                model_cls=self._config.model_cls,
            ),
        ]


class _VersionedInsertFromQueryIntent(IntentStep[int]):
    intent_tags = frozenset({"write", "insert_from_query", "intent"})
    intent_cardinality = Cardinality.SCALAR

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        config: _InsertFromQueryConfig,
    ) -> None:
        super().__init__(ref_id)
        self._config = config

    def tables_read(self: _VersionedInsertFromQueryIntent) -> frozenset[str]:
        from l1000_schema.table_utils import get_table_name

        return frozenset({get_table_name(self._config.source_model)})

    def tables_written(self: _VersionedInsertFromQueryIntent) -> frozenset[str]:
        from l1000_schema.table_utils import get_table_name

        return frozenset({get_table_name(self._config.model_cls)})

    def lower(self, ctx: LoweringContext) -> Sequence[ServerPlanStep[Any]]:
        from impl.common.l2070_server_plan.steps.ensure_staged_commit import (
            EnsureStagedCommitStep,
            _EnsureStagedCommitConfig,
        )
        from impl.common.l2070_server_plan.steps.intent_query import _build_session_user_resolution
        from impl.common.l2070_server_plan.steps.versioned_query_steps import (
            VersionedInsertFromQueryL0Step,
            _VersionedInsertFromQueryConfig,
        )

        config = self._config
        leading_steps, user_id_ref_id = _build_session_user_resolution(
            owner_ref_id=self.ref_id,
            model_cls=config.source_model,
            ctx=ctx,
            permission_filtering_enabled=True,
        )
        steps: list[ServerPlanStep[Any]] = list(leading_steps)
        # Materialise _staged_commits metadata so same-connection staged reads
        # can discover rows produced by INSERT...SELECT.
        staged_commit_id_for_insert = ctx.staged_commit_id
        sc: VersionedStagingCtx | None = None
        ensure_staged_commit_step: ServerPlanStep[Any] | None = None
        if ctx.staging_ctx_factory is not None:
            staging_ctx_factory = cast("_VersionedStagingContextFactory", ctx.staging_ctx_factory)
            sc = staging_ctx_factory(config.model_cls)
            staged_commit_id_raw = getattr(sc, "staged_commit_id_raw")
            session_id_raw = getattr(sc, "session_id_raw")
            connection_id_raw = getattr(sc, "connection_id_raw")
            if staged_commit_id_raw is None:
                msg = "Versioned INSERT...SELECT requires a staged commit id"
                raise ValueError(msg)
            staged_commit_id_for_insert = str(StagedCommitId(staged_commit_id_raw))
            ensure_staged_commit_step = EnsureStagedCommitStep(
                ServerPlanRefId(f"{self.ref_id}_ensure_staged_commit"),
                getattr(sc, "domain"),
                getattr(sc, "literal_branch", None) or getattr(sc, "lazy_branch"),
                _EnsureStagedCommitConfig(
                    staged_commit_id_raw=StagedCommitId(staged_commit_id_raw),
                    connection_id_value=(ConnectionId(connection_id_raw) if connection_id_raw is not None else None),
                    session_id_raw=SessionId(session_id_raw) if session_id_raw is not None else None,
                ),
            )
        versioned_config = _VersionedInsertFromQueryConfig(
            source_model=config.source_model,
            exprs=list(config.exprs),
            order_by=list(config.order_by),
            limit=config.limit,
            offset=config.offset,
            replacements=list(config.replacements),
            excluded_fields=list(config.excluded_fields),
            branch_id=ctx.branch_id,
            staged_commit_id=staged_commit_id_for_insert,
            user_id_ref_id=user_id_ref_id,
        )
        insert_after_refs: tuple[ServerPlanRefId, ...] = ()
        if _requires_insert_from_query_permission(ctx, config.model_cls):
            from impl.common.l2070_server_plan.steps.insert_permission import (
                InsertPermissionAssertionStep,
            )

            from impl.common.l2070_server_plan.steps.intent_versioning_extended import (
                _ValidateVersionedUpsertManyPermissionStep,
                _VersionedBatchSourceOrder,
                _build_versioned_upsert_batch_plan_from_cte,
                _lower_versioned_query_intent,
            )
            from l1200_versioned_ids import RevisionId
            from l2070_batching.server_ref import ServerRefs

            source_spec = config.source_query_spec
            if source_spec is None:
                msg = "Versioned INSERT...SELECT permission checks require a source query specification"
                raise ValueError(msg)
            domain = ctx.versioning_domain
            if domain is None:
                msg = "Versioned INSERT...SELECT permission checks require an explicit versioning domain"
                raise ValueError(msg)
            permission_source_ref = ServerPlanRefId(f"{self.ref_id}.permission_source")
            permission_rows_ref = ServerPlanRefId(f"{self.ref_id}.permission_rows")
            permission_ref = ServerPlanRefId(f"{self.ref_id}.insert_permission")
            revision_ref = ServerRefs.scalar(RevisionId.current())
            permission_anchor_refs = frozenset(
                ref_id
                for ref_id in (
                    (ctx.lazy_branch_tip_materialization.ref_id if ctx.lazy_branch_tip_materialization is not None else None),
                    (ctx.lazy_revision.ref_id if ctx.lazy_revision is not None else None),
                )
                if ref_id is not None
            )
            steps.extend(
                _lower_versioned_query_intent(
                    ref_id=permission_source_ref,
                    model_cls=config.source_model,
                    query_spec=source_spec,
                    revision_id=revision_ref,
                    domain=domain,
                    after_refs=permission_anchor_refs,
                    include_current_staged_overlay=True,
                    raw_mode=True,
                    prefer_current_tip=True,
                    ctx=ctx,
                ),
            )
            prepare_permission_rows = _PrepareTargetRowsFromRelationStep(
                permission_rows_ref,
                config=config,
                source_ref=permission_source_ref,
            )
            from l4000_permissions.graph_inherited_scheme import (
                GraphInheritedPermissionScheme,
            )
            from l4000_permissions.permission_registry import get_permission_scheme

            scheme = get_permission_scheme(config.model_cls)
            if isinstance(scheme, GraphInheritedPermissionScheme):
                if sc is None:
                    msg = "Graph-inherited INSERT...SELECT requires versioned staging context"
                    raise ValueError(msg)
                if user_id_ref_id is None:
                    msg = "Graph-inherited INSERT...SELECT requires an explicit permission user ref"
                    raise ValueError(msg)
                permission_step: ServerPlanStep[Any] = _ValidateVersionedUpsertManyPermissionStep(
                    permission_ref,
                    model_cls=config.model_cls,
                    after_refs=frozenset(),
                    staging_ctx=sc,
                    batch_plan=_build_versioned_upsert_batch_plan_from_cte(
                        model_cls=config.model_cls,
                        source_step_ref=str(permission_rows_ref),
                        staging_ctx=sc,
                        ctx=ctx,
                        conflict_columns=None,
                        on_conflict=None,
                        source_order=_VersionedBatchSourceOrder.UNORDERED,
                    ),
                    user_id_ref_id=user_id_ref_id,
                )
            else:
                permission_step = InsertPermissionAssertionStep(
                    permission_ref,
                    config.model_cls,
                    source_ref=permission_rows_ref,
                    source_is_sequence=True,
                )
            steps.extend(
                [
                    prepare_permission_rows,
                    permission_step,
                ],
            )
            insert_after_refs = (permission_ref,)
            versioned_config = replace(
                versioned_config,
                after_refs=insert_after_refs,
            )

        if ensure_staged_commit_step is not None:
            steps.append(ensure_staged_commit_step)
            insert_after_refs = (
                *insert_after_refs,
                ensure_staged_commit_step.ref_id,
            )
            versioned_config = replace(
                versioned_config,
                after_refs=insert_after_refs,
            )

        steps.append(
            VersionedInsertFromQueryL0Step(
                self.ref_id,
                config.model_cls,
                versioned_config,
            ),
        )
        return steps


class _UnversionedInsertFromQueryIntent(IntentStep[int]):
    intent_tags = frozenset({"write", "insert_from_query", "intent"})
    intent_cardinality = Cardinality.SCALAR

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        config: _InsertFromQueryConfig,
    ) -> None:
        super().__init__(ref_id)
        self._config = config

    def tables_read(self) -> frozenset[str]:
        from l1000_schema.table_utils import get_table_name

        return frozenset({get_table_name(self._config.source_model)})

    def tables_written(self) -> frozenset[str]:
        from l1000_schema.table_utils import get_table_name

        return frozenset({get_table_name(self._config.model_cls)})

    def lower(self, ctx: LoweringContext) -> Sequence[ServerPlanStep[Any]]:
        from impl.common.l2070_server_plan.steps.collect_results import CountSequenceItemsStep
        from impl.common.l2070_server_plan.steps.write_side_effect_intents import _has_matching_table_subscriptions

        if ctx.emit_table_event_intents and _has_matching_table_subscriptions(self._config.model_cls, "INSERT"):
            rows_ref = ServerPlanRefId(f"{self.ref_id}.inserted_rows")
            return [
                *InsertFromQueryReturningStep(rows_ref, self._config).lower(ctx),
                CountSequenceItemsStep(ServerPlanRefId(self.ref_id), source_ref=rows_ref),
            ]
        needs_insert_permission = _requires_insert_from_query_permission(
            ctx,
            self._config.model_cls,
        )
        if not needs_insert_permission:
            return [InsertFromQueryStep(self.ref_id, config=self._config)]

        from impl.common.l2070_server_plan.steps.insert_permission import (
            InsertPermissionAssertionStep,
        )
        from impl.common.l2070_server_plan.steps.intent_query import (
            QueryExecuteIntent,
            _QueryExecuteConfig,
        )

        source_spec = self._config.source_query_spec
        if source_spec is None:
            msg = "Permission-aware INSERT...SELECT requires a source query specification"
            raise ValueError(msg)
        source_ref = ServerPlanRefId(f"{self.ref_id}.permission_source")
        prepared_ref = ServerPlanRefId(f"{self.ref_id}.permission_rows")
        permission_ref = ServerPlanRefId(f"{self.ref_id}.insert_permission")
        inserted_ref = ServerPlanRefId(f"{self.ref_id}.inserted_rows")
        source_steps = QueryExecuteIntent(
            source_ref,
            self._config.source_model,
            _QueryExecuteConfig(
                query_spec=source_spec,
                raw_mode=True,
                always_publish_executor_binding=True,
            ),
        ).lower(ctx)
        return [
            *source_steps,
            _PrepareTargetRowsFromRelationStep(
                prepared_ref,
                config=self._config,
                source_ref=source_ref,
            ),
            InsertPermissionAssertionStep(
                permission_ref,
                self._config.model_cls,
                source_ref=prepared_ref,
                source_is_sequence=True,
            ),
            _InsertPreparedRowsStep(
                inserted_ref,
                model_cls=self._config.model_cls,
                rows_ref=prepared_ref,
                after_refs=(permission_ref,),
            ),
            CountSequenceItemsStep(
                self.ref_id,
                source_ref=inserted_ref,
            ),
        ]


class _InsertFromQueryStepCteRow(BaseModel):
    count: int


class InsertFromQueryStep(SqlRelationPublisherStep[int]):
    """Step for executing INSERT...SELECT (insert_into) operations."""

    def cte_publication_contract(self: InsertFromQueryStep) -> CtePublicationContract:
        columns = ("count",)
        column_type_hints = SqlColumnTypeHints(integer_columns=frozenset({"count"}))
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        _contract_model_cls = _InsertFromQueryStepCteRow
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=tuple(str(column) for column in columns),
            column_type_hints=column_type_hints,
            model_cls=_contract_model_cls,
            relation_contract=CteRelationContract.semantic_row(_contract_model_cls),
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def __init__(
        self: InsertFromQueryStep,
        ref_id: ServerPlanRefId,
        config: _InsertFromQueryConfig,
        *,
        after_refs: Sequence[ServerPlanRefId] = (),
    ) -> None:
        super().__init__(ref_id)
        self._config = config
        self._after_refs = tuple(after_refs)

    @property
    def level(self: InsertFromQueryStep) -> int:
        return 0

    def step_tags(self: InsertFromQueryStep) -> frozenset[str]:
        return frozenset({"write", "insert_from_query", "grammar"})

    def is_read_only(self: InsertFromQueryStep) -> bool:
        return False

    def result_cardinality(self: InsertFromQueryStep) -> Cardinality:
        return Cardinality.SCALAR

    def tables_read(self: InsertFromQueryStep) -> frozenset[str]:
        from l1000_schema.table_utils import get_table_name

        return frozenset({get_table_name(self._config.source_model)})

    def tables_written(self: InsertFromQueryStep) -> frozenset[str]:
        from l1000_schema.table_utils import get_table_name

        return frozenset({get_table_name(self._config.model_cls)})

    def dependencies(self: InsertFromQueryStep) -> frozenset[str]:
        from impl.common.l2070_server_plan.steps._resolve import collect_query_spec_deps

        dependencies = set(insert_from_query_filter_deps(self._config.exprs))
        dependencies.update(str(ref_id) for ref_id in self._after_refs)
        if self._config.source_query_spec is not None:
            dependencies.update(collect_query_spec_deps(self._config.source_query_spec))
        return frozenset(dependencies)

    def compile(self: InsertFromQueryStep, ctx: CompilationContext) -> CompiledStep[int]:
        """Compile INSERT INTO target SELECT ... FROM source."""

        model_cls = self._config.model_cls
        source_model = self._config.source_model

        from impl.common.l2100_sql_grammar.domain.infra.stmt_dml_simple import SqlInsertFromSelectStmt

        writable_target_cols = _target_db_columns(model_cls, list(self._config.excluded_fields))
        target_cols = _prepared_insert_from_query_target_columns(self._config)
        target_table = _sql_table_name(model_cls)
        source_table: SqlRenderable | SqlTableName = _sql_table_name(source_model)
        source_joins: Sequence[SqlRenderable] = ()
        source_where: SqlRenderable | None = None
        source_for_update: SqlRenderable | None = None
        source_group_by: SqlGroupByClause | None = None
        source_having: SqlRenderable | None = None
        source_order_by: SqlRenderable | None = None
        if self._config.source_query_spec is not None:
            from impl.common.l5200_sql_query.query_grammar import QueryGrammarBuilder

            source_grammar = QueryGrammarBuilder(
                self._config.source_query_spec,
                compilation_context=ctx,
            )
            source_table = source_grammar._build_from_clause()
            source_joins = tuple(source_grammar._build_join_clauses())
            source_where_clause = source_grammar.build_where_clause()
            source_where = None if source_where_clause is None else source_where_clause._condition
            source_for_update = source_grammar._build_for_update_clause()
            source_group_by = source_grammar._build_group_by_clause()
            source_having = source_grammar._build_having_clause()
            source_order_by = source_grammar._build_order_by_clause()
        target_col_list = _build_target_column_list(target_cols)
        select_col_list = _build_select_column_list(
            target_cols,
            source_model,
            _replacement_map(model_cls, list(self._config.replacements)),
            generate_sys_id="sys_id" not in writable_target_cols,
            config=self._config,
            compilation_context=ctx,
            target_model=model_cls,
        )
        where_clause = source_where or _build_where_clause(list(self._config.exprs), source_model, ctx)
        order_by_renderable = (
            source_order_by if source_order_by is not None else _build_order_by_items(list(self._config.order_by), source_model)
        )
        limit_clause = _build_limit_clause(self._config.limit)
        offset_clause = _build_offset_clause(self._config.offset)

        grammar = SqlInsertFromSelectStmt(
            target=target_table,
            columns=target_col_list,
            source=source_table,
            select_columns=select_col_list,
            where=where_clause,
            joins=source_joins,
            group_by=source_group_by,
            having=source_having,
            order_by=order_by_renderable,
            limit=limit_clause,
            offset=offset_clause,
            or_ignore=self._config.do_nothing_on_conflict,
            for_update=source_for_update,
        )

        from impl.common.l2070_server_plan.steps._query_helper_compile import (
            _query_update_count_batch,
            _query_update_count_relation,
            _query_update_driver_rowcount_batch,
        )

        result_transport = ctx.backend_profile.traits.dml_result_transport
        if result_transport is DmlResultTransport.STATEMENT_CHANGE_FUNCTION:
            grammar = _query_update_count_batch(grammar, count_expr_sql="changes()")
        elif result_transport is DmlResultTransport.DRIVER_ROWCOUNT:
            grammar = _query_update_driver_rowcount_batch(grammar)
        elif result_transport is DmlResultTransport.RETURNING_RELATION:
            from impl.common.l2050_sql_types.sql_branded_types import SqlCteName

            grammar = _query_update_count_relation(
                grammar,
                cte_name=SqlCteName(f"{str(target_table)}_inserted_rows"),
            )
        contract = self.cte_publication_contract()
        from l2070_batching.output_shape import (
            CompiledOutputShape,
            DeclaredResultRelation,
            synthetic_output_field,
        )

        output_shape = CompiledOutputShape(
            tuple(synthetic_output_field(column) for column in contract.columns),
        )
        return CompiledStep(
            output_shape=output_shape,
            result_relation=DeclaredResultRelation.from_output_shape(output_shape),
            grammar=grammar,
            column_type_hints=contract.column_type_hints,
            needs_returning=True,
            closed_post_op=scalar_column_post_op("count", default_value=0, use_default_on_empty=True),
            auxiliary_ctes=_available_auxiliary_ctes(ctx, self.dependencies()),
        )


class InsertFromQueryReturningStep[T](SqlRelationPublisherStep[list[T]]):
    """Step for INSERT...SELECT with RETURNING — returns inserted rows as model instances."""

    def __init__(
        self: InsertFromQueryReturningStep,
        ref_id: ServerPlanRefId,
        config: _InsertFromQueryConfig,
        *,
        after_refs: Sequence[ServerPlanRefId] = (),
    ) -> None:
        super().__init__(ref_id)
        self._config = config
        self._after_refs = tuple(after_refs)

    @property
    def level(self: InsertFromQueryReturningStep) -> int:
        return 1

    def step_tags(self: InsertFromQueryReturningStep) -> frozenset[str]:
        return frozenset({"write", "insert_from_query", "returning", "grammar"})

    def is_read_only(self: InsertFromQueryReturningStep) -> bool:
        return False

    def result_cardinality(self: InsertFromQueryReturningStep) -> Cardinality:
        return Cardinality.MANY

    def sequence_result_source_ref(self) -> ServerPlanRefId:
        return ServerPlanRefId(f"{self.ref_id}.raw")

    def tables_read(self: InsertFromQueryReturningStep) -> frozenset[str]:
        from l1000_schema.table_utils import get_table_name

        return frozenset({get_table_name(self._config.source_model)})

    def tables_written(self: InsertFromQueryReturningStep) -> frozenset[str]:
        from l1000_schema.table_utils import get_table_name

        return frozenset({get_table_name(self._config.model_cls)})

    def dependencies(self: InsertFromQueryReturningStep) -> frozenset[str]:
        from impl.common.l2070_server_plan.steps._resolve import collect_query_spec_deps

        dependencies = set(insert_from_query_filter_deps(self._config.exprs))
        if self._config.source_query_spec is not None:
            dependencies.update(collect_query_spec_deps(self._config.source_query_spec))
        dependencies.update(str(ref_id) for ref_id in self._after_refs)
        return frozenset(dependencies)

    def internal_ordering_dependency_refs(
        self: InsertFromQueryReturningStep,
    ) -> tuple[ServerPlanRefId, ...]:
        return self._after_refs

    def requires_prior_step_boundary(self: InsertFromQueryReturningStep) -> bool:
        return bool(self._after_refs)

    def cte_publication_contract(self: InsertFromQueryReturningStep) -> CtePublicationContract:
        def _legacy_cte_output_columns() -> tuple[str, ...]:
            from l1000_schema.schema_def import get_db_column_name

            return tuple(
                get_db_column_name(self._config.model_cls, DynamicFieldName(field_name))
                for field_name in self._config.model_cls.model_fields
            )

        columns = _legacy_cte_output_columns()

        def _legacy_cte_column_type_hints(columns: tuple[str, ...] | None) -> SqlColumnTypeHints:
            assert columns is not None
            hints = model_sql_column_type_hints(self._config.model_cls, columns)
            if hints is None:
                msg = f"Could not resolve SQL column type hints for {self._config.model_cls.__name__}"
                raise TypeError(msg)
            return hints

        column_type_hints = _legacy_cte_column_type_hints(columns)
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        _contract_model_cls = self._config.model_cls
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=tuple(str(column) for column in columns),
            column_type_hints=column_type_hints,
            model_cls=_contract_model_cls,
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def compile(self: InsertFromQueryReturningStep, ctx: CompilationContext) -> CompiledStep[list[T]]:
        del ctx
        _raise_insert_from_query_returning_must_lower(type(self).__name__)
        raise AssertionError("unreachable")

    def lower(self: InsertFromQueryReturningStep, ctx: LoweringContext) -> list[ServerPlanStep[Any]]:
        from impl.common.l2070_server_plan.steps.write_side_effect_intents import RecordTableEventIntent, _RecordTableEventConfig

        from impl.common.l2070_server_plan.steps.row_hydration import HydrateResolvedRowsStep

        effects = RecordTableEventIntent(
            ServerPlanRefId(f"{self.ref_id}_subscription_dispatch"),
            self._config.model_cls,
            _RecordTableEventConfig(event_type="INSERT", write_ref_id=ServerPlanRefId(self.ref_id)),
        ).lower(ctx)

        effective_after_refs = tuple(self._after_refs)
        permission_steps: list[ServerPlanStep[Any]] = []
        permission_rows_ref: ServerPlanRefId | None = None
        if _requires_insert_from_query_permission(ctx, self._config.model_cls):
            from impl.common.l2070_server_plan.steps.insert_permission import (
                InsertPermissionAssertionStep,
            )
            from impl.common.l2070_server_plan.steps.intent_query import (
                QueryExecuteIntent,
                _QueryExecuteConfig,
            )

            source_spec = self._config.source_query_spec
            if source_spec is None:
                msg = "Permission-aware INSERT...SELECT requires a source query specification"
                raise ValueError(msg)
            source_ref = ServerPlanRefId(f"{self.ref_id}.permission_source")
            permission_rows_ref = ServerPlanRefId(f"{self.ref_id}.permission_rows")
            permission_ref = ServerPlanRefId(f"{self.ref_id}.insert_permission")
            source_steps = QueryExecuteIntent(
                source_ref,
                self._config.source_model,
                _QueryExecuteConfig(
                    query_spec=source_spec,
                    raw_mode=True,
                    always_publish_executor_binding=True,
                ),
            ).lower(ctx)
            permission_steps.extend(
                [
                    *source_steps,
                    _PrepareTargetRowsFromRelationStep(
                        permission_rows_ref,
                        config=self._config,
                        source_ref=source_ref,
                    ),
                    InsertPermissionAssertionStep(
                        permission_ref,
                        self._config.model_cls,
                        source_ref=permission_rows_ref,
                        source_is_sequence=True,
                    ),
                ],
            )
            effective_after_refs = (*effective_after_refs, permission_ref)

        needs_partition_lock_boundary = (
            self._config.partitioned_ordinal is not None and ctx.backend_profile.traits.requires_partition_ordinal_lock_boundary
        )
        supports_insert_returning = ctx.sql_render_dialect().supports_returning() or (
            permission_rows_ref is None and ctx.backend_profile.traits.dml_conflict_transport is DmlConflictTransport.INSERTED_VALUES
        )
        if supports_insert_returning and needs_partition_lock_boundary:
            lock_ref = ServerPlanRefId(f"{self.ref_id}.partition_lock")
            raw_ref = ServerPlanRefId(f"{self.ref_id}.raw")
            return [
                *permission_steps,
                _PrepareInsertFromQueryRowsStep(
                    lock_ref,
                    self._config,
                    after_refs=effective_after_refs,
                ),
                InsertFromQueryReturningRawStep(
                    raw_ref,
                    self._config,
                    result_ref_id=self.ref_id,
                    after_refs=(*effective_after_refs, lock_ref),
                ),
                HydrateResolvedRowsStep(
                    self.ref_id,
                    source_ref=raw_ref,
                    model_cls=self._config.model_cls,
                    runtime_only=True,
                ),
                *effects,
            ]
        if not supports_insert_returning:
            raw_ref = ServerPlanRefId(f"{self.ref_id}.raw")
            lock_ref = ServerPlanRefId(f"{self.ref_id}.partition_lock")
            lock_steps: list[ServerPlanStep[Any]] = []
            after_refs: tuple[ServerPlanRefId, ...] = effective_after_refs
            if needs_partition_lock_boundary:
                lock_steps.append(
                    _PrepareInsertFromQueryRowsStep(
                        lock_ref,
                        self._config,
                    ),
                )
                after_refs = (*after_refs, lock_ref)
            reuse_permission_rows = permission_rows_ref is not None and not needs_partition_lock_boundary
            prepared_ref = permission_rows_ref if reuse_permission_rows else ServerPlanRefId(f"{self.ref_id}.prepared")
            assert prepared_ref is not None
            prepare_steps: list[ServerPlanStep[Any]] = []
            if not reuse_permission_rows:
                prepare_steps.append(
                    _PrepareInsertFromQueryRowsStep(
                        prepared_ref,
                        self._config,
                        after_refs=after_refs,
                    ),
                )
            base_steps: list[ServerPlanStep[Any]] = [
                *permission_steps,
                *lock_steps,
                *prepare_steps,
                _InsertPreparedRowsStep(
                    raw_ref,
                    model_cls=self._config.model_cls,
                    rows_ref=prepared_ref,
                    do_nothing_on_conflict=self._config.do_nothing_on_conflict,
                    after_refs=after_refs,
                ),
            ]
            if self._config.do_nothing_on_conflict:
                inserted_ref = ServerPlanRefId(f"{self.ref_id}.inserted")
                return [
                    *base_steps,
                    _SelectExistingPreparedRowsStep(
                        inserted_ref,
                        model_cls=self._config.model_cls,
                        rows_ref=prepared_ref,
                        after_ref=raw_ref,
                    ),
                    HydrateResolvedRowsStep(
                        self.ref_id,
                        source_ref=inserted_ref,
                        model_cls=self._config.model_cls,
                        runtime_only=True,
                    ),
                    *effects,
                ]

            return [
                *base_steps,
                ReturnSourceAfterDepsStep[list[Any]](
                    self.ref_id,
                    ReturnSourceAfterDepsConfig(
                        source_ref=prepared_ref,
                        after_refs=(raw_ref,),
                        model_cls=self._config.model_cls,
                        sequence_value=True,
                        dynamic_source_contract=True,
                    ),
                ),
                *effects,
            ]

        raw_ref = ServerPlanRefId(f"{self.ref_id}.raw")
        steps: list[ServerPlanStep[Any]] = [
            *permission_steps,
            InsertFromQueryReturningRawStep(
                raw_ref,
                self._config,
                result_ref_id=self.ref_id,
                after_refs=effective_after_refs,
            ),
            HydrateResolvedRowsStep(
                self.ref_id,
                source_ref=raw_ref,
                model_cls=self._config.model_cls,
                runtime_only=True,
            ),
        ]
        return [*steps, *effects]


