            source_tables=self.tables_read(),
        )

    def compile(self, ctx: CompilationContext) -> CompiledStep[list[dict[str, Any]]]:
        from impl.common.l2050_sql_types.sql_branded_types import (
            SqlAliasName,
            SqlColumnName,
            SqlFunctionName,
            SqlTableName,
        )
        from impl.common.l2100_sql_grammar.domain.infra.expr_primitives import SqlGeneratedSysId
        from impl.common.l2100_sql_grammar.domain.infra.stmt_dml_simple import SqlScalarSubquery
        from impl.common.l2100_sql_grammar.tree.clauses import (
            SqlSelectAlias,
            SqlSelectList,
            SqlSubqueryTableRef,
            SqlTableAlias,
        )
        from impl.common.l2100_sql_grammar.tree.enums import BinaryOp
        from impl.common.l2100_sql_grammar.tree.expr_compound import SqlFuncCall
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlParam
        from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp, sql_and
        from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
        from impl.common.l2100_sql_grammar.tree.statements import SqlSelect

        source_cte = _require_prepared_rows_cte(
            ctx.cte_refs.get(str(self._source_ref)),
            step_name=type(self).__name__,
            rows_ref=self._source_ref,
        )
        ordered_source_columns = tuple(source_cte.columns or ())
        source_columns = set(ordered_source_columns)
        contract = self.cte_publication_contract()
        source_alias = SqlAliasName("versioned_source_rows")
        ordinal = self._config.partitioned_ordinal
        ordinal_column = "" if ordinal is None else str(ordinal.target_field_name)
        replacement_map = _replacement_map(
            self._config.model_cls,
            list(self._config.replacements),
        )
        select_items: list[SqlRenderable] = []
        for column in contract.columns:
            if column == "sys_id":
                expression: SqlRenderable = SqlGeneratedSysId()
            elif ordinal is not None and column == ordinal_column:
                target_alias = SqlAliasName("ordinal_target")
                predicates = [
                    SqlBinaryOp(
                        SqlColumnRef(SqlColumnName(partition.name), qualifier=target_alias),
                        BinaryOp.EQ,
                        SqlColumnRef(SqlColumnName(partition.name), qualifier=source_alias),
                    )
                    for partition in ordinal.partition_fields
                ]
                max_select = SqlSelect(
                    select=SqlSelectList(
                        [
                            SqlFuncCall(
                                SqlFunctionName("MAX"),
                                [SqlColumnRef(SqlColumnName(column), qualifier=target_alias)],
                            ),
                        ],
                    ),
                    from_=SqlTableAlias(
                        SqlTableIdent(_sql_table_name(self._config.model_cls)),
                        target_alias,
                    ),
                    where=sql_and(*predicates),
                )
                prior = SqlFuncCall(
                    SqlFunctionName("COALESCE"),
                    [SqlScalarSubquery(max_select), SqlParam(ordinal.start - 1)],
                )
                expression = SqlBinaryOp(prior, BinaryOp.ADD, SqlParam(1))
            elif column in replacement_map:
                expression = _replacement_to_renderable(
                    replacement_map[column],
                    self._config.source_model,
                    source_alias=source_alias,
                )
            elif column in source_columns:
                expression = SqlColumnRef(SqlColumnName(column), qualifier=source_alias)
            else:
                expression = SqlParam(None)
            select_items.append(SqlSelectAlias(expression, SqlAliasName(column)))
        distinct_source = SqlSelect(
            select=SqlSelectList(
                [SqlColumnRef(SqlColumnName(column)) for column in ordered_source_columns],
            ),
            from_=SqlTableIdent(SqlTableName(source_cte.ref_id)),
            distinct=True,
        )
        grammar = SqlSelect(
            select=SqlSelectList(select_items),
            from_=SqlSubqueryTableRef(
                distinct_source,
                SqlTableName(str(source_alias)),
            ),
        )
        output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(contract)
        return CompiledStep(
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
            grammar=grammar,
            needs_returning=True,
            closed_post_op=row_dicts_post_op(),
            auxiliary_ctes=[(source_cte.ref_id, source_cte.auxiliary_query)] if source_cte.auxiliary_query is not None else None,
        )


