def _coerce_projected_value(
    model_cls: type[DatabaseObjectRow],
    column_projection: str,
    raw_val: object,
) -> object:
    """Wrap projected scalars in branded field types when possible."""

    from l1000_schema.schema_def import get_db_column_name

    resolved_hints = cached_runtime_type_hints(model_cls)
    converted_value: object = raw_val
    for fname in model_cls.model_fields:
        if get_db_column_name(model_cls, DynamicFieldName(fname)) != column_projection:
            continue
        annotation = resolved_hints.get(ReflectionAttributeName(fname), model_cls.model_fields[fname].annotation)
        if annotation is None:
            break
        args = get_args(annotation)
        if args:
            for arg in args:
                if arg is type(None):
                    continue
                is_exact_match = False
                with contextlib.suppress(TypeError):
                    is_exact_match = isinstance(raw_val, arg)
                if is_exact_match:
                    break
                if callable(arg):
                    try:
                        converted_value = arg(raw_val)
                        break
                    except (TypeError, ValueError):
                        continue
        elif get_origin(annotation) is None and callable(annotation):
            with contextlib.suppress(TypeError, ValueError):
                converted_value = annotation(raw_val)
        break
    return converted_value


def build_query_execute_standard_post_op(
    model_cls: type[DatabaseObjectRow],
    *,
    raw_mode: bool,
    select_columns: Sequence[object] | None = None,
    projection_output_aliases: Sequence[object] | None = None,
) -> CompiledPostOp:
    """Return raw rows or inline-hydrated models for plain SELECTs."""
    normalized_select_columns: tuple[str, ...] | None = None
    if select_columns and not raw_mode:
        if projection_output_aliases and len(projection_output_aliases) == len(select_columns):
            normalized_select_columns = tuple(str(alias) for alias in projection_output_aliases)
        else:
            normalized_select_columns = _select_projection_output_names(select_columns)
    return query_execute_rows_post_op(
        model_cls=model_cls,
        raw_mode=raw_mode,
        select_columns=normalized_select_columns,
    )


def _select_projection_output_names(
    select_columns: Sequence[object],
) -> tuple[str, ...]:
    output_names: list[str] = []
    for column in select_columns:
        if isinstance(column, str):
            output_names.append(column)
            continue
        if isinstance(column, Field):
            output_names.append(column.name)
            continue
        if isinstance(column, AliasedField):
            output_names.append(column.alias)
            continue
        if isinstance(column, AliasedExpression):
            output_names.append(column.alias)
            continue
        if isinstance(column, Expression) and column.field is not None and column.function is None and column.operator is None:
            output_names.append(column.field)
            continue
        return ()
    return tuple(output_names)


def _normalize_query_first_spec(
    query_spec: QuerySpec[DatabaseObjectRow],
    strict_one: bool,
) -> QuerySpec[DatabaseObjectRow]:
    if query_spec.limit is not None:
        return query_spec

    target_limit = 2 if strict_one else 1
    return replace(query_spec, limit=target_limit)


def _collect_query_first_deps(
    query_spec: QuerySpec[DatabaseObjectRow],
    *,
    after_refs: frozenset[ServerPlanRefId],
    user_id_ref_id: ServerPlanRefId | None,
    permission_dependency_refs: frozenset[ServerPlanRefId] = frozenset(),
) -> frozenset[str]:
    deps = {str(ref_id) for ref_id in after_refs | permission_dependency_refs}
    if user_id_ref_id is not None:
        deps.add(str(user_id_ref_id))
    from impl.common.l2070_server_plan.steps._resolve import collect_query_spec_deps

    deps.update(collect_query_spec_deps(query_spec))
    return frozenset(deps)


def _cached_query_first_deps(
    step: object,
    query_spec: QuerySpec[DatabaseObjectRow],
    *,
    after_refs: frozenset[ServerPlanRefId],
    user_id_ref_id: ServerPlanRefId | None,
    permission_dependency_refs: frozenset[ServerPlanRefId],
) -> frozenset[str]:
    cached = getattr(step, "_dependencies_cache", None)
    if cached is not None:
        assert isinstance(cached, frozenset)
        return cached
    dependencies = _collect_query_first_deps(
        query_spec,
        after_refs=after_refs,
        user_id_ref_id=user_id_ref_id,
        permission_dependency_refs=permission_dependency_refs,
    )
    setattr(step, "_dependencies_cache", dependencies)
    return dependencies


