    from impl.common.l2060_query_spec.query_spec import QuerySpec


@dataclass(frozen=True)
class _QueryExecuteAggregateStepConfig:
    query_spec: Any
    user_id_ref_id: ServerPlanRefId | None = None


def _require_aggregate_assertion_grammar(grammar: object | None) -> object:
    if grammar is not None:
        return grammar
    msg = "JSON_OBJECT_AGG null-key assertion requires compiled SQL grammar."
    raise RuntimeError(msg)


def _aggregate_output_shape(
    model_cls: type[DatabaseObjectRow],
    query_spec: Any,
) -> CompiledOutputShape | None:
    mappings: list[tuple[str, str, bool]] = []
    for index, group_column in enumerate(getattr(query_spec, "group_by", ()) or ()):
        if isinstance(group_column, str):
            db_col = get_db_column_name(model_cls, DynamicFieldName(group_column))
            mappings.append((db_col, db_col, False))
            continue
        if isinstance(group_column, AliasedField):
            mappings.append((group_column.alias, group_column.alias, False))
            continue
        if isinstance(group_column, Field):
            db_col = get_db_column_name(model_cls, DynamicFieldName(group_column.name))
            mappings.append((db_col, db_col, False))
            continue
        if isinstance(group_column, AliasedExpression):
            mappings.append((group_column.alias, group_column.alias, False))
            continue
        if (
            isinstance(group_column, Expression)
            and group_column.field is not None
            and group_column.function is None
            and group_column.operator is None
        ):
            db_col = get_db_column_name(model_cls, DynamicFieldName(group_column.field))
            mappings.append((db_col, db_col, False))
            continue
        mappings.append((f"__group_by_{index}", f"__group_by_{index}", False))
    for agg in getattr(query_spec, "aggregates", None) or getattr(query_spec, "aggregations", None) or ():
        if getattr(agg, "alias", None):
            mappings.append((agg.alias, agg.alias, False))
    if not mappings:
        return None
    from l2070_batching.output_shape import output_shape_from_mappings

    return output_shape_from_mappings(tuple(mappings))


def _aggregate_projection_lineage(
    model_cls: type[DatabaseObjectRow],
    query_spec: Any,
    columns: tuple[str, ...],
) -> tuple[tuple[str, str], ...]:
    lineage: dict[str, str] = {}
    for index, group_column in enumerate(getattr(query_spec, "group_by", ()) or ()):
        if isinstance(group_column, str):
            db_col = get_db_column_name(model_cls, DynamicFieldName(group_column))
            lineage[db_col] = db_col
            continue
        if isinstance(group_column, AliasedField):
            lineage[group_column.alias] = get_db_column_name(
                cast("type[DatabaseObjectRow]", group_column.owner_model),
                DynamicFieldName(group_column.name),
            )
            continue
        if isinstance(group_column, Field):
            db_col = get_db_column_name(model_cls, DynamicFieldName(group_column.name))
            lineage[db_col] = db_col
            continue
        if isinstance(group_column, AliasedExpression):
            lineage[group_column.alias] = f"expression:{group_column.alias}"
            continue
        if (
            isinstance(group_column, Expression)
            and group_column.field is not None
            and group_column.function is None
            and group_column.operator is None
        ):
            db_col = get_db_column_name(model_cls, DynamicFieldName(group_column.field))
            lineage[db_col] = db_col
            continue
        synthetic_column = f"__group_by_{index}"
        lineage[synthetic_column] = f"group_by:{synthetic_column}"
    for agg in getattr(query_spec, "aggregates", None) or getattr(query_spec, "aggregations", None) or ():
        alias = getattr(agg, "alias", None)
        if alias:
            lineage[alias] = f"aggregate:{alias}"
    return tuple((column, lineage.get(column, f"aggregate:{column}")) for column in columns)


def _json_object_agg_key_expressions(query_spec: Any) -> tuple[Expression, ...]:
    expressions: list[Expression] = []
    for agg in getattr(query_spec, "aggregates", None) or getattr(query_spec, "aggregations", None) or ():
        if str(getattr(agg, "function", "")).upper() != "JSON_OBJECT_AGG":
            continue
        source = getattr(agg, "source_expression", None) or getattr(agg, "expression", None)
        args = getattr(source, "args", None) or ()
        if args and isinstance(args[0], Expression):
            expressions.append(args[0])
    return tuple(expressions)


def _json_object_agg_null_key_assertion_spec(query_spec: Any) -> Any:
    from l2060_query_builder.query_contracts import QueryFilter

    key_expressions = _json_object_agg_key_expressions(query_spec)
    if not key_expressions:
        msg = "JSON_OBJECT_AGG null-key assertion requires at least one key expression."
        raise ValueError(msg)
    null_expr = key_expressions[0] == Expression(value=None)
    for key_expr in key_expressions[1:]:
        null_expr = null_expr | (key_expr == Expression(value=None))
    return dc_replace(
        query_spec,
        filters=[*getattr(query_spec, "filters", ()), QueryFilter(expression=null_expr)],
        group_by=[],
        aggregations=[],
        having=[],
        window_functions=[],
        order_by=[],
        limit=None,
        offset=None,
        select_columns=None,
    )


class _CompiledAggregateQueryStep(MaybeSqlRelationPublisherStep[list[dict[str, Any]]]):
    def can_join_session_preamble_statement_batch(self: _CompiledAggregateQueryStep) -> bool:
        return True

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        model_cls: type[DatabaseObjectRow],
        query_spec: Any,
        user_id_ref_id: ServerPlanRefId | None,
        assertion_ref_id: ServerPlanRefId | None = None,
    ) -> None:
        super().__init__(ref_id)
        self._model_cls = model_cls
        self._query_spec = query_spec
        self._user_id_ref_id = user_id_ref_id
        self._assertion_ref_id = assertion_ref_id

    @property
    def level(self) -> int:
        return 0

    def step_tags(self) -> frozenset[str]:
        return frozenset({"read", "query", "aggregate", "grammar"})

    def is_read_only(self) -> bool:
        return True

    def result_cardinality(self) -> Cardinality:
        return Cardinality.MANY

    def tables_read(self) -> frozenset[str]:
        from l1000_schema.table_utils import get_table_name

        return frozenset({get_table_name(self._model_cls)})

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def cte_publication_contract(self: _CompiledAggregateQueryStep) -> CtePublicationContract:
        def _legacy_cte_output_columns() -> tuple[str, ...] | None:
            output_shape = _aggregate_output_shape(self._model_cls, self._query_spec)
            if output_shape is None:
                return None
            return output_shape.cte_output_columns

        columns = _legacy_cte_output_columns()

        def _legacy_cte_column_type_hints(columns: tuple[str, ...] | None) -> SqlColumnTypeHints | None:
            if columns is None:
                return None
            return _query_spec_column_type_hints(self._model_cls, self._query_spec, columns)

        column_type_hints = _legacy_cte_column_type_hints(columns)
        if columns is None:
            if column_type_hints is not None and column_type_hints.has_any():
                msg = f"{type(self).__name__} declares SQL column type hints without an explicit cte_output_columns() contract."
                raise TypeError(msg)
            return CtePublicationContract.non_publishing()
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        contract_columns = tuple(str(column) for column in columns)
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=contract_columns,
            column_type_hints=column_type_hints,
            relation_contract=CteRelationContract.projection_over_model(
                source_model_cls=self._model_cls,
                projection_lineage=_aggregate_projection_lineage(
                    self._model_cls,
                    self._query_spec,
                    contract_columns,
                ),
            ),
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def dependencies(self) -> frozenset[str]:
        deps: set[str] = set()
        if self._user_id_ref_id is not None:
            deps.add(str(self._user_id_ref_id))
        if self._assertion_ref_id is not None:
            deps.add(str(self._assertion_ref_id))
        if self._query_spec is None:
            return frozenset(deps)
        from impl.common.l2070_server_plan.steps._resolve import collect_query_spec_deps

        deps.update(str(dep) for dep in collect_query_spec_deps(self._query_spec))
        return frozenset(deps)

    def compile(self, ctx: CompilationContext) -> CompiledStep[list[dict[str, Any]]]:
        from impl.common.l2070_server_plan.steps._compile_helpers import (
            attach_runtime_read_permission_grammar,
            compile_query_grammar,
        )

        effective_spec = attach_runtime_read_permission_grammar(
            self._query_spec,
            self._model_cls,
            ctx,
            user_id_ref_id=self._user_id_ref_id,
        )
        effective_spec = _inject_multitable_polymorphic_cte_if_needed(
            cast("QuerySpec[DatabaseObjectRow]", effective_spec),
            model_cls=self._model_cls,
            ctx=ctx,
        )
        compiled = compile_query_grammar(
            effective_spec,
            self._model_cls,
            ctx,
            is_count=False,
        )

        contract = self.cte_publication_contract()
        output_shape = None
        result_relation = None
        column_type_hints = None
        if contract is not None:
            output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(contract)
        return CompiledStep(
            grammar=compiled.grammar,
            params=compiled.params,
            needs_returning=compiled.needs_returning,
            external_params_first=compiled.external_params_first,
            runtime_ref_ids=compiled.runtime_ref_ids,
            auxiliary_ctes=compiled.auxiliary_ctes,
            closed_post_op=row_dicts_post_op(),
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
        )


class _JsonObjectAggNullKeyAssertionStep(SqlRelationPublisherStep[None]):
    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        model_cls: type[DatabaseObjectRow],
        query_spec: Any,
        user_id_ref_id: ServerPlanRefId | None,
    ) -> None:
        super().__init__(ref_id)
        self._model_cls = model_cls
        self._query_spec = query_spec
        self._user_id_ref_id = user_id_ref_id

    @property
    def level(self) -> int:
        return 0

    def step_tags(self) -> frozenset[str]:
        return frozenset({"read", "query", "aggregate", "assertion", "grammar"})

    def is_read_only(self) -> bool:
        return True

    def result_cardinality(self) -> Cardinality:
        return Cardinality.ONE

    def tables_read(self) -> frozenset[str]:
        from l1000_schema.table_utils import get_table_name

        return frozenset({get_table_name(self._model_cls)})

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def dependencies(self) -> frozenset[str]:
        deps: set[str] = set()
        if self._user_id_ref_id is not None:
            deps.add(str(self._user_id_ref_id))
        from impl.common.l2070_server_plan.steps._resolve import collect_query_spec_deps

        deps.update(str(dep) for dep in collect_query_spec_deps(self._query_spec))
        return frozenset(deps)

    def cte_publication_contract(self: _JsonObjectAggNullKeyAssertionStep) -> CtePublicationContract:
        output_shape = sql_assertion_output_shape()
        column_type_hints = sql_assertion_column_type_hints()
        columns = output_shape.cte_output_columns
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        contract_columns = tuple(str(column) for column in columns)
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=contract_columns,
            column_type_hints=column_type_hints,
            relation_contract=CteRelationContract.semantic_row(SqlAssertionRow),
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def compile(self, ctx: CompilationContext) -> CompiledStep[None]:
        from l1100_exceptions.exceptions import JsonAggregationError
        from impl.common.l2070_server_plan.steps._compile_helpers import (
            attach_runtime_read_permission_grammar,
            compile_query_grammar,
        )
        from impl.common.l2070_server_plan.steps.sql_error_gate import (
            sql_assertion_column_type_hints,
            sql_assertion_output_shape,
            sql_assertion_post_op,
            zero_count_assertion_query,
        )

        assertion_spec = _json_object_agg_null_key_assertion_spec(self._query_spec)
        effective_spec = attach_runtime_read_permission_grammar(
            assertion_spec,
            self._model_cls,
            ctx,
            user_id_ref_id=self._user_id_ref_id,
        )
        effective_spec = _inject_multitable_polymorphic_cte_if_needed(
            cast("QuerySpec[DatabaseObjectRow]", effective_spec),
            model_cls=self._model_cls,
            ctx=ctx,
        )
        compiled = compile_query_grammar(
            effective_spec,
            self._model_cls,
            ctx,
            is_count=True,
        )
        compiled_grammar = _require_aggregate_assertion_grammar(compiled.grammar)
        output_shape = sql_assertion_output_shape()
        return CompiledStep(
            grammar=zero_count_assertion_query(
                cast("Any", compiled_grammar),
                error_message="NULL key not allowed in JSON_OBJECT_AGG",
            ),
            params=compiled.params,
            needs_returning=True,
            external_params_first=compiled.external_params_first,
            runtime_ref_ids=compiled.runtime_ref_ids,
            auxiliary_ctes=compiled.auxiliary_ctes,
            closed_post_op=sql_assertion_post_op(
                "NULL key not allowed in JSON_OBJECT_AGG",
                exc_type=JsonAggregationError,
            ),
            output_shape=output_shape,
            result_relation=DeclaredResultRelation.from_output_shape(output_shape),
            column_type_hints=sql_assertion_column_type_hints(),
        )


class QueryExecuteAggregateStep(MaybeSqlRelationPublisherStep[list[dict[str, Any]]]):
    """Step for executing aggregate queries (GROUP BY with aggregate functions).

    Level 1 step that lowers to a GrammarRowsStep (Level 0) by building
    an SqlSelect from the query_spec's aggregation, group_by, and having
    fields.
    """

    def __init__(
        self: QueryExecuteAggregateStep,
        ref_id: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        config: _QueryExecuteAggregateStepConfig,
    ) -> None:
        super().__init__(ref_id)
        self._model_cls = model_cls
        self._query_spec = config.query_spec
        self._user_id_ref_id = config.user_id_ref_id

    @property
    def level(self: QueryExecuteAggregateStep) -> int:
        return 1

    def step_tags(self: QueryExecuteAggregateStep) -> frozenset[str]:
        return frozenset({"read", "query", "aggregate"})

    def is_read_only(self: QueryExecuteAggregateStep) -> bool:
        return True

    def result_cardinality(self: QueryExecuteAggregateStep) -> Cardinality:
        return Cardinality.MANY

    def tables_read(self: QueryExecuteAggregateStep) -> frozenset[str]:
        from l1000_schema.table_utils import get_table_name

        return frozenset({get_table_name(self._model_cls)})

    def tables_written(self: QueryExecuteAggregateStep) -> frozenset[str]:
        """Aggregate query is read-only; no tables written."""
        return frozenset()

    def cte_publication_contract(self: QueryExecuteAggregateStep) -> CtePublicationContract:
        def _legacy_cte_output_columns() -> tuple[str, ...] | None:
            output_shape = _aggregate_output_shape(self._model_cls, self._query_spec)
            if output_shape is None:
                return None
            return output_shape.cte_output_columns

        columns = _legacy_cte_output_columns()

        def _legacy_cte_column_type_hints(columns: tuple[str, ...] | None) -> SqlColumnTypeHints | None:
            if columns is None:
                return None
            return _query_spec_column_type_hints(self._model_cls, self._query_spec, columns)

        column_type_hints = _legacy_cte_column_type_hints(columns)
        if columns is None:
            if column_type_hints is not None and column_type_hints.has_any():
                msg = f"{type(self).__name__} declares SQL column type hints without an explicit cte_output_columns() contract."
                raise TypeError(msg)
            return CtePublicationContract.non_publishing()
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        contract_columns = tuple(str(column) for column in columns)
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=contract_columns,
            column_type_hints=column_type_hints,
            relation_contract=CteRelationContract.projection_over_model(
                source_model_cls=self._model_cls,
                projection_lineage=_aggregate_projection_lineage(
                    self._model_cls,
                    self._query_spec,
                    contract_columns,
                ),
            ),
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def dependencies(self: QueryExecuteAggregateStep) -> frozenset[str]:
        deps: set[str] = set()
        if self._user_id_ref_id is not None:
            deps.add(str(self._user_id_ref_id))
        if self._query_spec is None:
            return frozenset(deps)
        from impl.common.l2070_server_plan.steps._resolve import collect_query_spec_deps

        deps.update(str(dep) for dep in collect_query_spec_deps(self._query_spec))
        return frozenset(deps)

    def preprocess(self: QueryExecuteAggregateStep, resolved: ResolvedRefs) -> None:
        del resolved

    def lower(
        self: QueryExecuteAggregateStep,
        ctx: LoweringContext,
    ) -> Sequence[ServerPlanStep]:
        del ctx
        query_spec = self._query_spec
        model_cls = self._model_cls
        assertion_ref_id = (
            ServerPlanRefId(f"{self.ref_id}_json_object_agg_null_key_assertion") if _json_object_agg_key_expressions(query_spec) else None
        )
        assertion_steps: list[ServerPlanStep] = []
        if assertion_ref_id is not None:
            assertion_steps.append(
                _JsonObjectAggNullKeyAssertionStep(
                    ref_id=assertion_ref_id,
                    model_cls=model_cls,
                    query_spec=query_spec,
                    user_id_ref_id=self._user_id_ref_id,
                ),
            )
        return [
            *assertion_steps,
            _CompiledAggregateQueryStep(
                ref_id=ServerPlanRefId(self.ref_id),
                model_cls=model_cls,
                query_spec=query_spec,
                user_id_ref_id=self._user_id_ref_id,
                assertion_ref_id=assertion_ref_id,
            ),
        ]

    def compile(
        self: QueryExecuteAggregateStep,
        ctx: CompilationContext,
    ) -> CompiledStep[list[dict[str, Any]]]:
        del ctx
        raise TypeError(
            f"{type(self).__name__} is level {self.level} and must be lowered to terminal steps before compile() is called.",
        )

"""QueryExecuteRawStep: ServerPlan step for raw query execution."""

from __future__ import annotations

from collections.abc import Sequence
from dataclasses import dataclass, replace
from typing import TYPE_CHECKING, cast

from l2070_batching.cardinality import Cardinality
from l2070_batching.compilation import CompiledStep
from l2070_batching.sql_column_type_hints import SqlColumnTypeHints
from l2070_batching.step import CtePublicationContract, ServerPlanStep, ContractedSqlProducerStep, SqlRelationPublisherStep
from l1400_types import DynamicFieldName, ServerPlanRefId

if TYPE_CHECKING:
    from l1000_schema.schema_def import DatabaseObjectRow
    from l4000_permissions.permission_scheme import PermissionAction
    from l2070_batching.compilation import CompilationContext
    from l2070_batching.server_ref import ScalarServerRef
    from l1400_types import SysId
    from impl.common.l2060_query_spec.query_spec import QuerySpec


_MISSING_FILTER_VALUE = object()


def _query_spec_cte_output_columns(
    query_spec: QuerySpec[DatabaseObjectRow],
    model_cls: type[DatabaseObjectRow],
) -> tuple[str, ...]:
    from l1000_schema.schema_def import get_db_column_name
    from l1000_schema.typed_field import AliasedExpression, AliasedField, Expression, Field
    from l2070_batching.write_column_policy import returnable_db_columns

    if query_spec.select_columns is None:
        return returnable_db_columns(model_cls)
    columns: list[str] = []
    for projection in query_spec.select_columns or ():
        if isinstance(projection, AliasedField | AliasedExpression):
            columns.append(projection.alias)
        elif isinstance(projection, Field):
            owner = getattr(projection, "owner", None) or model_cls
            columns.append(str(get_db_column_name(owner, DynamicFieldName(projection.name))))
        elif isinstance(projection, Expression) and projection.field is not None:
            columns.append(str(get_db_column_name(model_cls, DynamicFieldName(projection.field))))
        else:
            alias = getattr(projection, "alias", None)
            if isinstance(alias, str):
                columns.append(alias)
    return tuple(dict.fromkeys(columns))


@dataclass(frozen=True)
class _QueryExecuteRawStepConfig:
    query_spec: QuerySpec[DatabaseObjectRow] | None
    user_id_ref_id: ServerPlanRefId | None = None
    hydrate_large_columns: bool = False
    permission_action: PermissionAction | None = None


def _is_select_one_raw_query_shape(
    query_spec: object,
    model_cls: type[DatabaseObjectRow],
) -> bool:
    from l1000_schema.schema_def import get_db_column_name

    is_simple_select_one_shape = (
        getattr(query_spec, "model_cls", None) is model_cls
        and getattr(query_spec, "select_columns", None) is None
        and not getattr(query_spec, "distinct", False)
        and not getattr(query_spec, "joins", None)
        and not getattr(query_spec, "order_by", None)
        and getattr(query_spec, "offset", None) is None
        and not getattr(query_spec, "group_by", None)
        and not getattr(query_spec, "aggregations", None)
        and not getattr(query_spec, "having", None)
        and not getattr(query_spec, "window_functions", None)
        and getattr(query_spec, "limit", None) in {1, 2}
    )
    if not is_simple_select_one_shape:
        return False

    filters = getattr(query_spec, "filters", None) or ()
    if len(filters) != 1:
        return False

    sys_id_names = {"sys_id", get_db_column_name(model_cls, DynamicFieldName("sys_id"))}
    filter_item = filters[0]
    expr = getattr(filter_item, "expression", None)
    if expr is not None:
        return getattr(expr, "field", None) in sys_id_names and getattr(expr, "operator", None) == "="

    return getattr(filter_item, "column", None) in sys_id_names and getattr(filter_item, "operator", None) == "="


def _select_one_raw_filter_value(query_spec: object) -> object:
    filters = getattr(query_spec, "filters", None) or ()
    if len(filters) != 1:
        return _MISSING_FILTER_VALUE

    filter_item = filters[0]
    expr = getattr(filter_item, "expression", None)
    if expr is not None:
        return getattr(expr, "value", _MISSING_FILTER_VALUE)
    return getattr(filter_item, "value", _MISSING_FILTER_VALUE)


def _extract_select_one_raw_sys_id(
    query_spec: object,
    model_cls: type[DatabaseObjectRow],
) -> ScalarServerRef[SysId] | None:
    from l2070_batching.server_ref import ScalarServerRef, ServerRefs

    if not _is_select_one_raw_query_shape(query_spec, model_cls):
        return None

    value = _select_one_raw_filter_value(query_spec)
    if value is _MISSING_FILTER_VALUE or isinstance(value, list):
        return None
    if isinstance(value, ScalarServerRef):
        return cast("ScalarServerRef[SysId]", value)
    return cast("ScalarServerRef[SysId]", ServerRefs.scalar(value))


def _normalize_raw_select_one_sys_id_filter(
    query_spec: QuerySpec[DatabaseObjectRow] | None,
    model_cls: type[DatabaseObjectRow],
) -> QuerySpec[DatabaseObjectRow] | None:
    from l1000_schema.typed_field import Expression
    from l2060_query_builder.query_contracts import QueryFilter
    from l1400_types import SysId

    if query_spec is None or not _is_select_one_raw_query_shape(query_spec, model_cls):
        return query_spec
    filters: list[QueryFilter] = list(getattr(query_spec, "filters", ()) or ())
    if len(filters) != 1:
        return query_spec
    filter_item = filters[0]
    expression = getattr(filter_item, "expression", None)
    if expression is not None:
        value = getattr(expression, "value", _MISSING_FILTER_VALUE)
        if not isinstance(value, SysId):
            return query_spec
        normalized_expression = Expression(
            field=getattr(expression, "field", None),
            operator=getattr(expression, "operator", None),
            value=value.unwrap_to_str(),
            left=getattr(expression, "left", None),
            right=getattr(expression, "right", None),
            logical_op=getattr(expression, "logical_op", None),
            function=getattr(expression, "function", None),
            args=getattr(expression, "args", None),
            owner=getattr(expression, "owner", None),
            server_ref_dependencies=tuple(getattr(expression, "server_ref_dependencies", ()) or ()),
        )
        filters[0] = QueryFilter(expression=normalized_expression)
        return replace(query_spec, filters=filters)
    value = getattr(filter_item, "value", _MISSING_FILTER_VALUE)
    if not isinstance(value, SysId):
        return query_spec
    filters[0] = QueryFilter(
        column=filter_item.column,
        operator=filter_item.operator,
        value=value.unwrap_to_str(),
        json_key=filter_item.json_key,
    )
    return replace(query_spec, filters=filters)


class QueryExecuteRawStep[T](SqlRelationPublisherStep[Sequence[T]]):
    """Execute a query spec and return plain dict rows."""

    def __init__(
        self: QueryExecuteRawStep,
        ref_id: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        config: _QueryExecuteRawStepConfig,
    ) -> None:
        super().__init__(ref_id)
        self._model_cls = model_cls
        self._query_spec = config.query_spec
        self._user_id_ref_id = config.user_id_ref_id
        self._hydrate_large_columns = config.hydrate_large_columns
        self._permission_action = config.permission_action
        self._compiled_cte_output_columns: tuple[str, ...] | None = None
        self._compiled_cte_column_type_hints: SqlColumnTypeHints | None = None

    @property
    def level(self: QueryExecuteRawStep) -> int:
        return 0

    def step_tags(self: QueryExecuteRawStep) -> frozenset[str]:
        return frozenset({"read", "query", "execute", "raw"})

    def is_read_only(self: QueryExecuteRawStep) -> bool:
        return True

    def result_cardinality(self: QueryExecuteRawStep) -> Cardinality:
        return Cardinality.MANY

    def raw_terminal_result_columns(self: QueryExecuteRawStep) -> tuple[str, ...] | None:
        if self._compiled_cte_output_columns is not None:
            return self._compiled_cte_output_columns
        if self._query_spec is None or self._query_spec.select_columns is None:
            return None
        from impl.common.l2070_server_plan.steps.query_execute import (
            _query_spec_selected_output_columns,
        )

        columns = tuple(
            output_name
            for output_name, _db_column, _is_binary in _query_spec_selected_output_columns(
                self._model_cls,
                self._query_spec,
            )
        )
        return columns

    def tables_read(self: QueryExecuteRawStep) -> frozenset[str]:
        from l1000_schema.table_utils import get_table_name

        return frozenset({get_table_name(self._model_cls)})

    def tables_written(self: QueryExecuteRawStep) -> frozenset[str]:
        return frozenset()

    def cte_publication_contract(self: QueryExecuteRawStep) -> CtePublicationContract:
        def _legacy_cte_output_columns() -> tuple[str, ...]:
            if self._query_spec is not None and (
                getattr(self._query_spec, "group_by", None)
                or getattr(self._query_spec, "aggregations", None)
                or getattr(self._query_spec, "window_functions", None)
            ):
                from impl.common.l2070_server_plan.steps.query_execute import (
                    _query_spec_computed_output_columns,
                )

                computed_columns = _query_spec_computed_output_columns(
                    self._model_cls,
                    self._query_spec,
                )
                return tuple(db_column for _output_name, db_column, _is_binary in computed_columns)
            if self._query_spec is not None and getattr(self._query_spec, "select_columns", None) is not None:
                from impl.common.l2070_server_plan.steps.query_execute import (
                    _query_spec_selected_output_columns,
                )

                return tuple(
                    output_name
                    for output_name, _db_column, _is_binary in _query_spec_selected_output_columns(
                        self._model_cls,
                        self._query_spec,
                    )
                )
            from l1000_schema.schema_def import get_db_column_name
            from l2070_batching.write_column_policy import collect_polymorphic_fields


            return tuple(
                get_db_column_name(self._model_cls, DynamicFieldName(field_name))
                for field_name in collect_polymorphic_fields(self._model_cls)
            )

        base_columns = _legacy_cte_output_columns()
        if self._compiled_cte_output_columns is not None:
            columns = self._compiled_cte_output_columns
        elif self._hydrate_large_columns:
            from impl.common.l2070_server_plan.steps.large_column_transport_contract import (
                selected_large_column_transport_columns,
            )

            large_columns = selected_large_column_transport_columns(self._model_cls, base_columns)
            columns = tuple(dict.fromkeys((*base_columns, *large_columns)))
        else:
            columns = base_columns

        def _legacy_cte_column_type_hints(columns: tuple[str, ...] | None) -> SqlColumnTypeHints:
            if not columns:
                return SqlColumnTypeHints()
            if self._hydrate_large_columns:
                from impl.common.l2070_server_plan.steps.large_column_transport_contract import (
                    large_column_transport_type_hints,
                    selected_large_column_transport_columns,
                )
                from impl.common.l2070_server_plan.steps.query_execute import _query_spec_column_type_hints
                from l2070_batching.sql_column_type_hints import combine_sql_column_type_hints

                large_columns = selected_large_column_transport_columns(self._model_cls, base_columns)
                base_hints = (
                    SqlColumnTypeHints()
                    if not base_columns
                    else _query_spec_column_type_hints(
                        self._model_cls,
                        self._query_spec,
                        base_columns,
                    )
                )
                return combine_sql_column_type_hints(
                    columns,
                    base_hints,
                    large_column_transport_type_hints(large_columns),
                )
            from impl.common.l2070_server_plan.steps.query_execute import _query_spec_column_type_hints

            return _query_spec_column_type_hints(self._model_cls, self._query_spec, columns)

        column_type_hints = (
            self._compiled_cte_column_type_hints
            if self._compiled_cte_column_type_hints is not None
            else _legacy_cte_column_type_hints(columns)
        )
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        _contract_model_cls = self._model_cls
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=tuple(str(column) for column in columns),
            column_type_hints=column_type_hints,
            model_cls=_contract_model_cls,
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def dependencies(self: QueryExecuteRawStep) -> frozenset[str]:
        deps: set[str] = set()
        if self._user_id_ref_id is not None:
            deps.add(str(self._user_id_ref_id))
        if self._query_spec is None:
            return frozenset(deps)
        from impl.common.l2070_server_plan.steps._resolve import collect_query_spec_deps

        deps.update(collect_query_spec_deps(self._query_spec))
        return frozenset(deps)

    def compile(self: QueryExecuteRawStep, ctx: CompilationContext) -> CompiledStep[Sequence[T]]:
        from l2070_batching.post_op import raw_rows_post_op
        from impl.common.l2070_server_plan.steps.query_execute import compile_sql_query_execute_step

        resolved_user_id = ctx.cte_refs.get(self._user_id_ref_id) if self._user_id_ref_id is not None else None
        compiled = compile_sql_query_execute_step(
            self._model_cls,
            _normalize_raw_select_one_sys_id_filter(self._query_spec, self._model_cls),
            ctx,
            raw_mode=True,
            resolved_user_id=resolved_user_id,
            closed_post_op=raw_rows_post_op(),
            step_name=type(self).__name__,
            force_hydrate_large_columns=self._hydrate_large_columns,
            permission_action=self._permission_action,
        )
        if compiled.output_shape is None:
            from l2070_batching.output_shape import (
                CompiledOutputShape,
                DeclaredResultRelation,
                synthetic_output_field,
            )

            contract = self.cte_publication_contract()
            output_shape = CompiledOutputShape(
                tuple(synthetic_output_field(column) for column in contract.columns),
            )
            compiled = replace(
                compiled,
                output_shape=output_shape,
                column_type_hints=contract.column_type_hints,
                result_relation=DeclaredResultRelation.from_output_shape(output_shape),
            )
            assert compiled.output_shape is not None
            assert compiled is not None
        self._compiled_cte_output_columns = compiled.output_shape.cte_output_columns
        self._compiled_cte_column_type_hints = compiled.column_type_hints
        self._cte_publication_contract_cache_valid = False
        self._publication_contract_cache_valid = False
        return cast("CompiledStep[Sequence[T]]", compiled)

