def graph_traversal_tables_read(node_type: type[object], edge_type: type[object]) -> frozenset[str]:
    """Return physical tables read by any traversal over this node/edge pair."""
    return frozenset({get_table_name(node_type), get_table_name(edge_type)})


def build_graph_traversal_compile_plan(
    *,
    ctx: CompilationContext,
    node_type: type[VersionedObjectRow[SysId]],
    edge_type: type[VersionedObjectRow[SysId]],
    direction: str,
    dependencies: Sequence[str],
) -> GraphTraversalCompilePlan:
    """Compute shared graph traversal compile metadata once."""
    from impl.common.l2070_server_plan.steps.versioning_intent_steps import (
        _collect_dependency_auxiliary_ctes,
    )

    catalog = require_planning_catalog(ctx, site="GraphTraversalCompilePlan")
    if catalog.backend_type is None:
        msg = "Graph traversal compile plans require a backend-scoped PlanningCatalog"
        raise RuntimeError(msg)
    edge_shape = catalog.graph_access_for_model(edge_type)
    if edge_shape is None:
        msg = f"No graph access-path metadata found for edge type {edge_type.__name__}"
        raise RuntimeError(msg)
    schema_columns = ctx.schema_column_cache.get(edge_shape.table_name)
    if schema_columns is not None:
        from l2070_batching.planning_catalog import build_graph_access_path_shape

        schema_edge_shape = build_graph_access_path_shape(
            edge_type,
            include_hash32_columns=False,
            access_columns=set(schema_columns),
        )
        if schema_edge_shape is not None:
            edge_shape = schema_edge_shape
    traversal_access = _choose_graph_traversal_access(
        edge_shape,
        direction,
        needs_type_filter=bool(edge_shape.concrete_type_ids),
    )
    if traversal_access.access_path is None:
        msg = traversal_access.diagnostic or "graph traversal has no usable access path"
        raise RuntimeError(msg)
    source_endpoint, target_endpoint = _edge_endpoint_join_plans(edge_shape)
    if (source_endpoint.candidate_kind != "none" and source_endpoint.candidate_column is None) or (
        target_endpoint.candidate_kind != "none" and target_endpoint.candidate_column is None
    ):
        msg = (
            f"Graph traversal compile plan for {edge_type.__name__} must publish "
            "both source and target candidate columns from PlanningCatalog."
        )
        raise RuntimeError(msg)
    dependency_auxiliary_ctes = _collect_dependency_auxiliary_ctes(ctx, *dependencies)
    return GraphTraversalCompilePlan(
        node_type=node_type,
        edge_type=edge_type,
        direction=direction,
        access_plan=traversal_access,
        source_endpoint=source_endpoint,
        target_endpoint=target_endpoint,
        tables_read=graph_traversal_tables_read(node_type, edge_type),
        dependency_auxiliary_ctes=tuple(dependency_auxiliary_ctes or ()),
    )


def _endpoint_join_plan(endpoint: GraphEndpointAccess | None, *, role: str) -> GraphEndpointJoinPlan:
    if endpoint is None:
        msg = f"Graph traversal catalog did not publish {role} endpoint access metadata."
        raise RuntimeError(msg)
    return GraphEndpointJoinPlan(
        exact_column=SqlColumnName(endpoint.exact_column),
        candidate_kind=endpoint.candidate_kind,
        candidate_column=(SqlColumnName(endpoint.candidate_column) if endpoint.candidate_column is not None else None),
    )


def _edge_endpoint_join_plans(
    edge_shape: GraphAccessPathShape,
) -> tuple[GraphEndpointJoinPlan, GraphEndpointJoinPlan]:
    return (
        _endpoint_join_plan(edge_shape.source_endpoint, role="source"),
        _endpoint_join_plan(edge_shape.target_endpoint, role="target"),
    )


def _endpoint_exact_access_path(
    edge_shape: GraphAccessPathShape,
    direction: str,
) -> GraphAccessPath | None:
    source_endpoint = edge_shape.source_endpoint
    target_endpoint = edge_shape.target_endpoint
    if source_endpoint is None or target_endpoint is None:
        return None
    exact_columns = (source_endpoint.exact_column, target_endpoint.exact_column)
    return GraphAccessPath(
        name=f"{direction}_endpoint_exact",
        table_name=edge_shape.table_name,
        columns=exact_columns,
        logical_columns=exact_columns,
        unique=False,
        available=True,
    )


def _choose_available_graph_path(
    preferred: GraphAccessPath | None,
    baseline: GraphAccessPath | None,
) -> GraphAccessPath | None:
    if preferred is not None and preferred.available:
        return preferred
    if baseline is not None and baseline.available:
        return baseline
    return preferred or baseline


def _choose_graph_traversal_access(
    edge_shape: GraphAccessPathShape,
    direction: str,
    *,
    needs_type_filter: bool,
) -> _GraphTraversalAccessPlan:
    """Choose the access path whose column order best matches traversal predicates."""
    match direction:
        case "out":
            preferred = edge_shape.type_qualified_outgoing if needs_type_filter else None
            baseline = edge_shape.outgoing_adjacency
        case "in":
            preferred = edge_shape.type_qualified_incoming if needs_type_filter else None
            baseline = edge_shape.incoming_adjacency
        case "both":
            outgoing = _choose_available_graph_path(
                edge_shape.type_qualified_outgoing if needs_type_filter else None,
                edge_shape.outgoing_adjacency,
            )
            incoming = _choose_available_graph_path(
                edge_shape.type_qualified_incoming if needs_type_filter else None,
                edge_shape.incoming_adjacency,
            )
            if outgoing is not None and outgoing.available and incoming is not None and incoming.available:
                return _GraphTraversalAccessPlan(
                    direction=direction,
                    access_path=outgoing,
                    secondary_access_path=incoming,
                )
            endpoint_exact = _endpoint_exact_access_path(edge_shape, direction)
            if endpoint_exact is not None:
                return _GraphTraversalAccessPlan(
                    direction=direction,
                    access_path=endpoint_exact,
                    access_kind="endpoint_exact",
                )
            missing = []
            if outgoing is None or not outgoing.available:
                missing.append("outgoing")
            if incoming is None or not incoming.available:
                missing.append("incoming")
            return _GraphTraversalAccessPlan(
                direction=direction,
                access_path=None,
                diagnostic=f"bidirectional traversal lacks configured {' and '.join(missing)} adjacency",
            )
        case _:
            return _GraphTraversalAccessPlan(
                direction=direction,
                access_path=None,
                diagnostic=f"unknown graph traversal direction {direction!r}",
            )

    if preferred is not None and preferred.available:
        return _GraphTraversalAccessPlan(direction=direction, access_path=preferred)
    if baseline is not None and baseline.available:
        return _GraphTraversalAccessPlan(direction=direction, access_path=baseline)
    endpoint_exact = _endpoint_exact_access_path(edge_shape, direction)
    if endpoint_exact is not None:
        return _GraphTraversalAccessPlan(
            direction=direction,
            access_path=endpoint_exact,
            access_kind="endpoint_exact",
        )
    reason = None
    for candidate in (preferred, baseline):
        if candidate is not None and candidate.reason is not None:
            reason = candidate.reason
            break
    return _GraphTraversalAccessPlan(
        direction=direction,
        access_path=None,
        diagnostic=reason or "no configured graph adjacency index for traversal direction",
    )


class _ProjectGraphScalarPrereqStep[T](SqlRelationPublisherStep[T]):
    """Publish a scalar prerequisite as a dedicated SQL-visible CTE column."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        config: _GraphScalarPrereqConfig[T],
    ) -> None:
        super().__init__(ref_id)
        self._source_ref = config.source_ref
        self._output_column = config.output_column
        self._coerce = config.coerce

    @property
    def level(self: _ProjectGraphScalarPrereqStep[T]) -> int:
        return 0

    def step_tags(self: _ProjectGraphScalarPrereqStep[T]) -> frozenset[str]:
        return frozenset({"read", "graph", "prereq", "project", "scalar"})

    def is_read_only(self: _ProjectGraphScalarPrereqStep[T]) -> bool:
        return True

    def execution_role(self: _ProjectGraphScalarPrereqStep[T]) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def result_cardinality(self: _ProjectGraphScalarPrereqStep[T]) -> Cardinality:
        return Cardinality.ONE

    def tables_read(self: _ProjectGraphScalarPrereqStep[T]) -> frozenset[str]:
        return frozenset()

    def tables_written(self: _ProjectGraphScalarPrereqStep[T]) -> frozenset[str]:
        return frozenset()

    def dependencies(self: _ProjectGraphScalarPrereqStep[T]) -> frozenset[str]:
        return frozenset(self._source_ref.dependencies())

    def cte_publication_contract(self: _ProjectGraphScalarPrereqStep) -> CtePublicationContract:
        columns = (str(self._output_column),)

        def _legacy_cte_column_type_hints(columns: tuple[str, ...] | None) -> SqlColumnTypeHints:
            column = str(self._output_column)
            if self._coerce in {RevisionId, SysId}:
                return SqlColumnTypeHints(uuid_columns=frozenset({column}))
            return SqlColumnTypeHints(text_columns=frozenset({column}))

        column_type_hints = _legacy_cte_column_type_hints(columns)
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        contract_columns = tuple(str(column) for column in columns)
        _contract_model_cls = cte_projection_row_model(
            f"{type(self).__name__}CteRow",
            contract_columns,
            column_type_hints,
        )
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=contract_columns,
            column_type_hints=column_type_hints,
            model_cls=_contract_model_cls,
            relation_contract=CteRelationContract.semantic_row(_contract_model_cls),
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def _coercion_key(self: _ProjectGraphScalarPrereqStep[T]) -> ScalarCoercionKind | None:
        if self._coerce is RevisionId:
            return ScalarCoercionKind.REVISION_ID
        if self._coerce is SysId:
            return ScalarCoercionKind.SYS_ID
        return None

    def compile(self: _ProjectGraphScalarPrereqStep[T], ctx: CompilationContext) -> CompiledStep[T]:
        from impl.common.l2070_server_plan.steps._compile_server_ref import get_scalar_server_ref_binding
        from impl.common.l2070_server_plan.steps._auxiliary_ctes import collect_dependency_auxiliary_ctes

        binding = get_scalar_server_ref_binding(
            self._source_ref,
            ctx,
            default_field=str(self._output_column),
        )
        if binding is None:
            source_ref_id = self._source_ref.ref_id
            if source_ref_id is not None:
                found_seed, seed_value = read_seeded_constant_from_ctx(ctx, ServerPlanRefId(source_ref_id))
                if not found_seed:
                    found_seed, seed_value = read_seeded_constant_from_ctx(None, ServerPlanRefId(source_ref_id))
                if found_seed:
                    grammar = SqlSelectExpressions([(SqlParam(seed_value), str(self._output_column))])
                    __opa002_grammar_548 = grammar
                    output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(
                        self.cte_publication_contract(),
                    )
                    return CompiledStep(
                        output_shape=output_shape,
                        result_relation=result_relation,
                        column_type_hints=column_type_hints,
                        grammar=__opa002_grammar_548,
                        needs_returning=True,
                        closed_post_op=scalar_column_post_op(
                            str(self._output_column),
                            scalar_coercion=self._coercion_key() or ScalarCoercionKind.NONE,
                        ),
                    )
            raise_missing_cte_fallback_forbidden(
                site_name=type(self).__name__,
                trigger=f"graph scalar prerequisite {source_ref_id!r} has no published CTE binding",
                blocked_path="compile-time fallback from graph prerequisite projection to runtime scalar resolution",
                result_contract=(
                    "graph scalar prerequisite publication must project from explicit upstream "
                    "SQL-visible bindings before the traversal terminal compiles."
                ),
                implementation_requirements=(
                    "Lower graph revision/start-node prerequisites into explicit prerequisite steps.",
                    "Keep prerequisite publication SQL-visible through ctx.cte_refs.",
                    "Do not resolve scalar prerequisite values in Python during compile().",
                ),
            )
        grammar = SqlSelectExpressions(
            [
                (
                    SqlCteFieldRef(
                        SqlCteStepName(binding.cte_name),
                        SqlColumnName(binding.field_name),
                    ),
                    str(self._output_column),
                ),
            ],
        )
        __opa002_grammar_581 = grammar
        output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(
            self.cte_publication_contract(),
        )
        return CompiledStep(
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
            grammar=__opa002_grammar_581,
            needs_returning=True,
            closed_post_op=scalar_column_post_op(
                str(self._output_column),
                scalar_coercion=self._coercion_key() or ScalarCoercionKind.NONE,
            ),
            auxiliary_ctes=collect_dependency_auxiliary_ctes(ctx, self.dependencies(), binding.cte_name),
        )


def _coerce_revision_prerequisite(value: object) -> RevisionId | None:
    """Return a concrete ``RevisionId`` only when ``value`` is already an explicit prerequisite."""
    if value is None:
        return None
    if isinstance(value, RevisionId):
        return value
    if isinstance(value, str):
        return RevisionId(value)
    return None


def _resolve_graph_traversal_revision_for_lower(
    payload_revision: object,
    ctx: LoweringContext,
) -> tuple[RevisionId | None, ServerPlanRefId | None]:
    """Resolve revision prerequisites for lowering from explicit payload only."""
    if isinstance(payload_revision, UUID):
        return RevisionId(str(payload_revision)), None
    if isinstance(payload_revision, SysId):
        return RevisionId(str(payload_revision)), None
    revision_id, revision_ref_id = _normalize_query_revision_source(
        payload_revision,
        step_name="GraphTraversalApiStep",
    )
    if revision_ref_id is not None and str(revision_ref_id).startswith("seed_"):
        found_seed, seed_value = read_seeded_constant_from_ctx(ctx, ServerPlanRefId(revision_ref_id))
        if not found_seed:
            found_seed, seed_value = read_seeded_constant_from_ctx(None, ServerPlanRefId(revision_ref_id))
        if found_seed:
            return RevisionId(str(seed_value)), None
    if revision_id is not None or revision_ref_id is not None:
        return revision_id, revision_ref_id
    msg = (
        "GraphTraversalApiStep requires an explicit revision prerequisite in its payload; "
        "lowering may not recover revision from LoweringContext."
    )
    raise TypeError(msg)


def _cte_subquery_select_sys_ids(
    sequence_ref: ScalarSequenceServerRef[Any],
    ctx: CompilationContext,
) -> tuple[SqlRenderable, CteReference | None]:
    """Build ``SELECT <col> FROM <cte>`` for a plan-backed start-id sequence ref.

    Returns the subquery grammar plus the resolved upstream :class:`CteReference`
    so the caller can lift its ``auxiliary_query`` into the outer WITH clause.
    """
    from impl.common.l2070_server_plan.steps._compile_server_ref import get_scalar_server_ref_binding

    carrier = cast(ScalarServerRef[Any], sequence_ref)
    binding = get_scalar_server_ref_binding(carrier, ctx, default_field="sys_id")
    if binding is None:
        from impl.common.l2070_server_plan.steps._runtime_replanning_error import (
            raise_missing_cte_fallback_forbidden,
        )

        ref_id = sequence_ref.ref_id
        raise_missing_cte_fallback_forbidden(
            site_name="graph_traverse.start_node_ids_ref",
            trigger=f"compile-time lowering for {ref_id!r} without a published CTE binding",
            blocked_path="implicit resolution of ScalarSequenceServerRef outside SQL-visible prerequisites",
            result_contract=(
                "start_node_ids_ref must reference an upstream step that publishes a CTE with the "
                "start-node id column before the graph traversal terminal compiles."
            ),
            implementation_requirements=(
                "Publish start-node ids as an explicit SQL-visible prerequisite (CTE-backed step "
                "output) and keep the sequence ref symbolic until compile.",
            ),
        )
    upstream_cte: CteReference | None = None
    for candidate in ctx.cte_refs.values():
        if isinstance(candidate, CteReference) and candidate.ref_id == binding.cte_name:
            upstream_cte = candidate
            break
    row_alias = SqlAliasName("graph_start_ids_src")
    col = SqlColumnRef(SqlColumnName(binding.field_name), qualifier=row_alias)
    parts = SqlQueryParts()
    parts.set_select(SqlSelectList([col]))
    if upstream_cte is not None and upstream_cte.auxiliary_query is not None:
        from impl.common.l2100_sql_grammar.tree.clauses import SqlSubqueryTableRef

        parts.set_from(
            SqlSubqueryTableRef(
                upstream_cte.auxiliary_query,
                SqlTableName(row_alias),
            ),
        )
        upstream_cte = None
    else:
        cte_table = SqlQuotedIdentifier(SqlTableName(binding.cte_name))
        parts.set_from(SqlTableAlias(cte_table, row_alias))
    from impl.common.l2100_sql_grammar.tree.expr_ops import SqlIsNull

    parts.add_where(SqlIsNull(col, negated=True))
    return parts, upstream_cte


def _require_graph_scalar_prereq_expr(
    *,
    prereq_ref_id: ServerPlanRefId,
    output_column: SqlColumnName,
    ctx: CompilationContext,
) -> SqlRenderable:
    """Return the SQL expression for a published graph scalar prerequisite."""
    binding = ctx.cte_refs.get(str(prereq_ref_id)) if ctx.cte_refs is not None else None
    if binding is None:
        raise_missing_cte_fallback_forbidden(
            site_name="graph_traverse.prerequisite_expr",
            trigger=f"compile-time lowering for graph prerequisite {prereq_ref_id!r} without a published CTE binding",
            blocked_path="graph terminal compile fallback to non-published scalar prerequisite state",
            result_contract=(
                "graph traversal terminals must consume revision/start-node prerequisites only "
                "from explicit prerequisite steps that publish SQL-visible bindings."
            ),
            implementation_requirements=(
                "Lower graph scalar prerequisites into explicit prerequisite projection steps.",
                "Thread those step ref ids through terminal config and dependencies.",
                "Do not recover by reading runtime refs or materialized values in compile().",
            ),
        )
    return SqlCteFieldRef(
        SqlCteStepName(binding.ref_id),
        output_column,
    )


def _cte_subquery_select_scalar_sys_id(
    prereq_ref_id: ServerPlanRefId,
    ctx: CompilationContext,
) -> tuple[SqlRenderable, CteReference | None]:
    """Build ``SELECT sys_id FROM <cte>`` for a published single start-node prerequisite.

    Returns the subquery grammar plus the resolved upstream :class:`CteReference`
    so the caller can lift its ``auxiliary_query`` into the outer WITH clause.
    """
    binding = ctx.cte_refs.get(str(prereq_ref_id)) if ctx.cte_refs is not None else None
    if binding is None:
        _require_graph_scalar_prereq_expr(
            prereq_ref_id=prereq_ref_id,
            output_column=SqlColumnName("sys_id"),
            ctx=ctx,
        )
        raise AssertionError("unreachable")
    row_alias = SqlAliasName("graph_start_node_src")
    col = SqlColumnRef(SqlColumnName("sys_id"), qualifier=row_alias)
    parts = SqlQueryParts()
    parts.set_select(SqlSelectList([col]))
    if binding.auxiliary_query is not None:
        from impl.common.l2100_sql_grammar.tree.clauses import SqlSubqueryTableRef

        parts.set_from(
            SqlSubqueryTableRef(
                binding.auxiliary_query,
                SqlTableName(row_alias),
            ),
        )
        upstream_cte = None
    else:
        cte_table = SqlQuotedIdentifier(SqlTableName(binding.ref_id))
        parts.set_from(SqlTableAlias(cte_table, row_alias))
        upstream_cte = binding
    from impl.common.l2100_sql_grammar.tree.expr_ops import SqlIsNull

    parts.add_where(SqlIsNull(col, negated=True))
    return parts, upstream_cte


