def _multistart_auxiliary_ctes(
    grammar: SqlRenderable,
    dialect: SqlDialect,
    upstream_ctes: Sequence[CteReference | None] = (),
) -> list[tuple[str, Any]] | None:
    """Assemble auxiliary CTEs for the WITH clause of an inline graph traversal.

    Combines two sources:

    * ``upstream_ctes``: :class:`CteReference` bindings published by upstream
      prerequisite steps (for example ``published_0`` for a start-id subquery).
      Their ``auxiliary_query`` holds the CTE body that must appear in the outer
      WITH clause so the terminal step's rendered SQL can reference them.
    * The inline grammar's own ``active_edges`` / ``active_nodes`` CTEs, returned
      by :meth:`SqlSparseGraph*Inline.get_auxiliary_ctes`.

    Non-inline grammars (single-start) and missing bindings are silently skipped.
    Returns ``None`` when nothing needs lifting.
    """
    aux: list[tuple[str, Any]] = []
    seen: set[str] = set()
    for cte in upstream_ctes:
        if cte is None or cte.auxiliary_query is None:
            continue
        if cte.ref_id in seen:
            continue
        seen.add(cte.ref_id)
        aux.append((cte.ref_id, cte.auxiliary_query))
    getter = getattr(grammar, "get_auxiliary_ctes", None)
    if getter is not None:
        grammar_aux = getter(dialect)
        if grammar_aux:
            for name, body in grammar_aux:
                if name in seen:
                    continue
                seen.add(name)
                aux.append((name, body))
    return aux or None


def _tip_traversal_relations(
    ctx: CompilationContext,
    graph_id_val: SqlRenderable | SysIdValue,
    revision_id: object,
    node_type: type,
    edge_type: type,
    node_type_filter: SqlRenderable | None,
    edge_type_filter: SqlRenderable | None,
    traversal_plan: GraphTraversalCompilePlan,
) -> tuple[SqlRenderable, SqlRenderable] | None:
    from impl.common.l9700_sql_graph_query.cross_table_utils import get_edge_table_info, get_node_table_info
    from l7000_versioned_schema.read_source_policy import published_source_for_read
    from l7000_versioned_schema.materialization_policy import PublishedVersionSource

    if published_source_for_read(ctx) is PublishedVersionSource.TIP:
        from impl.common.l2100_sql_grammar.domain.graph.graph_sparse import (
            SqlSparseActiveCteDescriptor,
            SqlSparseActiveCteKind,
        )
        from impl.common.l9700_sql_graph_query.bounded_path_relations import tip_path_relation
        from impl.common.l9700_sql_graph_query.tip_versioning_strategy import TipVersioningStrategy
        from l7000_versioned_schema.versioned_schema import BranchId

        branch_id = BranchId(ctx.branch_id) if ctx.branch_id is not None else None
        branch_expr = lower_scalar_source(ctx.lazy_branch, ctx) if ctx.lazy_branch is not None else None
        strategy = TipVersioningStrategy(branch_id, branch_expr=branch_expr)
        local_edges_cte = SqlSparseActiveCteDescriptor(
            SqlSparseActiveCteKind.SINGLE_TABLE,
            alias=SqlAliasName("active_edges"),
            graph_id=graph_id_val,
            revision_id=revision_id,
            use_graph_hash_filter=traversal_plan.include_hash32_columns,
            query=tip_path_relation(
                get_edge_table_info(
                    edge_type,
                    include_hash32_columns=traversal_plan.include_hash32_columns,
                    include_dense_key_columns=traversal_plan.include_dense_key_columns,
                ),
                strategy, graph_id_val, edge_type_filter,
            ),
        )
        from impl.common.l2100_sql_grammar.tree.clauses import SqlSelectList
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnAlias, SqlInlineLiteral, SqlStar
        from impl.common.l2100_sql_grammar.tree.statements import SqlSelect
        from impl.common.l2100_sql_grammar.tree.table_expr import sql_subquery_table

        tip_nodes = tip_path_relation(
            get_node_table_info(node_type, include_hash32_columns=traversal_plan.include_hash32_columns),
            strategy, graph_id_val, node_type_filter,
        )
        nodes_cte = SqlSparseActiveCteDescriptor(
            SqlSparseActiveCteKind.SINGLE_TABLE,
            alias=SqlAliasName("active_nodes"),
            graph_id=graph_id_val,
            revision_id=revision_id,
            use_graph_hash_filter=traversal_plan.include_hash32_columns,
            query=SqlSelect(
                SqlSelectList([
                    SqlStar(),
                    SqlColumnAlias(SqlInlineLiteral(False), SqlAliasName("sys_deleted")),
                    SqlColumnAlias(SqlInlineLiteral(None), SqlAliasName("sys_valid_from_revision_id")),
                    SqlColumnAlias(SqlInlineLiteral(None), SqlAliasName("sys_valid_to_revision_id")),
                ]),
                from_=sql_subquery_table(tip_nodes, SqlAliasName("tip_nodes")),
            ),
        )
        return local_edges_cte, nodes_cte
    return None


def _sparse_multistart_grammar(
    *,
    ctx: CompilationContext,
    graph_id: GraphId | ScalarServerRef[GraphId],
    revision_id: object,
    node_type: type,
    edge_type: type,
    direction: str,
    min_depth: int,
    max_depth: int,
    limit: int | None,
    filter_expressions: list[Expression],
    start_ids_subquery: SqlRenderable,
    traversal_plan: GraphTraversalCompilePlan,
) -> SqlRenderable:
    """Build sparse inline graph grammar with SQL-visible multi-start (CTE or VALUES subquery)."""
    from l9600_graphs.edge_type_info import EdgeKind, get_edge_type_info

    edge_info = get_edge_type_info(edge_type)
    if edge_info.kind != EdgeKind.LOCAL:
        msg = (
            "Graph traversal with ref-backed or subquery start-node sets requires local edges; "
            "cross-graph traversal terminals require a single SQL-visible start-node prerequisite."
        )
        raise ValueError(msg)
    graph_id_val = lower_scalar_source(graph_id, ctx)
    node_type_names = list(collect_polymorphic_type_names(node_type))
    edge_type_names = list(collect_polymorphic_type_names(edge_type))
    node_type_filter = SqlTypeNameInCondition(None, node_type_names) if node_type_names else None
    edge_type_filter = SqlTypeNameInCondition(None, edge_type_names) if edge_type_names else None

    edges_cte = _require_sparse_active_cte(
        _build_edge_cte_for_type(
            edge_type,
            graph_id_val,
            revision_id,
            edge_type_filter,
            include_hash32_columns=traversal_plan.include_hash32_columns,
            include_dense_key_columns=traversal_plan.include_dense_key_columns,
        ),
        role="edge",
    )
    nodes_cte = _require_sparse_active_cte(
        _build_node_cte_for_type(
            node_type,
            graph_id_val,
            revision_id,
            node_type_filter,
            include_hash32_columns=traversal_plan.include_hash32_columns,
        ),
        role="node",
    )
    tip_relations = _tip_traversal_relations(
        ctx, graph_id_val, revision_id, node_type, edge_type,
        node_type_filter, edge_type_filter, traversal_plan,
    )
    if tip_relations is not None:
        edges_cte = _require_sparse_active_cte(tip_relations[0], role="edge")
        nodes_cte = _require_sparse_active_cte(tip_relations[1], role="node")
    edges_alias = edges_cte._alias
    nodes_alias = nodes_cte._alias
    sparse_dir = SqlSparseEdgeDirection(
        coerce_graph_direction(GraphDirection, direction),
        edge_alias=edges_alias,
        node_alias=nodes_alias,
        source_candidate_column=traversal_plan.source_candidate_column,
        target_candidate_column=traversal_plan.target_candidate_column,
    )
    user_filters = SqlUserFilterConditions(filter_expressions, SqlAliasName("final_nodes"))

    if min_depth == 1 and max_depth == 1:
        return SqlSparseGraphOneHopInline(
            edges_cte,
            nodes_cte,
            sparse_dir,
            edges_alias,
            nodes_alias,
            start_node_id=None,
            start_node_ids_subquery=start_ids_subquery,
            user_filters=user_filters,
            limit=limit,
        )
    return SqlSparseGraphMultiHopInline(
        edges_cte,
        nodes_cte,
        sparse_dir,
        start_node_id=None,
        min_depth=min_depth,
        max_depth=max_depth,
        edges_alias=edges_alias,
        nodes_alias=nodes_alias,
        start_node_ids_subquery=start_ids_subquery,
        user_filters=user_filters,
        limit=limit,
    )


def _single_start_sparse_grammar(
    *,
    ctx: CompilationContext,
    graph_id: GraphId | ScalarServerRef[GraphId],
    revision_id: object,
    start_node_id: object,
    node_type: type,
    edge_type: type,
    direction: str,
    min_depth: int,
    max_depth: int,
    limit: int | None,
    filter_expressions: list[Expression],
    traversal_plan: GraphTraversalCompilePlan,
) -> SqlRenderable:
    """Build sparse inline graph grammar with a single explicit start-node prerequisite."""
    from impl.common.l2100_sql_grammar.domain.graph.graph_sparse import (
        SqlCrossGraphEdgeFilter,
        SqlCrossGraphGraphJoin,
        SqlCrossGraphNodeJoin,
        SqlCrossGraphRevisionJoin,
        SqlSparseActiveCte,
        SqlSparseCrossGraphOneHop,
    )
    from impl.common.l9700_sql_graph_query.cross_table_utils import (
        get_edge_table_info,
        get_node_table_info,
    )
    from l9600_graphs.edge_type_info import EdgeKind, get_edge_type_info

    edge_info = get_edge_type_info(edge_type)
    graph_id_val = lower_scalar_source(graph_id, ctx)
    start_node_value = _single_start_value(start_node_id)

    if edge_info.kind != EdgeKind.LOCAL:
        if min_depth != 1 or max_depth != 1:
            msg = "Cross-graph sparse traversal terminals require an exact one-hop traversal"
            raise ValueError(msg)
        if direction == "both":
            msg = "Cross-graph sparse traversal terminals require a concrete outbound or inbound direction"
            raise ValueError(msg)

        edge_type_names = list(collect_polymorphic_type_names(edge_type))
        edge_type_filter = SqlTypeNameInCondition(None, edge_type_names) if edge_type_names else None
        node_type_names = list(collect_polymorphic_type_names(node_type))
        node_type_filter = SqlTypeNameInCondition(None, node_type_names) if node_type_names else None

        edge_table_info = get_edge_table_info(
            edge_type,
            include_hash32_columns=traversal_plan.include_hash32_columns,
            include_dense_key_columns=traversal_plan.include_dense_key_columns,
        )
        edge_table = edge_table_info[0][0]
        node_table_info = get_node_table_info(
            node_type,
            include_hash32_columns=traversal_plan.include_hash32_columns,
        )
        node_table = node_table_info[0][0]
        edges_cte = SqlSparseActiveCte(
            table=edge_table,
            alias=SqlAliasName("active_edges"),
            graph_id=graph_id_val,
            revision_id=revision_id,
            type_filter=edge_type_filter,
            use_graph_hash_filter=traversal_plan.include_hash32_columns,
        )

        edge_alias = SqlAliasName("edges")
        node_alias = SqlAliasName("nodes")
        if direction == "out":
            filter_col = edge_info.source_node_field
            node_field = edge_info.target_node_field
            graph_field = edge_info.target_graph_field
            revision_field = edge_info.target_revision_field
        else:
            filter_col = edge_info.target_node_field
            node_field = edge_info.source_node_field
            graph_field = edge_info.source_graph_field
            revision_field = edge_info.source_revision_field

        if graph_field is None or revision_field is None:
            msg = (
                f"Cross-graph traversal direction '{direction}' points to "
                f"the local side of {edge_type.__name__}; "
                f"use the local-edge traversal pattern instead"
            )
            raise ValueError(msg)

        return SqlSparseCrossGraphOneHop(
            edges_cte=edges_cte,
            node_table=node_table,
            node_join=SqlCrossGraphNodeJoin(edge_alias, node_alias, node_field),
            node_graph_join=SqlCrossGraphGraphJoin(node_alias, edge_alias, graph_field),
            node_revision_join=SqlCrossGraphRevisionJoin(node_alias, edge_alias, revision_field),
            edge_filter=SqlCrossGraphEdgeFilter(edge_alias, filter_col),
            start_node_id=start_node_value,
            node_type_filter=node_type_filter,
            edge_type_filter=edge_type_filter,
            limit=limit,
        )

    if not isinstance(start_node_value, SysIdValue):
        msg = "Local sparse traversal requires a concrete SysId value"
        raise TypeError(msg)

    node_type_names = list(collect_polymorphic_type_names(node_type))
    edge_type_names = list(collect_polymorphic_type_names(edge_type))
    node_type_filter = SqlTypeNameInCondition(None, node_type_names) if node_type_names else None
    edge_type_filter = SqlTypeNameInCondition(None, edge_type_names) if edge_type_names else None
    local_edges_cte = _build_edge_cte_for_type(
        edge_type,
        graph_id_val,
        revision_id,
        edge_type_filter,
        include_hash32_columns=traversal_plan.include_hash32_columns,
        include_dense_key_columns=traversal_plan.include_dense_key_columns,
    )
    nodes_cte = _build_node_cte_for_type(
        node_type,
        graph_id_val,
        revision_id,
        node_type_filter,
        include_hash32_columns=traversal_plan.include_hash32_columns,
    )
    tip_relations = _tip_traversal_relations(
        ctx, graph_id_val, revision_id, node_type, edge_type,
        node_type_filter, edge_type_filter, traversal_plan,
    )
    if tip_relations is not None:
        local_edges_cte, nodes_cte = tip_relations
    sparse_dir = SqlSparseEdgeDirection(
        coerce_graph_direction(GraphDirection, direction),
        source_candidate_column=traversal_plan.source_candidate_column,
        target_candidate_column=traversal_plan.target_candidate_column,
    )

    if min_depth == 1 and max_depth == 1:
        user_filters = SqlUserFilterConditions(filter_expressions, SqlAliasName("nodes"))
        return SqlSparseGraphOneHop(
            local_edges_cte,
            nodes_cte,
            sparse_dir,
            start_node_id=start_node_value,
            user_filters=user_filters,
            limit=limit,
        )

    user_filters = SqlUserFilterConditions(filter_expressions, SqlAliasName("final_nodes"))
    return SqlSparseGraphMultiHop(
        local_edges_cte,
        nodes_cte,
        sparse_dir,
        start_node_id=start_node_value,
        min_depth=min_depth,
        max_depth=max_depth,
        user_filters=user_filters,
        limit=limit,
    )


def _lower_graph_traversal_prerequisites(
    *,
    owner_ref_id: ServerPlanRefId,
    revision_ref_id: ServerPlanRefId | None,
    start_node_ref: ScalarServerRef[SysId] | None,
) -> tuple[list[ServerPlanStep[Any]], ServerPlanRefId | None, ServerPlanRefId | None]:
    prereq_steps: list[ServerPlanStep[Any]] = []
    published_revision_ref_id: ServerPlanRefId | None = None
    published_start_node_ref_id: ServerPlanRefId | None = None

    if revision_ref_id is not None:
        published_revision_ref_id = revision_ref_id

    if start_node_ref is not None:
        start_node_step = _publish_graph_scalar_prereq_step(
            owner_ref_id=owner_ref_id,
            suffix="start_node_prereq",
            source_ref=start_node_ref,
            output_column=SqlColumnName("sys_id"),
            coerce=SysId,
        )
        prereq_steps.append(start_node_step)
        published_start_node_ref_id = start_node_step.ref_id

    return prereq_steps, published_revision_ref_id, published_start_node_ref_id


class GraphTraverseStep(NonPublishingStep):
    """Compile a guarded graph traversal relation."""

    def __init__(
        self: GraphTraverseStep,
        ref_id: ServerPlanRefId,
        graph_spec: GraphTraverseSpec,
    ) -> None:
        super().__init__(ref_id)
        self._graph_spec = graph_spec

    @property
    def level(self: GraphTraverseStep) -> int:
        return 2

    def step_tags(self: GraphTraverseStep) -> frozenset[str]:
        return frozenset({"read", "graph", "traverse"})

    def is_read_only(self: GraphTraverseStep) -> bool:
        return True

    def result_cardinality(self: GraphTraverseStep) -> Cardinality:
        return Cardinality.MANY

    def tables_read(self: GraphTraverseStep) -> frozenset[str]:
        return graph_traversal_tables_read(self._graph_spec.node_type, self._graph_spec.edge_type)

    def tables_written(self: GraphTraverseStep) -> frozenset[str]:
        return frozenset()

    def lower(
        self: GraphTraverseStep,
        ctx: LoweringContext,
    ) -> Sequence[ServerPlanStep]:
        """Lower to a _GraphTraversalTerminalStep (level 0)."""
        del ctx
        spec = self._graph_spec
        revision_id, revision_ref_id = _normalize_query_revision_source(
            spec.revision_id,
            step_name="GraphTraverseStep",
        )
        if revision_id is None and revision_ref_id is None:
            msg = "GraphTraverseStep requires an explicit revision prerequisite on GraphTraverseSpec.revision_id before lowering."
            raise TypeError(msg)
        prereq_steps, published_revision_ref_id, published_start_node_ref_id = _lower_graph_traversal_prerequisites(
            owner_ref_id=self.ref_id,
            revision_ref_id=revision_ref_id,
            start_node_ref=spec.start_node_ref,
        )
        terminal = _GraphTraversalTerminalStep(
            ref_id=self.ref_id,
            config=_GraphTraversalTerminalConfig(
                graph_id=spec.graph_id,
                start_node_id=spec.start_node_id,
                revision_ref_id=published_revision_ref_id,
                start_node_ref_id=published_start_node_ref_id,
                node_type=spec.node_type,
                edge_type=spec.edge_type,
                graph_type=spec.graph_type,
                direction=spec.direction,
                max_depth=spec.max_depth,
                min_depth=spec.min_depth,
                limit=spec.limit,
                filter_expressions=spec.filter_expressions,
                revision_id=revision_id if published_revision_ref_id is None else None,
                start_node_ids_ref=spec.start_node_ids_ref,
            ),
        )
        return [*prereq_steps, terminal]

    def compile(self: GraphTraverseStep, ctx: CompilationContext) -> CompiledStep[Any]:
        """Level 2 step — must be lowered before compilation."""
        del ctx
        raise TypeError(
            f"{type(self).__name__} is level {self.level} and must be lowered to terminal steps before compile() is called.",
        )


class GraphTraversalApiStep(NonPublishingStep):
    """Step for graph traversals via the txn.graph() API.

    The API-level step remains symbolic until lowering produces the terminal
    step that builds graph SQL grammar in compile().
    """

    def __init__(
        self: GraphTraversalApiStep,
        ref_id: ServerPlanRefId,
        config: _GraphTraversalApiConfig,
        *,
        requires_visibility_guard: bool = False,
    ) -> None:
        super().__init__(ref_id)
        self._config = config
        self._requires_visibility_guard = requires_visibility_guard

    @property
    def level(self: GraphTraversalApiStep) -> int:
        return 2

    def step_tags(self: GraphTraversalApiStep) -> frozenset[str]:
        return frozenset({"read", "graph", "traversal"})

    def is_read_only(self: GraphTraversalApiStep) -> bool:
        return True

    def result_cardinality(self: GraphTraversalApiStep) -> Cardinality:
        return Cardinality.MANY

    def tables_read(self: GraphTraversalApiStep) -> frozenset[str]:
        node_type = self._config.node_type
        edge_type = self._config.edge_type
        if node_type is not None and edge_type is not None:
            return graph_traversal_tables_read(node_type, edge_type)
        if node_type is not None:
            return frozenset({get_table_name(node_type)})
        if edge_type is not None:
            return frozenset({get_table_name(edge_type)})
        return frozenset()

    def tables_written(self: GraphTraversalApiStep) -> frozenset[str]:
        return frozenset()

    def dependencies(self: GraphTraversalApiStep) -> frozenset[str]:
        deps: set[str] = {str(ref_id) for ref_id in self._config.after_refs}
        if isinstance(self._config.graph_id, ScalarServerRef):
            deps.update(self._config.graph_id.dependencies())
        revision_ref = _root_ref_id(self._config.revision_ref_id)
        if revision_ref is not None:
            deps.add(revision_ref)
        if self._config.start_node_ref is not None:
            deps.update(self._config.start_node_ref.dependencies())
        if self._config.start_node_ids_ref is not None:
            deps.update(self._config.start_node_ids_ref.dependencies())
        return frozenset(deps)

    def lower(
        self: GraphTraversalApiStep,
        ctx: LoweringContext,
    ) -> Sequence[ServerPlanStep]:
        """Lower to a _GraphTraversalTerminalStep (level 0)."""
        cfg = self._config
        payload_revision: object = cfg.revision_ref_id if cfg.revision_ref_id is not None else cfg.revision_id
        revision_id, revision_ref_id = _resolve_graph_traversal_revision_for_lower(
            payload_revision,
            ctx,
        )
        start_node_id = cfg.start_node_id
        start_node_ref = cfg.start_node_ref
        if start_node_ref is not None:
            start_node_ref_id = start_node_ref.ref_id
            if start_node_ref_id is not None and start_node_ref_id.startswith("seed_"):
                found_seed, seed_value = read_seeded_constant_from_ctx(ctx, ServerPlanRefId(start_node_ref_id))
                if not found_seed:
                    found_seed, seed_value = read_seeded_constant_from_ctx(None, ServerPlanRefId(start_node_ref_id))
                if found_seed:
                    start_node_id = SysId(str(seed_value))
                    start_node_ref = None
        prereq_steps, published_revision_ref_id, published_start_node_ref_id = _lower_graph_traversal_prerequisites(
            owner_ref_id=self.ref_id,
            revision_ref_id=revision_ref_id,
            start_node_ref=start_node_ref,
        )
        visibility_steps: list[ServerPlanStep[Any]] = []
        terminal_after_refs = cfg.after_refs
        if ctx.explicit_revision_id is None:
            for branch_source in (ctx.lazy_branch, ctx.lazy_branch_tip_materialization):
                if branch_source is not None:
                    terminal_after_refs = terminal_after_refs | frozenset(
                        ServerPlanRefId(ref) for ref in branch_source.dependencies()
                    )
        if self._requires_visibility_guard and ctx.versioning_domain is not None:
            from impl.common.l2070_server_plan.steps.intent_versioning_extended import (
                VersionedSelectOneIntent,
                _VersionedSelectOneConfig,
            )
            from impl.common.l2070_server_plan.steps.return_value import (
                RequirePermittedRowStep,
                _RequirePermittedRowConfig,
            )

            graph_type = cfg.graph_type
            if not isinstance(graph_type, type) or not issubclass(graph_type, DatabaseObjectRow):
                msg = "Guarded graph traversal requires a concrete graph row type"
                raise TypeError(msg)
            graph_id = cfg.graph_id
            if isinstance(graph_id, ScalarServerRef):
                graph_id_ref = graph_id.ref_id
                if graph_id_ref is not None:
                    found_graph_id, graph_id_value = read_seeded_constant_from_ctx(
                        ctx,
                        ServerPlanRefId(graph_id_ref),
                    )
                    if not found_graph_id:
                        found_graph_id, graph_id_value = read_seeded_constant_from_ctx(
                            None,
                            ServerPlanRefId(graph_id_ref),
                        )
                    if found_graph_id:
                        graph_id = GraphId(str(graph_id_value))
            if not isinstance(graph_id, GraphId):
                msg = "Guarded graph traversal requires a concrete graph ID"
                raise TypeError(msg)
            if published_revision_ref_id is not None:
                revision_source = ServerRefs.from_ref_id(
                    published_revision_ref_id,
                    variant="scalar",
                )
            elif revision_id is not None:
                revision_source = ServerRefs.scalar(revision_id)
            elif ctx.lazy_revision is not None:
                revision_source = ctx.lazy_revision
            else:
                revision_source = ServerRefs.scalar(RevisionId.current())
            visible_graph_ref = ServerPlanRefId(f"{self.ref_id}_visible_graph")
            visible_graph_intent = VersionedSelectOneIntent(
                visible_graph_ref,
                model_cls=graph_type,
                config=ServerRefs.scalar(
                    _VersionedSelectOneConfig(
                        sys_id=ServerRefs.scalar(graph_id),
                        revision_id=revision_source,
                        domain=ctx.versioning_domain,
                        include_deleted=False,
                    ),
                ),
            )
            visibility_steps.extend(visible_graph_intent.lower(ctx))
            visible_rows_ref = ServerPlanRefId(f"{visible_graph_ref}.raw_rows")
            required_ref = ServerPlanRefId(f"{self.ref_id}_visible_graph_required")
            visibility_steps.append(
                RequirePermittedRowStep(
                    required_ref,
                    config=_RequirePermittedRowConfig(
                        source_ref=visible_rows_ref,
                        error_message=f"Graph {graph_id} is not visible in the current versioned read context",
                    ),
                ),
            )
            terminal_after_refs = terminal_after_refs | frozenset({required_ref})

        terminal = _GraphTraversalTerminalStep(
            ref_id=self.ref_id,
            config=_GraphTraversalTerminalConfig(
                graph_id=cfg.graph_id,
                start_node_id=start_node_id,
                revision_ref_id=published_revision_ref_id,
                start_node_ref_id=published_start_node_ref_id,
                node_type=cfg.node_type,
                edge_type=cfg.edge_type,
                direction=cfg.direction,
                max_depth=cfg.max_depth,
                min_depth=cfg.min_depth,
                limit=cfg.limit,
                filter_expressions=cfg.filter_exprs,
                revision_id=revision_id if published_revision_ref_id is None else None,
                start_node_ids_ref=cfg.start_node_ids_ref,
                graph_type=cfg.graph_type,
                after_refs=terminal_after_refs,
            ),
        )
        return [*prereq_steps, *visibility_steps, terminal]

    def compile(self: GraphTraversalApiStep, ctx: CompilationContext) -> CompiledStep[Any]:
        """Level 2 step — must be lowered before compilation."""
        del ctx
        raise TypeError(
            f"{type(self).__name__} is level {self.level} and must be lowered to terminal steps before compile() is called.",
        )


class PublicGraphTraversalIntent[T](IntentStep[list[T]]):
    """Transportable public graph traversal preserving ``graph_traverse_lazy`` semantics."""

    intent_tags = frozenset({"read", "graph", "traversal", "intent"})
    intent_cardinality = Cardinality.MANY
    intent_read_only = True

    def __init__(
        self: PublicGraphTraversalIntent,
        ref_id: ServerPlanRefId,
        config: _GraphTraversalApiConfig,
    ) -> None:
        super().__init__(ref_id)
        self._config = replace(config, after_refs=frozenset())

    @property
    def model_cls(self: PublicGraphTraversalIntent) -> type[object]:
        return self._config.node_type

    def tables_read(self: PublicGraphTraversalIntent) -> frozenset[str]:
        return GraphTraversalApiStep(self.ref_id, self._config).tables_read()

    def tables_written(self: PublicGraphTraversalIntent) -> frozenset[str]:
        return frozenset()

    def dependencies(self: PublicGraphTraversalIntent) -> frozenset[str]:
        return GraphTraversalApiStep(self.ref_id, self._config).dependencies()

    def dependency_contract(self: PublicGraphTraversalIntent) -> StepDependencyContract:
        refs = frozenset(ref for ref in self.dependencies() if not ref.partition(".")[0].startswith("seed_"))
        return StepDependencyContract.from_refs(
            refs,
            source=DependencySource.GRAPH_CONFIG,
            required_for=frozenset({DependencyUse.ORDERING, DependencyUse.TRANSPORT_GRAPH}),
            transport=TransportDependencyPolicy.TRANSPORTABLE,
            reason="graph traversal config carries symbolic graph/revision refs",
        )

    def lower(
        self: PublicGraphTraversalIntent,
        ctx: LoweringContext,
    ) -> Sequence[ServerPlanStep]:
        traversal = GraphTraversalApiStep(
            self.ref_id,
            replace(self._config, after_refs=frozenset()),
            requires_visibility_guard=True,
        )
        return [traversal]


def _project_graph_traversal_transport(
    grammar: SqlRenderable,
    columns: tuple[str, ...],
    available_columns: frozenset[str] | None,
    column_type_hints: SqlColumnTypeHints,
    transport: GraphProjectionTransport,
    transport_key: str,
) -> SqlRenderable:
    """Project sparse rows when their physical shape exceeds the declared relation."""
    declared_columns = frozenset(columns)
    if transport is not GraphProjectionTransport.SPARSE_DECLARED_COLUMNS and (
        available_columns is None or available_columns.issubset(declared_columns)
    ):
        return grammar
    from impl.common.l2050_sql_types.sql_branded_types import SqlAliasName, SqlColumnName, SqlCteName, SqlTableName
    from impl.common.l2100_sql_grammar.tree.clauses import SqlSelectAlias, SqlSelectList
    from impl.common.l2100_sql_grammar.tree.expr_compound import SqlCast
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlInlineLiteral
    from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
    from impl.common.l2100_sql_grammar.tree.statements import SqlCte, SqlSelect

    from hashlib import sha256

    transport_suffix = sha256(transport_key.encode("utf-8")).hexdigest()[:12]
    cte_name = SqlCteName(f"__graph_traversal_{transport_suffix}")
    projection_items: list[SqlRenderable] = []
    for column in columns:
        if available_columns is None or column in available_columns:
            projection_items.append(SqlColumnRef(SqlColumnName(column)))
            continue
        cast_target = column_type_hints.cast_target_for_column(column)
        missing_expr: SqlRenderable = SqlCast(SqlInlineLiteral(None), cast_target) if cast_target is not None else SqlInlineLiteral(None)
        projection_items.append(
            SqlSelectAlias(missing_expr, alias=SqlAliasName(column)),
        )
    projection = SqlSelect(
        select=SqlSelectList(projection_items),
        from_=SqlTableIdent(SqlTableName(cte_name)),
    )
    return SqlCte([(cte_name, grammar)], projection, recursive=True)


class _GraphTraversalTerminalStep(SqlRelationPublisherStep):
    """Level 0 graph terminal: compiles SQL from explicit revision and start-node prerequisites."""

    def _node_model_cls(self: _GraphTraversalTerminalStep) -> type[DatabaseObjectRow[Any]]:
        node_type = self._node_type
        if not isinstance(node_type, type) or not issubclass(node_type, DatabaseObjectRow):
            msg = f"Graph traversal node_type must be a DatabaseObjectRow, got {node_type!r}"
            raise TypeError(msg)
        return cast("type[DatabaseObjectRow[Any]]", node_type)

    def _publication_model_classes(
        self: _GraphTraversalTerminalStep,
    ) -> tuple[type[DatabaseObjectRow[Any]], ...]:
        node_type = self._node_model_cls()
        for ancestor in node_type.__mro__:
            if bool(ancestor.__dict__.get("_is_dynamic_base", False)):
                assert issubclass(ancestor, DatabaseObjectRow)
                return (ancestor,)

        from impl.common.l9700_sql_graph_query.cross_table_utils import get_node_table_info

        table_info = get_node_table_info(node_type, include_hash32_columns=False)
        if len(table_info) > 1:
            from l9600_graphs.dynamic_types import DynamicNodeBase

            return (node_type, DynamicNodeBase)
        node_table = get_table_name(node_type)
        family_root = node_type
        for ancestor in node_type.__mro__[1:]:
            if not issubclass(ancestor, DatabaseObjectRow):
                continue
            try:
                ancestor_table = get_table_name(ancestor)
            except (AttributeError, ValueError):
                continue
            if ancestor_table != node_table:
                break
            family_root = ancestor

        from impl.common.l9700_sql_graph_query.cross_table_utils import _spans_dynamic_nodes
        from l9600_graphs.dynamic_types import DynamicNodeBase
        from l9600_graphs.graph import GraphNode

        dynamic_storage_models: tuple[type[DatabaseObjectRow[Any]], ...] = (
            (DynamicNodeBase,) if family_root is GraphNode and _spans_dynamic_nodes(node_type) else ()
        )
        descendants: list[type[DatabaseObjectRow[Any]]] = []
        if family_root is not GraphNode:
            pending = list(family_root.__subclasses__())
            while pending:
                subtype = pending.pop()
                pending.extend(subtype.__subclasses__())
                if issubclass(subtype, DatabaseObjectRow):
                    descendants.append(subtype)

        subtypes = tuple(
            subtype for subtype in collect_polymorphic_dispatch_subtypes(node_type) if issubclass(subtype, DatabaseObjectRow)
        )
        physical_models = tuple(
            model_cls
            for model_cls in get_schema_models_for_table(node_type)
            if issubclass(model_cls, DatabaseObjectRow) and (issubclass(model_cls, family_root) or issubclass(family_root, model_cls))
        )
        return tuple(
            dict.fromkeys(
                (
                    node_type,
                    *subtypes,
                    *physical_models,
                    *dynamic_storage_models,
                    *sorted(
                        descendants,
                        key=lambda model_cls: (model_cls.__module__, model_cls.__qualname__),
                    ),
                ),
            ),
        )

    def _publication_db_columns(self: _GraphTraversalTerminalStep) -> tuple[str, ...]:
        node_table_name = get_table_name(self._node_model_cls())
        model_classes = tuple(
            model_cls
            for model_cls in self._publication_model_classes()
            if get_table_name(model_cls) == node_table_name
            or any(bool(mro_class.__dict__.get("_is_dynamic_base", False)) for mro_class in model_cls.__mro__)
        )
        storage_model_list: list[type[DatabaseObjectRow[Any]]] = []
        for model_cls in model_classes:
            storage_model = model_cls
            for mro_class in model_cls.__mro__:
                if not bool(mro_class.__dict__.get("_is_dynamic_base", False)):
                    continue
                assert issubclass(mro_class, DatabaseObjectRow)
                storage_model = mro_class
                break
            if storage_model not in storage_model_list:
                storage_model_list.append(storage_model)
        storage_models = tuple(storage_model_list)
        return tuple(
            dict.fromkeys(

                get_db_column_name(model_cls, DynamicFieldName(field_name))
                for model_cls in storage_models
                for field_name in model_cls.model_fields

            ),
        )

    def _publication_type_hints(self: _GraphTraversalTerminalStep) -> SqlColumnTypeHints:
        db_columns = self._publication_db_columns()
        model_hints = tuple(
            hints
            for model_cls in self._publication_model_classes()
            if (hints := model_sql_column_type_hints(model_cls, db_columns)) is not None
        )
        return combine_sql_column_type_hints(db_columns, *model_hints)

    def _sparse_executor_columns(self: _GraphTraversalTerminalStep) -> tuple[str, ...]:
        node_type = self._node_model_cls()
        db_columns = self._publication_db_columns()
        model_payload_columns = tuple(
            "sys_valid_from_revision_id" if column == "sys_revision_id" else column
            for column in db_columns
            if column
            not in {
                "branch_id",
                "branch_hash32",
                "graph_hash32",
                "branch_ord",
                "sys_id",
                "sys_created_at",
                "sys_updated_at",
                "sys_deleted",
                "sys_revision_id",
                "sys_valid_from_revision_id",
                "sys_valid_to_revision_id",
                "sys_valid_from_seq",
                "sys_valid_to_seq",
                "sys_staged_commit_id",
            }
        )
        discriminator_columns = ("type_name",) if collect_polymorphic_type_names(node_type) else ()
        return tuple(
            dict.fromkeys(
                (
                    "branch_id",
                    "sys_id",
                    "sys_valid_from_revision_id",
                    "sys_valid_to_revision_id",
                    "sys_created_at",
                    "sys_updated_at",
                    "sys_deleted",
                    *discriminator_columns,
                    *model_payload_columns,
                    "branch_hash32",
                    "graph_hash32",
                    "branch_ord",
                    "sys_valid_from_seq",
                    "sys_valid_to_seq",
                ),
            ),
        )

    def publishes_executor_visible_binding(self: _GraphTraversalTerminalStep) -> bool:
        """Traversal terminals publish raw rows for downstream permission guards."""
        return True

    def executor_publication_projection_columns(
        self: _GraphTraversalTerminalStep,
    ) -> tuple[str, ...]:
        """Project generated sparse rows to the producer-owned transport shape."""
        return self._sparse_executor_columns()

    def semantic_publication_columns(self: _GraphTraversalTerminalStep) -> tuple[str, ...]:
        return self._publication_db_columns()

    def semantic_publication_type_hints(self: _GraphTraversalTerminalStep) -> SqlColumnTypeHints:
        return self._publication_type_hints()

    def cte_publication_contract(self: _GraphTraversalTerminalStep) -> CtePublicationContract:
        node_type = self._node_model_cls()
        db_columns = self._publication_db_columns()
        columns = self._sparse_executor_columns()
        raw_column_type_hints = self._publication_type_hints()
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if raw_column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        column_type_hints = combine_sql_column_type_hints(
            columns,
            raw_column_type_hints.filtered(set(columns)),
            raw_column_type_hints.rename_column("sys_revision_id", "sys_valid_from_revision_id"),
            framework_physical_column_sql_column_type_hints(),
            SqlColumnTypeHints(
                text_columns=frozenset(
                    ("type_name",) if collect_polymorphic_type_names(self._node_type) else (),
                ),
            ),
        )
        contract_columns = tuple(str(column) for column in columns)

        required_node_columns = {
            get_db_column_name(node_type, DynamicFieldName(field_name)) for field_name in node_type.model_fields
        }

        _contract_model_cls = cte_projection_row_model(
            f"{type(self).__name__}CteRow",
            contract_columns,
            column_type_hints,
        )
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=contract_columns,
            column_type_hints=column_type_hints,
            model_cls=_contract_model_cls,
            relation_contract=CteRelationContract.projection_over_model(
                source_model_cls=node_type,
                projection_lineage=tuple((column, column) for column in contract_columns),
            ),
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
            optional_columns=frozenset(
                column
                for column in contract_columns
                if column
                in {
                    "branch_id",
                    "branch_hash32",
                    "graph_hash32",
                    "source_hash32",
                    "target_hash32",
                    "branch_ord",
                    "sys_valid_from_seq",
                    "sys_valid_to_seq",
                }
                or column not in required_node_columns
            ),
        )

    def __init__(
        self: _GraphTraversalTerminalStep,
        ref_id: ServerPlanRefId,
        config: _GraphTraversalTerminalConfig,
    ) -> None:
        super().__init__(ref_id)
        self._graph_id = config.graph_id
        self._start_node_id = config.start_node_id
        self._start_node_ref_id = config.start_node_ref_id
        self._node_type = config.node_type
        self._model_cls = config.node_type
        self._edge_type = config.edge_type
        self._direction = config.direction
        self._max_depth = config.max_depth
        self._min_depth = config.min_depth
        self._limit = config.limit
        self._filter_expressions = config.filter_expressions or []
        self._revision_id = config.revision_id
        self._revision_ref_id = config.revision_ref_id
        self._start_node_ids_ref = config.start_node_ids_ref
        self._graph_type = config.graph_type
        self._after_refs = config.after_refs

    @property
    def level(self: _GraphTraversalTerminalStep) -> int:
        return 0

    def step_tags(self: _GraphTraversalTerminalStep) -> frozenset[str]:
        return frozenset({"read", "graph", "traverse", "terminal", "grammar"})

    def is_read_only(self: _GraphTraversalTerminalStep) -> bool:
        return True

    def execution_role(self: _GraphTraversalTerminalStep) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def result_cardinality(self: _GraphTraversalTerminalStep) -> Cardinality:
        return Cardinality.MANY

    def dependencies(self: _GraphTraversalTerminalStep) -> frozenset[str]:
        """Return ref_ids this step depends on."""
        deps: set[str] = set()
        if self._revision_ref_id is not None:
            deps.add(str(self._revision_ref_id))
        if self._start_node_ref_id is not None:
            deps.add(str(self._start_node_ref_id))
        ref = self._start_node_ids_ref
        if isinstance(ref, ServerRef):
            deps.update(ref.dependencies())
        deps.update(str(ref_id) for ref_id in self._after_refs)
        return frozenset(deps)

    def tables_read(self: _GraphTraversalTerminalStep) -> frozenset[str]:
        return graph_traversal_tables_read(self._node_type, self._edge_type)

    def tables_written(self: _GraphTraversalTerminalStep) -> frozenset[str]:
        return frozenset()

    def consumes_executor_visible_dependencies(self: _GraphTraversalTerminalStep) -> bool:
        return bool(self.dependencies())

    def compile(
        self: _GraphTraversalTerminalStep,
        ctx: CompilationContext,
    ) -> CompiledStep[Any]:
        from l2070_batching.compilation import CompiledStep as CompiledStepFactory
        from l2070_batching.output_shape import (
            CompiledOutputShape,
            DeclaredResultRelation,
            synthetic_output_field,
        )

        contract = self.cte_publication_contract()
        output_shape = CompiledOutputShape(
            tuple(synthetic_output_field(column) for column in contract.columns),
        )
        result_relation = DeclaredResultRelation.from_output_shape(output_shape)

        revision = _effective_query_revision_override(
            self._revision_id,
            self._revision_ref_id,
            ctx,
            step_name=type(self).__name__,
        )
        if revision is None:
            msg = (
                "Graph traversal terminal requires an explicit revision prerequisite; "
                "implicit transaction-bound graph context is no longer supported."
            )
            raise TypeError(msg)
        dialect = ctx.sql_render_dialect()
        node_type = _require_versioned_row_type(self._node_type, role="node_type")
        edge_type = _require_versioned_row_type(self._edge_type, role="edge_type")
        traversal_plan = build_graph_traversal_compile_plan(
            ctx=ctx,
            node_type=node_type,
            edge_type=edge_type,
            direction=self._direction,
            dependencies=tuple(self.dependencies()),
        )
        from l3250_migrations.versioned_table_helpers import (
            VersionedTableType,
            get_auxiliary_table_name,
        )

        sparse_table_name = get_auxiliary_table_name(node_type, VersionedTableType.SPARSE)
        available_transport_columns = ctx.schema_column_cache.get(sparse_table_name)
        if available_transport_columns is None:
            unavailable_adjuncts: set[str] = {
                "branch_id",
                "branch_ord",
                "sys_valid_from_seq",
                "sys_valid_to_seq",
                "sys_fts_content_hash",
                "sys_fts_hash_short",
                "sys_fts_hash_high",
            }
            if not traversal_plan.include_hash32_columns:
                unavailable_adjuncts.update({"branch_hash32", "graph_hash32", "source_hash32", "target_hash32"})
            if not traversal_plan.include_dense_key_columns:
                unavailable_adjuncts.update({"graph_key", "source_node_key", "target_node_key"})
            available_transport_columns = frozenset(set(contract.columns) - unavailable_adjuncts)

        target_node_type = node_type

        seq_ref = self._start_node_ids_ref
        if isinstance(seq_ref, ScalarSequenceServerRef):
            subquery, upstream_cte = _cte_subquery_select_sys_ids(seq_ref, ctx)
            sparse_grammar = _sparse_multistart_grammar(
                ctx=ctx,
                graph_id=cast(GraphId, self._graph_id),
                revision_id=revision,
                node_type=node_type,
                edge_type=edge_type,
                direction=self._direction,
                min_depth=self._min_depth,
                max_depth=self._max_depth,
                limit=self._limit,
                filter_expressions=self._filter_expressions,
                start_ids_subquery=subquery,
                traversal_plan=traversal_plan,
            )

            auxiliary_ctes = traversal_plan.auxiliary_ctes_with(
                *(
                    _multistart_auxiliary_ctes(
                        sparse_grammar,
                        dialect,
                        upstream_ctes=(upstream_cte,),
                    )
                    or []
                ),
            )

            return CompiledStepFactory(
                output_shape=output_shape,
                result_relation=result_relation,
                grammar=_project_graph_traversal_transport(
                    sparse_grammar,
                    contract.columns,
                    available_transport_columns,
                    contract.column_type_hints,
                    ctx.backend_profile.traits.graph_projection_transport,
                    str(self.ref_id),
                ),
                column_type_hints=contract.column_type_hints,
                needs_returning=True,
                needs_recursive_with=True,
                closed_post_op=graph_nodes_post_op(target_node_type),
                auxiliary_ctes=auxiliary_ctes or None,
            )

        start_node_ref_id = self._start_node_ref_id
        if start_node_ref_id is not None:
            from l9600_graphs.edge_type_info import EdgeKind, get_edge_type_info

            edge_info = get_edge_type_info(edge_type)
            if edge_info.kind == EdgeKind.LOCAL:
                subquery, upstream_cte = _cte_subquery_select_scalar_sys_id(
                    start_node_ref_id,
                    ctx,
                )
                sparse_grammar = _sparse_multistart_grammar(
                    ctx=ctx,
                    graph_id=cast(GraphId, self._graph_id),
                    revision_id=revision,
                    node_type=node_type,
                    edge_type=edge_type,
                    direction=self._direction,
                    min_depth=self._min_depth,
                    max_depth=self._max_depth,
                    limit=self._limit,
                    filter_expressions=self._filter_expressions,
                    start_ids_subquery=subquery,
                    traversal_plan=traversal_plan,
                )

                auxiliary_ctes = traversal_plan.auxiliary_ctes_with(
                    *(
                        _multistart_auxiliary_ctes(
                            sparse_grammar,
                            dialect,
                            upstream_ctes=(upstream_cte,),
                        )
                        or []
                    ),
                )

                return CompiledStepFactory(
                    output_shape=output_shape,
                    result_relation=result_relation,
                    grammar=_project_graph_traversal_transport(
                        sparse_grammar,
                        contract.columns,
                        available_transport_columns,
                        contract.column_type_hints,
                        ctx.backend_profile.traits.graph_projection_transport,
                        str(self.ref_id),
                    ),
                    column_type_hints=contract.column_type_hints,
                    needs_returning=True,
                    needs_recursive_with=True,
                    closed_post_op=graph_nodes_post_op(target_node_type),
                    auxiliary_ctes=auxiliary_ctes or None,
                )
            effective_start: object = _require_graph_scalar_prereq_expr(
                prereq_ref_id=start_node_ref_id,
                output_column=SqlColumnName("sys_id"),
                ctx=ctx,
            )
        else:
            effective_start = self._start_node_id
        if effective_start is None:
            msg = (
                "Graph traversal terminal requires explicit start_node_id, start_node_ref, or "
                "start_node_ids_ref prerequisites (single id, symbolic single id, literal "
                "sequence, or CTE-bound sequence ref)."
            )
            raise TypeError(msg)

        single_grammar = _single_start_sparse_grammar(
            ctx=ctx,
            graph_id=cast(GraphId, self._graph_id),
            revision_id=revision,
            start_node_id=effective_start,
            node_type=node_type,
            edge_type=edge_type,
            direction=self._direction,
            min_depth=self._min_depth,
            max_depth=self._max_depth,
            limit=self._limit,
            filter_expressions=self._filter_expressions,
            traversal_plan=traversal_plan,
        )
        return CompiledStepFactory(
            output_shape=output_shape,
            result_relation=result_relation,
            grammar=_project_graph_traversal_transport(
                single_grammar,
                contract.columns,
                available_transport_columns,
                contract.column_type_hints,
                ctx.backend_profile.traits.graph_projection_transport,
                str(self.ref_id),
            ),
            column_type_hints=contract.column_type_hints,
            needs_returning=True,
            needs_recursive_with=True,
            closed_post_op=graph_nodes_post_op(target_node_type),
            auxiliary_ctes=traversal_plan.auxiliary_ctes_with(),
        )

