@dataclass(frozen=True, slots=True)
class _QueueVisibleRowTableEventsEffect(PipelineLifecycleEffect):
    """Queue snapshots before commit; the dispatcher delivers them after commit."""

    model_cls: type[DatabaseObjectRow]
    event_type: Literal["INSERT", "UPDATE", "UPSERT", "DELETE"]
    rows: tuple[object, ...]
    old_rows: tuple[object, ...] = ()
    rows_ref: ServerPlanRefId | None = None
    old_rows_ref: ServerPlanRefId | None = None
