    )


def build_versioned_commit_local_event_effects(
    *,
    model_classes: tuple[type[DatabaseObjectRow], ...],
    rows: tuple[object, ...],
    writer_ref: ServerPlanRefId | None = None,
) -> tuple[_QueueVisibleRowTableEventsEffect, ...]:
    """Build signed local callback effects from committed versioned deltas."""
    if not model_classes:
        raise ValueError("Committed local delivery requires at least one model class")
    models_by_name = {model_cls.__name__: model_cls for model_cls in model_classes}
    effects: list[_QueueVisibleRowTableEventsEffect] = []
    for raw_row in rows:
        if not isinstance(raw_row, Mapping):
            raise TypeError("A versioned commit delta row must be a mapping")
        delta_row: Mapping[object, object] = raw_row
        event_type_value = delta_row.get("event_class")
        if not isinstance(event_type_value, str):
            raise TypeError("A versioned commit delta row requires an event class")
        normalized_event_type = event_type_value.upper()
        if normalized_event_type == "INSERT":
            event_type: Literal["INSERT", "UPDATE", "DELETE"] = "INSERT"
        elif normalized_event_type == "UPDATE":
            event_type = "UPDATE"
        elif normalized_event_type == "DELETE":
            event_type = "DELETE"
        else:
            raise ValueError(f"Unsupported versioned commit event class: {event_type_value}")
        row_id = delta_row.get("sys_id")
        branch_id = delta_row.get("branch_id")
        revision_id = delta_row.get("revision_id")
        if row_id is None or branch_id is None or revision_id is None:
            raise ValueError("A versioned commit delta row requires row, branch, and revision identity")
        type_name = delta_row.get("new_type_name") or delta_row.get("old_type_name")
        if type_name is None:
            if len(model_classes) != 1:
                raise ValueError("A shared versioned table delta requires concrete type identity")
            resolved_model_cls = model_classes[0]
        else:
            candidate_model_cls = models_by_name.get(str(type_name))
            if candidate_model_cls is None:
                raise ValueError(f"Unknown committed delta model type: {type_name}")
            resolved_model_cls = candidate_model_cls

        def _state(prefix: str) -> DatabaseObjectRow:
            values: dict[str, object] = {"sys_id": row_id, "revision_id": revision_id}
            for field_name in resolved_model_cls.model_fields:
                key = f"{prefix}_{field_name}"
                if key in delta_row:
                    values[field_name] = delta_row[key]
            return resolved_model_cls.model_validate(values)

        visible_row = _state("old" if event_type == "DELETE" else "new")
        old_rows = (_state("old"),) if event_type == "UPDATE" else ()
        effects.append(
            _QueueVisibleRowTableEventsEffect(
                model_cls=resolved_model_cls,
                event_type=event_type,
                rows=(visible_row,),
                old_rows=old_rows,
                branch_id=branch_id,
                revision_id=revision_id,
                subscription_phase="committed",
                stage_remote_notification=False,
                writer_ref=writer_ref,
            ),
        )
    return tuple(effects)


