) -> tuple[CompiledOutputShape, DeclaredResultRelation, SqlColumnTypeHints]:
    """Declare physical rows consumed by lifecycle post-processing."""
    from l2070_batching.sql_column_type_hints import model_sql_column_type_hints
    from l2070_batching.write_column_policy import returnable_db_columns

    resolved_columns = tuple(str(column) for column in returnable_db_columns(model_cls)) if columns is None else columns
    column_type_hints = model_sql_column_type_hints(model_cls, resolved_columns)
    if column_type_hints is None:
        msg = f"Could not resolve lifecycle row hints for {model_cls.__name__}"
        raise TypeError(msg)
    relation_contract = (
        CteRelationContract.semantic_row(model_cls)
        if columns is None
        else CteRelationContract.projection_over_model(
            source_model_cls=model_cls,
            projection_lineage=tuple((column, column) for column in resolved_columns),
        )
    )
    output_shape = output_shape_from_cte_publication_contract(
        CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=resolved_columns,
            column_type_hints=column_type_hints,
            model_cls=model_cls,
            relation_contract=relation_contract,
        ),
        role="lifecycle_physical_rows",
    )
    return (
        output_shape,
        DeclaredResultRelation.from_output_shape(output_shape),
