class ResolveBranchIdByNameAnyWorkspaceStep(SqlRelationPublisherStep[BranchId]):
    """L0: Resolve a branch ``sys_id`` by branch name without workspace filter.

    Used when the read path has a domain but no known ``workspace_id`` (for
    example, a non-versioned read transaction that issues a history query
    against a domain whose ``workspace_id`` attribute was never set on the
    domain class). The domain's branch table is already
    domain-scoped, so a unique lookup by ``name`` (with ``sys_deleted = false``)
    is well-defined as long as no two workspaces share a branch name in this
    domain.
    """

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        branch_table: SqlTableName,
        branch_name: ScalarServerRef[BranchName],
    ) -> None:
        super().__init__(ref_id)
        self._branch_table = branch_table
        self._branch_name = branch_name

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self) -> bool:
        return True

    def step_tags(self) -> frozenset[str]:
        return frozenset({"read", "scalar", "branch", "lookup"})

    def tables_read(self) -> frozenset[str]:
        return frozenset({str(self._branch_table)})

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def dependencies(self) -> frozenset[str]:
        return frozenset(str(dep) for dep in self._branch_name.dependencies())

    def cte_publication_contract(self: ResolveBranchIdByNameAnyWorkspaceStep) -> CtePublicationContract:
        columns = ("sys_id",)
        column_type_hints = _branch_id_type_hints("sys_id")
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        _contract_model_cls = _ResolveBranchIdByNameAnyWorkspaceStepCteRow
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=tuple(str(column) for column in columns),
            column_type_hints=column_type_hints,
            model_cls=_contract_model_cls,
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def compile(self, ctx: CompilationContext) -> CompiledStep[BranchId]:
        branch_name_expr = lower_scalar_server_ref(self._branch_name, ctx)
        stmt = SqlDynamicSelectStmt(
            from_table=self._branch_table,
            columns=[SqlColumnName("sys_id")],
            where_conditions=[
                SqlBinaryOp(
                    SqlColumnRef(SqlColumnName("name")),
                    BinaryOp.EQ,
                    branch_name_expr,
                ),
                SqlBinaryOp(
                    SqlColumnRef(SqlColumnName("sys_deleted")),
                    BinaryOp.EQ,
                    SqlParam(False),
                ),
            ],
            limit=1,
        )

        __opa002_grammar_255 = stmt
        output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(
            self.cte_publication_contract(),
        )
        return CompiledStep(
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
            grammar=__opa002_grammar_255,
            closed_post_op=required_scalar_column_post_op(
                "sys_id",
                error_message="Branch not found",
                scalar_coercion=ScalarCoercionKind.BRANCH_ID,
            ),
            needs_returning=True,
        )


