def _build_revision_meta(
    revision_model_cls: type[BaseRevision],
    revision: BaseRevision | None,
    valid_from: RevisionId,
) -> RevisionMeta:
    from l1300_session.session import SessionId

    if revision is None:
        return RevisionMeta(
            revision_id=valid_from,
            session_id=SessionId.schema(),
            timestamp=datetime.now(UTC),
        )

    if isinstance(revision, dict):
        revision_id_raw = revision.get("sys_id", valid_from)
        session_id_raw = revision.get("session_id")
        timestamp_raw = revision.get("timestamp")
        parent_revision_id_raw = revision.get("parent_revision_sys_id")
    else:
        revision_id_raw = getattr(revision, "sys_id", valid_from)
        session_id_raw = getattr(revision, "session_id", None)
        timestamp_raw = getattr(revision, "timestamp", None)
        parent_revision_id_raw = getattr(revision, "parent_revision_sys_id", None)
    revision_id = revision_id_raw if isinstance(revision_id_raw, RevisionId) else RevisionId(str(revision_id_raw))

    if isinstance(session_id_raw, SessionId):
        session_id = session_id_raw
    elif session_id_raw is not None:
        session_id = SessionId(session_id_raw)
    else:
        session_id = SessionId.schema()

    timestamp = timestamp_raw if isinstance(timestamp_raw, datetime) else datetime.now(UTC)

    parent_revision_id = None
    if parent_revision_id_raw is not None:
        parent_revision_id = (
            parent_revision_id_raw if isinstance(parent_revision_id_raw, RevisionId) else RevisionId(str(parent_revision_id_raw))
        )

    author_raw = getattr(revision, "author", None)
    if isinstance(author_raw, UserId):
        author = author_raw
    elif author_raw is not None:
        author = UserId(author_raw)
    else:
        author = None

    custom_metadata: dict[str, Any] = {}
    base_fields = {
        "sys_id",
        "session_id",
        "timestamp",
        "parent_revision_sys_id",
        "parent_type",
        "author",
        "message",
    }
    for field_name in revision_model_cls.model_fields:
        if field_name in base_fields or not hasattr(revision, field_name):
            continue
        custom_metadata[field_name] = getattr(revision, field_name)

    return RevisionMeta(
        revision_id=revision_id,
        session_id=session_id,
        timestamp=timestamp,
        parent_revision_id=parent_revision_id,
        parent_type=getattr(revision, "parent_type", None),
        author=author,
        message=getattr(revision, "message", None),
        custom_metadata=custom_metadata,
    )


def _mapping_to_expression_context(context: Mapping[object, object]) -> dict[str, Any]:
    return {key: value for key, value in context.items() if isinstance(key, str)}


def _normalize_expression_context(context: object) -> dict[str, Any] | None:
    model_dump = getattr(context, "model_dump", None)
    if callable(model_dump):
        dumped = model_dump()
        if isinstance(dumped, Mapping):
            return _mapping_to_expression_context(dumped)
    if isinstance(context, Mapping):
        return _mapping_to_expression_context(context)
    raw_dict = getattr(context, "__dict__", None)
    if isinstance(raw_dict, Mapping):
        return _mapping_to_expression_context(raw_dict)
    return None


def _is_evaluation_context(context: object) -> TypeGuard[EvaluationContext]:
    return all(hasattr(context, attr) for attr in ("__getitem__", "__contains__", "get"))


def _match_simple_equality_expr(
    expr: Expression[Any, Any],
    normalized_context: Mapping[str, Any] | None,
) -> bool | None:
    if (
        normalized_context is None
        or expr.field is None
        or expr.operator not in ("=", "!=")
        or expr.logical_op is not None
        or expr.function is not None
    ):
        return None

    field_val = normalized_context.get(expr.field)
    compare_val = expr.value
    # Explicit None-comparison: bypass SQL three-valued logic so
    # ``Field.is_null()`` / ``is not None`` behave like Python.
    if compare_val is None:
        return field_val is None if expr.operator == "=" else field_val is not None
    if field_val is None:
        return bool(expr.operator != "=")
    # UUID/SysId vs str equality: ``model_dump()`` on a Pydantic row serialises
    # branded UUIDs while the filter value is still the wrapped instance.
    _uuidish: tuple[type, ...] = (_UUID, str, _SysId)
    if isinstance(field_val, _uuidish) and isinstance(compare_val, _uuidish):
        matched = str(field_val) == str(compare_val)
        return matched if expr.operator == "=" else not matched
    return None


def _expression_matches(expr: Expression[Any, Any], context: object) -> bool:
    normalized_context = _normalize_expression_context(context)
    simple_match = _match_simple_equality_expr(expr, normalized_context)
    if simple_match is not None:
        return simple_match
    try:
        if normalized_context is not None:
            return expr.evaluate(normalized_context) is True
        if _is_evaluation_context(context):
            return expr.evaluate(context) is True
    except Exception:
        return False
    return False


def _passes_object_filters(
    entry: HistoryEntry[Any],
    filters: Sequence[Expression[Any, Any]],
) -> bool:
    return all(_expression_matches(expr, entry.version) for expr in filters)


def _passes_revision_filters(
    revision: Any | None,
    filters: Sequence[Expression[Any, Any]],
) -> bool:
    if not filters:
        return True
    if revision is None:
        return False
    return all(_expression_matches(expr, revision) for expr in filters)


def _order_value(
    entry: HistoryEntryWithMeta[Any] | HistoryEntry[Any],
    target: Field[Any, Any] | Expression[Any, Any],
    revision_model_cls: type[BaseRevision],
) -> Any:
    field_name: str | None = None
    is_revision_target = _is_revision_order_target(target, revision_model_cls)
    if isinstance(target, Field):
        field_name = target.name
    else:
        field_name = target.field
        if field_name is None and target.left is None and target.right is None and target.function is None:
            return target.value
        if field_name is None:
            if isinstance(entry, HistoryEntryWithMeta):
                context = {
                    "sys_id": entry.revision_meta.revision_id,
                    "session_id": entry.revision_meta.session_id,
                    "timestamp": entry.revision_meta.timestamp,
                    "author": entry.revision_meta.author,
                    "message": entry.revision_meta.message,
                    "parent_type": entry.revision_meta.parent_type,
                    "parent_revision_sys_id": entry.revision_meta.parent_revision_id,
                    **entry.revision_meta.custom_metadata,
                }
            else:
                context = entry.version
            return target.evaluate(context)

    if is_revision_target and field_name in revision_model_cls.model_fields and isinstance(entry, HistoryEntryWithMeta):
        revision_meta_value_map = {
            "sys_id": entry.revision_meta.revision_id,
            "session_id": entry.revision_meta.session_id,
            "timestamp": entry.revision_meta.timestamp,
            "author": entry.revision_meta.author,
            "message": entry.revision_meta.message,
            "parent_type": entry.revision_meta.parent_type,
            "parent_revision_sys_id": entry.revision_meta.parent_revision_id,
        }
        if field_name in revision_meta_value_map:
            return revision_meta_value_map[field_name]
        return entry.revision_meta.custom_metadata.get(field_name)

    if isinstance(entry.version, dict):
        return entry.version.get(field_name)
    return getattr(entry.version, field_name, None)


@pure_lazy
def _order_target_owner(target: Field[Any, Any] | Expression[Any, Any]) -> type[Any] | None:
    owner = getattr(target, "owner", None)
    if isinstance(owner, type):
        return owner
    if isinstance(target, Expression):
        if target.left is not None:
            left_owner = _order_target_owner(target.left)
            if left_owner is not None:
                return left_owner
        if target.right is not None:
            right_owner = _order_target_owner(target.right)
            if right_owner is not None:
                return right_owner
        for arg in target.args:
            if isinstance(arg, Expression):
                arg_owner = _order_target_owner(arg)
                if arg_owner is not None:
                    return arg_owner
    return None


@pure_lazy
def _is_revision_order_target(
    target: Field[Any, Any] | Expression[Any, Any],
    revision_model_cls: type[BaseRevision],
) -> bool:
    field_name = target.name if isinstance(target, Field) else target.field
    owner = _order_target_owner(target)
    if owner is not None:
        return issubclass(owner, BaseRevision) and isinstance(field_name, str) and field_name in revision_model_cls.model_fields
    return isinstance(field_name, str) and field_name in revision_model_cls.model_fields


def _sort_entries[E: HistoryEntry[Any] | HistoryEntryWithMeta[Any]](
    entries: list[E],
    order_by_clauses: Sequence[tuple[Field[Any, Any] | Expression[Any, Any], str]],
    revision_model_cls: type[BaseRevision],
) -> list[E]:
    if not order_by_clauses:
        entries.sort(key=lambda entry: str(entry.valid_from), reverse=True)
        return entries

    for target, direction in reversed(order_by_clauses):
        entries.sort(
            key=lambda entry: (
                _order_value(entry, target, revision_model_cls) is None,
                _order_value(entry, target, revision_model_cls),
            ),
            reverse=direction.upper() == "DESC",
        )
    return entries


def _apply_offset_limit[T](items: list[T], *, offset: int | None, limit: int | None) -> list[T]:
    start = offset or 0
    if start:
        items = items[start:]
    if limit is not None:
        items = items[:limit]
    return items


