class QueryBranchHistoryRowsStep[T: BaseBranch, R: BaseRevision](SqlRelationPublisherStep[Any]):
    """L0: Query branch revision history as a SQL-owned relation."""

    def cte_publication_contract(self: QueryBranchHistoryRowsStep) -> CtePublicationContract:
        columns: tuple[str, ...]
        if self._count_only:
            columns = ("count",)
            column_type_hints = SqlColumnTypeHints(bigint_columns=frozenset({"count"}))
        else:
            branch_columns = tuple(
                get_db_column_name(self._spec.model_cls, DynamicFieldName(field_name)) for field_name in self._spec.model_cls.model_fields
            )
            revision_source_columns = tuple(
                get_db_column_name(self._spec.revision_model_cls, DynamicFieldName(field_name))
                for field_name in self._spec.revision_model_cls.model_fields
            )
            revision_columns = tuple(f"__rev_{column}" for column in revision_source_columns)
            columns = (
                *branch_columns,
                "sys_valid_from_revision_id",
                "sys_valid_to_revision_id",
                *revision_columns,
            )
            branch_hints = model_sql_column_type_hints(self._spec.model_cls, branch_columns)
            revision_hints = model_sql_column_type_hints(
                self._spec.revision_model_cls,
                revision_source_columns,
            )
            if branch_hints is None or revision_hints is None:
                msg = f"{type(self).__name__} requires model-declared SQL type hints."
                raise TypeError(msg)
            renamed_revision_hints = tuple(revision_hints.rename_column(column, f"__rev_{column}") for column in revision_source_columns)
            column_type_hints = combine_sql_column_type_hints(
                columns,
                branch_hints,
                SqlColumnTypeHints(
                    uuid_columns=frozenset(
                        {"sys_valid_from_revision_id", "sys_valid_to_revision_id"},
                    ),
                ),
                *renamed_revision_hints,
            )
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        contract_columns = tuple(str(column) for column in columns)
        _contract_model_cls: type[object]
        if self._count_only:
            _contract_model_cls = CountRow
            relation_contract = CteRelationContract.semantic_row(CountRow)
        else:
            _contract_model_cls = cte_projection_row_model(
                f"{type(self).__name__}CteRow",
                contract_columns,
                column_type_hints,
            )
            relation_contract = CteRelationContract.projection_over_model(
                source_model_cls=self._spec.model_cls,
                projection_lineage=tuple(
                    (column, f"revision:{column.removeprefix('__rev_')}" if column.startswith("__rev_") else column)
                    for column in contract_columns
                ),
            )
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=contract_columns,
            column_type_hints=column_type_hints,
            model_cls=_contract_model_cls,
            relation_contract=relation_contract,
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        spec: BranchRevisionHistorySpec[T, R],
        config: BranchHistoryRowsConfig,
    ) -> None:
        super().__init__(ref_id)
        self._spec = spec
        self._limit = config.limit
        self._offset = config.offset
        self._count_only = config.count_only
        self._apply_ordering = config.apply_ordering

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.SCALAR if self._count_only else Cardinality.MANY

    def is_read_only(self) -> bool:
        return True

    def step_tags(self) -> frozenset[str]:
        return frozenset({"read", "history", "branch", "grammar"})

    def tables_read(self) -> frozenset[str]:
        return frozenset(
            {
                get_table_name(self._spec.model_cls),
                get_table_name(self._spec.branch_index_model_cls),
                get_table_name(self._spec.revision_model_cls),
            },
        )

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def dependencies(self) -> frozenset[str]:
        deps: set[str] = set()
        for object_id in self._spec.object_ids or ():
            if isinstance(object_id, ScalarServerRef):
                deps.update(object_id.dependencies())
        if self._spec.permission_context_ref is not None:
            deps.add(str(self._spec.permission_context_ref))
        return frozenset(deps)

    def _branch_columns(self) -> list[SqlColumnName]:
        return [
            SqlColumnName(get_db_column_name(self._spec.model_cls, DynamicFieldName(field_name)))
            for field_name in self._spec.model_cls.model_fields
        ]

    def _revision_columns(self) -> list[SqlColumnName]:
        return [
            SqlColumnName(get_db_column_name(self._spec.revision_model_cls, DynamicFieldName(field_name)))
            for field_name in self._spec.revision_model_cls.model_fields
        ]

    def _conditions(self, ctx: CompilationContext) -> tuple[list[Any], list[Any]]:
        branch_converter = ExpressionToGrammar(self._spec.model_cls, table_alias="h")
        revision_converter = ExpressionToGrammar(self._spec.revision_model_cls, table_alias="r")
        branch_conditions = [branch_converter.convert(expr) for expr in self._spec.object_filters]
        if self._spec.object_ids is not None:
            id_col = SqlColumnRef(SqlColumnName(get_db_column_name(self._spec.model_cls, DynamicFieldName("sys_id"))), "h")
            object_ids = list(self._spec.object_ids)
            if not object_ids:
                branch_conditions.insert(0, SQL_EXPR_FALSE_COND)
            else:
                lowered = [lower_scalar_server_ref(_as_sys_id_ref(object_id), ctx) for object_id in object_ids]
                if len(lowered) == 1:
                    branch_conditions.insert(0, SqlBinaryOp(id_col, BinaryOp.EQ, lowered[0]))
                else:
                    branch_conditions.insert(0, SqlIn(id_col, lowered))
        keyset_condition = self._keyset_condition()
        if keyset_condition is not None:
            branch_conditions.append(keyset_condition)
        revision_conditions = [revision_converter.convert(expr) for expr in self._spec.revision_filters]
        if ctx.session_id is not None:
            permission_session_id = compilation_session_id(ctx)
            assert permission_session_id is not None
            session_vars = permission_session_vars_from_context(
                ctx,
                self._spec.permission_context_ref,
                self._spec.permission_context_type,
                site_name=type(self).__name__,
                result_contract="filter branch history from the bound session context",
            )
            permission_condition = compile_permission_where_with_user_expr(
                self._spec.model_cls,
                permission_session_id,
                session_user_id_expr(ctx.session_id, ctx),
                table_alias="h",
                action="read",
                session_id_sql=session_id_expr(ctx.session_id, ctx),
                session_vars=session_vars,
                compilation_context=ctx,
            )
            if permission_condition is not None:
                branch_conditions.append(permission_condition)
            revision_permission_condition = compile_permission_where_with_user_expr(
                self._spec.revision_model_cls,
                permission_session_id,
                session_user_id_expr(ctx.session_id, ctx),
                table_alias="r",
                action="read",
                session_id_sql=session_id_expr(ctx.session_id, ctx),
                session_vars=session_vars,
                compilation_context=ctx,
            )
            if revision_permission_condition is not None:
                revision_conditions.append(revision_permission_condition)
        return branch_conditions, revision_conditions

    def _keyset_condition(self) -> Any | None:
        if self._spec.cursor_values is None or self._spec.cursor_order_field is None or self._spec.cursor_direction is None:
            return None
        if len(self._spec.cursor_values) != 3:
            msg = "branch revision history cursor requires order value, valid_from revision, and branch id"
            raise ValueError(msg)
        order_value, valid_from_value, branch_id_value = self._spec.cursor_values
        order_model = self._spec.revision_model_cls if self._spec.cursor_order_is_revision else self._spec.model_cls
        order_alias = "r" if self._spec.cursor_order_is_revision else "h"
        order_col = SqlColumnRef(
            SqlColumnName(get_db_column_name(order_model, DynamicFieldName(self._spec.cursor_order_field))),
            order_alias,
        )
        valid_from_col = SqlColumnRef(SqlColumnName("sys_valid_from_revision_id"), "h")
        tie_direction = self._spec.cursor_tie_direction or self._spec.cursor_direction
        tie_op = BinaryOp.GT if tie_direction.upper() == "ASC" else BinaryOp.LT
        branch_id_col = SqlColumnRef(
            SqlColumnName(get_db_column_name(self._spec.model_cls, DynamicFieldName("sys_id"))),
            "h",
        )
        return _build_multicolumn_keyset_expr(
            col_exprs=[order_col, valid_from_col],
            col_values=[order_value, valid_from_value],
            col_directions=[
                self._spec.cursor_direction.upper(),
                tie_direction.upper(),
            ],
            identity_col_expr=branch_id_col,
            identity_value=branch_id_value,
            identity_op=tie_op,
        )

    def _order_by(self) -> list[Any]:
        if not self._apply_ordering:
            return []

        order_by = _history_order_by(
            model_cls=self._spec.model_cls,
            revision_model_cls=self._spec.revision_model_cls,
            order_by_clauses=self._spec.order_by_clauses,
        )
        if not order_by:
            order_by.append(
                SqlOrderByItem(
                    SqlColumnRef(
                        SqlColumnName(get_db_column_name(self._spec.revision_model_cls, DynamicFieldName("timestamp"))),
                        "r",
                    ),
                    OrderDirection.DESC,
                ),
            )
        if self._spec.cursor_direction is not None:
            tie_direction = self._spec.cursor_tie_direction or self._spec.cursor_direction
            tie_order_direction = OrderDirection.ASC if tie_direction.upper() == "ASC" else OrderDirection.DESC
            order_by.extend(
                [
                    SqlOrderByItem(
                        SqlColumnRef(SqlColumnName("sys_valid_from_revision_id"), "h"),
                        tie_order_direction,
                    ),
                    SqlOrderByItem(
                        SqlColumnRef(
                            SqlColumnName(get_db_column_name(self._spec.model_cls, DynamicFieldName("sys_id"))),
                            "h",
                        ),
                        tie_order_direction,
                    ),
                ],
            )
        return order_by

    def compile(self, ctx: CompilationContext) -> CompiledStep[Any]:
        branch_conditions, revision_conditions = self._conditions(ctx)
        stmt = SqlBranchRevisionHistoryRows(
            branch_table=get_table_name(self._spec.model_cls),
            branch_index_table=get_table_name(self._spec.branch_index_model_cls),
            revision_table=get_table_name(self._spec.revision_model_cls),
            branch_columns=self._branch_columns(),
            revision_columns=self._revision_columns(),
            revision_timestamp_column=SqlColumnName(
                get_db_column_name(self._spec.revision_model_cls, DynamicFieldName("timestamp")),
            ),
            branch_conditions=branch_conditions,
            revision_conditions=revision_conditions,
            order_by=self._order_by(),
            limit=self._limit,
            offset=self._offset,
            count_only=self._count_only,
        )
        __opa002_grammar_595 = stmt
        output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(
            self.cte_publication_contract(),
        )
        return CompiledStep(
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
            grammar=__opa002_grammar_595,
            closed_post_op=scalar_column_post_op(
                "count",
                default_value=0,
                use_default_on_empty=True,
                scalar_coercion=ScalarCoercionKind.INT,
            )
            if self._count_only
            else history_entries_with_meta_post_op(
                self._spec.model_cls,
                self._spec.revision_model_cls,
            ),
            needs_returning=True,
            auxiliary_ctes=collect_dependency_auxiliary_ctes(ctx, self.dependencies()),
        )


def _read_ctx_steps(
    ref_id: ServerPlanRefId,
    spec: RevisionHistorySpec[Any, Any],
    ctx: LoweringContext,
) -> tuple[list[ServerPlanStep[Any]], str]:
    from impl.common.l2070_server_plan.steps.intent_versioning import (
        ResolveVersionedReadContextByBranchIdIntent,
        ResolveVersionedReadContextByBranchNameIntent,
        ResolveVersionedReadContextByRevisionIntent,
        _absent_permission_context_ref,
    )

    permission_context = (
        ServerRefs.from_ref_id(
            spec.permission_context_ref,
            variant="object",
            type_hint=spec.permission_context_type,
        )
        if spec.permission_context_ref is not None and spec.permission_context_type is not None
        else _absent_permission_context_ref()
    )
    if ctx.lazy_revision is not None:
        lazy_rev = ctx.lazy_revision
        if isinstance(lazy_rev, ScalarServerRef):
            rev_ref: ScalarServerRef[RevisionId] = lazy_rev
        else:
            rev_ref = ServerRefs.scalar(lazy_rev)
        intent_by_rev = ResolveVersionedReadContextByRevisionIntent(
            ServerPlanRefId(ref_id),
            domain=spec.domain,
            revision_id=rev_ref,
            permission_context=permission_context,
        )
        return list(intent_by_rev.lower(ctx)), ref_id

    if ctx.revision_id is not None:
        intent_by_rev = ResolveVersionedReadContextByRevisionIntent(
            ServerPlanRefId(ref_id),
            domain=spec.domain,
            revision_id=ServerRefs.scalar(RevisionId(ctx.revision_id)),
            permission_context=permission_context,
        )
        return list(intent_by_rev.lower(ctx)), ref_id

    if ctx.branch_id is not None:
        intent_by_branch = ResolveVersionedReadContextByBranchIdIntent(
            ServerPlanRefId(ref_id),
            domain=spec.domain,
            branch_id=ServerRefs.scalar(BranchId(ctx.branch_id)),
            permission_context=permission_context,
        )
        return list(intent_by_branch.lower(ctx)), ref_id

    workspace_id = spec.domain.workspace_id or WorkspaceId.default()
    intent_by_name = ResolveVersionedReadContextByBranchNameIntent(
        ServerPlanRefId(ref_id),
        domain=spec.domain,
        branch_name=ServerRefs.scalar(BranchName("main")),
        workspace_id=ServerRefs.scalar(workspace_id),
        permission_context=permission_context,
    )
    return list(intent_by_name.lower(ctx)), ref_id


