def _classification_bool_grammar(cte_name: SqlCteName, field_name: str) -> SqlRenderable:
    if field_name == "needs_three_way":
        return SqlDerivedNeedsThreeWay(SqlGrammarKind(cte_name))
    return SqlFieldBoolFromCte(SqlGrammarKind(cte_name), SqlGrammarKind(field_name))


def _squash_merge_base_where_expr(
    *,
    source_branch_id_expr: SqlRenderable,
    target_tip_expr: SqlRenderable,
    target_branch_id_expr: SqlRenderable,
    supports_strategy: bool,
) -> SqlRenderable:
    from impl.common.l2100_sql_grammar.tree.enums import BinaryOp
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlParam
    from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp, sql_and

    where_expr = sql_and(
        SqlBinaryOp(
            SqlColumnRef(SqlColumnName("source_branch_sys_id")),
            BinaryOp.EQ,
            source_branch_id_expr,
        ),
        SqlBinaryOp(
            SqlColumnRef(SqlColumnName("result_revision_sys_id")),
            BinaryOp.EQ,
            target_tip_expr,
        ),
        SqlBinaryOp(
            SqlColumnRef(SqlColumnName("target_branch_sys_id")),
            BinaryOp.EQ,
            target_branch_id_expr,
        ),
        SqlBinaryOp(
            SqlColumnRef(SqlColumnName("status")),
            BinaryOp.EQ,
            SqlParam("complete"),
        ),
    )
    return (
        sql_and(
            where_expr,
            SqlBinaryOp(
                SqlColumnRef(SqlColumnName("strategy")),
                BinaryOp.EQ,
                SqlParam("squash_merge"),
            ),
        )
        if supports_strategy
        else where_expr
    )


def _existing_squash_merge_base_where_expr(
    *,
    existing_op_id: SysId,
    target_tip_expr: SqlRenderable,
    supports_strategy: bool,
) -> SqlRenderable:
    from impl.common.l2100_sql_grammar.tree.enums import BinaryOp
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlParam
    from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp, sql_and

    del target_tip_expr
    where_expr = SqlBinaryOp(
        SqlColumnRef(SqlColumnName("sys_id")),
        BinaryOp.EQ,
        SqlParam(existing_op_id),
    )
    return (
        sql_and(
            where_expr,
            SqlBinaryOp(
                SqlColumnRef(SqlColumnName("strategy")),
                BinaryOp.EQ,
                SqlParam("squash_merge"),
            ),
        )
        if supports_strategy
        else where_expr
    )


