                (SqlParam("fast_forward"), "status"),
                (lower_scalar_source(self._op_id, ctx, default_field="v"), "operation_id"),
                (_require_merge_op_scalar(ctx, ServerPlanRefId(s.base_revision_sys_id)), "base_revision_id"),
