                (_require_merge_op_scalar(ctx, ServerPlanRefId(s.target_tip_revision_sys_id)), "target_revision_id"),
                (_require_merge_op_scalar(ctx, ServerPlanRefId(s.source_tip_revision_sys_id)), "result_revision_id"),
                (SqlParam(0), "inserted"),
                (SqlParam(0), "updated"),
                (SqlParam(0), "deleted"),
                (SqlParam("[]"), "conflicts"),
            ],
        )
        contract = self.cte_publication_contract()
        output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(contract)
        return _CompiledStep(
            output_shape=output_shape,
            result_relation=result_relation,
            grammar=grammar,
            needs_returning=True,
            column_type_hints=column_type_hints,
            closed_post_op=merge_result_post_op(allow_empty_absent=True),
        )


