                            child_sparse_table=SqlTableName(sparse_table),
                            child_tip_table=SqlTableName(tip_table),
                            child_fk_column=SqlColumnName(get_db_column_name(table_cls, DynamicFieldName(rel.child_field))),
                            data_columns=tuple(data_columns),
