        self: _HasSourceChangesFromDiffsStep,
        ctx: CompilationContext,
    ) -> CompiledStep[bool]:
        consumed_ctes = [cte_ref for ref_id in self._diff_ref_ids if (cte_ref := ctx.cte_refs.get(ref_id)) is not None]
        cte_names = [cte_ref.ref_id for cte_ref in consumed_ctes]
        missing_refs = tuple(ref_id for ref_id in self._diff_ref_ids if ref_id not in ctx.cte_refs)
        if missing_refs:
            raise_missing_cte_fallback_forbidden(
                site_name="_HasSourceChangesFromDiffsStep.compile",
                trigger=f"source-change diff refs {missing_refs!r} are not SQL-visible",
                blocked_path="runtime diff row scan for source-side changes",
                result_contract="source-change checks must be SQL boolean projections over diff CTEs.",
                implementation_requirements=(
                    "Publish every squash/merge diff as a SQL-visible CTE before compiling this step.",
                    "Do not scan materialized Python diff rows to decide source-change gates.",
                ),
            )

        from impl.common.l2070_server_plan.steps._query_helper_compile import (
            _collect_auxiliary_ctes_from_consumed,
        )

        grammar = SqlSourceChangeExistsFromCtes(cte_names)
        auxiliary_ctes = _collect_auxiliary_ctes_from_consumed(consumed_ctes)
        return _compiled_bool_result(grammar, False, auxiliary_ctes=auxiliary_ctes)


