                projected_scalar_ref_id=self._lca_scalar_ref_id,
                row_ref_id=self._lca_ref_id,
            ),
        )
        return _compile_squash_merge_base_projection(
            op_table=self._op_table,
            lca_expr=lca_expr,
            target_tip_expr=target_tip_expr,
            where_expr=where_expr,
            consumed_cte_refs=consumed_cte_refs,
        )


