class _BuildUTDResultStep(SqlRelationPublisherStep[MergeResult]):
    """L0: Build MergeResult for up-to-date merge from a SQL result row."""

    __slots__ = (
        "_predicate_ref_id",
        "_reuse_target_tip_as_result_revision",
        "_source_ref_id",
        "_target_ref_id",
    )

    def __init__(
        self: _BuildUTDResultStep,
        ref_id: ServerPlanRefId,
        config: _BuildUTDResultConfig,
    ) -> None:
        super().__init__(ref_id)
        self._source_ref_id = str(config.source_branch_ref_id)
        self._target_ref_id = str(config.target_branch_ref_id)
        self._reuse_target_tip_as_result_revision = config.reuse_target_tip_as_result_revision
        self._predicate_ref_id = None if config.predicate_ref_id is None else str(config.predicate_ref_id)

    @property
    def level(self: _BuildUTDResultStep) -> int:
        return 0

    def result_cardinality(self: _BuildUTDResultStep) -> Cardinality:
        return Cardinality.ONE

    def always_publishes_executor_visible_binding(self: _BuildUTDResultStep) -> bool:
        return True

    def is_read_only(self: _BuildUTDResultStep) -> bool:
        return True

    def execution_role(self: _BuildUTDResultStep) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def step_tags(self: _BuildUTDResultStep) -> frozenset[str]:
        return frozenset({"merge", "result"})

    def tables_read(self: _BuildUTDResultStep) -> frozenset[str]:
        return frozenset()

    def tables_written(self: _BuildUTDResultStep) -> frozenset[str]:
        return frozenset()

    def cte_publication_contract(self: _BuildUTDResultStep) -> CtePublicationContract:
        columns = _MERGE_RESULT_ROW_COLUMNS
        column_type_hints = _merge_result_type_hints()
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        _contract_model_cls = _MergeResultRow
        contract_columns = tuple(str(column) for column in columns)
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=contract_columns,
            column_type_hints=column_type_hints,
            model_cls=_contract_model_cls,
            relation_contract=CteRelationContract.semantic_row(_MergeResultRow),
            relation_role=VERSIONED_SEMANTIC_RESULT_ROLE,
            source_tables=_contract_source_tables,
            empty_result_allowed=True,
        )

    def dependencies(self: _BuildUTDResultStep) -> frozenset[str]:
        return frozenset(
            {
                self._source_ref_id,
                self._target_ref_id,
                *((self._predicate_ref_id,) if self._predicate_ref_id is not None else ()),
            },
        )

    def compile(
        self: _BuildUTDResultStep,
        ctx: CompilationContext,
    ) -> CompiledStep[MergeResult]:
        from l2070_batching.compilation import CompiledStep as _CompiledStep
        from l2070_batching.compilation import CteReference
        from l2070_batching.output_shape import (
            CompiledOutputShape,
            DeclaredResultRelation,
            synthetic_output_field,
        )
        from impl.common.l2070_server_plan.steps._query_helper_compile import (
            _collect_auxiliary_ctes_from_consumed,
        )
        from impl.common.l2100_sql_grammar.domain.versioning.stmt_conditional_gate import (
            SqlBoolColumnSubquery,
            SqlGateCte,
            SqlGatedWhere,
        )

        source_cte = ctx.cte_refs.get(self._source_ref_id)
        target_cte = ctx.cte_refs.get(self._target_ref_id)
        reuse_target_tip_as_result_revision = self._reuse_target_tip_as_result_revision
        source_ref_id = self._source_ref_id
        target_ref_id = self._target_ref_id
        if source_cte is None or target_cte is None:
            missing = tuple(
                ref_id
                for ref_id, cte in (
                    (source_ref_id, source_cte),
                    (target_ref_id, target_cte),
                )
                if cte is None
            )
            raise_missing_cte_fallback_forbidden(
                site_name=type(self).__name__,
                trigger=f"up-to-date merge result branch refs {missing!r} are not SQL-visible",
                blocked_path="runtime MergeResult construction from materialized branch objects",
                result_contract="up-to-date merge result must compile to the closed SQL merge-result row shape",
                implementation_requirements=(
                    "Publish source and target branch lookups as upstream SQL CTEs before result construction.",
                    "Thread those CTE bindings through ctx.cte_refs.",
                    "Do not recover by reading materialized branch objects during compile or post-processing.",
                ),
            )
        assert source_cte is not None
        assert target_cte is not None

        source_tip_expr = SqlCteFieldRef(
            ServerPlanRefId(source_cte.ref_id),
            SqlColumnName("tip_revision_sys_id"),
        )
        target_tip_expr = SqlCteFieldRef(
            ServerPlanRefId(target_cte.ref_id),
            SqlColumnName("tip_revision_sys_id"),
        )
        result_revision_expr: SqlRenderable = (
            SqlCoalesceExpr(target_tip_expr, source_tip_expr) if reuse_target_tip_as_result_revision else SqlParam(None)
        )
        select_items: list[tuple[SqlRenderable, str]] = [
            (SqlParam("up_to_date"), "status"),
            (SqlParam(None), "operation_id"),
            (source_tip_expr, "base_revision_id"),
            (source_tip_expr, "source_revision_id"),
            (target_tip_expr, "target_revision_id"),
            (result_revision_expr, "result_revision_id"),
            (SqlParam(0), "inserted"),
            (SqlParam(0), "updated"),
            (SqlParam(0), "deleted"),
            (SqlParam("[]"), "conflicts"),
        ]
        grammar: SqlRenderable = SqlSelectExpressions(
            select_items,
        )
        consumed_ctes = [source_cte, target_cte]
        auxiliary_ctes = _collect_auxiliary_ctes_from_consumed(consumed_ctes) or []
        if self._predicate_ref_id is not None:
            predicate_cte = ctx.cte_refs.get(self._predicate_ref_id)
            if not isinstance(predicate_cte, CteReference):
                msg = f"Up-to-date result predicate {self._predicate_ref_id!r} has no SQL-visible CTE binding."
                raise ProgrammingError(msg)
            auxiliary_ctes.extend(_collect_auxiliary_ctes_from_consumed([predicate_cte]) or [])
            gate_name = SqlCteName(f"{self.ref_id}__predicate_gate")
            auxiliary_ctes.append(
                (
                    str(gate_name),
                    SqlGateCte(SqlBoolColumnSubquery(predicate_cte.ref_id, "__result")),
                ),
            )
            grammar = SqlGatedWhere(grammar, gate_name)
        contract = self.cte_publication_contract()
        output_shape = CompiledOutputShape(
            tuple(synthetic_output_field(column) for column in contract.columns),
        )

        return _CompiledStep(
            output_shape=output_shape,
            result_relation=DeclaredResultRelation.from_output_shape(output_shape),
            grammar=grammar,
            needs_returning=True,
            column_type_hints=contract.column_type_hints,
            closed_post_op=merge_result_post_op(allow_empty_absent=True),
            auxiliary_ctes=auxiliary_ctes or None,
        )


