                sql_and(
                    SqlBinaryOp(SqlColumnRef(SqlColumnName("branch_id")), BinaryOp.EQ, source_branch),
                    SqlExists(
                        SqlSelect(
                            select_list=SqlSelectList([SqlStar()]),
                            from_=SqlTableAlias(SqlTableIdent(self._sparse_table), target_change_alias),
                            where=SqlWhereClause(
                                sql_and(
                                    SqlBinaryOp(
