        return frozenset({"rebase", "result", "runtime_projection"})

    def tables_read(self: _RebaseResultCollectorStep) -> frozenset[str]:
        return frozenset()

    def tables_written(self: _RebaseResultCollectorStep) -> frozenset[str]:
        return frozenset()

    def dependencies(self: _RebaseResultCollectorStep) -> frozenset[str]:
        return frozenset(str(result_ref) for result_ref in self._result_refs)

    def compile(
        self: _RebaseResultCollectorStep,
        ctx: CompilationContext,
    ) -> CompiledStep[RebaseResult]:
        from l2070_batching.compilation import CompiledStep as _CompiledStep

        del ctx

        runtime_ref_ids = tuple(str(result_ref) for result_ref in self._result_refs)
        return _CompiledStep(
            runtime_ref_ids=runtime_ref_ids,
        )

    def execute_runtime(self: _RebaseResultCollectorStep, resolved: ResolvedRefs) -> RebaseResult:
        def _result_from_value(value: object) -> RebaseResult | None:
            if isinstance(value, RebaseResult):
                return value
            if isinstance(value, Mapping):
                for key in ("__executor_value__", "value"):
                    result = _result_from_value(value.get(key))
                    if result is not None:
                        return result
            if isinstance(value, Sequence) and not isinstance(value, str | bytes):
                for item in value:
                    result = _result_from_value(item)
                    if result is not None:
                        return result
            return None

        for result_ref in self._result_refs:
            for candidate_ref in (result_ref, ServerPlanRefId(f"{result_ref}.result")):
                result = _result_from_value(resolved.peek(candidate_ref))
                if result is not None:
                    return result
        return resolved.first_instance(
            self._result_refs,
            RebaseResult,
            site="_RebaseResultCollectorStep.execute_runtime",
        )


