    def execute_runtime(self: _MergeResultCollectorStep, resolved: ResolvedRefs) -> MergeResult:
        del resolved
        msg = "Merge result collectors require their canonical SQL relation."
        raise NotImplementedError(msg)

    def compile(
        self: _MergeResultCollectorStep,
        ctx: CompilationContext,
    ) -> CompiledStep[MergeResult]:
        return self._compile_sql_collector(ctx)

    def _compile_sql_collector(
        self: _MergeResultCollectorStep,
        ctx: CompilationContext,
    ) -> CompiledStep[MergeResult]:
        from impl.common.l2070_server_plan.steps._query_helper_compile import (
            _collect_auxiliary_ctes_from_consumed,
        )
        from impl.common.l2100_sql_grammar.domain.versioning.stmt_merge_result_collector import (
            SqlMergeResultCollector,
        )
        from l2070_batching.compilation import CompiledStep as _CompiledStep
        from l2070_batching.output_shape import (
            CompiledOutputShape,
            DeclaredResultRelation,
            synthetic_output_field,
        )

        consumed_ctes = []
        for ref_id in self._result_refs:
            cte_ref = ctx.cte_refs.get(ref_id)
            if cte_ref is None:
                raise_missing_cte_fallback_forbidden(
                    site_name=type(self).__name__,
                    trigger=f"merge-result collector source {ref_id!r} without a SQL-visible CTE",
                    blocked_path=(
                        "compile() would otherwise coalesce already materialized Python MergeResult objects from runtime refs."
                    ),
                    result_contract=(
                        "merge path result steps must publish normalized SQL result rows consumed by SqlMergeResultCollector."
                    ),
                    implementation_requirements=(
                        "Keep every conditional merge result path as a SQL-visible row relation.",
                        "Collect merge results with SqlMergeResultCollector over CTE bindings.",
                        "Do not choose a merge result from Python runtime refs.",
                    ),
                )
            consumed_ctes.append(cte_ref)
        grammar = SqlMergeResultCollector(
            [cte_ref.ref_id for cte_ref in consumed_ctes],
            _MERGE_RESULT_ROW_COLUMNS,
        )
        output_shape = CompiledOutputShape(
            tuple(synthetic_output_field(column) for column in _MERGE_RESULT_ROW_COLUMNS),
        )
        return _CompiledStep(
            grammar=grammar,
            needs_returning=True,
            auxiliary_ctes=_collect_auxiliary_ctes_from_consumed(consumed_ctes),
            output_shape=output_shape,
            result_relation=DeclaredResultRelation.from_output_shape(output_shape),
            column_type_hints=_merge_result_type_hints(),
            closed_post_op=merge_result_post_op(),
        )


class _ConditionalBranchBodyStep[T](MaybeSqlRelationPublisherStep[T]):
    """Expose a conditional merge branch body under an isolated gated ref."""

    __slots__ = ("_base_dependencies", "_extra_deps", "_inner", "_force_non_batchable")

    def __init__(
        self,
        inner: ServerPlanStep[T],
        extra_deps: frozenset[ServerPlanRefId],
        *,
        ref_id: ServerPlanRefId | None = None,
        base_dependencies: frozenset[ServerPlanRefId] | None = None,
        force_non_batchable: bool = False,
    ) -> None:
        super().__init__(inner.ref_id if ref_id is None else ref_id)
        self._inner = inner
        self._extra_deps = frozenset(str(dep) for dep in extra_deps)
        self._base_dependencies = None if base_dependencies is None else frozenset(str(dep) for dep in base_dependencies)
        self._force_non_batchable = force_non_batchable

    @property
    def level(self: _ConditionalBranchBodyStep[T]) -> int:
        return self._inner.level

    def result_cardinality(self: _ConditionalBranchBodyStep[T]) -> Cardinality:
        return self._inner.result_cardinality()

    def is_read_only(self: _ConditionalBranchBodyStep[T]) -> bool:
        return self._inner.is_read_only()

    def supports_sql_batch_transport(self: _ConditionalBranchBodyStep[T]) -> bool:
        return not self._force_non_batchable and self._inner.supports_sql_batch_transport()

    def requires_runtime_sequential_batch(self: _ConditionalBranchBodyStep[T]) -> bool:
        return self._force_non_batchable or self._inner.requires_runtime_sequential_batch()

    def requires_materialized_inputs(self: _ConditionalBranchBodyStep[T]) -> bool:
        return self._inner.requires_materialized_inputs()

    def requires_prior_step_boundary(self: _ConditionalBranchBodyStep[T]) -> bool:
        return self._inner.requires_prior_step_boundary()

    def _requires_materialized_conditional_output(self: _ConditionalBranchBodyStep[T]) -> bool:
        """Apply the wrapped result materializer before publishing its declared row shape."""
        return True

    def execution_role(self: _ConditionalBranchBodyStep[T]) -> StepExecutionRole:
        return self._inner.execution_role()

    def has_unbounded_params(self: _ConditionalBranchBodyStep[T]) -> bool:
        return self._inner.has_unbounded_params()

    def dependencies(self: _ConditionalBranchBodyStep[T]) -> frozenset[str]:
        base_dependencies = self._inner.dependencies() if self._base_dependencies is None else self._base_dependencies
        return base_dependencies | self._extra_deps

    def sql_visible_dependencies(self: _ConditionalBranchBodyStep[T]) -> frozenset[str]:
        inner_deps = set(self._inner.sql_visible_dependencies())
        if self._base_dependencies is not None:
            inner_deps &= set(self._base_dependencies)
        return frozenset(inner_deps)

    def tables_read(self: _ConditionalBranchBodyStep[T]) -> frozenset[str]:
        return self._inner.tables_read()

    def tables_written(self: _ConditionalBranchBodyStep[T]) -> frozenset[str]:
        return self._inner.tables_written()

    def always_publishes_executor_visible_binding(self: _ConditionalBranchBodyStep[T]) -> bool:
        return self.cte_publication_contract().publishes_relation

    def cte_publication_contract(self: _ConditionalBranchBodyStep) -> CtePublicationContract:
        inner_contract = self._inner.publication_contract()
        inner_transport = inner_contract.transport
        columns = inner_transport.columns if inner_transport is not None else None
        column_type_hints = inner_transport.column_type_hints if inner_transport is not None else None
        if columns is None:
            if column_type_hints is not None and column_type_hints.has_any():
                msg = f"{type(self).__name__} declares SQL column type hints without an explicit cte_output_columns() contract."
                raise TypeError(msg)
            return CtePublicationContract.non_publishing()
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        _contract_model_cls = inner_contract.model_cls or cte_projection_row_model(
            f"{type(self).__name__}CteRow",
            columns,
            column_type_hints,
        )
        contract_columns = tuple(str(column) for column in columns)
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=contract_columns,
            column_type_hints=column_type_hints,
            model_cls=_contract_model_cls,
            relation_contract=CteRelationContract.source_cte(source_cte_ref=str(self._inner.ref_id)),
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
            empty_result_allowed=True,
        )

    def expands_results(self: _ConditionalBranchBodyStep[T]) -> bool:
        return self._inner.expands_results()

    def step_tags(self: _ConditionalBranchBodyStep[T]) -> frozenset[str]:
        return self._inner.step_tags()

    def compile(self: _ConditionalBranchBodyStep[T], ctx: CompilationContext) -> CompiledStep[T]:
        return self._inner.compile(ctx)


class _RepublishAfterDepsStep[T](MaybeSqlRelationPublisherStep[T]):
    """Re-publish a gated result under the public ref without looking dependency-only."""

    optimizer_projection_owned = True

    __slots__ = (
        "_cte_column_type_hints",
        "_cte_output_columns",
        "_source_ref",
        "_table_reads",
        "_table_writes",
    )

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        source_ref: ServerPlanRefId,
        table_reads: frozenset[SqlTableName],
        table_writes: frozenset[SqlTableName],
        cte_output_columns: tuple[SqlColumnName, ...] | None = None,
        cte_column_type_hints: SqlColumnTypeHints | None = None,
    ) -> None:
        super().__init__(ref_id)
        self._source_ref = str(source_ref)
        self._table_reads = frozenset(str(table_name) for table_name in table_reads)
        self._table_writes = frozenset(str(table_name) for table_name in table_writes)
        if cte_output_columns is not None:
            if cte_column_type_hints is None:
                msg = f"Republish step {ref_id!r} declares CTE columns without SQL column type hints."
                raise TypeError(msg)
            cte_column_type_hints.require_complete(tuple(str(column) for column in cte_output_columns))
        self._cte_output_columns = cte_output_columns
        self._cte_column_type_hints = cte_column_type_hints

    def cte_publication_contract(self: _RepublishAfterDepsStep) -> CtePublicationContract:
        columns = None if self._cte_output_columns is None else tuple((str(column) for column in self._cte_output_columns))
        column_type_hints = self._cte_column_type_hints
        if columns is None:
            if column_type_hints is not None and column_type_hints.has_any():
                msg = f"{type(self).__name__} declares SQL column type hints without an explicit cte_output_columns() contract."
                raise TypeError(msg)
            return CtePublicationContract.non_publishing()
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        contract_columns = tuple(str(column) for column in columns)
        _contract_model_cls = cte_projection_row_model(
            f"{type(self).__name__}CteRow",
            contract_columns,
            column_type_hints,
        )
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=contract_columns,
            column_type_hints=column_type_hints,
            model_cls=_contract_model_cls,
            relation_contract=CteRelationContract.source_cte(source_cte_ref=str(self._source_ref)),
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    @property
    def level(self: _RepublishAfterDepsStep[T]) -> int:
        return 0

    def result_cardinality(self: _RepublishAfterDepsStep[T]) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self: _RepublishAfterDepsStep[T]) -> bool:
        return not self._table_writes

    def execution_role(self: _RepublishAfterDepsStep[T]) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def consumes_executor_visible_dependencies(self: _RepublishAfterDepsStep[T]) -> bool:
        return True

    def has_unbounded_params(self: _RepublishAfterDepsStep[T]) -> bool:
        return False

    def dependencies(self: _RepublishAfterDepsStep[T]) -> frozenset[str]:
        return frozenset({self._source_ref})

    def tables_read(self: _RepublishAfterDepsStep[T]) -> frozenset[str]:
        return self._table_reads

    def tables_written(self: _RepublishAfterDepsStep[T]) -> frozenset[str]:
        return self._table_writes

    def step_tags(self: _RepublishAfterDepsStep[T]) -> frozenset[str]:
        return frozenset({"read", "grammar", "merge", "republish"})

    def compile(self: _RepublishAfterDepsStep[T], ctx: CompilationContext) -> CompiledStep[T]:
        from impl.common.l2070_server_plan.steps._runtime_replanning_error import (
            raise_missing_cte_fallback_forbidden,
        )
        from impl.common.l2070_server_plan.steps._query_helper_compile import (
            _collect_auxiliary_ctes_from_consumed,
        )
        from l2070_batching.compilation import CompiledStep as _CompiledStep, CteReference

        source_cte = ctx.cte_refs.get(self._source_ref)
        if source_cte is None or not source_cte.columns:
            raise_missing_cte_fallback_forbidden(
                site_name=type(self).__name__,
                trigger=f"republish source {self._source_ref!r} without a SQL-visible CTE",
                blocked_path="runtime-ref merge result republishing",
                result_contract="republished merge result refs must expose SQL-visible row relations",
                implementation_requirements=(
                    "Publish the conditional branch body as a CTE with merge-result columns.",
                    "Carry the branch body's auxiliary query across batch boundaries.",
                    "Do not republish merge results from runtime refs.",
                ),
            )
        if source_cte.columns:
            from l2070_batching.output_shape import CompiledOutputShape, DeclaredResultRelation, synthetic_output_field

            output_shape = CompiledOutputShape(
                tuple(synthetic_output_field(column) for column in source_cte.columns),
            )

            auxiliary_source_ctes = [source_cte]
            if source_cte.auxiliary_query is None:
                aliased_source_cte = ctx.cte_refs.get(source_cte.ref_id)
                if isinstance(aliased_source_cte, CteReference):
                    auxiliary_source_ctes.append(aliased_source_cte)
            flattened_auxiliary_ctes = _collect_auxiliary_ctes_from_consumed(auxiliary_source_ctes) or []
            source_body = None
            remaining_auxiliary_ctes = []
            for aux_name, aux_query in flattened_auxiliary_ctes:
                if aux_name == source_cte.ref_id:
                    source_body = aux_query
                else:
                    remaining_auxiliary_ctes.append((aux_name, aux_query))
            if source_body is None:
                source_body = SqlSelectFromCteWithOverrides(
                    source_cte_name=SqlGrammarKind(source_cte.ref_id),
                    source_columns=tuple(str(column) for column in source_cte.columns),
                    overrides={},
                )

            return cast(
                "CompiledStep[T]",
                _CompiledStep(
                    output_shape=output_shape,
                    result_relation=DeclaredResultRelation.from_output_shape(output_shape),
                    grammar=source_body,
                    needs_returning=True,
                    column_type_hints=source_cte.column_type_hints,
                    auxiliary_ctes=flattened_auxiliary_ctes or remaining_auxiliary_ctes or None,
                    closed_post_op=raw_rows_post_op(),
                ),
            )
        raise AssertionError("unreachable")


def _gate_branch_steps[BranchStepsItemT](
    *,
    condition_ref: str,
    branch_steps: Sequence[ServerPlanStep[BranchStepsItemT]],
    force_non_batchable: bool,
    publish_ref_ids: frozenset[str] | None = None,
) -> list[ServerPlanStep[Any]]:
    from impl.common.l2070_server_plan.steps.conditional_builders import (
        build_one_sided_conditional,
    )
    from impl.common.l2070_server_plan.steps.return_value import SqlScalarLiteralStep

    gated_steps: list[ServerPlanStep[Any]] = []
    branch_ref_ids = frozenset(step.ref_id for step in branch_steps)
    previous_gate_ref: str | None = None
    for step in branch_steps:
        body_ref = f"{step.ref_id}__body"
        gate_ref = f"{step.ref_id}__gate"
        external_deps = frozenset(step.dependencies() - branch_ref_ids)
        step_transport = step.publication_contract().transport
        raw_cte_output_columns = step_transport.columns if step_transport is not None else None
        publishes_step = publish_ref_ids is None or step.ref_id in publish_ref_ids
        # A relation-producing branch publishes directly through the conditional
        # step's public ref. The conditional compiler owns the SQL relation and its
        # batch result alias; a later republish step cannot reconstruct that relation
        # after a required statement boundary.
        output_ref = str(step.ref_id) if publishes_step and raw_cte_output_columns is not None else gate_ref
        force_step_boundary = force_non_batchable
        marker_ref = f"{body_ref}__marker"
        body_step_ref = body_ref if publishes_step and raw_cte_output_columns is not None else f"{body_ref}__effect"
        sequenced_step: ServerPlanStep[Any]
        if previous_gate_ref is None:
            sequenced_step = _ConditionalBranchBodyStep(
                step,
                frozenset(),
                ref_id=ServerPlanRefId(body_step_ref),
                base_dependencies=frozenset(ServerPlanRefId(dep) for dep in external_deps),
                force_non_batchable=force_step_boundary,
            )
        else:
            sequenced_step = _ConditionalBranchBodyStep(
                step,
                frozenset({ServerPlanRefId(previous_gate_ref)}),
                ref_id=ServerPlanRefId(body_step_ref),
                base_dependencies=frozenset(ServerPlanRefId(dep) for dep in external_deps),
                force_non_batchable=force_step_boundary,
            )
        branch_body_steps: list[ServerPlanStep[Any]]
        result_ref = ServerPlanRefId(body_ref)
        default_value: object | None = None
        if publishes_step and raw_cte_output_columns is not None:
            branch_body_steps = [sequenced_step]
        else:
            branch_body_steps = [
                sequenced_step,
                SqlScalarLiteralStep(
                    ServerPlanRefId(marker_ref),
                    True,
                    empty_result_allowed=True,
                ),
            ]
            result_ref = ServerPlanRefId(marker_ref)
            default_value = False
        gated_steps.append(
            build_one_sided_conditional(
                ref_id=ServerPlanRefId(output_ref),
                condition_ref=ServerPlanRefId(condition_ref),
                if_true_steps=branch_body_steps,
                result_ref=result_ref,
                default_value=default_value,
                force_prior_step_boundary=force_step_boundary,
            ),
        )
        previous_gate_ref = output_ref
    return gated_steps


