def _lower_new_merge_steps(
    *,
    result_ref_id: str,
    domain: type[VersioningDomain],
    workspace_id: ScalarServerRef[WorkspaceId],
    source_branch_name: ScalarServerRef[BranchName],
    target_branch_name: ScalarServerRef[BranchName],
    session_id: SessionId,
    strategy: str,
    revision_metadata: RevisionMetadataPayload,
    versioned_tables: tuple[type[VersionedObjectRow[SysId]], ...],
    ctx: LoweringContext,
) -> Sequence[ServerPlanStep[Any]]:
    merge_op_id = SysId(str(uuid7()))

    def build_conflict_path_steps[ConflictRecordStepsItemT](
        conflict_insert_op: ServerPlanStep[Any],
        conflict_record_steps: list[ServerPlanStep[ConflictRecordStepsItemT]],
    ) -> list[ServerPlanStep[Any]]:
        return [conflict_insert_op, *conflict_record_steps]

    def build_clean_completion_steps(
        insert_merge_op: ServerPlanStep[Any],
        _update_existing_merge_op: ServerPlanStep[Any],
    ) -> list[ServerPlanStep[Any]]:
        return [insert_merge_op]

    return _lower_merge_steps_common(
        result_ref_id=result_ref_id,
        domain=domain,
        workspace_id=workspace_id,
        source_branch_name=source_branch_name,
        target_branch_name=target_branch_name,
        session_id=session_id,
        strategy=strategy,
        revision_metadata=revision_metadata,
        versioned_tables=versioned_tables,
        merge_op_id=merge_op_id,
        build_conflict_path_steps=build_conflict_path_steps,
        build_clean_completion_steps=build_clean_completion_steps,
        ctx=ctx,
    )


def _lower_resume_merge_steps(
    *,
    result_ref_id: str,
    domain: type[VersioningDomain],
    workspace_id: ScalarServerRef[WorkspaceId],
    source_branch_name: ScalarServerRef[BranchName],
    target_branch_name: ScalarServerRef[BranchName],
    session_id: SessionId,
    strategy: str,
    revision_metadata: RevisionMetadataPayload,
    versioned_tables: tuple[type[VersionedObjectRow[SysId]], ...],
    existing_op_id: SysId,
    ctx: LoweringContext,
) -> Sequence[ServerPlanStep[Any]]:
    def build_conflict_path_steps[ConflictRecordStepsItemT](
        _conflict_insert_op: ServerPlanStep[Any],
        _conflict_record_steps: list[ServerPlanStep[ConflictRecordStepsItemT]],
    ) -> list[ServerPlanStep[Any]]:
        return []

    def build_clean_completion_steps(
        _insert_merge_op: ServerPlanStep[Any],
        update_existing_merge_op: ServerPlanStep[Any],
    ) -> list[ServerPlanStep[Any]]:
        return [update_existing_merge_op]

    return _lower_merge_steps_common(
        result_ref_id=result_ref_id,
        domain=domain,
        workspace_id=workspace_id,
        source_branch_name=source_branch_name,
        target_branch_name=target_branch_name,
        session_id=session_id,
        strategy=strategy,
        revision_metadata=revision_metadata,
        versioned_tables=versioned_tables,
        merge_op_id=existing_op_id,
        build_conflict_path_steps=build_conflict_path_steps,
        build_clean_completion_steps=build_clean_completion_steps,
        resume_existing_op_id=existing_op_id,
        ctx=ctx,
    )


def _lower_merge_steps_common(
    *,
    result_ref_id: str,
    domain: type[VersioningDomain],
    workspace_id: ScalarServerRef[WorkspaceId],
    source_branch_name: ScalarServerRef[BranchName],
    target_branch_name: ScalarServerRef[BranchName],
    session_id: SessionId,
    strategy: str,
    revision_metadata: RevisionMetadataPayload,
    versioned_tables: tuple[type[VersionedObjectRow[SysId]], ...],
    merge_op_id: SysId,
    build_conflict_path_steps: Callable[
        [ServerPlanStep[Any], list[ServerPlanStep[Any]]],
        list[ServerPlanStep[Any]],
    ],
    build_clean_completion_steps: Callable[
        [ServerPlanStep[Any], ServerPlanStep[Any]],
        list[ServerPlanStep[Any]],
    ],
    ctx: LoweringContext,
    resume_existing_op_id: SysId | None = None,
) -> Sequence[ServerPlanStep[Any]]:
    from impl.common.l2070_server_plan.provider_helpers import (
        require_versioned_lowering_provider,
    )
    from impl.common.l2070_server_plan.steps.branch_mutation_permission import (
        NamedBranchReadPermissionStep,
    )
    from impl.common.l2070_server_plan.steps.conditional_builders import (
        build_one_sided_conditional,
    )
    from impl.common.l2070_server_plan.steps.intent_branch_ops import (
        build_branch_tip_update_with_expected_tip_steps,
    )
    from impl.common.l2070_server_plan.steps.merge_steps import (
        FetchBranchByNameStep,
        FindLCAStep,
        MergeClassifyStep,
        _FetchBranchByNameConfig,
        _FindLcaConfig,
        _MergeClassifyConfig,
    )
    from impl.common.l2070_server_plan.steps.merge_three_way_steps import (
        ThreeWayDiffStep,
        _AppliedMergeInsertLogEntriesConfig,
        _AppliedMergeInsertLogEntriesStep,
        _ApplyMergeCascadeClosureConfig,
        _ApplyMergeCascadeClosureStep,
        _ApplyMergeCloseConfig,
        _ApplyMergeCloseStep,
        _ApplyMergeDeleteTipConfig,
        _ApplyMergeDeleteTipStep,
        _ApplyMergeInsertConfig,
        _ApplyMergeInsertStep,
        _ApplyResolvedConflictConfig,
        _ApplyResolvedConflictStep,
        _ApplyMergeUpsertTipConfig,
        _ApplyMergeUpsertTipStep,
        _BuildCleanMergeResultConfig,
        _BuildCleanMergeResultStep,
        _BuildConflictResultConfig,
        _BuildConflictResultStep,
        _ConflictCountFromDiffsConfig,
        _ConflictCountFromDiffsStep,
        _DemoteMergeBranchTipConfig,
        _DemoteMergeBranchTipStep,
        _FastForwardMergeInsertLogEntriesConfig,
        _FastForwardMergeInsertLogEntriesStep,
        _FkCascadeConflictDiffConfig,
        _FkCascadeConflictDiffStep,
        _HasConflictsFromDiffsConfig,
        _HasConflictsFromDiffsStep,
        _HasUnresolvedMergeConflictsConfig,
        _HasUnresolvedMergeConflictsStep,
        _InsertCleanMergeOpConfig,
        _InsertCleanMergeOpStep,
        _InsertConflictMergeOpConfig,
        _InsertConflictMergeOpStep,
        _InsertConflictRecordsConfig,
        _InsertConflictRecordsFromDiffRefConfig,
        _InsertConflictRecordsFromDiffRefStep,
        _InsertConflictRecordsStep,
        _InsertMergeBranchIndexConfig,
        _InsertMergeBranchIndexStep,
        _InsertMergeParentsConfig,
        _InsertMergeParentsStep,
        _InsertMergeRevisionConfig,
        _InsertMergeRevisionStep,
        _InvertBoolConfig,
        _InvertBoolStep,
        _NoConflictsFromDiffsStep,
        _ThreeWayDiffConfig,
        _UpdateExistingMergeOpConfig,
        _UpdateExistingMergeOpStep,
        _UpdateMergeBranchTipConfig,
        _UpdateMergeBranchTipStep,
        build_merge_operation_scalar_projection_steps,
    )

    branch_table = get_table_name(domain.branch_model)
    branch_model = domain.branch_model
    revision_table = get_table_name(domain.revision_model)
    revision_parents_table = get_table_name(domain.revision_parent_model)
    op_table = get_table_name(MergeOperation)
    ff_op_id = SysId(str(uuid7()))
    ff_op_id_ref = cast("Any", ff_op_id)
    merge_revision_id = RevisionId(str(uuid7()))
    merge_revision_id_ref = cast("Any", merge_revision_id)
    session_id_ref = cast("Any", session_id)
    parent1_sys_id = str(uuid7())
    parent2_sys_id = str(uuid7())

    provider = require_versioned_lowering_provider(ctx)
    sqlite_force_non_batchable = provider.force_non_batchable_merge_plan()
    ripple_registry = RippleRegistry.get_instance()
    standard_merge_logs_enabled = False
    strategy_value = str(getattr(strategy, "values", strategy))
    # Merge intents run outside a branch-bound transaction, so ambient lowering
    # context cannot describe either participating branch. The default branch
    # contract is materialized; the explicit test override selects the tipless
    # path for tipless-policy conformance.
    branch_tip_materialized = not force_tipless_branch_mode_enabled()
    if domain.graphs:
        if ripple_registry.domain_has_connection_handlers(domain):
            ripple_registry.require_domain_sql_triggers(domain, connection=True)
        if (
            ctx.backend_profile.traits.eventing_mode is EventingExecutionMode.DATABASE_TRIGGERS
            and ripple_registry.domain_has_standard_handlers(domain)
        ):
            ripple_registry.require_domain_sql_triggers(domain, standard=True)
            standard_merge_logs_enabled = True

    rev_meta = revision_metadata.values

    source_branch_guard = NamedBranchReadPermissionStep(
        ServerPlanRefId("merge.source_branch_permission"),
        model=branch_model,
        branch_name=source_branch_name,
        workspace_id=workspace_id,
        session_id=session_id,
    )
    target_branch_guard = NamedBranchReadPermissionStep(
        ServerPlanRefId("merge.target_branch_permission"),
        model=branch_model,
        branch_name=target_branch_name,
        workspace_id=workspace_id,
        session_id=session_id,
        action="update",
    )
    fetch_source = FetchBranchByNameStep(
        ref_id=ServerPlanRefId("merge.source_branch"),
        config=_FetchBranchByNameConfig(
            branch_name=source_branch_name,
            branch_table=SqlTableName(branch_table),
            workspace_id=workspace_id,
            branch_model=branch_model,
            reset_merge_sql_materialization_caches=True,
        ),
    )
    fetch_target = FetchBranchByNameStep(
        ref_id=ServerPlanRefId("merge.target_branch"),
        config=_FetchBranchByNameConfig(
            branch_name=target_branch_name,
            branch_table=SqlTableName(branch_table),
            workspace_id=workspace_id,
            branch_model=branch_model,
        ),
    )
    validate_source = _ValidateSourceHasTipStep(
        ref_id=ServerPlanRefId("merge.validate_source"),
        config=_ValidateSourceHasTipConfig(
            source_branch_ref_id=ServerPlanRefId("merge.source_branch"),
            branch_model=branch_model,
        ),
    )
    find_lca = FindLCAStep(
        ref_id=ServerPlanRefId("merge.lca"),
        config=_FindLcaConfig(
            source_branch_ref_id=ServerPlanRefId("merge.source_branch"),
            target_branch_ref_id=ServerPlanRefId("merge.target_branch"),
            revision_table=SqlTableName(revision_table),
            revision_parents_table=SqlTableName(revision_parents_table),
            revision_model=domain.revision_model,
            revision_parent_model=domain.revision_parent_model,
        ),
    )
    op_meta_steps, op_meta_refs = build_merge_operation_scalar_projection_steps(
        ref_prefix="merge",
        source_branch_ref_id="merge.source_branch",
        target_branch_ref_id="merge.target_branch",
        base_revision_ref_id="merge.lca",
    )
    classify = MergeClassifyStep(
        ref_id=ServerPlanRefId("merge.classify"),
        config=_MergeClassifyConfig(
            lca_ref_id=ServerPlanRefId("merge.lca"),
            source_branch_ref_id=ServerPlanRefId("merge.source_branch"),
            target_branch_ref_id=ServerPlanRefId("merge.target_branch"),
        ),
    )
    extract_utd: ServerPlanStep[bool]
    extract_ff: ServerPlanStep[bool]
    extract_diverged: ServerPlanStep[bool]
    extract_three_way: ServerPlanStep[bool]
    if strategy_value == "three-way-no-ff":
        extract_utd = _StaticMergeBoolStep(ServerPlanRefId("merge.is_utd"), False)
        extract_ff = _StaticMergeBoolStep(ServerPlanRefId("merge.is_ff"), False)
        extract_diverged = _StaticMergeBoolStep(ServerPlanRefId("merge.is_diverged"), False)
        extract_three_way = _StaticMergeBoolStep(ServerPlanRefId("merge.is_three_way"), True)
    else:
        extract_utd = _ExtractClassificationBoolStep(
            ref_id=ServerPlanRefId("merge.is_utd"),
            config=_ExtractClassificationBoolConfig(
                classify_ref_id=ServerPlanRefId("merge.classify"),
                field_name="is_up_to_date",
            ),
        )
        extract_ff = _ExtractClassificationBoolStep(
            ref_id=ServerPlanRefId("merge.is_ff"),
            config=_ExtractClassificationBoolConfig(
                classify_ref_id=ServerPlanRefId("merge.classify"),
                field_name="is_fast_forward",
            ),
        )
        extract_diverged = _ExtractClassificationBoolStep(
            ref_id=ServerPlanRefId("merge.is_diverged"),
            config=_ExtractClassificationBoolConfig(
                classify_ref_id=ServerPlanRefId("merge.classify"),
                field_name="is_diverged",
            ),
        )
        extract_three_way = _ExtractClassificationBoolStep(
            ref_id=ServerPlanRefId("merge.is_three_way"),
            config=_ExtractClassificationBoolConfig(
                classify_ref_id=ServerPlanRefId("merge.classify"),
                field_name="needs_three_way",
            ),
        )
    utd_result = _BuildUTDResultStep(
        ref_id=ServerPlanRefId("merge.result_utd"),
        config=_BuildUTDResultConfig(
            source_branch_ref_id=ServerPlanRefId("merge.source_branch"),
            target_branch_ref_id=ServerPlanRefId("merge.target_branch"),
        ),
    )
    if strategy_value == "three-way-no-ff":
        utd_gated_steps = []
    else:
        utd_gated_steps = _gate_branch_steps(
            condition_ref="merge.is_utd",
            branch_steps=[utd_result],
            force_non_batchable=sqlite_force_non_batchable,
            publish_ref_ids=frozenset({"merge.result_utd"}),
        )

    ff_tip_projection_steps, ff_tip_refs = build_fast_forward_branch_tip_scalar_projection_steps(
        ref_prefix="merge.ff_tip",
        source_branch_ref_id="merge.source_branch",
        target_branch_ref_id="merge.target_branch",
    )
    _target_branch_ref_id, _target_tip_ref_id, source_tip_ref_id, _source_branch_ref_id = _ff_scalar_step_ref_ids(
        "merge.ff_tip",
    )
    merge_log_exclude = frozenset(
        {"sys_id", "revision_id", "staged_commit_id", "deleted", "branch_id", "valid_from_revision_id", "valid_to_revision_id"},
    )
    from impl.common.l2070_server_plan.steps.merge_replay_permission import FastForwardMergePermissionStep
    from impl.common.l2070_server_plan.steps.replay_permission import replay_actions_are_unconditional

    ff_data_steps: list[ServerPlanStep[Any]] = [
        FastForwardMergePermissionStep(
            ServerPlanRefId(f"merge.ff_permission_{get_table_name(model)}"),
            domain=domain,
            model=model,
            source_branch_ref=ServerPlanRefId(_source_branch_ref_id),
            target_branch_ref=ServerPlanRefId(_target_branch_ref_id),
            source_tip_ref=ServerPlanRefId(source_tip_ref_id),
            target_tip_ref=ServerPlanRefId(_target_tip_ref_id),
            session=session_id_ref,
        )
        for model in versioned_tables
        if not replay_actions_are_unconditional(model)
    ]
    for table_cls in versioned_tables:
        physical_tables = get_versioned_table_names(table_cls)
        tbl = physical_tables.base
        tip_tbl = physical_tables.tip
        sparse_tbl = physical_tables.sparse
        ff_data_steps.append(
            _FFDeleteBranchDataStep(
                ServerPlanRefId(f"merge.ff_del_tip_{tbl}"),
                _FFDeleteBranchDataConfig(
                    table=SqlTableName(tip_tbl),
                    target_branch_ref_id=ServerPlanRefId("merge.target_branch"),
                    require_target_materialized=True,
                ),
            ),
        )
        ff_data_steps.append(
            _FFCopyTipDataStep(
                ServerPlanRefId(f"merge.ff_copy_tip_{tbl}"),
                _FFCopyTipDataConfig(
                    tip_table=SqlTableName(tip_tbl),
                    source_branch_ref_id=ServerPlanRefId("merge.source_branch"),
                    target_branch_ref_id=ServerPlanRefId("merge.target_branch"),
                    model=table_cls,
                    require_source_materialized=True,
                    require_target_materialized=True,
                ),
            ),
        )
        ff_data_steps.append(
            _FFCopySparseDataStep(
                ServerPlanRefId(f"merge.ff_copy_sparse_from_tip_{tbl}"),
                _FFCopySparseDataConfig(
                    sparse_table=SqlTableName(sparse_tbl),
                    source_branch_ref_id=ServerPlanRefId("merge.source_branch"),
                    target_branch_ref_id=ServerPlanRefId("merge.target_branch"),
                    model=table_cls,
                    require_source_materialized=True,
                ),
            ),
        )
        close_sparse_ref_id = ServerPlanRefId(f"merge.ff_close_sparse_{tbl}")
        ff_data_steps.append(
            _FFCloseStaleSparseDataStep(
                close_sparse_ref_id,
                _FFCloseStaleSparseDataConfig(
                    sparse_table=SqlTableName(sparse_tbl),
                    source_branch_ref_id=ServerPlanRefId("merge.source_branch"),
