        return [resolve_op, fetch_by_resolved_op]


class ResolveConflictIntent(IntentStep[MergeConflictView]):
    """L4: Resolve a single merge conflict.

    Lowers to L0 steps that:
    1. SELECT the conflict record, validate it exists and is PENDING
    2. UPDATE the conflict with resolution_payload and new status
    3. Check if all conflicts are resolved; if so, auto-complete the merge
    """

    intent_tags = frozenset({"merge", "conflict", "write", "intent"})

    __slots__ = (
        "_conflict_id",
        "_domain",
        "_resolution_payload",
        "_session_id",
        "_status",
    )

    def __init__(
        self: ResolveConflictIntent,
        ref_id: ServerPlanRefId,
        *,
        domain: type[VersioningDomain],
        conflict_id: ScalarServerRef[SysId],
        resolution_payload: ObjectServerRef[ConflictResolutionPayloadMap],
        status: ScalarServerRef[MergeConflictStatusName],
    ) -> None:
        super().__init__(ref_id)
        self._domain = domain
        self._conflict_id = _require_seeded_ref(
            conflict_id,
            owner=type(self).__name__,
            field_name="conflict_id",
        )
        self._resolution_payload = _require_seeded_ref(
            resolution_payload,
            owner=type(self).__name__,
            field_name="resolution_payload",
        )
        self._status = _require_seeded_ref(status, owner=type(self).__name__, field_name="status")

    def lower(
        self: ResolveConflictIntent,
        ctx: LoweringContext,
    ) -> Sequence[ServerPlanStep[Any]]:
        from impl.common.l2070_server_plan.steps.conflict_resolution_steps import (
            FetchPendingConflictStep,
            IncrementAndMaybeCompleteStep,
            RefetchConflictViewStep,
            UpdateConflictResolutionStep,
            _IncrementAndMaybeCompleteConfig,
            _RefetchConflictViewConfig,
            _UpdateConflictResolutionConfig,
        )

        conflict_table = get_table_name(MergeConflictRecord)
        op_table = get_table_name(MergeOperation)
        conflict_id_raw = SysId(self._conflict_id)

        # Step 1: Fetch conflict, validate exists and status is 'pending'
        fetch_conflict = FetchPendingConflictStep(
            ref_id=ServerPlanRefId("resolve.fetch_conflict"),
            conflict_table=SqlTableName(conflict_table),
            conflict_id_raw=conflict_id_raw,
        )

        # Step 2: UPDATE conflict with resolution payload and new status
        update_conflict = UpdateConflictResolutionStep(
            ref_id=ServerPlanRefId("resolve.update_conflict"),
            conflict_table=SqlTableName(conflict_table),
            conflict_id_raw=conflict_id_raw,
            config=_UpdateConflictResolutionConfig(
                resolution_payload=dict(
                    self._resolution_payload,
                ),
                status=self._status,
                after_refs=frozenset({ServerPlanRefId("resolve.fetch_conflict")}),
            ),
        )

        # Step 3: Increment resolved_count and conditionally set status='complete'
        # in a single UPDATE to avoid undefined behavior when multiple CTE
        # UPDATEs target the same merge_operations row.
        incr_and_complete = IncrementAndMaybeCompleteStep(
            ref_id=ServerPlanRefId("resolve.incr_and_complete"),
            merge_op_table=SqlTableName(op_table),
            conflict_table=SqlTableName(conflict_table),
            conflict_ref_id=ServerPlanRefId("resolve.fetch_conflict"),
            config=_IncrementAndMaybeCompleteConfig(
                conflict_id_raw=conflict_id_raw,
                after_refs=frozenset({ServerPlanRefId("resolve.update_conflict")}),
            ),
        )

        # Step 4: Re-fetch the updated conflict record.
        # update_ref_id lets it read from the UPDATE CTE's RETURNING clause
        # in CTE-batched mode (PostgreSQL) where same-snapshot reads can't
        # see prior UPDATE effects.
        refetch = RefetchConflictViewStep(
            ref_id=self.ref_id,
            conflict_table=SqlTableName(conflict_table),
            conflict_id_raw=conflict_id_raw,
            config=_RefetchConflictViewConfig(
                after_refs=frozenset(
                    {
                        ServerPlanRefId("resolve.update_conflict"),
                        ServerPlanRefId("resolve.incr_and_complete"),
                    },
                ),
                update_ref_id=ServerPlanRefId("resolve.update_conflict"),
            ),
        )

        return [fetch_conflict, update_conflict, incr_and_complete, refetch]


class RebaseIntent(IntentStep[Any]):
    """L4: Rebase source_branch onto target_branch.

    Lowers to L0 steps that:
    1. Resolve both branches and find the fork point
    2. Walk the revision chain from fork to source tip
    3. For each commit: compute diff, apply changes to new base, create revision
    4. Update branch pointer to new tip
    """

    intent_tags = frozenset({"rebase", "intent"})

    __slots__ = (
        "_domain",
        "_revision_metadata",
        "_session_id",
        "_source_branch_name",
        "_target_branch_name",
        "_workspace_id",
    )

    def __init__(
        self: RebaseIntent,
        ref_id: ServerPlanRefId,
        *,
        domain: type[VersioningDomain],
        workspace_id: ScalarServerRef[WorkspaceId],
        source_branch_name: ScalarServerRef[BranchName],
        target_branch_name: ScalarServerRef[BranchName],
        session_id: ScalarServerRef[SessionId],
        revision_metadata: ObjectServerRef[RevisionMetadataPayload],
    ) -> None:
        super().__init__(ref_id)
        self._domain = domain
        self._workspace_id = workspace_id
        self._source_branch_name = source_branch_name
        self._target_branch_name = target_branch_name
        self._session_id = _require_seeded_ref(session_id, owner=type(self).__name__, field_name="session_id")
        self._revision_metadata = _require_seeded_ref(
            revision_metadata,
            owner=type(self).__name__,
            field_name="revision_metadata",
        )

    def lower(
        self: RebaseIntent,
        ctx: LoweringContext,
    ) -> Sequence[ServerPlanStep[Any]]:
        from impl.common.l2070_server_plan.steps.branch_mutation_permission import (
            NamedBranchReadPermissionStep,
        )
        from impl.common.l2070_server_plan.steps.conditional_builders import (
            build_one_sided_conditional,
        )
        from impl.common.l2070_server_plan.steps.merge_steps import (
            FetchBranchByNameStep,
            FindLCAStep,
            _FetchBranchByNameConfig,
            _FindLcaConfig,
        )
        from impl.common.l2070_server_plan.steps.merge_three_way_steps import (
            _InvertBoolConfig,
            _InvertBoolStep,
            _ProjectMergeOpMetadataScalarConfig,
            _ProjectMergeOpMetadataScalarStep,
        )
        from impl.common.l2070_server_plan.steps.rebase_steps import (
            FetchCommitChainStep,
            ReplayLoopStep,
            _BuildUpToDateRebaseResultConfig,
            _BuildUpToDateRebaseResultStep,
            _FetchCommitChainConfig,
            _ReplayLoopConfig,
            _TargetTipMatchesForkConfig,
            _TargetTipMatchesForkStep,
        )

        domain = self._domain
        branch_table = get_table_name(domain.branch_model)
        branch_model = domain.branch_model
        revision_table = get_table_name(domain.revision_model)
        revision_parents_table = get_table_name(domain.revision_parent_model)
        index_table = get_table_name(domain.revision_branch_index_model)
        session_id = self._session_id
        rev_meta = dict(
            self._revision_metadata.values,
        )

        # Per-table metadata (lowering-time iteration)
        table_names: list[VersionedBaseTableName] = []
        sparse_tables: list[VersionedSparseTableName] = []
        tip_tables: list[VersionedTipTableName] = []
        data_columns_by_table: list[list[str]] = []
        for table_cls in _all_merge_table_models(domain):
            physical_tables = get_versioned_table_names(table_cls)
            table_names.append(physical_tables.base)
            sparse_tables.append(physical_tables.sparse)
            tip_tables.append(physical_tables.tip)
            data_columns_by_table.append(
                _merge_data_columns(table_cls, _VERSIONED_APPLY_EXCLUDE),
            )

        def _ref(suffix: str) -> str:
            return f"{self.ref_id}__{suffix}"

        # Step 1: Resolve branches after checking source visibility and target mutation authority.
        source_branch_guard = NamedBranchReadPermissionStep(
            ServerPlanRefId(_ref("source_branch_permission")),
            model=branch_model,
            branch_name=self._source_branch_name,
            workspace_id=self._workspace_id,
            session_id=session_id,
        )
        target_branch_guard = NamedBranchReadPermissionStep(
            ServerPlanRefId(_ref("target_branch_permission")),
            model=branch_model,
            branch_name=self._target_branch_name,
            workspace_id=self._workspace_id,
            session_id=session_id,
            action="update",
        )
        fetch_source = FetchBranchByNameStep(
            ref_id=ServerPlanRefId(_ref("source_branch")),
            config=_FetchBranchByNameConfig(
                branch_name=self._source_branch_name,
                branch_table=SqlTableName(branch_table),
                workspace_id=self._workspace_id,
                branch_model=branch_model,
                reset_merge_sql_materialization_caches=True,
            ),
        )
        fetch_target = FetchBranchByNameStep(
            ref_id=ServerPlanRefId(_ref("target_branch")),
            config=_FetchBranchByNameConfig(
                branch_name=self._target_branch_name,
                branch_table=SqlTableName(branch_table),
                workspace_id=self._workspace_id,
                branch_model=branch_model,
            ),
        )

        # Step 2: Validate source has commits
        validate_source = _ValidateSourceHasTipStep(
            ref_id=ServerPlanRefId(_ref("validate_source")),
            config=_ValidateSourceHasTipConfig(
                source_branch_ref_id=ServerPlanRefId(_ref("source_branch")),
                branch_model=branch_model,
                source_branch_name=_seeded_ref_or_none(
                    self._source_branch_name,
                    owner=type(self).__name__,
                    field_name="source_branch_name",
                ),
            ),
        )
        validate_target = _ValidateSourceHasTipStep(
            ref_id=ServerPlanRefId(_ref("validate_target")),
            config=_ValidateSourceHasTipConfig(
                source_branch_ref_id=ServerPlanRefId(_ref("target_branch")),
                branch_model=branch_model,
                source_branch_name=_seeded_ref_or_none(
                    self._target_branch_name,
                    owner=type(self).__name__,
                    field_name="target_branch_name",
                ),
            ),
        )

        # Step 3: Find fork point (LCA)
        from impl.common.l2070_server_plan.provider_helpers import require_versioned_lowering_provider

        find_fork = FindLCAStep(
            ref_id=ServerPlanRefId(_ref("fork")),
            config=_FindLcaConfig(
                source_branch_ref_id=ServerPlanRefId(_ref("source_branch")),
                target_branch_ref_id=ServerPlanRefId(_ref("target_branch")),
                revision_table=SqlTableName(revision_table),
                revision_parents_table=SqlTableName(revision_parents_table),
                revision_model=domain.revision_model,
                revision_parent_model=domain.revision_parent_model,
                force_non_batchable=require_versioned_lowering_provider(ctx).force_non_batchable_merge_plan(),
            ),
        )

        # Step 4: Validate fork exists (diverged check)
        extract_diverged = _ExtractClassificationForkNullStep(
            ref_id=ServerPlanRefId(_ref("is_diverged")),
            config=_ExtractClassificationForkNullConfig(
                fork_ref_id=ServerPlanRefId(_ref("fork")),
            ),
        )
        raise_diverged = _RaiseDivergedStep(ref_id=ServerPlanRefId(_ref("raise_diverged")))
        cond_diverged = build_one_sided_conditional(
            ref_id=ServerPlanRefId(_ref("cond_diverged")),
            condition_ref=ServerPlanRefId(_ref("is_diverged")),
            if_true_steps=[raise_diverged],
            default_value=None,
        )

        # Step 5: Fetch commit chain
        fetch_chain = FetchCommitChainStep(
            ref_id=ServerPlanRefId(_ref("chain")),
            config=_FetchCommitChainConfig(
                source_branch_ref_id=ServerPlanRefId(_ref("source_branch")),
                fork_ref_id=ServerPlanRefId(_ref("fork")),
                revision_parents_table=SqlTableName(revision_parents_table),
            ),
        )

        # Step 6: Check if the source is already based on the current target tip.
        already_based = _TargetTipMatchesForkStep(
            ref_id=ServerPlanRefId(_ref("already_based")),
            config=_TargetTipMatchesForkConfig(
                fork_ref_id=ServerPlanRefId(_ref("fork")),
                target_branch_ref_id=ServerPlanRefId(_ref("target_branch")),
            ),
        )
        utd_result = _BuildUpToDateRebaseResultStep(
            ref_id=ServerPlanRefId(_ref("result_utd")),
            config=_BuildUpToDateRebaseResultConfig(
                source_branch_ref_id=ServerPlanRefId(_ref("source_branch")),
                target_branch_ref_id=ServerPlanRefId(_ref("target_branch")),
            ),
        )
        cond_utd = build_one_sided_conditional(
            ref_id=ServerPlanRefId(_ref("cond_utd")),
            condition_ref=ServerPlanRefId(_ref("already_based")),
            if_true_steps=[utd_result],
            result_ref=ServerPlanRefId(_ref("result_utd")),
            default_value=None,
        )

        source_branch_sys_id = _ProjectMergeOpMetadataScalarStep(
            ServerPlanRefId(_ref("source_branch_sys_id")),
            _ProjectMergeOpMetadataScalarConfig(
                row_ref_id=ServerPlanRefId(_ref("source_branch")),
                field_name="sys_id",
            ),
        )
        target_branch_sys_id = _ProjectMergeOpMetadataScalarStep(
            ServerPlanRefId(_ref("target_branch_sys_id")),
            _ProjectMergeOpMetadataScalarConfig(
                row_ref_id=ServerPlanRefId(_ref("target_branch")),
                field_name="sys_id",
            ),
        )
        target_tip_revision = _ProjectMergeOpMetadataScalarStep(
            ServerPlanRefId(_ref("target_tip_revision")),
            _ProjectMergeOpMetadataScalarConfig(
                row_ref_id=ServerPlanRefId(_ref("target_branch")),
                field_name="tip_revision_sys_id",
            ),
        )

        from impl.common.l2070_server_plan.steps.merge_embedding_refs import (
            merge_embedding_ref_tables,
        )
        from l5200_vector_index.vector_config import get_vector_indexes

        embedding_stores = tuple(
            (get_table_name(model), index_name, ref_table)
            for model in _all_merge_table_models(domain)
            for index_name, config in get_vector_indexes(model).items()
            for ref_table in merge_embedding_ref_tables(
                get_table_name(model),
                index_name,
                config.content_store_strategy,
                planning_catalog=ctx.planning_catalog,
            )
        )
        # Step 7: Replay loop (dynamic child step generation)
        needs_replay = _InvertBoolStep(
            ref_id=ServerPlanRefId(_ref("needs_replay")),
            config=_InvertBoolConfig(
                source_ref_id=ServerPlanRefId(_ref("already_based")),
            ),
        )
        replay = ReplayLoopStep(
            ref_id=ServerPlanRefId(_ref("replay")),
            config=_ReplayLoopConfig(
                domain=domain,
                needs_replay_ref_id=ServerPlanRefId(_ref("needs_replay")),
                embedding_stores=embedding_stores,
                chain_ref_id=ServerPlanRefId(_ref("chain")),
                fork_ref_id=ServerPlanRefId(_ref("fork")),
                source_branch_id_ref_id=ServerPlanRefId(_ref("source_branch_sys_id")),
                target_branch_id_ref_id=ServerPlanRefId(_ref("target_branch_sys_id")),
                target_tip_ref_id=ServerPlanRefId(_ref("target_tip_revision")),
                revision_table=SqlTableName(revision_table),
                revision_parents_table=SqlTableName(revision_parents_table),
                branch_table=SqlTableName(branch_table),
                index_table=SqlTableName(index_table),
                session_id=session_id,
                table_names=tuple(SqlTableName(name) for name in table_names),
                sparse_tables=tuple(SqlTableName(name) for name in sparse_tables),
                tip_tables=tuple(SqlTableName(name) for name in tip_tables),
                data_columns_by_table=tuple(tuple(SqlColumnName(name) for name in columns) for columns in data_columns_by_table),
                source_branch_ref_id=ServerPlanRefId(_ref("source_branch")),
                target_branch_ref_id=ServerPlanRefId(_ref("target_branch")),
                revision_metadata=rev_meta,
            ),
        )

        rebase_auxiliary_steps: list[ServerPlanStep[Any]] = []
        if domain.graphs:
            from impl.common.l2070_server_plan.steps.barrier import BarrierStep
            from impl.common.l2070_server_plan.steps.commit_branch_steps import ReconcileGraphAuxiliaryTablesStep
            from impl.common.l2070_server_plan.steps.edge_constraint_steps import CheckDirtyGraphTreeValidityStep
            from l2070_batching.staged_source import PublishScopeDescriptor, opaque_scope_token
            from impl.common.l7245_versioned_backends.graph_aux_reconciliation import (
                collect_graph_auxiliary_reconciliation_table_sources,
            )
            from l9600_graphs.incremental_validation_models import (
                ContainsTreeComponentTip,
                ContainsTreeStateTip,
                GraphVisibleNodeTip,
                tree_edge_state_scopes,
            )

            auxiliary_scalar_refs = _ff_scalar_step_ref_ids(f"{self.ref_id}_rebase_auxiliary")
            source_branch_aux_ref = ServerPlanRefId(auxiliary_scalar_refs[0])
            target_branch_aux_ref = ServerPlanRefId(auxiliary_scalar_refs[1])
            rebase_auxiliary_steps.append(
                _ProjectMergeOpMetadataScalarStep(
                    source_branch_aux_ref,
                    _ProjectMergeOpMetadataScalarConfig(
                        row_ref_id=ServerPlanRefId(_ref("source_branch")),
                        field_name="sys_id",
                    ),
                ),
            )
            rebase_auxiliary_steps.append(
                _ProjectMergeOpMetadataScalarStep(
                    target_branch_aux_ref,
                    _ProjectMergeOpMetadataScalarConfig(
                        row_ref_id=ServerPlanRefId(_ref("target_branch")),
                        field_name="sys_id",
                    ),
                ),
            )
            auxiliary_boundary_ref = ServerPlanRefId(_ref("auxiliary_boundary"))
            rebase_auxiliary_steps.append(
                BarrierStep(
                    auxiliary_boundary_ref,
                    depends_on=frozenset(
                        {
                            ServerPlanRefId(_ref("cond_utd")),
                            ServerPlanRefId(_ref("replay")),
                            source_branch_aux_ref,
                            target_branch_aux_ref,
                        },
                    ),
                    requires_prior_boundary=True,
                ),
            )
            source_branch_aux = ServerRefs.from_ref_id(
                str(source_branch_aux_ref),
                variant="scalar",
                type_hint=BranchId,
            )
            target_branch_aux = ServerRefs.from_ref_id(
                str(target_branch_aux_ref),
                variant="scalar",
                type_hint=BranchId,
            )
            previous_tip_delete_ref = auxiliary_boundary_ref
            tree_scopes = tree_edge_state_scopes(domain)
            tree_edge_tables = frozenset(scope.edge_table_name for scope in tree_scopes)
            # Replay starts from source tip rows. Remove identities that the target
            # deleted or moved before full-tip graph reconciliation starts.
            for index, (table_name, tip_table, sparse_table) in enumerate(
                zip(table_names, tip_tables, sparse_tables, strict=True),
            ):
                delete_tip_ref = ServerPlanRefId(_ref(f"apply_target_tombstones_{index}"))
                rebase_auxiliary_steps.append(
                    _DeleteRebaseTipRowsChangedOnTargetStep(
                        delete_tip_ref,
                        source_branch=source_branch_aux,
                        source_branch_row_ref_id=ServerPlanRefId(_ref("source_branch")),
                        target_branch=target_branch_aux,
                        target_branch_row_ref_id=ServerPlanRefId(_ref("target_branch")),
                        tip_table=SqlTableName(tip_table),
                        sparse_table=SqlTableName(sparse_table),
                        comparison_columns=(
                            (SqlColumnName("source_sys_id"), SqlColumnName("target_sys_id")) if table_name in tree_edge_tables else ()
                        ),
                        depends_on=previous_tip_delete_ref,
                    ),
                )
                previous_tip_delete_ref = delete_tip_ref
            previous_auxiliary_clear_ref = previous_tip_delete_ref
            for index, scope in enumerate(tree_scopes):
                for table_suffix, auxiliary_table_name in (
                    ("state", "sys_contains_tree_state_tip"),
                    ("component", "sys_contains_tree_component_tip"),
                ):
                    clear_ref = ServerPlanRefId(_ref(f"clear_tree_{table_suffix}_{index}"))
                    rebase_auxiliary_steps.append(
                        _DeleteGraphTreeAuxiliaryScopeStep(
                            clear_ref,
                            branch=source_branch_aux,
                            branch_row_ref_id=ServerPlanRefId(_ref("source_branch")),
                            table=SqlTableName(auxiliary_table_name),
                            tree_scope_key=_GraphTreeScopeKey(scope.tree_state_scope_key),
                            depends_on=previous_auxiliary_clear_ref,
                        ),
                    )
                    previous_auxiliary_clear_ref = clear_ref
            validation_dependencies = frozenset({previous_auxiliary_clear_ref})
            full_tip_scope = PublishScopeDescriptor(
                kind="explicit",
                branch_scope_token=opaque_scope_token(source_branch_aux),
                staged_commit_ids=(),
            )
            for index, scope in enumerate(tree_scopes):
                validation_ref = ServerPlanRefId(_ref(f"validate_tree_{index}"))
                edge_tip_table = derive_versioned_table_names(
                    VersionedBaseTableName(scope.edge_table_name),
                ).tip
                rebase_auxiliary_steps.append(
                    CheckDirtyGraphTreeValidityStep(
                        validation_ref,
                        edge_tip_table=edge_tip_table,
                        edge_staged_table=edge_tip_table,
                        edge_base_table=SqlTableName(scope.edge_table_name),
                        lazy_branch=source_branch_aux,
                        publish_scope=full_tip_scope,
                        depends_on=validation_dependencies,
                        type_name_filter=scope.type_name_filter,
                        validate_full_tip=True,
                        branch_lookup=(SqlTableName(branch_table), self._workspace_id, self._source_branch_name),
                        additional_branch_lookup=(
                            SqlTableName(branch_table),
                            self._workspace_id,
                            self._target_branch_name,
                        ),
                    ),
                )
                validation_dependencies = frozenset({validation_ref})
            validation_boundary_ref = ServerPlanRefId(_ref("tree_validation_boundary"))
            rebase_auxiliary_steps.append(
                BarrierStep(
                    validation_boundary_ref,
                    depends_on=validation_dependencies,
                    requires_prior_boundary=True,
                ),
            )
            reconcile_ref = ServerPlanRefId(_ref("reconcile_graph_auxiliary"))
            rebase_auxiliary_steps.append(
                ReconcileGraphAuxiliaryTablesStep(
                    reconcile_ref,
                    domain=domain,
                    branch_ref=cast(
                        "Any",
                        ServerRefs.from_ref_id(
                            str(source_branch_aux_ref),
                            variant="scalar",
                            type_hint=BranchId,
                        ),
                    ),
                    depends_on=frozenset({validation_boundary_ref}),
                ),
            )
            previous_ref = reconcile_ref
            node_sparse_tables = tuple(
                derive_versioned_table_names(
                    VersionedBaseTableName(source.node_table_name),
                ).sparse
                for source in collect_graph_auxiliary_reconciliation_table_sources(domain).graph_node_tip_sources
            )
            for auxiliary_model, identity_columns in (
                (GraphVisibleNodeTip, ("graph_sys_id", "node_sys_id")),
                (
                    ContainsTreeComponentTip,
                    ("graph_sys_id", "edge_table_name", "component_root_sys_id"),
                ),
                (ContainsTreeStateTip, ("graph_sys_id", "edge_table_name", "node_sys_id")),
            ):
                auxiliary_table = get_table_name(auxiliary_model)
                overlay_ref = ServerPlanRefId(_ref(f"overlay_{auxiliary_table}"))
                rebase_auxiliary_steps.append(
                    _FFOverlayAuxiliaryDataStep(
                        overlay_ref,
                        _FFOverlayAuxiliaryDataConfig(
                            table=SqlTableName(auxiliary_table),
                            model=auxiliary_model,
                            identity_columns=identity_columns,
                            source_branch=target_branch_aux,
                            target_branch=source_branch_aux,
                            success_results=(),
                            update_conflicts=False,
                            depends_on=frozenset({previous_ref}),
                        ),
                    ),
                )
                previous_ref = overlay_ref
                if auxiliary_model is GraphVisibleNodeTip and node_sparse_tables:
                    delete_ref = ServerPlanRefId(_ref("delete_target_node_tombstones"))
                    rebase_auxiliary_steps.append(
                        _DeleteRebaseVisibleNodesForTargetTombstonesStep(
                            delete_ref,
                            source_branch=source_branch_aux,
                            source_branch_row_ref_id=ServerPlanRefId(_ref("source_branch")),
                            target_branch=target_branch_aux,
                            target_branch_row_ref_id=ServerPlanRefId(_ref("target_branch")),
                            node_sparse_tables=node_sparse_tables,
                            depends_on=previous_ref,
                        ),
                    )
                    previous_ref = delete_ref

        # Step 8: Collect result (UTD or replay)
        collector = _RebaseResultCollectorStep(
            ref_id=ServerPlanRefId(self.ref_id),
            config=_RebaseResultCollectorConfig(
                result_refs=(
                    ServerPlanRefId(_ref("cond_utd")),
                    ServerPlanRefId(_ref("replay")),
                ),
            ),
        )

        return [
            source_branch_guard,
            target_branch_guard,
            fetch_source,
            fetch_target,
            validate_source,
            validate_target,
            find_fork,
            extract_diverged,
            cond_diverged,
            fetch_chain,
            already_based,
            cond_utd,
            source_branch_sys_id,
            target_branch_sys_id,
            target_tip_revision,
            needs_replay,
            replay,
            *rebase_auxiliary_steps,
            collector,
        ]


class SquashMergeIntent(IntentStep[MergeResult]):
    """L4: Publish a squash merge from source_branch onto target_branch."""

    intent_tags = frozenset({"squash_merge", "merge", "intent"})

    __slots__ = (
        "_domain",
        "_included_models",
        "_revision_metadata",
        "_session_id",
        "_source_branch_name",
        "_target_branch_name",
        "_workspace_id",
    )

    def __init__(
        self: SquashMergeIntent,
        ref_id: ServerPlanRefId,
        *,
        domain: type[VersioningDomain],
        workspace_id: ScalarServerRef[WorkspaceId],
        source_branch_name: ScalarServerRef[BranchName],
        target_branch_name: ScalarServerRef[BranchName],
        session_id: ScalarServerRef[SessionId],
        revision_metadata: ObjectServerRef[RevisionMetadataPayload],
    ) -> None:
        super().__init__(ref_id)
        self._domain = domain
        self._workspace_id = workspace_id
        self._source_branch_name = source_branch_name
        self._target_branch_name = target_branch_name
        self._session_id = _require_seeded_ref(session_id, owner=type(self).__name__, field_name="session_id")
        self._revision_metadata = _require_seeded_ref(
            revision_metadata,
            owner=type(self).__name__,
            field_name="revision_metadata",
        )

    def lower(
        self: SquashMergeIntent,
        ctx: LoweringContext,
    ) -> Sequence[ServerPlanStep[Any]]:
        return _lower_new_squash_merge_steps(
            result_ref_id=self.ref_id,
            domain=self._domain,
            workspace_id=self._workspace_id,
            source_branch_name=self._source_branch_name,
            target_branch_name=self._target_branch_name,
