@pure_lazy
def shape_revision_metadata_payload(
    *,
    domain: type[VersioningDomain],
    provided: Mapping[str, str | int | float | bool | None],
    default_message: str | None,
    required_label: str,
    skip_message_when_default_none: bool = False,
) -> RevisionMetadataPayload:
    rev_model = domain.revision_model
    metadata_fields = {
        field_name
        for field_name in rev_model.model_fields
        if field_name not in {"sys_id", "parent_revision_sys_id", "parent_type", "timestamp", "session_id"}
    }
    rev_meta: dict[str, RevisionMetadataScalar] = {}
    for field_name in metadata_fields:
        db_col = get_db_column_name(rev_model, DynamicFieldName(field_name))
        field_info = rev_model.model_fields[field_name]
        if field_name in provided:
            rev_meta[db_col] = provided[field_name]
        elif field_name == "message" and default_message is not None:
            rev_meta[db_col] = default_message
        elif field_name == "message" and skip_message_when_default_none:
            continue
        elif field_info.default_factory is not None:
            default_factory = cast(Callable[[], object], field_info.default_factory)
            rev_meta[db_col] = cast("str | int | float | bool | None", default_factory())
        elif field_info.default is not PydanticUndefined:
            rev_meta[db_col] = field_info.default
        elif field_info.is_required():
            raise ProgrammingError(
                f"{required_label} requires revision metadata field '{field_name}'",
            )
        else:
            rev_meta[db_col] = None
    return RevisionMetadataPayload(values=tuple(sorted(rev_meta.items())))


def _revision_metadata_without_message(
    revision_metadata: RevisionMetadataItems,
) -> RevisionMetadataItems:
    return tuple((key, value) for key, value in revision_metadata if key != "message")


