    error_code: str
    message: str


class _ValidateCancellableStep(SqlRelationPublisherStep[None]):
    """L0: Fetch merge operation by ID and validate it can be cancelled.

    Raises ObjectNotFoundError if missing, ProgrammingError if status
    is not in {running, awaiting_resolution}.
    """

    __slots__ = ("_op_table", "_operation_id")

    def cte_publication_contract(self: _ValidateCancellableStep) -> CtePublicationContract:
        columns = ("ok", "error_code", "message")
        column_type_hints = SqlColumnTypeHints(bool_columns=frozenset({"ok"}), text_columns=frozenset({"error_code", "message"}))
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        _contract_model_cls = _ValidateCancellableStepCteRow
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=tuple(str(column) for column in columns),
            column_type_hints=column_type_hints,
            model_cls=_contract_model_cls,
            relation_role=VERSIONED_SEMANTIC_RESULT_ROLE,
            source_tables=_contract_source_tables,
        )

    def __init__(
        self: _ValidateCancellableStep,
        ref_id: ServerPlanRefId,
        config: _ValidateCancellableConfig,
    ) -> None:
        super().__init__(ref_id)
        self._operation_id = config.operation_id
        self._op_table = str(config.op_table)

    @property
    def level(self: _ValidateCancellableStep) -> int:
        return 0

    def result_cardinality(self: _ValidateCancellableStep) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self: _ValidateCancellableStep) -> bool:
        return True

    def step_tags(self: _ValidateCancellableStep) -> frozenset[str]:
        return frozenset({"read", "validation", "merge"})

    def tables_read(self: _ValidateCancellableStep) -> frozenset[str]:
        return frozenset({self._op_table})

    def tables_written(self: _ValidateCancellableStep) -> frozenset[str]:
        return frozenset()

    def dependencies(self: _ValidateCancellableStep) -> frozenset[str]:
        return frozenset()

    def compile(self: _ValidateCancellableStep, ctx: CompilationContext) -> CompiledStep[None]:
        grammar = SqlSelect(
            select=SqlSelectList([SqlStar()]),
            from_clause=SqlFrom(SqlTableAlias(SqlTableIdent(SqlTableName(self._op_table)))),
            where=SqlWhereClause(
                SqlBinaryOp(
                    SqlColumnRef(SqlColumnName("sys_id")),
                    BinaryOp.EQ,
                    SqlParam(str(self._operation_id)),
                ),
            ),
        )

        from l2070_batching.compilation import CompiledStep as _CompiledStep, CteReference
        from l2070_batching.output_shape import (
            CompiledOutputShape,
            DeclaredResultRelation,
            synthetic_output_field,
        )

        contract = self.cte_publication_contract()
        output_shape = CompiledOutputShape(
            tuple(synthetic_output_field(column) for column in contract.columns),
        )

        return _CompiledStep(
            output_shape=output_shape,
            result_relation=DeclaredResultRelation.from_output_shape(output_shape),
            grammar=column_in_assertion_query(
                grammar,
                column="status",
                values=tuple(_CANCELLABLE_STATUSES),
                error_message=(f"Merge operation {self._operation_id} cannot abort; status is not cancellable"),
            ),
            needs_returning=True,
            column_type_hints=contract.column_type_hints,
            closed_post_op=CompiledPostOp.assert_result(
                ResultAssertionSpec(
                    empty_result_code=AssertionResultCode.NOT_FOUND,
                    mappings=(
                        AssertionExceptionMapping(
                            code=AssertionResultCode.NOT_FOUND,
                            exc_type=ObjectNotFoundError,
                            default_message=f"Merge operation {self._operation_id} not found",
                        ),
                        AssertionExceptionMapping(
                            code=AssertionResultCode.ERROR,
                            exc_type=ProgrammingError,
                            default_message=(f"Merge operation {self._operation_id} cannot abort; status is not cancellable"),
                        ),
                    ),
                ),
            ),
        )


