class _DeleteRebaseTipRowsChangedOnTargetStep(NonPublishingStep[None]):
    """Remove inherited source-tip rows replaced or deleted on the target."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        source_branch: ScalarServerRef[BranchId],
        source_branch_row_ref_id: ServerPlanRefId,
        target_branch: ScalarServerRef[BranchId],
        target_branch_row_ref_id: ServerPlanRefId,
        tip_table: SqlTableName,
        sparse_table: SqlTableName,
        comparison_columns: tuple[SqlColumnName, ...],
        depends_on: ServerPlanRefId,
    ) -> None:
        super().__init__(ref_id)
        _require_single_ref_dependency(
            source_branch,
            owner=type(self).__name__,
            field_name="source_branch",
        )
        _require_single_ref_dependency(
            target_branch,
            owner=type(self).__name__,
            field_name="target_branch",
        )
        self._source_branch = source_branch
        self._source_branch_row_ref_id = source_branch_row_ref_id
        self._target_branch = target_branch
        self._target_branch_row_ref_id = target_branch_row_ref_id
        self._tip_table = tip_table
        self._sparse_table = sparse_table
        self._comparison_columns = comparison_columns
        self._depends_on = depends_on

    @property
    def level(self: _DeleteRebaseTipRowsChangedOnTargetStep) -> int:
        return 0

    def result_cardinality(self: _DeleteRebaseTipRowsChangedOnTargetStep) -> Cardinality:
        return Cardinality.NONE

    def is_read_only(self: _DeleteRebaseTipRowsChangedOnTargetStep) -> bool:
        return False

    def step_tags(self: _DeleteRebaseTipRowsChangedOnTargetStep) -> frozenset[str]:
        return frozenset({"write", "rebase", "tip", "graph_auxiliary"})

    def tables_read(self: _DeleteRebaseTipRowsChangedOnTargetStep) -> frozenset[str]:
        return frozenset({str(self._sparse_table)})

    def tables_written(self: _DeleteRebaseTipRowsChangedOnTargetStep) -> frozenset[str]:
        return frozenset({str(self._tip_table)})

    def dependencies(self: _DeleteRebaseTipRowsChangedOnTargetStep) -> frozenset[str]:
        return frozenset(
            {
                *_ref_dependencies(self._source_branch),
                *_ref_dependencies(self._target_branch),
                str(self._depends_on),
            },
        )

    def compile(self: _DeleteRebaseTipRowsChangedOnTargetStep, ctx: CompilationContext) -> CompiledStep[None]:
        from impl.common.l2070_server_plan.steps._query_helper_compile import _collect_auxiliary_ctes_from_consumed
        from impl.common.l2100_sql_grammar.tree.expr_ops import SqlExists, SqlIsNull, sql_or
        from l2070_batching.compilation import CompiledStep as _CompiledStep

        source_ref = _require_single_ref_dependency(
            self._source_branch,
            owner=type(self).__name__,
            field_name="source_branch",
        )
        target_ref = _require_single_ref_dependency(
            self._target_branch,
            owner=type(self).__name__,
            field_name="target_branch",
        )
        source_branch = _require_merge_scalar_or_row_field(
            ctx,
            projected_scalar_ref_id=source_ref,
            row_ref_id=self._source_branch_row_ref_id,
            row_field_name="sys_id",
        )
        target_branch = _require_merge_scalar_or_row_field(
            ctx,
            projected_scalar_ref_id=target_ref,
            row_ref_id=self._target_branch_row_ref_id,
            row_field_name="sys_id",
        )
        target_change_alias = SqlAliasName("target_change")
        grammar = SqlDelete(
            table=SqlTableIdent(self._tip_table),
            where=SqlWhereClause(
                sql_and(
                    SqlBinaryOp(SqlColumnRef(SqlColumnName("branch_id")), BinaryOp.EQ, source_branch),
                    SqlExists(
                        SqlSelect(
                            select_list=SqlSelectList([SqlStar()]),
                            from_=SqlTableAlias(SqlTableIdent(self._sparse_table), target_change_alias),
                            where=SqlWhereClause(
                                sql_and(
                                    SqlBinaryOp(
                                        SqlColumnRef(SqlColumnName("branch_id"), str(target_change_alias)),
                                        BinaryOp.EQ,
                                        target_branch,
                                    ),
                                    SqlBinaryOp(
                                        SqlColumnRef(SqlColumnName("sys_id"), str(target_change_alias)),
                                        BinaryOp.EQ,
                                        SqlColumnRef(SqlColumnName("sys_id"), str(self._tip_table)),
                                    ),
                                    sql_or(
                                        SqlBinaryOp(
                                            SqlColumnRef(SqlColumnName("sys_deleted"), str(target_change_alias)),
                                            BinaryOp.EQ,
                                            SqlParam(True),
                                        ),
                                        *(
                                            SqlBinaryOp(
                                                SqlColumnRef(column, str(target_change_alias)),
                                                BinaryOp.NE,
                                                SqlColumnRef(column, str(self._tip_table)),
                                            )
                                            for column in self._comparison_columns
                                        ),
                                    ),
                                    SqlIsNull(
                                        SqlColumnRef(SqlColumnName("sys_valid_to_revision_id"), str(target_change_alias)),
                                    ),
                                ),
                            ),
                        ),
                    ),
                ),
            ),
        )
        consumed_ctes = [
            _consumed_merge_scalar_or_row_cte(
                ctx,
                projected_scalar_ref_id=str(source_ref),
                row_ref_id=str(self._source_branch_row_ref_id),
            ),
            _consumed_merge_scalar_or_row_cte(
                ctx,
                projected_scalar_ref_id=str(target_ref),
                row_ref_id=str(self._target_branch_row_ref_id),
            ),
        ]
        return _CompiledStep(
            grammar=grammar,
            needs_returning=False,
            auxiliary_ctes=_collect_auxiliary_ctes_from_consumed(consumed_ctes) or None,
        )


class _FFCopySparseDataStep(NonPublishingStep[None]):
    """L0: Copy sparse data from source branch to target branch during fast-forward merge."""

    __slots__ = (
        "_model",
        "_dependency_ref_ids",
        "_require_source_materialized",
        "_require_source_tipless",
        "_source_is_sparse",
        "_source_ref_id",
        "_sparse_table",
        "_target_ref_id",
    )

    def __init__(
        self: _FFCopySparseDataStep,
        ref_id: ServerPlanRefId,
        config: _FFCopySparseDataConfig,
    ) -> None:
        super().__init__(ref_id)
        self._sparse_table = str(config.sparse_table)
        self._source_ref_id = str(config.source_branch_ref_id)
        self._target_ref_id = str(config.target_branch_ref_id)
        self._model = config.model
        self._source_is_sparse = config.source_is_sparse
        self._dependency_ref_ids = tuple(str(ref_id) for ref_id in config.dependency_ref_ids)
        self._require_source_tipless = config.require_source_tipless
        self._require_source_materialized = config.require_source_materialized

    @property
    def level(self: _FFCopySparseDataStep) -> int:
        return 0

    def result_cardinality(self: _FFCopySparseDataStep) -> Cardinality:
        return Cardinality.NONE

    def is_read_only(self: _FFCopySparseDataStep) -> bool:
        return False

    def step_tags(self: _FFCopySparseDataStep) -> frozenset[str]:
        return frozenset({"write", "merge", "fast_forward", "grammar"})

    def tables_read(self: _FFCopySparseDataStep) -> frozenset[str]:
        tables = {self._sparse_table}
        if not self._source_is_sparse:
            tables.add(str(get_versioned_table_names(self._model).tip))
        return frozenset(tables)

    def tables_written(self: _FFCopySparseDataStep) -> frozenset[str]:
        return frozenset({self._sparse_table})

    def dependencies(self: _FFCopySparseDataStep) -> frozenset[str]:
        return frozenset({self._source_ref_id, self._target_ref_id, *self._dependency_ref_ids})

    def compile(self: _FFCopySparseDataStep, ctx: CompilationContext) -> CompiledStep[None]:
        from impl.common.l2050_sql_types.sql_branded_types import (
            SqlColumnName,
            SqlTableName,
        )
        from impl.common.l2070_server_plan.steps.branch_ops_steps import (
            _canonical_type_name_expr_for_copy,
            _get_sparse_columns_for_model,
        )
        from impl.common.l2070_server_plan.steps.generated_storage_columns import (
            include_generated_storage_columns,
        )
        from l1000_schema.table_utils import get_table_name
        from l2070_batching.compilation import CompiledStep as _CompiledStep

        sparse_columns = _get_sparse_columns_for_model(
            self._model,
            include_generated_storage_columns=include_generated_storage_columns(ctx),
        )
        cached_sparse_columns = ctx.schema_column_cache.get(self._sparse_table) if ctx.schema_column_cache is not None else None
        if cached_sparse_columns is not None:
            sparse_columns = [db_col for db_col in sparse_columns if db_col in cached_sparse_columns]
        physical_tables = get_versioned_table_names(self._model)
        base_table = physical_tables.base
        tip_table = physical_tables.tip
        source_alias = SqlAliasName("s")
        src_id_expr = _resolve_merge_cte_field(ctx, ServerPlanRefId(self._source_ref_id), "sys_id")
        tgt_id_expr = _resolve_merge_cte_field(ctx, ServerPlanRefId(self._target_ref_id), "sys_id")

        select_exprs: list[SqlRenderable] = []
        for db_col in sparse_columns:
            if db_col == "branch_id":
                select_exprs.append(tgt_id_expr)
                continue
            if db_col == "sys_valid_from_revision_id":
                source_column = "sys_valid_from_revision_id" if self._source_is_sparse else "sys_revision_id"
                select_exprs.append(SqlColumnRef(SqlColumnName(source_column), str(source_alias)))
                continue
            if db_col == "sys_valid_to_revision_id":
                select_exprs.append(
                    SqlColumnRef(SqlColumnName(db_col), str(source_alias)) if self._source_is_sparse else SqlInlineLiteral(None),
                )
                continue
            if db_col == "sys_deleted":
                select_exprs.append(
                    SqlColumnRef(SqlColumnName(db_col), str(source_alias)) if self._source_is_sparse else SqlInlineLiteral(False),
                )
                continue
            canonical_type_name_expr = _canonical_type_name_expr_for_copy(
                model=self._model,
                source_alias=str(source_alias),
                source_type_name_column=db_col,
                base_table=base_table,
            )
            if canonical_type_name_expr is not None:
                select_exprs.append(canonical_type_name_expr)
                continue
            select_exprs.append(
                SqlColumnRef(
                    SqlColumnName(db_col),
                    str(source_alias),
                ),
            )

        where_expr: SqlRenderable = SqlBinaryOp(
            SqlColumnRef(SqlColumnName("branch_id"), str(source_alias)),
            BinaryOp.EQ,
            src_id_expr,
        )
        if self._require_source_tipless:
            where_expr = sql_and(
                where_expr,
                _branch_tip_materialized_predicate(
                    ctx,
                    ServerPlanRefId(self._source_ref_id),
                    materialized=False,
                ),
            )
        if self._require_source_materialized:
            where_expr = sql_and(
                where_expr,
                _branch_tip_materialized_predicate(
                    ctx,
                    ServerPlanRefId(self._source_ref_id),
                    materialized=True,
                ),
            )
        conflict_columns = ["branch_id", "sys_id", "sys_valid_from_revision_id"]
        update_columns = [col for col in sparse_columns if col not in {"branch_id", "sys_id", "sys_valid_from_revision_id"}]
        grammar = SqlInsertFromSelect(
            target_table=SqlTableName(self._sparse_table),
            target_columns=sparse_columns,
            source_table=SqlTableName(self._sparse_table if self._source_is_sparse else tip_table),
            select_exprs=select_exprs,
            where=where_expr,
            source_alias=source_alias,
            conflict_columns=conflict_columns,
            update_columns=update_columns,
        )
        return _CompiledStep(grammar=grammar, needs_returning=False)


class _FFTableHasChangesStepCteRow(BaseModel):
    result: bool = Field(json_schema_extra={"db_column": "__result"})


class _FFTableHasChangesStep(MaybeSqlRelationPublisherStep[bool]):
    """Return True when a table's branch-local sparse history differs in FF merge."""

    __slots__ = (
        "_data_columns",
        "_revision_parents_table",
        "_revision_table",
        "_source_ref_id",
        "_sparse_table",
        "_target_ref_id",
    )

    def __init__(
        self: _FFTableHasChangesStep,
        ref_id: ServerPlanRefId,
        config: _FFTableHasChangesConfig,
    ) -> None:
        super().__init__(ref_id)
        self._source_ref_id = str(config.source_branch_ref_id)
        self._target_ref_id = str(config.target_branch_ref_id)
        self._sparse_table = str(config.sparse_table)
        self._data_columns = list(config.data_columns)
        self._revision_table = str(config.revision_table)
        self._revision_parents_table = str(config.revision_parents_table)

    @property
    def level(self: _FFTableHasChangesStep) -> int:
        return 0

    def result_cardinality(self: _FFTableHasChangesStep) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self: _FFTableHasChangesStep) -> bool:
        return True

    def execution_role(self: _FFTableHasChangesStep) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def step_tags(self: _FFTableHasChangesStep) -> frozenset[str]:
        return frozenset({"read", "merge", "fast_forward", "grammar"})

    def tables_read(self: _FFTableHasChangesStep) -> frozenset[str]:
        return frozenset({self._sparse_table})

    def tables_written(self: _FFTableHasChangesStep) -> frozenset[str]:
        return frozenset()

    def dependencies(self: _FFTableHasChangesStep) -> frozenset[str]:
        return frozenset({self._source_ref_id, self._target_ref_id})

    def cte_publication_contract(self: _FFTableHasChangesStep) -> CtePublicationContract:
        columns = ("__result",)
        column_type_hints = _bool_result_type_hints()
        if columns is None:
            if column_type_hints is not None and column_type_hints.has_any():
                msg = f"{type(self).__name__} declares SQL column type hints without an explicit cte_output_columns() contract."
                raise TypeError(msg)
            return CtePublicationContract.non_publishing()
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        _contract_model_cls = _FFTableHasChangesStepCteRow
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=tuple(str(column) for column in columns),
            column_type_hints=column_type_hints,
            model_cls=_contract_model_cls,
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def compile(self: _FFTableHasChangesStep, ctx: CompilationContext) -> CompiledStep[bool]:
        from impl.common.l2100_sql_grammar.domain.versioning.stmt_two_way_diff import (
            SqlTwoWayDiffCountQuery,
            SqlTwoWayDiffCte,
        )
        from impl.common.l2100_sql_grammar.domain.query.stmt_dynamic import (
            SqlSelectExistsFromSubquery,
        )
        from l2070_batching.compilation import CompiledStep as _CompiledStep

        source_tip = _resolve_merge_cte_field(ctx, ServerPlanRefId(self._source_ref_id), "tip_revision_sys_id")
        target_tip = _resolve_merge_cte_field(ctx, ServerPlanRefId(self._target_ref_id), "tip_revision_sys_id")
        source_branch_id = _resolve_merge_cte_field(ctx, ServerPlanRefId(self._source_ref_id), "sys_id")
        target_branch_id = _resolve_merge_cte_field(ctx, ServerPlanRefId(self._target_ref_id), "sys_id")

        diff_cte = SqlTwoWayDiffCte(
            old_revision_raw=target_tip,
            new_revision_raw=source_tip,
            sparse_table=SqlTableName(self._sparse_table),
            branch_id_raw=source_branch_id,
            data_columns=self._data_columns,
            revision_table=SqlTableName(self._revision_table),
            revision_parents_table=SqlTableName(self._revision_parents_table),
            old_branch_id_raw=target_branch_id,
        )
        grammar = SqlTwoWayDiffCountQuery(diff_cte)

        return _CompiledStep(
            grammar=SqlSelectExistsFromSubquery(grammar),
            needs_returning=True,
            closed_post_op=scalar_column_post_op(
                "__exists",
                scalar_coercion=ScalarCoercionKind.BOOL,
            ),
        )


