class MergeIntent(IntentStep[MergeResult]):
    """L4: Merge source_branch into target_branch.

    Lowers to L0 steps that:
    1. Resolve both branch pointers (SQL SELECT)
    2. Validate source has commits
    3. Find the LCA via recursive CTE
    4. Classify merge type (fast-forward / up-to-date / three-way)
    5. Extract classification booleans for ``ConditionalStep`` gating
    6. Conditional branches for UTD, FF, diverged
    7. Collect result from whichever branch fired
    """

    intent_tags = frozenset({"merge", "intent"})

    __slots__ = (
        "_domain",
        "_revision_metadata",
        "_session_id",
        "_source_branch_name",
        "_strategy",
        "_target_branch_name",
        "_workspace_id",
    )

    def __init__(
        self: MergeIntent,
        ref_id: ServerPlanRefId,
        *,
        domain: type[VersioningDomain],
        workspace_id: ScalarServerRef[WorkspaceId],
        source_branch_name: ScalarServerRef[BranchName],
        target_branch_name: ScalarServerRef[BranchName],
        session_id: ScalarServerRef[SessionId],
        strategy: ScalarServerRef[MergeStrategyName],
        revision_metadata: ObjectServerRef[RevisionMetadataPayload],
    ) -> None:
        super().__init__(ref_id)
        self._domain = domain
        self._workspace_id = workspace_id
        self._source_branch_name = source_branch_name
        self._target_branch_name = target_branch_name
        self._session_id = _require_seeded_ref(session_id, owner=type(self).__name__, field_name="session_id")
        self._strategy = _require_seeded_ref(strategy, owner=type(self).__name__, field_name="strategy")
        self._revision_metadata = _require_seeded_ref(
            revision_metadata,
            owner=type(self).__name__,
            field_name="revision_metadata",
        )

    def lower(
        self: MergeIntent,
        ctx: LoweringContext,
    ) -> Sequence[ServerPlanStep[Any]]:
        return _lower_new_merge_steps(
            result_ref_id=self.ref_id,
            domain=self._domain,
            workspace_id=self._workspace_id,
            source_branch_name=self._source_branch_name,
            target_branch_name=self._target_branch_name,
            session_id=self._session_id,
            strategy=self._strategy,
            revision_metadata=self._revision_metadata,
            versioned_tables=_all_merge_table_models(self._domain),
            ctx=ctx,
        )


