    ]


class AbortMergeIntent(IntentStep[None]):
    """L4: Abort a merge operation and clear its conflicts.

    Lowers to L0 steps that:
    1. Validate the operation exists and is in a cancellable state
    2. Delete all conflict records for the operation
    3. Update operation status to ABORTED
    """

    intent_tags = frozenset({"merge", "abort", "intent"})

    __slots__ = ("_domain", "_operation_id", "_session_id")

    def __init__(
        self: AbortMergeIntent,
        ref_id: ServerPlanRefId,
        *,
        domain: type[VersioningDomain],
        operation_id: ScalarServerRef[SysId],
    ) -> None:
        super().__init__(ref_id)
        self._domain = domain
        self._operation_id = _require_seeded_ref(
            operation_id,
            owner=type(self).__name__,
            field_name="operation_id",
        )

    def lower(
        self: AbortMergeIntent,
        ctx: LoweringContext,
    ) -> Sequence[ServerPlanStep[Any]]:
        from impl.common.l2060_query_spec.query_spec import QuerySpec
        from impl.common.l2070_server_plan.steps.query_delete import (
            QueryDeleteStep,
            _QueryDeleteStepConfig,
        )
        from impl.common.l2070_server_plan.steps.query_update import (
            QueryUpdateStep,
            _QueryUpdateStepConfig,
        )
        from l1000_schema.table_utils import get_table_name
        from l2060_query_builder.query_contracts import QueryFilter

        op_id = self._operation_id
        op_id_unwrap = getattr(op_id, "unwrap_to_str", None)
        op_id_filter_value = str(op_id_unwrap() if callable(op_id_unwrap) else op_id)
        op_table = get_table_name(MergeOperation)

        # Step 1: Fetch the merge operation, validate it exists and is cancellable.
        step1: ServerPlanStep[None] = _ValidateCancellableStep(
            ref_id=ServerPlanRefId("abort_merge.fetch_op"),
            config=_ValidateCancellableConfig(
                operation_id=op_id,
                op_table=SqlTableName(op_table),
            ),
        )

        # Step 2: Delete all conflict records for this operation (depends on step 1).
        delete_spec = QuerySpec(
            model_cls=MergeConflictRecord,
            select_columns=None,
            distinct=False,
            joins=[],
            filters=[QueryFilter(column="merge_operation_sys_id", operator="=", value=op_id_filter_value)],
            order_by=[],
            limit=None,
            offset=None,
            group_by=[],
            aggregations=[],
            having=[],
            window_functions=[],
            permission_grammar=None,
        )
        step2 = QueryDeleteStep(
            ref_id=ServerPlanRefId("abort_merge.delete_conflicts"),
            model_cls=MergeConflictRecord,
            config=_QueryDeleteStepConfig(
                query_spec=delete_spec,
                after_refs=frozenset({ServerPlanRefId("abort_merge.fetch_op")}),
            ),
        )

        # Step 3: Update operation status to ABORTED (depends on step 2)
        update_spec = QuerySpec(
            model_cls=MergeOperation,
            select_columns=None,
            distinct=False,
            joins=[],
            filters=[QueryFilter(column="sys_id", operator="=", value=op_id_filter_value)],
            order_by=[],
            limit=None,
            offset=None,
            group_by=[],
            aggregations=[],
            having=[],
            window_functions=[],
            permission_grammar=None,
        )
        step3 = QueryUpdateStep(
            ref_id=self.ref_id,
            model_cls=MergeOperation,
            config=_QueryUpdateStepConfig(
                query_spec=update_spec,
                updates={"status": "aborted"},
                after_refs=frozenset({ServerPlanRefId("abort_merge.delete_conflicts")}),
            ),
        )

        return [step1, step2, step3]


def _resolve_status_filter(
    status_filter: frozenset[MergeConflictStatusName] | ServerRef[Any],
) -> frozenset[str]:
    """Resolve a status-filter arg that may be either a frozenset or a seeded ServerRef."""
    if isinstance(status_filter, ServerRef):
        status_shape: PlanningServerValueShape = inspect_server_value_shape_for_planning(
            status_filter,
            site="_resolve_status_filter",
        )
        ref_id = status_shape.symbolic_ref_id
        if ref_id is None:
            msg = "status_filter ServerRef is not seeded at lowering time; pass a frozenset or seed one through ServerRefs.object(...)."
            raise ProgrammingError(msg)
        found, resolved = read_seeded_constant_from_ctx(None, ServerPlanRefId(ref_id))
        if not found:
            msg = "status_filter ServerRef is not seeded at lowering time; pass a frozenset or seed one through ServerRefs.object(...)."
            raise ProgrammingError(msg)
        status_filter = cast("frozenset[MergeConflictStatusName]", resolved)
    return frozenset(status_filter)


