@dataclass(frozen=True)
class _QueryExecuteAggregateStepConfig:
    query_spec: Any
    user_id_ref_id: ServerPlanRefId | None = None


def _require_aggregate_assertion_grammar(grammar: object | None) -> object:
    if grammar is not None:
        return grammar
    msg = "JSON_OBJECT_AGG null-key assertion requires compiled SQL grammar."
    raise RuntimeError(msg)


def _aggregate_output_shape(
    model_cls: type[DatabaseObjectRow],
    query_spec: Any,
) -> CompiledOutputShape | None:
    mappings: list[tuple[str, str, bool]] = []
    for index, group_column in enumerate(getattr(query_spec, "group_by", ()) or ()):
        if isinstance(group_column, str):
            db_col = get_db_column_name(model_cls, DynamicFieldName(group_column))
            mappings.append((db_col, db_col, False))
            continue
        if isinstance(group_column, AliasedField):
            mappings.append((group_column.alias, group_column.alias, False))
            continue
        if isinstance(group_column, Field):
            db_col = get_db_column_name(model_cls, DynamicFieldName(group_column.name))
            mappings.append((db_col, db_col, False))
            continue
        if isinstance(group_column, AliasedExpression):
            mappings.append((group_column.alias, group_column.alias, False))
            continue
        if (
            isinstance(group_column, Expression)
            and group_column.field is not None
            and group_column.function is None
            and group_column.operator is None
        ):
            db_col = get_db_column_name(model_cls, DynamicFieldName(group_column.field))
            mappings.append((db_col, db_col, False))
            continue
        mappings.append((f"__group_by_{index}", f"__group_by_{index}", False))
    for agg in getattr(query_spec, "aggregates", None) or getattr(query_spec, "aggregations", None) or ():
        if getattr(agg, "alias", None):
            mappings.append((agg.alias, agg.alias, False))
    if not mappings:
        return None
    from l2070_batching.output_shape import output_shape_from_mappings

    return output_shape_from_mappings(tuple(mappings))


def _aggregate_projection_lineage(
    model_cls: type[DatabaseObjectRow],
    query_spec: Any,
    columns: tuple[str, ...],
) -> tuple[tuple[str, str], ...]:
    lineage: dict[str, str] = {}
    for index, group_column in enumerate(getattr(query_spec, "group_by", ()) or ()):
        if isinstance(group_column, str):
            db_col = get_db_column_name(model_cls, DynamicFieldName(group_column))
            lineage[db_col] = db_col
            continue
        if isinstance(group_column, AliasedField):
            lineage[group_column.alias] = get_db_column_name(
                cast("type[DatabaseObjectRow]", group_column.owner_model),
                DynamicFieldName(group_column.name),
            )
            continue
        if isinstance(group_column, Field):
            db_col = get_db_column_name(model_cls, DynamicFieldName(group_column.name))
            lineage[db_col] = db_col
            continue
        if isinstance(group_column, AliasedExpression):
            lineage[group_column.alias] = f"expression:{group_column.alias}"
            continue
        if (
            isinstance(group_column, Expression)
            and group_column.field is not None
            and group_column.function is None
            and group_column.operator is None
        ):
            db_col = get_db_column_name(model_cls, DynamicFieldName(group_column.field))
            lineage[db_col] = db_col
            continue
        synthetic_column = f"__group_by_{index}"
        lineage[synthetic_column] = f"group_by:{synthetic_column}"
    for agg in getattr(query_spec, "aggregates", None) or getattr(query_spec, "aggregations", None) or ():
        alias = getattr(agg, "alias", None)
        if alias:
            lineage[alias] = f"aggregate:{alias}"
    return tuple((column, lineage.get(column, f"aggregate:{column}")) for column in columns)


def _json_object_agg_key_expressions(query_spec: Any) -> tuple[Expression, ...]:
    expressions: list[Expression] = []
    for agg in getattr(query_spec, "aggregates", None) or getattr(query_spec, "aggregations", None) or ():
        if str(getattr(agg, "function", "")).upper() != "JSON_OBJECT_AGG":
            continue
        source = getattr(agg, "source_expression", None) or getattr(agg, "expression", None)
        args = getattr(source, "args", None) or ()
        if args and isinstance(args[0], Expression):
            expressions.append(args[0])
    return tuple(expressions)


def _json_object_agg_null_key_assertion_spec(query_spec: Any) -> Any:
    from l2060_query_builder.query_contracts import QueryFilter

    key_expressions = _json_object_agg_key_expressions(query_spec)
    if not key_expressions:
        msg = "JSON_OBJECT_AGG null-key assertion requires at least one key expression."
        raise ValueError(msg)
    null_expr = key_expressions[0] == Expression(value=None)
    for key_expr in key_expressions[1:]:
        null_expr = null_expr | (key_expr == Expression(value=None))
    return dc_replace(
        query_spec,
        filters=[*getattr(query_spec, "filters", ()), QueryFilter(expression=null_expr)],
        group_by=[],
        aggregations=[],
        having=[],
        window_functions=[],
        order_by=[],
        limit=None,
        offset=None,
        select_columns=None,
    )


class _CompiledAggregateQueryStep(MaybeSqlRelationPublisherStep[list[dict[str, Any]]]):
    def can_join_session_preamble_statement_batch(self: _CompiledAggregateQueryStep) -> bool:
        return True

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        model_cls: type[DatabaseObjectRow],
        query_spec: Any,
        user_id_ref_id: ServerPlanRefId | None,
        assertion_ref_id: ServerPlanRefId | None = None,
    ) -> None:
        super().__init__(ref_id)
        self._model_cls = model_cls
        self._query_spec = query_spec
        self._user_id_ref_id = user_id_ref_id
        self._assertion_ref_id = assertion_ref_id

    @property
    def level(self) -> int:
        return 0

    def step_tags(self) -> frozenset[str]:
        return frozenset({"read", "query", "aggregate", "grammar"})

    def is_read_only(self) -> bool:
        return True

    def result_cardinality(self) -> Cardinality:
        return Cardinality.MANY

    def tables_read(self) -> frozenset[str]:
        from l1000_schema.table_utils import get_table_name

        return frozenset({get_table_name(self._model_cls)})

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def cte_publication_contract(self: _CompiledAggregateQueryStep) -> CtePublicationContract:
        def _legacy_cte_output_columns() -> tuple[str, ...] | None:
            output_shape = _aggregate_output_shape(self._model_cls, self._query_spec)
            if output_shape is None:
                return None
            return output_shape.cte_output_columns

        columns = _legacy_cte_output_columns()

        def _legacy_cte_column_type_hints(columns: tuple[str, ...] | None) -> SqlColumnTypeHints | None:
            if columns is None:
                return None
            return _query_spec_column_type_hints(self._model_cls, self._query_spec, columns)

        column_type_hints = _legacy_cte_column_type_hints(columns)
        if columns is None:
            if column_type_hints is not None and column_type_hints.has_any():
                msg = f"{type(self).__name__} declares SQL column type hints without an explicit cte_output_columns() contract."
                raise TypeError(msg)
            return CtePublicationContract.non_publishing()
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        contract_columns = tuple(str(column) for column in columns)
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=contract_columns,
            column_type_hints=column_type_hints,
            relation_contract=CteRelationContract.projection_over_model(
                source_model_cls=self._model_cls,
                projection_lineage=_aggregate_projection_lineage(
                    self._model_cls,
                    self._query_spec,
                    contract_columns,
                ),
            ),
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def dependencies(self) -> frozenset[str]:
        deps: set[str] = set()
        if self._user_id_ref_id is not None:
            deps.add(str(self._user_id_ref_id))
        if self._assertion_ref_id is not None:
            deps.add(str(self._assertion_ref_id))
        if self._query_spec is None:
            return frozenset(deps)
        from impl.common.l2070_server_plan.steps._resolve import collect_query_spec_deps

        deps.update(str(dep) for dep in collect_query_spec_deps(self._query_spec))
        return frozenset(deps)

    def compile(self, ctx: CompilationContext) -> CompiledStep[list[dict[str, Any]]]:
        from impl.common.l2070_server_plan.steps._compile_helpers import (
            attach_runtime_read_permission_grammar,
            compile_query_grammar,
        )

        effective_spec = attach_runtime_read_permission_grammar(
            self._query_spec,
            self._model_cls,
            ctx,
            user_id_ref_id=self._user_id_ref_id,
        )
        effective_spec = _inject_multitable_polymorphic_cte_if_needed(
            cast("QuerySpec[DatabaseObjectRow]", effective_spec),
            model_cls=self._model_cls,
            ctx=ctx,
        )
        compiled = compile_query_grammar(
            effective_spec,
            self._model_cls,
            ctx,
            is_count=False,
        )

        contract = self.cte_publication_contract()
        output_shape = None
        result_relation = None
        column_type_hints = None
        if contract is not None:
            output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(contract)
        return CompiledStep(
            grammar=compiled.grammar,
            params=compiled.params,
            needs_returning=compiled.needs_returning,
            external_params_first=compiled.external_params_first,
            runtime_ref_ids=compiled.runtime_ref_ids,
            auxiliary_ctes=compiled.auxiliary_ctes,
            closed_post_op=row_dicts_post_op(),
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
        )


class _JsonObjectAggNullKeyAssertionStep(SqlRelationPublisherStep[None]):
    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        model_cls: type[DatabaseObjectRow],
        query_spec: Any,
        user_id_ref_id: ServerPlanRefId | None,
    ) -> None:
        super().__init__(ref_id)
        self._model_cls = model_cls
        self._query_spec = query_spec
        self._user_id_ref_id = user_id_ref_id

    @property
    def level(self) -> int:
        return 0

    def step_tags(self) -> frozenset[str]:
        return frozenset({"read", "query", "aggregate", "assertion", "grammar"})

    def is_read_only(self) -> bool:
        return True

    def result_cardinality(self) -> Cardinality:
        return Cardinality.ONE

    def tables_read(self) -> frozenset[str]:
        from l1000_schema.table_utils import get_table_name

