def _require_squash_cte_field(
    ctx: CompilationContext,
    ref_id: ServerPlanRefId,
    field_name: str,
) -> SqlRenderable:
    """Resolve a squash dependency to a published CTE field."""
    from l2070_batching.compilation import CteReference
    from impl.common.l2100_sql_grammar.domain.infra.stmt_dml_simple import SqlCteFieldRef

    cte_ref = ctx.cte_refs.get(ref_id)
    if isinstance(cte_ref, CteReference):
        if field_name not in cte_ref.columns:
            raise ValueError(f"Squash input {ref_id!r} does not publish field {field_name!r}")
        field = SqlCteFieldRef(ServerPlanRefId(cte_ref.ref_id), SqlColumnName(field_name))
        if cte_ref.auxiliary_query is not None:
            from impl.common.l2100_sql_grammar.tree.expr_compound import SqlSubquery
            from impl.common.l2100_sql_grammar.tree.statements import SqlCte, SqlSelect
            from impl.common.l2100_sql_grammar.tree.clauses import SqlSelectList

            return SqlSubquery(SqlCte(
                [(cte_ref.ref_id, cte_ref.auxiliary_query)],
                SqlSelect(select=SqlSelectList([field])),
            ))
        return field
    raise_missing_cte_fallback_forbidden(
        site_name="_require_squash_cte_field",
        trigger=f"squash dependency {ref_id!r} has no CTE binding for field {field_name!r}",
        blocked_path="compile-time squash field fallback outside explicit SQL-visible refs",
        result_contract="squash SQL compilation must consume base, branch, and tip values from explicit CTE refs",
        implementation_requirements=(
            "Publish squash inputs through explicit upstream CTE refs before compile().",
            "Read squash fields through ctx.cte_refs rather than planner materialization.",
            "Do not reintroduce Python-side fallback for squash compile-time field access.",
        ),
    )
    raise AssertionError("unreachable")


def _require_squash_scalar_field(
    ctx: CompilationContext,
    ref_id: ServerPlanRefId,
) -> SqlRenderable:
    """Resolve a published squash scalar projection."""
    return _require_squash_cte_field(ctx, ref_id, "v")


def _squash_change_type_filter(change_type: str) -> SqlRenderable:
    from impl.common.l2100_sql_grammar.tree.enums import BinaryOp
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlInlineLiteral
    from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp

    return SqlBinaryOp(
        SqlColumnRef(SqlColumnName("change_type")),
        BinaryOp.EQ,
        SqlInlineLiteral(change_type),
    )


def _squash_change_type_count_expr(cte_names: Sequence[str], change_type: str) -> SqlRenderable:
    from impl.common.l2100_sql_grammar.domain.infra.stmt_dml_simple import (
        SqlCountQuery,
        SqlScalarSubquery,
    )
    from impl.common.l2100_sql_grammar.tree.clauses import SqlWhereClause
    from impl.common.l2100_sql_grammar.tree.enums import BinaryOp
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlParam
    from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp

    count_terms: list[SqlRenderable] = [
        SqlScalarSubquery(
            SqlCountQuery(
                table=SqlTableName(cte_name),
                where=SqlWhereClause(_squash_change_type_filter(change_type)),
            ),
        )
        for cte_name in cte_names
    ]
    if not count_terms:
        return SqlParam(0)

    total: SqlRenderable = count_terms[0]
    for term in count_terms[1:]:
        total = SqlBinaryOp(total, BinaryOp.ADD, term)
    return total


