        return True

    def step_tags(self: InsertSquashMergeRevisionStep) -> frozenset[str]:
        return frozenset({"write", "insert", "revision", "squash_merge", "grammar"})

    def tables_read(self: InsertSquashMergeRevisionStep) -> frozenset[str]:
        return frozenset()

    def tables_written(self: InsertSquashMergeRevisionStep) -> frozenset[str]:
        return frozenset({str(self._revision_table), "sys_revision_physical_keys"})

    def dependencies(self: InsertSquashMergeRevisionStep) -> frozenset[str]:
        return frozenset(
            {
                str(self._target_branch_ref_id),
                str(self._target_tip_scalar_ref_id),
                *_ref_dependencies(self._session_id),
                *_ref_dependencies(self._result_revision_id),
            },
        )

    def compile(self: InsertSquashMergeRevisionStep, ctx: CompilationContext) -> CompiledStep[RevisionId]:
        from l1000_schema.schema_def import get_db_column_name
        from l1000_schema.typed_field import SqlCastTargetType
        from l2070_batching.compilation import CompiledStep as _CompiledStep
        from impl.common.l2070_server_plan.steps._compile_server_ref import lower_scalar_source
        from impl.common.l2100_sql_grammar.domain.infra.stmt_compound_write import (
            SqlStatementBatch,
            SqlStatementBatchCategory,
        )
        from impl.common.l2100_sql_grammar.domain.infra.stmt_cte_helpers import (
            SqlInsertFromExpressions,
            SqlSelectExpressions,
        )
        from impl.common.l2100_sql_grammar.domain.versioning.physical_keys import (
            SqlInsertRevisionPhysicalKey,
        )
        from impl.common.l2100_sql_grammar.tree.enums import UnaryOp
        from impl.common.l2100_sql_grammar.tree.expr_compound import SqlCase, SqlCast
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlParam
        from impl.common.l2100_sql_grammar.tree.expr_ops import SqlUnaryOp

        now = datetime.now(UTC)
        tip_expr = _require_squash_scalar_field(ctx, ServerPlanRefId(self._target_tip_scalar_ref_id))
        null_text_expr = SqlCast(SqlParam(None), SqlCastTargetType(base_type="TEXT"))
        parent_type_expr: SqlRenderable = SqlCase(
            whens=[(SqlUnaryOp(UnaryOp.IS_NOT_NULL, tip_expr), SqlParam("squash"))],
            else_=null_text_expr,
        )
        column_names = [
            "sys_id",
            "parent_revision_sys_id",
            "parent_type",
            "timestamp",
            "session_id",
        ]
        exprs: list[SqlRenderable] = [
            lower_scalar_source(self._result_revision_id, ctx, default_field="v"),
            tip_expr,
            parent_type_expr,
            SqlParam(now),
            lower_scalar_source(self._session_id, ctx, default_field="v"),
        ]
        for key, value in self._metadata:
            column_names.append(
                get_db_column_name(self._revision_model_cls, DynamicFieldName(key)) if key in self._revision_model_cls.model_fields else key,
            )
            exprs.append(SqlParam(value))
        grammar = SqlInsertFromExpressions(self._revision_table, column_names, exprs)
        result_revision_id = self._result_revision_id
        physical_key_insert = SqlInsertRevisionPhysicalKey(
            lower_scalar_source(result_revision_id, ctx, default_field="v"),
        )
        if isinstance(result_revision_id, ScalarServerRef):
            result_projection = SqlSelectExpressions(
                [(lower_scalar_source(result_revision_id, ctx, default_field="v"), "v")],
            )
            output_shape = CompiledOutputShape((synthetic_output_field("v"),))
            column_type_hints = _revision_id_type_hints("v")
            return _CompiledStep(
                grammar=SqlStatementBatch(
                    [grammar, physical_key_insert, result_projection],
                    category=SqlStatementBatchCategory.ORDERED_SEMANTIC,
                    needs_returning_per_stmt=[False, False, True],
                    collect_results_per_stmt=[False, False, True],
                ),
                needs_returning=True,
                closed_post_op=scalar_column_post_op(
                    "v",
                    scalar_coercion=ScalarCoercionKind.REVISION_ID,
                ),
                output_shape=output_shape,
                result_relation=DeclaredResultRelation.from_output_shape(output_shape),
                column_type_hints=column_type_hints,
            )

        return _CompiledStep(
            grammar=SqlStatementBatch(
                [
                    grammar,
                    physical_key_insert,
                ],
                category=SqlStatementBatchCategory.ORDERED_SEMANTIC,
                needs_returning_per_stmt=[False, False],
                collect_results_per_stmt=[False, False],
            ),
            needs_returning=False,
            closed_post_op=literal_post_op(result_revision_id),
        )


