def _build_explicit_parent_revision_base_columns(
    *,
    result_revision_id: ScalarServerRef[RevisionId],
    parent_revision_id: ScalarServerRef[RevisionId],
    parent_type: RevisionParentType,
    session_id: ScalarServerRef[SessionId],
    ctx: CompilationContext,
) -> tuple[list[SqlColumnName], list[SqlRenderable]]:
    from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName
    from impl.common.l2070_server_plan.steps._compile_server_ref import lower_scalar_server_ref
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlParam

    now = datetime.now(UTC)
    return (
        [
            SqlColumnName("sys_id"),
            SqlColumnName("parent_revision_sys_id"),
            SqlColumnName("parent_type"),
            SqlColumnName("timestamp"),
            SqlColumnName("session_id"),
        ],
        [
            lower_scalar_server_ref(result_revision_id, ctx),
