            SqlParam(parent_type),
            SqlParam(now),
            lower_scalar_server_ref(session_id, ctx),
        ],
    )


def _append_revision_metadata_columns(
    *,
    column_names: list[SqlColumnName],
    column_values: list[SqlRenderable],
    revision_model_cls: type[BaseRevision],
    metadata: RevisionMetadataItems,
) -> None:
    from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlParam

    for key, value in metadata:
        column_names.append(
            SqlColumnName(
                get_db_column_name(revision_model_cls, DynamicFieldName(key)) if key in revision_model_cls.model_fields else key,
            ),
        )
        column_values.append(SqlParam(value))


