            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        _contract_model_cls = _BaseInsertExplicitParentRevisionStepCteRow
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=tuple(str(column) for column in columns),
            column_type_hints=column_type_hints,
            model_cls=_contract_model_cls,
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    @property
    def level(self: _BaseInsertExplicitParentRevisionStep) -> int:
        return 0

    def result_cardinality(self: _BaseInsertExplicitParentRevisionStep) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self: _BaseInsertExplicitParentRevisionStep) -> bool:
        return False

    def execution_role(self: _BaseInsertExplicitParentRevisionStep) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def step_tags(self: _BaseInsertExplicitParentRevisionStep) -> frozenset[str]:
        return frozenset({"write", "insert", "revision", "squash", "grammar"})

    def tables_read(self: _BaseInsertExplicitParentRevisionStep) -> frozenset[str]:
        return frozenset()

    def _compile_insert(
        self: _BaseInsertExplicitParentRevisionStep,
        *,
        ctx: CompilationContext,
        revision_table: SqlTableName,
        revision_model_cls: type[BaseRevision],
        result_revision_id: ScalarServerRef[RevisionId],
        column_names: list[SqlColumnName],
        column_values: list[SqlRenderable],
    ) -> CompiledStep[RevisionId]:
        del revision_model_cls

        from impl.common.l2070_server_plan.steps._compile_server_ref import lower_scalar_server_ref
        from l2070_batching.compilation import CompiledStep as _CompiledStep
        from impl.common.l2100_sql_grammar.domain.infra.stmt_compound_write import (
            SqlStatementBatch,
            SqlStatementBatchCategory,
        )
        from impl.common.l2100_sql_grammar.domain.infra.stmt_cte_helpers import SqlSelectExpressions
        from impl.common.l2100_sql_grammar.tree.clauses import SqlColumnNameList, SqlValuesClause, SqlValuesRow
        from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
        from impl.common.l2100_sql_grammar.tree.statements import SqlInsert

        grammar = SqlInsert(
            table=SqlTableIdent(revision_table),
            columns=SqlColumnNameList(list(column_names)),
            values=SqlValuesClause([SqlValuesRow(column_values)]),
        )
        result_projection = SqlSelectExpressions(
            [(lower_scalar_server_ref(result_revision_id, ctx), "v")],
        )

        output_shape, result_relation, column_type_hints = _compiled_contract_artifacts(self)
        return _CompiledStep(
            grammar=SqlStatementBatch(
                [grammar, result_projection],
                category=SqlStatementBatchCategory.ORDERED_SEMANTIC,
            ),
            needs_returning=True,
            closed_post_op=scalar_column_post_op(
                "v",
                scalar_coercion=ScalarCoercionKind.REVISION_ID,
            ),
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
        )


