    def supports_sql_batch_transport(self: _ResolveVisibleEmbeddingContentHashStep) -> bool:
        return True

    def dependencies(self: _ResolveVisibleEmbeddingContentHashStep) -> frozenset[str]:
        deps = {self._metadata_ref, *self._after_refs}
        if self._source_ref is not None:
            deps.add(self._source_ref)
        if self._source_rows_ref is not None:
            deps.add(self._source_rows_ref)
