        return frozenset({"read", "embedding", "hash"})

    def cte_relation_role(self: _ResolveVisibleEmbeddingContentHashStep) -> str:
        """Identify the producer-owned embedding hash relation contract."""
        return "embedding_hash"

    def cte_publication_contract(self: _ResolveVisibleEmbeddingContentHashStep) -> CtePublicationContract:
        columns = ("source_object_id", "hash_short", "hash_high")
        column_type_hints = SqlColumnTypeHints(
            bigint_columns=frozenset({"hash_short", "hash_high"}),
            text_columns=frozenset({"source_object_id"}),
        )
        if columns is None:
            if column_type_hints is not None and column_type_hints.has_any():
                msg = f"{type(self).__name__} declares SQL column type hints without an explicit cte_output_columns() contract."
                raise TypeError(msg)
            return CtePublicationContract.non_publishing()
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=tuple(str(column) for column in columns),
            column_type_hints=column_type_hints,
            relation_contract=CteRelationContract.semantic_row(_ResolveVisibleEmbeddingContentHashStepCteRow),
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def compile(
        self: _ResolveVisibleEmbeddingContentHashStep,
        ctx: CompilationContext,
    ) -> CompiledStep[_ResolvedEmbeddingHash | RawResult]:
        return runtime_resolve_visible_embedding_content_hash_compiled_step(
            metadata_ref=self._metadata_ref,
            ctx=ctx,
            source_ref=self._source_ref,
            source_rows_ref=self._source_rows_ref,
            source_id=self._source_id,
            source_obj=self._source_obj,
            source_objs=self._source_objs,
            model_cls=self._model_cls,
            index_name=SqlIndexName(self._index_name),
            step_ref=str(self.ref_id),
            canonical_model_hint=self._canonical_model_hint,
            batch=self._batch,
        )


def _source_presence_ref_from_steps[SourceStepsItemT](
    source_steps: Sequence[ServerPlanStep[SourceStepsItemT]],
    fallback_ref: ServerPlanRefId,
) -> ServerPlanRefId:
    for step in reversed(source_steps):
        if step.always_publishes_executor_visible_binding():
            return step.ref_id
    if source_steps:
        source_ref = source_steps[-1].publication_source_ref()
        if source_ref is not None:
            return source_ref
    return fallback_ref


