    def dependencies(self: _RequireResolvedSourceStep) -> frozenset[str]:
        return frozenset({self._source_ref})

    def tables_read(self: _RequireResolvedSourceStep) -> frozenset[str]:
        return frozenset()

    def tables_written(self: _RequireResolvedSourceStep) -> frozenset[str]:
        return frozenset()

    def step_tags(self: _RequireResolvedSourceStep) -> frozenset[str]:
        return frozenset({"read", "validation"})

    def compile(self: _RequireResolvedSourceStep, ctx: CompilationContext) -> CompiledStep[None]:
        from impl.common.l2050_sql_types.sql_branded_types import SqlAliasName, SqlColumnName, SqlTableName
        from impl.common.l2070_server_plan.steps._runtime_replanning_error import (
            raise_missing_cte_fallback_forbidden,
        )
        from impl.common.l2100_sql_grammar.tree.clauses import SqlSelectAlias, SqlSelectList, SqlWhereClause
        from impl.common.l2100_sql_grammar.tree.enums import BinaryOp
        from impl.common.l2100_sql_grammar.tree.expr_compound import SqlFuncCall, SqlSubquery
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlParam
        from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp
        from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
        from impl.common.l2100_sql_grammar.tree.statements import SqlSelect
        from l2070_batching.post_op import raw_rows_post_op

        source_cte = ctx.cte_refs.get(self._source_ref)
        if not isinstance(source_cte, CteReference):
            raise_missing_cte_fallback_forbidden(
                site_name="_RequireResolvedSourceStep.compile",
                trigger=f"source ref {self._source_ref!r} has no SQL-visible source rowset",
                blocked_path="_RequireResolvedSourceStep cannot validate source presence through Python runtime refs.",
                result_contract="source presence validation must be a SQL NOT EXISTS exception fact.",
                implementation_requirements=(
                    "Publish the source row lookup as a SQL-visible CTE.",
                    "Use terminal Python only to raise when the SQL missing-source relation emits a row.",
                ),
            )
        probe_column = source_cte.columns[0] if source_cte.columns else "sys_id"
        source_count = SqlSelect(
            select=SqlSelectList(
                [SqlFuncCall("COUNT", [SqlColumnRef(SqlColumnName(probe_column))])],
            ),
            from_=SqlTableIdent(SqlTableName(source_cte.ref_id)),
        )
        grammar = SqlSelect(
            select=SqlSelectList(
                [
                    SqlSelectAlias(SqlParam(True), SqlAliasName("missing_source")),
                    SqlSelectAlias(SqlSubquery(source_count), SqlAliasName("actual_count")),
                ],
            ),
            where=SqlWhereClause(
                SqlBinaryOp(
                    SqlSubquery(source_count),
                    BinaryOp.NE,
                    SqlParam(self._expected_count),
                ),
            ),
        )
        __opa002_grammar_365 = grammar
        output_shape = CompiledOutputShape(
            (
                synthetic_output_field("missing_source"),
                synthetic_output_field("actual_count"),
            ),
        )
        column_type_hints = SqlColumnTypeHints(
            bool_columns=frozenset({"missing_source"}),
            bigint_columns=frozenset({"actual_count"}),
        )
        column_type_hints.require_complete(output_shape.cte_output_columns)
        return CompiledStep(
            output_shape=output_shape,
            result_relation=DeclaredResultRelation.from_output_shape(output_shape),
            column_type_hints=column_type_hints,
            grammar=__opa002_grammar_365,
            needs_returning=True,
            closed_post_op=embedding_require_no_rows_post_op(
                message=self._error_message,
                expected_count=self._expected_count,
                actual_count_column="actual_count",
            ),
            auxiliary_ctes=[(source_cte.ref_id, source_cte.auxiliary_query)] if source_cte.auxiliary_query is not None else None,
            allow_empty_provenance_manifest=True,
        )


def _require_available_vector_backend_kind(
    ctx: LoweringContext,
    backend_kind: VectorBackendKind,
    *,
    index_name: VectorIndexName,
) -> VectorBackendKind:
    if backend_kind is not VectorBackendKind.USEARCH:
        return backend_kind
    from l5200_vector_index.index_implementations import usearch_index as usearch_backend

    if usearch_backend.USEARCH_AVAILABLE:
        return VectorBackendKind.USEARCH
    raise VectorIndexImplementationUnavailableError(
        operation=VectorIndexOperation.MAINTENANCE,
        table_name=VectorIndexTableName("registered_vector_model"),
        index_name=index_name,
        requested=VectorIndexImplementation.USEARCH,
        backend_type=ctx.backend_type,
        reason=VectorImplementationFailureReason("the USearch adapter is unavailable"),
        remediation=VectorImplementationRemediation("Install the 'usearch' package before maintenance"),
    )


def _resolve_vector_backend_kind(
    ctx: LoweringContext,
    *,
    backend_kind_override: str | None,
) -> VectorBackendKind:
    if backend_kind_override is not None:
        return _require_available_vector_backend_kind(
            ctx,
            VectorBackendKind(backend_kind_override),
            index_name=VectorIndexName("vector_index"),
        )
    return _resolve_backend_kind_for_vector_maintenance(ctx)


def _resolve_vector_backend_kind_for_config(
    ctx: LoweringContext,
    config: VectorIndexConfig,
    *,
    backend_kind_override: str | None,
) -> VectorBackendKind:
    if backend_kind_override is not None:
        return _require_available_vector_backend_kind(
            ctx,
            VectorBackendKind(backend_kind_override),
            index_name=VectorIndexName(config.index_name),
        )
    requested = config.resolved_index_policy.requested_implementation
    if requested is VectorIndexImplementation.USEARCH:
        return _require_available_vector_backend_kind(
            ctx,
            VectorBackendKind.USEARCH,
            index_name=VectorIndexName(config.index_name),
        )
    if requested is VectorIndexImplementation.SQL_TABLE_HNSW:
        return VectorBackendKind.SQL_TABLE_HNSW
    return _resolve_backend_kind_for_vector_maintenance(ctx, config)


def _first_compiled_row(
    compiled: CompiledStep[list[object]],
    *,
    publication_ref_id: ServerPlanRefId,
    publication_contract: CtePublicationContract,
    model_cls: type[DatabaseObjectRow[Any]],
    post_write_select: SqlRenderable | None,
    empty_message: str,
    output_shape: Any | None = None,
    column_type_hints: SqlColumnTypeHints | None = None,
) -> CompiledStep[object]:
    sql_ir = _require_compiled_embedding_sql_ir(compiled)
    closed_post_op = embedding_first_hydrated_row_post_op(
        model_cls=model_cls,
        empty_message=empty_message,
    )
    grammar = sql_ir.grammar
    params = sql_ir.params
    needs_returning = sql_ir.needs_returning
    external_params_first = sql_ir.external_params_first
    repeatable_publication_query = _require_embedding_post_write_select(post_write_select)
    if not sql_ir.needs_returning:
        post_write_select = repeatable_publication_query
        from impl.common.l2100_sql_grammar.domain.infra.stmt_compound_write import (
            SqlStatementBatch,
            SqlStatementBatchCategory,
        )

        grammar = SqlStatementBatch(
            [sql_ir.grammar, post_write_select],
            category=SqlStatementBatchCategory.ORDERED_SEMANTIC,
            params_per_stmt=[sql_ir.params, None],
            external_params_first=[sql_ir.external_params_first, False],
            needs_returning_per_stmt=[False, True],
            collect_results_per_stmt=[False, True],
        )
        params = None
        needs_returning = True
        external_params_first = False
    __opa002_grammar_430 = grammar
    if output_shape is None:
        msg = "_first_compiled_row requires an explicit output shape from the caller contract."
        # First-row helpers preserve caller-owned output contracts.
        raise ProgrammingError(msg)
    if column_type_hints is None:
        msg = "_first_compiled_row requires explicit column type hints from the caller contract."
        # First-row helpers preserve caller-owned output contracts.
        raise ProgrammingError(msg)
    from l2070_batching.compilation import compiled_sql_publication_from_query

    return CompiledStep(
        output_shape=output_shape,
        grammar=__opa002_grammar_430,
        params=params,
        needs_returning=needs_returning,
        result_relation=DeclaredResultRelation.from_output_shape(output_shape),
        column_type_hints=column_type_hints,
        external_params_first=external_params_first,
        provenance_manifest=sql_ir.provenance_manifest,
        allow_empty_provenance_manifest=sql_ir.allow_empty_provenance_manifest,
        use_savepoint_recovery=sql_ir.use_savepoint_recovery,
        closed_post_op=closed_post_op,
        lifecycle_effects=compiled.lifecycle_effects,
        compiled_sql_publication=compiled_sql_publication_from_query(
            ref_id=publication_ref_id,
            query=repeatable_publication_query,
            contract=publication_contract,
        ),
    )


def _output_shape_from_cte_contract(contract: CtePublicationContract) -> Any:
