def _embedding_metadata_post_write_select(
    instance: EmbeddingMetadata,
    *,
    columns: tuple[str, ...],
) -> SqlRenderable:
    from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName
    from impl.common.l2100_sql_grammar.builders import and_, col, eq, val
    from impl.common.l2100_sql_grammar.tree.clauses import SqlSelectList, SqlWhereClause
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef
    from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
    from impl.common.l2100_sql_grammar.tree.statements import SqlSelect
    from l1000_schema.table_utils import get_table_name
    from l5200_vector_index.embedding_metadata import EmbeddingMetadata

    return SqlSelect(
        select=SqlSelectList([SqlColumnRef(SqlColumnName(column)) for column in columns]),
        from_=SqlTableIdent(get_table_name(EmbeddingMetadata)),
        where=SqlWhereClause(
            and_(
                eq(col("table_name"), val(instance.table_name)),
                eq(col("field_name"), val(instance.field_name)),
            ),
        ),
        limit=1,
    )


