def _validate_whole_document_batch_writes(
    writes: Sequence[_RequestedWholeDocumentEmbeddingWrite | _VisibleWholeDocumentEmbeddingWrite],
) -> _WholeDocumentBatchShape:
    first_write = writes[0]
    dimensions = first_write.prepared.dimensions
    for write in writes:
        if write.target.table_name != first_write.target.table_name or write.target.index_name != first_write.target.index_name:
            msg = (
                "SetEmbeddingManyIntent requires a single source table and index per batch: "
                f"expected {first_write.target.table_name}.{first_write.target.index_name}, "
                f"got {write.target.table_name}.{write.target.index_name}"
            )
            raise ValueError(msg)
        if str(write.prepared.model_id) != str(first_write.prepared.model_id):
            msg = (
                f"Inconsistent whole-document embedding model ids for "
                f"{write.target.model_cls.__name__}.{write.target.index_name}: "
                f"expected {first_write.prepared.model_id}, got {write.prepared.model_id}"
            )
            raise ValueError(msg)
        if write.prepared.dimensions != dimensions:
            msg = (
                f"Inconsistent whole-document embedding dimensions for "
                f"{write.target.model_cls.__name__}.{write.target.index_name}: "
                f"expected {dimensions}, got {write.prepared.dimensions}"
            )
            raise ValueError(msg)
    return _WholeDocumentBatchShape(
        target=first_write.target,
        model_id=first_write.prepared.model_id,
        dimensions=dimensions,
    )


def _whole_document_batch_group_key(
    write: _RequestedWholeDocumentEmbeddingWrite | _VisibleWholeDocumentEmbeddingWrite,
) -> tuple[str, int]:
    return _prepared_embedding_group_key(write.prepared)


def _chunk_whole_document_batch_writes[
    T: _RequestedWholeDocumentEmbeddingWrite | _VisibleWholeDocumentEmbeddingWrite,
](
    writes: Sequence[T],
    *,
    bulk_transport: DmlBulkTransport,
) -> list[Sequence[T]]:
    """Split embedding batches before backend parameter limits are reached."""
    if bulk_transport is not DmlBulkTransport.PAYLOAD_AWARE_BOUND_VALUES:
        return [writes]
    parameter_budget = _POSTGRES_BIND_PARAMETER_LIMIT // _EMBEDDING_BATCH_PARAMETER_HEADROOM
    max_writes_per_chunk = max(1, parameter_budget // _ESTIMATED_PARAMS_PER_EMBEDDING_WRITE)
    if len(writes) <= max_writes_per_chunk:
        return [writes]
    return [writes[start : start + max_writes_per_chunk] for start in range(0, len(writes), max_writes_per_chunk)]


def _prepared_embedding_group_key(prepared: _PreparedEmbeddingValue) -> tuple[str, int]:
    return (prepared.model_id, prepared.dimensions)


def _embedding_vector_conflicts(
    existing: EmbeddingVector,
    prepared: _PreparedEmbeddingValue,
) -> bool:
    dimensions = existing["dimensions"] if isinstance(existing, dict) else existing.dimensions
    precision = existing["embedding_precision"] if isinstance(existing, dict) else existing.embedding_precision
    embedding = existing["embedding"] if isinstance(existing, dict) else existing.embedding
    embedding_binary = existing["embedding_binary"] if isinstance(existing, dict) else existing.embedding_binary
    embedding_binary_representation_id = (
        existing["embedding_binary_representation_id"] if isinstance(existing, dict) else existing.embedding_binary_representation_id
    )
    embedding_binary_projection_ref_id = (
        existing["embedding_binary_projection_ref_id"] if isinstance(existing, dict) else existing.embedding_binary_projection_ref_id
    )
    embedding_binary_dimensions = (
        existing["embedding_binary_dimensions"] if isinstance(existing, dict) else existing.embedding_binary_dimensions
    )
    changed: bool = (
        dimensions != prepared.dimensions
        or precision != prepared.precision
        or embedding != prepared.serialized_embedding
        or embedding_binary != prepared.embedding_binary
        or embedding_binary_representation_id != prepared.embedding_binary_representation_id
        or embedding_binary_projection_ref_id != prepared.embedding_binary_projection_ref_id
        or embedding_binary_dimensions != prepared.embedding_binary_dimensions
    )
    return changed


def _require_embedding_hash_payload_join_mode(
    hash_cte: CteReference,
    *,
    hash_ref: ServerPlanRefId,
    payload_count: int,
    model_id: EmbeddingModelCanonicalId | None,
    index_name: SqlIndexName,
    source_ids: tuple[SysId | None, ...],
) -> Literal["keyed", "unkeyed"]:
    """Validate the producer-owned cardinality contract for a hash-payload join."""
    if "source_object_id" in hash_cte.columns:
        return "keyed"
    context = f"model={model_id!r}, index={index_name!r}, hash_ref={hash_ref!r}, source_ids={source_ids!r}"
    if payload_count != 1:
        msg = f"Unkeyed embedding hash relation has {payload_count} payload rows; expected 1 ({context})"
        raise ValueError(msg)
    if hash_cte.relation_role != "embedding_hash" or hash_cte.columns != ("hash_short", "hash_high"):
        msg = (
            "Unkeyed embedding hash relation does not prove one-row cardinality through "
            f"the embedding_hash producer contract ({context}, relation_role={hash_cte.relation_role!r}, "
            f"columns={hash_cte.columns!r})"
        )
        raise ValueError(msg)
    return "unkeyed"


def _conflicting_embedding_vectors_error(model_id: str) -> ValueError:
    return ValueError(
        f"Conflicting embedding vectors resolved to the same content hash for model {model_id}",
    )


def _embedding_vector_upsert_where() -> Expression[bool, EmbeddingVector]:
    from l1000_schema.typed_field import EXCLUDED, field
    from l5200_vector_index.content_addressable_models import EmbeddingVector

    return (
        (field(EmbeddingVector.dimensions) == EXCLUDED(field(EmbeddingVector.dimensions)))
        & (field(EmbeddingVector.embedding_precision) == EXCLUDED(field(EmbeddingVector.embedding_precision)))
        & (field(EmbeddingVector.embedding) == EXCLUDED(field(EmbeddingVector.embedding)))
    )


def _embedding_vector_upsert_where_for_ctx(
    ctx: CompilationContext,
) -> Expression[bool, EmbeddingVector] | None:
    del ctx
    return None


def _compile_embedding_vector_instances_relation(
    *,
    ctx: CompilationContext,
    writes: Sequence[_PendingWholeDocumentEmbeddingVectorWrite],
) -> CompiledStep[list[dict[str, object]]]:
    from impl.common.l2050_sql_types.sql_branded_types import SqlAliasName, SqlColumnName, SqlTableName
    from impl.common.l2070_server_plan.steps._runtime_replanning_error import (
        raise_missing_cte_fallback_forbidden,
    )
    from impl.common.l2100_sql_grammar.domain.infra.expr_primitives import SqlGeneratedSysId
    from impl.common.l2100_sql_grammar.domain.infra.stmt_cte_helpers import SqlRequestInputRowsQuery
    from impl.common.l2100_sql_grammar.domain.versioning.stmt_cte import SqlUnionAll
    from impl.common.l2100_sql_grammar.tree.clauses import (
        SqlJoin,
        SqlSelectAlias,
        SqlSelectList,
        SqlSubqueryTableRef,
        SqlTableAlias,
        SqlWhereClause,
    )
    from impl.common.l2100_sql_grammar._expressions_all import NULL
    from impl.common.l2100_sql_grammar.tree.expr_compound import SqlCast, SqlFuncCall
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlParam
    from impl.common.l2100_sql_grammar.tree.enums import BinaryOp, JoinKind
    from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp
    from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
    from impl.common.l2100_sql_grammar.tree.statements import SqlSelect
    from l1000_schema.column_utils import get_db_column_name
    from l1000_schema.typed_field import SqlCastTargetType
    from l2070_batching.post_op import raw_rows_post_op
    from l5200_vector_index.content_addressable_models import EmbeddingVector

    field_columns = {
        field_name: get_db_column_name(EmbeddingVector, DynamicFieldName(field_name)) for field_name in EmbeddingVector.model_fields
    }
    short_col = field_columns["content_hash_short"]
    high_col = field_columns["content_hash_high"]
    model_ref_id_col = field_columns["model_ref_id"]
    model_id_col = field_columns["model_id"]
    dimensions_col = field_columns["dimensions"]
    embedding_col = field_columns["embedding"]
    embedding_binary_col = field_columns["embedding_binary"]
    embedding_binary_representation_id_col = field_columns["embedding_binary_representation_id"]
    embedding_binary_projection_ref_id_col = field_columns["embedding_binary_projection_ref_id"]
    embedding_binary_dimensions_col = field_columns["embedding_binary_dimensions"]
    precision_col = field_columns["embedding_precision"]
    created_at_col = field_columns["created_at"]
    updated_at_col = field_columns["updated_at"]
    sys_id_col = field_columns["sys_id"]
    column_type_hints = _embedding_vector_materialized_column_type_hints()
    model_ref_id_cast_type: Literal["UUID"] = "UUID"

    if not writes:
        output_shape = _output_shape_from_columns_and_hints(_embedding_vector_materialized_columns(), column_type_hints)
        null_select = SqlSelect(
            select=SqlSelectList(
                [
                    SqlSelectAlias(SqlCast(NULL, SqlCastTargetType(base_type="TEXT")), SqlAliasName(sys_id_col)),
                    SqlSelectAlias(SqlCast(NULL, SqlCastTargetType(base_type="BIGINT")), SqlAliasName(short_col)),
                    SqlSelectAlias(SqlCast(NULL, SqlCastTargetType(base_type="BIGINT")), SqlAliasName(high_col)),
                    SqlSelectAlias(
                        SqlCast(NULL, SqlCastTargetType(base_type=model_ref_id_cast_type)),
                        SqlAliasName(model_ref_id_col),
                    ),
                    SqlSelectAlias(SqlCast(NULL, SqlCastTargetType(base_type="TEXT")), SqlAliasName(model_id_col)),
                    SqlSelectAlias(SqlCast(NULL, SqlCastTargetType(base_type="INTEGER")), SqlAliasName(dimensions_col)),
                    SqlSelectAlias(
                        SqlCast(NULL, SqlCastTargetType(base_type="BLOB")),
                        SqlAliasName(embedding_col),
                    ),
                    SqlSelectAlias(
                        SqlCast(NULL, SqlCastTargetType(base_type="BLOB")),
                        SqlAliasName(embedding_binary_col),
                    ),
                    SqlSelectAlias(
                        SqlCast(NULL, SqlCastTargetType(base_type="TEXT")),
                        SqlAliasName(embedding_binary_representation_id_col),
                    ),
                    SqlSelectAlias(
                        SqlCast(NULL, SqlCastTargetType(base_type="TEXT")),
                        SqlAliasName(embedding_binary_projection_ref_id_col),
                    ),
                    SqlSelectAlias(
                        SqlCast(NULL, SqlCastTargetType(base_type="INTEGER")),
                        SqlAliasName(embedding_binary_dimensions_col),
                    ),
                    SqlSelectAlias(SqlCast(NULL, SqlCastTargetType(base_type="TEXT")), SqlAliasName(precision_col)),
                    SqlSelectAlias(SqlFuncCall("CURRENT_TIMESTAMP", []), SqlAliasName(created_at_col)),
                    SqlSelectAlias(SqlFuncCall("CURRENT_TIMESTAMP", []), SqlAliasName(updated_at_col)),
                ],
            ),
            where=SqlWhereClause(SqlParam(False)),
        )
        __opa002_grammar_1108 = null_select
        return CompiledStep(
            output_shape=output_shape,
            grammar=__opa002_grammar_1108,
            needs_returning=True,
            result_relation=DeclaredResultRelation.from_output_shape(output_shape),
            closed_post_op=raw_rows_post_op(),
            column_type_hints=column_type_hints,
        )

    payload_columns = (
        "source_object_id",
        model_ref_id_col,
        model_id_col,
        dimensions_col,
        embedding_col,
        embedding_binary_col,
        embedding_binary_representation_id_col,
        embedding_binary_projection_ref_id_col,
        embedding_binary_dimensions_col,
        precision_col,
    )
    payload_hints = SqlColumnTypeHints(
        uuid_columns=frozenset({model_ref_id_col}),
        integer_columns=frozenset({dimensions_col, embedding_binary_dimensions_col}),
        bytea_columns=frozenset({embedding_col, embedding_binary_col}),
        text_columns=frozenset(
            {
                model_id_col,
                embedding_binary_representation_id_col,
                embedding_binary_projection_ref_id_col,
                precision_col,
                "source_object_id",
            },
        ),
    ).require_complete(payload_columns)
    writes_by_hash_ref: dict[ServerPlanRefId, list[_PendingWholeDocumentEmbeddingVectorWrite]] = {}
    for write in writes:
        writes_by_hash_ref.setdefault(write.hash_ref, []).append(write)

    hash_ctes: list[CteReference] = []
    payload_ctes: list[tuple[str, SqlRenderable]] = []
    raw_selects: list[SqlSelect] = []
    for index, (hash_ref_id, grouped_writes) in enumerate(writes_by_hash_ref.items()):
        hash_ref = str(hash_ref_id)
        hash_cte = ctx.cte_refs.get(hash_ref)
        if not isinstance(hash_cte, CteReference):
            raise_missing_cte_fallback_forbidden(
                site_name="_MaterializeEmbeddingVectorInstancesStep.compile",
                trigger=f"hash ref {hash_ref!r} has no SQL-visible hash rowset",
                blocked_path=("_MaterializeEmbeddingVectorInstancesStep cannot build vector rows from Python hash runtime refs."),
                result_contract=(
                    "embedding vector instance rows must compile from SQL hash facts and literal prepared embedding payloads."
                ),
                implementation_requirements=(
                    "Ensure each hash-producing step publishes hash_short and hash_high as SQL-visible columns.",
                    "Keep vector row construction as a SQL relation consumed by validation and upsert steps.",
                ),
            )
        hash_ctes.append(hash_cte)
        hash_alias = SqlAliasName(f"vector_hash_{index}")
        payload_alias = SqlAliasName(f"vector_payload_{index}")
        payload_rows: list[_EmbeddingVectorPayloadRow] = [
            {
                "source_object_id": write.source_id,
                model_ref_id_col: write.prepared.model_ref_id,
                model_id_col: write.prepared.model_id,
                dimensions_col: write.prepared.dimensions,
                embedding_col: write.prepared.serialized_embedding,
                embedding_binary_col: write.prepared.embedding_binary,
                embedding_binary_representation_id_col: write.prepared.embedding_binary_representation_id,
                embedding_binary_projection_ref_id_col: write.prepared.embedding_binary_projection_ref_id,
                embedding_binary_dimensions_col: write.prepared.embedding_binary_dimensions,
                precision_col: write.prepared.precision,
            }
            for write in grouped_writes
        ]
        payload_cte_name = f"{hash_cte.ref_id}_vector_payload_{index}"
        hash_from = SqlTableAlias(SqlTableIdent(SqlTableName(hash_cte.ref_id)), hash_alias)
        payload_relation = SqlRequestInputRowsQuery(
            columns=payload_columns,
            rows=payload_rows,
            type_hints=payload_hints,
        )
        payload_source_id = SqlColumnRef(SqlColumnName("source_object_id"), qualifier=payload_alias)
        payload_expressions = [SqlColumnRef(SqlColumnName(column), qualifier=payload_alias) for column in payload_columns[1:]]
        source_ids = tuple(write.source_id for write in grouped_writes)
        if any(source_id is None for source_id in source_ids) and not all(source_id is None for source_id in source_ids):
            first_write = grouped_writes[0]
            msg = (
                "Embedding vector payloads cannot mix keyed and unkeyed hash rows "
                f"(model={first_write.prepared.model_id!r}, index={first_write.index_name!r}, "
                f"hash_ref={hash_ref_id!r}, source_ids={source_ids!r})"
            )
            raise ValueError(msg)
        first_write = grouped_writes[0]
        join_mode = _require_embedding_hash_payload_join_mode(
            hash_cte,
            hash_ref=hash_ref_id,
            payload_count=len(grouped_writes),
            model_id=first_write.prepared.model_id,
            index_name=first_write.index_name,
            source_ids=source_ids,
        )
        if join_mode == "keyed":
            hash_source_id = SqlColumnRef(SqlColumnName("source_object_id"), qualifier=hash_alias)
            join_condition: SqlRenderable = SqlBinaryOp(hash_source_id, BinaryOp.EQ, payload_source_id)
        else:
            join_condition = SqlParam(True)
        payload_ctes.append((payload_cte_name, payload_relation))
        raw_selects.append(
            SqlSelect(
                select=SqlSelectList(
                    [
                        SqlSelectAlias(SqlColumnRef(SqlColumnName("hash_short"), qualifier=hash_alias), SqlAliasName(short_col)),
                        SqlSelectAlias(SqlColumnRef(SqlColumnName("hash_high"), qualifier=hash_alias), SqlAliasName(high_col)),
                        *[
                            SqlSelectAlias(expression, SqlAliasName(column))
                            for column, expression in zip(payload_columns[1:], payload_expressions, strict=True)
                        ],
                    ],
                ),
                from_=hash_from,
                joins=[
                    SqlJoin(
                        join_type=JoinKind.INNER,
                        table=SqlTableAlias(SqlTableIdent(SqlTableName(payload_cte_name)), payload_alias),
                        condition=join_condition,
                    ),
                ],
            ),
        )

    raw_rows: SqlRenderable = raw_selects[0] if len(raw_selects) == 1 else SqlUnionAll(raw_selects)
    raw_alias = SqlTableName("raw_embedding_vectors")
    distinct_rows = SqlSelect(
        select=SqlSelectList(
            [
                SqlSelectAlias(SqlColumnRef(SqlColumnName(short_col), qualifier=raw_alias), SqlAliasName(short_col)),
                SqlSelectAlias(SqlColumnRef(SqlColumnName(high_col), qualifier=raw_alias), SqlAliasName(high_col)),
                SqlSelectAlias(
                    SqlColumnRef(SqlColumnName(model_ref_id_col), qualifier=raw_alias),
                    SqlAliasName(model_ref_id_col),
                ),
                SqlSelectAlias(
                    SqlColumnRef(SqlColumnName(model_id_col), qualifier=raw_alias),
                    SqlAliasName(model_id_col),
                ),
                SqlSelectAlias(
                    SqlColumnRef(SqlColumnName(dimensions_col), qualifier=raw_alias),
