class SetEmbeddingManyIntent(IntentStep[None]):
    """Batch embedding writes.

    Public callers still pass ``model_cls`` / ``index`` / ``EmbeddingWriteInput`` values.
    Internal callers may pass pre-validated visible-source writes directly as the
    second positional argument to use the batch lowering path.
    """

    intent_tags = frozenset({"write", "embedding", "intent"})
    intent_cardinality = Cardinality.NONE

    def __init__(
        self: SetEmbeddingManyIntent,
        ref_id: ServerPlanRefId,
        config: ScalarServerRef[_SetEmbeddingManyIntentConfig],
    ) -> None:
        super().__init__(ref_id)
        self._config = _require_seeded_config(config, type(self).__name__)

    def lower(self: SetEmbeddingManyIntent, ctx: LoweringContext) -> Sequence[ServerPlanStep[Any]]:
        from impl.common.l2060_query_spec.query_spec import QueryPermissionState
        from impl.common.l2070_server_plan.steps.query_execute import (
            QueryExecuteStep,
            _QueryExecuteStepConfig,
        )
        from impl.common.l2070_server_plan.steps.versioned_query_steps import (
            VersionedQueryFromSpecStep,
            _VersionedQueryFromSpecConfig,
        )
        from l1000_schema.large_column import get_large_column_configs, large_column_pointer_name
        from l1000_schema.typed_field import field
        from l7000_versioned_schema.versioned_schema import VersionedObjectRow

        config = self._config
        if not config.writes:
            return [BarrierStep(_plan_ref(self.ref_id), depends_on=frozenset())]

        source_rows_ref = f"{self.ref_id}.source_rows"
        object_ids = tuple(write.object_id for write in config.writes)
        requested_writes = tuple(
            _RequestedWholeDocumentEmbeddingWrite(
                target=_require_embedding_target(config.model_cls, write.object_id, SqlIndexName(config.index)),
                prepared=_prepare_embedding_value(
                    config.model_cls,
                    write.object_id,
                    SqlIndexName(config.index),
                    write.embedding,
                    write.model_id,
                    projected_embeddings=write.projected_embeddings,
                    serialized_dimensions=write.dimensions,
                    serialized_precision=write.precision,
                ),
            )
            for write in config.writes
        )
        grouped_writes: dict[tuple[str, int], list[_RequestedWholeDocumentEmbeddingWrite]] = {}
        for write in requested_writes:
            grouped_writes.setdefault(_whole_document_batch_group_key(write), []).append(write)
        batch_groups = [
            chunk
            for group_writes in grouped_writes.values()
            for chunk in _chunk_whole_document_batch_writes(
                group_writes,
                bulk_transport=ctx.backend_profile.traits.dml_bulk_transport,
            )
        ]

        source_query_spec = _query_spec(
            config.model_cls,
            field("sys_id").is_in(tuple([object_id.unwrap_to_str() for object_id in object_ids])),
        )
        embedding_source_fields = get_embedding_source_fields(config.model_cls, config.index)
        large_column_pointers = (
            large_column_pointer_name(ContentColumnName(large_column.column))
            for large_column in get_large_column_configs(config.model_cls)
            if large_column.column in embedding_source_fields
        )
        source_columns = tuple(
            dict.fromkeys(("sys_id", *embedding_source_fields, *large_column_pointers)),
        )
        source_query_spec = replace(source_query_spec, select_columns=list(source_columns))
        if config.permission_grammar is not None:
            source_query_spec = replace(
                source_query_spec,
                permission_grammar=config.permission_grammar,
                permission_state=QueryPermissionState.ATTACHED,
            )
        source_rows_step: ServerPlanStep[Any]
        branch_resolution_steps: list[ServerPlanStep[Any]] = []
        effective_scope_branch: _EmbeddingScopeValue = None
        effective_scope_revision: _EmbeddingScopeValue = None
        if issubclass(config.model_cls, VersionedObjectRow):
            if not ctx.is_versioned or not ctx.is_write_transaction:
                msg = (
                    "Versioned embedding write lowered with invalid context: "
                    f"ctx.is_versioned={ctx.is_versioned!r} "
                    f"ctx.is_write_transaction={ctx.is_write_transaction!r} "
                    f"ctx.branch_id={ctx.branch_id!r} "
                    f"ctx.lazy_branch={ctx.lazy_branch!r} "
                    f"ctx.revision_id={ctx.revision_id!r} "
                    f"txn={ctx.executor_txn_handle!r}"
                )
                raise AssertionError(msg)
            lazy_branch_ref_id = getattr(ctx.lazy_branch, "ref_id", None)
            branch_id = _branch_scope_value_for_context(ctx)
            branch_ref_id: ServerPlanRefId | None = None
            if lazy_branch_ref_id is not None and str(lazy_branch_ref_id):
                branch_ref_id = ServerPlanRefId(lazy_branch_ref_id)
            elif branch_id is None:
                if ctx.lazy_revision is None or ctx.branch_table is None:
                    msg = (
                        "Versioned embedding write lost branch scope: "
                        f"ctx.branch_id={ctx.branch_id!r} "
                        f"ctx.lazy_branch={ctx.lazy_branch!r} "
                        f"executor_branch_anchor={getattr(ctx.executor_txn_handle, 'branch_anchor', None)!r} "
                        f"ctx.lazy_revision={ctx.lazy_revision!r} "
                        f"ctx.branch_table={ctx.branch_table!r}"
                    )
                    raise AssertionError(msg)
                resolve_ref, resolve_step = ctx.get_or_create_branch_resolve(str(self.ref_id))
                branch_ref_id = ServerPlanRefId(resolve_ref)
                if resolve_step is not None:
                    branch_resolution_steps.append(resolve_step)
            branch_id_literal = branch_id if isinstance(branch_id, str) else None
            source_rows_step = VersionedQueryFromSpecStep(
                ServerPlanRefId(source_rows_ref),
                config.model_cls,
                _VersionedQueryFromSpecConfig(
                    query_spec=source_query_spec,
                    branch_id=branch_id_literal,
                    branch_ref_id=branch_ref_id,
                    raw_mode=True,
                    # The policy is an ordered executor dependency, not source-query data.
                    # See ``OrderedEffect`` in docs/design/SERVERPLAN_GENERIC_TARGET_ARCHITECTURE.md.
                    after_refs=(
                        ctx.lazy_branch_tip_materialization.dependencies()
                        if ctx.lazy_branch_tip_materialization is not None
                        else frozenset()
                    ),
                    always_publish_executor_binding=False,
                    publication_read_flavor=READ_FLAVOR_QUERY_ROWS,
                ),
            )
            if branch_id is not None:
                effective_scope_branch = branch_id
            elif branch_ref_id is not None:
                effective_scope_branch = ServerRefs.from_ref_id(
                    branch_ref_id,
                    variant="scalar",
                    type_hint=BranchId,
                )
            elif not (ctx.is_versioned and ctx.is_write_transaction):
                effective_scope_revision = _revision_scope_value_for_context(ctx)
            if effective_scope_branch is None and effective_scope_revision is None:
                msg = (
                    "Versioned embedding write lost scope context: "
                    f"ctx.branch_id={ctx.branch_id!r} "
                    f"ctx.lazy_branch={ctx.lazy_branch!r} "
                    f"executor_branch_anchor={getattr(ctx.executor_txn_handle, 'branch_anchor', None)!r} "
                    f"ctx.revision_id={ctx.revision_id!r} "
                    f"ctx.lazy_revision={ctx.lazy_revision!r}"
                )
                raise AssertionError(msg)
        else:
            source_rows_step = QueryExecuteStep(
                ServerPlanRefId(source_rows_ref),
                config.model_cls,
                _QueryExecuteStepConfig(
                    query_spec=source_query_spec,
                    raw_mode=True,
                    always_publish_executor_binding=True,
                ),
            )
        source_validate_ref = f"{self.ref_id}.source_validate"
        steps: list[ServerPlanStep[Any]] = [
            *branch_resolution_steps,
            source_rows_step,
        ]
        after_refs: set[str] = set()
        previous_group_ref: ServerPlanRefId | None = None
        for index, batch_writes in enumerate(batch_groups):
            child_ref = f"{self.ref_id}.group_{index}"
            shape = _validate_whole_document_batch_writes(batch_writes)
            metadata_ref = f"{child_ref}.metadata"
            group_after_refs = frozenset() if previous_group_ref is None else frozenset({previous_group_ref})
            metadata_refs, metadata_steps = _get_or_create_metadata_bootstrap_steps(
                ctx,
                ref_prefix=metadata_ref,
                target=shape.target,
                model_id=shape.model_id,
                dimensions=shape.dimensions,
            )
            from l5200_vector_index.content_addressable_models import (
                get_embedding_classes_for_strategy,
            )

            vector_config = _require_vector_config(
                shape.target.model_cls,
                SqlIndexName(shape.target.index_name),
            )
            vector_model_cls, ref_model_cls = get_embedding_classes_for_strategy(
                vector_config.content_store_strategy,
                model_id=shape.model_id,
                source_table_name=shape.target.table_name,
                field_name=shape.target.index_name,
            )
            vector_ref = f"{child_ref}.vectors"
            replace_ref = f"{child_ref}.replace_refs"
            maintenance_ref = f"{child_ref}.maintenance"
            hash_ref = f"{child_ref}.hashes"
            hash_steps = [
                _ResolveVisibleEmbeddingContentHashStep(
                    ServerPlanRefId(hash_ref),
                    config=_ResolveVisibleEmbeddingContentHashConfig(
                        model_cls=shape.target.model_cls,
                        index_name=shape.target.index_name,
                        source_rows_ref=ServerPlanRefId(source_rows_ref),
                        metadata_ref=metadata_refs.metadata_ref,
                        canonical_model_hint=shape.model_id,
                        batch=True,
                        after_refs=frozenset({metadata_refs.establish_ref, *group_after_refs}),
                    ),
                ),
            ]
            vector_writes: list[_PendingWholeDocumentEmbeddingVectorWrite] = []
            ref_writes: list[_PendingWholeDocumentEmbeddingRefWrite] = []
            maintenance_targets: list[_EmbeddingWriteTarget] = []
            for write in batch_writes:
                source_id = _require_concrete_target_object_id(write.target)
                vector_writes.append(
                    _PendingWholeDocumentEmbeddingVectorWrite(
                        hash_ref=ServerPlanRefId(hash_ref),
                        prepared=write.prepared,
                        index_name=SqlIndexName(write.target.index_name),
                        source_id=source_id,
                    ),
                )
                ref_writes.append(
                    _PendingWholeDocumentEmbeddingRefWrite(
                        scope=_embedding_ref_scope_for_context(
                            ctx=ctx,
                            target=write.target,
                            branch_id=effective_scope_branch,
                            revision_id=effective_scope_revision,
                        ),
                        hash_ref=ServerPlanRefId(hash_ref),
                    ),
                )
                maintenance_targets.append(write.target)
            steps.extend(metadata_steps)
            steps.extend(hash_steps)
            if previous_group_ref is None:
                steps.append(
                    _RequireResolvedSourceStep(
                        ServerPlanRefId(source_validate_ref),
                        config=_RequireResolvedSourceConfig(
                            source_ref=ServerPlanRefId(source_rows_ref),
                            error_message=(
                                f"Embedding sources not found or not visible for "
                                f"{config.model_cls.__name__}.{config.index}; "
                                f"requested_ids={sorted(str(object_id) for object_id in set(object_ids))}"
                            ),
                            expected_count=len(set(object_ids)),
                        ),
                    ),
                )
            steps.append(
                _UpsertManyEmbeddingVectorsStep(
                    ServerPlanRefId(vector_ref),
                    config=_UpsertManyEmbeddingVectorsConfig(
                        writes=tuple(vector_writes),
                        after_refs=frozenset(
                            {
                                ServerPlanRefId(source_validate_ref),
                                metadata_refs.establish_ref,
                                *group_after_refs,
                            },
                        ),
                        vector_model_cls=vector_model_cls,
                    ),
                ),
            )
            vector_completion_ref = ServerPlanRefId(vector_ref)
            steps.extend(
                ReplaceWholeDocumentEmbeddingRefsManyIntent(
                    ServerPlanRefId(replace_ref),
                    cast(
                        "Any",
                        _ReplaceWholeDocumentEmbeddingRefsManyIntentConfig(
                            writes=tuple(ref_writes),
                            after_refs=frozenset({vector_completion_ref}),
                            ref_model_cls=ref_model_cls,
                        ),
                    ),
                ).lower(ctx),
            )
            if maintenance_targets:
                vector_config = _require_vector_config(shape.target.model_cls, SqlIndexName(shape.target.index_name))
                resolved_backend_kind = _resolve_vector_backend_kind_for_config(
                    ctx,
                    vector_config,
                    backend_kind_override=config.backend_kind_override,
                )
                provided_intent_cls: (
                    type[ProvidedRefsPgvectorVectorIndexMaintenanceIntent] | type[ProvidedRefsUSearchVectorIndexMaintenanceIntent] | None
                )
                if resolved_backend_kind is VectorBackendKind.PGVECTOR:
                    provided_intent_cls = ProvidedRefsPgvectorVectorIndexMaintenanceIntent
                elif resolved_backend_kind is VectorBackendKind.USEARCH:
                    provided_intent_cls = ProvidedRefsUSearchVectorIndexMaintenanceIntent
                else:
                    provided_intent_cls = None
                steps.append(
                    provided_intent_cls(
                        _plan_ref(maintenance_ref),
                        VectorIndexMaintenanceOperation.REBUILD,
                        model_cls=shape.target.model_cls,
                        object_id=_target_object_id_ref(shape.target),
                        index=SqlIndexName(shape.target.index_name),
                        after_refs=_plan_refs(frozenset({replace_ref})),
                        refs_ref=_plan_ref(f"{replace_ref}.insert_refs.raw"),
                        vectors_ref=_plan_ref(f"{vector_ref}.raw"),
                    )
                    if provided_intent_cls is not None
                    else VectorIndexMaintenanceIntent(
                        _plan_ref(maintenance_ref),
                        VectorIndexMaintenanceOperation.REBUILD,
                        model_cls=shape.target.model_cls,
                        object_id=_target_object_id_ref(shape.target),
                        index=SqlIndexName(shape.target.index_name),
                        after_refs=_plan_refs(frozenset({replace_ref})),
                        backend_kind=resolved_backend_kind,
                    ),
                )
                steps.append(
                    BarrierStep(
                        _plan_ref(child_ref),
                        depends_on=_plan_refs(frozenset({maintenance_ref})),
                    ),
                )
            else:
                steps.append(
                    BarrierStep(_plan_ref(child_ref), depends_on=_plan_refs(frozenset({replace_ref}))),
                )
            after_refs.add(child_ref)
            previous_group_ref = ServerPlanRefId(child_ref)
        steps.append(
            BarrierStep(
                _plan_ref(self.ref_id),
                depends_on=_plan_refs(frozenset(ServerPlanRefId(ref_id) for ref_id in after_refs)),
            ),
        )
        return steps


class DeleteEmbeddingIntent(IntentStep[bool]):
    """L4: Delete embedding."""

    intent_tags = frozenset({"write", "embedding", "intent"})
    intent_cardinality = Cardinality.SCALAR

    def __init__(
        self: DeleteEmbeddingIntent,
        ref_id: ServerPlanRefId,
        config: ScalarServerRef[_DeleteEmbeddingIntentConfig],
    ) -> None:
        super().__init__(ref_id)
        self._config_ref = config
        self._config = _require_seeded_config(config, type(self).__name__)

    def lower(self: DeleteEmbeddingIntent, ctx: LoweringContext) -> Sequence[ServerPlanStep[Any]]:
        from impl.common.l2070_server_plan.steps.intent_query import SelectOneIntent, _SelectOneConfig
        from impl.common.l2070_server_plan.steps.row_hydration import (
            ResolveAnyDeletedCountResultStep,
        )

        config = self._config
        object_id_ref = config.object_id_ref
        target = _require_embedding_target(config.model_cls, config.object_id, SqlIndexName(config.index))
        internal_ref = f"{self.ref_id}.embedding"
        source_steps = list(
            SelectOneIntent(
                ServerPlanRefId(f"{internal_ref}.source_row"),
                config.model_cls,
                object_id_ref,
                _SelectOneConfig(
                    permission_grammar=config.permission_grammar,
                ),
            ).lower(ctx),
        )
        source_ref = source_steps[-1].ref_id
        source_presence_ref = cast(
            "ServerPlanRefId",
            ctx._lowering_cache.get(
                f"select_one_raw_ref:{internal_ref}.source_row",
                _source_presence_ref_from_steps(source_steps, ServerPlanRefId(source_ref)),
            ),
        )
        source_validate_ref = ServerPlanRefId(f"{internal_ref}.source_validate")
        ref_scope = _embedding_ref_scope_for_context(ctx=ctx, target=target)
        vector_config = _require_vector_config(config.model_cls, SqlIndexName(config.index))
        from l5200_vector_index.content_addressable_models import (
            get_embedding_classes_for_strategy,
        )
        from l5200_vector_index.vector_config import ContentStoreStrategy

        if vector_config.content_store_strategy is ContentStoreStrategy.PER_MODEL:
            from impl.common.l2070_server_plan.embedding_store_scope import (
                owned_per_model_embedding_storage,
            )

            ref_model_classes = tuple(
                ref_cls for _, _, ref_cls in owned_per_model_embedding_storage(ctx.planning_catalog)
            )
            if not ref_model_classes:
                raise ValueError("PER_MODEL embedding delete requires registered model storage")
        else:
            _vector_model_cls, ref_model_cls = get_embedding_classes_for_strategy(
                vector_config.content_store_strategy,
                source_table_name=target.table_name,
                field_name=target.index_name,
            )
            ref_model_classes = (ref_model_cls,)
        if vector_config.indexes_all_revisions:
            branch_scope = None
            revision_scope = None
        else:
            branch_scope = ref_scope.branch_id
            revision_scope = ref_scope.revision_id
        backend_kind = _resolve_vector_backend_kind_for_config(
            ctx,
            vector_config,
            backend_kind_override=config.backend_kind_override,
        )
        steps: list[ServerPlanStep[Any]] = [
            *source_steps,
            _RequireResolvedSourceStep(
                source_validate_ref,
                config=_RequireResolvedSourceConfig(
                    source_ref=source_presence_ref,
                    error_message=(
                        f"Object not found or not visible for embedding delete: {config.model_cls.__name__} with id {config.object_id}"
                    ),
                ),
            ),
        ]
        delete_ref_ids: list[ServerPlanRefId] = []
        previous_ref = source_validate_ref
        for position, ref_model_cls in enumerate(ref_model_classes):
            delete_ref = ServerPlanRefId(f"{internal_ref}.delete_refs.{position}")
            maintenance_ref = ServerPlanRefId(f"{internal_ref}.maintenance.{position}")
            delete_ref_ids.append(delete_ref)
            steps.append(
                _build_ref_delete_step(
                    ref_id=delete_ref,
                    target=target,
                    branch_id=branch_scope,
                    revision_id=revision_scope,
                    after_refs=frozenset({previous_ref}),
                    ignore_branch_revision_scope=vector_config.indexes_all_revisions,
                    return_deleted_rows=backend_kind is VectorBackendKind.USEARCH,
                    ref_model_cls=ref_model_cls,
                )
            )
            if backend_kind is VectorBackendKind.USEARCH:
                maintenance_step: ServerPlanStep[Any] = (
                    ProvidedRefsUSearchVectorIndexMaintenanceIntent(
                        _plan_ref(maintenance_ref),
                        VectorIndexMaintenanceOperation.DELETE,
                        model_cls=config.model_cls,
                        object_id=_target_object_id_ref(target),
                        index=SqlIndexName(config.index),
                        after_refs=_plan_refs(frozenset({delete_ref})),
                        refs_ref=_plan_ref(delete_ref),
                        vectors_ref=_plan_ref(delete_ref),
                    )
                )
            elif (
                config.backend_kind_override is None
                and vector_config.resolved_index_policy.native_index
            ):
                maintenance_step = ProviderResolvedVectorIndexMaintenanceIntent(
                    _plan_ref(maintenance_ref),
                    VectorIndexMaintenanceOperation.DELETE,
                    model_cls=config.model_cls,
                    object_id=cast("Any", config.object_id),
                    index=SqlIndexName(config.index),
                    after_refs=_plan_refs(frozenset({delete_ref})),
                )
            else:
                maintenance_step = VectorIndexMaintenanceIntent(
                    _plan_ref(maintenance_ref),
                    VectorIndexMaintenanceOperation.DELETE,
                    model_cls=config.model_cls,
                    object_id=cast("Any", config.object_id),
                    index=SqlIndexName(config.index),
                    after_refs=_plan_refs(frozenset({delete_ref})),
                    backend_kind=backend_kind,
                )
            steps.append(maintenance_step)
            previous_ref = maintenance_ref
        steps.append(
            ResolveAnyDeletedCountResultStep(
                ServerPlanRefId(self.ref_id), source_refs=delete_ref_ids
            )
        )
        return steps


class ClearEmbeddingRefsIntent(IntentStep[None]):
    """L4: Delete all scoped embedding refs without source visibility checks."""

    intent_tags = frozenset({"write", "embedding", "intent"})
    intent_cardinality = Cardinality.NONE

    def __init__(
        self: ClearEmbeddingRefsIntent,
        ref_id: ServerPlanRefId,
        config: ScalarServerRef[_ClearEmbeddingRefsIntentConfig],
    ) -> None:
        super().__init__(ref_id)
        self._config = _require_seeded_config(config, type(self).__name__)

    def lower(self: ClearEmbeddingRefsIntent, ctx: LoweringContext) -> Sequence[ServerPlanStep[Any]]:
        config = self._config
        target = _require_embedding_target(config.model_cls, config.object_id, SqlIndexName(config.index))
        delete_refs_ref = f"{self.ref_id}.embedding.delete_refs"
        branch_scope = _branch_scope_value_for_context(ctx)
        revision_scope = _revision_scope_value_for_context(ctx)
        return [
            _build_ref_delete_step(
                ref_id=ServerPlanRefId(delete_refs_ref),
                target=target,
                branch_id=branch_scope,
                revision_id=revision_scope,
                after_refs=frozenset(),
            ),
            BarrierStep(_plan_ref(self.ref_id), depends_on=_plan_refs(frozenset({delete_refs_ref}))),
        ]


def lower_set_visible_embedding_many_steps(
    ref_id: ServerPlanRefId,
    writes: Sequence[_VisibleWholeDocumentEmbeddingWrite],
    ctx: LoweringContext,
) -> list[ServerPlanStep[Any]]:
    """Lower visible whole-document writes to SQL-backed embedding persistence steps."""
    if not writes:
        return [BarrierStep(_plan_ref(ref_id), depends_on=frozenset())]
    grouped_writes: dict[
        tuple[str, str, str, int, object | None, object | None],
        list[_VisibleWholeDocumentEmbeddingWrite],
    ] = {}
    for write in writes:
        scope = _embedding_ref_scope_for_context(
            ctx=ctx,
            target=write.target,
            branch_id=write.branch_id,
            revision_id=write.revision_id,
        )
        grouped_writes.setdefault(
            (
                write.target.table_name,
                write.target.index_name,
                write.prepared.model_id,
                write.prepared.dimensions,
                _embedding_scope_group_key(scope.branch_id),
                _embedding_scope_group_key(scope.revision_id),
            ),
            [],
        ).append(write)
    batch_groups = [
        chunk
        for group_writes in grouped_writes.values()
        for chunk in _chunk_whole_document_batch_writes(
            group_writes,
            bulk_transport=ctx.backend_profile.traits.dml_bulk_transport,
        )
    ]

    steps: list[ServerPlanStep[Any]] = []
    after_refs: set[str] = set()
    previous_group_ref: ServerPlanRefId | None = None
    for idx, batch_writes in enumerate(batch_groups):
        if any(issubclass(write.target.model_cls, VersionedObjectRow) for write in batch_writes):
            if not ctx.is_versioned or not ctx.is_write_transaction:
                msg = (
                    "Visible versioned embedding write lowered with invalid context: "
                    f"ctx.is_versioned={ctx.is_versioned!r} "
                    f"ctx.is_write_transaction={ctx.is_write_transaction!r} "
                    f"ctx.branch_id={ctx.branch_id!r} "
                    f"ctx.lazy_branch={ctx.lazy_branch!r} "
                    f"ctx.revision_id={ctx.revision_id!r}"
                )
                raise AssertionError(msg)
        child_ref = f"{ref_id}.group_{idx}"
        shape = _validate_whole_document_batch_writes(batch_writes)
        metadata_ref = f"{child_ref}.metadata"
        group_after_refs = frozenset() if previous_group_ref is None else frozenset({previous_group_ref})
        metadata_refs, metadata_steps = _get_or_create_metadata_bootstrap_steps(
            ctx,
            ref_prefix=metadata_ref,
            target=shape.target,
            model_id=shape.model_id,
            dimensions=shape.dimensions,
        )
        hash_ref = f"{child_ref}.hashes"
        hash_steps = [
            _ResolveVisibleEmbeddingContentHashStep(
                ServerPlanRefId(hash_ref),
                config=_ResolveVisibleEmbeddingContentHashConfig(
                    model_cls=shape.target.model_cls,
                    index_name=shape.target.index_name,
                    source_objs=tuple(write.source_row for write in batch_writes),
                    metadata_ref=metadata_refs.metadata_ref,
                    batch=True,
                    after_refs=frozenset({metadata_refs.establish_ref, *group_after_refs}),
                ),
            ),
        ]
        vector_writes: list[_PendingWholeDocumentEmbeddingVectorWrite] = []
        ref_writes: list[_PendingWholeDocumentEmbeddingRefWrite] = []
        maintenance_targets: list[_EmbeddingWriteTarget] = []
        for write in batch_writes:
            source_id = _require_concrete_target_object_id(write.target)
            vector_writes.append(
                _PendingWholeDocumentEmbeddingVectorWrite(
                    hash_ref=ServerPlanRefId(hash_ref),
                    prepared=write.prepared,
                    index_name=SqlIndexName(write.target.index_name),
                    source_id=source_id,
                ),
            )
            ref_writes.append(
                _PendingWholeDocumentEmbeddingRefWrite(
                    scope=_embedding_ref_scope_for_context(
                        ctx=ctx,
                        target=write.target,
                        branch_id=write.branch_id,
                        revision_id=write.revision_id,
                    ),
                    hash_ref=ServerPlanRefId(hash_ref),
                ),
            )
            maintenance_targets.append(write.target)

        steps.extend(
            _lower_whole_document_batch_steps(
                ref_id=ServerPlanRefId(child_ref),
                shape=shape,
                metadata_steps=metadata_steps,
                metadata_establish_ref=metadata_refs.establish_ref,
                hash_steps=hash_steps,
                vector_writes=vector_writes,
                ref_writes=ref_writes,
                maintenance_targets=maintenance_targets,
                ctx=ctx,
                after_refs=group_after_refs,
            ),
        )
        after_refs.add(child_ref)
        previous_group_ref = ServerPlanRefId(child_ref)

    steps.append(BarrierStep(_plan_ref(ref_id), depends_on=_plan_refs(frozenset(after_refs))))
    return steps


class _SetVisibleEmbeddingManyIntent(IntentStep[None]):
    """L4: Batch set embedding vectors for already-visible rows."""

    intent_tags = frozenset({"write", "embedding", "intent"})
    intent_cardinality = Cardinality.NONE

    def __init__(
        self: _SetVisibleEmbeddingManyIntent,
        ref_id: ServerPlanRefId,
        config: ScalarServerRef[_SetVisibleEmbeddingManyIntentConfig],
    ) -> None:
        super().__init__(ref_id)
        self._config = _require_seeded_config(config, type(self).__name__)

    def lower(
        self: _SetVisibleEmbeddingManyIntent,
        ctx: LoweringContext,
    ) -> Sequence[ServerPlanStep[Any]]:
        writes = self._config.writes
        if not writes:
            return [BarrierStep(_plan_ref(self.ref_id), depends_on=frozenset())]

        grouped_writes: dict[
            tuple[str, str, str, int, object | None, object | None],
            list[_VisibleWholeDocumentEmbeddingWrite],
        ] = {}
        for write in writes:
            scope = _embedding_ref_scope_for_context(
                ctx=ctx,
                target=write.target,
                branch_id=write.branch_id,
                revision_id=write.revision_id,
            )
            grouped_writes.setdefault(
                (
                    write.target.table_name,
                    write.target.index_name,
                    write.prepared.model_id,
                    write.prepared.dimensions,
                    _embedding_scope_group_key(scope.branch_id),
                    _embedding_scope_group_key(scope.revision_id),
                ),
                [],
            ).append(write)
        batch_groups = [
            chunk
            for group_writes in grouped_writes.values()
            for chunk in _chunk_whole_document_batch_writes(
                group_writes,
                bulk_transport=ctx.backend_profile.traits.dml_bulk_transport,
            )
        ]

        steps: list[ServerPlanStep[Any]] = []
        after_refs: set[str] = set()
        previous_group_ref: ServerPlanRefId | None = None
        for idx, batch_writes in enumerate(batch_groups):
            child_ref = f"{self.ref_id}.group_{idx}"
            shape = _validate_whole_document_batch_writes(batch_writes)
            metadata_ref = f"{child_ref}.metadata"
            group_after_refs = frozenset() if previous_group_ref is None else frozenset({previous_group_ref})
            metadata_refs, metadata_steps = _get_or_create_metadata_bootstrap_steps(
                ctx,
                ref_prefix=metadata_ref,
                target=shape.target,
                model_id=shape.model_id,
                dimensions=shape.dimensions,
            )
            from l5200_vector_index.content_addressable_models import (
                get_embedding_classes_for_strategy,
            )

            vector_config = _require_vector_config(
                shape.target.model_cls,
                SqlIndexName(shape.target.index_name),
            )
            vector_model_cls, ref_model_cls = get_embedding_classes_for_strategy(
                vector_config.content_store_strategy,
                model_id=shape.model_id,
                source_table_name=shape.target.table_name,
                field_name=shape.target.index_name,
            )
            vector_ref = f"{child_ref}.vectors"
            replace_ref = f"{child_ref}.replace_refs"
            maintenance_ref = f"{child_ref}.maintenance"
            hash_ref = f"{child_ref}.hashes"
            hash_steps = [
                _ResolveVisibleEmbeddingContentHashStep(
                    ServerPlanRefId(hash_ref),
                    config=_ResolveVisibleEmbeddingContentHashConfig(
                        model_cls=shape.target.model_cls,
                        index_name=shape.target.index_name,
                        source_objs=tuple(write.source_row for write in batch_writes),
                        metadata_ref=metadata_refs.metadata_ref,
                        canonical_model_hint=shape.model_id,
                        batch=True,
                        after_refs=frozenset({metadata_refs.establish_ref, *group_after_refs}),
                    ),
                ),
            ]
            vector_writes: list[_PendingWholeDocumentEmbeddingVectorWrite] = []
            ref_writes: list[_PendingWholeDocumentEmbeddingRefWrite] = []
            maintenance_targets: list[_EmbeddingWriteTarget] = []
            for write in batch_writes:
                source_id = _require_concrete_target_object_id(write.target)
                scope = _embedding_ref_scope_for_context(
                    ctx=ctx,
                    target=write.target,
                    branch_id=write.branch_id,
                    revision_id=write.revision_id,
                )
                vector_writes.append(
                    _PendingWholeDocumentEmbeddingVectorWrite(
                        hash_ref=ServerPlanRefId(hash_ref),
                        prepared=write.prepared,
                        index_name=SqlIndexName(write.target.index_name),
                        source_id=source_id,
                    ),
                )
                ref_writes.append(
                    _PendingWholeDocumentEmbeddingRefWrite(
                        scope=scope,
                        hash_ref=ServerPlanRefId(hash_ref),
                    ),
                )
                maintenance_targets.append(write.target)

            steps.extend(metadata_steps)
            steps.extend(hash_steps)
            steps.append(
                _UpsertManyEmbeddingVectorsStep(
                    ServerPlanRefId(vector_ref),
                    config=_UpsertManyEmbeddingVectorsConfig(
                        writes=tuple(vector_writes),
                        after_refs=frozenset({metadata_refs.establish_ref, *group_after_refs}),
                        vector_model_cls=vector_model_cls,
                    ),
                ),
            )
            vector_completion_ref = ServerPlanRefId(vector_ref)
            steps.extend(
                ReplaceWholeDocumentEmbeddingRefsManyIntent(
                    ServerPlanRefId(replace_ref),
                    cast(
                        "Any",
                        _ReplaceWholeDocumentEmbeddingRefsManyIntentConfig(
                            writes=tuple(ref_writes),
                            after_refs=frozenset({vector_completion_ref}),
                            ref_model_cls=ref_model_cls,
                        ),
                    ),
                ).lower(ctx),
            )
            steps.append(
                VectorIndexMaintenanceIntent(
                    _plan_ref(maintenance_ref),
                    VectorIndexMaintenanceOperation.REBUILD,
                    model_cls=shape.target.model_cls,
                    object_id=_target_object_id_ref(shape.target),
                    index=SqlIndexName(shape.target.index_name),
                    after_refs=_plan_refs(frozenset({replace_ref})),
                    backend_kind=_resolve_vector_backend_kind_for_config(
                        ctx,
                        _require_vector_config(shape.target.model_cls, SqlIndexName(shape.target.index_name)),
                        backend_kind_override=None,
                    ),
                ),
            )
            steps.append(
                BarrierStep(_plan_ref(child_ref), depends_on=_plan_refs(frozenset({maintenance_ref}))),
            )
            after_refs.add(child_ref)
            previous_group_ref = ServerPlanRefId(child_ref)

        steps.append(BarrierStep(_plan_ref(self.ref_id), depends_on=_plan_refs(frozenset(after_refs))))
        return steps


class ReplaceChunkedEmbeddingsIntent(IntentStep[None]):
    """L4: Replace all chunked embedding refs for a source."""

    intent_tags = frozenset({"write", "embedding", "intent"})
    intent_cardinality = Cardinality.NONE

    def __init__(
        self: ReplaceChunkedEmbeddingsIntent,
        ref_id: ServerPlanRefId,
        config: ScalarServerRef[_ReplaceChunkedEmbeddingsIntentConfig],
    ) -> None:
        super().__init__(ref_id)
        self._config_ref = config
        self._config = _require_seeded_config(config, type(self).__name__)

    def lower(self: ReplaceChunkedEmbeddingsIntent, ctx: LoweringContext) -> Sequence[ServerPlanStep[Any]]:
        config = self._config
        target = _require_embedding_target(config.model_cls, config.object_id, SqlIndexName(config.index))
        vector_config = _require_vector_config(config.model_cls, SqlIndexName(config.index))
        seen_chunk_ids: set[object] = set()
        prepared_chunks: list[tuple[ChunkEmbedding, _PreparedEmbeddingValue]] = []
        for chunk in config.chunks:
            if chunk.chunk_id.is_whole_document():
                msg = "ReplaceChunkedEmbeddingsIntent does not accept the reserved whole_document chunk_id"
                raise ValueError(msg)
            if chunk.chunk_id in seen_chunk_ids:
                msg = f"ReplaceChunkedEmbeddingsIntent received duplicate chunk_id {chunk.chunk_id}"
                raise ValueError(msg)
            seen_chunk_ids.add(chunk.chunk_id)
            prepared_chunks.append(
                (
                    chunk,
                    _prepare_embedding_value(
                        config.model_cls,
                        config.object_id,
                        SqlIndexName(config.index),
                        chunk.embedding,
                        EmbeddingModelCanonicalId(config.model_id),
                        embedding_binary=chunk.embedding_binary,
                        projected_embeddings=chunk.projected_embeddings,
                    ),
                ),
            )

        from l5200_vector_index.content_addressable_models import get_embedding_classes_for_strategy

        vector_model_cls, ref_model_cls = get_embedding_classes_for_strategy(
            vector_config.content_store_strategy,
            model_id=prepared_chunks[0][1].model_id if prepared_chunks else config.model_id,
            source_table_name=target.table_name,
            field_name=config.index,
        )
        if not prepared_chunks:
            clear_ref = f"{self.ref_id}.clear_refs"
            maintenance_ref = f"{self.ref_id}.maintenance"
            branch_scope = _branch_scope_value_for_context(ctx)
            revision_scope = _revision_scope_value_for_context(ctx)
            return [
                _build_ref_delete_step(
                    ref_id=ServerPlanRefId(clear_ref),
                    target=target,
                    branch_id=branch_scope,
                    revision_id=revision_scope,
                    after_refs=frozenset(),
                    ref_model_cls=ref_model_cls,
                ),
                VectorIndexMaintenanceIntent(
                    _plan_ref(maintenance_ref),
                    VectorIndexMaintenanceOperation.REBUILD,
                    model_cls=config.model_cls,
                    object_id=cast("Any", config.object_id),
                    index=SqlIndexName(config.index),
                    after_refs=_plan_refs(frozenset({clear_ref})),
                    backend_kind=_resolve_backend_kind_for_vector_maintenance(ctx),
                ),
                BarrierStep(
                    _plan_ref(self.ref_id),
                    depends_on=_plan_refs(frozenset({ServerPlanRefId(maintenance_ref)})),
                ),
            ]

        first_prepared = prepared_chunks[0][1]
        for _chunk, prepared in prepared_chunks[1:]:
            if prepared.model_id != first_prepared.model_id or prepared.dimensions != first_prepared.dimensions:
                msg = "ReplaceChunkedEmbeddingsIntent requires a single model_id and embedding dimension per batch"
                raise ValueError(msg)

        metadata_refs, metadata_steps = _get_or_create_metadata_bootstrap_steps(
            ctx,
            ref_prefix=self.ref_id,
            target=target,
            model_id=first_prepared.model_id,
            dimensions=first_prepared.dimensions,
        )
        clear_ref = f"{self.ref_id}.clear_refs"
        maintenance_ref = f"{self.ref_id}.maintenance"
        branch_scope = _branch_scope_value_for_context(ctx)
        revision_scope = _revision_scope_value_for_context(ctx)
        steps: list[ServerPlanStep[Any]] = [
            *metadata_steps,
            _build_ref_delete_step(
                ref_id=ServerPlanRefId(clear_ref),
                target=target,
                branch_id=branch_scope,
                revision_id=revision_scope,
                after_refs=frozenset({metadata_refs.establish_ref}),
                ref_model_cls=ref_model_cls,
            ),
        ]
        after_insert_refs: set[str] = {clear_ref}
        for index, (chunk, prepared) in enumerate(prepared_chunks):
            prefix = f"{self.ref_id}.chunk_{index}"
            hash_ref = f"{prefix}.hash"
            vector_ref = f"{prefix}.vector"
            insert_ref = f"{prefix}.insert_ref"
            steps.extend(
                [
                    _ResolveChunkTextEmbeddingHashStep(
                        ServerPlanRefId(hash_ref),
                        _ResolveChunkTextEmbeddingHashConfig(
                            table_name=target.table_name,
                            index_name=SqlIndexName(config.index),
                            chunk_text=chunk.text,
                            metadata_ref=ServerPlanRefId(metadata_refs.metadata_ref),
                            config=vector_config,
                            after_refs=frozenset({metadata_refs.establish_ref}),
                        ),
                    ),
                    _UpsertEmbeddingVectorStep(
                        ServerPlanRefId(vector_ref),
                        config=_UpsertEmbeddingVectorConfig(
                            hash_ref=ServerPlanRefId(hash_ref),
                            index_name=SqlIndexName(config.index),
                            vector_model_cls=vector_model_cls,
                            model_id=prepared.model_id,
                            model_ref_id=prepared.model_ref_id,
                            dimensions=prepared.dimensions,
                            serialized_embedding=prepared.serialized_embedding,
                            precision=prepared.precision,
                            embedding_binary=prepared.embedding_binary,
                            embedding_binary_representation_id=prepared.embedding_binary_representation_id,
                            embedding_binary_projection_ref_id=prepared.embedding_binary_projection_ref_id,
                            embedding_binary_dimensions=prepared.embedding_binary_dimensions,
                        ),
                    ),
                    _InsertChunkEmbeddingRefStep(
                        ServerPlanRefId(insert_ref),
                        config=_InsertChunkEmbeddingRefConfig(
                            hash_ref=ServerPlanRefId(hash_ref),
                            source_id=config.object_id,
                            source_table=SqlTableName(target.table_name),
                            index_name=SqlIndexName(config.index),
                            branch_id=branch_scope,
                            revision_id=revision_scope,
                            chunk_id=chunk.chunk_id,
                            chunk_metadata=chunk.metadata,
                            chunking_scheme_hash=config.chunking_scheme_hash,
                            ref_model_cls=ref_model_cls,
                            after_refs=frozenset({ServerPlanRefId(clear_ref), ServerPlanRefId(vector_ref)}),
                        ),
                    ),
                ],
            )
            after_insert_refs.add(insert_ref)
        steps.append(
            VectorIndexMaintenanceIntent(
                _plan_ref(maintenance_ref),
                VectorIndexMaintenanceOperation.REBUILD,
                model_cls=config.model_cls,
                object_id=cast("Any", config.object_id),
                index=SqlIndexName(config.index),
                after_refs=frozenset(ServerPlanRefId(ref_id) for ref_id in after_insert_refs),
                backend_kind=_resolve_backend_kind_for_vector_maintenance(ctx),
            ),
        )
        steps.append(
            BarrierStep(
                _plan_ref(self.ref_id),
                depends_on=_plan_refs(frozenset({ServerPlanRefId(maintenance_ref)})),
            ),
        )
        return steps


def _metadata_filter_expr(table_name: SqlTableName, index_name: SqlIndexName) -> Expression[bool, Any]:
    from l1000_schema.typed_field import field
    from l5200_vector_index.embedding_metadata import EmbeddingMetadata

    return (field(EmbeddingMetadata.table_name) == table_name) & (field(EmbeddingMetadata.field_name) == index_name)


def _embedding_ref_scope_without_source_id(
    *,
    source_id: SysId | None = None,
    table_name: SqlTableName,
    index_name: SqlIndexName,
    branch_id: _EmbeddingScopeValue,
    revision_id: _EmbeddingScopeValue,
    model_cls: type[EmbeddingRef] | None = None,
) -> Expression[bool, Any]:
    """Scope filter for embedding refs by table, field, branch, and revision."""
    from l1000_schema.typed_field import field
    from l5200_vector_index.content_addressable_models import EmbeddingRef
    from l7000_versioned_schema.versioned_schema import BranchId, RevisionId

    if model_cls is None:
        model_cls = EmbeddingRef
    normalized_branch_id, normalized_revision_id = _normalize_embedding_ref_scope(
        branch_id=branch_id,
        revision_id=revision_id,
    )
    expr: Expression[bool, Any] = (field(model_cls.source_table) == table_name) & (
        field(model_cls.field_name) == index_name
    )
    if source_id is not None:
        expr = expr & (field(model_cls.source_id) == source_id)
    if normalized_branch_id is not None:
        if isinstance(normalized_branch_id, ScalarServerRef):
            expr = expr & (field(model_cls.branch_id) == normalized_branch_id)
        else:
            branch_literal = normalized_branch_id
            if not isinstance(branch_literal, BranchId | str):
                msg = f"Unsupported embedding ref branch scope {type(branch_literal).__name__}"
                raise TypeError(msg)
            expr = expr & (field(model_cls.branch_id) == BranchId(branch_literal))
    else:
        expr = expr & field(model_cls.branch_id).is_null()
    if normalized_revision_id is not None:
        if isinstance(normalized_revision_id, ScalarServerRef):
            expr = expr & (field(model_cls.revision_id) == normalized_revision_id)
        else:
            revision_literal = normalized_revision_id
            if not isinstance(revision_literal, RevisionId | str):
                msg = f"Unsupported embedding ref revision scope {type(revision_literal).__name__}"
                raise TypeError(msg)
            expr = expr & (field(model_cls.revision_id) == RevisionId(revision_literal))
    else:
        expr = expr & field(model_cls.revision_id).is_null()
    return expr


def _ref_scope_expr(
    *,
    source_id: SysId | None,
    table_name: SqlTableName,
    index_name: SqlIndexName,
    branch_id: _EmbeddingScopeValue,
    revision_id: _EmbeddingScopeValue,
    model_cls: type[EmbeddingRef] | None = None,
) -> Expression[bool, Any]:
    from l1000_schema.typed_field import field
    from l5200_vector_index.content_addressable_models import EmbeddingRef

    if model_cls is None:
        model_cls = EmbeddingRef
    expr = _embedding_ref_scope_without_source_id(
        table_name=table_name,
        index_name=index_name,
        branch_id=branch_id,
        revision_id=revision_id,
        model_cls=model_cls,
    )
    if source_id is None:
        return expr & field(model_cls.source_id).is_null()
    return expr & (field(model_cls.source_id) == source_id)


