    hash_high: int


class _ResolveChunkTextEmbeddingHashStep(MaybeSqlRelationPublisherStep[_ResolvedEmbeddingHash]):
    """Compute the content hash for one chunk from text and metadata nonce."""

    def __init__(
        self: _ResolveChunkTextEmbeddingHashStep,
        ref_id: ServerPlanRefId,
        config: _ResolveChunkTextEmbeddingHashConfig,
    ) -> None:
        super().__init__(ref_id)
        self._table_name = config.table_name
        self._index_name = config.index_name
        self._chunk_text = config.chunk_text
        self._metadata_ref = str(config.metadata_ref)
        self._config = config.config
        self._after_refs = frozenset(str(ref_id) for ref_id in config.after_refs)

    @property
    def level(self: _ResolveChunkTextEmbeddingHashStep) -> int:
        return 0

    def result_cardinality(self: _ResolveChunkTextEmbeddingHashStep) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self: _ResolveChunkTextEmbeddingHashStep) -> bool:
        return True

    def execution_role(self: _ResolveChunkTextEmbeddingHashStep) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def emits_sql_for_accounting(self: _ResolveChunkTextEmbeddingHashStep) -> bool | None:
        return True

    def consumes_executor_visible_dependencies(self: _ResolveChunkTextEmbeddingHashStep) -> bool:
        return True

    def requires_prior_step_boundary(self: _ResolveChunkTextEmbeddingHashStep) -> bool:
        return True

    def sql_visible_dependencies(self: _ResolveChunkTextEmbeddingHashStep) -> frozenset[str]:
        return frozenset({self._metadata_ref})

    def dependencies(self: _ResolveChunkTextEmbeddingHashStep) -> frozenset[str]:
        return frozenset({self._metadata_ref, *self._after_refs})

    def tables_read(self: _ResolveChunkTextEmbeddingHashStep) -> frozenset[str]:
        return frozenset({"sys_embedding_metadata"})

    def tables_written(self: _ResolveChunkTextEmbeddingHashStep) -> frozenset[str]:
        return frozenset()

    def step_tags(self: _ResolveChunkTextEmbeddingHashStep) -> frozenset[str]:
        return frozenset({"read", "embedding", "hash"})

    def cte_relation_role(self: _ResolveChunkTextEmbeddingHashStep) -> str:
        """Identify the producer-owned one-row chunk hash contract."""
        return "embedding_hash"

    def cte_publication_contract(self: _ResolveChunkTextEmbeddingHashStep) -> CtePublicationContract:
        columns = ("hash_short", "hash_high")
        column_type_hints = SqlColumnTypeHints(bigint_columns=frozenset({"hash_short", "hash_high"}))
        if columns is None:
            if column_type_hints is not None and column_type_hints.has_any():
                msg = f"{type(self).__name__} declares SQL column type hints without an explicit cte_output_columns() contract."
                raise TypeError(msg)
            return CtePublicationContract.non_publishing()
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=tuple(str(column) for column in columns),
            column_type_hints=column_type_hints,
            relation_contract=CteRelationContract.semantic_row(_ResolveChunkTextEmbeddingHashStepCteRow),
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def compile(
        self: _ResolveChunkTextEmbeddingHashStep,
        ctx: CompilationContext,
    ) -> CompiledStep[_ResolvedEmbeddingHash]:
        return runtime_resolve_chunk_text_embedding_hash_compiled_step(
            metadata_ref=self._metadata_ref,
            ctx=ctx,
            chunk_text=self._chunk_text,
            index_name=SqlIndexName(self._index_name),
            table_name=self._table_name,
            vector_config=self._config,
        )


class _MaterializeEmbeddingVectorInstancesStep(SqlRelationPublisherStep[list[dict[str, object]]]):
    """Materialize pending EmbeddingVector rows into a CTE-visible row set.

    Reads the content-hash refs published by prerequisite hash-resolution steps
    via ``runtime_ref_ids`` and emits a list of dict rows whose keys are the
    DB column names. The executor auto-publishes the result as a CTE via
    :meth:`PlanExecutor._publish_executor_visible_binding`, which
    :class:`UpsertManyStep` consumes through ``instances_ref`` (see
    :func:`compile_upsert_many_from_cte_binding`).
    """

    def __init__(
        self: _MaterializeEmbeddingVectorInstancesStep,
        ref_id: ServerPlanRefId,
        *,
        writes: tuple[_PendingWholeDocumentEmbeddingVectorWrite, ...],
        after_refs: frozenset[ServerPlanRefId] = frozenset(),
        model_cls: type[EmbeddingVector] | None = None,
    ) -> None:
        super().__init__(ref_id)
        if model_cls is None:
            from l5200_vector_index.content_addressable_models import EmbeddingVector

            model_cls = EmbeddingVector
        self._model_cls = model_cls
        self._writes = writes
        self._after_refs = frozenset(str(ref_id) for ref_id in after_refs)

    @property
    def level(self: _MaterializeEmbeddingVectorInstancesStep) -> int:
        return 0

    def result_cardinality(self: _MaterializeEmbeddingVectorInstancesStep) -> Cardinality:
        return Cardinality.MANY

    def is_read_only(self: _MaterializeEmbeddingVectorInstancesStep) -> bool:
        return True

    def execution_role(self: _MaterializeEmbeddingVectorInstancesStep) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def supports_sql_batch_transport(self: _MaterializeEmbeddingVectorInstancesStep) -> bool:
        return True

    def dependencies(self: _MaterializeEmbeddingVectorInstancesStep) -> frozenset[str]:
        return frozenset({*(write.hash_ref for write in self._writes), *self._after_refs})

    def sql_visible_dependencies(self: _MaterializeEmbeddingVectorInstancesStep) -> frozenset[str]:
        return frozenset(str(write.hash_ref) for write in self._writes)

    def tables_read(self: _MaterializeEmbeddingVectorInstancesStep) -> frozenset[str]:
        return frozenset()

    def tables_written(self: _MaterializeEmbeddingVectorInstancesStep) -> frozenset[str]:
        return frozenset()

    def step_tags(self: _MaterializeEmbeddingVectorInstancesStep) -> frozenset[str]:
        return frozenset({"embedding", "vector", "materialize", "grammar"})

    def cte_publication_contract(self: _MaterializeEmbeddingVectorInstancesStep) -> CtePublicationContract:
        columns = _embedding_vector_materialized_columns()
        column_type_hints = _embedding_vector_materialized_column_type_hints()

        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        contract_columns = tuple(str(column) for column in columns)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=contract_columns,
            column_type_hints=column_type_hints,
            model_cls=cte_projection_row_model(
                f"{type(self).__name__}CteRow",
                contract_columns,
                column_type_hints,
            ),
            relation_contract=CteRelationContract.projection_over_model(
                source_model_cls=self._model_cls,
                projection_lineage=tuple((column, column) for column in contract_columns),
            ),
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def compile(
        self: _MaterializeEmbeddingVectorInstancesStep,
        ctx: CompilationContext,
    ) -> CompiledStep[list[dict[str, object]]]:
        return _compile_embedding_vector_instances_relation(
            ctx=ctx,
            writes=self._writes,
        )


