    ) -> None:
        super().__init__(ref_id)
        self._model_cls = config.vector_model_cls
        self._writes = (
            _PendingWholeDocumentEmbeddingVectorWrite(
                hash_ref=config.hash_ref,
                index_name=config.index_name,
                prepared=_PreparedEmbeddingValue(
                    model_id=EmbeddingModelCanonicalId(config.model_id),
                    model_ref_id=config.model_ref_id,
                    dimensions=config.dimensions,
                    serialized_embedding=config.serialized_embedding,
                    precision=config.precision,
                    embedding_binary=config.embedding_binary,
                    embedding_binary_representation_id=config.embedding_binary_representation_id,
                    embedding_binary_projection_ref_id=config.embedding_binary_projection_ref_id,
                    embedding_binary_dimensions=config.embedding_binary_dimensions,
                ),
            ),
        )
        self._after_refs = frozenset(str(ref_id) for ref_id in config.after_refs)

    @property
    def level(self: _UpsertEmbeddingVectorStep) -> int:
        return 2

    def result_cardinality(self: _UpsertEmbeddingVectorStep) -> Cardinality:
        return Cardinality.MANY

    def is_read_only(self: _UpsertEmbeddingVectorStep) -> bool:
        return False

    def dependencies(self: _UpsertEmbeddingVectorStep) -> frozenset[str]:
        return frozenset(
            {write.hash_ref for write in self._writes} | set(self._after_refs),
        )

    def tables_read(self: _UpsertEmbeddingVectorStep) -> frozenset[str]:
        from l1000_schema.table_utils import get_table_name

        return frozenset({get_table_name(self._model_cls)})

    def tables_written(self: _UpsertEmbeddingVectorStep) -> frozenset[str]:
        return self.tables_read()

    def step_tags(self: _UpsertEmbeddingVectorStep) -> frozenset[str]:
        return frozenset({"write", "embedding", "vector", "insert"})

