class _UpsertManyEmbeddingVectorsStep(SqlRelationPublisherStep[Any]):
    """Batch upsert many whole-document vector rows after hash resolution."""

    def __init__(
        self: _UpsertManyEmbeddingVectorsStep,
        ref_id: ServerPlanRefId,
        config: _UpsertManyEmbeddingVectorsConfig,
    ) -> None:
        super().__init__(ref_id)
        if config.vector_model_cls is None:
            from l5200_vector_index.content_addressable_models import EmbeddingVector

            self._model_cls = EmbeddingVector
        else:
            self._model_cls = config.vector_model_cls
        self._writes = config.writes
        self._after_refs = frozenset(str(ref_id) for ref_id in config.after_refs)

    @property
    def level(self: _UpsertManyEmbeddingVectorsStep) -> int:
        return 2

    def result_cardinality(self: _UpsertManyEmbeddingVectorsStep) -> Cardinality:
        return Cardinality.MANY

    def is_read_only(self: _UpsertManyEmbeddingVectorsStep) -> bool:
        return False

    def dependencies(self: _UpsertManyEmbeddingVectorsStep) -> frozenset[str]:
        hash_refs = {write.hash_ref for write in self._writes}
        return frozenset(hash_refs | set(self._after_refs))

    def tables_read(self: _UpsertManyEmbeddingVectorsStep) -> frozenset[str]:
        from l1000_schema.table_utils import get_table_name

        return frozenset({get_table_name(self._model_cls)})

    def tables_written(self: _UpsertManyEmbeddingVectorsStep) -> frozenset[str]:
        return self.tables_read()

    def step_tags(self: _UpsertManyEmbeddingVectorsStep) -> frozenset[str]:
        return frozenset({"write", "embedding", "vector", "bulk", "insert"})

    def cte_publication_contract(self: _UpsertManyEmbeddingVectorsStep) -> CtePublicationContract:
        def _legacy_cte_output_columns() -> tuple[str, ...]:
            from l1000_schema.schema_def import get_db_column_name

            return tuple(
                get_db_column_name(self._model_cls, DynamicFieldName(field_name))
                for field_name in self._model_cls.model_fields
            )

        columns = _legacy_cte_output_columns()

        def _legacy_cte_column_type_hints(columns: tuple[str, ...]) -> SqlColumnTypeHints:
            from l2070_batching.sql_column_type_hints import model_sql_column_type_hints

            hints = model_sql_column_type_hints(self._model_cls, columns)
            if hints is None:
                msg = "Could not resolve SQL column type hints for EmbeddingVector bulk upsert rows"
                raise TypeError(msg)
            return hints

        column_type_hints = _legacy_cte_column_type_hints(columns)
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=tuple(str(column) for column in columns),
            column_type_hints=column_type_hints,
            model_cls=self._model_cls,
            relation_contract=CteRelationContract.model(self._model_cls),
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def lower(
        self: _UpsertManyEmbeddingVectorsStep,
        ctx: LoweringContext,
    ) -> list[ServerPlanStep[Any]]:
        from impl.common.l2070_server_plan.steps.upsert_many import UpsertManyRawResultStep

        if not self._writes:
            return [BarrierStep(_plan_ref(self.ref_id), depends_on=frozenset())]
        instances_ref = ServerPlanRefId(f"{self.ref_id}.instances")
        validate_ref = ServerPlanRefId(f"{self.ref_id}.validate")
        raw_ref = ServerPlanRefId(f"{self.ref_id}.raw")
        upsert_config = replace(
            _embedding_vector_upsert_config(ctx),
            instances_ref=instances_ref,
            after_refs=frozenset({validate_ref}),
        )
        return [
            _MaterializeEmbeddingVectorInstancesStep(
                instances_ref,
                writes=self._writes,
                after_refs=frozenset(ServerPlanRefId(ref_id) for ref_id in self._after_refs),
                model_cls=self._model_cls,
            ),
            _ValidateMaterializedEmbeddingVectorRowsStep(
                validate_ref,
                instances_ref=instances_ref,
                model_cls=self._model_cls,
            ),
            UpsertManyRawResultStep(
                raw_ref,
                self._model_cls,
                upsert_config,
            ),
            BarrierStep(_plan_ref(self.ref_id), depends_on=_plan_refs(frozenset({raw_ref}))),
        ]

    def compile(
        self: _UpsertManyEmbeddingVectorsStep,
        ctx: CompilationContext,
    ) -> CompiledStep[None]:
        del ctx
        raise NotImplementedError(f"{type(self).__name__} must be lowered before compile()")


