class _ValidateMaterializedEmbeddingVectorRowsStep(NonPublishingStep[None]):
    """Validate a published pending-vector relation against existing vector rows."""

    def __init__(
        self: _ValidateMaterializedEmbeddingVectorRowsStep,
        ref_id: ServerPlanRefId,
        *,
        instances_ref: ServerPlanRefId,
        after_refs: frozenset[ServerPlanRefId] = frozenset(),
        model_cls: type[EmbeddingVector] | None = None,
    ) -> None:
        super().__init__(ref_id)
        if model_cls is None:
            from l5200_vector_index.content_addressable_models import EmbeddingVector

            model_cls = EmbeddingVector
        self._model_cls = model_cls
        self._instances_ref = ServerPlanRefId(instances_ref)
        self._after_refs = frozenset(str(ref_id) for ref_id in after_refs)

    @property
    def level(self: _ValidateMaterializedEmbeddingVectorRowsStep) -> int:
        return 0

    def result_cardinality(self: _ValidateMaterializedEmbeddingVectorRowsStep) -> Cardinality:
        return Cardinality.NONE

    def is_read_only(self: _ValidateMaterializedEmbeddingVectorRowsStep) -> bool:
        return True

    def execution_role(self: _ValidateMaterializedEmbeddingVectorRowsStep) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def supports_sql_batch_transport(self: _ValidateMaterializedEmbeddingVectorRowsStep) -> bool:
        # Pending vectors may be executor-published by a prior SQL statement.
        return False

    def consumes_executor_visible_dependencies(self: _ValidateMaterializedEmbeddingVectorRowsStep) -> bool:
        return True

    def dependencies(self: _ValidateMaterializedEmbeddingVectorRowsStep) -> frozenset[str]:
        return frozenset({str(self._instances_ref), *self._after_refs})

    def sql_visible_dependencies(self: _ValidateMaterializedEmbeddingVectorRowsStep) -> frozenset[str]:
        return frozenset({str(self._instances_ref)})

    def tables_read(self: _ValidateMaterializedEmbeddingVectorRowsStep) -> frozenset[str]:
        from l1000_schema.table_utils import get_table_name

        return frozenset({get_table_name(self._model_cls)})

    def tables_written(self: _ValidateMaterializedEmbeddingVectorRowsStep) -> frozenset[str]:
        return frozenset()

    def step_tags(self: _ValidateMaterializedEmbeddingVectorRowsStep) -> frozenset[str]:
        return frozenset({"read", "embedding", "validate", "grammar"})

    def compile(
        self: _ValidateMaterializedEmbeddingVectorRowsStep,
        ctx: CompilationContext,
    ) -> CompiledStep[None]:
        from impl.common.l2050_sql_types.sql_branded_types import SqlAliasName, SqlColumnName, SqlTableName
        from impl.common.l2100_sql_grammar.tree.clauses import (
            SqlJoin,
            SqlSelectAlias,
            SqlSelectList,
            SqlTableAlias,
            SqlWhereClause,
        )
        from impl.common.l2100_sql_grammar._expressions_all import NULL
        from impl.common.l2100_sql_grammar.domain.versioning.stmt_cte import SqlUnionAll
        from impl.common.l2100_sql_grammar.tree.enums import BinaryOp, JoinKind
        from impl.common.l2100_sql_grammar.tree.expr_compound import SqlCast, SqlFuncCall
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlParam
        from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp, sql_and, sql_or
        from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
        from impl.common.l2100_sql_grammar.tree.statements import SqlSelect
        from l1000_schema.column_utils import get_db_column_name
        from l1000_schema.table_utils import get_table_name
        from l1000_schema.typed_field import SqlCastTargetType
        from l5200_vector_index.content_addressable_models import EmbeddingVector

        binding = _require_pending_vector_rows_cte(
            ctx,
            self._instances_ref,
            step_name=type(self).__name__,
        )

        short_col = get_db_column_name(EmbeddingVector, DynamicFieldName("content_hash_short"))
        high_col = get_db_column_name(EmbeddingVector, DynamicFieldName("content_hash_high"))
        model_ref_id_col = get_db_column_name(EmbeddingVector, DynamicFieldName("model_ref_id"))
        dimensions_col = get_db_column_name(EmbeddingVector, DynamicFieldName("dimensions"))
        precision_col = get_db_column_name(EmbeddingVector, DynamicFieldName("embedding_precision"))
        embedding_col = get_db_column_name(EmbeddingVector, DynamicFieldName("embedding"))
        embedding_binary_col = get_db_column_name(EmbeddingVector, DynamicFieldName("embedding_binary"))
        required_columns = (
            short_col,
            high_col,
            model_ref_id_col,
            dimensions_col,
            precision_col,
            embedding_col,
            embedding_binary_col,
        )
        _require_pending_vector_columns(
            binding,
            required_columns,
            step_name=type(self).__name__,
            instances_ref=self._instances_ref,
        )

        existing_alias = SqlAliasName("existing_vectors")
        pending_alias = SqlAliasName("pending_vectors")
        embedding_binary_cast = (
            "BYTEA" if ctx.backend_profile.traits.dml_parameter_transport is DmlParameterTransport.EXPLICIT_STORAGE_CASTS else "BLOB"
        )
        pending_cast_targets = {
            "BIGINT": SqlCastTargetType(base_type="BIGINT"),
            "BLOB": SqlCastTargetType(base_type="BLOB"),
            "BYTEA": SqlCastTargetType(base_type="BYTEA"),
        }

        def pending_column(
            column: str,
            cast_type: str | None = None,
            *,
            qualifier: SqlAliasName = pending_alias,
        ) -> SqlRenderable:
            expr: SqlRenderable = SqlColumnRef(SqlColumnName(column), qualifier=qualifier)
            if cast_type is None:
                return expr
            return SqlCast(expr, pending_cast_targets[cast_type])

        existing_dimensions_alias = SqlAliasName("existing_dimensions")
        pending_dimensions_alias = SqlAliasName("pending_dimensions")
        existing_precision_alias = SqlAliasName("existing_embedding_precision")
        pending_precision_alias = SqlAliasName("pending_embedding_precision")
        existing_embedding_alias = SqlAliasName("existing_embedding")
        pending_embedding_alias = SqlAliasName("pending_embedding")
        existing_embedding_binary_alias = SqlAliasName("existing_embedding_binary")
        pending_embedding_binary_alias = SqlAliasName("pending_embedding_binary")
        existing_conflict_rows = SqlSelect(
            select_list=SqlSelectList(
                [
                    SqlSelectAlias(
                        SqlColumnRef(SqlColumnName(model_ref_id_col), qualifier=existing_alias),
                        SqlAliasName(model_ref_id_col),
                    ),
                    SqlSelectAlias(
                        SqlColumnRef(SqlColumnName(dimensions_col), qualifier=existing_alias),
                        existing_dimensions_alias,
                    ),
                    SqlSelectAlias(
                        SqlColumnRef(SqlColumnName(dimensions_col), qualifier=pending_alias),
                        pending_dimensions_alias,
                    ),
                    SqlSelectAlias(
                        SqlColumnRef(SqlColumnName(precision_col), qualifier=existing_alias),
                        existing_precision_alias,
                    ),
                    SqlSelectAlias(
                        SqlColumnRef(SqlColumnName(precision_col), qualifier=pending_alias),
                        pending_precision_alias,
                    ),
                    SqlSelectAlias(
                        SqlColumnRef(SqlColumnName(embedding_col), qualifier=existing_alias),
                        existing_embedding_alias,
                    ),
                    SqlSelectAlias(
                        pending_column(embedding_col, embedding_binary_cast),
                        pending_embedding_alias,
                    ),
                    SqlSelectAlias(
                        SqlColumnRef(SqlColumnName(embedding_binary_col), qualifier=existing_alias),
                        existing_embedding_binary_alias,
                    ),
                    SqlSelectAlias(
                        pending_column(embedding_binary_col, embedding_binary_cast),
                        pending_embedding_binary_alias,
                    ),
                ],
            ),
            from_=SqlTableAlias(
                SqlTableIdent(get_table_name(self._model_cls)),
                existing_alias,
            ),
            joins=[
                SqlJoin(
                    join_type=JoinKind.INNER,
                    table=SqlTableAlias(SqlTableIdent(SqlTableName(binding.ref_id)), pending_alias),
                    condition=sql_and(
                        SqlBinaryOp(
                            SqlColumnRef(SqlColumnName(short_col), qualifier=existing_alias),
                            BinaryOp.EQ,
                            pending_column(short_col, "BIGINT"),
                        ),
                        SqlBinaryOp(
                            SqlColumnRef(SqlColumnName(high_col), qualifier=existing_alias),
                            BinaryOp.EQ,
                            pending_column(high_col, "BIGINT"),
                        ),
                        SqlBinaryOp(
                            SqlColumnRef(SqlColumnName(model_ref_id_col), qualifier=existing_alias),
                            BinaryOp.EQ,
                            pending_column(model_ref_id_col),
                        ),
                    ),
                ),
            ],
            where=SqlWhereClause(
                sql_or(
                    SqlBinaryOp(
                        SqlColumnRef(SqlColumnName(dimensions_col), qualifier=existing_alias),
                        BinaryOp.IS_DISTINCT_FROM,
                        SqlColumnRef(SqlColumnName(dimensions_col), qualifier=pending_alias),
                    ),
                    SqlBinaryOp(
                        SqlColumnRef(SqlColumnName(precision_col), qualifier=existing_alias),
                        BinaryOp.IS_DISTINCT_FROM,
                        SqlColumnRef(SqlColumnName(precision_col), qualifier=pending_alias),
                    ),
                    SqlBinaryOp(
                        SqlColumnRef(SqlColumnName(embedding_col), qualifier=existing_alias),
                        BinaryOp.IS_DISTINCT_FROM,
                        pending_column(embedding_col, embedding_binary_cast),
                    ),
                    SqlBinaryOp(
