class _MaterializeEmbeddingRefRowsStep(SqlRelationPublisherStep[list[dict[str, object]]]):
    """Materialize pending ``EmbeddingRef`` rows into a CTE-visible row set.

    Emits SQL rows keyed by DB column names. The executor auto-publishes the
    result as a CTE consumed by an ``UpsertManyStep`` via ``instances_ref``.
    """

    def __init__(
        self: _MaterializeEmbeddingRefRowsStep,
        ref_id: ServerPlanRefId,
        *,
        rows: tuple[_PendingEmbeddingRefRow, ...],
        after_refs: frozenset[ServerPlanRefId] = frozenset(),
        ref_model_cls: type[EmbeddingRef] | None = None,
    ) -> None:
        from l5200_vector_index.content_addressable_models import EmbeddingRef

        super().__init__(ref_id)
        self._rows = rows
        self._after_refs = after_refs
        self._model_cls = ref_model_cls or EmbeddingRef

    @property
    def level(self: _MaterializeEmbeddingRefRowsStep) -> int:
        return 0

    def result_cardinality(self: _MaterializeEmbeddingRefRowsStep) -> Cardinality:
        return Cardinality.MANY

    def is_read_only(self: _MaterializeEmbeddingRefRowsStep) -> bool:
        return True

    def execution_role(self: _MaterializeEmbeddingRefRowsStep) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def supports_sql_batch_transport(self: _MaterializeEmbeddingRefRowsStep) -> bool:
        return True

    def dependencies(self: _MaterializeEmbeddingRefRowsStep) -> frozenset[str]:
        deps: set[str] = {
            *(str(row.hash_ref) for row in self._rows),
            *(str(ref_id) for ref_id in self._after_refs),
        }
        for row in self._rows:
            for scope_value in (row.branch_id, row.revision_id):
                if isinstance(scope_value, ScalarServerRef) and scope_value.ref_id is not None:
                    deps.add(str(scope_value.ref_id))
        return frozenset(deps)

    def tables_read(self: _MaterializeEmbeddingRefRowsStep) -> frozenset[str]:
        return frozenset()

    def tables_written(self: _MaterializeEmbeddingRefRowsStep) -> frozenset[str]:
        return frozenset()

    def step_tags(self: _MaterializeEmbeddingRefRowsStep) -> frozenset[str]:
        return frozenset({"embedding", "ref", "materialize", "grammar"})

    def cte_publication_contract(self: _MaterializeEmbeddingRefRowsStep) -> CtePublicationContract:
        def _legacy_cte_output_columns() -> tuple[str, ...]:
            from l1000_schema.column_utils import get_db_column_name
            from l5200_vector_index.content_addressable_models import EmbeddingRef

            return tuple(
                get_db_column_name(EmbeddingRef, DynamicFieldName(field_name))
                for field_name in (
                    "sys_id",
                    "sys_created_at",
                    "sys_updated_at",
                    "source_id",
                    "source_table",
                    "field_name",
                    "branch_id",
                    "revision_id",
                    "content_hash_short",
                    "content_hash_high",
                    "computed_at",
                    "chunk_id",
                    "chunking_scheme_hash",
                    "chunk_metadata",
                )
            )

        columns = _legacy_cte_output_columns()

        def _legacy_cte_column_type_hints(columns: tuple[str, ...]) -> SqlColumnTypeHints:
            from l5200_vector_index.content_addressable_models import EmbeddingRef

            hints = model_sql_column_type_hints(EmbeddingRef, columns)
            if hints is None:
                msg = "Could not resolve SQL column type hints for EmbeddingRef rows"
                raise TypeError(msg)
            return hints

        column_type_hints = _legacy_cte_column_type_hints(columns)
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        from l5200_vector_index.content_addressable_models import EmbeddingRef

        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        contract_columns = tuple(str(column) for column in columns)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=contract_columns,
            column_type_hints=column_type_hints,
            model_cls=cte_projection_row_model(
                f"{type(self).__name__}CteRow",
                contract_columns,
                column_type_hints,
            ),
            relation_contract=CteRelationContract.projection_over_model(
                source_model_cls=EmbeddingRef,
                projection_lineage=tuple((column, column) for column in contract_columns),
            ),
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def compile(
        self: _MaterializeEmbeddingRefRowsStep,
        ctx: CompilationContext,
    ) -> CompiledStep[list[dict[str, object]]]:
        return _compile_embedding_ref_rows_relation(
            ctx=ctx,
            rows=self._rows,
        )


def _embedding_ref_upsert_config(
    *,
    upsert_on_conflict: bool,
) -> _UpsertManyStepConfig:
    """Build the ``_UpsertManyStepConfig`` for an EmbeddingRef write.

    When ``upsert_on_conflict`` is True, conflicts on the unique-scope tuple
    are silently ignored (no update). Otherwise we default to a primary-key
    ``DO NOTHING`` which never fires for freshly generated ``sys_id``s, so
    the step acts as a plain insert.
    """
    from impl.common.l2070_server_plan.steps.upsert_many import _UpsertManyStepConfig

    if upsert_on_conflict:
        return _UpsertManyStepConfig(
            conflict_columns=(
                "source_id",
                "source_table",
                "field_name",
                "branch_id",
                "revision_id",
                "chunk_id",
            ),
            on_conflict={},
            publish_sql_relation=True,
        )
    return _UpsertManyStepConfig(
        conflict_columns=("sys_id",),
        on_conflict={},
        publish_sql_relation=True,
    )


