    ) -> list[ServerPlanStep[Any]]:
        del ctx
        from impl.common.l2070_server_plan.steps.upsert_many import UpsertManyRawResultStep

        instances_ref = ServerPlanRefId(f"{self.ref_id}.instances")
        upsert_config = replace(
