@pure_lazy
def _table_event_dispatch_needed(
    model_cls: type[DatabaseObjectRow[Any]],
    event_type: str,
) -> bool:
    """Return whether table-event lowering has any work to perform.

    The subscription registries are process-local metadata. Checking them here
    avoids adding a runtime event-dispatch step whose only effect would be to
    discover that there are no subscribers. Cross-process subscription bridges
    still keep the step because they need compact post-commit notifications.
    """

    from l5000_subscriptions.cross_process import cross_process_runtime_active
    from l5000_subscriptions.subscription import _get_subscriptions

    if _has_matching_table_hooks(model_cls, event_type):
        return True
    if getattr(model_cls, "__subscription_notifications__", None) is True:
        return True
    if cross_process_runtime_active():
        return True
    table_name = get_table_name(model_cls)
    for registry_key in (f"table:{table_name}", f"versioned_table:{table_name}"):
        for subscription in _get_subscriptions(registry_key):
            if event_type in subscription.get("event_types", ()):
                return True
    return False


