def apply_queue_visible_row_table_events_effect(
    payload: object,
    txn: object | None,
) -> None:
    if not isinstance(payload, _QueueVisibleRowTableEventsEffect):
        msg = "QUEUE_VISIBLE_ROW_TABLE_EVENTS effect payload has the wrong type"
        raise TypeError(msg)
    if payload.rows_ref is not None or payload.old_rows_ref is not None:
        payload = replace(
            payload,
            rows=tuple(row for item in payload.rows for row in _resolved_visible_rows(item, payload.model_cls)),
            old_rows=tuple(row for item in payload.old_rows for row in _resolved_visible_rows(item, payload.model_cls)),
        )
    if payload.filter_unchanged:
        old_rows: list[DatabaseObjectRow] = []
        for item in payload.old_rows:
            for row in _resolved_visible_rows(item, payload.model_cls):
                if isinstance(row, payload.model_cls):
                    old_rows.append(row)
        old_by_id = {row.sys_id: row for row in old_rows}
        semantic_fields = tuple(
            name
            for name in payload.model_cls.model_fields
            if name not in {"created_at", "updated_at", "revision_id", "staged_commit_id"} and not name.startswith("sys_")
        )
        rows: list[DatabaseObjectRow] = []
        for item in payload.rows:
            for row in _resolved_visible_rows(item, payload.model_cls):
                if not isinstance(row, payload.model_cls):
                    continue
                old_row = old_by_id.get(row.sys_id)
                if old_row is None:
                    if payload.event_type == "UPSERT":
                        rows.append(row)
                elif any(getattr(row, name) != getattr(old_row, name) for name in semantic_fields):
                    rows.append(row)
        payload = replace(payload, rows=tuple(rows), old_rows=tuple(old_rows))
    if payload.delivery_order:
        row_order = {row_id: index for index, row_id in enumerate(payload.delivery_order)}

        def _delivery_index(candidate: object) -> int:
            row_id = candidate.get("sys_id") if isinstance(candidate, Mapping) else getattr(candidate, "sys_id", None)
            return row_order.get(row_id, len(row_order))

        payload = replace(
            payload,
            rows=tuple(sorted(payload.rows, key=_delivery_index)),
            old_rows=tuple(sorted(payload.old_rows, key=_delivery_index)),
        )
    resolved_branch_id = _lifecycle_branch_id(payload.branch_id)
    if payload.remote_only:
        if txn is None:
            return
        from l5000_subscriptions.cross_process import stage_remote_table_notification

        for row in payload.rows:
            if isinstance(row, payload.model_cls):
                visible_row = row
            elif isinstance(row, Mapping):
                visible_row = payload.model_cls.model_validate(row)
            else:
                continue
            stage_remote_table_notification(
                cast("WriteTransaction | LazyVersionedWriteTransaction", txn),
                payload.model_cls,
                payload.event_type,
                visible_row,
                session_id=None,
                branch_id=resolved_branch_id,
                derive_revision_from_row=payload.event_type == "DELETE",
            )
        return

    from impl.common.l2070_server_plan.subscription_queue_runtime import (
        queue_visible_row_table_events,
    )

    from l5000_subscriptions.deferred_dispatch import subscription_publication_scope

    from l5000_subscriptions.subscription import SubscriptionPhase

    resolved_revision_id = (
        payload.revision_id
        if isinstance(payload.revision_id, RevisionId)
        else RevisionId(str(payload.revision_id))
        if payload.revision_id is not None
        else None
    )
    resolved_phase = SubscriptionPhase(payload.subscription_phase) if payload.subscription_phase is not None else None
    with subscription_publication_scope(payload.staged_commit_id):
        queue_visible_row_table_events(
            txn=txn,
            model_cls=payload.model_cls,
            event_type=payload.event_type,
            rows=payload.rows,
            old_rows=payload.old_rows,
            branch_id=resolved_branch_id,
            revision_id=resolved_revision_id,
            phase=resolved_phase,
            stage_remote_notification=payload.stage_remote_notification,
            delivery_order=payload.delivery_order,
            exact_delete_preimages=payload.exact_delete_preimages,
        )
    if payload.dispatch_immediately and txn is not None:
        from l5000_subscriptions.deferred_dispatch import dispatch_queued_events

        dispatch_queued_events(cast("WriteTransaction | LazyVersionedWriteTransaction", txn))


