def _resolved_visible_rows(
    value: object,
    model_cls: type[DatabaseObjectRow],
) -> tuple[object, ...]:
    def _field_accepts_text(field_name: str) -> bool:
        field = model_cls.model_fields.get(field_name)
        if field is None:
            return False
        annotation = field.annotation
        if annotation is str:
            return True
        origin = get_origin(annotation)
        if origin is types.UnionType or origin is Union:
            return any(arg is str for arg in get_args(annotation))
        return False

    def _decode_executor_text_envelope(value: object) -> object:
        if (
            isinstance(value, Mapping)
            and value.get(_EXECUTOR_TEXT_ENVELOPE_KEY) == _EXECUTOR_TEXT_ENVELOPE_ENCODING
            and isinstance(value.get("payload"), str)
        ):
            try:
                compressed = base64.b64decode(value["payload"].encode("ascii"))
                return zlib.decompress(compressed).decode("utf-8")
            except Exception:
                return value
        return value

    def _coerce_visible_field_value(field_name: str, value: object) -> object:
        decoded = _decode_executor_text_envelope(value)
        if (
            _field_accepts_text(field_name)
            and not isinstance(decoded, str)
            and isinstance(decoded, Mapping | Sequence)
            and not isinstance(decoded, bytes | bytearray)
        ):
            return json.dumps(decoded, default=str, separators=(",", ":"), sort_keys=True)
        return decoded

    def _coerce(row: object) -> object:
        if isinstance(row, Mapping) and set(row) == {"__executor_value__"}:
            return _coerce(row["__executor_value__"])
        if isinstance(row, model_cls):
            return row
        if isinstance(row, Mapping):
            from l1000_schema.column_utils import get_python_field_name
            from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName
            from impl.common.l2070_server_plan.steps.large_column_read import (
                hydrate_inline_large_column_row_dicts,
            )

            hydrated_row = hydrate_inline_large_column_row_dicts(model_cls, [dict(row)])[0]
            visible_payload: dict[str, object] = {}
            for db_column, field_value in hydrated_row.items():
                field_name = (
                    db_column if db_column in model_cls.model_fields else get_python_field_name(model_cls, SqlColumnName(db_column))
                )
                if field_name in model_cls.model_fields:
                    visible_payload[field_name] = _coerce_visible_field_value(
                        field_name,
                        field_value,
                    )
            if "sys_id" not in visible_payload:
                return None
            from impl.common.l5200_sql_query.row_converter import convert_row_to_model

            return convert_row_to_model(
                model_cls,
                visible_payload,
                select_columns=[str(column_name) for column_name in visible_payload],
                hydrate_large_columns=False,
            )
        return row

    if value is None:
        return ()
    if isinstance(value, Sequence) and not isinstance(value, str | bytes | bytearray):
        return tuple(coerced for row in value if (coerced := _coerce(row)) is not None)
    coerced = _coerce(value)
    return () if coerced is None else (coerced,)


