    "frequency",
)


def _build_polyfill_fts_index_rows(
    *,
    model_cls: type[DatabaseObjectRow],
    visible_rows: Sequence[object],
) -> list[dict[str, object]]:
    from impl.common.l5150_fts_polyfill.manager import FTSPolyfillManager
    from l5100_fts.fts_config import get_fts_config

    fts_config = get_fts_config(model_cls)
    if fts_config is None:
        return []

    manager = FTSPolyfillManager()
    index_rows_by_hash: dict[str, tuple[dict[str, object], ...]] = {}
    for visible_row in visible_rows:
        if isinstance(visible_row, Mapping):
            from l1000_schema.column_utils import get_db_column_name

            row_data: dict[str, object] = {}
            for field_name in model_cls.model_fields:
                db_column_name = get_db_column_name(model_cls, DynamicFieldName(field_name))
                if field_name in visible_row:
                    row_data[field_name] = visible_row[field_name]
                elif db_column_name in visible_row:
                    row_data[field_name] = visible_row[db_column_name]
            validated_row = model_cls.model_validate(row_data)
        else:
            if not hasattr(visible_row, "model_dump"):
                msg = f"Polyfill FTS maintenance expected DatabaseObjectRow-compatible rows, got {type(visible_row).__name__}"
                raise TypeError(msg)
            validated_row = cast("DatabaseObjectRow[SysId]", visible_row)
        entries = manager._build_index_entries(validated_row, fts_config)
        if not entries:
            continue
        content_hash = entries[0].content_hash
        if content_hash in index_rows_by_hash:
            continue
        index_rows_by_hash[content_hash] = tuple(
            {
                "sys_id": SysId.new(),
                "content_hash": entry.content_hash,
                "token": entry.token,
                "field_name": entry.field_name,
                "position": entry.position,
                "frequency": entry.frequency,
            }
            for entry in entries
        )
    return [row for content_hash in index_rows_by_hash for row in index_rows_by_hash[content_hash]]


def _prepare_polyfill_fts_index_rows(
    *,
    model_cls: type[DatabaseObjectRow],
    visible_rows_ref: str,
    runtime_refs: Mapping[str, object],
) -> list[dict[str, object]]:
    resolved = runtime_refs.get(visible_rows_ref, ())
    if isinstance(resolved, DatabaseObjectRow | Mapping):
        visible_rows: Sequence[object] = (resolved,)
    elif isinstance(resolved, Sequence) and not isinstance(resolved, (str, bytes, bytearray)):
        visible_rows = resolved
    else:
        msg = f"_PreparePolyfillFtsIndexRowsStep expected visible row data, got {type(resolved).__name__}"
        raise TypeError(msg)
    return _build_polyfill_fts_index_rows(model_cls=model_cls, visible_rows=visible_rows)


