def _build_delete_polyfill_fts_rows_from_cte_stmt(
    *,
    table_name: SqlTableName,
    rows_cte_name: str,
) -> SqlRenderable:
    from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName
    from impl.common.l2100_sql_grammar.tree.clauses import SqlSelectList
    from impl.common.l2100_sql_grammar.tree.expr_compound import SqlSubquery
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef
    from impl.common.l2100_sql_grammar.tree.expr_ops import SqlIn
    from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
    from impl.common.l2100_sql_grammar.tree.statements import SqlDelete, SqlSelect

    content_hash_col = SqlColumnRef(SqlColumnName("content_hash"))
    content_hash_subquery = SqlSubquery(
        SqlSelect(
            SqlSelectList([content_hash_col]),
            from_=SqlTableIdent(SqlTableName(rows_cte_name)),
        ),
    )
    return cast(
        "SqlRenderable",
        SqlDelete(
            SqlTableIdent(table_name),
            where=SqlIn(content_hash_col, content_hash_subquery),
        ),
    )


def _build_delete_global_polyfill_fts_metadata_stmt(
