def _literal_lifecycle_row_contract(
    model_cls: type[DatabaseObjectRow],
    rows: tuple[DatabaseObjectRow, ...],
) -> tuple[tuple[str, ...], RelationContract | None]:
    if not rows:
        return (), None
    from l1000_schema.schema_def import get_db_column_name
    from l2070_batching.sql_column_type_hints import model_sql_column_type_hints

    field_names = tuple(rows[0].__dict__)
    columns = tuple(get_db_column_name(model_cls, DynamicFieldName(field_name)) for field_name in field_names)
    type_hints = model_sql_column_type_hints(model_cls, columns)
    if type_hints is None:
        msg = f"Could not resolve literal lifecycle row hints for {model_cls.__name__}"
        raise TypeError(msg)
    return field_names, RelationContract(columns, type_hints.require_complete(columns))


