    def _compile_changed_update_relation(
        self: _TableEventSubscriptionLifecycleStep,
        ctx: CompilationContext,
        rows_cte: CteReference,
        auxiliary_ctes: list[tuple[ServerPlanRefId, SqlRenderable]] | None,
    ) -> CompiledStep[tuple[object, ...]]:
        from impl.common.l2050_sql_types.sql_branded_types import SqlAliasName, SqlColumnName, SqlTableName
        from impl.common.l2100_sql_grammar.tree.clauses import SqlJoin, SqlSelectAlias, SqlSelectList, SqlTableAlias
        from impl.common.l2100_sql_grammar.tree.enums import BinaryOp, JoinKind
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef
        from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp, SqlIsNull, sql_or
        from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
        from impl.common.l2100_sql_grammar.tree.statements import SqlSelect
        from l2070_batching.output_shape import CompiledOutputShape, DeclaredResultRelation, synthetic_output_field
        from l2070_batching.post_op import row_dicts_post_op
        from l2070_batching.sql_column_type_hints import combine_sql_column_type_hints

        assert self._old_rows_ref is not None
        old_cte = ctx.cte_refs.get(self._old_rows_ref)
        if not isinstance(old_cte, CteReference):
            msg = f"Subscription old-row ref {self._old_rows_ref!r} has no SQL relation"
            raise ValueError(msg)
        new_alias = SqlAliasName("changed_new")
        old_alias = SqlAliasName("changed_old")
        embedded_preimage = old_cte.ref_id == rows_cte.ref_id and any(column.startswith("__pre__") for column in rows_cte.columns)
        new_columns = tuple(column for column in rows_cte.columns if not column.startswith("__pre__"))
        if embedded_preimage:
            old_source_columns = tuple(column for column in new_columns if f"__pre__{column}" in rows_cte.columns)
            old_physical_columns = tuple(f"__pre__{column}" for column in old_source_columns)
        else:
            old_source_columns = tuple(old_cte.columns)
            old_physical_columns = old_source_columns
        common_columns = tuple(column for column in new_columns if column in old_source_columns)
        semantic_columns = tuple(
            column for column in common_columns if column not in {"sys_id", "created_at", "updated_at"} and not column.startswith("sys_")
        )
        from impl.common.l2100_sql_grammar.tree.expr_ops import SqlDecimalIsDistinct
        from l2070_batching.sql_column_type_hints import model_sql_column_type_hints

        semantic_type_hints = model_sql_column_type_hints(self._model_cls, semantic_columns)

        def semantic_difference(column: str) -> SqlRenderable:
            new_value = SqlColumnRef(SqlColumnName(column), new_alias)
            old_value = SqlColumnRef(
                SqlColumnName(f"__pre__{column}" if embedded_preimage else column),
                new_alias if embedded_preimage else old_alias,
            )
            if semantic_type_hints is not None and column in semantic_type_hints.numeric_columns:
                return SqlDecimalIsDistinct(new_value, old_value)
            return SqlBinaryOp(new_value, BinaryOp.IS_DISTINCT_FROM, old_value)

        change_predicates = tuple(semantic_difference(column) for column in semantic_columns)
        select_items: list[SqlRenderable] = [
            SqlSelectAlias(SqlColumnRef(SqlColumnName(column), new_alias), SqlAliasName(column)) for column in new_columns
        ]
        old_output_columns = tuple(f"__old_{column}" for column in old_source_columns)
        select_items.extend(
            SqlSelectAlias(
                SqlColumnRef(
                    SqlColumnName(physical_column),
                    new_alias if embedded_preimage else old_alias,
                ),
                SqlAliasName(output_column),
            )
            for physical_column, output_column in zip(
                old_physical_columns,
                old_output_columns,
                strict=True,
            )
        )
        where = (
            sql_or(*change_predicates)
            if change_predicates
            else SqlBinaryOp(
                SqlColumnRef(SqlColumnName("sys_id"), new_alias),
                BinaryOp.IS_DISTINCT_FROM,
                SqlColumnRef(SqlColumnName("sys_id"), new_alias),
            )
        )
        if self._event_type == "UPSERT":
            where = sql_or(
                SqlIsNull(
                    SqlColumnRef(
                        SqlColumnName("__pre__sys_id" if embedded_preimage else "sys_id"),
                        new_alias if embedded_preimage else old_alias,
                    ),
                ),
                where,
            )
        joins: list[SqlRenderable] = []
        if not embedded_preimage:
            join_condition = SqlBinaryOp(
                SqlColumnRef(SqlColumnName("sys_id"), new_alias),
                BinaryOp.IS_NOT_DISTINCT_FROM,
                SqlColumnRef(SqlColumnName("sys_id"), old_alias),
            )
            joins.append(
                SqlJoin(
                    JoinKind.LEFT if self._event_type == "UPSERT" else JoinKind.INNER,
                    SqlTableAlias(SqlTableIdent(SqlTableName(old_cte.ref_id)), old_alias),
                    join_condition,
                ),
            )
        grammar = SqlSelect(
            SqlSelectList(select_items),
            from_=SqlTableAlias(SqlTableIdent(SqlTableName(rows_cte.ref_id)), new_alias),
            joins=joins,
            where=where,
        )
        output_columns = (*new_columns, *old_output_columns)
        output_shape = CompiledOutputShape(tuple(synthetic_output_field(column) for column in output_columns))
        old_hints = combine_sql_column_type_hints(
            old_output_columns,
            *(
                old_cte.column_type_hints.rename_column(physical_column, output_column)
                for physical_column, output_column in zip(
                    old_physical_columns,
                    old_output_columns,
                    strict=True,
                )
            ),
        )
        column_type_hints = combine_sql_column_type_hints(
            output_columns,
            rows_cte.column_type_hints,
            old_hints,
        ).require_complete(output_columns)
        if old_cte.auxiliary_query is not None:
            auxiliary_ctes = [*(auxiliary_ctes or []), (old_cte.ref_id, old_cte.auxiliary_query)]
        return CompiledStep(
            grammar=grammar,
            needs_returning=True,
            output_shape=output_shape,
            result_relation=DeclaredResultRelation.from_output_shape(output_shape),
            column_type_hints=column_type_hints,
            auxiliary_ctes=auxiliary_ctes,
            closed_post_op=row_dicts_post_op(),
            lifecycle_effects=(
                ResultBoundLifecycleEffects(
                    self._lifecycle_effects_from_result,
                    phase=PipelineLifecyclePhase.BEFORE_COMMIT_TRANSACTIONAL,
                ),
            ),
            allow_empty_provenance_manifest=True,
        )

    def _snapshot_effects(
        self: _TableEventSubscriptionLifecycleStep,
    ) -> Sequence[_QueueVisibleRowTableEventsEffect]:
        old_rows_ref = self._visible_rows_ref if self._event_type == "DELETE" else self._old_rows_ref
        return (
            _QueueVisibleRowTableEventsEffect(
                model_cls=self._model_cls,
                event_type=self._event_type,
                rows=(),
                rows_ref=self._hydrated_rows_ref or ServerPlanRefId(_executor_runtime_relation_ref_id(self._visible_rows_ref)),
                old_rows_ref=ServerPlanRefId(old_rows_ref) if old_rows_ref is not None else None,
                filter_unchanged=self._event_type in {"UPDATE", "UPSERT"},
                exact_delete_preimages=self._event_type == "DELETE",
                writer_ref=self._writer_ref,
                staged_commit_id=self._staged_commit_id,
                branch_id=None,
                remote_only=self._remote_only,
                delivery_order=self._delivery_order,
            ),
        )

    def _lifecycle_effects_from_result(
        self: _TableEventSubscriptionLifecycleStep,
        result: object,
    ) -> Sequence[_QueueVisibleRowTableEventsEffect]:
        if not isinstance(result, Sequence) or isinstance(result, str | bytes | bytearray):
            return ()
        rows: list[object] = []
        old_rows: list[object] = []
        result_branch_id: object | None = None
        for item in result:
            if isinstance(item, self._model_cls):
                rows.append(item)
                continue
            if not isinstance(item, Mapping):
                continue
            new_payload = {key: value for key, value in item.items() if not key.startswith("__old_")}
            old_payload = {key.removeprefix("__old_"): value for key, value in item.items() if key.startswith("__old_")}
            if result_branch_id is None:
                result_branch_id = new_payload.get("branch_id")
            rows.extend(_resolved_visible_rows(new_payload, self._model_cls))
            if old_payload:
                old_rows.extend(_resolved_visible_rows(old_payload, self._model_cls))
        if not rows:
            return ()
        return (
            _QueueVisibleRowTableEventsEffect(
                model_cls=self._model_cls,
                event_type=self._event_type,
                rows=tuple(rows),
                rows_ref=self._hydrated_rows_ref,
                old_rows=tuple(old_rows),
                exact_delete_preimages=self._event_type == "DELETE",
                writer_ref=self._writer_ref,
                staged_commit_id=self._staged_commit_id,
                branch_id=result_branch_id if result_branch_id is not None else self._branch_id,
                remote_only=self._remote_only,
                delivery_order=self._delivery_order,
            ),
        )

