def _require_seeded_ref[T](ref: ServerRef[T], *, owner: str, field_name: str) -> T:
    ref_shape: PlanningServerValueShape = inspect_server_value_shape_for_planning(
        ref,
        site=f"{owner}.{field_name}",
    )
    ref_id = ref_shape.symbolic_ref_id
    if ref_id is None:
        msg = f"{owner} requires a seeded {field_name} ref"
        raise NotImplementedError(msg)
    found, value = read_seeded_constant_from_ctx(None, ServerPlanRefId(ref_id))
    if not found:
        msg = f"{owner} requires a seeded {field_name} ref"
        raise NotImplementedError(msg)
    return cast("T", value)


def _seeded_ref_or_none[T](ref: ServerRef[T], *, owner: str, field_name: str) -> T | None:
    ref_shape = inspect_server_value_shape_for_planning(
        ref,
        site=f"{owner}.{field_name}",
    )
    ref_id = ref_shape.symbolic_ref_id
    if ref_id is None:
        return None
    found, value = read_seeded_constant_from_ctx(None, ServerPlanRefId(ref_id))
    return cast("T", value) if found else None


def _ref_dependencies(value: object) -> frozenset[str]:
    if isinstance(value, ServerRef):
        return value.dependencies()
    return frozenset()


def _require_single_ref_dependency[T](
    value: ServerRef[T],
    *,
    owner: str,
    field_name: str,
) -> ServerPlanRefId:
    """Return the sole symbolic dependency or reject the malformed plan."""
    dependencies = value.dependencies()
    if len(dependencies) != 1:
        msg = f"{owner}.{field_name} requires exactly one symbolic dependency; received {sorted(dependencies)!r}"
        raise ProgrammingError(msg)
    return ServerPlanRefId(next(iter(dependencies)))


