            excluded_fields=tuple(exclude),
            include_polymorphic=True,
        )
        if plan.is_json
    )


def _cascade_relationships_for_child(
    domain: type[VersioningDomain],
    child_table_cls: type[VersionedObjectRow[Any]],
) -> list[Any]:
    child_table = get_table_name(child_table_cls)
    relationships: list[Any] = []
    for _parent_model, rels in discover_fk_relationships(domain).items():
        for rel in rels:
            if get_table_name(rel.child_model) != child_table:
                continue
            if rel.on_delete.upper().replace(" ", "_") != "CASCADE":
                continue
            relationships.append(rel)
    return relationships


def _fk_relationships_for_child(
    domain: type[VersioningDomain],
    child_table_cls: type[VersionedObjectRow[Any]],
) -> list[Any]:
    child_table = get_table_name(child_table_cls)
    relationships: list[Any] = []
    for _parent_model, rels in discover_fk_relationships(domain).items():
        for rel in rels:
            if get_table_name(rel.child_model) == child_table:
                relationships.append(rel)
    return relationships


def _merge_cascade_ref_id(
    *,
    cascade_ref_prefix: _MergeCascadeRefPrefix,
    parent_table: SqlTableName,
    child_table: SqlTableName,
    cascade_index: int,
    action: _MergeCascadeAction,
) -> ServerPlanRefId:
    """Return the bounded physical relation identity for one merge cascade action."""
    logical_ref_id = ServerPlanRefId(
        f"{cascade_ref_prefix}.{parent_table}.{child_table}.{cascade_index}.{action}",
    )
    return physical_server_plan_ref_alias(logical_ref_id)


def _parent_cascade_publish_refs(
    domain: type[VersioningDomain],
    *,
    parent_model: type[VersionedObjectRow[Any]],
    cascade_ref_prefix: _MergeCascadeRefPrefix,
) -> frozenset[ServerPlanRefId]:
    parent_table = get_table_name(parent_model)
    refs: set[ServerPlanRefId] = set()
    for cascade_idx, rel in enumerate(_cascade_relationships_for_child(domain, parent_model)):
        grandparent_table = get_table_name(rel.parent_model)
        refs.update(
            _merge_cascade_ref_id(
                cascade_ref_prefix=cascade_ref_prefix,
                parent_table=grandparent_table,
                child_table=parent_table,
                cascade_index=cascade_idx,
                action=action,
            )
            for action in _MERGE_CASCADE_ACTIONS
        )
    return frozenset(refs)


def _fk_parent_tip_publish_refs(
    domain: type[VersioningDomain],
    *,
    child_model: type[VersionedObjectRow[Any]],
    tip_upsert_ref_prefix: str,
    cascade_ref_prefix: _MergeCascadeRefPrefix | None,
) -> frozenset[ServerPlanRefId]:
    refs: set[ServerPlanRefId] = set()
    for rel in _fk_relationships_for_child(domain, child_model):
        parent_table = get_table_name(rel.parent_model)
        refs.add(ServerPlanRefId(f"{tip_upsert_ref_prefix}.{parent_table}"))
        if cascade_ref_prefix is not None:
            refs.update(
                _parent_cascade_publish_refs(
                    domain,
                    parent_model=rel.parent_model,
                    cascade_ref_prefix=cascade_ref_prefix,
                ),
            )
    return frozenset(refs)


def _fk_parent_apply_refs(
    domain: type[VersioningDomain],
    *,
    child_model: type[VersionedObjectRow[Any]],
) -> frozenset[ServerPlanRefId]:
    refs: set[ServerPlanRefId] = set()
    for rel in _fk_relationships_for_child(domain, child_model):
        parent_table = get_table_name(rel.parent_model)
        refs.update(
            {
                ServerPlanRefId(f"merge.insert.{parent_table}"),
                ServerPlanRefId(f"merge.tip_delete.{parent_table}"),
                ServerPlanRefId(f"merge.tip_upsert.{parent_table}"),
            },
        )
    return frozenset(refs)


def _cascade_parent_tip_guards(
    domain: type[VersioningDomain],
    child_model: type[VersionedObjectRow[Any]],
) -> tuple[tuple[str, str, str], ...]:
    guards: list[tuple[str, str, str]] = []
    for rel in _cascade_relationships_for_child(domain, child_model):
        guards.append(
            (
                get_db_column_name(child_model, DynamicFieldName(rel.child_field)),
                str(get_versioned_table_names(rel.parent_model).tip),
                str(get_versioned_table_names(rel.parent_model).sparse),
            ),
        )
    return tuple(guards)


def _resolve_merge_cte_field(
    ctx: CompilationContext,
    ref_id: ServerPlanRefId,
    field_name: str,
) -> SqlRenderable:
    """Resolve a merge dependency to a CTE field expression."""
    return _require_cte_field(ctx, ref_id, field_name)


def _branch_tip_materialized_predicate(
    ctx: CompilationContext,
    branch_ref_id: ServerPlanRefId,
    *,
    materialized: bool,
) -> SqlRenderable:
    op = BinaryOp.EQ if materialized else BinaryOp.NE
    return SqlBinaryOp(
        _resolve_merge_cte_field(ctx, ServerPlanRefId(branch_ref_id), "tip_materialization"),
        op,
        SqlParam("materialized"),
    )


def _require_merge_scalar_or_row_field(
    ctx: CompilationContext,
    *,
    projected_scalar_ref_id: ServerPlanRefId,
    row_ref_id: ServerPlanRefId,
    row_field_name: str,
) -> SqlRenderable:
    """Prefer explicit scalar projection refs, else fall back to the row CTE field."""
    if projected_scalar_ref_id and projected_scalar_ref_id in ctx.cte_refs:
        return _require_merge_op_scalar(ctx, ServerPlanRefId(projected_scalar_ref_id))
    return _resolve_merge_cte_field(ctx, ServerPlanRefId(row_ref_id), row_field_name)


def _consumed_merge_scalar_or_row_cte(
    ctx: CompilationContext,
    *,
    projected_scalar_ref_id: str,
    row_ref_id: str,
) -> CteReference:
    """Return the exact SQL relation selected by ``_require_merge_scalar_or_row_field``."""
    from l2070_batching.compilation import CteReference

    selected_ref_id = projected_scalar_ref_id if projected_scalar_ref_id and projected_scalar_ref_id in ctx.cte_refs else row_ref_id
    binding = ctx.cte_refs.get(selected_ref_id)
    if not isinstance(binding, CteReference):
        msg = f"Merge scalar dependency {selected_ref_id!r} has no SQL-visible CTE binding."
        raise ProgrammingError(msg)
    return binding


@dataclass(frozen=True, slots=True)
class _FFBranchTipScalarRefIds:
    target_branch_sys_id: ScalarServerRef[BranchId]
    source_branch_sys_id: ScalarServerRef[BranchId]
    target_tip_revision_sys_id: ScalarServerRef[RevisionId | None]
    source_tip_revision_sys_id: ScalarServerRef[RevisionId]


def _ff_scalar_step_ref_ids(ref_prefix: str) -> tuple[str, str, str, str]:
    seed = sum((idx + 1) * ord(ch) for idx, ch in enumerate(ref_prefix))
    base = 800_000 + (seed % 10_000) * 10
    return (f"step_{base}", f"step_{base + 1}", f"step_{base + 2}", f"step_{base + 3}")


def build_fast_forward_branch_tip_scalar_projection_steps(
    *,
    ref_prefix: str,
    source_branch_ref_id: str,
    target_branch_ref_id: str,
) -> tuple[list[ServerPlanStep[Any]], _FFBranchTipScalarRefIds]:
    from impl.common.l2070_server_plan.steps.merge_three_way_steps import (
        _ProjectMergeOpMetadataScalarConfig,
        _ProjectMergeOpMetadataScalarStep,
    )

    (
        projected_target_branch_ref_id,
        projected_target_tip_ref_id,
        projected_source_tip_ref_id,
        projected_source_branch_ref_id,
    ) = _ff_scalar_step_ref_ids(ref_prefix)
    refs = _FFBranchTipScalarRefIds(
        target_branch_sys_id=ServerRefs.from_ref_id(
            ServerPlanRefId(projected_target_branch_ref_id),
            variant="scalar",
            type_hint=BranchId,
        ),
        source_branch_sys_id=ServerRefs.from_ref_id(
            ServerPlanRefId(projected_source_branch_ref_id),
            variant="scalar",
            type_hint=BranchId,
        ),
        target_tip_revision_sys_id=cast(
            "ScalarServerRef[RevisionId | None]",
            ServerRefs.from_ref_id(
                ServerPlanRefId(projected_target_tip_ref_id),
                variant="scalar",
            ),
        ),
        source_tip_revision_sys_id=ServerRefs.from_ref_id(
            ServerPlanRefId(projected_source_tip_ref_id),
            variant="scalar",
            type_hint=RevisionId,
        ),
    )
    steps: list[ServerPlanStep[Any]] = [
        _ProjectMergeOpMetadataScalarStep(
            ServerPlanRefId(projected_target_branch_ref_id),
            _ProjectMergeOpMetadataScalarConfig(
                row_ref_id=ServerPlanRefId(target_branch_ref_id),
                field_name="sys_id",
            ),
        ),
        _ProjectMergeOpMetadataScalarStep(
            ServerPlanRefId(projected_target_tip_ref_id),
            _ProjectMergeOpMetadataScalarConfig(
                row_ref_id=ServerPlanRefId(target_branch_ref_id),
                field_name="tip_revision_sys_id",
            ),
        ),
        _ProjectMergeOpMetadataScalarStep(
            ServerPlanRefId(projected_source_tip_ref_id),
            _ProjectMergeOpMetadataScalarConfig(
                row_ref_id=ServerPlanRefId(source_branch_ref_id),
                field_name="tip_revision_sys_id",
            ),
        ),
        _ProjectMergeOpMetadataScalarStep(
            ServerPlanRefId(projected_source_branch_ref_id),
            _ProjectMergeOpMetadataScalarConfig(
                row_ref_id=ServerPlanRefId(source_branch_ref_id),
                field_name="sys_id",
            ),
        ),
    ]
    return steps, refs


def _row_value(row: object, key: str, default: object = None) -> object:
    if isinstance(row, dict):
        return row.get(key, default)
    if hasattr(row, key):
        return getattr(row, key)
    row_get = getattr(row, "get", None)
    if callable(row_get):
        return row_get(key, default)
    row_getitem = getattr(row, "__getitem__", None)
    if callable(row_getitem):
        return row_getitem(key)
    return default


def _bool_result_from_raw_result(raw_result: RawResult, default: bool) -> bool:
    if raw_result and raw_result[0]:
        return bool(_row_value(raw_result[0], "__result", default))
    return default


def _compiled_bool_result(
    grammar: SqlRenderable,
    default: bool,
    *,
    auxiliary_ctes: list[tuple[str, Any]] | None = None,
) -> CompiledStep[bool]:
    from l2070_batching.compilation import CompiledStep as _CompiledStep
    from l2070_batching.output_shape import CompiledOutputShape, DeclaredResultRelation, synthetic_output_field

    output_shape = CompiledOutputShape((synthetic_output_field("__result"),))

    return _CompiledStep(
        output_shape=output_shape,
        result_relation=DeclaredResultRelation.from_output_shape(output_shape),
        grammar=grammar,
        needs_returning=True,
        column_type_hints=_bool_result_type_hints(),
        auxiliary_ctes=auxiliary_ctes,
        closed_post_op=scalar_column_post_op(
            "__result",
            default_value=default,
            use_default_on_empty=True,
            scalar_coercion=ScalarCoercionKind.BOOL,
        ),
    )


def _all_merge_table_models(
    domain: type[VersioningDomain],
) -> tuple[type[VersionedObjectRow[SysId]], ...]:
    """Return one ordered model per physical table included in a merge operation."""
    ordered = topological_sort_versioned_models(domain.all_versioned_models())
    models_by_table: dict[str, type[VersionedObjectRow[SysId]]] = {}
    for model in ordered:
        models_by_table.setdefault(get_table_name(model), model)
    return tuple(models_by_table.values())


def _resolve_selected_merge_table_models(
    domain: type[VersioningDomain],
    included_models: Sequence[type[VersionedObjectRow[SysId]]],
) -> tuple[type[VersionedObjectRow[SysId]], ...]:
    """Resolve the ordered set of domain models included in a merge operation."""
    ordered_models = list(_all_merge_table_models(domain))

    domain_table_names = {get_table_name(model) for model in ordered_models}
    included_table_names: set[str] = set()
    for model in included_models:
        if not issubclass(model, VersionedObjectRow):
            msg = f"Merge include list requires VersionedObjectRow types, got {model.__name__}"
            raise ProgrammingError(msg)
        table_name = get_table_name(model)
        if table_name not in domain_table_names:
            msg = f"Model {model.__name__} is not registered in versioning domain {domain.__name__}"
            raise ProgrammingError(msg)
        included_table_names.add(table_name)

    return tuple(model for model in ordered_models if get_table_name(model) in included_table_names)


def _literal_revision_result(
    resolved: RevisionId | None,
    source_branch_id_raw: str | None,
    target_branch_id_raw: str | None,
    target_tip_raw: str | None,
) -> CompiledStep[RevisionId | None] | None:
    from l2070_batching.compilation import CompiledStep as _CompiledStep

    if resolved is None and source_branch_id_raw is not None and target_branch_id_raw is not None and target_tip_raw is not None:
        return None

    return _CompiledStep(needs_returning=False, closed_post_op=literal_post_op(resolved))


def _literal_squash_merge_base_result(
