            column_type_hints=sql_assertion_column_type_hints(),
            model_cls=SqlAssertionRow,
            relation_contract=CteRelationContract.semantic_row(SqlAssertionRow),
            relation_role=self.cte_relation_role(),
            source_tables=None,
        )

    def compile(
        self: _ValidateSourceHasTipStep,
        ctx: CompilationContext,
    ) -> CompiledStep[None]:
        from impl.common.l2070_server_plan.steps._query_helper_compile import (
            _collect_auxiliary_ctes_from_consumed,
        )
        from l2070_batching.compilation import CompiledStep as _CompiledStep, CteReference
        from l2070_batching.output_shape import DeclaredResultRelation
        from impl.common.l2070_server_plan.steps._query_helper_compile import (
            _collect_auxiliary_ctes_from_consumed,
        )

        source_cte = ctx.cte_refs.get(self._source_ref_id)
        if source_cte is not None:
            output_shape = sql_assertion_output_shape()
            grammar = SqlDynamicSelectStmt(
                from_table=SqlTableName(source_cte.ref_id),
                columns=[
                    SqlColumnName("tip_revision_sys_id"),
                    SqlColumnName("name"),
                ],
            )

            return _CompiledStep(
                grammar=non_null_column_assertion_query(
                    grammar,
                    column="tip_revision_sys_id",
                    error_message="Source branch has no commits to merge",
                ),
                needs_returning=True,
                closed_post_op=CompiledPostOp.assert_result(
                    ResultAssertionSpec(
                        empty_result_code=AssertionResultCode.NOT_FOUND,
                        mappings=(
                            AssertionExceptionMapping(
                                code=AssertionResultCode.NOT_FOUND,
                                exc_type=BranchNotFoundError,
                                default_message=(
                                    f"Source branch {self._source_branch_name!s} not found"
                                    if self._source_branch_name is not None
                                    else "Source branch not found"
                                ),
                            ),
                            AssertionExceptionMapping(
                                code=AssertionResultCode.ERROR,
                                exc_type=ProgrammingError,
                                default_message="Source branch has no commits to merge",
                            ),
                        ),
                    ),
                ),
                output_shape=output_shape,
                result_relation=DeclaredResultRelation.from_output_shape(output_shape),
                column_type_hints=sql_assertion_column_type_hints(),
                auxiliary_ctes=_collect_auxiliary_ctes_from_consumed([source_cte]),
            )

        raise_missing_cte_fallback_forbidden(
            site_name=type(self).__name__,
            trigger=f"source-tip validation for {self._source_ref_id!r} without a SQL-visible CTE",
            blocked_path="runtime source-branch object inspection for merge validation",
            result_contract="source-tip validation must read the branch tip from a declared SQL relation",
            implementation_requirements=(
                "Publish the source branch lookup as an upstream CTE before validation.",
                "Project tip_revision_sys_id into a SQL assertion row.",
                "Do not inspect source branch runtime objects for this validation.",
            ),
        )


class _SquashMergeBaseProjectionRow(BaseModel):
    """Projected columns for squash-merge base resolution batching."""

    rev_id: str | None = None
    lca_rev_id: str | None = None
    target_tip: str | None = None


def _compile_squash_merge_base_projection(
    *,
    op_table: str,
    lca_expr: Any,
    target_tip_expr: Any,
    where_expr: Any,
    consumed_cte_refs: Sequence[CteReference],
    base_column: SqlColumnName = SqlColumnName("base_revision_sys_id"),
) -> CompiledStep[RevisionId | None]:
    from impl.common.l2070_server_plan.steps._query_helper_compile import (
        _collect_auxiliary_ctes_from_consumed,
    )
    from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName, SqlTableName
    from impl.common.l2100_sql_grammar.domain.infra.stmt_cte_helpers import SqlSelectExpressions
    from impl.common.l2100_sql_grammar.tree.clauses import (
        SqlFrom,
        SqlOrderByClause,
        SqlOrderByItem,
        SqlSelectList,
        SqlTableAlias,
        SqlWhereClause,
    )
    from impl.common.l2100_sql_grammar.tree.enums import OrderDirection
    from impl.common.l2100_sql_grammar.tree.expr_compound import SqlFuncCall, SqlSubquery
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef
    from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
    from impl.common.l2100_sql_grammar.tree.statements import SqlSelect
    from l2070_batching.compilation import CompiledStep as _CompiledStep
    from l2070_batching.output_shape import CompiledOutputShape, DeclaredResultRelation, synthetic_output_field

    base_query = SqlSelect(
        SqlSelectList(SqlColumnRef(base_column)),
        SqlFrom(SqlTableAlias(SqlTableIdent(SqlTableName(op_table)))),
        where=SqlWhereClause(where_expr),
        order_by=SqlOrderByClause(
            [
                SqlOrderByItem(
                    SqlColumnRef(SqlColumnName("sys_created_at")),
                    OrderDirection.DESC,
                ),
            ],
        ),
        limit=1,
    )

    base_revision_expr = SqlSubquery(base_query)
    effective_base_revision_expr = SqlFuncCall("COALESCE", (base_revision_expr, lca_expr))
    grammar = SqlSelectExpressions(
        [
            (effective_base_revision_expr, "rev_id"),
            (lca_expr, "lca_rev_id"),
            (target_tip_expr, "target_tip"),
        ],
    )
    columns = ("rev_id", "lca_rev_id", "target_tip")
    column_type_hints = SqlColumnTypeHints(uuid_columns=frozenset(columns))
    output_shape = CompiledOutputShape(tuple(synthetic_output_field(column) for column in columns))

    return _CompiledStep(
        output_shape=output_shape,
        result_relation=DeclaredResultRelation.from_output_shape(output_shape),
        grammar=grammar,
        needs_returning=True,
        column_type_hints=column_type_hints,
        auxiliary_ctes=_collect_auxiliary_ctes_from_consumed(consumed_cte_refs),
        closed_post_op=required_scalar_column_post_op(
            "rev_id",
            error_message="No common ancestor found",
            scalar_coercion=ScalarCoercionKind.REVISION_ID,
        ),
    )


