                ),
            ),
        )
        ff_data_steps.append(
            _FFCopySparseDataStep(
                ServerPlanRefId(f"merge.ff_copy_sparse_{tbl}"),
                _FFCopySparseDataConfig(
                    sparse_table=SqlTableName(sparse_tbl),
                    source_branch_ref_id=ServerPlanRefId("merge.source_branch"),
                    target_branch_ref_id=ServerPlanRefId("merge.target_branch"),
                    model=table_cls,
                    source_is_sparse=True,
                    dependency_ref_ids=(close_sparse_ref_id,),
                    require_source_tipless=True,
                ),
            ),
        )
        ff_data_steps.append(
            _FFCopySparseTipDataStep(
                ServerPlanRefId(f"merge.ff_copy_sparse_tip_{tbl}"),
                _FFCopyTipDataConfig(
                    tip_table=SqlTableName(tip_tbl),
                    source_branch_ref_id=ServerPlanRefId("merge.source_branch"),
                    target_branch_ref_id=ServerPlanRefId("merge.target_branch"),
                    model=table_cls,
                    require_target_materialized=True,
                ),
                domain=domain,
                source_revision=ff_tip_refs.source_tip_revision_sys_id,
                target_branch=ff_tip_refs.target_branch_sys_id,
            ),
