        if standard_merge_logs_enabled:
            ff_log_columns = _merge_data_columns(table_cls, merge_log_exclude)
            ff_data_steps.append(
                _FastForwardMergeInsertLogEntriesStep(
                    ref_id=ServerPlanRefId(f"merge.ff_log.{tbl}"),
                    config=_FastForwardMergeInsertLogEntriesConfig(
                        source_branch_ref_id=ServerPlanRefId("merge.source_branch"),
                        target_branch_ref_id=ServerPlanRefId("merge.target_branch"),
                        log_table=logged_table_name(tbl),
                        sparse_table=sparse_tbl,
                        data_columns=tuple(ff_log_columns),
                        session_id=session_id_ref,
                        revision_table=SqlTableName(revision_table),
                        revision_parents_table=SqlTableName(revision_parents_table),
                    ),
                ),
            )
    ff_data_tail_dependencies = frozenset({ff_data_steps[-1].ref_id}) if ff_data_steps else frozenset()
    ff_data_steps.extend(
        build_branch_tip_update_with_expected_tip_steps(
            ref_prefix="merge.ff_tip",
