    ff_insert_op = _FFInsertMergeOpStep(
        ref_id=ServerPlanRefId("merge.ff_insert_op"),
        config=_FFInsertMergeOpConfig(
            scalar_refs=op_meta_refs,
            op_table=SqlTableName(op_table),
            session_id=session_id_ref,
            op_id=ff_op_id_ref,
            strategy=strategy_value,
            depends_on=frozenset({ServerPlanRefId(ff_data_steps[-1].ref_id)}),
        ),
    )
    ff_result = _BuildFFResultStep(
        ref_id=ServerPlanRefId("merge.result_ff"),
        config=_BuildFFResultConfig(
            scalar_refs=op_meta_refs,
            op_id=ff_op_id_ref,
            depends_on=frozenset({ServerPlanRefId("merge.ff_insert_op")}),
