    )
    ff_data_steps.append(ff_insert_op)
    ff_data_steps.append(ff_result)
    if strategy_value == "three-way-no-ff":
        ff_gated_steps = []
    else:
        ff_gated_steps = _gate_branch_steps(
            condition_ref="merge.is_ff",
            branch_steps=ff_data_steps,
            force_non_batchable=(
                sqlite_force_non_batchable
                or ctx.backend_profile.traits.versioned_staging_transport is VersionedStagingTransport.SAME_STATEMENT_RELATION
            ),
            publish_ref_ids=frozenset({"merge.result_ff"}),
        )

    raise_diverged = _RaiseDivergedStep(ref_id=ServerPlanRefId("merge.raise_diverged"))
    cond_diverged_steps: list[ServerPlanStep[Any]]
    if strategy_value == "three-way-no-ff":
        cond_diverged_steps = []
    else:
        cond_diverged_steps = [
            build_one_sided_conditional(
                ref_id=ServerPlanRefId("merge.cond_diverged"),
                condition_ref=ServerPlanRefId("merge.is_diverged"),
                if_true_steps=[raise_diverged],
                default_value=None,
                force_prior_step_boundary=provider.force_conditional_prior_step_boundary(),
            ),
        ]

    diff_ref_ids: list[str] = []
    diff_ref_by_table: dict[str, str] = {}
    fk_conflict_diff_refs: list[tuple[str, str, tuple[str, ...]]] = []
    diff_steps: list[ServerPlanStep[Any]] = [
        FastForwardMergePermissionStep(
            ServerPlanRefId(f"merge.three_way_permission_{get_table_name(model)}"),
            domain=domain,
            model=model,
            source_branch_ref=op_meta_refs.source_branch_sys_id,
            target_branch_ref=op_meta_refs.target_branch_sys_id,
            source_tip_ref=op_meta_refs.source_tip_revision_sys_id,
            target_tip_ref=op_meta_refs.target_tip_revision_sys_id,
            base_revision_ref=op_meta_refs.base_revision_sys_id,
            session=session_id_ref,
        )
        for model in versioned_tables
        if not replay_actions_are_unconditional(model)
    ]
    for table_cls in versioned_tables:
        physical_tables = get_versioned_table_names(table_cls)
        table_name = physical_tables.base
        sparse_table = physical_tables.sparse
        data_columns = _merge_data_columns(table_cls, _VERSIONED_APPLY_EXCLUDE)
        diff_ref = f"merge.diff.{table_name}"
        diff_ref_ids.append(diff_ref)
        diff_ref_by_table[table_name] = diff_ref
        diff_steps.append(
            ThreeWayDiffStep(
                ref_id=ServerPlanRefId(diff_ref),
                config=_ThreeWayDiffConfig(
                    lca_ref_id=ServerPlanRefId("merge.lca"),
                    source_branch_ref_id=ServerPlanRefId("merge.source_branch"),
                    target_branch_ref_id=ServerPlanRefId("merge.target_branch"),
                    sparse_table=SqlTableName(sparse_table),
                    data_columns=tuple(data_columns),
                    revision_table=SqlTableName(revision_table),
                    revision_parents_table=SqlTableName(revision_parents_table),
                ),
            ),
        )
    for table_cls in versioned_tables:
        child_tables = get_versioned_table_names(table_cls)
        child_table = child_tables.base
        child_diff_ref = diff_ref_by_table[child_table]
        child_sparse_table = child_tables.sparse
        fk_data_columns = tuple(_merge_data_columns(table_cls, _VERSIONED_COMPARE_EXCLUDE))
        for cascade_idx, rel in enumerate(_cascade_relationships_for_child(domain, table_cls)):
            parent_table = get_table_name(rel.parent_model)
            parent_diff_ref = diff_ref_by_table.get(parent_table)
            if parent_diff_ref is None:
                continue
            fk_conflict_ref = str(
                physical_server_plan_ref_alias(
                    ServerPlanRefId(
                        f"merge.diff_fk_conflict.{parent_table}.{child_table}.{cascade_idx}",
                    ),
                    max_length=SqlIdentifierByteLimit(36),
                ),
            )
            diff_ref_ids.append(fk_conflict_ref)
            fk_conflict_diff_refs.append((fk_conflict_ref, child_table, fk_data_columns))
            diff_steps.append(
                _FkCascadeConflictDiffStep(
                    ref_id=ServerPlanRefId(fk_conflict_ref),
                    config=_FkCascadeConflictDiffConfig(
                        parent_diff_ref_id=ServerPlanRefId(parent_diff_ref),
                        child_diff_ref_id=ServerPlanRefId(child_diff_ref),
                        child_sparse_table=SqlTableName(child_sparse_table),
                        child_fk_column=SqlColumnName(get_db_column_name(table_cls, DynamicFieldName(rel.child_field))),
                        data_columns=fk_data_columns,
                    ),
                ),
            )
    conflict_table = get_table_name(MergeConflictRecord)
    has_conflicts: ServerPlanStep[bool]
    if resume_existing_op_id is None:
        has_conflicts = _HasConflictsFromDiffsStep(
            ref_id=ServerPlanRefId("merge.has_conflicts"),
            config=_HasConflictsFromDiffsConfig(
                diff_ref_ids=tuple(ServerPlanRefId(ref_id) for ref_id in diff_ref_ids),
            ),
        )
    else:
        has_conflicts = _HasUnresolvedMergeConflictsStep(
            ref_id=ServerPlanRefId("merge.has_conflicts"),
            config=_HasUnresolvedMergeConflictsConfig(
                conflict_table=SqlTableName(conflict_table),
                merge_op_id=cast("Any", merge_op_id),
            ),
        )
    conflict_count = _ConflictCountFromDiffsStep(
        ref_id=ServerPlanRefId("merge.conflict_count"),
        config=_ConflictCountFromDiffsConfig(
            diff_ref_ids=tuple(ServerPlanRefId(ref_id) for ref_id in diff_ref_ids),
        ),
    )
    if resume_existing_op_id is None:
        no_conflicts: ServerPlanStep[bool] = _NoConflictsFromDiffsStep(
            ref_id=ServerPlanRefId("merge.no_conflicts"),
            config=_HasConflictsFromDiffsConfig(
                diff_ref_ids=tuple(ServerPlanRefId(ref_id) for ref_id in diff_ref_ids),
                three_way_ref_id=ServerPlanRefId("merge.is_diverged"),
            ),
        )
    else:
        no_conflicts = _InvertBoolStep(
            ref_id=ServerPlanRefId("merge.no_conflicts"),
            config=_InvertBoolConfig(source_ref_id=ServerPlanRefId("merge.has_conflicts")),
        )

    conflict_insert_op = _InsertConflictMergeOpStep(
        ref_id=ServerPlanRefId("merge.conflict_insert_op"),
        config=_InsertConflictMergeOpConfig(
            scalar_refs=op_meta_refs,
            op_table=SqlTableName(op_table),
            session_id=session_id_ref,
            op_id=cast("Any", merge_op_id),
            diff_ref_ids=tuple(ServerPlanRefId(ref_id) for ref_id in diff_ref_ids),
            conflict_count_ref=ServerPlanRefId("merge.conflict_count"),
            strategy=strategy_value,
        ),
    )
    conflict_record_steps: list[ServerPlanStep[Any]] = []
    table_names: list[str] = []
    for table_cls in versioned_tables:
        physical_tables = get_versioned_table_names(table_cls)
        table_name = physical_tables.base
        sparse_table = physical_tables.sparse
        table_names.append(table_name)
        table_data_columns = _merge_data_columns(table_cls, _VERSIONED_COMPARE_EXCLUDE)
        conflict_record_steps.append(
            _InsertConflictRecordsStep(
                ref_id=ServerPlanRefId(f"merge.conflict_records.{table_name}"),
                config=_InsertConflictRecordsConfig(
                    lca_ref_id=ServerPlanRefId("merge.lca"),
                    source_branch_ref_id=ServerPlanRefId("merge.source_branch"),
                    target_branch_ref_id=ServerPlanRefId("merge.target_branch"),
                    merge_op_id=cast("Any", merge_op_id),
                    table_name=SqlTableName(table_name),
                    sparse_table=SqlTableName(sparse_table),
                    conflict_table=SqlTableName(conflict_table),
                    data_columns=tuple(table_data_columns),
                    json_columns=_merge_json_columns(table_cls, _VERSIONED_COMPARE_EXCLUDE),
                    revision_table=SqlTableName(revision_table),
                    revision_parents_table=SqlTableName(revision_parents_table),
                ),
            ),
        )
    for fk_conflict_ref, fk_child_table, fk_record_data_columns in fk_conflict_diff_refs:
        table_names.append(SqlTableName(fk_child_table))
        conflict_record_steps.append(
            _InsertConflictRecordsFromDiffRefStep(
                ref_id=ServerPlanRefId(f"merge.conflict_records.{fk_conflict_ref}"),
                config=_InsertConflictRecordsFromDiffRefConfig(
                    diff_ref_id=ServerPlanRefId(fk_conflict_ref),
                    merge_op_id=cast("Any", merge_op_id),
                    table_name=SqlTableName(fk_child_table),
                    conflict_table=SqlTableName(conflict_table),
                    data_columns=fk_record_data_columns,
                ),
            ),
        )
    conflict_result = _BuildConflictResultStep(
        ref_id=ServerPlanRefId("merge.result_conflict"),
        config=_BuildConflictResultConfig(
            source_branch_ref_id=ServerPlanRefId("merge.source_branch"),
            target_branch_ref_id=ServerPlanRefId("merge.target_branch"),
            lca_ref_id=ServerPlanRefId("merge.lca"),
            op_id=cast("Any", merge_op_id),
            diff_ref_ids=tuple(ServerPlanRefId(ref_id) for ref_id in diff_ref_ids),
            table_names=tuple(SqlTableName(table_name) for table_name in table_names),
        ),
    )
    conflict_path_steps = build_conflict_path_steps(
        conflict_insert_op,
        conflict_record_steps,
    )
    conflict_path_steps.append(conflict_result)
    conflict_gated_steps = _gate_branch_steps(
        condition_ref=("merge.has_conflicts" if strategy_value == "three-way-no-ff" else "merge.three_way_has_conflicts"),
        branch_steps=conflict_path_steps,
        force_non_batchable=sqlite_force_non_batchable,
        publish_ref_ids=frozenset({"merge.result_conflict"}),
    )

    insert_revision = _InsertMergeRevisionStep(
        ref_id=ServerPlanRefId("merge.insert_revision"),
        config=_InsertMergeRevisionConfig(
            revision_table=SqlTableName(revision_table),
            revision_model_cls=domain.revision_model,
            merge_revision_id=merge_revision_id_ref,
            session_id=session_id_ref,
            revision_metadata=rev_meta,
            parent_revision_ref_id=ServerPlanRefId("merge.target_branch"),
        ),
    )
    insert_parents = _InsertMergeParentsStep(
        ref_id=ServerPlanRefId("merge.insert_parents"),
        config=_InsertMergeParentsConfig(
            revision_parents_table=SqlTableName(revision_parents_table),
            merge_revision_id=merge_revision_id_ref,
            target_parent_sys_id=parent1_sys_id,
            source_parent_sys_id=parent2_sys_id,
            target_parent_revision_ref_id=ServerPlanRefId("merge.target_branch"),
            source_parent_revision_ref_id=ServerPlanRefId("merge.source_branch"),
        ),
    )
    apply_steps: list[ServerPlanStep[Any]] = []
    merge_log_steps: list[ServerPlanStep[Any]] = []
    for table_cls in versioned_tables:
        physical_tables = get_versioned_table_names(table_cls)
        table_name = physical_tables.base
        sparse_table = physical_tables.sparse
        tip_table = physical_tables.tip
        data_columns = _merge_data_columns(table_cls, _VERSIONED_APPLY_EXCLUDE)
        cascade_relationships = _cascade_relationships_for_child(domain, table_cls)
        close_ref = ServerPlanRefId(f"merge.close.{table_name}")
        apply_steps.append(
            _ApplyMergeCloseStep(
                ref_id=close_ref,
                config=_ApplyMergeCloseConfig(
                    lca_ref_id=ServerPlanRefId("merge.lca"),
                    source_branch_ref_id=ServerPlanRefId("merge.source_branch"),
                    target_branch_ref_id=ServerPlanRefId("merge.target_branch"),
                    merge_revision_id=merge_revision_id_ref,
                    sparse_table=SqlTableName(sparse_table),
                    data_columns=tuple(data_columns),
                    revision_table=SqlTableName(revision_table),
                    revision_parents_table=SqlTableName(revision_parents_table),
                ),
            ),
        )
        insert_ref = ServerPlanRefId(f"merge.insert.{table_name}")
        apply_steps.append(
            _ApplyMergeInsertStep(
                ref_id=insert_ref,
                config=_ApplyMergeInsertConfig(
                    lca_ref_id=ServerPlanRefId("merge.lca"),
                    source_branch_ref_id=ServerPlanRefId("merge.source_branch"),
                    target_branch_ref_id=ServerPlanRefId("merge.target_branch"),
                    merge_revision_id=merge_revision_id_ref,
                    sparse_table=SqlTableName(sparse_table),
                    data_columns=tuple(data_columns),
                    revision_table=SqlTableName(revision_table),
                    revision_parents_table=SqlTableName(revision_parents_table),
                    after_refs=frozenset({close_ref}),
                ),
            ),
        )
        from impl.common.l2070_server_plan.steps.merge_embedding_refs import (
            build_merge_embedding_ref_steps,
        )

        apply_steps.extend(
            build_merge_embedding_ref_steps(
                table_cls,
                _ApplyMergeInsertConfig(
                    lca_ref_id=ServerPlanRefId("merge.lca"),
                    source_branch_ref_id=ServerPlanRefId("merge.source_branch"),
                    target_branch_ref_id=ServerPlanRefId("merge.target_branch"),
                    merge_revision_id=merge_revision_id_ref,
                    sparse_table=SqlTableName(sparse_table),
                    data_columns=tuple(data_columns),
                    revision_table=SqlTableName(revision_table),
                    revision_parents_table=SqlTableName(revision_parents_table),
                    after_refs=frozenset({insert_ref}),
                ),
                prefix=f"merge.embedding_refs.{table_name}",
                planning_catalog=ctx.planning_catalog,
            )
        )
        for cascade_idx, rel in enumerate(cascade_relationships):
            parent_table = get_table_name(rel.parent_model)
            prior_refs = frozenset(
                {
                    insert_ref,
                    ServerPlanRefId(f"merge.insert.{parent_table}"),
                    ServerPlanRefId(f"merge.tip_delete.{parent_table}"),
                    ServerPlanRefId(f"merge.tip_upsert.{parent_table}"),
                    *_parent_cascade_publish_refs(domain, parent_model=rel.parent_model, cascade_ref_prefix="merge.cascade"),
                },
            )
            for action in _MERGE_CASCADE_ACTIONS:
                cascade_ref = _merge_cascade_ref_id(
                    cascade_ref_prefix="merge.cascade",
                    parent_table=parent_table,
                    child_table=table_name,
                    cascade_index=cascade_idx,
                    action=action,
                )
                apply_steps.append(
                    _ApplyMergeCascadeClosureStep(
                        ref_id=cascade_ref,
                        config=_ApplyMergeCascadeClosureConfig(
                            action=action,
                            target_branch_ref_id=ServerPlanRefId("merge.target_branch"),
                            merge_revision_id=merge_revision_id_ref,
                            parent_sparse_table=get_versioned_table_names(rel.parent_model).sparse,
                            parent_tip_table=get_versioned_table_names(rel.parent_model).tip,
                            child_sparse_table=SqlTableName(sparse_table),
                            child_tip_table=SqlTableName(tip_table),
                            child_fk_column=SqlColumnName(get_db_column_name(table_cls, DynamicFieldName(rel.child_field))),
                            data_columns=tuple(data_columns),
                            after_refs=prior_refs,
                        ),
                    ),
                )
                prior_refs = frozenset({cascade_ref})
        apply_steps.append(
            _ApplyMergeDeleteTipStep(
                ref_id=ServerPlanRefId(f"merge.tip_delete.{table_name}"),
                config=_ApplyMergeDeleteTipConfig(
                    lca_ref_id=ServerPlanRefId("merge.lca"),
                    source_branch_ref_id=ServerPlanRefId("merge.source_branch"),
                    target_branch_ref_id=ServerPlanRefId("merge.target_branch"),
                    sparse_table=SqlTableName(sparse_table),
                    tip_table=SqlTableName(tip_table),
                    data_columns=tuple(data_columns),
                    revision_table=SqlTableName(revision_table),
                    revision_parents_table=SqlTableName(revision_parents_table),
                ),
            ),
        )
        apply_steps.append(
            _ApplyMergeUpsertTipStep(
                ref_id=ServerPlanRefId(f"merge.tip_upsert.{table_name}"),
                config=_ApplyMergeUpsertTipConfig(
                    lca_ref_id=ServerPlanRefId("merge.lca"),
                    source_branch_ref_id=ServerPlanRefId("merge.source_branch"),
                    target_branch_ref_id=ServerPlanRefId("merge.target_branch"),
                    merge_revision_id=merge_revision_id_ref,
                    sparse_table=SqlTableName(sparse_table),
                    tip_table=SqlTableName(tip_table),
                    data_columns=tuple(data_columns),
                    revision_table=SqlTableName(revision_table),
                    revision_parents_table=SqlTableName(revision_parents_table),
                    after_refs=frozenset(
                        {
                            *_fk_parent_tip_publish_refs(
                                domain,
                                child_model=table_cls,
                                tip_upsert_ref_prefix="merge.tip_upsert",
                                cascade_ref_prefix="merge.cascade",
                            ),
                            *_fk_parent_apply_refs(domain, child_model=table_cls),
                        },
                    ),
                    parent_tip_guards=_cascade_parent_tip_guards(domain, table_cls),
                ),
            ),
        )
        if resume_existing_op_id is not None:
            resolved_cascade_tail_refs: set[ServerPlanRefId] = set()
            for cascade_idx, rel in enumerate(cascade_relationships):
                parent_table = get_table_name(rel.parent_model)
                prior_refs = frozenset(
                    {
                        insert_ref,
                        ServerPlanRefId(f"merge.insert.{parent_table}"),
                        ServerPlanRefId(f"merge.tip_delete.{parent_table}"),
                        ServerPlanRefId(f"merge.tip_upsert.{parent_table}"),
                        ServerPlanRefId(f"merge.resolved_close.{parent_table}"),
                        ServerPlanRefId(f"merge.resolved_insert.{parent_table}"),
                        ServerPlanRefId(f"merge.resolved_tip_delete.{parent_table}"),
                        ServerPlanRefId(f"merge.resolved_tip_upsert.{parent_table}"),
                        *_parent_cascade_publish_refs(domain, parent_model=rel.parent_model, cascade_ref_prefix="merge.cascade"),
                        *_parent_cascade_publish_refs(domain, parent_model=rel.parent_model, cascade_ref_prefix="merge.resolved_cascade"),
                    },
                )
                cascade_refs = tuple(
                    _merge_cascade_ref_id(
                        cascade_ref_prefix="merge.resolved_cascade",
                        parent_table=parent_table,
                        child_table=table_name,
                        cascade_index=cascade_idx,
                        action=action,
                    )
                    for action in _MERGE_CASCADE_ACTIONS
                )
                for action, cascade_ref in zip(_MERGE_CASCADE_ACTIONS, cascade_refs, strict=True):
                    apply_steps.append(
                        _ApplyMergeCascadeClosureStep(
                            ref_id=cascade_ref,
                            config=_ApplyMergeCascadeClosureConfig(
                                action=action,
                                target_branch_ref_id=ServerPlanRefId("merge.target_branch"),
                                merge_revision_id=merge_revision_id_ref,
                                parent_sparse_table=get_versioned_table_names(rel.parent_model).sparse,
                                parent_tip_table=get_versioned_table_names(rel.parent_model).tip,
                                child_sparse_table=SqlTableName(sparse_table),
                                child_tip_table=SqlTableName(tip_table),
                                child_fk_column=SqlColumnName(get_db_column_name(table_cls, DynamicFieldName(rel.child_field))),
                                data_columns=tuple(data_columns),
                                after_refs=prior_refs,
                            ),
                        ),
                    )
                    prior_refs = frozenset({cascade_ref})
                resolved_cascade_tail_refs.add(cascade_refs[-1])
            resolved_config = _ApplyResolvedConflictConfig(
                target_branch_ref_id=ServerPlanRefId("merge.target_branch"),
                merge_revision_id=merge_revision_id_ref,
                table_name=SqlTableName(table_name),
                sparse_table=SqlTableName(sparse_table),
                tip_table=SqlTableName(tip_table),
                conflict_table=SqlTableName(conflict_table),
                merge_op_id=cast("Any", merge_op_id),
                data_columns=tuple(data_columns),
                model_cls=table_cls,
                after_refs=frozenset(
                    {
                        ServerPlanRefId(f"merge.tip_upsert.{table_name}"),
                        *_fk_parent_apply_refs(domain, child_model=table_cls),
                        *resolved_cascade_tail_refs,
                    },
                ),
                parent_tip_guards=_cascade_parent_tip_guards(domain, table_cls),
            )
            resolved_close_ref = ServerPlanRefId(f"merge.resolved_close.{table_name}")
            apply_steps.append(
                _ApplyResolvedConflictStep(
                    ref_id=resolved_close_ref,
                    config=resolved_config,
                    action="close_sparse",
                ),
            )
            resolved_insert_ref = ServerPlanRefId(f"merge.resolved_insert.{table_name}")
            apply_steps.append(
                _ApplyResolvedConflictStep(
                    ref_id=resolved_insert_ref,
                    config=_ApplyResolvedConflictConfig(
                        target_branch_ref_id=ServerPlanRefId("merge.target_branch"),
                        merge_revision_id=merge_revision_id_ref,
                        table_name=SqlTableName(table_name),
                        sparse_table=SqlTableName(sparse_table),
                        tip_table=SqlTableName(tip_table),
                        conflict_table=SqlTableName(conflict_table),
                        merge_op_id=cast("Any", merge_op_id),
                        data_columns=tuple(data_columns),
                        model_cls=table_cls,
                        after_refs=frozenset(
                            {
                                resolved_close_ref,
                                *_fk_parent_apply_refs(domain, child_model=table_cls),
                            },
                        ),
                        parent_tip_guards=_cascade_parent_tip_guards(domain, table_cls),
                    ),
                    action="insert_sparse",
                ),
            )
            resolved_delete_ref = ServerPlanRefId(f"merge.resolved_tip_delete.{table_name}")
            apply_steps.append(
                _ApplyResolvedConflictStep(
                    ref_id=resolved_delete_ref,
                    config=_ApplyResolvedConflictConfig(
                        target_branch_ref_id=ServerPlanRefId("merge.target_branch"),
                        merge_revision_id=merge_revision_id_ref,
                        table_name=SqlTableName(table_name),
                        sparse_table=SqlTableName(sparse_table),
                        tip_table=SqlTableName(tip_table),
                        conflict_table=SqlTableName(conflict_table),
                        merge_op_id=cast("Any", merge_op_id),
                        data_columns=tuple(data_columns),
                        model_cls=table_cls,
                        after_refs=frozenset(
                            {
                                resolved_insert_ref,
                                *_fk_parent_apply_refs(domain, child_model=table_cls),
                            },
                        ),
                        parent_tip_guards=_cascade_parent_tip_guards(domain, table_cls),
                    ),
                    action="delete_tip",
                ),
            )
            apply_steps.append(
                _ApplyResolvedConflictStep(
                    ref_id=ServerPlanRefId(f"merge.resolved_tip_upsert.{table_name}"),
                    config=_ApplyResolvedConflictConfig(
                        target_branch_ref_id=ServerPlanRefId("merge.target_branch"),
                        merge_revision_id=merge_revision_id_ref,
                        table_name=SqlTableName(table_name),
                        sparse_table=SqlTableName(sparse_table),
                        tip_table=SqlTableName(tip_table),
                        conflict_table=SqlTableName(conflict_table),
                        merge_op_id=cast("Any", merge_op_id),
                        data_columns=tuple(data_columns),
                        model_cls=table_cls,
                        after_refs=frozenset(
                            {
                                resolved_delete_ref,
                                *_fk_parent_apply_refs(domain, child_model=table_cls),
                                *_fk_parent_tip_publish_refs(
                                    domain,
                                    child_model=table_cls,
                                    tip_upsert_ref_prefix="merge.resolved_tip_upsert",
                                    cascade_ref_prefix="merge.resolved_cascade",
                                ),
                            },
                        ),
                        parent_tip_guards=_cascade_parent_tip_guards(domain, table_cls),
                    ),
                    action="upsert_tip",
                ),
            )
        if standard_merge_logs_enabled:
            merge_log_columns = _merge_data_columns(table_cls, merge_log_exclude)
            merge_log_steps.append(
                _AppliedMergeInsertLogEntriesStep(
                    ref_id=ServerPlanRefId(f"merge.log.{table_name}"),
                    config=_AppliedMergeInsertLogEntriesConfig(
                        source_branch_ref_id=ServerPlanRefId("merge.source_branch"),
                        target_branch_ref_id=ServerPlanRefId("merge.target_branch"),
                        lca_ref_id=ServerPlanRefId("merge.lca"),
                        log_table=logged_table_name(table_name),
                        sparse_table=sparse_table,
                        data_columns=tuple(merge_log_columns),
                        session_id=session_id_ref,
                        publish_revision_id=merge_revision_id_ref,
                        revision_table=SqlTableName(revision_table),
                        revision_parents_table=SqlTableName(revision_parents_table),
                    ),
                ),
            )
    index_table = get_table_name(domain.revision_branch_index_model)
    demote_tip = _DemoteMergeBranchTipStep(
        ref_id=ServerPlanRefId("merge.demote_tip"),
        config=_DemoteMergeBranchTipConfig(
            index_table=SqlTableName(index_table),
            target_branch_ref_id=ServerPlanRefId("merge.target_branch"),
        ),
    )
    insert_index = _InsertMergeBranchIndexStep(
        ref_id=ServerPlanRefId("merge.insert_index"),
        config=_InsertMergeBranchIndexConfig(
            index_table=SqlTableName(index_table),
            merge_revision_id=merge_revision_id_ref,
            target_branch_ref_id=ServerPlanRefId("merge.target_branch"),
        ),
    )
    update_tip = _UpdateMergeBranchTipStep(
        ref_id=ServerPlanRefId("merge.update_tip"),
        config=_UpdateMergeBranchTipConfig(
            branch_table=SqlTableName(branch_table),
            merge_revision_id=merge_revision_id_ref,
            target_branch_ref_id=ServerPlanRefId("merge.target_branch"),
        ),
    )
    insert_merge_op = _InsertCleanMergeOpStep(
        ref_id=ServerPlanRefId("merge.insert_merge_op"),
        config=_InsertCleanMergeOpConfig(
            scalar_refs=op_meta_refs,
            op_table=SqlTableName(op_table),
            session_id=session_id_ref,
            op_id=cast("Any", merge_op_id),
            merge_revision_id=merge_revision_id_ref,
            strategy=strategy_value,
        ),
    )
    update_existing_merge_op = _UpdateExistingMergeOpStep(
        ref_id=ServerPlanRefId("merge.update_existing_merge_op"),
        config=_UpdateExistingMergeOpConfig(
            scalar_refs=op_meta_refs,
            op_table=SqlTableName(op_table),
            op_id=cast("Any", merge_op_id),
            merge_revision_id=merge_revision_id_ref,
            strategy=strategy_value,
        ),
    )
    build_result = _BuildCleanMergeResultStep(
        ref_id=ServerPlanRefId("merge.result_three_way"),
        config=_BuildCleanMergeResultConfig(
            source_branch_ref_id=ServerPlanRefId("merge.source_branch"),
            target_branch_ref_id=ServerPlanRefId("merge.target_branch"),
            lca_ref_id=ServerPlanRefId("merge.lca"),
            merge_revision_id=merge_revision_id_ref,
            op_id=cast("Any", merge_op_id),
            diff_ref_ids=tuple(ServerPlanRefId(ref_id) for ref_id in diff_ref_ids),
        ),
    )
    clean_merge_steps: list[ServerPlanStep[Any]] = [
        insert_revision,
        insert_parents,
        *apply_steps,
        *merge_log_steps,
        demote_tip,
        insert_index,
        update_tip,
        *build_clean_completion_steps(insert_merge_op, update_existing_merge_op),
        build_result,
    ]
    clean_gated_steps = _gate_branch_steps(
        condition_ref=("merge.no_conflicts" if strategy_value == "three-way-no-ff" else "merge.three_way_no_conflicts"),
        branch_steps=clean_merge_steps,
        force_non_batchable=sqlite_force_non_batchable,
        publish_ref_ids=frozenset({"merge.result_three_way"}),
    )
    if strategy_value == "three-way-no-ff":
        three_way_prelude_steps = [*diff_steps, has_conflicts, conflict_count, no_conflicts]
    else:
        from impl.common.l2070_server_plan.steps.versioned_lazy_support import BoolAndStep

        # Diff construction is a pure relational prelude and is safe for every
        # merge shape. Planning it unconditionally keeps all diff/count CTEs
        # available to both mutation branches. The explicit conjunctions below
        # gate side effects to the three-way path without hiding producer refs
        # behind runtime conditionals.
        three_way_prelude_steps = [
            *diff_steps,
            has_conflicts,
            conflict_count,
            no_conflicts,
            BoolAndStep(
                ServerPlanRefId("merge.three_way_has_conflicts"),
                left_ref="merge.is_three_way",
                right_ref="merge.has_conflicts",
            ),
            BoolAndStep(
                ServerPlanRefId("merge.three_way_no_conflicts"),
                left_ref="merge.is_three_way",
                right_ref="merge.no_conflicts",
            ),
        ]
    merge_result_refs = (
        (
            ServerPlanRefId("merge.result_conflict"),
            ServerPlanRefId("merge.result_three_way"),
        )
        if strategy_value == "three-way-no-ff"
        else (
            ServerPlanRefId("merge.result_utd"),
            ServerPlanRefId("merge.result_ff"),
            ServerPlanRefId("merge.result_conflict"),
            ServerPlanRefId("merge.result_three_way"),
        )
    )
    merge_auxiliary_steps: list[ServerPlanStep[Any]] = []
    if domain.graphs:
        from impl.common.l2070_server_plan.steps.barrier import BarrierStep
        from impl.common.l2070_server_plan.steps.commit_branch_steps import ReconcileGraphAuxiliaryTablesStep
        from impl.common.l2070_server_plan.steps.edge_constraint_steps import CheckDirtyGraphTreeValidityStep
        from l2070_batching.staged_source import PublishScopeDescriptor, opaque_scope_token
        from l9600_graphs.incremental_validation_models import (
            ContainsTreeComponentTip,
            ContainsTreeStateTip,
            GraphVisibleNodeTip,
            tree_edge_state_scopes,
        )

        target_branch_ref = ff_tip_refs.target_branch_sys_id
        merge_boundary_ref = ServerPlanRefId("merge.auxiliary_boundary")
        merge_auxiliary_steps.append(
            BarrierStep(
                merge_boundary_ref,
                depends_on=frozenset(merge_result_refs),
                requires_prior_boundary=True,
            ),
        )
        previous_auxiliary_clear_ref = merge_boundary_ref
        tree_scopes = tree_edge_state_scopes(domain)
        # Full-tip validation uses upserts. Clear each scope first so paths that
        # disappeared from the merged tip cannot survive in auxiliary state.
        for index, scope in enumerate(tree_scopes):
            for table_suffix, auxiliary_table_name in (
                ("state", "sys_contains_tree_state_tip"),
                ("component", "sys_contains_tree_component_tip"),
            ):
                clear_ref = ServerPlanRefId(f"merge.clear_tree_{table_suffix}_{index}")
                merge_auxiliary_steps.append(
                    _DeleteGraphTreeAuxiliaryScopeStep(
                        clear_ref,
                        branch=target_branch_ref,
                        branch_row_ref_id=ServerPlanRefId("merge.target_branch"),
                        table=SqlTableName(auxiliary_table_name),
                        tree_scope_key=_GraphTreeScopeKey(scope.tree_state_scope_key),
                        depends_on=previous_auxiliary_clear_ref,
                    ),
                )
                previous_auxiliary_clear_ref = clear_ref
        validation_dependencies = frozenset({previous_auxiliary_clear_ref})
        full_tip_scope = PublishScopeDescriptor(
            kind="explicit",
            branch_scope_token=opaque_scope_token(target_branch_ref),
            staged_commit_ids=(),
        )
        for index, scope in enumerate(tree_scopes):
            validation_ref = ServerPlanRefId(f"merge.validate_tree_{index}")
            edge_tip_table = derive_versioned_table_names(
                VersionedBaseTableName(scope.edge_table_name),
            ).tip
            merge_auxiliary_steps.append(
                CheckDirtyGraphTreeValidityStep(
                    validation_ref,
                    edge_tip_table=edge_tip_table,
                    edge_staged_table=edge_tip_table,
                    edge_base_table=SqlTableName(scope.edge_table_name),
                    lazy_branch=target_branch_ref,
                    publish_scope=full_tip_scope,
                    depends_on=validation_dependencies,
                    type_name_filter=scope.type_name_filter,
                    validate_full_tip=True,
                    branch_lookup=(SqlTableName(branch_table), workspace_id, target_branch_name),
                ),
            )
            validation_dependencies = frozenset({validation_ref})
        validation_boundary_ref = ServerPlanRefId("merge.tree_validation_boundary")
        merge_auxiliary_steps.append(
            BarrierStep(
                validation_boundary_ref,
                depends_on=validation_dependencies,
                requires_prior_boundary=True,
            ),
        )
        previous_ref = validation_boundary_ref
        reconcile_ref = ServerPlanRefId("merge.reconcile_graph_auxiliary")
        merge_auxiliary_steps.append(
            ReconcileGraphAuxiliaryTablesStep(
                reconcile_ref,
                domain=domain,
                branch_ref=cast("Any", ff_tip_refs.target_branch_sys_id),
                depends_on=frozenset({previous_ref}),
            ),
        )
        previous_ref = reconcile_ref
        for mode, candidate_success_results, update_conflicts in (("ff", ((ServerPlanRefId("merge.result_ff"), "fast_forward"),), True),):
            success_results = tuple(result for result in candidate_success_results if result[0] in merge_result_refs)
            if not success_results:
                continue
            for auxiliary_model, identity_columns in (
                (GraphVisibleNodeTip, ("graph_sys_id", "node_sys_id")),
                (
                    ContainsTreeComponentTip,
                    ("graph_sys_id", "edge_table_name", "component_root_sys_id"),
                ),
                (ContainsTreeStateTip, ("graph_sys_id", "edge_table_name", "node_sys_id")),
            ):
                auxiliary_table = get_table_name(auxiliary_model)
                overlay_ref = ServerPlanRefId(f"merge.{mode}_overlay_{auxiliary_table}")
                merge_auxiliary_steps.append(
                    _FFOverlayAuxiliaryDataStep(
                        overlay_ref,
                        _FFOverlayAuxiliaryDataConfig(
                            table=SqlTableName(auxiliary_table),
                            model=auxiliary_model,
                            identity_columns=identity_columns,
                            source_branch=ff_tip_refs.source_branch_sys_id,
                            target_branch=ff_tip_refs.target_branch_sys_id,
                            success_results=success_results,
                            update_conflicts=update_conflicts,
                            depends_on=frozenset({previous_ref}),
                        ),
                    ),
                )
                previous_ref = overlay_ref
    collector = _MergeResultCollectorStep(
        ref_id=ServerPlanRefId(result_ref_id),
        config=_MergeResultCollectorConfig(result_refs=merge_result_refs),
    )
    return [
        source_branch_guard,
        target_branch_guard,
        fetch_source,
        fetch_target,
        validate_source,
        find_lca,
        *op_meta_steps,
        classify,
        extract_utd,
        extract_ff,
        extract_diverged,
        extract_three_way,
        *utd_gated_steps,
        *cond_diverged_steps,
        *ff_tip_projection_steps,
        *ff_gated_steps,
        *three_way_prelude_steps,
        *conflict_gated_steps,
        *clean_gated_steps,
        *merge_auxiliary_steps,
        collector,
    ]


class AbortMergeIntent(IntentStep[None]):
    """L4: Abort a merge operation and clear its conflicts.

    Lowers to L0 steps that:
    1. Validate the operation exists and is in a cancellable state
    2. Delete all conflict records for the operation
    3. Update operation status to ABORTED
    """

    intent_tags = frozenset({"merge", "abort", "intent"})

    __slots__ = ("_domain", "_operation_id", "_session_id")

    def __init__(
        self: AbortMergeIntent,
        ref_id: ServerPlanRefId,
        *,
        domain: type[VersioningDomain],
        operation_id: ScalarServerRef[SysId],
    ) -> None:
        super().__init__(ref_id)
        self._domain = domain
        self._operation_id = _require_seeded_ref(
            operation_id,
            owner=type(self).__name__,
            field_name="operation_id",
        )

    def lower(
        self: AbortMergeIntent,
        ctx: LoweringContext,
    ) -> Sequence[ServerPlanStep[Any]]:
        from impl.common.l2060_query_spec.query_spec import QuerySpec
        from impl.common.l2070_server_plan.steps.query_delete import (
            QueryDeleteStep,
            _QueryDeleteStepConfig,
        )
        from impl.common.l2070_server_plan.steps.query_update import (
            QueryUpdateStep,
            _QueryUpdateStepConfig,
        )
        from l1000_schema.table_utils import get_table_name
        from l2060_query_builder.query_contracts import QueryFilter

        op_id = self._operation_id
        op_id_unwrap = getattr(op_id, "unwrap_to_str", None)
        op_id_filter_value = str(op_id_unwrap() if callable(op_id_unwrap) else op_id)
        op_table = get_table_name(MergeOperation)

        # Step 1: Fetch the merge operation, validate it exists and is cancellable.
        step1: ServerPlanStep[None] = _ValidateCancellableStep(
            ref_id=ServerPlanRefId("abort_merge.fetch_op"),
            config=_ValidateCancellableConfig(
                operation_id=op_id,
                op_table=SqlTableName(op_table),
            ),
        )

        # Step 2: Delete all conflict records for this operation (depends on step 1).
        delete_spec = QuerySpec(
            model_cls=MergeConflictRecord,
            select_columns=None,
            distinct=False,
            joins=[],
            filters=[QueryFilter(column="merge_operation_sys_id", operator="=", value=op_id_filter_value)],
            order_by=[],
            limit=None,
            offset=None,
            group_by=[],
            aggregations=[],
            having=[],
            window_functions=[],
            permission_grammar=None,
        )
        step2 = QueryDeleteStep(
            ref_id=ServerPlanRefId("abort_merge.delete_conflicts"),
            model_cls=MergeConflictRecord,
            config=_QueryDeleteStepConfig(
                query_spec=delete_spec,
                after_refs=frozenset({ServerPlanRefId("abort_merge.fetch_op")}),
            ),
        )

        # Step 3: Update operation status to ABORTED (depends on step 2)
        update_spec = QuerySpec(
            model_cls=MergeOperation,
            select_columns=None,
            distinct=False,
            joins=[],
            filters=[QueryFilter(column="sys_id", operator="=", value=op_id_filter_value)],
            order_by=[],
            limit=None,
            offset=None,
            group_by=[],
            aggregations=[],
            having=[],
            window_functions=[],
            permission_grammar=None,
        )
        step3 = QueryUpdateStep(
            ref_id=self.ref_id,
            model_cls=MergeOperation,
            config=_QueryUpdateStepConfig(
                query_spec=update_spec,
                updates={"status": "aborted"},
                after_refs=frozenset({ServerPlanRefId("abort_merge.delete_conflicts")}),
            ),
        )

        return [step1, step2, step3]


def _resolve_status_filter(
    status_filter: frozenset[MergeConflictStatusName] | ServerRef[Any],
) -> frozenset[str]:
    """Resolve a status-filter arg that may be either a frozenset or a seeded ServerRef."""
    if isinstance(status_filter, ServerRef):
        status_shape: PlanningServerValueShape = inspect_server_value_shape_for_planning(
            status_filter,
            site="_resolve_status_filter",
        )
        ref_id = status_shape.symbolic_ref_id
        if ref_id is None:
            msg = "status_filter ServerRef is not seeded at lowering time; pass a frozenset or seed one through ServerRefs.object(...)."
            raise ProgrammingError(msg)
        found, resolved = read_seeded_constant_from_ctx(None, ServerPlanRefId(ref_id))
        if not found:
            msg = "status_filter ServerRef is not seeded at lowering time; pass a frozenset or seed one through ServerRefs.object(...)."
            raise ProgrammingError(msg)
        status_filter = cast("frozenset[MergeConflictStatusName]", resolved)
    return frozenset(status_filter)


class ListConflictsByOperationIntent(IntentStep[list[MergeConflictView]]):
    """L4: List conflicts for a merge operation.

    Lowers to L0 steps that:
    1. Optionally resolve operation_id from merge_revision_id
    2. SELECT conflicts filtered by operation_id and optional status
    3. Hydrate into MergeConflictView objects in post_op
    """

    intent_tags = frozenset({"merge", "conflict", "read", "intent"})
    intent_cardinality = Cardinality.MANY
    intent_read_only = True

    __slots__ = (
        "_domain",
        "_operation_id",
        "_status_filter",
    )

    def __init__(
        self: ListConflictsByOperationIntent,
        ref_id: ServerPlanRefId,
        *,
        domain: type[VersioningDomain],
        operation_id: ScalarServerRef[SysId],
        status_filter: ObjectServerRef[frozenset[MergeConflictStatusName]],
    ) -> None:
        super().__init__(ref_id)
        self._domain = domain
        self._operation_id = _require_seeded_ref(
            operation_id,
            owner=type(self).__name__,
            field_name="operation_id",
        )
        self._status_filter = _require_seeded_ref(
            status_filter,
            owner=type(self).__name__,
            field_name="status_filter",
        )

    def lower(
        self: ListConflictsByOperationIntent,
        ctx: LoweringContext,
    ) -> Sequence[ServerPlanStep[Any]]:
        from impl.common.l2070_server_plan.steps.conflict_resolution_steps import (
            FetchConflictsByOpIdStep,
            _ConflictQueryConfig,
        )

        conflict_table = get_table_name(MergeConflictRecord)
        status_filter = _resolve_status_filter(self._status_filter)
        fetch_by_op_id = FetchConflictsByOpIdStep(
            ref_id=self.ref_id,
            conflict_table=SqlTableName(conflict_table),
            op_id_raw=self._operation_id,
            config=_ConflictQueryConfig(
                status_filter=status_filter,
            ),
        )
        return [fetch_by_op_id]


class ListConflictsByRevisionIntent(IntentStep[list[MergeConflictView]]):
    """L4: List conflicts by resolving a merge operation from a merge revision."""

    intent_tags = frozenset({"merge", "conflict", "read", "intent"})
    intent_cardinality = Cardinality.MANY
    intent_read_only = True

    __slots__ = (
        "_domain",
        "_merge_revision_id",
        "_status_filter",
    )

    def __init__(
        self: ListConflictsByRevisionIntent,
        ref_id: ServerPlanRefId,
        *,
        domain: type[VersioningDomain],
        merge_revision_id: ScalarServerRef[RevisionId],
        status_filter: ObjectServerRef[frozenset[MergeConflictStatusName]],
    ) -> None:
        super().__init__(ref_id)
        self._domain = domain
        self._merge_revision_id = _require_seeded_ref(
            merge_revision_id,
            owner=type(self).__name__,
            field_name="merge_revision_id",
        )
        self._status_filter = _require_seeded_ref(
            status_filter,
            owner=type(self).__name__,
            field_name="status_filter",
        )

    def lower(
        self: ListConflictsByRevisionIntent,
        ctx: LoweringContext,
    ) -> Sequence[ServerPlanStep[Any]]:
        from impl.common.l2070_server_plan.steps.conflict_resolution_steps import (
            FetchConflictsByResolvedOpStep,
            ResolveOpFromRevisionIdStep,
            _ConflictQueryConfig,
        )

        del ctx
        conflict_table = get_table_name(MergeConflictRecord)
