                _ApplyMergeUpsertTipStep(
                    ref_id=ServerPlanRefId(f"squash_merge.upsert_tip.{table_name}"),
                    config=_ApplyMergeUpsertTipConfig(
                        lca_ref_id=ServerPlanRefId("squash_merge.base"),
                        source_branch_ref_id=ServerPlanRefId("squash_merge.source_branch"),
                        target_branch_ref_id=ServerPlanRefId("squash_merge.target_branch"),
