def _build_squash_insert_revision_with_shaped_message(
    *,
    ref_id: ServerPlanRefId,
    domain: type[VersioningDomain],
    revision_table: SqlTableName,
    result_revision_id: ScalarServerRef[RevisionId],
    parent_revision_id: ScalarServerRef[RevisionId],
    session_id: ScalarServerRef[SessionId],
    revision_metadata: RevisionMetadataItems,
    branch_ref_id: ServerPlanRefId,
) -> ServerPlanStep[RevisionId]:
    from impl.common.l2070_server_plan.steps.squash_steps import (
        InsertExplicitParentRevisionWithMetadataStep,
        RevisionParentType,
        _InsertExplicitParentRevisionWithMetadataConfig,
    )

    del branch_ref_id
    return InsertExplicitParentRevisionWithMetadataStep(
        ref_id=ref_id,
        config=_InsertExplicitParentRevisionWithMetadataConfig(
            revision_table=revision_table,
            revision_model_cls=domain.revision_model,
            result_revision_id=result_revision_id,
            parent_revision_id=parent_revision_id,
            parent_type=RevisionParentType("squash"),
            session_id=session_id,
            revision_metadata=revision_metadata,
        ),
    )


def _build_squash_insert_revision_with_default_message(
    *,
    ref_id: ServerPlanRefId,
    domain: type[VersioningDomain],
    revision_table: SqlTableName,
    result_revision_id: ScalarServerRef[RevisionId],
    parent_revision_id: ScalarServerRef[RevisionId],
    session_id: ScalarServerRef[SessionId],
    revision_metadata: RevisionMetadataItems,
