        InsertExplicitParentRevisionWithDefaultMessageStep,
        RevisionParentType,
        _InsertExplicitParentRevisionWithDefaultMessageConfig,
    )

    filtered_metadata = _revision_metadata_without_message(revision_metadata)
    return InsertExplicitParentRevisionWithDefaultMessageStep(
        ref_id=ref_id,
        config=_InsertExplicitParentRevisionWithDefaultMessageConfig(
            revision_table=revision_table,
            revision_model_cls=domain.revision_model,
            result_revision_id=result_revision_id,
            parent_revision_id=parent_revision_id,
            parent_type=RevisionParentType("squash"),
            session_id=session_id,
            revision_metadata=filtered_metadata,
            default_message_branch_ref_id=branch_ref_id,
        ),
    )


def _build_squash_branch_plan(
    *,
    result_ref_id: str,
    domain: type[VersioningDomain],
    result_revision_id_ref: ScalarServerRef[RevisionId],
    base_revision_id: ScalarServerRef[RevisionId],
    fetch_branch: ServerPlanStep[Any],
    insert_revision: ServerPlanStep[RevisionId],
    ctx: LoweringContext,
) -> Sequence[ServerPlanStep[Any]]:
    from impl.common.l2070_server_plan.provider_helpers import (
        require_versioned_lowering_provider,
    )
    from impl.common.l2070_server_plan.steps.merge_three_way_steps import (
        _InvertBoolConfig,
        _InvertBoolStep,
        _ProjectMergeOpMetadataScalarConfig,
        _ProjectMergeOpMetadataScalarStep,
    )
    from impl.common.l2070_server_plan.steps.rebase_steps import (
        _RebaseDemoteTipConfig,
        _RebaseDemoteTipStep,
        _RebaseInsertBranchIndexConfig,
        _RebaseInsertBranchIndexStep,
        _RebaseUpdateBranchTipConfig,
        _RebaseUpdateBranchTipStep,
    )
    from impl.common.l2070_server_plan.steps.squash_steps import (
        ApplySquashBranchCloseStep,
        ApplySquashBranchDeleteTipStep,
        ApplySquashBranchInsertStep,
        ApplySquashBranchUpsertTipStep,
        InsertExplicitRevisionParentStep,
        IsSquashBranchNoOpStep,
        ProjectSquashBranchResultStep,
        ResolveSquashBaseRevisionStep,
        RevisionParentOrdinal,
        RevisionRelationshipType,
        SelectSquashBranchResultStep,
        ValidateBranchTipExistsStep,
        ValidateLinearRevisionRangeStep,
        ValidateRevisionAncestorStep,
    )

    branch_table = get_table_name(domain.branch_model)
    revision_table = get_table_name(domain.revision_model)
    revision_parents_table = get_table_name(domain.revision_parent_model)
    index_table = get_table_name(domain.revision_branch_index_model)

    sqlite_force_non_batchable = require_versioned_lowering_provider(
        ctx,
    ).force_non_batchable_merge_plan()
    squash_parent_id = SysId(str(uuid7()))

    def _ref(suffix: str) -> str:
        return f"{result_ref_id}.{suffix}"

    branch_sys_scalar_ref_id = ServerPlanRefId(
        f"step_{zlib.adler32(f'{result_ref_id}.branch_sys_id'.encode())}",
    )

    proj_branch_sys = _ProjectMergeOpMetadataScalarStep(
        branch_sys_scalar_ref_id,
        _ProjectMergeOpMetadataScalarConfig(
            row_ref_id=ServerPlanRefId(_ref("branch")),
            field_name="sys_id",
        ),
    )
    proj_branch_tip = _ProjectMergeOpMetadataScalarStep(
        ServerPlanRefId(_ref("sql.branch_tip")),
        _ProjectMergeOpMetadataScalarConfig(
            row_ref_id=ServerPlanRefId(_ref("branch")),
            field_name="tip_revision_sys_id",
        ),
    )
    validate_tip = ValidateBranchTipExistsStep(
        ref_id=ServerPlanRefId(_ref("validate_tip")),
        branch_ref_id=ServerPlanRefId(_ref("branch")),
    )
    resolve_base_revision = ResolveSquashBaseRevisionStep(
        ref_id=ServerPlanRefId(_ref("base_revision")),
        base_revision_id=base_revision_id,
    )
    is_noop = IsSquashBranchNoOpStep(
        ref_id=ServerPlanRefId(_ref("is_noop")),
        branch_ref_id=ServerPlanRefId(_ref("branch")),
        base_revision_id=base_revision_id,
    )
    should_apply = _InvertBoolStep(
        ref_id=ServerPlanRefId(_ref("should_apply")),
        config=_InvertBoolConfig(
            source_ref_id=ServerPlanRefId(_ref("is_noop")),
        ),
    )
    validate_ancestor = ValidateRevisionAncestorStep(
        ref_id=ServerPlanRefId(_ref("validate_ancestor")),
        branch_tip_scalar_ref_id=ServerPlanRefId(_ref("sql.branch_tip")),
        base_revision_id=base_revision_id,
        revision_parents_table=SqlTableName(revision_parents_table),
    )
    validate_linear = ValidateLinearRevisionRangeStep(
        ref_id=ServerPlanRefId(_ref("validate_linear")),
        branch_tip_scalar_ref_id=ServerPlanRefId(_ref("sql.branch_tip")),
        base_revision_id=base_revision_id,
        revision_parents_table=SqlTableName(revision_parents_table),
    )
    insert_parent = InsertExplicitRevisionParentStep(
        ref_id=ServerPlanRefId(_ref("insert_parent")),
        revision_parents_table=SqlTableName(revision_parents_table),
        result_revision_id=result_revision_id_ref,
        parent_revision_id=base_revision_id,
        relationship_type=RevisionRelationshipType("squash"),
        ordinal=RevisionParentOrdinal(0),
        parent_sys_id=squash_parent_id,
    )

    apply_steps: list[ServerPlanStep[Any]] = []
    for table_cls in _all_merge_table_models(domain):
        physical_tables = get_versioned_table_names(table_cls)
        table_name = physical_tables.base
        sparse_table = physical_tables.sparse
        tip_table = physical_tables.tip
        data_columns = _merge_data_columns(table_cls, _VERSIONED_APPLY_EXCLUDE)
        apply_steps.extend(
            [
                ApplySquashBranchCloseStep(
                    ref_id=ServerPlanRefId(_ref(f"close.{table_name}")),
                    branch_ref_id=ServerPlanRefId(_ref("branch")),
                    branch_sys_scalar_ref_id=branch_sys_scalar_ref_id,
                    branch_tip_scalar_ref_id=ServerPlanRefId(_ref("sql.branch_tip")),
                    base_revision_ref_id=ServerPlanRefId(_ref("base_revision")),
                    result_revision_id=result_revision_id_ref,
                    sparse_table=SqlTableName(sparse_table),
                    data_columns=[SqlColumnName(name) for name in data_columns],
                    revision_table=SqlTableName(revision_table),
                    revision_parents_table=SqlTableName(revision_parents_table),
                ),
                ApplySquashBranchInsertStep(
                    ref_id=ServerPlanRefId(_ref(f"insert.{table_name}")),
                    branch_ref_id=ServerPlanRefId(_ref("branch")),
                    branch_sys_scalar_ref_id=branch_sys_scalar_ref_id,
                    branch_tip_scalar_ref_id=ServerPlanRefId(_ref("sql.branch_tip")),
                    base_revision_ref_id=ServerPlanRefId(_ref("base_revision")),
                    result_revision_id=result_revision_id_ref,
                    sparse_table=SqlTableName(sparse_table),
                    data_columns=[SqlColumnName(name) for name in data_columns],
                    revision_table=SqlTableName(revision_table),
                    revision_parents_table=SqlTableName(revision_parents_table),
                ),
                ApplySquashBranchDeleteTipStep(
                    ref_id=ServerPlanRefId(_ref(f"delete_tip.{table_name}")),
                    branch_ref_id=ServerPlanRefId(_ref("branch")),
                    branch_sys_scalar_ref_id=branch_sys_scalar_ref_id,
                    branch_tip_scalar_ref_id=ServerPlanRefId(_ref("sql.branch_tip")),
                    base_revision_ref_id=ServerPlanRefId(_ref("base_revision")),
                    result_revision_id=result_revision_id_ref,
                    sparse_table=SqlTableName(sparse_table),
                    tip_table=SqlTableName(tip_table),
                    data_columns=[SqlColumnName(name) for name in data_columns],
                    revision_table=SqlTableName(revision_table),
                    revision_parents_table=SqlTableName(revision_parents_table),
                ),
                ApplySquashBranchUpsertTipStep(
                    ref_id=ServerPlanRefId(_ref(f"upsert_tip.{table_name}")),
                    branch_ref_id=ServerPlanRefId(_ref("branch")),
                    branch_sys_scalar_ref_id=branch_sys_scalar_ref_id,
                    branch_tip_scalar_ref_id=ServerPlanRefId(_ref("sql.branch_tip")),
                    base_revision_ref_id=ServerPlanRefId(_ref("base_revision")),
                    result_revision_id=result_revision_id_ref,
                    sparse_table=SqlTableName(sparse_table),
                    tip_table=SqlTableName(tip_table),
                    data_columns=[SqlColumnName(name) for name in data_columns],
                    revision_table=SqlTableName(revision_table),
                    revision_parents_table=SqlTableName(revision_parents_table),
                ),
            ],
        )

    demote_tip = _RebaseDemoteTipStep(
        ref_id=ServerPlanRefId(_ref("demote_tip")),
        config=_RebaseDemoteTipConfig(
            index_table=SqlTableName(index_table),
            branch_id=ServerRefs.from_ref_id(str(branch_sys_scalar_ref_id), variant="scalar"),
        ),
    )
    insert_index = _RebaseInsertBranchIndexStep(
        ref_id=ServerPlanRefId(_ref("insert_index")),
        config=_RebaseInsertBranchIndexConfig(
            index_table=SqlTableName(index_table),
            index_sys_id=SysId(str(uuid7())),
            new_tip=result_revision_id_ref,
            branch_id=ServerRefs.from_ref_id(str(branch_sys_scalar_ref_id), variant="scalar"),
        ),
    )
    update_tip = _RebaseUpdateBranchTipStep(
        ref_id=ServerPlanRefId(_ref("update_tip")),
        config=_RebaseUpdateBranchTipConfig(
            branch_table=SqlTableName(branch_table),
            new_tip=result_revision_id_ref,
            branch_id=ServerRefs.from_ref_id(str(branch_sys_scalar_ref_id), variant="scalar"),
        ),
    )
    project_result = ProjectSquashBranchResultStep(
        ref_id=ServerPlanRefId(_ref("project_result")),
        result_revision_id=result_revision_id_ref,
    )
    apply_steps_gated = _gate_branch_steps(
        condition_ref=_ref("should_apply"),
        branch_steps=[
            validate_ancestor,
            validate_linear,
            insert_revision,
            insert_parent,
            *apply_steps,
            demote_tip,
            insert_index,
            update_tip,
            project_result,
        ],
        force_non_batchable=sqlite_force_non_batchable,
    )
    select_result = SelectSquashBranchResultStep(
        ref_id=ServerPlanRefId(result_ref_id),
        is_noop_ref_id=ServerPlanRefId(_ref("is_noop")),
        base_revision_ref_id=ServerPlanRefId(_ref("base_revision")),
        apply_result_ref_id=ServerPlanRefId(_ref("project_result")),
    )
    return [
        fetch_branch,
        proj_branch_sys,
        proj_branch_tip,
        validate_tip,
        resolve_base_revision,
        is_noop,
        should_apply,
        *apply_steps_gated,
        select_result,
    ]


