def _ref_id(value: ServerPlanRefId | str) -> ServerPlanRefId:
    if isinstance(value, ServerPlanRefId):
        return value
    return ServerPlanRefId(value)


def _require_source_cte(
    ctx: CompilationContext,
    source_ref: str,
    *,
    step_name: str,
    runtime_fallback_name: str,
) -> CteReference:
    source_cte = ctx.cte_refs.get(source_ref)
    if isinstance(source_cte, CteReference):
        return source_cte
    msg = f"{step_name} requires a SQL-visible source relation for {source_ref!r}; {runtime_fallback_name} is not allowed."
    raise RuntimeError(msg)


def _compiled_artifacts_from_source_cte(
    source_cte: CteReference,
) -> tuple[CompiledOutputShape, DeclaredResultRelation, SqlColumnTypeHints]:
    if source_cte.columns is None:
        msg = f"Source CTE {source_cte.ref_id!r} has no explicit columns."
        raise TypeError(msg)
    output_shape = CompiledOutputShape(tuple(synthetic_output_field(column) for column in source_cte.columns))
    assert source_cte.column_type_hints is not None
    column_type_hints = source_cte.column_type_hints.filtered(set(source_cte.columns))
    column_type_hints.require_complete(source_cte.columns)
    return output_shape, DeclaredResultRelation.from_output_shape(output_shape), column_type_hints


def _server_ref_terminal_ref_id(step_ref_id: ServerPlanRefId, value: ServerRef[Any]) -> str:
    ref_id = value.ref_id
    if ref_id is None:
        msg = f"ReturnValueStep {step_ref_id} cannot return an unbound ServerRef terminal value."
        raise TypeError(msg)
    return str(ref_id)


def _raise_symbolic_terminal_ref(step_ref_id: ServerPlanRefId, ref_id: ServerPlanRefId) -> None:
    msg = f"ReturnValueStep {step_ref_id} cannot publish symbolic ref {ref_id!r} as a terminal result."
    raise TypeError(msg)


