def _declared_literal_rows(value: object, columns: tuple[str, ...]) -> list[dict[str, object]]:
    values = value if isinstance(value, Sequence) and not isinstance(value, (str, bytes, bytearray)) else (value,)
    rows: list[dict[str, object]] = []
    for item in values:
        if isinstance(item, BaseModel):
            dumped = item.model_dump(mode="python")
            if isinstance(item, DatabaseObjectRow):
                from l1000_schema.column_utils import get_db_column_name

                values_by_column = {
                    str(get_db_column_name(type(item), DynamicFieldName(field_name))): field_value
                    for field_name, field_value in dumped.items()
                }
            else:
                values_by_column = dumped
        elif is_dataclass(item) and not isinstance(item, type):
            values_by_column = {field.name: getattr(item, field.name) for field in fields(item)}
        elif isinstance(item, Mapping):
            values_by_column = {str(key): field_value for key, field_value in item.items()}
        elif len(columns) == 1:
            values_by_column = {columns[0]: unwrap_literal_sql_value(item)}
        else:
            msg = f"Declared literal with columns {columns!r} requires a row-shaped value."
            raise TypeError(msg)
        rows.append(
            {column: unwrap_literal_sql_value(values_by_column[column]) for column in columns},
        )
    return rows


def _require_runtime_int(value: object, *, field_name: str) -> int:
    if isinstance(value, bool) or not isinstance(value, int):
        msg = f"Expected integer runtime builder field {field_name!r}, got {type(value).__name__}."
        raise TypeError(msg)
    return value


def _require_runtime_sequence_of_mappings(
    value: object,
    *,
    context: str,
) -> Sequence[Mapping[str, object]]:
    if (
        not isinstance(value, Sequence)
        or isinstance(value, str | bytes | bytearray)
        or not all(isinstance(item, Mapping) for item in value)
    ):
        msg = f"{context} expected a sequence of mapping rows, got {type(value).__name__}."
        raise TypeError(msg)
    return cast("Sequence[Mapping[str, object]]", value)


def _require_database_row_model_cls(model_cls: type[BaseModel] | None) -> type[DatabaseObjectRow]:
    if model_cls is None or not issubclass(model_cls, DatabaseObjectRow):
        msg = "TupleQuery model projection requires a DatabaseObjectRow model_cls"
        raise TypeError(msg)
    result = model_cls
    assert isinstance(result, type)
    return result


def _server_ref_v_type_hints(value: ServerRef[Any]) -> SqlColumnTypeHints:
    type_hint = getattr(value, "_type_hint", None)
    if not isinstance(type_hint, type):
        msg = f"Cannot publish ServerRef {value!r} without an explicit type hint"
        raise TypeError(msg)
    if issubclass(type_hint, bool):
        return SqlColumnTypeHints(bool_columns=frozenset({"v"}))
    if issubclass(type_hint, UUID) or hasattr(type_hint, "unwrap_to_uuid"):
        return SqlColumnTypeHints(uuid_columns=frozenset({"v"}))
    if issubclass(type_hint, datetime):
        return SqlColumnTypeHints(timestamptz_columns=frozenset({"v"}))
    if issubclass(type_hint, date):
        return SqlColumnTypeHints(date_columns=frozenset({"v"}))
    if issubclass(type_hint, int):
        return SqlColumnTypeHints(bigint_columns=frozenset({"v"}))
    if issubclass(type_hint, float):
        return SqlColumnTypeHints(double_columns=frozenset({"v"}))
    if issubclass(type_hint, str) or issubclass(type_hint, Enum):
        return SqlColumnTypeHints(text_columns=frozenset({"v"}))
    if issubclass(type_hint, bytes | bytearray):
        return SqlColumnTypeHints(bytea_columns=frozenset({"v"}))
    if issubclass(type_hint, Mapping | Sequence) and not issubclass(type_hint, str | bytes | bytearray):
        return SqlColumnTypeHints(jsonb_columns=frozenset({"v"}))
    if issubclass(type_hint, BaseModel):
        return SqlColumnTypeHints(jsonb_columns=frozenset({"v"}))
    msg = f"Cannot publish ServerRef type hint {type_hint.__name__} without explicit SQL type hints"
    raise TypeError(msg)


def _literal_v_type_hints(value: object) -> SqlColumnTypeHints:
    if isinstance(value, ServerRef):
        return _server_ref_v_type_hints(value)
    original_unwrap_to_str = getattr(value, "unwrap_to_str", None)
    if callable(original_unwrap_to_str):
        return SqlColumnTypeHints(uuid_columns=frozenset({"v"}))
    normalized = unwrap_literal_sql_value(value)
    if isinstance(normalized, bool):
        return SqlColumnTypeHints(bool_columns=frozenset({"v"}))
    if isinstance(normalized, UUID):
        return SqlColumnTypeHints(uuid_columns=frozenset({"v"}))
    unwrap_to_str = getattr(normalized, "unwrap_to_str", None)
    if callable(unwrap_to_str):
        return SqlColumnTypeHints(uuid_columns=frozenset({"v"}))
    if isinstance(normalized, int):
        return SqlColumnTypeHints(bigint_columns=frozenset({"v"}))
    if isinstance(normalized, float):
        return SqlColumnTypeHints(double_columns=frozenset({"v"}))
    if isinstance(normalized, datetime):
        return SqlColumnTypeHints(timestamptz_columns=frozenset({"v"}))
    if isinstance(normalized, date):
        return SqlColumnTypeHints(date_columns=frozenset({"v"}))
    if isinstance(normalized, str):
        return SqlColumnTypeHints(text_columns=frozenset({"v"}))
    if isinstance(normalized, bytes | bytearray):
        return SqlColumnTypeHints(bytea_columns=frozenset({"v"}))
    if isinstance(normalized, Mapping | Sequence) and not isinstance(normalized, str | bytes | bytearray):
        return SqlColumnTypeHints(jsonb_columns=frozenset({"v"}))
    msg = f"Cannot publish SQL scalar literal of type {type(normalized).__name__} without explicit type hints"
    raise TypeError(msg)


@pure_lazy
def _is_publishable_scalar_literal(value: object) -> bool:
    if isinstance(value, ServerRef):
        return True
    original_unwrap_to_str = getattr(value, "unwrap_to_str", None)
    if callable(original_unwrap_to_str):
        return True
    normalized = unwrap_literal_sql_value(value)
    unwrap_to_str = getattr(normalized, "unwrap_to_str", None)
    if callable(unwrap_to_str):
        return True
    return isinstance(
        normalized,
        bool | int | float | datetime | date | str | bytes | bytearray | UUID,
    )


def _is_publishable_terminal_value(value: object) -> bool:
    if value is None:
        return True
    if _homogeneous_base_model_sequence_model(value) is not None:
        return True
    if isinstance(value, BaseModel):
        return True
    if is_dataclass(value) and not isinstance(value, type):
        return True
    if isinstance(value, Mapping):
        return all(_is_publishable_scalar_literal(item) for item in value.values())
    return _is_publishable_scalar_literal(value)


def _literal_object_type_hints(value: object, columns: tuple[str, ...]) -> SqlColumnTypeHints:
    jsonb_columns: set[str] = set()
    uuid_columns: set[str] = set()
    timestamptz_columns: set[str] = set()
    date_columns: set[str] = set()
    bool_columns: set[str] = set()
    bigint_columns: set[str] = set()
    double_columns: set[str] = set()
    text_columns: set[str] = set()
    bytea_columns: set[str] = set()
    for column in columns:
        raw = getattr(value, column)
        normalized = unwrap_literal_sql_value(raw)
        if normalized is None:
            if column.endswith("_id"):
                uuid_columns.add(column)
            elif column.startswith("is_") or column.startswith("has_"):
                bool_columns.add(column)
            else:
                text_columns.add(column)
        elif isinstance(normalized, bool):
            bool_columns.add(column)
        elif isinstance(normalized, UUID):
            uuid_columns.add(column)
        elif isinstance(normalized, int):
            bigint_columns.add(column)
        elif isinstance(normalized, float):
            double_columns.add(column)
        elif isinstance(normalized, datetime):
            timestamptz_columns.add(column)
        elif isinstance(normalized, date):
            date_columns.add(column)
        elif isinstance(normalized, bytes | bytearray):
            bytea_columns.add(column)
        elif isinstance(normalized, Enum | str):
            text_columns.add(column)
        elif isinstance(normalized, Mapping | Sequence) and not isinstance(normalized, str | bytes | bytearray):
            jsonb_columns.add(column)
        elif column.endswith("_id"):
            uuid_columns.add(column)
        else:
            text_columns.add(column)
    return SqlColumnTypeHints(
        jsonb_columns=frozenset(jsonb_columns),
        uuid_columns=frozenset(uuid_columns),
        timestamptz_columns=frozenset(timestamptz_columns),
        date_columns=frozenset(date_columns),
        bool_columns=frozenset(bool_columns),
        bigint_columns=frozenset(bigint_columns),
        double_columns=frozenset(double_columns),
        text_columns=frozenset(text_columns),
        bytea_columns=frozenset(bytea_columns),
    )


def _homogeneous_base_model_sequence_model(value: object) -> type[BaseModel] | None:
    if isinstance(value, Mapping | str | bytes | bytearray) or not isinstance(value, Sequence) or not value:
        return None
    if not all(isinstance(item, BaseModel) for item in value):
        return None
    model_classes = {type(cast(BaseModel, item)) for item in value}
    if len(model_classes) != 1:
        return None
    return next(iter(model_classes))


def _base_model_output_columns(model_cls: type[BaseModel]) -> tuple[str, ...]:
    if not issubclass(model_cls, DatabaseObjectRow):
        return tuple(model_cls.model_fields)
    return tuple(
        plan.db_column
        for plan in writable_field_plans(
            model_cls,
            include_polymorphic=False,
        )
    )


def _base_model_column_type_hints(model_cls: type[BaseModel], columns: tuple[str, ...]) -> SqlColumnTypeHints:
    from l1000_schema.column_utils import get_db_column_name
    from l2070_batching.sql_column_type_hints import model_field_sql_column_type_hints

    if issubclass(model_cls, DatabaseObjectRow):
        row_model_cls = cast("type[DatabaseObjectRow[SysId]]", model_cls)
        field_to_db_column = {
            field_name: get_db_column_name(row_model_cls, DynamicFieldName(field_name)) for field_name in model_cls.model_fields
        }
    else:
        from l2070_batching.sql_column_type_hints import (
            combine_sql_column_type_hints,
            sql_column_type_hints_for_declared_python_type,
        )

        field_hints = []
        for field_name in columns:
            field = model_cls.model_fields.get(field_name)
            if field is None or not isinstance(field.annotation, type):
                continue
            hint = sql_column_type_hints_for_declared_python_type(field_name, field.annotation)
            if hint is not None:
                field_hints.append(hint)
        return combine_sql_column_type_hints(columns, *field_hints)
    hints = model_field_sql_column_type_hints(row_model_cls, field_to_db_column)
    return hints.filtered(set(columns))


