class ReturnValueStep[T](MaybeSqlRelationPublisherStep[T]):
    """L0 step that returns a pre-computed value without executing any SQL."""

    def __init__(self, ref_id: ServerPlanRefId, value: T) -> None:
        super().__init__(_ref_id(ref_id))
        self._value = value

    def _validated_literal_post_op_for_value(self: ReturnValueStep[T]) -> CompiledPostOp:
        """Build a fresh post-op using validator-owned memoized analysis."""
        return literal_post_op(self._value)

    @property
    def level(self: ReturnValueStep[T]) -> int:
        return 0

    def result_cardinality(self: ReturnValueStep[T]) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self: ReturnValueStep[T]) -> bool:
        return True

    def execution_role(self: ReturnValueStep[T]) -> StepExecutionRole:
        if self.dependencies():
            return StepExecutionRole.APPLY
        contract = self.cte_publication_contract()
        if contract is None:
            return StepExecutionRole.APPLY
        columns = contract.columns
        if columns:
            return StepExecutionRole.APPLY
        return StepExecutionRole.VIRTUAL

    def publishes_executor_visible_binding(self: ReturnValueStep[T]) -> bool:
        """Return values are terminal runtime values, not executor-published SQL relations."""
        return False

    def consumes_executor_visible_dependencies(self: ReturnValueStep[T]) -> bool:
        return bool(self.dependencies())

    def step_tags(self: ReturnValueStep[T]) -> frozenset[str]:
        if self.execution_role() is StepExecutionRole.VIRTUAL:
            return frozenset({"return_value", "virtual"})
        return frozenset({"return_value", "apply"})

    def supports_sql_batch_transport(self: ReturnValueStep[T]) -> bool:
        return False

    def requires_materialized_inputs(self: ReturnValueStep[T]) -> bool:
        return True

    def _is_transport_safe_conditional_default(self: ReturnValueStep[T]) -> bool:
        """Literal defaults need no child result materializer inside an ordered request."""
        return True

    def tables_read(self: ReturnValueStep[T]) -> frozenset[str]:
        return frozenset()

    def tables_written(self: ReturnValueStep[T]) -> frozenset[str]:
        return frozenset()

    def internal_plan_state(self: ReturnValueStep[T]) -> PlanPayloadState:
        value = self._value
        if (
            isinstance(value, BaseModel)
            and getattr(
                type(value),
                "__nera_session_context_model__",
                False,
            )
            is True
        ):
            return {"_value_type": "ResolvedSessionContext"}
        return super().internal_plan_state()

    def internal_plan_ref_state(self: ReturnValueStep[T]) -> PlanPayloadState:
        return self.internal_plan_state()

    def dependencies(self: ReturnValueStep[T]) -> frozenset[str]:
        deps = {str(dep) for dep in collect_instance_deps(self._value)}
        deps.update(str(dep) for dep in server_value_deps(self._value))
        return frozenset(deps)

    def cte_publication_contract(self: ReturnValueStep) -> CtePublicationContract:
        def _legacy_cte_output_columns() -> tuple[str, ...] | None:
            value = self._value
            if not _is_publishable_terminal_value(value):
                return None
            sequence_model_cls = _homogeneous_base_model_sequence_model(value)
            if sequence_model_cls is not None:
                return _base_model_output_columns(sequence_model_cls)
            if is_dataclass(value) and not isinstance(value, type):
                return tuple(field.name for field in fields(value))
            if not isinstance(value, BaseModel):
                if value is None:
                    return None
                if isinstance(value, Mapping):
                    return tuple(str(key) for key in value)
                return ("__result",)
            return _base_model_output_columns(type(value))

        columns = _legacy_cte_output_columns()

        def _legacy_cte_column_type_hints(columns: tuple[str, ...] | None) -> SqlColumnTypeHints | None:
            value = self._value
            if not _is_publishable_terminal_value(value):
                return None
            sequence_model_cls = _homogeneous_base_model_sequence_model(value)
            if sequence_model_cls is not None:
                return None if columns is None else _base_model_column_type_hints(sequence_model_cls, columns)
            if not isinstance(value, BaseModel):
                if value is None:
                    return SqlColumnTypeHints()
                if isinstance(value, bool):
                    return SqlColumnTypeHints(bool_columns=frozenset({"__result"}))
                if isinstance(value, int):
                    return SqlColumnTypeHints(bigint_columns=frozenset({"__result"}))
                if is_dataclass(value) and not isinstance(value, type):
                    return None if columns is None else _literal_object_type_hints(value, columns)
                if isinstance(value, Mapping):
                    from l2070_batching.sql_column_type_hints import combine_sql_column_type_hints

                    columns = tuple(str(key) for key in value)
                    return combine_sql_column_type_hints(
                        columns,
                        *(
                            _literal_v_type_hints(item).rename_column("v", column)
                            for column, item in zip(columns, value.values(), strict=True)
                        ),
                    )
                return _literal_v_type_hints(value).rename_column("v", "__result")
            model_cls = type(value)
            hints = _base_model_column_type_hints(model_cls, columns or tuple(model_cls.model_fields))
            if columns is None or isinstance(value, DatabaseObjectRow):
                return hints
            try:
                hints.require_complete(columns)
            except ValueError:
                return _literal_object_type_hints(value, columns)
            return hints

        column_type_hints = _legacy_cte_column_type_hints(columns)
        if columns is None:
            if column_type_hints is not None and column_type_hints.has_any():
                msg = f"{type(self).__name__} declares SQL column type hints without an explicit cte_output_columns() contract."
                raise TypeError(msg)
            return CtePublicationContract.non_publishing()
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        contract_columns = tuple(str(column) for column in columns)
        publishes_scalar_value = (
            not isinstance(self._value, BaseModel | Mapping)
            and not (is_dataclass(self._value) and not isinstance(self._value, type))
            and _homogeneous_base_model_sequence_model(self._value) is None
        )
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.DECLARED_LITERAL_RELATION,
            columns=contract_columns,
            column_type_hints=column_type_hints,
            relation_contract=_return_value_relation_contract(
                self._value,
                contract_columns,
                column_type_hints,
            ),
