class PlanHistoryCursorPageStep[T](NonPublishingStep[T]):
    """Build plan-history cursor pages from resolved history entries."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        source_ref: ServerPlanRefId,
        payload: PlanHistoryCursorPagePayload,
        model_cls: type[DatabaseObjectRow[Any]],
        revision_model_cls: type[Any],
    ) -> None:
        super().__init__(ref_id)
        self._source_ref = source_ref
        self._payload = dict(payload.values)
        self._model_cls = model_cls
        self._revision_model_cls = revision_model_cls

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self) -> bool:
        return True

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def step_tags(self) -> frozenset[str]:
        return frozenset({"plan_history_cursor_page", "sql_projection"})

    def consumes_executor_visible_dependencies(self) -> bool:
        return True

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def dependencies(self) -> frozenset[str]:
        return frozenset({str(self._source_ref)})

    def compile(self, ctx: CompilationContext) -> CompiledStep[T]:
        source_ref = str(self._source_ref)
        source_cte = _require_source_cte(
            ctx,
            source_ref,
            step_name="PlanHistoryCursorPageStep",
            runtime_fallback_name="runtime-ref plan history cursor pagination",
        )
        __opa002_grammar_1026 = SqlDynamicSelectStmt(
            SqlTableName(source_cte.ref_id),
            columns=([SqlColumnName(column) for column in source_cte.columns] if source_cte.columns is not None else None),
        )
        output_shape, result_relation, column_type_hints = _compiled_artifacts_from_source_cte(source_cte)
        return CompiledStep(
            grammar=__opa002_grammar_1026,
            needs_returning=True,
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
            auxiliary_ctes=[(source_cte.ref_id, source_cte.auxiliary_query)] if source_cte.auxiliary_query is not None else None,
            closed_post_op=plan_history_cursor_page_post_op(
                self._payload,
                model_cls=self._model_cls,
                revision_model_cls=self._revision_model_cls,
            ),
        )

    def execute_runtime(self, resolved: TerminalResolvedValues) -> T:
        from l7200_versioned_transactions.plan_revision_history_query import (
            materialize_plan_history_cursor_page,
        )

        entries_value = resolved.get(str(self._source_ref))
        if entries_value is None:
            entries: Sequence[Any] = ()
        elif isinstance(entries_value, Sequence) and not isinstance(entries_value, str | bytes | bytearray):
            entries = entries_value
        else:
            msg = f"PlanHistoryCursorPageStep expected sequence source, got {type(entries_value).__name__}"
            raise TypeError(msg)
        ordering_columns = [
            (str(column), str(direction))
            for column, direction in cast(
                "Sequence[tuple[object, object]]",
                self._payload["ordering_columns"],
            )
        ]
        limit_value = self._payload["limit"]
        limit = limit_value if isinstance(limit_value, int) else int(str(limit_value))
        return cast(
            T,
            materialize_plan_history_cursor_page(
                entries=entries,
                limit=limit,
                backward=bool(self._payload["backward"]),
                ordering_columns=ordering_columns,
                field_name=str(self._payload["field_name"]),
                is_revision_field=bool(self._payload["is_revision_field"]),
            ),
        )


