def _sample_query_spec(
    *,
    model_cls: type[DatabaseObjectRow] = SampleProduct,
    filters: list[QueryFilter] | None = None,
    joins: list[JoinClause] | None = None,
    order_by: Sequence[Any] = (),
    limit: int | None = 1,
    offset: int | None = 0,
    type_filter_types: tuple[str | int, ...] | None = None,
    type_filter_column: str | None = None,
    aggregations: list[AggregationSpec] | None = None,
    group_by: list[Any] | None = None,
    having: list[Any] | None = None,
    window_functions: list[tuple[Any, str]] | None = None,
    select_columns: list[Any] | None = None,
) -> QuerySpec[Any]:
    """Build the closed QuerySpec record expected by versioned compile paths."""
    return QuerySpec(
        model_cls=model_cls,
        table=get_table_name(model_cls),
        select_columns=select_columns,
        distinct=False,
        joins=[] if joins is None else joins,
        filters=[] if filters is None else filters,
        order_by=order_by,
        limit=limit,
        offset=offset,
        group_by=[] if group_by is None else group_by,
        aggregations=[] if aggregations is None else aggregations,
        having=[] if having is None else having,
        window_functions=[] if window_functions is None else window_functions,
        type_filter_types=type_filter_types,
        type_filter_column=type_filter_column,
    )


