def build_planning_catalog(
    models: tuple[type[Any], ...] | None = None,
    *,
    backend_type: BackendType = BackendType.SQLITE,
    **kwargs: Any,
) -> Any:
    return _build_planning_catalog(
        models=_VERSIONED_QUERY_MODELS if models is None else models,
        backend_type=backend_type,
        **kwargs,
    )


def _declare_explicit_cte_projections(context: CompilationContext) -> CompilationContext:
    for logical_ref, binding in tuple(context.cte_refs.items()):
        if not isinstance(binding, CteReference) or binding.columns is None:
            continue
        for column in binding.columns:
            projected_ref = f"{logical_ref}.{column}"
            if projected_ref in context.cte_refs:
                continue
            is_scalar_value = binding.scalar_value_column is not None and binding.scalar_value_column.to_row_key() == column
            context.cte_refs[projected_ref] = CteReference(
                binding.ref_id,
                source_tables=binding.source_tables,
                columns=(column,),
                column_type_hints=(binding.column_type_hints.filtered({column}) if binding.column_type_hints is not None else None),
                relation_role=binding.relation_role,
                scalar_control_kind=binding.scalar_control_kind if is_scalar_value else None,
                scalar_value_column=binding.scalar_value_column if is_scalar_value else None,
                auxiliary_query=binding.auxiliary_query,
                ephemeral=binding.ephemeral,
            )
    return context


def make_compilation_context(*args: Any, **kwargs: Any) -> CompilationContext:
    profile = kwargs.get("profile") or (args[0] if args else None)
    backend_type = profile.backend_type if profile is not None else BackendType.SQLITE
    kwargs.setdefault(
        "planning_catalog",
        build_planning_catalog(models=_VERSIONED_QUERY_MODELS, backend_type=backend_type),
    )
    return _declare_explicit_cte_projections(_make_compilation_context(*args, **kwargs))


def make_lowering_context(*args: Any, **kwargs: Any) -> Any:
    profile = kwargs.get("profile") or (args[0] if args else None)
    backend_type = profile.backend_type if profile is not None else BackendType.SQLITE
    kwargs.setdefault(
        "planning_catalog",
        build_planning_catalog(models=_VERSIONED_QUERY_MODELS, backend_type=backend_type),
    )
    return _make_lowering_context(*args, **kwargs)


