    from l1000_schema.typed_field import CAST, MAX, SqlCastTargetType

    expression = CAST(LOWER(typed_field(SampleProduct.name)), SqlCastTargetType(base_type="TEXT"))
    aggregation = AggregationSpec(function="MAX", expression=expression, alias="payload", source_expression=MAX(expression))
