def test_versioned_projected_model_rows_map_logical_audit_aliases_to_physical_contract_columns() -> None:
    from impl.common.l2070_server_plan.steps.versioned_query_steps import VersionedQueryFromSpecStep
    from l1000_schema.typed_field import AliasedField

    spec = _sample_query_spec(
        model_cls=SampleVersionedProduct,
        select_columns=[
            typed_field(SampleVersionedProduct.sys_id),
            AliasedField(typed_field(SampleVersionedProduct.created_at), SchemaObjectName("created_at")),
            AliasedField(typed_field(SampleVersionedProduct.updated_at), SchemaObjectName("updated_at")),
        ],
    )
    step = VersionedQueryFromSpecStep(
        ServerPlanRefId("projected_audit_aliases"), SampleVersionedProduct, _versioned_query_config(spec, raw_mode=True)
    )
    compiled = step.compile(_compile_ctx(session_id=None))
    assert compiled.grammar is not None
    sql = render_to_sql(compiled.grammar, PostgresDialect())[0]
    import sqlglot
    from sqlglot import expressions as sqlglot_exp

    projection = sqlglot.parse_one(sql, read="postgres")
    aliases = {node.alias: node.this for node in projection.find_all(sqlglot_exp.Alias)}
    for logical, physical in (("created_at", "sys_created_at"), ("updated_at", "sys_updated_at")):
        source = aliases[logical].find(sqlglot_exp.Column)
        assert source is not None
        assert source.name == physical
        assert aliases[logical].find(sqlglot_exp.Null) is None


