class TestComputedQueryTerminals:
    def test_versioned_attach_refreshes_stale_permission_branch_anchor(self: TestComputedQueryTerminals) -> None:
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlLiteral
        from l2070_batching.server_ref import ServerRefs
        from l4000_permissions.permission_scheme import QueryPermissionPlan
        from l7000_versioned_schema.versioned_schema import BranchId

        stale_permission_grammar = SqlBinaryOp(
            SqlColumnRef(SqlColumnName("branch_id")),
            BinaryOp.EQ,
            SqlLiteral("stale"),
        )
        spec = QuerySpec(
            model_cls=SampleProduct,
            table="sample_products",
            select_columns=None,
            distinct=False,
            joins=[],
            filters=[],
            order_by=[],
            limit=None,
            offset=None,
            group_by=[],
            aggregations=[],
            having=[],
            window_functions=[],
            permission_grammar=stale_permission_grammar,
            permission_state=QueryPermissionState.ATTACHED,
        )
        ctx = replace(
            _compile_ctx(session_id="11111111-1111-7111-8111-111111111111"),
            versioning_domain=DefaultDomain,
            lazy_branch=ServerRefs.from_ref_id("step_0", variant="scalar", type_hint=BranchId),
            cte_refs={
                "step_0": CteReference(
                    ServerPlanRefId("b12"),
                    columns=("branch_id",),
                    column_type_hints=SqlColumnTypeHints(uuid_columns=frozenset({"branch_id"})),
                ),
            },
        )
        captured_branch_sql: list[SqlRenderable | None] = []

        def _compile_refreshed_permission(*args: object, **kwargs: object) -> SqlRenderable:
            del args
            version_anchor = kwargs.get("version_anchor")
            captured_branch_sql.append(
                cast("SqlRenderable | None", getattr(version_anchor, "branch_id_sql", None)),
            )
            return SqlLiteral(True)

        with (
            patch(
                "l4000_permissions.permission_enforcement._try_get_permission_scheme",
                return_value=OwnershipScheme(),
            ),
            patch(
                "l4000_permissions.permission_enforcement.get_query_permission_plan",
                return_value=QueryPermissionPlan.filtered(requires_user_id=True),
            ),
            patch(
                "impl.common.l7300_cross_branch.permission_expression_compiler.compile_versioned_permission_where_with_user_expr",
                side_effect=_compile_refreshed_permission,
            ),
        ):
            refreshed = attach_runtime_read_permission_grammar(spec, SampleProduct, ctx, attach_column_masking=False)

        assert refreshed is not None
        assert getattr(refreshed, "permission_grammar") is not stale_permission_grammar
        assert captured_branch_sql
        assert captured_branch_sql[0] is not None
        branch_sql, _params = render_to_sql(captured_branch_sql[0], _sqlite_dialect())
        assert '"b12"' in branch_sql
        assert '"step_0"' not in branch_sql

