    def test_raw_mode_branch_tip_read_retains_sys_deleted_for_spill_wrapper(
        self: TestComputedQueryTerminals,
    ) -> None:
        """Raw branch-tip reads must keep the tombstone column for the spill wrapper.

        Regression: when the branch-tip revision is cleared (the live primary-key
        ``select_one`` path), the published-tip *fast* read strips ``sys_deleted``
        (``_published_tip_output_shape``).  The shared spill-aware select-one wrapper
        (``_WrapOptionalRawRowStep``) then emits ``WHERE NOT sys_deleted`` against a
        CTE that lacks the column, raising ``column "sys_deleted" does not exist``.
        ``raw_mode`` reads must therefore route to the merged-CTE-over-``_tip`` path,
        which still hits the fast ``_tip`` table but retains the tombstone column.
        """

        ctx = CompilationContext(
            backend_type=BackendType.SQLITE,
            dialect=_sqlite_dialect(),
            supports_data_modifying_ctes=False,
            backend_profile=make_backend_profile(BackendType.SQLITE, dialect=_sqlite_dialect()),
            branch_id="branch-1",
            revision_id=None,
            session_id="session-1",
            prefer_tip_strategy=True,
            branch_tip_materialized=True,
            txn=SimpleNamespace(
                _is_materialized=True,
                _prefer_tip_merged=False,
                _prefer_tip_strategy=True,
                _branch_anchor="branch-1",
            ),  # type: ignore[arg-type]
            planning_catalog=build_planning_catalog(),
        )

        raw_result = compile_versioned_query(None, SampleProduct, ctx, include_deleted=False, raw_mode=True)
        raw_sql, _raw_params = render_to_sql(raw_result.grammar, _sqlite_dialect())

        assert "sample_products_tip" in raw_sql
        assert "sample_products_sparse" not in raw_sql
        # The tombstone column survives (as ``deleted``) so the downstream spill
        # wrapper can apply its delete filter. The stripped published-tip fast path
        # would emit neither ``deleted`` nor ``sys_deleted`` (see the non-raw read at
        # ``test_prefer_tip_strategy_keeps_general_reads_on_tip_but_allows_raw_tip_reads``).
        assert '"deleted"' in raw_sql
        assert raw_result.output_shape is not None
        assert "deleted" in raw_result.output_shape.cte_output_columns

