    def test_raw_mode_materialized_published_branch_tip_read_retains_tombstone(
        self: TestComputedQueryTerminals,
    ) -> None:
        """Raw select_one over a materialized published-branch context keeps the tombstone.

        The live ``GET /api/data/{model}/{id}`` route resolves the branch through a
        published read-context CTE carrying ``tip_materialization='materialized'``.
        ``prepare_versioned_compile_inputs`` then clears the revision override, and the
        raw-mode read must still surface the tombstone column so the spill-aware
        select-one wrapper can apply ``WHERE NOT deleted``.  Previously the cleared
        revision routed the read to a published-tip CTE that stripped the tombstone,
        raising ``column "deleted" does not exist`` (HTTP 400 after a delete).
        """
        from impl.common.l2070_server_plan.steps.versioned_query_steps import (
            VersionedQueryFromSpecStep,
        )

        ctx = replace(
            _compile_ctx(),
            branch_id=None,
            branch_tip_materialized=False,
            prefer_tip_strategy=True,
            cte_refs={
                "resolve_branch": _published_read_context_cte(
                    ServerPlanRefId("published_1"),
                    columns=("branch_id", "revision_id", "tip_materialization"),
                ),
                "resolve_revision": _published_cte_ref(
                    ServerPlanRefId("published_0"),
                    columns=("revision_id",),
                    rows=[{"revision_id": RevisionId("00000000-0000-0000-0000-000000000099")}],
                    type_hints=SqlColumnTypeHints(uuid_columns=frozenset({"revision_id"})),
                ),
            },
        )
        ctx = _declare_explicit_cte_projections(ctx)
        step = VersionedQueryFromSpecStep(
            ServerPlanRefId("q_raw_materialized_tip"),
            SampleProduct,
            _versioned_query_config(
                _sample_query_spec(model_cls=SampleProduct, limit=None, offset=0),
                branch_ref_id=ServerPlanRefId("resolve_branch"),
                revision_ref_id=ServerPlanRefId("resolve_revision.revision_id"),
                raw_mode=True,
            ),
        )

        compiled = step.compile(ctx)
        materialized = compiled.materialize_ir()
        assert isinstance(materialized, SqlStepIR)
        sql, _params = render_to_sql(materialized.grammar, _sqlite_dialect())
        assert "sample_products_tip" in sql
        assert '"deleted"' in sql

