                session_id=cast("Any", SessionId("33333333-3333-4333-8333-333333333333")),
                revision_metadata=(
                    ("author_timestamp", "2026-06-21T13:22:31+00:00"),
                    ("parent_commit_shas_json", '["abc"]'),
                ),
                parent_revision_ref_id=ServerPlanRefId("t_merge.target_branch"),
            ),
        )
        ctx = make_compilation_context(
