    def test_prefer_tip_strategy_routes_select_one_pk_to_query_from_spec_tip_path(
        self: TestVersionedSelectOneStep,
    ) -> None:
        """Primary-key ``select_one`` reads must take the branch-tip fast path.

        Regression: ``select_one_lazy`` always lowered to ``VersionedReadSelectOneStep``,
        which compiles to the sparse ``_visible_ancestors`` ancestry scan (catastrophic on
        deep histories — a single-row fetch can walk thousands of ``sys_revision_parents``
        rows, e.g. the 6s ``GET /api/data/{model}/{id}`` route). With ``prefer_tip_strategy``
        it must instead route through ``VersionedQueryFromSpecStep`` so compilation can serve
        the row from the materialized ``_tip`` table.
        """
        from impl.common.l2070_server_plan.steps.versioned_query_steps import (
            VersionedQueryFromSpecStep,
        )
        from l7000_versioned_schema.versioned_schema import BranchId, RevisionId

        intent = SelectOneIntent(
            ref_id=ServerPlanRefId("pk_lookup"),
            model_cls=SampleVersionedProduct,
            sys_id=ServerRefs.scalar(SysId.new()),
            config=_SelectOneConfig(),
        )

        def _lower(*, prefer_tip: bool) -> Sequence[Any]:
            return intent.lower(
                LoweringContext(
                    backend_type=BackendType.SQLITE,
                    backend_profile=make_backend_profile(BackendType.SQLITE),
                    is_versioned=True,
                    branch_table="revision_branches",
                    lazy_revision=ServerRefs.from_ref_id("step_1", variant="scalar", type_hint=RevisionId),
                    lazy_branch=ServerRefs.from_ref_id("step_2", variant="scalar", type_hint=BranchId),
                    session_id="11111111-1111-7111-8111-111111111111",
                    prefer_tip_strategy=prefer_tip,
                ),
            )

        tip_lowered = _lower(prefer_tip=True)
        assert any(isinstance(step, VersionedQueryFromSpecStep) for step in tip_lowered)

        sparse_lowered = _lower(prefer_tip=False)
        assert not any(isinstance(step, VersionedQueryFromSpecStep) for step in sparse_lowered)

