    def compile(self: _FFDeleteBranchDataStep, ctx: CompilationContext) -> CompiledStep[None]:
        from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName, SqlTableName
        from impl.common.l2100_sql_grammar.tree.clauses import SqlWhereClause
        from impl.common.l2100_sql_grammar.tree.enums import BinaryOp
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef
        from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp
        from l2070_batching.compilation import CompiledStep as _CompiledStep

        target_id_expr = _resolve_merge_cte_field(ctx, ServerPlanRefId(self._target_ref_id), "sys_id")
        where_expr: SqlRenderable = SqlBinaryOp(
            SqlColumnRef(SqlColumnName("branch_id")),
            BinaryOp.EQ,
            target_id_expr,
        )
        if self._require_target_materialized:
            where_expr = sql_and(
                where_expr,
                _branch_tip_materialized_predicate(
                    ctx,
                    ServerPlanRefId(self._target_ref_id),
                    materialized=True,
                ),
            )
        grammar = SqlDelete(
            table=SqlTableIdent(SqlTableName(self._table)),
            where=SqlWhereClause(where_expr),
        )
        return _CompiledStep(grammar=grammar, needs_returning=False)


class _FFCloseStaleSparseDataStep(NonPublishingStep[None]):
    """Close target sparse rows superseded by source branch sparse rows."""

    __slots__ = (
        "_require_source_tipless",
        "_source_ref_id",
        "_source_tip_ref_id",
        "_sparse_table",
        "_target_ref_id",
    )

    def __init__(
        self: _FFCloseStaleSparseDataStep,
        ref_id: ServerPlanRefId,
        config: _FFCloseStaleSparseDataConfig,
    ) -> None:
        super().__init__(ref_id)
        self._sparse_table = str(config.sparse_table)
        self._source_ref_id = str(config.source_branch_ref_id)
        self._target_ref_id = str(config.target_branch_ref_id)
        self._source_tip_ref_id = str(config.source_tip_revision_ref_id)
        self._require_source_tipless = config.require_source_tipless

    @property
    def level(self: _FFCloseStaleSparseDataStep) -> int:
        return 0

    def result_cardinality(self: _FFCloseStaleSparseDataStep) -> Cardinality:
        return Cardinality.NONE

    def is_read_only(self: _FFCloseStaleSparseDataStep) -> bool:
        return False

    def step_tags(self: _FFCloseStaleSparseDataStep) -> frozenset[str]:
        return frozenset({"write", "merge", "fast_forward", "grammar"})

    def tables_read(self: _FFCloseStaleSparseDataStep) -> frozenset[str]:
        return frozenset({self._sparse_table})

    def tables_written(self: _FFCloseStaleSparseDataStep) -> frozenset[str]:
        return frozenset({self._sparse_table})

    def dependencies(self: _FFCloseStaleSparseDataStep) -> frozenset[str]:
        return frozenset(
            {self._source_ref_id, self._target_ref_id, self._source_tip_ref_id},
        )

    def compile(self: _FFCloseStaleSparseDataStep, ctx: CompilationContext) -> CompiledStep[None]:
        from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName, SqlTableName
        from impl.common.l2100_sql_grammar.tree.clauses import SqlSetItem, SqlWhereClause
        from impl.common.l2100_sql_grammar.tree.enums import BinaryOp
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef
        from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp, SqlIn, SqlIsNull, sql_and
        from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
        from impl.common.l2100_sql_grammar.tree.statements import SqlSelect, SqlUpdate
        from l2070_batching.compilation import CompiledStep as _CompiledStep

        sparse_alias = SqlAliasName("target_sparse")
        source_alias = SqlAliasName("source_sparse")
        source_id_expr = _resolve_merge_cte_field(ctx, ServerPlanRefId(self._source_ref_id), "sys_id")
        target_id_expr = _resolve_merge_cte_field(ctx, ServerPlanRefId(self._target_ref_id), "sys_id")
        source_tip_revision_expr = _resolve_merge_cte_field(
            ctx,
            ServerPlanRefId(self._source_tip_ref_id),
            "v",
        )
        source_sys_ids = SqlSelect(
            select=SqlSelectList([SqlColumnRef(SqlColumnName("sys_id"), str(source_alias))]),
            from_=SqlFrom(SqlTableAlias(SqlTableIdent(SqlTableName(self._sparse_table)), source_alias)),
            where=SqlWhereClause(
                SqlBinaryOp(
                    SqlColumnRef(SqlColumnName("branch_id"), str(source_alias)),
                    BinaryOp.EQ,
                    source_id_expr,
                ),
            ),
        )
        where_expr: SqlRenderable = sql_and(
            SqlBinaryOp(
                SqlColumnRef(SqlColumnName("branch_id"), str(sparse_alias)),
                BinaryOp.EQ,
                target_id_expr,
            ),
            SqlIsNull(
                SqlColumnRef(SqlColumnName("sys_valid_to_revision_id"), str(sparse_alias)),
            ),
            SqlIn(
                SqlColumnRef(SqlColumnName("sys_id"), str(sparse_alias)),
                source_sys_ids,
            ),
        )
        if self._require_source_tipless:
            where_expr = sql_and(
                where_expr,
                _branch_tip_materialized_predicate(
                    ctx,
                    ServerPlanRefId(self._source_ref_id),
                    materialized=False,
                ),
            )
        stmt = SqlUpdate(
            table=SqlTableAlias(
                SqlTableIdent(SqlTableName(self._sparse_table)),
                sparse_alias,
            ),
            set_items=[
                SqlSetItem(SqlColumnName("sys_valid_to_revision_id"), source_tip_revision_expr),
            ],
            where=SqlWhereClause(where_expr),
        )
        return _CompiledStep(grammar=stmt, needs_returning=False)


class _FFCopyTipDataStep(NonPublishingStep[None]):
    """L0: Copy tip data from source branch to target branch during fast-forward merge."""

    __slots__ = (
        "_model",
        "_require_source_materialized",
        "_require_target_materialized",
        "_source_ref_id",
        "_target_ref_id",
        "_tip_table",
    )

    def __init__(
        self: _FFCopyTipDataStep,
        ref_id: ServerPlanRefId,
        config: _FFCopyTipDataConfig,
    ) -> None:
        super().__init__(ref_id)
        self._tip_table = str(config.tip_table)
        self._source_ref_id = str(config.source_branch_ref_id)
        self._target_ref_id = str(config.target_branch_ref_id)
        self._model = config.model
        self._require_source_materialized = config.require_source_materialized
        self._require_target_materialized = config.require_target_materialized

    @property
    def level(self: _FFCopyTipDataStep) -> int:
        return 0

    def result_cardinality(self: _FFCopyTipDataStep) -> Cardinality:
        return Cardinality.NONE

    def is_read_only(self: _FFCopyTipDataStep) -> bool:
        return False

    def step_tags(self: _FFCopyTipDataStep) -> frozenset[str]:
        return frozenset({"write", "merge", "fast_forward", "grammar"})

    def tables_read(self: _FFCopyTipDataStep) -> frozenset[str]:
        tables = {self._tip_table}
        return frozenset(tables)

    def tables_written(self: _FFCopyTipDataStep) -> frozenset[str]:
        return frozenset({self._tip_table})

    def dependencies(self: _FFCopyTipDataStep) -> frozenset[str]:
        return frozenset({self._source_ref_id, self._target_ref_id})

    def compile(self: _FFCopyTipDataStep, ctx: CompilationContext) -> CompiledStep[None]:
        from impl.common.l2050_sql_types.sql_branded_types import (
            SqlColumnName,
            SqlTableName,
        )
        from impl.common.l2070_server_plan.steps.branch_ops_steps import (
            _canonical_type_name_expr_for_copy,
            _get_tip_columns_for_model,
        )
        from impl.common.l2070_server_plan.steps.generated_storage_columns import (
            include_generated_storage_columns,
        )
        from l1000_schema.table_utils import get_table_name
        from l2070_batching.compilation import CompiledStep as _CompiledStep

        tip_columns = _get_tip_columns_for_model(
            self._model,
            include_generated_storage_columns=include_generated_storage_columns(ctx),
        )
        from l1000_schema.physical_adjuncts import TIP_SEQUENCE_COLUMNS

        tip_columns.extend(column for column in sorted(TIP_SEQUENCE_COLUMNS) if column not in tip_columns)
        cached_tip_columns = ctx.schema_column_cache.get(self._tip_table) if ctx.schema_column_cache is not None else None
        if cached_tip_columns is not None:
            tip_columns = [db_col for db_col in tip_columns if db_col in cached_tip_columns]
        base_table = get_table_name(self._model)
        source_alias = SqlAliasName("t")
        src_id_expr = _resolve_merge_cte_field(ctx, ServerPlanRefId(self._source_ref_id), "sys_id")
        tgt_id_expr = _resolve_merge_cte_field(ctx, ServerPlanRefId(self._target_ref_id), "sys_id")

        select_exprs: list[SqlRenderable] = []
        for db_col in tip_columns:
            if db_col == "branch_id":
                select_exprs.append(tgt_id_expr)
                continue
            if db_col == "branch_ord":
                from impl.common.l2100_sql_grammar.domain.versioning.physical_keys import SqlBranchPhysicalKeyScalar

                select_exprs.append(SqlBranchPhysicalKeyScalar(tgt_id_expr))
                continue
            canonical_type_name_expr = _canonical_type_name_expr_for_copy(
                model=self._model,
                source_alias=str(source_alias),
                source_type_name_column=db_col,
                base_table=base_table,
            )
            if canonical_type_name_expr is not None:
                select_exprs.append(canonical_type_name_expr)
                continue
            select_exprs.append(
                SqlColumnRef(
                    SqlColumnName(db_col),
                    str(source_alias),
                ),
            )

        where_expr: SqlRenderable = SqlBinaryOp(
            SqlColumnRef(SqlColumnName("branch_id"), str(source_alias)),
            BinaryOp.EQ,
            src_id_expr,
        )
        if self._require_source_materialized:
            where_expr = sql_and(
                where_expr,
                _branch_tip_materialized_predicate(
                    ctx,
                    ServerPlanRefId(self._source_ref_id),
                    materialized=True,
                ),
            )
        if self._require_target_materialized:
            where_expr = sql_and(
                where_expr,
                _branch_tip_materialized_predicate(
                    ctx,
                    ServerPlanRefId(self._target_ref_id),
                    materialized=True,
                ),
            )
        grammar = SqlInsertFromSelect(
            target_table=SqlTableName(self._tip_table),
            target_columns=tip_columns,
            source_table=SqlTableName(self._tip_table),
            select_exprs=select_exprs,
            where=where_expr,
            source_alias=source_alias,
        )
        return _CompiledStep(grammar=grammar, needs_returning=False)


class _FFCopySparseTipDataStep(_FFCopyTipDataStep):
    """Seed a materialized fast-forward target from a tipless source snapshot."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        config: _FFCopyTipDataConfig,
        *,
        domain: type[VersioningDomain],
        source_revision: ScalarServerRef[RevisionId],
        target_branch: ScalarServerRef[BranchId],
    ) -> None:
        super().__init__(ref_id, config)
        self._domain = domain
        self._source_revision = source_revision
        self._target_branch = target_branch

    def _copy_step(self) -> ServerPlanStep[None]:
        from impl.common.l2070_server_plan.steps.branch_ops_steps import CopySparseTipDataStep

        tables = get_versioned_table_names(self._model)
        return CopySparseTipDataStep(
            self.ref_id,
            tip_table=SqlTableName(self._tip_table),
            sparse_table=tables.sparse,
            idx_table=SqlTableName(get_table_name(self._domain.revision_branch_index_model)),
            revision_parents_table=SqlTableName(get_table_name(self._domain.revision_parent_model)),
            from_revision_id=self._source_revision,
            new_branch_id=self._target_branch,
            model=self._model,
            versioning_domain=self._domain,
        )

    def dependencies(self) -> frozenset[str]:
        return super().dependencies() | self._copy_step().dependencies()

    def tables_read(self) -> frozenset[str]:
        return super().tables_read() | self._copy_step().tables_read()

    def requires_prior_statement_visibility_after_writes(self) -> frozenset[str]:
        return self._copy_step().requires_prior_statement_visibility_after_writes()

    def compile(self, ctx: CompilationContext) -> CompiledStep[None]:
        from dataclasses import replace

        from impl.common.l2100_sql_grammar.domain.versioning.stmt_conditional_gate import (
            SqlGateCte,
            gate_grammar_structurally,
        )
        from impl.common.l2100_sql_grammar.protocols import SqlOuterCteSplitProtocol
        from impl.common.l2100_sql_grammar.tree.statements import SqlCte, SqlCteDefinition

        compiled = self._copy_step().compile(ctx)
        if not isinstance(compiled.grammar, SqlOuterCteSplitProtocol):
            raise TypeError("Sparse tip copying requires a structurally scoped INSERT")
        definitions, body = compiled.grammar.split_for_outer_cte()
        gate_name = SqlCteName(f"ff_sparse_tip_{zlib.adler32(str(self.ref_id).encode()):08x}")
        gate = SqlGateCte(
            sql_and(
                _branch_tip_materialized_predicate(ctx, ServerPlanRefId(self._source_ref_id), materialized=False),
                _branch_tip_materialized_predicate(ctx, ServerPlanRefId(self._target_ref_id), materialized=True),
            )
        )
        return replace(
            compiled,
            grammar=SqlCte(
                (*definitions, SqlCteDefinition(gate_name, gate)),
                gate_grammar_structurally(body, gate_name),
                recursive=True,
            ),
        )


class _FFOverlayAuxiliaryDataStep(NonPublishingStep[None]):
    """Upsert source branch-local auxiliary deltas onto a fast-forward target."""

    __slots__ = ("_config",)

    def __init__(
        self: _FFOverlayAuxiliaryDataStep,
        ref_id: ServerPlanRefId,
        config: _FFOverlayAuxiliaryDataConfig,
    ) -> None:
        super().__init__(ref_id)
        _require_single_ref_dependency(
            config.source_branch,
            owner=type(self).__name__,
            field_name="source_branch",
        )
        _require_single_ref_dependency(
            config.target_branch,
            owner=type(self).__name__,
            field_name="target_branch",
        )
        self._config = config

    @property
    def level(self: _FFOverlayAuxiliaryDataStep) -> int:
        return 0

    def result_cardinality(self: _FFOverlayAuxiliaryDataStep) -> Cardinality:
        return Cardinality.NONE

    def is_read_only(self: _FFOverlayAuxiliaryDataStep) -> bool:
        return False

    def step_tags(self: _FFOverlayAuxiliaryDataStep) -> frozenset[str]:
        return frozenset({"write", "merge", "fast_forward", "graph_auxiliary"})

    def tables_read(self: _FFOverlayAuxiliaryDataStep) -> frozenset[str]:
        return frozenset({str(self._config.table)})

    def tables_written(self: _FFOverlayAuxiliaryDataStep) -> frozenset[str]:
        return frozenset({str(self._config.table)})

    def dependencies(self: _FFOverlayAuxiliaryDataStep) -> frozenset[str]:
        return frozenset(
            {
                *(_ref_dependencies(self._config.source_branch)),
                *(_ref_dependencies(self._config.target_branch)),
                *(str(ref_id) for ref_id, _status in self._config.success_results),
                *(str(ref_id) for ref_id in self._config.depends_on),
            },
        )

    def compile(self: _FFOverlayAuxiliaryDataStep, ctx: CompilationContext) -> CompiledStep[None]:
        from impl.common.l2070_server_plan.steps._query_helper_compile import (
            _collect_auxiliary_ctes_from_consumed,
        )
        from impl.common.l2070_server_plan.steps.branch_ops_steps import _get_tip_columns_for_model
        from impl.common.l2070_server_plan.steps.generated_storage_columns import (
            include_generated_storage_columns,
        )
        from impl.common.l2100_sql_grammar.tree.expr_ops import SqlExists, SqlIn, SqlIsNull, sql_or
        from l2070_batching.compilation import CompiledStep as _CompiledStep

        predicate = (
            sql_or(
                *(
                    SqlBinaryOp(
                        _require_cte_field(ctx, result_ref_id, "status"),
                        BinaryOp.EQ,
                        SqlParam(status),
                    )
                    for result_ref_id, status in self._config.success_results
                ),
            )
            if self._config.success_results
            else SqlBinaryOp(SqlParam(1), BinaryOp.EQ, SqlParam(1))
        )
        columns = _get_tip_columns_for_model(
            self._config.model,
            include_generated_storage_columns=include_generated_storage_columns(ctx),
        )
        cached_columns = ctx.schema_column_cache.get(str(self._config.table)) if ctx.schema_column_cache else None
        if cached_columns is not None:
            columns = [column for column in columns if column in cached_columns]
        source_alias = SqlAliasName("source_aux")
        source_scalar_ref_id = _require_single_ref_dependency(
            self._config.source_branch,
            owner=type(self).__name__,
            field_name="source_branch",
        )
        target_scalar_ref_id = _require_single_ref_dependency(
            self._config.target_branch,
            owner=type(self).__name__,
            field_name="target_branch",
        )
        source_branch = _require_merge_scalar_or_row_field(
            ctx,
            projected_scalar_ref_id=source_scalar_ref_id,
            row_ref_id=ServerPlanRefId("merge.source_branch"),
            row_field_name="sys_id",
        )
        target_branch = _require_merge_scalar_or_row_field(
            ctx,
            projected_scalar_ref_id=target_scalar_ref_id,
            row_ref_id=ServerPlanRefId("merge.target_branch"),
            row_field_name="sys_id",
        )
        select_exprs: list[SqlRenderable] = [
            target_branch if column == "branch_id" else SqlColumnRef(SqlColumnName(column), str(source_alias)) for column in columns
        ]
        update_columns = (
            [column for column in columns if column not in {"branch_id", *self._config.identity_columns}]
            if self._config.update_conflicts
            else [self._config.identity_columns[-1]]
        )
        source_conditions: list[SqlRenderable] = [
            SqlBinaryOp(
                SqlColumnRef(SqlColumnName("branch_id"), str(source_alias)),
                BinaryOp.EQ,
                source_branch,
            ),
            predicate,
        ]
        if self._config.restrict_tree_parents_to_source_tip:
            parent_column = SqlColumnRef(SqlColumnName("parent_sys_id"), str(source_alias))
            edge_parent_sources: list[SqlRenderable] = []
            for index, (scope_key, tip_table, type_names) in enumerate(self._config.tree_parent_sources):
                edge_alias = SqlAliasName(f"source_edge_{index}")
                edge_conditions: list[SqlRenderable] = [
                    SqlBinaryOp(
                        SqlColumnRef(SqlColumnName("branch_id"), str(edge_alias)),
                        BinaryOp.EQ,
                        source_branch,
                    ),
                    SqlBinaryOp(
                        SqlColumnRef(SqlColumnName("graph_sys_id"), str(edge_alias)),
                        BinaryOp.EQ,
                        SqlColumnRef(SqlColumnName("graph_sys_id"), str(source_alias)),
                    ),
                    SqlBinaryOp(
                        SqlColumnRef(SqlColumnName("target_sys_id"), str(edge_alias)),
                        BinaryOp.EQ,
                        SqlColumnRef(SqlColumnName("node_sys_id"), str(source_alias)),
                    ),
                    SqlBinaryOp(
                        SqlColumnRef(SqlColumnName("source_sys_id"), str(edge_alias)),
                        BinaryOp.EQ,
                        parent_column,
                    ),
                    SqlBinaryOp(
                        SqlColumnRef(SqlColumnName("edge_table_name"), str(source_alias)),
                        BinaryOp.EQ,
                        SqlParam(scope_key),
                    ),
                ]
                if type_names:
                    edge_conditions.append(
                        SqlIn(
                            SqlColumnRef(SqlColumnName("type_name"), str(edge_alias)),
                            [SqlParam(type_name) for type_name in type_names],
                        ),
                    )
                edge_parent_sources.append(
                    SqlExists(
                        SqlSelect(
                            select_list=SqlSelectList([SqlStar()]),
                            from_=SqlTableAlias(SqlTableIdent(tip_table), edge_alias),
                            where=SqlWhereClause(sql_and(*edge_conditions)),
                        ),
                    ),
                )
            target_state_alias = SqlAliasName("target_state")
            target_root_exists = SqlExists(
                SqlSelect(
                    select_list=SqlSelectList([SqlStar()]),
                    from_=SqlTableAlias(SqlTableIdent(self._config.table), target_state_alias),
                    where=SqlWhereClause(
                        sql_and(
                            SqlBinaryOp(
                                SqlColumnRef(SqlColumnName("branch_id"), str(target_state_alias)),
                                BinaryOp.EQ,
                                target_branch,
                            ),
                            SqlBinaryOp(
                                SqlColumnRef(SqlColumnName("graph_sys_id"), str(target_state_alias)),
                                BinaryOp.EQ,
                                SqlColumnRef(SqlColumnName("graph_sys_id"), str(source_alias)),
                            ),
                            SqlBinaryOp(
                                SqlColumnRef(SqlColumnName("edge_table_name"), str(target_state_alias)),
                                BinaryOp.EQ,
                                SqlColumnRef(SqlColumnName("edge_table_name"), str(source_alias)),
                            ),
                            SqlBinaryOp(
                                SqlColumnRef(SqlColumnName("node_sys_id"), str(target_state_alias)),
                                BinaryOp.EQ,
                                SqlColumnRef(SqlColumnName("node_sys_id"), str(source_alias)),
                            ),
                            SqlIsNull(
                                SqlColumnRef(SqlColumnName("parent_sys_id"), str(target_state_alias)),
                            ),
                        ),
                    ),
                ),
                negated=True,
            )
            source_conditions.append(
                sql_or(
                    SqlIsNull(parent_column),
                    sql_and(target_root_exists, sql_or(*edge_parent_sources)),
                ),
            )
        grammar = SqlInsertFromSelect(
            target_table=self._config.table,
            target_columns=columns,
            source_table=self._config.table,
            select_exprs=select_exprs,
            where=sql_and(*source_conditions),
            conflict_columns=("branch_id", *self._config.identity_columns),
            update_columns=update_columns,
            source_alias=source_alias,
        )
        consumed_ctes = [
            _consumed_merge_scalar_or_row_cte(
                ctx,
                projected_scalar_ref_id=str(source_scalar_ref_id),
                row_ref_id="merge.source_branch",
            ),
            _consumed_merge_scalar_or_row_cte(
                ctx,
                projected_scalar_ref_id=str(target_scalar_ref_id),
                row_ref_id="merge.target_branch",
            ),
            *(ctx.cte_refs[result_ref_id] for result_ref_id, _status in self._config.success_results if result_ref_id in ctx.cte_refs),
        ]
        return _CompiledStep(
            grammar=grammar,
            needs_returning=False,
            auxiliary_ctes=_collect_auxiliary_ctes_from_consumed(consumed_ctes) or None,
        )


class _DeleteRebaseVisibleNodesForTargetTombstonesStep(NonPublishingStep[None]):
