                ),
            )
            apply_steps.append(
                _ApplyResolvedConflictStep(
                    ref_id=ServerPlanRefId(f"merge.resolved_tip_upsert.{table_name}"),
                    config=_ApplyResolvedConflictConfig(
                        target_branch_ref_id=ServerPlanRefId("merge.target_branch"),
                        merge_revision_id=merge_revision_id_ref,
                        table_name=SqlTableName(table_name),
                        sparse_table=SqlTableName(sparse_table),
                        tip_table=SqlTableName(tip_table),
                        conflict_table=SqlTableName(conflict_table),
                        merge_op_id=cast("Any", merge_op_id),
                        data_columns=tuple(data_columns),
                        model_cls=table_cls,
                        after_refs=frozenset(
                            {
                                resolved_delete_ref,
                                *_fk_parent_apply_refs(domain, child_model=table_cls),
                                *_fk_parent_tip_publish_refs(
                                    domain,
                                    child_model=table_cls,
                                    tip_upsert_ref_prefix="merge.resolved_tip_upsert",
                                    cascade_ref_prefix="merge.resolved_cascade",
                                ),
                            },
                        ),
                        parent_tip_guards=_cascade_parent_tip_guards(domain, table_cls),
                    ),
                    action="upsert_tip",
                ),
            )
        if standard_merge_logs_enabled:
            merge_log_columns = _merge_data_columns(table_cls, merge_log_exclude)
            merge_log_steps.append(
                _AppliedMergeInsertLogEntriesStep(
                    ref_id=ServerPlanRefId(f"merge.log.{table_name}"),
                    config=_AppliedMergeInsertLogEntriesConfig(
                        source_branch_ref_id=ServerPlanRefId("merge.source_branch"),
                        target_branch_ref_id=ServerPlanRefId("merge.target_branch"),
                        lca_ref_id=ServerPlanRefId("merge.lca"),
                        log_table=logged_table_name(table_name),
                        sparse_table=sparse_table,
                        data_columns=tuple(merge_log_columns),
                        session_id=session_id_ref,
                        publish_revision_id=merge_revision_id_ref,
                        revision_table=SqlTableName(revision_table),
                        revision_parents_table=SqlTableName(revision_parents_table),
                    ),
                ),
            )
    index_table = get_table_name(domain.revision_branch_index_model)
    demote_tip = _DemoteMergeBranchTipStep(
        ref_id=ServerPlanRefId("merge.demote_tip"),
        config=_DemoteMergeBranchTipConfig(
            index_table=SqlTableName(index_table),
            target_branch_ref_id=ServerPlanRefId("merge.target_branch"),
        ),
    )
    insert_index = _InsertMergeBranchIndexStep(
        ref_id=ServerPlanRefId("merge.insert_index"),
        config=_InsertMergeBranchIndexConfig(
            index_table=SqlTableName(index_table),
            merge_revision_id=merge_revision_id_ref,
