    update_tip = _UpdateMergeBranchTipStep(
        ref_id=ServerPlanRefId("merge.update_tip"),
        config=_UpdateMergeBranchTipConfig(
            branch_table=SqlTableName(branch_table),
            merge_revision_id=merge_revision_id_ref,
            target_branch_ref_id=ServerPlanRefId("merge.target_branch"),
        ),
    )
    insert_merge_op = _InsertCleanMergeOpStep(
        ref_id=ServerPlanRefId("merge.insert_merge_op"),
        config=_InsertCleanMergeOpConfig(
            scalar_refs=op_meta_refs,
            op_table=SqlTableName(op_table),
            session_id=session_id_ref,
            op_id=cast("Any", merge_op_id),
            merge_revision_id=merge_revision_id_ref,
