def _lower_new_squash_merge_steps(
    *,
    result_ref_id: str,
    domain: type[VersioningDomain],
    workspace_id: ScalarServerRef[WorkspaceId],
    source_branch_name: ScalarServerRef[BranchName],
    target_branch_name: ScalarServerRef[BranchName],
    session_id: SessionId,
    revision_metadata: RevisionMetadataPayload,
    versioned_tables: tuple[type[VersionedObjectRow[SysId]], ...],
    ctx: LoweringContext,
) -> Sequence[ServerPlanStep[Any]]:
    merge_op_id = SysId(str(uuid7()))

    def build_resolve_base_step(op_table_name: str, supports_strategy: bool) -> ServerPlanStep[Any]:
        return _ResolveFreshSquashMergeBaseStep(
            ref_id=ServerPlanRefId("squash_merge.base"),
            config=_ResolveFreshSquashMergeBaseConfig(
                lca_ref_id=ServerPlanRefId("squash_merge.lca"),
                source_branch_ref_id=ServerPlanRefId("squash_merge.source_branch"),
                target_branch_ref_id=ServerPlanRefId("squash_merge.target_branch"),
                lca_scalar_ref_id=ServerPlanRefId("squash_merge.sql.lca_rev_id"),
                source_branch_sys_id_scalar_ref_id=ServerPlanRefId(
                    "squash_merge.sql.source_branch_sys_id",
                ),
                target_tip_scalar_ref_id=ServerPlanRefId(
                    "squash_merge.sql.target_tip_revision_sys_id",
                ),
                target_branch_sys_id_scalar_ref_id=ServerPlanRefId(
                    "squash_merge.sql.target_branch_sys_id",
                ),
                op_table=SqlTableName(op_table_name),
                supports_strategy=supports_strategy,
            ),
        )

    def build_conflict_path_steps[ConflictRecordStepsItemT](
        _conflict_model: type[Any],
        _op_model: type[Any],
        conflict_insert_op: ServerPlanStep[Any],
        conflict_record_steps: list[ServerPlanStep[ConflictRecordStepsItemT]],
    ) -> list[ServerPlanStep[Any]]:
        return [conflict_insert_op, *conflict_record_steps]

    def build_clean_completion_steps(
        _conflict_model: type[Any],
        insert_merge_op: ServerPlanStep[Any],
        _update_existing_merge_op: ServerPlanStep[Any],
    ) -> list[ServerPlanStep[Any]]:
        return [insert_merge_op]

    return _lower_squash_merge_steps_common(
        result_ref_id=result_ref_id,
        domain=domain,
        workspace_id=workspace_id,
        source_branch_name=source_branch_name,
        target_branch_name=target_branch_name,
        session_id=session_id,
        revision_metadata=revision_metadata,
        versioned_tables=versioned_tables,
        merge_op_id=merge_op_id,
        build_resolve_base_step=build_resolve_base_step,
        build_conflict_path_steps=build_conflict_path_steps,
        build_clean_completion_steps=build_clean_completion_steps,
        update_existing_conflict_op=False,
        ctx=ctx,
    )


def _lower_resume_squash_merge_steps(
    *,
    result_ref_id: str,
    domain: type[VersioningDomain],
    workspace_id: ScalarServerRef[WorkspaceId],
    source_branch_name: ScalarServerRef[BranchName],
    target_branch_name: ScalarServerRef[BranchName],
    session_id: SessionId,
    revision_metadata: RevisionMetadataPayload,
    versioned_tables: tuple[type[VersionedObjectRow[SysId]], ...],
    existing_op_id: SysId,
    ctx: LoweringContext,
) -> Sequence[ServerPlanStep[Any]]:
    from impl.common.l2060_query_spec.query_spec import QuerySpec
    from impl.common.l2070_server_plan.steps.merge_three_way_steps import _DeleteMergeConflictsStep
    from l2060_query_builder.query_contracts import QueryFilter

    def build_resolve_base_step(op_table_name: str, supports_strategy: bool) -> ServerPlanStep[Any]:
        return _ResolveExistingSquashMergeBaseStep(
            ref_id=ServerPlanRefId("squash_merge.base"),
            config=_ResolveExistingSquashMergeBaseConfig(
                lca_ref_id=ServerPlanRefId("squash_merge.lca"),
                target_branch_ref_id=ServerPlanRefId("squash_merge.target_branch"),
                lca_scalar_ref_id=ServerPlanRefId("squash_merge.sql.lca_rev_id"),
                target_tip_scalar_ref_id=ServerPlanRefId(
                    "squash_merge.sql.target_tip_revision_sys_id",
                ),
                op_table=SqlTableName(op_table_name),
                supports_strategy=supports_strategy,
                existing_op_id=existing_op_id,
            ),
        )

    def build_conflict_path_steps[ConflictRecordStepsItemT](
        conflict_model: type[Any],
        _op_model: type[Any],
        conflict_insert_op: ServerPlanStep[Any],
        conflict_record_steps: list[ServerPlanStep[ConflictRecordStepsItemT]],
    ) -> list[ServerPlanStep[Any]]:
        clear_existing_conflicts_for_conflict = _DeleteMergeConflictsStep(
            ref_id=ServerPlanRefId("squash_merge.clear_existing_conflicts_for_conflict"),
            conflict_table=SqlTableName(get_table_name(conflict_model)),
            merge_op_id=existing_op_id,
        )
        return [
            clear_existing_conflicts_for_conflict,
            conflict_insert_op,
            *conflict_record_steps,
        ]

    def build_clean_completion_steps(
        conflict_model: type[Any],
        _insert_merge_op: ServerPlanStep[Any],
        update_existing_merge_op: ServerPlanStep[Any],
    ) -> list[ServerPlanStep[Any]]:
        clear_existing_conflicts_spec = QuerySpec(
            model_cls=conflict_model,
            select_columns=None,
            distinct=False,
            joins=[],
            filters=[
                QueryFilter(
                    column="merge_operation_sys_id",
                    operator="=",
                    value=existing_op_id,
                ),
            ],
            order_by=[],
            limit=None,
            offset=None,
            group_by=[],
            aggregations=[],
            having=[],
            window_functions=[],
            permission_grammar=None,
        )
        clear_existing_conflicts = _DeleteMergeConflictsStep(
            ref_id=ServerPlanRefId("squash_merge.clear_existing_conflicts"),
            conflict_table=SqlTableName(get_table_name(conflict_model)),
            merge_op_id=existing_op_id,
        )
        return [clear_existing_conflicts, update_existing_merge_op]

    return _lower_squash_merge_steps_common(
        result_ref_id=result_ref_id,
        domain=domain,
        workspace_id=workspace_id,
        source_branch_name=source_branch_name,
        target_branch_name=target_branch_name,
        session_id=session_id,
        revision_metadata=revision_metadata,
        versioned_tables=versioned_tables,
        merge_op_id=existing_op_id,
        build_resolve_base_step=build_resolve_base_step,
        build_conflict_path_steps=build_conflict_path_steps,
        build_clean_completion_steps=build_clean_completion_steps,
        update_existing_conflict_op=True,
        ctx=ctx,
    )


def _lower_squash_merge_steps_common(
    *,
    result_ref_id: str,
    domain: type[VersioningDomain],
    workspace_id: ScalarServerRef[WorkspaceId],
    source_branch_name: ScalarServerRef[BranchName],
    target_branch_name: ScalarServerRef[BranchName],
    session_id: SessionId,
    revision_metadata: RevisionMetadataPayload,
    versioned_tables: tuple[type[VersionedObjectRow[SysId]], ...],
    merge_op_id: SysId,
    build_resolve_base_step: Callable[[str, bool], ServerPlanStep[Any]],
    build_conflict_path_steps: Callable[..., list[ServerPlanStep[Any]]],
    build_clean_completion_steps: Callable[..., list[ServerPlanStep[Any]]],
    update_existing_conflict_op: bool,
    ctx: LoweringContext,
) -> Sequence[ServerPlanStep[Any]]:
    from impl.common.l2070_server_plan.provider_helpers import (
        require_versioned_lowering_provider,
    )
    from impl.common.l2070_server_plan.steps.branch_mutation_permission import (
        NamedBranchReadPermissionStep,
    )
    from impl.common.l2070_server_plan.steps.conditional_builders import (
        build_one_sided_conditional,
    )
    from impl.common.l2070_server_plan.steps.merge_steps import (
        FetchBranchByNameStep,
        FindLCAStep,
        _FetchBranchByNameConfig,
        _FindLcaConfig,
    )
    from impl.common.l2070_server_plan.steps.merge_three_way_steps import (
        ThreeWayDiffStep,
        _AppliedMergeInsertLogEntriesConfig,
        _AppliedMergeInsertLogEntriesStep,
        _ApplyMergeCloseConfig,
        _ApplyMergeCloseStep,
        _ApplyMergeDeleteTipConfig,
        _ApplyMergeDeleteTipStep,
        _ApplyMergeInsertConfig,
        _ApplyMergeInsertStep,
        _ApplyMergeUpsertTipConfig,
        _ApplyMergeUpsertTipStep,
        _BuildConflictResultConfig,
        _BuildConflictResultStep,
        _ConflictCountFromDiffsConfig,
        _ConflictCountFromDiffsStep,
        _DemoteMergeBranchTipConfig,
        _DemoteMergeBranchTipStep,
        _DeleteMergeConflictsStep,
        _HasConflictsFromDiffsConfig,
        _HasConflictsFromDiffsStep,
        _InsertCleanMergeOpConfig,
        _InsertCleanMergeOpStep,
        _InsertConflictMergeOpConfig,
        _InsertConflictMergeOpStep,
        _InsertConflictRecordsConfig,
        _InsertConflictRecordsStep,
        _InsertMergeBranchIndexConfig,
        _InsertMergeBranchIndexStep,
        _InvertBoolConfig,
        _InvertBoolStep,
        _ProjectMergeOpMetadataScalarConfig,
        _ProjectMergeOpMetadataScalarStep,
        _ThreeWayDiffConfig,
        _UpdateExistingMergeOpConfig,
        _UpdateExistingMergeOpStep,
        _UpdateMergeBranchTipConfig,
        _UpdateMergeBranchTipStep,
        build_merge_operation_scalar_projection_steps,
    )
    from impl.common.l2070_server_plan.steps.squash_steps import (
        BuildSquashMergeCtxStep,
        BuildSquashMergeResultStep,
        InsertSquashMergeParentStep,
        InsertSquashMergeRevisionStep,
        _InsertSquashMergeRevisionConfig,
    )
    from impl.common.l2070_server_plan.steps.versioned_lazy_support import BoolAndStep

    branch_table = get_table_name(domain.branch_model)
    branch_model = domain.branch_model
    revision_table = get_table_name(domain.revision_model)
    revision_parents_table = get_table_name(domain.revision_parent_model)
    index_table = get_table_name(domain.revision_branch_index_model)
    op_model = domain.merge_operation_model
    conflict_model = domain.merge_conflict_model
    op_table = get_table_name(op_model)
    conflict_table = get_table_name(conflict_model)
    sqlite_force_non_batchable = require_versioned_lowering_provider(
        ctx,
    ).force_non_batchable_merge_plan()
    ripple_registry = RippleRegistry.get_instance()
    standard_merge_logs_enabled = False
    if domain.graphs:
        if ripple_registry.domain_has_connection_handlers(domain):
            ripple_registry.require_domain_sql_triggers(domain, connection=True)
        if (
            ctx.backend_profile.traits.eventing_mode is EventingExecutionMode.DATABASE_TRIGGERS
            and ripple_registry.domain_has_standard_handlers(domain)
        ):
            ripple_registry.require_domain_sql_triggers(domain, standard=True)
            standard_merge_logs_enabled = True

    result_revision_id = RevisionId(str(uuid7()))
    result_revision_id_ref = cast("Any", result_revision_id)
    merge_op_id_ref = cast("Any", merge_op_id)
    session_id_ref = cast("Any", session_id)
    squash_parent_id = SysId(str(uuid7()))
    rev_meta = revision_metadata.values

    merge_log_exclude = frozenset(
        {"sys_id", "revision_id", "staged_commit_id", "deleted", "branch_id", "valid_from_revision_id", "valid_to_revision_id"},
    )
    diff_ref_ids: list[str] = []
    diff_steps: list[ServerPlanStep[Any]] = []
    conflict_record_steps: list[ServerPlanStep[Any]] = []
    apply_steps: list[ServerPlanStep[Any]] = []
    merge_log_steps: list[ServerPlanStep[Any]] = []
    table_names: list[str] = []
    for table_cls in versioned_tables:
        physical_tables = get_versioned_table_names(table_cls)
        table_name = physical_tables.base
        sparse_table = physical_tables.sparse
        tip_table = physical_tables.tip
        compare_columns = _merge_data_columns(table_cls, _VERSIONED_COMPARE_EXCLUDE)
        apply_columns = _merge_data_columns(table_cls, _VERSIONED_APPLY_EXCLUDE)
        diff_ref = f"squash_merge.diff.{table_name}"
        diff_ref_ids.append(diff_ref)
        table_names.append(table_name)

        diff_steps.append(
            ThreeWayDiffStep(
                ref_id=ServerPlanRefId(diff_ref),
                config=_ThreeWayDiffConfig(
                    lca_ref_id=ServerPlanRefId("squash_merge.base"),
                    source_branch_ref_id=ServerPlanRefId("squash_merge.source_branch"),
                    target_branch_ref_id=ServerPlanRefId("squash_merge.target_branch"),
                    sparse_table=SqlTableName(sparse_table),
                    data_columns=tuple(apply_columns),
                    revision_table=SqlTableName(revision_table),
                    revision_parents_table=SqlTableName(revision_parents_table),
                ),
            ),
        )
        conflict_record_steps.append(
            _InsertConflictRecordsStep(
                ref_id=ServerPlanRefId(f"squash_merge.conflict_records.{table_name}"),
                config=_InsertConflictRecordsConfig(
                    lca_ref_id=ServerPlanRefId("squash_merge.base"),
                    source_branch_ref_id=ServerPlanRefId("squash_merge.source_branch"),
                    target_branch_ref_id=ServerPlanRefId("squash_merge.target_branch"),
                    merge_op_id=merge_op_id_ref,
                    table_name=SqlTableName(table_name),
                    sparse_table=SqlTableName(sparse_table),
                    conflict_table=SqlTableName(conflict_table),
                    data_columns=tuple(compare_columns),
                    json_columns=_merge_json_columns(table_cls, _VERSIONED_COMPARE_EXCLUDE),
                    revision_table=SqlTableName(revision_table),
                    revision_parents_table=SqlTableName(revision_parents_table),
                ),
            ),
        )
        apply_steps.extend(
            [
                _ApplyMergeCloseStep(
                    ref_id=ServerPlanRefId(f"squash_merge.close.{table_name}"),
                    config=_ApplyMergeCloseConfig(
                        lca_ref_id=ServerPlanRefId("squash_merge.base"),
                        source_branch_ref_id=ServerPlanRefId("squash_merge.source_branch"),
                        target_branch_ref_id=ServerPlanRefId("squash_merge.target_branch"),
                        merge_revision_id=result_revision_id_ref,
                        sparse_table=SqlTableName(sparse_table),
                        data_columns=tuple(apply_columns),
                        revision_table=SqlTableName(revision_table),
                        revision_parents_table=SqlTableName(revision_parents_table),
                    ),
                ),
                _ApplyMergeInsertStep(
                    ref_id=ServerPlanRefId(f"squash_merge.insert.{table_name}"),
                    config=_ApplyMergeInsertConfig(
                        lca_ref_id=ServerPlanRefId("squash_merge.base"),
                        source_branch_ref_id=ServerPlanRefId("squash_merge.source_branch"),
                        target_branch_ref_id=ServerPlanRefId("squash_merge.target_branch"),
                        merge_revision_id=result_revision_id_ref,
                        sparse_table=SqlTableName(sparse_table),
                        data_columns=tuple(apply_columns),
                        revision_table=SqlTableName(revision_table),
                        revision_parents_table=SqlTableName(revision_parents_table),
                    ),
                ),
                _ApplyMergeDeleteTipStep(
                    ref_id=ServerPlanRefId(f"squash_merge.delete_tip.{table_name}"),
                    config=_ApplyMergeDeleteTipConfig(
                        lca_ref_id=ServerPlanRefId("squash_merge.base"),
                        source_branch_ref_id=ServerPlanRefId("squash_merge.source_branch"),
                        target_branch_ref_id=ServerPlanRefId("squash_merge.target_branch"),
                        sparse_table=SqlTableName(sparse_table),
                        tip_table=SqlTableName(tip_table),
                        data_columns=tuple(apply_columns),
                        revision_table=SqlTableName(revision_table),
                        revision_parents_table=SqlTableName(revision_parents_table),
                    ),
                ),
                _ApplyMergeUpsertTipStep(
                    ref_id=ServerPlanRefId(f"squash_merge.upsert_tip.{table_name}"),
                    config=_ApplyMergeUpsertTipConfig(
                        lca_ref_id=ServerPlanRefId("squash_merge.base"),
                        source_branch_ref_id=ServerPlanRefId("squash_merge.source_branch"),
                        target_branch_ref_id=ServerPlanRefId("squash_merge.target_branch"),
                        merge_revision_id=result_revision_id_ref,
                        sparse_table=SqlTableName(sparse_table),
                        tip_table=SqlTableName(tip_table),
                        data_columns=tuple(apply_columns),
                        revision_table=SqlTableName(revision_table),
                        revision_parents_table=SqlTableName(revision_parents_table),
                        after_refs=_fk_parent_tip_publish_refs(
                            domain,
                            child_model=table_cls,
                            tip_upsert_ref_prefix="squash_merge.upsert_tip",
                            cascade_ref_prefix=None,
                        ),
                        parent_tip_guards=_cascade_parent_tip_guards(domain, table_cls),
                    ),
                ),
            ],
        )
        from impl.common.l2070_server_plan.steps.merge_embedding_refs import (
            build_merge_embedding_ref_steps,
        )

        apply_steps.extend(
            build_merge_embedding_ref_steps(
                table_cls,
                _ApplyMergeInsertConfig(
                    lca_ref_id=ServerPlanRefId("squash_merge.base"),
                    source_branch_ref_id=ServerPlanRefId("squash_merge.source_branch"),
                    target_branch_ref_id=ServerPlanRefId("squash_merge.target_branch"),
                    merge_revision_id=result_revision_id_ref,
                    sparse_table=SqlTableName(sparse_table),
                    data_columns=tuple(apply_columns),
                    revision_table=SqlTableName(revision_table),
                    revision_parents_table=SqlTableName(revision_parents_table),
                    after_refs=frozenset({ServerPlanRefId(f"squash_merge.upsert_tip.{table_name}")}),
                ),
                prefix=f"squash_merge.embedding_refs.{table_name}",
                planning_catalog=ctx.planning_catalog,
            )
        )
        if standard_merge_logs_enabled:
            merge_log_columns = _merge_data_columns(table_cls, merge_log_exclude)
            merge_log_steps.append(
                _AppliedMergeInsertLogEntriesStep(
                    ref_id=ServerPlanRefId(f"squash_merge.log.{table_name}"),
                    config=_AppliedMergeInsertLogEntriesConfig(
                        source_branch_ref_id=ServerPlanRefId("squash_merge.source_branch"),
                        target_branch_ref_id=ServerPlanRefId("squash_merge.target_branch"),
                        lca_ref_id=ServerPlanRefId("squash_merge.base"),
                        log_table=logged_table_name(table_name),
                        sparse_table=sparse_table,
                        data_columns=tuple(merge_log_columns),
                        session_id=session_id_ref,
                        publish_revision_id=result_revision_id_ref,
                        revision_table=SqlTableName(revision_table),
                        revision_parents_table=SqlTableName(revision_parents_table),
                    ),
                ),
            )

    source_branch_guard = NamedBranchReadPermissionStep(
        ServerPlanRefId("squash_merge.source_branch_permission"),
        model=branch_model,
        branch_name=source_branch_name,
        workspace_id=workspace_id,
        session_id=session_id,
    )
    target_branch_guard = NamedBranchReadPermissionStep(
        ServerPlanRefId("squash_merge.target_branch_permission"),
        model=branch_model,
        branch_name=target_branch_name,
        workspace_id=workspace_id,
        session_id=session_id,
        action="update",
    )
    fetch_source = FetchBranchByNameStep(
        ref_id=ServerPlanRefId("squash_merge.source_branch"),
        config=_FetchBranchByNameConfig(
            branch_name=source_branch_name,
            branch_table=SqlTableName(branch_table),
            workspace_id=workspace_id,
            branch_model=branch_model,
            reset_merge_sql_materialization_caches=True,
        ),
    )
    fetch_target = FetchBranchByNameStep(
        ref_id=ServerPlanRefId("squash_merge.target_branch"),
        config=_FetchBranchByNameConfig(
            branch_name=target_branch_name,
            branch_table=SqlTableName(branch_table),
            workspace_id=workspace_id,
            branch_model=branch_model,
        ),
    )
    validate_source = _ValidateSourceHasTipStep(
        ref_id=ServerPlanRefId("squash_merge.validate_source"),
        config=_ValidateSourceHasTipConfig(
            source_branch_ref_id=ServerPlanRefId("squash_merge.source_branch"),
            branch_model=branch_model,
        ),
    )
    find_lca = FindLCAStep(
        ref_id=ServerPlanRefId("squash_merge.lca"),
        config=_FindLcaConfig(
            source_branch_ref_id=ServerPlanRefId("squash_merge.source_branch"),
            target_branch_ref_id=ServerPlanRefId("squash_merge.target_branch"),
            revision_table=SqlTableName(revision_table),
            revision_parents_table=SqlTableName(revision_parents_table),
            revision_model=domain.revision_model,
            revision_parent_model=domain.revision_parent_model,
            force_non_batchable=False,
        ),
    )
    squash_merge_sql_scalar_steps: list[ServerPlanStep[Any]] = [
        _ProjectMergeOpMetadataScalarStep(
            ServerPlanRefId("squash_merge.sql.source_branch_sys_id"),
            _ProjectMergeOpMetadataScalarConfig(
                row_ref_id=ServerPlanRefId("squash_merge.source_branch"),
                field_name="sys_id",
            ),
        ),
        _ProjectMergeOpMetadataScalarStep(
            ServerPlanRefId("squash_merge.sql.target_tip_revision_sys_id"),
            _ProjectMergeOpMetadataScalarConfig(
                row_ref_id=ServerPlanRefId("squash_merge.target_branch"),
                field_name="tip_revision_sys_id",
            ),
        ),
        _ProjectMergeOpMetadataScalarStep(
            ServerPlanRefId("squash_merge.sql.target_branch_sys_id"),
            _ProjectMergeOpMetadataScalarConfig(
                row_ref_id=ServerPlanRefId("squash_merge.target_branch"),
                field_name="sys_id",
            ),
        ),
        _ProjectMergeOpMetadataScalarStep(
            ServerPlanRefId("squash_merge.sql.lca_rev_id"),
            _ProjectMergeOpMetadataScalarConfig(
                row_ref_id=ServerPlanRefId("squash_merge.lca"),
                field_name="rev_id",
            ),
        ),
    ]
    resolve_base = build_resolve_base_step(
        op_table,
        "strategy" in op_model.model_fields,
    )
    squash_op_meta_steps, squash_op_meta_refs = build_merge_operation_scalar_projection_steps(
        ref_prefix="squash_merge",
        source_branch_ref_id="squash_merge.source_branch",
        target_branch_ref_id="squash_merge.target_branch",
        base_revision_ref_id="squash_merge.base",
    )
    from impl.common.l2070_server_plan.steps.merge_replay_permission import FastForwardMergePermissionStep
    from impl.common.l2070_server_plan.steps.replay_permission import replay_actions_are_unconditional

    squash_permission_steps: list[ServerPlanStep[Any]] = [
        FastForwardMergePermissionStep(
            ServerPlanRefId(f"squash_merge.permission_{get_table_name(model)}"),
            domain=domain,
            model=model,
            source_branch_ref=squash_op_meta_refs.source_branch_sys_id,
            target_branch_ref=squash_op_meta_refs.target_branch_sys_id,
            source_tip_ref=squash_op_meta_refs.source_tip_revision_sys_id,
            target_tip_ref=squash_op_meta_refs.target_tip_revision_sys_id,
            base_revision_ref=squash_op_meta_refs.base_revision_sys_id,
            session=session_id_ref,
        )
        for model in versioned_tables
        if not replay_actions_are_unconditional(model)
    ]
    utd_result = _BuildUTDResultStep(
        ref_id=ServerPlanRefId("squash_merge.result_utd"),
        config=_BuildUTDResultConfig(
            source_branch_ref_id=ServerPlanRefId("squash_merge.source_branch"),
            target_branch_ref_id=ServerPlanRefId("squash_merge.target_branch"),
            reuse_target_tip_as_result_revision=False,
            predicate_ref_id=ServerPlanRefId("squash_merge.no_source_changes"),
        ),
    )
    has_source_changes = _HasSourceChangesFromDiffsStep(
        ref_id=ServerPlanRefId("squash_merge.has_source_changes"),
        config=_HasSourceChangesFromDiffsConfig(
            diff_ref_ids=tuple(ServerPlanRefId(ref_id) for ref_id in diff_ref_ids),
        ),
    )
    no_source_changes = _InvertBoolStep(
        ref_id=ServerPlanRefId("squash_merge.no_source_changes"),
        config=_InvertBoolConfig(
            source_ref_id=ServerPlanRefId("squash_merge.has_source_changes"),
        ),
    )
    build_ctx = BuildSquashMergeCtxStep(
        ref_id=ServerPlanRefId("squash_merge.ctx"),
        source_branch_ref_id=ServerPlanRefId("squash_merge.source_branch"),
        target_branch_ref_id=ServerPlanRefId("squash_merge.target_branch"),
        lca_ref_id=ServerPlanRefId("squash_merge.base"),
        operation_id=merge_op_id,
        result_revision_id=result_revision_id_ref,
    )
    has_conflicts = _HasConflictsFromDiffsStep(
        ref_id=ServerPlanRefId("squash_merge.has_conflicts"),
        config=_HasConflictsFromDiffsConfig(
            diff_ref_ids=tuple(ServerPlanRefId(ref_id) for ref_id in diff_ref_ids),
        ),
    )
    conflict_count = _ConflictCountFromDiffsStep(
        ref_id=ServerPlanRefId("squash_merge.conflict_count"),
        config=_ConflictCountFromDiffsConfig(
            diff_ref_ids=tuple(ServerPlanRefId(ref_id) for ref_id in diff_ref_ids),
        ),
    )
    no_conflicts = _InvertBoolStep(
        ref_id=ServerPlanRefId("squash_merge.no_conflicts"),
        config=_InvertBoolConfig(
            source_ref_id=ServerPlanRefId("squash_merge.has_conflicts"),
        ),
    )
    clean_allowed = BoolAndStep(
        ServerPlanRefId("squash_merge.clean_allowed"),
        left_ref="squash_merge.has_source_changes",
        right_ref="squash_merge.no_conflicts",
    )
    conflict_insert_op = _InsertConflictMergeOpStep(
        ref_id=ServerPlanRefId("squash_merge.conflict_insert_op"),
        config=_InsertConflictMergeOpConfig(
            scalar_refs=squash_op_meta_refs,
            op_table=SqlTableName(op_table),
            session_id=session_id_ref,
            op_id=merge_op_id_ref,
            diff_ref_ids=tuple(ServerPlanRefId(ref_id) for ref_id in diff_ref_ids),
            conflict_count_ref=ServerPlanRefId("squash_merge.conflict_count"),
            update_existing=update_existing_conflict_op,
            strategy="squash_merge",
        ),
    )
    conflict_result = _BuildConflictResultStep(
        ref_id=ServerPlanRefId("squash_merge.result_conflict"),
        config=_BuildConflictResultConfig(
            source_branch_ref_id=ServerPlanRefId("squash_merge.source_branch"),
            target_branch_ref_id=ServerPlanRefId("squash_merge.target_branch"),
            lca_ref_id=ServerPlanRefId("squash_merge.base"),
            op_id=merge_op_id_ref,
            diff_ref_ids=tuple(ServerPlanRefId(ref_id) for ref_id in diff_ref_ids),
            table_names=tuple(SqlTableName(table_name) for table_name in table_names),
        ),
    )
    conflict_path_steps = build_conflict_path_steps(
        conflict_model,
        op_model,
        conflict_insert_op,
        conflict_record_steps,
    )
    conflict_path_steps.append(conflict_result)

    insert_revision = InsertSquashMergeRevisionStep(
        ref_id=ServerPlanRefId("squash_merge.insert_revision"),
        config=_InsertSquashMergeRevisionConfig(
            target_branch_ref_id=ServerPlanRefId("squash_merge.target_branch"),
            target_tip_scalar_ref_id=ServerPlanRefId(squash_op_meta_refs.target_tip_revision_sys_id),
            result_revision_id=result_revision_id_ref,
            revision_table=SqlTableName(revision_table),
            revision_model_cls=domain.revision_model,
            session_id=session_id_ref,
            revision_metadata=rev_meta,
        ),
    )
    from impl.common.l2070_server_plan.steps.squash_steps import RevisionParentOrdinal

    insert_parent = InsertSquashMergeParentStep(
        ref_id=ServerPlanRefId("squash_merge.insert_parent"),
        target_branch_ref_id=ServerPlanRefId("squash_merge.target_branch"),
        target_tip_scalar_ref_id=ServerPlanRefId(squash_op_meta_refs.target_tip_revision_sys_id),
        result_revision_id=result_revision_id_ref,
        revision_parents_table=SqlTableName(revision_parents_table),
        ordinal=RevisionParentOrdinal(0),
        parent_sys_id=squash_parent_id,
    )
    demote_tip = _DemoteMergeBranchTipStep(
        ref_id=ServerPlanRefId("squash_merge.demote_tip"),
        config=_DemoteMergeBranchTipConfig(
            index_table=SqlTableName(index_table),
            target_branch_ref_id=ServerPlanRefId("squash_merge.target_branch"),
        ),
    )
    insert_index = _InsertMergeBranchIndexStep(
        ref_id=ServerPlanRefId("squash_merge.insert_index"),
        config=_InsertMergeBranchIndexConfig(
            index_table=SqlTableName(index_table),
            merge_revision_id=result_revision_id_ref,
            target_branch_ref_id=ServerPlanRefId("squash_merge.target_branch"),
        ),
    )
    update_tip = _UpdateMergeBranchTipStep(
        ref_id=ServerPlanRefId("squash_merge.update_tip"),
        config=_UpdateMergeBranchTipConfig(
            branch_table=SqlTableName(branch_table),
            merge_revision_id=result_revision_id_ref,
            target_branch_ref_id=ServerPlanRefId("squash_merge.target_branch"),
        ),
    )
    insert_merge_op = _InsertCleanMergeOpStep(
        ref_id=ServerPlanRefId("squash_merge.insert_merge_op"),
        config=_InsertCleanMergeOpConfig(
            scalar_refs=squash_op_meta_refs,
            op_table=SqlTableName(op_table),
            session_id=session_id_ref,
            op_id=merge_op_id_ref,
            merge_revision_id=result_revision_id_ref,
            strategy="squash_merge",
        ),
    )
    update_existing_merge_op = _UpdateExistingMergeOpStep(
        ref_id=ServerPlanRefId("squash_merge.update_existing_merge_op"),
        config=_UpdateExistingMergeOpConfig(
            scalar_refs=squash_op_meta_refs,
            op_table=SqlTableName(op_table),
            op_id=merge_op_id_ref,
            merge_revision_id=result_revision_id_ref,
            strategy="squash_merge",
        ),
    )
    clean_completion_steps = build_clean_completion_steps(
        conflict_model,
        insert_merge_op,
        update_existing_merge_op,
    )
    clean_path_steps: list[ServerPlanStep[Any]] = [insert_revision, insert_parent]
    clean_path_steps.extend(apply_steps)
    clean_path_steps.extend(merge_log_steps)
    clean_path_steps.extend([demote_tip, insert_index, update_tip])
    clean_path_steps.extend(clean_completion_steps)
    clean_result = BuildSquashMergeResultStep(
        ref_id=ServerPlanRefId("squash_merge.result_clean"),
        ctx_ref_id=ServerPlanRefId("squash_merge.ctx"),
        diff_ref_ids=[ServerPlanRefId(ref_id) for ref_id in diff_ref_ids],
        completion_ref_id=ServerPlanRefId(f"{clean_completion_steps[-1].ref_id}__gate"),
        source_changes_ref_id=ServerPlanRefId("squash_merge.has_source_changes"),
    )
    conflict_gated_steps = _gate_branch_steps(
        condition_ref="squash_merge.has_conflicts",
        branch_steps=conflict_path_steps,
        force_non_batchable=sqlite_force_non_batchable,
    )
    clean_gated_steps = _gate_branch_steps(
        condition_ref="squash_merge.clean_allowed",
        branch_steps=clean_path_steps,
        force_non_batchable=sqlite_force_non_batchable,
    )
    squash_auxiliary_steps: list[ServerPlanStep[Any]] = []
    if domain.graphs:
        from impl.common.l2070_server_plan.steps.barrier import BarrierStep
        from impl.common.l2070_server_plan.steps.commit_branch_steps import ReconcileGraphAuxiliaryTablesStep
        from impl.common.l2070_server_plan.steps.edge_constraint_steps import CheckDirtyGraphTreeValidityStep
        from l2070_batching.staged_source import PublishScopeDescriptor, opaque_scope_token
        from l9600_graphs.incremental_validation_models import tree_edge_state_scopes

        target_branch_scalar_ref = ServerPlanRefId(_ff_scalar_step_ref_ids("squash_auxiliary")[0])
        squash_auxiliary_steps.append(
            _ProjectMergeOpMetadataScalarStep(
                target_branch_scalar_ref,
                _ProjectMergeOpMetadataScalarConfig(
                    row_ref_id=ServerPlanRefId("squash_merge.target_branch"),
                    field_name="sys_id",
                ),
            ),
        )
        auxiliary_boundary_ref = ServerPlanRefId("squash_merge.auxiliary_boundary")
        squash_auxiliary_steps.append(
            BarrierStep(
                auxiliary_boundary_ref,
                depends_on=frozenset(
                    {
                        ServerPlanRefId("squash_merge.result_utd"),
                        ServerPlanRefId("squash_merge.result_conflict"),
                        ServerPlanRefId("squash_merge.result_clean"),
                        target_branch_scalar_ref,
                    },
                ),
                requires_prior_boundary=True,
            ),
        )
        target_branch_ref = ServerRefs.from_ref_id(
            str(target_branch_scalar_ref),
            variant="scalar",
            type_hint=BranchId,
        )
        validation_dependencies = frozenset({auxiliary_boundary_ref})
        full_tip_scope = PublishScopeDescriptor(
            kind="explicit",
            branch_scope_token=opaque_scope_token(target_branch_ref),
            staged_commit_ids=(),
        )
        for index, scope in enumerate(tree_edge_state_scopes(domain)):
            validation_ref = ServerPlanRefId(f"squash_merge.validate_tree_{index}")
            edge_tip_table = derive_versioned_table_names(
                VersionedBaseTableName(scope.edge_table_name),
            ).tip
            squash_auxiliary_steps.append(
                CheckDirtyGraphTreeValidityStep(
                    validation_ref,
                    edge_tip_table=edge_tip_table,
                    edge_staged_table=edge_tip_table,
                    edge_base_table=SqlTableName(scope.edge_table_name),
                    lazy_branch=target_branch_ref,
                    publish_scope=full_tip_scope,
                    depends_on=validation_dependencies,
                    type_name_filter=scope.type_name_filter,
                    validate_full_tip=True,
                    branch_lookup=(SqlTableName(branch_table), workspace_id, target_branch_name),
                ),
            )
            validation_dependencies = frozenset({validation_ref})
        validation_boundary_ref = ServerPlanRefId("squash_merge.tree_validation_boundary")
        squash_auxiliary_steps.append(
            BarrierStep(
                validation_boundary_ref,
                depends_on=validation_dependencies,
                requires_prior_boundary=True,
            ),
        )
        squash_auxiliary_steps.append(
            ReconcileGraphAuxiliaryTablesStep(
                ServerPlanRefId("squash_merge.reconcile_graph_auxiliary"),
                domain=domain,
                branch_ref=cast(
                    "Any",
                    ServerRefs.from_ref_id(
                        str(target_branch_scalar_ref),
                        variant="scalar",
                        type_hint=BranchId,
                    ),
                ),
                depends_on=frozenset({validation_boundary_ref}),
            ),
        )
    collector = _MergeResultCollectorStep(
        ref_id=ServerPlanRefId(result_ref_id),
        config=_MergeResultCollectorConfig(
            result_refs=(
                ServerPlanRefId("squash_merge.result_utd"),
                ServerPlanRefId("squash_merge.result_conflict"),
                ServerPlanRefId("squash_merge.result_clean"),
            ),
        ),
    )
    return [
        source_branch_guard,
        target_branch_guard,
        fetch_source,
        fetch_target,
        validate_source,
        find_lca,
        *squash_merge_sql_scalar_steps,
        resolve_base,
        *squash_op_meta_steps,
        build_ctx,
        *squash_permission_steps,
        *diff_steps,
        has_source_changes,
        no_source_changes,
        utd_result,
        has_conflicts,
        conflict_count,
        no_conflicts,
        clean_allowed,
        *conflict_gated_steps,
        *clean_gated_steps,
        clean_result,
        *squash_auxiliary_steps,
        collector,
    ]


class SquashBranchIntent(IntentStep[RevisionId]):
    """L4: Squash a linear ``(base, tip]`` range into one replacement revision."""

    intent_tags = frozenset({"squash", "intent"})

    __slots__ = (
        "_base_revision_id",
        "_branch_name",
        "_domain",
        "_revision_metadata",
        "_session_id",
        "_workspace_id",
    )

    def __init__(
        self: SquashBranchIntent,
        ref_id: ServerPlanRefId,
        *,
        domain: type[VersioningDomain],
        workspace_id: ScalarServerRef[WorkspaceId],
        branch_name: ScalarServerRef[BranchName],
        base_revision_id: ScalarServerRef[RevisionId],
        session_id: ScalarServerRef[SessionId],
        revision_metadata: ObjectServerRef[RevisionMetadataPayload],
    ) -> None:
