    return ServerPlanRefId(value)


def _plan_refs(
    values: Sequence[ServerPlanRefId | str] | frozenset[ServerPlanRefId | str],
) -> frozenset[ServerPlanRefId]:
    return frozenset(_plan_ref(value) for value in values)


def _require_compiled_embedding_sql_ir(compiled: CompiledStep[list[object]]) -> Any:
    sql_ir = compiled.materialize_ir()
    if sql_ir is not None:
        return sql_ir
    msg = "Expected compiled embedding row source to materialize SQL IR"
    raise TypeError(msg)


def _require_embedding_post_write_select(post_write_select: SqlRenderable | None) -> SqlRenderable:
    if post_write_select is not None:
        return post_write_select
    msg = "Non-returning embedding write result requires a SQL post-write select relation"
    raise ValueError(msg)


def _require_resolved_value_source_cte(
    ctx: CompilationContext,
    source_ref: ServerPlanRefId,
) -> CteReference:
    source_cte = ctx.cte_refs.get(source_ref)
    if isinstance(source_cte, CteReference) and source_cte.columns:
        return source_cte
    msg = (
        "_ResolvedValueAfterDepsStep requires a SQL-visible source relation with "
        f"declared columns for {source_ref!r}; runtime-ref passthrough is forbidden."
    )
    raise RuntimeError(msg)


def _require_pending_vector_rows_cte(
    ctx: CompilationContext,
    instances_ref: ServerPlanRefId,
    *,
    step_name: str,
) -> CteReference:
    binding = ctx.cte_refs.get(instances_ref)
    if isinstance(binding, CteReference) and binding.columns:
        return binding
    if isinstance(binding, CteReference):
        msg = f"{step_name} requires pending vector rows at {instances_ref!r} to declare output columns."
    else:
        msg = f"{step_name} requires pending vector rows at {instances_ref!r} to be SQL-visible via ctx.cte_refs."
    raise RuntimeError(msg)


def _require_pending_vector_columns(
    binding: CteReference,
    required_columns: tuple[str, ...],
    *,
    step_name: str,
    instances_ref: ServerPlanRefId,
) -> None:
    assert binding.columns is not None
    missing_columns = [column for column in required_columns if column not in binding.columns]
    if not missing_columns:
        return
    msg = f"{step_name} pending vector rows at {instances_ref!r} are missing required columns: {', '.join(missing_columns)}."
    raise RuntimeError(msg)


