class _ResolveVisibleEmbeddingContentHashStep(
    MaybeSqlRelationPublisherStep[_ResolvedEmbeddingHash | RawResult],
):
    """Resolve a visible-source embedding content hash from runtime-published inputs."""

    def __init__(
        self: _ResolveVisibleEmbeddingContentHashStep,
        ref_id: ServerPlanRefId,
        config: _ResolveVisibleEmbeddingContentHashConfig,
    ) -> None:
        super().__init__(ref_id)
        self._model_cls = config.model_cls
        self._index_name = config.index_name
        self._metadata_ref = str(config.metadata_ref)
        self._source_ref = None if config.source_ref is None else str(config.source_ref)
        self._source_rows_ref = None if config.source_rows_ref is None else str(config.source_rows_ref)
        self._source_id = config.source_id
        self._source_obj = config.source_obj
        self._source_objs = config.source_objs
        self._canonical_model_hint = config.canonical_model_hint
        self._batch = config.batch
        self._after_refs = frozenset(str(ref_id) for ref_id in config.after_refs)

    @property
    def level(self: _ResolveVisibleEmbeddingContentHashStep) -> int:
        return 0

    def result_cardinality(self: _ResolveVisibleEmbeddingContentHashStep) -> Cardinality:
        return Cardinality.MANY if self._batch else Cardinality.ONE

    def is_read_only(self: _ResolveVisibleEmbeddingContentHashStep) -> bool:
        return True

    def execution_role(self: _ResolveVisibleEmbeddingContentHashStep) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def supports_sql_batch_transport(self: _ResolveVisibleEmbeddingContentHashStep) -> bool:
        return True

    def dependencies(self: _ResolveVisibleEmbeddingContentHashStep) -> frozenset[str]:
        deps = {self._metadata_ref, *self._after_refs}
        if self._source_ref is not None:
            deps.add(self._source_ref)
        if self._source_rows_ref is not None:
            deps.add(self._source_rows_ref)
        return frozenset(deps)

    def requires_prior_step_boundary(self: _ResolveVisibleEmbeddingContentHashStep) -> bool:
        return True

    def sql_visible_dependencies(self: _ResolveVisibleEmbeddingContentHashStep) -> frozenset[str]:
        deps = {self._metadata_ref}
        if self._source_ref is not None:
            deps.add(self._source_ref)
        if self._source_rows_ref is not None:
            deps.add(self._source_rows_ref)
        return frozenset(deps)

    def tables_read(self: _ResolveVisibleEmbeddingContentHashStep) -> frozenset[str]:
        from l1000_schema.table_utils import get_table_name
        from l5200_vector_index.embedding_metadata import EmbeddingMetadata

        return frozenset({get_table_name(self._model_cls), get_table_name(EmbeddingMetadata)})

    def tables_written(self: _ResolveVisibleEmbeddingContentHashStep) -> frozenset[str]:
        return frozenset()

    def step_tags(self: _ResolveVisibleEmbeddingContentHashStep) -> frozenset[str]:
        return frozenset({"read", "embedding", "hash"})

    def cte_relation_role(self: _ResolveVisibleEmbeddingContentHashStep) -> str:
        """Identify the producer-owned embedding hash relation contract."""
        return "embedding_hash"

    def cte_publication_contract(self: _ResolveVisibleEmbeddingContentHashStep) -> CtePublicationContract:
        columns = ("source_object_id", "hash_short", "hash_high")
        column_type_hints = SqlColumnTypeHints(
            bigint_columns=frozenset({"hash_short", "hash_high"}),
            text_columns=frozenset({"source_object_id"}),
        )
        if columns is None:
            if column_type_hints is not None and column_type_hints.has_any():
                msg = f"{type(self).__name__} declares SQL column type hints without an explicit cte_output_columns() contract."
                raise TypeError(msg)
            return CtePublicationContract.non_publishing()
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=tuple(str(column) for column in columns),
            column_type_hints=column_type_hints,
            relation_contract=CteRelationContract.semantic_row(_ResolveVisibleEmbeddingContentHashStepCteRow),
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def compile(
        self: _ResolveVisibleEmbeddingContentHashStep,
        ctx: CompilationContext,
    ) -> CompiledStep[_ResolvedEmbeddingHash | RawResult]:
        return runtime_resolve_visible_embedding_content_hash_compiled_step(
            metadata_ref=self._metadata_ref,
            ctx=ctx,
            source_ref=self._source_ref,
            source_rows_ref=self._source_rows_ref,
            source_id=self._source_id,
            source_obj=self._source_obj,
            source_objs=self._source_objs,
            model_cls=self._model_cls,
            index_name=SqlIndexName(self._index_name),
            step_ref=str(self.ref_id),
            canonical_model_hint=self._canonical_model_hint,
            batch=self._batch,
        )


def _source_presence_ref_from_steps[SourceStepsItemT](
    source_steps: Sequence[ServerPlanStep[SourceStepsItemT]],
    fallback_ref: ServerPlanRefId,
) -> ServerPlanRefId:
    for step in reversed(source_steps):
        if step.always_publishes_executor_visible_binding():
            return step.ref_id
    if source_steps:
        source_ref = source_steps[-1].publication_source_ref()
        if source_ref is not None:
            return source_ref
    return fallback_ref


class _RequireResolvedSourceStep(NonPublishingStep[None]):
    """Raise a stable ValueError if a prerequisite source row was not resolved."""

    def __init__(
        self: _RequireResolvedSourceStep,
        ref_id: ServerPlanRefId,
        config: _RequireResolvedSourceConfig,
    ) -> None:
        super().__init__(ref_id)
        self._source_ref = ServerPlanRefId(config.source_ref)
        self._error_message = config.error_message
        self._expected_count = config.expected_count

    @property
    def level(self: _RequireResolvedSourceStep) -> int:
        return 0

    def result_cardinality(self: _RequireResolvedSourceStep) -> Cardinality:
        return Cardinality.NONE

    def is_read_only(self: _RequireResolvedSourceStep) -> bool:
        return True

    def execution_role(self: _RequireResolvedSourceStep) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def supports_sql_batch_transport(self: _RequireResolvedSourceStep) -> bool:
        return False

    def consumes_executor_visible_dependencies(self: _RequireResolvedSourceStep) -> bool:
        return True

    def dependencies(self: _RequireResolvedSourceStep) -> frozenset[str]:
        return frozenset({self._source_ref})

    def tables_read(self: _RequireResolvedSourceStep) -> frozenset[str]:
        return frozenset()

    def tables_written(self: _RequireResolvedSourceStep) -> frozenset[str]:
        return frozenset()

    def step_tags(self: _RequireResolvedSourceStep) -> frozenset[str]:
        return frozenset({"read", "validation"})

    def compile(self: _RequireResolvedSourceStep, ctx: CompilationContext) -> CompiledStep[None]:
        from impl.common.l2050_sql_types.sql_branded_types import SqlAliasName, SqlColumnName, SqlTableName
        from impl.common.l2070_server_plan.steps._runtime_replanning_error import (
            raise_missing_cte_fallback_forbidden,
        )
        from impl.common.l2100_sql_grammar.tree.clauses import SqlSelectAlias, SqlSelectList, SqlWhereClause
        from impl.common.l2100_sql_grammar.tree.enums import BinaryOp
        from impl.common.l2100_sql_grammar.tree.expr_compound import SqlFuncCall, SqlSubquery
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlParam
        from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp
        from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
        from impl.common.l2100_sql_grammar.tree.statements import SqlSelect
        from l2070_batching.post_op import raw_rows_post_op

        source_cte = ctx.cte_refs.get(self._source_ref)
        if not isinstance(source_cte, CteReference):
            raise_missing_cte_fallback_forbidden(
                site_name="_RequireResolvedSourceStep.compile",
                trigger=f"source ref {self._source_ref!r} has no SQL-visible source rowset",
                blocked_path="_RequireResolvedSourceStep cannot validate source presence through Python runtime refs.",
                result_contract="source presence validation must be a SQL NOT EXISTS exception fact.",
                implementation_requirements=(
                    "Publish the source row lookup as a SQL-visible CTE.",
                    "Use terminal Python only to raise when the SQL missing-source relation emits a row.",
                ),
            )
        probe_column = source_cte.columns[0] if source_cte.columns else "sys_id"
        source_count = SqlSelect(
            select=SqlSelectList(
                [SqlFuncCall("COUNT", [SqlColumnRef(SqlColumnName(probe_column))])],
            ),
            from_=SqlTableIdent(SqlTableName(source_cte.ref_id)),
        )
        grammar = SqlSelect(
            select=SqlSelectList(
                [
                    SqlSelectAlias(SqlParam(True), SqlAliasName("missing_source")),
                    SqlSelectAlias(SqlSubquery(source_count), SqlAliasName("actual_count")),
                ],
            ),
            where=SqlWhereClause(
                SqlBinaryOp(
                    SqlSubquery(source_count),
                    BinaryOp.NE,
                    SqlParam(self._expected_count),
                ),
            ),
        )
        __opa002_grammar_365 = grammar
        output_shape = CompiledOutputShape(
            (
                synthetic_output_field("missing_source"),
                synthetic_output_field("actual_count"),
            ),
        )
        column_type_hints = SqlColumnTypeHints(
            bool_columns=frozenset({"missing_source"}),
            bigint_columns=frozenset({"actual_count"}),
        )
        column_type_hints.require_complete(output_shape.cte_output_columns)
        return CompiledStep(
            output_shape=output_shape,
            result_relation=DeclaredResultRelation.from_output_shape(output_shape),
            column_type_hints=column_type_hints,
            grammar=__opa002_grammar_365,
            needs_returning=True,
            closed_post_op=embedding_require_no_rows_post_op(
                message=self._error_message,
                expected_count=self._expected_count,
                actual_count_column="actual_count",
            ),
            auxiliary_ctes=[(source_cte.ref_id, source_cte.auxiliary_query)] if source_cte.auxiliary_query is not None else None,
            allow_empty_provenance_manifest=True,
        )


def _require_available_vector_backend_kind(
    ctx: LoweringContext,
    backend_kind: VectorBackendKind,
    *,
    index_name: VectorIndexName,
) -> VectorBackendKind:
    if backend_kind is not VectorBackendKind.USEARCH:
        return backend_kind
    from l5200_vector_index.index_implementations import usearch_index as usearch_backend

    if usearch_backend.USEARCH_AVAILABLE:
        return VectorBackendKind.USEARCH
    raise VectorIndexImplementationUnavailableError(
        operation=VectorIndexOperation.MAINTENANCE,
        table_name=VectorIndexTableName("registered_vector_model"),
        index_name=index_name,
        requested=VectorIndexImplementation.USEARCH,
        backend_type=ctx.backend_type,
        reason=VectorImplementationFailureReason("the USearch adapter is unavailable"),
        remediation=VectorImplementationRemediation("Install the 'usearch' package before maintenance"),
    )


def _resolve_vector_backend_kind(
    ctx: LoweringContext,
    *,
    backend_kind_override: str | None,
) -> VectorBackendKind:
    if backend_kind_override is not None:
        return _require_available_vector_backend_kind(
            ctx,
            VectorBackendKind(backend_kind_override),
            index_name=VectorIndexName("vector_index"),
        )
    return _resolve_backend_kind_for_vector_maintenance(ctx)


def _resolve_vector_backend_kind_for_config(
    ctx: LoweringContext,
    config: VectorIndexConfig,
    *,
    backend_kind_override: str | None,
) -> VectorBackendKind:
    if backend_kind_override is not None:
        return _require_available_vector_backend_kind(
            ctx,
            VectorBackendKind(backend_kind_override),
            index_name=VectorIndexName(config.index_name),
        )
    requested = config.resolved_index_policy.requested_implementation
    if requested is VectorIndexImplementation.USEARCH:
        return _require_available_vector_backend_kind(
            ctx,
            VectorBackendKind.USEARCH,
            index_name=VectorIndexName(config.index_name),
        )
    if requested is VectorIndexImplementation.SQL_TABLE_HNSW:
        return VectorBackendKind.SQL_TABLE_HNSW
    return _resolve_backend_kind_for_vector_maintenance(ctx, config)


def _first_compiled_row(
    compiled: CompiledStep[list[object]],
    *,
    publication_ref_id: ServerPlanRefId,
    publication_contract: CtePublicationContract,
    model_cls: type[DatabaseObjectRow[Any]],
    post_write_select: SqlRenderable | None,
    empty_message: str,
    output_shape: Any | None = None,
    column_type_hints: SqlColumnTypeHints | None = None,
) -> CompiledStep[object]:
    sql_ir = _require_compiled_embedding_sql_ir(compiled)
    closed_post_op = embedding_first_hydrated_row_post_op(
        model_cls=model_cls,
        empty_message=empty_message,
    )
    grammar = sql_ir.grammar
    params = sql_ir.params
    needs_returning = sql_ir.needs_returning
    external_params_first = sql_ir.external_params_first
    repeatable_publication_query = _require_embedding_post_write_select(post_write_select)
    if not sql_ir.needs_returning:
        post_write_select = repeatable_publication_query
        from impl.common.l2100_sql_grammar.domain.infra.stmt_compound_write import (
            SqlStatementBatch,
            SqlStatementBatchCategory,
        )

        grammar = SqlStatementBatch(
            [sql_ir.grammar, post_write_select],
            category=SqlStatementBatchCategory.ORDERED_SEMANTIC,
            params_per_stmt=[sql_ir.params, None],
            external_params_first=[sql_ir.external_params_first, False],
            needs_returning_per_stmt=[False, True],
            collect_results_per_stmt=[False, True],
        )
        params = None
        needs_returning = True
        external_params_first = False
    __opa002_grammar_430 = grammar
    if output_shape is None:
        msg = "_first_compiled_row requires an explicit output shape from the caller contract."
        # First-row helpers preserve caller-owned output contracts.
        raise ProgrammingError(msg)
    if column_type_hints is None:
        msg = "_first_compiled_row requires explicit column type hints from the caller contract."
        # First-row helpers preserve caller-owned output contracts.
        raise ProgrammingError(msg)
    from l2070_batching.compilation import compiled_sql_publication_from_query

    return CompiledStep(
        output_shape=output_shape,
        grammar=__opa002_grammar_430,
        params=params,
        needs_returning=needs_returning,
        result_relation=DeclaredResultRelation.from_output_shape(output_shape),
        column_type_hints=column_type_hints,
        external_params_first=external_params_first,
        provenance_manifest=sql_ir.provenance_manifest,
        allow_empty_provenance_manifest=sql_ir.allow_empty_provenance_manifest,
        use_savepoint_recovery=sql_ir.use_savepoint_recovery,
        closed_post_op=closed_post_op,
        lifecycle_effects=compiled.lifecycle_effects,
        compiled_sql_publication=compiled_sql_publication_from_query(
            ref_id=publication_ref_id,
            query=repeatable_publication_query,
            contract=publication_contract,
        ),
    )


def _output_shape_from_cte_contract(contract: CtePublicationContract) -> Any:
    return _output_shape_from_columns_and_hints(contract.columns, contract.column_type_hints)


def _output_shape_from_columns_and_hints(columns: tuple[str, ...], column_type_hints: SqlColumnTypeHints) -> Any:
    from l2070_batching.output_shape import output_shape_from_mappings

    bytea_columns = column_type_hints.bytea_columns if column_type_hints is not None else frozenset()
    return output_shape_from_mappings(
        tuple((column, column, column in bytea_columns) for column in columns),
    )


def _embedding_metadata_post_write_select(
    instance: EmbeddingMetadata,
    *,
    columns: tuple[str, ...],
) -> SqlRenderable:
    from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName
    from impl.common.l2100_sql_grammar.builders import and_, col, eq, val
    from impl.common.l2100_sql_grammar.tree.clauses import SqlSelectList, SqlWhereClause
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef
    from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
    from impl.common.l2100_sql_grammar.tree.statements import SqlSelect
    from l1000_schema.table_utils import get_table_name
    from l5200_vector_index.embedding_metadata import EmbeddingMetadata

    return SqlSelect(
        select=SqlSelectList([SqlColumnRef(SqlColumnName(column)) for column in columns]),
        from_=SqlTableIdent(get_table_name(EmbeddingMetadata)),
        where=SqlWhereClause(
            and_(
                eq(col("table_name"), val(instance.table_name)),
                eq(col("field_name"), val(instance.field_name)),
            ),
        ),
        limit=1,
    )


