        msg = "Embedding write lowering requires a concrete SysId for source-scoped hash and ref operations"
        raise NotImplementedError(msg)
    return object_id


def _runtime_require_embedding_metadata(
    value: object,
    *,
    ref_id: ServerPlanRefId,
    table_name_fallback: str,
    index_name_fallback: str,
) -> tuple[EmbeddingMetadata, bytes]:
    from impl.common.l5200_sql_query.row_converter import convert_row_to_model
    from l5200_vector_index.embedding_content_hash import normalize_content_hash_nonce
    from l5200_vector_index.embedding_metadata import EmbeddingMetadata

    metadata: EmbeddingMetadata
    if isinstance(value, EmbeddingMetadata):
        metadata = value
    elif isinstance(value, Mapping):
        metadata = cast(
            "EmbeddingMetadata",
            convert_row_to_model(
                EmbeddingMetadata,
                dict(value),
                conn=None,
                hydrate_large_columns=False,
            ),
        )
    elif value is None:
        msg = f"Embedding metadata not found at {ref_id!r} for {table_name_fallback}.{index_name_fallback}"
        raise ValueError(msg)
    else:
        msg = f"Expected EmbeddingMetadata for {table_name_fallback}.{index_name_fallback}, got {type(value).__name__}"
        raise TypeError(msg)

    nonce = normalize_content_hash_nonce(metadata.content_hash_nonce)
    if nonce is None:
        msg = f"Embedding metadata for {table_name_fallback}.{index_name_fallback} is missing content_hash_nonce"
        raise RuntimeError(msg)
    return metadata, nonce


