def _embedding_metadata_conflict_where() -> Expression[bool, EmbeddingMetadata]:
    from l1000_schema.typed_field import COALESCE, EXCLUDED, field
    from l5200_vector_index.embedding_metadata import EmbeddingMetadata

    return (~field(EmbeddingMetadata.algorithm_established)) | (
        (COALESCE(field(EmbeddingMetadata.provider), "") == COALESCE(EXCLUDED(field(EmbeddingMetadata.provider)), ""))
        & (field(EmbeddingMetadata.model) == EXCLUDED(field(EmbeddingMetadata.model)))
        & (COALESCE(field(EmbeddingMetadata.dimensions), -1) == COALESCE(EXCLUDED(field(EmbeddingMetadata.dimensions)), -1))
    )


class _EnsureEmbeddingMetadataRowStep(SqlRelationPublisherStep[Any]):
    """Create or validate embedding metadata in a single guarded upsert."""

    def __init__(
        self: _EnsureEmbeddingMetadataRowStep,
        ref_id: ServerPlanRefId,
        config: _EnsureEmbeddingMetadataRowConfig,
    ) -> None:
        super().__init__(ref_id)
        self._target = config.target
        self._model_id = config.model_id
        self._dimensions = config.dimensions
        self._existing_metadata_ref = str(config.existing_metadata_ref) if config.existing_metadata_ref is not None else None
        self._after_refs = frozenset(str(ref_id) for ref_id in config.after_refs)

    @property
    def level(self: _EnsureEmbeddingMetadataRowStep) -> int:
        return 0

    def result_cardinality(self: _EnsureEmbeddingMetadataRowStep) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self: _EnsureEmbeddingMetadataRowStep) -> bool:
        return False

    def dependencies(self: _EnsureEmbeddingMetadataRowStep) -> frozenset[str]:
        return self._after_refs

    def tables_read(self: _EnsureEmbeddingMetadataRowStep) -> frozenset[str]:
        from l1000_schema.table_utils import get_table_name
        from l5200_vector_index.embedding_metadata import EmbeddingMetadata

        return frozenset({get_table_name(EmbeddingMetadata)})

    def tables_written(self: _EnsureEmbeddingMetadataRowStep) -> frozenset[str]:
        return self.tables_read()

    def step_tags(self: _EnsureEmbeddingMetadataRowStep) -> frozenset[str]:
        return frozenset({"write", "embedding", "metadata", "grammar"})

    def always_publishes_executor_visible_binding(self) -> bool:
        return True

    def cte_publication_contract(self: _EnsureEmbeddingMetadataRowStep) -> CtePublicationContract:
        def _legacy_cte_output_columns() -> tuple[str, ...]:
            from l1000_schema.column_utils import get_db_column_name
            from l5200_vector_index.embedding_metadata import EmbeddingMetadata

            return tuple(
                get_db_column_name(EmbeddingMetadata, DynamicFieldName(field_name)) for field_name in EmbeddingMetadata.model_fields
            )

        columns = _legacy_cte_output_columns()

        def _legacy_cte_column_type_hints(columns: tuple[str, ...]) -> SqlColumnTypeHints:
            from l5200_vector_index.embedding_metadata import EmbeddingMetadata

            hints = model_sql_column_type_hints(EmbeddingMetadata, columns)
            if hints is None:
                msg = "Could not resolve SQL column type hints for EmbeddingMetadata rows"
                raise TypeError(msg)
            return hints

        column_type_hints = _legacy_cte_column_type_hints(columns)
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        from l5200_vector_index.embedding_metadata import EmbeddingMetadata

        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=tuple(str(column) for column in columns),
            column_type_hints=column_type_hints,
            model_cls=EmbeddingMetadata,
            relation_contract=CteRelationContract.model(EmbeddingMetadata),
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def compile(self: _EnsureEmbeddingMetadataRowStep, ctx: CompilationContext) -> CompiledStep[Any]:
        from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName, SqlTableName
        from impl.common.l2100_sql_grammar.domain.infra.stmt_upsert import SqlUpsertExcludedValue
        from impl.common.l2100_sql_grammar.domain.versioning.identifier_fragments import SqlColumnRef
        from impl.common.l2100_sql_grammar.tree.clauses import (
            SqlColumnList,
            SqlOnConflict,
            SqlPlaceholderRows,
            SqlReturningClause,
            SqlSetItem,
            SqlValuesSource,
        )
        from impl.common.l2100_sql_grammar.tree.enums import ConflictAction
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlStar
        from impl.common.l2100_sql_grammar.domain.infra.stmt_dml_simple import SqlRawExpression
        from impl.common.l2100_sql_grammar.tree.statements import SqlInsert
        from l5200_vector_index.embedding_metadata import EmbeddingMetadata
        from l5200_vector_index.system_embedding_tables import _split_model_id, embedding_model_ref_id_for_model_id

        provider, model_name = _split_model_id(self._model_id)
        instance = EmbeddingMetadata(
            table_name=self._target.table_name,
            field_name=self._target.index_name,
            content_hash_nonce=secrets.token_bytes(16),
            algorithm_established=True,
            provider=provider,
            model=model_name,
            model_ref_id=embedding_model_ref_id_for_model_id(self._model_id),
            dimensions=self._dimensions,
            next_sequence_id=1,
            next_expected_sequence=1,
        )
        columns = (
            "sys_id",
            "sys_created_at",
            "sys_updated_at",
            "table_name",
            "field_name",
            "algorithm_established",
            "provider",
            "model",
            "model_ref_id",
            "model_version",
            "dimensions",
            "next_sequence_id",
            "next_expected_sequence",
            "last_queued_at",
            "last_queued_sequence",
            "last_applied_at",
            "last_applied_sequence",
            "content_hash_nonce",
        )
        params = tuple(
            getattr(instance, field_name)
            for field_name in (
                "sys_id",
                "created_at",
                "updated_at",
                "table_name",
                "field_name",
                "algorithm_established",
                "provider",
                "model",
                "model_ref_id",
                "model_version",
                "dimensions",
                "next_sequence_id",
                "next_expected_sequence",
                "last_queued_at",
                "last_queued_sequence",
                "last_applied_at",
                "last_applied_sequence",
                "content_hash_nonce",
            )
        )
        set_items: tuple[SqlSetItem, ...] | None = None
        if ctx.backend_profile.traits.dml_conflict_transport is not DmlConflictTransport.INSERTED_VALUES:
            set_items = (
                SqlSetItem(
                    SqlColumnName("content_hash_nonce"),
                    SqlRawExpression('COALESCE("sys_embedding_metadata"."content_hash_nonce", EXCLUDED."content_hash_nonce")'),
                ),
                SqlSetItem(
                    SqlColumnName("provider"),
                    SqlRawExpression('COALESCE("sys_embedding_metadata"."provider", EXCLUDED."provider")'),
                ),
                SqlSetItem(
                    SqlColumnName("model"),
                    SqlRawExpression('COALESCE("sys_embedding_metadata"."model", EXCLUDED."model")'),
                ),
                SqlSetItem(
                    SqlColumnName("model_ref_id"),
