def _validate_whole_document_batch_writes(
    writes: Sequence[_RequestedWholeDocumentEmbeddingWrite | _VisibleWholeDocumentEmbeddingWrite],
) -> _WholeDocumentBatchShape:
    first_write = writes[0]
    dimensions = first_write.prepared.dimensions
    for write in writes:
        if write.target.table_name != first_write.target.table_name or write.target.index_name != first_write.target.index_name:
            msg = (
                "SetEmbeddingManyIntent requires a single source table and index per batch: "
                f"expected {first_write.target.table_name}.{first_write.target.index_name}, "
                f"got {write.target.table_name}.{write.target.index_name}"
            )
            raise ValueError(msg)
        if str(write.prepared.model_id) != str(first_write.prepared.model_id):
            msg = (
                f"Inconsistent whole-document embedding model ids for "
                f"{write.target.model_cls.__name__}.{write.target.index_name}: "
                f"expected {first_write.prepared.model_id}, got {write.prepared.model_id}"
            )
            raise ValueError(msg)
        if write.prepared.dimensions != dimensions:
            msg = (
                f"Inconsistent whole-document embedding dimensions for "
                f"{write.target.model_cls.__name__}.{write.target.index_name}: "
                f"expected {dimensions}, got {write.prepared.dimensions}"
            )
            raise ValueError(msg)
    return _WholeDocumentBatchShape(
        target=first_write.target,
        model_id=first_write.prepared.model_id,
        dimensions=dimensions,
    )


def _whole_document_batch_group_key(
    write: _RequestedWholeDocumentEmbeddingWrite | _VisibleWholeDocumentEmbeddingWrite,
) -> tuple[str, int]:
    return _prepared_embedding_group_key(write.prepared)


def _chunk_whole_document_batch_writes[
    T: _RequestedWholeDocumentEmbeddingWrite | _VisibleWholeDocumentEmbeddingWrite,
](
    writes: Sequence[T],
    *,
    bulk_transport: DmlBulkTransport,
) -> list[Sequence[T]]:
    """Split embedding batches before backend parameter limits are reached."""
    if bulk_transport is not DmlBulkTransport.PAYLOAD_AWARE_BOUND_VALUES:
        return [writes]
    parameter_budget = _POSTGRES_BIND_PARAMETER_LIMIT // _EMBEDDING_BATCH_PARAMETER_HEADROOM
    max_writes_per_chunk = max(1, parameter_budget // _ESTIMATED_PARAMS_PER_EMBEDDING_WRITE)
    if len(writes) <= max_writes_per_chunk:
        return [writes]
    return [writes[start : start + max_writes_per_chunk] for start in range(0, len(writes), max_writes_per_chunk)]


def _prepared_embedding_group_key(prepared: _PreparedEmbeddingValue) -> tuple[str, int]:
    return (prepared.model_id, prepared.dimensions)


def _embedding_vector_conflicts(
    existing: EmbeddingVector,
    prepared: _PreparedEmbeddingValue,
) -> bool:
    dimensions = existing["dimensions"] if isinstance(existing, dict) else existing.dimensions
    precision = existing["embedding_precision"] if isinstance(existing, dict) else existing.embedding_precision
    embedding = existing["embedding"] if isinstance(existing, dict) else existing.embedding
    embedding_binary = existing["embedding_binary"] if isinstance(existing, dict) else existing.embedding_binary
    embedding_binary_representation_id = (
        existing["embedding_binary_representation_id"] if isinstance(existing, dict) else existing.embedding_binary_representation_id
    )
    embedding_binary_projection_ref_id = (
        existing["embedding_binary_projection_ref_id"] if isinstance(existing, dict) else existing.embedding_binary_projection_ref_id
    )
    embedding_binary_dimensions = (
        existing["embedding_binary_dimensions"] if isinstance(existing, dict) else existing.embedding_binary_dimensions
    )
    changed: bool = (
        dimensions != prepared.dimensions
        or precision != prepared.precision
        or embedding != prepared.serialized_embedding
        or embedding_binary != prepared.embedding_binary
        or embedding_binary_representation_id != prepared.embedding_binary_representation_id
        or embedding_binary_projection_ref_id != prepared.embedding_binary_projection_ref_id
        or embedding_binary_dimensions != prepared.embedding_binary_dimensions
    )
    return changed


def _require_embedding_hash_payload_join_mode(
    hash_cte: CteReference,
    *,
    hash_ref: ServerPlanRefId,
    payload_count: int,
    model_id: EmbeddingModelCanonicalId | None,
    index_name: SqlIndexName,
    source_ids: tuple[SysId | None, ...],
) -> Literal["keyed", "unkeyed"]:
    """Validate the producer-owned cardinality contract for a hash-payload join."""
    if "source_object_id" in hash_cte.columns:
        return "keyed"
    context = f"model={model_id!r}, index={index_name!r}, hash_ref={hash_ref!r}, source_ids={source_ids!r}"
    if payload_count != 1:
        msg = f"Unkeyed embedding hash relation has {payload_count} payload rows; expected 1 ({context})"
        raise ValueError(msg)
    if hash_cte.relation_role != "embedding_hash" or hash_cte.columns != ("hash_short", "hash_high"):
        msg = (
            "Unkeyed embedding hash relation does not prove one-row cardinality through "
            f"the embedding_hash producer contract ({context}, relation_role={hash_cte.relation_role!r}, "
            f"columns={hash_cte.columns!r})"
        )
        raise ValueError(msg)
    return "unkeyed"


