def _embedding_vector_materialized_column_type_hints() -> SqlColumnTypeHints:
    from l5200_vector_index.content_addressable_models import EmbeddingVector

    columns = _embedding_vector_materialized_columns()
    hints = model_sql_column_type_hints(EmbeddingVector, columns)
    if hints is None:
        msg = "Could not resolve SQL column type hints for EmbeddingVector rows"
        raise TypeError(msg)
    return SqlColumnTypeHints(
        uuid_columns=hints.uuid_columns | frozenset({"model_ref_id"}),
        bigint_columns=hints.bigint_columns,
        integer_columns=hints.integer_columns,
        bool_columns=hints.bool_columns,
        jsonb_columns=hints.jsonb_columns,
        bytea_columns=hints.bytea_columns,
        text_columns=hints.text_columns - frozenset({"model_ref_id"}),
        timestamptz_columns=hints.timestamptz_columns,
        date_columns=hints.date_columns,
        time_columns=hints.time_columns,
        numeric_columns=hints.numeric_columns,
        double_columns=hints.double_columns,
    ).require_complete(columns)


