def _lower_whole_document_batch_steps[MetadataStepsItemT, HashStepsItemT](
    *,
    ref_id: ServerPlanRefId,
    shape: _WholeDocumentBatchShape,
    metadata_steps: Sequence[ServerPlanStep[MetadataStepsItemT]],
    metadata_establish_ref: ServerPlanRefId,
    hash_steps: Sequence[ServerPlanStep[HashStepsItemT]],
    vector_writes: Sequence[_PendingWholeDocumentEmbeddingVectorWrite],
    ref_writes: Sequence[_PendingWholeDocumentEmbeddingRefWrite],
    maintenance_targets: Sequence[_EmbeddingWriteTarget],
    ctx: LoweringContext,
    backend_kind_override: str | None = None,
    after_refs: frozenset[ServerPlanRefId] = frozenset(),
) -> list[ServerPlanStep[Any]]:
    vector_ref = f"{ref_id}.vectors"
    replace_ref = f"{ref_id}.replace_refs"
    maintenance_ref = f"{ref_id}.maintenance"
    vector_completion_ref = ServerPlanRefId(vector_ref)
    from l5200_vector_index.content_addressable_models import (
        get_embedding_classes_for_strategy,
    )

    vector_config = _require_vector_config(
        shape.target.model_cls,
        SqlIndexName(shape.target.index_name),
    )
    vector_model_cls, ref_model_cls = get_embedding_classes_for_strategy(
        vector_config.content_store_strategy,
        model_id=shape.model_id,
        source_table_name=shape.target.table_name,
        field_name=shape.target.index_name,
    )

    # UNIQUE(branch_id, revision_id, ...) treats NULLs as distinct on common SQL
    # backends, so INSERT..ON CONFLICT cannot merge rows when both are NULL.
    # When callers request cleanup, delete scoped refs before replace so at most
    # one whole-document ref remains per scope.
    pre_replace_cleanup: list[ServerPlanStep[Any]] = []
    cleanup_keys: set[tuple[object, ...]] = set()
    for ref_write in ref_writes:
        if ref_write.skip_existing_ref_cleanup:
            continue
        sc = ref_write.scope
        key = (
            sc.source_id,
            sc.source_table,
            sc.index_name,
            _embedding_scope_group_key(sc.branch_id),
            _embedding_scope_group_key(sc.revision_id),
        )
        if key in cleanup_keys:
            continue
        cleanup_keys.add(key)
        cleanup_ref = f"{ref_id}.pre_replace_cleanup_{len(pre_replace_cleanup)}"
        pre_replace_cleanup.append(
            _build_scope_ref_delete_step(
                ref_id=ServerPlanRefId(cleanup_ref),
                scope=sc,
                after_refs=frozenset({vector_completion_ref}),
                model_cls=ref_model_cls,
            ),
        )
    replace_after = frozenset({vector_completion_ref, *(step.ref_id for step in pre_replace_cleanup)})

    steps: list[ServerPlanStep[Any]] = [
        *metadata_steps,
        *hash_steps,
        _UpsertManyEmbeddingVectorsStep(
            ServerPlanRefId(vector_ref),
            config=_UpsertManyEmbeddingVectorsConfig(
                writes=tuple(vector_writes),
                vector_model_cls=vector_model_cls,
                after_refs=frozenset({metadata_establish_ref, *after_refs}),
            ),
        ),
        *pre_replace_cleanup,
        *ReplaceWholeDocumentEmbeddingRefsManyIntent(
            ServerPlanRefId(replace_ref),
            cast(
                "Any",
                _ReplaceWholeDocumentEmbeddingRefsManyIntentConfig(
                    writes=tuple(ref_writes),
                    ref_model_cls=ref_model_cls,
                    after_refs=replace_after,
                ),
            ),
        ).lower(ctx),
    ]
    if maintenance_targets:
        vector_config = _require_vector_config(shape.target.model_cls, SqlIndexName(shape.target.index_name))
        resolved_backend_kind = _resolve_vector_backend_kind_for_config(
            ctx,
            vector_config,
            backend_kind_override=backend_kind_override,
        )
        steps.append(
            ProvidedRefsPgvectorVectorIndexMaintenanceIntent(
                _plan_ref(maintenance_ref),
                VectorIndexMaintenanceOperation.REBUILD,
                model_cls=shape.target.model_cls,
                object_id=_target_object_id_ref(shape.target),
                index=SqlIndexName(shape.target.index_name),
                after_refs=_plan_refs(frozenset({replace_ref})),
                refs_ref=_plan_ref(f"{replace_ref}.insert_refs.raw"),
                vectors_ref=_plan_ref(f"{vector_ref}.raw"),
            )
            if resolved_backend_kind == VectorBackendKind.PGVECTOR
            else VectorIndexMaintenanceIntent(
                _plan_ref(maintenance_ref),
                VectorIndexMaintenanceOperation.REBUILD,
                model_cls=shape.target.model_cls,
                object_id=_target_object_id_ref(shape.target),
                index=SqlIndexName(shape.target.index_name),
                after_refs=_plan_refs(frozenset({replace_ref})),
                backend_kind=resolved_backend_kind,
            ),
        )
        steps.append(BarrierStep(_plan_ref(ref_id), depends_on=_plan_refs(frozenset({maintenance_ref}))))
        return steps

    steps.append(BarrierStep(_plan_ref(ref_id), depends_on=_plan_refs(frozenset({replace_ref}))))
    return steps


