def _build_metadata_bootstrap_steps(
    *,
    ref_prefix: str,
    target: _EmbeddingWriteTarget,
    model_id: str,
    dimensions: int,
    validate_after_ref: str | None = None,
    after_refs: frozenset[str] = frozenset(),
) -> tuple[_EmbeddingMetadataBootstrapRefs, list[ServerPlanStep[Any]]]:
    ensure_ref = f"{ref_prefix}.metadata_ensure"
    final_validate_ref = f"{ref_prefix}.metadata_validate_final"
    metadata_refs = _EmbeddingMetadataBootstrapRefs(
        shell_ref=ServerPlanRefId(ensure_ref),
        fill_nonce_ref=ServerPlanRefId(ensure_ref),
        metadata_ref=ServerPlanRefId(ensure_ref),
        validate_ref=ServerPlanRefId(final_validate_ref),
        establish_ref=ServerPlanRefId(final_validate_ref),
    )
    ensure_after_refs = set(after_refs)
    if validate_after_ref is not None:
        ensure_after_refs.add(validate_after_ref)
    ensure_after = frozenset(ensure_after_refs)
    return (
        metadata_refs,
        [
            _EnsureEmbeddingMetadataRowStep(
                ServerPlanRefId(ensure_ref),
                config=_EnsureEmbeddingMetadataRowConfig(
                    target=target,
                    model_id=model_id,
                    dimensions=dimensions,
                    after_refs=frozenset(ServerPlanRefId(ref_id) for ref_id in ensure_after),
                ),
            ),
            _ValidateEmbeddingMetadataStep(
                ServerPlanRefId(final_validate_ref),
                config=_ValidateEmbeddingMetadataConfig(
                    metadata_ref=ServerPlanRefId(ensure_ref),
                    table_name=SqlTableName(target.table_name),
                    index_name=target.index_name,
                    model_id=model_id,
                    dimensions=dimensions,
                ),
            ),
        ],
    )


def _get_or_create_metadata_bootstrap_steps(
    ctx: LoweringContext,
    *,
    ref_prefix: str,
    target: _EmbeddingWriteTarget,
    model_id: str,
    dimensions: int,
    validate_after_ref: str | None = None,
) -> tuple[_EmbeddingMetadataBootstrapRefs, list[ServerPlanStep[Any]]]:
    cache_key = f"embedding_metadata_bootstrap:{target.table_name}:{target.index_name}:{model_id}:{dimensions}"
    cached_refs = ctx._lowering_cache.get(cache_key)
    if isinstance(cached_refs, _EmbeddingMetadataBootstrapRefs):
        return cached_refs, []

    refs, steps = _build_metadata_bootstrap_steps(
        ref_prefix=ref_prefix,
        target=target,
        model_id=model_id,
        dimensions=dimensions,
        validate_after_ref=validate_after_ref,
    )
    ctx._lowering_cache[cache_key] = refs
    return refs, steps


def _build_ref_delete_step(
    *,
    ref_id: ServerPlanRefId,
    target: _EmbeddingWriteTarget,
    branch_id: _EmbeddingScopeValue,
    revision_id: _EmbeddingScopeValue,
    after_refs: frozenset[ServerPlanRefId],
    ignore_branch_revision_scope: bool = False,
    return_deleted_rows: bool = False,
    ref_model_cls: type[EmbeddingRef] | None = None,
) -> ServerPlanStep[int]:
    if ignore_branch_revision_scope:
        from impl.common.l2070_server_plan.steps.query_delete import QueryDeleteStep, _QueryDeleteStepConfig
        from l1000_schema.column_utils import get_db_column_name
        from l1000_schema.typed_field import field
        from l5200_vector_index.content_addressable_models import EmbeddingRef

        if ref_model_cls is None:
            ref_model_cls = EmbeddingRef
        return QueryDeleteStep(
            ref_id,
            ref_model_cls,
            _QueryDeleteStepConfig(
                query_spec=_query_spec(
                    ref_model_cls,
                    (field(ref_model_cls.source_table) == target.table_name)
                    & (field(ref_model_cls.field_name) == target.index_name)
                    & (
                        field(ref_model_cls.source_id) == _require_concrete_target_object_id(target)
                    ),
                ),
                after_refs=after_refs,
                cte_returning_columns=(
                    tuple(
                        get_db_column_name(ref_model_cls, DynamicFieldName(name))
                        for name in ref_model_cls.model_fields
                    )
                    if return_deleted_rows
                    else None
                ),
                returns_deleted_rows=return_deleted_rows,
            ),
        )
    return _build_scope_ref_delete_step(
        ref_id=ref_id,
        scope=_scope_for_target(
            target,
            branch_id=branch_id,
            revision_id=revision_id,
        ),
        after_refs=after_refs,
        return_deleted_rows=return_deleted_rows,
        model_cls=ref_model_cls,
    )


def _validate_chunk_embeddings(
    target: _EmbeddingWriteTarget,
    chunks: Sequence[ChunkEmbedding],
) -> int:
    dimensions = len(chunks[0].embedding)
    seen_chunk_ids: set[str] = set()
    for chunk in chunks:
        if len(chunk.embedding) != dimensions:
            msg = (
                f"Inconsistent chunk dimensions for {target.model_cls.__name__}.{target.index_name}: "
                f"expected {dimensions}, got {len(chunk.embedding)}"
            )
            raise ValueError(msg)
        if chunk.chunk_id.is_whole_document():
            msg = f"Chunked handler for {target.model_cls.__name__}.{target.index_name} returned reserved whole_document chunk_id"
            raise ValueError(msg)
        chunk_key = str(chunk.chunk_id)
        if chunk_key in seen_chunk_ids:
            msg = f"Chunked handler for {target.model_cls.__name__}.{target.index_name} returned duplicate chunk_id {chunk.chunk_id}"
            raise ValueError(msg)
        seen_chunk_ids.add(chunk_key)
    return dimensions


def _coerce_embedding_input(
    embedding: EmbeddingWriteValue,
) -> np.ndarray | list[float]:
    from l5200_vector_index.embedding_type import EmbeddingType

    if isinstance(embedding, EmbeddingType):
        vector = embedding.to_list()
        if not vector:
            raise ValueError("Embedding write value must contain at least one dimension")
        return vector
    if isinstance(embedding, np.ndarray):
        if embedding.ndim != 1:
            msg = f"Embedding write value must be one-dimensional, got {embedding.ndim} dimensions"
            raise ValueError(msg)
        return embedding
    if not embedding:
        raise ValueError("Embedding write value must contain at least one dimension")
    return [float(value) for value in embedding]


def _prepare_embedding_value(
    model_cls: type[DatabaseObjectRow[SysId]],
    object_id: SysId,
    index_name: SqlIndexName,
    embedding: EmbeddingWriteValue | bytes,
    model_id: EmbeddingModelCanonicalId,
    embedding_binary: bytes | None = None,
    projected_embeddings: tuple[ProjectedEmbeddingResult, ...] = (),
    serialized_dimensions: int | None = None,
    serialized_precision: EmbeddingPrecision | None = None,
) -> _PreparedEmbeddingValue:
    from l5200_vector_index.embedding_type import EmbeddingPrecision
    from l5200_vector_index.system_embedding_tables import prepare_embedding, prepare_serialized_embedding

    if isinstance(embedding, bytes):
        if serialized_dimensions is None or not isinstance(serialized_precision, EmbeddingPrecision):
            msg = (
                f"Serialized embedding for {model_cls.__name__}.{index_name} requires dimensions and precision; "
                f"got dimensions={serialized_dimensions!r}, precision={serialized_precision!r}"
            )
            raise ValueError(msg)
        prepared = prepare_serialized_embedding(
            model_cls,
            object_id,
            index_name,
            embedding,
            model_id,
            serialized_dimensions,
            serialized_precision,
            projected_embeddings=projected_embeddings,
        )
    else:
        prepared = prepare_embedding(
            model_cls,
            object_id,
            index_name,
            _coerce_embedding_input(embedding),
            model_id,
            embedding_binary=embedding_binary,
            projected_embeddings=projected_embeddings,
        )
    return _PreparedEmbeddingValue(
        model_id=prepared.model_id,
        model_ref_id=prepared.model_ref_id,
        dimensions=prepared.dimensions,
        serialized_embedding=prepared.serialized,
        precision=prepared.precision.value,
        embedding_binary=prepared.embedding_binary,
        embedding_binary_representation_id=prepared.embedding_binary_representation_id,
        embedding_binary_projection_ref_id=prepared.embedding_binary_projection_ref_id,
        embedding_binary_dimensions=prepared.embedding_binary_dimensions,
    )


def _scope_for_target(
    target: _EmbeddingWriteTarget,
    *,
    branch_id: _EmbeddingScopeValue,
    revision_id: _EmbeddingScopeValue,
) -> _WholeDocumentEmbeddingRefScope:
    normalized_branch_id, normalized_revision_id = _normalize_embedding_ref_scope(
        branch_id=branch_id,
        revision_id=revision_id,
    )
    return _WholeDocumentEmbeddingRefScope(
        source_id=_require_concrete_target_object_id(target),
        source_table=SqlTableName(target.table_name),
        index_name=SqlIndexName(target.index_name),
        branch_id=normalized_branch_id,
        revision_id=normalized_revision_id,
    )


def _require_embedding_scope_value(
    value: object | None,
    *,
    field_name: Literal["branch_id", "revision_id"],
) -> _EmbeddingScopeValue:
    if value is None or isinstance(value, str | BranchId | RevisionId | ScalarServerRef):
        return value
    msg = f"Embedding {field_name} scope has unsupported type {type(value).__name__}"
    raise TypeError(msg)


def _normalize_embedding_ref_scope(
    *,
    branch_id: _EmbeddingScopeValue,
    revision_id: _EmbeddingScopeValue,
) -> tuple[_EmbeddingScopeValue, _EmbeddingScopeValue]:
    """Normalize branch-scoped refs to the staged visibility contract."""
    normalized_branch = _require_embedding_scope_value(branch_id, field_name="branch_id")
    normalized_revision = _require_embedding_scope_value(revision_id, field_name="revision_id")
    if normalized_branch is not None:
        return normalized_branch, None
    return None, normalized_revision


def _embedding_ref_scope_for_context(
    *,
    ctx: LoweringContext,
    target: _EmbeddingWriteTarget,
    branch_id: _EmbeddingScopeValue = None,
    revision_id: _EmbeddingScopeValue = None,
) -> _WholeDocumentEmbeddingRefScope:
    effective_branch_id = branch_id
    if effective_branch_id is None:
        effective_branch_id = _branch_scope_value_for_context(ctx)
    effective_revision_id = revision_id
    if effective_revision_id is None and not (ctx.is_versioned and ctx.is_write_transaction):
        effective_revision_id = _revision_scope_value_for_context(ctx)
    if ctx.is_versioned and ctx.is_write_transaction and effective_branch_id is None:
        msg = (
            "Versioned embedding write lost branch scope: "
            f"ctx.branch_id={ctx.branch_id!r} "
            f"ctx.lazy_branch={ctx.lazy_branch!r} "
            f"executor_branch_anchor={getattr(ctx.executor_txn_handle, 'branch_anchor', None)!r} "
            f"target={target!r}"
        )
        raise AssertionError(msg)
    return _scope_for_target(
        target,
        branch_id=effective_branch_id,
        revision_id=effective_revision_id,
    )


def _branch_scope_value_for_context(ctx: LoweringContext) -> _EmbeddingScopeValue:
    if ctx.branch_id is not None:
        return ctx.branch_id
    executor_branch_anchor: object | None = getattr(ctx.executor_txn_handle, "branch_anchor", None)
    if executor_branch_anchor is not None:
        return _require_embedding_scope_value(
            executor_branch_anchor,
            field_name="branch_id",
        )
    return ctx.lazy_branch


def _revision_scope_value_for_context(ctx: LoweringContext) -> _EmbeddingScopeValue:
    if ctx.revision_id is not None:
        return ctx.revision_id
    return ctx.lazy_revision


def _embedding_scope_group_key(value: _EmbeddingScopeValue) -> _EmbeddingScopeKey:
    if isinstance(value, ScalarServerRef):
        return _EmbeddingScopeKey(kind="ref", value=str(value.ref_id))
    return _EmbeddingScopeKey(kind="literal", value=str(value))


