class _SetSourceRowsEmbeddingManyIntent(IntentStep[None]):
    """Internal intent: batch set whole-document embeddings from one visible row query."""

    intent_tags = frozenset({"write", "embedding", "intent", "internal"})
    intent_cardinality = Cardinality.NONE

    def __init__(
        self: _SetSourceRowsEmbeddingManyIntent,
        ref_id: ServerPlanRefId,
        config: ScalarServerRef[_SetSourceRowsEmbeddingManyIntentConfig],
    ) -> None:
        super().__init__(ref_id)
        self._config = _require_seeded_config(config, type(self).__name__)

    def lower(self: _SetSourceRowsEmbeddingManyIntent, ctx: LoweringContext) -> Sequence[ServerPlanStep[Any]]:
        config = self._config
        if not config.writes:
            return [BarrierStep(_plan_ref(self.ref_id), depends_on=frozenset())]

        steps: list[ServerPlanStep[Any]] = []
        completed_refs: set[ServerPlanRefId] = set()
        for write_index, write in enumerate(config.writes):
            child_ref = ServerPlanRefId(f"{self.ref_id}.write_{write_index}")
            steps.extend(
                SetVisibleSourceEmbeddingIntent(
                    child_ref,
                    cast(
                        "Any",
                        _SetVisibleSourceEmbeddingIntentConfig(
                            model_cls=config.model_cls,
                            source_id=_require_concrete_target_object_id(write.target),
                            index_name=config.index_name,
                            source_ref=config.source_rows_ref,
                            prepared=write.prepared,
                            backend_kind_override=config.backend_kind_override,
                        ),
                    ),
                ).lower(ctx),
            )
            completed_refs.add(child_ref)
        steps.append(
            BarrierStep(
                _plan_ref(self.ref_id),
                depends_on=_plan_refs(frozenset(completed_refs)),
            ),
        )
        return steps


