def _embedding_ref_upsert_config(
    *,
    upsert_on_conflict: bool,
) -> _UpsertManyStepConfig:
    """Build the ``_UpsertManyStepConfig`` for an EmbeddingRef write.

    When ``upsert_on_conflict`` is True, conflicts on the unique-scope tuple
    are silently ignored (no update). Otherwise we default to a primary-key
    ``DO NOTHING`` which never fires for freshly generated ``sys_id``s, so
    the step acts as a plain insert.
    """
    from impl.common.l2070_server_plan.steps.upsert_many import _UpsertManyStepConfig

    if upsert_on_conflict:
        return _UpsertManyStepConfig(
            conflict_columns=(
                "source_id",
                "source_table",
                "field_name",
                "branch_id",
                "revision_id",
                "chunk_id",
            ),
            on_conflict={},
            publish_sql_relation=True,
        )
    return _UpsertManyStepConfig(
        conflict_columns=("sys_id",),
        on_conflict={},
        publish_sql_relation=True,
    )


class _InsertEmbeddingRefStep(NonPublishingStep[Any]):
    """Insert the whole-document embedding ref after scoped cleanup."""

    def __init__(
        self: _InsertEmbeddingRefStep,
        ref_id: ServerPlanRefId,
        config: _InsertEmbeddingRefConfig,
    ) -> None:
        super().__init__(ref_id)
        self._hash_ref = config.hash_ref
        self._model_cls = config.ref_model_cls
        self._source_id = config.source_id
        self._source_table = str(config.source_table)
        self._index_name = config.index_name
        self._branch_id = config.branch_id
        self._revision_id = config.revision_id
        self._after_refs = frozenset(str(ref_id) for ref_id in config.after_refs)
        self._upsert_on_conflict = config.upsert_on_conflict

    @property
    def level(self: _InsertEmbeddingRefStep) -> int:
        return 2

    def result_cardinality(self: _InsertEmbeddingRefStep) -> Cardinality:
        return Cardinality.MANY

    def is_read_only(self: _InsertEmbeddingRefStep) -> bool:
        return False

    def dependencies(self: _InsertEmbeddingRefStep) -> frozenset[str]:
        return frozenset({self._hash_ref, *self._after_refs})

    def tables_read(self: _InsertEmbeddingRefStep) -> frozenset[str]:
        from l1000_schema.table_utils import get_table_name

        return frozenset({get_table_name(self._model_cls)})

    def tables_written(self: _InsertEmbeddingRefStep) -> frozenset[str]:
        return self.tables_read()

    def step_tags(self: _InsertEmbeddingRefStep) -> frozenset[str]:
        return frozenset({"write", "embedding", "ref", "insert"})

    def lower(
        self: _InsertEmbeddingRefStep,
        ctx: LoweringContext,
    ) -> list[ServerPlanStep[Any]]:
        del ctx
        from impl.common.l2070_server_plan.steps.upsert_many import UpsertManyRawResultStep

        instances_ref = ServerPlanRefId(f"{self.ref_id}.instances")
        upsert_config = replace(
            _embedding_ref_upsert_config(upsert_on_conflict=self._upsert_on_conflict),
            instances_ref=instances_ref,
            after_refs=frozenset(ServerPlanRefId(ref_id) for ref_id in self._after_refs),
        )
        pending = _PendingEmbeddingRefRow(
            hash_ref=self._hash_ref,
            source_id=self._source_id,
            source_table=SqlTableName(self._source_table),
            index_name=SqlIndexName(self._index_name),
            branch_id=self._branch_id,
            revision_id=self._revision_id,
        )
        return [
            _MaterializeEmbeddingRefRowsStep(
                instances_ref,
                rows=(pending,),
                after_refs=frozenset(ServerPlanRefId(ref_id) for ref_id in self._after_refs),
            ),
            UpsertManyRawResultStep(
                ServerPlanRefId(f"{self.ref_id}.raw"),
                self._model_cls,
                upsert_config,
            ),
        ]

    def compile(self: _InsertEmbeddingRefStep, ctx: CompilationContext) -> CompiledStep[Any]:
        del ctx
        raise NotImplementedError(f"{type(self).__name__} must be lowered before compile()")


