_COMMIT_PUBLISH_PLANNER_MEMORY_BUDGET_ENV = "NERA_COMMIT_PUBLISH_PLANNER_MEMORY_BUDGET_BYTES"
DEFAULT_COMMIT_PUBLISH_PLANNER_MEMORY_BUDGET_BYTES = 2_097_152
_ESTIMATED_COMMIT_PUBLISH_STEP_MEMORY_BYTES = 12_288
_ESTIMATED_COMMIT_PUBLISH_PARAM_MEMORY_BYTES = 512
_ESTIMATED_COMMIT_PUBLISH_COLUMN_MEMORY_BYTES = 384
