def commit_publish_planner_memory_budget_env_is_set(
    env: Mapping[str, str] | None = None,
) -> bool:
    source = os.environ if env is None else env
    return _COMMIT_PUBLISH_PLANNER_MEMORY_BUDGET_ENV in source


def commit_publish_planner_memory_budget_bytes_from_env(
    env: Mapping[str, str] | None = None,
) -> int | None:
    source = os.environ if env is None else env
    raw_value = source.get(_COMMIT_PUBLISH_PLANNER_MEMORY_BUDGET_ENV)
    if raw_value is None:
        return None
    stripped = raw_value.strip()
    if not stripped or stripped.lower() in {"off", "none", "disable", "disabled"}:
        return None
    try:
        budget = int(stripped)
    except ValueError as exc:
        msg = f"{_COMMIT_PUBLISH_PLANNER_MEMORY_BUDGET_ENV} must be an integer byte count, got {raw_value!r}"
        raise ValueError(msg) from exc
    if budget < 0:
        msg = f"{_COMMIT_PUBLISH_PLANNER_MEMORY_BUDGET_ENV} must be non-negative, got {raw_value!r}"
        raise ValueError(msg)
    return budget


def _estimate_commit_publish_planner_memory_bytes(
    publish_steps: Sequence[ServerPlanStep[Any]],
    *,
    sparse_data_cols: Sequence[str],
    tip_data_cols: Sequence[str],
    staged_returning_cols: Sequence[str] | None,
    unique_filters: Sequence[tuple[str, ...]],
    tree_validation_type_filters: Sequence[tuple[str, ...]],
) -> int:
    step_count = len(publish_steps)
    estimated_param_count = sum(step.estimated_param_count() or 0 for step in publish_steps)
    column_count = len(sparse_data_cols) + len(tip_data_cols)
    if staged_returning_cols is not None:
        column_count += len(staged_returning_cols)
    filter_count = len(unique_filters) + len(tree_validation_type_filters)
    return (
        step_count * _ESTIMATED_COMMIT_PUBLISH_STEP_MEMORY_BYTES
        + estimated_param_count * _ESTIMATED_COMMIT_PUBLISH_PARAM_MEMORY_BYTES
        + column_count * _ESTIMATED_COMMIT_PUBLISH_COLUMN_MEMORY_BYTES
        + filter_count * _ESTIMATED_COMMIT_PUBLISH_FILTER_MEMORY_BYTES
    )


