    if model is None:
        return False
    return any(get_db_column_name(model, DynamicFieldName(field_name)) == column_name for field_name in model.model_fields)


def _append_framework_physical_column(
    columns: list[str],
    seen: set[str],
    *,
    aux_model: type[Any] | None,
    column_name: SqlColumnName,
) -> None:
    if aux_model is None or not is_framework_physical_db_column(aux_model, column_name):
        return
    if column_name in seen:
        return
    columns.append(column_name)
    seen.add(column_name)


