_SERVER_REF_ID_PATTERN = re.compile(
    r"^(?:step_\d+|seed_\d+|out_\d+)(?:\.[a-zA-Z_][a-zA-Z0-9_]*)*$",
)


def _server_ref_compatible_child_ref(
    ctx: LoweringContext,
    preferred_base: ServerPlanRefId,
    *,
    field_name: str,
) -> ServerPlanRefId:
    """Return a ref id that can legally be wrapped in ``ServerRefs.from_ref_id``."""
    preferred = ServerPlanRefId(f"{preferred_base}.{field_name}")
    if _SERVER_REF_ID_PATTERN.match(preferred):
        return preferred

    cache_key = f"server_ref_alias:{preferred_base}"
    alias_base = ctx._lowering_cache.get(cache_key)
    if alias_base is None:
        alias_index = int(ctx._lowering_cache.get("server_ref_alias_next", 0))
        ctx._lowering_cache["server_ref_alias_next"] = alias_index + 1
        alias_base = f"step_{900_000_000 + alias_index}"
        ctx._lowering_cache[cache_key] = alias_base
    return ServerPlanRefId(f"{alias_base}.{field_name}")


