        depends_on: frozenset[ServerPlanRefId],
    ) -> None:
        super().__init__(ref_id)
        self._dependencies = depends_on

    @property
    def level(self: _ValidationCompleteStep) -> int:
        return 0

    def result_cardinality(self: _ValidationCompleteStep) -> Cardinality:
        return Cardinality.NONE

    def is_read_only(self: _ValidationCompleteStep) -> bool:
        return True

    def execution_role(self: _ValidationCompleteStep) -> StepExecutionRole:
        return StepExecutionRole.VIRTUAL

    def supports_sql_batch_transport(self: _ValidationCompleteStep) -> bool:
        return True

    def dependencies(self: _ValidationCompleteStep) -> frozenset[str]:
        return frozenset(str(ref_id) for ref_id in self._dependencies)

    def validation_completion_dependencies(
        self: _ValidationCompleteStep,
    ) -> frozenset[ServerPlanRefId] | None:
        return self._dependencies

    def sql_visible_dependencies(self: _ValidationCompleteStep) -> frozenset[str]:
        return frozenset()

    def tables_read(self: _ValidationCompleteStep) -> frozenset[str]:
        return frozenset()

    def tables_written(self: _ValidationCompleteStep) -> frozenset[str]:
        return frozenset()

    def counts_as_sql_group_for_accounting(self: _ValidationCompleteStep) -> bool | None:
        return False

    def emits_sql_for_accounting(self: _ValidationCompleteStep) -> bool | None:
        return False

    def compile(self: _ValidationCompleteStep, ctx: CompilationContext) -> CompiledStep[None]:
        del ctx
        return CompiledStep(allow_empty_provenance_manifest=True)


def _commit_branch_domain_metadata(
    domain: type[VersioningDomain],
    *,
    include_generated_storage_columns: bool = False,
    publish_table_names: frozenset[str] | None = None,
) -> _CommitBranchDomainMetadata:
    return _compute_commit_branch_domain_metadata(
        domain,
        include_generated_storage_columns=include_generated_storage_columns,
        publish_table_names=publish_table_names,
    )


def _compute_commit_branch_domain_metadata(
    domain: type[VersioningDomain],
    *,
    include_generated_storage_columns: bool,
    publish_table_names: frozenset[str] | None,
) -> _CommitBranchDomainMetadata:
    from _internal.type_utils import is_polymorphic_class
    from l1000_schema.large_column import get_large_column_configs, large_column_pointer_name
    from l1000_schema.table_utils import get_table_name
    from l1050_polymorphism.type_filter_helper import (
        get_all_concrete_subtypes,
        polymorphic_type_name_aliases,
    )
    from l1050_polymorphism.type_registry import get_polymorphic_base_class
    from l2070_batching.write_column_policy import returnable_db_columns, versioned_data_field_plans
    from l5100_fts.fts_config import get_fts_config
    from l9600_graphs.edge_constraints import get_edge_constraints
    from l9600_graphs.graph import Graph, GraphEdge, GraphNode

    sparse_versioning_exclude = {"sys_id", "revision_id", "staged_commit_id"}
    tip_versioning_exclude = {"sys_id", "revision_id", "staged_commit_id", "deleted"}
    from l1050_polymorphism.type_registry import get_type_registry
    from l7000_versioned_schema.versioned_schema import VersionedObjectRow
    from l9600_graphs.dynamic_types import DynamicEdgeBase, DynamicNodeBase

    domain_models = tuple(domain.all_versioned_models())
    explicitly_requested_models = frozenset(domain_models)
    declared_models: list[type[VersionedObjectRow[SysId]]] = []
    for model in domain_models:
        if not isinstance(model, type) or not issubclass(model, VersionedObjectRow):
            raise TypeError("Commit domain models must be VersionedObjectRow classes")
        current_model = model
        if not is_polymorphic_class(model) and not issubclass(model, (Graph, GraphNode, GraphEdge)):
            try:
                registered_table_name = SqlTableName(get_table_name(model))
            except AttributeError:
                registered_table_name = None
            current_registered_model = get_model_for_table(registered_table_name) if registered_table_name is not None else None
            if (
                isinstance(current_registered_model, type)
                and issubclass(current_registered_model, VersionedObjectRow)
                and current_registered_model.__module__ == model.__module__
            ):
                current_model = current_registered_model
        for dynamic_base in (DynamicNodeBase, DynamicEdgeBase):
            if model is not dynamic_base and issubclass(model, dynamic_base):
                registered = get_type_registry(dynamic_base).get_registered_class(
                    f"{model.__module__}.{model.__name__}",
                )
                if registered is None:
                    raise ValueError(f"Dynamic model {model.__name__!r} has no registered identity")
                current_model = registered
                break
        if current_model not in declared_models:
            declared_models.append(current_model)
    ordered_models: list[type[VersionedObjectRow[SysId]]] = list(
        topological_sort_versioned_models(declared_models),
    )
    if publish_table_names is not None:
        filtered_models: list[type[VersionedObjectRow[SysId]]] = []
        for model in ordered_models:
            try:
                table_name = get_table_name(model)
            except AttributeError:
                continue
            if table_name in publish_table_names:
                filtered_models.append(model)
        ordered_models = filtered_models

    table_models: dict[str, list[type[DatabaseObjectRow[SysId]]]] = {}
    edge_base_table_names: list[str] = []
    symmetric_auto_create_by_table: dict[str, list[tuple[str, ...]]] = {}

    for model in ordered_models:
        try:
            table_name = get_table_name(model)
        except AttributeError:
            continue
        models_for_table = table_models.setdefault(table_name, [])
        if model not in models_for_table:
            models_for_table.append(model)
        if getattr(model, "__polymorphic__", False):
            shared_subtypes: list[type[VersionedObjectRow[SysId]]] = []
            registry = get_type_registry(get_polymorphic_base_class(model) or model)
            candidates = tuple(dict.fromkeys((*registry.get_all_subtypes(), *ordered_models)))
            for sub in candidates:
                if sub is model or not issubclass(sub, model):
                    continue
                try:
                    sub_table_name = get_table_name(sub)
                except AttributeError:
                    continue
                if sub_table_name == table_name:
                    shared_subtypes.append(sub)
            explicitly_scoped_subtypes = [sub for sub in shared_subtypes if sub in explicitly_requested_models]
            registry_base = get_polymorphic_base_class(model)
            if not explicitly_scoped_subtypes and registry_base is not None:
                shared_subtypes = [
                    sub
                    for sub in shared_subtypes
                    if (
                        (subtype_registry_base := get_polymorphic_base_class(sub)) is not None
                        and get_type_registry(subtype_registry_base).is_registered(sub)
                    )
                    or getattr(sub, "__polymorphic_abstract__", False)
                ]
            for sub in explicitly_scoped_subtypes or shared_subtypes:
                if sub not in table_models[table_name]:
                    table_models[table_name].append(sub)

    for requested_table_name, models_for_table in table_models.items():
        explicitly_requested_concrete = [
            model
            for model in explicitly_requested_models
            if is_polymorphic_class(model)
            and not getattr(model, "__abstract__", False)
            and not getattr(model, "__polymorphic_abstract__", False)
            and get_table_name(model) == requested_table_name
        ]
        if not explicitly_requested_concrete:
            continue
        requested_aliases = {alias for model in explicitly_requested_concrete for alias in polymorphic_type_name_aliases(model)}
        models_for_table[:] = [
            model
            for model in models_for_table
            if model in explicitly_requested_models
            or getattr(model, "__abstract__", False)
            or getattr(model, "__polymorphic_abstract__", False)
            or not requested_aliases.intersection(polymorphic_type_name_aliases(model))
        ]

    for model in ordered_models:
        try:
            table_name = get_table_name(model)
        except AttributeError:
            continue

        try:
            is_graph_edge = issubclass(model, GraphEdge) and model is not GraphEdge
        except TypeError:
            continue
        if not is_graph_edge:
            continue
        if table_name not in edge_base_table_names:
            edge_base_table_names.append(table_name)
        cfg = get_edge_constraints(model)
        if cfg.symmetric and cfg.symmetric_auto_create and not is_polymorphic_class(model):
            symmetric_auto_create_by_table.setdefault(table_name, []).append(())

    table_entries: list[_CommitBranchTableEntry] = []
    for entry_table_name, models_for_table in table_models.items():
        table_name = SqlTableName(entry_table_name)
        sparse_data_cols: list[str] = []
        tip_data_cols: list[str] = []
        seen_sparse: set[str] = set()
        seen_tip: set[str] = set()
        sparse_model = get_model_for_table(SqlTableName(derive_versioned_table_names(VersionedBaseTableName(str(table_name))).sparse))
        tip_model = get_model_for_table(SqlTableName(derive_versioned_table_names(VersionedBaseTableName(str(table_name))).tip))
        for table_model in models_for_table:
            if include_generated_storage_columns:
                sparse_columns = tuple(
                    column
                    for column in returnable_db_columns(
                        table_model,
                        excluded_fields=tuple(sparse_versioning_exclude),
                        include_polymorphic=False,
                    )
                )
                tip_columns = tuple(
                    column
                    for column in returnable_db_columns(
                        table_model,
                        excluded_fields=tuple(tip_versioning_exclude),
                        include_polymorphic=False,
                    )
                )
            else:
                sparse_columns = tuple(
                    plan.db_column
                    for plan in versioned_data_field_plans(
                        table_model,
                        excluded_fields=tuple(sparse_versioning_exclude),
                        include_polymorphic=False,
                    )
                )
                tip_columns = tuple(
                    plan.db_column
                    for plan in versioned_data_field_plans(
                        table_model,
                        excluded_fields=tuple(tip_versioning_exclude),
                        include_polymorphic=False,
                    )
                )
            for db_col in sparse_columns:
                if db_col not in seen_sparse:
                    sparse_data_cols.append(db_col)
                    seen_sparse.add(db_col)
            for db_col in tip_columns:
                if db_col not in seen_tip:
                    tip_data_cols.append(db_col)
                    seen_tip.add(db_col)
            for lc_config in get_large_column_configs(table_model):
                ptr = large_column_pointer_name(ContentColumnName(lc_config.column))
                if ptr not in seen_sparse:
                    sparse_data_cols.append(ptr)
                    seen_sparse.add(ptr)
                if ptr not in seen_tip:
                    tip_data_cols.append(ptr)
                    seen_tip.add(ptr)
            if get_fts_config(table_model) is not None:
                if "sys_fts_content_hash" not in seen_sparse:
                    sparse_data_cols.append("sys_fts_content_hash")
                    seen_sparse.add("sys_fts_content_hash")
                if "sys_fts_content_hash" not in seen_tip:
                    tip_data_cols.append("sys_fts_content_hash")
                    seen_tip.add("sys_fts_content_hash")
            fts_content_hash_column = SqlColumnName("sys_fts_content_hash")
            if _model_declares_db_column(sparse_model, fts_content_hash_column) and fts_content_hash_column not in seen_sparse:
                sparse_data_cols.append(fts_content_hash_column)
                seen_sparse.add(fts_content_hash_column)
            if _model_declares_db_column(tip_model, fts_content_hash_column) and fts_content_hash_column not in seen_tip:
                tip_data_cols.append(fts_content_hash_column)
                seen_tip.add(fts_content_hash_column)
            _append_framework_physical_column(
                sparse_data_cols,
                seen_sparse,
                aux_model=sparse_model,
                column_name=fts_content_hash_column,
            )
            _append_framework_physical_column(
                tip_data_cols,
                seen_tip,
                aux_model=tip_model,
                column_name=fts_content_hash_column,
            )
        if table_name in edge_base_table_names:
            for col_name in sorted(GRAPH_DENSE_KEY_COLUMNS):
                _append_framework_physical_column(
                    sparse_data_cols,
                    seen_sparse,
                    aux_model=sparse_model,
                    column_name=SqlColumnName(col_name),
                )
                _append_framework_physical_column(
                    tip_data_cols,
                    seen_tip,
                    aux_model=tip_model,
                    column_name=SqlColumnName(col_name),
                )
        for col_name in sorted(SPARSE_SEQUENCE_COLUMNS):
            _append_framework_physical_column(
                sparse_data_cols,
                seen_sparse,
                aux_model=sparse_model,
                column_name=SqlColumnName(col_name),
            )
        for col_name in sorted(TIP_SEQUENCE_COLUMNS):
            _append_framework_physical_column(
                tip_data_cols,
                seen_tip,
                aux_model=tip_model,
                column_name=SqlColumnName(col_name),
            )
        table_entries.append((table_name, tuple(models_for_table), tuple(sparse_data_cols), tuple(tip_data_cols)))

    symmetric_entries = tuple(
        (table_name, tuple(dict.fromkeys(filters))) for table_name, filters in symmetric_auto_create_by_table.items()
    )
    return tuple(table_entries), tuple(edge_base_table_names), symmetric_entries


def _commit_branch_tree_validation_type_filters(
    *,
    table_name: SqlTableName,
    models_for_table: tuple[type[DatabaseObjectRow[SysId]], ...],
    backend_type: BackendType,
    tree_validation_transport: TreeValidationTransport,
    publish_scope_descriptor: PublishScopeDescriptor,
    graph_constraints_suppressed: bool,
) -> tuple[tuple[str, ...], ...]:
    from _internal.type_utils import is_polymorphic_class
    from l1050_polymorphism.type_filter_helper import polymorphic_type_name_aliases
    from l1000_schema.table_registry import get_direct_table_config
    from l1000_schema.table_utils import get_table_name
    from l9600_graphs.edge_constraints import (
        EdgeConstraints,
        get_edge_constraints,
        should_maintain_incremental_tree_state,
        uses_incremental_tree_validation,
    )
    from l9600_graphs.graph import GraphEdge

    def _graph_edge_model(model: type[DatabaseObjectRow[SysId]]) -> bool:
        return issubclass(model, GraphEdge) and model is not GraphEdge

    def _constraints_use_incremental_tree_validation(edge_constraints: EdgeConstraints) -> bool:
        if tree_validation_transport is TreeValidationTransport.INCREMENTAL:
            return bool(should_maintain_incremental_tree_state(edge_constraints))
        return bool(
            uses_incremental_tree_validation(
                edge_constraints,
                backend_type=backend_type,
                publish_scope=publish_scope_descriptor,
                is_polymorphic=False,
                global_enabled=True,
            )
        )

    if graph_constraints_suppressed:
        return ()

    edge_models = [model for model in models_for_table if _graph_edge_model(model)]
    direct_edge_config = get_direct_table_config(edge_models[0]) if len(set(edge_models)) == 1 else None
    if direct_edge_config is not None and not direct_edge_config.sti_config_override:
        edge_constraints = get_edge_constraints(edge_models[0])
        return ((),) if _constraints_use_incremental_tree_validation(edge_constraints) else ()
    if any(is_polymorphic_class(model) for model in edge_models):
        concrete_subtypes = [
            model
            for model in edge_models
            if is_polymorphic_class(model)
            and not getattr(model, "__polymorphic_abstract__", False)
            and get_table_name(model) == table_name
        ]
        from l1050_polymorphism.type_registry import get_polymorphic_base_class, get_type_registry

        registered: set[type[DatabaseObjectRow[SysId]]] = set()
        for subtype in concrete_subtypes:
            base = get_polymorphic_base_class(subtype)
            if base is not None and get_type_registry(base).is_registered(subtype):
                registered.add(subtype)
        registered_alias_ids: dict[str, set[int]] = {}
        for subtype in registered:
            type_id = getattr(subtype, "__polymorphic_type_id__", None)
            if isinstance(type_id, int):
                for alias in polymorphic_type_name_aliases(subtype):
                    registered_alias_ids.setdefault(alias, set()).add(type_id)
        # Registry replacement preserves the old type ID. Python subclasses keep
        # the retired class alive, but it must not own the replacement's aliases.
        current_subtypes: list[type[DatabaseObjectRow[SysId]]] = []
        for subtype in concrete_subtypes:
            type_id = getattr(subtype, "__polymorphic_type_id__", None)
            superseded = (
                subtype not in registered
                and isinstance(type_id, int)
                and any(type_id in registered_alias_ids.get(alias, ()) for alias in polymorphic_type_name_aliases(subtype))
            )
            if not superseded:
                current_subtypes.append(subtype)
        concrete_subtypes = current_subtypes
        if not any(_constraints_use_incremental_tree_validation(get_edge_constraints(model)) for model in concrete_subtypes):
            return ()
        subtype_filters: list[tuple[str, ...]] = []
        alias_owners: dict[str, type[DatabaseObjectRow[SysId]]] = {}
        for subtype in dict.fromkeys(concrete_subtypes):
            if not _constraints_use_incremental_tree_validation(get_edge_constraints(subtype)):
                continue
            aliases = polymorphic_type_name_aliases(subtype)
            for alias in aliases:
                existing_owner = alias_owners.get(alias)
                if (
                    existing_owner is not None
                    and existing_owner is not subtype
                    and (
                        _constraints_use_incremental_tree_validation(get_edge_constraints(existing_owner))
                        or _constraints_use_incremental_tree_validation(get_edge_constraints(subtype))
                    )
                ):
                    model_names = ", ".join(model.__name__ for model in models_for_table)
                    msg = (
                        f"Polymorphic tree discriminator alias {alias!r} identifies both "
                        f"{existing_owner.__name__} and {subtype.__name__} in {table_name} "
                        f"from [{model_names}]."
                    )
                    raise ValueError(msg)
                alias_owners[alias] = subtype
            subtype_filters.append(aliases)
        return tuple(dict.fromkeys(subtype_filters))

    filters: list[tuple[str, ...]] = []
    for model in edge_models:
        if not _constraints_use_incremental_tree_validation(get_edge_constraints(model)):
            continue
        filters.append(())
    return tuple(dict.fromkeys(filters))


def _staged_returning_columns_from_catalog(
    planning_catalog: PlanningCatalog | None,
    staged_table_name: str,
) -> tuple[str, ...] | None:
    from l2070_batching.write_column_policy import returnable_db_columns

    if planning_catalog is None:
        return None
    try:
        table_shape = planning_catalog.table_for_name(SqlTableName(staged_table_name))
    except KeyError:
        return None
    columns = returnable_db_columns(table_shape.model_cls)
    return columns or ("sys_id",)


def _log_table_name_from_catalog(
    planning_catalog: PlanningCatalog | None,
    table_name: SqlTableName,
    *,
    physically_present: bool | None = None,
) -> SqlTableName | None:
    """Return the log table name only when typed or physical facts prove it exists."""
    log_table_name = logged_table_name(table_name)
    if physically_present is True:
        return log_table_name
    if planning_catalog is not None:
        try:
            planning_catalog.table_for_name(log_table_name)
        except KeyError:
            pass
        else:
            return log_table_name
    from l6000_log_table.log_model_registry import get_log_model_by_log_table_name

    try:
        get_log_model_by_log_table_name(log_table_name)
    except KeyError:
        return None
    return log_table_name


def _unwrap_to_str(value: _StringBackedId) -> str:
    """Unwrap branded string identifiers without discarding their public types elsewhere."""
    unwrap = getattr(value, "unwrap_to_str", None)
    if callable(unwrap):
        return str(unwrap())
    return str(value)


@dataclass(slots=True)
class CommitBranchCtx:
    """Semantic commit-branch context shared across lowered commit steps."""

    branch_id: BranchId
    current_tip_revision_id: RevisionId | None
    new_revision_id: RevisionId
    staged_commit_ids: tuple[StagedCommitId, ...] = ()


@dataclass(frozen=True, slots=True)
class _AuthoritativePublicationCorrection:
    """Exact selector and locked tip for one isolated correction terminal."""

    staged_commit_ids: tuple[StagedCommitId, ...]
    current_tip_revision_id: RevisionId | None

    def __post_init__(self: _AuthoritativePublicationCorrection) -> None:
        if not self.staged_commit_ids:
            msg = "An authoritative publication correction requires staged-commit IDs"
            raise ValueError(msg)


@dataclass(frozen=True, slots=True)
class CommitBranchLifecyclePlan:
    """Precomputed lifecycle steps for commit-branch finalization."""

    steps: tuple[ServerPlanStep[None], ...]


class _VersionedWriteTransactionProtocol(Protocol):
    """Minimal protocol for the versioned write transaction reference."""

    @property
    def base_write_transaction(self: _VersionedWriteTransactionProtocol) -> object: ...

    @property
    def owns_base_transaction(self: _VersionedWriteTransactionProtocol) -> bool: ...


class _DependencyExtensibleStep(Protocol):
    """Step protocol for publish-cleanup helpers that can add dependencies."""

    ref_id: str

    def with_additional_dependencies(
        self: _DependencyExtensibleStep,
        depends_on: frozenset[str],
    ) -> ServerPlanStep[Any]: ...


def build_commit_branch_lifecycle_plan(
    *,
    ref_id: ServerPlanRefId,
    txn: _VersionedWriteTransactionProtocol,
) -> CommitBranchLifecyclePlan:
    """Precompute lifecycle steps before commit intent lowering begins."""
    return CommitBranchLifecyclePlan(
        steps=_build_commit_branch_lifecycle_steps(ref_id=ServerPlanRefId(ref_id), txn=txn),
    )


def _build_commit_branch_lifecycle_steps(
    *,
    ref_id: ServerPlanRefId,
    txn: _VersionedWriteTransactionProtocol,
) -> tuple[ServerPlanStep[None], ...]:
    from impl.common.l2070_server_plan.steps.commit_branch_steps import VersionedStateMarkStep
    from impl.common.l2070_server_plan.steps.transaction_lifecycle_steps import (
        CommitFinalizeAfterDepsStep,
        RuntimeDatabaseCommitAfterDepsStep,
        SessionTimestampUpdateStep,
        _resolve_cache_lifecycle_owner,
        _resolve_cache_transaction,
        build_cache_commit_lifecycle_steps,
    )
    from impl.common.l7300_sql_versioned_transactions.sql_write_transaction import (
        SqlWriteTransactionBase,
    )

    lifecycle_steps: list[ServerPlanStep[Any]] = []
    base_txn = txn.base_write_transaction
    owns_base = txn.owns_base_transaction
    if base_txn is not txn:
        lifecycle_steps.append(
            VersionedStateMarkStep(ServerPlanRefId(f"{ref_id}_vstate")),
        )

    if not owns_base:
        return cast(tuple[ServerPlanStep[None], ...], tuple(lifecycle_steps))

    if isinstance(base_txn, SqlWriteTransactionBase):
        session_id = base_txn._session_id
        if session_id is not None and not session_id.is_schema_session():
            has_sys_sessions = bool(getattr(base_txn, "_sys_sessions_table_exists", False))
            if has_sys_sessions:
                lifecycle_steps.append(
                    SessionTimestampUpdateStep(ServerPlanRefId(f"{ref_id}_session_ts")),
                )
    cache_owner = _resolve_cache_lifecycle_owner(txn)
    cache_txn = None if cache_owner is None else _resolve_cache_transaction(cache_owner)
    if cache_txn is not None:
        from impl.common.l1000_cache.transaction import CacheTransaction

        concrete_cache_txn = cast(CacheTransaction, cache_txn)
        lifecycle_steps.extend(
            build_cache_commit_lifecycle_steps(
                ref_id=ServerPlanRefId(ref_id),
                cache_txn=concrete_cache_txn,
                finalize_ref=f"{ref_id}_base_finalize",
            ),
        )
        return cast(tuple[ServerPlanStep[None], ...], tuple(lifecycle_steps))
    db_commit_ref = ServerPlanRefId(f"{ref_id}_db_commit")
    lifecycle_steps.append(
        RuntimeDatabaseCommitAfterDepsStep(
            db_commit_ref,
            source_refs=[],
        ),
    )
    lifecycle_steps.append(
        CommitFinalizeAfterDepsStep(
            ServerPlanRefId(f"{ref_id}_base_finalize"),
            source_refs=[db_commit_ref],
        ),
    )
    return cast(tuple[ServerPlanStep[None], ...], tuple(lifecycle_steps))


# ── Versioned staging context ──────────────────────────────────────────────
# Pre-computed, string-serialised staging data shared by insert/update/delete
# intents.  Produced by ``_get_versioned_staging_context()`` in the mixin.


@dataclass(init=False, slots=True)
class VersionedStagingCtx:
    """Typed container for versioned staging context (replaces dict[str, object]).

    ``lazy_branch`` is a ``LazyResult[BranchId]`` that may or may not be
    resolved yet (e.g. branch-by-name lookup requires a DB query).

    Lowering code passes ``sc.lazy_branch`` directly into ``SqlParam``.
    ``SqlParam.render()`` resolves the ``LazyResult`` at execution time
    (never during lower/compile).

    Physical staged/tip table names are derived from ``staged_model`` / ``tip_model``
    via the schema registry when lowering reads ``staged_table_name`` /
    ``tip_table_name`` — not precomputed at lazy plan construction.
    """

    branch_scope_token: BranchScopeToken
    common_columns: list[str]
    connection_id_raw: str
    domain: type[VersioningDomain]
    lazy_branch: ScalarServerRef[BranchId]
    lazy_revision: ScalarServerRef[RevisionId] | None
    branch_tip_materialization: BranchTipMaterialization | None
    literal_branch: BranchId | None
    session_id_raw: str
    staged_commit_id_raw: str
    staged_visibility: StagedVisibility
    staged_model: type[DatabaseObjectRow[SysId]]
    tip_model: type[DatabaseObjectRow[SysId]]
    sparse_table_name_value: SqlTableName | None
    type_ids: list[str] | None

    def __init__(
        self: VersionedStagingCtx,
        *,
        staged_model: type[DatabaseObjectRow[SysId]],
        tip_model: type[DatabaseObjectRow[SysId]],
        common_columns: list[str],
        type_ids: list[str] | None,
        lazy_branch: BranchRefInput,
        staged_commit_id_raw: str,
        domain: type[VersioningDomain],
        connection_id_raw: str,
        session_id_raw: str,
        lazy_revision: ScalarServerRef[RevisionId] | None = None,
        branch_tip_materialization: BranchTipMaterialization | None = None,
        staged_visibility: StagedVisibility = StagedVisibility.TRANSACTION,
        branch_scope_token: BranchScopeToken | None = None,
        literal_branch: BranchId | None = None,
        sparse_table_name_value: SqlTableName | None = None,
    ) -> None:
        self.staged_model = staged_model
        self.tip_model = tip_model
        self.sparse_table_name_value = sparse_table_name_value
        self.common_columns = common_columns
        self.type_ids = type_ids
        self.branch_scope_token = branch_scope_token or opaque_scope_token(lazy_branch)
        if isinstance(lazy_branch, ScalarServerRef):
            self.lazy_branch = lazy_branch
            self.literal_branch = literal_branch
        elif isinstance(lazy_branch, LazyResult):
            lazy_branch_result: LazyResult[BranchId] = lazy_branch
            self.lazy_branch = ServerRefs.scalar(lazy_branch_result)
            self.literal_branch = literal_branch
        else:
            resolved_literal_branch: BranchId = lazy_branch
            self.lazy_branch = ServerRefs.scalar(resolved_literal_branch)
            self.literal_branch = literal_branch or resolved_literal_branch
        self.staged_commit_id_raw = staged_commit_id_raw
        self.domain = domain
        self.lazy_revision = lazy_revision
        self.branch_tip_materialization = branch_tip_materialization
        self.connection_id_raw = connection_id_raw
        self.session_id_raw = session_id_raw
        self.staged_visibility = staged_visibility

    @property
    def staged_table_name(self) -> str:
        """Physical staged table name; resolved when lowering reads this attribute."""
        from l1000_schema.table_utils import get_table_name

        return str(get_table_name(self.staged_model))

    @property
    def sparse_table_name(self) -> str:
        """Physical sparse table name for this versioned family."""
        from l1000_schema.table_registry import get_table_config
        from l7000_versioned_schema.versioned_table_info import get_versioned_table_names, is_versioned_model

        if self.sparse_table_name_value is not None:
            return str(self.sparse_table_name_value)
        source_model = get_table_config(self.tip_model).source_versioned_model
        if source_model is None or not is_versioned_model(source_model):
            msg = f"{self.tip_model.__name__} does not identify its source versioned model."
            raise TypeError(msg)
        return str(get_versioned_table_names(source_model).sparse)

    @property
    def tip_table_name(self) -> str:
        """Physical tip table name; resolved when lowering reads this attribute."""
        from l1000_schema.table_utils import get_table_name

        return str(get_table_name(self.tip_model))


