class _RequireNonEmptyCommitStep(NonPublishingStep[None]):
    """Validate that at least one staged-row probe produced rows."""

    def __init__(
        self: _RequireNonEmptyCommitStep,
        ref_id: ServerPlanRefId,
        source_refs: Sequence[ServerPlanRefId],
    ) -> None:
        super().__init__(ref_id)
        self._source_refs = tuple(str(ref_id) for ref_id in source_refs)

    @property
    def level(self: _RequireNonEmptyCommitStep) -> int:
        return 0

    def result_cardinality(self: _RequireNonEmptyCommitStep) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self: _RequireNonEmptyCommitStep) -> bool:
        return True

    def execution_role(self: _RequireNonEmptyCommitStep) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def step_tags(self: _RequireNonEmptyCommitStep) -> frozenset[str]:
        return frozenset({"validation", "commit_branch"})

    def counts_as_sql_group_for_accounting(self: _RequireNonEmptyCommitStep) -> bool | None:
        return False

    def tables_read(self: _RequireNonEmptyCommitStep) -> frozenset[str]:
        return frozenset()

    def tables_written(self: _RequireNonEmptyCommitStep) -> frozenset[str]:
        return frozenset()

    def dependencies(self: _RequireNonEmptyCommitStep) -> frozenset[str]:
        return frozenset(self._source_refs)

    def supports_sql_batch_transport(self: _RequireNonEmptyCommitStep) -> bool:
        return True

    def compile(self: _RequireNonEmptyCommitStep, ctx: CompilationContext) -> CompiledStep[None]:
        from impl.common.l2100_sql_grammar.domain.versioning.stmt_commit_assertion import (
            SqlNonEmptyCommitAssertion,
        )
        from l1100_exceptions.exceptions import ProgrammingError

        probe_cte_names: list[str] = []
        auxiliary_ctes: list[tuple[str, object]] = []
        for source_ref in self._source_refs:
            source_cte = _require_non_empty_commit_source_cte(ctx, source_ref)
            probe_cte_names.append(source_cte.ref_id)
            if source_cte.auxiliary_query is not None:
                auxiliary_ctes.append((source_cte.ref_id, source_cte.auxiliary_query))
        __opa002_grammar_1049 = SqlNonEmptyCommitAssertion(tuple(probe_cte_names))
        output_shape = CompiledOutputShape(
            tuple(synthetic_output_field(column, role="non_empty_commit_assertion") for column in ("ok", "error_code", "message"))
        )
        column_type_hints = SqlColumnTypeHints(
            bool_columns=frozenset({"ok"}),
            text_columns=frozenset({"error_code", "message"}),
        )
        return CompiledStep(
            output_shape=output_shape,
            result_relation=DeclaredResultRelation.from_output_shape(output_shape),
            column_type_hints=column_type_hints,
            grammar=__opa002_grammar_1049,
            needs_returning=True,
            auxiliary_ctes=auxiliary_ctes or None,
            closed_post_op=sql_assertion_post_op(
                "No staged commits found for branch",
                exc_type=ProgrammingError,
            ),
        )

    def execute_runtime(self: _RequireNonEmptyCommitStep, resolved: TerminalResolvedValues) -> None:
        from l1100_exceptions.exceptions import ProgrammingError

        count = 0
        for ref_id in self._source_refs:
            value = resolved.get(ref_id)
            if not isinstance(value, bool):
                msg = f"Non-empty commit probe {ref_id!r} must publish bool, got {type(value).__name__}"
                raise TypeError(msg)
            if value:
                count += 1
        if count <= 0:
            raise ProgrammingError("No staged commits found for branch")


