class CommitBranchIntent(IntentStep[RevisionId], SpeculativePublicationSourceContract):
    """Unified commit-branch publish intent (#2372 §10.1).

    Single class replacing the six legacy variant subclasses. Internal
    dispatch is based on ``scope_kind`` (``"inline"`` /
    ``"connection_scoped"`` / ``"branch_scoped"``) and whether
    ``expected_tip_revision_id`` is present. Each combination selects a
    specific ``FetchBranch*Step`` and publish / cleanup strategy.
    """

    intent_tags = frozenset({"write", "commit_branch", "versioned", "intent"})
    domain: type[VersioningDomain]
    branch_id: ScalarServerRef[BranchId]
    literal_branch_id: BranchId | None
    session_id: ScalarServerRef[SessionId]
    allow_empty: bool
    is_new_branch: ScalarServerRef[bool]
    revision_metadata: _RevisionMetadataPayload
    scope_kind: CommitBranchScopeKind
    inline_staged_commit_id: StagedCommitId | None
    visibility_scope_value: CommitVisibilityScopeInput
    explicit_staged_commit_ids: tuple[StagedCommitId, ...]
    expected_tip_revision_id: ScalarServerRef[RevisionId] | None
    ordered_parent_revision_ids: tuple[RevisionId, ...] | None
    ordered_parent_relationship_types: tuple[ParentType, ...] | None
    concurrent_commit_behavior: ConcurrentBranchCommitBehavior
    branch_scope_token: BranchScopeToken
    materialize_tip: TipMaterializationPolicy
    inline_touched_table_names: frozenset[str] | None
    inline_deleted_table_names: frozenset[str] | None
    speculative_publish_table_names: frozenset[str] | None
    speculative_insert_only_table_names: frozenset[str]
    defer_database_commit: bool
    revision_timestamp: AwareDatetime | None
    revision_session_id: SessionId | None
    _authoritative_correction: _AuthoritativePublicationCorrection | None
    _new_revision_ref: ScalarServerRef[RevisionId]
    publication_epoch: PublicationEpoch
    publication_epoch_id: PublicationEpochId
    staged_admission_producers: tuple[StagedRowProductionEffect, ...]
    staged_admission_source_keys: tuple[AdmissionStagedSourceKey, ...]

    def __init__(self: CommitBranchIntent, ref_id: ServerPlanRefId) -> None:
        super().__init__(ref_id)
        self.prepublish_dependencies: frozenset[str] = frozenset()
        self.precommit_dependencies: frozenset[ServerPlanRefId] = frozenset()
        self.precommit_validation_steps: tuple[ServerPlanStep[Any], ...] = ()
        self._validation_anchor = ServerPlanRefId(f"{ref_id}_update_tip")
        self.prepublish_result_dependencies: frozenset[ServerPlanRefId] = frozenset()
        self._new_revision_id = RevisionId.new()
        self._new_revision_ref = ServerRefs.scalar(self._new_revision_id)
        self.literal_branch_id = None
        self.inline_staged_commit_id = None
        self.visibility_scope_value = None
        self.explicit_staged_commit_ids = ()
        self.expected_tip_revision_id = None
        self.ordered_parent_revision_ids = None
        self.ordered_parent_relationship_types = None
        self.concurrent_commit_behavior = ConcurrentBranchCommitBehavior.FAIL_FAST
        self.branch_scope_token = opaque_scope_token(None)
        self.materialize_tip = True
        self.inline_touched_table_names = None
        self.inline_deleted_table_names = None
        self.speculative_publish_table_names = None
        self.speculative_insert_only_table_names = frozenset()
        self.defer_database_commit = False
        self.revision_timestamp = None
        self.revision_session_id = None
        self._authoritative_correction = None
        self.publication_epoch_id = PublicationEpochId(f"{ref_id}:initial")
        self.publication_epoch = PublicationEpoch(
            epoch_id=self.publication_epoch_id,
            base_revision_ref=ServerPlanRefId(f"{ref_id}:base_revision"),
            predecessor_publication_ref=None,
            frontier=VersionedCommitEffectFrontier(()),
        )
        self.staged_admission_producers = ()
        self.staged_admission_source_keys = ()

    @property
    def new_revision_ref(self: CommitBranchIntent) -> ScalarServerRef[RevisionId]:
        """Return the planning-owned ID that this publication will create."""
        return self._new_revision_ref

    @property
    def transport_config(self: CommitBranchIntent) -> _CommitBranchTransportConfig:
        """Return the closed semantic payload used by generic intent transport."""
        if self.precommit_validation_steps:
            raise ValueError("CommitBranchIntent with custom validation steps is not transportable")
        if self._authoritative_correction is not None:
            raise ValueError("Corrective CommitBranchIntent is not transportable")
        return _CommitBranchTransportConfig(
            domain=self.domain,
            branch_id=self.branch_id,
            literal_branch_id=self.literal_branch_id,
            session_id=self.session_id,
            allow_empty=self.allow_empty,
            is_new_branch=self.is_new_branch,
            revision_metadata=self.revision_metadata,
            scope_kind=self.scope_kind,
            inline_staged_commit_id=self.inline_staged_commit_id,
            visibility_scope_value=self.visibility_scope_value,
            explicit_staged_commit_ids=self.explicit_staged_commit_ids,
            expected_tip_revision_id=self.expected_tip_revision_id,
            concurrent_commit_behavior=self.concurrent_commit_behavior,
            ordered_parent_revision_ids=self.ordered_parent_revision_ids,
            ordered_parent_relationship_types=self.ordered_parent_relationship_types,
            branch_scope_token=self.branch_scope_token,
            materialize_tip=self.materialize_tip,
            inline_touched_table_names=self.inline_touched_table_names,
            inline_deleted_table_names=self.inline_deleted_table_names,
            speculative_publish_table_names=self.speculative_publish_table_names,
            speculative_insert_only_table_names=self.speculative_insert_only_table_names,
            defer_database_commit=self.defer_database_commit,
            revision_timestamp=self.revision_timestamp,
            revision_session_id=self.revision_session_id,
            new_revision_id=str(self._new_revision_id),
            prepublish_dependencies=self.prepublish_dependencies,
            precommit_dependencies=self.precommit_dependencies,
            prepublish_result_dependencies=self.prepublish_result_dependencies,
            publication_epoch=self.publication_epoch,
            publication_epoch_id=self.publication_epoch_id,
            staged_admission_producers=self.staged_admission_producers,
            staged_admission_source_keys=self.staged_admission_source_keys,
        )

    @classmethod
    def _from_remote_payload(
        cls,
        *,
        ref_id: ServerPlanRefId,
        config: _CommitBranchTransportConfig,
    ) -> CommitBranchIntent:
        """Rebuild a branch-publication terminal from its semantic payload."""
        intent = cls(ref_id)
        intent.domain = config.domain
        intent.branch_id = config.branch_id
        intent.literal_branch_id = config.literal_branch_id
        intent.session_id = config.session_id
        intent.allow_empty = config.allow_empty
        intent.is_new_branch = config.is_new_branch
        intent.revision_metadata = config.revision_metadata
        intent.scope_kind = config.scope_kind
        intent.inline_staged_commit_id = config.inline_staged_commit_id
        intent.visibility_scope_value = config.visibility_scope_value
        intent.explicit_staged_commit_ids = config.explicit_staged_commit_ids
        intent.expected_tip_revision_id = config.expected_tip_revision_id
        intent.ordered_parent_revision_ids = config.ordered_parent_revision_ids
        intent.ordered_parent_relationship_types = config.ordered_parent_relationship_types
        intent.concurrent_commit_behavior = config.concurrent_commit_behavior
        intent.branch_scope_token = config.branch_scope_token
        intent.materialize_tip = config.materialize_tip
        intent.inline_touched_table_names = config.inline_touched_table_names
        intent.inline_deleted_table_names = config.inline_deleted_table_names
        intent.speculative_publish_table_names = config.speculative_publish_table_names
        intent.speculative_insert_only_table_names = config.speculative_insert_only_table_names
        intent.defer_database_commit = config.defer_database_commit
        intent.revision_timestamp = config.revision_timestamp
        intent.revision_session_id = config.revision_session_id
        intent._authoritative_correction = None
        intent._new_revision_id = RevisionId(config.new_revision_id)
        intent._new_revision_ref = ServerRefs.scalar(intent._new_revision_id)
        intent.prepublish_dependencies = config.prepublish_dependencies or frozenset()
        intent.precommit_dependencies = config.precommit_dependencies or frozenset()
        intent.prepublish_result_dependencies = config.prepublish_result_dependencies or frozenset()
        intent.publication_epoch = config.publication_epoch
        intent.publication_epoch_id = config.publication_epoch_id
        intent.staged_admission_producers = config.staged_admission_producers
        intent.staged_admission_source_keys = config.staged_admission_source_keys
        return intent

    def declared_lowered_ref_ids(self: CommitBranchIntent) -> frozenset[ServerPlanRefId]:
        return frozenset({self._validation_anchor, *(step.ref_id for step in self.precommit_validation_steps)})

    def commit_validation_anchor(self: CommitBranchIntent) -> ServerPlanRefId:
        return self._validation_anchor

    def configure_authoritative_correction(
        self: CommitBranchIntent,
        *,
        staged_commit_ids: Sequence[StagedCommitId],
        current_tip_revision_id: RevisionId | None,
    ) -> None:
        """Configure this fresh terminal as one exact-selector correction."""
        staged_commit_ids = tuple(staged_commit_ids)
        if self._authoritative_correction is not None:
            msg = "A commit terminal already has an authoritative correction"
            raise RuntimeError(msg)
        self._authoritative_correction = _AuthoritativePublicationCorrection(
            staged_commit_ids=staged_commit_ids,
            current_tip_revision_id=current_tip_revision_id,
        )

    def owns_database_commit(self: CommitBranchIntent) -> bool:
        """Return whether branch publication owns the durable commit terminal."""
        return not self.defer_database_commit

    def dependencies(self: CommitBranchIntent) -> frozenset[str]:
        deps: set[str] = set(self.prepublish_dependencies)
        deps.update(str(ref) for ref in self.prepublish_result_dependencies)
        deps.update(self.branch_id.dependencies())
        deps.update(self.session_id.dependencies())
        deps.update(self.is_new_branch.dependencies())
        if self.expected_tip_revision_id is not None:
            deps.update(self.expected_tip_revision_id.dependencies())
        deps.discard(str(self.ref_id))
        return frozenset(deps)

    def requires_prior_step_boundary(self: CommitBranchIntent) -> bool:
        return bool(self.prepublish_dependencies)

    def _effective_staged_commit_ids(self: CommitBranchIntent) -> tuple[StagedCommitId, ...]:
        inline_ids = (self.inline_staged_commit_id,) if self.inline_staged_commit_id is not None else ()
        return tuple(dict.fromkeys((*self.explicit_staged_commit_ids, *inline_ids)))

    def _effective_scope_kind(
        self: CommitBranchIntent,
        ctx: LoweringContext,
    ) -> _EffectiveCommitBranchScopeKind:
        return self.scope_kind

    def _build_commit_context_steps(
        self: CommitBranchIntent,
        *,
        domain: type[VersioningDomain],
        commit_ctx_ref: CommitBranchContextRefId,
        scope_kind: _EffectiveCommitBranchScopeKind,
        ctx: LoweringContext,
    ) -> tuple[Sequence[ServerPlanStep[Any]], ServerPlanStep[CommitBranchCtx]]:
        """Emit the prefix steps (fetch + optional concurrency guard) plus the
        semantic-context step that reads them.

        When ``expected_tip_revision_id`` is set, the prefix now expands to::

            fetch_step (non-locking read)
            verify_step = VerifyBranchTipMatchStep(fetch_ref, expected_tip)
            assert_step = AssertStep(
                predicate_ref=verify_step_output,
                error=ConcurrentBranchUpdateError(...),
            )

        instead of the legacy fused-fetch
        ``FetchBranch*WithExpectedTip*Step`` variants (#2372 §10.1,
        Phase 6). The optimistic-lock check is now a first-class
        :class:`AssertStep` and composes with optimizer Pass 3 rather
        than a hard-coded post-op inside the fetch step.
        """
        from impl.common.l2070_server_plan.steps.commit_branch_steps import (
            BuildCommitBranchCtxStep,
            LockedCommitBranchCtxStep,
            CommitAdmissionAssertStep,
            CommitAdmissionPredicateStep,
            AssertBranchTipMatchStep,
            FetchBranchAndStagedBranchScopedStep,
            FetchBranchAndStagedConnectionScopedStep,
            FetchBranchTipStep,
            VerifyBranchTipMatchStep,
            _FetchBranchOptions,
            build_concurrent_branch_update_error,
        )
        from l2070_batching.conditional_step import AssertStep
        from l2070_batching.server_ref import ServerRefs

        correction = self._authoritative_correction
        if correction is not None:
            if self.literal_branch_id is None:
                msg = "A publication correction requires a locked branch and exact staged selector"
                raise RuntimeError(msg)
            return (
                (),
                LockedCommitBranchCtxStep(
                    commit_ctx_ref,
                    branch_id=self.literal_branch_id,
                    current_tip_revision_id=correction.current_tip_revision_id,
                    staged_commit_ids=correction.staged_commit_ids,
                    new_revision_id=self._new_revision_id,
                ),
            )

        fetch_ref = ServerPlanRefId(f"{commit_ctx_ref}_fetch")
        fetch_allow_empty = True
        expected_tip = self.expected_tip_revision_id
        # PostgreSQL admission uses one transaction-scoped advisory lock for both
        # expected-tip and implicit-tip publication. The lock survives an internal
        # speculative correction request.
        fail_fast_publish = self.concurrent_commit_behavior == ConcurrentBranchCommitBehavior.FAIL_FAST
        use_lazy_commit_admission = (
            fail_fast_publish and ctx.backend_profile.traits.commit_admission_transport is CommitAdmissionTransport.LOCKED_PREDICATE
        )
        use_for_update = not (
            use_lazy_commit_admission
            or ctx.backend_profile.traits.commit_admission_transport is CommitAdmissionTransport.ORDERED_PREDICATE
        )
        for_update_nowait = (
            fail_fast_publish and ctx.backend_profile.traits.commit_admission_transport is CommitAdmissionTransport.MATERIALIZED_PREDICATE
        )
        inline_staged_commit_ids: tuple[StagedCommitId, ...] = ()
        fetch_step: ServerPlanStep[Any]
        admission_prefix_steps: list[ServerPlanStep[Any]] = []
        # The fetch snapshots the staged-commit set that the commit will
        # publish. It must run after every write the commit is sequenced
        # behind, otherwise staged commits created by those writes are
        # silently excluded from the promotion.
        fetch_depends_on: frozenset[ServerPlanRefId] = frozenset()
        prepublish_dependency_refs = (
            _lowered_commit_dependency_refs(
                ctx,
                (*self.prepublish_dependencies, *(str(ref) for ref in self.prepublish_result_dependencies)),
            )
            | self.prepublish_result_dependencies
        )
        owner_plan = ctx.owner_plan
        if self.prepublish_result_dependencies:
            from impl.common.l2070_server_plan.base_server_plan import BaseServerPlan

            assert isinstance(owner_plan, BaseServerPlan)
            returned_ref_ids = tuple(ref_id for _name, ref_id in owner_plan.returned_ref_bindings())
            prepublish_dependency_refs |= frozenset(
                _lowered_commit_dependency_ref_for(ctx, dependency_ref)
                for dependency_ref in self.prepublish_result_dependencies
                if dependency_ref in returned_ref_ids
            )
        pending_write_refs = frozenset(ctx.pending_versioned_commit_dependency_refs)
        ctx.pending_versioned_commit_dependency_refs.clear()

        if self._authoritative_correction is not None:
            pending_write_refs = frozenset()

        prepublish_dependency_refs = prepublish_dependency_refs | pending_write_refs
        commit_entry_steps: list[ServerPlanStep[Any]] = []
        effective_prefix_dependencies = prepublish_dependency_refs
        ctx._lowering_cache[f"effective_commit_dependencies:{self.ref_id}"] = tuple(
            sorted(str(ref_id) for ref_id in effective_prefix_dependencies)
        )

        if use_lazy_commit_admission:
            admission_ref = _server_ref_compatible_child_ref(
                ctx,
                self.ref_id,
                field_name="commit_admitted",
            )
            admission_assert_ref = _server_ref_compatible_child_ref(
                ctx,
                self.ref_id,
                field_name="commit_admission_assert",
            )
            admission_prefix_steps.append(
                CommitAdmissionPredicateStep(
                    admission_ref,
                    branch_id=self.branch_id,
                    depends_on=effective_prefix_dependencies,
                ),
            )
            admission_prefix_steps.append(
                CommitAdmissionAssertStep(
                    admission_assert_ref,
                    admission_ref=admission_ref,
                ),
            )
            fetch_depends_on = fetch_depends_on | {admission_assert_ref}
        else:
            fetch_depends_on = fetch_depends_on | effective_prefix_dependencies

        if self.explicit_staged_commit_ids:
            inline_staged_commit_ids = self._effective_staged_commit_ids()
            fetch_step = FetchBranchTipStep(
                fetch_ref,
                domain=domain,
                branch_id=self.branch_id,
                options=_FetchBranchOptions(
                    use_for_update=use_for_update,
                    allow_empty=fetch_allow_empty,
                    for_update_nowait=for_update_nowait,
                    depends_on=fetch_depends_on,
                ),
            )
        elif scope_kind == "inline":
            assert self.inline_staged_commit_id is not None
            inline_staged_commit_ids = (self.inline_staged_commit_id,)
            fetch_step = FetchBranchTipStep(
                fetch_ref,
                domain=domain,
                branch_id=self.branch_id,
                options=_FetchBranchOptions(
                    use_for_update=use_for_update,
                    allow_empty=fetch_allow_empty,
                    for_update_nowait=for_update_nowait,
                    depends_on=fetch_depends_on,
                ),
            )
        elif scope_kind == "connection_scoped":
            assert self.visibility_scope_value is not None
            if self.inline_staged_commit_id is not None:
                inline_staged_commit_ids = (self.inline_staged_commit_id,)
            connection_id = ConnectionId(self.visibility_scope_value.unwrap_to_uuid_compatible_str())
            fetch_step = FetchBranchAndStagedConnectionScopedStep(
                fetch_ref,
                domain=domain,
                branch_id=self.branch_id,
                connection_id=cast("Any", connection_id),
                options=_FetchBranchOptions(
                    use_for_update=use_for_update,
                    allow_empty=fetch_allow_empty,
                    for_update_nowait=for_update_nowait,
                    depends_on=fetch_depends_on,
                ),
            )
        else:
            if self.inline_staged_commit_id is not None:
                inline_staged_commit_ids = (self.inline_staged_commit_id,)
            fetch_step = FetchBranchAndStagedBranchScopedStep(
                fetch_ref,
                domain=domain,
                branch_id=self.branch_id,
                options=_FetchBranchOptions(
                    use_for_update=use_for_update,
                    allow_empty=fetch_allow_empty,
                    for_update_nowait=for_update_nowait,
                    depends_on=fetch_depends_on,
                ),
            )

        prefix_steps: list[ServerPlanStep[Any]] = [*commit_entry_steps, *admission_prefix_steps, fetch_step]
        extra_build_ctx_deps: frozenset[ServerPlanRefId] = frozenset()

        if expected_tip is not None:
            intent_ref_id = self.ref_id
            verify_ref = _server_ref_compatible_child_ref(
                ctx,
                intent_ref_id,
                field_name="tip_match",
            )
            verify_step = VerifyBranchTipMatchStep(
                verify_ref,
                fetch_ref=fetch_ref,
                expected_tip_revision_id=expected_tip,
            )
            assert_ref = _server_ref_compatible_child_ref(
                ctx,
                intent_ref_id,
                field_name="tip_assert",
            )
            branch_label = self.branch_id.ref_id or "<branch>"
            assert_step: ServerPlanStep[Any] = AssertBranchTipMatchStep(
                ref_id=assert_ref,
                verify_ref=verify_ref,
                error_message=str(build_concurrent_branch_update_error(branch_label=branch_label)),
            )
            prefix_steps.extend((verify_step, assert_step))
            extra_build_ctx_deps = frozenset({assert_ref})

        build_ctx_step = BuildCommitBranchCtxStep(
            commit_ctx_ref,
            fetch_ref=fetch_ref,
            branch_id=self.branch_id,
            literal_branch_id=self.literal_branch_id,
            new_revision_id=self._new_revision_id,
            inline_staged_commit_ids=inline_staged_commit_ids,
            depends_on=extra_build_ctx_deps,
        )
        return (tuple(prefix_steps), build_ctx_step)

    def _build_publish_scope(
        self: CommitBranchIntent,
        *,
        branch_ref: ScalarServerRef[BranchId],
        staged_commits_table: SqlTableName,
        scope_kind: _EffectiveCommitBranchScopeKind,
    ) -> BranchScopedSparsePublish | ExplicitSparsePublish:
        from impl.common.l2070_server_plan.steps.commit_branch_steps import (
            BranchScopedSparsePublish,
            ExplicitSparsePublish,
        )

        correction = self._authoritative_correction
        if correction is not None:
            correction_ids = correction.staged_commit_ids
            return ExplicitSparsePublish(
                branch_id=branch_ref,
                staged_commit_ids=correction_ids,
                branch_scope_token=self.branch_scope_token,
            )
        if self.explicit_staged_commit_ids:
            return ExplicitSparsePublish(
                branch_id=branch_ref,
                staged_commit_ids=self._effective_staged_commit_ids(),
                branch_scope_token=self.branch_scope_token,
            )
        if scope_kind == "inline":
            assert self.inline_staged_commit_id is not None
            del staged_commits_table
            return ExplicitSparsePublish(
                branch_id=branch_ref,
                staged_commit_ids=(self.inline_staged_commit_id,),
                branch_scope_token=self.branch_scope_token,
            )
        if scope_kind == "connection_scoped":
            assert self.visibility_scope_value is not None
            connection_id_raw: str | None = self.visibility_scope_value.unwrap_to_uuid_compatible_str()
        else:
            connection_id_raw = None
        return BranchScopedSparsePublish(
            branch_id=branch_ref,
            staged_commits_table=staged_commits_table,
            visibility_scope_value=connection_id_raw,
            branch_scope_token=self.branch_scope_token,
            inline_staged_commit_ids=((self.inline_staged_commit_id,) if self.inline_staged_commit_id is not None else ()),
        )

    def _append_cleanup_steps(
        self: CommitBranchIntent,
        *,
        steps: list[ServerPlanStep[Any]],
        branch_ref: ScalarServerRef[BranchId],
        staged_commits_table: SqlTableName,
        cleanup_dependencies: set[ServerPlanRefId],
        scope_kind: _EffectiveCommitBranchScopeKind,
    ) -> frozenset[ServerPlanRefId]:
        from impl.common.l2070_server_plan.steps.commit_branch_steps import (
            CleanupStagedCommitsStep,
            CleanupStagedFieldStreamsStep,
        )

        from l1000_schema.large_column import get_large_column_configs

        cleanup_staged_fields = any(get_large_column_configs(model_cls) for model_cls in self.domain.all_versioned_models())
        cleanup_refs: set[ServerPlanRefId] = set()
        connection_id_raw: str | None
        correction = self._authoritative_correction
        if correction is not None:
            connection_id_raw = None
            staged_commit_ids = correction.staged_commit_ids
        elif self.explicit_staged_commit_ids:
            connection_id_raw = None
            staged_commit_ids = self._effective_staged_commit_ids()
        elif scope_kind == "connection_scoped":
            assert self.visibility_scope_value is not None
            connection_id_raw = self.visibility_scope_value.unwrap_to_uuid_compatible_str()
            staged_commit_ids = (self.inline_staged_commit_id,) if self.inline_staged_commit_id is not None else ()
        elif scope_kind == "inline":
            assert self.inline_staged_commit_id is not None
            connection_id_raw = None
            staged_commit_ids = (self.inline_staged_commit_id,)
        else:
            connection_id_raw = None
            staged_commit_ids = ()
        cleanup_step_dependencies = frozenset(cleanup_dependencies)
        if cleanup_staged_fields:
            stream_cleanup_ref = ServerPlanRefId(f"{self.ref_id}_cleanup_streams")
            steps.append(
                CleanupStagedFieldStreamsStep(
                    stream_cleanup_ref,
                    staged_commits_table,
                    branch_ref,
                    connection_id_raw,
                    staged_commit_ids=staged_commit_ids,
                    depends_on=cleanup_step_dependencies,
                ),
            )
            cleanup_step_dependencies = frozenset({*cleanup_dependencies, stream_cleanup_ref})
        cleanup_ref = ServerPlanRefId(f"{self.ref_id}_cleanup")
        steps.append(
            CleanupStagedCommitsStep(
                cleanup_ref,
                staged_commits_table,
                branch_ref,
                connection_id_raw,
                staged_commit_ids=staged_commit_ids,
                depends_on=cleanup_step_dependencies,
            ),
        )
        cleanup_refs.add(cleanup_ref)
        if not self.explicit_staged_commit_ids and scope_kind != "inline" and self.inline_staged_commit_id is not None:
            inline_cleanup_dependencies = frozenset(cleanup_dependencies)
            if cleanup_staged_fields:
                inline_stream_cleanup_ref = ServerPlanRefId(f"{self.ref_id}_inline_cleanup_streams")
                steps.append(
                    CleanupStagedFieldStreamsStep(
                        inline_stream_cleanup_ref,
                        staged_commits_table,
                        branch_ref,
                        None,
                        staged_commit_ids=(self.inline_staged_commit_id,),
                        depends_on=inline_cleanup_dependencies,
                    ),
                )
                inline_cleanup_dependencies = frozenset({*cleanup_dependencies, inline_stream_cleanup_ref})
            inline_cleanup_ref = ServerPlanRefId(f"{self.ref_id}_inline_cleanup")
            steps.append(
                CleanupStagedCommitsStep(
                    inline_cleanup_ref,
                    staged_commits_table,
                    branch_ref,
                    None,
                    staged_commit_ids=(self.inline_staged_commit_id,),
                    depends_on=inline_cleanup_dependencies,
                ),
            )
            cleanup_refs.add(inline_cleanup_ref)
        return frozenset(cleanup_refs)

    def lower(self: CommitBranchIntent, ctx: LoweringContext) -> Sequence[ServerPlanStep[RevisionId]]:
        from impl.common.l2070_server_plan.steps.commit_branch_steps import (
            CleanupConnectionRippleCandidatesStep,
            DeleteStagedForCommitStep,
            DemoteOldBranchTipAnchorStep,
            EnqueueConnectionRippleBatchesStep,
            FinalizeConnectionRippleBatchesStep,
            FinalizeConnectionRippleItemsStep,
            StaticStagedAdmissionProofStep,
            InsertRevisionPhysicalKeyStep,
            InsertRevisionParentStep,
            InsertRevisionStep,
            ValidateRevisionIdAvailableStep,
            ValidateRevisionParentsExistStep,
            LockSelectedStagedCommitsStep,
            revision_identity_tables,
            ProjectCommitBranchResultStep,
            ExactGraphRouteDescriptor,
            PublishVersionedCommitNotificationsStep,
            ReconcileGraphAuxiliaryTablesStep,
            SelectVersionedCommitDeltaRowsStep,
            SpeculativePublicationGuardStep,
            StagedEdgeValidationNeededStep,
            CommitDeltaStepBuilder,
            VersionedCommitDeltaSource,
            UpdateBranchTipStep,
            UpsertRevisionBranchAnchorStep,
            UpsertRevisionParentsStep,
            CommitBranchAdmission,
            ValidateCommitBranchAdmissionStep,
            ValidateStagedFieldStreamsFinalizedStep,
            _DeleteStagedForCommitConfig,
            _DemoteOldBranchTipAnchorConfig,
            _FinalizeRippleBatchesConfig,
            _FinalizeRippleItemsConfig,
            _RippleHandlerConfig,
            _GraphAuxiliaryGrammarFactory,
            _GraphAuxiliarySqlStep,
            _InsertRevisionConfig,
            _LegacyRevisionParentMode,
            _RevisionParentRowSpec,
            _UpsertRevisionParentsConfig,
            _scope_descriptor_from_selector,
            _selector_for_scope,
            _UpsertRevisionBranchAnchorConfig,
            build_sparse_publish_steps,
        )
        from impl.common.l2070_server_plan.steps.edge_constraint_steps import (
            AutoCreateSymmetricReciprocalsInStagedStep,
            _AutoCreateSymmetricReciprocalsConfig,
        )
        from l9600_graphs.graph import GraphNode
        from impl.common.l2070_server_plan.provider_helpers import (
            require_versioned_lowering_provider,
        )
        from l1000_schema.table_utils import get_table_name
        from l9600_graphs.incremental_validation_models import domain_has_graph_models
        from l9600_graphs.suppress_constraints import are_graph_constraints_suppressed
        from l9800_rippling.registry import RippleRegistry
        from l2070_batching.backend_profile import TreePublishValidationRequest

        domain = self.domain
        graph_constraints_suppressed = are_graph_constraints_suppressed()
        branch_ref = self.branch_id
        scope_kind = self._effective_scope_kind(ctx)
        commit_ctx_ref = CommitBranchContextRefId(f"{self.ref_id}_commit_ctx")
        prefix_steps, build_ctx_step = self._build_commit_context_steps(
            domain=domain,
            commit_ctx_ref=commit_ctx_ref,
            scope_kind=scope_kind,
            ctx=ctx,
        )
        new_revision_id = self._new_revision_id
        new_revision_ref = self._new_revision_ref
        update_tip_ref = ServerPlanRefId(f"{self.ref_id}_update_tip")
        staged_commits_table = get_table_name(domain.staged_commit_model)
        branch_table: str = get_table_name(domain.branch_model)
        steps: list[ServerPlanStep[Any]] = [*prefix_steps, build_ctx_step]
        publish_scope = self._build_publish_scope(
            branch_ref=branch_ref,
            staged_commits_table=staged_commits_table,
            scope_kind=scope_kind,
        )
        publish_selector = _selector_for_scope(publish_scope)
        publish_scope_descriptor = _scope_descriptor_from_selector(branch_ref, publish_selector)
        non_empty_validation_ref = ServerPlanRefId(f"{self.ref_id}_non_empty_admission")
        from l1000_schema.table_utils import get_table_name

        domain_source_keys_list: list[AdmissionStagedSourceKey] = []
        admission_base_table_names: set[str] = set()
        for model in self.domain.all_versioned_models():
            try:
                admission_base_table_names.add(str(get_table_name(model)))
            except AttributeError:
                continue
        admission_base_table_names.update(str(name) for name in (self.inline_touched_table_names or ()))
        admission_base_table_names.update(str(name) for name in (self.inline_deleted_table_names or ()))
        for domain_table_name in sorted(admission_base_table_names):
            domain_source_keys_list.append(
                AdmissionStagedSourceKey(
                    staged_table_name=str(
                        derive_versioned_table_names(
                            VersionedBaseTableName(domain_table_name),
                        ).staged,
                    ),
                    branch_scope_token=publish_selector._branch_scope_token,
                ),
            )
        domain_source_keys = tuple(domain_source_keys_list)
        lowered_admission_producers = tuple(
            replace(
                producer,
                physical_effect_ref=_lowered_commit_dependency_ref_for(
                    ctx,
                    producer.physical_effect_ref,
                ),
            )
            for producer in self.staged_admission_producers
        )
        admission_requirement = StagedAdmissionRequirement(
            requirement_ref=non_empty_validation_ref,
            epoch_id=self.publication_epoch_id,
            source_keys=tuple(
                dict.fromkeys(
                    (
                        *domain_source_keys,
                        *self.staged_admission_source_keys,
                        *(
                            AdmissionStagedSourceKey(
                                staged_table_name=producer.source_key.staged_table_name,
                                branch_scope_token=producer.source_key.branch_scope_token,
                            )
                            for producer in lowered_admission_producers
                        ),
                    ),
                ),
            ),
            staged_commit_ids=tuple(dict.fromkeys(publish_scope_descriptor.staged_commit_ids)),
            source_generation=self.publication_epoch.source_generation,
            allow_empty=self.allow_empty,
            allow_new_branch=True,
        )
        static_admission_proof = prove_static_staged_admission(
            admission_requirement,
            lowered_admission_producers,
            (),
        )
        sql_admission_proof = (
            None
            if static_admission_proof is not None
            else prove_sql_staged_admission(
                admission_requirement,
                lowered_admission_producers,
                (),
            )
        )
        effective_commit_dependencies = ctx._lowering_cache.pop(
            f"effective_commit_dependencies:{self.ref_id}",
            tuple(self.prepublish_dependencies),
        )
        admission_dependencies = _lowered_commit_dependency_refs(
            ctx,
            (ref_id for ref_id in effective_commit_dependencies if str(ref_id) != str(self.ref_id)),
        )
        if self.allow_empty:
            steps.append(
                StaticStagedAdmissionProofStep(
                    non_empty_validation_ref,
                    depends_on=admission_dependencies,
                ),
            )
        else:
            steps.append(
                ValidateCommitBranchAdmissionStep(
                    non_empty_validation_ref,
                    staged_commits_table=staged_commits_table,
                    scope=publish_scope,
                    admission=CommitBranchAdmission(
                        allow_empty=self.allow_empty,
                        is_new_branch=self.is_new_branch,
                    ),
                    requirement=admission_requirement,
                    producers=lowered_admission_producers,
                    sql_proof=sql_admission_proof,
                    depends_on=admission_dependencies,
                ),
            )
        correction = self._authoritative_correction
        if correction is not None:
            stream_connection_id_raw: str | None = None
            stream_staged_commit_ids = correction.staged_commit_ids
        elif self.explicit_staged_commit_ids:
            stream_connection_id_raw = None
            stream_staged_commit_ids = self._effective_staged_commit_ids()
        elif scope_kind == "connection_scoped":
            assert self.visibility_scope_value is not None
            stream_connection_id_raw = self.visibility_scope_value.unwrap_to_uuid_compatible_str()
            stream_staged_commit_ids = (self.inline_staged_commit_id,) if self.inline_staged_commit_id is not None else ()
        elif scope_kind == "inline":
            assert self.inline_staged_commit_id is not None
            stream_connection_id_raw = None
            stream_staged_commit_ids = (self.inline_staged_commit_id,)
        else:
            stream_connection_id_raw = None
            stream_staged_commit_ids = ()
        from l1000_schema.large_column import get_large_column_configs

        domain_has_staged_fields = any(get_large_column_configs(model_cls) for model_cls in domain.all_versioned_models())
        if domain_has_staged_fields:
            staged_field_validation_ref = ServerPlanRefId(f"{self.ref_id}_staged_fields_finalized")
            steps.append(
                ValidateStagedFieldStreamsFinalizedStep(
                    staged_field_validation_ref,
                    staged_commits_table,
                    branch_ref,
                    stream_connection_id_raw,
                    staged_commit_ids=stream_staged_commit_ids,
                    depends_on=frozenset({non_empty_validation_ref}),
                ),
            )
            non_empty_validation_ref = staged_field_validation_ref
        graph_auxiliary_enabled = domain_has_graph_models(domain) and not graph_constraints_suppressed
        from impl.common.l7245_versioned_backends.graph_aux_reconciliation import (
            collect_graph_auxiliary_reconciliation_table_sources,
        )

        incremental_tree_sources = collect_graph_auxiliary_reconciliation_table_sources(domain).tree_edge_tip_sources
        incremental_tree_auxiliary_enabled = bool(incremental_tree_sources)
        if graph_auxiliary_enabled:
            dangling_validation_authority: _DanglingValidationAuthority = "branch_tip"
        else:
            dangling_validation_authority = "sparse_revision"
        full_table_entries, _full_edge_base_table_names, _full_symmetric_entries = _commit_branch_domain_metadata(
            domain,
            include_generated_storage_columns=include_generated_storage_columns(ctx),
            publish_table_names=None,
        )
        all_publish_table_names = frozenset(table_name for table_name, _models, _sparse_cols, _tip_cols in full_table_entries)
        guardable_publish_table_names = frozenset(
            table_name
            for table_name in all_publish_table_names
            if ctx.cached_table_exists(SqlTableName(derive_versioned_table_names(VersionedBaseTableName(str(table_name))).staged))
            is not False
        )
        publish_table_names = (
            self.inline_touched_table_names
            if scope_kind == "inline" and self.inline_touched_table_names is not None
            else (
                frozenset(
                    table_name
                    for table_name in (self.speculative_publish_table_names or frozenset())
                    if table_name in all_publish_table_names
                )
                if scope_kind != "inline" and self.speculative_publish_table_names is not None
                else None
            )
        )
        speculative_guard_ref: ServerPlanRefId | None = None
        commit_metadata_dependencies: frozenset[ServerPlanRefId] = frozenset(
            {non_empty_validation_ref, ServerPlanRefId(commit_ctx_ref)},
        )
        capture_refs: set[ServerPlanRefId] = set()
        if ctx.planning_catalog is not None and graph_auxiliary_enabled:
            import hashlib
            from impl.common.l2070_server_plan.steps.publication_selection_steps import CapturePublicationRowsStep
            from l2070_batching.publication_selection import PublicationSelectionContract, PublicationSelectionIdentity
            from l2070_batching.planning_catalog_contract import PlanningCatalogContract

            capture_selector = _selector_for_scope(publish_scope)
            for table_name, _models, _sparse, _tip in full_table_entries:
                if table_name not in guardable_publish_table_names:
                    continue
                source = SqlTableName(derive_versioned_table_names(VersionedBaseTableName(str(table_name))).staged)
                captured_columns = tuple(sorted(ctx.schema_column_cache.get(str(source), ())))
                if "sys_fts_content_hash" in _sparse:
                    captured_columns = (*captured_columns, "sys_fts_content_hash")
                if not captured_columns:
                    continue
                staged_model = get_model_for_table(source)
                if not capture_refs and scope_kind != "inline":
                    capture_lock_ref = ServerPlanRefId(f"{self.ref_id}_capture_selector_lock")
                    steps.append(
                        LockSelectedStagedCommitsStep(
                            capture_lock_ref,
                            staged_commits_table=staged_commits_table,
                            scope=publish_scope,
                            depends_on=commit_metadata_dependencies,
                        )
                    )
                    commit_metadata_dependencies = frozenset({capture_lock_ref})
                capture_ref = ServerPlanRefId(f"{self.ref_id}_capture_{table_name}")
                selection = PublicationSelectionContract(
                    identity=PublicationSelectionIdentity(
                        owner_ref=self.ref_id,
                        source_table=source,
                        scope=_scope_descriptor_from_selector(branch_ref, capture_selector),
                        partition_columns=(SqlColumnName("branch_id"), SqlColumnName("sys_id")),
                        physical_schema=SchemaFingerprintHash(
                            str(
                                PlanningCatalogContract.from_models(
                                    (*_models, staged_model) if staged_model is not None else _models,
                                ).digest()
                            )
                        ),
                    ),
                    columns=frozenset(
                        SqlColumnName(column)
                        for column in (
                            *captured_columns,
                            "branch_id",
                            "sys_id",
                            "sys_staged_commit_id",
                            "sys_deleted",
                        )
                    ),
                )
                correction_source = None
                if self._authoritative_correction is not None:
                    original_scope = PublishScopeDescriptor(
                        kind="explicit" if scope_kind == "inline" else "branch",
                        branch_scope_token=self.branch_scope_token,
                        staged_commits_table=None if scope_kind == "inline" else str(staged_commits_table),
                        connection_id_raw=(
                            self.visibility_scope_value.unwrap_to_uuid_compatible_str()
                            if scope_kind == "connection_scoped" and self.visibility_scope_value is not None
                            else None
                        ),
                        staged_commit_ids=((str(self.inline_staged_commit_id),) if self.inline_staged_commit_id is not None else ()),
                    )
                    correction_source = selection.identity.model_copy(update={"scope": original_scope})
                capture_name = SqlTableName("nera_pub_" + hashlib.sha256(selection.identity.model_dump_json().encode()).hexdigest()[:40])
                steps.append(
                    CapturePublicationRowsStep(
                        capture_ref,
                        selection=selection,
                        temporary_table=capture_name,
                        branch_ref=branch_ref,
                        selector=capture_selector,
                        depends_on=commit_metadata_dependencies,
                        correction_source=correction_source,
                    )
                )
                capture_refs.add(capture_ref)
            commit_metadata_dependencies |= frozenset(capture_refs)

        effective_speculative_tables = frozenset(publish_table_names or ()) & guardable_publish_table_names
        effective_insert_only_tables = (
            self.speculative_insert_only_table_names & effective_speculative_tables & guardable_publish_table_names
        )
        identity_insert_only_tables = effective_insert_only_tables
        effective_insert_only_tables -= frozenset(source.edge_table_name for source in incremental_tree_sources)
        # The first request validates operation shape. Its selected metadata rows
        # remain locked, so the correction can retain insert-only specialization
        # without re-running a shape probe after each statement-local mutation.
        # The correction guard still rejects any omitted touched table.
        guard_insert_only_tables = effective_insert_only_tables if self._authoritative_correction is None else frozenset()
        speculation_requires_guard = bool(
            self.speculative_publish_table_names
            and (effective_speculative_tables != guardable_publish_table_names or guard_insert_only_tables)
        )
        if speculation_requires_guard:
            guard_dependencies = commit_metadata_dependencies
            if not capture_refs and self._authoritative_correction is None and scope_kind != "inline":
                # Inline staged rows were created by this transaction and are not
                # visible to competing discard or staging transactions. Broader
                # selectors lock committed metadata rows until correction finishes.
                selector_lock_ref = ServerPlanRefId(f"{self.ref_id}_speculative_selector_lock")
                steps.append(
                    LockSelectedStagedCommitsStep(
                        selector_lock_ref,
                        staged_commits_table=staged_commits_table,
                        scope=publish_scope,
                        depends_on=guard_dependencies,
                    ),
                )
                guard_dependencies = frozenset({selector_lock_ref})
            speculative_guard_ref = ServerPlanRefId(f"{self.ref_id}_speculative_publication")
            steps.append(
                SpeculativePublicationGuardStep(
                    speculative_guard_ref,
                    all_base_table_names=tuple(sorted(guardable_publish_table_names)),
                    speculative_base_table_names=tuple(sorted(effective_speculative_tables)),
                    speculative_insert_only_base_table_names=tuple(sorted(guard_insert_only_tables)),
                    branch_table_name=SqlTableName(get_table_name(domain.branch_model)),
                    branch_tip_column_name=SqlColumnName(
                        get_db_column_name(domain.branch_model, DynamicFieldName("tip_revision_sys_id")),
                    ),
                    branch_id_column_name=SqlColumnName(
                        get_db_column_name(domain.branch_model, DynamicFieldName("sys_id")),
                    ),
                    scope=publish_scope,
                    new_revision_id=new_revision_id,
                    depends_on=guard_dependencies,
                ),
            )
            commit_metadata_dependencies = frozenset({speculative_guard_ref})
        rev_meta = self.revision_metadata.values
        from l3200_metadata.schema_metadata_snapshot import (
            SchemaMetadataSnapshot,
            remember_revision_schema_metadata,
        )

        remember_revision_schema_metadata(
            new_revision_id,
            SchemaMetadataSnapshot(
                schema_hash=SchemaFingerprintHash(str(rev_meta.get("schema_hash") or "")),
                json_schema_epoch=int(rev_meta.get("json_schema_epoch") or 0),
            ),
        )
        idx = 0

        revision_table = SqlTableName(get_table_name(domain.revision_model))
        identity_tables = revision_identity_tables(ctx, domain)
        revision_creation_dependencies = commit_metadata_dependencies
        if self.ordered_parent_revision_ids is not None:
            reserve_revision_id_ref = ServerPlanRefId(f"{self.ref_id}_reserve_revision_id")
            validate_revision_id_ref = ServerPlanRefId(f"{self.ref_id}_validate_revision_id")
            steps.extend(
                (
                    ValidateRevisionIdAvailableStep(
                        validate_revision_id_ref,
                        revision_tables=identity_tables,
                        revision_ids=(new_revision_id,),
                        depends_on=commit_metadata_dependencies,
                    ),
                    InsertRevisionPhysicalKeyStep(
                        reserve_revision_id_ref,
                        new_revision_ref,
                        depends_on=frozenset({validate_revision_id_ref}),
                        strict=True,
                    ),
                ),
            )
            revision_creation_dependencies = frozenset({reserve_revision_id_ref})
            if self.ordered_parent_revision_ids:
                validate_parents_ref = ServerPlanRefId(f"{self.ref_id}_validate_parents")
                steps.append(
                    ValidateRevisionParentsExistStep(
                        validate_parents_ref,
                        revision_table=revision_table,
                        parent_revision_ids=self.ordered_parent_revision_ids,
                        depends_on=revision_creation_dependencies,
                    ),
                )
                revision_creation_dependencies = frozenset({validate_parents_ref})

        insert_revision_ref = ServerPlanRefId(f"{self.ref_id}_revision")
        steps.append(
            InsertRevisionStep(
                insert_revision_ref,
                revision_table_name=get_table_name(domain.revision_model),
                revision_model_cls=domain.revision_model,
                revision_id=new_revision_id,
                lazy_branch=branch_ref,
                session_id=(ServerRefs.scalar(self.revision_session_id) if self.revision_session_id is not None else self.session_id),
                config=_InsertRevisionConfig(
                    revision_metadata=dict(rev_meta),
                    legacy_parent_mode=(
                        _LegacyRevisionParentMode.NONE if self.ordered_parent_revision_ids == () else _LegacyRevisionParentMode.BRANCH_TIP
                    ),
                    depends_on=revision_creation_dependencies,
                    branch_table_name=SqlTableName(branch_table),
                    branch_id_column=SqlColumnName(get_db_column_name(domain.branch_model, DynamicFieldName("sys_id"))),
                    tip_revision_column=SqlColumnName(
                        get_db_column_name(domain.branch_model, DynamicFieldName("tip_revision_sys_id")),
                    ),
                    compact_id_from_physical_key=self.ordered_parent_revision_ids is not None,
                    revision_timestamp=self.revision_timestamp,
                ),
            ),
        )

        revision_parents_table = get_table_name(domain.revision_parent_model)
        index_table = get_table_name(domain.revision_branch_index_model)
        revision_parents_exists = ctx.cached_table_exists(SqlTableName(revision_parents_table))
        branch_index_exists = ctx.cached_table_exists(SqlTableName(index_table))
        metadata_tables_available = True
        branch_index_ref: ServerPlanRefId | None = None
        if revision_parents_exists is not branch_index_exists and (revision_parents_exists is False or branch_index_exists is False):
            msg = (
                "versioning metadata tables are partially unavailable: "
                f"{revision_parents_table}={revision_parents_exists}, {index_table}={branch_index_exists}"
            )
            raise RuntimeError(msg)
        if metadata_tables_available:
            revision_parent_ref = ServerPlanRefId(f"{self.ref_id}_rev_parent")
            parent_publication_ref = insert_revision_ref
            demote_anchor_ref = ServerPlanRefId(f"{self.ref_id}_demote_old_anchor")
            branch_index_ref = ServerPlanRefId(f"{self.ref_id}_branch_index")
            if self.ordered_parent_revision_ids is None:
                steps.append(
                    InsertRevisionParentStep(
                        revision_parent_ref,
                        revision_parents_table=SqlTableName(revision_parents_table),
                        revision_id=new_revision_ref,
                        lazy_branch=branch_ref,
                        branch_table_name=SqlTableName(branch_table),
                        branch_id_column=SqlColumnName(get_db_column_name(domain.branch_model, DynamicFieldName("sys_id"))),
                        tip_revision_column=SqlColumnName(
                            get_db_column_name(domain.branch_model, DynamicFieldName("tip_revision_sys_id")),
                        ),
                        depends_on=commit_metadata_dependencies | frozenset({insert_revision_ref}),
                    ),
                )
                parent_publication_ref = revision_parent_ref
            else:
                relationship_types = self.ordered_parent_relationship_types or tuple(
                    ParentType("commit" if ordinal == 0 else "merge") for ordinal in range(len(self.ordered_parent_revision_ids))
                )
                if len(relationship_types) != len(self.ordered_parent_revision_ids):
                    raise ValueError("Ordered parent relationship types must match the ordered parent revisions")
                parent_rows = tuple(
                    _RevisionParentRowSpec(
                        parent_revision_id=parent_revision_id,
                        relationship_type=relationship_types[ordinal],
                        ordinal=ordinal,
                    )
                    for ordinal, parent_revision_id in enumerate(self.ordered_parent_revision_ids)
                )
                parent_dependencies = frozenset({insert_revision_ref})
                for chunk_index, chunk_start in enumerate(
                    range(0, len(parent_rows), _ORDERED_PARENT_INSERT_BATCH_SIZE),
                ):
                    revision_parent_ref = ServerPlanRefId(f"{self.ref_id}_rev_parent_{chunk_index}")
                    steps.append(
                        UpsertRevisionParentsStep(
                            revision_parent_ref,
                            SqlTableName(revision_parents_table),
                            new_revision_ref,
                            config=_UpsertRevisionParentsConfig(
                                parent_rows=parent_rows[chunk_start : chunk_start + _ORDERED_PARENT_INSERT_BATCH_SIZE],
                                depends_on=parent_dependencies,
                            ),
                        ),
                    )
                    parent_dependencies = frozenset({revision_parent_ref})
                    parent_publication_ref = revision_parent_ref
            steps.append(
                DemoteOldBranchTipAnchorStep(
                    demote_anchor_ref,
                    index_table=SqlTableName(index_table),
                    lazy_branch=branch_ref,
                    config=_DemoteOldBranchTipAnchorConfig(
                        branch_table_name=SqlTableName(branch_table),
                        revision_parents_table_name=SqlTableName(revision_parents_table),
                        branch_id_column=SqlColumnName(get_db_column_name(domain.branch_model, DynamicFieldName("sys_id"))),
                        tip_revision_column=SqlColumnName(
                            get_db_column_name(domain.branch_model, DynamicFieldName("tip_revision_sys_id")),
                        ),
                        depends_on=commit_metadata_dependencies | frozenset({insert_revision_ref}),
                    ),
                ),
            )
            steps.append(
                UpsertRevisionBranchAnchorStep(
                    ref_id=branch_index_ref,
                    index_table=SqlTableName(index_table),
                    revision_id=new_revision_ref,
                    branch_ref=branch_ref,
                    config=_UpsertRevisionBranchAnchorConfig(
                        anchor_reason=RevisionAnchorReason.BRANCH_TIP,
                        anchor_depth=0,
                        depends_on=frozenset({parent_publication_ref, demote_anchor_ref}),
                    ),
                ),
            )

        (
            table_entries,
            edge_base_table_names,
            symmetric_entries,
        ) = _commit_branch_domain_metadata(
            domain,
            include_generated_storage_columns=include_generated_storage_columns(ctx),
            publish_table_names=publish_table_names,
        )
        table_models = {table_name: list(models_for_table) for table_name, models_for_table, _, _ in table_entries}
        symmetric_auto_create_by_table = {table_name: list(filters) for table_name, filters in symmetric_entries}

        validation_dependencies: set[ServerPlanRefId] = set(revision_creation_dependencies)
        publish_tail_refs: list[ServerPlanRefId] = []
        shared_version_key_dependency_ref: ServerPlanRefId | None = None

        column_metadata_by_table = {
            table_name: (list(sparse_data_cols), list(tip_data_cols))
            for table_name, _models_for_table, sparse_data_cols, tip_data_cols in table_entries
        }
        publish_planner_memory_budget_bytes = (
            ctx.commit_publish_planner_memory_budget_bytes
            if ctx.backend_profile.traits.versioned_staging_transport is VersionedStagingTransport.SAME_STATEMENT_RELATION
            else None
        )
        current_publish_batch_estimated_memory_bytes = 0
        publish_batch_index = 0
        graph_owner_tables = {
            route[0]
            for models_for_table in table_models.values()
            for model in models_for_table
            for route in getattr(model, "__nera_exact_graph_routes__", ())
            if isinstance(route, tuple) and len(route) in (2, 4) and isinstance(route[0], str)
        }
        remaining_table_items = list(table_models.items())
        table_items: list[tuple[str, list[type[Any]]]] = []
        remaining_table_names = {table_name for table_name, _models in remaining_table_items}
        while remaining_table_items:
            ready_items = [
                (table_name, models)
                for table_name, models in remaining_table_items
                if not any(
                    fk.is_versioned_target
                    and isinstance(fk.target_model, type)
                    and get_table_name(fk.target_model) in remaining_table_names
                    and get_table_name(fk.target_model) != table_name
                    for model in models
                    for fk in iter_model_fks(model)
                )
            ]
            if not ready_items:
                ready_items = [remaining_table_items[0]]
            ready_items.sort(key=lambda item: item[0] not in graph_owner_tables)
            ready_names = {table_name for table_name, _models in ready_items}
            table_items.extend(ready_items)
            remaining_table_items = [item for item in remaining_table_items if item[0] not in ready_names]
            remaining_table_names.difference_update(ready_names)
        from impl.common.l2070_server_plan.steps.barrier import BarrierStep

        from l3250_migrations.versioned_table_helpers import (
            VersionedTableType,
            get_auxiliary_table_name,
        )

        published_tail_by_table: dict[str, ServerPlanRefId] = {}
        deferred_staged_row_cleanup_specs: list[tuple[str, SqlTableName, tuple[str, ...] | None]] = []
        for table_name, models_for_table in table_items:
            table_model = models_for_table[0]
            staged_table = get_auxiliary_table_name(table_model, VersionedTableType.STAGED)
            sparse_table = get_auxiliary_table_name(table_model, VersionedTableType.SPARSE)
            tip_table = get_auxiliary_table_name(table_model, VersionedTableType.TIP)
            sparse_data_cols, tip_data_cols = column_metadata_by_table[table_name]
            staged_returning_cols = _staged_returning_columns_from_catalog(
                ctx.planning_catalog,
                staged_table,
            )
            tree_validation_type_filters = _commit_branch_tree_validation_type_filters(
                table_name=SqlTableName(table_name),
                models_for_table=tuple(models_for_table),
                backend_type=ctx.backend_type,
                tree_validation_transport=ctx.backend_profile.traits.tree_validation_transport,
                publish_scope_descriptor=publish_scope_descriptor,
                graph_constraints_suppressed=graph_constraints_suppressed,
            )
            is_tree_edge_table = bool(tree_validation_type_filters)
            is_graph_node_table = False
            for model in models_for_table:
                try:
                    if issubclass(model, GraphNode) and model is not GraphNode:
                        is_graph_node_table = True
                        break
                except TypeError:
                    continue
            prefix = _ref_id(f"{self.ref_id}_t{idx}")
            idx += 1
            symmetric_filters = symmetric_auto_create_by_table.get(table_name, [])
            unique_filters = list(dict.fromkeys(symmetric_filters))
            staged_cols_for_reciprocal = set(staged_returning_cols or ())
            sparse_model = get_model_for_table(SqlTableName(sparse_table))
            data_cols_for_reciprocal = [
                c
                for c in sparse_data_cols
                if staged_returning_cols is None or c in staged_cols_for_reciprocal
                if c not in {"branch_id", "sys_deleted"}
                if not _is_framework_physical_data_column(sparse_model, SqlColumnName(c))
            ]
            publish_initial_dependencies: frozenset[ServerPlanRefId] = frozenset(
                {*admission_dependencies, *validation_dependencies},
            )
            parent_publish_tail_refs: list[ServerPlanRefId] = []
            tip_fk_parent_visibility_tables: set[SqlTableName] = set()
            seen_parent_tail_refs: set[ServerPlanRefId] = set()
            for model in models_for_table:
                for fk in iter_model_fks(model):
                    if not fk.is_versioned_target or not isinstance(fk.target_model, type):
                        continue
                    parent_table_name = get_table_name(fk.target_model)
                    if parent_table_name == table_name:
                        continue
                    tip_fk_parent_visibility_tables.add(
                        SqlTableName(derive_versioned_table_names(VersionedBaseTableName(str(parent_table_name))).tip)
                    )
                    parent_tail_ref = published_tail_by_table.get(parent_table_name)
                    if parent_tail_ref is None or parent_tail_ref in seen_parent_tail_refs:
                        continue
                    seen_parent_tail_refs.add(parent_tail_ref)
                    parent_publish_tail_refs.append(parent_tail_ref)
            if parent_publish_tail_refs:
                fk_visibility_barrier_ref = ServerPlanRefId(f"{self.ref_id}_t{idx}_fk_visibility_barrier")
                steps.append(
                    BarrierStep(
                        fk_visibility_barrier_ref,
                        depends_on=frozenset(parent_publish_tail_refs),
                    ),
                )
                publish_initial_dependencies = publish_initial_dependencies | frozenset({fk_visibility_barrier_ref})

            def _build_before_close_steps(
                dependencies: frozenset[ServerPlanRefId],
                affected_rows_ref: ServerPlanRefId | None,
                *,
                prefix_value: str = prefix,
                tree_edge_table_value: str = table_name,
                staged_table_value: str = staged_table,
                sparse_table_value: str = sparse_table,
                data_cols_for_reciprocal_value: list[str] = data_cols_for_reciprocal,
                unique_filters_value: list[tuple[str, ...]] = unique_filters,
            ) -> Sequence[ServerPlanStep[Any]]:
                del affected_rows_ref
                from impl.common.l2070_server_plan.steps.barrier import BarrierStep

                current_dependencies = dependencies
                before_close_steps: list[ServerPlanStep[Any]] = []
                for type_filter in unique_filters_value:
                    filter_suffix = "__".join(type_filter) if type_filter else "all"
                    sym_ref = ServerPlanRefId(f"{prefix_value}_sym_auto_{filter_suffix}")
                    step = AutoCreateSymmetricReciprocalsInStagedStep(
                        sym_ref,
                        config=_AutoCreateSymmetricReciprocalsConfig(
                            edge_staged_table=SqlTableName(staged_table_value),
                            edge_sparse_table=SqlTableName(sparse_table_value),
                            branch_table=SqlTableName(branch_table),
                            data_columns=tuple(data_cols_for_reciprocal_value),
                            branch_ref=branch_ref,
                            publish_scope=publish_scope_descriptor,
                            type_name_filter=type_filter,
                            depends_on=current_dependencies,
                        ),
                    )
                    before_close_steps.append(step)
                    current_dependencies = frozenset({sym_ref})
                if before_close_steps:
                    barrier_ref = ServerPlanRefId(f"{prefix_value}_sym_auto_barrier")
                    before_close_steps.append(
                        BarrierStep(barrier_ref, depends_on=current_dependencies),
                    )
                    current_dependencies = frozenset({barrier_ref})
                return before_close_steps

            def _build_after_insert_steps(
                dependencies: frozenset[ServerPlanRefId],
                affected_rows_ref: ServerPlanRefId | None,
                *,
                prefix_value: str = prefix,
                tree_edge_table_value: str = table_name,
                staged_table_value: str = staged_table,
                tree_type_filters_value: tuple[tuple[str, ...], ...] = tree_validation_type_filters,
                build_tree_validation: bool = is_tree_edge_table,
            ) -> Sequence[ServerPlanStep[Any]]:
                if build_tree_validation:
                    validation_steps: list[ServerPlanStep[Any]] = []
                    current_dependencies = dependencies
                    for filter_index, type_name_filter in enumerate(tree_type_filters_value):
                        validate_tree_ref = ServerPlanRefId(
                            f"{prefix_value}_validate_tree_cycle_{filter_index}",
                        )
                        current_validation_steps = tuple(
                            require_versioned_lowering_provider(
                                ctx,
                            ).build_tree_publish_validation_steps(
                                TreePublishValidationRequest(
                                    ref_id=validate_tree_ref,
                                    edge_tip_table=SqlTableName(
                                        derive_versioned_table_names(VersionedBaseTableName(str(tree_edge_table_value))).tip
                                    ),
                                    edge_staged_table=SqlTableName(staged_table_value),
                                    edge_base_table=SqlTableName(tree_edge_table_value),
                                    lazy_branch=branch_ref,
                                    publish_scope=publish_scope_descriptor,
                                    depends_on=current_dependencies,
                                    type_name_filter=type_name_filter,
                                    affected_rows_ref=affected_rows_ref,
                                ),
                            ),
                        )
                        validation_steps.extend(current_validation_steps)
                        if not current_validation_steps:
                            msg = f"No dirty-tree validator is available for {tree_edge_table_value!r}"
                            raise RuntimeError(msg)
                        current_dependencies = frozenset({current_validation_steps[-1].ref_id})
                        from l9600_graphs.incremental_validation_models import tree_state_scope_key

                        reset_state_ref = ServerPlanRefId(
                            f"{prefix_value}_reset_deleted_tree_state_{filter_index}",
                        )
                        validation_steps.append(
                            _GraphAuxiliarySqlStep(
                                reset_state_ref,
                                branch_ref=branch_ref,
                                grammar_factory=_GraphAuxiliaryGrammarFactory(
                                    kind="reset_deleted_tree_state",
                                    edge_table_name=tree_state_scope_key(
                                        tree_edge_table_value,
                                        type_name_filter,
                                    ),
                                    staged_table=SqlTableName(staged_table_value),
                                    selector=publish_selector,
                                    type_name_filter=type_name_filter,
                                ),
                                tables_read=frozenset({SqlTableName(staged_table_value)}),
                                tables_written=frozenset({SqlTableName("sys_contains_tree_state_tip")}),
                                depends_on=current_dependencies,
                            ),
                        )
                        current_dependencies = frozenset({reset_state_ref})
                    return tuple(validation_steps)
                return ()

            def _build_visible_node_aux_steps(
                dependencies: frozenset[ServerPlanRefId],
                affected_rows_ref: ServerPlanRefId | None,
                *,
                prefix_value: str = prefix,
                staged_table_value: str = staged_table,
                tip_table_value: str = tip_table,
                build_visible_aux: bool = is_graph_node_table,
            ) -> Sequence[ServerPlanStep[Any]]:
                if not build_visible_aux:
                    return ()
                delete_ref = ServerPlanRefId(f"{prefix_value}_visible_nodes_delete")
                insert_ref = ServerPlanRefId(f"{prefix_value}_visible_nodes_upsert")
                return (
                    _GraphAuxiliarySqlStep(
                        delete_ref,
                        branch_ref=branch_ref,
                        grammar_factory=_GraphAuxiliaryGrammarFactory(
                            kind="delete_visible_affected_nodes",
                            retained_tip_tables=tuple(
                                SqlTableName(derive_versioned_table_names(VersionedBaseTableName(str(name))).tip)
                                for name, models, _sparse_columns, _tip_columns in full_table_entries
                                if derive_versioned_table_names(VersionedBaseTableName(str(name))).tip != tip_table_value
                                and any(issubclass(model, GraphNode) and model is not GraphNode for model in models)
                            ),
                            staged_table=SqlTableName(staged_table_value),
                            selector=publish_selector,
                            affected_rows_ref=affected_rows_ref,
                        ),
                        tables_read=frozenset({SqlTableName(staged_table_value)}),
                        tables_written=frozenset({SqlTableName("sys_graph_visible_nodes_tip")}),
                        depends_on=dependencies,
                    ),
                    _GraphAuxiliarySqlStep(
                        insert_ref,
                        branch_ref=branch_ref,
                        grammar_factory=_GraphAuxiliaryGrammarFactory(
                            kind="insert_visible_from_staged_affected_nodes",
                            staged_table=SqlTableName(staged_table_value),
                            selector=publish_selector,
                            affected_rows_ref=affected_rows_ref,
                        ),
                        tables_read=frozenset({SqlTableName(staged_table_value)}),
                        tables_written=frozenset({SqlTableName("sys_graph_visible_nodes_tip")}),
                        depends_on=frozenset({delete_ref}),
                    ),
                )

            def _build_after_insert_steps_with_graph_aux(
                dependencies: frozenset[ServerPlanRefId],
                affected_rows_ref: ServerPlanRefId | None,
            ) -> Sequence[ServerPlanStep[Any]]:
                combined_steps: list[ServerPlanStep[Any]] = []
                current_dependencies = dependencies
                for step in _build_visible_node_aux_steps(current_dependencies, affected_rows_ref):
                    combined_steps.append(step)
                    current_dependencies = frozenset({step.ref_id})
                for step in _build_after_insert_steps(current_dependencies, affected_rows_ref):
                    combined_steps.append(step)
                    current_dependencies = frozenset({step.ref_id})
                return tuple(combined_steps)

            before_close_step_factory = _build_before_close_steps if unique_filters else None
            after_insert_step_factory = _build_after_insert_steps_with_graph_aux if is_tree_edge_table or is_graph_node_table else None
            commit_delta_graph_routes: list[ExactGraphRouteDescriptor] = []
            domain_graph_tables = {get_table_name(graph_definition.graph_type) for graph_definition in domain.graphs}
            commit_delta_discriminator_columns = (
                (SqlColumnName("type_name"),) if "type_name" in sparse_data_cols and len(models_for_table) > 1 else ()
            )
            for model in models_for_table:
                raw_routes = getattr(model, "__nera_exact_graph_routes__", ())
                if not isinstance(raw_routes, tuple):
                    raise TypeError("Exact graph notification routes must be a tuple")
                for raw_route in raw_routes:
                    if (
                        not isinstance(raw_route, tuple)
                        or len(raw_route) != 2
                        or not isinstance(raw_route[0], str)
                        or raw_route[1] not in ("node", "edge")
                    ):
                        raise TypeError("Exact graph notification route must contain graph name and object kind")
                    if raw_route[0] not in domain_graph_tables:
                        continue
                    object_kind: Literal["node", "edge"] = raw_route[1]
                    descriptor = ExactGraphRouteDescriptor(
                        graph_table=SqlTableName(raw_route[0]),
                        object_kind=object_kind,
                        object_table=SqlTableName(table_name),
                        model_type_name=model.__name__,
                        type_discriminator_column=(SqlColumnName("type_name") if commit_delta_discriminator_columns else None),
                        type_discriminator_value=(model.__name__ if commit_delta_discriminator_columns else None),
                    )
                    if descriptor not in commit_delta_graph_routes:
                        commit_delta_graph_routes.append(descriptor)

            commit_delta_step_builder: CommitDeltaStepBuilder | None = None
            from l5000_subscriptions.cross_process import cross_process_runtime_active
            from l5000_subscriptions.dispatcher import has_local_committed_subscriptions

            local_commit_subscriptions = any(has_local_committed_subscriptions(model_cls) for model_cls in models_for_table)
            durable_notification_table_state = ctx.cached_table_exists(SqlTableName("sys_notifications"))
            durable_commit_without_catalog_proof = cross_process_runtime_active() or any(
                getattr(model, "__subscription_notifications__", None) is True for model in models_for_table
            )
            durable_commit_publication = (
                durable_notification_table_state is True and (local_commit_subscriptions or durable_commit_without_catalog_proof)
            ) or (durable_notification_table_state is None and durable_commit_without_catalog_proof)
            if (
                not table_name.startswith("sys_")
                and (durable_commit_publication or local_commit_subscriptions)
                and any(getattr(model, "__subscription_notifications__", True) is not False for model in models_for_table)
            ):
                from impl.common.l2070_server_plan.steps.write_side_effect_intents import subscription_writer_steps

                local_writer_steps, local_writer_ref = (
                    subscription_writer_steps(ctx, ServerPlanRefId(f"{prefix}_commit_local_delta"))
                    if local_commit_subscriptions
                    else ([], None)
                )

                @dataclass(frozen=True, slots=True)
                class _CommitNotificationStepBuilder:
                    prefix_value: str
                    model_classes: tuple[type[Any], ...]
                    publish_durable: bool
                    publish_local: bool
                    writer_steps: tuple[ServerPlanStep[Any], ...]
                    writer_ref: ServerPlanRefId | None

                    def build(self, source: VersionedCommitDeltaSource) -> Sequence[ServerPlanStep[Any]]:
                        publication_ref = ServerPlanRefId(f"{self.prefix_value}_commit_notifications")
                        steps: list[ServerPlanStep[Any]] = list(self.writer_steps)
                        local_dependencies: frozenset[ServerPlanRefId] = frozenset()
                        if self.publish_durable:
                            steps.append(PublishVersionedCommitNotificationsStep(publication_ref, source=source))
                            local_dependencies = frozenset({publication_ref})
                        if self.publish_local:
                            steps.append(
                                SelectVersionedCommitDeltaRowsStep(
                                    ServerPlanRefId(f"{self.prefix_value}_commit_local_delta"),
                                    source=source,
                                    depends_on=local_dependencies,
                                    local_model_classes=self.model_classes,
                                    writer_ref=self.writer_ref,
                                ),
                            )
                        return tuple(steps)

                commit_delta_step_builder = _CommitNotificationStepBuilder(
                    prefix_value=prefix,
                    model_classes=tuple(models_for_table),
                    publish_durable=durable_commit_publication,
                    publish_local=local_commit_subscriptions,
                    writer_steps=tuple(local_writer_steps),
                    writer_ref=local_writer_ref,
                )

            branch_dependencies = tuple(sorted(branch_ref.dependencies()))
            affected_rows_branch_source_ref = (
                ServerPlanRefId(f"{str(branch_dependencies[0]).partition('.')[0]}_branch_row")
                if (
                    ctx.backend_profile.traits.versioned_staging_transport is VersionedStagingTransport.ORDERED_RELATION
                    and len(branch_dependencies) == 1
                    and str(branch_dependencies[0]).startswith("step_")
                )
                else None
            )
            publish_steps = list(
                build_sparse_publish_steps(
                    ref_id=prefix,
                    scope=publish_scope,
                    new_revision_id=new_revision_ref,
                    sparse_table_name=SqlTableName(sparse_table),
                    staged_table_name=SqlTableName(staged_table),
                    tip_table_name=SqlTableName(tip_table),
                    publication_model_cls=models_for_table[0] if models_for_table else None,
                    publication_table_name=SqlTableName(table_name),
                    sparse_data_columns=sparse_data_cols,
                    tip_data_columns=tip_data_cols,
                    log_table_name=_log_table_name_from_catalog(
                        ctx.planning_catalog,
                        SqlTableName(table_name),
                        physically_present=(
                            ctx.table_exists_in_cache(logged_table_name(SqlTableName(table_name)))
                            if ctx.table_exists_in_cache is not None
                            else None
                        ),
                    ),
                    staged_returning_columns=staged_returning_cols,
                    initial_dependencies=publish_initial_dependencies,
                    before_close_step_factory=before_close_step_factory,
                    after_insert_step_factory=after_insert_step_factory,
                    commit_delta_step_builder=commit_delta_step_builder,
                    commit_delta_type_discriminator_columns=commit_delta_discriminator_columns,
                    commit_delta_graph_routes=commit_delta_graph_routes,
                    commit_delta_staged_cleanup_boundary=ServerPlanRefId(f"{prefix}_delete_staged"),
                    log_depends_on_publish_chain=True,
                    materialize_tip=self.materialize_tip,
                    collect_deleted_count=not self.allow_empty,
                    include_delete_staged=False,
                    enable_postgres_shared_rowset=(
                        ctx.backend_profile.traits.versioned_staging_transport is VersionedStagingTransport.SAME_STATEMENT_RELATION
                    ),
                    version_key_dependency_ref=shared_version_key_dependency_ref,
                    speculative_insert_only=(
                        ctx.backend_profile.traits.versioned_staging_transport is VersionedStagingTransport.SAME_STATEMENT_RELATION
                        and table_name in self.speculative_insert_only_table_names
                    ),
                    tip_fk_parent_tables_requiring_prior_visibility=frozenset(tip_fk_parent_visibility_tables),
                    versioning_domain=domain,
                    affected_rows_sql_transport=(
                        ctx.backend_profile.traits.versioned_staging_transport is not VersionedStagingTransport.NONE
                    ),
                    affected_rows_branch_source_ref=affected_rows_branch_source_ref,
                ),
            )
            deferred_staged_row_cleanup_specs.append((prefix, SqlTableName(staged_table), staged_returning_cols))
            if shared_version_key_dependency_ref is None:
                for step in publish_steps:
                    physical_key_ref = step.revision_physical_key_publication_ref()
                    if physical_key_ref is not None:
                        shared_version_key_dependency_ref = physical_key_ref
                        break
            table_estimated_memory_bytes = _estimate_commit_publish_planner_memory_bytes(
                publish_steps,
                sparse_data_cols=sparse_data_cols,
                tip_data_cols=tip_data_cols,
                staged_returning_cols=staged_returning_cols,
                unique_filters=unique_filters,
                tree_validation_type_filters=tree_validation_type_filters,
            )
            if publish_planner_memory_budget_bytes is not None and table_estimated_memory_bytes > publish_planner_memory_budget_bytes:
                bounded_publish_steps: list[ServerPlanStep[Any]] = []
                current_table_segment_bytes = 0
                for publish_step in publish_steps:
                    step_estimated_memory_bytes = _estimate_commit_publish_planner_memory_bytes(
                        (publish_step,),
                        sparse_data_cols=sparse_data_cols,
                        tip_data_cols=tip_data_cols,
                        staged_returning_cols=staged_returning_cols,
                        unique_filters=unique_filters,
                        tree_validation_type_filters=tree_validation_type_filters,
                    )
                    if step_estimated_memory_bytes > publish_planner_memory_budget_bytes:
                        raise CommitPlanningBudgetExceededError(
                            exceeded_dimensions={
                                PhysicalLimit.ESTIMATED_PLANNER_MEMORY_BYTES: (
                                    step_estimated_memory_bytes,
                                    publish_planner_memory_budget_bytes,
                                ),
                            },
                        )
                    if (
                        current_table_segment_bytes > 0
                        and current_table_segment_bytes + step_estimated_memory_bytes > publish_planner_memory_budget_bytes
                    ):
                        publish_batch_index += 1
                        bounded_publish_steps.append(
                            BarrierStep(
                                ServerPlanRefId(
                                    f"{self.ref_id}_publish_batch_{publish_batch_index}",
                                ),
                                depends_on=frozenset({bounded_publish_steps[-1].ref_id}),
                                requires_prior_boundary=True,
                                commit_fallback_reason=CommitFallbackReason.PLANNER_MEMORY_POLICY,
                            ),
                        )
                        current_table_segment_bytes = 0
                    bounded_publish_steps.append(publish_step)
                    current_table_segment_bytes += step_estimated_memory_bytes
                publish_steps = bounded_publish_steps
                table_estimated_memory_bytes = current_table_segment_bytes
            if publish_planner_memory_budget_bytes is not None:
                if (
                    current_publish_batch_estimated_memory_bytes > 0
                    and current_publish_batch_estimated_memory_bytes + table_estimated_memory_bytes > publish_planner_memory_budget_bytes
                ):
                    publish_batch_index += 1
                    steps.append(
                        BarrierStep(
                            ServerPlanRefId(
                                f"{self.ref_id}_publish_batch_{publish_batch_index}",
                            ),
                            depends_on=frozenset({publish_tail_refs[-1]}),
                            requires_prior_boundary=True,
                            commit_fallback_reason=CommitFallbackReason.PLANNER_MEMORY_POLICY,
                        ),
                    )
                    current_publish_batch_estimated_memory_bytes = 0
            steps.extend(publish_steps)
            publish_tail_ref = ServerPlanRefId(publish_steps[-1].ref_id)
            published_tail_by_table[table_name] = publish_tail_ref
            publish_tail_refs.append(publish_tail_ref)
            current_publish_batch_estimated_memory_bytes += table_estimated_memory_bytes

        for publish_tail_ref in publish_tail_refs:
            validation_dependencies.add(publish_tail_ref)

        embedding_finalize_refs: set[ServerPlanRefId] = set()
        embedding_correction_steps: list[ServerPlanStep[Any]] = []
        try:
            from impl.common.l2070_server_plan.embedding_plan_helpers import _query_spec
            from impl.common.l2070_server_plan.steps.query_update import (
                QueryUpdateStep,
                _QueryUpdateStepConfig,
            )
            from l1000_schema.typed_field import field
            from l5200_vector_index.content_addressable_models import (
                EmbeddingRef,
                get_embedding_classes_for_strategy,
            )
            from l5200_vector_index.hnsw_models import (
                create_hnsw_content_edge_class,
                create_hnsw_content_node_class,
                create_hnsw_edge_class,
                create_hnsw_metadata_class,
                create_hnsw_node_class,
            )
            from l5200_vector_index.vector_config import get_vector_indexes
            from vector_types import ContentStoreStrategy

            auxiliary_finalize_keys: set[tuple[str, str | None]] = set()
            ordered_models_for_aux = topological_sort_versioned_models(domain.all_versioned_models())
            for model in ordered_models_for_aux:
                try:
                    source_table_name = get_table_name(model)
                except AttributeError:
                    continue
                if publish_table_names is not None and source_table_name not in publish_table_names:
                    continue
                vector_indexes = get_vector_indexes(cast(type[DatabaseObjectRow[SysId]], model))
                if not vector_indexes:
                    continue

                all_revisions_indexes = {
                    index_name: config for index_name, config in vector_indexes.items() if config.indexes_all_revisions
                }
                all_revisions_index_names = tuple(all_revisions_indexes)
                ref_models_by_table: dict[str, tuple[type[EmbeddingRef], set[str]]] = {}
                for index_name, index_config in all_revisions_indexes.items():
                    ref_models: list[type[EmbeddingRef]]
                    if index_config.content_store_strategy is ContentStoreStrategy.PER_MODEL:
                        from impl.common.l2070_server_plan.embedding_store_scope import (
                            owned_per_model_embedding_storage,
                        )

                        ref_models = [
                            ref_model
                            for _, _, ref_model in owned_per_model_embedding_storage(
                                ctx.planning_catalog,
                            )
                        ]
                    else:
                        _vector_model, ref_model = get_embedding_classes_for_strategy(
                            index_config.content_store_strategy,
                            source_table_name=source_table_name,
                            field_name=index_name,
                        )
                        ref_models = [ref_model]
                    for ref_model in ref_models:
                        ref_table_name = str(get_table_name(ref_model))
                        existing = ref_models_by_table.get(ref_table_name)
                        if existing is None:
                            ref_models_by_table[ref_table_name] = (ref_model, {index_name})
                        else:
                            existing[1].add(index_name)
                for ref_table_name, (ref_model, index_names) in ref_models_by_table.items():
                    ref_key = (ref_table_name, source_table_name)
                    if ref_key in auxiliary_finalize_keys:
                        continue
                    ref_branch_matches = cast(
                        "Expression[bool, DatabaseObjectRow[SysId]]",
                        field(ref_model.branch_id) == branch_ref,
                    )
                    ref_source_table_matches = cast(
                        "Expression[bool, DatabaseObjectRow[SysId]]",
                        field(ref_model.source_table) == source_table_name,
                    )
                    ref_revision_is_null = cast(
                        "Expression[bool, DatabaseObjectRow[SysId]]",
                        field(ref_model.revision_id).is_null(),
                    )
                    ref_revision_is_new = cast(
                        "Expression[bool, DatabaseObjectRow[SysId]]",
                        field(ref_model.revision_id) == new_revision_id,
                    )
                    ref_field_matches = cast(
                        "Expression[bool, DatabaseObjectRow[SysId]]",
                        field(ref_model.field_name).is_in(tuple(sorted(index_names))),
                    )
                    from l1000_schema.typed_field import field as typed_field
                    from l2060_query_builder.query_contracts import JoinClause

                    auxiliary_finalize_keys.add(ref_key)
                    sparse_model = get_model_for_table(
                        SqlTableName(derive_versioned_table_names(VersionedBaseTableName(str(source_table_name))).sparse)
                    )
                    if sparse_model is None:
                        continue
                    source_id_matches = typed_field(ref_model.source_id) == typed_field(sparse_model.sys_id)
                    source_branch_matches = typed_field(ref_model.branch_id) == typed_field(sparse_model.branch_id)
                    source_is_current = typed_field(sparse_model.valid_to_revision_id).is_null()
                    source_join = JoinClause(
                        target_model=sparse_model,
                        on_left=typed_field(ref_model.branch_id),
                        on_right=typed_field(sparse_model.branch_id),
                        join_type="INNER",
                    )
                    ref_expr: Expression[bool, DatabaseObjectRow[SysId]] = (
                        ref_source_table_matches
                        & ref_branch_matches
                        & ref_revision_is_null
                        & ref_field_matches
                        & source_id_matches
                        & source_branch_matches
                        & source_is_current
                    )
                    ref_finalize = ServerPlanRefId(
                        f"{self.ref_id}_{source_table_name}_{ref_table_name}_embedding_refs_finalize",
                    )
                    pre_tip_ref_updates: dict[str, object] = {"revision_id": new_revision_id}
                    steps.append(
                        QueryUpdateStep(
                            ref_finalize,
                            ref_model,
                            _QueryUpdateStepConfig(
                                query_spec=replace(
                                    _query_spec(ref_model, ref_expr),
                                    joins=[source_join],
                                ),
                                updates=pre_tip_ref_updates,
                                after_refs=frozenset(ServerPlanRefId(ref_id) for ref_id in validation_dependencies),
                            ),
                        ),
                    )
                    validation_dependencies.add(ref_finalize)
                    ref_revision_correct = ServerPlanRefId(
                        f"{self.ref_id}_{source_table_name}_{ref_table_name}_embedding_refs_revision_correct",
                    )
                    ref_branch_is_not_null = typed_field(ref_model.branch_id).is_not_null()
                    ref_correction_expr = (
                        ref_source_table_matches
                        & ref_branch_is_not_null
                        & ref_revision_is_new
                        & ref_field_matches
                        & source_id_matches
                        & source_branch_matches
                        & source_is_current
                    )
                    ref_query_spec = replace(
                        _query_spec(ref_model, ref_correction_expr),
                        joins=[source_join],
                    )
                    embedding_correction_steps.append(
                        QueryUpdateStep(
                            ref_revision_correct,
                            ref_model,
                            _QueryUpdateStepConfig(
                                query_spec=ref_query_spec,
                                updates={
                                    "branch_id": None,
                                    "revision_id": typed_field(sparse_model.valid_from_revision_id),
                                },
                                after_refs=frozenset({*validation_dependencies, update_tip_ref}),
                            ),
                        ),
                    )
                    embedding_finalize_refs.add(ref_revision_correct)
                    from impl.common.l2070_server_plan.steps.snapshot_embedding_refs import (
                        PublishSnapshotEmbeddingRefsStep,
                    )
                    from l5200_vector_index.embedding_content_hash import (
                        get_embedding_source_fields,
                    )

                    for index_number, index_name in enumerate(sorted(index_names)):
                        carry_ref = ServerPlanRefId(f"{ref_revision_correct}.carry{index_number}")
                        source_columns = tuple(
                            str(get_db_column_name(model, DynamicFieldName(name)))
                            for name in get_embedding_source_fields(model, index_name)
                        )
                        embedding_correction_steps.append(
                            PublishSnapshotEmbeddingRefsStep(
                                carry_ref,
                                ref_table=SqlTableName(ref_table_name),
                                source_table=SqlTableName(source_table_name),
                                index_name=index_name,
                                sparse_table=SqlTableName(
                                    derive_versioned_table_names(VersionedBaseTableName(str(source_table_name))).sparse
                                ),
                                data_columns=source_columns,
                                source_branch=branch_ref,
                                target_branch=branch_ref,
                                source_revision=None,
                                base_revision=None,
                                target_revision=None,
                                result_revision=new_revision_ref,
                                revision_table=get_table_name(domain.revision_model),
                                revision_parents_table=get_table_name(domain.revision_parent_model),
                                after_ref=ref_revision_correct,
                                retire=False,
                            )
                        )
                        embedding_finalize_refs.add(carry_ref)

                auxiliary_models: list[tuple[type[Any], tuple[str, ...] | None]] = [(create_hnsw_metadata_class(source_table_name), None)]
                if all_revisions_index_names:
                    auxiliary_models.extend(
                        [
                            (
                                create_hnsw_content_node_class(source_table_name),
                                all_revisions_index_names,
                            ),
                            (
                                create_hnsw_content_edge_class(source_table_name),
                                all_revisions_index_names,
                            ),
                        ],
                    )
                for auxiliary_model, auxiliary_field_names in auxiliary_models:
                    model_fields = getattr(auxiliary_model, "model_fields", {})
                    if "branch_id" not in model_fields or "revision_id" not in model_fields:
                        continue
                    typed_auxiliary_model = cast("type[DatabaseObjectRow[SysId]]", auxiliary_model)
                    auxiliary_table_name = get_table_name(auxiliary_model)
                    auxiliary_key = (auxiliary_table_name, None)
                    if auxiliary_key in auxiliary_finalize_keys:
                        continue
                    auxiliary_branch_matches = cast(
                        "Expression[bool, DatabaseObjectRow[SysId]]",
                        field(typed_auxiliary_model.branch_id) == branch_ref,
                    )
                    auxiliary_revision_is_null = cast(
                        "Expression[bool, DatabaseObjectRow[SysId]]",
                        field(typed_auxiliary_model.revision_id).is_null(),
                    )
                    auxiliary_expr = auxiliary_branch_matches & auxiliary_revision_is_null
                    if "field_name" in model_fields and auxiliary_field_names:
                        auxiliary_field_matches = cast(
                            "Expression[bool, DatabaseObjectRow[SysId]]",
                            field(typed_auxiliary_model.field_name).is_in(tuple(list(auxiliary_field_names))),
                        )
                        auxiliary_expr = auxiliary_expr & auxiliary_field_matches
                    finalize_ref = ServerPlanRefId(f"{self.ref_id}_{auxiliary_table_name}_finalize")
                    steps.append(
                        QueryUpdateStep(
                            finalize_ref,
                            typed_auxiliary_model,
                            _QueryUpdateStepConfig(
                                query_spec=_query_spec(typed_auxiliary_model, auxiliary_expr),
                                updates={"branch_id": None, "revision_id": new_revision_id},
                                after_refs=frozenset(ServerPlanRefId(ref_id) for ref_id in validation_dependencies),
                            ),
                        ),
                    )
                    validation_dependencies.add(finalize_ref)
                    auxiliary_finalize_keys.add(auxiliary_key)
            steps.extend(embedding_correction_steps)
        except ImportError as exc:
            msg = "Vector auxiliary finalization dependencies are unavailable"
            raise RuntimeError(msg) from exc

        registry = RippleRegistry.get_instance()
        connection_batch_tables = (
            "sys_ripple_connection_batch_candidates",
            "sys_ripple_connection_batches",
            "sys_ripple_connection_batch_items",
        )
        connection_batch_tables_available = all(
            ctx.cached_table_exists(SqlTableName(table_name)) is not False for table_name in connection_batch_tables
        )
        if registry.has_connection_triggers_created() and connection_batch_tables_available:
            connection_finalize_dependencies = set(validation_dependencies)
            for connection_trigger in registry.get_pending_connection_triggers():
                if publish_table_names is not None:
                    trigger_table_names = {
                        get_table_name(connection_trigger.connected_type),
                        get_table_name(connection_trigger.primary_type),
                    }
                    if trigger_table_names.isdisjoint(publish_table_names):
                        continue
                finalize_ref = ServerPlanRefId(
                    f"{self.ref_id}_{connection_trigger.handler_id}_conn_batches",
                )
                steps.append(
                    FinalizeConnectionRippleBatchesStep(
                        finalize_ref,
                        branch_id=branch_ref,
                        revision_id=new_revision_ref,
                        selector=publish_selector,
                        config=_FinalizeRippleBatchesConfig(
                            domain_name=domain.__name__,
                            handler_id=connection_trigger.handler_id,
                            connection_role=connection_trigger.connection_role.value,
                            is_edge_primary=connection_trigger.is_edge_primary,
                        ),
                        connected_type=connection_trigger.connected_type,
                        primary_type=connection_trigger.primary_type,
                        trigger_where=connection_trigger.trigger_where,
                        connected_where=connection_trigger.connected_where,
                        depends_on=frozenset(validation_dependencies),
                    ),
                )
                items_ref = ServerPlanRefId(f"{self.ref_id}_{connection_trigger.handler_id}_conn_items")
                steps.append(
                    FinalizeConnectionRippleItemsStep(
                        items_ref,
                        branch_id=branch_ref,
                        revision_id=new_revision_ref,
                        selector=publish_selector,
                        config=_FinalizeRippleItemsConfig(
                            handler_id=connection_trigger.handler_id,
                            connection_role=connection_trigger.connection_role.value,
                            is_edge_primary=connection_trigger.is_edge_primary,
                        ),
                        connected_type=connection_trigger.connected_type,
                        primary_type=connection_trigger.primary_type,
                        trigger_where=connection_trigger.trigger_where,
                        depends_on=frozenset({finalize_ref}),
                    ),
                )
                queue_ref = ServerPlanRefId(f"{self.ref_id}_{connection_trigger.handler_id}_conn_queue")
                steps.append(
                    EnqueueConnectionRippleBatchesStep(
                        queue_ref,
                        revision_id=new_revision_ref,
                        config=_RippleHandlerConfig(
                            handler_id=connection_trigger.handler_id,
                        ),
                        depends_on=frozenset({items_ref}),
                    ),
                )
                cleanup_candidates_ref = ServerPlanRefId(
                    f"{self.ref_id}_{connection_trigger.handler_id}_conn_cleanup",
                )
                steps.append(
                    CleanupConnectionRippleCandidatesStep(
                        cleanup_candidates_ref,
                        selector=publish_selector,
                        config=_RippleHandlerConfig(
                            handler_id=connection_trigger.handler_id,
                        ),
                        depends_on=frozenset({queue_ref}),
                    ),
                )
                connection_finalize_dependencies.add(cleanup_candidates_ref)
            validation_dependencies = connection_finalize_dependencies

        update_tip_ref = self._validation_anchor
        validation_depends_on = frozenset({update_tip_ref, *embedding_finalize_refs})

        validation_ref = ServerPlanRefId(f"{self.ref_id}_edge_constraints")
        edge_validation_condition_ref: ServerPlanRefId | None = None
        if scope_kind != "inline" and not graph_auxiliary_enabled:
            edge_staged_table_names = tuple(
                derive_versioned_table_names(VersionedBaseTableName(str(table_name))).staged for table_name in edge_base_table_names
            )
            node_staged_table_names = tuple(
                derive_versioned_table_names(VersionedBaseTableName(str(table_name))).staged
                for table_name, models_for_table in table_models.items()
                if any(issubclass(model, GraphNode) and model is not GraphNode for model in models_for_table)
            )
            if edge_staged_table_names or node_staged_table_names:
                edge_validation_condition_ref = ServerPlanRefId(f"{self.ref_id}_edge_validation_needed")
                steps.append(
                    StagedEdgeValidationNeededStep(
                        edge_validation_condition_ref,
                        edge_staged_table_names=edge_staged_table_names,
                        node_staged_table_names=node_staged_table_names,
                        scope=publish_scope,
                    ),
                )
        update_tip_dependencies = {
            *validation_dependencies,
            ServerPlanRefId(commit_ctx_ref),
            non_empty_validation_ref,
        }
        if branch_index_ref is not None:
            update_tip_dependencies.add(branch_index_ref)
        steps.append(
            UpdateBranchTipStep(
                update_tip_ref,
                branch_ref,
                new_revision_ref,
                branch_table_name=SqlTableName(branch_table),
                branch_id_column=SqlColumnName(get_db_column_name(domain.branch_model, DynamicFieldName("sys_id"))),
                tip_revision_column=SqlColumnName(
                    get_db_column_name(domain.branch_model, DynamicFieldName("tip_revision_sys_id")),
                ),
                depends_on=frozenset(update_tip_dependencies),
            ),
        )
        validation_step = make_validate_edge_constraints_intent(
            validation_ref,
            config=_ValidateEdgeConstraintsConfig(
                domain=domain,
                lazy_branch=branch_ref,
                new_revision_id=new_revision_id,
                publish_scope=publish_scope_descriptor,
                publish_table_names=publish_table_names,
                deleted_table_names=self.inline_deleted_table_names or frozenset(),
                insert_only_table_names=identity_insert_only_tables,
                # Branch tips and visible-node tips are the publication authority. Sparse history
                # cannot prove current endpoint visibility (feeder reroll audit finding A15).
                dangling_validation_authority=dangling_validation_authority,
                edge_validation_condition_ref=edge_validation_condition_ref,
                depends_on=_dep_ids(validation_depends_on),
            ),
        )
        steps.append(validation_step)
        forwarded_validation_dependencies = validation_step.validation_completion_dependencies()
        cleanup_validation_dependencies = (
            forwarded_validation_dependencies if forwarded_validation_dependencies is not None else frozenset({validation_ref})
        )
        if incremental_tree_auxiliary_enabled and ctx.backend_profile.traits.incremental_tree_auxiliary_reconciliation:
            graph_auxiliary_boundary_ref = ServerPlanRefId(
                f"{self.ref_id}_reconcile_graph_auxiliary_boundary",
            )
            steps.append(
                BarrierStep(
                    graph_auxiliary_boundary_ref,
                    depends_on=frozenset({*cleanup_validation_dependencies, update_tip_ref}),
                    requires_prior_boundary=True,
                ),
            )
            graph_auxiliary_ref = ServerPlanRefId(f"{self.ref_id}_reconcile_graph_auxiliary")
            steps.append(
                ReconcileGraphAuxiliaryTablesStep(
                    graph_auxiliary_ref,
                    domain=domain,
                    branch_ref=branch_ref,
                    depends_on=frozenset({graph_auxiliary_boundary_ref}),
                    tree_table_names=frozenset(publish_table_names or ()),
                )
            )
            cleanup_validation_dependencies = frozenset({graph_auxiliary_ref})
        deferred_staged_row_cleanup_refs: set[ServerPlanRefId] = set()
        for cleanup_prefix, staged_table, staged_returning_cols in deferred_staged_row_cleanup_specs:
            delete_staged_ref = ServerPlanRefId(f"{cleanup_prefix}_delete_staged")
            cleanup_step = DeleteStagedForCommitStep(
                delete_staged_ref,
                staged_table,
                branch_ref,
                publish_selector,
                config=_DeleteStagedForCommitConfig(
                    returning_columns=staged_returning_cols,
                    collect_deleted_count=not self.allow_empty,
                ),
                depends_on=frozenset({update_tip_ref, *publish_tail_refs, *cleanup_validation_dependencies}),
            )
            cleanup_step.bind_staged_source_invalidations(
                tuple(
                    dict.fromkeys(
                        StagedSourceInvalidationEffect(
                            source_key=producer.source_key,
                            epoch_id=producer.epoch_id,
                            source_generation=producer.source_generation,
                            invalidated_by=delete_staged_ref,
                        )
                        for producer in lowered_admission_producers
                        if producer.source_key.staged_table_name == str(staged_table)
                    ),
                ),
            )
            steps.append(cleanup_step)
            deferred_staged_row_cleanup_refs.add(delete_staged_ref)
        for validation in self.precommit_validation_steps:
            steps.extend(validation.lower(ctx) if validation.level >= self.level else (validation,))
        cleanup_refs = self._append_cleanup_steps(
            steps=steps,
            branch_ref=branch_ref,
            staged_commits_table=staged_commits_table,
            cleanup_dependencies={
                validation_ref,
                *self.precommit_dependencies,
                *deferred_staged_row_cleanup_refs,
            },
            scope_kind=scope_kind,
        )
        project_dependencies = frozenset(
            {*cleanup_validation_dependencies, update_tip_ref, *cleanup_refs}
            | ({non_empty_validation_ref} if non_empty_validation_ref is not None else set())
            | ({speculative_guard_ref} if speculative_guard_ref is not None else set()),
        )
        steps.append(
            ProjectCommitBranchResultStep(
                ServerPlanRefId(self.ref_id),
                commit_ctx_ref=CommitBranchContextRefId(commit_ctx_ref),
                new_revision_id=self._new_revision_id,
                depends_on=_dep_ids(project_dependencies),
            ),
        )
        if speculative_guard_ref is not None:
            guard_step = next(step for step in steps if step.ref_id == speculative_guard_ref)
            guard_seen = False
            for step in steps:
                if step is guard_step:
                    guard_seen = True
                    continue
                if guard_seen and not step.is_read_only():
                    step.require_publication_gate(
                        PublicationGateRequirement(
                            guard_ref=speculative_guard_ref,
                            guard_step=guard_step,
                        ),
                    )
        return steps


def make_commit_branch_intent(
    ref_id: ServerPlanRefId,
    *,
    domain: type[VersioningDomain],
    branch_id: ScalarServerRef[BranchId],
    session_id: ScalarServerRef[SessionId],
    lifecycle_plan: CommitBranchLifecyclePlan | None = None,
    allow_empty: bool,
    is_new_branch: ScalarServerRef[bool] | None = None,
    revision_metadata: _RevisionMetadataPayload,
    scope_kind: CommitBranchScopeKind,
    inline_staged_commit_id: StagedCommitId | None = None,
    connection_id: ConnectionId | None = None,
    explicit_staged_commit_ids: Sequence[StagedCommitId] = (),
    expected_tip_revision_id: ScalarServerRef[RevisionId] | None = None,
    ordered_parent_revision_ids: tuple[RevisionId, ...] | None = None,
    ordered_parent_relationship_types: tuple[ParentType, ...] | None = None,
    concurrent_commit_behavior: ConcurrentBranchCommitBehavior = ConcurrentBranchCommitBehavior.FAIL_FAST,
    branch_scope_token: BranchScopeToken | None = None,
    materialize_tip: TipMaterializationPolicy = True,
    inline_touched_table_names: frozenset[str] | None = None,
    inline_deleted_table_names: frozenset[str] | None = None,
    speculative_publish_table_names: frozenset[str] | None = None,
    speculative_insert_only_table_names: frozenset[str] | None = None,
    revision_id: RevisionId | None = None,
    defer_database_commit: bool = False,
    revision_timestamp: AwareDatetime | None = None,
    revision_session_id: SessionId | None = None,
) -> CommitBranchIntent:
    """Build the single unified commit-branch intent."""
    del lifecycle_plan
    if scope_kind == "inline" and inline_staged_commit_id is None:
        msg = "scope_kind='inline' requires inline_staged_commit_id"
        raise ValueError(msg)
    if scope_kind == "connection_scoped" and connection_id is None:
        msg = "scope_kind='connection_scoped' requires connection_id"
        raise ValueError(msg)
    if scope_kind == "branch_scoped" and connection_id is not None:
        msg = "scope_kind='branch_scoped' must not supply connection_id"
        raise ValueError(msg)
    if ordered_parent_relationship_types is not None and (
        ordered_parent_revision_ids is None or len(ordered_parent_relationship_types) != len(ordered_parent_revision_ids)
    ):
        raise ValueError("Ordered parent relationship types must match the ordered parent revisions")
    intent = CommitBranchIntent(ref_id)
    if revision_id is not None:
        intent._new_revision_id = revision_id
        intent._new_revision_ref = ServerRefs.scalar(revision_id)
    intent.domain = domain
    intent.branch_id = branch_id
    intent.literal_branch_id = None
    intent.session_id = session_id
    intent.allow_empty = allow_empty
    intent.is_new_branch = is_new_branch if is_new_branch is not None else ServerRefs.scalar(False)
    intent.revision_metadata = revision_metadata
    intent.scope_kind = scope_kind
    intent.inline_staged_commit_id = inline_staged_commit_id
    intent.visibility_scope_value = connection_id
    intent.explicit_staged_commit_ids = tuple(dict.fromkeys(explicit_staged_commit_ids))
    intent.expected_tip_revision_id = expected_tip_revision_id
    intent.ordered_parent_revision_ids = ordered_parent_revision_ids
    intent.ordered_parent_relationship_types = ordered_parent_relationship_types
    intent.concurrent_commit_behavior = concurrent_commit_behavior
    intent.branch_scope_token = branch_scope_token or opaque_scope_token(branch_id)
    intent.materialize_tip = materialize_tip
    intent.inline_touched_table_names = inline_touched_table_names
    intent.inline_deleted_table_names = inline_deleted_table_names
    intent.speculative_publish_table_names = speculative_publish_table_names
    intent.speculative_insert_only_table_names = speculative_insert_only_table_names or frozenset()
    intent.defer_database_commit = defer_database_commit
    intent.revision_timestamp = revision_timestamp
    intent.revision_session_id = revision_session_id
    return intent


