class CommitSparseIntent(IntentStep[CommitResult]):
    """L4: Commit explicit sparse staged rows for one table and return a summary."""

    intent_tags = frozenset({"write", "commit_sparse", "versioned", "intent"})

    def __init__(
        self: CommitSparseIntent,
        ref_id: ServerPlanRefId,
        *,
        branch_id: ScalarServerRef[BranchId],
        new_revision_id: ScalarServerRef[RevisionId],
        config: _CommitSparseConfig,
    ) -> None:
        super().__init__(ref_id)
        self.branch_id = branch_id
        self.new_revision_id = new_revision_id
        self.staged_commit_ids = tuple(config.staged_commit_ids)
        self.sparse_table_name = config.sparse_table_name
        self.staged_table_name = config.staged_table_name
        self.tip_table_name = config.tip_table_name
        self.sparse_data_columns = tuple(config.sparse_data_columns)
        self.tip_data_columns = tuple(config.tip_data_columns)
        self.log_table_name = config.log_table_name
        self.publication_model_cls = config.publication_model_cls

    def lower(self: CommitSparseIntent, ctx: LoweringContext) -> Sequence[ServerPlanStep[CommitResult]]:
        from impl.common.l2070_server_plan.steps.commit_branch_steps import (
            BuildCommitSparseResultStep,
            CountSparseCommitRowsStep,
            ExplicitSparsePublish,
            _StagedCommitSelector,
            build_sparse_publish_steps,
        )

        if not self.staged_commit_ids:
            return cast(Sequence[ServerPlanStep[CommitResult]], [BuildCommitSparseResultStep(self.ref_id)])

        inserted_ref = _ref_id(f"{self.ref_id}_count_inserted")
        updated_ref = _ref_id(f"{self.ref_id}_count_updated")
        deleted_ref = _ref_id(f"{self.ref_id}_count_deleted")
        selector = _StagedCommitSelector.explicit_ids(staged_commit_ids=self.staged_commit_ids)
        steps: list[ServerPlanStep[Any]] = [
            CountSparseCommitRowsStep(
                inserted_ref,
                staged_table_name=self.staged_table_name,
                sparse_table_name=self.sparse_table_name,
                branch_id=self.branch_id,
                selector=selector,
                mode="inserted",
            ),
            CountSparseCommitRowsStep(
                updated_ref,
                staged_table_name=self.staged_table_name,
                sparse_table_name=self.sparse_table_name,
                branch_id=self.branch_id,
                selector=selector,
                mode="updated",
            ),
            CountSparseCommitRowsStep(
                deleted_ref,
                staged_table_name=self.staged_table_name,
                sparse_table_name=self.sparse_table_name,
                branch_id=self.branch_id,
                selector=selector,
                mode="deleted",
            ),
            BuildCommitSparseResultStep(
                self.ref_id,
                inserted_ref=inserted_ref,
                updated_ref=updated_ref,
                deleted_ref=deleted_ref,
            ),
        ]
        publish_steps = build_sparse_publish_steps(
            ref_id=self.ref_id,
            scope=ExplicitSparsePublish(
                branch_id=self.branch_id,
                staged_commit_ids=self.staged_commit_ids,
            ),
            new_revision_id=self.new_revision_id,
            sparse_table_name=self.sparse_table_name,
            staged_table_name=self.staged_table_name,
            tip_table_name=self.tip_table_name,
            sparse_data_columns=self.sparse_data_columns,
            tip_data_columns=self.tip_data_columns,
            log_table_name=self.log_table_name,
            initial_dependencies=frozenset({inserted_ref, updated_ref, deleted_ref}),
            log_depends_on_publish_chain=True,
            collect_deleted_count=False,
            enable_postgres_shared_rowset=(
                ctx.backend_profile.traits.versioned_staging_transport is VersionedStagingTransport.SAME_STATEMENT_RELATION
            ),
            publication_model_cls=self.publication_model_cls,
        )
        assert isinstance(publish_steps, list)
        steps.extend(publish_steps)
        return cast(Sequence[ServerPlanStep[CommitResult]], steps)


