class _ValidationAnchorStep(NonPublishingStep[None]):
    """No-op anchor that preserves an intent ref after lowering."""

    def __init__(
        self: _ValidationAnchorStep,
        ref_id: ServerPlanRefId,
        *,
        depends_on: frozenset[ServerPlanRefId] = frozenset(),
    ) -> None:
        super().__init__(ref_id)
        self._dependencies = frozenset(str(dep) for dep in depends_on)

    @property
    def level(self: _ValidationAnchorStep) -> int:
        return 0

    def result_cardinality(self: _ValidationAnchorStep) -> Cardinality:
        return Cardinality.NONE

    def is_read_only(self: _ValidationAnchorStep) -> bool:
        return True

    def step_tags(self: _ValidationAnchorStep) -> frozenset[str]:
        return frozenset({"validation", "anchor"})

    def tables_read(self: _ValidationAnchorStep) -> frozenset[str]:
        return frozenset()

    def tables_written(self: _ValidationAnchorStep) -> frozenset[str]:
        return frozenset()

    def dependencies(self: _ValidationAnchorStep) -> frozenset[str]:
        return self._dependencies

    def compile(self: _ValidationAnchorStep, ctx: CompilationContext) -> CompiledStep[None]:
        del ctx
        return CompiledStep(grammar=None)


class ValidateEdgeConstraintsIntent(NonPublishingStep[None]):
    """L2: Validate edge constraints for a committed revision.

    Generic lowering inspects the domain's GraphEdge tables and their
    EdgeConstraints config, then emits L0 check steps per edge table:

    * ``on_duplicate == ERROR`` -> CheckDuplicateEdgesBatchStep
    * ``allow_dangling == False`` -> an authoritative dangling-edge batch step
    Tree-mode validation runs in ``CommitBranchIntent`` before this intent.

    Backends can override lowering at any granularity — the whole intent
    via ``_lower_ValidateEdgeConstraintsIntent``, or individual check steps.
    """

    def __init__(
        self: ValidateEdgeConstraintsIntent,
        ref_id: ServerPlanRefId,
        *,
        config: _ValidateEdgeConstraintsConfig | None = None,
        domain: type[VersioningDomain] | None = None,
        lazy_branch: BranchRefInput | None = None,
        new_revision_id_raw: RevisionRawInput | None = None,
        publish_scope: PublishScopeDescriptor | None = None,
        depends_on: DependencyRefs = frozenset(),
    ) -> None:
        super().__init__(ref_id)
        if config is None:
            if domain is None or lazy_branch is None or new_revision_id_raw is None:
                msg = "ValidateEdgeConstraintsIntent requires config or domain/lazy_branch/revision."
                raise TypeError(msg)
            revision_id = new_revision_id_raw if isinstance(new_revision_id_raw, RevisionId) else RevisionId(str(new_revision_id_raw))
            config = _ValidateEdgeConstraintsConfig(
                domain=domain,
                lazy_branch=_as_scalar_ref(lazy_branch),
                new_revision_id=revision_id,
                publish_scope=publish_scope,
                dangling_validation_authority="sparse_revision",
                depends_on=frozenset(str(dep) for dep in depends_on),
            )
        self.domain = config.domain
        self.lazy_branch = config.lazy_branch
        self.new_revision_id = config.new_revision_id
        self.new_revision_id_raw = config.new_revision_id.unwrap_to_str()
        self.publish_scope = config.publish_scope
        self.publish_table_names = config.publish_table_names
        self.deleted_table_names = config.deleted_table_names
        self.insert_only_table_names = config.insert_only_table_names
        self.dangling_validation_authority = config.dangling_validation_authority
        self.edge_validation_condition_ref = config.edge_validation_condition_ref
        self._dependencies = config.depends_on
        if self.dangling_validation_authority == "branch_tip" and self.publish_scope is None:
            msg = (
                "branch-tip dangling validation requires an explicit publication scope; "
                "scope-free validation must use sparse_revision authority"
            )
            raise ValueError(msg)

    def _required_publish_scope(self: ValidateEdgeConstraintsIntent) -> PublishScopeDescriptor:
        if self.publish_scope is None:
            msg = "branch-tip dangling validation requires an explicit publication scope"
            raise RuntimeError(msg)
        return self.publish_scope

    @property
    def level(self: ValidateEdgeConstraintsIntent) -> int:
        return 2

    def result_cardinality(self: ValidateEdgeConstraintsIntent) -> Cardinality:
        return Cardinality.SCALAR

    def is_read_only(self: ValidateEdgeConstraintsIntent) -> bool:
        return True

    def execution_role(self: ValidateEdgeConstraintsIntent) -> StepExecutionRole:
        return StepExecutionRole.VIRTUAL

    def step_tags(self: ValidateEdgeConstraintsIntent) -> frozenset[str]:
        return frozenset({"read", "validation", "edge_constraints", "intent"})

    def dependencies(self: ValidateEdgeConstraintsIntent) -> frozenset[str]:
        return self._dependencies

    def tables_read(self: ValidateEdgeConstraintsIntent) -> frozenset[str]:
        return frozenset()

    def tables_written(self: ValidateEdgeConstraintsIntent) -> frozenset[str]:
        return frozenset()

    def compile(
        self: ValidateEdgeConstraintsIntent,
        ctx: CompilationContext,
    ) -> CompiledStep[None]:
        raise TypeError("L2 ValidateEdgeConstraintsIntent must be lowered before compile")

    def lower(
        self: ValidateEdgeConstraintsIntent,
        ctx: LoweringContext,
    ) -> Sequence[ServerPlanStep[None]]:
        from impl.common.l2070_server_plan.steps.edge_constraint_steps import (
            CheckBranchTipDanglingEdgesBatchStep,
            CheckDanglingEdgesBatchStep,
            CheckDuplicateEdgesBatchStep,
            CheckGraphIdentityBatchStep,
            CheckGraphValidationNeededStep,
            CheckSymmetricEdgesStep,
            FetchEdgePairsForCycleCheckStep,
            _BatchedBranchTipDanglingEdgeEntry,
            _BatchedBranchTipDanglingEdgeValidationConfig,
            _BatchedDanglingEdgeEntry,
            _BatchedDanglingEdgeValidationConfig,
            _BatchedDuplicateEdgeEntry,
            _BatchedDuplicateEdgeValidationConfig,
            _EdgeValidationConfig,
            _GraphIdentityTable,
            _GraphIdentityValidationConfig,
            _GraphValidationNeededConfig,
        )
        from impl.common.l7100_versioned_operations.edge_constraint_validation import (
            _collect_edge_base_tables,
            _get_concrete_subtypes,
            _get_domain_edge_types,
            _group_subtypes_by_constraints,
        )
        from l1000_schema.table_utils import get_table_name
        from l1050_polymorphism.type_filter_helper import polymorphic_type_name_aliases
        from l2070_batching.write_column_policy import physical_table_publication_columns
        from l3250_migrations.versioned_table_helpers import (
            VersionedTableType,
            get_auxiliary_table_name,
        )
        from l9600_graphs.edge_constraints import UniqueEdgeScope, get_edge_constraints
        from l9600_graphs.graph import GraphNode
        from l9600_graphs.suppress_constraints import are_graph_constraints_suppressed

        if are_graph_constraints_suppressed():
            return [
                _ValidationCompleteStep(
                    self.ref_id,
                    depends_on=_dep_ids(self._dependencies),
                ),
            ]

        def _schema_table_available(
            *,
            base_table: SqlTableName,
            auxiliary_table: SqlTableName,
        ) -> bool:
            if self.publish_table_names is not None and str(base_table) in self.publish_table_names:
                return True
            if self.publish_scope is not None:
                return True
            exists = ctx.cached_table_exists(auxiliary_table)
            return exists is not False

        node_tables: list[_GraphNodeValidationTables] = []
        seen_node_sparse_tables: set[SqlTableName] = set()
        graph_node_models = tuple(node_model for graph_definition in self.domain.graphs for node_model in graph_definition.node_types)

        for model in dict.fromkeys((*self.domain.all_versioned_models(), *graph_node_models)):
            try:
                if issubclass(model, GraphNode) and model is not GraphNode:
                    sparse = SqlTableName(
                        get_auxiliary_table_name(model, VersionedTableType.SPARSE),
                    )
                    if sparse in seen_node_sparse_tables:
                        continue
                    node_tables.append(
                        _GraphNodeValidationTables(
                            base=SqlTableName(get_table_name(model)),
                            sparse=sparse,
                            staged=SqlTableName(
                                get_auxiliary_table_name(model, VersionedTableType.STAGED),
                            ),
                            has_type_name=any(
                                str(column) == "type_name"
                                for column in physical_table_publication_columns(
                                    model,
                                    include_shared_subtypes=False,
                                )
                            ),
                        ),
                    )
                    seen_node_sparse_tables.add(sparse)
            except TypeError:
                continue

        edge_base_tables = tuple(
            edge_base
            for edge_base in _collect_edge_base_tables(self.domain)
            if _schema_table_available(
                base_table=SqlTableName(get_table_name(edge_base)),
                auxiliary_table=SqlTableName(
                    get_auxiliary_table_name(edge_base, VersionedTableType.SPARSE),
                ),
            )
            and _schema_table_available(
                base_table=SqlTableName(get_table_name(edge_base)),
                auxiliary_table=SqlTableName(
                    get_auxiliary_table_name(edge_base, VersionedTableType.STAGED),
                ),
            )
        )
        if not edge_base_tables:
            return [
                _ValidationCompleteStep(
                    self.ref_id,
                    depends_on=_dep_ids(self._dependencies),
                ),
            ]

        deleted_node_tables = False
        if self.publish_table_names:
            edge_table_names = {get_table_name(edge_base) for edge_base in edge_base_tables}
            touched_edge_tables = bool(edge_table_names & set(self.publish_table_names))
            deleted_node_tables = bool(
                {str(node_table.base) for node_table in node_tables} & set(self.deleted_table_names),
            )
            if not touched_edge_tables and not deleted_node_tables:
                return [
                    _ValidationCompleteStep(
                        self.ref_id,
                        depends_on=_dep_ids(self._dependencies),
                    ),
                ]

        domain_edge_types = _get_domain_edge_types(self.domain)
        if deleted_node_tables:
            deleted_node_table_names = set(self.deleted_table_names)
            affected_graph_definitions = tuple(
                graph_definition
                for graph_definition in self.domain.graphs
                if any(get_table_name(node_type) in deleted_node_table_names for node_type in graph_definition.node_types)
            )
            affected_edge_types = {
                edge_type for graph_definition in affected_graph_definitions for edge_type in graph_definition.edge_types
            }
            if affected_edge_types:
                affected_edge_table_names = {get_table_name(edge_type) for edge_type in affected_edge_types}
                affected_node_table_names = {
                    get_table_name(node_type)
                    for graph_definition in affected_graph_definitions
                    for node_type in graph_definition.node_types
                }
                domain_edge_types.intersection_update(affected_edge_types)
                edge_base_tables = tuple(
                    edge_base for edge_base in edge_base_tables if get_table_name(edge_base) in affected_edge_table_names
                )
                node_tables = [node_table for node_table in node_tables if str(node_table.base) in affected_node_table_names]
        if self.publish_table_names and not deleted_node_tables:
            publish_table_names = set(self.publish_table_names)
            edge_base_tables = tuple(edge_base for edge_base in edge_base_tables if get_table_name(edge_base) in publish_table_names)

        steps: list[ServerPlanStep[Any]] = []
        duplicate_entries: list[_BatchedDuplicateEdgeEntry] = []
        dangling_entries: list[_BatchedDanglingEdgeEntry] = []
        branch_tip_dangling_entries: list[_BatchedBranchTipDanglingEdgeEntry] = []
        idx = 0

        def _requires_duplicate_validation(edge_type: type[Any]) -> bool:
            if self.publish_scope is not None:
                return True
            catalog = ctx.planning_catalog
            if catalog is None:
                msg = "ValidateEdgeConstraintsIntent requires PlanningCatalog graph metadata"
                raise RuntimeError(msg)
            edge_shape = catalog.graph_access_for_model(edge_type)
            if edge_shape is None:
                msg = f"No graph access-path metadata found for edge type {edge_type.__name__}"
                raise RuntimeError(msg)
            unique_access = edge_shape.unique_edge_access
            return unique_access is None or not unique_access.available

        def _next_ref(suffix: str) -> ServerPlanRefId:
            nonlocal idx
            ref = _server_ref_compatible_child_ref(
                ctx,
                self.ref_id,
                field_name=f"{suffix}_{idx}",
            )
            idx += 1
            return ref

        graph_identity_tables = tuple(
            [
                _GraphIdentityTable(
                    base_table=node_table.base,
                    sparse_table=node_table.sparse,
                    staged_table=node_table.staged,
                    has_type_name=node_table.has_type_name,
                )
                for node_table in node_tables
            ]
            + [
                _GraphIdentityTable(
                    base_table=SqlTableName(get_table_name(edge_base)),
                    sparse_table=SqlTableName(
                        get_auxiliary_table_name(edge_base, VersionedTableType.SPARSE),
                    ),
                    staged_table=SqlTableName(
                        get_auxiliary_table_name(edge_base, VersionedTableType.STAGED),
                    ),
                    has_type_name=any(
                        str(column) == "type_name"
                        for column in physical_table_publication_columns(
                            edge_base,
                            include_shared_subtypes=False,
                        )
                    ),
                )
                for edge_base in edge_base_tables
            ],
        )
        if self.publish_table_names is not None:
            graph_identity_tables = tuple(
                table
                for table in graph_identity_tables
                if str(table.base_table) in self.publish_table_names and str(table.base_table) not in self.insert_only_table_names
            )
        if graph_identity_tables:
            steps.append(
                CheckGraphIdentityBatchStep(
                    _next_ref("graph_identity"),
                    config=_GraphIdentityValidationConfig(
                        tables=graph_identity_tables,
                        publish_scope=self.publish_scope,
                        depends_on=_dep_ids(self._dependencies),
                    ),
                    lazy_branch=self.lazy_branch,
                ),
            )

        def _emit_dangling_check(
            edge_base_table: str,
            edge_sparse_table: str,
            edge_staged_table: str,
            edge_tip_table: str,
            *,
            type_name_filter: tuple[str, ...],
        ) -> None:
            if self.dangling_validation_authority == "branch_tip":
                branch_tip_dangling_entries.append(
                    _BatchedBranchTipDanglingEdgeEntry(
                        edge_tip_table=SqlTableName(edge_tip_table),
                        edge_sparse_table=SqlTableName(edge_sparse_table),
                        edge_staged_table=SqlTableName(edge_staged_table),
                        edge_base_table=SqlTableName(edge_base_table),
                        publish_scope=self._required_publish_scope(),
                        type_name_filter=type_name_filter,
                    ),
                )
            else:
                dangling_entries.append(
                    _BatchedDanglingEdgeEntry(
                        edge_sparse_table=SqlTableName(edge_sparse_table),
                        edge_staged_table=SqlTableName(edge_staged_table),
                        edge_base_table=SqlTableName(edge_base_table),
                        type_name_filter=type_name_filter,
                        publish_scope=self.publish_scope,
                    ),
                )

        def _emit_non_unique_checks(
            target_steps: list[ServerPlanStep[None]],
            edge_base_table: str,
            edge_sparse_table: str,
            edge_staged_table: str,
            edge_tip_table: str,
            *,
            config: Any,
            type_name_filter: tuple[str, ...],
            emit_dangling: bool = True,
        ) -> None:
            tree_mode = bool(config.tree_mode)
            acyclic = bool(config.acyclic)
            allow_dangling = bool(config.allow_dangling)
            symmetric = bool(config.symmetric)
            symmetric_auto_create = bool(config.symmetric_auto_create)
            if emit_dangling and not allow_dangling:
                _emit_dangling_check(
                    edge_base_table,
                    edge_sparse_table,
                    edge_staged_table,
                    edge_tip_table,
                    type_name_filter=type_name_filter,
                )

            if acyclic and not tree_mode:
                target_steps.append(
                    FetchEdgePairsForCycleCheckStep(
                        _next_ref("cycle"),
                        config=_EdgeValidationConfig(
                            edge_sparse_table=SqlTableName(edge_sparse_table),
                            edge_staged_table=SqlTableName(edge_staged_table),
                            edge_base_table=SqlTableName(edge_base_table),
                            revision_id_raw=self.new_revision_id,
                            type_name_filter=type_name_filter,
                            publish_scope=self.publish_scope,
                            depends_on=_dep_ids(self._dependencies),
                        ),
                        lazy_branch=self.lazy_branch,
                    ),
                )

            if symmetric and not symmetric_auto_create:
                target_steps.append(
                    CheckSymmetricEdgesStep(
                        _next_ref("sym"),
                        config=_EdgeValidationConfig(
                            edge_sparse_table=SqlTableName(edge_sparse_table),
                            edge_staged_table=SqlTableName(edge_staged_table),
                            edge_base_table=SqlTableName(edge_base_table),
                            revision_id_raw=self.new_revision_id,
                            type_name_filter=type_name_filter,
                            publish_scope=self.publish_scope,
                            depends_on=_dep_ids(self._dependencies),
                        ),
                        lazy_branch=self.lazy_branch,
                    ),
                )

        for edge_base in edge_base_tables:
            edge_steps: list[ServerPlanStep[Any]] = []
            config = get_edge_constraints(edge_base)
            scope = config.unique_scope
            is_poly = "type_name" in edge_base.model_fields

            edge_sparse = get_auxiliary_table_name(edge_base, VersionedTableType.SPARSE)
            edge_staged = get_auxiliary_table_name(edge_base, VersionedTableType.STAGED)
            edge_tip = get_auxiliary_table_name(edge_base, VersionedTableType.TIP)
            edge_base_table = get_table_name(edge_base)

            if config.unique:
                if not is_poly or scope == UniqueEdgeScope.PER_HIERARCHY:
                    if _requires_duplicate_validation(edge_base):
                        duplicate_entries.append(
                            _BatchedDuplicateEdgeEntry(
                                edge_sparse_table=SqlTableName(edge_sparse),
                                edge_staged_table=SqlTableName(edge_staged),
                                edge_base_table=SqlTableName(edge_base_table),
                                publish_scope=self.publish_scope,
                            ),
                        )
                elif scope == UniqueEdgeScope.PER_TYPE:
                    for subtype in _get_concrete_subtypes(edge_base, domain_edge_types):
                        sub_config = get_edge_constraints(subtype)
                        if not sub_config.unique:
                            continue
                        if not _requires_duplicate_validation(subtype):
                            continue
                        duplicate_entries.append(
                            _BatchedDuplicateEdgeEntry(
                                edge_sparse_table=SqlTableName(edge_sparse),
                                edge_staged_table=SqlTableName(edge_staged),
                                edge_base_table=SqlTableName(edge_base_table),
                                type_name_filter=polymorphic_type_name_aliases(subtype),
                                publish_scope=self.publish_scope,
                            ),
                        )

            if not is_poly:
                _emit_non_unique_checks(
                    edge_steps,
                    edge_base_table=edge_base_table,
                    edge_sparse_table=edge_sparse,
                    edge_staged_table=edge_staged,
                    edge_tip_table=edge_tip,
                    config=config,
                    type_name_filter=(),
                )
            else:
                constraint_groups = _group_subtypes_by_constraints(edge_base, domain_edge_types)
                for group_config, subtypes in constraint_groups.items():
                    if not group_config.allow_dangling:
                        combined_type_name_filter = tuple(
                            dict.fromkeys(alias for subtype in subtypes for alias in polymorphic_type_name_aliases(subtype)),
                        )
                        _emit_dangling_check(
                            edge_base_table,
                            edge_sparse,
                            edge_staged,
                            edge_tip,
                            type_name_filter=combined_type_name_filter,
                        )
                    for subtype in subtypes:
                        _emit_non_unique_checks(
                            edge_steps,
                            edge_base_table=edge_base_table,
                            edge_sparse_table=edge_sparse,
                            edge_staged_table=edge_staged,
                            edge_tip_table=edge_tip,
                            config=group_config,
                            type_name_filter=polymorphic_type_name_aliases(subtype),
                            emit_dangling=False,
                        )

            if not edge_steps:
                continue

            steps.extend(edge_steps)

        validation_needed_ref: ServerPlanRefId | None = None
        if self.edge_validation_condition_ref is None and (duplicate_entries or dangling_entries):
            validation_needed_ref = _next_ref("graph_validation_needed")
            steps.append(
                CheckGraphValidationNeededStep(
                    validation_needed_ref,
                    config=_GraphValidationNeededConfig(
                        edge_entries=(*duplicate_entries, *dangling_entries),
                        node_base_tables=tuple(node_table.base for node_table in node_tables),
                        node_sparse_tables=tuple(node_table.sparse for node_table in node_tables),
                        publish_scope=self.publish_scope,
                        depends_on=_dep_ids(self._dependencies),
                        node_staged_tables=tuple(node_table.staged for node_table in node_tables),
                    ),
                    lazy_branch=self.lazy_branch,
                ),
            )

        if duplicate_entries:
            steps.append(
                CheckDuplicateEdgesBatchStep(
                    _next_ref("dup_batch"),
                    config=_BatchedDuplicateEdgeValidationConfig(
                        entries=tuple(duplicate_entries),
                        revision_id_raw=self.new_revision_id,
                        validation_needed_ref=validation_needed_ref,
                        depends_on=_dep_ids(self._dependencies),
                    ),
                    lazy_branch=self.lazy_branch,
                ),
            )
        if dangling_entries:
            steps.append(
                CheckDanglingEdgesBatchStep(
                    _next_ref("dangle_batch"),
                    config=_BatchedDanglingEdgeValidationConfig(
                        entries=tuple(dangling_entries),
                        node_sparse_tables=tuple(node_table.sparse for node_table in node_tables),
                        revision_id_raw=self.new_revision_id,
                        revision_branch_index_table=SqlTableName(str(get_table_name(self.domain.revision_branch_index_model))),
                        validation_needed_ref=validation_needed_ref,
                        depends_on=_dep_ids(self._dependencies),
                        node_staged_tables=tuple(node_table.staged for node_table in node_tables),
                    ),
                    lazy_branch=self.lazy_branch,
                ),
            )
        for branch_tip_entry in branch_tip_dangling_entries:
            steps.append(
                CheckBranchTipDanglingEdgesBatchStep(
                    _next_ref("dangle_tip_batch"),
                    config=_BatchedBranchTipDanglingEdgeValidationConfig(
                        entries=(branch_tip_entry,),
                        node_staged_tables=tuple(node_table.staged for node_table in node_tables),
                        branch_table=SqlTableName(str(get_table_name(self.domain.branch_model))),
                        depends_on=_dep_ids(self._dependencies),
                    ),
                    lazy_branch=self.lazy_branch,
                ),
            )

        if self.edge_validation_condition_ref is not None and steps:
            from impl.common.l2070_server_plan.steps.conditional_builders import build_one_sided_conditional

            validation_gate_ref = ServerPlanRefId(f"{self.ref_id}_validation_gate")
            steps = [
                build_one_sided_conditional(
                    ref_id=validation_gate_ref,
                    condition_ref=self.edge_validation_condition_ref,
                    if_true_steps=steps,
                ),
            ]

        validation_dependencies = frozenset(step.ref_id for step in steps) if steps else _dep_ids(self._dependencies)
        steps.append(
            _ValidationCompleteStep(
                self.ref_id,
                depends_on=validation_dependencies,
            ),
        )
        return steps

