def cast_postgres_typed_field_expr(
    model_cls: type[Any],
    field_name: str,
    expr: SqlRenderable,
    backend_type: BackendType,
) -> SqlRenderable:
    if dml_parameter_transport_for_backend(backend_type) is not DmlParameterTransport.EXPLICIT_STORAGE_CASTS:
        return expr
    cast_target = model_field_cast_target(model_cls, field_name)
    if cast_target is None:
        return expr
    return SqlCast(expr, cast_target)


