@pure_lazy
def permission_session_vars_from_context(
    ctx: CompilationContext,
    permission_context_ref: ServerPlanRefId | None,
    permission_context_type: type[ResolvedSessionContext] | None,
    *,
    site_name: str,
    result_contract: str,
) -> SessionVariableSqlBindings | None:
    """Bind one plan-owned typed session-context relation for policy compilation."""
    if permission_context_ref is None and permission_context_type is None:
        return None
    if permission_context_ref is None or permission_context_type is None:
        msg = f"{site_name} requires both a permission context ref and model type"
        raise TypeError(msg)
    from impl.common.l2070_server_plan.steps.sql_projection import (
        _require_sql_visible_source_cte,
    )
    from impl.common.l7300_cross_branch.permission_expression_compiler import (
        _sql_session_context_bindings,
    )

    context_cte = _require_sql_visible_source_cte(
        ctx,
        permission_context_ref,
        site_name=site_name,
        result_contract=result_contract,
    )
    return _sql_session_context_bindings(
        permission_context_type,
        ServerPlanRefId(context_cte.ref_id),
    )


@pure_lazy
def materialize_permission_user_id(
    resolved_user_id: ResolvedPermissionUserId,
    ctx: CompilationContext,
) -> ResolvedPermissionUserId:
    """Use an executor-published user ID directly on MySQL-family backends."""
    if (
        not isinstance(resolved_user_id, CteReference)
        or ctx.backend_profile.traits.permission_user_transport is not PermissionUserTransport.MATERIALIZED_VALUE
    ):
        return resolved_user_id
    from impl.common.l2100_sql_grammar.domain.infra.stmt_cte_helpers import (
        SqlPublishedRowsQuery,
    )

    auxiliary_query = resolved_user_id.auxiliary_query
    if not isinstance(auxiliary_query, SqlPublishedRowsQuery):
        return resolved_user_id
    rows = auxiliary_query.published_rows_readonly
    if len(rows) != 1 or "user_id" not in rows[0]:
        return resolved_user_id
    user_id_value = rows[0]["user_id"]
    if user_id_value is None:
        return None
    return UserId(str(user_id_value))


class _CompileOnlySessionId:
    """Session-id adapter for compile-only contexts that use synthetic ids."""

    def __init__(self: _CompileOnlySessionId, value: str) -> None:
        self._value = value

    def unwrap_to_sql(self: _CompileOnlySessionId) -> str:
        return self._value


@pure_lazy
def compilation_session_id(ctx: CompilationContext) -> PermissionCompilationSessionId | None:
    """Return a session id object usable by permission compilers."""
    if ctx.session_id is None:
        return None
    from l2070_batching.server_ref import ScalarServerRef, inspect_server_value_shape_for_planning
    from l2070_batching.seeded_constants import read_seeded_constant_from_ctx

    if isinstance(ctx.session_id, SessionId):
        return ctx.session_id
    if isinstance(ctx.session_id, ScalarServerRef):
        shape = inspect_server_value_shape_for_planning(ctx.session_id, site="compilation_session_id")
        if shape.symbolic_ref_id is not None:
            ref_id = ServerPlanRefId(str(shape.symbolic_ref_id))
            found, value = read_seeded_constant_from_ctx(ctx, ref_id)
            if not found and str(ref_id).startswith("seed_"):
                found, value = read_seeded_constant_from_ctx(None, ref_id)
            if found and isinstance(value, SessionId):
                return value
    session_id_text = str(ctx.session_id)
    try:
        return SessionId(session_id_text)
    except (TypeError, ValueError):
        return _CompileOnlySessionId(session_id_text)


@pure_lazy
def session_id_expr(session_id: object, ctx: CompilationContext | None = None) -> SqlRenderable:
    """Lower a literal or symbolic session identity without executing it."""
    from impl.common.l2070_server_plan.steps._compile_server_ref import lower_scalar_server_ref
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlParam

    source = session_sql_source_or_none(session_id)
    if source is not None:
        if ctx is None:
            raise TypeError("A session query requires a compilation context")
        return source.session_id_expression(ctx)
    if isinstance(session_id, ScalarServerRef):
        if ctx is None:
            raise TypeError("Scalar session refs require a compilation context")
        if ctx.uses_bound_transaction_principal:
            from impl.common.l2100_sql_grammar.domain.triggers._expressions_trigger import (
                SqlTriggerSessionId,
            )

            return SqlTriggerSessionId()
        return lower_scalar_server_ref(session_id, ctx)
    return SqlParam(session_id)


@pure_lazy
def session_user_id_expr(session_id: object, ctx: CompilationContext | None = None) -> SqlRenderable:
    """Return a SQL expression resolving the user for a session id."""
    from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName, SqlTableName
    from impl.common.l2100_sql_grammar.domain.query.stmt_dynamic import SqlDynamicSelectStmt
    from impl.common.l2100_sql_grammar.tree.enums import BinaryOp
    from impl.common.l2100_sql_grammar.tree.expr_compound import SqlSubquery
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef
    from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp

    session_expr = session_id_expr(session_id, ctx)
    return SqlSubquery(
        SqlDynamicSelectStmt(
            from_table=SqlTableName("sys_sessions"),
            columns=[SqlColumnName("user_id")],
            where_conditions=[
                SqlBinaryOp(
                    SqlColumnRef(SqlColumnName("sys_id")),
                    BinaryOp.EQ,
                    session_expr,
                ),
            ],
            limit=1,
        ),
    )


def compile_branch_discovery_permission(
    model: type[DatabaseObjectRow],
    ctx: CompilationContext,
    table: str,
    *,
    permission_context_ref: ServerPlanRefId | None = None,
    permission_context_type: type[ResolvedSessionContext] | None = None,
) -> SqlRenderable | None:
    """Compile the branch model's concrete READ authority."""
    from impl.common.l7300_cross_branch.permission_expression_compiler import compile_permission_where_with_user_expr
    from l1100_exceptions.exceptions import PermissionCompilationError
    from l4000_permissions.permission_enforcement import get_query_permission_plan

    actor = compilation_session_id(ctx)
    if actor is None:
        raise PermissionCompilationError("Branch discovery requires an originating session")
    plan = get_query_permission_plan(model)
    if plan is not None and not plan.filters_session(actor if isinstance(actor, SessionId) else None) and permission_context_ref is None:
        return None
    session_vars = permission_session_vars_from_context(
        ctx,
        permission_context_ref,
        permission_context_type,
        site_name="branch discovery",
        result_contract="filter branches from the bound session context",
    )
    return compile_permission_where_with_user_expr(
        model,
        None if session_vars is not None else actor,
        session_user_id_expr(actor, ctx),
        table_alias=table,
        action="read",
        session_id_sql=session_id_expr(actor, ctx),
        session_vars=session_vars,
        compilation_context=ctx,
    )


def session_user_id_subquery(ctx: CompilationContext) -> SqlRenderable:
    """Return a SQL-visible user-id expression for the current session."""
    if ctx.session_id is None:
        msg = "Session user-id subquery requires a concrete session id"
        raise TypeError(msg)
    return session_user_id_expr(ctx.session_id, ctx)


@pure_lazy
def versioned_permission_branch_id_expr(ctx: CompilationContext) -> SqlRenderable | None:
    """Return the SQL-visible branch id expression for permission predicates."""
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlParam

    lazy_branch = getattr(ctx, "lazy_branch", None)
    if lazy_branch is not None:
        from impl.common.l2070_server_plan.steps._compile_server_ref import lower_scalar_server_ref

        return lower_scalar_server_ref(lazy_branch, ctx, default_field="branch_id")
    if ctx.branch_id is not None:
        return SqlParam(str(ctx.branch_id))
    return None


@pure_lazy
def versioned_permission_anchor(
    ctx: CompilationContext,
    *,
    domain: type[VersioningDomain] | None = None,
    fallback_branch_id_sql: SqlRenderable | None = None,
) -> PermissionVersionAnchor:
    """Build the permission anchor selected by the versioned read context."""
    from impl.common.l2070_server_plan.steps._compile_server_ref import lower_scalar_server_ref
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlParam
    from l2070_batching.server_ref import inspect_server_value_shape_for_planning
    from impl.common.l7300_cross_branch.permission_expression_compiler import (
        BranchTipPermissionAnchor,
        PinnedRevisionPermissionAnchor,
    )

    effective_domain = domain if domain is not None else ctx.versioning_domain
    if effective_domain is None:
        from l1100_exceptions.exceptions import PermissionCompilationError

        msg = "Versioned permission compilation requires an explicit domain"
        raise PermissionCompilationError(msg)

    branch_id_sql = versioned_permission_branch_id_expr(ctx)
    if branch_id_sql is None:
        branch_id_sql = fallback_branch_id_sql
    if branch_id_sql is not None and ctx.lazy_branch_tip_materialization is not None:
        tip_shape = inspect_server_value_shape_for_planning(
            ctx.lazy_branch_tip_materialization,
            site="versioned_permission_anchor tip materialization",
        )
        tip_ref_id = tip_shape.symbolic_ref_id
        has_tip_binding = (
            tip_ref_id is not None
            and ctx.cte_refs is not None
            and (tip_ref_id in ctx.cte_refs or tip_ref_id.partition(".")[0] in ctx.cte_refs)
        )
        if tip_shape.has_literal_value or has_tip_binding:
            tip_materialization_sql = lower_scalar_server_ref(
                ctx.lazy_branch_tip_materialization,
                ctx,
                default_field="tip_materialization",
            )
        else:
            from impl.common.l2100_sql_grammar.domain.query.stmt_dynamic import (
                SqlDynamicSelectStmt,
            )
            from impl.common.l2100_sql_grammar.tree.enums import BinaryOp
            from impl.common.l2100_sql_grammar.tree.expr_compound import SqlSubquery
            from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef
            from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp
            from l1000_schema.schema_def import get_db_column_name
            from l1000_schema.table_utils import get_table_name
            from l1400_types import DynamicFieldName

            branch_model = effective_domain.branch_model
            tip_materialization_sql = SqlSubquery(
                SqlDynamicSelectStmt(
                    from_table=SqlTableName(get_table_name(branch_model)),
                    columns=[
                        SqlColumnName(
                            get_db_column_name(
                                branch_model,
                                DynamicFieldName("tip_materialization"),
                            ),
                        ),
                    ],
                    where_conditions=[
                        SqlBinaryOp(
                            SqlColumnRef(
                                SqlColumnName(
                                    get_db_column_name(
                                        branch_model,
                                        DynamicFieldName("sys_id"),
                                    ),
                                ),
                            ),
                            BinaryOp.EQ,
                            branch_id_sql,
                        ),
                    ],
                    limit=1,
                ),
            )
        return BranchTipPermissionAnchor(
            domain=effective_domain,
            branch_id_sql=branch_id_sql,
            tip_materialization_sql=tip_materialization_sql,
        )
    if branch_id_sql is not None and ctx.branch_tip_materialized:
        return BranchTipPermissionAnchor(
            domain=effective_domain,
            branch_id_sql=branch_id_sql,
            tip_materialized=ctx.branch_tip_materialized,
        )

    # A tipless branch has no authoritative ``*_tip`` graph row. Its write
    # transaction still carries the current revision, so graph-inherited
    # permission checks must use sparse validity at that revision rather than
    # silently filtering every node through an empty tip table.
    revision_id_sql: SqlRenderable
    if ctx.lazy_revision is not None:
        revision_shape = inspect_server_value_shape_for_planning(
            ctx.lazy_revision,
            site="versioned_permission_anchor revision",
        )
        revision_ref_id = revision_shape.symbolic_ref_id
        has_sql_binding = (
            revision_ref_id is not None
            and ctx.cte_refs is not None
            and (revision_ref_id in ctx.cte_refs or revision_ref_id.partition(".")[0] in ctx.cte_refs)
        )
        if not has_sql_binding and ctx.revision_id is not None:
            revision_id_sql = SqlParam(ctx.revision_id)
        elif not has_sql_binding and branch_id_sql is not None:
            return BranchTipPermissionAnchor(
                domain=effective_domain,
                branch_id_sql=branch_id_sql,
                tip_materialized=ctx.branch_tip_materialized,
            )
        else:
            revision_id_sql = lower_scalar_server_ref(
                ctx.lazy_revision,
                ctx,
                default_field="revision_id",
            )
    elif ctx.revision_id is not None:
        revision_id_sql = SqlParam(ctx.revision_id)
    elif fallback_branch_id_sql is not None:
        return BranchTipPermissionAnchor(
            domain=effective_domain,
            branch_id_sql=fallback_branch_id_sql,
            tip_materialized=ctx.branch_tip_materialized,
        )
    else:
        from l1100_exceptions.exceptions import PermissionCompilationError

        msg = "Versioned permission compilation requires a branch or revision anchor"
        raise PermissionCompilationError(msg)
    return PinnedRevisionPermissionAnchor(
        domain=effective_domain,
        revision_id_sql=revision_id_sql,
        branch_id_sql=fallback_branch_id_sql,
    )


