@pure_lazy
def get_write_metadata_plan_from_catalog(
    planning_catalog: object | None,
    model_cls: type[DatabaseObjectRow],
) -> _WriteMetadataPlan:
    """Return write metadata from the transaction planning snapshot."""
    if planning_catalog is None:
        msg = f"ServerPlan write compilation requires PlanningCatalog for {model_cls.__name__}"
        raise RuntimeError(msg)
    write_metadata_for_model = getattr(planning_catalog, "write_metadata_for_model", None)
    if not callable(write_metadata_for_model):
        msg = f"Expected planning catalog with write metadata, got {type(planning_catalog).__name__}"
        raise TypeError(msg)
    return cast("_WriteMetadataPlan", write_metadata_for_model(model_cls))


def _resolve_sql_conn(
    txn: object | None,
    sql_connection: object | None = None,
) -> _SqlConnectionCore | None:
    """Extract _SqlConnectionCore from a transaction or bare connection.

    Handles both:
    - Transaction objects (txn._conn -> _SqlConnectionCore)
    - Bare _SqlConnectionCore passed as txn (for conn.plan())
    - CompilationContext.sql_connection fallback when txn is wrapped/opaque
    """
    from impl.common.l2200_sql_dialect.sql_connection import _SqlConnectionCore

    seen_ids: set[int] = set()
    candidate: object | None = txn
    while candidate is not None:
        candidate_id = id(candidate)
        if candidate_id in seen_ids:
            break
        seen_ids.add(candidate_id)
        if isinstance(candidate, _SqlConnectionCore):
            return candidate
        conn: object = getattr(candidate, "_conn", None)
        if isinstance(conn, _SqlConnectionCore):
            return conn
        candidate = getattr(candidate, "_txn", getattr(candidate, "_base_txn", None))
    if isinstance(sql_connection, _SqlConnectionCore):
        return sql_connection
    return None


def filter_columns_to_existing_schema(
    schema_column_cache: Mapping[str, frozenset[str]] | None,
    table_name: SqlTableName,
    candidate_columns: Sequence[str],
) -> tuple[str, ...]:
    """Filter write columns using already-known schema metadata.

    Compile-time write lowering must not issue schema SQL or recover live
    connection state. When the executor has published a cache entry for
    ``table_name``, that snapshot is the authority and columns absent from it
    are dropped. When no cache entry is
    available, the schema is unknown to the compiler, so the model-derived
    candidate list is preserved and any true schema mismatch fails at execution.
    """
    cached = _cached_schema_columns(schema_column_cache, table_name)
    if cached is None:
        return tuple(candidate_columns)
    return tuple(column for column in candidate_columns if column in cached)


def _cached_schema_columns(
    schema_column_cache: Mapping[str, frozenset[str]] | None,
    table_name: SqlTableName,
) -> frozenset[str] | None:
    if schema_column_cache is None:
        return None
    return schema_column_cache.get(table_name)


def filter_columns_and_values_to_existing_schema(
    schema_column_cache: Mapping[str, frozenset[str]] | None,
    table_name: SqlTableName,
    columns: Sequence[str],
    values: Sequence[object],
) -> tuple[tuple[str, ...], tuple[object, ...]]:
    """Apply cached schema-column filtering to a column/value sequence."""
    cached = _cached_schema_columns(schema_column_cache, table_name)
    if cached is None:
        return tuple(columns), tuple(values)
    keep_indexes = tuple(index for index, column in enumerate(columns) if column in cached)
    if len(keep_indexes) == len(columns):
        return tuple(columns), tuple(values)
    return (
        tuple(columns[index] for index in keep_indexes),
        tuple(values[index] for index in keep_indexes),
    )


def filter_row_plans_to_existing_schema(
    schema_column_cache: Mapping[str, frozenset[str]] | None,
    table_name: SqlTableName,
    columns: Sequence[str],
    row_plans: Sequence[_ResolvedWriteRowPlan],
) -> tuple[tuple[str, ...], list[_ResolvedWriteRowPlan]]:
    """Apply cached schema-column filtering to resolved multi-row write plans."""
    cached = _cached_schema_columns(schema_column_cache, table_name)
    if cached is None:
        return tuple(columns), list(row_plans)
    keep_indexes = tuple(index for index, column in enumerate(columns) if column in cached)
    if len(keep_indexes) == len(columns):
        return tuple(columns), list(row_plans)
    return (
        tuple(columns[index] for index in keep_indexes),
        [
            _ResolvedWriteRowPlan(
                columns=tuple(row_plan.columns[index] for index in keep_indexes),
                values=tuple(row_plan.values[index] for index in keep_indexes),
            )
            for row_plan in row_plans
        ],
    )


def bind_runtime_sql_conn[R_co](
    hydrator: Hydrator[R_co],
    sql_conn: _SqlConnectionCore | None,
) -> Hydrator[R_co]:
    """Attach the runtime SQL connection to a hydrator when possible."""
    if sql_conn is None:
        return hydrator
    from l2070_batching.hydrator import bind_runtime_hydrator

    return bind_runtime_hydrator(hydrator, sql_conn=sql_conn)


def runtime_txn_handle_from_hydrator(hydrator: object) -> object | None:
    """Return the executor-owned transaction handle carried by a runtime hydrator."""
    candidate: object | None = getattr(hydrator, _RUNTIME_TXN_ATTR, None)
    if candidate is not None:
        return candidate
    txn_candidate: object | None = getattr(hydrator, "txn", None)
    if txn_candidate is not None:
        return txn_candidate
    fallback: object | None = getattr(hydrator, "_txn", None)
    return fallback


def runtime_write_txn_from_hydrator(
    hydrator: object,
) -> WriteTransaction | None:
    """Return the executor-bound write transaction, if present."""
    from l2050_transaction.transaction import WriteTransaction

    candidate = getattr(hydrator, _RUNTIME_TXN_ATTR, None)
    if isinstance(candidate, WriteTransaction):
        return candidate
    candidate = getattr(hydrator, "txn", None)
    if isinstance(candidate, WriteTransaction):
        return candidate
    candidate = getattr(hydrator, "_txn", None)
    if isinstance(candidate, WriteTransaction):
        return candidate
    return None


def base_hydrator_from_runtime(hydrator: object) -> object:
    """Unwrap runtime hydrator wrappers to the underlying caller hydrator."""
    return getattr(hydrator, "base_hydrator", getattr(hydrator, "_base_hydrator", hydrator))


def _expression_references_any_field(expr: object, field_names: frozenset[str]) -> bool:
    if isinstance(expr, (list, tuple)):
        return any(_expression_references_any_field(child, field_names) for child in expr)
    field_name = getattr(expr, "field", None)
    if field_name is not None and str(field_name) in field_names:
        return True
    field_name = getattr(expr, "name", None)
    if field_name is not None and str(field_name) in field_names:
        return True
    for attr in (
        "left",
        "right",
        "value",
        "expression",
        "source_expression",
        "func",
        "spec",
        "partition_by",
        "order_by",
    ):
        child = getattr(expr, attr, None)
        if child is not None and _expression_references_any_field(child, field_names):
            return True
    for child in getattr(expr, "args", None) or ():
        if _expression_references_any_field(child, field_names):
            return True
    return False


def _private_field_names(model_cls: type[DatabaseObjectRow]) -> frozenset[str]:
    from l1000_schema.column_visibility import ColumnVisibility, get_field_visibility
    from impl.common.l2070_server_plan.steps._permission_filter import _COLUMN_MASKING_INFRA_FIELDS

    return frozenset(
        field_name
        for field_name in model_cls.model_fields
        if get_field_visibility(model_cls, DynamicFieldName(field_name)) != ColumnVisibility.PUBLIC
        and field_name not in _COLUMN_MASKING_INFRA_FIELDS
    )


def _query_references_fields(
    query_spec: object | None,
    field_names: frozenset[str],
    *,
    extra_fields: Sequence[object] = (),
    include_select_columns: bool = False,
) -> bool:
    if not field_names:
        return False
    for field_obj in extra_fields:
        field_name = getattr(field_obj, "name", None)
        if field_name is not None and str(field_name) in field_names:
            return True
        if _expression_references_any_field(field_obj, field_names):
            return True
    if query_spec is None:
        return False
    for filter_obj in getattr(query_spec, "filters", ()) or ():
        expression = getattr(filter_obj, "expression", None)
        if expression is not None and _expression_references_any_field(expression, field_names):
            return True
        column = getattr(filter_obj, "column", None)
        if column is not None and str(column) in field_names:
            return True
        if _expression_references_any_field(filter_obj, field_names):
            return True
    for order_column, _direction in getattr(query_spec, "order_by", ()) or ():
        if _expression_references_any_field(order_column, field_names):
            return True
    for group_column in getattr(query_spec, "group_by", ()) or ():
        if _expression_references_any_field(group_column, field_names):
            return True
    for aggregation in getattr(query_spec, "aggregations", ()) or ():
        if _expression_references_any_field(aggregation, field_names):
            return True
    for having_expr in getattr(query_spec, "having", ()) or ():
        if _expression_references_any_field(having_expr, field_names):
            return True
    for window_expr, _alias in getattr(query_spec, "window_functions", ()) or ():
        if _expression_references_any_field(window_expr, field_names):
            return True
    if include_select_columns:
        for column_obj in getattr(query_spec, "select_columns", ()) or ():
            field_name = getattr(column_obj, "name", None)
            if field_name is not None and str(field_name) in field_names:
                return True
            if _expression_references_any_field(column_obj, field_names):
                return True
    return False


def query_references_private_fields(
    query_spec: object | None,
    model_cls: type[DatabaseObjectRow],
    *,
    extra_fields: Sequence[object] = (),
    include_select_columns: bool = False,
) -> bool:
    """Return whether a narrow read references any private field."""
    return _query_references_fields(
        query_spec,
        _private_field_names(model_cls),
        extra_fields=extra_fields,
        include_select_columns=include_select_columns,
    )


def _is_a_resolved_user_source(resolved_user_id: PermissionUserIdSource) -> bool:
    """Return whether this is an actual user, rather than "look it up yourself".

    ``None`` is the absence of a source, and every other shape here names a
    value the statement can reach without querying: a user id, a CTE the plan
    published, or SQL the caller built. The distinction is the whole point of
    rebinding, so it is a function rather than an inline ``is not None``.
    """
    return resolved_user_id is not None


def _attach_join_permission_grammars(
    query_spec: QuerySpec,
    ctx: CompilationContext,
    *,
    action: str,
) -> QuerySpec:
    """Attach each joined model's policy to that join's target alias."""
    joins = getattr(query_spec, "joins", None)
    if not joins or ctx.session_id is None or ctx.system_authority is not None:
        return query_spec

    from impl.common.l7300_cross_branch.permission_expression_compiler import (
        _sql_session_context_bindings,
        compile_permission_where_with_user_expr,
    )
    from l1000_schema.schema_def import DatabaseObjectRow
    from l1000_schema.table_utils import get_table_name
    from l4000_permissions.permission_enforcement import get_query_permission_plan
    from l2060_query_builder.query_contracts import JoinClause

    session_id = compilation_session_id(ctx)
    if session_id is None:
        return query_spec
    user_id_expr = session_user_id_expr(ctx.session_id, ctx)
    session_id_sql = session_id_expr(ctx.session_id, ctx)
    session_vars: Mapping[str | tuple[type, str], SqlRenderable] | None = None
    permission_context_ref = getattr(query_spec, "permission_context_ref", None)
    permission_context_type = getattr(query_spec, "permission_context_type", None)
    if permission_context_ref is not None or permission_context_type is not None:
        if permission_context_ref is None or permission_context_type is None:
            raise TypeError("Permission context ref and model type must be provided together")
        from impl.common.l2070_server_plan.steps._compile_server_ref import (
            lower_scalar_server_ref,
        )
        from l2070_batching.server_ref import ObjectServerRef, ServerRefs

        context_ref = ServerRefs.from_ref_id(
            permission_context_ref,
            variant="object",
            type_hint=permission_context_type,
        )
        if not isinstance(context_ref, ObjectServerRef):
            raise TypeError("Permission context authority must be an object ref")
        logical_bindings = _sql_session_context_bindings(
            permission_context_type,
            permission_context_ref,
        )
        lowered_fields = {
            field_name: lower_scalar_server_ref(context_ref.field(field_name), ctx) for field_name in permission_context_type.model_fields
        }
        session_vars = {key: lowered_fields[key if isinstance(key, str) else key[1]] for key in logical_bindings}
    changed = False
    rewritten_joins: list[JoinClause] = []
    for join in joins:
        target_model = join.target_model
        if not isinstance(target_model, type) or not issubclass(target_model, DatabaseObjectRow):
            rewritten_joins.append(join)
            continue
        permission_plan = get_query_permission_plan(target_model, action=action)
        grammar: SqlRenderable | None = None
        reserved_session_bypass = (
            permission_plan.bypasses_reserved_session(session_id if isinstance(session_id, SessionId) else None)
            if permission_plan is not None and session_vars is None
            else None
        )
        if permission_plan is not None and permission_plan.filter_rows and reserved_session_bypass is not True:
            target_alias = join.target_alias or str(get_table_name(target_model))
            grammar = compile_permission_where_with_user_expr(
                target_model,
                session_id,
                user_id_expr,
                table_alias=target_alias,
                action=action,
                session_id_sql=session_id_sql,
                session_vars=session_vars,
                compilation_context=ctx,
            )
        column_masking = _column_masking_for_query_spec(
            target_model,
            ctx,
            user_id_expr=user_id_expr,
        )
        if grammar is None and column_masking is None:
            rewritten_joins.append(join)
            continue
        rewritten_joins.append(
            join._with_compiled_permission(
                permission_grammar=grammar,
                column_masking=None if column_masking is None else column_masking[0],
                column_masking_user_grammar=(None if column_masking is None else column_masking[1]),
            ),
        )
        changed = True
    if not changed:
        return query_spec
    return dc_replace(query_spec, joins=rewritten_joins)


def attach_runtime_permission_grammar(
    query_spec: object,
    model_cls: type[DatabaseObjectRow],
    ctx: CompilationContext,
    *,
    resolved_user_id: PermissionUserIdSource = None,
    action: str = "read",
    attach_column_masking: bool = True,
    fallback_branch_id_sql: SqlRenderable | None = None,
    permission_table_alias: str | None = None,
) -> object | None:
    """Attach permission grammar to a query spec at compile time when needed.

    This is for internal steps that construct ad hoc specs outside the
    normal permissioned query-builder path, such as keyed updates/deletes.
    """
    if query_spec is None:
        return None
    if ctx.system_authority is not None:
        return query_spec
    wrapped_query_spec = getattr(query_spec, "query_spec", None)
    if (
        is_dataclass(query_spec)
        and not isinstance(query_spec, type)
        and wrapped_query_spec is not None
        and wrapped_query_spec is not query_spec
    ):
        effective_inner_spec = attach_runtime_permission_grammar(
            wrapped_query_spec,
            model_cls,
            ctx,
            resolved_user_id=resolved_user_id,
            action=action,
            attach_column_masking=attach_column_masking,
            fallback_branch_id_sql=fallback_branch_id_sql,
            permission_table_alias=permission_table_alias,
        )
        return dc_replace(query_spec, query_spec=effective_inner_spec)
    if isinstance(resolved_user_id, CteReference):
        resolved_user_id = materialize_permission_user_id(resolved_user_id, ctx)
    from impl.common.l2060_query_spec.query_spec import (
        QueryPermissionState,
        get_query_permission_state,
        query_has_attached_permission_grammar,
        query_has_explicit_permission_bypass,
        query_has_provider_authority_permission,
        query_has_resolved_permission_check,
        query_permission_user_id_is_unresolved,
    )

    if query_has_explicit_permission_bypass(query_spec):
        return query_spec
    from impl.common.l2060_query_spec.query_spec import QuerySpec

    if isinstance(query_spec, QuerySpec):
        query_spec = _attach_join_permission_grammars(query_spec, ctx, action=action)
    # A query builder's read check cannot authorize a later mutation.
    requires_action_refresh = action != "read"
    if query_has_provider_authority_permission(query_spec) and not requires_action_refresh:
        return query_spec
    should_refresh_attached_permission = (
        requires_action_refresh
        or ctx.versioning_domain is not None
        or ctx.backend_profile.traits.permission_user_transport is PermissionUserTransport.MATERIALIZED_VALUE
        or session_sql_source_or_none(ctx.session_id) is not None
        or getattr(model_cls, "__polymorphic__", False)
        or permission_table_alias is not None
    )
    if query_has_resolved_permission_check(query_spec) and not should_refresh_attached_permission:
        return query_spec
    # An attached predicate that still looks its user up is rebuilt here when we
    # have a value for it, on the same terms as the versioned refresh below: the
    # policy is the model's own, so compiling it again against a resolved user
    # yields the same filter without the lookup. With nothing better to offer,
    # rebuilding would only reproduce the lookup, so we leave it alone.
    should_rebind_unresolved_permission_user = query_permission_user_id_is_unresolved(query_spec) and _is_a_resolved_user_source(
        resolved_user_id,
    )
    should_refresh_attached_versioned_permission = (
        requires_action_refresh
        or ctx.versioning_domain is not None
        or should_rebind_unresolved_permission_user
        or getattr(model_cls, "__polymorphic__", False)
        or permission_table_alias is not None
        or getattr(query_spec, "permission_context_ref", None) is not None
    )
    attached_permission = get_query_permission_state(query_spec) is QueryPermissionState.ATTACHED
    tip_ref = ctx.lazy_branch_tip_materialization
    tip_binding_is_available = bool(tip_ref is not None and ctx.cte_refs is not None and str(tip_ref.ref_id) in ctx.cte_refs)
    # Reuse the plan-owned predicate after a group boundary. Recompiling here
    # would require a tip ref that the completed group no longer publishes.
    if (
        attached_permission
        and action == "read"
        and ctx.versioning_domain is not None
        and tip_ref is not None
        and not tip_binding_is_available
    ):
        return query_spec
    if attached_permission and not should_refresh_attached_versioned_permission:
        if not query_has_attached_permission_grammar(query_spec):
            msg = "Explicit attached permission state requires a permission_grammar"
            raise TypeError(msg)
        if not attach_column_masking:
            return query_spec
        return _attach_column_masking_if_needed(
            query_spec,
            model_cls,
            ctx,
            user_id_expr=session_user_id_expr(ctx.session_id, ctx) if ctx.session_id is not None else None,
        )
    if query_has_attached_permission_grammar(query_spec) and not should_refresh_attached_versioned_permission:
        if not attach_column_masking:
            return query_spec
        return _attach_column_masking_if_needed(
            query_spec,
            model_cls,
            ctx,
            user_id_expr=session_user_id_expr(ctx.session_id, ctx) if ctx.session_id is not None else None,
        )
    from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName, SqlCteStepName
    from impl.common.l2100_sql_grammar.domain.infra.stmt_dml_simple import SqlCteFieldRef
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlParam
    from impl.common.l7300_cross_branch.permission_expression_compiler import (
        compile_permission_deny_all,
        compile_permission_where_for_dml_with_user_expr,
        compile_permission_where_with_user_expr,
        compile_versioned_permission_where_for_dml_with_user_expr,
        compile_versioned_permission_where_with_user_expr,
        _sql_session_context_bindings,
        admitted_identity_sql_bindings,
    )
    from l1000_schema.table_utils import get_table_name
    from l4000_permissions.permission_enforcement import (
        is_system_or_schema_session,
        permission_scheme_is_enforcing,
        _try_get_permission_scheme,
        get_query_permission_plan,
    )

    scheme = _try_get_permission_scheme(model_cls)
    permission_plan = get_query_permission_plan(model_cls, action=action)
    if permission_plan is None or (not permission_scheme_is_enforcing(scheme) and not permission_plan.filter_rows):
        return query_spec
    user_id_expr: SqlRenderable | None = None
    if ctx.session_id is None:
        if not permission_plan.filter_rows:
            return query_spec
        permission_grammar: SqlRenderable | None = compile_permission_deny_all()
    else:
        session_id = compilation_session_id(ctx)
        if session_id is None:
            msg = "Permission compilation requires a concrete session id"
            raise TypeError(msg)
        filters_session = permission_plan.filters_session(
            session_id if isinstance(session_id, SessionId) else None,
        )
        planned_context_type = getattr(query_spec, "permission_context_type", None)
        has_application_context = bool(
            isinstance(planned_context_type, type)
            and getattr(
                planned_context_type,
                "__nera_application_session_context__",
                False,
            )
            is True
        )
        if not filters_session and not has_application_context:
            return query_spec

        permission_table_alias = permission_table_alias or get_table_name(model_cls)
        if isinstance(resolved_user_id, CteReference):
            compiled_user_cte = ctx.cte_refs.get(resolved_user_id.ref_id) if ctx.cte_refs is not None else None
            if not isinstance(compiled_user_cte, CteReference):
                compiled_user_cte = resolved_user_id
            user_id_expr = SqlCteFieldRef(
                SqlCteStepName(compiled_user_cte.ref_id),
                SqlColumnName("user_id"),
            )
        elif isinstance(resolved_user_id, SqlRenderable):
            user_id_expr = resolved_user_id
        elif isinstance(resolved_user_id, UserId):
            user_id_expr = SqlParam(resolved_user_id)
        elif resolved_user_id is None:
            user_id_expr = session_user_id_expr(ctx.session_id, ctx)
        else:
            msg = "resolved_user_id must be None, UserId, CteReference, or SqlRenderable"
            raise TypeError(msg)

        session_vars: Mapping[str | tuple[type, str], SqlRenderable] | None = None
        permission_context_ref = getattr(query_spec, "permission_context_ref", None)
        permission_context_type = getattr(query_spec, "permission_context_type", None)
        if permission_context_ref is not None or permission_context_type is not None:
            if permission_context_ref is None or permission_context_type is None:
                msg = "Permission context ref and model type must be provided together"
                raise TypeError(msg)
            from impl.common.l2070_server_plan.steps._compile_server_ref import (
                lower_scalar_server_ref,
            )

            context_ref = ServerRefs.from_ref_id(
                permission_context_ref,
                variant="object",
                type_hint=permission_context_type,
            )
            if not isinstance(context_ref, ObjectServerRef):
                msg = "Permission context authority must be an object ref"
                raise TypeError(msg)
            logical_bindings = _sql_session_context_bindings(
                permission_context_type,
                permission_context_ref,
            )
            lowered_fields = {
                field_name: lower_scalar_server_ref(
                    context_ref.field(field_name),
                    ctx,
                )
                for field_name in permission_context_type.model_fields
            }
            session_vars = {key: lowered_fields[key if isinstance(key, str) else key[1]] for key in logical_bindings}

        permission_user_id_sql, permission_session_id_sql = admitted_identity_sql_bindings(
            session_vars,
            default_user_id_sql=user_id_expr,
            default_session_id_sql=session_id_expr(ctx.session_id, ctx),
        )

        if action in {"claim", "delete", "update"}:
            if ctx.versioning_domain is not None:
                permission_grammar = compile_versioned_permission_where_for_dml_with_user_expr(
                    model_cls,
                    permission_user_id_sql,
                    action=action,
                    table_alias=permission_table_alias,
                    target_table_name=permission_table_alias,
                    version_anchor=versioned_permission_anchor(ctx),
                    session_id_sql=permission_session_id_sql,
                    session_vars=session_vars,
                    compilation_context=ctx,
                )
            else:
                permission_grammar = compile_permission_where_for_dml_with_user_expr(
                    model_cls,
                    permission_user_id_sql,
                    action=action,
                    table_alias=permission_table_alias,
                    target_table_name=permission_table_alias,
                    session_id_sql=permission_session_id_sql,
                    session_vars=session_vars,
                )
        else:
            if ctx.versioning_domain is not None:
                permission_grammar = compile_versioned_permission_where_with_user_expr(
                    model_cls,
                    session_id,
                    permission_user_id_sql,
                    table_alias=permission_table_alias,
                    action=action,
                    session_id_sql=permission_session_id_sql,
                    session_vars=session_vars,
                    version_anchor=versioned_permission_anchor(
                        ctx,
                        fallback_branch_id_sql=(
                            fallback_branch_id_sql
                            if fallback_branch_id_sql is not None
                            else SqlColumnRef(
                                SqlColumnName("branch_id"),
                                qualifier=permission_table_alias,
                            )
                        ),
                    ),
                    compilation_context=ctx,
                )
            else:
                permission_grammar = compile_permission_where_with_user_expr(
                    model_cls,
                    session_id,
                    permission_user_id_sql,
                    table_alias=permission_table_alias,
                    action=action,
                    session_id_sql=permission_session_id_sql,
                    session_vars=session_vars,
                )
    if permission_grammar is None:
        if not attach_column_masking:
            return query_spec
        return _attach_column_masking_if_needed(
            query_spec,
            model_cls,
            ctx,
            user_id_expr=user_id_expr,
        )
    if not is_dataclass(query_spec) or isinstance(query_spec, type):
        if hasattr(query_spec, "__dict__"):
            mutable_query_spec = cast(Any, query_spec)
            mutable_query_spec.permission_grammar = permission_grammar
            mutable_query_spec.permission_state = QueryPermissionState.ATTACHED
            if attach_column_masking:
                query_spec = _attach_column_masking_if_needed(
                    mutable_query_spec,
                    model_cls,
                    ctx,
                    user_id_expr=user_id_expr,
                )
            return query_spec
        msg = "attach_runtime_permission_grammar requires a mutable query_spec when permission filtering is active"
        raise TypeError(msg)
    column_masking = (
        _column_masking_for_query_spec(
            model_cls,
            ctx,
            user_id_expr=user_id_expr,
        )
        if attach_column_masking
        else None
    )
    return dc_replace(
        query_spec,
        permission_grammar=permission_grammar,
        column_masking=None if column_masking is None else column_masking[0],
        column_masking_user_grammar=None if column_masking is None else column_masking[1],
        permission_state=QueryPermissionState.ATTACHED,
    )


def _column_masking_for_query_spec(
    model_cls: type[DatabaseObjectRow],
    ctx: CompilationContext,
    *,
    user_id_expr: object,
) -> tuple[tuple[str, list[str]], object] | None:
    from impl.common.l2070_server_plan.steps._permission_filter import get_column_masking_info

    if ctx.session_id is None or user_id_expr is None:
        return None
    session_id = compilation_session_id(ctx)
    catalog_models = None if ctx.planning_catalog is None else ctx.planning_catalog.tables.keys()
    column_masking = get_column_masking_info(
        model_cls,
        session_id if isinstance(session_id, SessionId) else None,
        catalog_models=catalog_models,
    )
    if column_masking is None:
        return None
    return column_masking, user_id_expr


def _attach_column_masking_if_needed(
    query_spec: object,
    model_cls: type[DatabaseObjectRow],
    ctx: CompilationContext,
    *,
    user_id_expr: object,
) -> object:
    column_masking = _column_masking_for_query_spec(model_cls, ctx, user_id_expr=user_id_expr)
    if column_masking is None:
        return query_spec
    masking_info, masking_user = column_masking
    if not is_dataclass(query_spec) or isinstance(query_spec, type):
        if hasattr(query_spec, "__dict__"):
            mutable_query_spec = cast(Any, query_spec)
            mutable_query_spec.column_masking = masking_info
            mutable_query_spec.column_masking_user_grammar = masking_user
            return query_spec
        msg = "column masking requires a mutable query_spec"
        raise TypeError(msg)
    return dc_replace(
        query_spec,
        column_masking=masking_info,
        column_masking_user_grammar=masking_user,
    )


def resolved_permission_user_id_from_ref(
    user_id_ref_id: ServerPlanRefId | None,
    ctx: CompilationContext,
) -> ResolvedPermissionUserId:
    """Return the SQL-visible user source published for read permission lowering."""
    if user_id_ref_id is None:
        return None
    if ctx.cte_refs is None:
        raise_missing_cte_fallback_forbidden(
            site_name="resolved_permission_user_id_from_ref",
            trigger=f"permission user ref {user_id_ref_id!r} has no CTE map during compile()",
            blocked_path="permission-user SQL cannot fall back to ambient session state",
            result_contract="permission-aware compilation must consume an explicit SQL-visible user_id ref.",
            implementation_requirements=(
                "Publish SessionUserIdStep output before the permission-aware terminal.",
                "Thread the published user_id_ref_id through dependencies and compile config.",
            ),
        )
    binding = ctx.cte_refs.get(str(user_id_ref_id))
    if not isinstance(binding, CteReference):
        raise_missing_cte_fallback_forbidden(
            site_name="resolved_permission_user_id_from_ref",
            trigger=f"permission user ref {user_id_ref_id!r} has no CTE binding during compile()",
            blocked_path="permission-user SQL cannot materialize user identity in Python during compile()",
            result_contract="permission-aware compilation must consume an explicit SQL-visible user_id ref.",
            implementation_requirements=(
                "Publish SessionUserIdStep output before the permission-aware terminal.",
                "Do not read ctx.materialized_pipeline or session tables from compile().",
            ),
        )
    if "user_id" not in binding.columns:
        raise_missing_cte_fallback_forbidden(
            site_name="resolved_permission_user_id_from_ref",
            trigger=f"permission user ref {user_id_ref_id!r} does not publish a user_id column",
            blocked_path="permission-user SQL cannot infer user identity from a weak CTE binding",
            result_contract="permission-aware compilation must consume a declared user_id column.",
            implementation_requirements=(
                "Publish SessionUserIdStep output with columns=('user_id',) and complete type hints.",
                "Do not pass name-only or wrong-shaped CTE bindings for permission checks.",
            ),
        )
    return cast("ResolvedPermissionUserId", binding)


def attach_runtime_read_permission_grammar(
    query_spec: object,
    model_cls: type[DatabaseObjectRow],
    ctx: CompilationContext,
    *,
    user_id_ref_id: ServerPlanRefId | None = None,
    resolved_user_id: PermissionUserIdSource = None,
    attach_column_masking: bool = True,
) -> object | None:
    """Attach read permission grammar using the shared runtime permission binder."""
    effective_user_id = resolved_user_id if resolved_user_id is not None else resolved_permission_user_id_from_ref(user_id_ref_id, ctx)
    return attach_runtime_permission_grammar(
        query_spec,
        model_cls,
        ctx,
        resolved_user_id=effective_user_id,
        action="read",
        attach_column_masking=attach_column_masking,
    )


def _normalize_query_scope_value(value: object) -> JsonValue:
    """Convert query-spec state into a deterministic JSON-like descriptor."""
    if value is None or isinstance(value, (str, int, float, bool)):
        return value
    if isinstance(value, bytes):
        return value.hex()
    if isinstance(value, type):
        return {"type": value.__name__}
    unwrap_to_str = getattr(value, "unwrap_to_str", None)
    if callable(unwrap_to_str):
        return str(unwrap_to_str())
    unwrap_to_sql = getattr(value, "unwrap_to_sql", None)
    if callable(unwrap_to_sql):
        return str(unwrap_to_sql())
    if isinstance(value, dict):
        return {str(key): _normalize_query_scope_value(nested) for key, nested in sorted(value.items(), key=lambda item: str(item[0]))}
    if isinstance(value, (list, tuple, set, frozenset)):
        return [_normalize_query_scope_value(item) for item in value]
    if is_dataclass(value):
        return {key: _normalize_query_scope_value(nested) for key, nested in sorted(value.__dict__.items()) if not key.startswith("_")}
    value_dict = getattr(value, "__dict__", None)
    if isinstance(value_dict, dict) and value_dict:
        return {key: _normalize_query_scope_value(nested) for key, nested in sorted(value_dict.items()) if not key.startswith("_")}
    slots = getattr(type(value), "__slots__", ())
    if isinstance(slots, str):
        slots = (slots,)
    if slots:
        normalized_slots: dict[str, JsonValue] = {}
        for slot in slots:
            if slot.startswith("_"):
                continue
            try:
                normalized_slots[slot] = _normalize_query_scope_value(getattr(value, slot))
            except AttributeError:
                continue
        if normalized_slots:
            return normalized_slots
    return {"repr_type": type(value).__name__}


def _get_provenance_proof_inputs(
    model_cls: type[Any],
    *,
    session_id: str | None,
    txn: object | None,
) -> tuple[str, Literal["none", "system", "user"], PermissionManifestProofKind, str | None]:
    from l2070_batching.permission_provenance import (
        _get_user_id_for_session,
        _normalize_scheme_kind,
    )
    from l4000_permissions.permission_enforcement import (
        is_system_or_schema_session,
        _try_get_permission_scheme,
    )

    scheme = _try_get_permission_scheme(model_cls)
    if scheme is None:
        return "public", "none" if session_id is None else "user", "public", None

    if session_id is None:
        return _normalize_scheme_kind(scheme), "none", "unsigned", None

    if is_system_or_schema_session(session_id):
        return _normalize_scheme_kind(scheme), "system", "system-grant", None

    user_id = None if txn is None else _get_user_id_for_session(session_id, txn)
    return _normalize_scheme_kind(scheme), "user", "permission", user_id


def _build_query_provenance_manifest(
    query_spec: object,
    model_cls: type[DatabaseObjectRow],
    ctx: CompilationContext,
    *,
    is_count: bool,
) -> tuple[PermissionProvenanceManifestEntry, ...]:
    """Build permission provenance metadata for query-driven SQL terminals."""
    from impl.common.l2060_query_spec.query_spec import (
        query_has_explicit_permission_bypass,
        search_op_from_query_spec,
    )
    from l2070_batching.permission_provenance import (
        build_permission_provenance_manifest_entry,
        get_model_db_columns,
        resolve_permission_provenance_secret,
    )

    resolved_secret = resolve_permission_provenance_secret(ctx.permission_provenance_secret)
    if resolved_secret is None or query_spec is None:
        return ()

    row_scope_kind = (
        "permission-bypass"
        if query_has_explicit_permission_bypass(query_spec)
        else "query-spec-count"
        if is_count
        else "query-spec-select"
    )
    search_op = search_op_from_query_spec(query_spec)
    row_scope_descriptor: dict[str, JsonValue] = {
        "kind": "query_spec",
        "model": model_cls.__name__,
        "table": getattr(query_spec, "table", None),
        "is_count": is_count,
        "distinct": getattr(query_spec, "distinct", None),
        "limit": getattr(query_spec, "limit", None),
        "offset": getattr(query_spec, "offset", None),
        "filters": _normalize_query_scope_value(getattr(query_spec, "filters", None)),
        "order_by": _normalize_query_scope_value(getattr(query_spec, "order_by", None)),
        "group_by": _normalize_query_scope_value(getattr(query_spec, "group_by", None)),
        "having": _normalize_query_scope_value(getattr(query_spec, "having", None)),
        "fts_query": _normalize_query_scope_value(search_op.fts_query),
        "fts_fields": _normalize_query_scope_value(search_op.fts_fields),
        "fts_mode": _normalize_query_scope_value(search_op.fts_mode),
        "vector_index_name": _normalize_query_scope_value(search_op.vector_index_name),
        "vector_query_vec": _normalize_query_scope_value(search_op.vector_query_vec),
        "vector_k": _normalize_query_scope_value(search_op.vector_k),
        "vector_threshold": _normalize_query_scope_value(search_op.vector_threshold),
        "rrf_k": _normalize_query_scope_value(search_op.rrf_k),
        "rrf_fts_weight": _normalize_query_scope_value(search_op.rrf_fts_weight),
        "rrf_vector_weight": _normalize_query_scope_value(search_op.rrf_vector_weight),
        "rrf_fts_candidates": _normalize_query_scope_value(search_op.rrf_fts_candidates),
        "rrf_vector_candidates": _normalize_query_scope_value(search_op.rrf_vector_candidates),
    }
    return (
        build_permission_provenance_manifest_entry(
            model_cls,
            action="select",
            columns_read=get_model_db_columns(model_cls),
            columns_masked=(),
            columns_written=(),
            row_scope_kind=row_scope_kind,
            row_scope_descriptor=row_scope_descriptor,
            session_id=None if ctx.session_id is None else str(ctx.session_id),
            branch_id=BranchId(ctx.branch_id) if ctx.branch_id is not None else None,
            revision_id=RevisionId(ctx.revision_id) if ctx.revision_id is not None else None,
            txn=None,
            secret=resolved_secret,
        ),
    )


def compile_permission_grammar_with_resolved_user_id(
    model_cls: type[DatabaseObjectRow],
    session_id: SessionId | str | None,
    *,
    resolved_user_id: UserId | None,
    txn: ReadTransaction | None = None,
    table_alias: str,
    action: str = "read",
    domain: type[VersioningDomain] | None = None,
) -> SqlRenderable | None:
    """Compile permission SQL using only compile-safe inputs."""
    if session_id is None:
        return None

    from impl.common.l7300_cross_branch.permission_expression_compiler import (
        compile_permission_where_with_user_id_sql,
        compile_versioned_permission_where_with_user_id_sql,
    )
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlParam
    from l4000_permissions.permission_enforcement import (
        get_permission_scheme,
        get_query_permission_plan,
    )

    scheme = get_permission_scheme(model_cls)
    if scheme is None:
        return None

    permission_plan = get_query_permission_plan(model_cls, action=action)
    typed_session_id = session_id if isinstance(session_id, SessionId) else SessionId(session_id)
    if permission_plan is not None and not permission_plan.filters_session(typed_session_id):
        return None

    user_id_sql = SqlParam(None if resolved_user_id is None else resolved_user_id.unwrap_to_str())
    if domain is not None:
        from impl.common.l7300_cross_branch.permission_expression_compiler import (
            permission_version_anchor_from_txn,
        )

        return cast(
            "SqlRenderable | None",
            compile_versioned_permission_where_with_user_id_sql(
                model_cls,
                user_id_sql,
                table_alias,
                action=action,
                version_anchor=permission_version_anchor_from_txn(domain, txn),
                session_id_sql=session_id_expr(typed_session_id),
            ),
        )
    return cast(
        "SqlRenderable | None",
        compile_permission_where_with_user_id_sql(
            model_cls,
            user_id_sql,
            table_alias,
            action=action,
            session_id_sql=session_id_expr(typed_session_id),
        ),
    )


def compile_dml_permission_filter(
    model_cls: type[DatabaseObjectRow],
    ctx: CompilationContext,
    *,
    action: Literal["delete", "insert", "update"],
    target_table_name: str,
    table_alias: str | None = None,
    resolved_user_id: PermissionUserIdSource = None,
    user_id_ref_id: ServerPlanRefId | None = None,
    permission_context_ref: ServerPlanRefId | None = None,
    permission_context_type: type[ResolvedSessionContext] | None = None,
) -> SqlRenderable | None:
    """Compile the DML permission predicate for ServerPlan write steps."""
    from impl.common.l7300_cross_branch.permission_expression_compiler import (
        compile_permission_deny_all,
        compile_permission_where_for_dml_with_user_expr,
        compile_versioned_permission_where_for_dml_with_user_expr,
    )
    from l4000_permissions.graph_inherited_scheme import GraphInheritedPermissionScheme
    from l4000_permissions.permission_enforcement import (
        _try_get_permission_scheme,
        get_query_permission_plan,
        is_system_or_schema_session,
        permission_scheme_is_enforcing,
    )

    scheme = _try_get_permission_scheme(model_cls)
    if not permission_scheme_is_enforcing(scheme):
        return None
    permission_plan = get_query_permission_plan(model_cls, action=action)
    if permission_plan is not None and not permission_plan.filter_rows:
        return None
    if ctx.session_id is None:
        return cast("SqlRenderable | None", compile_permission_deny_all())
    permission_session_id = compilation_session_id(ctx)
    if isinstance(permission_session_id, SessionId) and permission_plan is not None:
        if not permission_plan.filters_session(permission_session_id):
            return None
    session_vars: Mapping[str | tuple[type, str], SqlRenderable] | None = None
    if permission_context_ref is not None or permission_context_type is not None:
        if permission_context_ref is None or permission_context_type is None:
            msg = "DML permission context ref and model type must be provided together"
            raise TypeError(msg)
        from impl.common.l2070_server_plan.steps.sql_projection import (
            _require_sql_visible_source_cte,
        )
        from impl.common.l7300_cross_branch.permission_expression_compiler import (
            _sql_session_context_bindings,
        )

        context_cte = _require_sql_visible_source_cte(
            ctx,
            permission_context_ref,
            site_name="DML permission context",
            result_contract="authorize the DML target from the bound context row",
        )
        session_vars = _sql_session_context_bindings(
            permission_context_type,
            ServerPlanRefId(context_cte.ref_id),
        )

    user_id_expr: SqlRenderable
    if isinstance(resolved_user_id, CteReference):
        cte_ref = ctx.cte_refs.get(str(user_id_ref_id)) if ctx.cte_refs is not None and user_id_ref_id is not None else None
        if not isinstance(cte_ref, CteReference):
            cte_ref = resolved_user_id
        if "user_id" not in cte_ref.columns:
            raise_missing_cte_fallback_forbidden(
                site_name="compile_update_permission_filter",
                trigger="permission user CTE does not publish a user_id column",
                blocked_path="DML permission SQL cannot infer user identity from a weak CTE binding",
                result_contract="DML permission compilation must consume a declared user_id column.",
                implementation_requirements=(
                    "Publish permission-user prerequisites with columns=('user_id',).",
                    "Do not pass wrong-shaped CTE bindings as resolved_user_id.",
                ),
            )
        from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName
        from impl.common.l2100_sql_grammar.domain.infra.stmt_dml_simple import SqlCteFieldRef

        user_id_expr = SqlCteFieldRef(ServerPlanRefId(cte_ref.ref_id), SqlColumnName("user_id"))
    elif isinstance(resolved_user_id, SqlRenderable):
        user_id_expr = resolved_user_id
    elif isinstance(resolved_user_id, UserId):
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlParam

        user_id_expr = SqlParam(resolved_user_id)
    else:
        user_id_expr = session_user_id_subquery(ctx)

    from impl.common.l7300_cross_branch.permission_expression_compiler import (
        admitted_identity_sql_bindings,
    )

    permission_session_id_expr = session_id_expr(ctx.session_id, ctx)
    user_id_expr, permission_session_id_expr = admitted_identity_sql_bindings(
        session_vars,
        default_user_id_sql=user_id_expr,
        default_session_id_sql=permission_session_id_expr,
    )
    if isinstance(scheme, GraphInheritedPermissionScheme):
        from impl.common.l7300_cross_branch.permission_expression_compiler import (
            _compile_graph_inherited_with_ref,
        )

        return _compile_graph_inherited_with_ref(
            model_cls,
            user_id_expr,
            table_alias or target_table_name,
            action=action,
            domain=ctx.versioning_domain,
            version_anchor=versioned_permission_anchor(ctx),
            session_id_sql=permission_session_id_expr,
        )
    if ctx.versioning_domain is not None:
        versioned_permission_filter: SqlRenderable | None = compile_versioned_permission_where_for_dml_with_user_expr(
            model_cls,
            user_id_expr,
            table_alias=table_alias or target_table_name,
            target_table_name=target_table_name,
            action=action,
            version_anchor=versioned_permission_anchor(ctx),
            session_id_sql=permission_session_id_expr,
            session_vars=session_vars,
            compilation_context=ctx,
        )
        return versioned_permission_filter
    permission_filter: SqlRenderable | None = compile_permission_where_for_dml_with_user_expr(
        model_cls,
        user_id_expr,
        table_alias=table_alias or target_table_name,
        target_table_name=target_table_name,
        action=action,
        session_id_sql=permission_session_id_expr,
        session_vars=session_vars,
    )
    return permission_filter


def compile_update_permission_filter(
    model_cls: type[DatabaseObjectRow],
    ctx: CompilationContext,
    *,
    permission_context_ref: ServerPlanRefId | None = None,
    permission_context_type: type[ResolvedSessionContext] | None = None,
) -> SqlRenderable | None:
    """Compile the standard update permission predicate for a model table."""
    from l1000_schema.table_utils import get_table_name

    return compile_dml_permission_filter(
        model_cls,
        ctx,
        target_table_name=get_table_name(model_cls),
        action="update",
        permission_context_ref=permission_context_ref,
        permission_context_type=permission_context_type,
    )


def extract_columns_and_values_from_plan_runtime(
    plan: _WriteMetadataPlan,
    instance: DatabaseObjectRow,
    *,
    backend_type: BackendType | None = None,
    supplemental_values: _SupplementalWriteValues = (),
    include_sibling_nulls: bool = False,
) -> tuple[list[str], list[Any]]:
    """Extract DB column names and parameter values using catalog metadata."""

    row_plan = _resolve_write_row_plan(
        plan,
        instance,
        backend_type=backend_type,
        supplemental_values=supplemental_values,
        include_sibling_nulls=include_sibling_nulls,
    )
    return list(row_plan.columns), list(row_plan.values)


def map_python_columns_to_db_columns_from_plan(
    plan: _WriteMetadataPlan,
    columns: list[str] | tuple[str, ...],
) -> list[str]:
    """Map Python field names to DB column names using catalog metadata."""

    return [plan.field_to_db_column.get(column, column) for column in columns]


def resolve_conflict_db_columns_from_plan(
    plan: _WriteMetadataPlan,
    conflict_columns: Sequence[object] | None,
) -> list[str]:
    """Resolve conflict columns to DB column names using catalog metadata."""

    if conflict_columns is None:
        return list(plan.default_conflict_db_columns)

    result: list[str] = []
    for column in conflict_columns:
        if isinstance(column, str):
            result.append(plan.field_to_db_column.get(column, column))
        elif hasattr(column, "name"):
            field_name = getattr(column, "name", None)
            if isinstance(field_name, str):
                result.append(plan.field_to_db_column.get(field_name, field_name))
            else:
                result.append(str(column))
        else:
            result.append(str(column))
    return result


@pure_lazy
def _coerce_value_to_planned_storage_type(field_plan: _WriteFieldPlan, value: object) -> object:
    storage_type = field_plan.widened_storage_type
    if storage_type is None or value is None:
        return value
    raw_value = value.value if isinstance(value, Enum) else value
    if storage_type is str:
        if isinstance(raw_value, bool):
            return str(int(raw_value))
        return str(raw_value)
    if storage_type is int:
        if isinstance(raw_value, bool):
            return int(raw_value)
        if isinstance(raw_value, int):
            return raw_value
        if isinstance(raw_value, float | str):
            return int(raw_value)
        msg = f"Cannot coerce {type(raw_value).__name__} to widened integer storage"
        raise TypeError(msg)
    if storage_type is float:
        if isinstance(raw_value, bool | int | float | str):
            return float(raw_value)
        msg = f"Cannot coerce {type(raw_value).__name__} to widened float storage"
        raise TypeError(msg)
    return raw_value


def _serialize_write_field_value_runtime(
    instance: DatabaseObjectRow,
    field_plan: _WriteFieldPlan,
    *,
    backend_type: BackendType | None = None,
) -> object:
    """Serialize one field value for SQL binding."""
    from l2070_batching.server_ref import (
        ServerRef,
    )
    from impl.common.l2300_json_serialization.json_serialization import (
        model_json_field_encodes_none,
        serialize_model_json_field_value,
    )
    from impl.common.l2300_json_serialization.null_byte_validation import validate_text_field_value

    value: Any = getattr(instance, field_plan.field_name, None)
    if field_plan.field_name == "sys_fts_content_hash" and value is None:
        from l5100_fts.fts_config import compute_fts_content_hash, get_fts_config

        fts_config = get_fts_config(type(instance))
        if fts_config is not None:
            value = compute_fts_content_hash(instance, fts_config)
    if field_plan.autoincrement and value is None:
        return _SKIP_WRITE_FIELD

    if isinstance(value, ServerRef):
        return value

    encodes_none = model_json_field_encodes_none(
        type(instance),
        field_plan.field_name,
    )
    if field_plan.is_json and (value is not None or encodes_none):
        value = serialize_model_json_field_value(
            type(instance),
            field_plan.field_name,
            value,
            backend_type=backend_type,
        )
    else:
        unwrap_sql_bind = getattr(value, "unwrap_sql_bind", None)
        unwrap_to_sql = getattr(value, "unwrap_to_sql", None)
        unwrap_to_str = getattr(value, "unwrap_to_str", None)
        if callable(unwrap_sql_bind) and backend_type is not None:
            value = unwrap_sql_bind(backend_type)
            if field_plan.postgres_cast_type == "VECTOR" and isinstance(value, list):
                value = "[" + ",".join(repr(float(component)) for component in value) + "]"
        elif callable(unwrap_to_sql):
            value = unwrap_to_sql()
        elif callable(unwrap_to_str):
            value = unwrap_to_str()

        value = _coerce_value_to_planned_storage_type(field_plan, value)
        validate_text_field_value(
            value,
            field_name=field_plan.field_name,
            model_name=type(instance).__name__,
            backend_type=backend_type,
        )

    return value


def _resolve_write_row_plan_runtime(
    plan: _WriteMetadataPlan,
    instance: DatabaseObjectRow,
    *,
    backend_type: BackendType | None = None,
    supplemental_values: _SupplementalWriteValues = (),
    include_sibling_nulls: bool = True,
) -> _ResolvedWriteRowPlan:
    """Resolve one instance into concrete database columns and values."""
    columns: list[str] = []
    values: list[object] = []
    instance_model_fields = type(instance).model_fields
    instance_mro = type(instance).__mro__
    for field_plan in plan.field_plans:
        owner_cls = field_plan.owner_cls
        if owner_cls not in instance_mro or field_plan.field_name not in instance_model_fields:
            if include_sibling_nulls:
                columns.append(field_plan.db_column)
                values.append(None)
            continue
        value = _serialize_write_field_value(
            instance,
            field_plan,
            backend_type=backend_type,
        )
        if value is _SKIP_WRITE_FIELD:
            continue
        columns.append(field_plan.db_column)
        values.append(value)
    pointer_values = getattr(instance, "_serverplan_large_column_pointer_values", None)
    if isinstance(pointer_values, Mapping):
        for column, value in pointer_values.items():
            if not isinstance(column, str) or column in columns:
                continue
            columns.append(column)
            values.append(value)
    for supplemental in supplemental_values:
        column_name = str(supplemental.column)
        if column_name in columns:
            msg = f"Supplemental write column {column_name!r} duplicates planned model metadata"
            raise ValueError(msg)
        columns.append(column_name)
        values.append(supplemental.value)
    return _ResolvedWriteRowPlan(columns=tuple(columns), values=tuple(values))


def _build_write_metadata_plan(
    model_cls: type[DatabaseObjectRow],
    signature: tuple[object, ...],
) -> _WriteMetadataPlan:
    """Build cached write metadata for one model class."""

    field_plans: list[_WriteFieldPlan] = []
    field_to_db_column: dict[str, str] = {}

    for policy_plan in writable_field_plans(model_cls):
        field_plans.append(
            _WriteFieldPlan(
                field_name=policy_plan.field_name,
                db_column=policy_plan.db_column,
                owner_cls=policy_plan.owner_cls,
                autoincrement=policy_plan.autoincrement,
                is_json=policy_plan.is_json,
                postgres_cast_type=postgres_storage_cast_type_for_writable_field(policy_plan),
                postgres_h14_code=postgres_h14_code_for_writable_field(policy_plan),
                widened_storage_type=widened_storage_type_for_writable_field(policy_plan),
            ),
        )
        field_to_db_column.setdefault(policy_plan.field_name, policy_plan.db_column)

    return _WriteMetadataPlan(
        schema_signature=signature,
        field_plans=tuple(field_plans),
        field_to_db_column=field_to_db_column,
        db_column_to_field={field_plan.db_column: field_plan.field_name for field_plan in field_plans},
        default_conflict_db_columns=_resolve_default_conflict_db_columns(model_cls, field_to_db_column),
    )


def postgres_cast_type_for_db_column(plan: _WriteMetadataPlan, db_column: str) -> str | None:
    """Return the PostgreSQL storage cast for a writable DB column."""
    for field_plan in plan.field_plans:
        if field_plan.db_column == db_column:
            return field_plan.postgres_cast_type
    if db_column in {"sys_created_at", "sys_updated_at"}:
        return "TIMESTAMPTZ"
    return None


def postgres_uuid_columns_for_write_plan(
    plan: _WriteMetadataPlan,
    *,
    columns: Sequence[str] | None = None,
) -> frozenset[str]:
    """Return writable columns whose PostgreSQL storage type is UUID."""
    allowed = None if columns is None else frozenset(columns)
    return frozenset(
        field_plan.db_column
        for field_plan in plan.field_plans
        if field_plan.postgres_cast_type == "UUID" and (allowed is None or field_plan.db_column in allowed)
    )


def cast_postgres_expr_for_db_column(
    *,
    backend_type: BackendType | None,
    write_plan: _WriteMetadataPlan,
    db_column: str,
    expr: SqlRenderable,
) -> SqlRenderable:
    """Cast a SQL expression to the target storage type when required."""
    if backend_type is None or (dml_parameter_transport_for_backend(backend_type) is not DmlParameterTransport.EXPLICIT_STORAGE_CASTS):
        return expr
    field_plan = next(
        (candidate for candidate in write_plan.field_plans if candidate.db_column == db_column),
        None,
    )
    if field_plan is not None and field_plan.postgres_h14_code:
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef

        if isinstance(expr, SqlColumnRef) and str(expr.column) == db_column:
            return expr
        from impl.common.l2100_sql_grammar.domain.matching_h14 import SqlH14BytesToBit
        from impl.common.l2100_sql_grammar.tree.expr_compound import SqlCast
        from l1000_schema.typed_field import parse_cast_target_type

        return SqlH14BytesToBit(SqlCast(expr, parse_cast_target_type("BYTEA")))
    cast_type = postgres_cast_type_for_db_column(write_plan, db_column)
    if cast_type is None:
        return expr
    from impl.common.l2100_sql_grammar.tree.expr_compound import SqlCast
    from l1000_schema.typed_field import parse_cast_target_type

    return SqlCast(expr, parse_cast_target_type(cast_type))


def _resolve_default_conflict_db_columns(
    model_cls: type[DatabaseObjectRow],
    field_to_db_column: dict[str, str],
) -> tuple[str, ...]:
    """Resolve the default ON CONFLICT columns for a model."""

    from l1000_schema.sql_table_config import get_sql_table_config

    table_config = get_sql_table_config(model_cls)
    if table_config is not None and table_config.primary_key is not None:
        resolved_columns: list[str] = []
        for column in table_config.primary_key.columns:
            if not isinstance(column, str):
                continue
            resolved_columns.append(field_to_db_column.get(column, column))
        return tuple(resolved_columns)

    primary_key_fields = [
        field_name
        for field_name, field_info in model_cls.model_fields.items()
        if isinstance(field_info.json_schema_extra, dict) and field_info.json_schema_extra.get("primary_key")
    ]
    if primary_key_fields:
        return tuple(field_to_db_column.get(column, column) for column in primary_key_fields)

    return ("sys_id",)


def _write_metadata_schema_signature(
    model_cls: type[DatabaseObjectRow],
) -> tuple[object, ...]:
    """Return a cheap schema fingerprint for cached write metadata."""

    all_fields = collect_physical_table_fields(model_cls)
    signature: list[object] = [
        id(model_cls),
        id(model_cls.model_fields),
        tuple(
            (
                id(owner_cls),
                id(fields),
                repr(
                    tuple(
                        sorted(
                            (str(field_name), getattr(storage_type, "__name__", repr(storage_type)))
                            for field_name, storage_type in getattr(owner_cls, "__widened_storage_types__", {}).items()
                        ),
                    ),
                )
                if isinstance(getattr(owner_cls, "__widened_storage_types__", None), dict)
                else (),
                tuple(fields),
            )
            for owner_cls, fields in collect_physical_table_model_field_maps(model_cls)
        ),
        tuple(
            (
                field_name,
                _write_metadata_field_signature(field_info),
            )
            for field_name, field_info in all_fields.items()
        ),
        _write_metadata_polymorphic_subtype_signature(model_cls),
    ]

    return tuple(signature)


def _write_metadata_polymorphic_subtype_signature(
    model_cls: type[DatabaseObjectRow],
) -> tuple[object, ...]:
    base_cls = get_polymorphic_base_class(model_cls)
    if base_cls is None:
        return ()
    registry = get_type_registry(base_cls)
    return tuple(
        (
            id(subtype),
            subtype.__module__,
            subtype.__qualname__,
            id(subtype.model_fields),
            tuple(subtype.model_fields),
        )
        for subtype in registry.get_all_subtypes()
    )


def _write_metadata_field_signature(field_info: Any) -> tuple[object, ...]:
    """Return the subset of field metadata that affects write-plan compilation."""

    extra = field_info.json_schema_extra if isinstance(field_info.json_schema_extra, dict) else {}
    metadata = field_info.metadata or []
    return (
        id(field_info),
        bool(is_derived_column(field_info)),
        bool(is_database_generated_column(field_info)),
        bool(extra.get("autoincrement")),
        bool(extra.get("fts_generated_column")),
        is_json_field(field_info),
        tuple(getattr(item, "fts_generated_column", None) for item in metadata if hasattr(item, "fts_generated_column")),
    )


def _collect_large_column_pointer_db_columns(model_cls: type[DatabaseObjectRow]) -> list[str]:
    """Collect large-column pointer DB columns for a model hierarchy."""

    candidate_models: list[type[DatabaseObjectRow]] = [model_cls]
    if is_polymorphic_class(model_cls):
        table_root = table_root_class(model_cls)
        if table_root is not None:
            candidate_models = [
                cast("type[DatabaseObjectRow]", table_root),
                *get_type_registry(cast("type[DatabaseObjectRow]", table_root)).get_all_subtypes(),
            ]

    db_columns: list[str] = []
    seen: set[str] = set()
    for candidate_model in candidate_models:
        for config in get_large_column_configs(candidate_model):
            pointer_field_name = large_column_pointer_name(config.column)
            db_column = (
                get_db_column_name(candidate_model, DynamicFieldName(pointer_field_name))
                if pointer_field_name in candidate_model.model_fields
                else pointer_field_name
            )
            if db_column in seen:
                continue
            db_columns.append(db_column)
            seen.add(db_column)
    return db_columns


def is_simple_query_spec(query_spec: Any) -> bool:
    """Check if a query spec is simple enough for grammar-based compilation.

    Returns False (fall back to execute()) when the spec uses advanced
    features like joins, FTS, vector search, aggregations, etc. that
    require the full SQL pipeline.
    """
    if query_spec is None:
        return True
    complex_attrs: list[str] = [
        "group_by",
        "aggregations",
        "having",
        "window_functions",
        "fts_query",
        "vector_index_name",
    ]
    for attr in complex_attrs:
        val: Any = getattr(query_spec, attr, None)
        if val:
            return False
    # Views and backend aux tables need special handling
    if getattr(query_spec, "is_view", False):
        return False
    return not getattr(query_spec, "is_backend_aux_table", False)


def convert_row_db_to_python(model_cls: type, row: dict[str, Any]) -> dict[str, Any]:
    """Convert a row from DB column names to Python field names.

    Used by postprocess() when the compiled path returns raw SQL rows
    with DB column names (e.g. 'sys_created_at') that need to be
    converted to Python field names (e.g. 'created_at') for model hydration.

    Also normalizes datetime string values (from JSON deserialization or
    MariaDB string returns) into timezone-aware datetime objects. This is
    needed because:
    - JSON aggregation (JsonAggregationCodegen) serializes datetimes as strings
    - MariaDB's PyMySQL may return datetime columns as strings

    Filters out columns that are not fields of ``model_cls``, so callers must
    pass the class the row actually belongs to. Passing a polymorphic base
    silently drops the subtype's columns, and the result is indistinguishable
    from a row where those columns were NULL: dispatch on the discriminator
    first, or convert against each class sharing the physical table.

    Args:
        model_cls: The model class to use for field name mapping
        row: Dictionary with DB column names as keys

    Returns:
        Dictionary with Python field names as keys
    """
    from l1000_schema.schema_def import get_python_field_name

    # Build set of datetime field names for this model so we only
    # normalize strings that correspond to datetime-typed fields.
    dt_fields: frozenset[str] = _get_datetime_fields(model_cls)
    bytes_fields: frozenset[str] = _get_bytes_fields(model_cls)
    float_fields: frozenset[str] = _get_float_fields(model_cls)
    # Only include fields that exist in the model to avoid "extra inputs not permitted"
    model_fields: set[str] = set(model_cls.model_fields.keys()) if hasattr(model_cls, "model_fields") else set()

    converted: dict[str, Any] = {}
    for db_col, value in row.items():
        if db_col in {"sys_revision_id", "sys_staged_commit_id", "sys_deleted"} and value == db_col:
            continue
        try:
            python_field = get_python_field_name(model_cls, SqlColumnName(db_col))
        except (KeyError, ValueError):
            continue  # Skip columns not in the model (e.g. type_id, internal cols)
        # Skip columns that don't correspond to model fields (e.g. FTS vector
        # columns, internal DB columns). get_python_field_name returns the input
        # as-is for unknown columns, so we must verify it's a real field.
        if model_fields and python_field not in model_fields:
            continue
        if python_field in dt_fields:
            value = _normalize_datetime_value(value)
        if python_field in bytes_fields:
            value = _normalize_bytes_value(value)
        if python_field in float_fields:
            value = _normalize_float_value(value)
        converted[python_field] = value
    return converted


def _get_float_fields(model_cls: type[DatabaseObjectRow]) -> frozenset[str]:
    """Return fields declared as float or optional float."""
    result: set[str] = set()
    for field_name, field_info in model_cls.model_fields.items():
        ann = field_info.annotation
        if ann is None:
            continue
        if ann is float:
            result.add(field_name)
            continue
        args = getattr(ann, "__args__", None)
        if args and any(a is float for a in args):
            result.add(field_name)
    return frozenset(result)


def _normalize_float_value(value: Any) -> Any:
    """Normalize database decimal values for fields declared as floats."""
    if value is None:
        return value

    if isinstance(value, Decimal):
        return float(value)
    if isinstance(value, str):
        try:
            return float(value)
        except ValueError:
            return value
    return value


def _get_datetime_fields(model_cls: type[DatabaseObjectRow]) -> frozenset[str]:
    """Return the set of field names that have a datetime-compatible type."""

    from pydantic import AwareDatetime

    result: set[str] = set()
    for field_name, field_info in model_cls.model_fields.items():
        ann = field_info.annotation
        if ann is None:
            continue
        # Check direct datetime types
        if ann in (datetime, AwareDatetime):
            result.add(field_name)
            continue
        # Check Optional[datetime] = datetime | None
        args = getattr(ann, "__args__", None)
        if args and any(a in (datetime, AwareDatetime) for a in args):
            result.add(field_name)
    return frozenset(result)


def _normalize_datetime_value(value: Any) -> Any:
    """Normalize a datetime value, parsing strings and adding UTC timezone.

    MySQL/MariaDB and JSON deserialization may return datetime values as
    strings without timezone info. This function parses them and adds UTC.
    Only called for fields known to be datetime-typed.
    """
    if value is None:
        return value

    # Already a datetime — just ensure timezone-aware
    if isinstance(value, datetime):
        if value.tzinfo is None:
            return value.replace(tzinfo=UTC)
        return value

    if not isinstance(value, str):
        return value

    # Try ISO 8601 first (handles timezone offsets like +00:00)
    try:
        dt = datetime.fromisoformat(value)
        if dt.tzinfo is None:
            return dt.replace(tzinfo=UTC)
        return dt
    except ValueError:
        pass

    # Fallback: MySQL/JSON datetime formats without timezone
    for fmt in ("%Y-%m-%d %H:%M:%S.%f", "%Y-%m-%d %H:%M:%S"):
        try:
            dt = datetime.strptime(value, fmt)
            return dt.replace(tzinfo=UTC)
        except ValueError:
            continue
    msg = f"Cannot parse datetime string {value!r}"
    raise ValueError(msg)


def _get_bytes_fields(model_cls: type[DatabaseObjectRow]) -> frozenset[str]:
    """Return model field names with bytes-compatible annotations."""
    from impl.common.l2400_blob_serialization import get_binary_columns

    return _ensure_string_frozenset(get_binary_columns(model_cls), context="binary column names")


def _ensure_string_frozenset(value: object, *, context: str) -> frozenset[str]:
    if not isinstance(value, frozenset) or not all(isinstance(item, str) for item in value):
        msg = f"Expected {context} to be a frozenset[str], got {type(value).__name__}"
        raise TypeError(msg)
    return value


def _normalize_bytes_value(value: Any) -> Any:
    """Normalize PostgreSQL bytea hex strings to real bytes."""
    from impl.common.l2400_blob_serialization import normalize_sql_binary_value

    return normalize_sql_binary_value(value)


def _server_ref_needs_cte_subquery_lowering(ref: Any) -> bool:
    """True when an unresolved ServerRef can be lowered via CTE IN-subqueries."""
    from l2070_batching.server_ref import ServerRef, inspect_server_value_shape_for_planning

    if not isinstance(ref, ServerRef):
        return False
    shape = inspect_server_value_shape_for_planning(
        ref,
        site="_server_ref_needs_cte_subquery_lowering",
    )
    return shape.symbolic_ref_id is not None


_PENDING_LAZY_SENTINEL: Any = object()
_MAX_LAZY_RESULT_PEEL_STEPS = 512


def _peel_resolved_lazy_results(value: Any) -> Any:
    """Return *value* with resolved ``LazyResult`` wrappers removed.

    Pending ``LazyResult`` instances return :data:`_PENDING_LAZY_SENTINEL` so
    callers can avoid ``hasattr(..., \"field\")`` checks that would route
    through ``LazyResult.__getattr__`` and synchronously resolve during
    server-plan lowering (deadlocking async drivers).
    """
    cur = value
    seen: set[int] = set()
    steps = 0
    while isinstance(cur, LazyResult):
        cur_id = id(cur)
        if cur_id in seen or steps >= _MAX_LAZY_RESULT_PEEL_STEPS:
            return _PENDING_LAZY_SENTINEL
        seen.add(cur_id)
        steps += 1
        state = object.__getattribute__(cur, "_state")
        if state is LazyState.PENDING or state is LazyState.ERROR:
            return _PENDING_LAZY_SENTINEL
        cur = object.__getattribute__(cur, "_value")
    return cur


def _expression_ast_value(value: Any) -> Any | None:
    """Return a safe expression-like value after peeling resolved lazy wrappers."""
    from l1000_schema.typed_field import Expression

    peeled = _peel_resolved_lazy_results(value)
    if peeled is _PENDING_LAZY_SENTINEL:
        return None
    if isinstance(peeled, Expression):
        return peeled
    return None


def _expression_ast_shape_safe(value: Any) -> bool:
    """Whether *value* should be walked like an ``Expression`` without touching pending lazy."""
    return _expression_ast_value(value) is not None


def _expression_attr(expr: Any, name: str, default: Any = None) -> Any:
    """Read an expression attribute without invoking dynamic ``__getattr__``."""
    expr_ast = _expression_ast_value(expr)
    if expr_ast is None:
        return default
    try:
        inspect.getattr_static(expr_ast, name)
    except AttributeError:
        return default
    try:
        return object.__getattribute__(expr_ast, name)
    except AttributeError:
        return default


def _has_server_ref_in_filters(query_spec: Any) -> bool:
    """Check if any filter embeds a ``ServerRef`` value that needs compile-time rewriting."""
    from l1000_schema.typed_field import Expression
    from l2070_batching.server_ref import ServerRef

    def _contains_cte_lowering_ref(value: Any) -> bool:
        stack: list[Any] = [value]
        seen_expr_asts: set[int] = set()
        while stack:
            peeled = _peel_resolved_lazy_results(stack.pop())
            if peeled is _PENDING_LAZY_SENTINEL:
                continue
            if isinstance(peeled, ServerRef):
                return True
            if isinstance(peeled, list | tuple):
                stack.extend(peeled)
                continue
            if isinstance(peeled, Expression):
                expr_ast = _expression_ast_value(peeled)
                if expr_ast is None:
                    continue
                expr_id = id(expr_ast)
                if expr_id in seen_expr_asts:
                    continue
                seen_expr_asts.add(expr_id)
                stack.append(_expression_attr(expr_ast, "left"))
                stack.append(_expression_attr(expr_ast, "right"))
                stack.append(_expression_attr(expr_ast, "value"))
                args = _expression_attr(expr_ast, "args")
                if isinstance(args, list | tuple):
                    stack.extend(args)
        return False

    def _expression_contains_cte_lowering_ref(expr: Any) -> bool:
        return _contains_cte_lowering_ref(expr)

    filters = getattr(query_spec, "filters", None)
    if not filters:
        return False
    for filter_obj in filters:
        if _contains_cte_lowering_ref(getattr(filter_obj, "value", None)):
            return True
        expression = getattr(filter_obj, "expression", None)
        if expression is not None and _expression_contains_cte_lowering_ref(expression):
            return True
        if isinstance(filter_obj, Expression) and _expression_contains_cte_lowering_ref(filter_obj):
            return True
    return False


def materialized_filter_operator_and_value(
    operator: str,
    values: Sequence[object],
) -> tuple[str, object]:
    """Preserve membership polarity when a relation materializes to values."""
    if not values:
        return ("NOT IN", []) if operator.upper() in {"NOT IN", "!=", "<>"} else ("IN", [])
    op_upper = operator.upper()
    if op_upper in {"IN", "NOT IN"}:
        return op_upper, list(values)
    if len(values) == 1:
        return operator, values[0]
    if operator in {"=", "=="}:
        return "IN", list(values)
    if operator in {"!=", "<>"}:
        return "NOT IN", list(values)
    msg = f"Cannot lower projected ServerRef filter with operator {operator!r} against {len(values)} materialized values"
    raise ValueError(msg)


def _resolve_server_ref_filters_to_cte(
    query_spec: Any,
    ctx: CompilationContext,
    *,
    table_alias: str | None = None,
    consumed_cte_refs: list[Any] | None = None,
) -> list[Any]:
    """Convert ServerRef filter values to CTE IN-subquery grammar expressions.

    For each filter whose value is a ServerRef referencing a sibling CTE step,
    generates a ``col IN (SELECT field FROM cte_name)`` grammar expression.
    The ServerRef filter is then removed from the spec's filter list so
    the QueryGrammarBuilder doesn't see it.

    Raises NotImplementedError if a ServerRef cannot be resolved via CTE refs.

    Returns:
        List of SqlIn grammar expressions to inject into WHERE.
    """
    from impl.common.l2050_sql_types.sql_branded_types import (
        JsonKey,
        SqlAliasName,
        SqlColumnName,
        SqlTableName,
    )
    from impl.common.l2100_sql_grammar.domain.infra.stmt_dml_simple import (
        SqlJsonArrayContainsSubquery,
    )
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef
    from impl.common.l2100_sql_grammar.tree.expr_ops import SqlIn
    from l1000_schema.schema_def import get_db_column_name
    from l1000_schema.typed_field import Expression
    from l2060_query_builder.query_contracts import QueryFilter
    from l2070_batching.server_ref import (
        PlanningServerValueShape,
        ServerRef,
        inspect_server_value_shape_for_planning,
    )

    filters = getattr(query_spec, "filters", None)
    if not filters:
        return []
    qualifier = SqlAliasName(table_alias) if table_alias is not None else None

    cte_refs = getattr(ctx, "cte_refs", {})
    cte_exprs: list[Any] = []
    remaining: list[Any] = []
    model_cls = query_spec.model_cls

    def _context_filter_value_for_ref(value: ScalarServerRef[Any]) -> object | None:
        type_hint = getattr(value, "_type_hint", None)
        if type_hint is BranchId and ctx.branch_id is not None:
            return cast("object | None", BranchId(ctx.branch_id))
        if type_hint is RevisionId and ctx.revision_id is not None:
            return cast("object | None", RevisionId(ctx.revision_id))
        if type_hint is SessionId and ctx.session_id is not None:
            return cast("object | None", SessionId(str(ctx.session_id)))
        return None

    def _server_ref_shape(ref: ServerRef[Any], *, site: str) -> PlanningServerValueShape:
        return inspect_server_value_shape_for_planning(ref, site=site)

    def _expr_contains_cte_lowering_server_ref(expr: Any) -> bool:
        if not isinstance(expr, Expression):
            return False
        if isinstance(expr.value, ServerRef) and _server_ref_needs_cte_subquery_lowering(expr.value):
            return True
        return _expr_contains_cte_lowering_server_ref(expr.left) or _expr_contains_cte_lowering_server_ref(
            expr.right,
        )

    def _postgres_subquery_cast_for_column(db_col: str) -> str | None:
        if ctx.backend_profile.traits.dml_parameter_transport is not DmlParameterTransport.EXPLICIT_STORAGE_CASTS:
            return None
        hints = model_sql_column_type_hints(model_cls, (db_col,))
        cast_target = hints.cast_target_for_column(db_col) if hints is not None else None
        if cast_target is None:
            return None
        return f"::{cast_target.to_sql().lower()}"

    def _build_cte_subquery_expr(
        *,
        field_name: str,
        operator: str,
        ref_value: ServerRef[Any],
        json_key: str | None = None,
    ) -> Any:
        def _scalar_cte_comparison(
            *,
            cte_name: SqlTableName,
            cte_field: SqlColumnName,
            column_expression: SqlRenderable,
        ) -> SqlRenderable | None:
            if isinstance(ref_value, ScalarSequenceServerRef):
                return None
            from impl.common.l2100_sql_grammar.domain.infra.stmt_dml_simple import SqlScalarSubquery
            from impl.common.l2100_sql_grammar.tree.enums import BinaryOp
            from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp
            from impl.common.l2100_sql_grammar.tree.clauses import SqlSelectList
            from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
            from impl.common.l2100_sql_grammar.tree.statements import SqlSelect

            operator_map = {
                "=": BinaryOp.EQ,
                "==": BinaryOp.EQ,
                "EQ": BinaryOp.EQ,
                "!=": BinaryOp.NE,
                "<>": BinaryOp.NE,
                "NE": BinaryOp.NE,
                "<": BinaryOp.LT,
                "LT": BinaryOp.LT,
                "<=": BinaryOp.LE,
                "LE": BinaryOp.LE,
                ">": BinaryOp.GT,
                "GT": BinaryOp.GT,
                ">=": BinaryOp.GE,
                "GE": BinaryOp.GE,
            }
            binary_operator = operator_map.get(operator.upper())
            if binary_operator is None:
                return None
            projected_value = cast_postgres_typed_field_expr(
                model_cls,
                field_name,
                SqlColumnRef(cte_field),
                ctx.backend_type,
            )
            scalar_query = SqlSelect(
                select=SqlSelectList([projected_value]),
                from_=SqlTableIdent(cte_name),
            )
            return SqlBinaryOp(
                column_expression,
                binary_operator,
                SqlScalarSubquery(scalar_query),
            )

        def _materialized_published_rows_filter(
            binding: Any,
            column_name: SqlColumnName,
        ) -> QueryFilter | None:
            if (
                ctx.backend_profile.traits.executor_published_relation_transport
                is not ExecutorPublishedRelationTransport.MATERIALIZED_VALUES
                and ctx.backend_profile.traits.permission_user_transport is not PermissionUserTransport.MATERIALIZED_VALUE
            ):
                return None
            from impl.common.l2100_sql_grammar.domain.infra.stmt_cte_helpers import (
                SqlPublishedRowsQuery,
            )

            auxiliary_query = binding.auxiliary_query
            if not isinstance(auxiliary_query, SqlPublishedRowsQuery):
                return None
            values = [unwrap_literal_sql_value(row[column_name]) for row in auxiliary_query.published_rows_readonly if column_name in row]
            materialized_operator, materialized_value = materialized_filter_operator_and_value(operator, values)
            return QueryFilter(
                column=field_name,
                operator=materialized_operator,
                value=materialized_value,
            )

        ref_shape = _server_ref_shape(ref_value, site="_build_cte_subquery_expr")
        ref_id = ref_shape.symbolic_ref_id
        if ref_id is None:
            return QueryFilter(
                column=field_name,
                operator=operator,
                value=ref_value,
            )
        hydrated_owner, hydrated_separator, hydrated_field = str(ref_id).partition(".hydrated.")
        if hydrated_separator and isinstance(ref_value, ScalarServerRef):
            from impl.common.l2100_sql_params.runtime_bind_slot import SqlRuntimeBindSlot

            return QueryFilter(
                column=field_name,
                operator=operator,
                value=SqlRuntimeBindSlot(ServerPlanRefId(hydrated_owner), field_name=hydrated_field),
            )
        if (
            isinstance(ref_value, ScalarSequenceServerRef)
            and ref_value.field_identity is not None
            and ref_id.startswith(("seed_", "api.binding.", "graphql.binding."))
        ):
            # Request lists use terminal parameter transport. SQL-produced
            # sequences retain their CTE binding and consumed dependency.
            return QueryFilter(
                column=field_name,
                operator=operator,
                value=ref_value,
            )
        if "." not in ref_id:
            from impl.common.l2070_server_plan.steps._compile_server_ref import lower_scalar_server_ref
            from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlParam

            if isinstance(ref_value, ScalarSequenceServerRef) or ref_id.startswith("seed_"):
                found_seed, seed_value = read_seeded_constant_from_ctx(ctx, ref_id)
                if found_seed:
                    raw_values = (
                        seed_value if isinstance(seed_value, Sequence) and not isinstance(seed_value, (str, bytes)) else (seed_value,)
                    )
                    values: list[object] = []
                    for item in raw_values:
                        if field_name and isinstance(item, dict) and field_name in item:
                            item = item[field_name]
                        elif field_name and hasattr(item, field_name):
                            item = getattr(item, field_name)
                        values.append(unwrap_literal_sql_value(item))
                    materialized_operator, materialized_value = materialized_filter_operator_and_value(operator, values)
                    return QueryFilter(
                        column=field_name,
                        operator=materialized_operator,
                        value=materialized_value,
                    )
            if isinstance(ref_value, ScalarServerRef):
                lowered_value = lower_scalar_server_ref(ref_value, ctx)
                if isinstance(lowered_value, SqlParam):
                    return QueryFilter(
                        column=field_name,
                        operator=operator,
                        value=lowered_value.value,
                    )
                # Non-literal SqlRenderable (e.g. SqlCteFieldRef pointing at a
                # published scalar CTE). Fall through to the CTE subquery path
                # below so ``sys_id = <ref>`` compiles to
                # ``sys_id IN (SELECT __result FROM published_N)`` rather than
                # being stuffed into ``QueryFilter.value`` as a parameter value
                # the driver cannot bind.
            cte_reference = cte_refs.get(ref_id)
            if cte_reference is None:
                msg = f"compile_query_grammar: sequence ServerRef {ref_id!r} has no published CTE binding for direct field filter"
                raise TypeError(msg)
            cte_name = cte_reference.ref_id
            cte_field = cte_reference.columns[0] if cte_reference.columns else "__result"
            materialized_filter = _materialized_published_rows_filter(cte_reference, SqlColumnName(cte_field))
            if materialized_filter is not None:
                return materialized_filter
            if consumed_cte_refs is not None:
                consumed_cte_refs.append(cte_reference)
            db_col = get_db_column_name(model_cls, DynamicFieldName(field_name)) if field_name else cte_field
            col_expr = SqlColumnRef(SqlColumnName(db_col), qualifier=qualifier)
            scalar_comparison = _scalar_cte_comparison(
                cte_name=SqlTableName(cte_name),
                cte_field=SqlColumnName(cte_field),
                column_expression=col_expr,
            )
            if scalar_comparison is not None:
                return scalar_comparison
            from impl.common.l2100_sql_grammar.domain.infra.stmt_dml_simple import (
                SqlCteInSubqueryRef,
            )
            from impl.common.l2100_sql_grammar.tree.clauses import SqlSelectList
            from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
            from impl.common.l2100_sql_grammar.tree.statements import SqlSelect

            if operator == "JSON_ARRAY_CONTAINS_REF":
                subq = SqlSelect(
                    select=SqlSelectList([SqlColumnRef(SqlColumnName(cte_field))]),
                    from_=SqlTableIdent(SqlTableName(cte_name)),
                )
                resolved_json_key = json_key or "id"
                return SqlJsonArrayContainsSubquery(
                    column=col_expr,
                    json_key=JsonKey(resolved_json_key),
                    subquery=subq,
                )
            negated = operator.upper() in {"NOT IN", "!=", "<>"}
            return SqlIn(
                col_expr,
                SqlCteInSubqueryRef(
                    ServerPlanRefId(cte_name),
                    SqlColumnName(cte_field),
                    postgres_cast=_postgres_subquery_cast_for_column(db_col),
                ),
                negated=negated,
            )

        found_seed, seed_value = read_seeded_constant_from_ctx(ctx, ServerPlanRefId(ref_id))
        if found_seed:
            return QueryFilter(
                column=field_name,
                operator=operator,
                value=unwrap_literal_sql_value(seed_value),
            )

        from impl.common.l2070_server_plan.steps._sql_visible_refs import resolve_sql_visible_ref

        resolved_binding = resolve_sql_visible_ref(ctx, ServerPlanRefId(ref_id))
        if resolved_binding is not None:
            cte_name = resolved_binding.cte_name
            cte_field = resolved_binding.field_name
            materialized_filter = _materialized_published_rows_filter(
                resolved_binding.binding,
                SqlColumnName(cte_field),
            )
            if materialized_filter is not None:
                return materialized_filter
            if consumed_cte_refs is not None:
                consumed_cte_refs.append(resolved_binding.binding)
            db_col = get_db_column_name(model_cls, DynamicFieldName(field_name)) if field_name else cte_field
            col_expr = SqlColumnRef(SqlColumnName(db_col), qualifier=qualifier)
            scalar_comparison = _scalar_cte_comparison(
                cte_name=SqlTableName(cte_name),
                cte_field=SqlColumnName(cte_field),
                column_expression=col_expr,
            )
            if scalar_comparison is not None:
                return scalar_comparison
            from impl.common.l2100_sql_grammar.domain.infra.stmt_dml_simple import (
                SqlCteInSubqueryRef,
            )
            from impl.common.l2100_sql_grammar.tree.clauses import SqlSelectList
            from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
            from impl.common.l2100_sql_grammar.tree.statements import SqlSelect

            if operator == "JSON_ARRAY_CONTAINS_REF":
                subq = SqlSelect(
                    select=SqlSelectList([SqlColumnRef(SqlColumnName(cte_field))]),
                    from_=SqlTableIdent(SqlTableName(cte_name)),
                )
                resolved_json_key = json_key or "id"
                return SqlJsonArrayContainsSubquery(
                    column=col_expr,
                    json_key=JsonKey(resolved_json_key),
                    subquery=subq,
                )
            negated = operator.upper() in {"NOT IN", "!=", "<>"}
            return SqlIn(
                col_expr,
                SqlCteInSubqueryRef(
                    ServerPlanRefId(cte_name),
                    SqlColumnName(cte_field),
                    postgres_cast=_postgres_subquery_cast_for_column(db_col),
                ),
                negated=negated,
            )

        base_ref, field_path = ref_id.split(".", 1)
        cte_reference = cte_refs.get(base_ref)
        if base_ref.startswith("seed_"):
            found_seed, seed_value = read_seeded_constant_from_ctx(ctx, ref_id)
            if found_seed:
                if isinstance(seed_value, Sequence) and not isinstance(seed_value, (str, bytes)):
                    values = [unwrap_literal_sql_value(item) for item in seed_value]
                else:
                    values = [unwrap_literal_sql_value(seed_value)]
                materialized_operator, materialized_value = materialized_filter_operator_and_value(operator, values)
                return QueryFilter(
                    column=field_name,
                    operator=materialized_operator,
                    value=materialized_value,
                )
        # Projection steps (e.g. ProjectScalarFieldStep) publish themselves
        # under their full dotted ref_id rather than the bare base_ref. Probe
        # the full ref_id before falling back to partition-based lookup so
        # cross-step filters resolve to an IN (SELECT ...) subquery instead of
        # raising through lower_projected_ref_field.
        full_cte_reference = cte_refs.get(ref_id) if cte_reference is None else None
        if cte_reference is None and full_cte_reference is not None:
            cte_reference = full_cte_reference
            if full_cte_reference.columns is not None and len(full_cte_reference.columns) == 1:
                field_path = full_cte_reference.columns[0]
        if cte_reference is None:
            # User-visible refs often get lowered to dotted descendants (e.g.
            # ``step_0`` lowers to ``step_0.raw`` with virtual hydrators).
            # Walk dotted descendants of the base ref to find a sibling CTE
            # that carries the projected column.
            prefix = base_ref + "."
            candidate_field = field_path.split(".")[0]
            for candidate_ref_id, candidate_binding in cte_refs.items():
                if not candidate_ref_id.startswith(prefix):
                    continue
                if not isinstance(candidate_binding, CteReference):
                    continue
                columns = candidate_binding.columns
                if columns is not None and candidate_field not in columns:
                    continue
                cte_reference = candidate_binding
                break
        if cte_reference is None:
            from impl.common.l2070_server_plan.steps._compile_server_ref import (
                lower_projected_ref_field,
            )
            from impl.common.l2070_server_plan.steps._runtime_replanning_error import (
                raise_missing_cte_fallback_forbidden,
            )

            if base_ref in ctx.materialized_pipeline or any(
                candidate_ref_id.startswith(base_ref + ".") for candidate_ref_id in ctx.materialized_pipeline
            ):
                raise_missing_cte_fallback_forbidden(
                    site_name="_resolve_server_ref_filters_to_cte",
                    trigger=f"query filter references {ref_id!r} without a SQL-visible CTE binding",
                    blocked_path="compile-time materialized_pipeline fallback for query filter ServerRefs",
                    result_contract=(
                        "query filter ServerRefs must lower through explicit CTE bindings or "
                        "seeded literal values before QueryDelete/QuerySelect compilation"
                    ),
                    implementation_requirements=(
                        "Ensure dependency collection reports the filter ServerRef before optimization.",
                        "Publish the needed projected field as a SQL-visible CTE binding.",
                        "Do not read ctx.materialized_pipeline during query filter compilation.",
                    ),
                )
            return QueryFilter(
                column=field_name,
                operator=operator,
                value=lower_projected_ref_field(ServerPlanRefId(base_ref), field_path, ctx),
            )

        cte_name = cte_reference.ref_id
        cte_field = field_path.split(".")[0]
        materialized_filter = _materialized_published_rows_filter(cte_reference, SqlColumnName(cte_field))
        if materialized_filter is not None:
            return materialized_filter
        if consumed_cte_refs is not None:
            consumed_cte_refs.append(cte_reference)
        db_col = get_db_column_name(model_cls, DynamicFieldName(field_name)) if field_name else cte_field
        col_expr = SqlColumnRef(SqlColumnName(db_col), qualifier=qualifier)
        from impl.common.l2100_sql_grammar.domain.infra.stmt_dml_simple import (
            SqlCteInSubqueryRef,
        )
        from impl.common.l2100_sql_grammar.tree.clauses import SqlSelectList
        from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
        from impl.common.l2100_sql_grammar.tree.statements import SqlSelect

        if operator == "JSON_ARRAY_CONTAINS_REF":
            subq = SqlSelect(
                select=SqlSelectList([SqlColumnRef(SqlColumnName(cte_field))]),
                from_=SqlTableIdent(SqlTableName(cte_name)),
            )
            resolved_json_key = json_key or "id"
            return SqlJsonArrayContainsSubquery(
                column=col_expr,
                json_key=JsonKey(resolved_json_key),
                subquery=subq,
            )
        negated = operator.upper() in {"NOT IN", "!=", "<>"}
        return SqlIn(
            col_expr,
            SqlCteInSubqueryRef(
                ServerPlanRefId(cte_name),
                SqlColumnName(cte_field),
                postgres_cast=_postgres_subquery_cast_for_column(db_col),
            ),
            negated=negated,
        )

    def _extract_expression_ctes(expr: Any) -> tuple[Any | None, list[Any]]:
        if not isinstance(expr, Expression):
            return expr, []
        if expr.logical_op == "AND":
            left_remaining, left_ctes = _extract_expression_ctes(expr.left)
            right_remaining, right_ctes = _extract_expression_ctes(expr.right)
            merged_ctes = [*left_ctes, *right_ctes]
            if left_remaining is not None and right_remaining is not None:
                return Expression(left=left_remaining, right=right_remaining, logical_op="AND"), merged_ctes
            if left_remaining is not None:
                return left_remaining, merged_ctes
            if right_remaining is not None:
                return right_remaining, merged_ctes
            return None, merged_ctes
        if expr.logical_op == "OR":
            left_remaining, left_ctes = _extract_expression_ctes(expr.left)
            right_remaining, right_ctes = _extract_expression_ctes(expr.right)
            if left_ctes or right_ctes:
                if left_remaining is not None or right_remaining is not None:
                    raise NotImplementedError(
                        "compile_query_grammar: mixed ServerRef and non-ServerRef filters "
                        "inside OR expressions are not supported for CTE lowering",
                    )
                from impl.common.l2100_sql_grammar.tree.expr_ops import sql_or

                return None, [sql_or(*left_ctes, *right_ctes)]
            return expr, []
        if expr.logical_op == "NOT":
            inner_remaining, inner_ctes = _extract_expression_ctes(expr.left)
            if inner_ctes:
                if inner_remaining is not None:
                    raise NotImplementedError(
                        "compile_query_grammar: mixed ServerRef and non-ServerRef filters "
                        "inside NOT expressions are not supported for CTE lowering",
                    )
                from impl.common.l2100_sql_grammar.tree.enums import UnaryOp
                from impl.common.l2100_sql_grammar.tree.expr_ops import SqlUnaryOp, sql_and

                return None, [SqlUnaryOp(UnaryOp.NOT, sql_and(*inner_ctes))]
            return expr, []
        if isinstance(expr.value, ScalarSequenceServerRef) and expr.field is not None and expr.operator in {"IN", "NOT IN"}:
            expr_value_shape: PlanningServerValueShape = _server_ref_shape(
                expr.value,
                site="_extract_expression_ctes.sequence_literal",
            )
            if expr_value_shape.symbolic_ref_id is None:
                msg = "ServerRef sequence filters must carry symbolic ref ids"
                raise TypeError(msg)
        if isinstance(expr.value, ServerRef) and expr.field is not None and expr.operator is not None:
            inner_ref = expr.value
            inner_ref_shape: PlanningServerValueShape = _server_ref_shape(
                inner_ref,
                site="_extract_expression_ctes.server_ref",
            )
            if inner_ref_shape.symbolic_ref_id is None and isinstance(inner_ref, ScalarServerRef):
                msg = "Scalar filter refs must carry symbolic ref ids"
                raise TypeError(msg)
            if not _server_ref_needs_cte_subquery_lowering(inner_ref):
                return expr, []
            rewritten = _build_cte_subquery_expr(
                field_name=expr.field,
                operator=expr.operator,
                ref_value=inner_ref,
                json_key=getattr(expr, "json_key", None),
            )
            if isinstance(rewritten, QueryFilter):
                return Expression(
                    field=expr.field,
                    operator=rewritten.operator,
                    value=rewritten.value,
                    owner=getattr(expr, "owner", None),
                ), []
            return None, [rewritten]
        return expr, []

    for f in filters:
        f_value = getattr(f, "value", None)
        f_value_shape: PlanningServerValueShape | None
        if isinstance(f_value, ServerRef):
            f_value_shape = _server_ref_shape(
                f_value,
                site="_resolve_server_ref_filters_to_cte.filter_value",
            )
        else:
            f_value_shape = None
        if isinstance(f_value, ServerRef) and f_value_shape is not None and f_value_shape.symbolic_ref_id is None:
            if isinstance(f_value, ScalarServerRef):
                context_filter_value = _context_filter_value_for_ref(f_value)
            else:
                context_filter_value = None
            if context_filter_value is not None:
                remaining.append(
                    QueryFilter(
                        column=f.column,
                        operator=getattr(f, "operator", None) or "IN",
                        value=context_filter_value,
                        expression=f.expression,
                        json_key=f.json_key,
                    ),
                )
                continue
            msg = (
                "Query filter ServerRefs must carry symbolic ref ids "
                f"(column={getattr(f, 'column', None)!r}, value_type={type(f_value).__name__}, "
                f"type_hint={getattr(f_value, '_type_hint', None)!r})"
            )
            raise TypeError(msg)
        if not isinstance(f_value, ServerRef) or not _server_ref_needs_cte_subquery_lowering(f_value):
            expr = getattr(f, "expression", None)
            if expr is None:
                remaining.append(f)
                continue
            rewritten_expr, extracted_ctes = _extract_expression_ctes(expr)
            cte_exprs.extend(extracted_ctes)
            if rewritten_expr is None:
                continue
            if rewritten_expr is expr and not extracted_ctes:
                remaining.append(f)
                continue
            remaining.append(QueryFilter(expression=rewritten_expr))
            continue

        ref_for_cte = f.value
        assert isinstance(ref_for_cte, ServerRef)
        ref_for_cte_shape: PlanningServerValueShape = _server_ref_shape(
            ref_for_cte,
            site="_resolve_server_ref_filters_to_cte.cte_value",
        )
        if ref_for_cte_shape.symbolic_ref_id is None:
            msg = "Query filter CTE refs must carry symbolic ref ids"
            raise TypeError(msg)
        rewritten = _build_cte_subquery_expr(
            field_name=f.column if f.column is not None else "",
            operator=getattr(f, "operator", None) or "IN",
            ref_value=ref_for_cte,
            json_key=getattr(f, "json_key", None),
        )
        if isinstance(rewritten, QueryFilter):
            remaining.append(rewritten)
            continue
        cte_exprs.append(rewritten)

    _replace_query_filters(query_spec, remaining)

    return cte_exprs


def _replace_query_filters(query_spec: Any, remaining: list[Any]) -> None:
    """Write back updated filters for list- or tuple-backed query specs."""
    filters = getattr(query_spec, "filters", None)
    if isinstance(filters, tuple):
        object.__setattr__(query_spec, "filters", tuple(remaining))
        return
    object.__setattr__(query_spec, "filters", list(remaining))


def _resolve_json_array_contains_literal_filters(query_spec: Any) -> list[Any]:
    """Convert literal JSON_ARRAY_CONTAINS_REF filters into SQL EXISTS expressions."""
    from impl.common.l2050_sql_types.sql_branded_types import (
        JsonKey,
        SqlAliasName,
        SqlColumnName,
    )
    from impl.common.l2100_sql_grammar.domain.infra.stmt_dml_simple import (
        SqlJsonArrayContainsSubquery,
    )
    from impl.common.l2100_sql_grammar.domain.versioning.stmt_cte import SqlUnionAll
    from impl.common.l2100_sql_grammar.tree.clauses import SqlSelectAlias, SqlSelectList
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlParam
    from impl.common.l2100_sql_grammar.tree.statements import SqlSelect
    from l1000_schema.column_utils import get_db_column_name
    from l2070_batching.server_ref import ServerRef

    filters = getattr(query_spec, "filters", None)
    if not filters:
        return []

    literal_exprs: list[Any] = []
    remaining: list[Any] = []
    model_cls = query_spec.model_cls

    for f in filters:
        if getattr(f, "operator", None) != "JSON_ARRAY_CONTAINS_REF":
            remaining.append(f)
            continue

        if isinstance(getattr(f, "value", None), ServerRef):
            remaining.append(f)
            continue

        json_field = getattr(f, "column", None)
        if not isinstance(json_field, str):
            remaining.append(f)
            continue

        values = f.value if isinstance(f.value, list) else [f.value]
        if not values:
            remaining.append(f)
            continue

        db_col = get_db_column_name(model_cls, DynamicFieldName(json_field))
        col_expr = SqlColumnRef(SqlColumnName(db_col))
        literal_queries = [
            SqlSelect(select=SqlSelectList([SqlSelectAlias(SqlParam(value), alias=SqlAliasName("sys_id"))])) for value in values
        ]
        subquery = literal_queries[0] if len(literal_queries) == 1 else SqlUnionAll(literal_queries)
        json_key = getattr(f, "json_key", None) or "id"
        literal_exprs.append(
            SqlJsonArrayContainsSubquery(
                column=col_expr,
                json_key=JsonKey(json_key),
                subquery=subquery,
            ),
        )

    _replace_query_filters(query_spec, remaining)
    return literal_exprs


def _clear_non_join_projection(query_spec: Any) -> Any:
    """Clear partial projection from a query spec while preserving DISTINCT.

    ``TupleQuery`` sets ``preserve_non_join_projection=True`` on its prepared
    spec so its auto-aliased ``_tuple_expr_<idx>`` columns survive to
    the SQL SELECT list; otherwise the extractor would be forced to fall back
    to Python-side ``Expression.evaluate``.
    """
    if getattr(query_spec, "preserve_non_join_projection", False):
        return query_spec

    select_columns = getattr(query_spec, "select_columns", None)
    if select_columns and getattr(query_spec, "distinct", False):
        return query_spec
    if select_columns and any(isinstance(column, (AliasedExpression, AliasedField)) for column in select_columns):
        return query_spec
    if select_columns:
        try:
            return dc_replace(query_spec, select_columns=None)
        except (TypeError, ValueError) as exc:
            raise NotImplementedError(
                "compile_query_grammar: failed to clear select_columns from query spec",
            ) from exc

    select = getattr(query_spec, "select", None)
    if select is None or not getattr(select, "columns", None):
        return query_spec

    try:
        cleared_select = dc_replace(select, columns=None)
    except (TypeError, ValueError):
        try:
            cleared_select = type(select)(
                columns=None,
                distinct=getattr(select, "distinct", False),
            )
        except TypeError:
            return query_spec

    try:
        return dc_replace(query_spec, select=cleared_select)
    except (TypeError, ValueError):
        return query_spec


def _expression_contains_aggregate(value: Any) -> bool:
    function = getattr(value, "function", None)
    if function is not None and str(function).upper() in {
        "AVG",
        "BOOL_AND",
        "BOOL_OR",
        "COUNT",
        "COUNT_DISTINCT",
        "JSON_AGG",
        "JSON_OBJECT_AGG",
        "MAX",
        "MIN",
        "STDDEV",
        "SUM",
        "VARIANCE",
    }:
        return True
    expression = getattr(value, "expression", None)
    if expression is not None and _expression_contains_aggregate(expression):
        return True
    for attr_name in ("args", "left", "right"):
        child = getattr(value, attr_name, None)
        if child is None:
            continue
        if isinstance(child, Sequence) and not isinstance(child, str | bytes | bytearray):
            if any(_expression_contains_aggregate(item) for item in child):
                return True
            continue
        if _expression_contains_aggregate(child):
            return True
    return False


def _query_needs_ordered_limited_aggregate_input(query_spec: Any) -> bool:
    if not (
        getattr(query_spec, "order_by", None) or getattr(query_spec, "limit", None) is not None or getattr(query_spec, "offset", None)
    ):
        return False
    if getattr(query_spec, "group_by", None) or getattr(query_spec, "having", None):
        return False
    return any(_expression_contains_aggregate(column) for column in getattr(query_spec, "select_columns", None) or ())


def _combine_where(
    base: Any | None,
    extras: list[Any],
) -> Any | None:
    """Combine a base WHERE expression with additional CTE expressions via AND."""
    from impl.common.l2100_sql_grammar.tree.expr_ops import sql_and

    combined = base
    for expr in extras:
        combined = expr if combined is None else sql_and(combined, expr)
    return combined


def _where_condition(where: Any | None) -> Any | None:
    """Extract the raw condition from either WHERE wrapper shape."""
    from impl.common.l2100_sql_grammar.tree.clauses import SqlConditionalClause

    if where is None:
        return None
    if isinstance(where, SqlConditionalClause):
        return where.condition
    return where


def _rebuild_where_like(
    original_where: Any | None,
    condition: Any | None,
) -> Any | None:
    """Rewrap a combined condition to match the original WHERE shape."""
    from impl.common.l2100_sql_grammar.tree.clauses import SqlConditionalClause, SqlWhereClause

    if condition is None:
        return None
    if isinstance(original_where, SqlConditionalClause):
        return SqlWhereClause(condition)
    return condition


def compile_query_grammar(
    query_spec: Any,
    model_cls: type[DatabaseObjectRow],
    ctx: CompilationContext,
    *,
    is_count: bool,
    contract_projection_columns: tuple[str, ...] | None = None,
    output_shape: CompiledOutputShape | None = None,
    result_relation: DeclaredResultRelation | None = None,
    column_type_hints: SqlColumnTypeHints | None = None,
    needs_returning: bool = True,
) -> CompiledStep[Any]:
    """Compile a simple query spec through QueryGrammarBuilder."""
    from impl.common.l2050_sql_types.sql_branded_types import SqlAliasName
    from impl.common.l2100_sql_grammar.stmt_fragments import SQL_COUNT_STAR_AS_COUNT
    from impl.common.l2100_sql_grammar.tree.expr_compound import SqlSubquery
    from impl.common.l2100_sql_grammar.tree.statements import SqlSelect
    from impl.common.l5200_sql_query.query_grammar import (
        QueryGrammarBuilder,
        _apply_implicit_polymorphic_type_filter,
    )
    from l2070_batching.server_ref import (
        PlanningServerValueShape,
        ServerRef,
        inspect_server_value_shape_for_planning,
    )

    if isinstance(query_spec, ServerRef):
        query_spec_shape: PlanningServerValueShape = inspect_server_value_shape_for_planning(
            query_spec,
            site="compile_query_grammar",
        )
        ref_id = query_spec_shape.symbolic_ref_id
        if ref_id is None:
            msg = "compile_query_grammar requires a seeded query spec input"
            raise TypeError(msg)
        found, seeded_query_spec = read_seeded_constant_from_ctx(ctx, ServerPlanRefId(ref_id))
        if not found:
            msg = "compile_query_grammar requires a seeded query spec input"
            raise TypeError(msg)
        query_spec = seeded_query_spec
    from l1000_schema.table_utils import get_table_name

    effective_spec = _apply_implicit_polymorphic_type_filter(query_spec)
    source = getattr(effective_spec, "source", None)
    filter_table_alias: str | None
    if getattr(effective_spec, "joins", ()):
        if source is None:
            filter_table_alias = str(get_table_name(effective_spec.model_cls))
        else:
            from impl.common.l2060_query_spec.query_source import query_source_qualifier

            filter_table_alias = str(query_source_qualifier(source))
    else:
        filter_table_alias = None
    consumed_cte_refs: list[Any] = []
    cte_exprs = _resolve_server_ref_filters_to_cte(
        effective_spec,
        ctx,
        table_alias=filter_table_alias,
        consumed_cte_refs=consumed_cte_refs,
    )
    literal_exprs = _resolve_json_array_contains_literal_filters(effective_spec)

    from impl.common.l2100_sql_grammar.domain.graph.graph_predicates import (
        graph_predicate_context_for_revision,
    )

    from impl.common.l2060_query_spec.graph_predicate_spec import contains_graph_predicates, query_filter_to_expression
    from l1000_schema.typed_field import Expression

    needs_graph_context = any(
        (expression := query_filter_to_expression(query_filter)) is not None
        and isinstance(expression, Expression)
        and contains_graph_predicates(expression)
        for query_filter in effective_spec.filters
    )
    if ctx.lazy_revision is not None and needs_graph_context:
        from impl.common.l2070_server_plan.steps._compile_server_ref import lower_scalar_server_ref
        from impl.common.l2070_server_plan.steps._compile_versioned import _graph_predicate_revision_value

        graph_revision = _graph_predicate_revision_value(
            ctx,
            revision_id=lower_scalar_server_ref(ctx.lazy_revision, ctx, default_field="revision_id"),
        )
        graph_context = graph_predicate_context_for_revision(
            RevisionId(graph_revision) if isinstance(graph_revision, str) else graph_revision,
        )
    else:
        graph_context = (
            graph_predicate_context_for_revision(RevisionId(ctx.revision_id)) if ctx.revision_id is not None else nullcontext()
        )
    stmt: SqlRenderable
    contract_projection_sources = (
        {field.output_column: field.source_db_column for field in output_shape.fields if field.source_db_column is not None}
        if output_shape is not None
        else None
    )

    def _build_select_for_spec(spec: Any, *, projection_columns: tuple[str, ...] | None) -> SqlSelect:
        builder = QueryGrammarBuilder(
            spec,
            planning_catalog=ctx.planning_catalog,
            compilation_context=ctx,
            contract_projection_columns=projection_columns,
            contract_projection_sources=contract_projection_sources,
        )
        built = builder.build_select_stmt()
        if not isinstance(built, SqlSelect):
            msg = "QueryGrammarBuilder.build_select_stmt() must return SqlSelect"
            raise TypeError(msg)
        if not (literal_exprs or cte_exprs):
            return built
        combined_condition = _combine_where(
            _where_condition(built._where),
            [*cte_exprs, *literal_exprs],
        )
        return SqlSelect(
            select_list=built._select_list,
            from_=built._from,
            joins=built._joins,
            where=_rebuild_where_like(built._where, combined_condition),
            group_by=built._group_by,
            having=built._having,
            order_by=built._order_by,
            limit=built._limit,
            offset=built._offset,
            for_update=built._for_update,
            distinct=built._distinct,
            as_of=built._as_of,
        )

    with graph_context:
        if _query_needs_ordered_limited_aggregate_input(effective_spec):
            aggregate_stmt = _build_select_for_spec(
                effective_spec,
                projection_columns=contract_projection_columns,
            )
            source_spec = dc_replace(
                effective_spec,
                select_columns=None,
                group_by=[],
                aggregations=[],
                having=[],
                window_functions=[],
                preserve_non_join_projection=False,
            )
            source_stmt = _build_select_for_spec(_clear_non_join_projection(source_spec), projection_columns=None)
            stmt = SqlSelect(
                select_list=aggregate_stmt._select_list,
                from_=SqlSubquery(source_stmt, alias=SqlAliasName("_ordered_aggregate_input")),
            )
        elif literal_exprs or cte_exprs:
            builder = QueryGrammarBuilder(
                effective_spec,
                planning_catalog=ctx.planning_catalog,
                compilation_context=ctx,
                contract_projection_columns=contract_projection_columns,
                contract_projection_sources=contract_projection_sources,
            )
            base_stmt = builder.build_select_stmt()
            if not isinstance(base_stmt, SqlSelect):
                msg = "QueryGrammarBuilder.build_select_stmt() must return SqlSelect"
                raise TypeError(msg)
            combined_condition = _combine_where(
                _where_condition(base_stmt._where),
                [*cte_exprs, *literal_exprs],
            )
            stmt = SqlSelect(
                select_list=base_stmt._select_list,
                from_=base_stmt._from,
                joins=base_stmt._joins,
                where=_rebuild_where_like(base_stmt._where, combined_condition),
                group_by=base_stmt._group_by,
                having=base_stmt._having,
                order_by=base_stmt._order_by,
                limit=base_stmt._limit,
                offset=base_stmt._offset,
                for_update=base_stmt._for_update,
                distinct=base_stmt._distinct,
                as_of=base_stmt._as_of,
            )
        else:
            stmt = QueryGrammarBuilder(
                _clear_non_join_projection(effective_spec),
                planning_catalog=ctx.planning_catalog,
                compilation_context=ctx,
                contract_projection_columns=contract_projection_columns,
                contract_projection_sources=contract_projection_sources,
            ).build_select_stmt()

    if is_count:
        stmt = SqlSelect(
            SQL_COUNT_STAR_AS_COUNT,
            SqlSubquery(stmt, alias=SqlAliasName("_merged")),
        )
    auxiliary_ctes: list[tuple[str, Any]] = []
    seen_aliases: set[str] = set()
    from impl.common.l2060_query_spec.query_spec import get_query_sql_cte_definitions
    from impl.common.l2070_server_plan.steps._auxiliary_ctes import collect_dependency_auxiliary_ctes
    from impl.common.l2070_server_plan.steps._resolve import collect_query_spec_deps

    for cte_name, cte_query in get_query_sql_cte_definitions(effective_spec):
        if cte_name in seen_aliases:
            continue
        seen_aliases.add(cte_name)
        auxiliary_ctes.append((cte_name, cte_query))
    for cte_ref_id, cte_query in collect_dependency_auxiliary_ctes(ctx, collect_query_spec_deps(effective_spec)) or ():
        if cte_ref_id in seen_aliases:
            continue
        seen_aliases.add(cte_ref_id)
        auxiliary_ctes.append((cte_ref_id, cte_query))
    for cte_ref in consumed_cte_refs:
        if cte_ref.auxiliary_query is None:
            continue
        if cte_ref.ref_id in seen_aliases:
            continue
        seen_aliases.add(cte_ref.ref_id)
        auxiliary_ctes.append((cte_ref.ref_id, cte_ref.auxiliary_query))
    from l2070_batching.compilation import require_planning_catalog
    from l2070_batching.output_shape import CompiledOutputShape, DeclaredResultRelation, synthetic_output_field
    from l2070_batching.planning_catalog import READ_FLAVOR_QUERY_ROWS, output_shape_from_read_projection
    from l2070_batching.sql_column_type_hints import SqlColumnTypeHints, model_sql_column_type_hints

    if is_count:
        output_shape = CompiledOutputShape((synthetic_output_field("count"),))
        column_type_hints = SqlColumnTypeHints(bigint_columns=frozenset({"count"}))
    else:
        if output_shape is None:
            output_shape = output_shape_from_read_projection(
                require_planning_catalog(ctx, site="compile_query_grammar output shape")
                .read_metadata_for_model(effective_spec.model_cls)
                .projection_for(READ_FLAVOR_QUERY_ROWS),
                declared_outputs=contract_projection_columns,
            )
        if column_type_hints is None:
            column_type_hints = model_sql_column_type_hints(
                effective_spec.model_cls,
                output_shape.cte_output_columns,
            )
    resolved_result_relation = result_relation or DeclaredResultRelation.from_output_shape(output_shape)
    return CompiledStep(
        grammar=stmt,
        needs_returning=needs_returning,
        output_shape=output_shape,
        result_relation=resolved_result_relation,
        column_type_hints=column_type_hints,
        auxiliary_ctes=auxiliary_ctes if auxiliary_ctes else None,
    )


def resolve_query_spec_server_refs(query_spec: Any, resolved: ResolvedRefs) -> None:
    """Resolve ``ServerRef`` values stored inside a query spec in place."""
    from impl.common.l2070_server_plan.steps._resolve import _resolve_value_recursive
    from l2070_batching.server_ref import ScalarSequenceServerRef, ServerRef

    def _resolve_value(value: Any) -> Any:
        if isinstance(value, ScalarSequenceServerRef) and value.ref_id is not None and value.field_identity is not None:
            # Schema-typed list refs are terminal runtime bindings. Preserve
            # their symbolic identity regardless of which API allocated the
            # seed. Untyped sequence refs can still resolve to CTE/literal
            # values for structural plan behavior.
            return value
        if isinstance(value, ServerRef):
            return resolved.resolve_server_ref(value)
        if isinstance(value, list):
            resolved_list_items = [_resolve_value(item) for item in value]
            return (
                resolved_list_items
                if any(new_item is not item for new_item, item in zip(resolved_list_items, value, strict=True))
                else value
            )
        if isinstance(value, tuple):
            resolved_tuple_items = tuple(_resolve_value(item) for item in value)
            return (
                resolved_tuple_items
                if any(new_item is not item for new_item, item in zip(resolved_tuple_items, value, strict=True))
                else value
            )
        return _resolve_value_recursive(value, resolved)

    def _coerce_sequence_operator(operator: Any, value: Any) -> Any:
        if not isinstance(value, list | tuple):
            return operator
        if operator == "=":
            return "IN"
        if operator == "!=":
            return "NOT IN"
        return operator

    def _resolve_expression_refs(expr: Any) -> None:
        expr_ast = _expression_ast_value(expr)
        if expr_ast is None:
            return
        expr = expr_ast
        if getattr(expr, "left", None) is not None:
            left = expr.left
            if isinstance(left, ServerRef | list | tuple):
                expr.left = _resolve_value(left)
            else:
                left_expr = _expression_ast_value(left)
                if left_expr is not None:
                    if left_expr is not left:
                        expr.left = left_expr
                    _resolve_expression_refs(left_expr)
        if getattr(expr, "right", None) is not None:
            right = expr.right
            if isinstance(right, ServerRef | list | tuple):
                expr.right = _resolve_value(right)
            else:
                right_expr = _expression_ast_value(right)
                if right_expr is not None:
                    if right_expr is not right:
                        expr.right = right_expr
                    _resolve_expression_refs(right_expr)
        expr_value = getattr(expr, "value", None)
        if isinstance(expr_value, ServerRef | list | tuple):
            expr.value = _resolve_value(expr_value)
            expr.operator = _coerce_sequence_operator(getattr(expr, "operator", None), expr.value)
        args = getattr(expr, "args", None)
        if isinstance(args, list):
            for idx, arg in enumerate(args):
                if isinstance(arg, ServerRef | list | tuple):
                    args[idx] = _resolve_value(arg)
                else:
                    arg_expr = _expression_ast_value(arg)
                    if arg_expr is not None:
                        args[idx] = arg_expr
                        _resolve_expression_refs(arg_expr)

    filters = getattr(query_spec, "filters", None)
    if filters is not None:
        updated_filters: list[Any] = []
        filters_changed = False
        for filter_obj in filters:
            original_filter_obj = filter_obj
            expression = getattr(filter_obj, "expression", None)
            expression_ast = _expression_ast_value(expression)
            if expression_ast is not None:
                _resolve_expression_refs(expression_ast)
                if expression_ast is not expression:
                    if is_dataclass(filter_obj) and not isinstance(filter_obj, type):
                        filter_obj = dc_replace(filter_obj, expression=expression_ast)
                    else:
                        mutable_filter_for_expression: Any = filter_obj
                        mutable_filter_for_expression.expression = expression_ast
            filter_value = getattr(filter_obj, "value", None)
            if filter_value is not None:
                resolved_value = _resolve_value(filter_value)
                value_changed = resolved_value is not filter_value
                resolved_operator = getattr(filter_obj, "operator", None)
                resolved_operator = _coerce_sequence_operator(resolved_operator, resolved_value)
                if value_changed or resolved_operator != getattr(filter_obj, "operator", None):
                    if is_dataclass(filter_obj) and not isinstance(filter_obj, type):
                        filter_obj = dc_replace(
                            filter_obj,
                            value=resolved_value,
                            operator=resolved_operator,
                        )
                    else:
                        mutable_filter: Any = filter_obj
                        mutable_filter.value = resolved_value
                        mutable_filter.operator = resolved_operator
            elif expression is None:
                filter_expression = _expression_ast_value(filter_obj)
                if filter_expression is not None:
                    _resolve_expression_refs(filter_expression)
            updated_filters.append(filter_obj)
            if filter_obj is not original_filter_obj:
                filters_changed = True
        if filters_changed:
            _replace_query_filters(query_spec, updated_filters)

    for attr_name in ("branch_filter", "revision_filter"):
        expr_value = getattr(query_spec, attr_name, None)
        if expr_value is None:
            continue
        if isinstance(expr_value, ServerRef | list | tuple):
            setattr(query_spec, attr_name, _resolve_value(expr_value))
            continue
        expr_ast = _expression_ast_value(expr_value)
        if expr_ast is not None:
            _resolve_expression_refs(expr_ast)
            if expr_ast is not expr_value:
                setattr(query_spec, attr_name, expr_ast)

    vector_branch_ids = getattr(query_spec, "vector_branch_ids", None)
    if isinstance(vector_branch_ids, ServerRef):
        query_spec.vector_branch_ids = resolved.resolve_server_ref(vector_branch_ids)

    field_names = (
        "joins",
        "order_by",
        "group_by",
        "aggregations",
        "having",
        "window_functions",
        "permission_grammar",
        "precomputed_fts_components",
        "vector_query_vec",
    )
    for field_name in field_names:
        value = getattr(query_spec, field_name, None)
        resolved_value = _resolve_value(value)
        if resolved_value is not value:
            object.__setattr__(query_spec, field_name, resolved_value)


def dispatch_write_subscription(
    model_cls: type[DatabaseObjectRow],
    event_type: str,
    new_row: Any,
    txn: WriteTransaction,
    *,
    old_row: Any = None,
) -> None:
    """Queue a visible-row table subscription on the current write transaction."""
    queue_visible_row = load_python_module("l5000_subscriptions.dispatcher").queue_table_event_for_visible_row
    session_id = getattr(txn, "session_id", None)
    if not isinstance(session_id, SessionId):
        msg = "Subscription dispatch requires a transaction session identity"
        raise RuntimeError(msg)
    queue_visible_row(
        txn,
        model_cls,
        event_type,
        new_row,
        session_id,
        old_row=old_row,
    )


def dispatch_write_subscription_from_runtime(
    model_cls: type[DatabaseObjectRow],
    event_type: str,
    new_row: Any,
    hydrator: object,
    *,
    old_row: Any = None,
    fallback_txn: object | None = None,
) -> None:
    """Dispatch using the executor-owned runtime transaction when available."""
    runtime_txn = runtime_write_txn_from_hydrator(hydrator) or fallback_txn
    if runtime_txn is None:
        return
    if old_row is None:
        dispatch_write_subscription(
            model_cls,
            event_type,
            new_row,
            cast("WriteTransaction", runtime_txn),
        )
        return
    dispatch_write_subscription(
        model_cls,
        event_type,
        new_row,
        cast("WriteTransaction", runtime_txn),
        old_row=old_row,
    )


def runtime_subscription_after_hydrate(
    model_cls: type[DatabaseObjectRow],
    event_type: str,
    *,
    old_row: Any = None,
) -> Callable[[Any, object], None]:
    """Build an after-hydrate hook that dispatches from executor-owned runtime state."""

    def _after_hydrate(result: Any, hydrator: object) -> None:
        dispatch_write_subscription_from_runtime(
            model_cls,
            event_type,
            result,
            hydrator,
            old_row=old_row,
        )

    return _after_hydrate


def _to_row_dict(row: Any) -> dict[str, Any]:
    """Normalize a row-like object to a plain dict."""
    return dict(row) if not isinstance(row, dict) else row


def hydrate_dict_one_post_op(
    model_cls: type[DatabaseObjectRow],
    returning_columns: list[str] | None = None,
) -> Any:
    """Post-op: convert first row to dict (no hydrator); filter columns if given."""

    def post_op(raw_result: Any, hydrator: Any) -> dict[str, Any] | None:
        del hydrator
        if not raw_result:
            return None
        row_dict = _to_row_dict(raw_result[0])
        if returning_columns is not None:
            row_dict = {k: v for k, v in row_dict.items() if k in returning_columns}
        converted = convert_row_db_to_python(model_cls, row_dict)
        if returning_columns is not None:
            converted = {k: v for k, v in converted.items() if k in returning_columns}
        return _stringify_uuid_sys_id(dict(converted))

    return post_op


def _stringify_uuid_sys_id(row: dict[str, Any]) -> dict[str, Any]:
    if isinstance(row.get("sys_id"), UUID):
        row["sys_id"] = str(row["sys_id"])
    return row


def hydrate_dict_many_post_op(
    model_cls: type[DatabaseObjectRow],
    returning_columns: list[str] | None = None,
) -> Any:
    """Post-op: convert all rows to dicts; filter columns if given."""

    def post_op(raw_result: Any, hydrator: Any) -> list[dict[str, Any]]:
        del hydrator
        result: list[dict[str, Any]] = []
        for raw_row in raw_result:
            row_dict = _to_row_dict(raw_row)
            if returning_columns is not None:
                row_dict = {k: v for k, v in row_dict.items() if k in returning_columns}
            converted = convert_row_db_to_python(model_cls, row_dict)
            if returning_columns is not None:
                converted = {k: v for k, v in converted.items() if k in returning_columns}
            result.append(_stringify_uuid_sys_id(dict(converted)))
        return result

    return post_op


def hydrate_cross_branch_with_meta_post_op(
    model_cls: type[DatabaseObjectRow],
) -> Any:
    """Post-op: hydrate rows and extract cross-branch metadata columns."""

    def post_op(raw_result: Any, hydrator: Any) -> Any:
        from l7000_versioned_schema.versioned_schema import BranchId, RevisionId

        models: list[Any] = []
        metas: list[Any] = []
        for row in raw_result:
            row_dict: dict[str, Any] = dict(row)
            branch_id_val: object | None = row_dict.pop("__branch_id", None)
            branch_name_val: str = str(row_dict.pop("__branch_name", ""))
            revision_id_val: object | None = row_dict.pop("__revision_id", None)
            converted = convert_row_db_to_python(model_cls, row_dict)
            models.append(hydrator(model_cls, converted))
            from l7000_versioned_schema.cross_branch import CrossBranchMeta

            metas.append(
                CrossBranchMeta(
                    branch_id=BranchId(str(branch_id_val)) if branch_id_val is not None else BranchId(""),
                    branch_name=BranchName(branch_name_val),
                    revision_id=(RevisionId(str(revision_id_val)) if revision_id_val is not None else RevisionId("")),
                ),
            )
        return models, metas

    return post_op


