def _with_query_permission_context(
    contract: StepPlanningContract,
    query_spec: object,
) -> StepPlanningContract:
    context_ref = getattr(query_spec, "permission_context_ref", None)
    if context_ref is None:
        return contract
    if not isinstance(context_ref, str):
        msg = "Query permission context ref must be a ServerPlanRefId"
        raise TypeError(msg)
    return replace(
        contract,
        session_context=SessionContextRequirement(
            scope=SessionContextScope.TRANSACTION,
            validated_session_ref=None,
            permission_context_ref=ServerPlanRefId(context_ref),
        ),
    )


class _QueryPermissionPlanningMixin:
    query_spec: Any

    def planning_contract(self: _QueryPermissionPlanningMixin) -> StepPlanningContract:
        step = cast("ServerPlanStep[Any]", self)
        return _with_query_permission_context(
            ServerPlanStep.planning_contract(step),
            self.query_spec,
        )


def _literal_insert_sys_id_ref_from_lowering_cache(
    sys_id: ScalarServerRef[SysId],
    ctx: LoweringContext,
) -> ScalarServerRef[SysId]:
    ref_id = sys_id.ref_id
    if ref_id is None or not ref_id.endswith(".sys_id"):
        return sys_id
    base_ref = ref_id.removesuffix(".sys_id")
    literal_sys_id = ctx._lowering_cache.get(f"literal_sys_id_for_step:{base_ref}")
    if literal_sys_id is None:
        return sys_id
    return cast("ScalarServerRef[SysId]", ServerRefs.scalar(literal_sys_id))


def _branch_ref_from_context_or_resolve(
    ctx: LoweringContext,
    ref_id: ServerPlanRefId,
    revision_ref: ScalarServerRef[RevisionId],
) -> tuple[list[ServerPlanStep[Any]], ServerPlanRefId]:
    from impl.common.l2070_server_plan.steps.resolve_branch_steps import (
        ResolveLiteralBranchStep,
        ResolveBranchForRevisionStep,
    )
    from impl.common.l2070_server_plan.steps.versioned_query_steps import (
        _ProjectVersionedRevisionPrereqStep,
        _VersionedRevisionPrereqConfig,
    )

    assert ctx.branch_table is not None, "Versioned read lowering context must have branch_table"
    lazy_branch = ctx.lazy_branch
    lazy_branch_ref_id = getattr(lazy_branch, "ref_id", None)
    if lazy_branch_ref_id is not None and str(lazy_branch_ref_id):
        return [], ServerPlanRefId(lazy_branch_ref_id)
    if ctx.branch_id is not None:
        return [ResolveLiteralBranchStep(ref_id, BranchId(ctx.branch_id))], ref_id

    revision_source = revision_ref
    revision_prereq_steps: list[ServerPlanStep[Any]] = []
    revision_ref_id = getattr(revision_ref, "ref_id", None)
    revision_ref_text = "" if revision_ref_id is None else str(revision_ref_id)
    if (
        revision_ref_text
        and "." in revision_ref_text
        and not revision_ref_text.startswith("seed_")
        and not revision_ref_text.startswith("step_")
    ):
        published_revision_ref = _synthetic_step_ref_id(ref_id, "revision_prereq")
        revision_prereq_steps.append(
            _ProjectVersionedRevisionPrereqStep(
                published_revision_ref,
                config=_VersionedRevisionPrereqConfig(source_ref=ServerPlanRefId(revision_ref_text)),
            )
        )
        revision_source = ServerRefs.from_ref_id(
            published_revision_ref,
            variant="scalar",
            type_hint=RevisionId,
        )
    versioning_domain = ctx.versioning_domain
    if versioning_domain is None:
        msg = "revision branch resolution requires a versioning domain"
        raise TypeError(msg)
    return [
        *revision_prereq_steps,
        ResolveBranchForRevisionStep(
            ref_id,
            revision_source,
            SqlTableName(ctx.branch_table),
            index_table=get_table_name(versioning_domain.revision_branch_index_model),
            branch_id_column=ctx.branch_id_column,
            tip_revision_column=ctx.branch_tip_revision_column,
            deleted_column=ctx.branch_deleted_column,
            current_branch_source=(
                ctx.lazy_branch if ctx.lazy_branch is not None else BranchId(ctx.branch_id) if ctx.branch_id is not None else None
            ),
        ),
    ], ref_id


def _versioned_query_branch_and_revision_inputs(
    *,
    ctx: LoweringContext,
    ref_id: ServerPlanRefId,
) -> tuple[list[ServerPlanStep[Any]], str | None, ServerPlanRefId | None, RevisionId | None, ServerPlanRefId | None]:
    revision_id = RevisionId(ctx.revision_id) if ctx.revision_id is not None else None
    if ctx.branch_id is not None:
        return [], ctx.branch_id, None, revision_id, None

    assert ctx.lazy_revision is not None
    lazy_revision_ref = ServerRefs.scalar(revision_id) if revision_id is not None else ctx_lazy_revision_ref(ctx)
    branch_steps, branch_ref = _branch_ref_from_context_or_resolve(
        ctx,
        ref_id,
        lazy_revision_ref,
    )
    if branch_ref is not None:
        return branch_steps, None, branch_ref, revision_id, None
    revision_ref_id = _context_revision_ref_id_for_read(ctx, lazy_revision_ref, revision_id)
    emitted_revision_prereq = any(step.exports_revision_prerequisite_projection() for step in branch_steps)
    if emitted_revision_prereq and revision_ref_id is not None and not str(revision_ref_id).startswith("seed_"):
        revision_ref_id = _synthetic_step_ref_id(ref_id, "revision_prereq")
    return branch_steps, None, branch_ref, revision_id, revision_ref_id


def _write_branch_source_for_context(ctx: LoweringContext) -> str | ScalarServerRef[BranchId] | None:
    if ctx.branch_id is not None:
        return ctx.branch_id
    return ctx.lazy_branch


def _merged_select_revision_after_refs(ctx: LoweringContext) -> frozenset[ServerPlanRefId]:
    if not ctx.prefer_tip_merged or ctx.is_write_transaction or ctx.lazy_revision is None:
        return frozenset()
    return frozenset(ServerPlanRefId(dependency) for dependency in ctx_lazy_revision_ref(ctx).dependencies())


def _versioned_query_publication_flavor_for_context(ctx: LoweringContext) -> str | None:
    if ctx.staged_commit_id is not None or ctx.prefer_tip_merged:
        return READ_FLAVOR_QUERY_ROWS
    return None


def _coerce_column_masking(
    column_masking: tuple[str, list[str]] | None,
) -> tuple[SqlColumnName, list[SqlColumnName]] | None:
    if column_masking is None:
        return None
    masked_column, source_columns = column_masking
    return SqlColumnName(masked_column), [SqlColumnName(column) for column in source_columns]


def _coerce_session_id(session_id_str: str | None) -> SessionId | None:
    if session_id_str is None:
        return None
    return SessionId(session_id_str)


def _coerce_optional_session_id(session_id: object | None) -> SessionId | None:
    if session_id is None:
        return None
    if isinstance(session_id, SessionId):
        return session_id
    if isinstance(session_id, str):
        return SessionId(session_id)
    return None


def _coerce_ref_id(ref_id: ServerPlanRefId | str) -> ServerPlanRefId:
    if isinstance(ref_id, ServerPlanRefId):
        return ref_id
    return ServerPlanRefId(ref_id)


def _synthetic_step_ref_id(base_ref_id: ServerPlanRefId | str, suffix: str) -> ServerPlanRefId:
    digest = hashlib.sha256(f"{base_ref_id}:{suffix}".encode("utf-8")).digest()
    return ServerPlanRefId(f"step_{int.from_bytes(digest[:8], 'big')}")


def _require_session_scalar_ref(session_id: object | None) -> ScalarServerRef[SessionId]:
    if isinstance(session_id, ScalarServerRef):
        return session_id
    if isinstance(session_id, SessionId):
        return ServerRefs.scalar(session_id)
    if isinstance(session_id, str):
        return ServerRefs.scalar(SessionId(session_id))
    shape = inspect_server_value_shape_for_planning(
        session_id,
        site="session user resolution session source",
    )
    if shape.symbolic_ref_id is not None:
        return ServerRefs.from_ref_id(
            shape.symbolic_ref_id,
            variant="scalar",
            type_hint=SessionId,
        )
    msg = "session user resolution requires a concrete session id"
    raise RuntimeError(msg)


def _coerce_revision_ref(revision_id: object | None) -> ScalarServerRef[RevisionId] | None:
    if revision_id is None:
        return None
    if isinstance(revision_id, ScalarServerRef):
        return revision_id
    return ServerRefs.scalar(cast(RevisionId, revision_id))


def _context_revision_ref_id_for_read(
    ctx: LoweringContext,
    lazy_revision_ref: ScalarServerRef[RevisionId],
    revision_literal: RevisionId | None,
) -> ServerPlanRefId | None:
    if revision_literal is not None:
        return None
    if ctx.prefer_tip_strategy and ctx.branch_tip_materialized and ctx.explicit_revision_id is None:
        return None
    return None if lazy_revision_ref.ref_id is None else ServerPlanRefId(lazy_revision_ref.ref_id)


def _shared_session_user_resolution(
    *,
    owner_ref_id: ServerPlanRefId,
    ctx: LoweringContext,
) -> tuple[list[ServerPlanStep[Any]], ServerPlanRefId]:
    cache_key = "permission_session_user_resolution_ref"
    cached_ref = ctx._lowering_cache.get(cache_key)
    if isinstance(cached_ref, ServerPlanRefId):
        return [], cached_ref
    user_id_ref_id = ServerPlanRefId(f"{owner_ref_id}_resolve_uid")
    ctx._lowering_cache[cache_key] = user_id_ref_id
    from impl.common.l2070_server_plan.steps.session_user_id import SessionUserIdStep

    session_source = session_sql_source_or_none(ctx.session_id)
    session_id = session_source if session_source is not None else _require_session_scalar_ref(ctx.session_id)
    return [SessionUserIdStep(user_id_ref_id, session_id)], user_id_ref_id


def _query_permission_needs_user_resolution(query_spec: object) -> bool:
    if getattr(query_spec, "skip_permission_filtering", False):
        return False
    if getattr(query_spec, "permission_context_ref", None) is not None:
        return False
    if query_has_attached_permission_grammar(query_spec):
        return query_permission_user_id_is_unresolved(query_spec)
    return True


def _build_session_user_resolution(
    *,
    owner_ref_id: ServerPlanRefId,
    model_cls: type[DatabaseObjectRow],
    ctx: LoweringContext,
    permission_filtering_enabled: bool,
    query_spec: object | None = None,
) -> tuple[list[ServerPlanStep[Any]], ServerPlanRefId | None]:
    from impl.common.l2060_query_spec.subqueries import query_has_semantic_subquery

    if query_spec is not None and query_has_semantic_subquery(query_spec):
        return _shared_session_user_resolution(owner_ref_id=owner_ref_id, ctx=ctx)
    if not _requires_session_user_resolution(
        model_cls,
        ctx.session_id,
        permission_filtering_enabled=permission_filtering_enabled,
    ):
        return [], None
    return _shared_session_user_resolution(
        owner_ref_id=owner_ref_id,
        ctx=ctx,
    )


def _build_required_session_user_resolution(
    *,
    owner_ref_id: ServerPlanRefId,
    ctx: LoweringContext,
    permission_filtering_enabled: bool,
) -> tuple[list[ServerPlanStep[Any]], ServerPlanRefId | None]:
    if not permission_filtering_enabled:
        return [], None
    return _shared_session_user_resolution(
        owner_ref_id=owner_ref_id,
        ctx=ctx,
    )


def _permission_dependency_refs_for_query(
    ctx: LoweringContext,
    *,
    permission_filtering_enabled: bool,
    query_spec: QuerySpec[Any] | None,
) -> frozenset[ServerPlanRefId]:
    if not permission_filtering_enabled:
        return frozenset()
    dependency_refs: set[ServerPlanRefId] = set()
    query_model_cls = None if query_spec is None else getattr(query_spec, "model_cls", None)
    if query_spec is not None and (query_model_cls is None or issubclass(query_model_cls, VersionedObjectRow)):
        for authority, site in (
            (ctx.lazy_branch, "query permission branch context"),
            (
                ctx.lazy_branch_tip_materialization,
                "query permission branch tip materialization",
            ),
        ):
            if authority is None:
                continue
            shape = inspect_server_value_shape_for_planning(authority, site=site)
            dependency_refs.update(ServerPlanRefId(ref_id) for ref_id in shape.dependency_refs)
            if shape.symbolic_ref_id is not None:
                dependency_refs.add(ServerPlanRefId(shape.symbolic_ref_id))
    permission_context_ref = None if query_spec is None else getattr(query_spec, "permission_context_ref", None)
    if permission_context_ref is not None:
        dependency_refs.add(permission_context_ref)
    return frozenset(dependency_refs)


def _requires_session_user_resolution(
    model_cls: type[DatabaseObjectRow],
    session_id: PlanningSessionId | None,
    *,
    permission_filtering_enabled: bool,
) -> bool:
    """Return whether the plan must resolve this session's user id.

    Resolving it costs a round trip of its own -- ``SessionUserIdStep`` is a
    separate statement against ``sys_sessions`` -- so the answer should be no
    whenever nothing downstream will read the result. Both compile paths that
    consume it (``attach_runtime_permission_grammar`` and
    ``compile_dml_permission_filter``) return before touching the user id when
    the model's scheme is absent or ``NoSecurityScheme``, so asking that same
    question here is what keeps the two in step.

    Having a scheme is a weaker condition than having a predicate, so the
    policy is asked as well: a scheme whose policy for this action is
    ``PERMISSION_TRUE`` compiles to no filter, and a user resolved for it is a
    round trip spent on a value no SQL will mention.

    Drift between the two is safe in the direction that matters: if this says no
    and a predicate turns out to want a user after all, the compile path falls
    back to an inline ``SELECT user_id ... LIMIT 1`` subquery inside the main
    statement, which is correct and costs no extra round trip. Saying yes when
    nothing reads it is the wasteful direction, and it is the one this guards.

    The step is still lowered for a concrete non-system session, and the read it
    costs is a duplicate: the same plan validates that session, reading the row
    this column belongs to. Removing it here is not the fix, and was tried --
    the predicate then falls back to the inline subquery, which trades a round
    trip for a correlated lookup in every filtered statement and rests on that
    lookup being reachable from every query shape, including versioned and
    spill reads. What removes the read honestly is a validated user the query
    can bind, which is NER-879's remaining work; until there is one, this step
    is how the value gets there.
    """
    from l4000_permissions.permission_enforcement import (
        get_query_permission_plan,
        model_has_enforcing_permission_scheme,
        model_policy_admits_everyone,
    )

    if not isinstance(model_cls, type):
        msg = (
            "Expected model_cls to be a type during permission resolution, got "
            f"{type(model_cls).__module__}.{type(model_cls).__qualname__}"
        )
        raise TypeError(msg)
    if session_id is None or not permission_filtering_enabled:
        return False
    if not model_has_enforcing_permission_scheme(model_cls) or model_policy_admits_everyone(model_cls):
        return False
    permission_plan = get_query_permission_plan(model_cls, action="read")
    if permission_plan is None or not permission_plan.filter_rows or not permission_plan.requires_user_id:
        return False
    # Symbolic sessions use the same SQL-visible user projection as concrete
    # sessions. The validation optimizer re-sources it from the validated row,
    # preserving one fused statement without materializing identity in Python.
    if session_sql_source_or_none(session_id) is not None:
        return True
    session_value: object = session_id
    if isinstance(session_value, ScalarServerRef):
        session_shape = inspect_server_value_shape_for_planning(
            session_value,
            site="_requires_session_user_resolution",
        )
        if not session_shape.has_literal_value:
            return True
        session_value = session_shape.literal_value
    elif not isinstance(session_value, SessionId | str):
        session_shape = inspect_server_value_shape_for_planning(
            session_value,
            site="_requires_session_user_resolution",
        )
        if session_shape.symbolic_ref_id is not None and not session_shape.has_literal_value:
            return True
        if session_shape.has_literal_value:
            session_value = session_shape.literal_value
    return True


@dataclass(frozen=True)
