def _with_catalog_default_projection(
    query_spec: Any,
    model_cls: type[DatabaseObjectRow],
    ctx: LoweringContext,
) -> Any:
    """Freeze ordinary model acquisition before publication planning."""
    from impl.common.l2060_query_spec.query_source import AliasedSource, LogicalTableSource
    from l1000_schema.table_utils import get_table_name
    from l1050_polymorphism.type_registry import is_polymorphic_class

    if not isinstance(query_spec, QuerySpec) or ctx.planning_catalog is None or not is_polymorphic_class(model_cls):
        return query_spec
    if query_spec.default_projection_columns is not None:
        return query_spec
    source = query_spec.source
    while isinstance(source, AliasedSource):
        source = source.source
    if source is not None and (not isinstance(source, LogicalTableSource) or source.model_cls is not model_cls):
        return query_spec
    if query_spec.table is not None and query_spec.table != str(get_table_name(model_cls)):
        return query_spec
    projection = ctx.planning_catalog.read_metadata_for_model(model_cls).projection_for(
        READ_FLAVOR_QUERY_ROWS,
    )
    return replace(
        query_spec,
        default_projection_columns=tuple(SqlColumnName(column) for column in projection.cte_output_columns),
    )


class SelectOneIntent[T](IntentStep[T | None]):
    """L4: Select a single row by primary key."""

    intent_tags = frozenset({"read", "select_one", "intent"})
    intent_read_only = True
    model_cls: type[DatabaseObjectRow]
    sys_id: ScalarServerRef[SysId]
    permission_grammar: Any
    column_masking: tuple[str, list[str]] | None
    session_id_str: str | None
    permission_bypass: bool
    publish_raw_rows: bool

    def __init__(
        self: SelectOneIntent,
        ref_id: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        sys_id: ScalarServerRef[SysId],
        config: _SelectOneConfig,
    ) -> None:
        super().__init__(ref_id)
        self.model_cls = model_cls
        self.sys_id = sys_id
        self.permission_grammar = config.permission_grammar
        self.column_masking = config.column_masking
        self.session_id_str = config.session_id_str
        self.permission_bypass = config.permission_bypass
        self.publish_raw_rows = config.publish_raw_rows

    def lower(self: SelectOneIntent, ctx: LoweringContext) -> Sequence[ServerPlanStep[Any]]:
        return _lower_select_one_intent(
            ref_id=self.ref_id,
            model_cls=self.model_cls,
            sys_id=self.sys_id,
            permission_grammar=self.permission_grammar,
            column_masking=self.column_masking,
            session_id_str=self.session_id_str,
            permission_bypass=self.permission_bypass,
            publish_raw_rows=self.publish_raw_rows,
            ctx=ctx,
        )

    def sql_relation_publication_ref(self) -> ServerPlanRefId:
        """Return the producer-owned raw SQL relation publication."""
        return ServerPlanRefId(f"{self.ref_id}.raw")

    def publication_result_ref(self: SelectOneIntent) -> ServerPlanRefId | None:
        if self.publish_raw_rows:
            return ServerPlanRefId(f"{self.ref_id}.raw_rows")
        return None

    def dependencies(self: SelectOneIntent) -> frozenset[str]:
        return self.sys_id.dependencies()

    def dependency_contract(self: SelectOneIntent) -> StepDependencyContract:
        return StepDependencyContract.from_refs(
            self.sys_id.dependencies(),
            source=DependencySource.DIRECT_FIELD,
            required_for=frozenset({DependencyUse.ORDERING, DependencyUse.TRANSPORT_GRAPH}),
            transport=TransportDependencyPolicy.TRANSPORTABLE,
            reason="select-one sys_id source",
        )


def _lower_select_one_intent(
    *,
    ref_id: ServerPlanRefId,
    model_cls: type[DatabaseObjectRow],
    sys_id: ScalarServerRef[SysId],
    permission_grammar: Any,
    column_masking: tuple[str, list[str]] | None,
    session_id_str: str | None,
    permission_bypass: bool,
    publish_raw_rows: bool,
    ctx: LoweringContext,
) -> Sequence[ServerPlanStep[Any]]:
    from impl.common.l2070_server_plan.steps._versioned_routing import (
        get_versioned_read_info,
        is_versioned_operation,
    )
    from impl.common.l2070_server_plan.steps.large_column_read import (
        build_select_one_query_spec,
        lower_spill_read_for_backend,
        should_lower_spill_read,
    )
    from impl.common.l2070_server_plan.steps.select_one import SelectOneStep

    causal_sys_id_refs = frozenset(ServerPlanRefId(ref_id) for ref_id in sys_id.dependencies())
    sys_id = _literal_insert_sys_id_ref_from_lowering_cache(sys_id, ctx)
    is_versioned = is_versioned_operation(model_cls, ctx)
    permission_filtering_enabled = not permission_bypass and (permission_grammar is not None or column_masking is not None)
    if is_versioned:
        from impl.common.l2070_server_plan.steps.versioned_select_one import (
            analyze_versioned_select_one_permissions,
        )

        catalog_models = None if ctx.planning_catalog is None else ctx.planning_catalog.tables.keys()
        permission_filtering_enabled = analyze_versioned_select_one_permissions(
            model_cls,
            ctx.session_id,
            catalog_models=catalog_models,
            permission_bypass=permission_bypass,
        ).needs_permission_user_ref

    if is_versioned:
        steps, user_id_ref_id = _build_required_session_user_resolution(
            owner_ref_id=ref_id,
            ctx=ctx,
            permission_filtering_enabled=permission_filtering_enabled,
        )
    else:
        steps, user_id_ref_id = _build_session_user_resolution(
            owner_ref_id=ref_id,
            model_cls=model_cls,
            ctx=ctx,
            permission_filtering_enabled=permission_filtering_enabled,
        )

    if is_versioned:
        info = get_versioned_read_info(model_cls)

        sv = sys_id
        historical_revision_id = ctx.explicit_revision_id
        if (
            historical_revision_id is None
            and not ctx.is_write_transaction
            and ctx.staging_ctx_factory is None
            and not ctx.prefer_tip_merged
            and not (ctx.prefer_tip_strategy and ctx.branch_tip_materialized and ctx.explicit_revision_id is None)
        ):
            # Read-only plan batches set is_write_transaction=False; versioned writes set
            # staging_ctx_factory and must not pin to ctx.revision_id (sparse read).
            # Read-side staged overlays also must not pin to the published tip revision,
            # or ``observe_staged_from`` collapses to sparse history and hides staging.
            historical_revision_id = ctx.revision_id

        # When revision_id is set (write txn with base_revision_id),
        # read from the sparse table at that specific revision
        if historical_revision_id is not None and ctx.branch_id is not None:
            from impl.common.l2070_server_plan.steps.large_column_read import should_lower_spill_read
            from impl.common.l2070_server_plan.steps.versioned_select_one import (
                VersionedReadSelectOneRawStep,
                VersionedReadSelectOneStep,
                _VersionedReadSelectOneConfig,
                build_versioned_select_one_query_spec,
                lower_versioned_spill_aware_select_one_steps,
            )
            from l7000_versioned_schema.versioned_schema import BranchId as _BranchId
            from l7000_versioned_schema.versioned_schema import RevisionId as _RevisionId

            query_spec = build_versioned_select_one_query_spec(
                model_cls,
                sys_id=sys_id,
                permission_state_override=(QueryPermissionState.BYPASS if permission_bypass else None),
            )
            if not publish_raw_rows and not should_lower_spill_read(
                ctx=ctx,
                model_cls=model_cls,
                query_spec=query_spec,
                raw_mode=False,
                versioned=True,
            ):
                return [
                    *steps,
                    VersionedReadSelectOneStep(
                        ref_id,
                        model_cls,
                        sv,
                        _VersionedReadSelectOneConfig(
                            sparse_table_name=SqlTableName(info.sparse_table),
                            branch_id=_BranchId(ctx.branch_id),
                            revision_id=_RevisionId(historical_revision_id),
                            type_ids=tuple(info.type_ids) if info.type_ids is not None else None,
                            user_id_ref_id=user_id_ref_id,
                            permission_bypass=permission_bypass,
                        ),
                    ),
                ]
            return [
                *steps,
                *lower_versioned_spill_aware_select_one_steps(
                    ctx=ctx,
                    ref_id=ref_id,
                    model_cls=model_cls,
                    query_spec=query_spec,
                    raw_step=VersionedReadSelectOneRawStep(
                        ref_id=ServerPlanRefId(f"{ref_id}.raw"),
                        model_cls=model_cls,
                        sys_id=sv,
                        config=_VersionedReadSelectOneConfig(
                            sparse_table_name=SqlTableName(info.sparse_table),
                            branch_id=_BranchId(ctx.branch_id),
                            revision_id=_RevisionId(historical_revision_id),
                            type_ids=tuple(info.type_ids) if info.type_ids is not None else None,
                            user_id_ref_id=user_id_ref_id,
                            permission_bypass=permission_bypass,
                        ),
                    ),
                ),
            ]

        if ctx.branch_id is not None and (ctx.staging_ctx_factory is not None or ctx.prefer_tip_merged):
            # Write transactions (``staging_ctx_factory`` is published by
            # ``LazyVersionedWriteTransaction``) need to see their own staged work
            # merged with tip. Read-side ``observe_staged_from`` overlays carry
            # ``prefer_tip_merged`` without a staging factory and use the same
            # staged+tip grammar with a CONNECTION-scoped staged filter.
            from impl.common.l2070_server_plan.steps.large_column_read import should_lower_spill_read
            from impl.common.l2070_server_plan.steps.versioned_select_one import (
                VersionedSelectOneRawStep,
                VersionedSelectOneStep,
                _VersionedSelectOneConfig,
                build_versioned_select_one_query_spec,
                lower_versioned_spill_aware_select_one_steps,
            )
            from impl.common.l2070_server_plan.steps.versioned_query_steps import (
                build_versioned_query_from_spec_steps,
                VersionedQueryFromSpecStep,
                _VersionedQueryFromSpecConfig,
            )

            query_spec = build_versioned_select_one_query_spec(
                model_cls,
                sys_id=sys_id,
                permission_state_override=(QueryPermissionState.BYPASS if permission_bypass else None),
            )
            has_multitable_sources = False
            if ctx.planning_catalog is not None:
                has_multitable_sources = bool(
                    ctx.planning_catalog.read_metadata_for_model(model_cls).multitable_source_models,
                )
            if (
                ctx.staging_ctx_factory is not None
                and not ctx.branch_tip_materialized
                and (ctx.explicit_revision_id is not None or has_multitable_sources)
            ):
                return [
                    *steps,
                    *lower_versioned_spill_aware_select_one_steps(
                        ctx=ctx,
                        ref_id=ref_id,
                        model_cls=model_cls,
                        query_spec=query_spec,
                        raw_step=VersionedQueryFromSpecStep(
                            ServerPlanRefId(f"{ref_id}.raw"),
                            model_cls,
                            _VersionedQueryFromSpecConfig(
                                query_spec=query_spec,
                                branch_id=ctx.branch_id,
                                revision_id=(RevisionId(ctx.revision_id) if ctx.revision_id is not None else None),
                                user_id_ref_id=user_id_ref_id,
                                raw_mode=True,
                            ),
                        ),
                    ),
                ]
            if not publish_raw_rows and not should_lower_spill_read(
                ctx=ctx,
                model_cls=model_cls,
                query_spec=query_spec,
                raw_mode=False,
                versioned=True,
            ):
                return [
                    *steps,
                    VersionedSelectOneStep(
                        ref_id,
                        model_cls,
                        sv,
                        _VersionedSelectOneConfig(
                            staged_table_name=SqlTableName(info.staged_table),
                            tip_table_name=SqlTableName(info.tip_table),
                            common_columns=tuple(SqlColumnName(name) for name in info.common_columns),
                            branch_id=_write_branch_source_for_context(ctx),
                            type_ids=tuple(info.type_ids) if info.type_ids is not None else None,
                            user_id_ref_id=user_id_ref_id,
                            permission_bypass=permission_bypass,
                            after_refs=_merged_select_revision_after_refs(ctx),
                        ),
                    ),
                ]
            return [
                *steps,
                *lower_versioned_spill_aware_select_one_steps(
                    ctx=ctx,
                    ref_id=ref_id,
                    model_cls=model_cls,
                    query_spec=query_spec,
                    raw_step=VersionedSelectOneRawStep(
                        ServerPlanRefId(f"{ref_id}.raw"),
                        model_cls,
                        sv,
                        _VersionedSelectOneConfig(
                            staged_table_name=SqlTableName(info.staged_table),
                            tip_table_name=SqlTableName(info.tip_table),
                            common_columns=tuple(SqlColumnName(name) for name in info.common_columns),
                            branch_id=_write_branch_source_for_context(ctx),
                            type_ids=tuple(info.type_ids) if info.type_ids is not None else None,
                            user_id_ref_id=user_id_ref_id,
                            permission_bypass=permission_bypass,
                            after_refs=_merged_select_revision_after_refs(ctx),
                        ),
                    ),
                ),
            ]

        if ctx.branch_id is not None and (
            ctx.revision_id is None
            or ctx.explicit_revision_id is None
            or ctx.staging_ctx_factory is not None
            or (ctx.prefer_tip_strategy and ctx.branch_tip_materialized and ctx.explicit_revision_id is None)
        ):
            from impl.common.l2070_server_plan.steps.resolve_branch_steps import (
                ResolveBranchTipRevisionStep,
            )
            from impl.common.l2070_server_plan.steps.large_column_read import should_lower_spill_read
            from impl.common.l2070_server_plan.steps.versioned_select_one import (
                VersionedReadSelectOneRawStep,
                VersionedReadSelectOneStep,
                _VersionedReadSelectOneConfig,
                build_versioned_select_one_query_spec,
                lower_versioned_spill_aware_select_one_steps,
            )
            from l2070_batching.server_ref import ServerRefs
            from l7000_versioned_schema.versioned_schema import BranchId as _BranchId
            from l7000_versioned_schema.versioned_schema import RevisionId as _RevisionId

            query_spec = build_versioned_select_one_query_spec(
                model_cls,
                sys_id=sys_id,
                permission_state_override=(QueryPermissionState.BYPASS if permission_bypass else None),
            )
            assert ctx.branch_table is not None, "Versioned branch-tip select_one requires branch_table"
            tip_ref = ServerPlanRefId(f"{ref_id}.tip_revision")
            tip_revision_ref = ServerRefs.from_ref_id(
                tip_ref,
                variant="scalar",
                type_hint=_RevisionId,
            )
            tip_step = ResolveBranchTipRevisionStep(
                tip_ref,
                branch_id=ServerRefs.scalar(_BranchId(ctx.branch_id)),
                branch_table=SqlTableName(ctx.branch_table),
                branch_id_column=ctx.branch_id_column,
                tip_revision_column=ctx.branch_tip_revision_column,
            )
            if publish_raw_rows or should_lower_spill_read(
                ctx=ctx,
                model_cls=model_cls,
                query_spec=query_spec,
                raw_mode=False,
                versioned=True,
            ):
                return [
                    *steps,
                    tip_step,
                    *lower_versioned_spill_aware_select_one_steps(
                        ctx=ctx,
                        ref_id=ref_id,
                        model_cls=model_cls,
                        query_spec=query_spec,
                        raw_step=VersionedReadSelectOneRawStep(
                            ServerPlanRefId(f"{ref_id}.raw"),
                            model_cls,
                            sv,
                            _VersionedReadSelectOneConfig(
                                sparse_table_name=SqlTableName(info.sparse_table),
                                branch_id=_BranchId(ctx.branch_id),
                                revision_ref=tip_revision_ref,
                                permission_historical=False,
                                type_ids=tuple(info.type_ids) if info.type_ids is not None else None,
                                user_id_ref_id=user_id_ref_id,
                                permission_bypass=permission_bypass,
                            ),
                        ),
                    ),
                ]
            return [
                *steps,
                tip_step,
                VersionedReadSelectOneStep(
                    ref_id,
                    model_cls,
                    sv,
                    _VersionedReadSelectOneConfig(
                        sparse_table_name=SqlTableName(info.sparse_table),
                        branch_id=_BranchId(ctx.branch_id),
                        revision_ref=tip_revision_ref,
                        permission_historical=False,
                        type_ids=tuple(info.type_ids) if info.type_ids is not None else None,
                        user_id_ref_id=user_id_ref_id,
                        permission_bypass=permission_bypass,
                    ),
                ),
            ]

        from impl.common.l2070_server_plan.steps.large_column_read import should_lower_spill_read
        from impl.common.l2070_server_plan.steps.versioned_select_one import (
            VersionedReadSelectOneRawStep,
            VersionedReadSelectOneStep,
            _VersionedReadSelectOneConfig,
            build_versioned_select_one_query_spec,
            lower_versioned_spill_aware_select_one_steps,
        )

        assert ctx.lazy_revision is not None, "Versioned read lowering requires lazy_revision"
        assert ctx.branch_table is not None, "Versioned read lowering requires branch_table"

        resolve_ref, resolve_step = ctx.get_or_create_branch_resolve(ref_id)
        if resolve_step is not None:
            steps.append(resolve_step)
        revision_ref = ctx_lazy_revision_ref(ctx)
        query_spec = build_versioned_select_one_query_spec(
            model_cls,
            sys_id=sys_id,
            permission_state_override=(QueryPermissionState.BYPASS if permission_bypass else None),
        )
        if ctx.prefer_tip_strategy:
            # Branch-tip primary-key reads route through the query-from-spec terminal so
            # compile-time branch-tip materialization detection can serve the row from the
            # fast published ``_tip`` table instead of the sparse ``_visible_ancestors``
            # ancestry scan (catastrophic on deep histories: a single-row fetch can walk
            # thousands of ``sys_revision_parents`` rows). The lazy tip revision ref is
            # retained, so non-materialized branches transparently fall back to the sparse
            # historical read at compile time. This mirrors the query-list read path, which
            # already defers the tip-vs-sparse choice to compilation.
            from impl.common.l2070_server_plan.steps.versioned_query_steps import (
                VersionedQueryFromSpecStep,
                _VersionedQueryFromSpecConfig,
            )

            tip_revision_ref_id = ServerPlanRefId(revision_ref.ref_id) if revision_ref.ref_id is not None else None
            return [
                *steps,
                *lower_versioned_spill_aware_select_one_steps(
                    ctx=ctx,
                    ref_id=ref_id,
                    model_cls=model_cls,
                    query_spec=query_spec,
                    raw_step=VersionedQueryFromSpecStep(
                        ServerPlanRefId(f"{ref_id}.raw"),
                        model_cls,
                        _VersionedQueryFromSpecConfig(
                            query_spec=query_spec,
                            branch_ref_id=_coerce_ref_id(resolve_ref),
                            revision_ref_id=tip_revision_ref_id,
                            user_id_ref_id=user_id_ref_id,
                            raw_mode=True,
                            publication_read_flavor=READ_FLAVOR_QUERY_ROWS,
                        ),
                    ),
                ),
            ]
        if not publish_raw_rows and not should_lower_spill_read(
            ctx=ctx,
            model_cls=model_cls,
            query_spec=query_spec,
            raw_mode=False,
            versioned=True,
        ):
            return [
                *steps,
                VersionedReadSelectOneStep(
                    ref_id,
                    model_cls,
                    sv,
                    _VersionedReadSelectOneConfig(
                        sparse_table_name=SqlTableName(info.sparse_table),
                        branch_ref_id=_coerce_ref_id(resolve_ref),
                        revision_ref=revision_ref,
                        type_ids=tuple(info.type_ids) if info.type_ids is not None else None,
                        user_id_ref_id=user_id_ref_id,
                        permission_bypass=permission_bypass,
                    ),
                ),
            ]
        return [
            *steps,
            *lower_versioned_spill_aware_select_one_steps(
                ctx=ctx,
                ref_id=ref_id,
                model_cls=model_cls,
                query_spec=query_spec,
                raw_step=VersionedReadSelectOneRawStep(
                    ref_id=ServerPlanRefId(f"{ref_id}.raw"),
                    model_cls=model_cls,
                    sys_id=sv,
                    config=_VersionedReadSelectOneConfig(
                        sparse_table_name=SqlTableName(info.sparse_table),
                        branch_ref_id=_coerce_ref_id(resolve_ref),
                        revision_ref=revision_ref,
                        type_ids=tuple(info.type_ids) if info.type_ids is not None else None,
                        user_id_ref_id=user_id_ref_id,
                        permission_bypass=permission_bypass,
                    ),
                ),
            ),
        ]

    scalar_sys_id = sys_id
    if publish_raw_rows:
        from impl.common.l2070_server_plan.steps.row_hydration import HydrateFirstResolvedRowStep
        from impl.common.l2070_server_plan.steps.select_one_by_query_raw import SelectOneByQueryRawStep

        raw_rows_ref = ServerPlanRefId(f"{ref_id}.raw_rows")
        raw_query_spec = build_select_one_query_spec(
            model_cls,
            sys_id=scalar_sys_id,
            permission_grammar=permission_grammar,
            permission_state_override=(QueryPermissionState.BYPASS if permission_bypass else None),
            planning_catalog=ctx.planning_catalog,
        )
        return [
            SelectOneByQueryRawStep(
                raw_rows_ref,
                model_cls,
                raw_query_spec,
                user_id_ref_id=user_id_ref_id,
            ),
            HydrateFirstResolvedRowStep(
                _coerce_ref_id(ref_id),
                source_ref=raw_rows_ref,
                model_cls=model_cls,
            ),
        ]
    if column_masking is None:
        query_spec = build_select_one_query_spec(
            model_cls,
            sys_id=scalar_sys_id,
            permission_grammar=permission_grammar,
            permission_state_override=(QueryPermissionState.BYPASS if permission_bypass else None),
            planning_catalog=ctx.planning_catalog,
        )
        if should_lower_spill_read(
            ctx=ctx,
            model_cls=model_cls,
            query_spec=query_spec,
            raw_mode=False,
            versioned=False,
        ):
            spill_steps = lower_spill_read_for_backend(
                ctx=ctx,
                ref_id=ref_id,
                model_cls=model_cls,
                query_spec=query_spec,
                result_mode="strict_one",
            )
            if spill_steps:
                return spill_steps

    return [
        SelectOneStep(
            _coerce_ref_id(ref_id),
            model_cls,
            scalar_sys_id,
            permission_grammar=permission_grammar,
            column_masking=_coerce_column_masking(column_masking),
            session_id_str=_coerce_session_id(session_id_str),
            permission_state_override=(QueryPermissionState.BYPASS if permission_bypass else None),
        ),
    ]


class SelectOneRequiredIntent[T](IntentStep[T]):
    """L4: Select a single row by primary key, raise if not found.

    Same SQL as SelectOneIntent but the post_op raises ObjectNotFoundError
    instead of returning None. The error is raised AFTER the SQL executes,
    not between SQL statements.
    """

    intent_tags = frozenset({"read", "select_one", "required", "intent"})
    intent_read_only = True

    def __init__(
        self: SelectOneRequiredIntent,
        ref_id: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        sys_id: ScalarServerRef[SysId],
    ) -> None:
        super().__init__(ref_id)
        self.model_cls = model_cls
        self.sys_id = sys_id

    def lower(self: SelectOneRequiredIntent, ctx: LoweringContext) -> Sequence[ServerPlanStep[Any]]:
        # Reuse SelectOneIntent's lowering, then wrap with RequireNonNullStep
        intent = SelectOneIntent(
            ServerPlanRefId(f"{self.ref_id}_inner"),
            self.model_cls,
            self.sys_id,
            _SelectOneConfig(),
        )
        lowered = intent.lower(ctx)
        from impl.common.l2070_server_plan.steps.return_value import (
            RequireNonNullStep,
            _RequireNonNullConfig,
        )

        return [
            *lowered,
            RequireNonNullStep(
                ServerPlanRefId(self.ref_id),
                config=_RequireNonNullConfig(
                    source_ref=ServerPlanRefId(lowered[-1].ref_id),
                    model_cls=self.model_cls,
                    sys_id=self.sys_id,
                ),
            ),
        ]

    def dependency_contract(self: SelectOneRequiredIntent) -> StepDependencyContract:
        return StepDependencyContract.from_refs(
            self.sys_id.dependencies(),
            source=DependencySource.DIRECT_FIELD,
            required_for=frozenset({DependencyUse.ORDERING, DependencyUse.TRANSPORT_GRAPH}),
            transport=TransportDependencyPolicy.TRANSPORTABLE,
            reason="select-one required sys_id source",
        )


class QueryFirstValueIntent[V](_QueryPermissionPlanningMixin, IntentStep[V | None]):
    """L4: Project a single column from the first matching row.

    Compiles to SELECT column FROM ... LIMIT 1. The column extraction
    happens in SQL, not Python.
    """

    intent_tags = frozenset({"read", "query", "intent"})
    intent_read_only = True
    model_cls: type[DatabaseObjectRow]
    query_spec: Any | None
    column: Any

    def __init__(
        self: QueryFirstValueIntent,
        ref_id: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        config: _QueryFirstValueConfig,
    ) -> None:
        super().__init__(ref_id)
        self.model_cls = model_cls
        self.query_spec = config.query_spec
        self.after_refs = config.after_refs
        self.column = config.column

    def lower(self: QueryFirstValueIntent, ctx: LoweringContext) -> Sequence[ServerPlanStep[Any]]:
        return _lower_query_first_value_intent(self, ctx)


def _lower_query_first_value_intent(
    self: QueryFirstValueIntent[Any],
    ctx: LoweringContext,
) -> Sequence[ServerPlanStep[Any]]:
    from impl.common.l2070_server_plan.steps._versioned_routing import is_versioned_operation
    from impl.common.l2070_server_plan.steps.query_execute import (
        QueryFirstProjectedValueStep,
        _QueryFirstProjectedValueStepConfig,
    )
    from l1000_schema.schema_def import get_db_column_name

    db_col: str
    if isinstance(self.column, AliasedExpression):
        db_col = self.column.alias
    elif isinstance(self.column, AliasedField):
        db_col = self.column.alias
    elif isinstance(self.column, Expression):
        db_col = str(self.column)
    else:
        col_name = self.column.name if hasattr(self.column, "name") else str(self.column)
        db_col = get_db_column_name(self.model_cls, DynamicFieldName(col_name))

    spec = self.query_spec
    assert spec is not None
    spec = replace(
        spec,
        select_columns=[self.column],
        limit=1,
        preserve_non_join_projection=True,
    )

    permission_filtering_enabled = _query_permission_needs_user_resolution(spec)
    leading_steps, user_id_ref_id = _build_session_user_resolution(
        owner_ref_id=self.ref_id,
        model_cls=self.model_cls,
        ctx=ctx,
        permission_filtering_enabled=permission_filtering_enabled,
        query_spec=spec,
    )
    permission_dependency_refs = _permission_dependency_refs_for_query(
        ctx,
        permission_filtering_enabled=permission_filtering_enabled,
        query_spec=spec,
    )

    if is_versioned_operation(self.model_cls, ctx):
        from impl.common.l2070_server_plan.steps.versioned_query_steps import (
            VersionedQueryFirstFromSpecStep,
            _VersionedQueryFirstFromSpecConfig,
        )

        if ctx.branch_id is not None:
            tip_revision_steps, tip_revision_ref_id = build_tip_revision_resolve_for_graph_preds(
                self.ref_id,
                ctx,
                spec,
            )
            return [
                *leading_steps,
                *tip_revision_steps,
                VersionedQueryFirstFromSpecStep(
                    self.ref_id,
                    self.model_cls,
                    _VersionedQueryFirstFromSpecConfig(
                        query_spec=spec,
                        branch_id=ctx.branch_id,
                        revision_id=None if tip_revision_ref_id is not None else ctx_revision_id(ctx),
                        revision_ref_id=tip_revision_ref_id,
                        user_id_ref_id=user_id_ref_id,
                        column_projection=SqlColumnName(db_col),
                        raw_mode=True,
                        after_refs=self.after_refs,
                    ),
                ),
            ]

        assert ctx.lazy_revision is not None
        resolve_ref = _coerce_ref_id(f"{self.ref_id}_resolve_branch")
        lazy_revision_ref = ctx_lazy_revision_ref(ctx)
        branch_steps, branch_ref = _branch_ref_from_context_or_resolve(
            ctx,
            resolve_ref,
            lazy_revision_ref,
        )
        first_revision_literal = _resolve_context_revision_literal(ctx)
        first_revision_ref_id = _context_revision_ref_id_for_read(ctx, lazy_revision_ref, first_revision_literal)
        return [
            *leading_steps,
            *branch_steps,
            VersionedQueryFirstFromSpecStep(
                self.ref_id,
                self.model_cls,
                _VersionedQueryFirstFromSpecConfig(
                    query_spec=spec,
                    branch_ref_id=branch_ref,
                    revision_id=first_revision_literal,
                    revision_ref_id=first_revision_ref_id,
                    user_id_ref_id=user_id_ref_id,
                    column_projection=SqlColumnName(db_col),
                    raw_mode=True,
                    after_refs=self.after_refs,
                ),
            ),
        ]

    return [
        QueryFirstProjectedValueStep(
            self.ref_id,
            self.model_cls,
            _QueryFirstProjectedValueStepConfig(
                query_spec=spec,
                column_projection=db_col,
                after_refs=self.after_refs,
                permission_dependency_refs=permission_dependency_refs,
            ),
        ),
    ]


class SelectManyIntent[T](IntentStep[Sequence[T]]):
    """L4: Select multiple rows by primary keys."""

    intent_tags = frozenset({"read", "select_many", "intent"})
    intent_cardinality = Cardinality.MANY
    intent_read_only = True

    def __init__(
        self: SelectManyIntent,
        ref_id: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        sys_ids: ScalarSequenceServerRef[SysId],
    ) -> None:
        super().__init__(ref_id)
        self.model_cls = model_cls
        self.sys_ids = sys_ids

    def lower(self: SelectManyIntent, ctx: LoweringContext) -> Sequence[ServerPlanStep[Any]]:
        from impl.common.l2070_server_plan.steps._versioned_routing import is_versioned_operation

        if is_versioned_operation(self.model_cls, ctx):
            from impl.common.l2070_server_plan.steps.versioned_query_steps import (
                VersionedSelectManyStep,
                _VersionedSelectManyConfig,
            )

            if ctx.branch_id is not None:
                return [
                    VersionedSelectManyStep(
                        self.ref_id,
                        self.model_cls,
                        _VersionedSelectManyConfig(
                            sys_ids=self.sys_ids,
                            branch_id=ctx.branch_id,
                        ),
                    ),
                ]

            assert ctx.lazy_revision is not None, "Versioned read lowering context must have lazy_revision"

            resolve_ref = _coerce_ref_id(f"{self.ref_id}_resolve_branch")
            branch_steps, branch_ref = _branch_ref_from_context_or_resolve(
                ctx,
                resolve_ref,
                ctx_lazy_revision_ref(ctx),
            )
            return [
                *branch_steps,
                VersionedSelectManyStep(
                    self.ref_id,
                    self.model_cls,
                    _VersionedSelectManyConfig(
                        sys_ids=self.sys_ids,
                        branch_ref_id=branch_ref,
                    ),
                ),
            ]

        from impl.common.l2070_server_plan.steps.select_many import SelectManyStep
        from l2070_batching.server_ref import ScalarSequenceServerRef

        ids_ref: ScalarSequenceServerRef[SysId] = self.sys_ids
        return [SelectManyStep(ServerPlanRefId(self.ref_id), self.model_cls, ids_ref)]

    def dependency_contract(self: SelectManyIntent) -> StepDependencyContract:
        return StepDependencyContract.from_refs(
            self.sys_ids.dependencies(),
            source=DependencySource.DIRECT_FIELD,
            required_for=frozenset({DependencyUse.ORDERING, DependencyUse.TRANSPORT_GRAPH}),
            transport=TransportDependencyPolicy.TRANSPORTABLE,
            reason="select-many sys_ids source",
        )


