class QueryExecuteIntent[T](_QueryPermissionPlanningMixin, IntentStep[Sequence[T]]):
    """L4: Execute a query with filters, order, limit."""

    intent_tags = frozenset({"read", "query", "intent"})
    intent_cardinality = Cardinality.MANY
    intent_read_only = True
    model_cls: type[DatabaseObjectRow]
    query_spec: Any

    def __init__(
        self: QueryExecuteIntent,
        ref_id: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        config: _QueryExecuteConfig,
    ) -> None:
        super().__init__(ref_id)
        self.model_cls = model_cls
        self.query_spec = config.query_spec
        self.raw_mode = config.raw_mode
        self.after_refs = config.after_refs
        self.always_publish_executor_binding = config.always_publish_executor_binding

    def require_sql_relation_publication(self: QueryExecuteIntent) -> None:
        """Require the lowered query to publish rows for a SQL consumer."""
        self.always_publish_executor_binding = True

    def lower(self: QueryExecuteIntent, ctx: LoweringContext) -> Sequence[ServerPlanStep[Any]]:
        return _lower_query_execute_intent(self, ctx)

    def dependencies(self: QueryExecuteIntent) -> frozenset[str]:
        deps = {str(ref_id) for ref_id in self.after_refs}
        from impl.common.l2070_server_plan.steps._resolve import collect_query_spec_deps

        deps.update(collect_query_spec_deps(self.query_spec))
        return frozenset(deps)

    def tables_read(self: QueryExecuteIntent) -> frozenset[str]:
        base_table = str(get_table_name(self.model_cls))
        if issubclass(self.model_cls, VersionedObjectRow):
            return frozenset(
                {
                    derive_versioned_table_names(VersionedBaseTableName(str(base_table))).staged,
                    derive_versioned_table_names(VersionedBaseTableName(str(base_table))).tip,
                    derive_versioned_table_names(VersionedBaseTableName(str(base_table))).sparse,
                    "sys_revision_parents",
                }
            )
        return frozenset({base_table})

    def requires_prior_statement_visibility_after_writes(self: QueryExecuteIntent) -> frozenset[str]:
        return self.tables_read()


def _insert_hydrated_scalar_projection_steps[StepsItemT](
    steps: Sequence[ServerPlanStep[StepsItemT]],
    ctx: LoweringContext,
) -> list[ServerPlanStep[Any]]:
    from impl.common.l2070_server_plan.steps.field_projection import (
        ProjectScalarFieldStep,
        project_scalar_field_config_from_steps,
    )

    projected_refs: set[str] = {str(step.ref_id) for step in steps}
    context_refs = {str(ref.ref_id) for ref in (ctx.lazy_branch, ctx.lazy_revision) if ref is not None}
    projection_steps_by_source: dict[str, list[ServerPlanStep[Any]]] = {}
    declared_relation_refs = frozenset(
        str(ref_id)
        for step in steps
        for ref_id in (
            step.sequence_result_source_ref(),
            *step.additional_batch_binding_ref_ids(),
            *((step.publication_result_ref(),) if step.publication_result_ref() is not None else ()),
        )
    )
    owner_plan = ctx.owner_plan
    seeded_constants = getattr(owner_plan, "seeded_constants", {})
    ordered_statement_transport = ctx.backend_profile.traits.same_plan_write_transport is SamePlanWriteTransport.ORDERED_STATEMENTS
    for step in steps:
        sql_visible_dependencies = step.sql_visible_dependencies()
        dependencies = (
            step.ordered_statement_sql_visible_dependencies()
            | frozenset(dependency for dependency in sql_visible_dependencies if ".hydrated." in dependency)
            if ordered_statement_transport
            else sql_visible_dependencies
        )
        for dependency in dependencies:
            if dependency.endswith(".write"):
                continue
            if ServerPlanRefId(dependency) in seeded_constants:
                continue
            marker = ".hydrated."
            if dependency in projected_refs or dependency in context_refs or dependency in declared_relation_refs:
                continue
            if marker in dependency:
                source_ref, field_name = dependency.rsplit(".", 1)
                projection_source_ref = source_ref
            else:
                source_ref, separator, field_name = dependency.rpartition(".")
                if not separator or "." in source_ref:
                    continue
                if source_ref not in projected_refs:
                    continue
                projection_source_ref = source_ref
            placement_ref = source_ref.removesuffix(".hydrated")
            if placement_ref not in projected_refs or field_name in {"raw", "rows"}:
                continue
            producer = next(candidate for candidate in steps if str(candidate.ref_id) == placement_ref)
            publication = producer.publication_contract()
            declared_columns = {
                column
                for relation in (publication.transport, publication.semantic)
                if relation is not None
                for column in relation.columns
            }
            if field_name in declared_columns and marker not in dependency:
                continue
            projection_step: ServerPlanStep[Any] = ProjectScalarFieldStep(
                ServerPlanRefId(dependency),
                config=project_scalar_field_config_from_steps(
                    source_ref=ServerPlanRefId(projection_source_ref),
                    field_name=field_name,
                    steps=steps,
                ),
            )
            projection_steps_by_source.setdefault(placement_ref, []).append(projection_step)
            projected_refs.add(dependency)
    if not projection_steps_by_source:
        return list(steps)
    ordered_steps: list[ServerPlanStep[Any]] = []
    inserted_sources: set[str] = set()
    for step in steps:
        ordered_steps.append(step)
        source_ref = str(step.ref_id)
        ordered_steps.extend(projection_steps_by_source.get(source_ref, ()))
        inserted_sources.add(source_ref)
    leading_projections = [
        projection
        for source_ref, projections in projection_steps_by_source.items()
        if source_ref not in inserted_sources
        for projection in projections
    ]
    return [*leading_projections, *ordered_steps]


def _lower_query_execute_intent(
    self: QueryExecuteIntent[Any],
    ctx: LoweringContext,
) -> Sequence[ServerPlanStep[Any]]:
    from impl.common.l2060_query_spec.query_spec import search_op_from_query_spec
    from impl.common.l2070_server_plan.steps._versioned_routing import is_versioned_operation
    from impl.common.l2070_server_plan.steps.intent_query_extended import (
        _should_hydrate_search_payload,
    )
    from impl.common.l2070_server_plan.steps.large_column_read import (
        lower_spill_read_for_backend,
    )
    from impl.common.l2070_server_plan.steps.query_execute import _QueryExecuteStepConfig
    from impl.common.l2070_server_plan.steps.search_payload import (
        ProjectSearchPayloadResultsStep,
    )

    permission_filtering_enabled = _query_permission_needs_user_resolution(self.query_spec)
    leading_steps, user_id_ref_id = _build_session_user_resolution(
        owner_ref_id=self.ref_id,
        model_cls=self.model_cls,
        ctx=ctx,
        permission_filtering_enabled=permission_filtering_enabled,
        query_spec=self.query_spec,
    )
    permission_dependency_refs = _permission_dependency_refs_for_query(
        ctx,
        permission_filtering_enabled=permission_filtering_enabled,
        query_spec=self.query_spec,
    )
    search_op = search_op_from_query_spec(self.query_spec)
    if search_op.mode == "invalid_hybrid":
        raise ValueError(invalid_hybrid_message())

    def build_versioned_query_steps() -> list[ServerPlanStep[Any]]:
        from impl.common.l2070_server_plan.steps.large_column_read import should_lower_spill_read
        from impl.common.l2070_server_plan.steps.versioned_query_steps import (
            build_versioned_query_from_spec_steps,
            VersionedQueryFromSpecStep,
            _VersionedQueryFromSpecConfig,
            lower_versioned_spill_aware_query_read_steps,
        )

        use_explicit_read = self.query_spec is not None
        policy = None if ctx.is_write_transaction else ctx.lazy_branch_tip_materialization
        policy_after_refs = self.after_refs
        if policy is not None and policy.ref_id is not None and policy.ref_id not in policy_after_refs:
            policy_after_refs = policy_after_refs | frozenset({policy.ref_id})

        def _should_lower_hydrated_many_via_raw_relation() -> bool:
            if self.raw_mode or not use_explicit_read:
                return False
            from l1000_schema.large_column import get_large_column_configs

            if get_large_column_configs(self.model_cls):
                return False
            dotted_dependency_map = ctx._lowering_cache.get("sql_visible_dotted_dependencies_by_base_ref")
            if not isinstance(dotted_dependency_map, dict) or str(self.ref_id) not in dotted_dependency_map:
                return False
            return not (
                getattr(self.query_spec, "aggregations", None)
                or getattr(self.query_spec, "group_by", None)
                or getattr(self.query_spec, "select_columns", None)
                or getattr(self.query_spec, "select_column_tables", None)
                or getattr(self.query_spec, "window_functions", None)
                or getattr(self.query_spec, "computed_columns", None)
                or getattr(self.query_spec, "computed_column_specs", None)
            )

        def _raw_relation_hydrated_steps(
            *,
            branch_id: str | None,
            branch_ref_id: ServerPlanRefId | None = None,
            revision_id: RevisionId | None = None,
            revision_ref_id: ServerPlanRefId | None = None,
        ) -> list[ServerPlanStep[Any]]:
            return [
                VersionedQueryFromSpecStep(
                    self.ref_id,
                    self.model_cls,
                    _VersionedQueryFromSpecConfig(
                        query_spec=self.query_spec,
                        branch_id=branch_id,
                        branch_ref_id=branch_ref_id,
                        revision_id=revision_id,
                        revision_ref_id=revision_ref_id,
                        user_id_ref_id=user_id_ref_id,
                        after_refs=policy_after_refs,
                        raw_mode=False,
                        always_publish_executor_binding=True,
                    ),
                ),
            ]

        context_branch_ref_id: ServerPlanRefId | None = None
        if ctx.branch_id is None and ctx.lazy_branch is not None:
            lazy_branch_ref = ctx_lazy_branch_ref(ctx)
            if lazy_branch_ref.ref_id is not None:
                context_branch_ref_id = ServerPlanRefId(lazy_branch_ref.ref_id)
        has_branch_input = ctx.branch_id is not None or context_branch_ref_id is not None
        if has_branch_input and (ctx.revision_id is None or ctx.staging_ctx_factory is not None or ctx.prefer_tip_merged):
            # Versioned write transactions (``staging_ctx_factory`` is published by
            # ``LazyVersionedWriteTransaction``) query the tip+staged merged CTE so their
            # own staged work remains visible. Read transactions resolve the branch
            # tip revision first and drive a sparse-read query at that revision so
            # uncommitted staged work from other connections stays hidden.
            is_read_only_branch_txn = ctx.staging_ctx_factory is None and not ctx.prefer_tip_merged
            branch_tip_steps: list[ServerPlanStep[Any]] = []
            branch_tip_revision_ref: ServerPlanRefId | None = None
            if ctx.lazy_revision is not None:
                lazy_revision_ref = ctx_lazy_revision_ref(ctx)
                if lazy_revision_ref.ref_id is not None:
                    branch_tip_revision_ref = ServerPlanRefId(lazy_revision_ref.ref_id)
            if branch_tip_revision_ref is None and is_read_only_branch_txn and ctx.branch_table is not None and ctx.branch_id is not None:
                from impl.common.l2050_sql_types.sql_branded_types import SqlTableName
                from impl.common.l2070_server_plan.steps.resolve_branch_steps import (
                    ResolveBranchTipRevisionStep,
                )
                from l7000_versioned_schema.versioned_schema import BranchId

                if ctx.branch_id is None:
                    msg = "Versioned query compilation requires an explicit branch ID"
                    raise RuntimeError(msg)
                tip_ref = ServerPlanRefId(f"{self.ref_id}_resolve_branch_tip")
                branch_tip_steps = [
                    ResolveBranchTipRevisionStep(
                        tip_ref,
                        branch_id=ServerRefs.scalar(BranchId(ctx.branch_id)),
                        branch_table=SqlTableName(ctx.branch_table),
                        branch_id_column=ctx.branch_id_column,
                        tip_revision_column=ctx.branch_tip_revision_column,
                    ),
                ]
                branch_tip_revision_ref = tip_ref
            elif not is_read_only_branch_txn:
                _graph_pred_steps, graph_pred_ref = build_tip_revision_resolve_for_graph_preds(
                    self.ref_id,
                    ctx,
                    self.query_spec,
                )
                branch_tip_steps = list(_graph_pred_steps)
                branch_tip_revision_ref = graph_pred_ref
            if (
                not self.raw_mode
                and use_explicit_read
                and should_lower_spill_read(
                    ctx=ctx,
                    model_cls=self.model_cls,
                    query_spec=self.query_spec,
                    raw_mode=False,
                    versioned=True,
                )
            ):
                return [
                    *leading_steps,
                    *branch_tip_steps,
                    *lower_versioned_spill_aware_query_read_steps(
                        ref_id=self.ref_id,
                        model_cls=self.model_cls,
                        query_spec=self.query_spec,
                        branch_id=ctx.branch_id,
                        revision_id=branch_tip_revision_ref,
                        user_id_ref_id=user_id_ref_id,
                        always_publish_executor_binding=self.always_publish_executor_binding,
                    ),
                ]
            if _should_lower_hydrated_many_via_raw_relation():
                return [
                    *leading_steps,
                    *branch_tip_steps,
                    *_raw_relation_hydrated_steps(
                        branch_id=ctx.branch_id,
                        branch_ref_id=context_branch_ref_id,
                        revision_ref_id=branch_tip_revision_ref,
                    ),
                ]
            return [
                *leading_steps,
                *branch_tip_steps,
                *build_versioned_query_from_spec_steps(
                    ref_id=self.ref_id,
                    model_cls=self.model_cls,
                    config=_VersionedQueryFromSpecConfig(
                        query_spec=self.query_spec,
                        branch_id=ctx.branch_id,
                        branch_ref_id=context_branch_ref_id,
                        revision_ref_id=branch_tip_revision_ref,
                        user_id_ref_id=user_id_ref_id,
                        after_refs=policy_after_refs,
                        raw_mode=self.raw_mode,
                        always_publish_executor_binding=self.always_publish_executor_binding,
                    ),
                ),
            ]

        assert ctx.lazy_revision is not None, "Versioned read lowering context must have lazy_revision"
        assert ctx.branch_table is not None, "Versioned read lowering context must have branch_table"
        lazy_revision_ref = ctx_lazy_revision_ref(ctx)
        steps: list[ServerPlanStep[Any]] = list(leading_steps)
        branch_ref_id: ServerPlanRefId | None = None
        if ctx.branch_id is None and _resolve_context_revision_literal(ctx) is None:
            branch_steps, branch_ref_id = _branch_ref_from_context_or_resolve(
                ctx,
                _coerce_ref_id(f"{self.ref_id}_resolve_branch"),
                lazy_revision_ref,
            )
            steps.extend(branch_steps)
        if (
            not self.raw_mode
            and use_explicit_read
            and should_lower_spill_read(
                ctx=ctx,
                model_cls=self.model_cls,
                query_spec=self.query_spec,
                raw_mode=False,
                versioned=True,
            )
        ):
            steps.extend(
                lower_versioned_spill_aware_query_read_steps(
                    ref_id=self.ref_id,
                    model_cls=self.model_cls,
                    query_spec=self.query_spec,
                    branch_id=ctx.branch_id,
                    branch_ref_id=branch_ref_id,
                    revision_id=lazy_revision_ref,
                    user_id_ref_id=user_id_ref_id,
                    always_publish_executor_binding=self.always_publish_executor_binding,
                ),
            )
            return steps
        vqs_revision_literal = _resolve_context_revision_literal(ctx)
        vqs_revision_ref_id = _context_revision_ref_id_for_read(ctx, lazy_revision_ref, vqs_revision_literal)
        if _should_lower_hydrated_many_via_raw_relation():
            steps.extend(
                _raw_relation_hydrated_steps(
                    branch_id=ctx.branch_id,
                    branch_ref_id=branch_ref_id,
                    revision_id=vqs_revision_literal,
                    revision_ref_id=vqs_revision_ref_id,
                ),
            )
            return steps
        steps.extend(
            build_versioned_query_from_spec_steps(
                ref_id=self.ref_id,
                model_cls=self.model_cls,
                config=_VersionedQueryFromSpecConfig(
                    query_spec=self.query_spec,
                    branch_id=ctx.branch_id,
                    branch_ref_id=branch_ref_id,
                    revision_id=vqs_revision_literal,
                    revision_ref_id=vqs_revision_ref_id,
                    user_id_ref_id=user_id_ref_id,
                    after_refs=policy_after_refs,
                    raw_mode=self.raw_mode,
                    always_publish_executor_binding=self.always_publish_executor_binding,
                ),
            ),
        )
        return steps

    result: list[ServerPlanStep[Any]]
    explicit_values = self.query_spec is not None and isinstance(getattr(self.query_spec, "source", None), ValuesSource)
    if is_versioned_operation(self.model_cls, ctx) and not explicit_values:
        if search_op is not None and search_op.is_search:
            assert self.query_spec is not None
            from impl.common.l2070_server_plan.steps.intent_search_lowering import lower_search_query

            should_hydrate_payload = _should_hydrate_search_payload(self.query_spec)
            result = list(
                lower_search_query(
                    ref_id=self.ref_id,
                    model_cls=self.model_cls,
                    query_spec=self.query_spec,
                    ctx=ctx,
                    is_versioned=True,
                    projection="results",
                    raw_mode=should_hydrate_payload,
                    session_id=_coerce_optional_session_id(ctx.session_id),
                    should_hydrate_payload=should_hydrate_payload,
                    build_projection_step=lambda final_ref, payload_ref: ProjectSearchPayloadResultsStep(
                        final_ref,
                        payload_ref,
                    ),
                ),
            )
        else:
            result = build_versioned_query_steps()
    elif search_op is not None and search_op.is_search:
        assert self.query_spec is not None
        from impl.common.l2070_server_plan.steps.intent_search_lowering import lower_search_query

        result = list(
            lower_search_query(
                ref_id=ServerPlanRefId(self.ref_id),
                model_cls=self.model_cls,
                query_spec=self.query_spec,
                ctx=ctx,
                is_versioned=False,
                projection="results",
                raw_mode=self.raw_mode,
                session_id=_coerce_optional_session_id(ctx.session_id),
                should_hydrate_payload=True,
                build_projection_step=lambda final_ref, payload_ref: ProjectSearchPayloadResultsStep(
                    final_ref,
                    payload_ref,
                ),
            ),
        )
    elif self.query_spec is not None:
        query_spec = _with_catalog_default_projection(self.query_spec, self.model_cls, ctx)
        spill_steps = lower_spill_read_for_backend(
            ctx=ctx,
            ref_id=self.ref_id,
            model_cls=self.model_cls,
            query_spec=query_spec,
            result_mode="many",
            user_id_ref_id=user_id_ref_id,
        )
        if not self.raw_mode and spill_steps:
            result = [*leading_steps, *spill_steps]
        else:
            from impl.common.l2070_server_plan.steps.query_execute import (
                QueryExecuteStep,
                _QueryExecuteStepConfig,
            )

            result = [
                *leading_steps,
                QueryExecuteStep(
                    self.ref_id,
                    self.model_cls,
                    _QueryExecuteStepConfig(
                        query_spec=query_spec,
                        raw_mode=self.raw_mode,
                        after_refs=self.after_refs,
                        permission_dependency_refs=permission_dependency_refs,
                        user_id_ref_id=user_id_ref_id,
                        always_publish_executor_binding=self.always_publish_executor_binding,
                    ),
                ),
            ]
    else:
        from impl.common.l2070_server_plan.steps.query_execute import (
            QueryExecuteStep,
            _QueryExecuteStepConfig,
        )

        result = [
            *leading_steps,
            QueryExecuteStep(
                self.ref_id,
                self.model_cls,
                _QueryExecuteStepConfig(
                    query_spec=self.query_spec,
                    raw_mode=self.raw_mode,
                    after_refs=self.after_refs,
                    permission_dependency_refs=permission_dependency_refs,
                    user_id_ref_id=(user_id_ref_id),
                    always_publish_executor_binding=self.always_publish_executor_binding,
                ),
            ),
        ]

    return result


class QueryFirstIntent[T](_QueryPermissionPlanningMixin, IntentStep[T | None]):
    """L4: Execute a query, return first result or None."""

    intent_tags = frozenset({"read", "query", "intent"})
    intent_read_only = True
    model_cls: type[DatabaseObjectRow]
    query_spec: Any
    raw_mode: bool

    def __init__(
        self: QueryFirstIntent,
        ref_id: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        config: _QuerySingleResultConfig,
    ) -> None:
        super().__init__(ref_id)
        self.model_cls = model_cls
        self.query_spec = config.query_spec
        self.raw_mode = config.raw_mode
        self.after_refs = config.after_refs

    def sequence_result_source_ref(self) -> ServerPlanRefId:
        if issubclass(self.model_cls, VersionedObjectRow):
            from impl.common.l2070_server_plan.steps.intent_versioning_extended import (
                versioned_select_raw_rows_source_ref,
            )

            return versioned_select_raw_rows_source_ref(self.ref_id)
        return self.ref_id

    def lower(self: QueryFirstIntent, ctx: LoweringContext) -> Sequence[ServerPlanStep[Any]]:
        return _lower_query_first_intent(self, ctx)


def _lower_query_first_intent(
    self: QueryFirstIntent[Any],
    ctx: LoweringContext,
) -> Sequence[ServerPlanStep[Any]]:
    from impl.common.l2070_server_plan.steps._versioned_routing import is_versioned_operation
    from impl.common.l2070_server_plan.steps.large_column_read import should_lower_spill_read
    from impl.common.l2070_server_plan.steps.query_execute import (
        QueryFirstRawStep,
        QueryFirstStep,
        _QueryFirstRawStepConfig,
        _QueryFirstStepConfig,
    )

    permission_filtering_enabled = _query_permission_needs_user_resolution(self.query_spec)
    leading_steps, user_id_ref_id = _build_session_user_resolution(
        owner_ref_id=self.ref_id,
        model_cls=self.model_cls,
        ctx=ctx,
        permission_filtering_enabled=permission_filtering_enabled,
        query_spec=self.query_spec,
    )
    permission_dependency_refs = _permission_dependency_refs_for_query(
        ctx,
        permission_filtering_enabled=permission_filtering_enabled,
        query_spec=self.query_spec,
    )

    if is_versioned_operation(self.model_cls, ctx):
        from impl.common.l2070_server_plan.steps.versioned_query_steps import (
            VersionedQueryFirstFromSpecStep,
            _VersionedQueryFirstFromSpecConfig,
            lower_versioned_spill_aware_query_read_steps,
        )

        if ctx.branch_id is not None:
            tip_revision_steps, tip_revision_ref_id = build_tip_revision_resolve_for_graph_preds(
                self.ref_id,
                ctx,
                self.query_spec,
            )
            if should_lower_spill_read(
                ctx=ctx,
                model_cls=self.model_cls,
                query_spec=self.query_spec,
                raw_mode=self.raw_mode,
                versioned=True,
            ):
                return [
                    *leading_steps,
                    *tip_revision_steps,
                    *lower_versioned_spill_aware_query_read_steps(
                        ref_id=self.ref_id,
                        model_cls=self.model_cls,
                        query_spec=self.query_spec,
                        branch_id=ctx.branch_id,
                        revision_id=tip_revision_ref_id if tip_revision_ref_id is not None else ctx_revision_id(ctx),
                        result_mode="first",
                        user_id_ref_id=user_id_ref_id,
                    ),
                ]
            return [
                *leading_steps,
                *tip_revision_steps,
                VersionedQueryFirstFromSpecStep(
                    self.ref_id,
                    self.model_cls,
                    _VersionedQueryFirstFromSpecConfig(
                        query_spec=self.query_spec,
                        branch_id=ctx.branch_id,
                        revision_id=None if tip_revision_ref_id is not None else ctx_revision_id(ctx),
                        revision_ref_id=tip_revision_ref_id,
                        user_id_ref_id=user_id_ref_id,
                        raw_mode=self.raw_mode,
                        after_refs=self.after_refs,
                    ),
                ),
            ]

        assert ctx.lazy_revision is not None

        resolve_ref = _coerce_ref_id(f"{self.ref_id}_resolve_branch")
        lazy_revision_ref = ctx_lazy_revision_ref(ctx)
        branch_steps, branch_ref = _branch_ref_from_context_or_resolve(
            ctx,
            resolve_ref,
            lazy_revision_ref,
        )
        first_revision_literal = _resolve_context_revision_literal(ctx)
        first_revision_ref_id = _context_revision_ref_id_for_read(ctx, lazy_revision_ref, first_revision_literal)
        if should_lower_spill_read(
            ctx=ctx,
            model_cls=self.model_cls,
            query_spec=self.query_spec,
            raw_mode=self.raw_mode,
            versioned=True,
        ):
            return [
                *leading_steps,
                *branch_steps,
                *lower_versioned_spill_aware_query_read_steps(
                    ref_id=self.ref_id,
                    model_cls=self.model_cls,
                    query_spec=self.query_spec,
                    branch_ref_id=branch_ref,
                    revision_id=lazy_revision_ref,
                    result_mode="first",
                    user_id_ref_id=user_id_ref_id,
                ),
            ]
        return [
            *leading_steps,
            *branch_steps,
            VersionedQueryFirstFromSpecStep(
                self.ref_id,
                self.model_cls,
                _VersionedQueryFirstFromSpecConfig(
                    query_spec=self.query_spec,
                    branch_ref_id=branch_ref,
                    revision_id=first_revision_literal,
                    revision_ref_id=first_revision_ref_id,
                    user_id_ref_id=user_id_ref_id,
                    raw_mode=self.raw_mode,
                    after_refs=self.after_refs,
                ),
            ),
        ]

    query_spec = _with_catalog_default_projection(self.query_spec, self.model_cls, ctx)
    return [
        *leading_steps,
        (
            QueryFirstRawStep(
                self.ref_id,
                self.model_cls,
                _QueryFirstRawStepConfig(
                    query_spec=query_spec,
                    after_refs=self.after_refs,
                    permission_dependency_refs=permission_dependency_refs,
                    user_id_ref_id=user_id_ref_id,
                ),
            )
            if self.raw_mode
            else QueryFirstStep(
