def _lower_query_count_intent(
    self: QueryCountIntent,
    ctx: LoweringContext,
) -> Sequence[ServerPlanStep[Any]]:
    from impl.common.l2070_server_plan.steps._versioned_routing import is_versioned_operation

    leading_steps, user_id_ref_id = _build_session_user_resolution(
        owner_ref_id=self.ref_id,
        model_cls=self.model_cls,
        ctx=ctx,
        permission_filtering_enabled=not getattr(self.query_spec, "skip_permission_filtering", False),
        query_spec=self.query_spec,
    )

    if is_versioned_operation(self.model_cls, ctx):
        from impl.common.l2070_server_plan.steps.versioned_query_steps import (
            build_versioned_query_count_from_spec_steps,
            VersionedQueryCountFromSpecStep,
            _VersionedQueryScalarFromSpecConfig,
        )

        # PostgreSQL sibling CTE reads cannot observe data-modifying CTE writes
        # in the same statement, so versioned scalar reads must flush after staged writes.
        allow_batch = versioned_scalar_query_allow_batch(ctx)
        policy = None if ctx.is_write_transaction else ctx.lazy_branch_tip_materialization
        policy_dependencies = frozenset({policy.ref_id}) if policy is not None and policy.ref_id is not None else frozenset()

        if ctx.branch_id is not None:
            tip_revision_steps, tip_revision_ref_id = build_tip_revision_resolve_for_graph_preds(
                self.ref_id,
                ctx,
                self.query_spec,
            )
            return [
                *leading_steps,
                *tip_revision_steps,
                *build_versioned_query_count_from_spec_steps(
                    ref_id=self.ref_id,
                    model_cls=self.model_cls,
                    config=_VersionedQueryScalarFromSpecConfig(
                        query_spec=self.query_spec,
                        branch_id=ctx.branch_id,
                        revision_id=None if tip_revision_ref_id is not None else ctx_revision_id(ctx),
                        revision_ref_id=tip_revision_ref_id,
                        user_id_ref_id=user_id_ref_id,
                        allow_batch=allow_batch,
                        after_refs=policy_dependencies,
                    ),
                ),
            ]

        assert ctx.lazy_revision is not None

        resolve_ref = _coerce_ref_id(f"{self.ref_id}_resolve_branch")
        lazy_revision_ref = ctx_lazy_revision_ref(ctx)
        branch_steps, branch_ref = _branch_ref_from_context_or_resolve(
            ctx,
            resolve_ref,
            lazy_revision_ref,
        )
        count_revision_literal = _resolve_context_revision_literal(ctx)
        count_revision_ref_id = _context_revision_ref_id_for_read(ctx, lazy_revision_ref, count_revision_literal)
        return [
            *leading_steps,
            *branch_steps,
            *build_versioned_query_count_from_spec_steps(
                ref_id=self.ref_id,
                model_cls=self.model_cls,
                config=_VersionedQueryScalarFromSpecConfig(
                    query_spec=self.query_spec,
                    branch_ref_id=branch_ref,
                    revision_id=count_revision_literal,
                    revision_ref_id=count_revision_ref_id,
                    user_id_ref_id=user_id_ref_id,
                    allow_batch=allow_batch,
                    after_refs=policy_dependencies,
                ),
            ),
        ]

    from impl.common.l2070_server_plan.steps.query_count import (
        QueryCountStep,
        _QueryCountStepConfig,
    )

    return [
        *leading_steps,
        QueryCountStep(
            self.ref_id,
            self.model_cls,
            _QueryCountStepConfig(
                query_spec=self.query_spec,
                user_id_ref_id=user_id_ref_id,
                after_refs=self.after_refs,
            ),
        ),
    ]


class QueryDeleteIntent(_QueryPermissionPlanningMixin, IntentStep[int]):
    """L4: Delete rows matching a query."""

    intent_tags = frozenset({"write", "delete", "query", "intent"})
    intent_cardinality = Cardinality.SCALAR
    model_cls: type[DatabaseObjectRow]
    query_spec: Any

    def __init__(
        self: QueryDeleteIntent,
        ref_id: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        config: _QueryExecuteConfig,
    ) -> None:
        super().__init__(ref_id)
        self.model_cls = model_cls
        self.query_spec = config.query_spec
        self.after_refs = config.after_refs
        self.preimage_ref_id = config.preimage_ref_id
        self.effect_only = config.effect_only

    def tables_written(self: QueryDeleteIntent) -> frozenset[str]:
        return frozenset({str(get_table_name(self.model_cls))})

    def lower(self: QueryDeleteIntent, ctx: LoweringContext) -> Sequence[ServerPlanStep[Any]]:
        from dataclasses import replace
        from impl.common.l2070_server_plan.steps._versioned_routing import get_versioned_staging_ctx
        from impl.common.l2070_server_plan.steps.write_side_effect_intents import (
            RecordTableEventIntent,
            _RecordTableEventConfig,
            _has_matching_table_subscriptions,
        )

        if (
            not ctx.emit_table_event_intents
            or not _has_matching_table_subscriptions(self.model_cls, "DELETE")
            or get_versioned_staging_ctx(self.model_cls, ctx) is not None
        ):
            return _lower_query_delete_intent(self, ctx)
        preimage_ref = self.preimage_ref_id or ServerPlanRefId(f"{self.ref_id}.subscription_preimage")
        selected = QueryExecuteIntent(
            preimage_ref,
            self.model_cls,
            _QueryExecuteConfig(
                query_spec=replace(self.query_spec, select_columns=None, projection_output_aliases=None),
                raw_mode=True,
                after_refs=self.after_refs,
            ),
        )
        mutation = QueryDeleteIntent(
            ServerPlanRefId(self.ref_id),
            self.model_cls,
            _QueryExecuteConfig(
                query_spec=self.query_spec,
                after_refs=self.after_refs | frozenset({preimage_ref}),
                preimage_ref_id=self.preimage_ref_id,
                effect_only=self.effect_only,
            ),
        )
        return [
            *(selected.lower(ctx) if self.preimage_ref_id is None else ()),
            *_lower_query_delete_intent(mutation, ctx),
            *RecordTableEventIntent(
                ServerPlanRefId(f"{self.ref_id}_subscription_dispatch"),
                self.model_cls,
                _RecordTableEventConfig(
                    event_type="DELETE",
                    write_ref_id=preimage_ref,
                    completion_ref=ServerPlanRefId(self.ref_id),
                ),
            ).lower(ctx),
        ]


@dataclass(frozen=True)
class _ApplyQueryUpdatesToRowsConfig:
    model_cls: type[DatabaseObjectRow]
    source_ref: ServerPlanRefId
    updates: Mapping[str, Any]
    returning_projections: tuple[object, ...] | None = None
    source_columns: tuple[str, ...] | None = None


def _first_expression_field_name(expression: Expression[Any, DatabaseObjectRow]) -> str | None:
    if expression.field is not None:
        return expression.field
    if expression.left is not None:
        left_field = _first_expression_field_name(expression.left)
        if left_field is not None:
            return left_field
    if expression.right is not None:
        right_field = _first_expression_field_name(expression.right)
        if right_field is not None:
            return right_field
    for arg in expression.args:
        if isinstance(arg, Expression):
            arg_field = _first_expression_field_name(arg)
            if arg_field is not None:
                return arg_field
    return None


class _ApplyQueryUpdatesToRowsStep(SqlRelationPublisherStep[list[Any]]):
    """Apply query-update values to selected model rows before versioned staging."""

    optimizer_projection_owned = True

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        config: _ApplyQueryUpdatesToRowsConfig,
    ) -> None:
        super().__init__(ref_id)
        self._model_cls = config.model_cls
        self._source_ref = config.source_ref
        self._updates = config.updates
        self._returning_projections = config.returning_projections
        self._source_columns = config.source_columns

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.MANY

    def is_read_only(self) -> bool:
        return True

    def step_tags(self) -> frozenset[str]:
        return frozenset({"read", "query", "update", "versioned", "projection"})

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def supports_sql_batch_transport(self) -> bool:
        return True

    def supports_ordered_sql_statement_batch(self) -> bool:
        return True

    def ordered_statement_sql_visible_dependencies(self) -> frozenset[str]:
        return frozenset()

    def dependencies(self) -> frozenset[str]:
        return frozenset({str(self._source_ref)})

    def imported_dependency_refs(self) -> frozenset[ServerPlanRefId]:
        return frozenset(ServerPlanRefId(dependency) for dependency in self.dependencies())

    def consumes_executor_visible_dependencies(self) -> bool:
        return True

    def always_publishes_executor_visible_binding(self) -> bool:
        return True

    def cte_publication_contract(self) -> CtePublicationContract:
        columns = self._cte_output_columns()
        column_type_hints = self._cte_column_type_hints()
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=columns,
            column_type_hints=column_type_hints,
            model_cls=cte_projection_row_model(
                f"{type(self).__name__}CteRow",
                columns,
                column_type_hints,
            ),
        )

    def _cte_output_columns(self) -> tuple[str, ...]:
        from l1000_schema.schema_def import get_db_column_name
        from l1000_schema.typed_field import AliasedExpression, AliasedField
        from impl.common.l2070_server_plan.steps.large_column_read import inline_large_column_alias_columns
        from l2070_batching.write_column_policy import cte_payload_columns

        # Inline aliases describe the selected preimage. Updated pointer columns must be
        # rehydrated from their new values instead of publishing stale preimage payloads.
        inline_transport_columns = frozenset(inline_large_column_alias_columns(self._model_cls))
        columns = [
            column
            for column in (
                self._source_columns
                if self._source_columns is not None
                else cte_payload_columns(self._model_cls, include_polymorphic=True)
            )
            if column not in inline_transport_columns
        ]
        for field_name in self._updates:
            columns.append(get_db_column_name(self._model_cls, DynamicFieldName(field_name)))
        for projection in self._returning_projections or ():
            if isinstance(projection, (AliasedExpression, AliasedField)):
                columns.append(projection.alias)
            elif isinstance(projection, Field):
                columns.append(get_db_column_name(self._model_cls, DynamicFieldName(projection.name)))
        return tuple(dict.fromkeys(columns))

    def _cte_column_type_hints(self) -> SqlColumnTypeHints:
        output_columns = self._cte_output_columns()
        hints = model_sql_column_type_hints(self._model_cls, output_columns)
        if hints is None:
            msg = f"Could not resolve SQL column type hints for {self._model_cls.__name__}"
            raise TypeError(msg)
        from impl.common.l2070_server_plan.steps.large_column_read import (
            inline_large_column_sql_column_type_hints,
        )

        projection_hints = self._returning_projection_type_hints(hints)
        inline_large_column_hints = inline_large_column_sql_column_type_hints(self._model_cls).filtered(set(output_columns))
        synthetic_hints = (
            SqlColumnTypeHints(uuid_columns=frozenset({"branch_id"}))
            if "branch_id" in output_columns and not hints.covers(("branch_id",))
            else SqlColumnTypeHints()
        )
        combined_hints = combine_sql_column_type_hints(
            output_columns,
            hints,
            projection_hints,
            inline_large_column_hints,
            synthetic_hints,
        )
        if combined_hints is None:
            msg = f"Could not combine SQL column type hints for {self._model_cls.__name__}"
            raise TypeError(msg)
        return combined_hints

    def _returning_projection_type_hints(self, model_hints: SqlColumnTypeHints) -> SqlColumnTypeHints:
        from l1000_schema.schema_def import get_db_column_name
        from l1000_schema.typed_field import AliasedExpression, AliasedField

        hints: list[SqlColumnTypeHints] = []
        for projection in self._returning_projections or ():
            if isinstance(projection, AliasedField):
                source_column = get_db_column_name(self._model_cls, DynamicFieldName(projection.name))
                hints.append(model_hints.rename_column(source_column, projection.alias))
            elif isinstance(projection, AliasedExpression):
                if model_hints.covers((projection.alias,)):
                    continue
                source_field = _first_expression_field_name(projection.expression)
                if source_field is None:
                    msg = f"Cannot infer SQL type hint for aliased expression {projection.alias!r}"
                    raise TypeError(msg)
                source_column = get_db_column_name(self._model_cls, DynamicFieldName(source_field))
                if source_column in model_hints.jsonb_columns:
                    hints.append(SqlColumnTypeHints(text_columns=frozenset({projection.alias})))
                else:
                    hints.append(model_hints.rename_column(source_column, projection.alias))
        if not hints:
            return SqlColumnTypeHints()
        return combine_sql_column_type_hints(self._cte_output_columns(), *hints)

    def compile(self, ctx: Any) -> Any:
        cte_ref = ctx.cte_refs.get(str(self._source_ref))
        if cte_ref is not None:
            return self._compile_from_cte(cte_ref)
        msg = (
            "_ApplyQueryUpdatesToRowsStep requires a SQL-visible source relation; "
            "query update patching must lower to SQL assignments rather than Python row mutation."
        )
        raise RuntimeError(msg)

    def _compile_from_cte(self, cte_ref: Any) -> Any:
        from impl.common.l5200_sql_query.expression_grammar import ExpressionToGrammar
        from impl.common.l2100_sql_grammar.domain.infra.stmt_cte_helpers import (
            SqlSelectFromCteWithOverrides,
        )
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlParam
        from l1000_schema.schema_def import get_db_column_name
        from l1000_schema.typed_field import AliasedExpression, AliasedField, Expression, Field

        converter = ExpressionToGrammar(self._model_cls, table_alias="src")
        source_alias = SqlAliasName("src")
        from l1000_schema.json_type import get_json_columns
        from impl.common.l2100_sql_grammar.tree.expr_json import SqlJsonLiteral

        json_columns = get_json_columns(self._model_cls)
        overrides: dict[str, Any] = {}
        for field_name, value in self._updates.items():
            db_column = get_db_column_name(self._model_cls, DynamicFieldName(field_name))
            if isinstance(value, Expression):
                overrides[db_column] = converter.convert(value)
            elif isinstance(value, Field):
                overrides[db_column] = SqlColumnRef(
                    SqlColumnName(get_db_column_name(self._model_cls, DynamicFieldName(value.name))),
                    source_alias,
                )
            else:
                unwrap_to_str = getattr(value, "unwrap_to_str", None)
                if callable(unwrap_to_str):
                    value = unwrap_to_str()
                overrides[db_column] = SqlJsonLiteral(value) if field_name in json_columns else SqlParam(value)
        output_columns = self._cte_output_columns()
        source_cte_columns = {str(column) for column in cte_ref.columns or ()}
        if (
            "sys_revision_id" in output_columns
            and "sys_revision_id" not in source_cte_columns
            and "sys_valid_from_revision_id" in source_cte_columns
            and "sys_revision_id" not in overrides
        ):
            overrides["sys_revision_id"] = SqlColumnRef(SqlColumnName("sys_valid_from_revision_id"), "src")
        for physical_column in ("sys_revision_id", "sys_staged_commit_id"):
            if physical_column in output_columns and physical_column not in source_cte_columns and physical_column not in overrides:
                overrides[physical_column] = SqlParam(None)
        if "sys_deleted" in output_columns and "sys_deleted" not in source_cte_columns:
            overrides["sys_deleted"] = SqlParam(False)

        def _post_update_field_ref(field_name: str) -> Any:
            db_column = get_db_column_name(self._model_cls, DynamicFieldName(field_name))
            return overrides.get(db_column) or SqlColumnRef(SqlColumnName(db_column), source_alias)

        returning_converter = ExpressionToGrammar(
            self._model_cls,
            table_alias="src",
            field_ref_factory=_post_update_field_ref,
        )
        for projection in self._returning_projections or ():
            if isinstance(projection, AliasedExpression):
                overrides[projection.alias] = returning_converter.convert(projection.expression)
            elif isinstance(projection, AliasedField):
                overrides[projection.alias] = SqlColumnRef(
                    SqlColumnName(get_db_column_name(self._model_cls, DynamicFieldName(projection.name))),
                    source_alias,
                )

        contract_columns = self.cte_publication_contract().columns
        projectable_columns = set(contract_columns)
        candidate_columns = set(source_cte_columns) | {column for column in overrides if column in projectable_columns}
        source_columns = tuple(column for column in contract_columns if column in candidate_columns)
        grammar = SqlSelectFromCteWithOverrides(
            source_cte_name=cte_ref.ref_id,
            source_columns=source_columns,
            overrides=overrides,
        )
        output_shape = CompiledOutputShape(tuple(synthetic_output_field(column) for column in source_columns))

        __opa002_grammar_2189 = grammar
        column_type_hints = self.cte_column_type_hints()
        assert column_type_hints is not None
        from impl.common.l2070_server_plan.steps._query_helper_compile import (
            _collect_auxiliary_ctes_from_consumed,
        )

        return CompiledStep(
            output_shape=output_shape,
            grammar=__opa002_grammar_2189,
            needs_returning=True,
            result_relation=DeclaredResultRelation.from_output_shape(output_shape),
            column_type_hints=column_type_hints.filtered(set(source_columns)),
            closed_post_op=CompiledPostOp.materialize(
                ResultMaterializationSpec(
                    behavior=PostOpBehavior.TERMINAL_ARRAY,
                    model_cls=None,
                    raw_mode=True,
                ),
            ),
            auxiliary_ctes=_collect_auxiliary_ctes_from_consumed([cte_ref]),
        )


def _lower_query_delete_intent(
    self: QueryDeleteIntent,
    ctx: LoweringContext,
) -> Sequence[ServerPlanStep[Any]]:
    from impl.common.l2070_server_plan.steps._versioned_routing import (
        get_versioned_staging_ctx,
        is_versioned_model,
        is_versioned_operation,
    )

    leading_steps, user_id_ref_id = _build_session_user_resolution(
        owner_ref_id=self.ref_id,
        model_cls=self.model_cls,
        ctx=ctx,
        permission_filtering_enabled=not getattr(self.query_spec, "skip_permission_filtering", False),
        query_spec=self.query_spec,
    )

    if is_versioned_model(self.model_cls) and (is_versioned_operation(self.model_cls, ctx) or ctx.is_versioned):
        steps: list[ServerPlanStep[Any]] = list(leading_steps)
        sc = get_versioned_staging_ctx(self.model_cls, ctx)
        if sc is not None:
            from impl.common.l2070_server_plan.steps.intent_versioning_extended import (
                VersionedDeleteManyIntent,
                _VersionedDeleteManyConfig,
            )
            from impl.common.l2070_server_plan.steps.versioned_query_steps import (
                build_versioned_query_from_spec_steps,
                VersionedQueryFromSpecStep,
                _VersionedQueryFromSpecConfig,
            )

            branch_steps, branch_id, branch_ref_id, revision_id, revision_ref_id = _versioned_query_branch_and_revision_inputs(
                ctx=ctx,
                ref_id=ServerPlanRefId(f"{self.ref_id}_resolve_branch"),
            )
            if revision_id is None and revision_ref_id is None and ctx.lazy_revision is not None:
                revision_ref_id = _context_revision_ref_id_for_read(
                    ctx,
                    ctx_lazy_revision_ref(ctx),
                    None,
                )
            selected_ref = ServerPlanRefId(f"{self.ref_id}.selected_rows")
            steps.extend(branch_steps)
            steps.extend(
                build_versioned_query_from_spec_steps(
                    ref_id=selected_ref,
                    model_cls=self.model_cls,
                    config=_VersionedQueryFromSpecConfig(
                        query_spec=self.query_spec,
                        branch_id=branch_id,
                        branch_ref_id=branch_ref_id,
                        revision_id=revision_id,
                        revision_ref_id=revision_ref_id,
                        user_id_ref_id=user_id_ref_id,
                        raw_mode=True,
                        publication_read_flavor=READ_FLAVOR_SPARSE_HISTORICAL,
                    ),
                ),
            )
            steps.extend(
                VersionedDeleteManyIntent(
                    self.ref_id,
                    self.model_cls,
                    cast(
                        "Any",
                        _VersionedDeleteManyConfig(
                            sys_ids=(),
                            staging_ctx=sc,
                            after_refs=self.after_refs | frozenset({selected_ref}),
                            source_ref=selected_ref,
                            user_id_ref_id=user_id_ref_id,
                        ),
                    ),
                ).lower(ctx),
            )
            return steps
        msg = "Versioned query delete requires versioned staging context"
        raise RuntimeError(msg)

    from impl.common.l2070_server_plan.steps.embedding_auto_queue_intent import (
        EmbeddingDeleteCleanupIntent,
        _EmbeddingDeleteCleanupConfig,
        _ResolveObjectIdsConfig,
        _ResolveObjectIdsStep,
    )
    from impl.common.l2070_server_plan.steps.query_delete import (
        QueryDeleteStep,
        _QueryDeleteStepConfig,
    )
    from impl.common.l2070_server_plan.steps.query_execute import (
        QueryExecuteStep,
        _QueryExecuteStepConfig,
    )
    from l1000_schema.large_column import get_large_column_configs
    from l5200_vector_index.vector_config import get_vector_indexes

    delta_configs = tuple(
        config for config in get_large_column_configs(self.model_cls) if config.delta_storage is not None and config.delta_storage.enabled
    )

    def _with_delta_cleanup(
        mutation_steps: list[ServerPlanStep[Any]],
        *,
        source_ref: ServerPlanRefId,
        extra_after_refs: tuple[ServerPlanRefId, ...] = (),
    ) -> list[ServerPlanStep[Any]]:
        if not delta_configs:
            return mutation_steps
        from impl.common.l2070_server_plan.steps.collect_results import (
            ReturnSourceAfterDepsConfig,
            ReturnSourceAfterDepsStep,
        )
        from impl.common.l2070_server_plan.steps.intent_content_delta_storage import (
            build_delta_orphan_cleanup_steps,
        )

        cleanup_steps, cleanup_after_refs = build_delta_orphan_cleanup_steps(
            ref_prefix=ServerPlanRefId(self.ref_id),
            model_cls=self.model_cls,
            configs=delta_configs,
            after_ref=source_ref,
        )
        return [
            *mutation_steps,
            *cleanup_steps,
            ReturnSourceAfterDepsStep[int](
                ServerPlanRefId(self.ref_id),
                ReturnSourceAfterDepsConfig(
                    source_ref=source_ref,
                    after_refs=(*cleanup_after_refs, *extra_after_refs),
                ),
            ),
        ]

    if get_vector_indexes(self.model_cls):
        selected_rows_ref = f"{self.ref_id}_selected_rows"
        object_ids_ref = f"{self.ref_id}_object_ids"
        delete_ref = self.ref_id if not delta_configs else ServerPlanRefId(f"{self.ref_id}.write")
        embedding_cleanup_ref = ServerPlanRefId(f"{self.ref_id}_emb_cleanup")
        mutation_steps: list[ServerPlanStep[Any]] = [
            *leading_steps,
            QueryExecuteStep(
                ServerPlanRefId(selected_rows_ref),
                self.model_cls,
                _QueryExecuteStepConfig(
                    query_spec=self.query_spec,
                    raw_mode=True,
                    user_id_ref_id=user_id_ref_id,
                ),
            ),
            _ResolveObjectIdsStep(
                ServerPlanRefId(object_ids_ref),
                ServerPlanRefId(selected_rows_ref),
                config=_ResolveObjectIdsConfig(
                    after_refs=frozenset({ServerPlanRefId(selected_rows_ref)}),
                ),
            ),
            QueryDeleteStep(
                ServerPlanRefId(delete_ref),
                self.model_cls,
                _QueryDeleteStepConfig(
                    query_spec=self.query_spec,
                    after_refs=frozenset({ServerPlanRefId(selected_rows_ref)}),
                    user_id_ref_id=(user_id_ref_id),
                ),
            ),
            EmbeddingDeleteCleanupIntent(
                embedding_cleanup_ref,
                self.model_cls,
                ServerPlanRefId(object_ids_ref),
                config=_EmbeddingDeleteCleanupConfig(trigger_ref=ServerPlanRefId(delete_ref)),
            ),
        ]
        return _with_delta_cleanup(
            mutation_steps,
            source_ref=ServerPlanRefId(delete_ref),
            extra_after_refs=(embedding_cleanup_ref,),
        )

    from impl.common.l2070_server_plan.steps._query_spec_chunking import (
        split_query_spec_on_oversized_literal_in,
    )

    split_specs = split_query_spec_on_oversized_literal_in(
        self.query_spec,
        backend_type=ctx.backend_type,
        preserve_read_semantics=False,
    )
    if split_specs is not None:
        from impl.common.l2070_server_plan.steps.collect_results import SumIntResultsStep

        chunk_steps: list[ServerPlanStep[Any]] = list(leading_steps)
        chunk_refs: list[str] = []
        for idx, split_spec in enumerate(split_specs):
            chunk_ref = f"{self.ref_id}_chunk_{idx}"
            chunk_refs.append(chunk_ref)
            chunk_steps.append(
                QueryDeleteStep(
                    ServerPlanRefId(chunk_ref),
                    self.model_cls,
                    _QueryDeleteStepConfig(
                        query_spec=split_spec,
                        user_id_ref_id=(user_id_ref_id),
                    ),
                ),
            )
        count_ref = self.ref_id if not delta_configs else ServerPlanRefId(f"{self.ref_id}.write_count")
        chunk_steps.append(SumIntResultsStep(ServerPlanRefId(count_ref), chunk_refs))
        return _with_delta_cleanup(chunk_steps, source_ref=ServerPlanRefId(count_ref))

    delete_ref = self.ref_id if not delta_configs else ServerPlanRefId(f"{self.ref_id}.write")
    mutation_steps = [
        *leading_steps,
        QueryDeleteStep(
            ServerPlanRefId(delete_ref),
            self.model_cls,
            _QueryDeleteStepConfig(
                query_spec=self.query_spec,
                after_refs=self.after_refs,
                user_id_ref_id=(user_id_ref_id),
                preimage_ref_id=self.preimage_ref_id,
                effect_only=self.effect_only,
            ),
        ),
    ]
    return _with_delta_cleanup(mutation_steps, source_ref=ServerPlanRefId(delete_ref))


class QueryUpdateIntent(_QueryPermissionPlanningMixin, IntentStep[int]):
    """L4: Update rows matching a query."""

    intent_tags = frozenset({"write", "update", "query", "intent"})
    intent_cardinality = Cardinality.SCALAR
    model_cls: type[DatabaseObjectRow]
    query_spec: Any
    updates: dict[str, Any]

    def __init__(
        self: QueryUpdateIntent,
        ref_id: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        config: _QueryUpdateConfig,
    ) -> None:
        super().__init__(ref_id)
        self.model_cls = model_cls
        self.query_spec = config.query_spec
        self.updates = config.updates
        self.after_refs = config.after_refs
        self.pre_write_after_refs = config.pre_write_after_refs

    def tables_written(self: QueryUpdateIntent) -> frozenset[str]:
        table_name = str(get_table_name(self.model_cls))
        if issubclass(self.model_cls, VersionedObjectRow):
            table_name = str(
                derive_versioned_table_names(
                    VersionedBaseTableName(table_name),
                ).staged,
            )
        return frozenset({table_name})

    def dependencies(self: QueryUpdateIntent) -> frozenset[str]:
        """Return exact write-order dependencies declared by the query builder."""
        return frozenset(str(ref) for ref in self.after_refs | self.pre_write_after_refs)

    def commit_dependency_ref_id(self: QueryUpdateIntent) -> ServerPlanRefId:
        """Return the exact written-row relation used by publication admission."""
        if issubclass(self.model_cls, VersionedObjectRow):
            return ServerPlanRefId(f"{self.ref_id}.write_batch_return.raw_rows")
        return ServerPlanRefId(f"{self.ref_id}.write")

    def additional_batch_binding_ref_ids(self: QueryUpdateIntent) -> tuple[ServerPlanRefId, ...]:
        return (ServerPlanRefId(f"{self.ref_id}.updated_count"),)

    def affected_count_source_contract(self: QueryUpdateIntent) -> AffectedCountSourceContract:
        if issubclass(self.model_cls, VersionedObjectRow):
            return AffectedCountSourceContract(
                sql_ref=ServerPlanRefId(f"{self.ref_id}.updated_rows"),
                producer_ref=self.ref_id,
                scheduling_dependency_ref=self.ref_id,
                representation=AffectedCountSourceRepresentation.ROW_RELATION,
                requires_atomic_cte_region=False,
            )
        return AffectedCountSourceContract(
            sql_ref=self.ref_id,
            producer_ref=self.ref_id,
            scheduling_dependency_ref=self.ref_id,
            representation=AffectedCountSourceRepresentation.SCALAR_COUNT,
            value_column=LockedColumnName("count"),
            ordered_statement_mode=(
                AffectedCountOrderedStatementMode.DRIVER_COUNT_WITHOUT_SQL_RELATION
                if self.after_refs
                else AffectedCountOrderedStatementMode.DRIVER_COUNT
            ),
        )

    def lower(self: QueryUpdateIntent, ctx: LoweringContext) -> Sequence[ServerPlanStep[Any]]:
        return _lower_query_update_intent(self, ctx)


def _query_spec_for_versioned_update_selection(query_spec: Any) -> Any:
    """Select full versioned rows before overlaying update assignments."""
    if query_spec is None:
        return None
    if not getattr(query_spec, "select_columns", None) and not getattr(query_spec, "select_column_tables", None):
        return query_spec

    if is_dataclass(query_spec) and not isinstance(query_spec, type):
        updates: dict[str, object] = {}
        field_names = {field.name for field in fields(query_spec)}
        if "select_columns" in field_names:
            updates["select_columns"] = None
        if "select_column_tables" in field_names:
            updates["select_column_tables"] = {}
        if "default_projection_columns" in field_names:
            updates["default_projection_columns"] = None
        return replace(query_spec, **updates) if updates else query_spec

    clone = copy(query_spec)
    if hasattr(clone, "select_columns"):
        setattr(clone, "select_columns", None)
    if hasattr(clone, "select_column_tables"):
        setattr(clone, "select_column_tables", {})
    if hasattr(clone, "default_projection_columns"):
        setattr(clone, "default_projection_columns", None)
    return clone


def _query_spec_has_json_function_filter(query_spec: Any) -> bool:
    def _expr_has_json_function(value: object) -> bool:
        function = getattr(value, "function", None)
        if function is not None and "JSON_GET_" in str(function):
            return True
        for attr in ("left", "right"):
            child = getattr(value, attr, None)
            if child is not None and _expr_has_json_function(child):
                return True
        for child in getattr(value, "args", ()) or ():
            if _expr_has_json_function(child):
                return True
        for child in getattr(value, "expressions", ()) or ():
            if _expr_has_json_function(child):
                return True
        return False

    for query_filter in getattr(query_spec, "filters", ()) or ():
        expression = getattr(query_filter, "expression", None)
        if expression is not None and _expr_has_json_function(expression):
            return True
    return False


def _lower_query_update_intent(
    self: QueryUpdateIntent,
    ctx: LoweringContext,
) -> Sequence[ServerPlanStep[Any]]:
    from impl.common.l2070_server_plan.steps.collect_results import (
        CountSequenceItemsStep,
        ReturnSourceAfterDepsConfig,
        ReturnSourceAfterDepsStep,
    )
    from impl.common.l2070_server_plan.steps.query_update import (
        QueryUpdateStep,
        _QueryUpdateStepConfig,
    )
    from l5200_vector_index.vector_config import get_vector_indexes

    leading_steps, user_id_ref_id = _build_session_user_resolution(
        owner_ref_id=self.ref_id,
        model_cls=self.model_cls,
        ctx=ctx,
        permission_filtering_enabled=not getattr(self.query_spec, "skip_permission_filtering", False),
        query_spec=self.query_spec,
    )

    from impl.common.l2070_server_plan.steps._versioned_routing import (
        get_versioned_staging_ctx,
        is_versioned_model,
        is_versioned_operation,
    )

    if is_versioned_model(self.model_cls) and (is_versioned_operation(self.model_cls, ctx) or ctx.is_versioned):
        from impl.common.l2070_server_plan.steps.intent_versioning_extended import (
            VersionedUpdateManyBatchIntent,
            _VersionedBatchSourceOrder,
            _VersionedUpdateManyBatchConfig,
            versioned_write_raw_rows_source_ref,
        )
        from impl.common.l2070_server_plan.steps.versioned_query_steps import (
            build_versioned_query_from_spec_steps,
            VersionedQueryFromSpecStep,
            _VersionedQueryFromSpecConfig,
        )
        from l2070_batching.server_ref import ObjectSequenceServerRef

        sc = get_versioned_staging_ctx(self.model_cls, ctx)
        if sc is None:
            msg = "Versioned query update requires versioned staging context"
            raise RuntimeError(msg)
        branch_steps, branch_id, branch_ref_id, revision_id, revision_ref_id = _versioned_query_branch_and_revision_inputs(
            ctx=ctx,
            ref_id=ServerPlanRefId(f"{self.ref_id}_resolve_branch"),
        )
        selected_ref = ServerPlanRefId(f"{self.ref_id}.selected_rows")
        updated_ref = ServerPlanRefId(f"{self.ref_id}.updated_rows")
        write_ref = ServerPlanRefId(f"{self.ref_id}.write")
        written_raw_ref = versioned_write_raw_rows_source_ref(
            ServerPlanRefId(f"{write_ref}_batch_return"),
        )
        updated_count_ref = ServerPlanRefId(f"{self.ref_id}.updated_count")
        selection_branch_id = branch_id
        selection_branch_ref_id = branch_ref_id
        selection_revision_id = revision_id
        selection_revision_ref_id = revision_ref_id
        update_selection_query_spec = _query_spec_for_versioned_update_selection(self.query_spec)
        original_has_json_filter = _query_spec_has_json_function_filter(self.query_spec)
        selection_has_json_filter = _query_spec_has_json_function_filter(update_selection_query_spec)
        if (original_has_json_filter or selection_has_json_filter) and not ctx.branch_tip_materialized:
            lazy_revision_ref = ctx_lazy_revision_ref(ctx)
            historical_revision_ref_id = _context_revision_ref_id_for_read(
                ctx,
                lazy_revision_ref,
                _resolve_context_revision_literal(ctx),
            )
            if historical_revision_ref_id is None and ctx.branch_id is not None and ctx.branch_table is not None:
                from impl.common.l2070_server_plan.steps.resolve_branch_steps import ResolveBranchTipRevisionStep

                historical_revision_ref_id = ServerPlanRefId(f"{self.ref_id}_resolve_tip_for_json")
                branch_steps = [
                    *branch_steps,
                    ResolveBranchTipRevisionStep(
                        historical_revision_ref_id,
                        branch_id=ServerRefs.scalar(BranchId(ctx.branch_id)),
                        branch_table=SqlTableName(ctx.branch_table),
                        branch_id_column=ctx.branch_id_column,
                        tip_revision_column=ctx.branch_tip_revision_column,
                    ),
                ]
            if historical_revision_ref_id is None and selection_branch_ref_id is not None and ctx.branch_table is not None:
                from impl.common.l2070_server_plan.steps.resolve_branch_steps import ResolveBranchTipRevisionStep

                historical_revision_ref_id = ServerPlanRefId(f"{self.ref_id}_resolve_tip_for_json")
                branch_steps = [
                    *branch_steps,
                    ResolveBranchTipRevisionStep(
                        historical_revision_ref_id,
                        branch_id=ServerRefs.from_ref_id(
                            selection_branch_ref_id,
                            variant="scalar",
                            type_hint=BranchId,
                        ),
                        branch_table=SqlTableName(ctx.branch_table),
                        branch_id_column=ctx.branch_id_column,
                        tip_revision_column=ctx.branch_tip_revision_column,
                    ),
                ]
            if historical_revision_ref_id is not None:
                selection_revision_id = None
                selection_revision_ref_id = historical_revision_ref_id
        effective_updates = dict(self.updates)
        spill_steps: list[ServerPlanStep[Any]] = []
        from impl.common.l2070_server_plan.steps._versioned_staging import (
            build_large_column_spill_steps,
            copy_large_column_pointer_assignments,
            prepare_large_column_spill_plan_from_tuples,
        )
        from l1000_schema.large_column import get_large_column_configs, large_column_pointer_name
        from l1000_schema.typed_field import Expression, Field
        from l2070_batching.sql_renderable import SqlRenderable

        large_column_configs = get_large_column_configs(self.model_cls)
        copy_large_column_pointer_assignments(self.model_cls, effective_updates)
        for config in large_column_configs:
            column = str(config.column)
            if column not in effective_updates:
                continue
            value = effective_updates[column]
            if isinstance(value, (Expression, Field, SqlRenderable)):
                continue
            pointer = large_column_pointer_name(config.column)
            if value is None:
                effective_updates[pointer] = None
                continue
            rows, spill_plan = prepare_large_column_spill_plan_from_tuples(
                self.model_cls,
                [column, pointer],
                [(value, None)],
                backend_type=ctx.backend_type,
            )
            rewritten = rows[0]
            effective_updates[column] = rewritten[0]
            effective_updates[pointer] = rewritten[1]
            if spill_plan.rows or spill_plan.delta_rows:
                spill_steps.extend(
                    build_large_column_spill_steps(
                        self.model_cls,
                        spill_plan,
                        write_ref_id=ServerPlanRefId(f"{self.ref_id}.{column}.spill"),
                    ),
                )
        spill_after_refs = frozenset(ServerPlanRefId(step.ref_id) for step in spill_steps)
        selected_steps = build_versioned_query_from_spec_steps(
            ref_id=selected_ref,
            model_cls=self.model_cls,
            config=_VersionedQueryFromSpecConfig(
                query_spec=update_selection_query_spec,
                after_refs=self.after_refs,
                branch_id=selection_branch_id,
                branch_ref_id=selection_branch_ref_id,
                revision_id=selection_revision_id,
                revision_ref_id=selection_revision_ref_id,
                user_id_ref_id=user_id_ref_id,
                raw_mode=True,
                always_publish_executor_binding=True,
                publication_read_flavor=READ_FLAVOR_STAGED_MERGED,
            ),
        )
        selected_publisher = next(step for step in selected_steps if step.ref_id == selected_ref)
        selected_source_columns = selected_publisher.cte_publication_contract().columns
        updated_rows_step = _ApplyQueryUpdatesToRowsStep(
            updated_ref,
            config=_ApplyQueryUpdatesToRowsConfig(
                model_cls=self.model_cls,
                source_ref=selected_ref,
                updates=effective_updates,
                source_columns=selected_source_columns,
            ),
        )
        updated_source_columns = updated_rows_step.cte_publication_contract().columns
        return [
            *leading_steps,
            *branch_steps,
            *spill_steps,
            *selected_steps,
            updated_rows_step,
            *VersionedUpdateManyBatchIntent(
                write_ref,
                self.model_cls,
                cast(
                    ObjectSequenceServerRef[Any],
                    ServerRefs.from_ref_id(updated_ref, variant="object_sequence"),
                ),
                cast(
                    "Any",
                    _VersionedUpdateManyBatchConfig(
                        staging_ctx=sc,
                        source_order=_VersionedBatchSourceOrder.UNORDERED,
                        after_refs=frozenset({updated_ref}) | spill_after_refs | self.after_refs,
                        source_existence_prevalidated=True,
                        user_id_ref_id=user_id_ref_id,
                        source_columns=updated_source_columns,
                    ),
                ),
            ).lower(ctx),
            CountSequenceItemsStep(
                ServerPlanRefId(updated_count_ref),
                source_ref=written_raw_ref,
            ),
            CountSequenceItemsStep(
                ServerPlanRefId(self.ref_id),
                source_ref=written_raw_ref,
            ),
        ]

    from impl.common.l2070_server_plan.steps.write_side_effect_intents import _has_matching_table_subscriptions

    if ctx.emit_table_event_intents and _has_matching_table_subscriptions(self.model_cls, "UPDATE"):
        from impl.common.l2070_server_plan.steps.intent_query_extended import QueryUpdateReturningIntent, _QueryUpdateReturningConfig

        returning_ref = ServerPlanRefId(f"{self.ref_id}.returning")
        return [
            *QueryUpdateReturningIntent(
                returning_ref,
                self.model_cls,
                _QueryUpdateReturningConfig(
                    query_spec=self.query_spec,
                    updates=self.updates,
                    pre_write_after_refs=self.after_refs,
                ),
            ).lower(ctx),
            CountSequenceItemsStep(
                ServerPlanRefId(self.ref_id),
                source_ref=ServerPlanRefId(f"{returning_ref}.updated_rows"),
            ),
        ]

    if get_vector_indexes(self.model_cls):
        from impl.common.l2070_server_plan.steps.intent_query_extended import (
            QueryUpdateReturningIntent,
            _QueryUpdateReturningConfig,
        )

        returning_ref = ServerPlanRefId(f"{self.ref_id}.vector_returning")
        return [
            *QueryUpdateReturningIntent(
                returning_ref,
                self.model_cls,
                _QueryUpdateReturningConfig(
                    query_spec=self.query_spec,
                    updates=self.updates,
                    pre_write_after_refs=self.after_refs,
                ),
            ).lower(ctx),
            CountSequenceItemsStep(
                ServerPlanRefId(self.ref_id),
                source_ref=ServerPlanRefId(f"{returning_ref}.updated_rows"),
            ),
        ]

    effective_updates = dict(self.updates)
    fallback_spill_steps: list[ServerPlanStep[Any]] = []
    from impl.common.l2070_server_plan.steps._versioned_staging import (
        build_large_column_spill_steps,
        copy_large_column_pointer_assignments,
        prepare_large_column_spill_plan_from_tuples,
    )
    from l1000_schema.large_column import ContentColumnName, get_large_column_configs, large_column_pointer_name
    from l1000_schema.typed_field import Expression, Field
    from l2070_batching.sql_renderable import SqlRenderable

    copy_large_column_pointer_assignments(self.model_cls, effective_updates)
    for config in get_large_column_configs(self.model_cls):
        column = str(config.column)
        if column not in effective_updates:
            continue
        value = effective_updates[column]
        if isinstance(value, Field):
            continue
        if isinstance(value, (Expression, SqlRenderable)):
            if config.delta_storage is not None and config.delta_storage.enabled:
                msg = (
                    f"Expression updates are not supported for delta-stored column "
                    f"{self.model_cls.__name__}.{column}; provide a concrete value"
                )
                raise ValueError(msg)
            continue
        pointer = large_column_pointer_name(ContentColumnName(column))
        if value is None:
            effective_updates[pointer] = None
            continue
        rows, spill_plan = prepare_large_column_spill_plan_from_tuples(
            self.model_cls,
            [column, pointer],
            [(value, None)],
            backend_type=ctx.backend_type,
        )
        rewritten = rows[0]
        effective_updates[column] = rewritten[0]
        effective_updates[pointer] = rewritten[1]
        if spill_plan.rows or spill_plan.delta_rows:
            fallback_spill_steps.extend(
                build_large_column_spill_steps(
                    self.model_cls,
                    spill_plan,
                    write_ref_id=ServerPlanRefId(f"{self.ref_id}.{column}.spill"),
                ),
            )
    write_ref = ServerPlanRefId(f"{self.ref_id}.write")
    from impl.common.l2070_server_plan.steps.intent_content_delta_storage import (
        build_delta_orphan_cleanup_steps,
    )

    changed_delta_configs = tuple(
        config
        for config in get_large_column_configs(self.model_cls)
        if str(config.column) in effective_updates and config.delta_storage is not None and config.delta_storage.enabled
    )
    cleanup_steps, cleanup_after_refs = build_delta_orphan_cleanup_steps(
        ref_prefix=ServerPlanRefId(self.ref_id),
        model_cls=self.model_cls,
        configs=changed_delta_configs,
        after_ref=write_ref,
    )
    if not cleanup_steps:
        steps = [
            *leading_steps,
            *fallback_spill_steps,
            QueryUpdateStep(
                self.ref_id,
                self.model_cls,
                _QueryUpdateStepConfig(
                    query_spec=self.query_spec,
                    updates=effective_updates,
                    after_refs=self.after_refs | frozenset(ServerPlanRefId(step.ref_id) for step in fallback_spill_steps),
                    user_id_ref_id=(user_id_ref_id),
                ),
            ),
        ]
        return _insert_hydrated_scalar_projection_steps(steps, ctx)
    steps = [
        *leading_steps,
        *fallback_spill_steps,
        QueryUpdateStep(
            write_ref,
            self.model_cls,
            _QueryUpdateStepConfig(
                query_spec=self.query_spec,
                updates=effective_updates,
                after_refs=self.after_refs | frozenset(ServerPlanRefId(step.ref_id) for step in fallback_spill_steps),
                user_id_ref_id=(user_id_ref_id),
            ),
        ),
        *cleanup_steps,
        ReturnSourceAfterDepsStep[int](
            ServerPlanRefId(self.ref_id),
            ReturnSourceAfterDepsConfig(
                source_ref=write_ref,
                after_refs=tuple(cleanup_after_refs),
            ),
        ),
    ]
    return _insert_hydrated_scalar_projection_steps(steps, ctx)


# Grammar class mapping (L4 → eventual L0 grammar):
# SelectOneIntent → SqlSelectStmt, SqlStagedTipUnionLookup (versioned)
# SelectManyIntent → SqlSelectStmt, SqlColumnInPlaceholders
# QueryExecuteIntent → SqlSelectStmt (via QueryGrammarBuilder)
# QueryFirstIntent → SqlSelectStmt with LIMIT 1
# QueryCountIntent → SqlCountQuery
# QueryDeleteIntent → SqlDeleteStmt with WHERE from QueryGrammarBuilder
# QueryUpdateIntent → SqlUpdateStmt with SET + WHERE from QueryGrammarBuilder

