def _has_matching_table_subscriptions(
    model_cls: type[DatabaseObjectRow],
    event_type: str,
) -> bool:
    from l5000_subscriptions.subscription import _get_graph_subscriptions, _get_subscriptions
    from l9600_graphs.graph import GraphEdge, GraphNode

    table_name = get_table_name(model_cls)
    registry_keys = (f"table:{table_name}", f"versioned_table:{table_name}")
    if issubclass(model_cls, GraphNode | GraphEdge) and any(
        event_type in subscription.get("event_types", ()) for subscription in _get_graph_subscriptions()
    ):
        return True
    return any(
        event_type in subscription.get("event_types", ())
        for registry_key in registry_keys
        for subscription in _get_subscriptions(registry_key)
    )


def _has_matching_staged_table_subscriptions(
    model_cls: type[DatabaseObjectRow],
    event_type: str,
) -> bool:
    from l5000_subscriptions.subscription import (
        SubscriptionPhase,
        SubscriptionRecord,
        _get_graph_subscriptions,
        _get_subscriptions,
        _subscription_accepts_phase,
    )
    from l9600_graphs.graph import GraphEdge, GraphNode

    def matches(record: SubscriptionRecord) -> bool:
        return event_type in record.get("event_types", ()) and _subscription_accepts_phase(
            record,
            SubscriptionPhase.STAGED,
        )

    table_name = get_table_name(model_cls)
    registry_keys = (f"table:{table_name}", f"versioned_table:{table_name}")
    if issubclass(model_cls, GraphNode | GraphEdge) and any(matches(record) for record in _get_graph_subscriptions()):
        return True
    return any(matches(record) for registry_key in registry_keys for record in _get_subscriptions(registry_key))


