def _auxiliary_ctes_for_rows_ref(
    ctx: CompilationContext,
    *,
    rows_ref: ServerPlanRefId,
    step_name: str,
) -> tuple[
    ServerPlanRefId,
    list[tuple[ServerPlanRefId, SqlRenderable]] | None,
    CteReference,
]:
    from impl.common.l2070_server_plan.steps._auxiliary_ctes import (
        resolve_auxiliary_cte_binding,
    )

    rows_cte = resolve_auxiliary_cte_binding(ctx, rows_ref)
    if not isinstance(rows_cte, CteReference):
        available_refs = (
            ", ".join(
                f"{key}->{candidate.ref_id}[aux={candidate.auxiliary_query is not None},ephemeral={candidate.ephemeral}]"
                if isinstance(candidate, CteReference)
                else f"{key}->{type(candidate).__name__}"
                for key, candidate in sorted(ctx.cte_refs.items())
            )
            if ctx.cte_refs
            else "<none>"
        )
        raise_missing_cte_fallback_forbidden(
            site_name=step_name,
            trigger=(
                f"rows ref {rows_ref!r} has no published CTE binding for polyfill FTS side-effect SQL (available refs: {available_refs})"
            ),
            blocked_path="compile-time polyfill FTS side-effect SQL outside explicit published CTE refs",
            result_contract=("polyfill FTS side-effect compilation must consume prepared rows from explicit CTE bindings"),
            implementation_requirements=(
                "Publish the prepared rows as an explicit CTE before compiling the polyfill FTS side effect.",
                "Thread that CTE binding through ctx.cte_refs into the side-effect compile path.",
                "Do not recover by reading resolved runtime rows during compile().",
            ),
        )
        raise AssertionError("unreachable")
    auxiliary_ctes = [(rows_cte.ref_id, rows_cte.auxiliary_query)] if rows_cte.auxiliary_query is not None else None
    return rows_cte.ref_id, auxiliary_ctes, rows_cte


