def _exact_notification_relation_contract(model_cls: type[DatabaseObjectRow]) -> RelationContract:
    columns = tuple(model_cls.model_fields)
    hints = model_and_framework_sql_column_type_hints(model_cls, columns)
    if hints is None:
        raise TypeError("Exact notification models must publish SQL column type metadata")
    return RelationContract(columns=columns, column_type_hints=hints)


class _TransactionalTableNotificationStep(NonPublishingStep[None]):
    """Publish exact row identity from bounded write-result relations."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        event_type: str,
        write_ref_id: ServerPlanRefId,
        *,
        relation_contract: RelationContract,
        old_rows_ref: ServerPlanRefId | None = None,
        versioned: bool = False,
        staged_branch_id: object | None = None,
        staged_commit_id: str | None = None,
        graph_routes: tuple[tuple[str, Literal["node", "edge"]], ...] = (),
        executor_materialized: bool = False,
        runtime_rows_ref: ServerPlanRefId | None = None,
        require_sql_relation: bool = False,
    ) -> None:
        from l2200_notification.polling_channel import NotificationRowId

        super().__init__(ref_id)
        self._model_cls = model_cls
        self._event_type = event_type
        self._write_ref_id = str(write_ref_id)
        self._relation_contract = relation_contract
        from l1000_schema.blob_type import is_blob_column

        from l1000_schema.typed_field import parse_cast_target_type
        from l2070_batching.sql_column_type_hints import model_field_cast_target

        runtime_cast_targets: dict[SqlColumnName, SqlCastTargetType] = {}
        for column in relation_contract.columns:
            field_info = model_cls.model_fields.get(column)
            if field_info is None:
                continue
            extra = field_info.json_schema_extra
            sql_type = extra.get("sql_type") if isinstance(extra, dict) else None
            cast_target = parse_cast_target_type(sql_type) if sql_type is not None else model_field_cast_target(model_cls, column)
            if cast_target is not None:
                runtime_cast_targets[SqlColumnName(column)] = cast_target
        self._runtime_cast_targets = runtime_cast_targets
        self._state_payload_supported = all(
            not is_blob_column(model_cls.model_fields[column].annotation)
            for column in relation_contract.columns
            if column in model_cls.model_fields and not column.startswith("sys_")
        )
        self._old_rows_ref = str(old_rows_ref) if old_rows_ref is not None else None
        self._versioned = versioned
        self._staged_branch_id = staged_branch_id
        self._staged_commit_id = staged_commit_id
        self._graph_routes = graph_routes
        self._notification_id = NotificationRowId.new()
        self._executor_materialized = executor_materialized
        self._runtime_transport = executor_materialized
        self._runtime_rows_ref = None if runtime_rows_ref is None else str(runtime_rows_ref)
        self._require_sql_relation = require_sql_relation
        self._ordered_runtime_transport = False

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.NONE

    def is_read_only(self) -> bool:
        return False

    def dependencies(self) -> frozenset[str]:
        refs = {_executor_runtime_relation_ref_id(self._write_ref_id) if self._runtime_transport else self._write_ref_id}
        if self._old_rows_ref is not None:
            refs.add(_executor_runtime_relation_ref_id(self._old_rows_ref) if self._runtime_transport else self._old_rows_ref)
        return frozenset(refs)

    def configure_backend_scheduling(self, profile: ServerPlanBackendProfile) -> None:
        self._runtime_transport = self._executor_materialized
        self._ordered_runtime_transport = (
            self._runtime_transport
            and profile.traits.executor_published_relation_transport is not ExecutorPublishedRelationTransport.CTE_RELATION
        )

    def consumes_executor_visible_dependencies(self) -> bool:
        return self._runtime_transport

    def is_executor_owned_runtime_step(self) -> bool:
        return self._runtime_transport

    def requires_materialized_inputs(self) -> bool:
        """Bind runtime payloads only after executor-visible write rows exist."""
        return self._runtime_transport and self._runtime_rows_ref is None

    def requires_runtime_sequential_batch(self) -> bool:
        """Prepare runtime publication after the write result is materialized."""
        return self._ordered_runtime_transport and self._runtime_rows_ref is None

    def requires_prior_step_boundary(self) -> bool:
        """Materialize rows when publication cannot consume a SQL relation."""
        return self._runtime_transport and self._runtime_rows_ref is None

    def supports_sql_batch_transport(self) -> bool:
        """Consume SQL-visible write relations in the producer statement group."""
        return not self._runtime_transport

    def allows_later_sql_transport(self) -> bool:
        return True

    def consumes_repeatable_post_write_relations_for_transport(
        self,
        transport: DmlResultTransport,
    ) -> bool:
        return not self._runtime_transport and transport is DmlResultTransport.RETURNING_RELATION

    def supports_ordered_sql_statement_batch(self) -> bool:
        """Keep SQL-visible commit relations in their atomic statement batch."""
        return not self._runtime_transport

    def requires_standalone_physical_request(self) -> bool:
        """Materialize SQL-only DML subrelations before runtime payload binding."""
        return self._executor_materialized and self._runtime_rows_ref is None

    def sql_visible_dependencies(self) -> frozenset[str]:
        """Return relation dependencies when the backend can preserve SQL visibility."""
        return frozenset() if self._runtime_transport else self.dependencies()

    def executor_visible_dependencies(self) -> frozenset[str]:
        return self.dependencies() if self._runtime_transport else frozenset()

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset({"sys_notifications"})

    def _require_relation(
        self,
        ctx: CompilationContext,
        ref_id: str,
    ) -> CteReference | _ExactRuntimeRelation:
        from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName
        from impl.common.l2100_sql_grammar.domain.notification import build_runtime_rows_relation
        from l2070_batching.compilation import CteReference

        relation = ctx.cte_refs.get(ref_id)
        resolved_runtime_ref_id = _executor_runtime_relation_ref_id(ref_id)
        if not isinstance(relation, CteReference):
            versioned_write_ref_id = f"{resolved_runtime_ref_id}.write"
            versioned_relation = ctx.cte_refs.get(versioned_write_ref_id)
            if isinstance(versioned_relation, CteReference):
                relation = versioned_relation
            elif ctx.is_versioned and resolved_runtime_ref_id.removeprefix("step_").isdigit():
                resolved_runtime_ref_id = versioned_write_ref_id
        if not isinstance(relation, CteReference) and self._require_sql_relation:
            raise_missing_cte_fallback_forbidden(
                site_name=type(self).__name__,
                trigger=f"rows ref {ref_id!r} has no published SQL relation binding",
                blocked_path="exact notification runtime-row fallback",
                result_contract="bounded exact publication consumes its producer-owned SQL relation",
                implementation_requirements=(
                    "Publish the bounded producer relation before compiling exact notification SQL.",
                    "Keep hydration, local delivery, and durable publication in the same physical request.",
                    "Do not recover by serializing executor-visible rows into a later request.",
                ),
            )
            raise AssertionError("unreachable")
        if not isinstance(relation, CteReference):
            columns = self._relation_contract.columns
            if "sys_id" not in columns:
                raise RuntimeError("Exact runtime notification rows must contain sys_id")
            runtime_ref_id = resolved_runtime_ref_id
            cast_targets = self._runtime_cast_targets
            relation_ref_id = "__exact_runtime_write" if ref_id == self._write_ref_id else "__exact_runtime_old"
            return _ExactRuntimeRelation(
                ref_id=relation_ref_id,
                source_ref=ServerPlanRefId(runtime_ref_id),
                contract=self._relation_contract,
                auxiliary_query=build_runtime_rows_relation(
                    ref_id=ServerPlanRefId(runtime_ref_id),
                    columns=tuple(SqlColumnName(column) for column in columns),
                    cast_targets=cast_targets,
                ),
            )
        if "sys_id" not in relation.columns:
            msg = f"Exact table notification relation {ref_id!r} must declare sys_id"
            raise RuntimeError(msg)
        return relation

    def compile(self, ctx: CompilationContext) -> CompiledStep[None]:
        from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName
        from impl.common.l2100_sql_grammar.domain.notification import (
            build_exact_table_notification_publication,
            build_mariadb_runtime_notification_publication,
        )
        from l2070_batching.compilation import CteReference
        from l2200_notification.polling_channel import NOTIFICATION_TTL_SECONDS
        from l5000_subscriptions.cross_process import (
            ExactNotificationRuntimeConfig,
            subscription_notification_sender_id,
        )

        write_relation = self._require_relation(ctx, self._write_ref_id)
        old_relation: CteReference | _ExactRuntimeRelation | None = None
        if self._old_rows_ref is not None:
            old_relation = self._require_relation(ctx, self._old_rows_ref)

        write_columns = set(write_relation.columns if isinstance(write_relation, CteReference) else write_relation.contract.columns)
        if self._graph_routes and "graph_sys_id" not in write_columns:
            raise RuntimeError("Exact graph notification relation must declare graph_sys_id")
        if self._versioned:
            missing_scope_columns = {"branch_id", "revision_id"} - write_columns
            if missing_scope_columns:
                missing = ", ".join(sorted(missing_scope_columns))
                raise RuntimeError(f"Exact versioned notification relation must declare {missing}")
        old_columns = (
            set(old_relation.columns if isinstance(old_relation, CteReference) else old_relation.contract.columns)
            if old_relation is not None
            else write_columns
        )
        semantic_columns = tuple(
            SqlColumnName(column)
            for column in self._relation_contract.columns
            if not column.startswith("sys_") and column in write_columns and column in old_columns
        )
        semantic_type_hints = self._relation_contract.column_type_hints
        numeric_columns = frozenset(column for column in semantic_columns if column in semantic_type_hints.numeric_columns)
        from impl.common.l2100_sql_grammar.domain.infra.request_scalar import SqlRequestRowRelation

        def _inline_request_row_query(
            relation: CteReference | _ExactRuntimeRelation | None,
        ) -> SqlRenderable | None:
            if isinstance(relation, _ExactRuntimeRelation):
                return relation.auxiliary_query
            if (
                isinstance(relation, CteReference)
                and relation.auxiliary_query is not None
                and (
                    isinstance(relation.auxiliary_query, SqlRequestRowRelation)
                    or ctx.backend_profile.traits.inline_auxiliary_relation_queries_in_consumers
                )
            ):
                return relation.auxiliary_query
            return None

        auxiliary_ctes: list[tuple[str, SqlRenderable]] = []
        for relation in (write_relation, old_relation):
            if (
                isinstance(relation, CteReference)
                and relation.auxiliary_query is not None
                and _inline_request_row_query(relation) is None
            ):
                auxiliary_ctes.append((relation.ref_id, relation.auxiliary_query))

        if self._executor_materialized:
            runtime_columns = tuple(SqlColumnName(column) for column in self._relation_contract.columns)
            runtime_write_ref_id = self._runtime_rows_ref or _executor_runtime_relation_ref_id(self._write_ref_id)
            runtime_old_rows_ref = _executor_runtime_relation_ref_id(self._old_rows_ref) if self._old_rows_ref is not None else None
            return CompiledStep(
                grammar=build_mariadb_runtime_notification_publication(
                    notifications_table=SqlTableName("sys_notifications"),
                    ref_id=ServerPlanRefId(runtime_write_ref_id),
                    columns=runtime_columns,
                    transformer=ExactNotificationRuntimeConfig(
                        sender_id=str(subscription_notification_sender_id()),
                        table_name=get_table_name(self._model_cls),
                        event_class=self._event_type.lower(),
                        versioned=self._versioned,
                        graph_routes=self._graph_routes,
                        semantic_columns=semantic_columns,
                        numeric_columns=numeric_columns,
                        old_rows_ref=runtime_old_rows_ref,
                        staged_branch_id=self._staged_branch_id,
                        staged_commit_id=self._staged_commit_id,
                        max_changes_per_envelope=int(
                            getattr(
                                self._model_cls,
                                "__subscription_max_changes_per_envelope__",
                                16 if self._graph_routes else 8,
                            ),
                        ),
                    ),
                    ttl_seconds=NOTIFICATION_TTL_SECONDS,
                ),
            )

        def _runtime_refs(relation: CteReference | _ExactRuntimeRelation | None) -> tuple[str, ...]:
            if not isinstance(relation, _ExactRuntimeRelation):
                return ()
            return (str(relation.source_ref),)

        runtime_ref_ids = tuple(
            dict.fromkeys(ref_id for relation in (write_relation, old_relation) for ref_id in _runtime_refs(relation)),
        )
        return CompiledStep(
            grammar=build_exact_table_notification_publication(
                backend_type=ctx.backend_type,
                notifications_table=SqlTableName("sys_notifications"),
                write_rows_relation=SqlTableName(write_relation.ref_id),
                old_rows_relation=SqlTableName(old_relation.ref_id) if old_relation is not None else None,
                semantic_columns=semantic_columns,
                numeric_columns=numeric_columns,
                notification_id=str(self._notification_id),
                write_rows_query=_inline_request_row_query(write_relation),
                old_rows_query=_inline_request_row_query(old_relation),
                sender_id=str(subscription_notification_sender_id()),
                table_name=get_table_name(self._model_cls),
                event_class=self._event_type.lower(),
                ttl_seconds=NOTIFICATION_TTL_SECONDS,
                versioned=self._versioned,
                staged_branch_id=self._staged_branch_id,
                staged_commit_id=self._staged_commit_id,
                max_changes_per_envelope=int(
                    getattr(
                        self._model_cls,
                        "__subscription_max_changes_per_envelope__",
                        16 if self._graph_routes else 8,
                    ),
                ),
                graph_routes=self._graph_routes,
                state_payload_supported=self._state_payload_supported,
            ),
            auxiliary_ctes=auxiliary_ctes or None,
            runtime_ref_ids=runtime_ref_ids,
        )


def _exact_graph_notification_routes(
    model_cls: type[DatabaseObjectRow],
) -> tuple[tuple[str, Literal["node", "edge"]], ...]:
    """Return graph routes registered on this concrete object model."""
    raw_routes = getattr(model_cls, "__nera_exact_graph_routes__", ())
    if not isinstance(raw_routes, tuple):
        raise TypeError("Exact graph notification routes must be a tuple")
    routes: list[tuple[str, Literal["node", "edge"]]] = []
    for raw_route in raw_routes:
        if (
            not isinstance(raw_route, tuple)
            or len(raw_route) != 2
            or not isinstance(raw_route[0], str)
            or raw_route[1] not in ("node", "edge")
        ):
            raise TypeError("Exact graph notification route must contain graph name and object kind")
        route: tuple[str, Literal["node", "edge"]] = (raw_route[0], raw_route[1])
        if route not in routes:
            routes.append(route)
    return tuple(routes)


class RecordTableEventIntent(NonPublishingStep[None]):
    """L4 semantic intent to record table-write events."""

    def __init__(
        self: RecordTableEventIntent,
        ref_id: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        config: _RecordTableEventConfig,
    ) -> None:
        super().__init__(ref_id)
        self._model_cls = model_cls
        self._event_type: Literal["INSERT", "UPDATE", "UPSERT", "DELETE"] = config.event_type
        self._write_ref_id = str(config.write_ref_id)
        self._hydrated_rows_ref = config.hydrated_rows_ref
        self._old_rows_ref = config.old_rows_ref
        self._completion_ref = config.completion_ref
        self._after_refs = config.after_refs
        self._replayable_visible_rows = config.replayable_visible_rows
        self._visible_rows_cardinality = config.visible_rows_cardinality
        self._ensure_late_subscriber_delivery = config.ensure_late_subscriber_delivery
        self._delivery_order = config.delivery_order
        self._literal_rows = config.literal_rows

    @property
    def level(self: RecordTableEventIntent) -> int:
        return 3

    def result_cardinality(self: RecordTableEventIntent) -> Cardinality:
        return Cardinality.NONE

    def is_read_only(self: RecordTableEventIntent) -> bool:
        return True

    def tables_read(self: RecordTableEventIntent) -> frozenset[str]:
        return frozenset({get_table_name(self._model_cls)})

    def tables_written(self: RecordTableEventIntent) -> frozenset[str]:
        return frozenset()

    def lower(self: RecordTableEventIntent, ctx: LoweringContext) -> Sequence[ServerPlanStep[Any]]:
        from impl.common.l2070_server_plan.steps._versioned_routing import (
            get_versioned_staging_ctx,
            is_versioned_operation,
        )
        from l2070_batching.server_ref import ServerRefs
        from l5100_fts.fts_config import FTSIndexImplementation, get_fts_config

        steps: list[ServerPlanStep[Any]] = []

        def preserve_completion_ref() -> list[ServerPlanStep[Any]]:
            if any(step.ref_id == self.ref_id for step in steps):
                return steps
            from impl.common.l2070_server_plan.steps.runtime_fallback import DependencyBarrierStep

            fallback_ref = str(self._completion_ref or self._write_ref_id)
            if self._completion_ref is None:
                for internal_suffix in (".raw", ".selected"):
                    if fallback_ref.endswith(internal_suffix):
                        fallback_ref = fallback_ref[: -len(internal_suffix)]
                        break
            completion_deps = tuple(step.ref_id for step in steps) or (ServerPlanRefId(fallback_ref),)
            steps.append(
                DependencyBarrierStep(
                    self.ref_id,
                    after_refs=completion_deps,
                ),
            )
            return steps

        fts_config = get_fts_config(self._model_cls)
        explicit_polyfill = fts_config is not None and fts_config.implementation is FTSIndexImplementation.POLYFILL
        if not ctx.is_versioned and self._event_type != "DELETE" and explicit_polyfill:
            operation: Literal["insert", "update"] = "insert" if self._event_type == "INSERT" else "update"
            steps.extend(
                MaintainFtsIndexIntent(
                    ServerPlanRefId(f"{self.ref_id}_fts_polyfill"),
                    self._model_cls,
                    _MaintainFtsIndexConfig(
                        operation=operation,
                        write_ref_id=ServerPlanRefId(self._write_ref_id),
                    ),
                ).lower(ctx),
            )
        staged_remote_publication = (
            ctx.backend_profile.traits.versioned_staging_transport is VersionedStagingTransport.SAME_STATEMENT_RELATION
            and getattr(self._model_cls, "__staged_cross_process_notifications__", False) is True
        )
        table_name = get_table_name(self._model_cls)
        publishes_remote_events = getattr(self._model_cls, "__subscription_notifications__", True)
        is_versioned = is_versioned_operation(self._model_cls, ctx)
        has_subscriptions = (
            not _is_versioning_infrastructure_model(self._model_cls)
            and publishes_remote_events is not False
            and (
                _has_matching_table_subscriptions(self._model_cls, self._event_type)
                or (
                    (
                        self._ensure_late_subscriber_delivery
                        or getattr(self._model_cls, "__subscription_notifications__", None) is True
                    )
                    and ctx.emit_table_event_intents
                    and not _is_versioning_infrastructure_model(self._model_cls)
                )
            )
        )
        has_hooks = ctx.emit_table_event_intents and _has_matching_table_hooks(
            self._model_cls,
            self._event_type,
        )
        if has_subscriptions or has_hooks:
            writer_steps, writer_ref = subscription_writer_steps(ctx, ServerPlanRefId(self.ref_id))
            steps.extend(writer_steps)
            config = _TableEventSubscriptionLifecycleConfig(
                event_type=self._event_type,
                writer_ref=writer_ref,
                visible_rows_ref=ServerPlanRefId(self._write_ref_id),
                hydrated_rows_ref=self._hydrated_rows_ref,
                replayable_visible_rows=self._replayable_visible_rows,
                old_rows_ref=self._old_rows_ref,
                completion_ref=self._completion_ref,
                after_refs=self._after_refs,
                capture_mutation_rows=not self._replayable_visible_rows,
                allow_sql_batch_transport=(
                    self._replayable_visible_rows
                    or ctx.backend_profile.traits.table_event_lifecycle_transport is TableEventLifecycleTransport.ORDERED_BATCH_RUNTIME
                ),
                delivery_order=self._delivery_order,
            )
            if has_subscriptions:
                steps.append(
                    _TableEventSubscriptionLifecycleStep(
                        ServerPlanRefId(self.ref_id),
                        self._model_cls,
                        config,
                    ),
                )
            if has_hooks:
                steps.append(
                    _TableHookLifecycleStep(
                        ServerPlanRefId(f"{self.ref_id}_hooks"),
                        self._model_cls,
                        config,
                    ),
                )

        if table_name.startswith("sys_") or publishes_remote_events is False:
            return preserve_completion_ref()
        from l5000_subscriptions.cross_process import cross_process_runtime_active

        notification_table_exists = ctx.cached_table_exists(SqlTableName("sys_notifications"))
        request_local_relation = (
            self._replayable_visible_rows
            and self._visible_rows_cardinality.is_at_most_one()
            and ctx.backend_profile.traits.request_scalar_transport is RequestScalarTransport.ANONYMOUS_BLOCK
        )
        non_cte_relation_transport = (
            ctx.backend_profile.traits.executor_published_relation_transport is not ExecutorPublishedRelationTransport.CTE_RELATION
        )
        if (
            self._replayable_visible_rows
            and self._visible_rows_cardinality.is_at_most_one()
            and non_cte_relation_transport
            and not request_local_relation
        ):
            raise TypeError("Bounded exact publication requires request-local relation transport")
        durable_remote_publication = getattr(self._model_cls, "__subscription_notifications__", None) is True or (
            has_subscriptions and cross_process_runtime_active()
        )
        if (durable_remote_publication and notification_table_exists is True) or (
            staged_remote_publication and notification_table_exists is not False
        ):
            notification_ref = ServerPlanRefId(f"{self.ref_id}_remote_notification")
            old_rows_ref = self._old_rows_ref if self._old_rows_ref is not None and self._event_type in ("UPDATE", "UPSERT") else None
            runtime_rows_ref: ServerPlanRefId | None = None
            if self._literal_rows and (
                ctx.backend_profile.traits.executor_published_relation_transport is not ExecutorPublishedRelationTransport.CTE_RELATION
            ):
                runtime_rows_ref = ServerRefs.object_sequence(self._literal_rows).ref_id
                assert runtime_rows_ref is not None
            if not is_versioned:
                steps.append(
                    _TransactionalTableNotificationStep(
                        notification_ref,
                        self._model_cls,
                        self._event_type,
                        ServerPlanRefId(self._write_ref_id),
                        relation_contract=_exact_notification_relation_contract(self._model_cls),
                        old_rows_ref=old_rows_ref,
                        graph_routes=_exact_graph_notification_routes(self._model_cls),
                        executor_materialized=(
                            runtime_rows_ref is not None
                            or not self._replayable_visible_rows
                            or (non_cte_relation_transport and not request_local_relation)
                        ),
                        runtime_rows_ref=runtime_rows_ref,
                        require_sql_relation=request_local_relation,
                    ),
                )
            elif (
                ctx.backend_profile.traits.versioned_staging_transport is VersionedStagingTransport.SAME_STATEMENT_RELATION
                and getattr(self._model_cls, "__staged_cross_process_notifications__", False) is True
            ):
                staging_ctx = get_versioned_staging_ctx(self._model_cls, ctx)
                if staging_ctx is None:
                    raise RuntimeError("Cross-process staged publication requires versioned staging identity")
                steps.append(
                    _TransactionalTableNotificationStep(
                        notification_ref,
                        self._model_cls,
                        self._event_type,
                        ServerPlanRefId(self._write_ref_id),
                        relation_contract=_exact_notification_relation_contract(self._model_cls),
                        old_rows_ref=old_rows_ref,
                        staged_branch_id=staging_ctx.literal_branch or staging_ctx.lazy_branch,
                        staged_commit_id=staging_ctx.staged_commit_id_raw,
                        graph_routes=_exact_graph_notification_routes(self._model_cls),
                        executor_materialized=(
                            runtime_rows_ref is not None
                            or not self._replayable_visible_rows
                            or (non_cte_relation_transport and not request_local_relation)
                        ),
                        runtime_rows_ref=runtime_rows_ref,
                        require_sql_relation=request_local_relation,
                    ),
                )
        return preserve_completion_ref()

    def compile(self: RecordTableEventIntent, ctx: CompilationContext) -> CompiledStep[None]:
        del ctx
        raise TypeError("RecordTableEventIntent must be lowered before compile")


class RecordQueueEventIntent(NonPublishingStep[None]):
    """L4 semantic intent to record queue-write events."""

    def __init__(
        self: RecordQueueEventIntent,
        ref_id: ServerPlanRefId,
        config: _RecordQueueEventConfig,
    ) -> None:
        super().__init__(ref_id)
        self._queue_name = config.queue_name
        event_type = config.event_type
