def _build_polyfill_fts_sql_steps(
    *,
    ref_id: ServerPlanRefId,
    model_cls: type[DatabaseObjectRow],
    visible_rows_ref: ServerPlanRefId,
    rebuild: bool,
) -> list[ServerPlanStep[Any]]:
    from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
    from impl.common.l2100_sql_grammar.tree.statements import SqlDelete
    from impl.common.l5150_fts_polyfill.metadata_schema import (
        GLOBAL_DOC_COUNT_SENTINEL,
        GLOBAL_STATS_SENTINEL,
        GLOBAL_TOTAL_DOC_LENGTH_SENTINEL,
    )

    from .barrier import BarrierStep
    from .grammar_execute import GrammarEffectStep, UtilityEffectStep, _GrammarExecuteConfig

    planning_state = _polyfill_fts_planning_state(model_cls)
    index_table = planning_state.index_table
    metadata_table = planning_state.metadata_table
    idf_cache_table = planning_state.idf_cache_table

    runtime_ref_prefix = str(ref_id)
    prepared_rows_ref = _build_ref_id(runtime_ref_prefix, "prepared_index_rows")
    steps: list[ServerPlanStep[Any]] = [
        _PreparePolyfillFtsIndexRowsStep(
            prepared_rows_ref,
            model_cls,
            _PolyfillFtsMaintenanceConfig(
                visible_rows_ref=visible_rows_ref,
            ),
        ),
    ]

    if rebuild:
        clear_index_ref = _build_ref_id(runtime_ref_prefix, "clear_index_rows")
        clear_metadata_ref = _build_ref_id(runtime_ref_prefix, "clear_metadata_rows")
        insert_index_after = frozenset({clear_index_ref})
        insert_metadata_after = frozenset({clear_metadata_ref})
        steps.extend(
            [
                UtilityEffectStep(
                    clear_index_ref,
                    SqlDelete(SqlTableIdent(index_table)),
                ),
                UtilityEffectStep(
                    clear_metadata_ref,
                    SqlDelete(SqlTableIdent(metadata_table)),
                ),
            ],
        )
    else:
        delete_index_ref = _build_ref_id(runtime_ref_prefix, "delete_index_rows")
        delete_metadata_ref = _build_ref_id(runtime_ref_prefix, "delete_metadata_rows")
        insert_index_after = frozenset({delete_index_ref})
        insert_metadata_after = frozenset({delete_metadata_ref})
        steps.extend(
            [
                _DeletePreparedPolyfillFtsRowsStep(
                    delete_index_ref,
                    _PreparedPolyfillFtsRowsSqlConfig(
                        rows_ref=prepared_rows_ref,
                        table_name=index_table,
                    ),
                ),
                _DeletePreparedPolyfillFtsRowsStep(
                    delete_metadata_ref,
                    _PreparedPolyfillFtsRowsSqlConfig(
                        rows_ref=prepared_rows_ref,
                        table_name=metadata_table,
                    ),
                ),
            ],
        )

    insert_index_ref = _build_ref_id(runtime_ref_prefix, "insert_index_rows")
    insert_metadata_ref = _build_ref_id(runtime_ref_prefix, "insert_metadata_rows")
    delete_global_ref = _build_ref_id(runtime_ref_prefix, "delete_global_metadata_rows")
    refresh_global_ref = _build_ref_id(runtime_ref_prefix, "refresh_global_metadata_rows")
    clear_idf_ref = _build_ref_id(runtime_ref_prefix, "clear_idf_cache_rows")
    refresh_idf_ref = _build_ref_id(runtime_ref_prefix, "refresh_idf_cache_rows")
    steps.extend(
        [
            _InsertPreparedPolyfillFtsIndexRowsStep(
                insert_index_ref,
                _PreparedPolyfillFtsRowsSqlConfig(
                    rows_ref=prepared_rows_ref,
                    table_name=index_table,
                    after_refs=insert_index_after,
                ),
            ),
            _InsertPreparedPolyfillFtsMetadataRowsStep(
                insert_metadata_ref,
                _PreparedPolyfillFtsRowsSqlConfig(
                    rows_ref=prepared_rows_ref,
                    table_name=metadata_table,
                    after_refs=insert_metadata_after,
                ),
            ),
            _DeleteGlobalPolyfillFtsMetadataStep(
                delete_global_ref,
                metadata_table=metadata_table,
                content_hashes=(
                    ContentHashValue(GLOBAL_STATS_SENTINEL),
                    ContentHashValue(GLOBAL_TOTAL_DOC_LENGTH_SENTINEL),
                    ContentHashValue(GLOBAL_DOC_COUNT_SENTINEL),
                ),
                after_refs=frozenset({insert_metadata_ref}),
            ),
            _RefreshPolyfillFtsGlobalMetadataStep(
                refresh_global_ref,
                _RefreshPolyfillFtsGlobalMetadataConfig(
                    metadata_table=metadata_table,
                    after_refs=frozenset({delete_global_ref}),
                ),
            ),
            UtilityEffectStep(
                clear_idf_ref,
                SqlDelete(SqlTableIdent(idf_cache_table)),
            ),
            _RefreshPolyfillFtsIdfCacheStep(
                refresh_idf_ref,
                _RefreshPolyfillFtsIdfCacheConfig(
                    index_table=index_table,
                    metadata_table=metadata_table,
                    idf_cache_table=idf_cache_table,
                    after_refs=frozenset({insert_index_ref, refresh_global_ref, clear_idf_ref}),
                ),
            ),
            BarrierStep(
                ref_id,
                depends_on=frozenset({refresh_idf_ref}),
            ),
        ],
    )
    return steps


