        source = ServerRefs.scalar(session)
    else:
        source = session
    writer_ref = ServerPlanRefId(f"{ref_id}_writer")
    return [SubscriptionWriterStep(writer_ref, source)], writer_ref


class _TableEventSubscriptionLifecycleStep(NonPublishingStep[tuple[object, ...]]):
    """L0: Queue table subscription events after visible-row ref resolution."""

    def __init__(
        self: _TableEventSubscriptionLifecycleStep,
        ref_id: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        config: _TableEventSubscriptionLifecycleConfig,
    ) -> None:
        super().__init__(ref_id)
        self._model_cls = model_cls
        self._event_type: Literal["INSERT", "UPDATE", "UPSERT", "DELETE"] = config.event_type
        self._visible_rows_ref = str(config.visible_rows_ref)
        self._hydrated_rows_ref = config.hydrated_rows_ref
        self._writer_ref = config.writer_ref
        self._staged_commit_id = config.staged_commit_id
        self._replayable_visible_rows = config.replayable_visible_rows
        self._remote_only = config.remote_only
        self._completion_ref = str(config.completion_ref or config.visible_rows_ref)
        self._after_refs = frozenset(str(ref_id) for ref_id in config.after_refs)
        self._old_rows_ref = None if config.old_rows_ref is None else str(config.old_rows_ref)
        self._branch_id = config.branch_id
        self._materialized_snapshots = not config.replayable_visible_rows and (
            (config.event_type == "INSERT" and config.capture_mutation_rows and not config.literal_rows)
            or (config.event_type == "UPSERT" and not config.literal_rows)
            or config.event_type == "DELETE"
            or (
                (config.capture_mutation_rows or config.allow_sql_batch_transport or config.event_type == "UPSERT")
                and config.event_type in {"UPDATE", "UPSERT"}
                and config.old_rows_ref is not None
                and config.old_rows_ref != config.visible_rows_ref
            )
        )
        self._allow_sql_batch_transport = config.allow_sql_batch_transport and not self._materialized_snapshots
        self._literal_rows = config.literal_rows
        self._delivery_order = config.delivery_order
        self._literal_row_field_names, self._literal_row_contract = _literal_lifecycle_row_contract(
            model_cls,
            self._literal_rows,
        )

    @property
    def level(self: _TableEventSubscriptionLifecycleStep) -> int:
        return 0

    def result_cardinality(self: _TableEventSubscriptionLifecycleStep) -> Cardinality:
        return Cardinality.MANY

    def is_read_only(self: _TableEventSubscriptionLifecycleStep) -> bool:
        return True

    def execution_role(self: _TableEventSubscriptionLifecycleStep) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def step_tags(self: _TableEventSubscriptionLifecycleStep) -> frozenset[str]:
        return frozenset({"subscription", "semantic", "lifecycle"})

    def tables_read(self: _TableEventSubscriptionLifecycleStep) -> frozenset[str]:
        return frozenset()

    def tables_written(self: _TableEventSubscriptionLifecycleStep) -> frozenset[str]:
        return frozenset()

    def dependencies(self: _TableEventSubscriptionLifecycleStep) -> frozenset[str]:
        # Queueing owns no rediscovery path: visible/old rows and completion
        # are exact executor dependencies with caller-transaction lifetime.
        if self._materialized_snapshots:
            refs = {
                str(self._hydrated_rows_ref)
                if self._hydrated_rows_ref is not None
                else _executor_runtime_relation_ref_id(self._visible_rows_ref)
            }
        else:
            refs = {self._visible_rows_ref, self._completion_ref}
            if self._hydrated_rows_ref is not None:
                refs.add(str(self._hydrated_rows_ref))
        refs.update(self._after_refs)
        if self._writer_ref is not None:
            refs.add(str(self._writer_ref))
        if self._old_rows_ref is not None:
            refs.add(self._old_rows_ref)
        return frozenset(refs)

    def sql_visible_dependencies(self: _TableEventSubscriptionLifecycleStep) -> frozenset[str]:
        if self._materialized_snapshots:
            return frozenset()
        non_sql_dependencies = set(self._after_refs)
        if self._hydrated_rows_ref is not None:
            non_sql_dependencies.add(str(self._hydrated_rows_ref))
        return self.dependencies() - non_sql_dependencies

    def sql_imported_dependency_refs(
        self: _TableEventSubscriptionLifecycleStep,
    ) -> frozenset[ServerPlanRefId]:
        if self._materialized_snapshots or self._literal_rows:
            return frozenset()
        refs = {ServerPlanRefId(self._visible_rows_ref), ServerPlanRefId(self._completion_ref)}
        if self._old_rows_ref is not None:
            refs.add(ServerPlanRefId(self._old_rows_ref))
        return frozenset(refs)

    def imported_dependency_contract(
        self: _TableEventSubscriptionLifecycleStep,
        ref_id: ServerPlanRefId,
        producer_contract: CtePublicationContract,
    ) -> CtePublicationContract:
        """Accept denied or no-op mutations as empty lifecycle input."""
        if str(ref_id) == self._completion_ref and self._completion_ref != self._visible_rows_ref:
            return replace(producer_contract, empty_result_allowed=True)
        output_shape, _relation, _hints = _lifecycle_row_transport_artifacts(self._model_cls)
        columns = tuple(column for column in output_shape.cte_output_columns if column in producer_contract.columns)
        return replace(producer_contract.projected(columns), empty_result_allowed=True)

    def supports_sql_batch_transport(self: _TableEventSubscriptionLifecycleStep) -> bool:
        return self._allow_sql_batch_transport

    def allows_later_sql_transport(self: _TableEventSubscriptionLifecycleStep) -> bool:
        return True

    def emits_sql_for_accounting(self: _TableEventSubscriptionLifecycleStep) -> bool | None:
        if self._materialized_snapshots or (self._literal_rows and self._staged_commit_id is not None):
            return False
        return None

    def lifecycle_empty_result_allowed(self: _TableEventSubscriptionLifecycleStep) -> bool:
        """No visible rows means that this lifecycle action emits no effects."""
        return True

    def requires_prior_step_boundary(self: _TableEventSubscriptionLifecycleStep) -> bool:
        return not self._allow_sql_batch_transport

    def consumes_repeatable_post_write_relations_for_transport(
        self: _TableEventSubscriptionLifecycleStep,
        transport: DmlResultTransport,
    ) -> bool:
        """Consume a bounded post-write relation through its backend-native transport."""
        return not self._materialized_snapshots and transport in {
            DmlResultTransport.DRIVER_ROWCOUNT,
            DmlResultTransport.RETURNING_RELATION,
        }

    def compile(
        self: _TableEventSubscriptionLifecycleStep,
        ctx: CompilationContext,
    ) -> CompiledStep[tuple[object, ...]]:
        if self._materialized_snapshots:
            # Ordered statement batches cannot replay a pre-write SELECT after
            # the mutation. Consume the executor's captured rowsets instead.
            return CompiledStep(
                closed_post_op=literal_post_op(()),
                lifecycle_effects=self._snapshot_effects(),
            )
        if self._literal_rows and self._staged_commit_id is not None:
            return CompiledStep(
                closed_post_op=literal_post_op(()),
                lifecycle_effects=(
                    _QueueVisibleRowTableEventsEffect(
                        model_cls=self._model_cls,
                        event_type=self._event_type,
                        rows=tuple(self._literal_rows),
                        writer_ref=self._writer_ref,
                        staged_commit_id=self._staged_commit_id,
                        branch_id=self._branch_id,
                        delivery_order=self._delivery_order,
                    ),
                ),
            )
        if self._literal_rows:
            from impl.common.l2100_sql_grammar.domain.infra.stmt_cte_helpers import (
                SqlLifecycleInputRowsQuery,
            )

            relation = self._literal_row_contract
            assert relation is not None
            literal_grammar = SqlLifecycleInputRowsQuery(
                columns=relation.columns,
                rows=[
                    {
                        column: getattr(row, field_name)
                        for field_name, column in zip(
                            self._literal_row_field_names,
                            relation.columns,
                            strict=True,
                        )
                    }
                    for row in self._literal_rows
                ],
                type_hints=relation.column_type_hints,
            )
            output_shape, result_relation, column_type_hints = _lifecycle_row_transport_artifacts(
                self._model_cls,
                columns=tuple(str(column) for column in relation.columns),
            )
            return CompiledStep(
                grammar=literal_grammar,
                needs_returning=True,
                output_shape=output_shape,
                result_relation=result_relation,
                column_type_hints=column_type_hints,
                closed_post_op=row_dicts_post_op(),
                lifecycle_effects=(
                    ResultBoundLifecycleEffects(
                        self._lifecycle_effects_from_result,
                        phase=PipelineLifecyclePhase.BEFORE_COMMIT_TRANSACTIONAL,
                    ),
                ),
                allow_empty_provenance_manifest=True,
            )
        rows_cte_name, auxiliary_ctes, rows_cte = _auxiliary_ctes_for_rows_ref(
            ctx,
            rows_ref=ServerPlanRefId(self._visible_rows_ref),
            step_name=type(self).__name__,
        )
        if self._old_rows_ref is None:
            from l2070_batching.write_column_policy import returnable_db_columns

            model_columns = frozenset(str(column) for column in returnable_db_columns(self._model_cls))
            lifecycle_columns = tuple(str(column) for column in rows_cte.columns if str(column) in model_columns)
            output_shape, result_relation, column_type_hints = _lifecycle_row_transport_artifacts(
                self._model_cls,
                columns=lifecycle_columns,
            )
            grammar, auxiliary_ctes = self._gate_rows_on_completion(
                ctx,
                rows_cte_name,
                auxiliary_ctes,
                columns=lifecycle_columns,
            )
            return CompiledStep(
                grammar=grammar,
                needs_returning=True,
                output_shape=output_shape,
                result_relation=result_relation,
                column_type_hints=column_type_hints,
                auxiliary_ctes=auxiliary_ctes,
                sql_visible_dependency_aliases=frozenset(
                    {str(rows_cte_name), *(str(ref_id) for ref_id, _query in auxiliary_ctes or ())},
                ),
                closed_post_op=row_dicts_post_op(),
                lifecycle_effects=(
                    ResultBoundLifecycleEffects(
                        self._lifecycle_effects_from_result,
                        phase=PipelineLifecyclePhase.BEFORE_COMMIT_TRANSACTIONAL,
                    ),
                ),
                allow_empty_provenance_manifest=True,
            )
        return self._compile_changed_update_relation(ctx, rows_cte, auxiliary_ctes)

    def _gate_rows_on_completion(
        self: _TableEventSubscriptionLifecycleStep,
        ctx: CompilationContext,
        rows_cte_name: ServerPlanRefId,
        auxiliary_ctes: list[tuple[ServerPlanRefId, SqlRenderable]] | None,
        *,
        columns: tuple[str, ...],
    ) -> tuple[SqlRenderable, list[tuple[ServerPlanRefId, SqlRenderable]] | None]:
        grammar = _select_all_from_cte(rows_cte_name, columns=columns)
        if self._completion_ref == self._visible_rows_ref:
            return grammar, auxiliary_ctes
        completion_cte = ctx.cte_refs.get(self._completion_ref)
        if not isinstance(completion_cte, CteReference):
            msg = f"Subscription completion ref {self._completion_ref!r} has no SQL relation"
            raise ValueError(msg)
        from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName, SqlTableName
        from impl.common.l2100_sql_grammar.tree.clauses import SqlSelectList
        from impl.common.l2100_sql_grammar.tree.enums import BinaryOp
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlLiteral
        from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp, SqlExists
        from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
        from impl.common.l2100_sql_grammar.tree.statements import SqlSelect

        completion_where = None
        count_column = completion_cte.scalar_value_column
        if count_column is not None and completion_cte.scalar_control_kind is ScalarControlKind.AFFECTED_COUNT:
            completion_where = SqlBinaryOp(
                SqlColumnRef(count_column.to_sql_column_name()),
                BinaryOp.GT,
                SqlLiteral(0),
            )
        completion_exists = SqlExists(
            SqlSelect(
                SqlSelectList([SqlLiteral(1)]),
                from_=SqlTableIdent(SqlTableName(completion_cte.ref_id)),
                where=completion_where,
            ),
        )
        grammar = _select_all_from_cte(rows_cte_name, where=completion_exists, columns=columns)
        if completion_cte.auxiliary_query is not None:
            auxiliary_ctes = [
                *(auxiliary_ctes or []),
                (completion_cte.ref_id, completion_cte.auxiliary_query),
            ]
        return grammar, auxiliary_ctes

    def _compile_changed_update_relation(
        self: _TableEventSubscriptionLifecycleStep,
        ctx: CompilationContext,
        rows_cte: CteReference,
        auxiliary_ctes: list[tuple[ServerPlanRefId, SqlRenderable]] | None,
    ) -> CompiledStep[tuple[object, ...]]:
        from impl.common.l2050_sql_types.sql_branded_types import SqlAliasName, SqlColumnName, SqlTableName
        from impl.common.l2100_sql_grammar.tree.clauses import SqlJoin, SqlSelectAlias, SqlSelectList, SqlTableAlias
        from impl.common.l2100_sql_grammar.tree.enums import BinaryOp, JoinKind
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef
        from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp, SqlIsNull, sql_or
        from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
        from impl.common.l2100_sql_grammar.tree.statements import SqlSelect
        from l2070_batching.output_shape import CompiledOutputShape, DeclaredResultRelation, synthetic_output_field
        from l2070_batching.post_op import row_dicts_post_op
        from l2070_batching.sql_column_type_hints import combine_sql_column_type_hints

        assert self._old_rows_ref is not None
        old_cte = ctx.cte_refs.get(self._old_rows_ref)
        if not isinstance(old_cte, CteReference):
            msg = f"Subscription old-row ref {self._old_rows_ref!r} has no SQL relation"
            raise ValueError(msg)
        new_alias = SqlAliasName("changed_new")
        old_alias = SqlAliasName("changed_old")
        embedded_preimage = old_cte.ref_id == rows_cte.ref_id and any(column.startswith("__pre__") for column in rows_cte.columns)
        new_columns = tuple(column for column in rows_cte.columns if not column.startswith("__pre__"))
        if embedded_preimage:
            old_source_columns = tuple(column for column in new_columns if f"__pre__{column}" in rows_cte.columns)
            old_physical_columns = tuple(f"__pre__{column}" for column in old_source_columns)
        else:
            old_source_columns = tuple(old_cte.columns)
            old_physical_columns = old_source_columns
        common_columns = tuple(column for column in new_columns if column in old_source_columns)
        semantic_columns = tuple(
            column for column in common_columns if column not in {"sys_id", "created_at", "updated_at"} and not column.startswith("sys_")
        )
        from impl.common.l2100_sql_grammar.tree.expr_ops import SqlDecimalIsDistinct
        from l2070_batching.sql_column_type_hints import model_sql_column_type_hints

        semantic_type_hints = model_sql_column_type_hints(self._model_cls, semantic_columns)

        def semantic_difference(column: str) -> SqlRenderable:
            new_value = SqlColumnRef(SqlColumnName(column), new_alias)
            old_value = SqlColumnRef(
                SqlColumnName(f"__pre__{column}" if embedded_preimage else column),
                new_alias if embedded_preimage else old_alias,
            )
            if semantic_type_hints is not None and column in semantic_type_hints.numeric_columns:
                return SqlDecimalIsDistinct(new_value, old_value)
            return SqlBinaryOp(new_value, BinaryOp.IS_DISTINCT_FROM, old_value)

        change_predicates = tuple(semantic_difference(column) for column in semantic_columns)
        select_items: list[SqlRenderable] = [
            SqlSelectAlias(SqlColumnRef(SqlColumnName(column), new_alias), SqlAliasName(column)) for column in new_columns
        ]
        old_output_columns = tuple(f"__old_{column}" for column in old_source_columns)
        select_items.extend(
            SqlSelectAlias(
                SqlColumnRef(
                    SqlColumnName(physical_column),
                    new_alias if embedded_preimage else old_alias,
                ),
                SqlAliasName(output_column),
            )
            for physical_column, output_column in zip(
                old_physical_columns,
                old_output_columns,
                strict=True,
            )
        )
        where = (
            sql_or(*change_predicates)
            if change_predicates
            else SqlBinaryOp(
                SqlColumnRef(SqlColumnName("sys_id"), new_alias),
                BinaryOp.IS_DISTINCT_FROM,
                SqlColumnRef(SqlColumnName("sys_id"), new_alias),
            )
        )
        if self._event_type == "UPSERT":
            where = sql_or(
                SqlIsNull(
                    SqlColumnRef(
                        SqlColumnName("__pre__sys_id" if embedded_preimage else "sys_id"),
                        new_alias if embedded_preimage else old_alias,
                    ),
                ),
                where,
            )
        joins: list[SqlRenderable] = []
        if not embedded_preimage:
            join_condition = SqlBinaryOp(
                SqlColumnRef(SqlColumnName("sys_id"), new_alias),
                BinaryOp.IS_NOT_DISTINCT_FROM,
                SqlColumnRef(SqlColumnName("sys_id"), old_alias),
            )
            joins.append(
                SqlJoin(
                    JoinKind.LEFT if self._event_type == "UPSERT" else JoinKind.INNER,
                    SqlTableAlias(SqlTableIdent(SqlTableName(old_cte.ref_id)), old_alias),
                    join_condition,
                ),
            )
        grammar = SqlSelect(
            SqlSelectList(select_items),
            from_=SqlTableAlias(SqlTableIdent(SqlTableName(rows_cte.ref_id)), new_alias),
            joins=joins,
            where=where,
        )
        output_columns = (*new_columns, *old_output_columns)
        output_shape = CompiledOutputShape(tuple(synthetic_output_field(column) for column in output_columns))
        old_hints = combine_sql_column_type_hints(
            old_output_columns,
            *(
                old_cte.column_type_hints.rename_column(physical_column, output_column)
                for physical_column, output_column in zip(
                    old_physical_columns,
                    old_output_columns,
                    strict=True,
                )
            ),
        )
        column_type_hints = combine_sql_column_type_hints(
            output_columns,
            rows_cte.column_type_hints,
            old_hints,
        ).require_complete(output_columns)
        if old_cte.auxiliary_query is not None:
            auxiliary_ctes = [*(auxiliary_ctes or []), (old_cte.ref_id, old_cte.auxiliary_query)]
        return CompiledStep(
            grammar=grammar,
            needs_returning=True,
            output_shape=output_shape,
            result_relation=DeclaredResultRelation.from_output_shape(output_shape),
            column_type_hints=column_type_hints,
            auxiliary_ctes=auxiliary_ctes,
            closed_post_op=row_dicts_post_op(),
            lifecycle_effects=(
                ResultBoundLifecycleEffects(
                    self._lifecycle_effects_from_result,
                    phase=PipelineLifecyclePhase.BEFORE_COMMIT_TRANSACTIONAL,
                ),
            ),
            allow_empty_provenance_manifest=True,
        )

    def _snapshot_effects(
        self: _TableEventSubscriptionLifecycleStep,
    ) -> Sequence[_QueueVisibleRowTableEventsEffect]:
        old_rows_ref = self._visible_rows_ref if self._event_type == "DELETE" else self._old_rows_ref
        return (
            _QueueVisibleRowTableEventsEffect(
                model_cls=self._model_cls,
                event_type=self._event_type,
                rows=(),
                rows_ref=self._hydrated_rows_ref or ServerPlanRefId(_executor_runtime_relation_ref_id(self._visible_rows_ref)),
                old_rows_ref=ServerPlanRefId(old_rows_ref) if old_rows_ref is not None else None,
                filter_unchanged=self._event_type in {"UPDATE", "UPSERT"},
                exact_delete_preimages=self._event_type == "DELETE",
                writer_ref=self._writer_ref,
                staged_commit_id=self._staged_commit_id,
                branch_id=None,
                remote_only=self._remote_only,
                delivery_order=self._delivery_order,
            ),
        )

    def _lifecycle_effects_from_result(
        self: _TableEventSubscriptionLifecycleStep,
        result: object,
    ) -> Sequence[_QueueVisibleRowTableEventsEffect]:
        if not isinstance(result, Sequence) or isinstance(result, str | bytes | bytearray):
            return ()
        rows: list[object] = []
        old_rows: list[object] = []
        result_branch_id: object | None = None
        for item in result:
            if isinstance(item, self._model_cls):
                rows.append(item)
                continue
            if not isinstance(item, Mapping):
                continue
            new_payload = {key: value for key, value in item.items() if not key.startswith("__old_")}
            old_payload = {key.removeprefix("__old_"): value for key, value in item.items() if key.startswith("__old_")}
            if result_branch_id is None:
                result_branch_id = new_payload.get("branch_id")
            rows.extend(_resolved_visible_rows(new_payload, self._model_cls))
            if old_payload:
                old_rows.extend(_resolved_visible_rows(old_payload, self._model_cls))
        if not rows:
            return ()
        return (
            _QueueVisibleRowTableEventsEffect(
                model_cls=self._model_cls,
                event_type=self._event_type,
                rows=tuple(rows),
                rows_ref=self._hydrated_rows_ref,
                old_rows=tuple(old_rows),
                exact_delete_preimages=self._event_type == "DELETE",
                writer_ref=self._writer_ref,
                staged_commit_id=self._staged_commit_id,
                branch_id=result_branch_id if result_branch_id is not None else self._branch_id,
                remote_only=self._remote_only,
                delivery_order=self._delivery_order,
            ),
        )

