def _assert_versioned_write_plan_optimizes_with_staged_commit_boundary(
    steps: list[ServerPlanStep[Any]],
) -> None:
    opt_ctx = make_optimization_context()
    optimized, batch_warnings = optimize_steps_with_batch_warnings(steps, ctx=opt_ctx)
    assert count_sql_groups(optimized, ctx=opt_ctx) >= 1
    for warning in batch_warnings:
        message = str(warning.message)
        assert "EnsureStagedCommitStep" in message or "PhysicalStatementGroup" in message


def _optimized_step_type_names(steps: list[ServerPlanStep[Any]]) -> set[str]:
    names: set[str] = set()

    def _visit(step: ServerPlanStep[Any]) -> None:
        names.add(type(step).__name__)
        if isinstance(step, PhysicalStatementGroup):
            for child in step.children:
                _visit(child)

    for step in steps:
        _visit(step)
    return names


def _assert_inline_admission_is_not_fused_into_dmc(steps: list[ServerPlanStep[Any]]) -> None:
    for step in steps:
        if not isinstance(step, PhysicalStatementGroup) or not isinstance(step.strategy, DataModifyingCteStrategy):
            continue
        child_type_names = {type(child).__name__ for child in step.children}
        assert "StaticStagedAdmissionProofStep" not in child_type_names


