    ) -> VersionedStagingCtx:
        del context_refs
        table_name = get_table_name(model_cls)
        if table_name == get_table_name(_PlannerSourceDocument):
            staged_model: type[DatabaseObjectRow[SysId]] = _PlannerSourceDocumentStaged
            tip_model: type[DatabaseObjectRow[SysId]] = _PlannerSourceDocumentTip
            common_columns = ["sys_id", "stable_key", "path", "content_hash"]
        elif table_name == get_table_name(_PlannerSourceChunkContext):
            staged_model = _PlannerSourceChunkContextStaged
            tip_model = _PlannerSourceChunkContextTip
            common_columns = ["sys_id", "stable_key", "document_key", "path"]
