def test_versioned_insert_many_lazy_preserves_explicit_dependencies() -> None:
    txn = _PlannerHarnessWriteTxn()
    inserted_nodes = txn.insert_many_lazy(
        _PlannerSurfaceItem,
        (
            _PlannerSurfaceItem(
                sys_id=SysId("01900000-0000-7000-8000-000000000331"),
                unique_key="node",
                scope="dependency",
                counter=1,
            ),
        ),
    )
    assert SqlTableName("vwlsp_items") in txn._inline_touched_versioned_tables
    dependency_ref = inserted_nodes._commit_dependency_ref_id
    assert dependency_ref is not None

    txn.insert_many_lazy(
        _PlannerSurfaceItem,
        (
            _PlannerSurfaceItem(
                sys_id=SysId("01900000-0000-7000-8000-000000000332"),
                unique_key="dependent",
                scope="dependency",
                counter=2,
            ),
        ),
        after_refs=(ServerPlanRefId(dependency_ref),),
    )

    dependent_intent = txn._plan._steps[-1]
    steps_by_ref = {str(step.ref_id): step for step in txn._plan._steps}
    dependency_closure = set(dependent_intent.dependencies())
    pending = list(dependency_closure)
    while pending:
        dependency = steps_by_ref.get(pending.pop())
        if dependency is None:
            continue
        for ref_id in dependency.dependencies():
            if ref_id not in dependency_closure:
                dependency_closure.add(ref_id)
                pending.append(ref_id)
    assert dependency_ref in dependency_closure

    lowered = lower_steps(
        txn._plan._steps,
        ctx=make_lowering_context(
            make_backend_profile(BackendType.POSTGRES),
