        ),
    )
    isolated_dependent_writes = [step for step in lowered if "write" in step.step_tags() and step.requires_runtime_sequential_batch()]
    assert len(isolated_dependent_writes) == 1
    assert not isolated_dependent_writes[0].supports_sql_batch_transport()
    assert any(dependency_ref in step.dependencies() for step in lowered)


