@pytest.mark.parametrize("staged_commit_materialized", [False, True])
def test_versioned_insert_many_deferred_preserves_dependencies_across_ensure_ladder_tdd_red(
    staged_commit_materialized: bool,
) -> None:
    """Symbolic bulk ordering survives both ensure-present and ensure-elided lowering."""
    from impl.common.l2070_server_plan.steps.intent_versioning_extended import (
        VersionedInsertManyDeferredIntent,
        _VersionedInsertManyConfig,
    )

    txn = _PlannerHarnessWriteTxn()
    staging_ctx = txn._get_versioned_staging_context(_PlannerSurfaceItem)
    prerequisite = ServerPlanRefId("step_80.write")
    source = cast(
        "Any",
        ServerRefs.from_ref_id(
            ServerPlanRefId("step_90"),
            variant="object_sequence",
        ),
    )
    intent = VersionedInsertManyDeferredIntent(
        ServerPlanRefId("deferred_edges"),
        _PlannerSurfaceItem,
        source,
        ServerRefs.scalar(
            _VersionedInsertManyConfig(
                staging_ctx=staging_ctx,
                after_refs=frozenset({prerequisite}),
            ),
        ),
    )
    materialized_txn = SimpleNamespace(
        _staged_commit_record_materialized=staged_commit_materialized,
        _staged_commit_id=StagedCommitId(staging_ctx.staged_commit_id_raw),
    )

    lowered = list(
        intent.lower(
            make_lowering_context(
                make_backend_profile(BackendType.POSTGRES),
                is_versioned=True,
                is_write_transaction=True,
                staging_ctx_factory=txn._get_versioned_staging_context,
                branch_id=txn.branch_id.unwrap_to_str(),
                session_id=txn.session_id.unwrap_to_sql(),
                executor_txn_handle=materialized_txn,
            ),
        ),
    )

    ensure_steps = [step for step in lowered if type(step).__name__ == "EnsureStagedCommitStep"]
    assert bool(ensure_steps) is not staged_commit_materialized
    steps_by_ref = {str(step.ref_id): step for step in lowered}

    def _dependency_closure(step: ServerPlanStep[Any]) -> set[str]:
        pending = list(step.dependencies())
        seen: set[str] = set()
        while pending:
            ref_id = pending.pop()
            if ref_id in seen:
                continue
            seen.add(ref_id)
            dependency = steps_by_ref.get(ref_id)
            if dependency is not None:
                pending.extend(dependency.dependencies())
        return seen

    writes = [step for step in lowered if step.step_tags() >= {"write", "versioned", "batch"}]
    assert writes
    assert str(prerequisite) in _dependency_closure(writes[0])
    assert all(step.requires_runtime_sequential_batch() for step in writes)
    assert all(not step.supports_sql_batch_transport() for step in writes)


