    )
    published = txn.commit_branch_lazy(
        expected_tip_revision_id=RevisionId("01900000-0000-7000-8000-000000000444"),
        allow_empty=True,
        message="exact history raw insert publish",
    )

    assert inserted._step_ref_id is not None
    assert published._step_ref_id is not None

    profile = make_backend_profile(BackendType.SQLITE)
    lowered = lower_steps(
        txn._plan._steps,
