            emit_table_event_intents=False,
        ),
    )
    optimized = optimize_steps(lowered, ctx=make_optimization_context(profile))
    optimized_shape = [
        (
            type(step).__name__,
            str(step.ref_id),
            [f"{type(child).__name__}:{child.ref_id}" for child in step.children] if isinstance(step, PhysicalStatementGroup) else [],
        )
        for step in optimized
    ]

    assert count_sql_groups(optimized, ctx=make_optimization_context(profile)) == 1, optimized_shape


def test_sqlite_same_plan_delete_raw_insert_publish_compiles_without_semicolon_cte_tdd_red() -> None:
    """Replacement replay must be able to delete and insert in one revision.

