            str(step.ref_id),
            [f"{type(child).__name__}:{child.ref_id}" for child in step.children] if isinstance(step, PhysicalStatementGroup) else [],
        )
        for step in optimized
    ]

    assert sql_artifacts
    assert not any("WITH RECURSIVE" in artifact.sql and ";\nDELETE FROM" in artifact.sql for artifact in sql_artifacts)
    assert count_sql_groups(optimized, ctx=make_optimization_context(profile)) == 1, optimized_shape
    ordered_refs = [
        str(child.ref_id) if isinstance(step, PhysicalStatementGroup) else str(step.ref_id)
        for step in optimized
        for child in (step.children if isinstance(step, PhysicalStatementGroup) else (step,))
