    assert ordered_refs.index("step_0.tombstone") < ordered_refs.index("step_1.raw")
    assert ordered_refs.index("step_1.raw") < ordered_refs.index("step_2_commit_ctx_fetch")
    assert len(ordered_refs) == len(set(ordered_refs)), optimized_shape


