            assert result_contract.columns == (
                "scope_id",
                "attempt_id",
                "ok",
                "frame_complete",
                "expected_record_count",
                "row_kind",
                "outcome",
                "table_name",
                "revision_id",
                "materialization",
                "active",
                "staged_commit_id",
            )
            assert result_contract.column_type_hints.has_any()
        compiled_guard = guard.compile(
            make_compilation_context(
                profile,
                branch_id=txn.branch_id.unwrap_to_str(),
            ),
        )
        if guard.tables_read():
            assert compiled_guard.output_shape is not None
            assert compiled_guard.output_shape.cte_output_columns == result_contract.columns
            assert compiled_guard.grammar is not None
        else:
            assert compiled_guard.output_shape is None
            assert compiled_guard.grammar is None
        assert compiled_guard.closed_post_op is not None
    optimized = optimize_steps(lowered, ctx=make_optimization_context(profile))
    optimized_shape = [
        (
            type(step).__name__,
            str(step.ref_id),
            type(step.strategy).__name__ if isinstance(step, PhysicalStatementGroup) else "",
            [f"{type(child).__name__}:{child.ref_id}" for child in step.children] if isinstance(step, PhysicalStatementGroup) else [],
        )
        for step in optimized
    ]
    all_tables = {str(table) for step in optimized for table in (step.tables_read() | step.tables_written())}
    written_tables = {str(table) for step in optimized for table in step.tables_written()}

    expected_written_tables = {
        "vwlsp_source_documents_sparse",
        "vwlsp_source_chunk_contexts_sparse",
        "vwlsp_source_chunks_sparse",
        "sys_queue_messages",
    }
    assert expected_written_tables <= all_tables
    assert expected_written_tables <= written_tables
    assert not any(table.startswith("vwlsp_items") for table in written_tables), (written_tables, optimized_shape)


