def test_same_plan_insert_publish_reuses_pending_staged_source_across_batches_tdd_red() -> None:
    txn = _PlannerHarnessWriteTxn()
    txn.insert_lazy(
        _PlannerSurfaceItem,
        LazyResult.of(_PlannerSurfaceItem(unique_key="inline-key", scope="publish", counter=1)),
    )
    txn.commit_branch_lazy(
        expected_tip_revision_id=RevisionId("01900000-0000-7000-8000-000000000444"),
        allow_empty=True,
        message="inline publish",
    )

    profile = make_backend_profile(BackendType.POSTGRES)
    lowered = lower_steps(
        txn._plan._steps,
        ctx=make_lowering_context(
            profile,
            is_versioned=True,
            is_write_transaction=True,
            staging_ctx_factory=txn._get_versioned_staging_context,
            branch_id=txn.branch_id.unwrap_to_str(),
            session_id=txn.session_id.unwrap_to_sql(),
        ),
    )
    optimized = optimize_steps(lowered, ctx=make_optimization_context(profile))
    compilation_ctx = make_compilation_context(
        profile,
        branch_id=txn.branch_id.unwrap_to_str(),
    )

    def _batches(step: ServerPlanStep[Any]) -> list[PhysicalStatementGroup]:
        if not isinstance(step, PhysicalStatementGroup):
            return []
        return [step]

    batch_grammars: list[str] = []
    for batch in (batch for step in optimized for batch in _batches(step)):
        child_refs = {str(child.ref_id) for child in batch.children}
        external_dependencies = {
            str(dependency) for child in batch.children for dependency in child.dependencies() if str(dependency) not in child_refs
        }
        if external_dependencies:
            continue
        compiled = batch.compile(compilation_ctx)
        if compiled.grammar is not None:
            batch_grammars.append(repr(compiled.grammar))

    assert batch_grammars
    assert all("SqlTableName('step_0.write')" not in grammar for grammar in batch_grammars)


