            ref_id,
            ReturnSourceAfterDepsConfig(
                source_ref=ServerPlanRefId(id_source_ref),
                after_refs=tuple(ServerPlanRefId(ref_id) for ref_id in after_refs),
                default_value=None,
                scalar_coercion=ScalarCoercionKind.SYS_ID,
            ),
        )
        self._existing_row_source_ref = existing_row_source_ref
        self._permission_context_ref = permission_context_ref
        self._model_cls = model_cls

    def cte_publication_contract(self: _ExistingRowWritePermissionSysIdResultStep) -> CtePublicationContract:
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=("sys_id",),
            column_type_hints=SqlColumnTypeHints(uuid_columns=frozenset({"sys_id"})),
            model_cls=_SysIdResultRow,
            relation_contract=CteRelationContract.semantic_row(_SysIdResultRow),
            relation_role=self.cte_relation_role(),
            source_tables=self.tables_read() or None,
        )

    def publishes_executor_visible_binding(self) -> bool:
        return True

    def requires_prior_step_boundary(self) -> bool:
        return True

    def compile(
        self,
        ctx: CompilationContext,
    ) -> CompiledStep[SysId]:
        model_cls = self._model_cls
        assert model_cls is not None
        return runtime_existing_row_write_permission_sysid_compiled_step(
            self._source_ref,
            ctx=ctx,
            result_ref_id=str(self.ref_id),
            existing_row_source_ref=self._existing_row_source_ref,
            permission_context_ref=self._permission_context_ref,
            model_cls=model_cls,
            allow_missing=self._allow_missing,
            action=self._action,
        )

