def _result_row_output_columns(
    model_cls: type[DatabaseObjectRow],
    *,
    include_fts_rank: bool,
    include_vector_score: bool,
    include_rrf_meta: bool,
) -> tuple[str, ...]:
    from l1000_schema.physical_adjuncts import (
        is_framework_physical_adjunct_column,
        is_framework_physical_adjunct_field,
    )

    columns: list[str] = []
    for field_plan in polymorphic_read_field_plans(model_cls):
        if field_plan.field_name in {"revision_id", "staged_commit_id"}:
            continue
        if is_framework_physical_adjunct_field(model_cls, DynamicFieldName(field_plan.field_name)):
            continue
        if is_framework_physical_adjunct_column(SqlColumnName(field_plan.db_column)):
            continue
        if field_plan.db_column in _SEARCH_META_OUTPUT_COLUMNS:
            continue
        columns.append(field_plan.db_column)
    if include_fts_rank:
        columns.append("__fts_rank")
    if include_vector_score:
        columns.append("__vector_score")
    if include_rrf_meta:
        columns.extend(("__rrf_score", "__fts_rrf_rank", "__vector_rrf_rank", "__chunk_id", "__chunk_metadata"))
    return tuple(columns)


def _score_prereq_type_hints(columns: tuple[str, ...]) -> SqlColumnTypeHints:
