def _hybrid_result_type_hints(
    model_cls: type[DatabaseObjectRow],
    columns: tuple[str, ...],
) -> SqlColumnTypeHints:
    model_columns = tuple(column for column in columns if column not in _SEARCH_META_OUTPUT_COLUMNS)
    model_hints = model_sql_column_type_hints(model_cls, model_columns)
    if model_hints is None:
        msg = f"Could not resolve SQL column type hints for {model_cls.__name__}"
        raise TypeError(msg)
    return combine_sql_column_type_hints(
        columns,
        model_hints,
        SqlColumnTypeHints(
            double_columns=frozenset(
                column for column in columns if column in _SEARCH_META_OUTPUT_COLUMNS and column not in {"__chunk_id", "__chunk_metadata"}
            ),
            uuid_columns=frozenset(column for column in columns if column == "__chunk_id"),
            jsonb_columns=frozenset(column for column in columns if column == "__chunk_metadata"),
        ),
    )


