def _require_hybrid_revision_id(
    ctx: CompilationContext,
    step_name: str,
    *,
    branch_id: BranchId | SqlRenderable | None,
    branch_source_ref_id: ServerPlanRefId | None,
) -> str | SqlRenderable:
    if ctx.revision_id is not None:
        return ctx.revision_id
    if ctx.lazy_revision is not None:
        from impl.common.l2070_server_plan.steps._compile_server_ref import lower_scalar_server_ref

        return lower_scalar_server_ref(ctx.lazy_revision, ctx)
    if branch_source_ref_id is not None:
        branch_binding = ctx.cte_refs.get(str(branch_source_ref_id))
        if branch_binding is None:
            branch_binding = next(
                (binding for binding in ctx.cte_refs.values() if str(binding.ref_id) == str(branch_source_ref_id)),
                None,
            )
        if branch_binding is not None:
            revision_column = next(
                (column for column in ("tip_revision_id", "current_tip_revision_id", "revision_id") if column in branch_binding.columns),
                None,
            )
            if revision_column is not None:
                from impl.common.l2100_sql_grammar.domain.infra.stmt_dml_simple import (
                    SqlCteFieldRef,
                )

                return SqlCteFieldRef(
                    ServerPlanRefId(branch_binding.ref_id),
                    SqlColumnName(revision_column),
                )
    from impl.common.l2070_server_plan.steps._compile_versioned import (
        _graph_predicate_revision_value,
    )

    branch_selector = branch_id.unwrap_to_str() if isinstance(branch_id, BranchId) else branch_id
    tip_revision = _graph_predicate_revision_value(ctx, branch_id=branch_selector)
    if tip_revision is not None:
        return tip_revision
    msg = f"{step_name} requires revision_id for versioned hybrid RRF compilation"
    raise RuntimeError(msg)


