def build_search_prereq_ref_id(ref_id: ServerPlanRefId | str, *, kind: str) -> ServerPlanRefId:
    ref_text = str(ref_id)
    match = re.match(r"step_(\d+)", ref_text)
    if match:
        base_num = int(match.group(1))
        offset = 9150 if kind == "fts" else 9200
        return ServerPlanRefId(f"step_{base_num + offset}")
    suffix = "fts_scores" if kind == "fts" else "vector_scores"
    return ServerPlanRefId(f"{ref_text}_{suffix}")


