def _source_authority_membership(
    model_cls: type[DatabaseObjectRow],
    spec: QuerySpec,
    ctx: CompilationContext,
    source_id: SqlRenderable,
    *,
    branch_id: str | None = None,
    branch_ref_id: ServerPlanRefId | None = None,
    outer_ctes: list[SqlCteDefinition] | None = None,
) -> SqlRenderable:
    from impl.common.l5200_sql_query.query_grammar import QueryGrammarBuilder
    from impl.common.l2100_sql_grammar.tree.expr_ops import SqlIn

    if issubclass(model_cls, VersionedObjectRow):
        from dataclasses import replace
        from impl.common.l2070_server_plan.steps._compile_versioned import compile_versioned_query

        resolved_branch, branch_ref = (
            (branch_id, None)
            if branch_id is not None
            else _compile_branch_inputs(ctx, str(branch_ref_id) if branch_ref_id is not None else None)
        )
        effective_branch = _effective_branch_id(
            ctx, resolved_branch, branch_ref, branch_ref_id=str(branch_ref_id) if branch_ref_id is not None else None
        )
        query = replace(spec, search=None, select_columns=["sys_id"], order_by=(), limit=None, offset=None)
        revision = _require_hybrid_revision_id(
            ctx,
            "authorized hybrid source",
            branch_id=SqlParam(effective_branch) if isinstance(effective_branch, str) else effective_branch,
            branch_source_ref_id=branch_ref_id,
        )
        source = compile_versioned_query(
            query,
            model_cls,
            ctx,
            branch_id_override=effective_branch,
            revision_id_override=SqlParam(revision) if isinstance(revision, str) else revision,
            raw_mode=True,
        ).grammar
        if outer_ctes is not None:
            from impl.common.l2100_sql_grammar.tree.statements import SqlWith
            from impl.common.l2100_sql_grammar.domain.versioning.stmt_sparse import SqlSelectStarSparseAncestryVersioned

            if isinstance(source, (SqlWith, SqlSelectStarSparseAncestryVersioned)):
                definitions, source = source.split_for_outer_cte()
                outer_ctes.extend(definitions)
        return SqlIn(
            source_id,
            SqlSelect(
                select=[SqlColumnRef(SqlColumnName("sys_id"), qualifier="authorized_versioned")],
                from_=SqlSubqueryTableRef(source, SqlTableName("authorized_versioned")),
            ),
        )
    table = SqlTableName(get_table_name(model_cls))
    where = QueryGrammarBuilder(spec, planning_catalog=ctx.planning_catalog, compilation_context=ctx).build_where_clause()
    return SqlIn(
        source_id,
        SqlSelect(
            select=[SqlColumnRef(SqlColumnName("sys_id"), qualifier=str(table))],
            from_=SqlTableIdent(table),
            where=where,
        ),
    )


def _build_unversioned_fts_scores_prereq_select(
    *,
    model_cls: type[DatabaseObjectRow],
    spec: QuerySpec,
    ctx: CompilationContext,
) -> CompiledStep[object]:
    """Compile an FTS scores prerequisite CTE for an unversioned model.

    Produces a SELECT with columns ``(object_id, rank)`` that performs the FTS
    match/join against the base table. The resulting CTE is later consumed by
    the hybrid RRF query via ``_build_unversioned_fts_sql_components_from_score_cte``.
    """
    from l2070_batching.backend_profile import CrossBranchFtsCompileRequest
    from impl.common.l2070_server_plan.backend_profiles import _build_cross_branch_compile_sql_fts_components

    fts_query, fts_fields = _require_hybrid_fts_inputs(spec, versioned=False)

    table_name = get_table_name(model_cls)
    table_alias = SqlAliasName("t")
    fts_components = _build_cross_branch_compile_sql_fts_components(
        backend_type=ctx.backend_type,
        model_type=model_cls,
        compile_request=CrossBranchFtsCompileRequest(
            query=fts_query,
            columns=fts_fields,
            mode=spec.search_op.fts_mode if spec.search_op.fts_mode is not None else FTSSearchMode.NATURAL,
            table_name=table_name,
            table_alias=str(table_alias),
            use_content_hash=False,
            use_polyfill=False,
        ),
    )
    from_source: SqlRenderable
    joins: tuple[SqlRenderable, ...] = ()
    if fts_components.join_style == SqlFTSJoinStyle.FTS_TABLE_SYS_ID_JOIN:
        from_source = SqlFrom(_require_fts_table_join_clause(fts_components))
        joins = (
            SqlJoin(
                JoinKind.INNER,
                SqlTableAlias(SqlTableIdent(SqlTableName(table_name)), table_alias),
                SqlBinaryOp(
                    SqlColumnRef(SqlColumnName("sys_id"), qualifier=SqlAliasName("f")),
                    BinaryOp.EQ,
                    SqlColumnRef(SqlColumnName("sys_id"), qualifier=table_alias),
                ),
            ),
        )
    elif fts_components.join_style == SqlFTSJoinStyle.WHERE_ONLY:
        from_source = SqlFrom(SqlTableAlias(SqlTableIdent(SqlTableName(table_name)), table_alias))
    else:
