def _pgvector_metric_name(metric: object) -> str:
    from vector_types import VectorMetric

    if metric == VectorMetric.EUCLIDEAN:
        return "euclidean"
    if metric == VectorMetric.DOT_PRODUCT:
        return "dot_product"
    return "cosine"


def _pgvector_distance_kind(metric: object) -> str:
    from vector_types import VectorMetric

    if metric == VectorMetric.EUCLIDEAN:
        return "euclidean_distance"
    if metric == VectorMetric.DOT_PRODUCT:
        return "negative_inner_product"
    return "cosine_distance"


def _pgvector_similarity_threshold_to_max_distance(
    metric: object,
    threshold: float | None,
) -> float | None:
    from vector_types import VectorMetric

    if threshold is None:
        return None
    if metric == VectorMetric.COSINE:
        return (1.0 - threshold) * 2.0
    if metric == VectorMetric.EUCLIDEAN:
        if threshold <= 0.0:
            return None
        return (1.0 / threshold) - 1.0
    return -threshold


def _hamming_similarity_threshold_to_max_distance(
    threshold: float | None,
    *,
    dimensions: int,
) -> float | None:
    from l5200_vector_index.vector_projection import (
        VectorDimensions,
        VectorRawScoreKind,
        VectorScoreNormalizationKind,
        VectorScoreNormalizationSpec,
    )

    raw_threshold = VectorScoreNormalizationSpec(
        kind=VectorScoreNormalizationKind.HAMMING_DISTANCE,
        raw_score_kind=VectorRawScoreKind.HAMMING_DISTANCE,
        dimensions=VectorDimensions(dimensions),
    ).raw_threshold_for_canonical(threshold)
    if raw_threshold is None:
        return None
    return float(raw_threshold)


def _pgvector_score_expr(*, metric: object, distance_expr: SqlRenderable) -> SqlRenderable:
    from impl.common.l2100_sql_grammar.tree.enums import BinaryOp
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlInlineLiteral
    from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp
    from vector_types import VectorMetric

    if metric == VectorMetric.COSINE:
        return SqlBinaryOp(
            SqlInlineLiteral(1.0),
            BinaryOp.SUB,
            SqlBinaryOp(distance_expr, BinaryOp.DIV, SqlInlineLiteral(2.0)),
        )
    if metric == VectorMetric.EUCLIDEAN:
        return SqlBinaryOp(
            SqlInlineLiteral(1.0),
            BinaryOp.DIV,
            SqlBinaryOp(SqlInlineLiteral(1.0), BinaryOp.ADD, distance_expr),
        )
    return SqlBinaryOp(SqlInlineLiteral(-1.0), BinaryOp.MUL, distance_expr)


def _build_single_branch_pgvector_scores_prereq_select(
    *,
    model_cls: type[DatabaseObjectRow],
    spec: QuerySpec,
    ctx: CompilationContext,
    branch_id: str | None,
    branch_ref_id: ServerPlanRefId | None,
    use_rrf_candidates: bool,
) -> CompiledStep[object]:
    from impl.common.l2070_server_plan.steps.versioning_intent_steps import (
        _collect_dependency_auxiliary_ctes,
    )
    from impl.common.l2100_sql_grammar.domain.pgvector.pgvector import SqlVectorSearch
    from l5200_vector_index.vector_config import (
        get_vector_config,
    )

    _require_hybrid_vector_inputs(spec, site="Single-branch pgvector prerequisite compilation")
    assert spec.search_op.vector_index_name is not None
    config = _require_configured_pgvector_index(
        get_vector_config(model_cls, spec.search_op.vector_index_name),
        index_name=spec.search_op.vector_index_name,
        model_cls=model_cls,
    )
    projected_payload = _projected_vector_payload(spec)
    query_vector: tuple[float, ...] | None = None
    if projected_payload is None:
        assert spec.search_op.vector_query_vec is not None
        validate_query_vector_dimensions(model_cls, spec.search_op.vector_index_name, spec.search_op.vector_query_vec)
        query_vector = _require_hybrid_query_vector(
            spec,
            site="Single-branch pgvector prerequisite compilation",
        )
    effective_branch_id: str | SqlRenderable | None = branch_id
    revision_id: str | SqlRenderable | None = None
    if issubclass(model_cls, VersionedObjectRow):
        revision_id = ctx.revision_id
        if revision_id is None and effective_branch_id is None:
            resolved_branch_id, branch_cte_ref = _compile_branch_inputs(
                ctx,
                str(branch_ref_id) if branch_ref_id is not None else None,
            )
            effective_branch = _effective_branch_id(
                ctx,
                resolved_branch_id,
                branch_cte_ref,
                branch_ref_id=str(branch_ref_id) if branch_ref_id is not None else None,
            )
            effective_branch_id = effective_branch
        if config.indexes_all_revisions:
            revision_id = _require_hybrid_revision_id(
                ctx,
                "hybrid pgvector scores",
                branch_id=SqlParam(effective_branch_id) if isinstance(effective_branch_id, str) else effective_branch_id,
                branch_source_ref_id=branch_ref_id,
            )
            effective_branch_id = None
    revision_input = SysIdValue(revision_id) if isinstance(revision_id, str) else revision_id
    branch_input = SysIdValue(effective_branch_id) if isinstance(effective_branch_id, str) else effective_branch_id
    include_chunks = query_spec_requests_vector_chunks(spec)
    source_filter = (
        _source_authority_membership(
            model_cls, spec, ctx, SqlColumnRef(SqlColumnName("source_id")), branch_id=branch_id, branch_ref_id=branch_ref_id
        )
        if spec.search_op.rrf_enabled
        else None
    )
    if config.indexes_all_revisions and revision_id is not None:
        scope_alias = SqlAliasName("embedding_scope_ref")
        revision_expr = SqlParam(revision_id) if isinstance(revision_id, str) else revision_id
        assert isinstance(revision_expr, SqlRenderable)
        revision_scope = SqlExists(
            SqlSelect(
                select=SqlSelectList([SqlParam(1)]),
                from_=SqlTableAlias(SqlTableIdent(SqlTableName("sys_embedding_refs")), scope_alias),
                where=sql_and(
                    SqlBinaryOp(
                        SqlColumnRef(SqlColumnName("sys_id"), qualifier=scope_alias),
                        BinaryOp.EQ,
                        SqlColumnRef(SqlColumnName("embedding_ref_id")),
                    ),
                    SqlBinaryOp(
                        SqlColumnRef(SqlColumnName("revision_id"), qualifier=scope_alias),
                        BinaryOp.EQ,
                        revision_expr,
                    ),
                ),
            ),
        )
        source_filter = revision_scope if source_filter is None else sql_and(source_filter, revision_scope)
        revision_input = None
    if projected_payload is None:
        assert query_vector is not None
        inner_query = SqlVectorSearch(
            table=SqlTableName(f"{get_table_name(model_cls)}_{spec.search_op.vector_index_name}_embeddings"),
            query_vec=EmbeddingText("[" + ",".join(str(float(value)) for value in query_vector) + "]"),
            k=compute_vector_search_k(spec, use_rrf_candidates=use_rrf_candidates),
            metric=SqlVectorMetric(_pgvector_metric_name(config.metric)),
            revision_id=revision_input,
            branch_id=branch_input,
            max_distance=_pgvector_similarity_threshold_to_max_distance(config.metric, spec.search_op.vector_threshold),
            source_filter=source_filter,
        )
    else:
        from l5200_vector_index.vector_projection import VectorRepresentationKind

        representation_id = getattr(projected_payload, "projected_representation_id", None)
        representation = next(
            (candidate for candidate in config.available_representations if candidate.representation_id == representation_id),
            None,
        )
        if representation is None:
            msg = f"Projected representation {representation_id!r} is not configured for {model_cls.__name__}.{spec.search_op.vector_index_name}"
            raise ValueError(msg)
        if representation.kind != VectorRepresentationKind.BIT_HAMMING:
            msg = f"Projected pgvector search requires bit_hamming representation, got {representation.kind.value}"
            raise ValueError(msg)
        if config.native_binary_dimensions != int(representation.dimensions):
            msg = (
                "Projected pgvector search requires native_binary_dimensions to match "
                f"representation dimensions ({config.native_binary_dimensions!r} != {int(representation.dimensions)!r})"
            )
            raise ValueError(msg)
        inner_query = SqlVectorSearch(
            table=SqlTableName(f"{get_table_name(model_cls)}_{spec.search_op.vector_index_name}_embeddings"),
            query_vec=_packed_vector_code_to_bit_string(getattr(projected_payload, "projected_value")),
            k=compute_vector_search_k(spec, use_rrf_candidates=use_rrf_candidates),
            metric=SqlVectorMetric("hamming"),
            revision_id=revision_input,
            branch_id=branch_input,
            max_distance=_hamming_similarity_threshold_to_max_distance(
                spec.search_op.vector_threshold,
                dimensions=int(representation.dimensions),
            ),
            search_column=SqlColumnName(representation.storage_column),
            binary_dimensions=int(representation.dimensions),
            source_filter=source_filter,
        )
    scores_alias = SqlAliasName("pgv")
    select_items: list[Any] = [
        SqlSelectAlias(
            SqlColumnRef(SqlColumnName("source_id"), qualifier=scores_alias),
            SqlAliasName("object_id"),
        ),
        SqlSelectAlias(
            SqlColumnRef(SqlColumnName("score"), qualifier=scores_alias),
            SqlAliasName("score"),
        ),
        SqlSelectAlias(
            SqlColumnRef(SqlColumnName("distance"), qualifier=scores_alias),
            SqlAliasName("distance"),
        ),
        SqlSelectAlias(
            SqlInlineLiteral("hamming_distance" if projected_payload is not None else _pgvector_distance_kind(config.metric)),
            SqlAliasName("distance_kind"),
        ),
    ]
    if include_chunks:
        select_items.append(
            SqlSelectAlias(
                SqlColumnRef(SqlColumnName("chunk_id"), qualifier=scores_alias),
                SqlAliasName("chunk_id"),
            ),
        )
        select_items.append(
            SqlSelectAlias(
                SqlColumnRef(SqlColumnName("chunk_metadata"), qualifier=scores_alias),
                SqlAliasName("chunk_metadata"),
            ),
        )
    grammar = SqlSelect(
        select=SqlSelectList(select_items),
        from_=SqlFrom(SqlSubqueryTableRef(inner_query, SqlTableName("pgv"))),
    )
    dependency_auxiliary_ctes = _collect_dependency_auxiliary_ctes(ctx, str(branch_ref_id)) if branch_ref_id is not None else None
    __opa002_grammar_668 = grammar
    columns = (
        ("object_id", "score", "distance", "distance_kind", "chunk_id", "chunk_metadata")
        if include_chunks
        else ("object_id", "score", "distance", "distance_kind")
    )
    output_shape = CompiledOutputShape(tuple(synthetic_output_field(column, role="hybrid_vector_scores") for column in columns))
    column_type_hints = _score_prereq_type_hints(columns)
    return CompiledStep(
        output_shape=output_shape,
        grammar=__opa002_grammar_668,
        result_relation=DeclaredResultRelation.from_output_shape(output_shape),
        column_type_hints=column_type_hints,
        needs_returning=True,
        auxiliary_ctes=dependency_auxiliary_ctes,
        closed_post_op=row_dicts_post_op(),
    )


