class _PortableUSearchBlobPrereqStep(SqlRelationPublisherStep[object]):
    """Read one persisted USearch artifact through backend-neutral SQL."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        model_cls: type[DatabaseObjectRow],
        index_name: SqlIndexName,
        branch_ref_id: ServerPlanRefId | None,
    ) -> None:
        super().__init__(ref_id)
        self._model_cls = model_cls
        self._index_name = index_name
        self._branch_ref_id = branch_ref_id

    @property
    def level(self) -> int:
        return 0

    def step_tags(self) -> frozenset[str]:
        return frozenset({"read", "vector", "usearch", "artifact"})

    def is_read_only(self) -> bool:
        return True

    def result_cardinality(self) -> Cardinality:
        return Cardinality.ONE

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def tables_read(self) -> frozenset[str]:
        source_table = vector_source_table_name(self._model_cls)
        return frozenset({get_usearch_index_table_name(source_table)})

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def dependencies(self) -> frozenset[str]:
        if self._branch_ref_id is None:
            return frozenset()
        return frozenset({str(self._branch_ref_id)})

    def relation_output_columns(self) -> tuple[str, ...]:
        return ("index_blob", "dimensionality", "metric_type")

    def cte_relation_role(self) -> str:
        return "vector_usearch_artifact"

    def cte_publication_contract(self) -> CtePublicationContract:
        columns = self.relation_output_columns()
        hints = SqlColumnTypeHints(
            bytea_columns=frozenset({"index_blob"}),
            bigint_columns=frozenset({"dimensionality"}),
            text_columns=frozenset({"metric_type"}),
        )
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=columns,
            column_type_hints=hints,
            relation_contract=CteRelationContract.semantic_row(_USearchBlobPrereqRow),
            relation_role=self.cte_relation_role(),
            source_tables=self.tables_read(),
        )

    def compile(self, ctx: CompilationContext) -> CompiledStep[object]:
        source_table = vector_source_table_name(self._model_cls)
        usearch_table = SqlTableName(get_usearch_index_table_name(source_table))
        conditions: list[SqlRenderable] = [
            SqlBinaryOp(
                SqlColumnRef(SqlColumnName("field_name")),
                BinaryOp.EQ,
                SqlParam(str(self._index_name)),
            ),
            SqlIsNull(SqlColumnRef(SqlColumnName("revision_id"))),
        ]
        auxiliary_ctes = None
        if issubclass(self._model_cls, VersionedObjectRow):
            resolved_branch_id, branch_cte_ref = _compile_branch_inputs(
                ctx,
                str(self._branch_ref_id) if self._branch_ref_id is not None else None,
            )
            effective_branch = _effective_branch_id(
                ctx,
                resolved_branch_id,
                branch_cte_ref,
                branch_ref_id=(str(self._branch_ref_id) if self._branch_ref_id is not None else None),
            )
            if effective_branch is None:
                raise ProgrammingError("Portable USearch search requires a branch identity")
            conditions.append(SqlIsNull(SqlColumnRef(SqlColumnName("branch_id"))))
            from impl.common.l2070_server_plan.steps.versioning_intent_steps import (
                _collect_dependency_auxiliary_ctes,
            )

            auxiliary_ctes = (
                _collect_dependency_auxiliary_ctes(ctx, str(self._branch_ref_id)) if self._branch_ref_id is not None else None
            )
        else:
            conditions.append(SqlIsNull(SqlColumnRef(SqlColumnName("branch_id"))))

        columns = self.relation_output_columns()
        output_shape = CompiledOutputShape(tuple(synthetic_output_field(column, role="vector_usearch_artifact") for column in columns))
        grammar = SqlSelect(
            select=SqlSelectList([SqlColumnRef(SqlColumnName(column)) for column in columns]),
            from_=SqlFrom(SqlTableIdent(usearch_table)),
            where=SqlWhereClause(sql_and(*conditions)),
        )
        return CompiledStep(
            output_shape=output_shape,
            grammar=grammar,
            result_relation=DeclaredResultRelation.from_output_shape(output_shape),
            column_type_hints=self.cte_publication_contract().column_type_hints,
            needs_returning=True,
            auxiliary_ctes=auxiliary_ctes,
            closed_post_op=row_dicts_post_op(),
        )


class _PortableUSearchScorePrereqStep(ServerPlanStep[list[dict[str, object]]]):
    """Score a SQL-read USearch artifact and publish typed candidate rows."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        blob_ref_id: ServerPlanRefId,
        query_vector: DenseVectorValues,
        k: VectorCandidateLimit,
        ef_search: PortableUSearchEfSearch,
        threshold: PortableUSearchScoreThreshold | None,
    ) -> None:
        super().__init__(ref_id)
        self._blob_ref_id = blob_ref_id
        self._query_vector = query_vector
        self._k = k
        self._ef_search = ef_search
        self._threshold = threshold

    @property
    def level(self) -> int:
        return 0

    def step_tags(self) -> frozenset[str]:
        return frozenset({"read", "vector", "usearch", "score"})

    def is_read_only(self) -> bool:
        return True

    def result_cardinality(self) -> Cardinality:
        return Cardinality.MANY

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def is_executor_owned_runtime_step(self) -> bool:
        return True

    def requires_prior_step_boundary(self) -> bool:
        return True

    def supports_sql_batch_transport(self) -> bool:
        return False

    def dependencies(self) -> frozenset[str]:
        return frozenset({str(self._blob_ref_id)})

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def cte_publication_contract(self) -> CtePublicationContract:
        return CtePublicationContract.non_publishing()

    def semantic_publication_columns(self) -> tuple[str, ...]:
        return ("native_key", "score", "distance", "distance_kind")

    def semantic_publication_type_hints(self) -> SqlColumnTypeHints:
        return SqlColumnTypeHints(
            bigint_columns=frozenset({"native_key"}),
            double_columns=frozenset({"score", "distance"}),
            text_columns=frozenset({"distance_kind"}),
        )

    def executor_visible_published_rows(self) -> Sequence[Mapping[str, object]] | None:
        return None

    def publication_products(self) -> StepPublicationProducts:
        return StepPublicationProducts(
            sql=NoSqlBinding(),
            runtime=NoRuntimePublication(),
        )

    def compile(self, ctx: CompilationContext) -> CompiledStep[list[dict[str, object]]]:
        del ctx
        output_shape = CompiledOutputShape(
            tuple(synthetic_output_field(column, role="hybrid_vector_scores") for column in self.semantic_publication_columns())
        )
        return CompiledStep(
            output_shape=output_shape,
            result_relation=DeclaredResultRelation.from_output_shape(output_shape),
            column_type_hints=self.semantic_publication_type_hints(),
        )

    def execute_runtime(self, resolved: ResolvedRefs) -> list[dict[str, object]]:
        from l5200_vector_index.usearch_runtime import (
            load_usearch_blob,
            require_usearch_metric,
            search_loaded_usearch_index,
            usearch_distance_kind,
        )

        raw_rows = resolved.get(str(self._blob_ref_id), ())
        if not isinstance(raw_rows, Sequence) or isinstance(raw_rows, str | bytes | bytearray):
            raise TypeError("Portable USearch artifact input must be a row sequence")
        if not raw_rows:
            return []
        row = raw_rows[0]
        if not isinstance(row, Mapping):
            raise TypeError("Portable USearch artifact row must be a mapping")
        raw_blob = row.get("index_blob")
        dimensions = row.get("dimensionality")
        metric = row.get("metric_type")
        if isinstance(raw_blob, bytearray | memoryview):
            artifact_blob = bytes(raw_blob)
        elif isinstance(raw_blob, bytes):
            artifact_blob = raw_blob
        elif isinstance(raw_blob, str) and raw_blob.startswith("\\x"):
            artifact_blob = bytes.fromhex(raw_blob[2:])
        else:
            raise TypeError("Portable USearch artifact index_blob must be binary")
        if not isinstance(dimensions, int):
            raise TypeError("Portable USearch artifact dimensionality must be an integer")
        if not isinstance(metric, str):
            raise TypeError("Portable USearch artifact metric_type must be text")
        typed_metric = require_usearch_metric(metric)
        scores = search_loaded_usearch_index(
            load_usearch_blob(artifact_blob, dimensions, typed_metric),
            typed_metric,
            self._query_vector,
            self._k,
            self._ef_search,
        )
        distance_kind = usearch_distance_kind(typed_metric)
        return [
            {
                "native_key": int(score.native_key),
                "score": score.score,
                "distance": score.distance,
                "distance_kind": distance_kind,
            }
            for score in scores
            if self._threshold is None or score.score >= self._threshold
        ]


def _build_sqlite_usearch_scores_prereq_select(
    *,
    model_cls: type[DatabaseObjectRow],
    spec: QuerySpec,
    ctx: CompilationContext,
    branch_id: str | None,
    branch_ref_id: ServerPlanRefId | None,
    use_rrf_candidates: bool,
) -> CompiledStep[object]:
    from impl.common.l2100_sql_grammar.domain.vector_index.sqlite_usearch import (
        SqliteUSearchFilteredScoreRelation,
        SqliteUSearchScoreRelation,
    )

    _require_hybrid_vector_inputs(spec, site="SQLite USearch prerequisite compilation")
    branch_expr: SqlRenderable | None = None
    if issubclass(model_cls, VersionedObjectRow):
        resolved_branch_id, branch_cte_ref = _compile_branch_inputs(
            ctx,
            str(branch_ref_id) if branch_ref_id is not None else None,
        )
        effective_branch = _effective_branch_id(
            ctx,
            branch_id or resolved_branch_id,
            branch_cte_ref,
            branch_ref_id=str(branch_ref_id) if branch_ref_id is not None else None,
        )
        if effective_branch is None:
            raise ProgrammingError("SQLite USearch tip search requires a branch identity")
        branch_expr = SqlParam(str(effective_branch)) if isinstance(effective_branch, str | BranchId) else effective_branch
    assert spec.search_op.vector_index_name is not None
    query_vector = sql_table_hnsw_query_vector(spec)
    assert query_vector is not None
    vector_config = get_vector_config(model_cls, spec.search_op.vector_index_name)
    if vector_config is None:
        raise ProgrammingError(f"SQLite USearch index {spec.search_op.vector_index_name!r} is not configured")
    source_table = SqlTableName(vector_source_table_name(model_cls))
    candidate_count = compute_vector_search_k(
        spec,
        use_rrf_candidates=use_rrf_candidates,
    )
    relation: SqlShapeClause = SqliteUSearchScoreRelation(
        source_table=source_table,
        field_name=spec.search_op.vector_index_name,
        query_vector=tuple(query_vector),
        k=candidate_count,
        ef_search=spec.search_op.vector_ef_search or vector_config.ef_search,
        threshold=spec.search_op.vector_threshold,
        branch_id=branch_expr,
    )
    if spec.filters:
        from impl.common.l5200_sql_query.query_grammar import QueryGrammarBuilder

        where_clause = QueryGrammarBuilder(
            spec,
            table_alias="t",
            planning_catalog=ctx.planning_catalog,
        ).build_where_clause()
        if where_clause is not None:
            relation = SqliteUSearchFilteredScoreRelation(
                source_table=source_table,
                source_id_column=SqlColumnName(get_db_column_name(model_cls, DynamicFieldName("sys_id"))),
                field_name=spec.search_op.vector_index_name,
                query_vector=tuple(query_vector),
                k=candidate_count,
                ef_search=spec.search_op.vector_ef_search or vector_config.ef_search,
                threshold=spec.search_op.vector_threshold,
                branch_id=branch_expr,
                filter_condition=where_clause.condition,
            )
    columns = (
        "object_id",
        "score",
        "distance",
        "distance_kind",
        "chunk_id",
        "chunk_metadata",
    )
    output_shape = CompiledOutputShape(tuple(synthetic_output_field(column, role="hybrid_vector_scores") for column in columns))
    return CompiledStep(
        output_shape=output_shape,
        grammar=relation,
        result_relation=DeclaredResultRelation.from_output_shape(output_shape),
        column_type_hints=_score_prereq_type_hints(columns),
        needs_returning=True,
        closed_post_op=row_dicts_post_op(),
    )


def _build_content_addressed_vector_scores_prereq_select(
    *,
    model_cls: type[DatabaseObjectRow],
    spec: QuerySpec,
    ctx: CompilationContext,
    branch_id: str | None,
    branch_ref_id: ServerPlanRefId | None,
    user_id_ref_id: ServerPlanRefId | None,
    use_rrf_candidates: bool,
) -> CompiledStep[object]:
    """Score authoritative embedding rows when the selected index is application-owned."""
    from impl.common.l2070_server_plan.steps.versioning_intent_steps import (
        _collect_dependency_auxiliary_ctes,
    )
    from l5200_vector_index.content_addressable_models import EmbeddingRef, EmbeddingVector
    from l5200_vector_index.vector_config import get_vector_config

    _require_hybrid_vector_inputs(spec, site="Content-addressed vector prerequisite compilation")
    index_name = spec.search_op.vector_index_name
    assert index_name is not None
    query_vector = _require_hybrid_query_vector(
        spec,
        site="Content-addressed vector prerequisite compilation",
    )
    validate_query_vector_dimensions(model_cls, index_name, query_vector)
    config = get_vector_config(model_cls, index_name)
    if config is None:
        raise ValueError(f"Vector index {model_cls.__name__}.{index_name} is not configured")

    refs_alias = SqlAliasName("usearch_refs")
    vectors_alias = SqlAliasName("usearch_vectors")
    embedding = SqlColumnRef(SqlColumnName("embedding"), qualifier=vectors_alias)
    projected_dimensions = config.target_dimensions
    if projected_dimensions is None:
        effective_query_vector = tuple(float(value) for value in query_vector)
        query_json = json.dumps(effective_query_vector, separators=(",", ":"))
        dot: SqlRenderable = SqlFuncCall("nera_embedding_dot", [embedding, SqlParam(query_json)])
        vector_norm_squared: SqlRenderable = SqlFuncCall("nera_embedding_dot", [embedding, embedding])
    else:
        effective_query_vector = tuple(float(value) for value in query_vector[:projected_dimensions])
        dot = SqlInlineLiteral(0.0)
        vector_norm_squared = SqlInlineLiteral(0.0)
        for index, query_value in enumerate(effective_query_vector):
            component = SqlFuncCall(
                "nera_embedding_float32_at",
                [embedding, SqlInlineLiteral(index)],
            )
            dot = SqlBinaryOp(
                dot,
                BinaryOp.ADD,
                SqlBinaryOp(component, BinaryOp.MUL, SqlParam(query_value)),
            )
            vector_norm_squared = SqlBinaryOp(
                vector_norm_squared,
                BinaryOp.ADD,
                SqlBinaryOp(component, BinaryOp.MUL, component),
            )
    query_norm_squared = sum(value * value for value in effective_query_vector)
    if config.metric == VectorMetric.COSINE:
        denominator = SqlFuncCall(
            "SQRT",
            [SqlBinaryOp(vector_norm_squared, BinaryOp.MUL, SqlParam(query_norm_squared))],
        )
        score: SqlRenderable = SqlFuncCall(
            "COALESCE",
            [
                SqlBinaryOp(
                    dot,
                    BinaryOp.DIV,
                    SqlFuncCall("NULLIF", [denominator, SqlInlineLiteral(0.0)]),
                ),
                SqlInlineLiteral(0.0),
            ],
        )
        distance: SqlRenderable = SqlBinaryOp(SqlInlineLiteral(1.0), BinaryOp.SUB, score)
        distance_kind = "cosine_distance"
    elif config.metric == VectorMetric.EUCLIDEAN:
        squared_distance = SqlBinaryOp(
            SqlBinaryOp(vector_norm_squared, BinaryOp.ADD, SqlParam(query_norm_squared)),
            BinaryOp.SUB,
            SqlBinaryOp(SqlInlineLiteral(2.0), BinaryOp.MUL, dot),
        )
        distance = squared_distance
        score = SqlBinaryOp(
            SqlInlineLiteral(1.0),
            BinaryOp.DIV,
            SqlBinaryOp(
                SqlInlineLiteral(1.0),
                BinaryOp.ADD,
                SqlFuncCall("SQRT", [squared_distance]),
            ),
        )
        distance_kind = "squared_euclidean_distance"
    else:
        score = dot
        distance = SqlBinaryOp(SqlInlineLiteral(-1.0), BinaryOp.MUL, dot)
        distance_kind = "negative_inner_product"

    if ctx.backend_profile.traits.vector_sql_transport is VectorSqlTransport.PGVECTOR and config.indexes_all_revisions:
        from impl.common.l2100_sql_grammar.domain.pgvector.pgvector import SqlCanonicalPgVector, SqlPgVectorDistance

        native_embedding = SqlCanonicalPgVector(embedding, projected_dimensions)
        distance = SqlPgVectorDistance(
            native_embedding,
            EmbeddingText("[" + ",".join(str(float(value)) for value in effective_query_vector) + "]"),
            SqlVectorMetric(_pgvector_metric_name(config.metric)),
        )
        score = _pgvector_score_expr(metric=config.metric, distance_expr=distance)
        distance_kind = _pgvector_distance_kind(config.metric)

    conditions: list[SqlRenderable] = [
        SqlBinaryOp(
            SqlColumnRef(SqlColumnName("source_table"), qualifier=refs_alias),
            BinaryOp.EQ,
            SqlParam(vector_source_table_name(model_cls)),
        ),
        SqlBinaryOp(
            SqlColumnRef(SqlColumnName("field_name"), qualifier=refs_alias),
            BinaryOp.EQ,
            SqlParam(index_name),
        ),
    ]
    effective_branch: str | SqlRenderable | None = branch_id
    if issubclass(model_cls, VersionedObjectRow) and effective_branch is None:
        resolved_branch_id, branch_cte_ref = _compile_branch_inputs(
            ctx,
            str(branch_ref_id) if branch_ref_id is not None else None,
        )
        effective_branch = _effective_branch_id(
            ctx,
            resolved_branch_id,
            branch_cte_ref,
            branch_ref_id=str(branch_ref_id) if branch_ref_id is not None else None,
        )
    revision_branch = SqlParam(effective_branch) if isinstance(effective_branch, str) else effective_branch
    if issubclass(model_cls, VersionedObjectRow) and config.indexes_all_revisions:
        effective_branch = None
    if effective_branch is not None:
        branch_expression = SqlParam(effective_branch) if isinstance(effective_branch, str) else effective_branch
        conditions.append(
            SqlBinaryOp(
                SqlColumnRef(SqlColumnName("branch_id"), qualifier=refs_alias),
                BinaryOp.EQ,
                branch_expression,
            ),
        )
    else:
        conditions.append(SqlIsNull(SqlColumnRef(SqlColumnName("branch_id"), qualifier=refs_alias)))
    source_ctes: list[SqlCteDefinition] = []
    source_joins: list[SqlJoin] = []
    revision_scope: str | SqlRenderable | None = ctx.revision_id
    if issubclass(model_cls, VersionedObjectRow) and config.indexes_all_revisions:
        from impl.common.l2070_server_plan.steps.versioned_hybrid_source import visible_hybrid_source
        from impl.common.l2070_server_plan.steps.hybrid_source_hash import source_content_matches_reference

        revision_scope = _require_hybrid_revision_id(
            ctx, "hybrid vector scores", branch_id=revision_branch, branch_source_ref_id=branch_ref_id
        )
        from l5200_vector_index.embedding_content_hash import get_embedding_source_fields
        from l1000_schema.dynamic_field_utils import is_dynamic_property_field

        source_fields = get_embedding_source_fields(model_cls, SqlIndexName(index_name))
        source_columns = list(
            dict.fromkeys(
                [
                    "sys_id",
                    *("properties" if is_dynamic_property_field(model_cls, DynamicFieldName(name)) else name for name in source_fields),
                ]
            )
        )
        source_ctes.extend(
            visible_hybrid_source(
                model_cls,
                spec,
                ctx,
                revision=revision_scope,
                branch=revision_branch,
                name="hybrid_vector_visible",
                columns=source_columns,
            )
        )
        source_joins.append(
            SqlJoin(
                JoinKind.INNER,
                SqlTableAlias(SqlTableIdent(SqlTableName("hybrid_vector_visible")), SqlAliasName("visible_vector")),
                SqlBinaryOp(
                    SqlColumnRef(SqlColumnName("sys_id"), qualifier="visible_vector"),
                    BinaryOp.EQ,
                    SqlColumnRef(SqlColumnName("source_id"), qualifier=refs_alias),
                ),
            )
        )
        conditions.append(source_content_matches_reference(model_cls, index_name, source_alias="visible_vector", refs_alias=refs_alias))
    elif revision_scope is not None:
        conditions.append(
            SqlBinaryOp(
                SqlColumnRef(SqlColumnName("revision_id"), qualifier=refs_alias),
                BinaryOp.EQ,
                SqlParam(revision_scope) if isinstance(revision_scope, str) else revision_scope,
            ),
        )
    else:
        conditions.append(SqlIsNull(SqlColumnRef(SqlColumnName("revision_id"), qualifier=refs_alias)))
    if query_spec_requests_vector_chunks(spec):
        chunk_alias = SqlAliasName("preferred_chunk_ref")

        def _same_nullable_scope(column: str) -> SqlRenderable:
            current = SqlColumnRef(SqlColumnName(column), qualifier=refs_alias)
            candidate = SqlColumnRef(SqlColumnName(column), qualifier=chunk_alias)
            return sql_or(
                SqlBinaryOp(candidate, BinaryOp.EQ, current),
                sql_and(SqlIsNull(candidate), SqlIsNull(current)),
            )

        chunk_ref_query = SqlSelect(
            select=[SqlInlineLiteral(1)],
            from_=SqlFrom(
                SqlTableAlias(
                    SqlTableIdent(SqlTableName(get_table_name(EmbeddingRef))),
                    chunk_alias,
                ),
            ),
            where=sql_and(
                SqlBinaryOp(
                    SqlColumnRef(SqlColumnName("source_id"), qualifier=chunk_alias),
                    BinaryOp.EQ,
                    SqlColumnRef(SqlColumnName("source_id"), qualifier=refs_alias),
                ),
                SqlBinaryOp(
                    SqlColumnRef(SqlColumnName("source_table"), qualifier=chunk_alias),
                    BinaryOp.EQ,
                    SqlColumnRef(SqlColumnName("source_table"), qualifier=refs_alias),
                ),
                SqlBinaryOp(
                    SqlColumnRef(SqlColumnName("field_name"), qualifier=chunk_alias),
                    BinaryOp.EQ,
                    SqlColumnRef(SqlColumnName("field_name"), qualifier=refs_alias),
                ),
                _same_nullable_scope("branch_id"),
                _same_nullable_scope("revision_id"),
                SqlIsNull(
                    SqlColumnRef(SqlColumnName("chunk_metadata"), qualifier=chunk_alias),
                    negated=True,
                ),
            ),
        )
        conditions.append(
            sql_or(
                SqlIsNull(
                    SqlColumnRef(SqlColumnName("chunk_metadata"), qualifier=refs_alias),
                    negated=True,
                ),
                SqlExists(chunk_ref_query, negated=True),
            )
        )
    if ctx.backend_profile.traits.vector_sql_transport is VectorSqlTransport.PGVECTOR and config.indexes_all_revisions:
        conditions.append(SqlIsNull(distance, negated=True))
    if spec.search_op.vector_threshold is not None:
        conditions.append(SqlBinaryOp(score, BinaryOp.GE, SqlParam(spec.search_op.vector_threshold)))
    if spec.search_op.rrf_enabled and not (issubclass(model_cls, VersionedObjectRow) and config.indexes_all_revisions):
        conditions.append(
            _source_authority_membership(
                model_cls,
                spec,
                ctx,
                SqlColumnRef(SqlColumnName("source_id"), qualifier=refs_alias),
                branch_id=branch_id,
                branch_ref_id=branch_ref_id,
                outer_ctes=source_ctes,
            )
        )

    select_items: list[SqlRenderable] = [
        SqlSelectAlias(
            SqlColumnRef(SqlColumnName("source_id"), qualifier=refs_alias),
            SqlAliasName("object_id"),
        ),
        SqlSelectAlias(score, SqlAliasName("score")),
        SqlSelectAlias(distance, SqlAliasName("distance")),
        SqlSelectAlias(SqlInlineLiteral(distance_kind), SqlAliasName("distance_kind")),
        SqlSelectAlias(
            SqlColumnRef(SqlColumnName("chunk_id"), qualifier=refs_alias),
            SqlAliasName("chunk_id"),
        ),
        SqlSelectAlias(
            SqlColumnRef(SqlColumnName("chunk_metadata"), qualifier=refs_alias),
            SqlAliasName("chunk_metadata"),
        ),
    ]
    columns = ["object_id", "score", "distance", "distance_kind", "chunk_id", "chunk_metadata"]
    grammar = SqlSelect(
        select=SqlSelectList(select_items),
        distinct=issubclass(model_cls, VersionedObjectRow) and config.indexes_all_revisions,
        from_=SqlFrom(
            SqlTableAlias(
                SqlTableIdent(SqlTableName(get_table_name(EmbeddingRef))),
                refs_alias,
            ),
        ),
        joins=[
            *source_joins,
            SqlJoin(
                JoinKind.INNER,
                SqlTableAlias(
                    SqlTableIdent(SqlTableName(get_table_name(EmbeddingVector))),
                    vectors_alias,
                ),
                sql_and(
                    SqlBinaryOp(
                        SqlColumnRef(SqlColumnName("content_hash_short"), qualifier=vectors_alias),
                        BinaryOp.EQ,
                        SqlColumnRef(SqlColumnName("content_hash_short"), qualifier=refs_alias),
                    ),
                    SqlBinaryOp(
                        SqlColumnRef(SqlColumnName("content_hash_high"), qualifier=vectors_alias),
                        BinaryOp.EQ,
                        SqlColumnRef(SqlColumnName("content_hash_high"), qualifier=refs_alias),
                    ),
                ),
            ),
        ],
        where=SqlWhereClause(sql_and(*conditions)),
        order_by=SqlOrderByClause(
            [SqlOrderByItem(SqlColumnRef(SqlColumnName("score")), OrderDirection.DESC)],
        ),
        limit=None,
    )
    output_columns = tuple(columns)
    output_shape = CompiledOutputShape(
        tuple(synthetic_output_field(column, role="hybrid_vector_scores") for column in output_columns),
    )
    dependency_refs = [str(ref_id) for ref_id in (branch_ref_id, user_id_ref_id) if ref_id is not None]
    if isinstance(ctx.lazy_revision, ScalarServerRef):
        dependency_refs.extend(ctx.lazy_revision.dependencies())
    dependency_auxiliary_ctes = _collect_dependency_auxiliary_ctes(ctx, *dependency_refs)
    return CompiledStep(
        output_shape=output_shape,
        grammar=SqlCte(source_ctes, grammar) if source_ctes else grammar,
        result_relation=DeclaredResultRelation.from_output_shape(output_shape),
        column_type_hints=_score_prereq_type_hints(output_columns),
        needs_returning=True,
        auxiliary_ctes=dependency_auxiliary_ctes,
        closed_post_op=row_dicts_post_op(),
    )


def _build_single_branch_vector_scores_prereq_select(
    *,
    model_cls: type[DatabaseObjectRow],
    spec: QuerySpec,
    ctx: CompilationContext,
    branch_id: str | None,
    branch_ref_id: ServerPlanRefId | None,
    user_id_ref_id: ServerPlanRefId | None,
    use_rrf_candidates: bool,
) -> CompiledStep[object]:
    from impl.common.l2070_server_plan.backend_profiles import (
        query_spec_prefers_sql_table_hnsw_components,
    )
    from impl.common.l2070_server_plan.steps.versioning_intent_steps import (
        _collect_dependency_auxiliary_ctes,
    )
    from impl.common.l2100_sql_grammar.domain.sql_table_hnsw import (
        build_sql_table_hnsw_score_components,
    )

    from l5200_vector_index.vector_config import get_vector_config

    config = get_vector_config(model_cls, spec.search_op.vector_index_name) if spec.search_op.vector_index_name is not None else None
    if spec.search_op.rrf_enabled:
        return _build_content_addressed_vector_scores_prereq_select(
            model_cls=model_cls,
            spec=spec,
            ctx=ctx,
            branch_id=branch_id,
            branch_ref_id=branch_ref_id,
            user_id_ref_id=user_id_ref_id,
            use_rrf_candidates=use_rrf_candidates,
        )
    backend_override = spec.search_op.vector_backend_kind_override
    if backend_override is None and spec.search_op.vector_index_name is not None:
        from l1450_index_policy_contracts import VectorIndexImplementation

        configured_indexes = getattr(model_cls, "__vector_indexes__", {})
        selected_config = configured_indexes.get(spec.search_op.vector_index_name) if isinstance(configured_indexes, dict) else None
        if (
            selected_config is not None
            and selected_config.resolved_index_policy.requested_implementation is VectorIndexImplementation.USEARCH
        ):
            backend_override = "usearch"
    if (
        backend_override == "usearch"
        and ctx.backend_profile.traits.has_usearch_sql_runtime
        and not issubclass(model_cls, VersionedObjectRow)
    ):
        return _build_sqlite_usearch_scores_prereq_select(
            model_cls=model_cls,
            spec=spec,
            ctx=ctx,
            branch_id=branch_id,
            branch_ref_id=branch_ref_id,
            use_rrf_candidates=use_rrf_candidates,
        )
    if backend_override == "usearch":
        from l1100_exceptions import NativeSearchIntegrityError

        raise NativeSearchIntegrityError("USearch requires native prerequisite lowering")
    if query_spec_prefers_sql_table_hnsw_components(
        model_cls=model_cls,
        query_spec=spec,
        backend_type=ctx.backend_type,
    ):
        pass
    elif ctx.backend_profile.traits.vector_sql_transport is VectorSqlTransport.PGVECTOR:
        return _build_single_branch_pgvector_scores_prereq_select(
            model_cls=model_cls,
            spec=spec,
            ctx=ctx,
            branch_id=branch_id,
            branch_ref_id=branch_ref_id,
            use_rrf_candidates=use_rrf_candidates,
        )
    else:
        _raise_sql_table_hnsw_components_required(
            f"Single-branch vector prerequisite compilation (backend override: {backend_override!r})"
        )
        raise AssertionError("unreachable")
    _require_hybrid_vector_inputs(spec, site="Single-branch vector prerequisite compilation")
    assert spec.search_op.vector_index_name is not None
    projected_hamming = sql_table_hnsw_projected_hamming_query(
        model_cls=model_cls,
        index_name=SqlIndexName(spec.search_op.vector_index_name),
        spec=spec,
    )
    if projected_hamming is None:
        assert spec.search_op.vector_query_vec is not None
        validate_query_vector_dimensions(model_cls, spec.search_op.vector_index_name, spec.search_op.vector_query_vec)
        query_vector = _require_hybrid_query_vector(
            spec,
            site="Single-branch vector prerequisite compilation",
        )
    else:
        query_vector = (0.0,)
    include_chunks = query_spec_requests_vector_chunks(spec)
    effective_branch_id: str | SqlRenderable | None = branch_id
    revision_id = ctx.revision_id
    if revision_id is None and effective_branch_id is None and issubclass(model_cls, VersionedObjectRow):
        resolved_branch_id, branch_cte_ref = _compile_branch_inputs(
            ctx,
            str(branch_ref_id) if branch_ref_id is not None else None,
        )
        if resolved_branch_id is not None:
            effective_branch_id = resolved_branch_id
        effective_branch = _effective_branch_id(
            ctx,
            resolved_branch_id,
            branch_cte_ref,
            branch_ref_id=str(branch_ref_id) if branch_ref_id is not None else None,
        )
        if effective_branch_id is None:
            effective_branch_id = effective_branch
    from l5200_vector_index.index_resolution import VectorBackendKind, resolve_vector_keying_mode
    from l5200_vector_index.vector_config import get_vector_config

    vector_config = get_vector_config(model_cls, spec.search_op.vector_index_name)
    vector_config = _require_hybrid_vector_config(
        vector_config,
        index_name=spec.search_op.vector_index_name,
        model_cls=model_cls,
    )
    from impl.common.l2070_server_plan.hnsw_content_stores import hnsw_embedding_tables

    vector_tables, ref_tables = hnsw_embedding_tables(
        SqlTableName(vector_source_table_name(model_cls)),
        SqlIndexName(spec.search_op.vector_index_name),
        vector_config,
        catalog=ctx.planning_catalog,
    )
    vector_components = build_sql_table_hnsw_score_components(
        embedding_vector_tables=vector_tables,
        embedding_ref_tables=ref_tables,
        metric=vector_config.metric,
        source_table_name=vector_source_table_name(model_cls),
        field_name=spec.search_op.vector_index_name,
        query_vector=query_vector,
        k=compute_vector_search_k(spec, use_rrf_candidates=use_rrf_candidates),
        ef_search=spec.search_op.vector_ef_search,
        threshold=spec.search_op.vector_threshold,
        include_chunks=include_chunks,
        table_alias="t",
        branch_id=effective_branch_id,
        revision_id=revision_id,
        keying_mode=resolve_vector_keying_mode(vector_config, VectorBackendKind.SQL_TABLE_HNSW),
        query_binary=(None if projected_hamming is None else projected_hamming.query_binary),
        binary_dimensions=(None if projected_hamming is None else projected_hamming.binary_dimensions),
    )
    _require_hybrid_vector_join_clause(
        vector_components,
        site="Single-branch vector prerequisite compilation",
    )
    select_items: list[Any] = [
        SqlSelectAlias(
            SqlColumnRef(SqlColumnName("source_id"), qualifier=SqlAliasName("vs")),
            SqlAliasName("object_id"),
        ),
        SqlSelectAlias(
            SqlColumnRef(SqlColumnName("score"), qualifier=SqlAliasName("vs")),
            SqlAliasName("score"),
        ),
        SqlSelectAlias(SQL_EXPR_NULL, SqlAliasName("distance")),
        SqlSelectAlias(SQL_EXPR_NULL, SqlAliasName("distance_kind")),
    ]
    if include_chunks:
        select_items.append(
            SqlSelectAlias(
                SqlColumnRef(SqlColumnName("chunk_id"), qualifier=SqlAliasName("vs")),
                SqlAliasName("chunk_id"),
            ),
        )
        select_items.append(
            SqlSelectAlias(
                SqlColumnRef(SqlColumnName("chunk_metadata"), qualifier=SqlAliasName("vs")),
                SqlAliasName("chunk_metadata"),
            ),
        )
    grammar = SqlSelect(
        select=SqlSelectList(select_items),
        from_=vector_components.join_clause,
        order_by=SqlOrderByClause(
            [
                SqlOrderByItem(
                    SqlColumnRef(SqlColumnName("score"), qualifier=SqlAliasName("vs")),
                    OrderDirection.DESC,
                ),
            ],
        ),
    )
    dependency_auxiliary_ctes = _collect_dependency_auxiliary_ctes(ctx, str(branch_ref_id)) if branch_ref_id is not None else None
    __opa002_grammar_811 = grammar
    columns = (
        ("object_id", "score", "distance", "distance_kind", "chunk_id", "chunk_metadata")
        if include_chunks
        else ("object_id", "score", "distance", "distance_kind")
    )
    output_shape = CompiledOutputShape(tuple(synthetic_output_field(column, role="hybrid_vector_scores") for column in columns))
    column_type_hints = _score_prereq_type_hints(columns)
    return CompiledStep(
        output_shape=output_shape,
        grammar=__opa002_grammar_811,
        needs_returning=True,
        needs_recursive_with=True,
        result_relation=DeclaredResultRelation.from_output_shape(output_shape),
        column_type_hints=column_type_hints,
        auxiliary_ctes=dependency_auxiliary_ctes,
        closed_post_op=row_dicts_post_op(),
    )


def _search_prereq_dependencies(
    extra: tuple[ServerPlanRefId, ...],
    user: ServerPlanRefId | None,
    revision: ScalarServerRef[RevisionId] | None,
) -> tuple[ServerPlanRefId, ...]:
    refs = list(extra)
    if user is not None:
        refs.append(user)
    if revision is not None:
        refs.extend(ServerPlanRefId(ref) for ref in revision.dependencies())
    return tuple(dict.fromkeys(refs))


def _authorized_search_spec(
    spec: Any,
    model_cls: type[DatabaseObjectRow],
    ctx: CompilationContext,
    user_id_ref_id: ServerPlanRefId | None,
) -> Any:
    from impl.common.l2070_server_plan.steps._compile_helpers import attach_runtime_read_permission_grammar

    authorized = attach_runtime_read_permission_grammar(spec, model_cls, ctx, user_id_ref_id=user_id_ref_id)
    assert authorized is not None
    assert type(authorized) is type(spec)
    return authorized


class _SingleBranchFtsScoresPrereqStep(SqlRelationPublisherStep[object]):
    """Publish single-branch FTS score rows before hybrid terminal compilation."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        model_cls: type[DatabaseObjectRow],
        query_spec: QuerySpec,
        user_id_ref_id: ServerPlanRefId | None = None,
        revision_source: ScalarServerRef[RevisionId] | None = None,
        branch_id: BranchId | None = None,
        branch_ref_id: ServerPlanRefId | None = None,
        extra_dependency_ref_ids: tuple[ServerPlanRefId, ...] = (),
    ) -> None:
        super().__init__(ref_id)
        self._model_cls = model_cls
        self._query_spec = query_spec
        self._branch_id = branch_id
        self._branch_ref_id = branch_ref_id
        self._user_id_ref_id = user_id_ref_id
        self._revision_source = revision_source
        self._extra_dependency_ref_ids = _search_prereq_dependencies(extra_dependency_ref_ids, user_id_ref_id, revision_source)

    @property
    def level(self) -> int:
        return 0

    def step_tags(self) -> frozenset[str]:
        return frozenset({"read", "fts", "prereq", "query"})

    def is_read_only(self) -> bool:
        return True

    def result_cardinality(self) -> Cardinality:
        return Cardinality.MANY

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def publishes_replayable_statement_local_relation(self) -> bool:
        return True

    def tables_read(self) -> frozenset[str]:
        return _versioned_storage_tables(self._model_cls) if issubclass(self._model_cls, VersionedObjectRow) else frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def dependencies(self) -> frozenset[str]:
        deps: set[str] = set(_collect_spec_deps(self._query_spec))
        if self._branch_ref_id is not None:
            deps.add(str(self._branch_ref_id))
        deps.update(str(ref_id) for ref_id in self._extra_dependency_ref_ids)
        return frozenset(deps)

    def compile(self, ctx: CompilationContext) -> CompiledStep[object]:
        if self._revision_source is not None:
            ctx = replace(ctx, lazy_revision=self._revision_source)
        if issubclass(self._model_cls, VersionedObjectRow):
            from impl.common.l2070_server_plan.steps._compile_policy_read import compile_symbolic_policy_read

            dispatched = compile_symbolic_policy_read(ctx, self.compile)
            if dispatched is not None:
                return dispatched
            return _build_versioned_fts_scores_prereq_select(
                model_cls=self._model_cls,
                spec=self._query_spec,
                ctx=ctx,
                branch_id=None if self._branch_id is None else str(self._branch_id),
                branch_ref_id=self._branch_ref_id,
                user_id_ref_id=self._user_id_ref_id,
            )
        return _build_unversioned_fts_scores_prereq_select(
            model_cls=self._model_cls,
            spec=_authorized_search_spec(self._query_spec, self._model_cls, ctx, self._user_id_ref_id),
            ctx=ctx,
        )

    def relation_output_columns(self) -> tuple[str, ...]:
        if issubclass(self._model_cls, VersionedObjectRow):
            return ("object_id", "branch_id", "rank")
        return ("object_id", "rank")

    def cte_publication_contract(self: _SingleBranchFtsScoresPrereqStep) -> CtePublicationContract:
        columns = self.relation_output_columns()
        column_type_hints = _score_prereq_type_hints(self.relation_output_columns())
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        if issubclass(self._model_cls, VersionedObjectRow):
            relation_contract = CteRelationContract.semantic_row(_VersionedFtsScorePrereqRow)
        else:
            relation_contract = CteRelationContract.semantic_row(_FtsScorePrereqRow)
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=tuple(str(column) for column in columns),
            column_type_hints=column_type_hints,
            relation_contract=relation_contract,
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )


