def _build_unversioned_fts_sql_components_from_score_cte(
    *,
    score_cte_ref_id: str,
    table_alias: str,
) -> SqlFTSComponents:
    """Join a published FTS score CTE (``object_id``, ``rank``) onto the base row alias."""
    from impl.common.l2100_sql_grammar.domain.versioning.cross_branch import sql_aliased_column

    scores_alias = SqlAliasName("fs")
    table_alias_name = SqlAliasName(table_alias)
    return SqlFTSComponents(
        join_clause=SqlTableAlias(
            SqlTableIdent(SqlTableName(score_cte_ref_id)),
            alias=scores_alias,
        ),
        where_clause=SqlBinaryOp(
            SqlColumnRef(SqlColumnName("sys_id"), qualifier=table_alias_name),
            BinaryOp.EQ,
            SqlColumnRef(SqlColumnName("object_id"), qualifier=scores_alias),
        ),
        rank_expression=sql_aliased_column(
            scores_alias,
            SqlColumnName("rank"),
        ),
        join_style=SqlFTSJoinStyle.JOIN_ON_CONDITION,
        rank_alias="__fts_rank",
    )


def _resolve_hybrid_fts_for_compile(
    *,
    spec: QuerySpec,
    model_cls: type[DatabaseObjectRow],
    ctx: CompilationContext,
    versioned: bool,
    fts_scores_cte_ref: str | None,
) -> SqlFTSComponents:
    """Resolve FTS SQL components from explicit prerequisites only."""
    precomputed = spec.search_op.precomputed_fts_components
    if precomputed is not None:
        return _require_precomputed_fts_components(precomputed)
    if fts_scores_cte_ref is not None:
        if versioned:
            from impl.common.l2070_server_plan.steps.cross_branch import (
                _build_versioned_fts_sql_components_from_score_cte,
            )

            return _build_versioned_fts_sql_components_from_score_cte(
                score_cte_ref_id=fts_scores_cte_ref,
                table_alias="t",
            )
        return _build_unversioned_fts_sql_components_from_score_cte(
            score_cte_ref_id=fts_scores_cte_ref,
            table_alias="t",
        )
    del model_cls, ctx
    raise_missing_cte_fallback_forbidden(
        site_name="_resolve_hybrid_fts_for_compile",
        trigger=(
            "versioned hybrid compile reached FTS lowering without precomputed_fts_components or a published fts_ref_id CTE prerequisite"
        ),
        blocked_path="compile-time reconstruction of hybrid FTS sources from runtime state",
        result_contract=(
            "hybrid FTS compilation must consume either precomputed SqlFTSComponents or a published SQL-visible FTS score relation"
        ),
        implementation_requirements=(
            "Publish the FTS prerequisite as an explicit CTE-backed score step before hybrid compile.",
            "Or attach precomputed_fts_components directly to the QuerySpec at planning time.",
            "Do not recover by inspecting runtime values or reopening immediate execution authority.",
        ),
    )
    raise AssertionError("unreachable")


def _resolve_hybrid_vector_for_compile(
    *,
    spec: QuerySpec,
    model_cls: type[DatabaseObjectRow],
    ctx: CompilationContext,
    table_alias: str,
    include_chunks: bool,
    branch_id: BranchId | SqlRenderable | None,
    vector_scores_cte_ref: str | None,
) -> SqlVectorSearchComponents:
    """Resolve vector SQL components from explicit prerequisites only."""
    from impl.common.l2070_server_plan.backend_profiles import (
        query_spec_prefers_sql_table_hnsw_components,
    )
    from impl.common.l2100_sql_grammar.domain.sql_table_hnsw import (
        build_sql_table_hnsw_score_components,
    )

    if vector_scores_cte_ref is not None:
        return cast(
            SqlVectorSearchComponents,
            build_sql_components_from_score_cte(
                score_cte_ref_id=vector_scores_cte_ref,
                table_alias=table_alias,
                include_chunks=include_chunks,
            ),
        )
    if query_spec_prefers_sql_table_hnsw_components(
        model_cls=model_cls,
        query_spec=spec,
        backend_type=ctx.backend_type,
    ):
        _require_hybrid_vector_inputs(spec, site="Hybrid vector compilation")
        assert spec.search_op.vector_index_name is not None
        projected_hamming = sql_table_hnsw_projected_hamming_query(
            model_cls=model_cls,
            index_name=SqlIndexName(spec.search_op.vector_index_name),
            spec=spec,
        )
        if projected_hamming is None:
            assert spec.search_op.vector_query_vec is not None
            validate_query_vector_dimensions(model_cls, spec.search_op.vector_index_name, spec.search_op.vector_query_vec)
            query_vector = _require_hybrid_query_vector(spec, site="Hybrid vector compilation")
        else:
            query_vector = (0.0,)
        resolved_branch_scope: str | SqlRenderable | None = None
        revision_id = ctx.revision_id
        if revision_id is None:
            if isinstance(branch_id, BranchId):
                resolved_branch_scope = branch_id.unwrap_to_str()
            elif branch_id is not None:
                resolved_branch_scope = branch_id
        from l5200_vector_index.index_resolution import VectorBackendKind, resolve_vector_keying_mode
        from l5200_vector_index.vector_config import get_vector_config

        vector_config = _require_hybrid_vector_config(
            get_vector_config(model_cls, spec.search_op.vector_index_name),
            index_name=spec.search_op.vector_index_name,
            model_cls=model_cls,
        )
        from impl.common.l2070_server_plan.hnsw_content_stores import hnsw_embedding_tables

        vector_tables, ref_tables = hnsw_embedding_tables(
            SqlTableName(vector_source_table_name(model_cls)),
            SqlIndexName(spec.search_op.vector_index_name),
            vector_config,
            catalog=ctx.planning_catalog,
        )
        return cast(
            SqlVectorSearchComponents,
            build_sql_table_hnsw_score_components(
                embedding_vector_tables=vector_tables,
                embedding_ref_tables=ref_tables,
                metric=vector_config.metric,
                source_table_name=vector_source_table_name(model_cls),
                field_name=spec.search_op.vector_index_name,
                query_vector=query_vector,
                k=compute_vector_search_k(
                    spec,
                    use_rrf_candidates=bool(spec.search_op.rrf_enabled),
                ),
                ef_search=spec.search_op.vector_ef_search,
                threshold=spec.search_op.vector_threshold,
                include_chunks=include_chunks,
                table_alias=table_alias,
                branch_id=resolved_branch_scope,
                revision_id=revision_id,
                keying_mode=resolve_vector_keying_mode(vector_config, VectorBackendKind.SQL_TABLE_HNSW),
                query_binary=(None if projected_hamming is None else projected_hamming.query_binary),
                binary_dimensions=(None if projected_hamming is None else projected_hamming.binary_dimensions),
            ),
        )
    del spec, model_cls, ctx, table_alias, include_chunks, branch_id
    raise_missing_cte_fallback_forbidden(
        site_name="_resolve_hybrid_vector_for_compile",
        trigger=("versioned hybrid compile reached vector lowering without a published vector_ref_id score CTE"),
        blocked_path="compile-time reconstruction of hybrid vector scores from runtime state",
        result_contract=("hybrid vector compilation must consume a published SQL-visible vector score relation"),
        implementation_requirements=(
            "Publish the vector prerequisite as an explicit CTE-backed score step before hybrid compile.",
            "Do not recover by resolving runtime values or branching on ServerRef materialization state.",
        ),
    )
    raise AssertionError("unreachable")


def _rrf_final_limit(spec: QuerySpec) -> int:
    if spec.limit is not None:
        return int(spec.limit)
    candidate_limits = [
        value
        for value in (
            spec.search_op.rrf_fts_candidates,
            spec.search_op.rrf_vector_candidates,
        )
        if value is not None
    ]
    if candidate_limits:
        return int(max(candidate_limits))
    return 100


def _has_search_cursor(spec: QuerySpec) -> bool:
    return getattr(spec, "cursor_after", None) is not None or getattr(spec, "cursor_before", None) is not None


def _compile_versioned_hybrid_sql(
    *,
    model_cls: type[DatabaseObjectRow],
    spec: QuerySpec,
    ctx: CompilationContext,
    branch_id: BranchId | SqlRenderable | None,
    step_name: str,
    branch_source_ref_id: ServerPlanRefId | None = None,
    fts_ref_id: ServerPlanRefId | None,
    vector_ref_id: ServerPlanRefId | None,
) -> CompiledStep[Any]:
    dialect = _require_hybrid_sql_dialect(ctx, step_name)
    from impl.common.l2070_server_plan.steps._compile_helpers import _build_query_provenance_manifest
    from impl.common.l2070_server_plan.steps.versioning_intent_steps import (
        _collect_dependency_auxiliary_ctes,
    )

    fts_cte = resolve_cte_ref_id(
        str(fts_ref_id) if fts_ref_id is not None else None,
        ctx.cte_refs,
    )
    vec_cte = resolve_cte_ref_id(
        str(vector_ref_id) if vector_ref_id is not None else None,
        ctx.cte_refs,
    )
    from l7000_versioned_schema.read_source_policy import is_current_branch_read, persisted_tip_materialization
    from l7000_versioned_schema.versioned_schema import BranchTipMaterialization

    use_tip_content = is_current_branch_read(ctx) and persisted_tip_materialization(ctx) is not BranchTipMaterialization.TIPLESS
    content_model: type[DatabaseObjectRow]
    if use_tip_content:
        from impl.common.l7245_versioned_backends.generic_sparse import GenericSparseVersionedBackend

        backend: GenericSparseVersionedBackend = GenericSparseVersionedBackend()
        backend.configure_for_backend_type(ctx.backend_type)
        content_model = backend._get_or_create_tip_model(model_cls)
    else:
        content_model = _planner_sparse_model(model_cls, ctx)
    include_chunks = query_spec_requests_vector_chunks(spec)
    fts_components = _resolve_hybrid_fts_for_compile(
        spec=spec,
        model_cls=model_cls,
        ctx=ctx,
        versioned=True,
        fts_scores_cte_ref=fts_cte,
    )
    inlined_fts_cte_name: str | None = None
    if (
        ctx.backend_profile.traits.fts_sql_transport is FtsSqlTransport.MATCH_AGAINST
        and fts_ref_id is not None
        and ctx.cte_refs is not None
    ):
        fts_binding = ctx.cte_refs.get(str(fts_ref_id))
        if fts_binding is not None and fts_binding.auxiliary_query is not None:
            inlined_fts_cte_name = fts_binding.ref_id
            fts_components = replace(
                fts_components,
                join_clause=SqlSubqueryTableRef(
                    fts_binding.auxiliary_query,
                    SqlTableName("fs"),
                ),
            )
    branch_cte_refs: frozenset[str] = (
        branch_id.statement_local_cte_refs() if isinstance(branch_id, DeclaresStatementLocalCteRefs) else frozenset()
    )
    branch_auxiliary_ctes = _collect_dependency_auxiliary_ctes(
        ctx,
        *(str(ref_id) for ref_id in (branch_source_ref_id,) if ref_id is not None),
        *branch_cte_refs,
    )
    vector_components = _resolve_hybrid_vector_for_compile(
        spec=spec,
        model_cls=model_cls,
        ctx=ctx,
        table_alias="t",
        include_chunks=include_chunks,
        branch_id=branch_id,
        vector_scores_cte_ref=vec_cte,
    )
    if branch_auxiliary_ctes and vec_cte is None:
        join_clause = _require_hybrid_vector_join_clause(
            vector_components,
            site="versioned hybrid branch CTE placement",
        )
        scoped_join_clause = _attach_required_statement_local_ctes(
            join_clause,
            branch_auxiliary_ctes,
        )
        vector_components = SqlVectorSearchComponents(
            join_clause=scoped_join_clause,
            where_clause=vector_components.where_clause,
            score_expression=vector_components.score_expression,
            score_alias=vector_components.score_alias,
            result_id_expression=vector_components.result_id_expression,
            distance_expression=vector_components.distance_expression,
            distance_kind_expression=vector_components.distance_kind_expression,
            chunk_id_expression=vector_components.chunk_id_expression,
            chunk_metadata_expression=vector_components.chunk_metadata_expression,
        )
    revision_id = _require_hybrid_revision_id(
        ctx,
        step_name,
        branch_id=branch_id,
        branch_source_ref_id=branch_source_ref_id,
    )
    build = _build_versioned_rrf_grammar_from_components(
        model_cls=model_cls,
        row_model=content_model,
        data_table=get_table_name(content_model),
        use_tip_content=use_tip_content,
        spec=spec,
        dialect=dialect,
        revision_id=revision_id,
        ctx=ctx,
        branch_id=branch_id,
        fts_components=fts_components,
        vector_components=vector_components,
    )
    final_limit = _rrf_final_limit(spec)
    hybrid_grammar = build.grammar
    nested_definitions: Sequence[SqlCteDefinitionInput] = []
    if isinstance(hybrid_grammar, SqlOuterCteSplitProtocol):
        nested_definitions, hybrid_grammar = hybrid_grammar.split_for_outer_cte()
    __opa002_grammar_1230 = wrap_search_cursor_page(
        hybrid_grammar,
        spec,
        score_column="__rrf_score",
        source_alias="hybrid_page",
        model_cls=model_cls,
        limit=final_limit,
    )
    columns = _result_row_output_columns(
        model_cls,
        include_fts_rank=bool(spec.search_op.fts_query),
        include_vector_score=bool(spec.search_op.vector_index_name),
        include_rrf_meta=bool(spec.search_op.rrf_enabled),
    )
    result_alias = SqlAliasName("hybrid_result_projected")
    projected_query = SqlSelect(
        [SqlColumnRef(SqlColumnName(column), qualifier=result_alias) for column in columns],
        SqlSubqueryTableRef(
            __opa002_grammar_1230,
            SqlTableName(result_alias),
        ),
        order_by=[
            SqlOrderByItem(
                SqlColumnRef(
                    SqlColumnName("__rrf_score"),
                    qualifier=result_alias,
                ),
                OrderDirection.DESC,
            ),
            SqlOrderByItem(
                SqlColumnRef(
                    SqlColumnName("sys_id"),
                    qualifier=result_alias,
                ),
                OrderDirection.ASC,
            ),
        ],
    )
    projected_grammar: SqlRenderable = projected_query
    output_shape, result_relation, column_type_hints = _hybrid_result_output_contract(model_cls, columns)
    auxiliary_ctes = merge_auxiliary_ctes(
        branch_auxiliary_ctes,
        _collect_visible_auxiliary_ctes(ctx),
        _collect_dependency_auxiliary_ctes(
            ctx,
            *(str(ref_id) for ref_id in (branch_source_ref_id, fts_ref_id, vector_ref_id) if ref_id is not None),
        ),
        nested_definitions,
    )
    if inlined_fts_cte_name is not None and auxiliary_ctes is not None:
        auxiliary_ctes = [definition for definition in auxiliary_ctes if auxiliary_cte_name(definition) != inlined_fts_cte_name] or None
    return CompiledStep(
        output_shape=output_shape,
        grammar=projected_grammar,
        result_relation=result_relation,
        column_type_hints=column_type_hints,
        params=build.params,
        needs_returning=True,
        external_params_first=build.external_params_first,
        provenance_manifest=_build_query_provenance_manifest(
            spec,
            model_cls,
            ctx,
            is_count=False,
        ),
        use_savepoint_recovery=build.use_savepoint_recovery,
        auxiliary_ctes=auxiliary_ctes,
        closed_post_op=row_dicts_post_op(),
    )


def _compile_unversioned_hybrid_sql(
    *,
    model_cls: type[DatabaseObjectRow],
    spec: QuerySpec,
    ctx: CompilationContext,
    step_name: str,
    fts_ref_id: ServerPlanRefId | None,
    vector_ref_id: ServerPlanRefId | None,
    permission_user_ref_id: ServerPlanRefId | None = None,
) -> CompiledStep[Any]:
    dialect = _require_hybrid_sql_dialect(ctx, step_name)
    from impl.common.l2070_server_plan.search_prereq_utils import query_spec_requests_vector_chunks
    from impl.common.l2070_server_plan.steps._compile_helpers import (
        _build_query_provenance_manifest,
        attach_runtime_permission_grammar,
    )
    from impl.common.l2070_server_plan.steps.versioning_intent_steps import (
        _collect_dependency_auxiliary_ctes,
    )
    from impl.common.l2070_server_plan.steps.sql_projection import (
        _require_sql_visible_source_cte,
    )

    permission_user_source = (
        None
        if permission_user_ref_id is None
        else _require_sql_visible_source_cte(
            ctx,
            permission_user_ref_id,
            site_name=step_name,
            result_contract="compile hybrid-search permission authority",
        )
    )
    effective_spec = cast(
        "QuerySpec",
        attach_runtime_permission_grammar(
            spec,
            model_cls,
            ctx,
            resolved_user_id=permission_user_source,
            action="read",
            permission_table_alias="t",
        ),
    )

    fts_cte = resolve_cte_ref_id(
        str(fts_ref_id) if fts_ref_id is not None else None,
        ctx.cte_refs,
    )
    vec_cte = resolve_cte_ref_id(
        str(vector_ref_id) if vector_ref_id is not None else None,
        ctx.cte_refs,
    )
    include_chunks = query_spec_requests_vector_chunks(spec)
    fts_components = _resolve_hybrid_fts_for_compile(
        spec=effective_spec,
        model_cls=model_cls,
        ctx=ctx,
        versioned=False,
        fts_scores_cte_ref=fts_cte,
    )
    inlined_fts_cte_name: str | None = None
    if (
        ctx.backend_profile.traits.fts_sql_transport is FtsSqlTransport.MATCH_AGAINST
        and fts_ref_id is not None
        and ctx.cte_refs is not None
    ):
        fts_binding = ctx.cte_refs.get(str(fts_ref_id))
        if fts_binding is not None and fts_binding.auxiliary_query is not None:
            inlined_fts_cte_name = fts_binding.ref_id
            fts_components = replace(
                fts_components,
                join_clause=SqlSubqueryTableRef(
                    fts_binding.auxiliary_query,
                    SqlTableName("fs"),
                ),
            )
    vector_components = _resolve_hybrid_vector_for_compile(
        spec=effective_spec,
        model_cls=model_cls,
        ctx=ctx,
        table_alias="t",
        include_chunks=include_chunks,
        branch_id=None,
        vector_scores_cte_ref=vec_cte,
    )
    grammar = _build_unversioned_rrf_grammar_from_components(
        model_cls=model_cls,
        spec=effective_spec,
        dialect=dialect,
        fts_components=fts_components,
        vector_components=vector_components,
        planning_catalog=ctx.planning_catalog,
    )
    nested_definitions: Sequence[SqlCteDefinitionInput] = []
    if isinstance(grammar, SqlOuterCteSplitProtocol):
        nested_definitions, grammar = grammar.split_for_outer_cte()
    final_limit = _rrf_final_limit(spec)
    __opa002_grammar_1302 = wrap_search_cursor_page(
        grammar,
        spec,
        score_column="__rrf_score",
        source_alias="hybrid_page",
        model_cls=model_cls,
        limit=final_limit,
    )
    columns = _result_row_output_columns(
        model_cls,
        include_fts_rank=bool(spec.search_op.fts_query),
        include_vector_score=bool(spec.search_op.vector_index_name),
        include_rrf_meta=bool(spec.search_op.rrf_enabled),
    )
    result_alias = SqlAliasName("hybrid_result_projected")
    projected_grammar = SqlSelect(
        [SqlColumnRef(SqlColumnName(column), qualifier=result_alias) for column in columns],
        SqlSubqueryTableRef(
            __opa002_grammar_1302,
            SqlTableName(result_alias),
        ),
        order_by=[
            SqlOrderByItem(
                SqlColumnRef(
                    SqlColumnName("__rrf_score"),
                    qualifier=result_alias,
                ),
                OrderDirection.DESC,
            ),
            SqlOrderByItem(
                SqlColumnRef(
                    SqlColumnName("sys_id"),
                    qualifier=result_alias,
                ),
                OrderDirection.ASC,
            ),
        ],
    )
    output_shape, result_relation, column_type_hints = _hybrid_result_output_contract(model_cls, columns)
    from impl.common.l2070_server_plan.steps.query_execute import (
        _permission_context_ref_auxiliary_ctes,
    )

    permission_context_auxiliary_ctes = (
        ()
        if effective_spec.permission_context_ref is None
        else _permission_context_ref_auxiliary_ctes(
            effective_spec.permission_context_ref,
            ctx,
        )
    )
    auxiliary_ctes = merge_auxiliary_ctes(
        nested_definitions,
        _collect_visible_auxiliary_ctes(ctx),
        permission_context_auxiliary_ctes,
        _collect_dependency_auxiliary_ctes(
            ctx,
            *(str(ref_id) for ref_id in (fts_ref_id, vector_ref_id, permission_user_ref_id) if ref_id is not None),
        ),
    )
    if inlined_fts_cte_name is not None and auxiliary_ctes is not None:
        auxiliary_ctes = [definition for definition in auxiliary_ctes if auxiliary_cte_name(definition) != inlined_fts_cte_name] or None
    return CompiledStep(
        output_shape=output_shape,
        grammar=projected_grammar,
        params=(),
        result_relation=result_relation,
        column_type_hints=column_type_hints,
        needs_returning=True,
        external_params_first=False,
        provenance_manifest=_build_query_provenance_manifest(
            spec,
            model_cls,
            ctx,
            is_count=False,
        ),
        use_savepoint_recovery=False,
        auxiliary_ctes=auxiliary_ctes,
        closed_post_op=row_dicts_post_op(),
    )


class VersionedHybridSearchStep[T](ConsumedRowsReducerMixin, SqlRelationPublisherStep[object]):
    """L0: Versioned RRF hybrid search compiled directly to SQL."""

    def __init__(
        self: VersionedHybridSearchStep,
        ref_id: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        query_spec: QuerySpec,
        *,
        revision_source: ScalarServerRef[RevisionId] | None = None,
        branch_id: BranchId | None = None,
        branch_ref_id: ServerPlanRefId | None = None,
        validation_ref_id: ServerPlanRefId | None = None,
        fts_ref_id: ServerPlanRefId | None = None,
        vector_ref_id: ServerPlanRefId | None = None,
    ) -> None:
        super().__init__(ref_id)
        self._model_cls = model_cls
        self._query_spec = query_spec
        self._branch_id = branch_id
        self._branch_ref_id = branch_ref_id
        self._validation_ref_id = validation_ref_id
        self._fts_ref_id = fts_ref_id
        self._vector_ref_id = vector_ref_id
        self._revision_source = revision_source

    @property
    def level(self: VersionedHybridSearchStep) -> int:
        return 0

    def step_tags(self: VersionedHybridSearchStep) -> frozenset[str]:
        return frozenset({"read", "query", "execute", "versioned", "hybrid", "rrf"})

    def is_read_only(self: VersionedHybridSearchStep) -> bool:
        return True

    def requires_runtime_sequential_batch(self: VersionedHybridSearchStep) -> bool:
        return False

    def result_cardinality(self: VersionedHybridSearchStep) -> Cardinality:
        return Cardinality.ONE

    def json_aggregation_order_by(
        self: VersionedHybridSearchStep,
    ) -> tuple[tuple[str, str], ...]:
        return (("__rrf_score", "DESC"), ("sys_id", "ASC"))

    def tables_read(self: VersionedHybridSearchStep) -> frozenset[str]:
        tables: frozenset[str] = _versioned_storage_tables(self._model_cls)
        return tables

    def tables_written(self: VersionedHybridSearchStep) -> frozenset[str]:
        return frozenset()

    def dependencies(self: VersionedHybridSearchStep) -> frozenset[str]:
        deps: set[str] = set()
        if self._revision_source is not None:
            deps.update(self._revision_source.dependencies())
        if self._branch_ref_id is not None:
            deps.add(str(self._branch_ref_id))
        if self._validation_ref_id is not None:
            deps.add(str(self._validation_ref_id))
        if self._fts_ref_id is not None:
            deps.add(str(self._fts_ref_id))
        if self._vector_ref_id is not None:
            deps.add(str(self._vector_ref_id))
        deps.update(_collect_spec_deps(self._query_spec))
        return frozenset(deps)

    def sql_visible_dependencies(self: VersionedHybridSearchStep) -> frozenset[str]:
        embedded_prerequisites = {
            str(ref_id)
            for ref_id in (
                self._branch_ref_id,
                self._validation_ref_id,
                self._fts_ref_id,
                self._vector_ref_id,
            )
            if ref_id is not None
        }
        return self.dependencies() - embedded_prerequisites

    def compile(
        self: VersionedHybridSearchStep,
        ctx: CompilationContext,
    ) -> CompiledStep[object]:
        if self._revision_source is not None:
            ctx = replace(ctx, lazy_revision=self._revision_source)
        from impl.common.l2070_server_plan.steps._compile_policy_read import compile_symbolic_policy_read

        dispatched = compile_symbolic_policy_read(ctx, self.compile)
        if dispatched is not None:
            return dispatched
        resolved_branch_id, branch_cte_ref = (
            (str(self._branch_id), None) if self._branch_id is not None else _compile_branch_inputs(ctx, self._branch_ref_id)
        )
        effective_branch = _effective_branch_id(
            ctx,
            resolved_branch_id,
            branch_cte_ref,
            branch_ref_id=self._branch_ref_id,
        )
        return _compile_versioned_hybrid_sql(
            model_cls=self._model_cls,
            spec=self._query_spec,
            ctx=ctx,
            branch_id=effective_branch,
            step_name=type(self).__name__,
            branch_source_ref_id=self._branch_ref_id,
            fts_ref_id=self._fts_ref_id,
            vector_ref_id=self._vector_ref_id,
        )

    def relation_output_columns(self) -> tuple[str, ...]:
        return _result_row_output_columns(
            self._model_cls,
            include_fts_rank=bool(self._query_spec.search_op.fts_query),
            include_vector_score=bool(self._query_spec.search_op.vector_index_name),
            include_rrf_meta=bool(self._query_spec.search_op.rrf_enabled),
        )

    def cte_publication_contract(self: VersionedHybridSearchStep) -> CtePublicationContract:
        columns = self.relation_output_columns()
        column_type_hints = _hybrid_result_type_hints(self._model_cls, self.relation_output_columns())
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=tuple(str(column) for column in columns),
            column_type_hints=column_type_hints,
            relation_contract=CteRelationContract.projection_over_model(
                source_model_cls=self._model_cls,
                projection_lineage=_hybrid_result_projection_lineage(columns),
            ),
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )


def _build_versioned_rrf_grammar_from_components(
    *,
    model_cls: type[DatabaseObjectRow],
    row_model: type[DatabaseObjectRow],
    data_table: str,
    spec: QuerySpec,
    dialect: SqlDialect,
    revision_id: str | SqlRenderable | None,
    use_tip_content: bool = False,
    ctx: CompilationContext,
    branch_id: BranchId | SqlRenderable | None,
    fts_components: SqlFTSComponents,
    vector_components: SqlVectorSearchComponents,
) -> _VersionedHybridGrammarBuild:
    """Assemble versioned hybrid grammar from already-fetched components."""
    from impl.common.l2070_server_plan.steps.versioned_hybrid_source import visible_hybrid_source
    from impl.common.l5350_hybrid_search import HybridSearchBuilder, RRFCTEConfig

    del data_table

    candidate_where_conditions: list[SqlRenderable] = []
    rrf_config = RRFCTEConfig(
        k=spec.search_op.rrf_k,
        fts_weight=spec.search_op.rrf_fts_weight,
        vector_weight=spec.search_op.rrf_vector_weight,
        fts_candidates=spec.search_op.rrf_fts_candidates,
        vector_candidates=spec.search_op.rrf_vector_candidates,
        final_limit=_rrf_final_limit(spec),
    )

    assert revision_id is not None, "RRF hybrid search requires revision_id"
    source_definitions = visible_hybrid_source(
        model_cls,
        spec,
        ctx,
        revision=revision_id,
        branch=SqlParam(branch_id) if isinstance(branch_id, BranchId) else branch_id,
        name="hybrid_visible_rows",
    )
    builder = HybridSearchBuilder(
        dialect=dialect,
        data_table="hybrid_visible_rows",
        id_column="sys_id",
        fts_components=fts_components,
        vector_components=vector_components,
        rrf_config=rrf_config,
        branch_id_column="branch_id",
        branch_table=None,
        base_where_conditions=candidate_where_conditions,
        final_offset=None if _has_search_cursor(spec) else spec.offset if spec.offset and spec.offset > 0 else None,
    )
    from l1000_schema.physical_adjuncts import (
        is_framework_physical_adjunct_column,
        is_framework_physical_adjunct_field,
    )

    columns: list[SqlRenderable] = []
    for field_name in row_model.model_fields:
        if is_framework_physical_adjunct_field(
            row_model,
            DynamicFieldName(field_name),
        ):
            continue
        db_col = get_db_column_name(row_model, DynamicFieldName(field_name))
        if is_framework_physical_adjunct_column(SqlColumnName(db_col)):
            continue
        columns.append(SqlColumnRef(SqlColumnName(db_col), qualifier=SqlAliasName("t")))
    if use_tip_content:
        from impl.common.l2100_sql_grammar.tree.clauses import SqlSelectAlias

        columns.append(SqlSelectAlias(SqlParam(False), SqlAliasName("sys_deleted")))

    grammar = builder.build_complete_grammar(
        columns=columns,
        additional_where=None,
        include_branch_metadata=False,
    )
    if isinstance(grammar, SqlCte):
        definitions, grammar = grammar.split_for_outer_cte()
        source_definitions.extend(definitions)
    return _VersionedHybridGrammarBuild(
        grammar=SqlCte(source_definitions, grammar),
        row_model=row_model,
        params=(),
        external_params_first=False,
        use_savepoint_recovery=False,
    )


