def _build_unversioned_rrf_grammar_from_components(
    *,
    model_cls: type[DatabaseObjectRow],
    spec: QuerySpec,
    dialect: SqlDialect,
    fts_components: SqlFTSComponents,
    vector_components: SqlVectorSearchComponents,
    planning_catalog: PlanningCatalog | None,
) -> SqlRenderable:
    """Assemble unversioned hybrid grammar from already-fetched components."""
    from impl.common.l5350_hybrid_search import HybridSearchBuilder, RRFCTEConfig

    table_name = get_table_name(model_cls)
    rrf_config = RRFCTEConfig(
        k=spec.search_op.rrf_k,
        fts_weight=spec.search_op.rrf_fts_weight,
        vector_weight=spec.search_op.rrf_vector_weight,
        fts_candidates=spec.search_op.rrf_fts_candidates,
        vector_candidates=spec.search_op.rrf_vector_candidates,
        final_limit=_rrf_final_limit(spec),
    )

    base_where_conditions: list[SqlRenderable] = []
    if spec.filters or spec.permission_grammar is not None:
        from impl.common.l5200_sql_query.query_grammar import QueryGrammarBuilder

        grammar_builder = QueryGrammarBuilder(
            spec,
            table_alias="t",
            planning_catalog=planning_catalog,
        )
        where_clause = grammar_builder.build_where_clause()
        if where_clause is not None:
            from impl.common.l2070_server_plan.steps._compile_versioned import _rewrite_permission_qualifiers

            base_where_conditions.append(
                _rewrite_permission_qualifiers(
                    where_clause.condition,
                    from_qualifier=str(table_name),
                    to_qualifier="t",
                )
            )

    builder = HybridSearchBuilder(
        dialect=dialect,
        data_table=table_name,
        id_column="sys_id",
        fts_components=fts_components,
        vector_components=vector_components,
        rrf_config=rrf_config,
        branch_id_column=None,
        branch_table=None,
        base_where_conditions=base_where_conditions,
        final_offset=None if _has_search_cursor(spec) else spec.offset if spec.offset and spec.offset > 0 else None,
    )

    columns: list[SqlColumnRef] = []
    for field_name in model_cls.model_fields:
        db_col = str(get_db_column_name(model_cls, DynamicFieldName(field_name)))
        columns.append(SqlColumnRef(SqlColumnName(db_col), qualifier=SqlAliasName("t")))

    grammar: SqlRenderable = builder.build_complete_grammar(
        columns=columns,
        additional_where=None,
        include_branch_metadata=False,
    )
    return grammar

