def _normalize_scalar_ref[T](value: T | ScalarServerRef[T]) -> ScalarServerRef[T]:
    if isinstance(value, ScalarServerRef):
        return value
    return ServerRefs.scalar(value)


def _combine_auxiliary_ctes(
    *groups: Sequence[SqlCteDefinitionInput] | None,
) -> list[SqlCteDefinitionInput] | None:
    combined: list[SqlCteDefinitionInput] = []
    for group in groups:
        if group is not None:
            combined.extend(group)
    return combined or None


def _ctx_uses_tipless_branch(ctx: CompilationContext) -> bool:
    return not ctx.branch_tip_materialized


def _versioned_select_one_relation_contract(
    model_cls: type[DatabaseObjectRow],
    columns: tuple[str, ...],
) -> CteRelationContract:
    """Lineage for versioned select-one rows over a concrete model."""
    return CteRelationContract.projection_over_model(
        source_model_cls=model_cls,
        projection_lineage=tuple((column, column if not column.startswith("sys_") else f"versioning:{column}") for column in columns),
    )


def _multitable_source_db_columns(model_cls: type[DatabaseObjectRow]) -> tuple[str, ...]:
    return tuple(
        dict.fromkeys(
            get_db_column_name(source_model, DynamicFieldName(field_name))
            for source_model in get_multitable_polymorphic_source_models_for_model(model_cls)
            for field_name in source_model.model_fields
        ),
    )


def _multitable_source_type_hints(
    model_cls: type[DatabaseObjectRow],
    columns: tuple[str, ...],
) -> tuple[SqlColumnTypeHints, ...]:
    return tuple(
        hints
        for source_model in get_multitable_polymorphic_source_models_for_model(model_cls)
        if (hints := model_sql_column_type_hints(source_model, columns)) is not None
    )


def _select_one_output_shape(
    ctx: CompilationContext,
    model_cls: type[DatabaseObjectRow],
    *,
    declared_outputs: tuple[str, ...] | list[str] | None = None,
) -> CompiledOutputShape:
    from l2070_batching.output_shape import synthetic_output_field

    projection = (
        require_planning_catalog(
            ctx,
            site="versioned_select_one.output_shape",
        )
        .read_metadata_for_model(model_cls)
        .projection_for(READ_FLAVOR_HYDRATED_SELECT_ONE)
    )
    shape = output_shape_from_read_projection(
        projection,
        declared_outputs=tuple(declared_outputs) if declared_outputs is not None else None,
    )
    if declared_outputs is None:
        return shape
    declared = tuple(str(output) for output in declared_outputs)
    declared_columns = set(shape.cte_output_columns)
    missing_fields = tuple(synthetic_output_field(output) for output in declared if output not in declared_columns)
    if not missing_fields:
        return shape
    return shape.with_fields(missing_fields)


def _output_shape_with_missing_synthetic_columns(
    output_shape: CompiledOutputShape,
    columns: Sequence[str],
) -> CompiledOutputShape:
    missing_columns = tuple(column for column in columns if column not in output_shape.cte_output_columns)
    if not missing_columns:
        return output_shape
    return output_shape_with_synthetic_fields(
        output_shape,
        tuple(synthetic_output_field(column) for column in missing_columns),
    )


def _output_shape_reordered_to_columns(
    output_shape: CompiledOutputShape,
    columns: Sequence[str],
) -> CompiledOutputShape:
    fields_by_column = {field.output_column: field for field in output_shape.fields}
    ordered_fields = tuple(fields_by_column[column] for column in columns if column in fields_by_column)
    if len(ordered_fields) != len(output_shape.fields):
        return output_shape
    return CompiledOutputShape(ordered_fields)


