@dataclass(frozen=True, slots=True)
class _VersionedSelectOnePermissionAnalysis:
    scheme: object | None
    column_masking: tuple[str, list[str]] | None
    needs_permission_user_ref: bool


def analyze_versioned_select_one_permissions(
    model_cls: type[DatabaseObjectRow],
    session_id: PlanningSessionId | None,
    *,
    catalog_models: Collection[type[DatabaseObjectRow]] | None = None,
    permission_bypass: bool = False,
) -> _VersionedSelectOnePermissionAnalysis:
    """Summarize whether versioned select_one needs a published permission-user ref."""
    if permission_bypass or session_id is None:
        return _VersionedSelectOnePermissionAnalysis(
            scheme=None,
            column_masking=None,
            needs_permission_user_ref=False,
        )

    from impl.common.l2070_server_plan.steps._permission_filter import get_column_masking_info
    from l4000_permissions.permission_enforcement import (
        _try_get_permission_scheme,
        get_query_permission_plan,
    )

    scheme = _try_get_permission_scheme(model_cls)
    if not isinstance(session_id, SessionId):
        return _VersionedSelectOnePermissionAnalysis(
            scheme=scheme,
            column_masking=None,
            needs_permission_user_ref=scheme is not None,
        )
    if catalog_models is None:
        column_masking = get_column_masking_info(model_cls, session_id)
    else:
        column_masking = get_column_masking_info(
            model_cls,
            session_id,
            catalog_models=catalog_models,
        )
    if scheme is None and column_masking is None:
        return _VersionedSelectOnePermissionAnalysis(
            scheme=scheme,
            column_masking=column_masking,
            needs_permission_user_ref=False,
        )

    permission_plan = get_query_permission_plan(model_cls)

    return _VersionedSelectOnePermissionAnalysis(
        scheme=scheme,
        column_masking=column_masking,
        needs_permission_user_ref=((permission_plan is not None and permission_plan.requires_user_id) or column_masking is not None),
    )


def _project_versioned_raw_row(
    model_cls: type[DatabaseObjectRow],
    row: dict[str, Any],
    *,
    include_deleted: bool,
    allow_historical_fallback: bool = False,
) -> dict[str, Any] | None:
    """Polymorphism+tombstone filter that preserves versioning system columns.

    Used by ``VersionedSelectOneRawStep`` whose result is published as a CTE
    consumed by ``_WrapOptionalRawRowStep``'s ``WHERE NOT sys_deleted`` SQL.
    The system columns (``sys_deleted``, ``sys_revision_id``,
    ``sys_staged_commit_id``, etc.) must remain on the row so the downstream
    CTE contains the columns declared by ``cte_output_columns``.
    """
    if not _matches_versioned_polymorphic_row(
        model_cls,
        row,
        allow_historical_fallback=allow_historical_fallback,
    ):
        return None

    is_deleted = _coerce_deleted_flag(
        row.get("sys_deleted") if row.get("sys_deleted") is not None else row.get("deleted"),
    )
    if is_deleted and not include_deleted:
        return None
    row["deleted"] = is_deleted
    from l3200_metadata.schema_evolution import (
        RevisionSchemaContext,
        preprocess_json_fields_for_evolution,
    )

    preprocess_json_fields_for_evolution(model_cls, row, schema_context=RevisionSchemaContext())
    return row


def _coerce_deleted_flag(value: object) -> bool:
    """Normalise a ``sys_deleted``/``deleted`` payload to a Python bool.

    The JSON-aggregation path on the MariaDB/DoltDB family wraps every column
    in ``CAST(... AS CHAR CHARACTER SET utf8mb4)`` to dodge utf8mb4_bin vs
    utf8mb4_general_ci collation errors inside ``JSON_OBJECT``. That cast
    stringifies boolean columns to the characters ``"0"`` / ``"1"``. Treating
    the result with Python's native truthiness would mark every undeleted row
    as deleted (because ``bool("0") is True``), silently filtering out fresh
    inserts on those backends. Normalise here so every callsite gets a real
    bool regardless of how the driver serialised the column.
    """
    if value is None or value is False:
        return False
    if value is True:
        return True
    if isinstance(value, (int, float)):
        return bool(value)
    if isinstance(value, (bytes, bytearray)):
        value = value.decode("ascii", errors="ignore")
    if isinstance(value, str):
        lowered = value.strip().lower()
        return lowered not in ("", "0", "false", "f", "no", "n")
    return bool(value)


def _matches_versioned_polymorphic_row(
    model_cls: type[DatabaseObjectRow],
    row: dict[str, Any],
    *,
    allow_historical_fallback: bool,
) -> bool:
    from impl.common.l1050_polymorphism.type_dispatcher import dispatch_polymorphic_type
    from impl.common.l1050_polymorphism.type_filter_helper import matches_polymorphic_row
    from l1400_types import GraphQLTypeName
    from l9600_graphs.dynamic_types import DynamicTypeRegistry

    has_type_discriminator = row.get("type_name") is not None or row.get("type_id") is not None
    is_dynamic_model = DynamicTypeRegistry.is_dynamic_type_name(
        GraphQLTypeName(model_cls.__name__),
    )
    should_enforce_type_match = has_type_discriminator or not is_dynamic_model
    if not should_enforce_type_match:
        return True
    if matches_polymorphic_row(model_cls, row):
        return True
    if not allow_historical_fallback:
        return False
    try:
        concrete_cls, _ = dispatch_polymorphic_type(
            model_cls,
            dict(row),
            filter_fields=False,
            historical_fallback=True,
        )
    except ValueError:
        return False
    return issubclass(concrete_cls, model_cls)


def _project_versioned_row(
    model_cls: type[DatabaseObjectRow],
    row: dict[str, Any],
    *,
    include_deleted: bool,
    schema_context: RevisionSchemaContext,
) -> dict[str, Any] | None:
    if not _matches_versioned_polymorphic_row(
        model_cls,
        row,
        allow_historical_fallback=schema_context.is_historical,
    ):
        return None

    is_deleted = _coerce_deleted_flag(
        row.get("sys_deleted") if row.get("sys_deleted") is not None else row.get("deleted"),
    )
    if is_deleted and not include_deleted:
        return None
    if include_deleted:
        row["deleted"] = is_deleted

    keys_to_remove = [
        "sys_valid_from_revision_id",
        "sys_valid_to_revision_id",
        "sys_deleted",
        "branch_id",
        "sys_staged_commit_id",
        "sys_revision_id",
        "valid_from_revision_id",
        "valid_to_revision_id",
    ]
    if not include_deleted:
        keys_to_remove.append("deleted")
    for key in keys_to_remove:
        row.pop(key, None)
    from l3200_metadata.schema_evolution import preprocess_json_fields_for_evolution

    preprocess_json_fields_for_evolution(model_cls, row, schema_context=schema_context)
    return row


def _post_process_versioned_select_one[T: DatabaseObjectRow](
    model_cls: type[T],
    include_deleted: bool,
    raw_result: RawResult,
    hydrator: Hydrator,
) -> T | None:
    from impl.common.l2070_server_plan.steps.row_hydration import (
        _hydrate_row,
        _revision_schema_context_from_hydrator,
    )

    if not raw_result:
        return None
    row = raw_result[0]
    row_dict: dict[str, Any] = dict(row)
    schema_context = _revision_schema_context_from_hydrator(model_cls, hydrator)
    projected = _project_versioned_row(
        model_cls,
        row_dict,
        include_deleted=include_deleted,
        schema_context=schema_context,
    )
    if projected is None:
        return None
    return _hydrate_row(
        model_cls,
        projected,
        hydrator,
        schema_context=schema_context,
    )


def _project_optional_raw_from_raw(
    *,
    model_cls: type[DatabaseObjectRow],
    include_deleted: bool,
    raw_result: RawResult,
    allow_historical_fallback: bool = False,
) -> dict[str, Any] | None:
    if not raw_result:
        return None
    row = raw_result[0]
    return _project_versioned_raw_row(
        model_cls,
        dict(row),
        include_deleted=include_deleted,
        allow_historical_fallback=allow_historical_fallback,
    )


def _wrap_optional_raw_row_for_hydration(
    *,
    include_deleted: bool,
    raw_result: RawResult,
) -> dict[str, Any] | None:
    if not raw_result:
        return None
    row = dict(raw_result[0])
    is_deleted = _coerce_deleted_flag(
        row.get("sys_deleted") if row.get("sys_deleted") is not None else row.get("deleted"),
    )
    if is_deleted and not include_deleted:
        return None
    return row


def build_versioned_select_one_query_spec(
    model_cls: type[DatabaseObjectRow],
    *,
    sys_id: object,
    include_deleted: bool = False,
    permission_state_override: QueryPermissionState | None = None,
) -> QuerySpec[DatabaseObjectRow]:
    """Build a full-row query spec used by spill-aware versioned hydration."""
    from l1000_schema.typed_field import field, lazy_expr

    sys_id_field: Any = field(model_cls.sys_id)  # pyright: ignore[reportGeneralTypeIssues]
    sys_id_filter = QueryFilter(expression=sys_id_field == lazy_expr(sys_id))
    permission_state = permission_state_override if permission_state_override is not None else QueryPermissionState.AUTO
    return QuerySpec(
        model_cls=model_cls,
        select_columns=None,
        distinct=False,
        joins=[],
        filters=[sys_id_filter],
        order_by=[],
        limit=1,
        offset=None,
        group_by=[],
        aggregations=[],
        having=[],
        window_functions=[],
        permission_state=permission_state,
        permission_grammar=None,
        include_deleted=include_deleted,
    )


def lower_versioned_spill_aware_select_one_steps(
    *,
    ctx: LoweringContext,
    ref_id: ServerPlanRefId,
    model_cls: type[DatabaseObjectRow],
    query_spec: QuerySpec[DatabaseObjectRow],
    raw_step: (ServerPlanStep[dict[str, Any] | None] | ServerPlanStep[list[dict[str, Any]]] | ServerPlanStep[Sequence[dict[str, Any]]]),
    after_refs: frozenset[ServerPlanRefId] = frozenset(),
    include_hydrated: bool = True,
) -> list[ServerPlanStep[Any]]:
    from impl.common.l2070_server_plan.steps.row_hydration import HydrateFirstResolvedRowStep

    raw_select_ref = ServerPlanRefId(f"{ref_id}.raw_select")
    raw_ref = ServerPlanRefId(f"{ref_id}.raw_rows")
    raw_contract = raw_step.cte_publication_contract()
    assert raw_contract is not None
    source_columns = raw_contract.columns
    if source_columns is None:
        msg = f"{type(raw_step).__name__} must declare CTE columns for optional raw-row wrapping"
        raise TypeError(msg)
    source_column_type_hints = raw_contract.column_type_hints
    if source_column_type_hints is None:
        msg = f"{type(raw_step).__name__} must declare CTE column type hints for optional raw-row wrapping"
        raise TypeError(msg)
    source_column_type_hints.require_complete(source_columns)
    raw_step.ref_id = raw_select_ref
    if after_refs:
        object.__setattr__(raw_step, "_after_refs", after_refs)
    steps: list[ServerPlanStep[Any]] = [
        *raw_step.lower(ctx),
        _WrapOptionalRawRowStep(
            raw_ref,
            config=_WrapOptionalRawRowConfig(
                source_ref=raw_select_ref,
                include_deleted=query_spec.include_deleted,
                source_columns=source_columns,
                source_column_type_hints=source_column_type_hints,
            ),
            model_cls=model_cls,
        ),
    ]
    if include_hydrated:
        steps.append(
            HydrateFirstResolvedRowStep(
                ServerPlanRefId(ref_id),
                source_ref=raw_ref,
                model_cls=model_cls,
                include_deleted=query_spec.include_deleted,
                cte_output_columns=source_columns,
                cte_column_type_hints=source_column_type_hints,
            ),
        )
    return steps


def _select_raw_row_tombstone_column(columns: tuple[str, ...] | None) -> str:
    """Pick the tombstone column for a raw select-one source CTE.

    The spill-aware raw select-one source always materializes the tombstone as
    ``deleted`` (the sparse/merged-over-``_tip`` read output; see
    ``_versioned_sparse_cte_output_columns``).  Some explicitly published raw CTEs
    instead expose the system column ``sys_deleted`` directly, so honour that when
    the producer declares it.

    Republished split/fallback CTEs drop their column metadata
    (``CteReference.columns is None``).  In that case we must not assume
    ``sys_deleted``: the published-tip source only carries ``deleted`` and
    ``WHERE NOT sys_deleted`` raises ``column "sys_deleted" does not exist`` (the
    HTTP 400 regression on ``GET /api/data/{model}/{id}`` after a delete).
    """
    if columns is not None and "sys_deleted" in columns:
        return "sys_deleted"
    return "deleted"


class _WrapOptionalRawRowStep(SqlRelationPublisherStep[list[dict[str, Any]]]):
    """Normalize optional raw select-one rows into list form for spill loading."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        config: _WrapOptionalRawRowConfig,
        model_cls: type[DatabaseObjectRow],
    ) -> None:
        super().__init__(ref_id)
        self._source_ref = config.source_ref
        self._model_cls = model_cls
        self._include_deleted = config.include_deleted
        self._source_columns = config.source_columns
        self._source_column_type_hints = config.source_column_type_hints

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.MANY

    def is_read_only(self) -> bool:
        return True

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def supports_sql_batch_transport(self) -> bool:
        # Raw-row normalization is a relational projection and must remain in
        # the same statement as its SQL-native source on backends without
        # cross-statement relation transport.
        return True

    def consumes_executor_visible_dependencies(self) -> bool:
        return True

    def publishes_executor_visible_binding(self) -> bool:
        return self._source_columns is not None

    def always_publishes_executor_visible_binding(self) -> bool:
        return self._source_columns is not None

    def step_tags(self) -> frozenset[str]:
        return frozenset({"select_one", "raw", "project"})

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def dependencies(self) -> frozenset[str]:
        return frozenset({str(self._source_ref)})

    def sql_visible_dependencies(self) -> frozenset[str]:
        return frozenset({str(self._source_ref)})

    def cte_publication_contract(self: _WrapOptionalRawRowStep) -> CtePublicationContract:
        columns = self._source_columns
        column_type_hints = self._source_column_type_hints
        if columns is None:
            msg = f"{type(self).__name__} cannot publish a CTE contract without source columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        contract_columns = tuple(str(column) for column in columns)
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=contract_columns,
            column_type_hints=column_type_hints,
            relation_contract=CteRelationContract.source_cte(source_cte_ref=str(self._source_ref)),
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def preprocess(self, resolved: ResolvedRefs) -> None:
        del resolved

    def compile(self, ctx: CompilationContext) -> CompiledStep[list[dict[str, Any]]]:
        cte_ref = ctx.cte_refs.get(str(self._source_ref)) if ctx.cte_refs is not None else None
        if cte_ref is not None:
            cte_name = cte_ref.ref_id

            where = None
            if not self._include_deleted:
                tombstone_column = _select_raw_row_tombstone_column(cte_ref.columns)
                where = SqlWhereClause(
                    SqlUnaryOp(
                        UnaryOp.NOT,
                        SqlColumnRef(SqlColumnName(tombstone_column)),
                    ),
                )
            contract = self.cte_publication_contract()
            selected_columns = tuple(contract.columns)
            column_type_hints = contract.column_type_hints
            __opa002_grammar_593 = SqlSelect(
                select=SqlSelectList(
                    [SqlColumnRef(SqlColumnName(column)) for column in selected_columns] if selected_columns else [SqlStar()],
                ),
                from_clause=SqlTableIdent(SqlTableName(cte_name)),
                where=where,
                limit=1,
            )
            from l2070_batching.output_shape import CompiledOutputShape, synthetic_output_field

            output_shape = CompiledOutputShape(
                tuple(synthetic_output_field(column) for column in selected_columns),
            )
            return CompiledStep(
                output_shape=output_shape,
                result_relation=DeclaredResultRelation.from_output_shape(output_shape),
                grammar=__opa002_grammar_593,
                column_type_hints=column_type_hints,
                needs_returning=True,
                closed_post_op=CompiledPostOp.materialize(
                    ResultMaterializationSpec(
                        behavior=PostOpBehavior.TERMINAL_ARRAY,
                        raw_mode=True,
                        # Keep include_deleted as closed literal metadata for
                        # the terminal decoder, never as a runtime-ref fallback.
                        literal_payload={"include_deleted": self._include_deleted},
                    ),
                ),
                auxiliary_ctes=[(cte_name, cte_ref.auxiliary_query)] if cte_ref.auxiliary_query is not None else None,
            )
        raise_missing_cte_fallback_forbidden(
            site_name=type(self).__name__,
            trigger=f"optional raw-row source {self._source_ref!r} has no CTE binding during compile()",
            blocked_path="compile-time normalization of versioned select_one raw rows",
            result_contract=("versioned select_one normalization must consume an explicit SQL-visible raw-row source"),
            implementation_requirements=(
                "Compile the upstream raw select step as a published CTE before normalization.",
                "Thread that CTE binding through ctx.cte_refs into _WrapOptionalRawRowStep.compile().",
                "Do not recover by reading runtime refs or resolved Python rows during compile().",
            ),
        )
        raise AssertionError("unreachable")

    def execute_runtime(self, resolved: ResolvedRefs) -> list[dict[str, Any]]:
        source = resolved.get(str(self._source_ref))
        if source is None:
            return []
        items = source if isinstance(source, list | tuple) else (source,)
        rows: list[dict[str, Any]] = []
        for item in items:
            if item is None:
                continue
            if isinstance(item, dict):
                row = dict(item)
            elif hasattr(item, "model_dump"):
                row = cast("Any", item).model_dump(mode="python")
            else:
                row = {
                    field_name: getattr(item, field_name)
                    for field_name in getattr(self._model_cls, "model_fields", {})
                    if hasattr(item, field_name)
                }
            if not self._include_deleted and bool(row.get("sys_deleted", row.get("deleted", False))):
                continue
            if self._source_columns is not None:
                row = {str(column): row.get(str(column)) for column in self._source_columns}
            rows.append(row)
        return rows[:1]


def _resolve_versioned_permission_user_cte(
    *,
    ctx: CompilationContext,
    user_id_ref_id: ServerPlanRefId | None,
) -> CteReference | None:
    from l2070_batching.compilation import CteReference

    if user_id_ref_id is None:
        return None
    cte_ref = ctx.cte_refs.get(str(user_id_ref_id)) if ctx.cte_refs is not None else None
    if isinstance(cte_ref, CteReference):
        if "user_id" not in cte_ref.columns:
            raise_missing_cte_fallback_forbidden(
                site_name="_resolve_versioned_permission_user_cte",
                trigger=f"permission user ref {user_id_ref_id!r} does not publish a user_id column",
                blocked_path="versioned select_one permission SQL cannot infer user identity from a weak CTE binding",
                result_contract="versioned select_one permission lowering must consume a declared user_id column.",
                implementation_requirements=(
                    "Publish SessionUserIdStep output with columns=('user_id',) and complete type hints.",
                    "Do not pass a name-only or wrong-shaped CTE binding for permission checks.",
                ),
            )
        return cte_ref
    raise_missing_cte_fallback_forbidden(
        site_name="_resolve_versioned_permission_user_cte",
        trigger=f"permission user ref {user_id_ref_id!r} has no CTE binding during compile()",
        blocked_path="planner-time permission-user materialization for versioned select_one compilation",
        result_contract=("versioned select_one permission lowering must consume an explicit SQL-visible user id ref"),
        implementation_requirements=(
            "Publish SessionUserIdStep output as an explicit upstream ref before terminal compile.",
            "Thread that ref through ctx.cte_refs before compiling the permission-wrapped SELECT.",
            "Do not recover by reading ctx.txn, ctx.materialized_pipeline, or session-owned tables here.",
        ),
    )
    raise AssertionError("unreachable")


def _compile_versioned_permission_user_expr(cte_ref: CteReference) -> SqlRenderable:
    from impl.common.l2100_sql_grammar.domain.infra.stmt_dml_simple import SqlCteFieldRef

    return SqlCteFieldRef(
        SqlCteStepName(cte_ref.ref_id),
        SqlColumnName("user_id"),
    )


def _compile_versioned_read_revision_expr(
    revision_id: RevisionId | None,
    revision_ref: ScalarServerRef[RevisionId] | None,
    ctx: CompilationContext,
) -> SqlRenderable | None:
    if revision_id is not None:
        return SqlParam(revision_id)
    if revision_ref is None:
        return None
    return lower_scalar_server_ref(revision_ref, ctx)


def _permission_user_auxiliary_ctes(
    ctx: CompilationContext,
    user_id_ref_id: ServerPlanRefId | None,
) -> list[tuple[str, SqlRenderable]] | None:
    if user_id_ref_id is None or ctx.cte_refs is None:
        return None
    cte_ref = ctx.cte_refs.get(str(user_id_ref_id))
    if not isinstance(cte_ref, CteReference) or cte_ref.auxiliary_query is None:
        return None
    return [(cte_ref.ref_id, cte_ref.auxiliary_query)]


