def _select_one_full_row_columns(model_cls: type[DatabaseObjectRow], *, historical: bool = False) -> list[str]:
    from impl.common.l7050_versioned_schema_builder.polymorphic_field_helper import (
        get_all_select_columns,
    )

    selected_columns: list[str] = []
    for field_name in get_all_select_columns(model_cls):
        try:
            selected_columns.append(_model_field_db_column(model_cls, field_name))
        except (AttributeError, ValueError):
            selected_columns.append(field_name)
    sparse_absent_columns = {"sys_revision_id", "sys_staged_commit_id"} if historical else set()
    if sparse_absent_columns:
        selected_columns = [column for column in selected_columns if column not in sparse_absent_columns]
    for extra_col in (
        "sys_deleted",
        "branch_id",
        "sys_staged_commit_id",
        "sys_revision_id",
        "sys_valid_from_revision_id",
        "sys_valid_to_revision_id",
    ):
        if extra_col in sparse_absent_columns:
            continue
        if extra_col not in selected_columns:
            selected_columns.append(extra_col)
    return selected_columns


def _wrap_versioned_select_with_permissions(
    model_cls: type[DatabaseObjectRow],
    stmt: SqlRenderable,
    ctx: CompilationContext,
    *,
    selected_columns: list[str] | None = None,
    user_id_ref_id: ServerPlanRefId | None = None,
    permission_bypass: bool = False,
    historical: bool = False,
    historical_revision_sql: SqlRenderable | None = None,
    fallback_branch_id_sql: SqlRenderable | None = None,
    permission_context_ref: ServerPlanRefId | None = None,
    permission_context_type: type[ResolvedSessionContext] | None = None,
) -> SqlRenderable:
    """Wrap versioned select-one SQL with permission filtering and masking."""
    from impl.common.l2050_sql_types.sql_branded_types import (
        SqlAliasName,
        SqlColumnName,
    )
    from impl.common.l2100_sql_grammar.domain.infra.stmt_dml_simple import (
        SqlWrappedSubquery,
    )
    from impl.common.l2100_sql_grammar.tree.clauses import (
        SqlFrom,
        SqlSelectAlias,
        SqlSelectList,
        SqlWhereClause,
    )
    from impl.common.l2100_sql_grammar.tree.expr_leaf import (
        SqlColumnRef,
        SqlStar,
    )
    from impl.common.l2100_sql_grammar.tree.statements import SqlSelect
    from impl.common.l5200_sql_query.field_reference_policy import build_sql_field_reference_policy
    from impl.common.l7300_cross_branch.permission_expression_compiler import (
        compile_versioned_permission_where_with_user_id_sql,
    )
    from l1000_schema.schema_def import get_db_column_name

    alias = "v"
    session_source = ctx.session_id
    if isinstance(session_source, ServerRef):
        session_shape = inspect_server_value_shape_for_planning(
            session_source,
            site="_wrap_versioned_select_with_permissions.session_id",
        )
        if session_shape.symbolic_ref_id is not None:
            from l2070_batching.seeded_constants import read_seeded_constant_from_ctx

            found_session, seeded_session = read_seeded_constant_from_ctx(
                ctx,
                ServerPlanRefId(session_shape.symbolic_ref_id),
            )
            if found_session:
                session_source = seeded_session
    catalog_models = None if ctx.planning_catalog is None else ctx.planning_catalog.tables.keys()
    permission_analysis = analyze_versioned_select_one_permissions(
        model_cls,
        ctx.session_id,
        catalog_models=catalog_models,
        permission_bypass=permission_bypass,
    )
    scheme = permission_analysis.scheme
    column_masking = permission_analysis.column_masking
    requires_application_context = False
    if scheme is not None:
        from l4000_permissions.permission_scheme import (
            permission_scheme_requires_application_context,
        )

        requires_application_context = permission_scheme_requires_application_context(
            scheme,
            model_cls,
            action="read",
        )
    if session_source == SessionId.schema() and not requires_application_context:
        return stmt
    if requires_application_context and (permission_context_ref is None or permission_context_type is None):
        from l1100_exceptions.exceptions import PermissionCompilationError

        msg = "Versioned select-one application policy requires a bound session context"
        raise PermissionCompilationError(msg)
    if not permission_analysis.needs_permission_user_ref and not requires_application_context:
        return stmt
    versioning_domain = ctx.versioning_domain
    if versioning_domain is None:
        try:
            versioning_domain = model_cls.__versioning_domain__
        except AttributeError:
            versioning_domain = None
    if scheme is not None and versioning_domain is None:
        versioning_domain = require_versioning_domain(
            ctx,
            site="_wrap_versioned_select_with_permissions",
        )

    resolved_user_cte = _resolve_versioned_permission_user_cte(
        ctx=ctx,
        user_id_ref_id=user_id_ref_id,
    )
    if resolved_user_cte is None:
        raise_missing_cte_fallback_forbidden(
            site_name="_wrap_versioned_select_with_permissions",
            trigger=("versioned select_one permission compilation reached a path without a published permission-user ref"),
            blocked_path="planner-time permission-user fallback for versioned select_one compilation",
            result_contract=(
                "versioned select_one permission lowering must consume a SQL-visible user-id ref "
                "or an explicit bypass/system-session path"
            ),
            implementation_requirements=(
                "Keep SessionUserIdStep output published as an explicit upstream ref.",
                "Thread that ref through ctx.cte_refs before compiling the permission-wrapped SELECT.",
                "Do not recover by consulting ctx.txn, sys_sessions, or other hidden runtime state.",
            ),
        )

    permission_grammar: SqlRenderable | None
    if scheme is not None:
        assert versioning_domain is not None
        from impl.common.l2070_server_plan.steps._compile_helpers import (
            session_id_expr,
            versioned_permission_anchor,
        )
        from impl.common.l7300_cross_branch.permission_expression_compiler import (
            PermissionVersionAnchor,
            PinnedRevisionPermissionAnchor,
        )

        permission_version_anchor: PermissionVersionAnchor
        if historical:
            if historical_revision_sql is None:
                msg = "Historical permission compilation requires a revision anchor"
                raise TypeError(msg)
            permission_version_anchor = PinnedRevisionPermissionAnchor(
                domain=versioning_domain,
                revision_id_sql=historical_revision_sql,
            )
        else:
            permission_version_anchor = versioned_permission_anchor(
                ctx,
                domain=versioning_domain,
                fallback_branch_id_sql=fallback_branch_id_sql,
            )
        session_vars = None
        if permission_context_ref is not None and permission_context_type is not None:
            from impl.common.l7300_cross_branch.permission_expression_compiler import (
                _sql_session_context_bindings,
            )

            session_vars = _sql_session_context_bindings(
                permission_context_type,
                permission_context_ref,
            )
        nested_context = replace(
            ctx,
            versioning_domain=versioning_domain,
            query_versioned_scope=(
                fallback_branch_id_sql,
                historical_revision_sql if historical else None,
            ),
        )
        permission_grammar = compile_versioned_permission_where_with_user_id_sql(
            model_cls,
            _compile_versioned_permission_user_expr(resolved_user_cte),
            alias,
            action="read",
            version_anchor=permission_version_anchor,
            session_id_sql=session_id_expr(ctx.session_id, ctx),
            session_vars=session_vars,
            compilation_context=nested_context,
        )
    else:
        permission_grammar = None
    if permission_grammar is None and column_masking is None:
        return stmt

    if selected_columns is None:
        selected_columns = _select_one_full_row_columns(model_cls, historical=historical)

    select_items: list[Any]
    if column_masking is not None:
        owner_field, private_columns = column_masking
        if resolved_user_cte is None:
            msg = "resolved_user_cte must exist before versioned select_one column masking compiles"
            raise RuntimeError(msg)
        session_user_id_expr = _compile_versioned_permission_user_expr(resolved_user_cte)
        field_by_private_db_column = {
            get_db_column_name(model_cls, DynamicFieldName(field_name)): field_name for field_name in private_columns
        }
        field_policy = build_sql_field_reference_policy(
            get_db_column=lambda field_name: get_db_column_name(model_cls, DynamicFieldName(field_name)),
            table_alias=alias,
            column_masking=(owner_field, private_columns),
            column_masking_user_grammar=session_user_id_expr,
        )
        select_items = []
        for db_col in selected_columns:
            private_field_name = field_by_private_db_column.get(SqlColumnName(db_col))
            if private_field_name is not None:
                select_items.append(
                    SqlSelectAlias(
                        field_policy.observable_field(
                            private_field_name,
                            db_col=db_col,
                            qualifier=alias,
                        ),
                        alias=SqlAliasName(db_col),
                    ),
                )
                continue
            select_items.append(SqlColumnRef(SqlColumnName(db_col), qualifier=alias))
    else:
        select_items = [SqlStar(qualifier=alias)]

    return SqlSelect(
        select=SqlSelectList(select_items),
        from_clause=SqlFrom(SqlWrappedSubquery(stmt, alias=SqlAliasName(alias))),
        where=SqlWhereClause(permission_grammar) if permission_grammar is not None else None,
    )


def _select_one_columns(common_columns: list[str]) -> list[str]:
    return [column for column in common_columns if column not in {"branch_hash32", "graph_hash32", "source_hash32", "target_hash32"}]


def _versioned_sparse_cte_output_columns(
    model_cls: type[DatabaseObjectRow],
    *,
    include_validity_columns: bool = True,
) -> tuple[str, ...]:
    """Return the SQL-visible columns for sparse historical ``SELECT *`` reads."""
    projection = build_read_metadata_plan(model_cls).projection_for(READ_FLAVOR_SPARSE_HISTORICAL)
    columns = list(projection.cte_output_columns)
    for sparse_column in (
        "branch_ord",
        "sys_revision_id",
        "sys_staged_commit_id",
        "sys_valid_from_seq",
        "sys_valid_to_seq",
    ):
        if sparse_column not in columns:
            columns.append(sparse_column)
    for field_name in getattr(model_cls, "model_fields", {}):
        if not is_framework_physical_adjunct_field(model_cls, field_name):
            continue
        db_column = str(get_db_column_name(model_cls, DynamicFieldName(field_name)))
        if db_column not in columns:
            columns.append(db_column)
    physical_hash_columns: tuple[str, ...] = ()
    try:
        from l9600_graphs.graph import GraphEdge, GraphNode

        if issubclass(model_cls, GraphNode | GraphEdge):
            physical_hash_columns = (
                (("branch_hash32",) if "branch_id" in columns else ())
                + (("graph_hash32",) if "graph_sys_id" in columns else ())
                + (("source_hash32",) if "source_sys_id" in columns else ())
                + (("target_hash32",) if "target_sys_id" in columns else ())
            )
    except Exception:
        physical_hash_columns = ()
    for db_column in physical_hash_columns:
        if db_column not in columns:
            columns.append(db_column)
    graph_dense_key_columns: tuple[str, ...] = ()
    try:
        from l9600_graphs.graph import GraphEdge

        if issubclass(model_cls, GraphEdge):
            graph_dense_key_columns = (
                (("graph_key",) if "graph_sys_id" in columns else ())
                + (("source_node_key",) if "source_sys_id" in columns else ())
                + (("target_node_key",) if "target_sys_id" in columns else ())
            )
    except Exception:
        graph_dense_key_columns = ()
    for db_column in graph_dense_key_columns:
        if db_column not in columns:
            columns.append(db_column)
    dynamic_fts_generated_columns = False
    try:
        from l9600_graphs.dynamic_types import DynamicEdgeBase, DynamicNodeBase

        dynamic_fts_generated_columns = issubclass(model_cls, DynamicNodeBase | DynamicEdgeBase)
    except Exception:
        dynamic_fts_generated_columns = False
    fts_generated_columns: tuple[str, ...] = (
        ("sys_fts_content_hash", "sys_fts_hash_short", "sys_fts_hash_high")
        if get_fts_config(model_cls) is not None or dynamic_fts_generated_columns
        else ()
    )
    for db_column in fts_generated_columns:
        if db_column not in columns:
            columns.append(db_column)
    if not include_validity_columns:
        columns = [
            column
            for column in columns
            if column
            not in {
                "sys_valid_from_revision_id",
                "sys_valid_from_seq",
                "sys_valid_to_revision_id",
                "sys_valid_to_seq",
            }
        ]
    return tuple(columns)


def _versioned_sparse_cte_type_hints(
    model_cls: type[DatabaseObjectRow],
    columns: tuple[str, ...],
) -> SqlColumnTypeHints:
    existence_column = _EXISTENCE_COLUMN.to_row_key()
    model_columns = tuple(column for column in columns if column != existence_column)
    hints = model_sql_column_type_hints(model_cls, model_columns)
    if hints is None:
        msg = f"Could not resolve SQL column type hints for {model_cls.__name__}"
        raise TypeError(msg)
    projection = build_read_metadata_plan(model_cls).projection_for(READ_FLAVOR_SPARSE_HISTORICAL)
    return combine_sql_column_type_hints(
        model_columns,
        hints,
        projection.declared_sql_column_type_hints(),
        framework_physical_column_sql_column_type_hints(),
    )


def _versioned_select_one_cte_type_hints(
    model_cls: type[DatabaseObjectRow],
    columns: tuple[str, ...] | None = None,
) -> SqlColumnTypeHints:
    output_columns = columns or _versioned_sparse_cte_output_columns(model_cls)
    sparse_hints = _versioned_sparse_cte_type_hints(
        model_cls,
        output_columns,
    )
    inline_hints = _inline_large_column_cte_type_hints(model_cls)
    output_column_set = frozenset(output_columns)
    return SqlColumnTypeHints(
        jsonb_columns=sparse_hints.jsonb_columns,
        uuid_columns=sparse_hints.uuid_columns,
        timestamptz_columns=sparse_hints.timestamptz_columns,
        date_columns=sparse_hints.date_columns,
        time_columns=sparse_hints.time_columns,
        numeric_columns=sparse_hints.numeric_columns,
        bool_columns=(
            sparse_hints.bool_columns
            | inline_hints.bool_columns
            | (frozenset({_EXISTENCE_COLUMN.to_row_key()}) if _EXISTENCE_COLUMN.to_row_key() in output_columns else frozenset())
            | (frozenset({"sys_deleted"}) if "sys_deleted" in output_columns else frozenset())
        ),
        integer_columns=sparse_hints.integer_columns | inline_hints.integer_columns,
        bigint_columns=sparse_hints.bigint_columns,
        double_columns=sparse_hints.double_columns,
        text_columns=sparse_hints.text_columns | inline_hints.text_columns,
        bytea_columns=sparse_hints.bytea_columns | inline_hints.bytea_columns,
        driver_native_columns=sparse_hints.driver_native_columns | inline_hints.driver_native_columns,
        postgres_bit_columns=sparse_hints.postgres_bit_columns | inline_hints.postgres_bit_columns,
        postgres_vector_columns=sparse_hints.postgres_vector_columns | inline_hints.postgres_vector_columns,
    ).filtered(set(output_column_set))


