def _without_large_column_transport_columns(
    model_cls: type[DatabaseObjectRow],
    columns: Sequence[str],
) -> tuple[str, ...]:
    model_columns = {
        candidate for field_name in model_cls.model_fields for candidate in (field_name, _model_field_db_column(model_cls, field_name))
    }
    internal_sparse_columns = frozenset({"branch_id"} - model_columns)
    pointer_columns = _large_column_pointer_column_candidates(model_cls)
    return tuple(column for column in columns if column not in pointer_columns and column not in internal_sparse_columns)


def _effective_select_one_materialization_ctx(
    ctx: CompilationContext,
) -> CompilationContext:
    lazy_tip_materialization = ctx.lazy_branch_tip_materialization
    if lazy_tip_materialization is None or lazy_tip_materialization.ref_id is None:
        return ctx
    resolved_tip_binding = resolve_sql_visible_ref(
        ctx,
        ServerPlanRefId(str(lazy_tip_materialization.ref_id)),
        default_field="tip_materialization",
    )
    if resolved_tip_binding is None:
        return ctx
    tip_materialization = _literal_tip_materialization_from_cte(
        resolved_tip_binding.binding,
    )
    if tip_materialization is None:
        return ctx
    return replace(
        ctx,
        branch_tip_materialized=tip_materialization == "materialized",
    )


def _compile_versioned_select_one_stmt(
    sys_id: object,
    *,
    model_cls: type[DatabaseObjectRow],
    staged_table_name: str,
    tip_table_name: str,
    common_columns: list[str],
    branch_id: SqlRenderable | str | ScalarServerRef[BranchId],
    type_ids: list[str] | None,
    multitable_sparse_cte_name: str | None,
    ctx: CompilationContext,
) -> SqlRenderable:
    from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName, SqlTableName
    from impl.common.l2070_server_plan.steps._compile_server_ref import (
        lower_scalar_source,
    )
    from impl.common.l2100_sql_grammar.domain.versioning.stmt_versioned import SqlStagedTipUnionLookup
    from impl.common.l2100_sql_grammar.tree.clauses import SqlSelectList
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef
    from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
    from impl.common.l2100_sql_grammar.tree.statements import SqlSelect
    from l1000_schema.table_utils import bounded_identifier_with_suffix, get_table_name

    direct_cte_ref: CteReference | None = None
    required_columns = _select_one_columns(common_columns)
    sys_id_shape = (
        inspect_server_value_shape_for_planning(
            sys_id,
            site="_compile_versioned_select_one_stmt.sys_id",
        )
        if isinstance(sys_id, ServerRef)
        else None
    )
    sys_id_deps = sys_id_shape.dependency_refs if sys_id_shape is not None else frozenset()
    effective_sys_id = sys_id
    if sys_id_shape is not None and sys_id_shape.symbolic_ref_id is not None:
        from l2070_batching.seeded_constants import read_seeded_constant_from_ctx

        found_sys_id, seeded_sys_id = read_seeded_constant_from_ctx(
            ctx,
            ServerPlanRefId(sys_id_shape.symbolic_ref_id),
        )
        if found_sys_id:
            unwrap_to_str = getattr(seeded_sys_id, "unwrap_to_str", None)
            if callable(unwrap_to_str):
                effective_sys_id = str(unwrap_to_str())
            else:
                effective_sys_id = str(seeded_sys_id) if isinstance(seeded_sys_id, UUID) else seeded_sys_id
    for dep in sorted(sys_id_deps):
        candidate = ctx.cte_refs.get(dep)
        if candidate is None and "." in dep:
            # ScalarServerRef produced by ``.sys_id`` on an ObjectServerRef carries
            # the dotted child ref_id (e.g. ``insert_0.sys_id``) while the CTE
            # binding is registered under the base step ref (e.g. ``insert_0``).
            # Walk the dotted prefix chain to find the registered ancestor, per
            # the contract documented on ``ServerRef.dependencies``.
            base = dep.split(".", 1)[0]
            candidate = ctx.cte_refs.get(base)
        if candidate is None or candidate.source_tables is None:
            continue
        if staged_table_name not in candidate.source_tables:
            continue
        # Only use the direct CTE path when the binding points at an insert
        # CTE defined in the same batch (``auxiliary_query is None``). Cross-
        # batch ``published_N`` bindings carry a ``SqlPublishedRowsQuery``
        # auxiliary_query that replays only the explicitly-published columns
        # (typically just ``sys_id``) and cannot satisfy a versioned select
        # that needs ``branch_id``/``sys_deleted``. In that case fall through
        # to ``SqlStagedTipUnionLookup`` against the committed staged table.
        if candidate.auxiliary_query is not None:
            continue
        cte_columns = candidate.columns
        if cte_columns is not None:
            cte_column_set = set(cte_columns)
            if not all(col in cte_column_set for col in required_columns):
                continue
        direct_cte_ref = candidate
        break

    if direct_cte_ref is not None:
        return SqlSelect(
            select=SqlSelectList(
                [SqlColumnRef(SqlColumnName(col)) for col in _select_one_columns(common_columns)],
            ),
            from_clause=SqlTableIdent(SqlTableName(direct_cte_ref.ref_id)),
            limit=1,
        )
    effective_ctx = _effective_select_one_materialization_ctx(ctx)
    use_sparse_published_source = not effective_ctx.branch_tip_materialized
    if use_sparse_published_source:
        table_names = derive_versioned_table_names(VersionedBaseTableName(get_table_name(model_cls)))
        published_table_name = multitable_sparse_cte_name or table_names.sparse
    else:
        published_table_name = tip_table_name
    published_sparse_branch_index_table: SqlTableName | None = None
    if use_sparse_published_source:
        domain = require_versioning_domain(ctx, site="versioned_select_one._compile_select_one_sql")
        published_sparse_branch_index_table = get_table_name(domain.revision_branch_index_model)
    published_sparse_revision_id: RevisionId | SqlRenderable | None = None
    if use_sparse_published_source and not ctx.is_write_transaction and ctx.revision_id is not None:
        published_sparse_revision_id = RevisionId(ctx.revision_id)
    elif use_sparse_published_source and not ctx.is_write_transaction and ctx.lazy_revision is not None:
        published_sparse_revision_id = lower_scalar_source(ctx.lazy_revision, ctx)
    staged_visibility_filter = ctx.staged_visibility_filter
    if not ctx.is_write_transaction and not ctx.prefer_tip_merged:
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlInlineLiteral

        staged_visibility_filter = SqlInlineLiteral(False)
    lookup_columns = [column for column in required_columns if column != "sys_deleted"]
    model_identity_column = str(get_db_column_name(model_cls, DynamicFieldName("sys_id")))
    lookup_source_columns = tuple("sys_id" if column == model_identity_column else column for column in lookup_columns)
    return SqlStagedTipUnionLookup(
        staged_table=SqlTableName(staged_table_name),
        tip_table=SqlTableName(published_table_name),
        columns=lookup_columns,
        source_columns=lookup_source_columns,
        branch_id=lower_scalar_source(branch_id, ctx),
        sys_id=lower_scalar_source(effective_sys_id, ctx),
        type_ids=type_ids,
        published_sparse_revision_id=published_sparse_revision_id,
        published_sparse_open_row=use_sparse_published_source and published_sparse_revision_id is None,
        published_sparse_branch_index_table=published_sparse_branch_index_table,
        staged_visibility_filter=staged_visibility_filter,
    )


def _effective_read_revision_id_and_ref(
    revision_id: RevisionId | None,
    revision_ref: ScalarServerRef[RevisionId] | None,
    ctx: CompilationContext,
) -> tuple[RevisionId | None, ScalarServerRef[RevisionId] | None]:
    """Fold revision for sparse read compile without inspecting ref resolvedness."""
    if revision_id is not None:
        return revision_id, None
    if revision_ref is not None and revision_ref.ref_id is None and ctx.revision_id is not None:
        return RevisionId(ctx.revision_id), None
    if revision_ref is not None:
        return None, revision_ref
    rid = ctx.revision_id
    return (RevisionId(rid), None) if rid is not None else (None, None)


def _select_one_ancestor_cte_name(ref_id: ServerPlanRefId) -> str:
    from l1000_schema.schema_def import safe_index_name

    safe_ref = "".join(char if char.isalnum() else "_" for char in str(ref_id))
    return safe_index_name(f"_visible_ancestors_{safe_ref}")


def _auxiliary_cte_for_scalar_ref(
    ref: ScalarServerRef[Any] | None,
    ctx: CompilationContext,
) -> tuple[str, SqlRenderable] | None:
    if ref is None:
        return None
    from impl.common.l2070_server_plan.steps._compile_server_ref import (
        get_scalar_server_ref_binding,
    )

    binding = get_scalar_server_ref_binding(ref, ctx)
    if binding is None:
        return None
    for cte_ref in ctx.cte_refs.values():
        if cte_ref.ref_id == binding.cte_name and cte_ref.auxiliary_query is not None:
            return cte_ref.ref_id, cte_ref.auxiliary_query
    return None


def _effective_type_ids_for_model(
    model_cls: type[DatabaseObjectRow],
    type_ids: list[str] | None,
) -> list[str] | None:
    from l1400_types import GraphQLTypeName
    from l9600_graphs.dynamic_types import DynamicTypeRegistry

    if DynamicTypeRegistry.is_dynamic_type_name(GraphQLTypeName(model_cls.__name__)):
        return None
    return type_ids


def _build_multitable_sparse_cte_for_select_one(
    model_cls: type[DatabaseObjectRow],
    ctx: CompilationContext,
) -> tuple[str, tuple[tuple[str, Any], ...]] | None:
    """Return sparse UNION CTE metadata for multitable polymorphic base lookups."""
    from impl.common.l2100_sql_grammar.domain.polymorphism.multitable_cte import (
        build_multitable_polymorphic_cte_definition,
        build_multitable_polymorphic_cte_name,
    )
    from impl.common.l7245_versioned_backends.generic_sparse import GenericSparseVersionedBackend
    from l1000_schema.table_utils import get_table_name

    catalog = require_planning_catalog(ctx, site="_build_multitable_sparse_cte_for_select_one")
    read_shape = catalog.read_metadata_for_model(model_cls)
    if not read_shape.multitable_source_models:
        return None

    backend: GenericSparseVersionedBackend[Any] = GenericSparseVersionedBackend()
    backend.configure_for_backend_type(ctx.backend_type)
    materialized = build_materialized_multitable_read_projection(
        read_shape,
        flavor=READ_FLAVOR_SPARSE_HISTORICAL,
        materialize_model=backend._get_or_create_sparse_model,
    )
    assert materialized is not None
    materialized_model = materialized.output_model_cls
    materialized_sources = materialized.source_models
    cte_name = build_multitable_polymorphic_cte_name(get_table_name(materialized_model))
    cte_definition = build_multitable_polymorphic_cte_definition(
        materialized_model,
        materialized_sources,
        cte_name=SqlCteName(cte_name),
        read_projection=materialized.projection,
    )
    if cte_definition is None:
        return None
    return cte_name, (cte_definition,)


def _build_multitable_merged_ctes_for_select_one(
    model_cls: type[DatabaseObjectRow],
    _ctx: CompilationContext,
    common_columns: list[str],
) -> tuple[str, str, list[str], tuple[tuple[str, Any], ...]] | None:
    """Return staged/tip UNION CTE metadata for branch-tip multitable lookups."""
    from impl.common.l2100_sql_grammar.domain.polymorphism.multitable_cte import (
        build_multitable_polymorphic_cte_definition,
        build_multitable_polymorphic_cte_name,
    )
    from impl.common.l7245_versioned_backends.generic_sparse import GenericSparseVersionedBackend
    from l1000_schema.table_utils import get_table_name

    catalog = require_planning_catalog(_ctx, site="_build_multitable_merged_ctes_for_select_one")
    read_shape = catalog.read_metadata_for_model(model_cls)
    if not read_shape.multitable_source_models:
        return None

    backend: GenericSparseVersionedBackend[Any] = GenericSparseVersionedBackend()
    backend.configure_for_backend_type(_ctx.backend_type)
    tip_materialized = build_materialized_multitable_read_projection(
        read_shape,
        flavor=READ_FLAVOR_TIP_MERGED,
        materialize_model=backend._get_or_create_tip_model,
    )
    assert tip_materialized is not None
    tip_model = tip_materialized.output_model_cls
    tip_sources = tip_materialized.source_models
    tip_cte_name = build_multitable_polymorphic_cte_name(get_table_name(tip_model))
    tip_cte_definition = build_multitable_polymorphic_cte_definition(
        tip_model,
        tip_sources,
        cte_name=SqlCteName(tip_cte_name),
        read_projection=tip_materialized.projection,
    )

    staged_materialized = build_materialized_multitable_read_projection(
        read_shape,
        flavor=READ_FLAVOR_STAGED_MERGED,
        materialize_model=backend._get_or_create_staged_model,
    )
    assert staged_materialized is not None
    staged_model = staged_materialized.output_model_cls
    staged_sources = staged_materialized.source_models
    staged_cte_name = build_multitable_polymorphic_cte_name(get_table_name(staged_model))
    staged_cte_definition = build_multitable_polymorphic_cte_definition(
        staged_model,
        staged_sources,
        cte_name=SqlCteName(staged_cte_name),
        read_projection=staged_materialized.projection,
    )

    if tip_cte_definition is None or staged_cte_definition is None:
        return None

    projection_columns = {field.cte_output_column for field in tip_materialized.projection.data_fields}
    projection_columns.add("branch_id")
    staged_source_columns = {
        get_db_column_name(source_model, DynamicFieldName(field_name))
        for source_model in staged_sources
        for field_name in source_model.model_fields
    }
    projected_columns = list(
        dict.fromkeys(
            (
                *(column for column in common_columns if column in projection_columns),
                *(field.cte_output_column for field in tip_materialized.projection.data_fields),
                *(
                    get_db_column_name(source_model, DynamicFieldName(field_name))
                    for source_model in tip_sources
                    for field_name in source_model.model_fields
                    if get_db_column_name(source_model, DynamicFieldName(field_name)) in staged_source_columns
                ),
            ),
        ),
    )
    if "branch_id" not in projected_columns:
        projected_columns.append("branch_id")

    return tip_cte_name, staged_cte_name, projected_columns, (tip_cte_definition, staged_cte_definition)


class VersionedSelectOneStep[T](SqlRelationPublisherStep[T | None]):
    """L0: Versioned select_one via SqlStagedTipUnionLookup.

    For the write path (branch_id already known): ``compile()`` reads
    ``ctx.branch_id`` from the CompilationContext, consistent with
    other versioned read steps (VersionedQueryFromSpecStep, etc.).

    All data is pre-computed at lowering time. compile() only renders grammar.
    """

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        sys_id: object,
        config: _VersionedSelectOneConfig,
    ) -> None:
        super().__init__(ref_id)
        self._model_cls = model_cls
        self._sys_id = sys_id
        self._staged_table_name = config.staged_table_name
        self._tip_table_name = config.tip_table_name
        self._common_columns = config.common_columns
        self._branch_id = config.branch_id
        self._branch_ref_id = config.branch_ref_id
        self._branch_scope_token = config.branch_scope_token
        self._type_ids = config.type_ids
        self._user_id_ref_id = config.user_id_ref_id
        self._permission_bypass = config.permission_bypass
        self._include_deleted = config.include_deleted
        self._permission_context_ref = config.permission_context_ref
        self._permission_context_type = config.permission_context_type
        self._compiled_cte_output_columns: tuple[str, ...] | None = None
        self._compiled_cte_column_type_hints: SqlColumnTypeHints | None = None
        self._after_refs = config.after_refs
        self._use_context_permission_anchors = config.use_context_permission_anchors
        self._permission_anchor_refs: frozenset[str] = frozenset()

    def lower(self: VersionedSelectOneStep[T], ctx: LoweringContext) -> list[ServerPlanStep[Any]]:
        from l2055_lazy_result.lazy_param import server_value_deps

        self._permission_anchor_refs = (
            frozenset(
                ref
                for value in (ctx.lazy_revision, ctx.lazy_branch, ctx.lazy_branch_tip_materialization)
                for ref in server_value_deps(value)
            )
            if self._use_context_permission_anchors
            else frozenset()
        )
        return [self]

    def dependencies(self: VersionedSelectOneStep[T]) -> frozenset[str]:
        from l2055_lazy_result.lazy_param import server_value_deps

        deps: set[str] = set(server_value_deps(self._sys_id))
        if self._branch_ref_id is not None:
            deps.add(str(self._branch_ref_id))
        elif self._branch_id is not None:
            deps.update(server_value_deps(self._branch_id))
        if self._user_id_ref_id is not None:
            deps.add(str(self._user_id_ref_id))
        if self._permission_context_ref is not None:
            deps.add(str(self._permission_context_ref))
        deps.update(str(ref) for ref in self._after_refs)
        deps.update(self._permission_anchor_refs)
        return frozenset(deps)

    def sql_visible_dependencies(self: VersionedSelectOneStep[T]) -> frozenset[str]:
        from l2055_lazy_result.lazy_param import server_value_deps

        deps: set[str] = set(server_value_deps(self._sys_id))
        if self._branch_ref_id is not None:
            deps.add(str(self._branch_ref_id))
        elif self._branch_id is not None:
            deps.update(server_value_deps(self._branch_id))
        if self._user_id_ref_id is not None:
            deps.add(str(self._user_id_ref_id))
        if self._permission_context_ref is not None:
            deps.add(str(self._permission_context_ref))
        deps.update(self._permission_anchor_refs)
        return frozenset(ref_id for ref_id in deps if not ref_id.partition(".")[0].startswith("seed_"))

    @property
    def level(self: VersionedSelectOneStep[T]) -> int:
        return 0

    def result_cardinality(self: VersionedSelectOneStep[T]) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self: VersionedSelectOneStep[T]) -> bool:
        return True

    def step_tags(self: VersionedSelectOneStep[T]) -> frozenset[str]:
        return frozenset({"select_one", "grammar"})

    def supports_sql_batch_transport(self: VersionedSelectOneStep[T]) -> bool:
        # Multitable polymorphic select-one compiles through auxiliary UNION CTEs.
        # SQLite compound statement batching currently drops those nested CTEs,
        # so keep these reads as standalone statements.
        from impl.common.l2100_sql_grammar.domain.polymorphism.multitable_cte import (
            get_multitable_polymorphic_source_models,
        )

        return not bool(get_multitable_polymorphic_source_models(self._model_cls))

    def cte_publication_contract(self: VersionedSelectOneStep) -> CtePublicationContract:
        columns = tuple(dict.fromkeys((*_select_one_columns([str(column) for column in self._common_columns]),)))
        column_type_hints = _versioned_sparse_cte_type_hints(self._model_cls, columns)
        if self._compiled_cte_output_columns is not None:
            columns = self._compiled_cte_output_columns
        if self._compiled_cte_column_type_hints is not None:
            column_type_hints = self._compiled_cte_column_type_hints
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        contract_columns = tuple(str(column) for column in columns)
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=contract_columns,
            column_type_hints=column_type_hints,
            optional_columns=(
                frozenset()
                if self._include_deleted
                else frozenset({"sys_deleted", "sys_revision_id", "sys_staged_commit_id"}) & set(contract_columns)
            ),
            relation_contract=_versioned_select_one_relation_contract(self._model_cls, contract_columns),
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
            empty_result_allowed=True,
            scalar_control_kind=(ScalarControlKind.TERMINAL_VALUE if _EXISTENCE_COLUMN.to_row_key() in contract_columns else None),
            scalar_value_column=(_EXISTENCE_COLUMN if _EXISTENCE_COLUMN.to_row_key() in contract_columns else None),
        )

    def always_publishes_executor_visible_binding(self) -> bool:
        return True

    def tables_read(self: VersionedSelectOneStep[T]) -> frozenset[str]:
        from l1000_schema.table_utils import get_table_name

        table_names = derive_versioned_table_names(VersionedBaseTableName(get_table_name(self._model_cls)))
        sparse_table_name = str(table_names.sparse)
        return frozenset({str(self._staged_table_name), str(self._tip_table_name), sparse_table_name})

    def _inline_large_columns_in_base_compile(self: VersionedSelectOneStep[T]) -> bool:
        return True

    def requires_prior_statement_visibility_after_writes(self: VersionedSelectOneStep[T]) -> frozenset[str]:
        return self.tables_read() - frozenset({str(self._staged_table_name)})

    def staged_read_descriptor(self: VersionedSelectOneStep[T]) -> StagedReadRequirement | None:
        branch_scope_token = self._branch_scope_token or opaque_scope_token(self._branch_id)
        return StagedReadRequirement(
            source_keys=(
                StagedSourceKey(
                    staged_table_name=str(self._staged_table_name),
                    branch_scope_token=branch_scope_token,
                ),
            ),
            scope=PublishScopeDescriptor(
                kind="branch",
                branch_scope_token=branch_scope_token,
            ),
        )

    def tables_written(self: VersionedSelectOneStep[T]) -> frozenset[str]:
        return frozenset()

    def compile(
        self: VersionedSelectOneStep[T],
        ctx: CompilationContext,
    ) -> CompiledStep[T | None]:
        """Compile to SqlStagedTipUnionLookup. No registry/transaction access."""
        from impl.common.l2070_server_plan.steps._compile_policy_read import compile_symbolic_policy_read

        dispatched = compile_symbolic_policy_read(ctx, self.compile)
        if dispatched is not None:
            return dispatched
        from impl.common.l2070_server_plan.steps._query_helper_compile import (
            bind_staged_visibility_filter_to_branch,
            effective_versioned_branch_id,
        )

        branch_ref_id = self._branch_ref_id
        if branch_ref_id is None and isinstance(self._branch_id, ScalarServerRef):
            raw_branch_ref_id = self._branch_id.ref_id
            if raw_branch_ref_id is not None:
                branch_ref_id = ServerPlanRefId(raw_branch_ref_id)
        branch_cte_ref = None if branch_ref_id is None else ctx.cte_refs.get(str(branch_ref_id))
        effective_branch_id = effective_versioned_branch_id(
            ctx=ctx,
            resolved_branch_id=self._branch_id if isinstance(self._branch_id, str) else None,
            branch_cte_ref=branch_cte_ref,
            branch_ref_id=None if branch_ref_id is None else str(branch_ref_id),
        )
        if effective_branch_id is None:
            msg = "VersionedSelectOneStep requires branch_id or branch_ref_id in step config"
            raise ValueError(msg)

        model_cls = self._model_cls
        staged_table_name: Any = ctx.staged_source_cte_by_table.get(
            str(self._staged_table_name),
            str(self._staged_table_name),
        )
        tip_table_name: Any = self._tip_table_name
        from impl.common.l7050_versioned_schema_builder.polymorphic_field_helper import (
            get_all_select_columns,
        )

        model_select_columns: list[SqlColumnName] = []
        for field_name in get_all_select_columns(model_cls):
            try:
                db_column = _model_field_db_column(model_cls, field_name)
            except (AttributeError, ValueError):
                db_column = field_name
            model_select_columns.append(SqlColumnName(db_column))
        common_columns: Any = tuple(
            dict.fromkeys((*self._common_columns, *model_select_columns)),
        )
        cte_definitions: tuple[tuple[str, Any], ...] = ()
        multitable_sparse_cte_name: str | None = None
        cte_info = _build_multitable_merged_ctes_for_select_one(
            model_cls,
            ctx,
            [str(column) for column in common_columns],
        )
        if cte_info is not None:
            tip_table_name, staged_table_name, common_columns, cte_definitions = cte_info
            if not ctx.branch_tip_materialized:
                sparse_cte_info = _build_multitable_sparse_cte_for_select_one(model_cls, ctx)
                if sparse_cte_info is not None:
                    multitable_sparse_cte_name = sparse_cte_info[0]
                    cte_definitions = (*cte_definitions, *sparse_cte_info[1])
        lookup_columns = _select_one_columns([str(column) for column in common_columns])
        selected_columns = lookup_columns
        if self._include_deleted:
            lookup_columns = list(
                dict.fromkeys(
                    (
                        *lookup_columns,
                        "branch_id",
                        "sys_staged_commit_id",
                        "sys_revision_id",
                    ),
                ),
            )
            selected_columns = [*lookup_columns, "sys_deleted"]
        effective_ctx = _effective_select_one_materialization_ctx(
            bind_staged_visibility_filter_to_branch(ctx, effective_branch_id),
        )
        stmt = _compile_versioned_select_one_stmt(
            self._sys_id,
            model_cls=model_cls,
            staged_table_name=str(staged_table_name),
            tip_table_name=str(tip_table_name),
            common_columns=lookup_columns,
            branch_id=effective_branch_id,
            type_ids=_effective_type_ids_for_model(
                model_cls,
                list(self._type_ids) if self._type_ids is not None else None,
            ),
            multitable_sparse_cte_name=multitable_sparse_cte_name,
            ctx=effective_ctx,
        )
        stmt = _wrap_versioned_select_with_permissions(
            model_cls,
            stmt,
            effective_ctx,
            selected_columns=selected_columns,
            user_id_ref_id=self._user_id_ref_id,
            permission_bypass=self._permission_bypass,
            fallback_branch_id_sql=lower_scalar_source(
                effective_branch_id,
                effective_ctx,
                default_field="branch_id",
            ),
            permission_context_ref=self._permission_context_ref,
            permission_context_type=self._permission_context_type,
        )
        if not self._include_deleted:
            # The staged+tip union projects the staged-latest row even when it
            # is a tombstone; filter it in SQL so both the step result and any
            # published CTE consumers see the row as absent.
            from impl.common.l2100_sql_grammar.tree.clauses import SqlSubqueryTableRef

            stmt = SqlSelect(
                select=SqlSelectList(
                    [SqlColumnRef(SqlColumnName(column)) for column in selected_columns],
                ),
                from_clause=SqlSubqueryTableRef(stmt, SqlTableName("_select_one_visible")),
                where=SqlWhereClause(
                    SqlUnaryOp(UnaryOp.NOT, SqlColumnRef(SqlColumnName("sys_deleted"))),
                ),
                limit=1,
            )
        if cte_definitions:
            from impl.common.l2070_server_plan.steps._compile_versioned import (
                _wrap_query_renderable_with_ctes,
            )

            stmt = _wrap_query_renderable_with_ctes(
                SimpleNamespace(sql_cte_definitions=cte_definitions),
                stmt,
            )
        output_shape = _select_one_output_shape(
            ctx,
            model_cls,
            declared_outputs=tuple(selected_columns),
        )
        output_shape = _output_shape_reordered_to_columns(output_shape, selected_columns)
        context_revision_aux = _auxiliary_cte_for_scalar_ref(ctx.lazy_revision, ctx)
        context_revision_auxiliary_ctes = (context_revision_aux,) if context_revision_aux is not None else ()
        staged_source_binding = next(
            (
                binding
                for binding in ctx.cte_refs.values()
                if str(binding.ref_id) == str(staged_table_name) and binding.auxiliary_query is not None
            ),
            None,
        )
        staged_source_auxiliary_ctes: tuple[SqlCteDefinitionInput, ...] = ()
        if staged_source_binding is not None:
            staged_source_query = staged_source_binding.auxiliary_query
            assert staged_source_query is not None
            staged_source_auxiliary_ctes = ((staged_source_binding.ref_id, staged_source_query),)
        compiled: CompiledStep[T | None] = CompiledStep(
            grammar=stmt,
            closed_post_op=CompiledPostOp.materialize(
                ResultMaterializationSpec(
                    behavior=PostOpBehavior.TERMINAL_OBJECT,
                    inline_large_column_query_config=InlineLargeColumnQueryMaterializationConfig(
                        model_cls=model_cls,
                        defer_large_columns=False,
                        result_mode="first",
                        raw_mode=False,
                        projected_columns=tuple(selected_columns),
                    ),
                ),
            ),
            needs_returning=True,
            auxiliary_ctes=_combine_auxiliary_ctes(
                cte_definitions,
                staged_source_auxiliary_ctes,
                collect_dependency_auxiliary_ctes(ctx, self.dependencies()),
                context_revision_auxiliary_ctes,
                _permission_user_auxiliary_ctes(ctx, self._user_id_ref_id),
                _permission_context_auxiliary_ctes(ctx, self._permission_context_ref),
            ),
            output_shape=output_shape,
            result_relation=DeclaredResultRelation.from_output_shape(output_shape),
            column_type_hints=_versioned_select_one_cte_type_hints(model_cls, output_shape.cte_output_columns),
        )
        if self._inline_large_columns_in_base_compile():
            compiled = wrap_compiled_sql_with_inline_large_columns(
                compiled,
                model_cls=model_cls,
                force_inline=True,
            )
        assert compiled.output_shape is not None
        self._compiled_cte_output_columns = compiled.output_shape.cte_output_columns
        self._compiled_cte_column_type_hints = compiled.column_type_hints
        self._cte_publication_contract_cache_valid = False
        self._publication_contract_cache_valid = False
        return compiled


class VersionedReadSelectOneStep[T](SqlRelationPublisherStep[T | None]):
    """L0: Versioned select_one at a specific revision via SqlSelectSparseSingleObject.

    Used by the read-path (SyncVersionedReadTransaction). Queries the sparse table
    with revision validity window filtering. Compile authority comes only from
    constructor inputs plus ``CompilationContext``/``ctx.cte_refs``.
    """

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        sys_id: ScalarServerRef[SysId],
        config: _VersionedReadSelectOneConfig,
    ) -> None:
        super().__init__(ref_id)
        self._model_cls = model_cls
        self._sys_id = sys_id
        self._sparse_table_name = config.sparse_table_name
        self._policy_ref_id = config.policy_ref_id
        self._historical_snapshot = config.historical_snapshot
        self._after_refs = config.after_refs | (frozenset({config.policy_ref_id}) if config.policy_ref_id is not None else frozenset())
        self._branch_id = config.branch_id
        self._branch_ref_id = config.branch_ref_id
        self._revision_ref = config.revision_ref
        self._revision_id = config.revision_id
        self._permission_historical = config.permission_historical
        self._type_ids = config.type_ids
        self._user_id_ref_id = config.user_id_ref_id
        self._permission_bypass = config.permission_bypass
        self._include_deleted = config.include_deleted
        self._permission_context_ref = config.permission_context_ref
        self._permission_context_type = config.permission_context_type
        self._compiled_cte_output_columns: tuple[str, ...] | None = None
        self._compiled_cte_column_type_hints: SqlColumnTypeHints | None = None

    @property
    def level(self: VersionedReadSelectOneStep[T]) -> int:
        return 0

    def result_cardinality(self: VersionedReadSelectOneStep[T]) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self: VersionedReadSelectOneStep[T]) -> bool:
        return True

    def step_tags(self: VersionedReadSelectOneStep[T]) -> frozenset[str]:
        return frozenset({"select_one", "grammar"})

    def tables_read(self: VersionedReadSelectOneStep[T]) -> frozenset[str]:
        from impl.common.l2070_server_plan.steps._versioned_routing import get_versioned_read_info

        info = get_versioned_read_info(self._model_cls)
        return frozenset({str(self._sparse_table_name), info.staged_table, info.tip_table})

    def tables_written(self: VersionedReadSelectOneStep[T]) -> frozenset[str]:
        return frozenset()

    def _inline_large_columns_in_base_compile(self: VersionedReadSelectOneStep[T]) -> bool:
        return True

    def dependencies(self: VersionedReadSelectOneStep[T]) -> frozenset[str]:
        deps: set[str] = {str(ref) for ref in self._after_refs}
        if self._branch_ref_id is not None:
            deps.add(str(self._branch_ref_id))
        if self._user_id_ref_id is not None:
            deps.add(str(self._user_id_ref_id))
        if self._permission_context_ref is not None:
            deps.add(str(self._permission_context_ref))
        deps.update(self._sys_id.dependencies())
        if self._revision_ref is not None:
            deps.update(self._revision_ref.dependencies())
        return frozenset(deps)

    def imported_dependency_refs(self: VersionedReadSelectOneStep[T]) -> frozenset[ServerPlanRefId]:
        """Declare version-context refs that may originate in an earlier plan flush."""
        refs: set[str] = {str(ref) for ref in self._after_refs}
        if self._branch_ref_id is not None:
            refs.add(str(self._branch_ref_id))
        if self._revision_ref is not None:
            refs.update(self._revision_ref.dependencies())
        return frozenset(ServerPlanRefId(ref_id) for ref_id in refs)

    def cte_publication_contract(self: VersionedReadSelectOneStep) -> CtePublicationContract:
        columns = _versioned_sparse_cte_output_columns(
            self._model_cls,
            include_validity_columns=True,
        )
        column_type_hints = _versioned_sparse_cte_type_hints(self._model_cls, columns)
        if self._compiled_cte_output_columns is not None:
            columns = self._compiled_cte_output_columns
        if self._compiled_cte_column_type_hints is not None:
            column_type_hints = self._compiled_cte_column_type_hints
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        contract_columns = tuple(str(column) for column in columns)
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=contract_columns,
            column_type_hints=column_type_hints,
            optional_columns=frozenset(
                column for column in contract_columns if column in {"branch_hash32", "graph_hash32", "source_hash32", "target_hash32"}
            ),
            relation_contract=_versioned_select_one_relation_contract(self._model_cls, contract_columns),
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def compile(
        self: VersionedReadSelectOneStep[T],
        ctx: CompilationContext,
    ) -> CompiledStep[T | None]:
        """Compile to SqlSelectSparseSingleObject. No registry/transaction access."""
        from impl.common.l2070_server_plan.steps._compile_policy_read import compile_symbolic_policy_read

        if self._historical_snapshot:
            ctx = replace(ctx, branch_tip_materialized=False, prefer_tip_strategy=False, lazy_branch_tip_materialization=None)
        else:
            ctx = _effective_select_one_materialization_ctx(ctx)
            dispatched = compile_symbolic_policy_read(ctx, self.compile, policy_ref_id=self._policy_ref_id)
            if dispatched is not None:
                return dispatched
        from impl.common.l2070_server_plan.steps._query_helper_compile import (
            compile_versioned_read_select_one_stmt,
            effective_versioned_branch_id,
        )
        from impl.common.l2070_server_plan.steps._versioned_routing import get_versioned_read_info
        from impl.common.l2070_server_plan.steps.versioned_query_steps import (
            _compile_branch_inputs,
        )

        from l7000_versioned_schema.read_source_policy import is_current_branch_read

        revision_ref = self._revision_ref
        has_explicit_revision_selector = (self._revision_id is not None or revision_ref is not None) and not (
            ctx.prefer_tip_strategy and (is_current_branch_read(ctx) or ctx.selected_branch_policy_ref_id is not None)
        )
        eff_revision_id, eff_revision_ref = _effective_read_revision_id_and_ref(
            self._revision_id,
            revision_ref,
            ctx,
        )
        compile_branch_id, compile_branch_cte_ref = (
            (self._branch_id, None)
            if self._branch_id is not None
            else _compile_branch_inputs(
                ctx,
                self._branch_ref_id,
            )
        )

        model_cls = self._model_cls
        sparse_table_name = self._sparse_table_name
        cte_definitions: tuple[tuple[str, Any], ...] = ()
        staged_table_name: str | None = None
        tip_table_name: str | None = None
        common_columns: Sequence[str] | None = None
        merged_cte_info = (
            _build_multitable_merged_ctes_for_select_one(
                model_cls,
                ctx,
                [str(column) for column in get_versioned_read_info(model_cls).common_columns],
            )
            if ctx.branch_tip_materialized and not has_explicit_revision_selector
            else None
        )
        if merged_cte_info is not None:
            tip_table_name, staged_table_name, common_columns, cte_definitions = merged_cte_info
        elif ctx.branch_tip_materialized and not has_explicit_revision_selector:
            projection = build_read_metadata_plan(model_cls).projection_for(READ_FLAVOR_TIP_MERGED)
            common_columns = tuple(
                dict.fromkeys(
                    (
                        "sys_id",
                        "branch_id",
                        *(field.cte_output_column for field in projection.data_fields),
                    )
                )
            )
        else:
            cte_info = _build_multitable_sparse_cte_for_select_one(model_cls, ctx)
            if cte_info is not None:
                sparse_table_name = SqlTableName(cte_info[0])
                cte_definitions = cte_info[1]
        stmt_ctx = replace(ctx, prefer_tip_merged=False) if has_explicit_revision_selector else ctx
        historical_permissions = has_explicit_revision_selector or (
            self._branch_id is None and self._branch_ref_id is None and (eff_revision_id is not None or eff_revision_ref is not None)
        )
        if self._permission_historical is not None:
            historical_permissions = self._permission_historical
        historical_revision_sql = (
            _compile_versioned_read_revision_expr(eff_revision_id, eff_revision_ref, ctx) if historical_permissions else None
        )
        stmt = compile_versioned_read_select_one_stmt(
            model_cls,
            str(sparse_table_name),
            branch_id=(
                self._branch_id
                if self._branch_id is not None
                else (compile_branch_cte_ref if compile_branch_cte_ref is not None else compile_branch_id)
            ),
            branch_ref_id=str(self._branch_ref_id) if self._branch_ref_id is not None else None,
            revision_ref=cast(ScalarServerRef[object] | None, eff_revision_ref),
            revision_id=eff_revision_id,
            sys_id=cast(ScalarServerRef[object], self._sys_id),
            type_ids=_effective_type_ids_for_model(
                model_cls,
                list(self._type_ids) if self._type_ids is not None else None,
            ),
            include_deleted=self._include_deleted,
            ctx=stmt_ctx,
            ancestor_cte_name=_select_one_ancestor_cte_name(self.ref_id),
            staged_table_name=staged_table_name,
            tip_table_name=tip_table_name,
            common_columns=common_columns,
        )
        split_for_outer_cte = getattr(stmt, "split_for_outer_cte", None)
        ancestry_aux: list[tuple[str, SqlRenderable]] = []
        if callable(split_for_outer_cte):
            ancestry_aux, stmt = cast(
                "tuple[list[tuple[str, SqlRenderable]], SqlRenderable]",
                split_for_outer_cte(),
            )
        stmt = _wrap_versioned_select_with_permissions(
            model_cls,
            stmt,
            ctx,
            user_id_ref_id=self._user_id_ref_id,
            permission_bypass=self._permission_bypass,
            historical=historical_permissions,
            historical_revision_sql=historical_revision_sql,
            fallback_branch_id_sql=effective_versioned_branch_id(
                ctx=ctx,
                resolved_branch_id=None if compile_branch_id is None else str(compile_branch_id),
                branch_cte_ref=compile_branch_cte_ref,
                branch_ref_id=None if self._branch_ref_id is None else str(self._branch_ref_id),
            ),
            permission_context_ref=self._permission_context_ref,
            permission_context_type=self._permission_context_type,
        )
        if cte_definitions:
            from impl.common.l2070_server_plan.steps._compile_versioned import (
                _wrap_query_renderable_with_ctes,
            )

            stmt = _wrap_query_renderable_with_ctes(
                SimpleNamespace(sql_cte_definitions=cte_definitions),
                stmt,
            )

        aux: list[tuple[str, SqlRenderable]] = [*cte_definitions]
        if compile_branch_cte_ref is not None and compile_branch_cte_ref.auxiliary_query is not None:
            aux.append(
                (compile_branch_cte_ref.ref_id, compile_branch_cte_ref.auxiliary_query),
            )
        revision_aux = _auxiliary_cte_for_scalar_ref(revision_ref, ctx)
        if revision_aux is not None and all(ref_id != revision_aux[0] for ref_id, _query in aux):
            aux.append(revision_aux)
        sys_id_aux = _auxiliary_cte_for_scalar_ref(self._sys_id, ctx)
        if sys_id_aux is not None and all(ref_id != sys_id_aux[0] for ref_id, _query in aux):
            aux.append(sys_id_aux)
        permission_user_aux = _permission_user_auxiliary_ctes(ctx, self._user_id_ref_id)
        if permission_user_aux is not None:
            for ref_id, query in permission_user_aux:
                if all(existing_ref_id != ref_id for existing_ref_id, _query in aux):
                    aux.append((ref_id, query))
        permission_context_aux = _permission_context_auxiliary_ctes(
            ctx,
            self._permission_context_ref,
        )
        if permission_context_aux is not None:
            for ref_id, query in permission_context_aux:
                if all(existing_ref_id != ref_id for existing_ref_id, _query in aux):
                    aux.append((ref_id, query))
        aux.extend(ancestry_aux)
        contract = self.cte_publication_contract()
        from l1000_schema.physical_adjuncts import supports_graph_hash32_generated_columns

        physical_contract_columns = tuple(column for column in contract.columns if not column.startswith("__nera_inline_large_column__"))
        selected_columns = (
            physical_contract_columns
            if supports_graph_hash32_generated_columns(ctx.backend_type)
            else tuple(_select_one_columns(list(physical_contract_columns)))
        )
        from impl.common.l2100_sql_grammar.tree.clauses import SqlSubqueryTableRef
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef
        from impl.common.l2100_sql_grammar.tree.statements import SqlSelect

        stmt = SqlSelect(
            select_list=tuple(SqlColumnRef(SqlColumnName(column)) for column in selected_columns),
            from_=SqlSubqueryTableRef(
                stmt,
                SqlTableName("_versioned_read_select_one"),
            ),
            limit=1,
        )
        output_shape = _select_one_output_shape(
            ctx,
            self._model_cls,
            declared_outputs=selected_columns,
        )
        missing_contract_columns = tuple(
            column
            for column in contract.columns
            if column not in output_shape.cte_output_columns and column not in contract.optional_columns
        )
        if missing_contract_columns:
            output_shape = output_shape_with_synthetic_fields(
                output_shape,
                tuple(synthetic_output_field(column) for column in missing_contract_columns),
            )
        if self._include_deleted:
            output_shape = output_shape.with_fields(
                (
                    synthetic_output_field(
                        "deleted",
                        "sys_deleted",
                        role="versioned_tombstone_marker",
                    ),
                ),
            )
        compiled: CompiledStep[T | None] = CompiledStep(
            grammar=stmt,
            closed_post_op=CompiledPostOp.materialize(
                ResultMaterializationSpec(
                    behavior=PostOpBehavior.TERMINAL_OBJECT,
                    inline_large_column_query_config=InlineLargeColumnQueryMaterializationConfig(
                        model_cls=self._model_cls,
                        defer_large_columns=False,
                        result_mode="first",
                        raw_mode=False,
                        projected_columns=None,
                    ),
                ),
            ),
            needs_returning=True,
            auxiliary_ctes=aux or None,
            needs_recursive_with=bool(ancestry_aux),
            output_shape=output_shape,
            result_relation=DeclaredResultRelation.from_output_shape(output_shape),
            column_type_hints=_versioned_select_one_cte_type_hints(self._model_cls, output_shape.cte_output_columns),
        )
        if self._inline_large_columns_in_base_compile():
            wrapped = wrap_compiled_sql_with_inline_large_columns(
                compiled,
                model_cls=self._model_cls,
                force_inline=True,
            )
            assert wrapped.output_shape is not None
            self._compiled_cte_output_columns = wrapped.output_shape.cte_output_columns
            self._compiled_cte_column_type_hints = wrapped.column_type_hints
            self._cte_publication_contract_cache_valid = False
            self._publication_contract_cache_valid = False
            return wrapped
        return compiled


class VersionedSelectOneRawStep(VersionedSelectOneStep[dict[str, Any]]):
    """Write-path versioned select_one returning raw row dicts for spill-aware reads.

    The result is published as a CTE that downstream ``_WrapOptionalRawRowStep``
    filters via ``WHERE NOT sys_deleted``. We therefore must keep the
    versioning system columns (``sys_deleted``, ``sys_revision_id``,
    ``sys_staged_commit_id``) on the raw row so the downstream CTE matches
    the declared ``cte_output_columns``. Polymorphism / tombstone handling
    is still applied; we just don't strip the system columns.
    """

    def publication_products(self: VersionedSelectOneRawStep) -> StepPublicationProducts:
        """Declare the repeatable raw SQL relation separately from runtime materialization."""
        contract = self.cte_publication_contract()
        lineage = contract.relation_contract
        if lineage is None:
            msg = f"{type(self).__name__} requires explicit raw select lineage."
            raise TypeError(msg)
        return StepPublicationProducts(
            sql=RepeatableSqlQueryBinding(
                ref_id=self.ref_id,
                relation=RelationContract(
                    columns=contract.columns,
                    column_type_hints=contract.column_type_hints,
                    optional_columns=contract.optional_columns,
                    empty_result_allowed=contract.empty_result_allowed,
                ),
                lineage=lineage,
            ),
            runtime=NoRuntimePublication(),
        )

    def cte_publication_contract(self: VersionedSelectOneRawStep) -> CtePublicationContract:
        from l1000_schema.large_column import get_large_column_configs

        selected_columns = (
            self._compiled_cte_output_columns
            if self._compiled_cte_output_columns is not None
            else tuple(str(column) for column in _select_one_columns(list(self._common_columns)))
        )
        multitable_columns = (
            build_read_metadata_plan(self._model_cls)
            .projection_for(
                READ_FLAVOR_STAGED_MERGED,
            )
            .cte_output_columns
        )
        base_columns = tuple(
            column
            for column in dict.fromkeys(
                (
                    *selected_columns,
                    *multitable_columns,
                    *_multitable_source_db_columns(self._model_cls),
                    "branch_id",
                    "sys_staged_commit_id",
                    "sys_revision_id",
                    "sys_deleted",
                ),
            )
        )
        inline_large_columns = _inline_large_column_cte_columns(self._model_cls)
        columns = tuple(
            dict.fromkeys(
                (
                    *_without_large_column_transport_columns(
                        self._model_cls,
                        ("__exists", *base_columns),
                    ),
                    *_large_column_pointer_columns(self._model_cls),
                    *inline_large_columns,
                ),
            ),
        )

        def _legacy_cte_column_type_hints(columns: tuple[str, ...]) -> SqlColumnTypeHints:
            typed_base_columns = ("__exists", *base_columns)
            return combine_sql_column_type_hints(
                columns,
                _versioned_select_one_cte_type_hints(self._model_cls, typed_base_columns),
                self._compiled_cte_column_type_hints or SqlColumnTypeHints(),
                *_multitable_source_type_hints(self._model_cls, columns),
                _inline_large_column_cte_type_hints(self._model_cls),
                framework_physical_column_sql_column_type_hints(),
            )

        column_type_hints = _legacy_cte_column_type_hints(columns)
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        contract_columns = tuple(str(column) for column in columns)
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=contract_columns,
            column_type_hints=column_type_hints,
            relation_contract=_versioned_select_one_relation_contract(self._model_cls, contract_columns),
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
            empty_result_allowed=True,
            scalar_control_kind=(ScalarControlKind.TERMINAL_VALUE if _EXISTENCE_COLUMN.to_row_key() in contract_columns else None),
            scalar_value_column=(_EXISTENCE_COLUMN if _EXISTENCE_COLUMN.to_row_key() in contract_columns else None),
        )

    def declares_consumed_rows_reduction(self) -> bool:
        return bool(self._after_refs)

    def publishes_replayable_statement_local_relation(self) -> bool:
        return True

    def _inline_large_columns_in_base_compile(self: VersionedSelectOneRawStep) -> bool:
        return False

    def semantic_publication_columns(self: VersionedSelectOneRawStep) -> tuple[str, ...] | None:
        return self.cte_publication_contract().columns

    def semantic_publication_type_hints(self: VersionedSelectOneRawStep) -> SqlColumnTypeHints | None:
        return self.cte_publication_contract().column_type_hints

    def compile(
        self,
        ctx: CompilationContext,
    ) -> CompiledStep[dict[str, Any] | None]:
        from impl.common.l2100_sql_grammar.tree.clauses import SqlSelectAlias, SqlSelectList
        from impl.common.l2100_sql_grammar.tree.expr_compound import SqlSubquery
        from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlInlineLiteral
        from impl.common.l2100_sql_grammar.tree.identifiers import SqlAliasName
        from impl.common.l2100_sql_grammar.tree.statements import SqlSelect

        from impl.common.l2070_server_plan.steps._compile_policy_read import compile_symbolic_policy_read

        dispatched = compile_symbolic_policy_read(ctx, self.compile)
        if dispatched is not None:
            return dispatched
        base_compile = cast(Any, VersionedSelectOneStep.compile).__wrapped__
        original_include_deleted = self._include_deleted
        object.__setattr__(self, "_include_deleted", True)
        try:
            compiled = base_compile(self, ctx)
        finally:
            object.__setattr__(self, "_include_deleted", original_include_deleted)
        assert compiled.grammar is not None
        assert compiled.output_shape is not None
        inner_grammar = compiled.grammar
        auxiliary_ctes = compiled.auxiliary_ctes
        needs_recursive_with = compiled.needs_recursive_with
        if isinstance(inner_grammar, SqlOuterCteSplitProtocol):
            inner_auxiliary_ctes, inner_grammar = inner_grammar.split_for_outer_cte()
            if inner_auxiliary_ctes:
                auxiliary_ctes = _combine_auxiliary_ctes(auxiliary_ctes, inner_auxiliary_ctes)
                needs_recursive_with = True
        contract = self.cte_publication_contract()
        transport_columns = tuple(column for column in contract.columns if not column.startswith("__nera_inline_large_column__"))
        wrapped_stmt = SqlSelect(
            SqlSelectList(
                [
                    SqlSelectAlias(SqlInlineLiteral(True), SqlAliasName(_EXISTENCE_COLUMN.to_row_key())),
                    *(
                        SqlColumnRef(
                            SqlColumnName(column),
                            qualifier=SqlAliasName("_selected_row"),
                        )
                        for column in transport_columns
                        if column != _EXISTENCE_COLUMN.to_row_key()
                    ),
                ],
            ),
            SqlSubquery(inner_grammar, alias=SqlAliasName("_selected_row")),
        )
        from l2070_batching.output_shape import CompiledOutputShape

        output_fields = [
            synthetic_output_field(
                column,
                role="exists" if column == _EXISTENCE_COLUMN.to_row_key() else "versioned_raw_transport",
            )
            for column in transport_columns
        ]
        output_shape = CompiledOutputShape(
            tuple(output_fields),
        )
        result_relation = DeclaredResultRelation.from_output_shape(output_shape)
        transport_result_relation = DeclaredResultRelation(
            result_relation.columns,
            terminal_materialization_shape=output_shape.cte_output_columns,
        )
        raw_compiled = replace(
            compiled,
            grammar=wrapped_stmt,
            auxiliary_ctes=auxiliary_ctes,
            compiled_sql_publication=compiled_repeatable_sql_publication(
                ref_id=self.ref_id,
                query=wrapped_stmt,
                contract=contract,
            ),
            needs_recursive_with=needs_recursive_with,
            column_type_hints=combine_sql_column_type_hints(
                output_shape.cte_output_columns,
                contract.column_type_hints,
                _versioned_select_one_cte_type_hints(self._model_cls, output_shape.cte_output_columns),
                _inline_large_column_cte_type_hints(self._model_cls),
                framework_physical_column_sql_column_type_hints(),
            ),
            closed_post_op=query_first_row_post_op(
                strict_one=False,
                model_cls=None,
            ),
            output_shape=output_shape,
            result_relation=transport_result_relation,
        )
        return wrap_compiled_sql_with_inline_large_columns(
            raw_compiled,
            model_cls=self._model_cls,
            force_inline=True,
        )


def _versioned_read_select_one_raw_transport_columns(
    model_cls: type[DatabaseObjectRow[SysId]],
) -> tuple[str, ...]:
    """Return the canonical raw select-one publication order."""
    from l1000_schema.large_column import get_large_column_configs

    support_only_columns = {
        "branch_hash32",
        "branch_ord",
        "graph_hash32",
        "source_hash32",
        "target_hash32",
        "sys_revision_id",
        "sys_staged_commit_id",
        "sys_valid_from_revision_id",
        "sys_valid_from_seq",
        "sys_valid_to_revision_id",
        "sys_valid_to_seq",
        "deleted",
    }
    if get_fts_config(model_cls) is None:
        support_only_columns.update({"sys_fts_hash_short", "sys_fts_hash_high"})
    sparse_columns = tuple(
        dict.fromkeys(
            (
                *(column for column in _versioned_sparse_cte_output_columns(model_cls) if column not in support_only_columns),
                *(column for column in _multitable_source_db_columns(model_cls) if column not in support_only_columns),
            ),
        ),
    )
    from impl.common.l7050_versioned_schema_builder.polymorphic_widening import (
        get_polymorphic_table_root_class,
    )

    table_root = get_polymorphic_table_root_class(model_cls)
    if table_root is not None and table_root is not model_cls:
        concrete_columns = {str(get_db_column_name(model_cls, DynamicFieldName(field_name))) for field_name in model_cls.model_fields}
        sparse_columns = tuple(
            column for column in sparse_columns if column in concrete_columns or column.startswith("__nera_inline_large_column__")
        )
    base_columns = _without_large_column_transport_columns(
        model_cls,
        tuple(column for column in sparse_columns if column != "sys_deleted"),
    )
    return tuple(
        dict.fromkeys(
            (
                *base_columns,
                "sys_deleted",
                *_large_column_pointer_columns(model_cls),
                *_inline_large_column_cte_columns(model_cls),
            ),
        ),
    )


class VersionedReadSelectOneRawStep(VersionedReadSelectOneStep[dict[str, Any]]):
    """Historical versioned select_one returning raw row dicts for spill-aware reads.

    Downstream ``_WrapOptionalRawRowStep`` filters the published CTE with
    ``WHERE NOT sys_deleted``. Preserve the versioning system columns on the
    raw row so the CTE schema matches ``cte_output_columns`` and the
    downstream filter can resolve ``sys_deleted``.
    """

    def reads_explicit_historical_revision(self: VersionedReadSelectOneRawStep) -> bool:
        return True

    def cte_publication_contract(self: VersionedReadSelectOneRawStep) -> CtePublicationContract:
        sparse_columns = _versioned_sparse_cte_output_columns(self._model_cls)
        columns = _versioned_read_select_one_raw_transport_columns(self._model_cls)

        def _legacy_cte_column_type_hints(columns: tuple[str, ...]) -> SqlColumnTypeHints:
            return combine_sql_column_type_hints(
                columns,
                _versioned_sparse_cte_type_hints(self._model_cls, sparse_columns),
                *_multitable_source_type_hints(self._model_cls, columns),
                _inline_large_column_cte_type_hints(self._model_cls),
                framework_physical_column_sql_column_type_hints(),
            )

        column_type_hints = _legacy_cte_column_type_hints(columns)
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        contract_columns = tuple(str(column) for column in columns)
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=contract_columns,
            column_type_hints=column_type_hints,
            relation_contract=_versioned_select_one_relation_contract(self._model_cls, contract_columns),
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def semantic_publication_columns(self: VersionedReadSelectOneRawStep) -> tuple[str, ...] | None:
        return None

    def _inline_large_columns_in_base_compile(self: VersionedReadSelectOneRawStep) -> bool:
        return False

    def semantic_publication_type_hints(self: VersionedReadSelectOneRawStep) -> SqlColumnTypeHints | None:
        return None

    def compile(
        self,
        ctx: CompilationContext,
    ) -> CompiledStep[dict[str, Any] | None]:
        from impl.common.l2100_sql_grammar.tree.clauses import SqlSelectAlias, SqlSelectList
        from impl.common.l2100_sql_grammar.tree.expr_compound import SqlSubquery
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef
        from impl.common.l2100_sql_grammar.tree.identifiers import SqlAliasName
        from impl.common.l2100_sql_grammar.tree.statements import SqlSelect

        from impl.common.l2070_server_plan.steps._compile_policy_read import compile_symbolic_policy_read

        if not self._historical_snapshot:
            dispatched = compile_symbolic_policy_read(ctx, self.compile, policy_ref_id=self._policy_ref_id)
            if dispatched is not None:
                return dispatched
        base_compile = cast(Any, VersionedReadSelectOneStep.compile).__wrapped__
        original_include_deleted = self._include_deleted
        object.__setattr__(self, "_include_deleted", True)
        try:
            compiled = base_compile(self, ctx)
        finally:
            object.__setattr__(self, "_include_deleted", original_include_deleted)

        assert compiled.grammar is not None
        inner_grammar = compiled.grammar
        auxiliary_ctes = compiled.auxiliary_ctes
        needs_recursive_with = compiled.needs_recursive_with
        if isinstance(inner_grammar, SqlOuterCteSplitProtocol):
            inner_auxiliary_ctes, inner_grammar = inner_grammar.split_for_outer_cte()
            if inner_auxiliary_ctes:
                auxiliary_ctes = _combine_auxiliary_ctes(
                    auxiliary_ctes,
                    inner_auxiliary_ctes,
                )
                needs_recursive_with = True
        selected_alias = SqlAliasName("_selected_row")
        contract_columns = self.cte_publication_contract().columns
        transport_contract_columns = tuple(column for column in contract_columns if not column.startswith("__nera_inline_large_column__"))
        output_shape = CompiledOutputShape(
            tuple(synthetic_output_field(column, role="versioned_raw_transport") for column in transport_contract_columns),
        )
        result_relation = DeclaredResultRelation.from_output_shape(output_shape) if output_shape is not None else compiled.result_relation
        materializer_relation = (
            DeclaredResultRelation(
                result_relation.columns,
                terminal_materialization_shape=output_shape.cte_output_columns,
            )
            if result_relation is not None and output_shape is not None
            else result_relation
        )
        source_column_by_contract_column = {
            "revision_id": "sys_revision_id",
            "staged_commit_id": "sys_staged_commit_id",
            "deleted": "sys_deleted",
        }
        exact_projection = SqlSelect(
            SqlSelectList(
                [
                    SqlSelectAlias(
                        SqlColumnRef(
                            SqlColumnName(source_column_by_contract_column.get(column, column)),
                            qualifier=selected_alias,
                        ),
                        SqlAliasName(column),
                    )
                    for column in transport_contract_columns
                ],
            ),
            SqlSubquery(inner_grammar, alias=selected_alias),
        )
        raw_compiled = replace(
            compiled,
            grammar=exact_projection,
            auxiliary_ctes=auxiliary_ctes,
            needs_recursive_with=needs_recursive_with,
            closed_post_op=query_first_row_post_op(
                strict_one=False,
                model_cls=None,
            ),
            output_shape=output_shape,
            result_relation=materializer_relation,
            column_type_hints=(
                self.cte_publication_contract().column_type_hints.filtered(
                    set(output_shape.cte_output_columns),
                )
                if output_shape is not None
                else compiled.column_type_hints
            ),
        )
        result = wrap_compiled_sql_with_inline_large_columns(
            raw_compiled,
            model_cls=self._model_cls,
            force_inline=True,
        )
        if self._historical_snapshot:
            from impl.common.l2100_sql_grammar.cte_definition_copy import tree_cte_definition
            from impl.common.l2100_sql_grammar.domain.versioning.policy_dispatched_read import SqlHistoricalRead

            result_grammar = result.grammar
            assert isinstance(result_grammar, SqlRenderable)
            result = replace(
                result,
                grammar=SqlHistoricalRead(result_grammar),
                auxiliary_ctes=tuple(
                    replace(
                        tree_cte_definition(definition),
                        query=SqlHistoricalRead(tree_cte_definition(definition).query),
                    )
                    for definition in result.auxiliary_ctes or ()
                ),
            )
        return result

