        required_error_message=required_error_message,
    )


def _build_query_first_hydrated_post_op(
    model_cls: type[DatabaseObjectRow],
    *,
    strict_one: bool,
    select_columns: Sequence[object] | None = None,
    projection_output_aliases: Sequence[object] | None = None,
    required_error_message: str | None = None,
) -> CompiledPostOp:
    def _selected_name(column: object) -> str:
        alias = getattr(column, "alias", None)
        if isinstance(alias, str):
            return alias
        name = getattr(column, "name", None)
        if isinstance(name, str):
            return name
        field_name = getattr(column, "field", None)
        if isinstance(field_name, str):
            return field_name
        return str(column)

    selected_names = tuple(_selected_name(col) for col in select_columns) if select_columns else None
    if select_columns and projection_output_aliases and len(projection_output_aliases) == len(select_columns):
        selected_names = tuple(str(alias) for alias in projection_output_aliases)
    return query_first_row_post_op(
        strict_one=strict_one,
        model_cls=model_cls,
        select_columns=selected_names,
        required_error_message=required_error_message,
    )


def _build_query_first_projected_value_post_op(
    model_cls: type[DatabaseObjectRow],
    *,
    column_projection: str,
) -> CompiledPostOp:
    return query_first_projected_value_post_op(
        model_cls=model_cls,
        column_projection=column_projection,
    )


def _query_spec_selects_large_column(
    model_cls: type[DatabaseObjectRow],
    query_spec: QuerySpec[DatabaseObjectRow],
) -> bool:
    from l1000_schema.large_column import get_large_column_configs

    selected_columns = _query_spec_selected_output_columns(model_cls, query_spec)
    if not selected_columns:
        return False
    requested = {output_name for output_name, _db_column, _is_binary in selected_columns}
    requested.update(db_column for _output_name, db_column, _is_binary in selected_columns)
    for config in get_large_column_configs(model_cls):
        if {
            config.column,
            get_db_column_name(model_cls, DynamicFieldName(config.column)),
        }.intersection(requested):
            return True
    return False


def _needs_inline_large_column_hydration(
    model_cls: type[DatabaseObjectRow],
    query_spec: QuerySpec[DatabaseObjectRow],
    *,
    raw_mode: bool,
    force_hydrate_large_columns: bool = False,
) -> bool:
    from l1000_schema.large_column import get_large_column_configs

    if not get_large_column_configs(model_cls):
        return False
    if force_hydrate_large_columns:
        return True
    if bool(getattr(query_spec, "defer_large_columns", False)):
        return False
    if raw_mode:
        if not getattr(query_spec, "select_columns", None):
            return True
        return _query_spec_selects_large_column(model_cls, query_spec)
    if getattr(query_spec, "joins", None):
        return False
    select_columns = getattr(query_spec, "select_columns", None)
    return not select_columns or _query_spec_selects_large_column(model_cls, query_spec)


def _large_column_projected_output_columns(
    model_cls: type[DatabaseObjectRow],
    query_spec: QuerySpec[DatabaseObjectRow],
) -> tuple[str, ...] | None:
    if not getattr(query_spec, "select_columns", None):
        return None
    return tuple(output_name for output_name, _db_column, _is_binary in _query_spec_selected_output_columns(model_cls, query_spec))


def _with_large_column_acquisition_projection(
    model_cls: type[DatabaseObjectRow],
    query_spec: QuerySpec[DatabaseObjectRow],
) -> QuerySpec[DatabaseObjectRow]:
    select_columns = getattr(query_spec, "select_columns", None)
    if not select_columns or not _query_spec_selects_large_column(model_cls, query_spec):
        return query_spec
    return replace(query_spec, select_columns=None)


def _attach_query_spec_prerender_info(
    stmt: SqlRenderable,
    *,
    query_spec: QuerySpec[Any],
    ctx: CompilationContext,
) -> SqlRenderable:
    from impl.common.l2155_query_prerender_cache import analyze_query_prerenderability
    from impl.common.l2200_sql_dialect.sql_connection import (
        AttributedSqlRenderable,
        QueryPrerenderInfo,
        QueryPrerenderShapeMetadata,
    )

    from l1400_types.type_surface_contracts import (
        QueryPrerenderSeam,
        QueryPrerenderShapeKey,
    )

    if not issubclass(query_spec.model_cls, DatabaseObjectRow):
        return stmt

    analysis = analyze_query_prerenderability(
        query_spec,
        mode="select",
        dialect=ctx.sql_render_dialect(),
    )
    info = QueryPrerenderInfo.from_shape(
        QueryPrerenderShapeMetadata(
            exact_shape_key=QueryPrerenderShapeKey(analysis.exact_shape_key),
            family_shape_key=QueryPrerenderShapeKey(analysis.family_shape_key),
            mode="select",
            seam=QueryPrerenderSeam("query_spec"),
        ),
        prerender_cache_hit=False,
        prerender_supported=analysis.is_prerenderable,
    )
    if isinstance(stmt, AttributedSqlRenderable):
        return cast("SqlRenderable", AttributedSqlRenderable(inner=stmt.inner, prerender_info=info))
    return cast("SqlRenderable", AttributedSqlRenderable(inner=stmt, prerender_info=info))


def _require_query_execute_spec(
    query_spec: QuerySpec[DatabaseObjectRow] | None,
    *,
    step_name: str,
) -> QuerySpec[DatabaseObjectRow]:
    if query_spec is not None:
        return query_spec
    msg = f"{step_name}.compile(): no query_spec provided"
    raise NotImplementedError(msg)


def _require_query_grammar(
    grammar: SqlRenderable | None,
    *,
    step_name: str,
    split: bool = False,
) -> SqlRenderable:
    if grammar is not None:
        return grammar
    scope = "split query" if split else "query"
    msg = f"{step_name}.compile(): {scope} compilation produced no grammar"
    raise NotImplementedError(msg)


def _permission_context_ref_auxiliary_ctes(
    context_ref: ServerPlanRefId | None,
    ctx: CompilationContext,
) -> tuple[tuple[str, SqlRenderable], ...]:
    if context_ref is None:
        return ()
    from impl.common.l2070_server_plan.steps.sql_projection import (
        _require_sql_visible_source_cte,
    )
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef
    from impl.common.l2100_sql_grammar.tree.statements import SqlSelect
    from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName, SqlTableName

    context_cte = _require_sql_visible_source_cte(
        ctx,
        context_ref,
        site_name="permission query",
        result_contract="consume the bound session-context relation",
    )
    if str(context_cte.ref_id) == str(context_ref):
        if context_cte.auxiliary_query is None:
            return ()
        return ((str(context_ref), context_cte.auxiliary_query),)
    alias_query = SqlSelect(
        select=[SqlColumnRef(SqlColumnName(column)) for column in context_cte.columns],
        from_=SqlTableName(str(context_cte.ref_id)),
    )
    return ((str(context_ref), alias_query),)


def _permission_context_auxiliary_ctes(
    query_spec: QuerySpec[DatabaseObjectRow],
    ctx: CompilationContext,
) -> tuple[tuple[str, SqlRenderable], ...]:
    return _permission_context_ref_auxiliary_ctes(
        query_spec.permission_context_ref,
        ctx,
    )


def _permission_user_auxiliary_ctes(
    resolved_user_id: object,
) -> tuple[tuple[str, SqlRenderable], ...]:
    from l2070_batching.compilation import CteReference

    if not isinstance(resolved_user_id, CteReference) or resolved_user_id.auxiliary_query is None:
        return ()
    return ((str(resolved_user_id.ref_id), resolved_user_id.auxiliary_query),)


def _merge_auxiliary_ctes(
    *auxiliary_cte_groups: Sequence[CompiledAuxiliaryCteInput] | None,
) -> tuple[CompiledAuxiliaryCteInput, ...] | None:
    merged: list[CompiledAuxiliaryCteInput] = []
    seen_aliases: set[str] = set()
    for auxiliary_ctes in auxiliary_cte_groups:
        if not auxiliary_ctes:
            continue
        for definition in auxiliary_ctes:
            alias = definition[0] if isinstance(definition, tuple) else str(definition.name)
            if alias in seen_aliases:
                continue
            seen_aliases.add(alias)
            merged.append(definition)
    return tuple(merged) if merged else None


def compile_sql_query_execute_step(
    model_cls: type[DatabaseObjectRow],
    query_spec: QuerySpec[DatabaseObjectRow] | None,
    ctx: CompilationContext,
    *,
    raw_mode: bool,
    resolved_user_id: ResolvedPermissionUserId,
    closed_post_op: CompiledPostOp | None,
    step_name: str,
    attach_column_masking: bool = True,
    result_mode: Literal["many", "first", "strict_one"] = "many",
    force_hydrate_large_columns: bool = False,
    permission_action: PermissionAction | None = None,
) -> CompiledStep[Sequence[object]]:
    """Compile the SQL-backed query execute terminal shared by helper steps."""
    query_spec = _require_query_execute_spec(query_spec, step_name=step_name)
    if not raw_mode and bool(getattr(query_spec, "defer_large_columns", False)) and not getattr(query_spec, "select_columns", None):
        msg = "defer_large_columns requires an explicit projection for typed query execution"
        raise ValueError(msg)

    from impl.common.l2070_server_plan.steps._compile_helpers import (
        attach_runtime_permission_grammar,
        compile_query_grammar,
        query_references_private_fields,
    )

    effective_attach_column_masking = attach_column_masking
    has_narrow_output_shape = bool(
        getattr(query_spec, "select_columns", None)
        or getattr(query_spec, "group_by", None)
        or getattr(query_spec, "aggregations", None)
        or getattr(query_spec, "window_functions", None)
    )
    if attach_column_masking and has_narrow_output_shape:
        effective_attach_column_masking = query_references_private_fields(
            query_spec,
            model_cls,
            include_select_columns=True,
        )

    effective_spec = cast(
        "QuerySpec[DatabaseObjectRow]",
        attach_runtime_permission_grammar(
            query_spec,
            model_cls,
            ctx,
            resolved_user_id=resolved_user_id,
            action="read" if permission_action is None else permission_action,
            attach_column_masking=effective_attach_column_masking,
        ),
    )
    effective_spec = _inject_multitable_polymorphic_cte_if_needed(
        effective_spec,
        model_cls=model_cls,
        ctx=ctx,
    )
    needs_inline_large_column_hydration = _needs_inline_large_column_hydration(
        model_cls,
        effective_spec,
        raw_mode=raw_mode,
        force_hydrate_large_columns=force_hydrate_large_columns,
    )
    projected_columns = _large_column_projected_output_columns(model_cls, effective_spec) if needs_inline_large_column_hydration else None
    if needs_inline_large_column_hydration:
        effective_spec = _with_large_column_acquisition_projection(model_cls, effective_spec)
    contract_projection_columns = _query_spec_cte_output_columns(model_cls, effective_spec)
    query_output_shape = (
        _raw_query_execute_output_shape(model_cls, effective_spec)
        if raw_mode and not needs_inline_large_column_hydration
        else _query_execute_output_shape(model_cls, effective_spec)
    )
    if query_output_shape is None and needs_inline_large_column_hydration:
        from l2070_batching.output_shape import CompiledOutputShape, synthetic_output_field

        query_output_shape = CompiledOutputShape(
            tuple(synthetic_output_field(column) for column in contract_projection_columns),
        )
    if query_output_shape is None:
        msg = "QueryExecuteStep must compile with explicit output shape."
        # Query execution must publish explicit shape before batching.
        raise ProgrammingError(msg)
    if raw_mode and not needs_inline_large_column_hydration:
        contract_projection_columns = query_output_shape.cte_output_columns
    from l2070_batching.output_shape import DeclaredResultRelation

    query_result_relation = DeclaredResultRelation.from_output_shape(query_output_shape)
    query_column_type_hints = _query_spec_column_type_hints(
        model_cls,
        effective_spec,
        query_output_shape.cte_output_columns,
    )
    if raw_mode and result_mode == "many" and not needs_inline_large_column_hydration:
        from impl.common.l2070_server_plan.steps._query_spec_chunking import (
            split_query_spec_on_oversized_literal_in,
        )

        split_specs = split_query_spec_on_oversized_literal_in(
            effective_spec,
            backend_type=ctx.backend_type,
            preserve_read_semantics=True,
        )
        if split_specs is not None:
            from impl.common.l2100_sql_grammar.domain.infra.stmt_compound_write import (
                SqlStatementBatch,
                SqlStatementBatchCategory,
            )

            statements: list[SqlRenderable] = []
            params_per_stmt: list[tuple[Any, ...] | None] = []
            external_params_first: list[bool] = []
            for split_spec in split_specs:
                split_compiled = compile_query_grammar(
                    split_spec,
                    model_cls,
                    ctx,
                    is_count=False,
                    contract_projection_columns=_raw_query_execute_output_shape(
                        model_cls,
                        split_spec,
                    ).cte_output_columns,
                    output_shape=query_output_shape,
                    result_relation=query_result_relation,
                    column_type_hints=query_column_type_hints,
                )
                split_grammar = _require_query_grammar(
                    split_compiled.grammar,
                    step_name=step_name,
                    split=True,
                )
                statements.append(
                    _attach_query_spec_prerender_info(
                        split_grammar,
                        query_spec=split_spec,
                        ctx=ctx,
                    ),
                )
                params_per_stmt.append(split_compiled.params or None)
                external_params_first.append(split_compiled.external_params_first)

            if closed_post_op is not None:
                final_post_op = closed_post_op
            elif raw_mode or _query_spec_has_computed_outputs(effective_spec):
                final_post_op = row_dicts_post_op()
            else:
                final_post_op = build_query_execute_standard_post_op(
                    model_cls,
                    raw_mode=raw_mode,
                    select_columns=getattr(effective_spec, "select_columns", None),
                    projection_output_aliases=getattr(effective_spec, "projection_output_aliases", None),
                )
            return CompiledStep(
                grammar=SqlStatementBatch(
                    statements,
                    category=SqlStatementBatchCategory.BUDGET_SPLIT,
                    params_per_stmt=params_per_stmt,
                    external_params_first=external_params_first,
                    needs_returning_per_stmt=[True] * len(statements),
                    collect_results_per_stmt=[True] * len(statements),
                ),
                needs_returning=True,
                closed_post_op=final_post_op,
                output_shape=query_output_shape,
                result_relation=query_result_relation,
                column_type_hints=query_column_type_hints,
                auxiliary_ctes=_merge_auxiliary_ctes(
                    _permission_context_auxiliary_ctes(effective_spec, ctx),
                    _permission_user_auxiliary_ctes(resolved_user_id),
                ),
            )
    compiled = compile_query_grammar(
        effective_spec,
        model_cls,
        ctx,
        is_count=False,
        contract_projection_columns=contract_projection_columns,
        output_shape=query_output_shape,
        result_relation=query_result_relation,
        column_type_hints=query_column_type_hints,
    )
    compiled_grammar = _require_query_grammar(compiled.grammar, step_name=step_name)

    if needs_inline_large_column_hydration:
        from impl.common.l2070_server_plan.steps.large_column_read import (
            inline_large_column_query_post_op,
        )

        final_post_op = inline_large_column_query_post_op(
            model_cls=model_cls,
            query_spec=effective_spec,
            result_mode=result_mode,
            raw_mode=raw_mode,
            projected_columns=projected_columns,
        )
    elif closed_post_op is None and (raw_mode or _query_spec_has_computed_outputs(effective_spec)):
        final_post_op = row_dicts_post_op()
    elif closed_post_op is None:
        final_post_op = build_query_execute_standard_post_op(
            model_cls,
            raw_mode=raw_mode,
            select_columns=getattr(effective_spec, "select_columns", None),
            projection_output_aliases=getattr(effective_spec, "projection_output_aliases", None),
        )
    else:
        final_post_op = closed_post_op
    compiled_grammar = _attach_query_spec_prerender_info(
        compiled_grammar,
        query_spec=effective_spec,
        ctx=ctx,
    )
    output_shape = compiled.output_shape
    if output_shape is None:
        msg = "QueryExecuteStep must compile with explicit output shape."
        # Query execution must publish complete result metadata.
        raise ProgrammingError(msg)
    column_type_hints = compiled.column_type_hints
    if column_type_hints is None:
        msg = "QueryExecuteStep must compile with explicit SQL column type hints."
        # Query execution must publish complete result metadata.
        raise ProgrammingError(msg)
    result_relation = compiled.result_relation
    if result_relation is None:
        msg = "QueryExecuteStep must compile with explicit result relation."
        # Query execution must publish complete result metadata.
        raise ProgrammingError(msg)
    compiled_step: CompiledStep[Any] = CompiledStep(
        grammar=compiled_grammar,
        params=compiled.params,
        needs_returning=compiled.needs_returning,
        external_params_first=compiled.external_params_first,
        provenance_manifest=compiled.provenance_manifest,
        runtime_ref_ids=compiled.runtime_ref_ids,
        auxiliary_ctes=_merge_auxiliary_ctes(
            compiled.auxiliary_ctes,
            _permission_context_auxiliary_ctes(effective_spec, ctx),
            _permission_user_auxiliary_ctes(resolved_user_id),
        ),
        closed_post_op=final_post_op,
        output_shape=output_shape,
        result_relation=result_relation,
        column_type_hints=column_type_hints,
    )
    if needs_inline_large_column_hydration:
        from impl.common.l2070_server_plan.steps.large_column_read import (
            wrap_compiled_sql_with_inline_large_columns,
        )

        return wrap_compiled_sql_with_inline_large_columns(
            compiled_step,
            model_cls=model_cls,
            force_inline=True,
            include_pointer_columns=True,
        )
    return compiled_step


def _inject_multitable_polymorphic_cte_if_needed(
    query_spec: QuerySpec[DatabaseObjectRow],
    *,
    model_cls: type[DatabaseObjectRow],
    ctx: CompilationContext,
) -> QuerySpec[DatabaseObjectRow]:
    source_models: tuple[type[DatabaseObjectRow], ...] = query_spec.polymorphic_source_models
    if ctx.schema_column_cache:
        source_models = tuple(
            source_model for source_model in source_models if str(get_table_name(source_model)) in ctx.schema_column_cache
        )
    if not source_models or bool(getattr(query_spec, "sql_cte_definitions", None)):
        return query_spec
    planning_catalog = require_planning_catalog(
        ctx,
        site="query_execute.multitable_cte",
    )
    from l7000_versioned_schema.versioned_schema import VersionedObjectRow

    if issubclass(model_cls, VersionedObjectRow):
        return query_spec

    read_shape = planning_catalog.read_metadata_for_model(model_cls)
    projection = align_multitable_read_projection(
        read_shape.projection_for(READ_FLAVOR_QUERY_ROWS),
        source_models,
    )
    cte_name = build_multitable_polymorphic_cte_name(
        get_table_name(model_cls),
        source_tables=tuple(get_table_name(model) for model in source_models),
    )
    cte_definition = build_multitable_polymorphic_cte_definition(
        model_cls,
        source_models,
        cte_name=SqlCteName(cte_name),
        read_projection=projection,
    )
    if cte_definition is None:
        return query_spec
    permission_grammar = query_spec.permission_grammar
    if permission_grammar is not None:
        from impl.common.l2070_server_plan.steps._compile_versioned import (
            _rewrite_permission_qualifiers,
        )

        permission_grammar = _rewrite_permission_qualifiers(
            permission_grammar,
            from_qualifier=get_table_name(model_cls),
            to_qualifier=None,
        )
    return replace(
        query_spec,
        table=cte_name,
        permission_grammar=permission_grammar,
        select_columns=(
            query_spec.select_columns
            if query_spec.select_columns is not None
            else [Expression(field=column) for column in projection.cte_output_columns]
        ),
        sql_cte_definitions=(cte_definition,),
        source_read_projection=projection,
        polymorphic_source_models=(),
        type_filter_types=(),
        type_filter_column=None,
    )


def _query_execute_output_shape(
    model_cls: type[DatabaseObjectRow],
    query_spec: QuerySpec[DatabaseObjectRow],
) -> CompiledOutputShape:
    """Describe explicit query projections for JSON batching."""
    from l2070_batching.output_shape import CompiledOutputShape, output_shape_from_mappings, synthetic_output_field

    if (
        getattr(query_spec, "window_functions", None)
        and not getattr(query_spec, "select_columns", None)
        and not getattr(query_spec, "group_by", None)
        and not getattr(query_spec, "aggregations", None)
    ):
        return CompiledOutputShape(
            tuple(synthetic_output_field(column) for column in _query_spec_cte_output_columns(model_cls, query_spec)),
        )
    output_columns = _query_spec_selected_output_columns(model_cls, query_spec)
    if not output_columns:
        output_columns = _query_spec_computed_output_columns(model_cls, query_spec)

    if not output_columns:
        return CompiledOutputShape(
            tuple(synthetic_output_field(column) for column in _query_spec_cte_output_columns(model_cls, query_spec)),
        )

    return output_shape_from_mappings(output_columns)


def _raw_query_execute_output_shape(
    model_cls: type[DatabaseObjectRow],
    query_spec: QuerySpec[DatabaseObjectRow],
) -> CompiledOutputShape:
    """Describe raw query output using database column keys."""

    from l2070_batching.output_shape import CompiledOutputShape, output_shape_from_mappings, synthetic_output_field

    if (
        getattr(query_spec, "window_functions", None)
        and not getattr(query_spec, "select_columns", None)
        and not getattr(query_spec, "group_by", None)
        and not getattr(query_spec, "aggregations", None)
    ):
        return CompiledOutputShape(
            tuple(synthetic_output_field(column) for column in _query_spec_cte_output_columns(model_cls, query_spec)),
        )
    selected_columns = _query_spec_selected_output_columns(model_cls, query_spec)
    projection_aliases = tuple(
        cast("Sequence[object]", getattr(query_spec, "projection_output_aliases", ()) or ()),
    )
    select_columns = tuple(cast("Sequence[object]", getattr(query_spec, "select_columns", ()) or ()))
    if selected_columns:
        if len(select_columns) == len(selected_columns):
            return output_shape_from_mappings(
                tuple(
                    mapping
                    if isinstance(column, (AliasedField, AliasedExpression, PlanAliasedExpression))
                    else (mapping[1], mapping[1], mapping[2])
                    for column, mapping in zip(select_columns, selected_columns, strict=True)
                ),
            )
        return output_shape_from_mappings(
            tuple((db_column, db_column, is_binary) for _output_name, db_column, is_binary in selected_columns),
        )
    if projection_aliases:
        return CompiledOutputShape(
            tuple(synthetic_output_field(str(alias)) for alias in projection_aliases),
        )
    computed_columns = _query_spec_computed_output_columns(model_cls, query_spec)
    if computed_columns:
        return output_shape_from_mappings(
            tuple((db_column, db_column, is_binary) for _output_name, db_column, is_binary in computed_columns),
        )
    return CompiledOutputShape(
        tuple(synthetic_output_field(column) for column in _query_full_row_output_columns(model_cls, query_spec)),
    )


def _query_spec_has_computed_outputs(query_spec: QuerySpec[DatabaseObjectRow]) -> bool:
    return bool(
        getattr(query_spec, "group_by", None)
        or getattr(query_spec, "aggregations", None)
        or getattr(query_spec, "window_functions", None)
    )


def _required_contract_column_type_hints(
    model_cls: type[DatabaseObjectRow],
    columns: tuple[str, ...],
) -> SqlColumnTypeHints:
    from l2070_batching.sql_column_type_hints import sql_column_type_hints_for_declared_sql_types
    from l5100_fts.fts_config import FTS_HASH_FIELD_SQL_TYPES

    model_hints = model_sql_column_type_hints(model_cls, columns) or SqlColumnTypeHints()
    covered = set().union(*model_hints.as_tuple())
    fts_hash_columns = set(columns) & set(FTS_HASH_FIELD_SQL_TYPES) - covered
    fts_hash_hints = (
        sql_column_type_hints_for_declared_sql_types(
            {SqlColumnName(column): RawSqlText(FTS_HASH_FIELD_SQL_TYPES[column]) for column in sorted(fts_hash_columns)},
        )
        if fts_hash_columns
        else SqlColumnTypeHints()
    )
    covered |= set().union(*fts_hash_hints.as_tuple())
    framework_hints = framework_physical_column_sql_column_type_hints().filtered(
        set(columns) - covered,
    )
    covered |= set().union(*framework_hints.as_tuple())
    logical_version_id_columns = frozenset(
        {"revision_id", "staged_commit_id"} & (set(columns) - covered),
    )
    logical_version_hints = SqlColumnTypeHints(
        uuid_columns=logical_version_id_columns,
    )
    if not framework_hints.has_any() and not fts_hash_hints.has_any() and not logical_version_hints.has_any():
        return model_hints
    return combine_sql_column_type_hints(
        columns,
        model_hints,
        fts_hash_hints,
        framework_hints,
        logical_version_hints,
    )


@pure_lazy
def _field_projection_type_hints(
    model_cls: type[DatabaseObjectRow],
    field_name: str,
    output_column: str,
    *,
    owner: type[DatabaseObjectRow] | None = None,
) -> SqlColumnTypeHints:
    owner_model = owner if owner is not None else model_cls
    if field_name not in owner_model.model_fields:
        field_plan = next(
            (plan for plan in polymorphic_read_field_plans(model_cls) if plan.field_name == field_name),
            None,
        )
        if field_plan is not None:
            owner_model = field_plan.owner_cls
    hints = model_field_sql_column_type_hints(owner_model, {field_name: output_column})
    if hints.covers((output_column,)):
        return hints
    if field_name in {"created_at", "updated_at", "sys_created_at", "sys_updated_at"}:
        return SqlColumnTypeHints(timestamptz_columns=frozenset({output_column}))
    from l1000_schema.large_column import get_large_column_configs, large_column_pointer_name

    pointer_columns = {str(large_column_pointer_name(config.column)) for config in get_large_column_configs(owner_model)}
    if field_name in pointer_columns:
        return SqlColumnTypeHints(text_columns=frozenset({output_column}))
    return hints


@pure_lazy
def _expression_field_type_hints(
    model_cls: type[DatabaseObjectRow],
    expression: Expression,
    output_column: str,
) -> SqlColumnTypeHints | None:
    if expression.function is not None or expression.operator is not None or expression.logical_op is not None:
        return None
    if expression.field is None:
        if output_column not in model_cls.model_fields:
            return None
        declared = _field_projection_type_hints(model_cls, output_column, output_column)
        if expression.value is None or output_column in declared.jsonb_columns:
            return declared
        return None
    owner = getattr(expression, "owner", None)
    owner_model = cast("type[DatabaseObjectRow] | None", owner if isinstance(owner, type) else None)
    return _field_projection_type_hints(
        model_cls,
        expression.field,
        output_column,
        owner=owner_model,
    )


@pure_lazy
def _expression_output_type_hints(
    expression: Expression,
    output_column: str,
) -> SqlColumnTypeHints | None:
    if expression.field is None and expression.function is None and expression.operator is None and expression.logical_op is None:
        return literal_sql_column_type_hints(output_column, expression.value)
    if expression.logical_op is not None or expression.operator in {
        "=",
        "==",
        "!=",
        "<",
        "<=",
        ">",
        ">=",
        "eq",
        "ne",
        "lt",
        "le",
        "gt",
        "ge",
    }:
        return SqlColumnTypeHints(bool_columns=frozenset({output_column}))
    return None


@pure_lazy
def _expression_function_type_hints(
    model_cls: type[DatabaseObjectRow],
    expression: Expression,
    output_column: str,
) -> SqlColumnTypeHints:
    function_name = SqlFunctionName(expression.function) if expression.function is not None else NO_EXPRESSION_FUNCTION_NAME
    value_expression = expression_result_argument(function_name, expression.args)
    if isinstance(value_expression, Expression):
        return (
            _expression_field_type_hints(model_cls, value_expression, output_column)
            or _expression_output_type_hints(value_expression, output_column)
            or _expression_function_type_hints(model_cls, value_expression, output_column)
        )
    return _function_output_type_hints(expression.function, output_column)


@pure_lazy
def _function_output_type_hints(function_name: object, output_column: str) -> SqlColumnTypeHints:
    function = str(function_name).upper()
    if function in {"COUNT", "COUNT_DISTINCT", "ROW_NUMBER", "RANK", "DENSE_RANK", "TABLE_COUNT"}:
        return SqlColumnTypeHints(bigint_columns=frozenset({output_column}))
    if function in {"AVG", "SUM", "STDDEV", "VARIANCE"}:
        return SqlColumnTypeHints(double_columns=frozenset({output_column}))
    if function in {"BOOL_AND", "BOOL_OR", "BOOL_NOT", "BOOL_XOR"}:
        return SqlColumnTypeHints(bool_columns=frozenset({output_column}))
    if function in {
        "UPPER",
        "LOWER",
        "TRIM",
        "LTRIM",
        "RTRIM",
        "CONCAT",
        "SUBSTR",
        "LEFT",
        "RIGHT",
        "REPLACE",
        "REVERSE",
    }:
        return SqlColumnTypeHints(text_columns=frozenset({output_column}))
    if function in {"LENGTH", "YEAR", "MONTH", "DAY", "HOUR", "MINUTE", "SECOND", "DATE_DIFF", "DIFF_SECONDS"}:
        return SqlColumnTypeHints(bigint_columns=frozenset({output_column}))
    if function in {"ABS", "ROUND", "FLOOR", "CEIL", "MOD", "POWER", "SQRT", "LOG", "LN", "EXP"}:
        return SqlColumnTypeHints(double_columns=frozenset({output_column}))
    if function in {"NOW", "CURRENT_TIMESTAMP", "DATE_TRUNC", "ADD_SECONDS"}:
        return SqlColumnTypeHints(timestamptz_columns=frozenset({output_column}))
    if function in {
        "JSON_AGG",
        "JSON_OBJECT_AGG",
        "JSON_BUILD_OBJECT",
        "JSON_BUILD_ARRAY",
        "JSON_GET",
        "JSON_KEYS",
        "TABLE_JSON_AGG",
        "TABLE_JSON_FIRST",
        "TABLE_JSON_OBJECT_AGG",
    }:
        return SqlColumnTypeHints(jsonb_columns=frozenset({output_column}))
    if function in {"JSON_GET_TEXT", "JSON_TYPE"}:
        return SqlColumnTypeHints(text_columns=frozenset({output_column}))
    if function == "JSON_GET_INT":
        return SqlColumnTypeHints(bigint_columns=frozenset({output_column}))
    if function == "JSON_GET_FLOAT":
        return SqlColumnTypeHints(double_columns=frozenset({output_column}))
    if function in {"JSON_GET_BOOL", "JSON_EXISTS", "JSON_CONTAINS"}:
        return SqlColumnTypeHints(bool_columns=frozenset({output_column}))
    return SqlColumnTypeHints(jsonb_columns=frozenset({output_column}))


def _plan_expression_type_hints(
    expression: object,
    output_column: str,
) -> SqlColumnTypeHints:
    if isinstance(expression, PlanColumnRef):
        return _field_projection_type_hints(
            cast("type[DatabaseObjectRow]", expression.model_cls),
            expression.name,
            output_column,
        )
    if isinstance(expression, PlanParamRef):
        return _plan_expression_type_hints(expression.value, output_column)
    if isinstance(expression, PlanBinaryExpression | PlanFunctionExpression):
        return SqlColumnTypeHints(double_columns=frozenset({output_column}))
    if isinstance(expression, PlanCaseExpression):
        branch_hints = tuple(_plan_expression_type_hints(value, output_column) for _predicate, value in expression.whens)
        return combine_sql_column_type_hints(
            (output_column,),
            *branch_hints,
            _plan_expression_type_hints(expression.else_value, output_column),
        )
    if isinstance(expression, bool):
        return SqlColumnTypeHints(bool_columns=frozenset({output_column}))
    if isinstance(expression, int):
        return SqlColumnTypeHints(bigint_columns=frozenset({output_column}))
    if isinstance(expression, float):
        return SqlColumnTypeHints(double_columns=frozenset({output_column}))
    if isinstance(expression, str):
        return SqlColumnTypeHints(text_columns=frozenset({output_column}))
    return SqlColumnTypeHints()


def _query_spec_selected_type_hints(
    model_cls: type[DatabaseObjectRow],
    query_spec: QuerySpec[DatabaseObjectRow] | None,
) -> SqlColumnTypeHints | None:
    if query_spec is None or not getattr(query_spec, "select_columns", None):
        return None
    selected_output_columns = _query_spec_selected_output_columns(model_cls, query_spec)
    columns = tuple(output_name for output_name, _db_column, _is_binary in selected_output_columns)
    if not columns:
        return None
    hints: list[SqlColumnTypeHints] = []
    source_projection = query_spec.source_read_projection
    source_hints = source_projection.sql_column_type_hints() if source_projection is not None else None
    for index, selected in enumerate(query_spec.select_columns or ()):
        output_column = selected_output_columns[index][0]
        source_column: str | None = None
        if isinstance(selected, str):
            source_column = selected
        elif isinstance(selected, Field | AliasedField):
            source_column = selected.name
        elif isinstance(selected, Expression) and selected.field is not None and selected.operator is None and selected.function is None:
            source_column = selected.field
        if source_hints is not None and source_column is not None:
            db_column = str(get_db_column_name(model_cls, DynamicFieldName(source_column)))
            published_hints = source_hints.filtered({db_column})
            if published_hints.covers((db_column,)):
                hints.append(published_hints.rename_column(db_column, output_column))
                continue
        if isinstance(selected, str):
            hints.append(_field_projection_type_hints(model_cls, selected, output_column))
            continue
        if isinstance(selected, Field):
            owner = getattr(selected, "owner", model_cls)
            owner_model = cast("type[DatabaseObjectRow]", owner if isinstance(owner, type) else model_cls)
            hints.append(
                _field_projection_type_hints(
                    model_cls,
                    selected.name,
                    output_column,
                    owner=owner_model,
                )
            )
            continue
        if isinstance(selected, AliasedField):
            hints.append(
                _field_projection_type_hints(
                    model_cls,
                    selected.name,
                    selected.alias,
                    owner=cast("type[DatabaseObjectRow]", selected.owner_model),
                )
            )
            continue
        if isinstance(selected, PlanAliasedExpression):
            hints.append(
                _plan_expression_type_hints(
                    selected.expression,
                    selected.alias,
                ),
            )
            continue
        if isinstance(selected, AliasedExpression):
            expression_hints = _expression_field_type_hints(model_cls, selected.expression, selected.alias)
            expression_output_hints = _expression_output_type_hints(selected.expression, selected.alias)
            hints.append(
                expression_hints
                or expression_output_hints
                or _expression_function_type_hints(model_cls, selected.expression, selected.alias)
            )
            continue
        if isinstance(selected, Expression) and selected.field is not None and selected.function is None and selected.operator is None:
            hints.append(_field_projection_type_hints(model_cls, selected.field, output_column))
    return combine_sql_column_type_hints(columns, *hints)


def _query_spec_computed_type_hints(
    model_cls: type[DatabaseObjectRow],
    query_spec: QuerySpec[DatabaseObjectRow] | None,
) -> SqlColumnTypeHints | None:
    columns = tuple(db_column for _output_name, db_column, _is_binary in _query_spec_computed_output_columns(model_cls, query_spec))
    if not columns or query_spec is None:
        return None
    hints: list[SqlColumnTypeHints] = []
    for index, group_column in enumerate(getattr(query_spec, "group_by", ()) or ()):
        if isinstance(group_column, str):
            hints.append(
                _field_projection_type_hints(
                    model_cls,
                    group_column,
                    get_db_column_name(model_cls, DynamicFieldName(group_column)),
                )
            )
            continue
        if isinstance(group_column, AliasedField):
            hints.append(
                _field_projection_type_hints(
                    model_cls,
                    group_column.name,
                    group_column.alias,
                    owner=cast("type[DatabaseObjectRow]", group_column.owner_model),
                )
            )
            continue
        if isinstance(group_column, Field):
            owner = getattr(group_column, "owner", model_cls)
            owner_model = cast("type[DatabaseObjectRow]", owner if isinstance(owner, type) else model_cls)
            hints.append(
                _field_projection_type_hints(
                    model_cls,
                    group_column.name,
                    get_db_column_name(owner_model, DynamicFieldName(group_column.name)),
                    owner=owner_model,
                )
            )
            continue
        if isinstance(group_column, AliasedExpression):
            expression_hints = _expression_field_type_hints(model_cls, group_column.expression, group_column.alias)
            expression_output_hints = _expression_output_type_hints(group_column.expression, group_column.alias)
            hints.append(
                expression_hints
                or expression_output_hints
                or _expression_function_type_hints(model_cls, group_column.expression, group_column.alias)
            )
            continue
        if isinstance(group_column, Expression):
            output_column = _query_spec_computed_output_columns(model_cls, query_spec)[index][1]
            expression_hints = _expression_field_type_hints(model_cls, group_column, output_column)
            hints.append(
                expression_hints
                if expression_hints is not None
                else _expression_function_type_hints(model_cls, group_column, output_column)
            )
    for aggregation in getattr(query_spec, "aggregations", ()) or ():
        alias = getattr(aggregation, "alias", None)
        if isinstance(alias, str):
            function = getattr(aggregation, "function", None)
            expression = getattr(aggregation, "expression", None)
            if str(function).upper() in {"MIN", "MAX", "SUM"} and isinstance(expression, Expression):
                expression_hints = _expression_field_type_hints(model_cls, expression, alias)
                if expression_hints is not None:
                    hints.append(expression_hints)
                    continue
            hints.append(_function_output_type_hints(function, alias))
    for window_expr, alias in getattr(query_spec, "window_functions", ()) or ():
        window_function = getattr(window_expr, "func", None)
        function = getattr(window_function, "name", None)
        function_args = getattr(window_function, "args", ())
        result_function = SqlFunctionName(function) if isinstance(function, str) else NO_EXPRESSION_FUNCTION_NAME
        value_expression = expression_result_argument(result_function, function_args)
        if isinstance(value_expression, Expression):
            hints.append(
                _expression_field_type_hints(model_cls, value_expression, alias)
                or _expression_output_type_hints(value_expression, alias)
                or _expression_function_type_hints(model_cls, value_expression, alias)
            )
        else:
            hints.append(_function_output_type_hints(function, alias))
    return combine_sql_column_type_hints(columns, *hints)


def _query_spec_column_type_hints(
    model_cls: type[DatabaseObjectRow],
    query_spec: QuerySpec[DatabaseObjectRow] | None,
    columns: tuple[str, ...],
) -> SqlColumnTypeHints:
    projection_model = query_spec.projection_model_cls if query_spec is not None else None
    if projection_model is None:
        return _query_spec_inferred_column_type_hints(model_cls, query_spec, columns)
    declared = _required_contract_column_type_hints(projection_model, columns)
    if declared.covers(columns):
        return declared
    covered = set().union(*declared.as_tuple())
    inferred = _query_spec_inferred_column_type_hints(model_cls, query_spec, columns)
    return combine_sql_column_type_hints(columns, inferred.filtered(set(columns) - covered), declared)


def _query_spec_inferred_column_type_hints(
    model_cls: type[DatabaseObjectRow],
    query_spec: QuerySpec[DatabaseObjectRow] | None,
    columns: tuple[str, ...],
) -> SqlColumnTypeHints:
    projection_model = query_spec.projection_model_cls if query_spec is not None else None
    hint_model = projection_model if projection_model is not None else model_cls
    selected_hints = _query_spec_selected_type_hints(model_cls, query_spec)
    if selected_hints is not None:
        computed_hints = _query_spec_computed_type_hints(model_cls, query_spec)
        base_hints = SqlColumnTypeHints() if selected_hints.covers(columns) else _required_contract_column_type_hints(hint_model, columns)
        if computed_hints is not None:
            return combine_sql_column_type_hints(columns, base_hints, selected_hints, computed_hints)
        return combine_sql_column_type_hints(columns, base_hints, selected_hints)
    computed_hints = _query_spec_computed_type_hints(model_cls, query_spec)
    if computed_hints is not None:
        return combine_sql_column_type_hints(
            columns,
            _required_contract_column_type_hints(hint_model, columns),
            computed_hints,
        )
    return _required_contract_column_type_hints(hint_model, columns)


def _query_output_shape_column_type_hints(
    model_cls: type[DatabaseObjectRow],
    query_spec: QuerySpec[DatabaseObjectRow] | None,
    output_shape: CompiledOutputShape,
) -> SqlColumnTypeHints:
    return _query_spec_column_type_hints(model_cls, query_spec, output_shape.cte_output_columns)


def _query_spec_computed_output_columns(
    model_cls: type[DatabaseObjectRow],
    query_spec: QuerySpec[DatabaseObjectRow] | None,
) -> tuple[tuple[str, str, bool], ...]:
    """Return output mappings for aggregate/window query shapes."""
    if query_spec is None:
        return ()
    mappings: list[tuple[str, str, bool]] = []
    for index, group_column in enumerate(getattr(query_spec, "group_by", ()) or ()):
        if isinstance(group_column, str):
            db_col = str(get_db_column_name(model_cls, DynamicFieldName(group_column)))
            mappings.append((db_col, db_col, False))
            continue
        if isinstance(group_column, AliasedField):
            mappings.append((group_column.alias, group_column.alias, False))
            continue
        if isinstance(group_column, Field):
            db_col = str(get_db_column_name(model_cls, DynamicFieldName(group_column.name)))
            mappings.append((db_col, db_col, False))
            continue
        if isinstance(group_column, AliasedExpression):
            mappings.append((group_column.alias, group_column.alias, False))
            continue
        if (
            isinstance(group_column, Expression)
            and group_column.field is not None
            and group_column.function is None
            and group_column.operator is None
        ):
            db_col = (
                get_db_column_name(model_cls, DynamicFieldName(group_column.field))
                if group_column.field in model_cls.model_fields
                else group_column.field
            )
            mappings.append((db_col, db_col, False))
            continue
        mappings.append((f"__group_by_{index}", f"__group_by_{index}", False))
    for aggregation in getattr(query_spec, "aggregations", ()) or ():
        alias = getattr(aggregation, "alias", None)
        if alias:
            mappings.append((alias, alias, False))
    for _window_expr, alias in getattr(query_spec, "window_functions", ()) or ():
        if alias:
            mappings.append((alias, alias, False))
    return tuple(mappings)


def _query_spec_selected_output_columns(
    model_cls: type[DatabaseObjectRow],
    query_spec: QuerySpec[DatabaseObjectRow] | None,
) -> tuple[tuple[str, str, bool], ...]:
    """Pair each public projection name with its physical source column."""
    if query_spec is None:
        return ()
    select_columns = getattr(query_spec, "select_columns", None)
    if not select_columns:
        return ()
    mappings: list[tuple[str, str, bool]] = []
    for column in select_columns:
        if isinstance(column, str):
            db_column = polymorphic_read_column_name(model_cls, column)
            mappings.append((column, db_column, False))
            continue
        if isinstance(column, Field):
            field_owner = getattr(column, "owner", model_cls)
            if not isinstance(field_owner, type):
                field_owner = model_cls
            db_column = polymorphic_read_column_name(field_owner, column.name)
            mappings.append((column.name, db_column, False))
            continue
        if isinstance(column, AliasedField):
            field_owner = getattr(column.field, "owner", model_cls)
            if not isinstance(field_owner, type):
                field_owner = model_cls
            db_column = polymorphic_read_column_name(field_owner, column.field.name)
            mappings.append((column.alias, db_column, False))
            continue
        if isinstance(column, (AliasedExpression, PlanAliasedExpression)):
            mappings.append((column.alias, column.alias, False))
            continue
        if isinstance(column, Expression) and column.field is not None and column.function is None and column.operator is None:
            owner: type[DatabaseObjectRow] = model_cls
            owner_value = getattr(column, "owner", None)
            if isinstance(owner_value, type) and issubclass(owner_value, DatabaseObjectRow):
                owner = owner_value
            db_column = polymorphic_read_column_name(owner, column.field)
            mappings.append((column.field, db_column, False))
            continue
        return ()
    return tuple(mappings)


def _query_spec_projection_lineage(
    model_cls: type[DatabaseObjectRow],
    query_spec: QuerySpec[DatabaseObjectRow] | None,
    columns: tuple[str, ...],
) -> tuple[tuple[str, str], ...]:
    """Lineage for query CTEs bounded by ``model_cls``.

    Full-row and simple field projections map directly to model DB columns.
    Aliases and computed SQL outputs still carry explicit lineage labels here;
    their SQL type hints are calculated separately by ``_query_spec_column_type_hints``.
    """
    if query_spec is None:
        return tuple((column, column) for column in columns)
    lineage: dict[str, str] = {}
    for column in getattr(query_spec, "select_columns", ()) or ():
        if isinstance(column, str):
            db_column = polymorphic_read_column_name(model_cls, column)
            lineage[column] = db_column
            continue
        if isinstance(column, Field):
            field_owner = getattr(column, "owner", model_cls)
            if not isinstance(field_owner, type):
                field_owner = model_cls
            db_column = polymorphic_read_column_name(field_owner, column.name)
            if field_owner is not model_cls and column.name in lineage:
                continue
            lineage[column.name] = db_column
            continue
        if isinstance(column, AliasedField):
            lineage[column.alias] = str(
                get_db_column_name(cast("type[DatabaseObjectRow]", column.owner_model), DynamicFieldName(column.name))
            )
            continue
        if isinstance(column, (AliasedExpression, PlanAliasedExpression)):
            lineage[column.alias] = f"expression:{column.alias}"
            continue
        if isinstance(column, Expression) and column.field is not None and column.function is None and column.operator is None:
            owner: type[DatabaseObjectRow] = model_cls
            owner_value = getattr(column, "owner", None)
            if isinstance(owner_value, type) and issubclass(owner_value, DatabaseObjectRow):
                owner = owner_value
            db_column = polymorphic_read_column_name(owner, column.field)
            lineage[column.field] = db_column
    for output_name, db_column, _is_binary in _query_spec_computed_output_columns(model_cls, query_spec):
        lineage[db_column] = output_name if output_name != db_column else f"computed:{db_column}"
    return tuple((column, lineage.get(column, column)) for column in columns)


def _query_spec_relation_contract(
    model_cls: type[DatabaseObjectRow],
    query_spec: QuerySpec[DatabaseObjectRow] | None,
    columns: tuple[str, ...],
) -> CteRelationContract:
    """Relation owner for a query CTE over ``model_cls``.

    A plain full-row query publishes the model relation. Once the query narrows,
    aliases, aggregates, windows, or otherwise reshapes the row, it becomes a
    projection-over-model relation with explicit output lineage.
    """
    if query_spec is not None and not _query_spec_has_computed_outputs(query_spec) and not getattr(query_spec, "select_columns", None):
        full_row_columns = _query_full_row_output_columns(model_cls, query_spec)
        if tuple(columns) == full_row_columns:
            return CteRelationContract.model(model_cls)
    return CteRelationContract.projection_over_model(
        source_model_cls=model_cls,
        projection_lineage=_query_spec_projection_lineage(
            model_cls,
            query_spec,
            columns,
        ),
    )


def _query_contract_model_cls(
    model_cls: type[DatabaseObjectRow],
    step_name: str,
    columns: tuple[str, ...],
    column_type_hints: SqlColumnTypeHints,
) -> type:
    """Return the exact SQL-visible row model for a query terminal."""
    return cte_projection_row_model(
        f"{model_cls.__name__}{step_name}Row",
        columns,
        column_type_hints,
    )


def _query_full_row_output_columns(
    model_cls: type[DatabaseObjectRow],
    query_spec: QuerySpec[DatabaseObjectRow] | None = None,
) -> tuple[str, ...]:
    """Scope subtype columns to the queried model and retain explicit source projections."""
    from impl.common.l2070_server_plan.steps._compile_helpers import (
        _collect_large_column_pointer_db_columns,
    )
    from l1050_polymorphism.type_registry import get_polymorphic_base_class

    if query_spec is not None and query_spec.default_projection_columns is not None:
        return tuple(str(column) for column in query_spec.default_projection_columns)

    table_root = get_polymorphic_base_class(model_cls)
    fields = (
        collect_polymorphic_fields(model_cls)
        if (table_root is None or table_root is model_cls or getattr(model_cls, "__polymorphic_abstract__", False))
        else model_fields_map(model_cls)
    )
    columns = list(
        dict.fromkeys(
            (
                *(polymorphic_read_column_name(model_cls, name) for name in fields),
                *_collect_large_column_pointer_db_columns(model_cls),
            ),
        ),
    )
    base_fields = set(model_cls.model_fields)
    source_models = () if query_spec is None else tuple(query_spec.polymorphic_source_models or ())
    for source_model in source_models:
        for field_name in source_model.model_fields:
            output_column = str(get_db_column_name(model_cls, DynamicFieldName(field_name))) if field_name in base_fields else field_name
            if output_column not in columns:
                columns.append(output_column)
    return tuple(columns)


def _query_spec_cte_output_columns(
    model_cls: type[DatabaseObjectRow],
    query_spec: QuerySpec[DatabaseObjectRow] | None,
    *,
    full_row_uses_model_fields: bool = False,
) -> tuple[str, ...]:
    selected_columns = _query_spec_selected_output_columns(model_cls, query_spec)
    window_columns = tuple(
        db_column
        for _output_name, db_column, _is_binary in _query_spec_computed_output_columns(model_cls, query_spec)
        if query_spec is not None and any(alias == db_column for _window_expr, alias in getattr(query_spec, "window_functions", ()) or ())
    )
    if selected_columns:
        base_columns = tuple(output_name for output_name, _db_column, _is_binary in selected_columns)
        return tuple(dict.fromkeys((*base_columns, *window_columns)))
    computed_columns = _query_spec_computed_output_columns(model_cls, query_spec)
    if window_columns:
        return tuple(dict.fromkeys((*_query_full_row_output_columns(model_cls, query_spec), *window_columns)))
    if computed_columns:
        return tuple(db_column for _output_name, db_column, _is_binary in computed_columns)
    if full_row_uses_model_fields:
        return _query_full_row_output_columns(model_cls, query_spec)
    return _query_full_row_output_columns(model_cls, query_spec)


def _query_spec_physical_tables(query_spec: object) -> frozenset[str]:
    """Collect physical and logical table sources without treating CTE rows as tables."""

    from impl.common.l2060_query_spec.query_source import (
        AliasedSource,
        DerivedQuerySource,
        LogicalTableSource,
        PhysicalTableSource,
    )

    tables: set[str] = set()
    seen: set[int] = set()

    def _collect(value: object) -> None:
        value_id = id(value)
        if value_id in seen:
            return
        seen.add(value_id)
        source = getattr(value, "source", None)
        while isinstance(source, AliasedSource):
            source = source.source
        if isinstance(source, LogicalTableSource):
            tables.add(str(get_table_name(source.model_cls)))
        elif isinstance(source, PhysicalTableSource):
            tables.add(str(source.table_name))
        elif isinstance(source, DerivedQuerySource):
            _collect(source.query)
        for join in getattr(value, "joins", ()) or ():
            target_source = getattr(join, "target_source", None)
            while isinstance(target_source, AliasedSource):
                target_source = target_source.source
            if isinstance(target_source, LogicalTableSource):
                tables.add(str(get_table_name(target_source.model_cls)))
            elif isinstance(target_source, PhysicalTableSource):
                tables.add(str(target_source.table_name))
            elif isinstance(target_source, DerivedQuerySource):
                _collect(target_source.query)
        for definition in getattr(value, "ctes", ()) or ():
            _collect(definition.query)
        for branch in getattr(value, "branches", ()) or ():
            _collect(branch.query_spec)

    _collect(query_spec)
    return frozenset(tables)


def _validate_planned_query_cte_metadata(
    *,
    step_name: str,
    model_cls: type[DatabaseObjectRow],
    query_spec: QuerySpec[DatabaseObjectRow] | None,
    planned_model_cls: type[DatabaseObjectRow],
    planned_query_spec: QuerySpec[DatabaseObjectRow] | None,
    planned_columns: tuple[str, ...],
    current_columns: tuple[str, ...] | None = None,
) -> None:
    if (
        model_cls is planned_model_cls
        and query_spec is planned_query_spec
        and (current_columns is None or current_columns == planned_columns)
    ):
        return
    msg = f"{step_name} planned CTE metadata is stale. The query/model source changed after step construction."
    raise StaleCtePublicationContractError(msg)


def _publish_compiled_query_cte_metadata(
    step: object,
    compiled: CompiledStep[Sequence[object]] | CompiledStep[object],
) -> None:
    """Make a query step's declared CTE metadata match compiler-owned transport shape."""
    if compiled.output_shape is None or compiled.column_type_hints is None:
        return
    setattr(step, "_cte_output_columns", compiled.output_shape.cte_output_columns)
    setattr(step, "_cte_column_type_hints", compiled.column_type_hints)
    setattr(step, "_cte_publication_contract_cache_valid", False)
    setattr(step, "_publication_contract_cache_valid", False)


