class QueryExecuteStep[T](SqlRelationPublisherStep[Sequence[T]]):
    """Step for executing queries with filters, order, limit (the most common read operation)."""

    optimizer_projection_owned = True

    def sql_snapshot_source_ref(self: QueryExecuteStep[T]) -> ServerPlanRefId | None:
        return self.ref_id if self._preserve_snapshot else None

    def requires_same_statement_snapshot(self: QueryExecuteStep[T]) -> bool:
        return self._preserve_snapshot

    def can_join_session_preamble_statement_batch(self: QueryExecuteStep[T]) -> bool:
        return True

    def supports_mysql_json_aggregation(self: QueryExecuteStep[T]) -> bool:
        query_spec = self._query_spec
        return query_spec is not None and query_spec.offset in {None, 0} and not query_spec.order_by

    def __init__(
        self: QueryExecuteStep,
        ref_id: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        config: _QueryExecuteStepConfig,
    ) -> None:
        super().__init__(ref_id)
        self._model_cls = model_cls
        self._query_spec = config.query_spec
        self._raw_mode = config.raw_mode
        self._after_refs = config.after_refs
        self._permission_dependency_refs = config.permission_dependency_refs
        self._user_id_ref_id = config.user_id_ref_id
        self._force_hydrate_large_columns = config.force_hydrate_large_columns
        self._always_publish_executor_binding = config.always_publish_executor_binding
        self._preserve_snapshot = config.preserve_snapshot
        self._resolved_user_id: ResolvedPermissionUserId = None
        self._cte_output_columns = (
            _raw_query_execute_output_shape(self._model_cls, self._query_spec).cte_output_columns
            if self._raw_mode and self._query_spec is not None
            else _query_spec_cte_output_columns(self._model_cls, self._query_spec)
        )
        self._cte_column_type_hints = _query_spec_column_type_hints(
            self._model_cls,
            self._query_spec,
            self._cte_output_columns,
        )
        self._cte_metadata_model_cls = self._model_cls
        self._cte_metadata_query_spec = self._query_spec
        self._dependencies_cache: frozenset[str] | None = None
        from impl.common.l2070_server_plan.steps._resolve import _collect_dependency_refs_from_payload

        input_refs: set[str] = set()
        _collect_dependency_refs_from_payload(self._query_spec, input_refs, preserve_dotted_refs=True)
        self._hydrated_scalar_owners = frozenset(ref.partition(".hydrated.")[0] for ref in input_refs if ".hydrated." in ref)
        self._has_hydrated_scalar_inputs = bool(self._hydrated_scalar_owners)

    @property
    def level(self: QueryExecuteStep) -> int:
        return 0

    def step_tags(self: QueryExecuteStep) -> frozenset[str]:
        """Return tags identifying this step type."""
        return frozenset({"read", "query", "execute"})

    def is_read_only(self: QueryExecuteStep) -> bool:
        """Locking reads do not mutate rows."""
        return True

    def requires_materialized_inputs(self: QueryExecuteStep) -> bool:
        return self._query_spec is None or self._has_hydrated_scalar_inputs

    def requires_prior_step_boundary(self: QueryExecuteStep) -> bool:
        return bool(self._after_refs) or self.requires_materialized_inputs() or self._has_hydrated_scalar_inputs

    def requires_standalone_physical_request(self: QueryExecuteStep) -> bool:
        return self._has_hydrated_scalar_inputs

    def without_ordering_only_dependency(self: QueryExecuteStep[T], ref: str) -> QueryExecuteStep[T] | None:
        """Drop an explicit ordering edge that is not consumed by query SQL."""
        matching_ref = next((item for item in self._after_refs if str(item) == ref), None)
        if matching_ref is None:
            return None
        return QueryExecuteStep(
            self.ref_id,
            self._model_cls,
            _QueryExecuteStepConfig(
                query_spec=self._query_spec,
                raw_mode=self._raw_mode,
                after_refs=self._after_refs - {matching_ref},
                permission_dependency_refs=self._permission_dependency_refs,
                user_id_ref_id=self._user_id_ref_id,
                force_hydrate_large_columns=self._force_hydrate_large_columns,
                always_publish_executor_binding=self._always_publish_executor_binding,
                preserve_snapshot=self._preserve_snapshot,
            ),
        )

    def result_cardinality(self: QueryExecuteStep) -> Cardinality:
        """Return MANY - this step returns multiple results."""
        return Cardinality.MANY

    def tables_read(self: QueryExecuteStep) -> frozenset[str]:
        """Return physical tables declared by the query relation program."""
        tables = _query_spec_physical_tables(self._query_spec)
        if tables or getattr(self._query_spec, "source", None) is not None:
            return tables
        return frozenset({get_table_name(self._model_cls)})

    def tables_written(self: QueryExecuteStep) -> frozenset[str]:
        """Include lock targets in the write-conflict footprint."""
        return self.tables_read() if self._query_spec is not None and self._query_spec.for_update else frozenset()

    def requires_prior_statement_visibility_after_writes(self: QueryExecuteStep) -> frozenset[str]:
        return self.tables_read()

    def _publish_compiled_cte_metadata(self: QueryExecuteStep, compiled: CompiledStep[Sequence[object]]) -> None:
        """Make the declared publication contract match the catalog-owned compiled shape."""
        _publish_compiled_query_cte_metadata(self, compiled)

    def supports_sql_batch_transport(self: QueryExecuteStep) -> bool:
        if self._has_hydrated_scalar_inputs:
            return False
        if self._query_spec is None:
            return True
        from impl.common.l2070_server_plan.steps._query_spec_chunking import (
            split_query_spec_on_oversized_literal_in,
        )

        if (
            split_query_spec_on_oversized_literal_in(
                self._query_spec,
                backend_type=None,
                preserve_read_semantics=True,
            )
            is not None
        ):
            return False
        return not _needs_inline_large_column_hydration(
            self._model_cls,
            self._query_spec,
            raw_mode=self._raw_mode,
            force_hydrate_large_columns=self._force_hydrate_large_columns,
        )

    def supports_ordered_sql_statement_batch(self: QueryExecuteStep) -> bool:
        return self.supports_sql_batch_transport()

    def ordered_statement_sql_visible_dependencies(self: QueryExecuteStep) -> frozenset[str]:
        return frozenset()

    def executor_publication_projection_columns(self: QueryExecuteStep) -> tuple[str, ...]:
        """Project driver support columns out of the declared query relation."""
        return self._cte_output_columns

    def cte_publication_contract(self: QueryExecuteStep) -> CtePublicationContract:
        def _legacy_cte_output_columns() -> tuple[str, ...]:
            _validate_planned_query_cte_metadata(
                step_name=type(self).__name__,
                model_cls=self._model_cls,
                query_spec=self._query_spec,
                planned_model_cls=self._cte_metadata_model_cls,
                planned_query_spec=self._cte_metadata_query_spec,
                planned_columns=self._cte_output_columns,
            )
            return self._cte_output_columns

        columns = _legacy_cte_output_columns()

        def _legacy_cte_column_type_hints(columns: tuple[str, ...] | None) -> SqlColumnTypeHints:
            _validate_planned_query_cte_metadata(
                step_name=type(self).__name__,
                model_cls=self._model_cls,
                query_spec=self._query_spec,
                planned_model_cls=self._cte_metadata_model_cls,
                planned_query_spec=self._cte_metadata_query_spec,
                planned_columns=self._cte_output_columns,
            )
            return self._cte_column_type_hints

        column_type_hints = _legacy_cte_column_type_hints(columns)
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        _contract_model_cls = cte_projection_row_model(
            f"{self._model_cls.__name__}QueryExecuteRow",
            columns,
            column_type_hints,
        )
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=columns,
            column_type_hints=column_type_hints,
            model_cls=_contract_model_cls,
            relation_contract=_query_spec_relation_contract(
                self._model_cls,
                self._query_spec,
                tuple(str(column) for column in columns),
            ),
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
            optional_columns=frozenset(columns) - {"sys_id"},
            empty_result_allowed=True,
        )

    def always_publishes_executor_visible_binding(self: QueryExecuteStep) -> bool:
        return self._always_publish_executor_binding or not self.supports_sql_batch_transport()

    def publication_source_kind(self: QueryExecuteStep) -> PublicationSourceKind:
        # Inline large-column acquisition keeps the step out of SQL batch fusion, but
        # its declared relation remains SQL-visible to hydration consumers.
        return super().publication_source_kind()

    def dependencies(self: QueryExecuteStep) -> frozenset[str]:
        if self._dependencies_cache is not None:
            return self._dependencies_cache
        deps: set[str] = {str(ref_id) for ref_id in self._after_refs | self._permission_dependency_refs}
        if self._user_id_ref_id is not None:
            deps.add(str(self._user_id_ref_id))
        if self._query_spec is None:
            result = frozenset(deps)
            self._dependencies_cache = result
            return result
        from impl.common.l2070_server_plan.steps._resolve import (
            collect_query_spec_deps,
        )

        deps.update(collect_query_spec_deps(self._query_spec))
        deps.update(self._hydrated_scalar_owners)
        result = frozenset(ref for ref in deps if ".hydrated" not in ref and not ref.partition(".")[0].startswith("seed_"))
        self._dependencies_cache = result
        return result

    def sql_visible_dependencies(self: QueryExecuteStep) -> frozenset[str]:
        return self.dependencies() - frozenset(str(ref_id) for ref_id in self._after_refs) - self._hydrated_scalar_owners

    def executor_visible_dependencies(self: QueryExecuteStep) -> frozenset[str]:
        return self._hydrated_scalar_owners

    def consumes_executor_visible_dependencies(self: QueryExecuteStep) -> bool:
        return self._has_hydrated_scalar_inputs

    def compile(self: QueryExecuteStep, ctx: CompilationContext) -> CompiledStep[Sequence[T]]:
        _check_system_rippler_query_access(self._model_cls)
        resolved_user_id = (
            self._resolved_user_id
            if self._resolved_user_id is not None
            else (ctx.cte_refs.get(self._user_id_ref_id) if self._user_id_ref_id is not None else None)
        )
        compiled = compile_sql_query_execute_step(
            self._model_cls,
            self._query_spec,
            ctx,
            raw_mode=self._raw_mode,
            resolved_user_id=resolved_user_id,
            closed_post_op=None,
            step_name=type(self).__name__,
            force_hydrate_large_columns=self._force_hydrate_large_columns,
        )
        if not self.supports_sql_batch_transport():
            self._publish_compiled_cte_metadata(compiled)
            return cast("CompiledStep[Sequence[T]]", compiled)
        self._publish_compiled_cte_metadata(compiled)
        contract = _cte_publication_contract_for_step(self)
        assert contract is not None
        output_shape = compiled.output_shape or _output_shape_from_contract(contract)
        # Combine compiled and contract hints so transport/semantic columns stay
        # producer-owned through output-shape replacement.
        compiled_column_type_hints = compiled.column_type_hints
        if compiled_column_type_hints is None:
            compiled_column_type_hints = contract.column_type_hints
        column_type_hints = combine_sql_column_type_hints(
            output_shape.cte_output_columns,
            compiled_column_type_hints,
            contract.column_type_hints,
        ).require_complete(output_shape.cte_output_columns)
        compiled = replace(compiled, output_shape=output_shape, column_type_hints=column_type_hints)
        if self._preserve_snapshot:
            from impl.common.l2070_server_plan.steps.captured_json import capture_compiled_json

            compiled = capture_compiled_json(compiled, self.ref_id, contract)
        return cast("CompiledStep[Sequence[T]]", compiled)


class QueryFirstStep[T](SqlRelationPublisherStep[T | None]):
    """Step for executing queries returning only the first result (or None)."""

    optimizer_projection_owned = True

    def __init__(
        self: QueryFirstStep,
        ref_id: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        config: _QueryFirstStepConfig,
    ) -> None:
        super().__init__(ref_id)
        self._model_cls = model_cls
        self._query_spec = config.query_spec
        self._after_refs = config.after_refs
        self._permission_dependency_refs = config.permission_dependency_refs
        self._user_id_ref_id = config.user_id_ref_id
        self._resolved_user_id: ResolvedPermissionUserId = None
        self._cte_output_columns = _query_spec_cte_output_columns(self._model_cls, self._query_spec)
        self._cte_column_type_hints = _query_spec_column_type_hints(
            self._model_cls,
            self._query_spec,
            self._cte_output_columns,
        )
        self._cte_metadata_model_cls = self._model_cls
        self._cte_metadata_query_spec = self._query_spec

    @property
    def level(self: QueryFirstStep) -> int:
        return 0

    def step_tags(self: QueryFirstStep) -> frozenset[str]:
        return frozenset({"read", "query", "first"})

    def is_read_only(self: QueryFirstStep) -> bool:
        return True

    def result_cardinality(self: QueryFirstStep) -> Cardinality:
        return Cardinality.ONE

    def always_publishes_executor_visible_binding(self: QueryFirstStep) -> bool:
        """Preserve an explicit typed empty relation when no row matches."""
        return True

    def declares_consumed_rows_reduction(self: QueryFirstStep) -> bool:
        return True

    def tables_read(self: QueryFirstStep) -> frozenset[str]:
        return frozenset({get_table_name(self._model_cls)})

    def tables_written(self: QueryFirstStep) -> frozenset[str]:
        # Locking reads require writer admission and conflict with table writes.
        return self.tables_read() if self._query_spec.for_update else frozenset()

    def requires_prior_statement_visibility_after_writes(self: QueryFirstStep) -> frozenset[str]:
        return self.tables_read()

    def cte_publication_contract(self: QueryFirstStep) -> CtePublicationContract:
        def _legacy_cte_output_columns() -> tuple[str, ...]:
            _validate_planned_query_cte_metadata(
                step_name=type(self).__name__,
                model_cls=self._model_cls,
                query_spec=self._query_spec,
                planned_model_cls=self._cte_metadata_model_cls,
                planned_query_spec=self._cte_metadata_query_spec,
                planned_columns=self._cte_output_columns,
            )
            return self._cte_output_columns

        columns = _legacy_cte_output_columns()

        def _legacy_cte_column_type_hints(columns: tuple[str, ...] | None) -> SqlColumnTypeHints:
            _validate_planned_query_cte_metadata(
                step_name=type(self).__name__,
                model_cls=self._model_cls,
                query_spec=self._query_spec,
                planned_model_cls=self._cte_metadata_model_cls,
                planned_query_spec=self._cte_metadata_query_spec,
                planned_columns=self._cte_output_columns,
            )
            return self._cte_column_type_hints

        column_type_hints = _legacy_cte_column_type_hints(columns)
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        contract_columns = tuple(str(column) for column in columns)
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=contract_columns,
            column_type_hints=column_type_hints,
            model_cls=_query_contract_model_cls(
                self._model_cls,
                type(self).__name__,
                contract_columns,
                column_type_hints,
            ),
            relation_contract=_query_spec_relation_contract(self._model_cls, self._query_spec, contract_columns),
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
            empty_result_allowed=True,
        )

    def dependencies(self: QueryFirstStep) -> frozenset[str]:
        return _cached_query_first_deps(
            self,
            self._query_spec,
            after_refs=self._after_refs,
            permission_dependency_refs=self._permission_dependency_refs,
            user_id_ref_id=self._user_id_ref_id,
        )

    def supports_ordered_sql_statement_batch(self: QueryFirstStep) -> bool:
        return self.supports_sql_batch_transport()

    def ordered_statement_sql_visible_dependencies(self: QueryFirstStep) -> frozenset[str]:
