type StagedFieldProjectionScalar = str | int | bool | bytes | memoryview | datetime | UUID | None
type StagedFieldProjection = dict[str, StagedFieldProjectionScalar]
type StagedFieldMetadataName = Literal[
    "actual_sha256",
    "already_present",
    "chunk_sha256",
    "chunk_size",
    "content_hash",
    "delta_base_hash",
    "delta_base_sha256",
    "expired",
    "expected_sha256",
    "matches",
    "original_size",
    "requested_length",
    "requested_offset",
    "total_chunks",
    "writable",
]


def _database_boolean(value: StagedFieldProjectionScalar, *, name: StagedFieldMetadataName) -> bool:
    """Validate a backend boolean without truthiness coercion."""
    if isinstance(value, bool):
        return value
    if isinstance(value, int) and value in {0, 1}:
        return value == 1
    raise TypeError(f"Staged-field metadata {name!r} must be a database boolean")


def _database_nonnegative_integer(
    value: StagedFieldProjectionScalar,
    *,
    name: StagedFieldMetadataName,
) -> int:
    """Validate nonnegative integer metadata without fallback coercion."""
    if not isinstance(value, int) or isinstance(value, bool) or value < 0:
        raise TypeError(f"Staged-field metadata {name!r} must be a nonnegative integer")
    return value


def _database_sha256(value: StagedFieldProjectionScalar, *, name: StagedFieldMetadataName) -> StagedFieldSha256:
    """Validate a SHA-256 value returned by the database."""
    if not isinstance(value, str):
        raise TypeError(f"Staged-field metadata {name!r} must be a SHA-256 string")
    normalized = value.lower()
    if len(normalized) != 64 or any(character not in "0123456789abcdef" for character in normalized):
        raise TypeError(f"Staged-field metadata {name!r} must contain 64 hexadecimal characters")
    return StagedFieldSha256(normalized)


