class StagedFieldPlanStep[T](NonPublishingStep[T]):
    """Schema-owned staged-field operation lowered before SQL compilation."""

    intent_tags: frozenset[str] = frozenset({"staged_field"})
    intent_cardinality: Cardinality = Cardinality.ONE
    intent_read_only: bool = False

    @property
    def level(self) -> int:
        return 3

    def result_cardinality(self) -> Cardinality:
        return self.intent_cardinality

    def is_read_only(self) -> bool:
        return self.intent_read_only

    def step_tags(self) -> frozenset[str]:
        return self.intent_tags

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def compile(self, ctx: CompilationContext) -> CompiledStep[T]:
        del ctx
        raise TypeError(f"{type(self).__name__} must be lowered before compile")


class ValidateOrdinaryStagedFieldAbortScopeStep(NonPublishingStep[bool]):
    """Reject an ordinary abort when its public handle changed storage kind."""

    def __init__(self, ref_id: ServerPlanRefId, *, manifest_ref: ServerPlanRefId) -> None:
        super().__init__(ref_id)
        self._manifest_ref = manifest_ref

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self) -> bool:
        return True

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def dependencies(self) -> frozenset[str]:
        return frozenset({str(self._manifest_ref)})

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def consumes_executor_visible_dependencies(self) -> bool:
        return True

    def execute_runtime(self, resolved: ResolvedRefs) -> bool:
        manifest = _validated_abort_manifest(resolved, self._manifest_ref)
        if manifest is None:
            return True
        if manifest.storage_kind is not StagedFieldStorageKind.ORDINARY:
            raise StagedFieldAuthorizationError("The staged upload is not an ordinary upload")
        return True

    def compile(self, ctx: CompilationContext) -> CompiledStep[bool]:
        del ctx
        return CompiledStep()


class ValidateStagedFieldAbortScopeStep(NonPublishingStep[bool]):
    """Reject a versioned abort when its public handle changed domain scope."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        manifest_ref: ServerPlanRefId,
        table_key: StagedFieldTableKey,
        branch_id: BranchId,
        connection_id: ConnectionId,
        staged_commit_id: StagedCommitId,
        workspace_id: WorkspaceId,
    ) -> None:
        super().__init__(ref_id)
        self._manifest_ref = manifest_ref
        self._table_key = table_key
        self._branch_id = branch_id
        self._connection_id = connection_id
        self._staged_commit_id = staged_commit_id
        self._workspace_id = workspace_id

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self) -> bool:
        return True

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def dependencies(self) -> frozenset[str]:
        return frozenset({str(self._manifest_ref)})

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def consumes_executor_visible_dependencies(self) -> bool:
        return True

    def execute_runtime(self, resolved: ResolvedRefs) -> bool:
        manifest = _validated_abort_manifest(resolved, self._manifest_ref)
        if manifest is None:
            return True
        if manifest.storage_kind is not StagedFieldStorageKind.VERSIONED:
            raise StagedFieldAuthorizationError("The staged upload is not a versioned upload")
        if manifest.table_key != self._table_key:
            raise StagedFieldAuthorizationError("The staged upload table scope changed")
        if manifest.branch_id != self._branch_id or manifest.connection_id != self._connection_id:
            raise StagedFieldAuthorizationError("The staged upload branch scope changed")
        if manifest.staged_commit_id != self._staged_commit_id:
            raise StagedFieldAuthorizationError("The staged upload commit scope changed")
        if manifest.workspace_id != self._workspace_id:
            raise StagedFieldAuthorizationError("The staged upload workspace scope changed")
        return True

    def compile(self, ctx: CompilationContext) -> CompiledStep[bool]:
        del ctx
        return CompiledStep()


class ValidateStagedFieldCleanupStep(NonPublishingStep[bool]):
    """Reject destructive cleanup from durable manifest state."""

    def __init__(self, ref_id: ServerPlanRefId, *, check_ref: ServerPlanRefId) -> None:
        super().__init__(ref_id)
        self._check_ref = check_ref

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self) -> bool:
        return True

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def dependencies(self) -> frozenset[str]:
        return frozenset({str(self._check_ref)})

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def consumes_executor_visible_dependencies(self) -> bool:
        return True

    def execute_runtime(self, resolved: ResolvedRefs) -> bool:
        from l7000_versioned_schema.staged_field_api import (
            StagedFieldNotExpiredError,
            StagedFieldNotWritableError,
        )

        value = resolved.peek(self._check_ref)
        if not isinstance(value, dict):
            raise TypeError("Staged cleanup validation returned invalid metadata")
        if not _database_boolean(value.get("writable"), name="writable"):
            raise StagedFieldNotWritableError("A finalized staged upload cannot be cleaned up")
        if not _database_boolean(value.get("expired"), name="expired"):
            raise StagedFieldNotExpiredError("The staged upload has not expired")
        return True

    def compile(self, ctx: CompilationContext) -> CompiledStep[bool]:
        del ctx
        return CompiledStep()


def _aware_staged_datetime(value: StagedFieldProjectionScalar) -> datetime | None:
    """Attach UTC to backend timestamps that omit an explicit offset."""
    parsed = datetime.fromisoformat(value) if isinstance(value, str) else value
    if parsed is not None and not isinstance(parsed, datetime):
        raise TypeError("The staged upload timestamp has an unsupported type")
    if parsed is not None and parsed.tzinfo is None:
        return parsed.replace(tzinfo=UTC)
    return parsed


def _validated_abort_manifest(
    resolved: ResolvedRefs,
    manifest_ref: ServerPlanRefId,
) -> StagedFieldStream | None:
    """Validate the complete durable manifest before destructive abort work."""
    value = resolved.peek(manifest_ref)
    if value is None:
        return None
    if not isinstance(value, dict) or not all(isinstance(key, str) for key in value):
        raise StagedFieldAuthorizationError("The staged upload manifest is unavailable")
    try:
        return StagedFieldStream.model_validate(
            {
                **value,
                "expires_at": _aware_staged_datetime(value.get("expires_at")),
                "created_at": _aware_staged_datetime(value.get("created_at")),
                "updated_at": _aware_staged_datetime(value.get("updated_at")),
            },
        )
    except (TypeError, ValueError) as exc:
        raise StagedFieldAuthorizationError("The staged upload manifest is invalid") from exc


class DecodeStagedFieldUploadLookupStep(
    NonPublishingStep[StagedFieldUpload | MissingStagedFieldUpload],
):
    """Convert an authorized manifest lookup into an explicit result variant."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        source_ref: ServerPlanRefId,
        upload_id: StagedFieldUploadId,
    ) -> None:
        super().__init__(ref_id)
        self._source_ref = source_ref
        self._upload_id = upload_id

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self) -> bool:
        return True

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def dependencies(self) -> frozenset[str]:
        return frozenset({str(self._source_ref)})

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def consumes_executor_visible_dependencies(self) -> bool:
        return True

    def execute_runtime(
        self,
        resolved: ResolvedRefs,
    ) -> StagedFieldUpload | MissingStagedFieldUpload:
        value = resolved.peek(self._source_ref)
        if value is None:
            return MissingStagedFieldUpload(StagedFieldUploadId(str(self._upload_id)))
        if not isinstance(value, dict):
            raise TypeError("The staged upload lookup returned invalid metadata")
        from l7000_versioned_schema.staged_field_operations import _staged_upload_handle

        stream = StagedFieldStream.model_validate(
            {
                **value,
                "expires_at": _aware_staged_datetime(value.get("expires_at")),
                "created_at": _aware_staged_datetime(value.get("created_at")),
                "updated_at": _aware_staged_datetime(value.get("updated_at")),
            },
        )
        # The security requirements in NER_1544_STAGED_LARGE_COLUMN_STREAMING_API.rst
        # forbid candidate metadata from revealing a protected target row.
        if stream.storage_kind.value == "ordinary":
            from l1000_schema.table_registry import get_model_for_table
            from l4000_permissions.permission_enforcement import model_has_enforcing_permission_scheme

            model_cls = get_model_for_table(SqlTableName(stream.table_key))
            exposes_candidate_base = model_cls is not None and not model_has_enforcing_permission_scheme(model_cls)
            if not exposes_candidate_base:
                stream = stream.model_copy(
                    update={
                        "candidate_base_hash": None,
                        "candidate_base_revision_id": None,
                        "candidate_row_exists": False,
                    },
                )
        return _staged_upload_handle(stream)

    def compile(
        self,
        ctx: CompilationContext,
    ) -> CompiledStep[StagedFieldUpload | MissingStagedFieldUpload]:
        del ctx
        return CompiledStep()


class DecodeStagedFieldChunkListStep(NonPublishingStep[Sequence[StagedFieldStreamChunk]]):
    """Hydrate owner-scoped chunk metadata from the internal SQL projection."""

    def __init__(self, ref_id: ServerPlanRefId, *, source_ref: ServerPlanRefId) -> None:
        super().__init__(ref_id)
        self._source_ref = source_ref

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self) -> bool:
        return True

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def dependencies(self) -> frozenset[str]:
        return frozenset({str(self._source_ref)})

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def consumes_executor_visible_dependencies(self) -> bool:
        return True

    def execute_runtime(self, resolved: ResolvedRefs) -> Sequence[StagedFieldStreamChunk]:
        value = resolved.peek(self._source_ref)
        if not isinstance(value, list) or not all(isinstance(row, dict) for row in value):
            raise TypeError("The staged chunk lookup returned invalid metadata")
        chunks: list[StagedFieldStreamChunk] = []
        for row in value:
            created_at = _aware_staged_datetime(row.get("created_at"))
            chunks.append(
                StagedFieldStreamChunk.model_validate(
                    {**row, "created_at": created_at},
                ),
            )
        return chunks

    def compile(self, ctx: CompilationContext) -> CompiledStep[Sequence[StagedFieldStreamChunk]]:
        del ctx
        return CompiledStep()


