class DecodeStagedFieldChunkStep(_DecodeStagedFieldResultStep["StagedFieldChunkReceipt"]):
    """Decode one database-owned chunk receipt."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        source_ref: ServerPlanRefId,
        upload: StagedFieldUpload,
        chunk_index: int,
        data: bytes,
    ) -> None:
        super().__init__(ref_id, source_ref=source_ref)
        self._upload = upload
        self._chunk_index = chunk_index
        self._data = data

    def execute_runtime(self, resolved: ResolvedRefs) -> StagedFieldChunkReceipt:
        from l7000_versioned_schema.staged_field_operations import (
            _AcceptedChunkWriteResult,
            _ChunkWriteResult,
            _decode_chunk_receipt,
            _MissingChunkWriteResult,
        )

        value = resolved.peek(self._source_ref)
        result: _ChunkWriteResult
        if value is None:
            result = _MissingChunkWriteResult()
        elif isinstance(value, dict):
            result = _AcceptedChunkWriteResult(
                matches=_database_boolean(value.get("matches"), name="matches"),
                chunk_sha256=_database_sha256(
                    value.get("chunk_sha256"),
                    name="chunk_sha256",
                ),
                already_present=_database_boolean(
                    value.get("already_present"),
                    name="already_present",
                ),
            )
        else:
            raise TypeError("The staged chunk write returned invalid metadata")
        return _decode_chunk_receipt(self._upload, self._chunk_index, self._data, result)


class DecodeFinalizedStagedFieldStep(_DecodeStagedFieldResultStep["FinalizedStagedField"]):
    """Decode one database-owned finalization result."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        source_ref: ServerPlanRefId,
        upload: StagedFieldUpload,
        detached_delta_storage: bool,
    ) -> None:
        super().__init__(ref_id, source_ref=source_ref)
        self._upload = upload
        self._detached_delta_storage = detached_delta_storage

    def execute_runtime(self, resolved: ResolvedRefs) -> FinalizedStagedField:
        from l7000_versioned_schema.staged_field_api import (
            StagedFieldCompressionAlgorithm,
            StagedFieldError,
            StagedFieldHashExpectation,
            StagedFieldStorageBackend,
        )
        from l7000_versioned_schema.staged_field_operations import (
            _decode_finalized,
            _DeltaFinalizationResult,
            _FinalizationResult,
            _IncompleteFinalizationResult,
            _MaterializedFinalizationResult,
            _UnpublishedFinalizationResult,
        )
        from l7000_versioned_schema.staged_field_streams import StagedFieldStreamState

        value = resolved.peek(self._source_ref)
        if value is None or (isinstance(value, dict) and value.get("actual_sha256") is None):
            return _decode_finalized(self._upload, _IncompleteFinalizationResult())
        if not isinstance(value, dict):
            raise TypeError("Staged finalization returned invalid metadata")
        actual_raw = value.get("actual_sha256")
        expected_raw = value.get("expected_sha256")
        state_raw = value.get("state")
        if not isinstance(state_raw, str):
            raise TypeError("Staged finalization omitted required state metadata")
        try:
            state = StagedFieldStreamState(state_raw)
        except ValueError as exc:
            raise StagedFieldError("Staged finalization returned unsupported state metadata") from exc
        expected = (
            StagedFieldHashExpectation.UNVERIFIED if expected_raw is None else _database_sha256(expected_raw, name="expected_sha256")
        )
        actual = _database_sha256(actual_raw, name="actual_sha256")
        if state is not StagedFieldStreamState.FINALIZED:
            return _decode_finalized(
                self._upload,
                _UnpublishedFinalizationResult(
                    actual_sha256=actual,
                    expected_sha256=expected,
                    state=state,
                ),
            )
        size_raw = value.get("expected_size")
        if not isinstance(size_raw, int) or isinstance(size_raw, bool) or size_raw < 0:
            raise TypeError("Staged finalization returned an invalid nonnegative size")
        if self._detached_delta_storage:
            return _decode_finalized(
                self._upload,
                _MaterializedFinalizationResult(
                    actual_sha256=actual,
                    expected_sha256=expected,
                    state=state,
                    size_bytes=size_raw,
                    compression_algorithm=StagedFieldCompressionAlgorithm.NONE,
                    storage_chunk_count=0,
                    storage_backend=StagedFieldStorageBackend("database"),
                    delta_chain_depth=0,
                    delta_chunk_count=0,
                ),
            )
        compression_raw = value.get("compression_algorithm")
        backend_raw = value.get("storage_backend")
        storage_chunk_count_raw = value.get("storage_chunk_count")
        delta_chain_depth_raw = value.get("delta_chain_depth")
        delta_chunk_count_raw = value.get("delta_chunk_count")
        if not isinstance(compression_raw, str) or not isinstance(backend_raw, str):
            raise TypeError("Staged finalization omitted required storage metadata")
        integer_metadata = (
            storage_chunk_count_raw,
            delta_chain_depth_raw,
            delta_chunk_count_raw,
        )
        if any(not isinstance(item, int) or isinstance(item, bool) or item < 0 for item in integer_metadata):
            raise TypeError("Staged finalization returned invalid nonnegative integer metadata")
        assert isinstance(storage_chunk_count_raw, int)
        assert isinstance(delta_chain_depth_raw, int)
        assert isinstance(delta_chunk_count_raw, int)
        try:
            compression = StagedFieldCompressionAlgorithm(compression_raw)
        except ValueError as exc:
            raise StagedFieldError("Staged finalization returned unsupported storage metadata") from exc
        size_bytes = size_raw
        storage_chunk_count = storage_chunk_count_raw
        storage_backend = StagedFieldStorageBackend(backend_raw)
        delta_chain_depth = delta_chain_depth_raw
        delta_chunk_count = delta_chunk_count_raw
        delta_base_raw = value.get("delta_base_hash")
        result: _FinalizationResult
        if delta_base_raw is None:
            result = _MaterializedFinalizationResult(
                actual_sha256=actual,
                expected_sha256=expected,
                state=state,
                size_bytes=size_bytes,
                compression_algorithm=compression,
                storage_chunk_count=storage_chunk_count,
                storage_backend=storage_backend,
                delta_chain_depth=delta_chain_depth,
                delta_chunk_count=delta_chunk_count,
            )
        else:
            result = _DeltaFinalizationResult(
                actual_sha256=actual,
                expected_sha256=expected,
                state=state,
                size_bytes=size_bytes,
                compression_algorithm=compression,
                storage_chunk_count=storage_chunk_count,
                storage_backend=storage_backend,
                delta_chain_depth=delta_chain_depth,
                delta_chunk_count=delta_chunk_count,
                delta_base_sha256=_database_sha256(
                    delta_base_raw,
                    name="delta_base_hash",
                ),
            )
        return _decode_finalized(self._upload, result)


class DecodeStagedFieldRangeStep(_DecodeStagedFieldResultStep[bytes]):
    """Decode one database-owned bounded range result."""

    def execute_runtime(self, resolved: ResolvedRefs) -> bytes:
        from l7000_versioned_schema.staged_field_api import (
            StagedFieldCompressionAlgorithm,
            StagedFieldError,
        )
        from l7000_versioned_schema.staged_field_operations import (
            _ChunkedRangeResult,
            _ChunkStorageManifest,
            _CompressedRangeResult,
            _decode_range,
            _MissingRangeResult,
            _PlainRangeResult,
        )

        value = resolved.peek(self._source_ref)
        if value is None:
            return _decode_range(_MissingRangeResult())
        if not isinstance(value, dict):
            raise TypeError("The staged range read returned invalid metadata")
        payload_raw = value.get("payload")
        total_chunks = _database_nonnegative_integer(value.get("total_chunks"), name="total_chunks")
        compression_raw = value.get("compression_algorithm")
        if not isinstance(compression_raw, str):
            raise TypeError("Staged-field metadata 'compression_algorithm' must be a string")
        try:
            compression = StagedFieldCompressionAlgorithm(compression_raw)
        except ValueError as exc:
            raise StagedFieldError(
                f"Staged range read returned unsupported compression algorithm {compression_raw!r}",
            ) from exc
        requested_offset = _database_nonnegative_integer(
            value.get("requested_offset"),
            name="requested_offset",
        )
        requested_length = _database_nonnegative_integer(
            value.get("requested_length"),
            name="requested_length",
        )
        if total_chunks > 0:
            original_size = _database_nonnegative_integer(
                value.get("original_size"),
                name="original_size",
            )
            if isinstance(payload_raw, bytes):
                manifest = _ChunkStorageManifest(payload_raw.decode())
            elif isinstance(payload_raw, str):
                manifest = _ChunkStorageManifest(payload_raw)
            elif payload_raw is None and requested_offset >= original_size:
                manifest = _ChunkStorageManifest("[]")
            else:
                raise TypeError("Chunked range metadata omitted its storage manifest")
            chunk_size = _database_nonnegative_integer(value.get("chunk_size"), name="chunk_size")
            if chunk_size == 0:
                raise TypeError("Chunked range metadata requires a positive chunk size")
            return _decode_range(
                _ChunkedRangeResult(
                    manifest=manifest,
                    compression_algorithm=compression,
                    requested_offset=requested_offset,
                    requested_length=requested_length,
                    original_size=original_size,
                    chunk_size=chunk_size,
                    content_hash=_database_sha256(value.get("content_hash"), name="content_hash"),
                ),
            )
        if payload_raw is None:
            payload = b""
        elif isinstance(payload_raw, bytes):
            payload = payload_raw
        elif isinstance(payload_raw, memoryview):
            payload = payload_raw.tobytes()
        elif isinstance(payload_raw, str):
            encoded = payload_raw[2:] if payload_raw.startswith("\\x") else payload_raw
            payload = bytes.fromhex(encoded)
        else:
            raise TypeError("The staged range read returned an invalid binary payload")
        if compression is StagedFieldCompressionAlgorithm.NONE:
            return _decode_range(_PlainRangeResult(payload=payload))
        return _decode_range(
            _CompressedRangeResult(
                payload=payload,
                compression_algorithm=compression,
                requested_offset=requested_offset,
                requested_length=requested_length,
                content_hash=_database_sha256(value.get("content_hash"), name="content_hash"),
            ),
        )


class DecodeDeltaLargeColumnRangeStep(_DecodeStagedFieldResultStep[bytes]):
    """Validate and slice one bounded sequence of delta-storage chunks."""

    def execute_runtime(self, resolved: ResolvedRefs) -> bytes:
        from l7000_versioned_schema.staged_field_operations import (
            _DeltaLargeColumnRangeRow,
            _decode_delta_large_column_range,
        )

        value = resolved.peek(self._source_ref)
        if not isinstance(value, list) or not all(isinstance(row, dict) for row in value):
            raise TypeError("The delta large-column range returned invalid rows")
        rows = [_DeltaLargeColumnRangeRow(row) for row in value]
        return _decode_delta_large_column_range(rows)


class OpenLargeColumnReadStep(NonPublishingStep["LargeColumnReadLookup"]):
    """Convert one authorized pointer projection into an opaque read handle."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        pointer_ref: ServerPlanRefId,
        inline_payload_ref: ServerPlanRefId,
        owner_session_id: SessionId,
        model_cls: type[DatabaseObjectRow[SysId]],
        row_id: SysId,
        field_name: DynamicFieldName,
        delta_storage_enabled: bool,
    ) -> None:
        super().__init__(ref_id)
        if pointer_ref == inline_payload_ref:
            raise ValueError("Published large-column reads require distinct projection references")
        if not isinstance(delta_storage_enabled, bool):
            raise TypeError("delta_storage_enabled must be a boolean")
        self._pointer_ref = pointer_ref
        self._inline_payload_ref = inline_payload_ref
        self._owner_session_id = owner_session_id
        self._model_cls = model_cls
        self._row_id = row_id
        self._field_name = field_name
        self._delta_storage_enabled = delta_storage_enabled

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self) -> bool:
        return True

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def dependencies(self) -> frozenset[str]:
        return frozenset({self._pointer_ref, self._inline_payload_ref})

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def consumes_executor_visible_dependencies(self) -> bool:
        return True

    def execute_runtime(self, resolved: ResolvedRefs) -> LargeColumnReadLookup:
        from l7000_versioned_schema.staged_field_api import StagedFieldError, StagedFieldSha256
        from l7000_versioned_schema.staged_field_operations import (
            DeltaStoredLargeColumnRead,
            InlineBinaryLargeColumnRead,
            InlineJsonLargeColumnRead,
            InlineTextLargeColumnRead,
            MissingLargeColumnRead,
            StoredLargeColumnRead,
            _InlineJsonAttachmentValue,
            _InlineTextAttachmentValue,
            _encode_inline_large_column_attachment,
            _large_column_config,
        )

        pointer_projection = resolved.peek(self._pointer_ref)
        inline_projection = resolved.peek(self._inline_payload_ref)
        if pointer_projection is not None and (not isinstance(pointer_projection, tuple) or len(pointer_projection) != 2):
            raise TypeError("The published large-column pointer projection is invalid")
        if inline_projection is not None and (not isinstance(inline_projection, tuple) or len(inline_projection) != 2):
            raise TypeError("The published inline large-column projection is invalid")
        if pointer_projection is not None and pointer_projection[0] != self._row_id:
            raise StagedFieldError("The published large-column pointer row identity is invalid")
        if inline_projection is not None and inline_projection[0] != self._row_id:
            raise StagedFieldError("The published inline large-column row identity is invalid")
        pointer = None if pointer_projection is None else pointer_projection[1]
        inline_payload = None if inline_projection is None else inline_projection[1]
        if pointer is not None and inline_payload is not None:
            raise StagedFieldError("The published large-column attachment is ambiguous")
        if pointer is None and inline_payload is None:
            return MissingLargeColumnRead(
                model_cls=self._model_cls,
                row_id=self._row_id,
                field_name=self._field_name,
            )
        if pointer is not None and not isinstance(pointer, str):
            raise StagedFieldError("The published large-column pointer is invalid")
        config = _large_column_config(self._model_cls, self._field_name)
        configured_delta_storage = config.delta_storage is not None and config.delta_storage.enabled
        if configured_delta_storage != self._delta_storage_enabled:
            raise StagedFieldError("The published large-column storage mode does not match its schema")
        if pointer is not None:
            if self._delta_storage_enabled:
                try:
                    content_value_id = SysId(pointer)
                except (TypeError, ValueError) as exc:
                    raise StagedFieldError("The published delta content value ID is invalid") from exc
                if str(content_value_id) != pointer:
                    raise StagedFieldError("The published delta content value ID is not canonical")
                return DeltaStoredLargeColumnRead(
                    owner_session_id=self._owner_session_id,
                    model_cls=self._model_cls,
                    row_id=self._row_id,
                    field_name=self._field_name,
                    content_value_id=content_value_id,
                )
            normalized_pointer = pointer.lower()
            if (
                pointer != normalized_pointer
                or len(normalized_pointer) != 64
                or any(character not in "0123456789abcdef" for character in normalized_pointer)
            ):
                raise StagedFieldError("The published large-column SHA-256 pointer is invalid")
            return StoredLargeColumnRead(
                owner_session_id=self._owner_session_id,
                model_cls=self._model_cls,
                row_id=self._row_id,
                field_name=self._field_name,
                sha256=StagedFieldSha256(pointer),
            )
        assert inline_payload is not None
        attachment_payload: bytes | bytearray | memoryview | _InlineTextAttachmentValue | _InlineJsonAttachmentValue
        if config.content_type == "json":
            attachment_payload = _InlineJsonAttachmentValue(inline_payload)
        elif config.content_type == "text":
            if not isinstance(inline_payload, str):
                raise StagedFieldError("The published inline text large-column payload is invalid")
            attachment_payload = _InlineTextAttachmentValue(inline_payload)
        else:
            if not isinstance(inline_payload, bytes | bytearray | memoryview):
                raise StagedFieldError("The published inline binary large-column payload is invalid")
            attachment_payload = inline_payload
        encoded_payload = _encode_inline_large_column_attachment(attachment_payload, config.content_type)
        if config.content_type == "binary":
            return InlineBinaryLargeColumnRead(
                owner_session_id=self._owner_session_id,
                model_cls=self._model_cls,
                row_id=self._row_id,
                field_name=self._field_name,
                inline_payload=encoded_payload,
                inline_attachment=encoded_payload,
            )
        if config.content_type == "text":
            return InlineTextLargeColumnRead(
                owner_session_id=self._owner_session_id,
                model_cls=self._model_cls,
                row_id=self._row_id,
                field_name=self._field_name,
                inline_payload=encoded_payload,
                inline_attachment=encoded_payload,
            )
        return InlineJsonLargeColumnRead(
            owner_session_id=self._owner_session_id,
            model_cls=self._model_cls,
            row_id=self._row_id,
            field_name=self._field_name,
            inline_payload=encoded_payload,
            inline_attachment=encoded_payload,
        )

    def compile(self, ctx: CompilationContext) -> CompiledStep[LargeColumnReadLookup]:
        del ctx
        return CompiledStep()


class ValidatePublishedRangeAttachmentStep(NonPublishingStep[bytes]):
    """Expose a range only while its versioned row retains the opened attachment."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        attachment_ref: ServerPlanRefId,
        range_ref: ServerPlanRefId | None,
        expected_row_id: SysId,
        expected_attachment: StagedFieldSha256 | _LargeColumnPointerValue | bytes | str,
        literal_payload: bytes | None,
        range_is_delta: bool,
        attachment_content_type: LargeColumnKind | None = None,
    ) -> None:
        super().__init__(ref_id)
        if (range_ref is None) == (literal_payload is None):
            raise ValueError("Published large-column validation requires exactly one payload source")
        if range_is_delta and literal_payload is not None:
            raise ValueError("A delta large-column validation requires a range result")
        self._attachment_ref = attachment_ref
        self._range_ref = range_ref
        self._expected_row_id = expected_row_id
        self._expected_attachment = expected_attachment
        self._attachment_content_type = attachment_content_type
        self._literal_payload = literal_payload
        self._range_is_delta = range_is_delta

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self) -> bool:
        return True

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def dependencies(self) -> frozenset[str]:
        refs = {str(self._attachment_ref)}
        if self._range_ref is not None:
            refs.add(str(self._range_ref))
        return frozenset(refs)

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def consumes_executor_visible_dependencies(self) -> bool:
        return True

    def execute_runtime(self, resolved: ResolvedRefs) -> bytes:
        projection = resolved.peek(self._attachment_ref)
        if projection is None:
            raise StagedFieldAuthorizationError("The published large-column row has no attached content value")
        if not isinstance(projection, tuple) or len(projection) != 2:
            raise TypeError("The published large-column attachment projection is invalid")
        row_id, attachment = projection
        if row_id != self._expected_row_id:
            raise StagedFieldAuthorizationError("The published large-column row identity changed")
        if self._attachment_content_type is not None:
            from l7000_versioned_schema.staged_field_api import StagedFieldError
            from l7000_versioned_schema.staged_field_operations import (
                _InlineJsonAttachmentValue,
                _InlineTextAttachmentValue,
                _encode_inline_large_column_attachment,
            )

            content_type = self._attachment_content_type
            assert content_type in ("binary", "text", "json")
            attachment_payload: bytes | bytearray | memoryview | _InlineTextAttachmentValue | _InlineJsonAttachmentValue
            if content_type == "json":
                attachment_payload = _InlineJsonAttachmentValue(attachment)
            elif content_type == "text":
                if not isinstance(attachment, str):
                    raise StagedFieldError("The published inline text large-column payload is invalid")
                attachment_payload = _InlineTextAttachmentValue(attachment)
            else:
                if not isinstance(attachment, bytes | bytearray | memoryview):
                    raise StagedFieldError("The published inline binary large-column payload is invalid")
                attachment_payload = attachment
            attachment = _encode_inline_large_column_attachment(
                attachment_payload,
                content_type,
            )
        if attachment != self._expected_attachment:
            raise StagedFieldAuthorizationError("The published large-column attachment changed")
        if self._literal_payload is not None:
            return self._literal_payload
        assert self._range_ref is not None
        if self._range_is_delta:
            return DecodeDeltaLargeColumnRangeStep(
                ServerPlanRefId(f"{self.ref_id}:decode"),
                source_ref=self._range_ref,
            ).execute_runtime(resolved)
        return DecodeStagedFieldRangeStep(
            ServerPlanRefId(f"{self.ref_id}:decode"),
            source_ref=self._range_ref,
        ).execute_runtime(resolved)

    def compile(self, ctx: CompilationContext) -> CompiledStep[bytes]:
        del ctx
        return CompiledStep()


class _InitializedStagedFieldResultStep(NonPublishingStep[StagedFieldUpload]):
    """Return the manifest only after SQL initialized one authorized staged row."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        initialization_ref: ServerPlanRefId,
        upload: StagedFieldUpload,
    ) -> None:
        super().__init__(ref_id)
        self._initialization_ref = initialization_ref
        self._upload = upload

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self) -> bool:
        return True

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def dependencies(self) -> frozenset[str]:
        return frozenset({self._initialization_ref})

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def requires_prior_step_boundary(self) -> bool:
        return True

    def consumes_executor_visible_dependencies(self) -> bool:
        return True

