    def compile(self, ctx: CompilationContext) -> CompiledStep[StagedFieldUpload]:
        del ctx
        return CompiledStep()


class _OrdinaryStagedFieldAbortResultStep(NonPublishingStep[DiscardResult]):
    """Convert manifest deletion counts to the public discard result."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        deletion_refs: frozenset[ServerPlanRefId],
    ) -> None:
        super().__init__(ref_id)
        self._deletion_refs = deletion_refs

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self) -> bool:
        return True

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def dependencies(self) -> frozenset[str]:
        return frozenset(self._deletion_refs)

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def requires_prior_step_boundary(self) -> bool:
        return True

    def consumes_executor_visible_dependencies(self) -> bool:
        return True

    def execute_runtime(self, resolved: ResolvedRefs) -> DiscardResult:
        deleted = 0
        for ref_id in self._deletion_refs:
            value = resolved.peek(ref_id)
            assert isinstance(value, int)
            deleted += value
        return DiscardResult(staged_commits_deleted=0, staged_data_rows_deleted=deleted)

    def compile(self, ctx: CompilationContext) -> CompiledStep[DiscardResult]:
        del ctx
        return CompiledStep()


def _delete_staged_upload_steps(
    *,
    ref_prefix: ServerPlanRefId,
    stream_id: StagedFieldUploadId,
    owner_session_id: SessionId,
    after_refs: frozenset[ServerPlanRefId],
) -> tuple[list[ServerPlanStep[Any]], ServerPlanRefId]:
    """Delete physical upload rows in the order required by the delta-storage design.

    See ``docs/design/LARGE_COLUMN_DELTA_STORAGE.rst``. Explicit deletion is
    required because application-managed foreign keys do not provide a native
    cascade on every maintained backend.
    """
    chunk_ref = ServerPlanRefId(f"{ref_prefix}:delete_chunks")
    payload_ref = ServerPlanRefId(f"{ref_prefix}:delete_payload")
    manifest_ref = ServerPlanRefId(f"{ref_prefix}:delete")
    stream_table = SqlTableName("sys_staged_field_streams")
    return (
        [
            GrammarEffectStep(
                chunk_ref,
                SqlDeleteStagedFieldChunks(
                    stream_id=stream_id,
                    owner_session_id=owner_session_id,
                ),
                _GrammarExecuteConfig(
                    reads=frozenset(),
                    writes=frozenset({SqlTableName("sys_staged_field_stream_chunks")}),
                    after_refs=after_refs,
                    requires_prior_boundary=True,
                ),
            ),
            GrammarEffectStep(
                payload_ref,
                SqlDeleteStagedFieldPayload(
                    stream_id=stream_id,
                    owner_session_id=owner_session_id,
                ),
                _GrammarExecuteConfig(
                    reads=frozenset({stream_table}),
                    writes=frozenset({SqlTableName("sys_staged_field_stream_payloads")}),
                    after_refs=frozenset({chunk_ref}),
                    requires_prior_boundary=True,
                ),
            ),
            GrammarEffectStep(
                manifest_ref,
                SqlDeleteStagedFieldManifest(
                    stream_id=stream_id,
                    owner_session_id=owner_session_id,
                ),
                _GrammarExecuteConfig(
                    reads=frozenset(),
                    writes=frozenset({stream_table}),
                    after_refs=frozenset({payload_ref}),
                    requires_prior_boundary=True,
                ),
            ),
        ],
        manifest_ref,
    )


def _ordinary_abort_validation_steps(
    *,
    ref_prefix: ServerPlanRefId,
    stream_id: StagedFieldUploadId,
    owner_session_id: SessionId,
) -> tuple[tuple[ServerPlanStep[Any], ...], ServerPlanRefId]:
    manifest_ref = ServerPlanRefId(f"{ref_prefix}:manifest_scope")
    validation_ref = ServerPlanRefId(f"{ref_prefix}:scope_validation")
    return (
        (
            GrammarRowStep(
                manifest_ref,
                SqlReadOwnedStagedFieldManifest(
                    stream_id=stream_id,
                    owner_session_id=owner_session_id,
                ),
            ),
            ValidateOrdinaryStagedFieldAbortScopeStep(
                validation_ref,
                manifest_ref=manifest_ref,
            ),
        ),
        validation_ref,
    )


class OrdinaryStagedFieldAbortResultIntent(StagedFieldPlanStep[DiscardResult]):
    """Delete one ordinary upload inside the publication plan."""

    intent_tags = frozenset({"write", "staged_field", "ordinary", "abort", "intent"})
    intent_cardinality = Cardinality.ONE
    intent_read_only = False

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        stream_id: StagedFieldUploadId,
        owner_session_id: SessionId,
        after_refs: frozenset[ServerPlanRefId] = frozenset(),
    ) -> None:
        super().__init__(ref_id)
        self._stream_id = stream_id
        self._owner_session_id = owner_session_id
        self._after_refs = after_refs

    def lower(self, ctx: LoweringContext) -> Sequence[ServerPlanStep[Any]]:
        del ctx
        validation_steps, validation_ref = _ordinary_abort_validation_steps(
            ref_prefix=self.ref_id,
            stream_id=self._stream_id,
            owner_session_id=self._owner_session_id,
        )
        delete_steps, delete_ref = _delete_staged_upload_steps(
            ref_prefix=self.ref_id,
            stream_id=self._stream_id,
            owner_session_id=self._owner_session_id,
            after_refs=self._after_refs | frozenset({validation_ref}),
        )
        return (
            *validation_steps,
            *delete_steps,
            _OrdinaryStagedFieldAbortResultStep(
                self.ref_id,
                deletion_refs=frozenset({delete_ref}),
            ),
        )


class CleanupExpiredOrdinaryStagedFieldIntent(StagedFieldPlanStep[DiscardResult]):
    """Validate expiry before deleting one ordinary upload."""

    intent_tags = frozenset({"write", "staged_field", "ordinary", "cleanup", "intent"})
    intent_cardinality = Cardinality.ONE
    intent_read_only = False

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        stream_id: StagedFieldUploadId,
        owner_session_id: SessionId,
        cleanup_as_of: datetime,
    ) -> None:
        super().__init__(ref_id)
        self._stream_id = stream_id
        self._owner_session_id = owner_session_id
        self._cleanup_as_of = cleanup_as_of

    def lower(self, ctx: LoweringContext) -> Sequence[ServerPlanStep[Any]]:
        del ctx
        cleanup_check_ref = ServerPlanRefId(f"{self.ref_id}:cleanup_check")
        cleanup_validation_ref = ServerPlanRefId(f"{self.ref_id}:cleanup_validation")
        scope_steps, scope_validation_ref = _ordinary_abort_validation_steps(
            ref_prefix=self.ref_id,
            stream_id=self._stream_id,
            owner_session_id=self._owner_session_id,
        )
        delete_steps, delete_ref = _delete_staged_upload_steps(
            ref_prefix=self.ref_id,
            stream_id=self._stream_id,
            owner_session_id=self._owner_session_id,
            after_refs=frozenset({cleanup_validation_ref}),
        )
        return (
            *scope_steps,
            GrammarRowStep(
                cleanup_check_ref,
                SqlStagedFieldCleanupCheck(
                    stream_id=self._stream_id,
                    owner_session_id=self._owner_session_id,
                    as_of=self._cleanup_as_of,
                ),
                config=_GrammarRowConfig(
                    after_refs=frozenset({scope_validation_ref}),
                    output_columns=("writable", "expired"),
                ),
            ),
            ValidateStagedFieldCleanupStep(
                cleanup_validation_ref,
                check_ref=cleanup_check_ref,
            ),
            *delete_steps,
            _OrdinaryStagedFieldAbortResultStep(
                self.ref_id,
                deletion_refs=frozenset({delete_ref}),
            ),
        )


class _VersionedStagedFieldAbortResultStep(NonPublishingStep[DiscardResult]):
    """Return guarded versioned staging deletion counts."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        commit_ref: ServerPlanRefId,
        data_refs: frozenset[ServerPlanRefId],
        cleanup_ref: ServerPlanRefId,
    ) -> None:
        super().__init__(ref_id)
        self._commit_ref = commit_ref
        self._data_refs = data_refs
        self._cleanup_ref = cleanup_ref

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self) -> bool:
        return True

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def dependencies(self) -> frozenset[str]:
        return frozenset({self._commit_ref, self._cleanup_ref, *self._data_refs})

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def requires_prior_step_boundary(self) -> bool:
        return True

    def consumes_executor_visible_dependencies(self) -> bool:
