class AbortVersionedStagedFieldIntent(StagedFieldPlanStep[DiscardResult]):
    """Atomically discard a live upload's complete versioned staging scope."""

    intent_tags = frozenset({"write", "versioning", "staged_field", "abort", "intent"})
    intent_cardinality = Cardinality.ONE
    intent_read_only = False

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        domain: DomainType,
        stream_id: StagedFieldUploadId,
        owner_session_id: SessionId,
        branch_id: BranchId,
        connection_id: ConnectionId,
        staged_commit_id: StagedCommitId,
        workspace_id: WorkspaceId,
        table_key: StagedFieldTableKey,
        cleanup_as_of: datetime | None = None,
    ) -> None:
        super().__init__(ref_id)
        self._domain = domain
        self._stream_id = stream_id
        self._owner_session_id = owner_session_id
        self._branch_id = branch_id
        self._connection_id = connection_id
        self._staged_commit_id = staged_commit_id
        self._workspace_id = workspace_id
        self._table_key = table_key
        self._cleanup_as_of = cleanup_as_of

    def lower(self, ctx: LoweringContext) -> Sequence[ServerPlanStep[Any]]:
        del ctx
        from l1000_schema.column_utils import get_db_column_name
        from l1000_schema.large_column import get_large_column_configs
        from l1000_schema.table_utils import get_table_name
        from l1000_schema.typed_field import field

        stream_table = SqlTableName("sys_staged_field_streams")
        commit_model = self._domain.staged_commit_model
        commit_table = SqlTableName(get_table_name(commit_model))
        commit_id_column = get_db_column_name(commit_model, field(commit_model.sys_id).name)
        branch_column = get_db_column_name(commit_model, field(commit_model.branch_id).name)
        connection_column = get_db_column_name(commit_model, field(commit_model.connection_id).name)
        data_refs: list[ServerPlanRefId] = []
        manifest_ref = ServerPlanRefId(f"{self.ref_id}:manifest_scope")
        scope_validation_ref = ServerPlanRefId(f"{self.ref_id}:scope_validation")
        steps: list[ServerPlanStep[Any]] = [
            GrammarRowStep(
                manifest_ref,
                SqlReadOwnedStagedFieldManifest(
                    stream_id=self._stream_id,
                    owner_session_id=self._owner_session_id,
                ),
            ),
            ValidateStagedFieldAbortScopeStep(
                scope_validation_ref,
                manifest_ref=manifest_ref,
                table_key=self._table_key,
                branch_id=self._branch_id,
                connection_id=self._connection_id,
                staged_commit_id=self._staged_commit_id,
                workspace_id=self._workspace_id,
            ),
        ]
        prior_refs: frozenset[ServerPlanRefId] = frozenset({scope_validation_ref})
        if self._cleanup_as_of is not None:
            cleanup_check_ref = ServerPlanRefId(f"{self.ref_id}:cleanup_check")
            cleanup_validation_ref = ServerPlanRefId(f"{self.ref_id}:cleanup_validation")
            steps.extend(
                (
                    GrammarRowStep(
                        cleanup_check_ref,
                        SqlStagedFieldCleanupCheck(
                            stream_id=self._stream_id,
                            owner_session_id=self._owner_session_id,
                            as_of=self._cleanup_as_of,
                        ),
                        config=_GrammarRowConfig(
                            after_refs=prior_refs,
                            output_columns=("writable", "expired"),
                        ),
                    ),
                    ValidateStagedFieldCleanupStep(
                        cleanup_validation_ref,
                        check_ref=cleanup_check_ref,
                    ),
                ),
            )
            prior_refs = frozenset({cleanup_validation_ref})
        for model in self._domain.all_versioned_models():
            model_table = get_table_name(model)
            table = SqlTableName(derive_versioned_table_names(VersionedBaseTableName(str(model_table))).staged)
            if get_large_column_configs(model):
                release_ref = ServerPlanRefId(f"{self.ref_id}:release:{model_table}")
                steps.append(
                    GrammarEffectStep(
                        release_ref,
                        SqlReleaseAbortedStagedFieldContent(
                            content_store_table=SqlTableName(f"{model_table}_content_store"),
                            stream_id=self._stream_id,
                            owner_session_id=self._owner_session_id,
                            branch_id=self._branch_id,
                            connection_id=self._connection_id,
                            table_key=SqlTableName(model_table),
                        ),
                        _GrammarExecuteConfig(
                            reads=frozenset({stream_table}),
                            writes=frozenset({SqlTableName(f"{model_table}_content_store")}),
                            after_refs=prior_refs,
                            requires_prior_boundary=bool(prior_refs),
                        ),
                    ),
                )
                prior_refs = frozenset({release_ref})
            staged_commit_column = SqlColumnName("sys_staged_commit_id")
            data_ref = ServerPlanRefId(f"{self.ref_id}:data:{table}")
            data_refs.append(data_ref)
            steps.append(
                GrammarEffectStep(
                    data_ref,
                    SqlAbortStagedFieldScope(
                        target_table=table,
                        staged_commit_table=commit_table,
                        staged_commit_column=staged_commit_column,
                        staged_commit_id_column=commit_id_column,
                        branch_column=branch_column,
                        connection_column=connection_column,
                        stream_id=self._stream_id,
                        owner_session_id=self._owner_session_id,
                        branch_id=self._branch_id,
                        connection_id=self._connection_id,
                    ),
                    _GrammarExecuteConfig(
                        reads=frozenset({commit_table, stream_table}),
                        writes=frozenset({table}),
                        after_refs=prior_refs,
                        requires_prior_boundary=bool(prior_refs),
                    ),
                ),
            )
            prior_refs = frozenset({data_ref})
        commit_ref = ServerPlanRefId(f"{self.ref_id}:commits")
        steps.append(
            GrammarEffectStep(
                commit_ref,
                SqlAbortStagedFieldCommits(
                    staged_commit_table=commit_table,
                    branch_column=branch_column,
                    connection_column=connection_column,
                    stream_id=self._stream_id,
                    owner_session_id=self._owner_session_id,
                    branch_id=self._branch_id,
                    connection_id=self._connection_id,
                ),
                _GrammarExecuteConfig(
                    reads=frozenset({stream_table}),
                    writes=frozenset({commit_table}),
                    after_refs=prior_refs,
                    requires_prior_boundary=bool(prior_refs),
                ),
            ),
        )
        delete_steps, delete_ref = _delete_staged_upload_steps(
            ref_prefix=self.ref_id,
            stream_id=self._stream_id,
            owner_session_id=self._owner_session_id,
            after_refs=frozenset({commit_ref}),
        )
        steps.extend(delete_steps)
        steps.append(
            _VersionedStagedFieldAbortResultStep(
                self.ref_id,
                commit_ref=commit_ref,
                data_refs=frozenset(data_refs),
                cleanup_ref=delete_ref,
            ),
        )
        return steps


