class InitializeStagedFieldIntent(StagedFieldPlanStep[StagedFieldUpload]):
    """Allocate a staged field's placeholder bytes in database execution."""

    intent_tags = frozenset({"write", "versioning", "staged_field", "intent"})
    intent_cardinality = Cardinality.NONE
    intent_read_only = False

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        staged_table: SqlTableName,
        tip_table: SqlTableName,
        staged_commits_table: SqlTableName,
        branches_table: SqlTableName,
        payload_column: SqlColumnName,
        pointer_column: SqlColumnName,
        row_id: SysId,
        staged_commit_id: StagedCommitId | None,
        owner_session_id: SessionId,
        branch_id: BranchId,
        connection_id: ConnectionId,
        workspace_id: WorkspaceId,
        stream_id: StagedFieldUploadId,
        expected_size: int,
        manifest: StagedFieldStream,
        upload: StagedFieldUpload,
        after_refs: frozenset[ServerPlanRefId] = frozenset(),
    ) -> None:
        super().__init__(ref_id)
        self._staged_table = staged_table
        self._tip_table = tip_table
        self._staged_commits_table = staged_commits_table
        self._branches_table = branches_table
        self._payload_column = payload_column
        self._pointer_column = pointer_column
        self._row_id = row_id
        self._staged_commit_id = staged_commit_id
        self._owner_session_id = owner_session_id
        self._branch_id = branch_id
        self._connection_id = connection_id
        self._workspace_id = workspace_id
        self._stream_id = stream_id
        self._expected_size = expected_size
        self._manifest = manifest
        self._upload = upload
        self._after_refs = after_refs

    def lower(self, ctx: LoweringContext) -> Sequence[ServerPlanStep[Any]]:
        del ctx
        manifest_ref = ServerPlanRefId(f"{self.ref_id}:manifest")
        capture_ref = ServerPlanRefId(f"{self.ref_id}:candidate_base")
        initialize_ref = ServerPlanRefId(f"{self.ref_id}:initialize")
        capture = SqlCaptureStagedFieldCandidateBase(
            staged_table=self._staged_table,
            tip_table=self._tip_table,
            branches_table=self._branches_table,
            pointer_column=self._pointer_column,
            row_id=self._row_id,
            staged_commit_id=self._staged_commit_id,
            branch_id=self._branch_id,
            stream_id=self._stream_id,
        )
        statement = SqlInitializeStagedField(
            staged_table=self._staged_table,
            staged_commits_table=self._staged_commits_table,
            branches_table=self._branches_table,
            payload_column=self._payload_column,
            pointer_column=self._pointer_column,
            row_id=self._row_id,
            staged_commit_id=self._staged_commit_id,
            owner_session_id=self._owner_session_id,
            branch_id=self._branch_id,
            connection_id=self._connection_id,
            workspace_id=self._workspace_id,
            expected_size=self._expected_size,
        )
        return (
            GrammarEffectStep(
                manifest_ref,
                SqlCreateStagedFieldManifest(self._manifest),
                _GrammarExecuteConfig(
                    reads=frozenset(),
                    writes=frozenset({SqlTableName("sys_staged_field_streams")}),
                    after_refs=self._after_refs,
                    requires_prior_boundary=bool(self._after_refs),
                ),
            ),
            GrammarEffectStep(
                capture_ref,
                capture,
                _GrammarExecuteConfig(
                    reads=frozenset({self._staged_table, self._tip_table, self._branches_table}),
                    writes=frozenset({SqlTableName("sys_staged_field_streams")}),
                    after_refs=frozenset({manifest_ref}),
                    requires_prior_boundary=True,
                ),
            ),
            GrammarEffectStep(
                initialize_ref,
                statement,
                _GrammarExecuteConfig(
                    reads=frozenset(
                        {self._staged_table, self._staged_commits_table, self._branches_table},
                    ),
                    writes=frozenset({self._staged_table}),
                    after_refs=frozenset({capture_ref}),
                    requires_prior_boundary=True,
                ),
            ),
            _InitializedStagedFieldResultStep(
                self.ref_id,
                initialization_ref=initialize_ref,
                upload=self._upload,
            ),
        )


class InitializeOrdinaryStagedFieldIntent(StagedFieldPlanStep[StagedFieldUpload]):
    """Allocate a hidden ordinary-model staged payload in database execution."""

    intent_tags = frozenset({"write", "staged_field", "ordinary", "intent"})
    intent_cardinality = Cardinality.NONE
    intent_read_only = False

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        payload_table: SqlTableName,
        target_table: SqlTableName,
        target_payload_column: SqlColumnName,
        target_pointer_column: SqlColumnName,
        target_row_id: SysId,
        stream_id: StagedFieldUploadId,
        owner_session_id: SessionId,
        expected_size: int,
        capture_candidate_base: bool,
        manifest: StagedFieldStream,
        upload: StagedFieldUpload,
        content_type: LargeColumnKind = "binary",
        after_refs: frozenset[ServerPlanRefId] = frozenset(),
    ) -> None:
        super().__init__(ref_id)
        self._payload_table = payload_table
        self._target_table = target_table
        self._target_payload_column = target_payload_column
        self._target_pointer_column = target_pointer_column
        self._target_row_id = target_row_id
        self._stream_id = stream_id
        self._owner_session_id = owner_session_id
        self._expected_size = expected_size
        self._capture_candidate_base = capture_candidate_base
        self._manifest = manifest
        self._upload = upload
        self._content_type: LargeColumnKind = content_type
        self._after_refs = after_refs

    def lower(self, ctx: LoweringContext) -> Sequence[ServerPlanStep[Any]]:
        del ctx
        manifest_ref = ServerPlanRefId(f"{self.ref_id}:manifest")
        capture_ref = ServerPlanRefId(f"{self.ref_id}:candidate_base")
        initialize_ref = ServerPlanRefId(f"{self.ref_id}:initialize")
        capture_steps: tuple[ServerPlanStep[Any], ...] = ()
        initialize_after_ref = manifest_ref
        if self._capture_candidate_base:
            capture = SqlCaptureOrdinaryStagedFieldCandidateBase(
                target_table=self._target_table,
                payload_column=self._target_payload_column,
                pointer_column=self._target_pointer_column,
                row_id=self._target_row_id,
                stream_id=self._stream_id,
                content_type=self._content_type,
            )
            capture_steps = (
                GrammarEffectStep(
                    capture_ref,
                    capture,
                    _GrammarExecuteConfig(
                        reads=frozenset({self._target_table}),
                        writes=frozenset({SqlTableName("sys_staged_field_streams")}),
                        after_refs=frozenset({manifest_ref}),
                        requires_prior_boundary=True,
                    ),
                ),
            )
            initialize_after_ref = capture_ref
        statement = SqlInitializeOrdinaryStagedField(
            payload_table=self._payload_table,
            stream_id=self._stream_id,
            owner_session_id=self._owner_session_id,
            expected_size=self._expected_size,
        )
        return (
            GrammarEffectStep(
                manifest_ref,
                SqlCreateStagedFieldManifest(self._manifest),
                _GrammarExecuteConfig(
                    reads=frozenset(),
                    writes=frozenset({SqlTableName("sys_staged_field_streams")}),
                    after_refs=self._after_refs,
                    requires_prior_boundary=bool(self._after_refs),
                ),
            ),
            *capture_steps,
            GrammarEffectStep(
                initialize_ref,
                statement,
                _GrammarExecuteConfig(
                    reads=frozenset({SqlTableName("sys_staged_field_streams")}),
                    writes=frozenset({self._payload_table}),
                    after_refs=frozenset({initialize_after_ref}),
                    requires_prior_boundary=True,
                ),
            ),
            _InitializedStagedFieldResultStep(
                self.ref_id,
                initialization_ref=initialize_ref,
                upload=self._upload,
            ),
        )


class FinalizeStagedFieldIntent(StagedFieldPlanStep[dict[str, Any] | None]):
    """Calculate, validate, and return a staged field's manifest hash."""

    intent_tags = frozenset({"write", "versioning", "staged_field", "finalize", "intent"})
    intent_cardinality = Cardinality.ONE
    intent_read_only = False

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        staged_table: SqlTableName,
        payload_column: SqlColumnName,
        pointer_column: SqlColumnName,
        content_store_table: SqlTableName,
        row_id: SysId,
        manifest_row_id: SysId,
        staged_commit_id: StagedCommitId | None,
        stream_id: StagedFieldUploadId,
        owner_session_id: SessionId,
        table_key: SqlTableName,
        column_key: DynamicFieldName,
        expected_size: int,
        chunk_size: int,
        total_chunks: int,
        size_mode: StagedFieldSizeMode,
        source_pointer_column: SqlColumnName | None = None,
        pointer_table: SqlTableName | None = None,
        pointer_row_id: SysId | None = None,
        pointer_payload_column: SqlColumnName | None = None,
        payload_uses_stream_id: bool = False,
        authorization_ref: ServerPlanRefId | None = None,
        storage_chunk_count: int = 0,
        storage_chunk_size: int = 0,
        storage_compression: StagedFieldStorageCompression = StagedFieldStorageCompression.NONE,
        storage_backend: StagedFieldStorageBackend = StagedFieldStorageBackend("database"),
        content_type: LargeColumnKind = "binary",
        delta_enabled: bool = False,
        max_delta_chain_depth: int = 1,
        detached_delta_storage: bool = False,
        dynamic_inline_threshold: int | None = None,
    ) -> None:
        super().__init__(ref_id)
        self._staged_table = staged_table
        self._payload_column = payload_column
        self._pointer_column = pointer_column
        self._owner_session_id = owner_session_id
        self._content_store_table = content_store_table
        self._source_pointer_column = source_pointer_column or pointer_column
        self._row_id = row_id
        self._manifest_row_id = manifest_row_id
        self._staged_commit_id = staged_commit_id
        self._stream_id = stream_id
        self._table_key = table_key
        self._column_key = column_key
        self._expected_size = expected_size
        self._chunk_size = chunk_size
        self._total_chunks = total_chunks
        self._size_mode = size_mode
        self._pointer_table = pointer_table or staged_table
        self._pointer_row_id = row_id if pointer_row_id is None else pointer_row_id
        self._pointer_payload_column = pointer_payload_column or payload_column
        self._payload_uses_stream_id = payload_uses_stream_id
        self._authorization_ref = authorization_ref
        self._storage_chunk_count = storage_chunk_count
        self._storage_chunk_size = storage_chunk_size
        self._storage_compression = storage_compression
        self._storage_backend = storage_backend
        self._content_type: LargeColumnKind = content_type
        self._delta_enabled = delta_enabled
        self._max_delta_chain_depth = max_delta_chain_depth
        self._detached_delta_storage = detached_delta_storage
        self._dynamic_inline_threshold = dynamic_inline_threshold

    def dependencies(self) -> frozenset[str]:
        if self._authorization_ref is None:
            return frozenset()
        return frozenset({self._authorization_ref})

    def lower(self, ctx: LoweringContext) -> Sequence[ServerPlanStep[Any]]:
        del ctx
        stream_table = SqlTableName("sys_staged_field_streams")
        chunk_table = SqlTableName("sys_staged_field_stream_chunks")
        authorization_steps: tuple[ServerPlanStep[Any], ...] = ()
        hash_after_refs: frozenset[ServerPlanRefId] = frozenset()
        if self._authorization_ref is not None and not self._detached_delta_storage:
            from l7000_versioned_schema.staged_field_api import StagedFieldTargetAttachmentError

            authorization_assertion_ref = ServerPlanRefId(f"{self.ref_id}:authorization")
            authorization_steps = (
                RequireAffectedCountStep(
                    authorization_assertion_ref,
                    source=AffectedCountSourceContract(
                        sql_ref=self._authorization_ref,
                        producer_ref=self._authorization_ref,
                        scheduling_dependency_ref=self._authorization_ref,
                        representation=AffectedCountSourceRepresentation.SCALAR_COUNT,
                        value_column=LockedColumnName("count"),
                        ordered_statement_mode=AffectedCountOrderedStatementMode.DRIVER_COUNT,
                    ),
                    expectation="at_least_one",
                    error_message="The streamed target row is absent or unavailable",
                    rollback_prior_writes=RollbackPriorWrites(True),
                    error_cls=StagedFieldTargetAttachmentError,
                ),
            )
            hash_after_refs = frozenset({authorization_assertion_ref})
        materialize_ref = ServerPlanRefId(f"{self.ref_id}:materialize")
        hash_ref = ServerPlanRefId(f"{self.ref_id}:hash")
        finalize_ref = ServerPlanRefId(f"{self.ref_id}:state")
        release_ref = ServerPlanRefId(f"{self.ref_id}:release_candidate")
        store_ref = ServerPlanRefId(f"{self.ref_id}:store")
        source_pointer_ref = ServerPlanRefId(f"{self.ref_id}:source_pointer")
        pointer_ref = ServerPlanRefId(f"{self.ref_id}:pointer")
        materialize_steps: tuple[HeterogeneousServerPlanStep, ...] = ()
        if self._detached_delta_storage or self._delta_enabled or (
            self._storage_backend == StagedFieldStorageBackend("database")
            and self._storage_compression is StagedFieldStorageCompression.NONE
        ):
            materialize_steps = (
                GrammarEffectStep(
                    materialize_ref,
                    SqlMaterializeStagedField(
                        staged_table=self._staged_table,
                        payload_column=self._payload_column,
                        row_id=self._row_id,
                        manifest_row_id=self._manifest_row_id,
                        staged_commit_id=self._staged_commit_id,
                        stream_id=self._stream_id,
                        owner_session_id=self._owner_session_id,
                        table_key=self._table_key,
                        column_key=self._column_key,
                        size_mode=self._size_mode,
                    ),
                    _GrammarExecuteConfig(
                        reads=frozenset({stream_table, chunk_table}),
                        writes=frozenset({self._staged_table}),
                        after_refs=hash_after_refs,
                        requires_prior_boundary=bool(hash_after_refs),
                    ),
                ),
            )
            hash_after_refs = frozenset({materialize_ref})
        hash_statement = SqlCalculateStagedFieldHash(
            staged_table=self._staged_table,
            payload_column=self._payload_column,
            row_id=self._row_id,
            manifest_row_id=self._manifest_row_id,
            staged_commit_id=self._staged_commit_id,
            stream_id=self._stream_id,
            owner_session_id=self._owner_session_id,
            table_key=self._table_key,
            column_key=self._column_key,
            expected_size=self._expected_size,
            chunk_size=self._chunk_size,
            total_chunks=self._total_chunks,
            size_mode=self._size_mode,
        )
        finalize_statement = SqlFinalizeStagedFieldManifest(
            stream_id=self._stream_id,
            owner_session_id=self._owner_session_id,
            storage_backend=self._storage_backend,
        )
        store_statement = SqlPublishStagedFieldContent(
            staged_table=self._staged_table,
            payload_column=self._payload_column,
            pointer_column=self._source_pointer_column,
            content_store_table=self._content_store_table,
            row_id=self._row_id,
            staged_commit_id=self._staged_commit_id,
            stream_id=self._stream_id,
            payload_uses_stream_id=self._payload_uses_stream_id,
            physical_chunking=(self._storage_chunk_count > 0 or self._size_mode is StagedFieldSizeMode.UNKNOWN),
            storage_compression=self._storage_compression,
            storage_chunk_count=self._storage_chunk_count,
            storage_chunk_size=self._storage_chunk_size,
            storage_backend=self._storage_backend,
            content_type=self._content_type,
            delta_enabled=self._delta_enabled,
            max_delta_chain_depth=self._max_delta_chain_depth,
            dynamic_upload_chunks=self._size_mode is StagedFieldSizeMode.UNKNOWN,
            dynamic_inline_threshold=self._dynamic_inline_threshold,
        )
        source_pointer_statement = SqlPointStagedFieldToContent(
            staged_table=self._staged_table,
            payload_column=self._payload_column,
            pointer_column=self._source_pointer_column,
            row_id=self._row_id,
            staged_commit_id=self._staged_commit_id,
            stream_id=self._stream_id,
        )
        pointer_statement = SqlPointStagedFieldToContent(
            staged_table=self._pointer_table,
            payload_column=self._pointer_payload_column,
            pointer_column=self._pointer_column,
            row_id=self._pointer_row_id,
            staged_commit_id=self._staged_commit_id,
            stream_id=self._stream_id,
            require_candidate_match=self._payload_uses_stream_id,
            content_type=self._content_type,
        )
        check_statement = SqlStagedFieldFinalizationCheck(
            stream_id=self._stream_id,
            target_table=self._pointer_table,
            pointer_column=self._pointer_column,
            row_id=self._pointer_row_id,
            content_store_table=self._content_store_table,
            include_delta_metadata=self._delta_enabled,
        )
        if self._detached_delta_storage:
            return (
                *authorization_steps,
                *materialize_steps,
                GrammarEffectStep(
                    hash_ref,
                    hash_statement,
                    _GrammarExecuteConfig(
                        reads=frozenset({self._staged_table, stream_table, chunk_table}),
                        writes=frozenset({stream_table}),
                        after_refs=hash_after_refs,
                        requires_prior_boundary=bool(hash_after_refs),
                    ),
                ),
                GrammarEffectStep(
                    finalize_ref,
                    finalize_statement,
                    _GrammarExecuteConfig(
                        reads=frozenset({stream_table}),
                        writes=frozenset({stream_table}),
                        after_refs=frozenset({hash_ref}),
                        requires_prior_boundary=True,
                    ),
                ),
                GrammarRowStep(
                    self.ref_id,
                    SqlStagedFieldFinalizationCheck(stream_id=self._stream_id),
                    config=_GrammarRowConfig(
                        after_refs=frozenset({finalize_ref}),
                        output_columns=("actual_sha256", "expected_sha256", "state", "expected_size"),
                    ),
                ),
            )
        release_steps: tuple[ServerPlanStep[Any], ...] = ()
        source_pointer_steps: tuple[ServerPlanStep[Any], ...] = ()
        store_after_ref = finalize_ref
        pointer_after_ref = store_ref
        if self._payload_uses_stream_id:
            release_statement = SqlReleaseOrdinaryStagedFieldCandidateBase(
                content_store_table=self._content_store_table,
                target_table=self._pointer_table,
                pointer_column=self._pointer_column,
                row_id=self._pointer_row_id,
                stream_id=self._stream_id,
            )
            release_steps = (
                GrammarEffectStep(
                    release_ref,
                    release_statement,
                    _GrammarExecuteConfig(
                        reads=frozenset({stream_table}),
                        writes=frozenset({self._content_store_table}),
                        after_refs=frozenset({finalize_ref}),
                        supports_batch_transport=False,
                        requires_prior_boundary=True,
                        collect_row_count=False,
                    ),
                ),
            )
            store_after_ref = release_ref
            source_pointer_steps = (
                GrammarEffectStep(
                    source_pointer_ref,
                    source_pointer_statement,
                    _GrammarExecuteConfig(
                        reads=frozenset({stream_table}),
                        writes=frozenset({self._staged_table}),
                        after_refs=frozenset({store_ref}),
                        supports_batch_transport=False,
                        requires_prior_boundary=True,
                        collect_row_count=False,
                    ),
                ),
            )
            pointer_after_ref = source_pointer_ref
        chunk_steps: list[ServerPlanStep[Any]] = []
        chunk_after_ref = store_ref
        if self._size_mode is StagedFieldSizeMode.UNKNOWN:
            chunk_after_ref = ServerPlanRefId(f"{self.ref_id}:storage_chunks")
            dynamic_chunk_statement: SqlRenderable
            dynamic_chunk_reads = {stream_table, chunk_table, self._content_store_table}
            if self._dynamic_inline_threshold is None:
                dynamic_chunk_statement = SqlPublishUnknownSizeStagedFieldContentChunks(
                    content_store_table=self._content_store_table,
                    stream_id=self._stream_id,
                )
            else:
                dynamic_chunk_statement = SqlPublishUnknownSizeDatabaseContentChunks(
                    staged_table=self._staged_table,
                    payload_column=self._payload_column,
                    content_store_table=self._content_store_table,
                    row_id=self._row_id,
                    staged_commit_id=self._staged_commit_id,
                    stream_id=self._stream_id,
                    storage_chunk_size=self._storage_chunk_size,
                    inline_threshold=self._dynamic_inline_threshold,
                    payload_uses_stream_id=self._payload_uses_stream_id,
                )
                dynamic_chunk_reads.add(self._staged_table)
            chunk_steps.append(
                GrammarEffectStep(
                    chunk_after_ref,
                    dynamic_chunk_statement,
                    _GrammarExecuteConfig(
                        reads=frozenset(dynamic_chunk_reads),
                        writes=frozenset({SqlTableName(f"{self._content_store_table}_chunks")}),
                        after_refs=frozenset({store_ref}),
                        requires_prior_boundary=True,
                    ),
                ),
            )
        for chunk_index in range(self._storage_chunk_count if self._size_mode is StagedFieldSizeMode.KNOWN else 0):
            chunk_ref = ServerPlanRefId(f"{self.ref_id}:storage_chunk:{chunk_index}")
            chunk_steps.append(
                GrammarEffectStep(
                    chunk_ref,
                    SqlPublishStagedFieldContentChunk(
                        staged_table=self._staged_table,
                        payload_column=self._payload_column,
                        content_store_table=self._content_store_table,
                        row_id=self._row_id,
                        staged_commit_id=self._staged_commit_id,
                        stream_id=self._stream_id,
                        chunk_index=chunk_index,
                        storage_chunk_size=self._storage_chunk_size,
                        storage_compression=self._storage_compression,
                        storage_backend=self._storage_backend,
                        delta_enabled=self._delta_enabled,
                        payload_uses_stream_id=self._payload_uses_stream_id,
                    ),
                    _GrammarExecuteConfig(
                        reads=frozenset({self._staged_table, stream_table, self._content_store_table}),
                        writes=frozenset({SqlTableName(f"{self._content_store_table}_chunks")}),
                        after_refs=frozenset({chunk_after_ref}),
                        requires_prior_boundary=True,
                    ),
                ),
            )
            chunk_after_ref = chunk_ref
        if self._delta_enabled and chunk_steps:
            delta_metadata_ref = ServerPlanRefId(f"{self.ref_id}:delta_metadata")
            chunk_steps.append(
                GrammarEffectStep(
                    delta_metadata_ref,
                    SqlFinalizeStagedFieldDeltaMetadata(
                        content_store_table=self._content_store_table,
                        stream_id=self._stream_id,
                    ),
                    _GrammarExecuteConfig(
                        reads=frozenset(
                            {
                                stream_table,
                                SqlTableName(f"{self._content_store_table}_chunks"),
                            },
                        ),
                        writes=frozenset({self._content_store_table}),
                        after_refs=frozenset({chunk_after_ref}),
                        requires_prior_boundary=True,
                        collect_row_count=False,
                    ),
                ),
            )
            chunk_after_ref = delta_metadata_ref
        if chunk_steps:
            if source_pointer_steps:
                source_pointer_steps = (
                    GrammarEffectStep(
                        source_pointer_ref,
                        source_pointer_statement,
                        _GrammarExecuteConfig(
                            reads=frozenset({stream_table}),
                            writes=frozenset({self._staged_table}),
                            after_refs=frozenset({chunk_after_ref}),
                            supports_batch_transport=False,
                            requires_prior_boundary=True,
                            collect_row_count=False,
                        ),
                    ),
                )
                pointer_after_ref = source_pointer_ref
            else:
                pointer_after_ref = chunk_after_ref
        return (
            *authorization_steps,
            *materialize_steps,
            GrammarEffectStep(
                hash_ref,
                hash_statement,
                _GrammarExecuteConfig(
                    reads=frozenset({self._staged_table, stream_table, chunk_table}),
                    writes=frozenset({stream_table}),
                    after_refs=hash_after_refs,
                    requires_prior_boundary=bool(hash_after_refs),
                ),
            ),
            GrammarEffectStep(
                finalize_ref,
                finalize_statement,
                _GrammarExecuteConfig(
                    reads=frozenset({stream_table}),
                    writes=frozenset({stream_table}),
                    after_refs=frozenset({hash_ref}),
                    requires_prior_boundary=True,
                ),
            ),
            *release_steps,
            GrammarEffectStep(
                store_ref,
                store_statement,
                _GrammarExecuteConfig(
                    reads=frozenset({self._staged_table, stream_table}),
                    writes=frozenset({self._content_store_table}),
                    after_refs=frozenset({store_after_ref}),
                    supports_batch_transport=False,
                    requires_prior_boundary=True,
                    collect_row_count=False,
                ),
            ),
            *chunk_steps,
            *source_pointer_steps,
            GrammarEffectStep(
                pointer_ref,
                pointer_statement,
                _GrammarExecuteConfig(
                    reads=frozenset({stream_table}),
                    writes=frozenset(),
                    after_refs=frozenset({pointer_after_ref}),
                    supports_batch_transport=False,
                    requires_prior_boundary=True,
                    collect_row_count=False,
                ),
            ),
            GrammarRowStep(
                self.ref_id,
                check_statement,
                config=_GrammarRowConfig(
                    after_refs=frozenset({pointer_ref}),
                    output_columns=(
                        "actual_sha256",
                        "expected_sha256",
                        "state",
                        "expected_size",
                        "storage_chunk_count",
                        "compression_algorithm",
                        "storage_backend",
                        "delta_base_hash",
                        "delta_chain_depth",
                        "delta_chunk_count",
                    ),
                ),
            ),
        )


class ReadStagedFieldRangeIntent(StagedFieldPlanStep[dict[str, Any] | None]):
    """Read one bounded finalized-content range."""

    intent_tags = frozenset({"read", "staged_field", "range", "intent"})
    intent_cardinality = Cardinality.ONE
    intent_read_only = True

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        content_store_table: SqlTableName,
        content_hash: StagedFieldSha256 | None,
        offset: int,
        length: int,
        size_bytes: int | None = None,
        stream_id: StagedFieldUploadId | None = None,
        owner_session_id: SessionId | None = None,
        table_key: SqlTableName | None = None,
        source_table: SqlTableName | None = None,
        source_row_id: SysId | None = None,
        source_pointer_column: SqlColumnName | None = None,
        source_payload_column: SqlColumnName | None = None,
        inline_payload: bytes | None = None,
        inline_attachment: bytes | str | None = None,
        inline_is_text: bool = False,
    ) -> None:
        super().__init__(ref_id)
        self._content_store_table = content_store_table
        self._content_hash = content_hash
        self._offset = offset
        self._length = length
        self._size_bytes = size_bytes
        self._stream_id = stream_id
        self._owner_session_id = owner_session_id
        self._table_key = table_key
        self._source_table = source_table
        self._source_row_id = source_row_id
        self._source_pointer_column = source_pointer_column
        self._source_payload_column = source_payload_column
        self._inline_payload = inline_payload
        self._inline_attachment = inline_attachment
        self._inline_is_text = inline_is_text

    def lower(self, ctx: LoweringContext) -> Sequence[ServerPlanStep[Any]]:
        del ctx
        statement: SqlRenderable
        if self._inline_payload is not None:
            assert self._source_table is not None
            assert self._source_row_id is not None
            assert self._source_pointer_column is not None
            assert self._source_payload_column is not None
            statement = SqlReadPublishedInlineFieldRange(
                source_table=SqlTableName(self._source_table),
                source_row_id=self._source_row_id,
                source_payload_column=SqlColumnName(self._source_payload_column),
                source_pointer_column=SqlColumnName(self._source_pointer_column),
                expected_payload=(self._inline_attachment if self._inline_attachment is not None else self._inline_payload),
                payload_is_text=self._inline_is_text,
                offset=self._offset,
                length=self._length,
            )
        else:
            statement = SqlReadStagedFieldRange(
                content_store_table=self._content_store_table,
                content_hash=self._content_hash,
                offset=self._offset,
                length=self._length,
                size_bytes=self._size_bytes,
                stream_id=self._stream_id,
                owner_session_id=self._owner_session_id,
                table_key=self._table_key,
                source_table=self._source_table,
                source_row_id=self._source_row_id,
                source_pointer_column=self._source_pointer_column,
            )
        return (
            GrammarRowStep(
                self.ref_id,
                statement,
                config=_GrammarRowConfig(
                    output_columns=(
                        "payload",
                        "compression_algorithm",
                        "compression_level",
                        "original_size",
                        "content_hash",
                        "total_chunks",
                        "chunk_size",
                        "requested_offset",
                        "requested_length",
                    ),
                ),
            ),
        )


