class _StoreExternalStagedChunkStep(NonPublishingStep[dict[str, Any] | None]):
    """Store an accepted bounded chunk in the configured external backend."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        receipt_ref: ServerPlanRefId,
        backend_type: StagedFieldStorageBackend,
        payload: bytes,
    ) -> None:
        super().__init__(ref_id)
        self._receipt_ref = receipt_ref
        self._backend_type = backend_type
        self._payload = payload

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self) -> bool:
        return False

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def dependencies(self) -> frozenset[str]:
        return frozenset({str(self._receipt_ref)})

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def requires_prior_step_boundary(self) -> bool:
        return True

    def consumes_executor_visible_dependencies(self) -> bool:
        return True

    def execute_runtime(self, resolved: ResolvedRefs) -> dict[str, Any] | None:
        receipt = resolved.peek(self._receipt_ref)
        if receipt is None:
            return None
        if not isinstance(receipt, dict):
            raise TypeError("The staged chunk receipt has an invalid result type")
        if not _database_boolean(receipt.get("matches"), name="matches"):
            return receipt
        digest = hashlib.sha256(self._payload).hexdigest()
        from impl.common.l2550_storage_backend.large_column_service import (
            get_large_column_storage_backend,
        )

        backend = get_large_column_storage_backend()
        if backend is None or backend.backend_type != self._backend_type:
            raise RuntimeError("The staged-field storage backend changed during chunk execution")
        backend.store(digest, self._payload)
        result = dict(receipt)
        result["storage_backend"] = backend.backend_type
        return result

    def compile(self, ctx: CompilationContext) -> CompiledStep[dict[str, Any] | None]:
        del ctx
        return CompiledStep()


class WriteStagedFieldChunkIntent(StagedFieldPlanStep[dict[str, Any] | None]):
    """Write one bounded chunk into its assigned staged-field slot."""

    intent_tags = frozenset({"write", "versioning", "staged_field", "chunk", "intent"})
    intent_cardinality = Cardinality.ONE
    intent_read_only = False

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        staged_table: SqlTableName,
        payload_column: SqlColumnName,
        row_id: SysId,
        manifest_row_id: SysId,
        staged_commit_id: StagedCommitId | None,
        stream_id: StagedFieldUploadId,
        chunk_id: StagedFieldStreamChunkId,
        owner_session_id: SessionId,
        table_key: SqlTableName,
        column_key: DynamicFieldName,
        size_mode: StagedFieldSizeMode,
        chunk_index: int,
        offset: int,
        data: bytes,
        storage_payload: bytes,
        storage_compression: StagedFieldStorageCompression,
        external_backend_type: StagedFieldStorageBackend | None = None,
    ) -> None:
        super().__init__(ref_id)
        self._staged_table = staged_table
        self._payload_column = payload_column
        self._row_id = row_id
        self._manifest_row_id = manifest_row_id
        self._staged_commit_id = staged_commit_id
        self._stream_id = stream_id
        self._chunk_id = chunk_id
        self._owner_session_id = owner_session_id
        self._table_key = table_key
        self._column_key = column_key
        self._size_mode = size_mode
        self._chunk_index = chunk_index
        self._offset = offset
        self._data = data
        self._storage_payload = storage_payload
        self._storage_compression = storage_compression
        self._external_backend_type = external_backend_type

    def lower(self, ctx: LoweringContext) -> Sequence[ServerPlanStep[Any]]:
        del ctx
        chunk_table = SqlTableName("sys_staged_field_stream_chunks")
        record_ref = ServerPlanRefId(f"{self.ref_id}:record")
        patch_ref = ServerPlanRefId(f"{self.ref_id}:patch")
        record = SqlRecordStagedFieldChunk(
            stream_id=self._stream_id,
            chunk_id=self._chunk_id,
            owner_session_id=self._owner_session_id,
            chunk_index=self._chunk_index,
            data=self._data,
            storage_payload=self._storage_payload,
            storage_compression=self._storage_compression,
            storage_backend=(self._external_backend_type or StagedFieldStorageBackend("database")),
            size_mode=self._size_mode,
        )
        patch = SqlStagedFieldPatch(
            staged_table=self._staged_table,
            payload_column=self._payload_column,
            row_id=self._row_id,
            manifest_row_id=self._manifest_row_id,
            staged_commit_id=self._staged_commit_id,
            stream_id=self._stream_id,
            owner_session_id=self._owner_session_id,
            table_key=self._table_key,
            column_key=self._column_key,
            size_mode=self._size_mode,
            chunk_id=self._chunk_id,
            offset=self._offset,
            payload=self._data,
            chunk_index=self._chunk_index,
        )
        geometry_ref = ServerPlanRefId(f"{self.ref_id}:geometry")
        geometry_steps: tuple[HeterogeneousServerPlanStep, ...] = ()
        check_after_ref = patch_ref
        if self._size_mode is StagedFieldSizeMode.UNKNOWN:
            geometry_steps = (
                GrammarEffectStep(
                    geometry_ref,
                    SqlUpdateUnknownStagedFieldGeometry(
                        stream_id=self._stream_id,
                        owner_session_id=self._owner_session_id,
                        chunk_index=self._chunk_index,
                        chunk_size=len(self._data),
                    ),
                    _GrammarExecuteConfig(
                        reads=frozenset({SqlTableName("sys_staged_field_streams")}),
                        writes=frozenset({SqlTableName("sys_staged_field_streams")}),
                        after_refs=frozenset({patch_ref}),
                        requires_prior_boundary=True,
                    ),
                ),
            )
            check_after_ref = geometry_ref
        check_ref = self.ref_id if self._external_backend_type is None else ServerPlanRefId(f"{self.ref_id}:check")
        check = SqlStagedFieldChunkCheck(
            stream_id=self._stream_id,
            chunk_id=self._chunk_id,
            owner_session_id=self._owner_session_id,
            row_id=self._manifest_row_id,
            staged_commit_id=self._staged_commit_id,
            table_key=self._table_key,
            column_key=self._column_key,
            size_mode=self._size_mode,
            offset=self._offset,
            chunk_index=self._chunk_index,
            data=self._data,
        )
        return (
            GrammarEffectStep(
                record_ref,
                record,
                _GrammarExecuteConfig(
                    reads=frozenset({chunk_table}),
                    writes=frozenset({chunk_table}),
                ),
            ),
            GrammarEffectStep(
                patch_ref,
                patch,
                _GrammarExecuteConfig(
                    reads=frozenset(
                        {chunk_table, SqlTableName("sys_staged_field_streams"), self._staged_table},
                    ),
                    writes=frozenset({self._staged_table}),
                    after_refs=frozenset({record_ref}),
                    requires_prior_boundary=True,
                ),
            ),
            *geometry_steps,
            GrammarRowStep(
                check_ref,
                check,
                config=_GrammarRowConfig(
                    after_refs=frozenset({check_after_ref}),
                    output_columns=("chunk_sha256", "matches", "already_present"),
                ),
            ),
            *(
                (
                    _StoreExternalStagedChunkStep(
                        self.ref_id,
                        receipt_ref=check_ref,
                        backend_type=self._external_backend_type,
                        payload=self._storage_payload,
                    ),
                )
                if self._external_backend_type is not None
                else ()
            ),
        )


