class RevisionDiffSelectionError(ValueError):
    """Raised when a revision-diff selection is invalid."""


ModelT_co = TypeVar("ModelT_co", bound=VersionedObjectRow, covariant=True)


class RevisionDiffSelection(BaseModel, Generic[ModelT_co]):
    """Select one versioned model family and an optional row predicate."""

    model: type[ModelT_co]
    predicate: Expression[bool, ModelT_co] | Expression[bool | None, ModelT_co] | None = None

    model_config = ConfigDict(arbitrary_types_allowed=True, frozen=True)

    def __init__(
        self: Self,
        *,
        model: type[ModelT_co],
        predicate: Expression[bool, ModelT_co] | Expression[bool | None, ModelT_co] | None = None,
    ) -> None:
        if not isinstance(model, type) or not issubclass(model, VersionedObjectRow):
            msg = "Revision diff selection model must derive from VersionedObjectRow."
            raise RevisionDiffSelectionError(msg)
        if predicate is not None and not isinstance(predicate, Expression):
            msg = f"Revision diff predicate for {model.__name__} must be an Expression."
            raise RevisionDiffSelectionError(msg)
        try:
            super().__init__(model=model, predicate=predicate)
        except ValidationError as exc:
            msg = f"Revision diff selection for {model.__name__} is invalid."
            raise RevisionDiffSelectionError(msg) from exc


