def _build_revert_diff_cte(
    spec: _RevertDiffCteSpec,
    branch_expr: SqlRenderable,
) -> SqlTwoWayDiffCte:
    from impl.common.l2100_sql_grammar.domain.versioning.stmt_two_way_diff import SqlTwoWayDiffCte
    from impl.common.l2100_sql_grammar.domain.versioning.subquery_lookups import (
        SqlBranchTipSubquery,
    )

    from_revision: object = (
        SqlBranchTipSubquery(spec.from_revision.branch_table, branch_expr)
        if isinstance(spec.from_revision, _CurrentBranchTipRevision)
        else spec.from_revision
    )
    return SqlTwoWayDiffCte(
        old_revision_raw=cast(SqlGrammarValue | SqlRenderable, from_revision),
        new_revision_raw=cast(SqlGrammarValue | SqlRenderable, spec.to_revision),
        sparse_table=SqlTableName(spec.sparse_table),
        branch_id_raw=branch_expr if spec.diff_uses_write_branch else spec.diff_branch_id,
        data_columns=list(spec.data_columns),
        revision_table=SqlTableName(spec.revision_table),
        revision_parents_table=SqlTableName(spec.revision_parents_table),
        old_branch_id_raw=(branch_expr if spec.old_diff_uses_write_branch else spec.old_diff_branch_id),
    )


def _build_branch_aware_revert_statement(
    spec: _BranchAwareRevertStatementSpec,
    branch_expr: SqlRenderable,
) -> SqlRenderable:
    from impl.common.l2100_sql_grammar.domain.versioning.stmt_apply_diff_staged import (
        SqlRevertApplyToStaged,
        SqlRevertClearStagedCommit,
        SqlRevertCleanStaged,
        SqlRevertCountDiff,
    )

    match spec.kind:
        case "clear":
            return cast(
                "SqlRenderable",
                SqlRevertClearStagedCommit(
                    staged_table=spec.staged_table,
                    branch_id_raw=branch_expr,
                    staged_commit_id_raw=spec.staged_commit_id_raw,
                ),
            )
        case "clean":
            assert spec.diff_cte is not None
            return cast(
                "SqlRenderable",
                SqlRevertCleanStaged(
                    diff_cte=_build_revert_diff_cte(spec.diff_cte, branch_expr),
                    staged_table=spec.staged_table,
                    branch_id_raw=branch_expr,
                    staged_commit_id_raw=spec.staged_commit_id_raw,
                ),
            )
        case "apply":
            assert spec.diff_cte is not None
            return cast(
                "SqlRenderable",
                SqlRevertApplyToStaged(
                    diff_cte=_build_revert_diff_cte(spec.diff_cte, branch_expr),
                    staged_table=spec.staged_table,
                    branch_id_raw=branch_expr,
                    staged_commit_id_raw=spec.staged_commit_id_raw,
                    data_columns=list(spec.diff_cte.data_columns),
                ),
            )
        case "count":
            assert spec.diff_cte is not None
            return cast("SqlRenderable", SqlRevertCountDiff(diff_cte=_build_revert_diff_cte(spec.diff_cte, branch_expr)))


def _branch_source_from_raw(value: object) -> object:
    if isinstance(value, ScalarServerRef):
        return cast(ScalarServerRef[BranchId], value)
    if isinstance(value, BranchId):
        return value
    shape = inspect_server_value_shape_for_planning(value, site="_branch_source_from_raw")
    if shape.symbolic_ref_id is not None:
        return value
    if getattr(getattr(value, "_state", None), "name", None) == "RESOLVED":
        resolved_value = object.__getattribute__(value, "_value")
        if isinstance(resolved_value, ScalarServerRef | BranchId):
            return resolved_value
        return cast(BranchId, resolved_value)
    return value


class _BranchAwareGrammarEffectStep(GrammarEffectStep):
    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        stmt_spec: _BranchAwareRevertStatementSpec,
        branch_source: object,
        config: _GrammarExecuteConfig,
    ) -> None:
        super().__init__(
            ref_id,
            _build_branch_aware_revert_statement(stmt_spec, _BRANCH_PLACEHOLDER),
            config=config,
        )
        self._stmt_spec = stmt_spec
        self._branch_source = branch_source

    def dependencies(self) -> frozenset[str]:
        dependencies = getattr(self._branch_source, "dependencies", None)
        branch_dependencies = cast(Callable[[], frozenset[str]], dependencies)() if callable(dependencies) else frozenset()
        return super().dependencies() | branch_dependencies

    def compile(self, ctx: CompilationContext) -> CompiledStep[int]:
        self._stmt = _build_branch_aware_revert_statement(
            self._stmt_spec,
            lower_scalar_source(self._branch_source, ctx),
        )
        compiled = super().compile(ctx)
        return dataclass_replace_auxiliary_ctes(
            compiled,
            collect_dependency_auxiliary_ctes(ctx, self.dependencies()),
        )


class _BranchAwareGrammarRowStep(GrammarRowStep[dict[str, Any]]):
    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        stmt_spec: _BranchAwareRevertStatementSpec,
        branch_source: object,
        after_refs: frozenset[ServerPlanRefId] = frozenset(),
    ) -> None:
        super().__init__(
            ref_id,
            _build_branch_aware_revert_statement(stmt_spec, _BRANCH_PLACEHOLDER),
        )
        self._stmt_spec = stmt_spec
        self._branch_source = branch_source
        self._after_refs = after_refs

    def dependencies(self) -> frozenset[str]:
        dependencies = getattr(self._branch_source, "dependencies", None)
        branch_dependencies = cast(Callable[[], frozenset[str]], dependencies)() if callable(dependencies) else frozenset()
        return branch_dependencies | frozenset(str(ref) for ref in self._after_refs)

    def compile(self, ctx: CompilationContext) -> CompiledStep[dict[str, Any] | None]:
        self._stmt = _build_branch_aware_revert_statement(
            self._stmt_spec,
            lower_scalar_source(self._branch_source, ctx),
        )
        columns = ("added_count", "modified_count", "deleted_count")
        output_shape = CompiledOutputShape(
            tuple(synthetic_output_field(column, role="revert_count") for column in columns),
        )
        compiled: CompiledStep[dict[str, Any] | None] = CompiledStep(
            output_shape=output_shape,
            result_relation=DeclaredResultRelation.from_output_shape(output_shape),
            column_type_hints=SqlColumnTypeHints(bigint_columns=frozenset(columns)),
            grammar=self._stmt,
            needs_returning=True,
            closed_post_op=optional_single_row_post_op(),
        )
        return dataclass_replace_auxiliary_ctes(
            compiled,
            collect_dependency_auxiliary_ctes(ctx, self.dependencies()),
        )


def dataclass_replace_auxiliary_ctes[T](
    compiled: CompiledStep[T],
    auxiliary_ctes: Sequence[tuple[str, SqlRenderable]] | None,
) -> CompiledStep[T]:
    if auxiliary_ctes is None:
        return compiled

    existing = compiled.auxiliary_ctes or ()
    return replace(compiled, auxiliary_ctes=(*existing, *auxiliary_ctes))


