def _prefixed_model_column_hints(
    model_cls: type[VersionedObjectRow[Any]],
    data_columns: Sequence[str],
    prefixes: Sequence[str],
    *,
    bytea_columns: frozenset[str] = frozenset(),
) -> SqlColumnTypeHints:
    from l2070_batching.sql_column_type_hints import model_sql_column_type_hints

    base_hints = model_sql_column_type_hints(model_cls, tuple(data_columns)) or SqlColumnTypeHints()

    def _prefixed(columns: frozenset[str]) -> frozenset[str]:
        return frozenset(f"{prefix}_{column}" for prefix in prefixes for column in columns)

    hinted_columns = set().union(*base_hints.as_tuple())
    fallback_text_columns = set(data_columns) - hinted_columns - bytea_columns
    return SqlColumnTypeHints(
        jsonb_columns=_prefixed(base_hints.jsonb_columns),
        uuid_columns=_prefixed(base_hints.uuid_columns),
        timestamptz_columns=_prefixed(base_hints.timestamptz_columns),
        date_columns=_prefixed(base_hints.date_columns),
        time_columns=_prefixed(base_hints.time_columns),
        numeric_columns=_prefixed(base_hints.numeric_columns),
        bool_columns=_prefixed(base_hints.bool_columns),
        integer_columns=_prefixed(base_hints.integer_columns),
        bigint_columns=_prefixed(base_hints.bigint_columns),
        double_columns=_prefixed(base_hints.double_columns),
        text_columns=_prefixed(base_hints.text_columns | frozenset(fallback_text_columns)),
        bytea_columns=_prefixed(base_hints.bytea_columns | bytea_columns),
    )


def _row_to_dict(row: Any) -> dict[str, Any]:
