def _build_field_map(
    model_cls: type[VersionedObjectRow[Any]],
    data_columns: list[str],
) -> dict[str, str]:
    """Precompute db_column -> python_field mapping (once per model)."""
    from l1000_schema.schema_def import get_db_column_name

    reverse = {get_db_column_name(model_cls, DynamicFieldName(f)): f for f in model_cls.model_fields if f not in _SYSTEM_FIELDS}
    return {c: reverse[SqlColumnName(c)] for c in data_columns if c in reverse}


def _make_object(
    model_cls: type[VersionedObjectRow[Any]],
    row: dict[str, Any],
    prefix: str,
    col_map: dict[str, str],
) -> VersionedObjectRow[Any] | None:
    """Construct a model from prefixed diff-row columns (pure)."""
    if row.get(f"{prefix}_sys_deleted") in (1, True, "1"):
        return None
    kwargs = {py: row.get(f"{prefix}_{db}") for db, py in col_map.items()}
    if all(v is None for v in kwargs.values()):
        return None
    kwargs["sys_id"] = SysId(str(row["sys_id"]))
    return model_cls.model_construct(**kwargs)


def _json_payload_to_dict(value: object) -> dict[str, Any]:
    if value is None:
        return {}
    if isinstance(value, dict):
        return dict(value)
    if isinstance(value, str):
        loaded = loads(value)
        if isinstance(loaded, dict):
            return loaded
    msg = f"Expected JSON object payload, got {type(value).__name__}"
    raise TypeError(msg)


def _materialize_two_way_payload(
    model_cls: type[VersionedObjectRow],
    payload: dict[str, Any],
) -> VersionedObjectRow:
    """Materialize one diff payload with concrete polymorphic dispatch."""
    from impl.common.l1050_polymorphism.type_dispatcher import dispatch_polymorphic_type
    from impl.common.l2070_server_plan.steps.large_column_read import (
        hydrate_inline_large_column_row_dicts,
    )
    from impl.common.l5200_sql_query.row_converter import convert_row_to_model

    concrete_model, concrete_payload = dispatch_polymorphic_type(model_cls, payload)
    hydrated_payloads = hydrate_inline_large_column_row_dicts(
        concrete_model,
        [concrete_payload],
    )
    concrete_payload = hydrated_payloads[0]
    hydrated = convert_row_to_model(concrete_model, concrete_payload)
    assert isinstance(hydrated, VersionedObjectRow)
    return hydrated


@dataclass(frozen=True, slots=True)
class _TwoWayDiffSqlRowsMaterializer:
    table_models: dict[SqlTableName, type[VersionedObjectRow[Any]]]

    def materialize(self: _TwoWayDiffSqlRowsMaterializer, raw: Sequence[Mapping[str, object]], _hydrator: Any) -> Any:
        from impl.common.l7400_versioned_diff.versioned_diff import ObjectDiff, RevisionDiff, TableDiff

        metadata_rows: list[dict[str, Any]] = []
        table_diffs: dict[str, TableDiff] = {
            str(table_name): TableDiff(table_name=str(table_name), changes=[]) for table_name in self.table_models
        }
        for raw_row in raw:
            row = _row_to_dict(raw_row)
            if str(row.get("row_kind", "diff")) == "metadata":
                metadata_rows.append(row)
                continue
            table_name = SqlTableName(row["table_name"])
            model_cls = self.table_models[table_name]
            status = str(row["status"]).lower()
            old_payload = _json_payload_to_dict(row.get("old_payload"))
            new_payload = _json_payload_to_dict(row.get("new_payload"))
            old_data = None if status == "added" else _materialize_two_way_payload(model_cls, old_payload)
            new_data = None if status == "deleted" else _materialize_two_way_payload(model_cls, new_payload)
            table_diffs[str(table_name)].changes.append(
                ObjectDiff(
                    object_id=SysId(str(row["sys_id"])),
                    status=status,
                    old_data=old_data,
                    new_data=new_data,
                ),
            )
        if len(metadata_rows) != 1:
            msg = f"Expected exactly one two-way diff metadata row, got {len(metadata_rows)}"
            raise RuntimeError(msg)
        for table_diff in table_diffs.values():
            table_diff.changes.sort(key=lambda change: str(change.object_id))
        metadata = metadata_rows[0]
        return RevisionDiff(
            from_revision_id=RevisionId(str(metadata["from_revision_id"])),
            to_revision_id=RevisionId(str(metadata["to_revision_id"])),
            table_diffs=table_diffs,
        )


def _payload_to_model(
    model_cls: type[VersionedObjectRow[Any]],
    payload: object,
    deleted: object,
) -> VersionedObjectRow[Any] | None:
    if deleted in (1, True, "1"):
        return None
    payload_dict = _json_payload_to_dict(payload)
    if not payload_dict:
        return None
    if all(value is None for key, value in payload_dict.items() if key != "sys_id"):
        return None
    return _materialize_two_way_payload(model_cls, payload_dict)


_EFFECTIVE_DIFF_IGNORED_FIELDS = frozenset(
    {
        "sys_id",
        "created_at",
        "updated_at",
        "revision_id",
        "staged_commit_id",
        "deleted",
    },
)


def _same_effective_payload(
    model_cls: type[VersionedObjectRow[Any]],
    left: VersionedObjectRow[Any] | None,
    right: VersionedObjectRow[Any] | None,
) -> bool:
    """Return whether two branch payloads are equivalent for merge diff purposes."""
    if left is None or right is None:
        return left is right
    for field_name in model_cls.model_fields:
        if field_name in _EFFECTIVE_DIFF_IGNORED_FIELDS:
            continue
        if getattr(left, field_name, None) != getattr(right, field_name, None):
            return False
    return True


@dataclass(frozen=True, slots=True)
class _ThreeWayDiffSqlRowsMaterializer:
    table_models: dict[SqlTableName, type[VersionedObjectRow[Any]]]

    def materialize(self: _ThreeWayDiffSqlRowsMaterializer, raw: Sequence[Mapping[str, object]], _hydrator: Any) -> Any:
        from impl.common.l7400_versioned_diff.versioned_diff import (
            ChangeType,
            TableThreeWayDiff,
            ThreeWayDiffResult,
            ThreeWayObjectChange,
        )

        metadata_rows: list[dict[str, Any]] = []
        table_diffs: dict[str, TableThreeWayDiff] = {
            str(table_name): TableThreeWayDiff(table_name=str(table_name), changes=[]) for table_name in self.table_models
        }
        for raw_row in raw:
            row = _row_to_dict(raw_row)
            if str(row.get("row_kind", "diff")) == "metadata":
                metadata_rows.append(row)
                continue
            table_name = SqlTableName(row["table_name"])
            model_cls = self.table_models[table_name]
            base = _payload_to_model(model_cls, row.get("base_payload"), row.get("base_deleted"))
            left = _payload_to_model(model_cls, row.get("source_payload"), row.get("source_deleted"))
            right = _payload_to_model(model_cls, row.get("target_payload"), row.get("target_deleted"))
            if _same_effective_payload(model_cls, left, right):
                continue
            table_diffs[str(table_name)].changes.append(
                ThreeWayObjectChange(
                    object_id=SysId(str(row["sys_id"])),
                    base=base,
                    left=left,
                    right=right,
                    left_change=(
                        ChangeType.UNCHANGED
                        if _same_effective_payload(model_cls, base, left)
                        else ChangeType.DELETED
                        if left is None
                        else ChangeType.ADDED
                        if base is None
                        else ChangeType.UPDATED
                    ),
                    right_change=(
                        ChangeType.UNCHANGED
                        if _same_effective_payload(model_cls, base, right)
                        else ChangeType.DELETED
                        if right is None
                        else ChangeType.ADDED
                        if base is None
                        else ChangeType.UPDATED
                    ),
                ),
            )
        if len(metadata_rows) != 1:
            msg = f"Expected exactly one three-way diff metadata row, got {len(metadata_rows)}"
            raise RuntimeError(msg)
        metadata = metadata_rows[0]
        return ThreeWayDiffResult(
            base_revision_id=RevisionId(str(metadata["base_revision_id"])),
            left_revision_id=RevisionId(str(metadata["left_revision_id"])),
            right_revision_id=RevisionId(str(metadata["right_revision_id"])),
            table_diffs=table_diffs,
        )


@dataclass(frozen=True, slots=True)
class TwoWayDiffMaterializationConfig:
    table_models: dict[SqlTableName, type[VersionedObjectRow[Any]]]


@dataclass(frozen=True, slots=True)
