def materialize_two_way_diff_sql_rows(
    config: object,
    raw: Sequence[Mapping[str, object]],
) -> Any:
    typed_config = config
    assert isinstance(typed_config, TwoWayDiffMaterializationConfig)
    return _TwoWayDiffSqlRowsMaterializer(
        table_models=typed_config.table_models,
    ).materialize(raw, None)


def materialize_three_way_diff_sql_rows(
    config: object,
    raw: Sequence[Mapping[str, object]],
) -> Any:
    typed_config = config
    assert isinstance(typed_config, ThreeWayDiffMaterializationConfig)
    return _ThreeWayDiffSqlRowsMaterializer(
        table_models=typed_config.table_models,
    ).materialize(raw, None)


