@pure_lazy
def _compile_diff_scope_predicate(scope: _PhysicalDiffScope) -> SqlRenderable | None:
    """Compile one physical-table selection union into typed SQL grammar.

    See ``docs/design/NER_1384_SCOPED_REVISION_DIFF_DESIGN.rst``. Compilation
    keeps both snapshot filters in SQL and rejects invalid internal state.
    """
    from l1000_schema.schema_def import DatabaseObjectRow, get_db_column_name
    from l1050_polymorphism.type_filter_helper import (
        collect_polymorphic_type_names,
        polymorphic_type_name_aliases,
    )
    from l1050_polymorphism.type_registry import get_polymorphic_base_class
    from impl.common.l2100_sql_grammar.tree.enums import BinaryOp
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlParam
    from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp, SqlIn, SqlIsNull
    from impl.common.l5200_sql_query.expression_grammar import ExpressionToGrammar
    from impl.common.l2050_sql_types.sql_branded_types import SqlAliasName, SqlColumnName

    if scope.unfiltered:
        return None

    clauses: list[SqlRenderable] = []
    for selection in scope.selections:
        model = selection.model
        predicate = selection.predicate
        family_predicate: SqlRenderable | None = None
        if getattr(model, "__polymorphic__", False) and "type_name" in scope.data_columns:
            type_names = set(collect_polymorphic_type_names(model))
            is_root_model = get_polymorphic_base_class(model) is model
            if is_root_model:
                type_names.update(polymorphic_type_name_aliases(model))
            sorted_type_names = tuple(sorted(type_names))
            type_name_ref = SqlColumnRef(
                SqlColumnName("type_name"),
                qualifier=SqlAliasName("s"),
            )
            named_family: SqlRenderable | None = None
            if sorted_type_names:
                named_family = SqlIn(
                    type_name_ref,
                    [SqlParam(type_name) for type_name in sorted_type_names],
                )
            if is_root_model:
                base_family = SqlIsNull(type_name_ref)
                family_predicate = base_family if named_family is None else SqlBinaryOp(base_family, BinaryOp.OR, named_family)
            else:
                family_predicate = named_family
        user_predicate: SqlRenderable | None = None
        if predicate is not None:
            if not isinstance(predicate, Expression):
                msg = f"Revision diff predicate for {model.__name__} must be an Expression."
                raise RevisionDiffSelectionError(msg)

            def _owner_field_ref(owner: type[DatabaseObjectRow], field_name: str) -> SqlRenderable:
                return SqlColumnRef(
                    SqlColumnName(get_db_column_name(owner, DynamicFieldName(field_name))),
                    qualifier=SqlAliasName("s"),
                )

            converter = ExpressionToGrammar(
                model,
                table_alias="s",
                owner_field_ref_factory=_owner_field_ref,
            )
            try:
                user_predicate = converter.convert(predicate)
            except (TypeError, ValueError) as exc:
                msg = f"Invalid revision diff predicate for {model.__name__}: {exc}"
                raise RevisionDiffSelectionError(msg) from exc
        if family_predicate is None and user_predicate is None:
            return None
        if family_predicate is None:
            assert user_predicate is not None
            clauses.append(user_predicate)
        elif user_predicate is None:
            clauses.append(family_predicate)
        else:
            clauses.append(SqlBinaryOp(family_predicate, BinaryOp.AND, user_predicate))

    if not clauses:
        return None
    result = clauses[0]
    for clause in clauses[1:]:
        result = SqlBinaryOp(result, BinaryOp.OR, clause)
    return result


class _TwoWayVersionedDiffRowsStep(SqlRelationPublisherStep[list[object]]):
    """Per-table two-way diff rows with compile-time scalar source lowering."""

    def __init__(
        self: _TwoWayVersionedDiffRowsStep,
        ref_id: ServerPlanRefId,
        *,
        domain: Any,
        from_revision_source: object,
        to_revision_source: object,
        sparse_table: SqlTableName,
        data_columns: list[str],
        revision_table: SqlTableName,
        revision_parents_table: SqlTableName,
        config: _VersionedDiffRowsConfig,
        scope: _PhysicalDiffScope,
        session_source: object = None,
    ) -> None:
        super().__init__(ref_id)
        self._domain = domain
        self._from_revision_source = from_revision_source
        self._to_revision_source = to_revision_source
        self._sparse_table = sparse_table
        self._data_columns = data_columns
        self._revision_table = revision_table
        self._revision_parents_table = revision_parents_table
        self._model_cls = config.model_cls
        self._behavior = config.behavior
        self._scope = scope
        self._session_source = session_source

    @property
    def level(self: _TwoWayVersionedDiffRowsStep) -> int:
        return 0

    def result_cardinality(self: _TwoWayVersionedDiffRowsStep) -> Cardinality:
        return Cardinality.MANY

    def is_read_only(self: _TwoWayVersionedDiffRowsStep) -> bool:
        return True

    def execution_role(self: _TwoWayVersionedDiffRowsStep) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def supports_sql_batch_transport(self: _TwoWayVersionedDiffRowsStep) -> bool:
        return True

    def step_tags(self: _TwoWayVersionedDiffRowsStep) -> frozenset[str]:
        return frozenset({"read", "diff", "grammar", "rows"})

    def tables_read(self: _TwoWayVersionedDiffRowsStep) -> frozenset[str]:
        return frozenset()

    def tables_written(self: _TwoWayVersionedDiffRowsStep) -> frozenset[str]:
        return frozenset()

    def _publication_columns(self: _TwoWayVersionedDiffRowsStep) -> tuple[str, ...]:
        old_columns = tuple(f"old_{column}" for column in self._data_columns)
        new_columns = tuple(f"new_{column}" for column in self._data_columns)
        return (
            "sys_id",
            "change_type",
            "old_sys_deleted",
            "new_sys_deleted",
            *old_columns,
            *new_columns,
        )

    def _publication_column_type_hints(self: _TwoWayVersionedDiffRowsStep) -> SqlColumnTypeHints:
        from l2070_batching.sql_column_type_hints import combine_sql_column_type_hints

        columns = self._publication_columns()
        return combine_sql_column_type_hints(
            columns,
            SqlColumnTypeHints(
                uuid_columns=frozenset({"sys_id"}),
                text_columns=frozenset({"change_type"}),
                bool_columns=frozenset({"old_sys_deleted", "new_sys_deleted"}),
            ),
            _prefixed_model_column_hints(
                self._model_cls,
                self._data_columns,
                ("old", "new"),
                bytea_columns=frozenset(str(column) for column in self._scope.bytea_columns),
            ),
        )

    def cte_publication_contract(self: _TwoWayVersionedDiffRowsStep) -> CtePublicationContract:
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=self._publication_columns(),
            column_type_hints=self._publication_column_type_hints(),
            model_cls=_VersionedDiffSqlRow,
            relation_role=self.cte_relation_role(),
            source_tables=None,
        )

    def dependencies(self: _TwoWayVersionedDiffRowsStep) -> frozenset[str]:
        return (
            _source_dependencies(self._from_revision_source)
            | _source_dependencies(
                self._to_revision_source,
            )
            | _source_dependencies(self._session_source)
        )

    def compile(self: _TwoWayVersionedDiffRowsStep, ctx: CompilationContext) -> CompiledStep[list[object]]:
        from l1000_schema.table_utils import get_table_name
        from impl.common.l2070_server_plan.steps._conditional_compile import (
            _sanitize_ref_id_for_cte_name,
        )
        from impl.common.l2100_sql_grammar.domain.versioning.stmt_two_way_diff import SqlTwoWayDiffCte
        from impl.common.l2100_sql_grammar.domain.versioning.subquery_lookups import (
            SqlResolvedBranchIdForRevisionSubquery,
        )

        from_revision_sql = lower_scalar_source(
            self._from_revision_source,
            ctx,
            default_field="rev_id",
        )
        to_revision_sql = lower_scalar_source(
            self._to_revision_source,
            ctx,
            default_field="rev_id",
        )
        branch_table = get_table_name(self._domain.branch_model)
        branch_index_table = get_table_name(self._domain.revision_branch_index_model)
        from impl.common.l2070_server_plan.steps.diff_permission_scope import compile_diff_permission_scope
        from impl.common.l2100_sql_grammar.tree.expr_ops import sql_and

        old_branch = SqlResolvedBranchIdForRevisionSubquery(branch_table, branch_index_table, from_revision_sql)
        new_branch = SqlResolvedBranchIdForRevisionSubquery(branch_table, branch_index_table, to_revision_sql)
        selection_predicate = _compile_diff_scope_predicate(self._scope)
        old_permission = compile_diff_permission_scope(
            self._scope, ctx, domain=self._domain, revision=from_revision_sql, branch=old_branch
        )
        new_permission = compile_diff_permission_scope(self._scope, ctx, domain=self._domain, revision=to_revision_sql, branch=new_branch)
        old_scope = (
            sql_and(selection_predicate, old_permission)
            if selection_predicate is not None and old_permission is not None
            else selection_predicate
            if old_permission is None
            else old_permission
        )
        new_scope = (
            sql_and(selection_predicate, new_permission)
            if selection_predicate is not None and new_permission is not None
            else selection_predicate
            if new_permission is None
            else new_permission
        )
        stmt = SqlTwoWayDiffCte(
            old_revision_raw=from_revision_sql,
            new_revision_raw=to_revision_sql,
            sparse_table=self._sparse_table,
            branch_id_raw=SqlResolvedBranchIdForRevisionSubquery(
                branch_table,
                branch_index_table,
                to_revision_sql,
            ),
            data_columns=self._data_columns,
            revision_table=self._revision_table,
            revision_parents_table=self._revision_parents_table,
            old_branch_id_raw=SqlResolvedBranchIdForRevisionSubquery(
                branch_table,
