    def _publication_column_type_hints(self: _ThreeWayVersionedDiffRowsStep) -> SqlColumnTypeHints:
        from l2070_batching.sql_column_type_hints import combine_sql_column_type_hints

        columns = self._publication_columns()
        return combine_sql_column_type_hints(
            columns,
            SqlColumnTypeHints(
                uuid_columns=frozenset({"sys_id"}),
