            _source_dependencies(self._base_revision_source)
            | _source_dependencies(self._left_revision_source)
            | _source_dependencies(self._right_revision_source)
            | _source_dependencies(self._session_source)
        )

    def compile(self: _ThreeWayVersionedDiffRowsStep, ctx: CompilationContext) -> CompiledStep[list[object]]:
        from l1000_schema.table_utils import get_table_name
        from impl.common.l2100_sql_grammar.domain.versioning.stmt_three_way_diff import SqlThreeWayDiffCte
        from impl.common.l2100_sql_grammar.domain.versioning.subquery_lookups import (
            SqlResolvedBranchIdForRevisionSubquery,
