            default_field="rev_id",
        )
        right_revision_sql = lower_scalar_source(
            self._right_revision_source,
            ctx,
            default_field="rev_id",
        )
        branch_table = get_table_name(self._domain.branch_model)
        branch_index_table = get_table_name(self._domain.revision_branch_index_model)
        from impl.common.l2070_server_plan.steps.diff_permission_scope import compile_diff_permission_scope

        base_branch = SqlResolvedBranchIdForRevisionSubquery(branch_table, branch_index_table, base_revision_sql)
        left_branch = SqlResolvedBranchIdForRevisionSubquery(branch_table, branch_index_table, left_revision_sql)
        right_branch = SqlResolvedBranchIdForRevisionSubquery(branch_table, branch_index_table, right_revision_sql)
        stmt = SqlThreeWayDiffCte(
            lca_revision_raw=base_revision_sql,
            source_tip_raw=left_revision_sql,
            target_tip_raw=right_revision_sql,
            sparse_table=self._sparse_table,
            source_branch_id_raw=SqlResolvedBranchIdForRevisionSubquery(
                branch_table,
                branch_index_table,
                left_revision_sql,
            ),
            target_branch_id_raw=SqlResolvedBranchIdForRevisionSubquery(
                branch_table,
                branch_index_table,
                right_revision_sql,
            ),
            cte_namespace=str(self.ref_id),
            base_branch_id_raw=base_branch,
            base_scope_predicate=compile_diff_permission_scope(
                self._scope, ctx, domain=self._domain, revision=base_revision_sql, branch=base_branch
            ),
            source_scope_predicate=compile_diff_permission_scope(
                self._scope, ctx, domain=self._domain, revision=left_revision_sql, branch=left_branch
            ),
            target_scope_predicate=compile_diff_permission_scope(
                self._scope, ctx, domain=self._domain, revision=right_revision_sql, branch=right_branch
            ),
            data_columns=self._data_columns,
            revision_table=self._revision_table,
            revision_parents_table=self._revision_parents_table,
            model_cls=self._model_cls,
        )
        contract = self.cte_publication_contract()
        output_shape = _contract_output_shape(self)
        select = stmt.local_relation()
        return CompiledStep(
            output_shape=output_shape,
            result_relation=DeclaredResultRelation.from_output_shape(output_shape),
            grammar=select,
            needs_returning=True,
