@pure_lazy
def _physical_diff_scopes(config: _DiffRevisionsConfig | _ThreeWayDiffConfig) -> tuple[_PhysicalDiffScope, ...]:
    """Group logical model selections by physical table."""
    from l1000_schema.table_utils import get_table_name
    from l2070_batching.sql_column_type_hints import model_sql_column_type_hints
    from impl.common.l7400_versioned_diff.versioned_diff import _get_data_columns

    configured_selections = config.selections if isinstance(config, _DiffRevisionsConfig) else None
    domain_models = tuple(config.domain.all_versioned_models())
    grouped_models: dict[SqlTableName, list[type[VersionedObjectRow]]] = {}
    for model in domain_models:
        grouped_models.setdefault(get_table_name(model), []).append(model)

    selected_by_table: dict[
        SqlTableName,
        list[RevisionDiffSelection[VersionedObjectRow]],
    ] = {}
    if configured_selections is None:
        for table_name in grouped_models:
            selected_by_table[table_name] = []
    else:
        for selection in configured_selections:
            selected_by_table.setdefault(get_table_name(selection.model), []).append(selection)

    scopes: list[_PhysicalDiffScope] = []
    for table_name, selections in selected_by_table.items():
        schema_models = tuple(grouped_models[table_name])
        hydration_model = min(schema_models, key=lambda model: len(model.__mro__))
        from impl.common.l2100_sql_grammar.domain.infra.stmt_inline_large_columns import (
            inline_large_column_transport_columns,
        )

        data_columns = tuple(
            dict.fromkeys(
                column
                for model in schema_models
                for column in (
                    *(SqlColumnName(name) for name in _get_data_columns(model)),
                    *(SqlColumnName(name) for name in inline_large_column_transport_columns(model)),
                )
            ),
        )
        json_columns = frozenset(
            SqlColumnName(column)
            for model in schema_models
            for column in (model_sql_column_type_hints(model, data_columns) or SqlColumnTypeHints()).jsonb_columns
        )
        from l1000_schema.large_column import get_large_column_configs
        from impl.common.l2100_sql_grammar.domain.infra.stmt_inline_large_columns import (
            inline_large_column_alias,
        )

        bytea_columns = frozenset(
            {
                *(
                    SqlColumnName(column)
                    for model in schema_models
                    for column in (model_sql_column_type_hints(model, data_columns) or SqlColumnTypeHints()).bytea_columns
                ),
                *(
                    SqlColumnName(inline_large_column_alias(SqlGrammarKind(config.column), "payload"))
                    for model in schema_models
                    for config in get_large_column_configs(model)
                ),
            }
        )
        scopes.append(
            _PhysicalDiffScope(
                table_name=table_name,
                hydration_model=hydration_model,
                schema_models=schema_models,
                data_columns=data_columns,
                json_columns=json_columns,
                bytea_columns=bytea_columns,
                selections=tuple(selections),
                unfiltered=configured_selections is None,
            ),
        )
    return tuple(scopes)


@pure_lazy
def _scope_column_map(scope: _PhysicalDiffScope) -> dict[str, str]:
    """Map each physical data column to its Python model field."""
    from l1000_schema.large_column import get_large_column_configs, large_column_pointer_name
    from l1000_schema.schema_def import get_db_column_name
    from impl.common.l2100_sql_grammar.domain.infra.stmt_inline_large_columns import (
        inline_large_column_transport_column_groups,
    )

    result: dict[str, str] = {}
    for model in scope.schema_models:
        for field_name in model.model_fields:
            if field_name in _SYSTEM_FIELDS:
                continue
            result.setdefault(get_db_column_name(model, DynamicFieldName(field_name)), field_name)
        for large_config in get_large_column_configs(model):
            pointer_name = large_column_pointer_name(large_config.column)
            result.setdefault(
                get_db_column_name(model, DynamicFieldName(pointer_name)),
                pointer_name,
            )
        for _logical_column, _pointer_column, transport_columns in inline_large_column_transport_column_groups(model):
            for transport_column in transport_columns[1:]:
                result.setdefault(transport_column, transport_column)
    return {column: result[column] for column in scope.data_columns if column in result}


class DiffRevisionsIntent(IntentStep[Any]):
    """L4 intent: two-way diff between two revisions.

    ``lower()`` emits one ``GrammarRowsStep`` per versioned table
    plus a ``_DiffCollectorStep`` that assembles the ``RevisionDiff``.

    Revision params accept ``RevisionId`` or ``SqlRenderable`` (subquery).
    """

    intent_tags = frozenset({"read", "diff", "grammar"})
    intent_read_only = True

    def __init__(
        self: DiffRevisionsIntent,
        ref_id: ServerPlanRefId,
        config: _DiffRevisionsConfig,
    ) -> None:
        super().__init__(ref_id)
        self._config = config

    def lower(
        self: DiffRevisionsIntent,
        ctx: Any,
    ) -> Sequence[ServerPlanStep[Any]]:
        from l1000_schema.table_utils import get_table_name

        config = self._config
        domain = config.domain

        revision_table = SqlTableName(get_table_name(domain.revision_model))
        revision_parents_table = SqlTableName(get_table_name(domain.revision_parent_model))

        metadata_ref = ServerPlanRefId(f"{self.ref_id}_metadata")
        steps: list[ServerPlanStep[Any]] = [
            _TwoWayDiffMetadataStep(
                metadata_ref,
                _TwoWayDiffMetadataConfig(
                    from_revision_source=config.from_revision_source,
                    to_revision_source=config.to_revision_source,
                ),
            ),
        ]
        table_refs: dict[SqlTableName, ServerPlanRefId] = {}
        table_models: dict[SqlTableName, type[VersionedObjectRow[Any]]] = {}
        column_maps: dict[SqlTableName, dict[str, str]] = {}
        bytea_columns: dict[SqlTableName, frozenset[str]] = {}

        for scope in _physical_diff_scopes(config):
            table_name = scope.table_name
            sparse_table = derive_versioned_table_names(VersionedBaseTableName(str(table_name))).sparse
            data_columns = [str(column) for column in scope.data_columns]
            col_map = _scope_column_map(scope)

            child_ref = f"{self.ref_id}_diff_{table_name}"

            steps.append(
                _TwoWayVersionedDiffRowsStep(
                    ServerPlanRefId(child_ref),
                    domain=domain,
                    from_revision_source=config.from_revision_source,
                    to_revision_source=config.to_revision_source,
                    sparse_table=SqlTableName(sparse_table),
                    data_columns=data_columns,
                    revision_table=SqlTableName(revision_table),
                    revision_parents_table=SqlTableName(revision_parents_table),
                    config=_VersionedDiffRowsConfig(
                        model_cls=scope.hydration_model,
                        column_map=col_map,
                        behavior=PostOpBehavior.TERMINAL_ARRAY,
                    ),
                    scope=scope,
                    session_source=ctx.session_id,
                ),
            )
            table_refs[table_name] = ServerPlanRefId(child_ref)
            table_models[table_name] = scope.hydration_model
            column_maps[table_name] = col_map
            bytea_columns[table_name] = frozenset(str(column) for column in scope.bytea_columns)

        steps.append(
            _DiffCollectorStep(
                ref_id=self.ref_id,
                metadata_ref_id=metadata_ref,
                config=_TableRefCollectorConfig(
                    table_refs=table_refs,
                    table_models=table_models,
                    column_maps=column_maps,
                    bytea_columns=bytea_columns,
                ),
            ),
        )
        return steps


def _build_revision_diff_from_values(
    table_refs: dict[SqlTableName, ServerPlanRefId],
    from_revision_id: RevisionId,
    to_revision_id: RevisionId,
    resolved_values: Mapping[str, object],
) -> Any:
    from impl.common.l7400_versioned_diff.versioned_diff import RevisionDiff, TableDiff

    table_diffs: dict[str, TableDiff] = {
        str(table_name): TableDiff(
            table_name=str(table_name),
            changes=sorted(
                _coerce_object_diff_rows(resolved_values.get(str(child_ref))),
                key=lambda change: str(change.object_id),
            ),
        )
        for table_name, child_ref in table_refs.items()
    }
    return RevisionDiff(
        from_revision_id=from_revision_id,
        to_revision_id=to_revision_id,
        table_diffs=table_diffs,
    )


def _build_three_way_diff_from_values(
    table_refs: dict[SqlTableName, ServerPlanRefId],
    base_revision_id: RevisionId,
    left_revision_id: RevisionId,
    right_revision_id: RevisionId,
    resolved_values: Mapping[str, object],
) -> Any:
    from impl.common.l7400_versioned_diff.versioned_diff import (
        TableThreeWayDiff,
        ThreeWayDiffResult,
    )

    table_diffs: dict[str, TableThreeWayDiff] = {
        str(table_name): TableThreeWayDiff(
            table_name=str(table_name),
            changes=_coerce_three_way_rows(resolved_values.get(str(child_ref))),
        )
        for table_name, child_ref in table_refs.items()
    }
    return ThreeWayDiffResult(
        base_revision_id=base_revision_id,
        left_revision_id=left_revision_id,
        right_revision_id=right_revision_id,
        table_diffs=table_diffs,
    )


