class ThreeWayDiffIntent(IntentStep[Any]):
    """L4 intent: three-way diff (base, left, right)."""

    intent_tags = frozenset({"read", "diff", "grammar"})
    intent_read_only = True

    def __init__(
        self: ThreeWayDiffIntent,
        ref_id: ServerPlanRefId,
        config: _ThreeWayDiffConfig,
    ) -> None:
        super().__init__(ref_id)
        self._config = config

    def lower(
        self: ThreeWayDiffIntent,
        ctx: Any,
    ) -> Sequence[ServerPlanStep[Any]]:
        from l1000_schema.table_utils import get_table_name

        config = self._config
        domain = config.domain
        revision_table = SqlTableName(get_table_name(domain.revision_model))
        revision_parents_table = SqlTableName(get_table_name(domain.revision_parent_model))
        metadata_ref = ServerPlanRefId(f"{self.ref_id}_metadata")

        steps: list[ServerPlanStep[Any]] = [
            _ThreeWayDiffMetadataStep(
                metadata_ref,
                _ThreeWayDiffMetadataConfig(
                    base_revision_source=config.base_revision_source,
                    left_revision_source=config.left_revision_source,
                    right_revision_source=config.right_revision_source,
                ),
            ),
        ]
        table_refs: dict[SqlTableName, ServerPlanRefId] = {}
        table_models: dict[SqlTableName, type[VersionedObjectRow[Any]]] = {}
        column_maps: dict[SqlTableName, dict[str, str]] = {}
        bytea_columns: dict[SqlTableName, frozenset[str]] = {}

        for scope in _physical_diff_scopes(config):
            model_cls = scope.hydration_model
            table_name = scope.table_name
            sparse_table = derive_versioned_table_names(VersionedBaseTableName(str(table_name))).sparse
            data_columns: list[str] = list(scope.data_columns)
            col_map = _scope_column_map(scope)

            child_ref = f"{self.ref_id}_3way_{table_name}"

            steps.append(
                _ThreeWayVersionedDiffRowsStep(
                    ServerPlanRefId(child_ref),
                    domain=domain,
                    base_revision_source=config.base_revision_source,
                    left_revision_source=config.left_revision_source,
                    right_revision_source=config.right_revision_source,
                    sparse_table=SqlTableName(sparse_table),
                    data_columns=data_columns,
                    revision_table=SqlTableName(revision_table),
                    revision_parents_table=SqlTableName(revision_parents_table),
                    config=_VersionedDiffRowsConfig(
                        model_cls=model_cls,
                        column_map=col_map,
                        behavior=PostOpBehavior.TERMINAL_ARRAY,
                    ),
                    scope=scope,
                    session_source=ctx.session_id,
                ),
            )
            sql_table_name = SqlTableName(table_name)
            table_refs[sql_table_name] = ServerPlanRefId(child_ref)
            table_models[sql_table_name] = model_cls
            column_maps[sql_table_name] = col_map
            bytea_columns[sql_table_name] = frozenset(str(column) for column in scope.bytea_columns)

        steps.append(
            _ThreeWayDiffCollectorStep(
                ref_id=self.ref_id,
                metadata_ref_id=metadata_ref,
                config=_TableRefCollectorConfig(
                    table_refs=table_refs,
                    table_models=table_models,
                    column_maps=column_maps,
                    bytea_columns=bytea_columns,
                ),
            ),
        )
        return steps


