class _ThreeWayDiffCollectorStep(ConsumedRowsReducerMixin, SqlRelationPublisherStep[Any]):
    """L0: collect per-table ThreeWayObjectChange lists into ThreeWayDiffResult."""

    def __init__(
        self: _ThreeWayDiffCollectorStep,
        ref_id: ServerPlanRefId,
        metadata_ref_id: ServerPlanRefId,
        config: _TableRefCollectorConfig,
    ) -> None:
        super().__init__(ref_id)
        self._metadata_ref_id = metadata_ref_id
        self._table_refs = config.table_refs
        self._table_models = config.table_models or {}
        self._column_maps = config.column_maps or {}
        self._bytea_columns = config.bytea_columns or {}

    @property
    def level(self: _ThreeWayDiffCollectorStep) -> int:
        return 0

    def result_cardinality(self: _ThreeWayDiffCollectorStep) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self: _ThreeWayDiffCollectorStep) -> bool:
        return True

    def execution_role(self: _ThreeWayDiffCollectorStep) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def step_tags(self: _ThreeWayDiffCollectorStep) -> frozenset[str]:
        return frozenset({"read", "diff", "collector", "sql_visible"})

    def cte_publication_contract(self: _ThreeWayDiffCollectorStep) -> CtePublicationContract:
        columns = (
            "row_kind",
            "table_name",
            "sys_id",
            "left_change",
            "right_change",
            "base_deleted",
            "source_deleted",
            "target_deleted",
            "base_payload",
            "source_payload",
            "target_payload",
            "base_revision_id",
            "left_revision_id",
            "right_revision_id",
        )
        column_type_hints = SqlColumnTypeHints(
            uuid_columns=frozenset({"sys_id", "base_revision_id", "left_revision_id", "right_revision_id"}),
            text_columns=frozenset(
                {
                    "row_kind",
                    "table_name",
                    "left_change",
                    "right_change",
                    "base_payload",
                    "source_payload",
                    "target_payload",
                },
            ),
            bool_columns=frozenset({"base_deleted", "source_deleted", "target_deleted"}),
        )
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=columns,
            column_type_hints=column_type_hints,
            model_cls=_ThreeWayDiffCollectorStepCteRow,
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def tables_read(self: _ThreeWayDiffCollectorStep) -> frozenset[str]:
        return frozenset()

    def tables_written(self: _ThreeWayDiffCollectorStep) -> frozenset[str]:
        return frozenset()

    def dependencies(self: _ThreeWayDiffCollectorStep) -> frozenset[str]:
        return frozenset({str(self._metadata_ref_id), *(str(ref_id) for ref_id in self._table_refs.values())})

    def requires_materialized_inputs(self: _ThreeWayDiffCollectorStep) -> bool:
        return True

    def requires_prior_step_boundary(self: _ThreeWayDiffCollectorStep) -> bool:
        return True

    def supports_ordered_sql_statement_batch(self: _ThreeWayDiffCollectorStep) -> bool:
        return False

    def compile(self: _ThreeWayDiffCollectorStep, ctx: Any) -> CompiledStep[Any]:
        _require_diff_collector_metadata(
            self._table_refs,
            self._table_models,
            self._column_maps,
            step_name=type(self).__name__,
        )
        cte_refs: list[CteReference] = []
        sources: list[SqlThreeWayDiffCollectorSource] = []
        metadata_cte_ref = _require_diff_source_cte(
            ctx,
            self._metadata_ref_id,
            purpose="three-way diff metadata collection",
        )
        for table_name, ref_id in self._table_refs.items():
            cte_ref = _require_diff_source_cte(
                ctx,
                ref_id,
                purpose="three-way diff collection",
            )
            cte_refs.append(cte_ref)
            column_map = self._column_maps[table_name]
            sources.append(
                SqlThreeWayDiffCollectorSource(
                    table_name=str(table_name),
                    cte_name=cte_ref.ref_id,
                    field_columns=tuple((field_name, db_column) for db_column, field_name in column_map.items()),
                    bytea_columns=frozenset(SqlColumnName(column) for column in self._bytea_columns.get(table_name, frozenset())),
                ),
            )
        __opa002_grammar_1175 = SqlThreeWayDiffCollectorRows(
            tuple(sources),
            metadata_cte_name=metadata_cte_ref.ref_id,
        )
        output_shape = _contract_output_shape(self)
        return CompiledStep(
            output_shape=output_shape,
            result_relation=DeclaredResultRelation.from_output_shape(output_shape),
            grammar=__opa002_grammar_1175,
            needs_returning=True,
            column_type_hints=self.cte_publication_contract().column_type_hints,
            auxiliary_ctes=collect_dependency_auxiliary_ctes(
                ctx,
                tuple(self.dependencies()),
            ),
            closed_post_op=_three_way_diff_post_op(
                table_models=self._table_models,
            ),
        )


