# ═════════════════════════════════════════════════════════════════════


class ApplyDiffStagedIntent(IntentStep[Any]):
    """L4 intent: compute diff and apply to staged tables.

    ``lower()`` emits:
    - One ``GrammarEffectStep`` for staged-commit INSERT OR IGNORE
    - Per table: clean, apply, count steps
    - A collector step that aggregates counts into ``DiffApplicationResult``
    """

    intent_tags = frozenset({"write", "revert", "grammar"})

    def __init__(
        self: ApplyDiffStagedIntent,
        ref_id: ServerPlanRefId,
        config: _ApplyDiffStagedConfig,
    ) -> None:
        super().__init__(ref_id)
        self._config = config

    def lower(
        self: ApplyDiffStagedIntent,
        ctx: Any,
    ) -> Sequence[ServerPlanStep[Any]]:
        from l1000_schema.table_utils import get_table_name
        from impl.common.l7400_versioned_diff.versioned_diff import _get_data_columns

        config = self._config
        domain = config.domain
        revision_table = get_table_name(domain.revision_model)
        revision_parents_table = get_table_name(domain.revision_parent_model)
        branch_source = _branch_source_from_raw(config.branch_id_raw)
        diff_uses_write_branch = config.diff_branch_id is config.branch_id_raw
        diff_branch_id = config.diff_branch_id
        old_diff_uses_write_branch = config.old_diff_branch_id is config.branch_id_raw
        old_diff_branch_id = config.old_diff_branch_id
        staged_commit_id_raw = config.staged_commit_id_raw

        steps: list[ServerPlanStep[Any]] = []
        # Step 0: ensure staged commit row
        steps.append(
            EnsureStagedCommitStep(
                ref_id=ServerPlanRefId(f"{self.ref_id}_ensure_sc"),
                domain=domain,
                lazy_branch=cast("BranchId | ScalarServerRef[BranchId]", branch_source),
                config=_EnsureStagedCommitConfig(
                    staged_commit_id_raw=StagedCommitId(staged_commit_id_raw),
                    connection_id_value=ConnectionId(config.connection_id_str),
                    session_id_raw=SessionId(config.session_id_raw),
                ),
            ),
        )

        count_refs: list[str] = []
        previous_ref = ServerPlanRefId(f"{self.ref_id}_ensure_sc")
        table_specs: list[tuple[SqlTableName, _RevertDiffCteSpec]] = []

        from impl.common.l2070_server_plan.steps.intent_merge import _all_merge_table_models, _merge_data_columns
        from impl.common.l7400_versioned_diff.versioned_diff import _SYSTEM_FIELDS

        for model_cls in _all_merge_table_models(domain):
            table_name = get_table_name(model_cls)
            sparse_table = derive_versioned_table_names(VersionedBaseTableName(str(table_name))).sparse
            data_columns = _merge_data_columns(model_cls, frozenset(_SYSTEM_FIELDS))
            from l1000_schema.large_column import get_large_column_configs, large_column_pointer_name
            from l1000_schema.schema_def import get_db_column_name

            for large_column_config in get_large_column_configs(model_cls):
                pointer_column = get_db_column_name(
                    model_cls,
                    DynamicFieldName(large_column_pointer_name(large_column_config.column)),
                )
                if pointer_column not in data_columns:
                    data_columns.append(pointer_column)
            diff_cte_spec = _RevertDiffCteSpec(
                sparse_table=sparse_table,
                data_columns=tuple(data_columns),
                from_revision=config.from_revision,
                to_revision=config.to_revision,
                diff_branch_id=diff_branch_id,
                old_diff_branch_id=old_diff_branch_id,
                diff_uses_write_branch=diff_uses_write_branch,
                old_diff_uses_write_branch=old_diff_uses_write_branch,
                revision_table=revision_table,
                revision_parents_table=revision_parents_table,
            )

            table_specs.append((table_name, diff_cte_spec))
            from impl.common.l2070_server_plan.steps.replay_permission import (
                ReplayPermissionStep,
                ReplayPolicyFamilyExistsStep,
                replay_actions_are_unconditional,
                replay_permission_check_groups,
            )

            if not replay_actions_are_unconditional(model_cls):
                for checks, policy_model, graph_type in replay_permission_check_groups(
                    model_cls,
                    domain,
                    split_actions=True,
                ):
                    policy_name = policy_model.__name__ if policy_model is not None else "family"
                    graph_name = graph_type.__name__ if graph_type is not None else "direct"
                    action_name = "_".join(sorted(checks))
                    check_name = f"{policy_name}_{graph_name}"
                    permission_ref = ServerPlanRefId(f"permission_{action_name}_{self.ref_id}_{table_name}_{check_name}")
                    permission_step = ReplayPermissionStep(
                        permission_ref,
                        model=model_cls,
                        domain=domain,
                        diff_spec=diff_cte_spec,
                        branch=branch_source,
                        session=ctx.session_id,
                        after=None if policy_model is not None else previous_ref,
                        checks=checks,
                        policy_model=policy_model,
                        graph_type=graph_type,
                    )
                    from impl.common.l2070_server_plan.steps.conditional_builders import build_one_sided_conditional

                    condition_ref = ServerPlanRefId(f"{permission_ref}_has_changes")
                    steps.append(
                        ReplayPolicyFamilyExistsStep(
                            condition_ref,
                            model=model_cls,
                            policy_model=policy_model,
                            graph_type=graph_type,
                            diff_spec=diff_cte_spec,
                            branch=branch_source,
                            after=previous_ref,
                        )
                    )
                    conditional_ref = ServerPlanRefId(f"{permission_ref}_conditional")
                    steps.append(
                        build_one_sided_conditional(
                            ref_id=conditional_ref,
                            condition_ref=condition_ref,
                            if_true_steps=(permission_step,),
                            result_ref=permission_ref,
                            force_prior_step_boundary=True,
                        )
                    )
                    previous_ref = conditional_ref

        for table_name, diff_cte_spec in table_specs:
            staged_table = derive_versioned_table_names(VersionedBaseTableName(str(table_name))).staged
            clean_ref = f"{self.ref_id}_clean_{table_name}"
            if config.replace_staged_commit:
                clear_ref = f"{self.ref_id}_clear_{table_name}"
                steps.append(
                    _BranchAwareGrammarEffectStep(
                        ref_id=ServerPlanRefId(clear_ref),
                        stmt_spec=_BranchAwareRevertStatementSpec(
                            kind="clear",
                            staged_table=staged_table,
                            staged_commit_id_raw=staged_commit_id_raw,
                        ),
                        branch_source=branch_source,
                        config=_GrammarExecuteConfig(
                            reads=frozenset(),
                            writes=frozenset({SqlTableName(staged_table)}),
                            after_refs=frozenset({previous_ref}),
                        ),
                    ),
                )
                previous_ref = ServerPlanRefId(clear_ref)
            steps.append(
                _BranchAwareGrammarEffectStep(
                    ref_id=ServerPlanRefId(clean_ref),
                    stmt_spec=_BranchAwareRevertStatementSpec(
                        kind="clean",
                        staged_table=staged_table,
                        staged_commit_id_raw=staged_commit_id_raw,
                        diff_cte=diff_cte_spec,
                    ),
                    branch_source=branch_source,
                    config=_GrammarExecuteConfig(
                        reads=frozenset(),
                        writes=frozenset({SqlTableName(staged_table)}),
                        after_refs=frozenset({previous_ref}),
                    ),
                ),
            )
            previous_ref = ServerPlanRefId(clean_ref)

            apply_ref = f"{self.ref_id}_apply_{table_name}"
            steps.append(
                _BranchAwareGrammarEffectStep(
                    ref_id=ServerPlanRefId(apply_ref),
                    stmt_spec=_BranchAwareRevertStatementSpec(
                        kind="apply",
                        staged_table=staged_table,
                        staged_commit_id_raw=staged_commit_id_raw,
                        diff_cte=diff_cte_spec,
                    ),
                    branch_source=branch_source,
                    config=_GrammarExecuteConfig(
                        reads=frozenset(),
                        writes=frozenset({SqlTableName(staged_table)}),
                        after_refs=frozenset({previous_ref}),
                    ),
                ),
            )
            previous_ref = ServerPlanRefId(apply_ref)

            count_ref = f"{self.ref_id}_count_{table_name}"
            steps.append(
                _BranchAwareGrammarRowStep(
                    ref_id=ServerPlanRefId(count_ref),
                    stmt_spec=_BranchAwareRevertStatementSpec(
                        kind="count",
                        staged_table=staged_table,
                        staged_commit_id_raw=staged_commit_id_raw,
                        diff_cte=diff_cte_spec,
                    ),
                    branch_source=branch_source,
                    after_refs=frozenset({previous_ref}),
                ),
            )
            count_refs.append(count_ref)
            previous_ref = ServerPlanRefId(count_ref)

        steps.append(
            _ApplyDiffCountCollectorStep(
                ref_id=self.ref_id,
                config=_ApplyDiffCountCollectorConfig(
                    count_refs=tuple(ServerPlanRefId(ref_id) for ref_id in count_refs),
                ),
            ),
        )
        return steps


