# DiffBranchesIntent
# ═════════════════════════════════════════════════════════════════════


class DiffBranchesIntent(IntentStep[Any]):
    """L4 intent: diff two branches by name.

    ``lower()`` resolves branch names to tip revision IDs via SQL subqueries,
    then delegates to ``DiffRevisionsIntent``.
    """

    intent_tags = frozenset({"read", "diff", "grammar"})
    intent_read_only = True

    def __init__(
        self: DiffBranchesIntent,
        ref_id: ServerPlanRefId,
        config: _DiffBranchesConfig,
    ) -> None:
        super().__init__(ref_id)
        self._config = config

    def lower(
        self: DiffBranchesIntent,
        ctx: Any,
    ) -> Sequence[ServerPlanStep[Any]]:
        from l1000_schema.table_utils import get_table_name
        from l1100_exceptions.exceptions import BranchNotFoundError
        from impl.common.l2070_server_plan.steps.validate_exists import ValidateExistsStep
        from impl.common.l2100_sql_grammar.domain.versioning.stmt_validate import SqlCountWhereInWorkspace
        from impl.common.l2100_sql_grammar.domain.versioning.subquery_lookups import SqlBranchTipByNameSubquery

        config = self._config
        domain = config.domain
        branch_table = get_table_name(domain.branch_model)

        tip_a = SqlBranchTipByNameSubquery(
            SqlTableName(branch_table),
            SqlGrammarKind(config.branch_a_name),
            workspace_id=config.workspace_id,
        )
        tip_b = SqlBranchTipByNameSubquery(
            SqlTableName(branch_table),
            SqlGrammarKind(config.branch_b_name),
            workspace_id=config.workspace_id,
        )

        validate_steps: tuple[ServerPlanStep[Any], ...] = (
            ValidateExistsStep(
                ref_id=ServerPlanRefId(f"{self.ref_id}_validate_a"),
                stmt=SqlCountWhereInWorkspace(
                    branch_table,
                    SqlColumnName("name"),
                    BranchName(config.branch_a_name),
                    config.workspace_id,
                ),
                error_message=ValidationErrorMessage(
                    f"Branch '{config.branch_a_name}' not found",
                ),
                exception_cls=BranchNotFoundError,
            ),
            ValidateExistsStep(
                ref_id=ServerPlanRefId(f"{self.ref_id}_validate_b"),
                stmt=SqlCountWhereInWorkspace(
                    branch_table,
                    SqlColumnName("name"),
                    BranchName(config.branch_b_name),
                    config.workspace_id,
                ),
                error_message=ValidationErrorMessage(
                    f"Branch '{config.branch_b_name}' not found",
                ),
                exception_cls=BranchNotFoundError,
            ),
        )

        # Construct a DiffRevisionsIntent and immediately lower it to L0 steps
        # (since DiffBranchesIntent is L4 and can't return L4 children).
        diff_intent = DiffRevisionsIntent(
            ref_id=ServerPlanRefId(self.ref_id),
            config=_build_diff_revisions_config(
                domain=domain,
                from_revision_source=tip_a,
                to_revision_source=tip_b,
                selections=config.selections,
            ),
        )
        diff_l0_steps = diff_intent.lower(ctx)

        # Diff grammar steps must not be batched with the validation steps:
        # the diff CTE references tables (e.g. sys_revision_branch_index) that
        # may not exist when branches are missing.  Marking them non-batchable
        # forces the optimizer to flush the validation batch first, raising
        # BranchNotFoundError before the diff grammar executes.
        diff_l0_steps = [step.after_prerequisite_validation_boundary() for step in diff_l0_steps]

        return [*validate_steps, *diff_l0_steps]


