class RevertToRevisionIntent(IntentStep[Any]):
    """L4 intent: revert to a target revision.

    ``lower()`` validates the revision exists, then delegates to
    ``ApplyDiffStagedIntent`` with tip subquery -> target revision.
    """

    intent_tags = frozenset({"write", "revert", "grammar"})

    def __init__(
        self: RevertToRevisionIntent,
        ref_id: ServerPlanRefId,
        config: _RevertToRevisionConfig,
    ) -> None:
        super().__init__(ref_id)
        self._config = config

    def lower(
        self: RevertToRevisionIntent,
        ctx: Any,
    ) -> Sequence[ServerPlanStep[Any]]:
        from l1000_schema.table_utils import get_table_name
        from impl.common.l2070_server_plan.steps.validate_exists import ValidateExistsStep
        from impl.common.l2100_sql_grammar.domain.versioning.stmt_validate import SqlCountWhere
        from impl.common.l7400_versioned_diff.versioned_diff import _branch_id_subquery

        config = self._config
        domain = config.domain
        revision_table = get_table_name(domain.revision_model)
        branch_table = get_table_name(domain.branch_model)

        validate_step = ValidateExistsStep(
            ref_id=ServerPlanRefId(f"{self.ref_id}_validate_rev"),
            stmt=SqlCountWhere(revision_table, SqlColumnName("sys_id"), config.target_revision_id),
            error_message=ValidationErrorMessage(
                f"Revision '{config.target_revision_id}' not found",
            ),
        )

        tip_subq = _CurrentBranchTipRevision(SqlTableName(branch_table))
        diff_branch_id = _branch_id_subquery(domain, config.target_revision_id)

        apply_intent = ApplyDiffStagedIntent(
            ref_id=ServerPlanRefId(self.ref_id),
            config=_ApplyDiffStagedConfig(
                domain=domain,
                from_revision=tip_subq,
                to_revision=str(config.target_revision_id),
                branch_id_raw=config.branch_id_raw,
                staged_commit_id_raw=config.staged_commit_id_raw,
                connection_id_str=config.connection_id_str,
                session_id_raw=config.session_id_raw,
                diff_branch_id=diff_branch_id,
                replace_staged_commit=True,
                old_diff_branch_id=config.branch_id_raw,
            ),
        )
        apply_l0_steps = apply_intent.lower(ctx)

        return [validate_step, *apply_l0_steps]


