        self._config = config

    def lower(
        self: RevertRevisionIntent,
        ctx: Any,
    ) -> Sequence[ServerPlanStep[Any]]:
        from l1000_schema.table_utils import get_table_name
        from impl.common.l2070_server_plan.steps.validate_exists import ValidateExistsStep
        from impl.common.l2100_sql_grammar.domain.versioning.stmt_validate import SqlCountWhere
        from impl.common.l2100_sql_grammar.domain.versioning.subquery_lookups import SqlRevisionParentSubquery
        from impl.common.l7400_versioned_diff.versioned_diff import _branch_id_subquery

        config = self._config
        domain = config.domain
        revision_parents_table = get_table_name(domain.revision_parent_model)
        revision_table = get_table_name(domain.revision_model)

        validate_step = ValidateExistsStep(
            ref_id=ServerPlanRefId(f"{self.ref_id}_validate_parent"),
            stmt=SqlCountWhere(
                revision_parents_table,
                SqlColumnName("revision_sys_id"),
                config.revision_id,
            ),
            error_message=ValidationErrorMessage(
                "Cannot revert initial revision (no parent found)",
            ),
        )

        parent_subq = SqlRevisionParentSubquery(SqlTableName(revision_table), str(config.revision_id))
        revision_branch_id = _branch_id_subquery(domain, config.revision_id)

        apply_intent = ApplyDiffStagedIntent(
            ref_id=ServerPlanRefId(self.ref_id),
            config=_ApplyDiffStagedConfig(
                domain=domain,
                from_revision=str(config.revision_id),
                to_revision=parent_subq,
                branch_id_raw=config.branch_id_raw,
                staged_commit_id_raw=config.staged_commit_id_raw,
                connection_id_str=config.connection_id_str,
                session_id_raw=config.session_id_raw,
                diff_branch_id=revision_branch_id,
                old_diff_branch_id=revision_branch_id,
            ),
        )
        apply_l0_steps = apply_intent.lower(ctx)

        return [validate_step, *apply_l0_steps]


class _ApplyDiffCountCollectorStep(NonPublishingStep[Any]):
    """L0: aggregate per-table count rows into DiffApplicationResult."""

    def __init__(
        self: _ApplyDiffCountCollectorStep,
        ref_id: ServerPlanRefId,
        config: _ApplyDiffCountCollectorConfig,
    ) -> None:
        super().__init__(ref_id)
        self._count_refs = config.count_refs

    @property
    def level(self: _ApplyDiffCountCollectorStep) -> int:
        return 0

    def result_cardinality(self: _ApplyDiffCountCollectorStep) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self: _ApplyDiffCountCollectorStep) -> bool:
        return True

    def execution_role(self: _ApplyDiffCountCollectorStep) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def step_tags(self: _ApplyDiffCountCollectorStep) -> frozenset[str]:
        return frozenset({"read", "diff", "count", "runtime_projection", "terminal_projection"})

    def tables_read(self: _ApplyDiffCountCollectorStep) -> frozenset[str]:
        return frozenset()

    def tables_written(self: _ApplyDiffCountCollectorStep) -> frozenset[str]:
        return frozenset()

    def dependencies(self: _ApplyDiffCountCollectorStep) -> frozenset[str]:
        return frozenset(str(ref_id) for ref_id in self._count_refs)

    def compile(self: _ApplyDiffCountCollectorStep, ctx: Any) -> CompiledStep[Any]:
        del ctx
        return CompiledStep()

    def execute_runtime(self: _ApplyDiffCountCollectorStep, resolved: ResolvedRefs) -> Any:
        from l7450_versioned_revert.revert import DiffApplicationResult

        inserted = 0
        updated = 0
        deleted = 0
        for ref_id in self._count_refs:
            value = resolved.get(str(ref_id), None)
            rows: Sequence[object]
            if value is None:
                rows = ()
            elif isinstance(value, Mapping):
                rows = (value,)
            elif isinstance(value, Sequence) and not isinstance(value, str | bytes | bytearray):
                rows = value
            else:
                rows = (value,)
            for row in rows:
                if not isinstance(row, Mapping):
                    continue
                inserted += int(row.get("added_count", row.get("inserted", 0)) or 0)
                updated += int(row.get("modified_count", row.get("updated", 0)) or 0)
                deleted += int(row.get("deleted_count", row.get("deleted", 0)) or 0)
        return DiffApplicationResult(inserted=inserted, updated=updated, deleted=deleted)

