def _replacement_to_renderable(
    expr_val: object,
    model_cls: type[DatabaseObjectRow],
    *,
    source_alias: SqlAliasName | None = None,
) -> SqlRenderable:
    """Convert a replacement value to a SQL renderable.

    Handles literal values (via SqlParam), Field references (via SqlColumnRef),
    and Expression trees (arithmetic, etc.) via recursive translation.
    """
    from impl.common.l2050_sql_types.sql_branded_types import SqlAliasName, SqlColumnName
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlParam
    from l1000_schema.schema_def import get_db_column_name
    from l1000_schema.table_utils import get_table_name
    from l1000_schema.typed_field import Expression, Field

    if isinstance(expr_val, Expression):
        return _expression_to_renderable(expr_val, model_cls, source_alias=source_alias)
    if isinstance(expr_val, Field):
        owner = getattr(expr_val, "owner", None)
        field_model = owner if isinstance(owner, type) else model_cls
        col = get_db_column_name(field_model, DynamicFieldName(expr_val.name))
        qualifier = source_alias or SqlAliasName(get_table_name(field_model))
        return SqlColumnRef(SqlColumnName(col), qualifier=qualifier)
    if isinstance(expr_val, str):
        return SqlParam(_TextLiteralParam(expr_val))
    # Literal value — unwrap branded types
    unwrap_to_sql = getattr(expr_val, "unwrap_to_sql", None)
    if callable(unwrap_to_sql):
        expr_val = unwrap_to_sql()
    else:
        unwrap_to_str = getattr(expr_val, "unwrap_to_str", None)
        if callable(unwrap_to_str):
            expr_val = unwrap_to_str()
    return SqlParam(expr_val)


def _expression_to_renderable(
    expr: object,
    model_cls: type[DatabaseObjectRow],
    *,
    source_alias: SqlAliasName | None = None,
) -> SqlRenderable:
    """Translate an Expression tree to SQL grammar renderables."""
    from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlParam
    from l1000_schema.schema_def import get_db_column_name
    from l1000_schema.typed_field import Expression

    if not isinstance(expr, Expression):
        return _replacement_to_renderable(expr, model_cls, source_alias=source_alias)

    # Simple field reference: Expression(field="price")
    if expr.field is not None and expr.operator is None and expr.function is None:
        owner = getattr(expr, "owner", None)
        field_model = owner if isinstance(owner, type) else model_cls
        col = get_db_column_name(field_model, DynamicFieldName(expr.field))
        from impl.common.l2050_sql_types.sql_branded_types import SqlAliasName
        from l1000_schema.table_utils import get_table_name

        qualifier = source_alias or SqlAliasName(get_table_name(field_model))
        return SqlColumnRef(SqlColumnName(col), qualifier=qualifier)

    if expr.function is not None:
        from impl.common.l5200_sql_query.expression_grammar import ExpressionToGrammar

        return ExpressionToGrammar(model_cls, table_alias=source_alias).convert(expr)

    # Arithmetic operators: +, -, *, /, %
    from impl.common.l2100_sql_grammar.tree.enums import BinaryOp, SqlTreeKind

    op_map: dict[str, SqlTreeKind] = {}
    if not op_map:
        op_map.update({"+": BinaryOp.ADD, "-": BinaryOp.SUB, "*": BinaryOp.MUL, "/": BinaryOp.DIV, "%": BinaryOp.MOD})

    if expr.operator in op_map and expr.left is not None:
        from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp

        left_r = _expression_to_renderable(expr.left, model_cls, source_alias=source_alias)
        right_r = (
            _expression_to_renderable(expr.right, model_cls, source_alias=source_alias)
            if expr.right is not None
            else SqlParam(expr.value)
        )
        return SqlBinaryOp(left_r, op_map[expr.operator], right_r)

    # Unary minus: UNARY-
    if expr.operator == "UNARY-" and expr.left is not None:
        from impl.common.l2100_sql_grammar.tree.enums import BinaryOp
        from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp

        left_r = _expression_to_renderable(expr.left, model_cls, source_alias=source_alias)
        zero = SqlParam(0)
        return SqlBinaryOp(zero, BinaryOp.SUB, left_r)

    # Literal value
    if expr.value is not None:
        return SqlParam(expr.value)

    msg = f"Unsupported expression in insert_from_query: {expr!r}"
    raise NotImplementedError(msg)


def _source_has_db_column(source_model: type[DatabaseObjectRow], db_col: str) -> bool:
    """Check if a database column exists in the source model."""
    from l1000_schema.schema_def import get_db_column_name

    return any(get_db_column_name(source_model, DynamicFieldName(field_name)) == db_col for field_name in source_model.model_fields)


def _target_db_columns(
    model_cls: type[DatabaseObjectRow],
    excluded_fields: list[str],
) -> list[str]:
    """Reject unvalidated targets and return writable target columns."""
    from l1100_exceptions.exceptions import PermissionError as DbPermissionError
    from l4000_permissions.permission_enforcement import _try_get_permission_scheme
    from l2070_batching.write_column_policy import writable_db_columns

    scheme = _try_get_permission_scheme(model_cls)
    if scheme is not None and scheme.requires_validated_insert_models():
        raise DbPermissionError("Query-copy insertion cannot validate the target model. Use typed model insertion.")
    columns = writable_db_columns(model_cls, excluded_fields=excluded_fields, include_polymorphic=False)
    excluded = set(excluded_fields)
    return [column for column in columns if column not in excluded]


def _prepared_insert_from_query_target_columns(config: _InsertFromQueryConfig) -> list[str]:
    """Return columns to publish for non-RETURNING execute_returning fallback."""
    target_cols = _target_db_columns(config.model_cls, list(config.excluded_fields))
    if "sys_id" not in target_cols:
        return ["sys_id", *target_cols]
    return target_cols


