@pure_lazy
def InsertFromQueryIntent(
    ref_id: ServerPlanRefId,
    config: _InsertFromQueryConfig,
) -> IntentStep[int]:
    """Route an INSERT...SELECT request to its concrete versioning intent."""
    from impl.common.l2070_server_plan.steps._versioned_routing import is_versioned_model

    if is_versioned_model(config.model_cls):
        return _VersionedInsertFromQueryIntent(ref_id, config=config)
    return _UnversionedInsertFromQueryIntent(ref_id, config=config)


def _prepare_versioned_source_insert_config(
    config: _InsertFromQueryConfig,
) -> _InsertFromQueryConfig:
    """Shape a versioned source projection before the concrete intent is enqueued."""
    from dataclasses import replace

    from l1000_schema.table_utils import get_table_name
    from l1000_schema.typed_field import AliasedExpression, Expression, Field

    source_spec = config.source_query_spec
    if source_spec is None:
        msg = "versioned source insert requires a source query spec"
        raise TypeError(msg)
    target_columns = _target_db_columns(config.model_cls, list(config.excluded_fields))
    ordinal_column = None if config.partitioned_ordinal is None else config.partitioned_ordinal.target_field_name
    replacements = _replacement_map(config.model_cls, list(config.replacements))
    projections: list[SelectColumn] = []
    projection_tables: list[str] = []
    for column in target_columns:
        if column in {"sys_id", ordinal_column}:
            continue
        value = replacements.get(column)
        if value is None:
            if _source_has_db_column(config.source_model, column):
                value = Expression(field=column, owner=config.source_model)
            else:
                value = Expression(value=None)
        if isinstance(value, Field):
            projections.append(value.as_(SchemaObjectName(column)))
            owner = value.owner if isinstance(value.owner, type) else config.source_model
        elif isinstance(value, Expression):
            projections.append(value.as_(SchemaObjectName(column)))
            owner = value.owner if isinstance(value.owner, type) else config.source_model
        else:
            projections.append(AliasedExpression(Expression(value=value), SchemaObjectName(column)))
            owner = config.source_model
        projection_tables.append(get_table_name(owner))
    projected_spec = replace(
        source_spec,
        select_columns=projections,
        select_column_tables=tuple(projection_tables),
        preserve_non_join_projection=True,
        projection_model_cls=config.model_cls,
        for_update=(source_spec.for_update or config.partitioned_ordinal is not None),
    )
    return replace(config, source_query_spec=projected_spec)


