    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        model_cls: type[DatabaseObjectRow],
        rows_ref: ServerPlanRefId,
        do_nothing_on_conflict: bool = False,
        after_refs: Sequence[ServerPlanRefId] = (),
    ) -> None:
        super().__init__(ref_id)
        self._model_cls = model_cls
        self._rows_ref = rows_ref
        self._do_nothing_on_conflict = do_nothing_on_conflict
        self._after_refs = tuple(after_refs)

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.MANY

    def is_read_only(self) -> bool:
        return False

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def step_tags(self) -> frozenset[str]:
        return frozenset({"write", "insert_from_query", "prepared_rows"})

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        from l1000_schema.table_utils import get_table_name

        return frozenset({get_table_name(self._model_cls)})

    def dependencies(self) -> frozenset[str]:
        return frozenset({str(self._rows_ref), *(str(ref) for ref in self._after_refs)})

    def compile(self, ctx: CompilationContext) -> CompiledStep[list[dict[str, Any]]]:
        from impl.common.l2050_sql_types.sql_branded_types import SqlAliasName, SqlColumnName, SqlTableName
        from impl.common.l2100_sql_grammar.domain.infra.stmt_dml_simple import SqlColumnListFragment, SqlInsertFromSelectStmt
        from impl.common.l2100_sql_grammar.tree.clauses import SqlColumnNameList, SqlReturningClause, SqlSelectAlias
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef
        from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
        from impl.common.l2070_server_plan.steps._compile_helpers import (
            cast_postgres_expr_for_db_column,
            get_write_metadata_plan_from_catalog,
        )

        rows_cte = _require_prepared_rows_cte(
            resolve_auxiliary_cte_binding(ctx, self._rows_ref),
            step_name=type(self).__name__,
            rows_ref=self._rows_ref,
        )
        columns = tuple(rows_cte.columns or ())
        write_plan = get_write_metadata_plan_from_catalog(ctx.planning_catalog, self._model_cls)
        column_refs = [SqlColumnRef(SqlColumnName(column)) for column in columns]
        select_columns = SqlColumnListFragment(
            [
                SqlSelectAlias(
                    cast_postgres_expr_for_db_column(
                        backend_type=ctx.backend_type,
                        write_plan=write_plan,
                        db_column=column,
                        expr=column_ref,
                    ),
                    alias=SqlAliasName(column),
                )
                for column, column_ref in zip(columns, column_refs, strict=True)
            ],
        )
        contract = self.cte_publication_contract()
        grammar = SqlInsertFromSelectStmt(
            target=SqlTableName(_sql_table_name(self._model_cls)),
            columns=SqlColumnNameList(column_refs),
            source=SqlTableIdent(SqlTableName(rows_cte.ref_id)),
            select_columns=select_columns,
            returning=SqlReturningClause(_build_returning_column_list(contract.columns)),
            or_ignore=self._do_nothing_on_conflict,
        )

        output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(contract)
        return CompiledStep(
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
            grammar=grammar,
            needs_returning=True,
            closed_post_op=row_dicts_post_op(),
            auxiliary_ctes=[(rows_cte.ref_id, rows_cte.auxiliary_query)] if rows_cte.auxiliary_query is not None else None,
        )


