class InsertFromQueryReturningRawStep(InsertFromQueryReturningStep[dict[str, DatabaseValue]]):
    """Terminal raw-row variant of INSERT...SELECT RETURNING."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        config: _InsertFromQueryConfig,
        *,
        result_ref_id: ServerPlanRefId,
        after_refs: Sequence[ServerPlanRefId] = (),
    ) -> None:
        super().__init__(ref_id, config, after_refs=after_refs)
        self._result_ref_id = result_ref_id

    @property
    def level(self) -> int:
        return 0

    def step_tags(self) -> frozenset[str]:
        return frozenset({"write", "insert_from_query", "returning", "grammar", "raw"})

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def additional_sql_binding_ref_ids(self) -> tuple[ServerPlanRefId, ...]:
        return (self._result_ref_id,)

    def publishes_repeatable_sql_write_product(
        self,
        transport: DmlReturningRelationTransport,
    ) -> bool:
        return transport is DmlReturningRelationTransport.CONNECTION_LOCAL_JSON and self.supports_ordered_sql_statement_batch()

    def cte_publication_contract(self: InsertFromQueryReturningRawStep) -> CtePublicationContract:
        def _legacy_cte_output_columns() -> tuple[str, ...]:
            from l1000_schema.schema_def import get_db_column_name

            return tuple(
                get_db_column_name(self._config.model_cls, DynamicFieldName(field_name))
                for field_name in self._config.model_cls.model_fields
            )

        columns = _legacy_cte_output_columns()

        def _legacy_cte_column_type_hints(columns: tuple[str, ...] | None) -> SqlColumnTypeHints:
            assert columns is not None
            hints = model_sql_column_type_hints(self._config.model_cls, columns)
            if hints is None:
                msg = f"Could not resolve SQL column type hints for {self._config.model_cls.__name__}"
                raise TypeError(msg)
            return hints

        column_type_hints = _legacy_cte_column_type_hints(columns)
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        _contract_model_cls = self._config.model_cls
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=tuple(str(column) for column in columns),
            column_type_hints=column_type_hints,
            model_cls=_contract_model_cls,
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def always_publishes_executor_visible_binding(self) -> bool:
        return True

    def lower(self, ctx: LoweringContext) -> list[ServerPlanStep[Any]]:
        del ctx
        return [self]

    def compile(self, ctx: CompilationContext) -> CompiledStep[list[dict[str, DatabaseValue]]]:
        """Compile INSERT INTO target SELECT ... FROM source RETURNING *."""

        model_cls = self._config.model_cls
        source_model = self._config.source_model

        from impl.common.l2100_sql_grammar.domain.infra.stmt_dml_simple import (
            SqlInsertFromSelectStmt,
        )
        from impl.common.l2100_sql_grammar.tree.clauses import SqlReturningClause

        writable_target_cols = _target_db_columns(model_cls, list(self._config.excluded_fields))
        target_cols = _prepared_insert_from_query_target_columns(self._config)
        contract = self.cte_publication_contract()
        target_table = _sql_table_name(model_cls)
        source_table: SqlRenderable | SqlTableName = _sql_table_name(source_model)
        from dataclasses import replace
        from impl.common.l2070_server_plan.steps._compile_helpers import (
            _resolve_server_ref_filters_to_cte,
        )

        source_spec = self._config.source_query_spec
        relation_predicates: list[Any] = []
        consumed_cte_refs: list[CteReference] = []
        if source_spec is not None:
            source_spec = replace(source_spec, filters=list(source_spec.filters))
            relation_predicates = _resolve_server_ref_filters_to_cte(
                source_spec,
                ctx,
                table_alias=str(source_table),
                consumed_cte_refs=consumed_cte_refs,
            )
        source_joins: Sequence[SqlRenderable] = ()
        source_where: SqlRenderable | None = None
        source_for_update: SqlRenderable | None = None
        source_group_by: SqlGroupByClause | None = None
        source_having: SqlRenderable | None = None
        source_order_by: SqlRenderable | None = None
        if source_spec is not None:
            from impl.common.l5200_sql_query.query_grammar import QueryGrammarBuilder

            source_grammar = QueryGrammarBuilder(
                source_spec,
                compilation_context=ctx,
            )
            source_table = source_grammar._build_from_clause()
            source_joins = tuple(source_grammar._build_join_clauses())
            source_where_clause = source_grammar.build_where_clause()
            source_where = None if source_where_clause is None else source_where_clause._condition
            source_for_update = source_grammar._build_for_update_clause()
            source_group_by = source_grammar._build_group_by_clause()
            source_having = source_grammar._build_having_clause()
            source_order_by = source_grammar._build_order_by_clause()
        target_col_list = _build_target_column_list(target_cols)
        select_col_list = _build_select_column_list(
            target_cols,
            source_model,
            _replacement_map(model_cls, list(self._config.replacements)),
            generate_sys_id="sys_id" not in writable_target_cols,
            config=self._config,
            compilation_context=ctx,
            target_model=model_cls,
        )
        where_clause = source_where or _build_where_clause(list(self._config.exprs), source_model, ctx)
        order_by_renderable = (
            source_order_by if source_order_by is not None else _build_order_by_items(list(self._config.order_by), source_model)
        )
        limit_clause = _build_limit_clause(self._config.limit)
        offset_clause = _build_offset_clause(self._config.offset)
        assert contract.column_type_hints is not None
        capture = None
        if ctx.backend_profile.traits.dml_returning_relation_transport is DmlReturningRelationTransport.CONNECTION_LOCAL_JSON:
            from impl.common.l2070_server_plan.steps.mariadb_returning_capture import (
                build_mariadb_returning_capture,
            )

            capture = build_mariadb_returning_capture(
                self.ref_id,
                tuple(SqlColumnName(column) for column in contract.columns),
                contract.column_type_hints,
            )
        returning = SqlReturningClause(
            _build_returning_column_list(contract.columns) if capture is None else capture.returning_columns,
        )
        from impl.common.l2070_server_plan.steps._compile_helpers import _combine_where

        where_clause = _combine_where(
            source_where if source_spec is not None else where_clause,
            relation_predicates,
        )

        grammar = SqlInsertFromSelectStmt(
            target=target_table,
            columns=target_col_list,
            source=source_table,
            select_columns=select_col_list,
            where=where_clause,
            joins=source_joins,
            group_by=source_group_by,
            having=source_having,
            order_by=order_by_renderable,
            limit=limit_clause,
            offset=offset_clause,
            returning=returning,
            or_ignore=self._config.do_nothing_on_conflict,
            for_update=source_for_update,
        )

        from impl.common.l2100_sql_grammar.domain.infra.stmt_compound_write import (
            SqlStatementBatch,
            SqlStatementBatchCategory,
            SqlStatementRelationship,
            SqlStatementRelationshipKind,
        )

        output_grammar: SqlRenderable = (
            grammar
            if capture is None
            else SqlStatementBatch(
                (capture.initialize, grammar),
                category=SqlStatementBatchCategory.DEPENDENCY_GRAPH,
                relationships=(SqlStatementRelationship(0, 1, SqlStatementRelationshipKind.DATA_VISIBILITY),),
                needs_returning_per_stmt=(False, True),
                collect_results_per_stmt=(False, True),
            )
        )
        contract = self.cte_publication_contract()
        from l2070_batching.output_shape import CompiledOutputShape, DeclaredResultRelation, synthetic_output_field

        output_shape = CompiledOutputShape(
            tuple(synthetic_output_field(column) for column in contract.columns),
        )
        return CompiledStep(
            output_shape=output_shape,
            result_relation=DeclaredResultRelation.from_output_shape(output_shape),
            grammar=output_grammar,
            compiled_sql_publication=compiled_sql_publication_from_query(
                ref_id=self.ref_id,
                query=None if capture is None else capture.query,
                contract=contract,
            ),
            needs_returning=True,
            column_type_hints=contract.column_type_hints,
            closed_post_op=row_dicts_post_op(),
            auxiliary_ctes=_available_auxiliary_ctes(
                ctx,
                self.sql_visible_dependencies(),
            ),
        )


class VersionedInsertFromQueryStep(NonPublishingStep[int]):
    """Step for executing a stored VersionedInsertFromQueryBuilder.

    Level 1 step whose ``lower()`` is not yet implemented because the
    builder produces a complex INSERT...SELECT FROM (UNION ALL subquery)
    merging tip and staged rows.  The grammar infrastructure does not
    yet support INSERT FROM subquery (``SqlInsertFromSelectStmt`` only
    accepts a table name source, not an arbitrary ``SqlRenderable``).

    Requirements for full lowering:

    * ``SqlInsertFromSelectStmt`` (or a new grammar) accepting a subquery
      or CTE as the source
    * Dialect-aware UUID generation grammar (replacing raw
      ``get_uuid7_select_expression()`` strings)
    * Grammar for NOT IN subquery within WHERE
    """

    def __init__(
        self: VersionedInsertFromQueryStep,
        ref_id: ServerPlanRefId,
        builder: object,
    ) -> None:
        super().__init__(ref_id)
        self._builder = builder

    @property
    def level(self: VersionedInsertFromQueryStep) -> int:
        return 1

    def step_tags(self: VersionedInsertFromQueryStep) -> frozenset[str]:
        return frozenset({"write", "versioned", "insert_from_query", "grammar"})

    def is_read_only(self: VersionedInsertFromQueryStep) -> bool:
        return False

    def result_cardinality(self: VersionedInsertFromQueryStep) -> Cardinality:
        return Cardinality.SCALAR

    def tables_read(self: VersionedInsertFromQueryStep) -> frozenset[str]:
        """Versioned insert-from-query reads from source tables."""
        return frozenset()

    def tables_written(self: VersionedInsertFromQueryStep) -> frozenset[str]:
        """Versioned insert-from-query writes to target table."""
        return frozenset()

    def lower(
        self: VersionedInsertFromQueryStep,
        ctx: LoweringContext,
    ) -> Sequence[ServerPlanStep]:
        """Lower to Level 0 steps.

        Not yet implemented.  The ``VersionedInsertFromQueryBuilder``
        generates complex INSERT...SELECT FROM (tip UNION ALL staged)
        SQL that requires grammar infrastructure that does not exist yet:

        * ``SqlInsertFromSelectStmt`` with subquery/CTE source
        * Dialect-aware UUID generation grammar
        * Transaction-scoped ``staged_commit_id`` parameter injection

        Raises ``NotImplementedError`` so callers can fall back to
        direct builder execution.
        """
        raise NotImplementedError(
            "VersionedInsertFromQueryStep.lower() requires grammar support "
            "for INSERT FROM subquery (UNION ALL of tip + staged tables). "
            "SqlInsertFromSelectStmt currently only accepts SqlTableName sources.",
        )

    def compile(self: VersionedInsertFromQueryStep, ctx: CompilationContext) -> CompiledStep[int]:
        del ctx
        raise TypeError(
            f"{type(self).__name__} is level {self.level} and must be lowered to terminal steps before compile() is called.",
        )

