def _squash_auxiliary_ctes(
    ctx: CompilationContext,
    ref_ids: Sequence[str],
) -> list[tuple[str, Any]] | None:
    """Carry exact upstream SQL relations into a standalone squash statement."""
    from impl.common.l2070_server_plan.steps._query_helper_compile import (
        _collect_auxiliary_ctes_from_consumed,
    )
    from l2070_batching.compilation import CteReference

    consumed_refs: list[CteReference] = []
    for ref_id in ref_ids:
        binding = ctx.cte_refs.get(str(ref_id))
