            old_branch_id_raw=branch_id_sql,
        )
        grammar = SqlApplyRebaseInsert(
            diff_cte=diff_cte,
            sparse_table=self._sparse_table,
            branch_id_raw=branch_id_sql,
            new_revision_id_raw=lower_scalar_server_ref(self._result_revision_id, ctx),
