        self._target_tip_scalar_ref_id = target_tip_scalar_ref_id
        self._result_revision_id = result_revision_id
        self._revision_parents_table = revision_parents_table
        self._ordinal = ordinal
        self._parent_sys_id = parent_sys_id

    @property
    def level(self: InsertSquashMergeParentStep) -> int:
        return 0

    def result_cardinality(self: InsertSquashMergeParentStep) -> Cardinality:
        return Cardinality.NONE

    def is_read_only(self: InsertSquashMergeParentStep) -> bool:
        return False

    def execution_role(self: InsertSquashMergeParentStep) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def emits_sql_for_accounting(self: InsertSquashMergeParentStep) -> bool | None:
        return True

    def step_tags(self: InsertSquashMergeParentStep) -> frozenset[str]:
        return frozenset({"write", "insert", "revision_parent", "squash_merge", "grammar"})

    def tables_read(self: InsertSquashMergeParentStep) -> frozenset[str]:
        return frozenset()

    def tables_written(self: InsertSquashMergeParentStep) -> frozenset[str]:
        return frozenset({str(self._revision_parents_table)})

    def dependencies(self: InsertSquashMergeParentStep) -> frozenset[str]:
        return frozenset(
            {
                str(self._target_branch_ref_id),
                str(self._target_tip_scalar_ref_id),
                *_ref_dependencies(self._result_revision_id),
            },
        )

    def compile(self: InsertSquashMergeParentStep, ctx: CompilationContext) -> CompiledStep[None]:
        from l2070_batching.compilation import CompiledStep as _CompiledStep
        from impl.common.l2050_sql_types.sql_branded_types import SqlTableName
        from impl.common.l2070_server_plan.steps._compile_server_ref import lower_scalar_source
        from impl.common.l2100_sql_grammar.domain.versioning.stmt_insert_select import SqlInsertFromSelect
        from impl.common.l2100_sql_grammar.tree.enums import UnaryOp
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlParam
        from impl.common.l2100_sql_grammar.tree.expr_ops import SqlUnaryOp

        target_columns = [
            "sys_id",
            "revision_sys_id",
            "parent_revision_sys_id",
            "relationship_type",
            "ordinal",
        ]
        grammar: SqlRenderable
        from l2070_batching.compilation import CteReference
        from impl.common.l2100_sql_grammar.domain.infra.stmt_dml_simple import SqlCteFieldRef

        scalar_cte = ctx.cte_refs.get(str(self._target_tip_scalar_ref_id))
        branch_cte = ctx.cte_refs.get(str(self._target_branch_ref_id))
        cte_tip_expr: SqlRenderable
        if isinstance(scalar_cte, CteReference):
            cte_name = scalar_cte.ref_id
            cte_tip_expr = SqlCteFieldRef(ServerPlanRefId(cte_name), SqlColumnName("v"))
        else:
            if branch_cte is None:
                msg = (
                    "InsertSquashMergeParentStep requires CTE-bound target tip scalar ref "
                    f"{str(self._target_tip_scalar_ref_id)!r} or "
                    f"target branch ref {str(self._target_branch_ref_id)!r}."
                )
                raise NotImplementedError(msg)
            cte_name = branch_cte.ref_id
            cte_tip_expr = _require_squash_cte_field(
                ctx,
                ServerPlanRefId(self._target_branch_ref_id),
                "tip_revision_sys_id",
            )
        where_tip = SqlUnaryOp(UnaryOp.IS_NOT_NULL, cte_tip_expr)
        select_exprs_cte: list[SqlRenderable] = [
            SqlParam(str(self._parent_sys_id)),
            lower_scalar_source(self._result_revision_id, ctx, default_field="v"),
            cte_tip_expr,
            SqlParam("squash"),
            SqlParam(int(self._ordinal)),
        ]
        grammar = SqlInsertFromSelect(
            target_table=self._revision_parents_table,
            target_columns=target_columns,
            source_table=SqlTableName(cte_name),
            select_exprs=select_exprs_cte,
            where=where_tip,
        )
        return _CompiledStep(grammar=grammar, needs_returning=False)


class BuildSquashMergeResultStep(SqlRelationPublisherStep[MergeResult]):
    """Build the clean squash-merge ``MergeResult`` from semantic context and diffs."""

    __slots__ = ("_completion_ref_id", "_ctx_ref_id", "_diff_ref_ids", "_source_changes_ref_id")

    def __init__(
        self: BuildSquashMergeResultStep,
        ref_id: ServerPlanRefId,
        *,
        ctx_ref_id: ServerPlanRefId,
        diff_ref_ids: Sequence[ServerPlanRefId],
        completion_ref_id: ServerPlanRefId | None = None,
        source_changes_ref_id: ServerPlanRefId | None = None,
    ) -> None:
        super().__init__(ref_id)
        self._ctx_ref_id = ServerPlanRefId(ctx_ref_id)
        self._diff_ref_ids = tuple(ServerPlanRefId(ref_id) for ref_id in diff_ref_ids)
        self._completion_ref_id = completion_ref_id
        self._source_changes_ref_id = source_changes_ref_id

    @property
    def level(self: BuildSquashMergeResultStep) -> int:
        return 0

    def result_cardinality(self: BuildSquashMergeResultStep) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self: BuildSquashMergeResultStep) -> bool:
        return True

    def execution_role(self: BuildSquashMergeResultStep) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def step_tags(self: BuildSquashMergeResultStep) -> frozenset[str]:
        return frozenset({"read", "squash_merge", "semantic_result"})

    def is_semantic_result_projection(self: BuildSquashMergeResultStep) -> bool:
        return True

    def tables_read(self: BuildSquashMergeResultStep) -> frozenset[str]:
        return frozenset()

    def tables_written(self: BuildSquashMergeResultStep) -> frozenset[str]:
        return frozenset()

    def cte_publication_contract(self: BuildSquashMergeResultStep) -> CtePublicationContract:
        columns = _MERGE_RESULT_ROW_COLUMNS
        column_type_hints = _merge_result_type_hints()
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        contract_columns = tuple(str(column) for column in columns)
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=contract_columns,
            column_type_hints=column_type_hints,
            relation_contract=CteRelationContract.semantic_row(_SquashMergeResultRow),
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def dependencies(self: BuildSquashMergeResultStep) -> frozenset[str]:
        return frozenset(
            {
                str(self._ctx_ref_id),
                *(str(ref_id) for ref_id in self._diff_ref_ids),
                *((str(self._completion_ref_id),) if self._completion_ref_id is not None else ()),
                *((str(self._source_changes_ref_id),) if self._source_changes_ref_id is not None else ()),
            },
        )

    def sql_visible_dependencies(self: BuildSquashMergeResultStep) -> frozenset[str]:
        return frozenset(
            {
                str(self._ctx_ref_id),
                *(str(ref_id) for ref_id in self._diff_ref_ids),
                *((str(self._source_changes_ref_id),) if self._source_changes_ref_id is not None else ()),
            },
        )

    def compile(self: BuildSquashMergeResultStep, ctx: CompilationContext) -> CompiledStep[MergeResult]:
        from l2070_batching.compilation import CompiledStep as _CompiledStep
        from l2070_batching.compilation import CteReference
        from impl.common.l2050_sql_types.sql_branded_types import SqlCteName
        from impl.common.l2100_sql_grammar.domain.infra.stmt_cte_helpers import SqlSelectExpressions
        from impl.common.l2100_sql_grammar.domain.versioning.stmt_conditional_gate import (
            SqlBoolColumnSubquery,
            SqlGateCte,
            SqlGatedWhere,
        )
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlParam

        ctx_ref_id = str(self._ctx_ref_id)
        diff_cte_names: list[str] = []
        for diff_ref_id in self._diff_ref_ids:
            diff_ref = str(diff_ref_id)
            binding = ctx.cte_refs.get(diff_ref)
            if not isinstance(binding, CteReference):
                raise_missing_cte_fallback_forbidden(
                    site_name=type(self).__name__,
                    trigger=f"squash merge diff ref {diff_ref!r} is not SQL-visible",
                    blocked_path="runtime squash merge diff row counting",
                    result_contract="squash merge result must compile to a SQL result-facts row",
                    implementation_requirements=(
                        "Publish each squash merge diff relation as a SQL CTE before result construction.",
                        "Count source-side diff change types in SQL over those CTEs.",
                        "Do not recover by iterating materialized diff rows in Python.",
                    ),
                )
            diff_cte_names.append(binding.ref_id)

        grammar: SqlRenderable = SqlSelectExpressions(
            [
                (SqlParam(MergeStatus.PUBLISHED.value), "status"),
                (_require_squash_cte_field(ctx, ServerPlanRefId(ctx_ref_id), "operation_id"), "operation_id"),
                (_require_squash_cte_field(ctx, ServerPlanRefId(ctx_ref_id), "base_revision_id"), "base_revision_id"),
                (_require_squash_cte_field(ctx, ServerPlanRefId(ctx_ref_id), "source_revision_id"), "source_revision_id"),
                (_require_squash_cte_field(ctx, ServerPlanRefId(ctx_ref_id), "target_revision_id"), "target_revision_id"),
                (_require_squash_cte_field(ctx, ServerPlanRefId(ctx_ref_id), "result_revision_id"), "result_revision_id"),
                (_squash_change_type_count_expr(diff_cte_names, "ADD_SOURCE"), "inserted"),
                (_squash_change_type_count_expr(diff_cte_names, "MODIFY_SOURCE"), "updated"),
                (_squash_change_type_count_expr(diff_cte_names, "DELETE_SOURCE"), "deleted"),
                (SqlParam("[]"), "conflicts"),
            ],
            jsonb_columns=frozenset({"conflicts"}),
        )
        auxiliary_ref_ids = [
            str(self._ctx_ref_id),
            *(str(ref_id) for ref_id in self._diff_ref_ids),
        ]
        auxiliary_ctes = _squash_auxiliary_ctes(ctx, auxiliary_ref_ids) or []
        if self._source_changes_ref_id is not None:
            source_changes_ref_id = str(self._source_changes_ref_id)
            source_changes_binding = ctx.cte_refs.get(source_changes_ref_id)
            if not isinstance(source_changes_binding, CteReference):
                msg = f"Squash source-changes dependency {source_changes_ref_id!r} has no SQL-visible CTE binding."
                raise ProgrammingError(msg)
            auxiliary_ctes.extend(_squash_auxiliary_ctes(ctx, [source_changes_ref_id]) or [])
            gate_name = SqlCteName(f"{self.ref_id}__source_changes_gate")
            auxiliary_ctes.append(
                (
                    str(gate_name),
                    SqlGateCte(SqlBoolColumnSubquery(source_changes_binding.ref_id, "__result")),
                ),
            )
            grammar = SqlGatedWhere(grammar, gate_name)

        output_shape, result_relation, column_type_hints = _compiled_contract_artifacts(self)
        return _CompiledStep(
            grammar=grammar,
            needs_returning=True,
            closed_post_op=merge_result_post_op(allow_empty_absent=True),
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
            auxiliary_ctes=auxiliary_ctes or None,
        )


