        from impl.common.l2100_sql_grammar.protocols import SqlRenderable
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlParam
        from l1000_schema.schema_def import get_db_column_name
        from l1000_schema.table_utils import get_table_name

        binding = ctx.cte_refs.get(str(self._source_ref)) if ctx.cte_refs is not None else None
        if binding is None:
            raise_runtime_replanning_forbidden(
                step_name=type(self).__name__,
                trigger=f"compile-time lowering for {self._source_ref!r} without a published CTE binding",
                blocked_path=(
                    "planner-time materialization of a resolved lookup row in Python before rebuilding the versioned update payload"
                ),
                result_contract=("key-based versioned update payloads must attach sys_id through explicit CTE-visible relations only"),
                implementation_requirements=(
                    "Publish the lookup row as an explicit upstream CTE before compiling this step.",
                    "Keep sys_id attachment inside SQL-visible prerequisite steps.",
                    "Do not read resolved lookup rows in Python during compile().",
                ),
            )

        items: list[tuple[SqlRenderable, str]] = [
            (
                SqlCteFieldRef(
                    ServerPlanRefId(binding.ref_id),
                    SqlColumnName(get_db_column_name(self._model_cls, DynamicFieldName("sys_id"))),
                ),
                "sys_id",
