        __opa002_grammar_205 = SqlSelectExpressions(items)
        output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(
            self.cte_publication_contract(),
        )
        return CompiledStep(
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
            grammar=__opa002_grammar_205,
            needs_returning=True,
            closed_post_op=row_dicts_post_op(),
            auxiliary_ctes=[(binding.ref_id, binding.auxiliary_query)] if binding.auxiliary_query is not None else None,
        )

    def _build_output_columns_and_values(
        self,
        template_instance: T,
    ) -> tuple[tuple[str, ...], tuple[object, ...]]:
        from l1000_schema.schema_def import get_db_column_name
        from l2070_batching.write_column_policy import writable_field_plans

        model_cls = type(template_instance)
        row_data = template_instance.model_dump()
        columns = [get_db_column_name(self._model_cls, DynamicFieldName("sys_id"))]
        values: list[object] = []
        for field_plan in writable_field_plans(
            model_cls,
            excluded_fields=("sys_id",),
            include_polymorphic=False,
        ):
            field_name = field_plan.field_name
            columns.append(get_db_column_name(self._model_cls, DynamicFieldName(field_name)))
            values.append(row_data[field_name])
        return tuple(columns), tuple(values)


