    def _build_source_rows(self) -> tuple[tuple[str, ...], list[dict[str, object]]]:
        from l1000_schema.schema_def import get_db_column_name

        source_db_columns = self._configured_source_db_columns or tuple(
            get_db_column_name(self._model_cls, DynamicFieldName(field_name)) for field_name in self._source_field_names
        )
        if len(source_db_columns) != len(self._source_field_names):
            msg = (
                f"{type(self).__name__} received {len(self._source_field_names)} source fields "
                f"but {len(source_db_columns)} source database columns"
            )
            raise ValueError(msg)
        source_columns = ("_input_ord", *source_db_columns)
        published_rows = [
            {
                "_input_ord": idx,
                **dict(zip(source_columns[1:], row, strict=True)),
            }
            for idx, row in enumerate(self._source_input_rows)
        ]
        return source_columns, published_rows

    def _build_join_columns(self) -> list[str]:
        from l1000_schema.schema_def import get_db_column_name

        return [get_db_column_name(self._model_cls, DynamicFieldName(field_name)) for field_name in self._key_field_names]

    def _match_data_columns(self) -> tuple[str, ...]:
        from l1000_schema.schema_def import get_db_column_name, is_database_generated_column
        from l2070_batching.write_column_policy import physical_table_publication_columns

        family_columns = {SqlColumnName(column) for column in physical_table_publication_columns(self._model_cls)}
        generated_columns = {
            get_db_column_name(self._model_cls, DynamicFieldName(field_name))
            for field_name, field_info in self._model_cls.model_fields.items()
            if is_database_generated_column(field_info)
        }
        ordered_columns = [
            column for column in self._staging_ctx.common_columns if column in family_columns and column not in generated_columns
        ]
        ordered_columns.extend(
            column
            for column in self._source_columns
            if column in family_columns and column not in generated_columns and column not in ordered_columns
        )
        return tuple(ordered_columns)

    def _build_output_columns_and_selection(self) -> tuple[tuple[str, ...], list[tuple[str, str]]]:
        from l1000_schema.schema_def import get_db_column_name

        source_db_columns = set(self._source_columns)
        identity_column = str(get_db_column_name(self._model_cls, DynamicFieldName("sys_id")))
        output_columns = ["_input_ord", identity_column, "__inserted"]
        selected_columns: list[tuple[str, str]] = [
            ("src", "_input_ord"),
            ("m", identity_column),
            ("m", "__inserted"),
        ]
        framework_columns = {
            get_db_column_name(self._model_cls, DynamicFieldName(field_name))
            for field_name in ("sys_id", "branch_id", "revision_id", "staged_commit_id", "deleted")
        }
        for db_column in self._match_data_columns():
            if db_column in framework_columns:
                continue
            output_columns.append(db_column)
            selected_columns.append(("src" if db_column in source_db_columns else "m", db_column))
        return tuple(output_columns), selected_columns


