    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def dependencies(self) -> frozenset[str]:
        return frozenset({str(self._matched_ref)})

    def cte_publication_contract(self: MissingRawRowsByInputOrdinalStep) -> CtePublicationContract:
        columns = tuple((str(column) for column in self._raw_columns))
        column_type_hints = model_sql_column_type_hints(self._model_cls, columns)
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        _contract_model_cls = self._model_cls
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=tuple(str(column) for column in columns),
            column_type_hints=column_type_hints,
            model_cls=_contract_model_cls,
            relation_role=self.cte_relation_role(),
            source_tables=None,
        )

    def compile(self, ctx: CompilationContext) -> CompiledStep[list[dict[str, object]]]:
        from impl.common.l2100_sql_grammar.domain.infra.stmt_cte_helpers import SqlRequestInputRowsQuery
        from impl.common.l2100_sql_grammar.tree.clauses import SqlItemList, SqlJoin
        from impl.common.l2100_sql_grammar.tree.enums import BinaryOp, JoinKind
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef
        from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp, SqlIsNull
        from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
        from impl.common.l2100_sql_grammar.tree.statements import SqlSelect
        from impl.common.l2070_server_plan.steps._auxiliary_ctes import collect_dependency_auxiliary_ctes

        candidate_cte_name = f"{self.ref_id}_candidate_rows"
        matched_binding = ctx.cte_refs.get(str(self._matched_ref)) if ctx.cte_refs is not None else None
        matched_cte_name = matched_binding.ref_id if isinstance(matched_binding, CteReference) else str(self._matched_ref)
        raw_column_names = self.cte_publication_contract().columns
        candidate_columns = ("_input_ord", *raw_column_names)
        candidate_rows = _candidate_rows_by_input_ordinal(raw_column_names, self._raw_rows)
        selected_columns = [SqlColumnRef(column, qualifier=candidate_cte_name) for column in self._raw_columns]
        input_ord = SqlColumnName("_input_ord")
        grammar = SqlSelect(
            SqlItemList(selected_columns),
            from_=SqlTableIdent(SqlTableName(candidate_cte_name)),
            joins=[
                SqlJoin(
                    JoinKind.LEFT,
                    SqlTableIdent(SqlTableName(matched_cte_name)),
                    SqlBinaryOp(
                        SqlColumnRef(input_ord, qualifier=candidate_cte_name),
                        BinaryOp.EQ,
                        SqlColumnRef(input_ord, qualifier=matched_cte_name),
                    ),
                ),
            ],
            where=SqlIsNull(SqlColumnRef(input_ord, qualifier=matched_cte_name)),
        )
        auxiliary_ctes = collect_dependency_auxiliary_ctes(ctx, self.dependencies()) or []
        candidate_model_hints = model_sql_column_type_hints(self._model_cls, candidate_columns)
        if candidate_model_hints is None:
            msg = f"Could not resolve SQL column type hints for {self._model_cls.__name__}"
            # Versioned lazy candidates must preserve complete SQL type metadata.
            raise ProgrammingError(msg)
        candidate_type_hints = combine_sql_column_type_hints(
            candidate_columns,
            candidate_model_hints,
            SqlColumnTypeHints(integer_columns=frozenset({"_input_ord"})),
        )
        if candidate_type_hints is None:
            msg = f"Could not combine SQL column type hints for {self._model_cls.__name__}"
            # Versioned lazy candidates must preserve complete SQL type metadata.
            raise ProgrammingError(msg)
        auxiliary_ctes.append(
            (
                candidate_cte_name,
                SqlRequestInputRowsQuery(
                    columns=candidate_columns,
                    rows=candidate_rows,
                    type_hints=candidate_type_hints,
                ),
            ),
        )
        __opa002_grammar_591 = grammar
        output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(
            self.cte_publication_contract(),
        )
        return CompiledStep(
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
            grammar=__opa002_grammar_591,
            needs_returning=True,
            closed_post_op=row_dicts_post_op(),
            auxiliary_ctes=auxiliary_ctes,
        )


