class ExtractFieldFromResolvedRowStep[T](ReturnValueStep[T | None]):
    """Extract one field from a previously-resolved row/model/dict."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        source_ref: str,
        field_name: str,
        coerce: Callable[[object], T] | None = None,
    ) -> None:
        super().__init__(ServerPlanRefId(ref_id), None)
        self._source_ref = source_ref
        self._field_name = field_name
        self._coerce = coerce

    def dependencies(self) -> frozenset[str]:
        return frozenset({self._source_ref})

    def declares_consumed_rows_reduction(self: ExtractFieldFromResolvedRowStep[T]) -> bool:
        return True

    def execution_role(self: ExtractFieldFromResolvedRowStep[T]) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def publishes_executor_visible_binding(self: ExtractFieldFromResolvedRowStep[T]) -> bool:
        return True

    def cte_publication_contract(self: ExtractFieldFromResolvedRowStep) -> CtePublicationContract:
        columns = (self._field_name,)

        def _legacy_cte_column_type_hints(columns: tuple[str, ...] | None) -> SqlColumnTypeHints:
            column = str(self._field_name)
            if column == "sys_id" or column.endswith("_id"):
                return SqlColumnTypeHints(uuid_columns=frozenset({column}))
            return SqlColumnTypeHints(text_columns=frozenset({column}))

        column_type_hints = _legacy_cte_column_type_hints(columns)
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        contract_columns = tuple(str(column) for column in columns)
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=contract_columns,
            column_type_hints=column_type_hints,
            relation_contract=CteRelationContract.source_cte(source_cte_ref=str(self._source_ref)),
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def compile(self, ctx: CompilationContext) -> CompiledStep[T | None]:
        from impl.common.l2100_sql_grammar.domain.infra.stmt_cte_helpers import SqlSelectExpressions
        from impl.common.l2100_sql_grammar.domain.infra.stmt_dml_simple import SqlCteFieldRef
        from impl.common.l2070_server_plan.steps.versioned_lazy_runtime_projection import (
            _scalar_coercion_from_coerce,
        )
        from l2070_batching.compilation import CteReference
        from l2070_batching.output_shape import CompiledOutputShape, DeclaredResultRelation, synthetic_output_field
        from l2070_batching.post_op import scalar_column_post_op

        binding = ctx.cte_refs.get(str(self._source_ref))
        if isinstance(binding, CteReference):
            try:
                if binding.column_type_hints is None:
                    column_type_hints = self.cte_publication_contract().column_type_hints
                else:
                    column_type_hints = binding.column_type_hints.filtered({self._field_name}).require_complete(
                        (self._field_name,),
                    )
            except ValueError:
                if self._field_name != "sys_id" and not self._field_name.endswith("_id"):
                    raise
                column_type_hints = SqlColumnTypeHints(uuid_columns=frozenset({self._field_name}))
            output_shape = CompiledOutputShape((synthetic_output_field(self._field_name),))
            return CompiledStep(
                grammar=SqlSelectExpressions(
                    [
                        (
                            SqlCteFieldRef(
                                ServerPlanRefId(binding.ref_id),
                                SqlColumnName(self._field_name),
                            ),
                            self._field_name,
                        )
                    ],
                ),
                needs_returning=True,
                auxiliary_ctes=([(binding.ref_id, binding.auxiliary_query)] if binding.auxiliary_query is not None else None),
                output_shape=output_shape,
                result_relation=DeclaredResultRelation.from_output_shape(output_shape),
                column_type_hints=column_type_hints,
                closed_post_op=scalar_column_post_op(
                    self._field_name,
                    scalar_coercion=_scalar_coercion_from_coerce(self._coerce),
                ),
            )
        return runtime_extract_field_from_resolved_row_compiled_step(
            source_ref=self._source_ref,
            field_name=self._field_name,
            coerce=self._coerce,
            ctx=ctx,
        )

    def _extract_field(self, source: object) -> T | None:
        if source is None:
            return None
        raw = source.get(self._field_name) if isinstance(source, dict) else getattr(source, self._field_name, None)
        if raw is None:
            return None
        if self._coerce is not None:
            return self._coerce(raw)
        return cast(T, raw)


