        ref_id: ServerPlanRefId,
        *,
        source_ref: str,
        explicit_model_cls: type[DatabaseObjectRow],
    ) -> None:
        super().__init__(ServerPlanRefId(ref_id), SysId(uuid.UUID(int=0)))
        self._source_ref = source_ref
        self._explicit_model_cls = explicit_model_cls

