        return frozenset({self._source_ref})

    def cte_publication_contract(self) -> CtePublicationContract:
        from l2070_batching.cte_contracts import projection_over_model_contract

        return projection_over_model_contract(
            columns=("sys_id",),
            column_type_hints=SqlColumnTypeHints(uuid_columns=frozenset({"sys_id"})),
            source_model_cls=self._explicit_model_cls,
            projection_lineage=(("sys_id", "sys_id"),),
            relation_role=self.cte_relation_role(),
            source_tables=frozenset({get_table_name(self._explicit_model_cls)}),
        )

    def compile(self, ctx: CompilationContext) -> CompiledStep[SysId]:
        return runtime_sys_id_from_resolved_row_id_compiled_step(
            source_ref=self._source_ref,
            explicit_model_cls=self._explicit_model_cls,
            ctx=ctx,
        )

    def _project_sys_id(self, resolved_value: object) -> SysId:
        if resolved_value is None:
            msg = (
                f"SysIdFromResolvedRowIdStep missing dependency {self._source_ref!r}: "
                f"RowId resolution produced no value for {self._explicit_model_cls.__name__}"
            )
            raise RuntimeError(msg)
        if not isinstance(resolved_value, RowId):
            msg = f"Expected RowId for {self._source_ref!r}, got {type(resolved_value).__name__}"
            raise TypeError(msg)
        resolved_table = type(resolved_value).resolve_target_table()
        if resolved_table is not self._explicit_model_cls:
            msg = f"RowId target {resolved_table.__name__} does not match explicit model_cls {self._explicit_model_cls.__name__}"
            raise TypeError(msg)
        return SysId(resolved_value.unwrap_to_uuid())


def _raw_model_sql_projection(
    model_cls: type[DatabaseObjectRow],
    source_columns: tuple[str, ...],
    source_hints: SqlColumnTypeHints,
) -> tuple[tuple[str, ...], SqlSelectList, SqlColumnTypeHints]:
    """Build a final SQL projection under public model field names."""
    from impl.common.l2100_sql_grammar.tree.clauses import SqlSelectAlias, SqlSelectList
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef

    output_columns = tuple(get_python_field_name(model_cls, SqlColumnName(source_column)) for source_column in source_columns)

    if len(output_columns) != len(set(output_columns)):
        msg = f"Raw model projection contains duplicate public columns: {output_columns!r}."
        raise ValueError(msg)
    select_items = tuple(
        SqlColumnRef(SqlColumnName(source_column))
        if source_column == output_column
        else SqlSelectAlias(
            SqlColumnRef(SqlColumnName(source_column)),
            SqlAliasName(output_column),
        )
        for source_column, output_column in zip(
            source_columns,
            output_columns,
            strict=True,
        )
    )
    output_hints = combine_sql_column_type_hints(
        output_columns,
        *(
            source_hints.rename_column(source_column, output_column)
            for source_column, output_column in zip(
                source_columns,
                output_columns,
                strict=True,
            )
        ),
    )
    return output_columns, SqlSelectList(select_items), output_hints


