            grammar=__opa002_grammar_1237,
            needs_returning=True,
            closed_post_op=scalar_column_post_op(
                self._field_name,
                scalar_coercion=self._scalar_coercion,
            ),
            auxiliary_ctes=[(cte_ref.ref_id, cte_ref.auxiliary_query)] if cte_ref.auxiliary_query is not None else None,
        )


class _TruthyOptionalRowStepCteRow(BaseModel):
    exists: bool = Field(json_schema_extra={"db_column": "__exists"})


class TruthyOptionalRowStep(ReturnValueStep[bool]):
    """Return ``True`` when a prior step resolved a non-``None`` row/object."""

    def __init__(self, ref_id: ServerPlanRefId, *, source_ref: ServerPlanRefId) -> None:
        super().__init__(ServerPlanRefId(ref_id), False)
        self._source_ref = str(source_ref)

    def dependencies(self) -> frozenset[str]:
        return frozenset({self._source_ref})

    def declares_consumed_rows_reduction(self) -> bool:
        return True

    def always_publishes_executor_visible_binding(self) -> bool:
        return True

    def cte_publication_contract(self: TruthyOptionalRowStep) -> CtePublicationContract:
        columns = ("__exists",)
        column_type_hints = SqlColumnTypeHints(bool_columns=frozenset({"__exists"}))
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        _contract_model_cls = _TruthyOptionalRowStepCteRow
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=tuple(str(column) for column in columns),
            column_type_hints=column_type_hints,
            model_cls=_contract_model_cls,
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def compile(self, ctx: CompilationContext) -> CompiledStep[bool]:
        return sql_sequence_exists_compiled_step(
            self._source_ref,
            ctx=ctx,
            result_ref_id=str(self.ref_id),
        )

    def _is_truthy_optional_row(self, value: object) -> bool:
        return value is not None


class ResolvedLenStep(ReturnValueStep[int]):
    """Return ``len(resolved[source_ref])`` after the dependency finishes."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        source_ref: str,
        after_refs: frozenset[ServerPlanRefId] = frozenset(),
    ) -> None:
        super().__init__(ServerPlanRefId(ref_id), 0)
        self._source_ref = source_ref
        self._after_refs = after_refs

    def dependencies(self) -> frozenset[str]:
        return frozenset({self._source_ref, *(str(ref) for ref in self._after_refs)})

    def sql_visible_dependencies(self) -> frozenset[str]:
        return frozenset({self._source_ref})

    def declares_consumed_rows_reduction(self) -> bool:
        return True

    def cte_publication_contract(self) -> CtePublicationContract:
        columns = ("count",)
        hints = SqlColumnTypeHints(bigint_columns=frozenset(columns))
        return CtePublicationContract(
            columns=columns,
            column_type_hints=hints,
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            model_cls=cte_projection_row_model(
                f"{type(self).__name__}CteRow",
                columns,
                hints,
            ),
            relation_role=self.cte_relation_role(),
        )

    def compile(self, ctx: CompilationContext) -> CompiledStep[int]:
        return sql_count_sequence_items_compiled_step(
            self._source_ref,
            ctx=ctx,
            result_ref_id=str(self.ref_id),
        )

