def _large_column_pointer_db_column(column_name: SqlColumnName) -> str:
    return str(large_column_pointer_name(ContentColumnName(column_name)))


def _model_large_column_pointer_db_column(
    model_cls: type[DatabaseObjectRow],
    column_name: SqlColumnName,
) -> str:
    pointer_field = _large_column_pointer_db_column(column_name)
    if pointer_field in model_cls.model_fields:
        return str(get_db_column_name(model_cls, DynamicFieldName(pointer_field)))
    return pointer_field


def _large_column_pointer_fields(model_cls: type[DatabaseObjectRow]) -> frozenset[str]:
    return frozenset(
        _model_large_column_pointer_db_column(model_cls, SqlColumnName(config.column)) for config in get_large_column_configs(model_cls)
    )


def _model_field_db_column(model_cls: type[DatabaseObjectRow], field_name: str) -> str:
    if field_name in _large_column_pointer_fields(model_cls):
        return field_name
    return str(get_db_column_name(model_cls, DynamicFieldName(field_name)))


def should_use_spill_aware_read(
    model_cls: type[DatabaseObjectRow],
    query_spec: QuerySpec[Any],
) -> bool:
    """Return whether a query can be lowered via spill-aware read steps."""
    if not get_large_column_configs(model_cls):
        return False
    if query_spec.select_columns is not None:
        return False
    if query_spec.defer_large_columns:
        return False
    if getattr(query_spec, "joins", None):
        return False
    return is_simple_query_spec(query_spec)


def should_lower_spill_read(
    *,
    ctx: LoweringContext,
    model_cls: type[DatabaseObjectRow],
    query_spec: QuerySpec[Any] | None,
    raw_mode: bool,
    versioned: bool,
) -> bool:
    del ctx, versioned
    if raw_mode:
        return False
    if query_spec is None:
        return False
    return should_use_spill_aware_read(model_cls, query_spec)


