@dataclass(frozen=True, slots=True)
class LargeColumnRefOwnership:
    """Explicit raw/hydrated/scalar refs owned by a public large-column result ref."""

    public_ref: ServerPlanRefId
    raw_ref: ServerPlanRefId
    hydrated_ref: ServerPlanRefId
    scalar_refs: Mapping[str, ServerPlanRefId]

    def scalar_ref_for_field(self, field_name: str) -> ServerPlanRefId | None:
        return self.scalar_refs.get(field_name)


_LARGE_COLUMN_OWNERSHIP_CACHE_KEY = "large_column_ref_ownership"


def _large_column_field_names(model_cls: type[DatabaseObjectRow]) -> tuple[str, ...]:
    return tuple(config.column for config in get_large_column_configs(model_cls))


def make_large_column_ref_ownership(
    public_ref: ServerPlanRefId | str,
    model_cls: type[DatabaseObjectRow],
) -> LargeColumnRefOwnership:
    public = ServerPlanRefId(public_ref)
    raw = ServerPlanRefId(f"{public}.raw")
    hydrated = ServerPlanRefId(f"{public}.hydrated")
    return LargeColumnRefOwnership(
        public_ref=public,
        raw_ref=raw,
        hydrated_ref=hydrated,
        scalar_refs={field_name: ServerPlanRefId(f"{hydrated}.{field_name}") for field_name in _large_column_field_names(model_cls)},
    )


def _ownership_cache(ctx: LoweringContext) -> dict[str, LargeColumnRefOwnership]:
    cache = ctx._lowering_cache.setdefault(_LARGE_COLUMN_OWNERSHIP_CACHE_KEY, {})
    return cast("dict[str, LargeColumnRefOwnership]", cache)


def register_large_column_ref_ownership(
    ctx: LoweringContext,
    ownership: LargeColumnRefOwnership,
    *,
    aliases: Sequence[ServerPlanRefId | str] = (),
) -> None:
    cache = _ownership_cache(ctx)
    cache[str(ownership.public_ref)] = ownership
    for alias in aliases:
        cache[str(alias)] = ownership


def get_large_column_ref_ownership(
    ctx: LoweringContext,
    ref_id: ServerPlanRefId | str,
) -> LargeColumnRefOwnership | None:
    if not hasattr(ctx, "_lowering_cache"):
        return None
    return _ownership_cache(ctx).get(str(ref_id))


def attach_large_column_ref_ownership(
    steps: Sequence[ServerPlanStep[Any]],
    ownership: LargeColumnRefOwnership,
) -> None:
    for step in steps:
        existing = tuple(getattr(step, "_large_column_ref_ownership", ()))
        object.__setattr__(step, "_large_column_ref_ownership", (*existing, ownership))


def large_column_ref_ownership_for_steps(
    steps: Sequence[ServerPlanStep[Any]],
    ref_id: ServerPlanRefId | str,
) -> LargeColumnRefOwnership | None:
    ref_text = str(ref_id)
    for step in steps:
        for ownership in tuple(getattr(step, "_large_column_ref_ownership", ())):
            if isinstance(ownership, LargeColumnRefOwnership) and str(ownership.public_ref) == ref_text:
                return ownership
    return None


def reexport_large_column_ref_ownership(
    step: ServerPlanStep[Any],
    source: LargeColumnRefOwnership,
) -> LargeColumnRefOwnership:
    """Return the ownership contract that a passthrough wrapper republishes."""
    del step
    return source


def lower_spill_aware_query_read_steps(
    ref_id: ServerPlanRefId,
    model_cls: type[DatabaseObjectRow],
    query_spec: QuerySpec[Any],
    *,
    result_mode: Literal["many", "first", "strict_one"] = "many",
    user_id_ref_id: ServerPlanRefId | None = None,
) -> list[ServerPlanStep[Any]]:
    """Lower a large-column read into explicit SQL acquisition and hydration refs."""
    typed_ref_id = ServerPlanRefId(ref_id)
    raw_ref_id = ServerPlanRefId(f"{ref_id}.raw")
    target_query_spec = query_spec
    if result_mode == "first":
        if query_spec.limit is None:
            target_query_spec = replace(query_spec, limit=1)
    elif result_mode == "strict_one":
        target_limit = 2
        if query_spec.limit is None or query_spec.limit == 1 or query_spec.limit > target_limit:
            target_query_spec = replace(query_spec, limit=target_limit)
    target_query_spec = replace(target_query_spec, defer_large_columns=True)

    from impl.common.l2070_server_plan.steps.collect_results import (
        AllowMissingRuntimeSource,
        RuntimeSourceAfterDepsStep,
        RuntimeSourceSequenceValue,
    )
    from impl.common.l2070_server_plan.steps.query_execute import _QueryExecuteStepConfig
    from impl.common.l2070_server_plan.steps.row_hydration import (
        HydrateResolvedRowsStep,
        HydrateFirstResolvedRowStep,
        HydrateStrictFirstResolvedRowStep,
    )

    ownership = make_large_column_ref_ownership(typed_ref_id, model_cls)
    raw_step = QueryExecuteStep(
        raw_ref_id,
        model_cls,
        _QueryExecuteStepConfig(
            query_spec=target_query_spec,
            raw_mode=True,
            user_id_ref_id=user_id_ref_id,
            force_hydrate_large_columns=True,
        ),
    )
    if result_mode == "first":
        hydration_step: ServerPlanStep[Any] = HydrateFirstResolvedRowStep(
            ownership.hydrated_ref,
            source_ref=raw_ref_id,
            model_cls=model_cls,
        )
        sequence_value = RuntimeSourceSequenceValue(False)
    elif result_mode == "strict_one":
        hydration_step = HydrateStrictFirstResolvedRowStep(
            ownership.hydrated_ref,
            source_ref=raw_ref_id,
            model_cls=model_cls,
            include_deleted=False,
        )
        sequence_value = RuntimeSourceSequenceValue(False)
    else:
        hydration_step = HydrateResolvedRowsStep(
            ownership.hydrated_ref,
            source_ref=raw_ref_id,
            model_cls=model_cls,
        )
        sequence_value = RuntimeSourceSequenceValue(True)
    public_step = RuntimeSourceAfterDepsStep[Any](
        typed_ref_id,
        source_ref=ownership.hydrated_ref,
        after_refs=(),
        sequence_value=sequence_value,
        allow_missing_source=AllowMissingRuntimeSource(result_mode != "many"),
    )
    steps = cast("list[ServerPlanStep[Any]]", [raw_step, hydration_step, public_step])
    attach_large_column_ref_ownership(steps, ownership)
    return steps


def lower_spill_read_for_backend(
    *,
    ctx: LoweringContext,
    ref_id: ServerPlanRefId,
    model_cls: type[DatabaseObjectRow],
    query_spec: QuerySpec[Any],
    result_mode: Literal["many", "first", "strict_one"] = "many",
    versioned: bool = False,
    raw_step: ServerPlanStep[Any] | None = None,
    user_id_ref_id: ServerPlanRefId | None = None,
) -> list[ServerPlanStep[Any]]:
    """Lower spill-aware reads at lower time or fail early on unsupported backends."""
    if not should_lower_spill_read(
        ctx=ctx,
        model_cls=model_cls,
        query_spec=query_spec,
        raw_mode=False,
        versioned=versioned,
    ):
        public_ref = ServerPlanRefId(ref_id)
        register_large_column_ref_ownership(
            ctx,
            LargeColumnRefOwnership(
                public_ref=public_ref,
                raw_ref=public_ref,
                hydrated_ref=public_ref,
                scalar_refs={
                    field_name: ServerPlanRefId(f"{public_ref}.{field_name}") for field_name in _large_column_field_names(model_cls)
                },
            ),
        )
        return []
    if versioned:
        if raw_step is None:
            msg = "versioned spill-aware lowering requires raw_step"
            raise TypeError(msg)
        from impl.common.l2070_server_plan.steps.versioned_select_one import (
            lower_versioned_spill_aware_select_one_steps,
        )

        public_ref = ServerPlanRefId(ref_id)
        steps = list(
            lower_versioned_spill_aware_select_one_steps(
                ctx=ctx,
                ref_id=public_ref,
                model_cls=model_cls,
                query_spec=query_spec,
                raw_step=raw_step,
            ),
        )
        ownership = LargeColumnRefOwnership(
            public_ref=public_ref,
            raw_ref=ServerPlanRefId(f"{public_ref}.raw_rows"),
            hydrated_ref=public_ref,
            scalar_refs={
                field_name: ServerPlanRefId(f"{public_ref}.{field_name}") for field_name in _large_column_field_names(model_cls)
            },
        )
        register_large_column_ref_ownership(
            ctx,
            ownership,
            aliases=(ownership.raw_ref, ServerPlanRefId(f"{public_ref}.raw_select")),
        )
        attach_large_column_ref_ownership(steps, ownership)
        return steps
    steps = lower_spill_aware_query_read_steps(
        ref_id,
        model_cls,
        query_spec,
        result_mode=result_mode,
        user_id_ref_id=user_id_ref_id,
    )
    register_large_column_ref_ownership(
        ctx,
        make_large_column_ref_ownership(ServerPlanRefId(ref_id), model_cls),
    )
    return steps


