@pure_lazy
def _inline_suffix_hint_kinds(config: LargeColumnConfig) -> tuple[tuple[str, str], ...]:
    if config.delta_storage is None or not config.delta_storage.enabled:
        return _INLINE_SUFFIX_HINT_KINDS
    return _INLINE_SUFFIX_HINT_KINDS + _DELTA_INLINE_SUFFIX_HINT_KINDS


@pure_lazy
def inline_large_column_alias_columns(
    model_cls: type[DatabaseObjectRow],
) -> tuple[str, ...]:
    """Inline manifest alias columns published alongside a large-column model row."""
    from impl.common.l2100_sql_grammar.domain.infra.stmt_inline_large_columns import (
        inline_large_column_alias,
    )

    return tuple(
        inline_large_column_alias(SqlGrammarKind(config.column), suffix)
        for config in get_large_column_configs(model_cls)
        for suffix, _kind in _inline_suffix_hint_kinds(config)
    )


@pure_lazy
def inline_large_column_sql_column_type_hints(
    model_cls: type[DatabaseObjectRow],
) -> SqlColumnTypeHints:
    """Declared SQL type hints for the inline large-column manifest aliases."""
    from impl.common.l2100_sql_grammar.domain.infra.stmt_inline_large_columns import (
        inline_large_column_alias,
    )

    columns_by_kind: dict[str, set[str]] = defaultdict(set)
    for config in get_large_column_configs(model_cls):
        pointer_column = str(
            get_db_column_name(
                model_cls,
                DynamicFieldName(large_column_pointer_name(config.column)),
            )
        )
        columns_by_kind["text"].add(pointer_column)
        for suffix, kind in _inline_suffix_hint_kinds(config):
            alias = inline_large_column_alias(SqlGrammarKind(config.column), suffix)
            columns_by_kind[kind].add(alias)
    return SqlColumnTypeHints(
        bool_columns=frozenset(columns_by_kind["bool"]),
        integer_columns=frozenset(columns_by_kind["integer"]),
        text_columns=frozenset(columns_by_kind["text"]),
        bytea_columns=frozenset(columns_by_kind["bytea"]),
    )


def wrap_compiled_sql_with_inline_large_columns(
    compiled: CompiledStep[Any],
    *,
    model_cls: type[DatabaseObjectRow],
    force_inline: bool = False,
    include_pointer_columns: bool = True,
    include_internal_sparse_columns: bool = False,
) -> CompiledStep[Any]:
    """Wrap a compiled SQL step so spilled large-column data arrives inline."""
    large_configs = get_large_column_configs(model_cls)
    if compiled.grammar is None or not large_configs:
        return compiled

    sql_ir = compiled.materialize_ir()
    assert sql_ir is not None
    source_output_shape = compiled.output_shape or sql_ir.output_shape
    from impl.common.l2100_sql_grammar.domain.query.stmt_dynamic import SqlDynamicSelectStmt

    grammar_already_inline = _grammar_has_inline_large_column_select(compiled.grammar)
    if isinstance(compiled.grammar, SqlDynamicSelectStmt) and compiled.grammar.selected_columns is not None:
        projected_columns = {str(column) for column in compiled.grammar.selected_columns}
        grammar_already_inline = grammar_already_inline or set(inline_large_column_alias_columns(model_cls)) <= projected_columns
    from impl.common.l2100_sql_grammar.domain.versioning.stmt_conditional_gate import (
        SqlGatedWhere,
    )

    gated_shape_is_inline = isinstance(compiled.grammar, SqlGatedWhere) and _output_shape_has_inline_large_columns(
        source_output_shape,
        model_cls,
    )
    if grammar_already_inline or gated_shape_is_inline:
        return compiled
    if not force_inline and not _output_shape_requests_large_columns(source_output_shape, model_cls):
        return compiled
    if source_output_shape is None and compiled.column_type_hints is not None:
        from l2070_batching.publication import hinted_columns

        hinted = hinted_columns(compiled.column_type_hints)
        has_pointer_hint = False
        for config in get_large_column_configs(model_cls):
            pointer_name = large_column_pointer_name(config.column)
            if {pointer_name, _model_large_column_pointer_db_column(model_cls, SqlColumnName(config.column))}.intersection(hinted):
                has_pointer_hint = True
                break
        if not has_pointer_hint:
            return compiled
    if source_output_shape is None:
        return compiled
    if not force_inline and not _output_shape_has_large_column_pointer(source_output_shape, model_cls):
        return compiled

    def _model_output_shape() -> CompiledOutputShape:
        return CompiledOutputShape(
            tuple(
                synthetic_output_field(
                    field_name,
                    _model_field_db_column(model_cls, field_name),
                )
                for field_name in model_cls.model_fields
            ),
        )

    from impl.common.l2050_sql_types.sql_branded_types import SqlAliasName, SqlGrammarKind
    from impl.common.l2100_sql_grammar.domain.infra.stmt_inline_large_columns import (
        SqlInlineLargeColumnSelect,
        inline_large_column_alias,
    )
    from impl.common.l2100_sql_grammar.tree.enums import ProjectionKind, TableExprKind
    from impl.common.l2100_sql_grammar.tree.projections import SqlProjectionItem
    from impl.common.l2100_sql_grammar.tree.statements import SqlSelect
    from impl.common.l2100_sql_grammar.tree.statements import SqlCte
    from impl.common.l2100_sql_grammar.tree.table_expr import SqlTableExpr

    declared_source_output_shape = source_output_shape or _model_output_shape()

    def _inline_source(
        grammar: SqlRenderable,
        available_columns: Sequence[SqlColumnName] | None = None,
    ) -> SqlInlineLargeColumnSelect:
        source_columns = {
            str(column)
            for column in (available_columns if available_columns is not None else declared_source_output_shape.cte_output_columns)
        }
        pointer_column_overrides: list[tuple[SqlGrammarKind, SqlColumnName]] = []
        for config in get_large_column_configs(model_cls):
            pointer_field = large_column_pointer_name(config.column)
            pointer_db_column = str(get_db_column_name(model_cls, DynamicFieldName(pointer_field)))
            if pointer_db_column not in source_columns and pointer_field in source_columns:
                pointer_column_overrides.append(
                    (SqlGrammarKind(config.column), SqlColumnName(pointer_field)),
                )
        return SqlInlineLargeColumnSelect(
            grammar,
            model_cls,
            pointer_column_overrides=tuple(pointer_column_overrides),
            available_source_columns=frozenset(SqlColumnName(column) for column in source_columns),
        )

    output_shape = _inline_large_column_output_shape(
        declared_source_output_shape,
        model_cls,
        include_pointer_columns=include_pointer_columns and not grammar_already_inline,
        include_internal_sparse_columns=include_internal_sparse_columns,
    )
    assert output_shape is not None

    def _large_column_projection_columns(
        existing_columns: Sequence[SqlColumnName],
        *,
        include_pointer: bool = True,
    ) -> list[SqlColumnName]:
        pointer_columns = {
            str(get_db_column_name(model_cls, DynamicFieldName(large_column_pointer_name(config.column))))
            for config in get_large_column_configs(model_cls)
        }
        existing_names = tuple(str(column) for column in existing_columns if include_pointer or str(column) not in pointer_columns)
        available_names = set(existing_names)
        for column in output_shape.cte_output_columns:
            if column.startswith("__nera_inline_large_column__"):
                available_names.add(column)
            elif include_pointer and column in pointer_columns:
                available_names.add(column)
        ordered_names = [column for column in output_shape.cte_output_columns if column in available_names]
        ordered_names.extend(column for column in existing_names if column not in output_shape.cte_output_columns)
        return [SqlColumnName(column) for column in dict.fromkeys(ordered_names)]

    def _final_projection_parts(
        grammar: SqlRenderable,
    ) -> tuple[SqlRenderable, tuple[SqlColumnName, ...], SqlAliasName] | None:
        if not isinstance(grammar, SqlSelect):
            return None
        from_ = getattr(grammar, "_from", None)
        if not isinstance(from_, SqlTableExpr) or from_._kind != TableExprKind.SUBQUERY:
            return None
        if from_._source is None or from_._alias is None:
            return None
        select_list = getattr(grammar, "_select_list", None)
        items = getattr(select_list, "_items", None)
        if items is None:
            return None
        columns: list[SqlColumnName] = []
        for item in items:
            expr = item._expr if isinstance(item, SqlProjectionItem) else item
            if isinstance(item, SqlProjectionItem) and item._kind != ProjectionKind.EXPR:
                return None
            column_name = getattr(expr, "_name", None)
            if column_name is None:
                return None
            columns.append(SqlColumnName(column_name))
        if not columns:
            return None
        return from_._source, tuple(columns), from_._alias

    def _wrap_final_projection(grammar: SqlRenderable) -> SqlRenderable | None:
        parts = _final_projection_parts(grammar)
        if parts is None:
            return None
        inner, columns, _source_alias = parts
        from impl.common.l2100_sql_grammar.domain.query.stmt_dynamic import (
            SqlFinalProjectionSelect,
        )

        framework_columns = {
            "__exists",
            "branch_id",
            "sys_deleted",
            "sys_revision_id",
            "sys_valid_from_revision_id",
            "sys_valid_to_revision_id",
        }
        declared_projection_names = {str(column) for column in columns}
        implicit_framework_columns: tuple[SqlColumnName, ...] = ()
        if "branch_id" in declared_projection_names and "sys_deleted" not in declared_projection_names:
            implicit_framework_columns = (SqlColumnName("sys_deleted"),)
        projection_columns = tuple(
            dict.fromkeys(
                (
                    *columns,
                    *implicit_framework_columns,
                    *(SqlColumnName(column) for column in output_shape.cte_output_columns if column in framework_columns),
                ),
            ),
        )
        if is_versioned_object_model(model_cls):
            source_columns = tuple(column for column in columns if not str(column).startswith("__nera_inline_large_column__"))
            inline_source = _inline_source(inner, source_columns)
        else:
            inline_source = _inline_source(grammar, columns)
        return SqlFinalProjectionSelect(
            inline_source,
            _large_column_projection_columns(
                projection_columns,
                include_pointer=include_pointer_columns,
            ),
        )

    def _wrap_with_declared_projection(grammar: SqlRenderable) -> SqlRenderable:
        from impl.common.l2100_sql_grammar.domain.query.stmt_dynamic import (
            SqlFinalProjectionSelect,
        )

        projection_names = output_shape.cte_output_columns
        if "branch_id" in projection_names and "sys_deleted" not in projection_names:
            projection_names = (*projection_names, "sys_deleted")
        projection_columns = tuple(SqlColumnName(column) for column in projection_names)
        if is_versioned_object_model(model_cls):
            source_columns = tuple(column for column in projection_columns if not str(column).startswith("__nera_inline_large_column__"))
            inline_source = _inline_source(grammar, source_columns)
        else:
            inline_source = _inline_source(grammar)
        return SqlFinalProjectionSelect(
            inline_source,
            _large_column_projection_columns(
                projection_columns,
                include_pointer=include_pointer_columns,
            ),
        )

    from l2070_batching.sql_column_type_hints import SqlColumnTypeHints, combine_sql_column_type_hints, model_sql_column_type_hints

    inline_hints = inline_large_column_sql_column_type_hints(model_cls)
    output_columns = output_shape.cte_output_columns
    output_column_set = set(output_columns)
    compiled_hints = compiled.column_type_hints.filtered(output_column_set) if compiled.column_type_hints is not None else None
    model_hints = model_sql_column_type_hints(model_cls, output_columns)
    search_meta_hints = SqlColumnTypeHints(
        double_columns=frozenset(
            column
            for column in (
                "_fts_rank",
                "__fts_rank",
                "_vector_score",
                "__vector_score",
                "_vector_distance",
                "__vector_distance",
                "_rrf_score",
                "__rrf_score",
            )
            if column in output_column_set
        ),
        integer_columns=frozenset(
            column
            for column in (
                "_fts_rrf_rank",
                "__fts_rrf_rank",
                "_vector_rrf_rank",
                "__vector_rrf_rank",
            )
            if column in output_column_set
        ),
        text_columns=frozenset(column for column in ("_vector_distance_kind", "__vector_distance_kind") if column in output_column_set),
    )
    combined_hints = combine_sql_column_type_hints(
        output_columns,
        *tuple(
            hint
            for hint in (
                compiled_hints,
                model_hints,
                search_meta_hints,
                inline_hints.filtered(output_column_set),
            )
            if hint is not None
        ),
    ).require_complete(output_columns)

    grammar = compiled.grammar
    wrapped_grammar: SqlRenderable
    if grammar_already_inline:
        from impl.common.l2100_sql_grammar.domain.query.stmt_dynamic import (
            SqlFinalProjectionSelect,
        )

        projection_columns = tuple(SqlColumnName(column) for column in output_shape.cte_output_columns if column != "branch_id")
        wrapped_grammar = SqlFinalProjectionSelect(
            grammar,
            _large_column_projection_columns(projection_columns, include_pointer=False),
        )
    elif isinstance(grammar, SqlCte):
        definitions, final_query = grammar.split_for_outer_cte()
        wrapped_final_query = _wrap_final_projection(final_query)
        if wrapped_final_query is not None:
            wrapped_grammar = SqlCte(
                definitions,
                wrapped_final_query,
                recursive=grammar.recursive,
            )
        else:
            wrapped_grammar = _inline_source(grammar)
    else:
        maybe_wrapped_grammar = _wrap_final_projection(grammar)
        wrapped_grammar = _wrap_with_declared_projection(grammar) if maybe_wrapped_grammar is None else maybe_wrapped_grammar
    from l2070_batching.output_shape import DeclaredResultRelation

    result_relation = DeclaredResultRelation.from_output_shape(output_shape)
    closed_post_op = compiled.closed_post_op
    if closed_post_op is not None and isinstance(closed_post_op.spec, ResultMaterializationSpec):
        closed_post_op = replace(
            closed_post_op,
            spec=replace(closed_post_op.spec, input_relation=result_relation),
        )

    return CompiledStep(
        grammar=wrapped_grammar,
        params=sql_ir.params,
        external_params_first=sql_ir.external_params_first,
        needs_returning=sql_ir.needs_returning,
        closed_post_op=closed_post_op,
        runtime_ref_ids=compiled.runtime_ref_ids,
        provenance_manifest=sql_ir.provenance_manifest,
        allow_empty_provenance_manifest=sql_ir.allow_empty_provenance_manifest,
        use_savepoint_recovery=sql_ir.use_savepoint_recovery,
        output_shape=output_shape,
        result_relation=result_relation,
        column_type_hints=combined_hints,
        auxiliary_ctes=compiled.auxiliary_ctes,
        needs_recursive_with=compiled.needs_recursive_with,
    )


def _output_shape_requests_large_columns(
    output_shape: CompiledOutputShape | None,
    model_cls: type[DatabaseObjectRow],
) -> bool:
    if output_shape is None:
        return True
    requested = {
        candidate
        for field_info in output_shape.fields
        for candidate in (
            field_info.output_name,
            field_info.output_column,
            field_info.source_db_column,
            field_info.model_field_name,
        )
        if candidate is not None
    }
    requested.update(output_shape.cte_output_columns)
    from impl.common.l2100_sql_grammar.domain.infra.stmt_inline_large_columns import (
        inline_large_column_alias,
    )

    for config in get_large_column_configs(model_cls):
        pointer_name = large_column_pointer_name(config.column)
        if {
            config.column,
            get_db_column_name(model_cls, DynamicFieldName(config.column)),
            pointer_name,
            _model_large_column_pointer_db_column(model_cls, SqlColumnName(config.column)),
        }.intersection(requested):
            return True
        for suffix, _kind in _inline_suffix_hint_kinds(config):
            if inline_large_column_alias(SqlGrammarKind(config.column), suffix) in requested:
                return True
    return False


def _grammar_has_inline_large_column_select(grammar: SqlRenderable | None) -> bool:
    if grammar is None:
        return False
    from impl.common.l2100_sql_grammar.domain.infra.stmt_inline_large_columns import (
        SqlInlineLargeColumnSelect,
    )

    if isinstance(grammar, SqlInlineLargeColumnSelect):
        return True
    for attr_name in (
        "_inner",
        "inner",
        "_with",
        "_final_query",
        "_source",
        "_from",
        "_from_clause",
        "_table",
        "_query",
        "query",
        "_expr",
        "_select",
        "_select_list",
    ):
        child = getattr(grammar, attr_name, None)
        if _grammar_has_inline_large_column_select(child):
            return True
    for attr_name in ("_definitions", "_items"):
        children = getattr(grammar, attr_name, None)
        if children is None:
            continue
        if isinstance(children, dict):
            iterable = children.values()
        else:
            iterable = children
        for child in iterable:
            if isinstance(child, tuple):
                if any(_grammar_has_inline_large_column_select(part) for part in child):
                    return True
            elif _grammar_has_inline_large_column_select(child):
                return True
    return False


