def _inline_large_column_output_shape(
    output_shape: CompiledOutputShape | None,
    model_cls: type[DatabaseObjectRow],
    *,
    include_pointer_columns: bool = True,
    include_internal_sparse_columns: bool = False,
) -> CompiledOutputShape | None:
    """Add inline large-column payload aliases to a compiled output shape."""
    if output_shape is None:
        return None
    from impl.common.l2100_sql_grammar.domain.infra.stmt_inline_large_columns import (
        inline_large_column_alias,
    )

    model_columns = {
        candidate
        for field_name in model_cls.model_fields
        for candidate in (field_name, str(get_db_column_name(model_cls, DynamicFieldName(field_name))))
    }
    pointer_columns = {
        pointer_column
        for config in get_large_column_configs(model_cls)
        for pointer_column in (
            large_column_pointer_name(config.column),
            _model_large_column_pointer_db_column(model_cls, SqlColumnName(config.column)),
        )
    }
    model_columns = {
        candidate for field_name in model_cls.model_fields for candidate in (field_name, _model_field_db_column(model_cls, field_name))
    }
    internal_sparse_columns = frozenset() if include_internal_sparse_columns else frozenset({"branch_id"} - model_columns)
    source_output_columns = set(output_shape.cte_output_columns)
    prefers_logical_pointer_aliases = is_versioned_object_model(model_cls)
    inline_fields_by_pointer: dict[str, tuple[Any, ...]] = {}
    pointer_identity_by_column: dict[str, str] = {}
    for config in get_large_column_configs(model_cls):
        pointer_name = large_column_pointer_name(config.column)
        pointer_db_column = str(get_db_column_name(model_cls, DynamicFieldName(pointer_name)))
        fields: list[Any] = []
        if include_pointer_columns:
            pointer_output_column = (
                pointer_name if prefers_logical_pointer_aliases and pointer_name in source_output_columns else pointer_db_column
            )
            fields.append(
                synthetic_output_field(
                    pointer_name,
                    pointer_output_column,
                    role="large_column_pointer",
                ),
            )
        for suffix, _kind in _inline_suffix_hint_kinds(config):
            alias = inline_large_column_alias(SqlGrammarKind(config.column), suffix)
            fields.append(
                synthetic_output_field(
                    alias,
                    is_binary=suffix == "payload",
                    role="large_column_payload",
                ),
            )
        inline_fields_by_pointer[pointer_name] = tuple(fields)
        inline_fields_by_pointer[pointer_db_column] = tuple(fields)
        pointer_identity_by_column[pointer_name] = pointer_name
        pointer_identity_by_column[pointer_db_column] = pointer_name

    fields = []
    emitted_pointers: set[str] = set()
    for field in output_shape.fields:
        output_column = str(field.output_column)
        output_name = str(field.output_name)
        if output_column in internal_sparse_columns or output_name in internal_sparse_columns:
            continue
        pointer_key = output_column if output_column in pointer_columns else output_name
        if pointer_key in pointer_columns:
            pointer_identity = pointer_identity_by_column[pointer_key]
            if pointer_identity not in emitted_pointers:
                pointer_fields = inline_fields_by_pointer[pointer_key]
                if include_pointer_columns:
                    fields.append(pointer_fields[0])
                emitted_pointers.add(pointer_identity)
            continue
        fields.append(field)
    for config in get_large_column_configs(model_cls):
        pointer_identity = str(large_column_pointer_name(config.column))
        if pointer_identity not in emitted_pointers:
            continue
        pointer_fields = inline_fields_by_pointer[pointer_identity]
        fields.extend(pointer_fields[1:] if include_pointer_columns else pointer_fields)
    return CompiledOutputShape(tuple(fields))


def build_select_one_query_spec(
    model_cls: type[DatabaseObjectRow],
    *,
    sys_id: object,
    permission_grammar: object,
    permission_state_override: QueryPermissionState | None = None,
    permission_context_ref: ServerPlanRefId | None = None,
    permission_context_type: type[ResolvedSessionContext] | None = None,
    planning_catalog: PlanningCatalog | None = None,
) -> QuerySpec[DatabaseObjectRow]:
    """Build a simple full-row QuerySpec for select-one reads."""
    from l1000_schema.table_utils import get_table_name
    from l1050_polymorphism.type_registry import is_polymorphic_class
    from l2070_batching.planning_catalog import READ_FLAVOR_QUERY_ROWS

    if get_table_name(model_cls) == "sys_polymorphic_types":
        unwrap_to_str = getattr(sys_id, "unwrap_to_str", None)
        if callable(unwrap_to_str):
            sys_id = unwrap_to_str()
        sys_id_filter = QueryFilter(column="sys_id", operator="=", value=sys_id)
    else:
        sys_id_field: Any = field(model_cls.sys_id)  # pyright: ignore[reportGeneralTypeIssues]
        from l2070_batching.server_ref import ServerRef, ServerRefs

        if isinstance(sys_id, ServerRef) and sys_id.ref_id is not None:
            source_values = ServerRefs.from_ref_id(
                ServerPlanRefId(sys_id.ref_id),
                variant="scalar_sequence",
                type_hint=SysId,
            )
            sys_id_filter = QueryFilter(
                expression=Expression(
                    field="sys_id",
                    operator="IN",
                    value=source_values,
                    left=sys_id_field,
                    right=cast(Any, source_values),
                ),
            )
        else:
            sys_id_filter = QueryFilter(expression=sys_id_field == cast(SysId, sys_id))
    if permission_state_override is not None:
        permission_state = permission_state_override
        grammar = None if permission_state is QueryPermissionState.BYPASS else permission_grammar
    else:
        grammar = permission_grammar
        permission_state = QueryPermissionState.ATTACHED if grammar is not None else QueryPermissionState.AUTO
    return QuerySpec(
        model_cls=model_cls,
        select_columns=None,
        distinct=False,
        joins=[],
        filters=[sys_id_filter],
        default_projection_columns=(
            None
            if planning_catalog is None or not is_polymorphic_class(model_cls)
            else tuple(
                SqlColumnName(column)
                for column in planning_catalog.read_metadata_for_model(model_cls)
                .projection_for(READ_FLAVOR_QUERY_ROWS)
                .cte_output_columns
            )
        ),
        order_by=[],
        limit=1,
        offset=None,
        group_by=[],
        aggregations=[],
        having=[],
        window_functions=[],
        permission_state=permission_state,
        permission_grammar=grammar,
        permission_context_ref=permission_context_ref,
        permission_context_type=permission_context_type,
    )


def _extract_content_hashes(
    model_cls: type[DatabaseObjectRow],
    raw_rows: Sequence[dict[str, Any] | Any],
) -> list[str]:
    hashes: list[str] = []
    seen: set[str] = set()
    for raw_row in raw_rows:
        row = raw_row if isinstance(raw_row, dict) else dict(raw_row)
        for config in get_large_column_configs(model_cls):
            pointer_column = _model_large_column_pointer_db_column(model_cls, SqlColumnName(config.column))
            value_column = str(get_db_column_name(model_cls, DynamicFieldName(config.column)))
            pointer = row.get(pointer_column)
            if not isinstance(pointer, str) or not pointer:
                continue
            if row.get(value_column) is not None:
                continue
            if pointer in seen:
                continue
            seen.add(pointer)
            hashes.append(pointer)
    return hashes


