def _content_store_table_name(model_cls: type[DatabaseObjectRow]) -> str:
    configs = get_large_column_configs(model_cls)
    for config in configs:
        source_model = getattr(config, "source_versioned_model", None)
        if source_model is not None:
            return f"{get_table_name(source_model)}_content_store"
    return f"{get_table_name(model_cls)}_content_store"


def _content_store_chunk_table_name(model_cls: type[DatabaseObjectRow]) -> str:
    return f"{_content_store_table_name(model_cls)}_chunks"


def _compile_content_store_table_name(table_name: SqlTableName, ctx: CompilationContext) -> str:
    has_tight_identifier_limit = (
        ctx.backend_profile.traits.content_store_identifier_transport is ContentStoreIdentifierTransport.SHORT_HASHED
    )
    if not has_tight_identifier_limit:
        return table_name
    max_identifier_length = ctx.backend_profile.traits.content_store_identifier_max_length
    if max_identifier_length is None:
        msg = "Short-hashed content-store transport requires an identifier length limit."
        raise TypeError(msg)
    max_base_length = max_identifier_length - len("_chunks")
    if len(table_name.encode()) <= max_base_length:
        return table_name
    digest = hashlib.sha1(table_name.encode("utf-8")).hexdigest()[:12]
    prefix_bytes = table_name.encode()[: max_base_length - len(digest) - 1]
    return f"{prefix_bytes.decode(errors='ignore')}_{digest}"


def _coerce_int(value: object) -> int:
    if isinstance(value, bool):
        return int(value)
    if isinstance(value, int):
        return value
    if isinstance(value, str):
        return int(value)
    msg = f"Expected integer-compatible value, got {type(value).__name__}"
    raise TypeError(msg)


def _coerce_bytes(value: object) -> bytes:
    if isinstance(value, bytes):
        return value
    if isinstance(value, bytearray):
        return bytes(value)
    if isinstance(value, memoryview):
        return value.tobytes()
    msg = f"Expected bytes-compatible payload, got {type(value).__name__}"
    raise TypeError(msg)


def _coerce_inline_bytes(value: object) -> bytes:
    if value is None:
        return b""
    if isinstance(value, bytes | bytearray | memoryview):
        return _coerce_bytes(value)
    if isinstance(value, str):
        normalized = value[2:] if value.startswith("\\x") else value
        if normalized and len(normalized) % 2 == 0:
            with suppress(ValueError):
                return bytes.fromhex(normalized)
        with suppress(ValueError):
            return base64.b64decode(value, validate=True)
    msg = f"Expected inline large-column bytes, got {type(value).__name__}"
    raise TypeError(msg)


def _decode_large_column_payload(
    *,
    content_hash: str,
    config_content_type: str,
    is_binary: bool,
    stored_content: bytes,
    compression_algorithm: str,
    compression_level: int,
    original_size: int,
) -> bytes | str:
    payload = stored_content
    storage_format = CompressionStorageFormat(compression_algorithm)
    if storage_format is CompressionStorageFormat.CHUNKED_ZSTD:
        if len(payload) != original_size:
            msg = f"Chunked compressed content size mismatch for {content_hash}: expected {original_size}, got {len(payload)}"
            raise ValueError(msg)
        if hashlib.sha256(payload).hexdigest() != content_hash:
            raise ValueError(f"Chunked compressed content hash mismatch for {content_hash}")
    elif storage_format is not CompressionStorageFormat.NONE and original_size > 0:
        metadata = CompressionMetadata(
            algorithm=CompressionAlgorithm(storage_format.value),
            compression_level=compression_level,
            original_size=original_size,
            compressed_size=len(stored_content),
        )
        payload = decompress(stored_content, metadata)
    if config_content_type == "binary" or is_binary:
        return payload
    return payload.decode("utf-8")


def decode_large_column_payload(
    *,
    content_hash: str,
    config_content_type: str,
    is_binary: bool,
    stored_content: bytes,
    compression_algorithm: str,
    compression_level: int,
    original_size: int,
) -> bytes | str:
    """Decode a stored large-column payload, including optional decompression."""
    return _decode_large_column_payload(
        content_hash=content_hash,
        config_content_type=config_content_type,
        is_binary=is_binary,
        stored_content=stored_content,
        compression_algorithm=compression_algorithm,
        compression_level=compression_level,
        original_size=original_size,
    )


def _inline_large_column_alias(column_name: SqlColumnName, suffix: str) -> str:
    from impl.common.l2100_sql_grammar.domain.infra.stmt_inline_large_columns import (
        inline_large_column_alias,
    )

    alias: str = inline_large_column_alias(SqlGrammarKind(column_name), suffix)
    return alias


def _pop_inline_large_column_keys(row: dict[str, Any], column_name: SqlColumnName) -> None:
    row.pop(f"__nera_inline_large_column__{column_name}", None)
    for suffix in (
        "content_hash",
        "payload",
        "total_chunks",
        "is_binary",
        "compression_algorithm",
        "compression_level",
        "original_size",
        "chunk_payloads_hex",
        "chunk_hashes",
        "chunk_storage_backends",
        "delta_original_size",
        "delta_content_hash_short",
        "delta_content_hash_high",
        "delta_chunk_payloads_hex",
        "delta_chunk_lengths",
        "delta_chunk_hash_shorts",
        "delta_chunk_hash_highs",
    ):
        row.pop(_inline_large_column_alias(column_name, suffix), None)


def _coerce_row_mapping(raw_row: dict[str, Any] | Any) -> dict[str, Any]:
    if isinstance(raw_row, dict):
        return dict(raw_row)
    keys = getattr(raw_row, "keys", None)
    if callable(keys):
        key_values = keys()
        if not isinstance(key_values, Iterable):
            raise TypeError("Row keys() must return an iterable")
        key_names = [str(key) for key in key_values]
        backend_row = getattr(raw_row, "row", None)
        if backend_row is not None:
            try:
                return {key: backend_row[index] for index, key in enumerate(key_names)}
            except (IndexError, KeyError, TypeError):
                pass
        return {key: raw_row[key] for key in key_names}
    items = getattr(raw_row, "items", None)
    if callable(items):
        item_values = items()
        if not isinstance(item_values, Iterable):
            raise TypeError("Row items() must return an iterable")
        normalized: dict[str, Any] = {}
        for item in item_values:
            if not isinstance(item, tuple) or len(item) != 2:
                raise TypeError("Row items() must yield key-value pairs")
            key, value = item
            normalized[str(key)] = value
        return normalized
    return dict(raw_row)


def _hydrate_inline_large_column_rows(
    model_cls: type[DatabaseObjectRow],
    raw_rows: Sequence[dict[str, Any] | Any],
    *,
    hydrate_large_columns: bool,
) -> list[dict[str, Any]]:
    if not hydrate_large_columns:
        return [_coerce_row_mapping(row) for row in raw_rows]

    hydrated_rows: list[dict[str, Any]] = []
    for raw_row in raw_rows:
        row = _coerce_row_mapping(raw_row)
        for config in get_large_column_configs(model_cls):
            column_name = config.column
            value_column = str(get_db_column_name(model_cls, DynamicFieldName(column_name)))
            pointer_name = large_column_pointer_name(ContentColumnName(column_name))
            pointer_column = _model_large_column_pointer_db_column(model_cls, SqlColumnName(column_name))
            if value_column not in row and column_name in row:
                value_column = column_name
            if pointer_column not in row and pointer_name in row:
                pointer_column = pointer_name
            content_hash_key = _inline_large_column_alias(SqlColumnName(column_name), "content_hash")
            payload_key = _inline_large_column_alias(SqlColumnName(column_name), "payload")
            bare_payload_key = f"__nera_inline_large_column__{column_name}"
            total_chunks_key = _inline_large_column_alias(SqlColumnName(column_name), "total_chunks")
            is_binary_key = _inline_large_column_alias(SqlColumnName(column_name), "is_binary")
            compression_algorithm_key = _inline_large_column_alias(SqlColumnName(column_name), "compression_algorithm")
            compression_level_key = _inline_large_column_alias(SqlColumnName(column_name), "compression_level")
            original_size_key = _inline_large_column_alias(SqlColumnName(column_name), "original_size")
            chunk_payloads_key = _inline_large_column_alias(SqlColumnName(column_name), "chunk_payloads_hex")
            chunk_hashes_key = _inline_large_column_alias(SqlColumnName(column_name), "chunk_hashes")
            chunk_backends_key = _inline_large_column_alias(SqlColumnName(column_name), "chunk_storage_backends")
            delta_original_size_key = _inline_large_column_alias(
                SqlColumnName(column_name),
                "delta_original_size",
            )
            delta_content_hash_short_key = _inline_large_column_alias(
                SqlColumnName(column_name),
                "delta_content_hash_short",
            )
            delta_content_hash_high_key = _inline_large_column_alias(
                SqlColumnName(column_name),
                "delta_content_hash_high",
            )
            delta_payloads_key = _inline_large_column_alias(
                SqlColumnName(column_name),
                "delta_chunk_payloads_hex",
            )
            delta_lengths_key = _inline_large_column_alias(
                SqlColumnName(column_name),
                "delta_chunk_lengths",
            )
            delta_hash_shorts_key = _inline_large_column_alias(
                SqlColumnName(column_name),
                "delta_chunk_hash_shorts",
            )
            delta_hash_highs_key = _inline_large_column_alias(
                SqlColumnName(column_name),
                "delta_chunk_hash_highs",
            )
            inline_payload_present = (
                row.get(payload_key) is not None
                or row.get(bare_payload_key) is not None
                or _coerce_int(row.get(total_chunks_key) or 0) > 0
                or bool(row.get(chunk_payloads_key))
                or bool(row.get(chunk_hashes_key))
                or bool(row.get(delta_payloads_key))
                or row.get(delta_original_size_key) is not None
            )
            if not inline_payload_present:
                continue
            if row.get(value_column) not in (None, ""):
                _pop_inline_large_column_keys(row, SqlColumnName(column_name))
                continue
            if config.delta_storage is not None and config.delta_storage.enabled and row.get(delta_original_size_key) is not None:
                from l1200_content_hash.content_hash import ContentHash

                expected_size = _coerce_int(row.get(delta_original_size_key) or 0)
                chunk_bytes: list[bytes] = []
                if expected_size > 0 or row.get(delta_payloads_key):
                    payload_parts = str(row[delta_payloads_key]).split(":")
                    length_parts = str(row.get(delta_lengths_key) or "").split(":")
                    short_parts = str(row.get(delta_hash_shorts_key) or "").split(":")
                    high_parts = str(row.get(delta_hash_highs_key) or "").split(":")
                    if not (len(payload_parts) == len(length_parts) == len(short_parts) == len(high_parts)):
                        msg = f"Inline delta large-column manifest length mismatch for {model_cls.__name__}.{column_name}"
                        raise ValueError(msg)
                    for ordinal, (payload_hex, length_text, short_text, high_text) in enumerate(
                        zip(
                            payload_parts,
                            length_parts,
                            short_parts,
                            high_parts,
                            strict=True,
                        ),
                    ):
                        location = f"{model_cls.__name__}.{column_name} chunk {ordinal}"
                        if not payload_hex:
                            msg = f"missing delta chunk payload for {location}"
                            raise ValueError(msg)
                        payload_bytes = bytes.fromhex(payload_hex)
                        expected_length = int(length_text)
                        if len(payload_bytes) != expected_length:
                            msg = f"delta chunk length mismatch for {location}: expected {expected_length}, got {len(payload_bytes)}"
                            raise ValueError(msg)
                        digest = ContentHash.from_sha256(hashlib.sha256(payload_bytes).digest())
                        expected_chunk_hash = (int(short_text), int(high_text))
                        if (digest.short, digest.high) != expected_chunk_hash:
                            msg = (
                                f"delta chunk hash mismatch for {location}: expected {expected_chunk_hash}, "
                                f"got {(digest.short, digest.high)}"
                            )
                            raise ValueError(msg)
                        chunk_bytes.append(payload_bytes)
                stored_content = b"".join(chunk_bytes)
                if len(stored_content) != expected_size:
                    msg = (
                        f"delta content length mismatch for {model_cls.__name__}.{column_name}: "
                        f"expected {expected_size}, got {len(stored_content)}"
                    )
                    raise ValueError(msg)
                content_digest = ContentHash.from_sha256(hashlib.sha256(stored_content).digest())
                expected_content_hash = (
                    _coerce_int(row.get(delta_content_hash_short_key)),
                    _coerce_int(row.get(delta_content_hash_high_key)),
                )
                if (content_digest.short, content_digest.high) != expected_content_hash:
                    msg = (
                        f"delta content hash mismatch for {model_cls.__name__}.{column_name}: "
                        f"expected {expected_content_hash}, got {(content_digest.short, content_digest.high)}"
                    )
                    raise ValueError(msg)
                row[value_column] = stored_content if config.content_type == "binary" else stored_content.decode("utf-8")
                _pop_inline_large_column_keys(row, SqlColumnName(column_name))
                continue
            pointer_value = row.get(pointer_column) or row.get(content_hash_key)
            total_chunks = _coerce_int(row.get(total_chunks_key) or 0)
            payload_manifest = row.get(chunk_payloads_key)
            from l1000_schema.json_type import JSONType

            if isinstance(payload_manifest, JSONType):
                payload_manifest = payload_manifest.unwrap()
            payload_values: list[str] | None = None
            if isinstance(payload_manifest, list):
                if not all(isinstance(value, str) for value in payload_manifest):
                    msg = f"Inline large-column payload manifest contains a non-string value for {model_cls.__name__}.{column_name}"
                    raise ValueError(msg)
                payload_values = payload_manifest
            elif isinstance(payload_manifest, str) and payload_manifest.startswith("["):
                try:
                    parsed_manifest = json.loads(payload_manifest)
                except json.JSONDecodeError as exc:
                    msg = f"Inline large-column payload manifest is invalid JSON for {model_cls.__name__}.{column_name}"
                    raise ValueError(msg) from exc
                if not isinstance(parsed_manifest, list) or not all(isinstance(value, str) for value in parsed_manifest):
                    msg = f"Inline large-column payload manifest must be a list of strings for {model_cls.__name__}.{column_name}"
                    raise ValueError(msg)
                payload_values = parsed_manifest
            payloads_hex = str(payload_manifest or "")
            expected_hashes = str(row.get(chunk_hashes_key) or "")
            storage_backends_raw = row.get(chunk_backends_key)
            storage_backends = storage_backends_raw if isinstance(storage_backends_raw, str) else ""
            if total_chunks == 0 and payloads_hex:
                total_chunks = len(payload_values) if payload_values is not None else len(payloads_hex.split(":"))
            if pointer_value in (None, "") and row.get(payload_key) is None and total_chunks == 0:
                _pop_inline_large_column_keys(row, SqlColumnName(column_name))
                continue
            content_hash = str(pointer_value or f"{model_cls.__name__}.{column_name}")
            if total_chunks > 0:
                if not expected_hashes or not storage_backends:
                    msg = f"Inline large-column chunk manifest omitted hash or backend metadata for {model_cls.__name__}.{column_name}"
                    raise ValueError(msg)
                payload_parts = payload_values if payload_values is not None else payloads_hex.split(":")
                hash_parts = expected_hashes.split(":")
                backend_parts = storage_backends.split(":")
                if not (len(payload_parts) == len(hash_parts) == len(backend_parts) == total_chunks):
                    msg = (
                        f"Inline large-column chunk manifest length mismatch for {model_cls.__name__}.{column_name}: "
                        f"declared={total_chunks}, payloads={len(payload_parts)}, hashes={len(hash_parts)}, "
                        f"backends={len(backend_parts)}, payload_manifest={payloads_hex[:80]!r}"
                    )
                    raise ValueError(msg)
                stored_chunks: list[dict[str, DatabaseValue]] = []
                for index, (payload_hex, expected_hash, storage_backend_hex) in enumerate(
                    zip(payload_parts, hash_parts, backend_parts, strict=True),
                ):
                    try:
                        storage_backend = bytes.fromhex(storage_backend_hex).decode("utf-8")
                        chunk_payload = (
                            base64.b64decode(payload_hex.removeprefix("b64:"), validate=True)
                            if payload_hex.startswith("b64:")
                            else bytes.fromhex(payload_hex)
                        )
                    except (UnicodeDecodeError, ValueError) as exc:
                        msg = f"Inline large-column chunk metadata is not valid encoded data for {model_cls.__name__}.{column_name} at index {index}"
                        raise ValueError(msg) from exc
                    stored_chunks.append(
                        {
                            "content_hash": content_hash,
                            "chunk_index": index,
                            "chunk_hash": expected_hash,
                            "payload": chunk_payload,
                            "storage_backend": storage_backend,
                        },
                    )
                stored_content = _reassemble_chunk_payload(
                    content_hash=content_hash,
                    total_chunks=total_chunks,
                    chunk_rows=stored_chunks,
                    compression_algorithm=str(row.get(compression_algorithm_key) or "none"),
                )
            else:
                inline_payload = row.get(payload_key, row.get(bare_payload_key))
                if inline_payload is None:
                    msg = f"Missing inline spilled content for {model_cls.__name__}.{column_name}"
                    raise ValueError(msg)
                stored_content = _coerce_inline_bytes(inline_payload)
            row[value_column] = _decode_large_column_payload(
                content_hash=content_hash,
                config_content_type=config.content_type,
                is_binary=bool(row.get(is_binary_key)),
                stored_content=stored_content,
                compression_algorithm=str(row.get(compression_algorithm_key) or "none"),
                compression_level=_coerce_int(row.get(compression_level_key) or 0),
                original_size=_coerce_int(row.get(original_size_key) or 0),
            )
            _pop_inline_large_column_keys(row, SqlColumnName(column_name))
        hydrated_rows.append(_normalize_raw_model_field_keys(model_cls, row))
    return hydrated_rows


def _normalize_raw_model_field_keys(
    model_cls: type[DatabaseObjectRow],
    row: dict[str, Any],
) -> dict[str, Any]:
    for field_name in model_cls.model_fields:
        if field_name in row:
            continue
        db_column = str(get_db_column_name(model_cls, DynamicFieldName(field_name)))
        if db_column in row:
            row[field_name] = row[db_column]
    return row


def hydrate_inline_large_column_row_dicts(
    model_cls: type[DatabaseObjectRow],
    raw_rows: Sequence[dict[str, Any] | Any],
    *,
    hydrate_large_columns: bool = True,
) -> list[dict[str, Any]]:
    """Hydrate inline large-column aliases before ordinary model hydration."""
    return _hydrate_inline_large_column_rows(
        model_cls,
        raw_rows,
        hydrate_large_columns=hydrate_large_columns,
    )


def _reassemble_chunk_payload(
    *,
    content_hash: str,
    total_chunks: int,
    chunk_rows: Sequence[DatabaseRecord],
    compression_algorithm: str = "none",
) -> bytes:
    storage_format = CompressionStorageFormat(compression_algorithm)
    sorted_chunks = sorted(chunk_rows, key=lambda row: _coerce_int(row["chunk_index"]))
    if len(sorted_chunks) != total_chunks:
        msg = f"Expected {total_chunks} chunks, found {len(sorted_chunks)} for {content_hash}"
        raise ValueError(msg)

    parts: list[bytes] = []
    for expected_index, row in enumerate(sorted_chunks):
        chunk_index = _coerce_int(row["chunk_index"])
        if chunk_index != expected_index:
            msg = f"Chunk index mismatch for {content_hash}: expected {expected_index}, got {chunk_index}"
            raise ValueError(msg)
        from impl.common.l2550_storage_backend.large_column_service import (
            StoredChunkBackendName,
            StoredChunkSha256,
            retrieve_stored_chunk,
        )

        storage_backend_raw = row.get("storage_backend")
        chunk_hash_raw = row.get("chunk_hash")
        if not isinstance(storage_backend_raw, str) or not isinstance(chunk_hash_raw, str):
            msg = f"Chunk metadata is incomplete for {content_hash} at index {chunk_index}"
            raise ValueError(msg)
        try:
            storage_backend_value = row["storage_backend"]
            chunk_hash_value = row["chunk_hash"]
            if not isinstance(storage_backend_value, str) or not isinstance(chunk_hash_value, str):
                raise ValueError("Chunk backend and SHA-256 metadata must be strings")
            chunk_payload = retrieve_stored_chunk(
                storage_backend=StoredChunkBackendName(storage_backend_value),
                chunk_sha256=StoredChunkSha256(chunk_hash_value),
                database_payload=_coerce_bytes(row["payload"]),
            )
        except (KeyError, TypeError, ValueError) as exc:
            msg = f"Large-column chunk retrieval failed for {content_hash} at index {chunk_index}: {exc}"
            raise ValueError(msg) from exc
        if storage_format is CompressionStorageFormat.CHUNKED_ZSTD:
            from impl.common.l2505_compression.algorithms import zstd

            if zstd is None:
                raise ValueError("Zstandard support is not available")
            try:
                chunk_payload = zstd.ZstdDecompressor().decompress(chunk_payload)
            except zstd.ZstdError as exc:
                msg = f"Large-column chunk decompression failed for {content_hash} at index {chunk_index}"
                raise ValueError(msg) from exc
        parts.append(chunk_payload)
    return b"".join(parts)


def _hydrate_large_column_rows(
    model_cls: type[DatabaseObjectRow],
    raw_rows: Sequence[dict[str, Any] | Any],
    content_store_rows: Sequence[dict[str, Any] | Any],
    content_chunk_rows: Sequence[dict[str, Any] | Any],
    *,
    hydrate_large_columns: bool,
) -> list[dict[str, Any]]:
    if not hydrate_large_columns:
        return [dict(row) for row in raw_rows]

    store_by_hash = {str(dict(row)["content_hash"]): dict(row) for row in content_store_rows}
    chunks_by_hash: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for row in content_chunk_rows:
        row_dict = dict(row)
        chunks_by_hash[str(row_dict["content_hash"])].append(row_dict)

    hydrated_rows: list[dict[str, Any]] = []
    for raw_row in raw_rows:
        row = dict(raw_row)
        for config in get_large_column_configs(model_cls):
            value_column = str(get_db_column_name(model_cls, DynamicFieldName(config.column)))
            pointer_column = _model_large_column_pointer_db_column(model_cls, SqlColumnName(config.column))
            pointer = row.get(pointer_column)
            if pointer is None:
                continue
            if row.get(value_column) not in (None, ""):
                continue
            content_hash = str(pointer)
            store_row = store_by_hash.get(content_hash)
            if store_row is None:
                msg = f"Missing spilled content for {model_cls.__name__}.{config.column}: {content_hash}"
                raise ValueError(msg)
            total_chunks = _coerce_int(store_row["total_chunks"])
            if total_chunks > 0:
                stored_content = _reassemble_chunk_payload(
                    content_hash=content_hash,
                    total_chunks=total_chunks,
                    chunk_rows=chunks_by_hash.get(content_hash, []),
                    compression_algorithm=str(store_row["compression_algorithm"]),
                )
            else:
                stored_content = _coerce_bytes(store_row["payload"])
            row[value_column] = _decode_large_column_payload(
                content_hash=content_hash,
                config_content_type=config.content_type,
                is_binary=bool(store_row["is_binary"]),
                stored_content=stored_content,
                compression_algorithm=str(store_row["compression_algorithm"]),
                compression_level=_coerce_int(store_row["compression_level"]),
                original_size=_coerce_int(store_row["original_size"]),
            )
        hydrated_rows.append(row)
    return hydrated_rows


def _post_process_hydrate_large_column_results[T: DatabaseObjectRow](
    model_cls: type[T],
    query_spec: QuerySpec[Any],
    source_ref: str,
    content_store_ref: str,
    content_chunk_ref: str,
    _raw_result: RawResult,
    _hydrator: Hydrator,
    runtime_refs: Mapping[str, object],
) -> list[T]:
    return _hydrate_large_column_results_from_refs(
        model_cls,
        query_spec,
        source_ref,
        content_store_ref,
        content_chunk_ref,
        runtime_refs,
    )


def _hydrate_large_column_results_from_refs[T: DatabaseObjectRow](
    model_cls: type[T],
    query_spec: QuerySpec[Any],
    source_ref: str,
    content_store_ref: str,
    content_chunk_ref: str,
    runtime_refs: Mapping[str, object],
) -> list[T]:
    resolved_rows = runtime_refs.get(source_ref, [])
    resolved_store_rows = runtime_refs.get(content_store_ref, [])
    resolved_chunk_rows = runtime_refs.get(content_chunk_ref, [])
    if not isinstance(resolved_rows, list):
        msg = f"Expected resolved list for {source_ref}, got {type(resolved_rows).__name__}"
        raise TypeError(msg)
    if not isinstance(resolved_store_rows, list):
        msg = f"Expected resolved list for {content_store_ref}, got {type(resolved_store_rows).__name__}"
        raise TypeError(msg)
    if not isinstance(resolved_chunk_rows, list):
        msg = f"Expected resolved list for {content_chunk_ref}, got {type(resolved_chunk_rows).__name__}"
        raise TypeError(msg)

    hydrated_rows = _hydrate_large_column_rows(
        model_cls,
        cast("Sequence[dict[str, Any]]", resolved_rows),
        cast("Sequence[dict[str, Any]]", resolved_store_rows),
        cast("Sequence[dict[str, Any]]", resolved_chunk_rows),
        hydrate_large_columns=not query_spec.defer_large_columns,
    )
    return [
        cast(
            "T",
            convert_row_to_model(
                model_cls,
                row,
                select_columns=cast("list[str] | None", query_spec.select_columns),
                hydrate_large_columns=False,
            ),
        )
        for row in hydrated_rows
    ]


def _post_process_hydrate_inline_large_column_results[T: DatabaseObjectRow](
    model_cls: type[T],
    defer_large_columns: bool,
    result_mode: Literal["many", "first", "strict_one"],
    raw_mode: bool,
    projected_columns: tuple[str, ...] | None,
    raw_result: RawResult,
    hydrator: Hydrator,
) -> object:
    if (
        raw_mode
        and projected_columns is not None
        and not _projected_columns_request_large_columns(model_cls, projected_columns)
        and _raw_rows_have_inline_large_column_aliases(raw_result)
    ):
        msg = (
            "post_op.unrequested_large_column_hydration: inline large-column aliases "
            "reached a projected raw materializer that did not request a large column"
        )
        raise ValueError(msg)
    hydrated_rows = _hydrate_inline_large_column_rows(
        model_cls,
        raw_result,
        hydrate_large_columns=not defer_large_columns,
    )
    if raw_mode:
        if projected_columns is None:
            rows: object = hydrated_rows
        else:
            rows = [{column: row.get(column) for column in projected_columns} for row in hydrated_rows]
    else:
        from impl.common.l5200_sql_query.row_converter import convert_row_to_model

        rows = [
            cast(
                "T",
                convert_row_to_model(
                    model_cls,
                    row,
                    hydrate_large_columns=False,
                ),
            )
            for row in hydrated_rows
        ]
    if result_mode == "many":
        return rows
    if not isinstance(rows, Sequence) or isinstance(rows, bytes | bytearray | str):
        msg = f"Expected hydrated row sequence, got {type(rows).__name__}"
        raise TypeError(msg)
    if result_mode == "strict_one" and len(rows) > 1:
        msg = f"Multiple results found: execute_one() returned more than one result ({len(rows)}+ rows)"
        raise ValueError(msg)
    return rows[0] if rows else None


def _raw_rows_have_inline_large_column_aliases(raw_result: RawResult) -> bool:
    inline_prefix = "__nera_inline_large_column__"
    return any(isinstance(row, Mapping) and any(str(key).startswith(inline_prefix) for key in row) for row in raw_result)


def _projected_columns_request_large_columns(
    model_cls: type[DatabaseObjectRow],
    projected_columns: tuple[str, ...],
) -> bool:
    requested = set(projected_columns)
    for config in get_large_column_configs(model_cls):
        pointer_name = large_column_pointer_name(config.column)
        if {
            config.column,
            get_db_column_name(model_cls, DynamicFieldName(config.column)),
            pointer_name,
            _model_large_column_pointer_db_column(model_cls, SqlColumnName(config.column)),
        }.intersection(requested):
            return True
    return False


