def inline_large_column_query_post_op(
    *,
    model_cls: type[DatabaseObjectRow],
    query_spec: QuerySpec[Any],
    result_mode: Literal["many", "first", "strict_one"],
    raw_mode: bool,
    projected_columns: tuple[str, ...] | None = None,
) -> CompiledPostOp:
    """Hydrate inline large-column aliases as a declared large-column post-op."""
    return CompiledPostOp.materialize(
        ResultMaterializationSpec(
            behavior=PostOpBehavior.TERMINAL_OBJECT,
            inline_large_column_query_config=InlineLargeColumnQueryMaterializationConfig(
                model_cls=model_cls,
                defer_large_columns=bool(query_spec.defer_large_columns),
                result_mode=result_mode,
                raw_mode=raw_mode,
                projected_columns=projected_columns,
            ),
        ),
    )


def _post_process_select_resolved_row(
    strict_one: bool,
    source_ref: str,
    _raw_result: RawResult,
    _hydrator: Hydrator,
    runtime_refs: Mapping[str, object],
) -> object | None:
    resolved_rows = runtime_refs.get(source_ref, [])
    if not isinstance(resolved_rows, list):
        msg = f"Expected resolved list for {source_ref}, got {type(resolved_rows).__name__}"
        raise TypeError(msg)
    rows = cast("list[object]", resolved_rows)
    if strict_one and len(rows) > 1:
        msg = f"Multiple results: execute_one() returned more than one result ({len(rows)}+ rows)"
        raise ValueError(msg)
    return rows[0] if rows else None


