        fetch_kind="content_chunks" if chunked else "content_store",
    )


class _LoadLargeColumnContentStoreRowsStep(NonPublishingStep[list[dict[str, Any]]]):
    """Placeholder for the deleted raw-row -> content-store fetch seam."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        config: _LargeColumnFetchRowsConfig,
    ) -> None:
        super().__init__(ref_id)
        self._model_cls = config.model_cls
        self._source_ref = config.source_ref

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.MANY

    def is_read_only(self) -> bool:
        return True

    def execution_role(self) -> StepExecutionRole:
        if not get_large_column_configs(self._model_cls):
            return StepExecutionRole.VIRTUAL
        return StepExecutionRole.SQL

    def step_tags(self) -> frozenset[str]:
        return frozenset({"read", "large_column", "content_store"})

    def dependencies(self) -> frozenset[str]:
        return frozenset({self._source_ref})

    def tables_read(self) -> frozenset[str]:
        if not get_large_column_configs(self._model_cls):
            return frozenset()
        return frozenset({_content_store_table_name(self._model_cls)})

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def compile(self, ctx: CompilationContext) -> CompiledStep[list[dict[str, Any]]]:
        del ctx
        if not get_large_column_configs(self._model_cls):
            # Model publishes no large-column pointers, so there are no
            # content-store rows to fetch. Emit a symbolic empty-list result
            # with no SQL grammar; this avoids hitting the execution-time
            # replanning tripwire while preserving the downstream ref shape.
            return CompiledStep(closed_post_op=literal_post_op([]))
        return raise_runtime_replanning_forbidden(
            step_name=type(self).__name__,
            trigger=f"large-column content hashes still depend on unresolved source rows from {self._source_ref!r}",
            blocked_path="planner-time extraction of spilled content hashes from materialized raw rows",
            result_contract="return raw content-store rows for the hashes referenced by the source rows",
            implementation_requirements=(
                "Publish large-column content hashes through an explicit SQL-visible upstream ref.",
                "Compile content-store fetches from that explicit hash source, not ctx.materialized_pipeline.",
                "Preserve the existing raw row result shape for downstream hydration.",
            ),
        )


