class GraphTraversalCompilePlan:
    """Shared compile metadata for ServerPlan graph traversal steps."""

    node_type: type[VersionedObjectRow[SysId]]
    edge_type: type[VersionedObjectRow[SysId]]
    direction: str
    access_plan: _GraphTraversalAccessPlan
    source_endpoint: GraphEndpointJoinPlan
    target_endpoint: GraphEndpointJoinPlan
    tables_read: frozenset[str]
    dependency_auxiliary_ctes: tuple[tuple[str, object], ...]

    @property
    def source_candidate_column(self: GraphTraversalCompilePlan) -> SqlColumnName | None:
        return self.source_endpoint.candidate_column

    @property
    def target_candidate_column(self: GraphTraversalCompilePlan) -> SqlColumnName | None:
        return self.target_endpoint.candidate_column

    @property
    def include_hash32_columns(self: GraphTraversalCompilePlan) -> bool:
        return self.source_endpoint.candidate_kind == "hash32" or self.target_endpoint.candidate_kind == "hash32"

    @property
    def include_dense_key_columns(self: GraphTraversalCompilePlan) -> bool:
        return self.source_endpoint.candidate_kind == "dense_node_key" or self.target_endpoint.candidate_kind == "dense_node_key"

    def auxiliary_ctes_with(
        self: GraphTraversalCompilePlan,
        *upstream_ctes: tuple[str, object] | None,
    ) -> list[tuple[str, Any]] | None:
        merged: list[tuple[str, object]] = []
        seen: set[str] = set()
        for cte in upstream_ctes:
            if cte is None:
                continue
            name, body = cte
            if name in seen:
                continue
            merged.append((name, body))
            seen.add(name)
        for name, body in self.dependency_auxiliary_ctes:
            if name in seen:
                continue
            merged.append((name, body))
            seen.add(name)
        return cast("list[tuple[str, Any]]", merged) or None


