def _cte_scalar_expr(ctx: CompilationContext, ref_id: ServerPlanRefId) -> SqlRenderable:
    """Resolve a scalar worker dependency to its published CTE field."""
    cte_ref = ctx.cte_refs.get(ref_id)
    assert isinstance(cte_ref, CteReference)
    return cast("SqlRenderable", SqlCteFieldRef(ServerPlanRefId(cte_ref.ref_id), SqlColumnName("v")))


def _scalar_expr_or_param(ctx: CompilationContext, ref_id: ServerPlanRefId, value: object | None) -> SqlRenderable:
    if value is not None:
        return cast("SqlRenderable", SqlParam(value))
    cte_ref = ctx.cte_refs.get(ref_id)
    if isinstance(cte_ref, CteReference):
        return cast("SqlRenderable", SqlCteFieldRef(ServerPlanRefId(cte_ref.ref_id), SqlColumnName("v")))
    return _cte_scalar_expr(ctx, ref_id)


def _scalar_cte_if_used(ctx: CompilationContext, ref_id: ServerPlanRefId, value: object | None) -> CteReference | None:
    cte_ref = ctx.cte_refs.get(ref_id)
    if isinstance(cte_ref, CteReference):
        return cte_ref
    if value is None:
        _cte_scalar_expr(ctx, ref_id)
    return None


