def _materialize_embedding_worker_task_rows(
    source_ref: str,
    _raw: RawResult,
    hydrator: Hydrator,
    refs: Mapping[str, object],
) -> list[EmbeddingComputeRequestRow]:
    source_rows = refs.get(source_ref)
    if source_rows is None:
        return []
    if not isinstance(source_rows, Sequence) or isinstance(source_rows, str | bytes | bytearray):
        msg = "MaterializeEmbeddingWorkerTasksStep expected source rows to be a sequence"
        raise TypeError(msg)
    rows: list[EmbeddingComputeRequestRow] = []
    for row in source_rows:
        if isinstance(row, EmbeddingComputeRequestRow):
            rows.append(row)
        else:
            row_data = cast(Mapping[str, object], row) if isinstance(row, Mapping) else cast(Mapping[str, object], dict(cast(Any, row)))
            rows.append(
                cast(
                    EmbeddingComputeRequestRow,
                    hydrator(EmbeddingComputeRequestRow, dict(row_data)),
                ),
            )
    return rows


def _embedding_worker_groups_from_rows(
    raw: Sequence[object],
    hydrator: Hydrator,
) -> list[EmbeddingWorkerApplyGroupKey]:
    del hydrator
    groups: list[EmbeddingWorkerApplyGroupKey] = []
    for row in raw:
        if isinstance(row, Mapping):
            source_row = row
        else:
            try:
                source_row = dict(cast(Any, row))
            except (TypeError, ValueError) as exc:
                msg = f"Embedding worker dispatch row must be mapping-compatible, got {type(row).__name__}"
                raise TypeError(msg) from exc
        row_dict = {str(key): value for key, value in source_row.items()}
        if "request_sys_ids_json" not in row_dict:
            msg = (
                "Embedding worker dispatch groups require SQL-aggregated rows with "
                "request_sys_ids_json; runtime grouping is not an allowed fallback."
            )
            raise RuntimeError(msg)
        revision_id = row_dict.get("revision_id")
        branch_id = row_dict.get("branch_id")
        assert revision_id is None or isinstance(revision_id, str)
        assert branch_id is None or isinstance(branch_id, str)
        groups.append(
            EmbeddingWorkerApplyGroupKey(
                table_name=str(row_dict.get("table_name") or ""),
                index_name=str(row_dict.get("index_name") or ""),
                revision_id=revision_id,
                branch_id=branch_id,
                request_sys_ids=_parse_request_sys_ids_json(row_dict.get("request_sys_ids_json")),
            ),
        )
    return groups


