def _target_id_key_value(value: object | None) -> LiteralKeyValue | ServerRefKeyValue | None:
    if value is None:
        return None
    ref_id = getattr(value, "ref_id", None)
    if isinstance(ref_id, str):
        if "." in ref_id:
            parent_ref, field_name = ref_id.split(".", 1)
            return ServerRefKeyValue(ServerPlanRefId(parent_ref), field_name)
        return ServerRefKeyValue(ServerPlanRefId(ref_id), None)
    raw_value = value
    for method_name in ("unwrap_to_storage_key", "unwrap_to_uuid", "unwrap_to_sql", "unwrap_to_str"):
        unwrap = getattr(raw_value, method_name, None)
        if callable(unwrap):
            raw_value = unwrap()
            break
    try:
        hash(raw_value)
    except TypeError:
        return None
    return LiteralKeyValue(raw_value)


