    from l2055_lazy_result.lazy_result import LazyResult

    if not isinstance(instances, LazyResult):
        return cast("Sequence[DatabaseObjectRow]", instances)
    msg = "UpdateManyStep requires resolved lazy instances before compile"
    raise RuntimeError(msg)


def _require_selected_rows_cte(
    ctx: CompilationContext,
    selected_rows_ref: ServerPlanRefId,
) -> Any:
    cte_ref = ctx.cte_refs.get(str(selected_rows_ref))
    if cte_ref is not None:
        return cte_ref
    msg = (
        "SelectedRowsUpdateRawResultStep requires a CTE-backed selected_rows_ref. "
        "Lower this flow through SelectOneRawStep before compile()."
    )
    raise RuntimeError(msg)


def _require_prepared_json_update_binding(
    prepared_instance_binding: CteReference | None,
) -> CteReference:
    if prepared_instance_binding is not None:
        return prepared_instance_binding
    msg = "JSON object PATCH updates require a prepared payload relation"
    raise RuntimeError(msg)


class UpdateStep[T](ServerPlanStep[T]):
    """Step for updating model instances."""

    def __init__(
        self: UpdateStep,
        ref_id: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        config: _UpdateStepConfig,
    ) -> None:
        super().__init__(ref_id)
        self._model_cls = model_cls
        self._instance = config.instance
        self._lazy_instance = config.lazy_instance
        self._literal_instance = config.literal_instance
        self._after_refs = config.after_refs
        self._published_preimage_hydration = config.published_preimage_hydration
        self._permission_context_ref = config.permission_context_ref
        self._permission_context_type = config.permission_context_type

    @property
    def level(self: UpdateStep) -> int:
        return 1

    def step_tags(self: UpdateStep) -> frozenset[str]:
        """Return tags identifying this step type."""
        return frozenset({"write", "update"})

    def is_read_only(self: UpdateStep) -> bool:
        """Return False - this step modifies data."""
        return False

    def requires_materialized_inputs(self: UpdateStep) -> bool:
        return bool(self.dependencies())

    def execution_role(self: UpdateStep) -> StepExecutionRole:
        """Use APPLY when the update still depends on prior refs."""
        return StepExecutionRole.APPLY if self.dependencies() else StepExecutionRole.SQL

    def result_cardinality(self: UpdateStep) -> Cardinality:
        """Return ONE - this step returns a single updated instance."""
        return Cardinality.ONE

    def publishes_executor_visible_binding(self: UpdateStep) -> bool:
        """The lowered raw update step owns executor-visible publication."""
        return False

    def always_publishes_executor_visible_binding(self: UpdateStep) -> bool:
        """Author-level update wrappers do not publish their own ref."""
        return False

    def tables_read(self: UpdateStep) -> frozenset[str]:
        """Update FK reads are exposed through catalog-backed optimizer facts."""
        return frozenset()

    def tables_written(self: UpdateStep) -> frozenset[str]:
        """Return the table name this step writes to."""
        from l1000_schema.table_utils import get_table_name

        return frozenset({get_table_name(self._model_cls)})

    def dependencies(self: UpdateStep) -> frozenset[str]:
        deps = {str(ref_id) for ref_id in self._after_refs}
        if self._permission_context_ref is not None:
            deps.add(str(self._permission_context_ref))
        deps = deps | collect_instance_deps(self._instance)  # handles LazyResult gracefully
        from l2055_lazy_result.lazy_param import server_value_deps
        from l2070_batching.server_ref import ObjectServerRef

        deps = deps | frozenset(server_value_deps(self._instance))
        if isinstance(self._instance, ObjectServerRef) and isinstance(self._instance.ref_id, str):
            deps = deps | frozenset({self._instance.ref_id})
        if self._lazy_instance is not None:
            from l2055_lazy_result.lazy_param import lazy_param_deps

            deps = deps | lazy_param_deps(self._lazy_instance)
        return frozenset(deps)

    def foreign_key_checks(
        self: UpdateStep,
        planning_catalog: PlanningCatalog | None = None,
    ) -> frozenset[ForeignKeyCheckFact]:
        instance = self._literal_instance if self._literal_instance is not None else self._instance
        return foreign_key_checks_for_instance(self._model_cls, instance, planning_catalog)

    def foreign_key_read_tables(
        self: UpdateStep,
        planning_catalog: PlanningCatalog | None = None,
    ) -> frozenset[str]:
        return insert_fk_read_tables(self._model_cls, planning_catalog)

    def write_key_facts(
        self: UpdateStep,
        planning_catalog: PlanningCatalog | None = None,
    ) -> frozenset[WriteKeyFact]:
        instance = self._literal_instance if self._literal_instance is not None else self._instance
        return write_key_facts_for_instance(
            self.ref_id,
            self._model_cls,
            instance,
            planning_catalog,
        )

    def lower(self: UpdateStep, ctx: LoweringContext) -> list[ServerPlanStep[Any]]:
        from impl.common.l2070_server_plan.steps.collect_results import ReturnSourceAfterDepsConfig, ReturnSourceAfterDepsStep
        from impl.common.l2070_server_plan.steps.return_value import ReturnValueStep
        from impl.common.l2070_server_plan.steps.row_hydration import (
            DispatchWithOldRowFlag,
            HydratePublishedSelectedUpdateResultStep,
            HydrateSelectedUpdateResultStep,
            RequireExistingFlag,
            RequireWhenSelectedFlag,
        )
        from l2055_lazy_result.lazy_result import LazyResult
        from l2070_batching.server_ref import (
            ObjectServerRef,
            PlanningServerValueShape,
            inspect_server_value_shape_for_planning,
        )

        raw_ref = f"{self.ref_id}.raw"
        selected_ref = f"{self.ref_id}.selected"
        selected_step: ServerPlanStep[Any]
        raw_lazy_instance = self._lazy_instance
        raw_instance: object = self._instance
        uses_symbolic_selected_payload = False
        selected_payload_ref = ServerPlanRefId(selected_ref)
        hydration_selected_ref = selected_payload_ref

        def _split_large_column_source_ref(source: ServerPlanRefId) -> tuple[ServerPlanRefId, ServerPlanRefId]:
            from l1000_schema.large_column import get_large_column_configs
            from impl.common.l2070_server_plan.steps.large_column_read import (
                get_large_column_ref_ownership,
                LargeColumnRefOwnership,
            )

            if not get_large_column_configs(self._model_cls):
                return source, source
            ownership = get_large_column_ref_ownership(ctx, source)
            if ownership is None:
                ownership = LargeColumnRefOwnership(
                    public_ref=source,
                    raw_ref=source,
                    hydrated_ref=source,
                    scalar_refs={},
                )
            return ownership.raw_ref, ownership.hydrated_ref

        if self._lazy_instance is not None:
            lazy_instance = cast("LazyResult[Any]", self._lazy_instance)
            lazy_shape: PlanningServerValueShape = inspect_server_value_shape_for_planning(
                lazy_instance,
                site=f"{type(self).__name__}.lower",
            )
            source_ref = lazy_shape.symbolic_ref_id
            if source_ref is not None:
                selected_payload_ref, hydration_selected_ref = _split_large_column_source_ref(source_ref)
                selected_step = ReturnSourceAfterDepsStep(
                    ServerPlanRefId(selected_ref),
                    ReturnSourceAfterDepsConfig(
                        source_ref=selected_payload_ref,
                        after_refs=(),
                        model_cls=self._model_cls,
                        dynamic_source_contract=True,
                    ),
                )
                uses_symbolic_selected_payload = True
            else:
                # Legacy wrappers may hand us an immediately-resolved LazyResult wrapper
                # around a concrete model instance with no backing plan ref.
                selected_step = ReturnValueStep(ServerPlanRefId(selected_ref), self._instance)
                raw_lazy_instance = None
        elif isinstance(self._instance, LazyResult):
            instance_shape: PlanningServerValueShape = inspect_server_value_shape_for_planning(
                self._instance,
                site=f"{type(self).__name__}.lower",
            )
            source_ref = instance_shape.symbolic_ref_id
            if source_ref is None:
                msg = "UpdateStep lazy source must be plan-backed before lowering"
                raise RuntimeError(msg)
            selected_payload_ref, hydration_selected_ref = _split_large_column_source_ref(source_ref)
            selected_step = ReturnSourceAfterDepsStep(
                ServerPlanRefId(selected_ref),
                ReturnSourceAfterDepsConfig(
                    source_ref=selected_payload_ref,
                    after_refs=(),
                    model_cls=self._model_cls,
                    dynamic_source_contract=True,
                ),
            )
            uses_symbolic_selected_payload = True
        elif isinstance(self._instance, ObjectServerRef):
            object_source_ref = self._instance.ref_id
            if isinstance(object_source_ref, str):
                selected_payload_ref, hydration_selected_ref = _split_large_column_source_ref(
                    ServerPlanRefId(object_source_ref),
                )
                selected_step = ReturnSourceAfterDepsStep(
                    ServerPlanRefId(selected_ref),
                    ReturnSourceAfterDepsConfig(
                        source_ref=selected_payload_ref,
                        after_refs=(),
                        model_cls=self._model_cls,
                        dynamic_source_contract=True,
                    ),
                )
                uses_symbolic_selected_payload = True
            else:
                msg = "UpdateStep requires a symbolic object ref before lowering"
                raise NotImplementedError(msg)
        else:
            selected_step = ReturnValueStep(ServerPlanRefId(selected_ref), self._instance)
        if uses_symbolic_selected_payload:
            from impl.common.l2070_server_plan.steps._versioned_staging import (
                build_large_column_spill_steps,
                prepare_large_column_spill_plan_from_tuples,
            )
            from l1000_schema.large_column import get_large_column_configs, large_column_pointer_name

            selected_patch_updates: dict[str, Any] = {}
            if isinstance(self._literal_instance, self._model_cls):
                selected_patch_updates = dict(self._literal_instance.model_dump(mode="python"))
                selected_patch_updates.pop("sys_id", None)
            elif isinstance(raw_instance, self._model_cls):
                selected_patch_updates = dict(raw_instance.model_dump(mode="python"))
                selected_patch_updates.pop("sys_id", None)
            spill_steps: list[ServerPlanStep[Any]] = []
            for config in get_large_column_configs(self._model_cls):
                column = str(config.column)
                if column not in selected_patch_updates:
                    continue
                value = selected_patch_updates[column]
                pointer = large_column_pointer_name(ContentColumnName(column))
                rows, spill_plan = prepare_large_column_spill_plan_from_tuples(
                    self._model_cls,
                    [column, pointer],
                    [(value, None)],
                    backend_type=ctx.backend_type,
                )
                rewritten = rows[0]
                selected_patch_updates[column] = rewritten[0]
                selected_patch_updates[pointer] = rewritten[1]
                if spill_plan.rows:
                    spill_steps.extend(
                        build_large_column_spill_steps(
                            self._model_cls,
                            spill_plan,
                            write_ref_id=ServerPlanRefId(f"{self.ref_id}.{column}.spill"),
                        ),
                    )
            update_step: ServerPlanStep[Any] = SelectedRowsUpdateRawResultStep(
                ServerPlanRefId(raw_ref),
                self._model_cls,
                _SelectedRowsUpdateStepConfig(
                    instance=ObjectServerRef(
                        None,
                        selected_payload_ref,
                        type_hint=self._model_cls,
                    ),
                    selected_rows_ref=selected_payload_ref,
                    patch_updates=selected_patch_updates,
                    apply_update_rules=True,
                    after_refs=self._after_refs | frozenset(ServerPlanRefId(step.ref_id) for step in spill_steps),
                    permission_context_ref=self._permission_context_ref,
                    permission_context_type=self._permission_context_type,
                ),
            )
        else:
            spill_steps = []
            update_step = UpdateRawResultStep(
                ServerPlanRefId(raw_ref),
                self._model_cls,
                _UpdateStepConfig(
                    instance=raw_instance,
                    lazy_instance=raw_lazy_instance,
                    literal_instance=self._literal_instance,
                    after_refs=frozenset({ServerPlanRefId(selected_ref), *self._after_refs}),
                    permission_context_ref=self._permission_context_ref,
                    permission_context_type=self._permission_context_type,
                ),
            )
        hydration_step_type = (
            HydratePublishedSelectedUpdateResultStep if self._published_preimage_hydration else HydrateSelectedUpdateResultStep
        )
        return [
            selected_step,
            *spill_steps,
            update_step,
            hydration_step_type(
                self.ref_id,
                source_ref=ServerPlanRefId(raw_ref),
                selected_ref=hydration_selected_ref,
                model_cls=self._model_cls,
                require_when_selected=RequireWhenSelectedFlag(True),
                dispatch_with_old_row=DispatchWithOldRowFlag(False),
                require_existing=RequireExistingFlag(True),
            ),
        ]

    def compile(self: UpdateStep, ctx: CompilationContext) -> CompiledStep[T]:
        del ctx
        raise NotImplementedError(f"{type(self).__name__} must be lowered before compile()")


class UpdateRawResultStep(UpdateStep[list[dict[str, Any]]]):
    """Terminal raw-row variant of single-row update."""

    def __init__(
        self: UpdateRawResultStep,
        ref_id: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        config: _UpdateStepConfig,
    ) -> None:
        super().__init__(ref_id, model_cls, config)
        self._requires_runtime_replanning = config.lazy_instance is not None
        if not self._requires_runtime_replanning:
            from l2070_batching.server_ref import ObjectServerRef

            symbolic_ref = isinstance(self._instance, ObjectServerRef) and isinstance(self._instance.ref_id, str)
            # ``literal_instance`` carries the originally-supplied concrete row
            # through an upstream permission-guard wrapping layer. When it is
            # present, compile() has everything needed to emit the final UPDATE
            # directly, while the symbolic ``instance`` ref still enforces
            # permission-before-update ordering via ``dependencies()``.
            self._requires_runtime_replanning = symbolic_ref and self._literal_instance is None

    @property
    def level(self: UpdateRawResultStep) -> int:
        return 0

    def step_tags(self: UpdateRawResultStep) -> frozenset[str]:
        return frozenset({"write", "update", "raw"})

    def cte_publication_contract(self: UpdateRawResultStep) -> CtePublicationContract:
        columns = tuple(
            (get_db_column_name(self._model_cls, DynamicFieldName(field_name)) for field_name in self._model_cls.model_fields)
        )
        from l1000_schema.large_column import get_large_column_configs, large_column_pointer_name

        for config in get_large_column_configs(self._model_cls):
            pointer_column = get_db_column_name(self._model_cls, DynamicFieldName(large_column_pointer_name(config.column)))
            if pointer_column not in columns:
                columns = (*columns, pointer_column)
        column_type_hints = model_sql_column_type_hints(self._model_cls, columns)
        if get_large_column_configs(self._model_cls):
            from l2070_batching.sql_column_type_hints import combine_sql_column_type_hints

            pointer_columns = frozenset(
                str(get_db_column_name(self._model_cls, DynamicFieldName(large_column_pointer_name(config.column))))
                for config in get_large_column_configs(self._model_cls)
            )
            column_type_hints = combine_sql_column_type_hints(
                columns,
                column_type_hints or SqlColumnTypeHints(),
                SqlColumnTypeHints(text_columns=pointer_columns),
            )
        if columns is None:
            if column_type_hints is not None and column_type_hints.has_any():
                msg = f"{type(self).__name__} declares SQL column type hints without an explicit cte_output_columns() contract."
                raise TypeError(msg)
            return CtePublicationContract.non_publishing()
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        _contract_model_cls = self._model_cls
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=tuple(str(column) for column in columns),
            column_type_hints=column_type_hints,
            model_cls=_contract_model_cls,
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def always_publishes_executor_visible_binding(self: UpdateRawResultStep) -> bool:
        return True

    def publishes_executor_visible_binding(self: UpdateRawResultStep) -> bool:
        return True

    def lower(self: UpdateRawResultStep, ctx: LoweringContext) -> list[ServerPlanStep[Any]]:
        del ctx
        return [self]

    def compile(self: UpdateRawResultStep, ctx: CompilationContext) -> CompiledStep[list[dict[str, Any]]]:
        from impl.common.l2070_server_plan.steps._compile_write import compile_update_grammar

        if self._requires_runtime_replanning:
            return _compile_runtime_gated_update_raw(self)
        # Prefer the explicit literal when the primary ``instance`` is a
        # symbolic ObjectServerRef that was only carrying the dependency chain
        # through the permission guard step.
        instance = cast(
            DatabaseObjectRow[Any],
            self._literal_instance if self._literal_instance is not None else self._instance,
        )
        contract = self.cte_publication_contract()
        assert contract is not None
        output_shape = output_shape_from_cte_publication_contract(contract)
        column_type_hints = contract.column_type_hints
        column_type_hints.require_complete(output_shape.cte_output_columns)
        from l2070_batching.output_shape import DeclaredResultRelation

        result_relation = DeclaredResultRelation.from_output_shape(output_shape)
        ir = compile_update_grammar(
            self._model_cls,
            instance,
            ctx,
            output_shape=output_shape,
            result_relation=result_relation,
            permission_context_ref=self._permission_context_ref,
            permission_context_type=self._permission_context_type,
        )
        assert ir is not None
        closed_post_op = row_dicts_post_op()
        if not ir.needs_returning:
            from impl.common.l2070_server_plan.steps._compile_helpers import (
                compile_update_permission_filter,
            )
            from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName
            from impl.common.l2100_sql_grammar.domain.infra.stmt_compound_write import (
                SqlStatementBatch,
                SqlStatementBatchCategory,
            )
            from impl.common.l2100_sql_grammar.domain.query.stmt_dynamic import (
                SqlDynamicSelectStmt,
            )
            from impl.common.l2100_sql_grammar.tree.enums import BinaryOp
            from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlParam
            from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp
            from l1000_schema.table_utils import get_table_name

            readback_conditions: list[SqlRenderable] = [
                SqlBinaryOp(
                    SqlColumnRef(SqlColumnName("sys_id")),
                    BinaryOp.EQ,
                    SqlParam(instance.sys_id),
                ),
            ]
            permission_expr = compile_update_permission_filter(
                self._model_cls,
                ctx,
                permission_context_ref=self._permission_context_ref,
                permission_context_type=self._permission_context_type,
            )
            if permission_expr is not None:
                readback_conditions.append(permission_expr)
            select_grammar = SqlDynamicSelectStmt(
                from_table=get_table_name(self._model_cls),
                columns=[SqlColumnName(column) for column in contract.columns],
                where_conditions=readback_conditions,
            )
            return CompiledStep(
                grammar=SqlStatementBatch(
                    [ir.grammar, select_grammar],
                    category=SqlStatementBatchCategory.ORDERED_SEMANTIC,
                    needs_returning_per_stmt=[False, True],
                    collect_results_per_stmt=[False, True],
                ),
                needs_returning=True,
                closed_post_op=closed_post_op,
                external_params_first=ir.external_params_first,
                provenance_manifest=ir.provenance_manifest,
                allow_empty_provenance_manifest=ir.allow_empty_provenance_manifest,
                use_savepoint_recovery=ir.use_savepoint_recovery,
                output_shape=output_shape,
                result_relation=result_relation,
                column_type_hints=column_type_hints,
            )
        return CompiledStep(
            grammar=ir.grammar,
            params=ir.params,
            needs_returning=ir.needs_returning,
            external_params_first=ir.external_params_first,
            provenance_manifest=ir.provenance_manifest,
            allow_empty_provenance_manifest=ir.allow_empty_provenance_manifest,
            use_savepoint_recovery=ir.use_savepoint_recovery,
            closed_post_op=closed_post_op,
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
        )


class UpdateManyStep[T](NonPublishingStep[list[T]]):
    """Bulk update step for concrete or lazily resolved model sequences."""

    def __init__(
        self: UpdateManyStep,
        ref_id: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        instances: Sequence[DatabaseObjectRow] | LazyResult[Sequence[DatabaseObjectRow]],
    ) -> None:
        super().__init__(ref_id)
        self._model_cls = model_cls
        self._instances = instances

    @property
    def level(self: UpdateManyStep) -> int:
        return 1

    def step_tags(self: UpdateManyStep) -> frozenset[str]:
        return frozenset({"write", "update", "bulk"})

    def is_read_only(self: UpdateManyStep) -> bool:
        return False

    def result_cardinality(self: UpdateManyStep) -> Cardinality:
        return Cardinality.MANY

    def tables_read(self: UpdateManyStep) -> frozenset[str]:
        return frozenset()

    def tables_written(self: UpdateManyStep) -> frozenset[str]:
        from l1000_schema.table_utils import get_table_name

        return frozenset({get_table_name(self._model_cls)})

    def dependencies(self: UpdateManyStep) -> frozenset[str]:
