        )

    def preprocess(self: UpdateManyStep, resolved: ResolvedRefs) -> None:
        del resolved

    def compile(self: UpdateManyStep, ctx: CompilationContext) -> CompiledStep[list[T]]:
        del ctx
        _raise_update_many_must_lower(type(self).__name__)
        raise AssertionError("unreachable")

    def _compile_legacy_direct(self: UpdateManyStep, ctx: CompilationContext) -> CompiledStep[list[T]]:
        from impl.common.l2070_server_plan.steps._compile_write import compile_update_grammar
        from impl.common.l2100_sql_grammar.domain.infra.stmt_compound_write import (
            SqlStatementBatch,
            SqlStatementBatchCategory,
        )
        from l2055_lazy_result.lazy_result import LazyResult

        instances = _require_resolved_update_many_instances(self._instances)
        if not instances:
            return CompiledStep(closed_post_op=literal_post_op([]))

        compiled_steps = [compile_update_grammar(self._model_cls, instance, ctx) for instance in instances]
        statements: list[Any] = []
        params_per_stmt: list[tuple[Any, ...]] = []
        for compiled in compiled_steps:
            assert compiled is not None
            statements.append(compiled.grammar)
            params_per_stmt.append(tuple(compiled.params or ()))

        grammar = SqlStatementBatch(
            statements,
            category=SqlStatementBatchCategory.REQUEST_BATCH_BOUNDARY,
            params_per_stmt=params_per_stmt,
            external_params_first=[True] * len(statements),
        )
        from l2070_batching.output_shape import DeclaredResultRelation

        __opa002_grammar_650 = grammar
        output_shape = output_shape_from_cte_publication_contract(self.cte_publication_contract())
        result_relation = DeclaredResultRelation.from_output_shape(output_shape)
        column_type_hints = model_sql_column_type_hints(
            self._model_cls,
            output_shape.cte_output_columns,
