class SelectedRowsUpdateRawResultStep(UpdateStep[list[dict[str, Any]]]):
    """Terminal raw-row update compiled from explicit selected-row authority."""

    def result_cardinality(self: SelectedRowsUpdateRawResultStep) -> Cardinality:
        return Cardinality.MANY

    def __init__(
        self: SelectedRowsUpdateRawResultStep,
        ref_id: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        config: _SelectedRowsUpdateStepConfig,
    ) -> None:
        super().__init__(
            ref_id,
            model_cls,
            _UpdateStepConfig(
                instance=config.instance,
                permission_context_ref=config.permission_context_ref,
                permission_context_type=config.permission_context_type,
            ),
        )
        self._selected_rows_ref = config.selected_rows_ref
        self._patch_updates = dict(config.patch_updates)
        self._apply_update_rules = config.apply_update_rules
        self._target_id = config.target_id
        self._after_refs = config.after_refs
        self._materialize_selected_rows = config.materialize_selected_rows

    @property
    def level(self: SelectedRowsUpdateRawResultStep) -> int:
        return 0

    def step_tags(self: SelectedRowsUpdateRawResultStep) -> frozenset[str]:
        return frozenset({"write", "update", "raw"})

    def cte_publication_contract(self: SelectedRowsUpdateRawResultStep) -> CtePublicationContract:
        columns = tuple(
            str(get_db_column_name(self._model_cls, DynamicFieldName(field_name))) for field_name in self._model_cls.model_fields
        )
        from l1000_schema.large_column import get_large_column_configs, large_column_pointer_name

        large_column_configs = get_large_column_configs(self._model_cls)
        for config in large_column_configs:
            pointer_column = str(
                get_db_column_name(self._model_cls, DynamicFieldName(large_column_pointer_name(config.column))),
            )
            if pointer_column not in columns:
                columns = (*columns, pointer_column)
        column_type_hints = model_sql_column_type_hints(self._model_cls, columns)
        if large_column_configs:
            from l2070_batching.sql_column_type_hints import combine_sql_column_type_hints

            pointer_columns = frozenset(
                str(get_db_column_name(self._model_cls, DynamicFieldName(large_column_pointer_name(config.column))))
                for config in large_column_configs
            )
            column_type_hints = combine_sql_column_type_hints(
                columns,
                column_type_hints or SqlColumnTypeHints(),
                SqlColumnTypeHints(text_columns=pointer_columns),
            )
        if columns is None:
            if column_type_hints is not None and column_type_hints.has_any():
                msg = f"{type(self).__name__} declares SQL column type hints without an explicit cte_output_columns() contract."
                raise TypeError(msg)
            return CtePublicationContract.non_publishing()
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        _contract_model_cls = self._model_cls
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=tuple(str(column) for column in columns),
            column_type_hints=column_type_hints,
            model_cls=_contract_model_cls,
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def runtime_publication_transport_columns(self) -> frozenset[str]:
        from impl.common.l2070_server_plan.steps.large_column_read import (
            inline_large_column_alias_columns,
        )

        return frozenset(inline_large_column_alias_columns(self._model_cls))

    def batch_result_labels(self: SelectedRowsUpdateRawResultStep) -> tuple[str, ...]:
        ref_id = str(self.ref_id)
        return (ref_id, f"{ref_id}.raw")

    def always_publishes_executor_visible_binding(self: SelectedRowsUpdateRawResultStep) -> bool:
        return True

    def publishes_executor_visible_binding(self: SelectedRowsUpdateRawResultStep) -> bool:
        return True

    def execution_role(self: SelectedRowsUpdateRawResultStep) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def supports_sql_batch_transport(self: SelectedRowsUpdateRawResultStep) -> bool:
        return True

    def supports_ordered_sql_statement_batch(self: SelectedRowsUpdateRawResultStep) -> bool:
        return not self._apply_update_rules

    def ordered_statement_sql_visible_dependencies(
        self: SelectedRowsUpdateRawResultStep,
    ) -> frozenset[str]:
        if not self._apply_update_rules:
            return frozenset()
        return super().ordered_statement_sql_visible_dependencies()

    def requires_prior_step_boundary(self: SelectedRowsUpdateRawResultStep) -> bool:
        return self._materialize_selected_rows

    def requires_materialized_inputs(self: SelectedRowsUpdateRawResultStep) -> bool:
        return self._materialize_selected_rows

    def write_key_facts(
        self: SelectedRowsUpdateRawResultStep,
        planning_catalog: PlanningCatalog | None = None,
    ) -> frozenset[WriteKeyFact]:
        del planning_catalog
        from l1000_schema.table_utils import get_table_name

        key_value = _target_id_key_value(self._target_id)
        return frozenset(
            {
                WriteKeyFact(
                    producer_ref=self.ref_id,
                    table=get_table_name(self._model_cls),
                    columns=("sys_id",),
                    key_values=frozenset() if key_value is None else frozenset({KeyTupleValue((key_value,))}),
                    has_unknown_key_values=key_value is None,
                ),
            },
        )

