        return True

    def dependencies(self: SelectedRowsUpdateRawResultStep) -> frozenset[str]:
        deps: set[str] = set()
        instance_ref_id = getattr(self._instance, "ref_id", None)
        if isinstance(instance_ref_id, str):
            deps.add(instance_ref_id)
        else:
            deps.update(super().dependencies())
        selected_ref = str(self._selected_rows_ref)
        deps.add(selected_ref)
        deps.update(str(ref_id) for ref_id in self._after_refs)
        if self._permission_context_ref is not None:
            deps.add(str(self._permission_context_ref))
        selected_base_ref = selected_ref.split(".", 1)[0]
        own_base_ref = str(self.ref_id).split(".", 1)[0]
        if selected_base_ref != own_base_ref:
            deps.add(selected_base_ref)
        return frozenset(deps)

    def lower(self: SelectedRowsUpdateRawResultStep, ctx: LoweringContext) -> list[ServerPlanStep[Any]]:
        from impl.common.l2070_server_plan.steps._versioned_staging import (
            build_large_column_spill_steps,
            prepare_large_column_spill_plan_from_tuples,
        )
        from l1000_schema.large_column import get_large_column_configs, large_column_pointer_name
        from l1000_schema.typed_field import Expression, Field

        spill_steps: list[ServerPlanStep[Any]] = []
        for config in get_large_column_configs(self._model_cls):
            column = str(config.column)
            if column not in self._patch_updates:
                continue
            value = self._patch_updates[column]
            if isinstance(value, (Expression, Field, SqlRenderable)):
                continue
            pointer = large_column_pointer_name(ContentColumnName(column))
            if value is None:
                self._patch_updates[pointer] = None
                continue
            rows, spill_plan = prepare_large_column_spill_plan_from_tuples(
                self._model_cls,
                [column, pointer],
                [(value, None)],
                backend_type=ctx.backend_type,
            )
            rewritten = rows[0]
            self._patch_updates[column] = rewritten[0]
            self._patch_updates[pointer] = rewritten[1]
            if spill_plan.rows:
                spill_steps.extend(
                    build_large_column_spill_steps(
                        self._model_cls,
                        spill_plan,
                        write_ref_id=ServerPlanRefId(f"{self.ref_id}.{column}.spill"),
                    ),
                )
        if spill_steps:
            self._after_refs = frozenset(
                (*self._after_refs, *(ServerPlanRefId(step.ref_id) for step in spill_steps)),
            )
        return [*spill_steps, self]

