def merge_conflict_views_post_op() -> CompiledPostOp:
    """Materialize SQL conflict rows as conflict view domain objects."""
    return CompiledPostOp.materialize(
        ResultMaterializationSpec(
            behavior=PostOpBehavior.TERMINAL_ARRAY,
            structured_array=StructuredArraySpec(
                StructuredResultSpec(
                    result_cls=MergeConflictView,
                    fields=_merge_conflict_view_fields(),
                ),
            ),
        ),
    )


def required_merge_conflict_view_post_op(conflict_id: str) -> CompiledPostOp:
    """Materialize a required SQL conflict-view row."""
    return CompiledPostOp.materialize(
        ResultMaterializationSpec(
            behavior=PostOpBehavior.TERMINAL_OBJECT,
            structured_result=StructuredResultSpec(
                result_cls=MergeConflictView,
                fields=_merge_conflict_view_fields(),
                empty_exception=db_exc.ObjectNotFoundError,
                empty_message=f"Merge conflict {conflict_id} was not found.",
            ),
        ),
    )


