def _parse_json_field(val: object) -> dict[str, object] | None:
    """Parse a JSON field that may be a string, dict, or None."""
    if val is None:
        return None
    if isinstance(val, dict):
        return {str(key): value for key, value in val.items()}
    if isinstance(val, str):
        parsed = json.loads(val)
        if isinstance(parsed, dict):
            return {str(key): value for key, value in parsed.items()}
        return None
    return None


def _with_optional_status_filter(
    where_expr: SqlRenderable,
    status_filter: AbstractSet[str] | None,
) -> SqlRenderable:
    """Append a status IN predicate when the caller supplied a filter."""
    if not status_filter:
        return where_expr

    from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName, SqlTableName
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlParam
    from impl.common.l2100_sql_grammar.tree.expr_ops import SqlIn, sql_and

    status_in = SqlIn(
        SqlColumnRef(SqlColumnName("status")),
        [SqlParam(status) for status in sorted(status_filter)],
    )
    return sql_and(where_expr, status_in)


def _with_visible_conflict_filter(
    where_expr: SqlRenderable,
    status_filter: AbstractSet[str] | None,
) -> SqlRenderable:
    """Append optional status predicates for conflict list views."""
    return _with_optional_status_filter(where_expr, status_filter)


def _conflict_dependency_is_cte_bound(ctx: CompilationContext, conflict_ref_id: str) -> bool:
    return _dependency_cte_name(ctx, conflict_ref_id) is not None


def _dependency_cte_name(ctx: CompilationContext, conflict_ref_id: str) -> str | None:
    """Return the compiled CTE name for a conflict dependency ref."""
    direct = ctx.cte_refs.get(conflict_ref_id)
    if isinstance(direct, CteReference):
        return direct.ref_id
    base_ref_id = conflict_ref_id.split(".", 1)[0]
    base = ctx.cte_refs.get(base_ref_id)
    if isinstance(base, CteReference):
        return base.ref_id
    return None


def _dependency_cte_reference(ctx: CompilationContext, conflict_ref_id: str) -> CteReference | None:
    """Return the CteReference object for a conflict dependency ref, if any."""
    direct = ctx.cte_refs.get(conflict_ref_id)
    if isinstance(direct, CteReference):
        return direct
    base_ref_id = conflict_ref_id.split(".", 1)[0]
    base = ctx.cte_refs.get(base_ref_id)
    if isinstance(base, CteReference):
        return base
    return None


def _auxiliary_ctes_for_conflict_ref(ctx: CompilationContext, conflict_ref_id: str) -> list[tuple[str, Any]] | None:
    """Build the auxiliary_ctes list that re-publishes a split-step result.

    When the conflict ref points to a previously executed step whose result
    has been republished into the plan's CTE namespace (``auxiliary_query``
    carries the republish grammar), downstream compilations must include that
    CTE definition so the emitted SQL can reference it by name. Without the
    auxiliary WITH entry, SQLite/MariaDB raise "no such table" because the
    CTE is only in scope of the statement that defined it.
    """
    from impl.common.l2070_server_plan.steps._auxiliary_ctes import resolve_auxiliary_cte_binding

    cte_ref = resolve_auxiliary_cte_binding(ctx, ServerPlanRefId(conflict_ref_id))
    if cte_ref is None or cte_ref.auxiliary_query is None:
        return None
    return [(cte_ref.ref_id, cte_ref.auxiliary_query)]


def _materialized_merge_operation_sys_id_str(
    ctx: CompilationContext,
    conflict_ref_id: str,
) -> str:
    """Tripwire the deleted materialized conflict fallback."""
    del ctx
    raise_missing_cte_fallback_forbidden(
        site_name="_materialized_merge_operation_sys_id_str",
        trigger=f"conflict dependency {conflict_ref_id!r} is not CTE-bound",
        blocked_path="compile-time materialized merge-operation-id fallback for conflict resolution",
        result_contract="conflict resolution SQL must read merge_operation_sys_id from an explicit upstream ref",
        implementation_requirements=(
            "Publish merge conflict dependencies through explicit CTE refs before compile().",
            "Compile conflict SQL against ctx.cte_refs rather than planner materialized values.",
            "Do not recover merge_operation_sys_id from ctx.materialized_pipeline during compile().",
        ),
    )


def _merge_op_sys_id_sql_for_operation_ref(
    ctx: CompilationContext,
    op_ref_id: ServerPlanRefId,
) -> SqlRenderable:
    """Resolve an operation dependency to the SQL expression for its sys_id."""
    from impl.common.l2070_server_plan.steps.merge_three_way_steps import (
        _require_cte_field,
        _require_merge_op_scalar,
    )

    if op_ref_id in ctx.cte_refs:
        return _require_merge_op_scalar(ctx, op_ref_id)
    return _require_cte_field(ctx, ServerPlanRefId(op_ref_id), "sys_id")


def _merge_operation_id_sql_for_conflict_row(
    ctx: CompilationContext,
    conflict_ref_id: str,
) -> SqlRenderable:
    """Lower conflict-row dependency to merge_operation_sys_id (CTE field ref or param)."""
    from impl.common.l2100_sql_grammar.domain.infra.stmt_dml_simple import SqlCteFieldRef
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlParam

    cte_name = _dependency_cte_name(ctx, conflict_ref_id)
    if cte_name is not None:
        from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName

        return SqlCteFieldRef(ServerPlanRefId(cte_name), SqlColumnName("merge_operation_sys_id"))
    return SqlParam(_materialized_merge_operation_sys_id_str(ctx, conflict_ref_id))


def _all_conflicts_resolved_where_clause(
    *,
    ctx: CompilationContext,
    conflict_table: str,
    conflict_ref_id: str,
    conflict_id_raw: SysId | None,
) -> SqlRenderable:
    """Build the pending-or-dismissed predicate for a merge operation."""
    from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName
    from impl.common.l2100_sql_grammar.domain.infra.stmt_dml_simple import SqlScalarSubquery
    from impl.common.l2100_sql_grammar.tree.clauses import SqlFrom, SqlSelectList, SqlTableAlias, SqlWhereClause
    from impl.common.l2100_sql_grammar.tree.enums import BinaryOp
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlParam
    from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp, SqlIn, sql_and
    from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
    from impl.common.l2100_sql_grammar.tree.statements import SqlSelect

    cte_bound = _conflict_dependency_is_cte_bound(ctx, conflict_ref_id)
    if cte_bound:
        merge_operation_id_expr = _merge_operation_id_sql_for_conflict_row(ctx, conflict_ref_id)
    elif conflict_id_raw is not None:
        merge_operation_id_expr = SqlScalarSubquery(
            SqlSelect(
                select=SqlSelectList([SqlColumnRef(SqlColumnName("merge_operation_sys_id"))]),
                from_clause=SqlFrom(SqlTableAlias(SqlTableIdent(SqlTableName(conflict_table)))),
                where=SqlWhereClause(
                    SqlBinaryOp(
                        SqlColumnRef(SqlColumnName("sys_id")),
                        BinaryOp.EQ,
                        SqlParam(_sys_id_bind_str(conflict_id_raw)),
                    ),
                ),
            ),
        )
    else:
        merge_operation_id_expr = _merge_operation_id_sql_for_conflict_row(ctx, conflict_ref_id)
    where_expr = sql_and(
        SqlBinaryOp(
            SqlColumnRef(SqlColumnName("merge_operation_sys_id")),
            BinaryOp.EQ,
            merge_operation_id_expr,
        ),
        SqlIn(
            SqlColumnRef(SqlColumnName("status")),
            [SqlParam("pending"), SqlParam("dismissed")],
        ),
    )
    if conflict_id_raw is not None:
        where_expr = sql_and(
            where_expr,
            SqlBinaryOp(
                SqlColumnRef(SqlColumnName("sys_id")),
                BinaryOp.NE,
                SqlParam(_sys_id_bind_str(conflict_id_raw)),
            ),
        )
    return where_expr


def _compile_all_conflicts_resolved_cte_step(
    *,
    ctx: CompilationContext,
    conflict_table: str,
    where: SqlRenderable,
    conflict_ref_id: str,
) -> CompiledStep[bool]:
    """Compile the CTE-backed all-conflicts-resolved check."""
    from impl.common.l2100_sql_grammar.domain.infra.stmt_dml_simple import SqlRawExpression
    from impl.common.l2100_sql_grammar.tree.clauses import SqlWhereClause

    dialect = ctx.sql_render_dialect()
    where_clause = SqlWhereClause(where)
    where_frag = where_clause.render(dialect)
    where_sql, where_params = where_frag.to_sql(dialect)
    raw_sql = f'SELECT NOT EXISTS(SELECT 1 FROM "{conflict_table}" {where_sql}) AS "__result"'
    grammar: SqlRenderable = SqlRawExpression(raw_sql, tuple(where_params))

    __opa002_grammar_1306 = grammar
    output_shape = CompiledOutputShape((synthetic_output_field("__result", role="conflicts_resolved"),))
    column_type_hints = SqlColumnTypeHints(bool_columns=frozenset({"__result"}))
    return CompiledStep(
        output_shape=output_shape,
        grammar=__opa002_grammar_1306,
        needs_returning=True,
        result_relation=DeclaredResultRelation.from_output_shape(output_shape),
        column_type_hints=column_type_hints,
        closed_post_op=scalar_column_post_op(
            "__result",
            default_value=True,
            use_default_on_empty=True,
            scalar_coercion=ScalarCoercionKind.BOOL,
        ),
        auxiliary_ctes=_auxiliary_ctes_for_conflict_ref(ctx, conflict_ref_id),
    )


def _compile_all_conflicts_resolved_step(
    *,
    ctx: CompilationContext,
    conflict_table: str,
    conflict_ref_id: str,
    conflict_id_raw: SysId | None,
) -> CompiledStep[bool]:
    """Compile the merge-operation resolution completeness check."""
    from impl.common.l2050_sql_types.sql_branded_types import SqlTableName
    from impl.common.l2100_sql_grammar.domain.infra.stmt_dml_simple import SqlCountQuery
    from impl.common.l2100_sql_grammar.tree.clauses import SqlWhereClause

    cte_bound = _conflict_dependency_is_cte_bound(ctx, conflict_ref_id)
    where_expr = _all_conflicts_resolved_where_clause(
        ctx=ctx,
        conflict_table=conflict_table,
        conflict_ref_id=conflict_ref_id,
        conflict_id_raw=conflict_id_raw,
    )
    if cte_bound:
        return _compile_all_conflicts_resolved_cte_step(
            ctx=ctx,
            conflict_table=conflict_table,
            where=where_expr,
            conflict_ref_id=conflict_ref_id,
        )

    from impl.common.l2050_sql_types.sql_branded_types import SqlAliasName
    from impl.common.l2100_sql_grammar.tree.clauses import (
        SqlFrom,
        SqlSelectAlias,
        SqlSelectList,
        SqlTableAlias,
    )
    from impl.common.l2100_sql_grammar.tree.enums import AggregateKind, BinaryOp
    from impl.common.l2100_sql_grammar.tree.expr_compound import SqlAggregate
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlParam
    from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp
    from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
    from impl.common.l2100_sql_grammar.tree.statements import SqlSelect

    grammar = SqlSelect(
        select=SqlSelectList(
            [
                SqlSelectAlias(
                    SqlBinaryOp(
                        SqlAggregate(AggregateKind.COUNT_STAR),
                        BinaryOp.EQ,
                        SqlParam(0),
                    ),
                    SqlAliasName("__result"),
                ),
            ],
        ),
        from_clause=SqlFrom(SqlTableAlias(SqlTableIdent(SqlTableName(conflict_table)))),
        where=SqlWhereClause(where_expr),
    )

    __opa002_grammar_1377 = grammar
    output_shape = CompiledOutputShape((synthetic_output_field("__result", role="conflicts_resolved"),))
    column_type_hints = SqlColumnTypeHints(bool_columns=frozenset({"__result"}))
    return CompiledStep(
        output_shape=output_shape,
        grammar=__opa002_grammar_1377,
        needs_returning=True,
        result_relation=DeclaredResultRelation.from_output_shape(output_shape),
        column_type_hints=column_type_hints,
        closed_post_op=scalar_column_post_op(
            "__result",
            default_value=True,
            use_default_on_empty=True,
            scalar_coercion=ScalarCoercionKind.BOOL,
        ),
    )


