def _resolve_refetch_source_table_name(
    *,
    update_ref_id: str | None,
    conflict_table: str,
    cte_refs: dict[str, Any],
) -> str:
    """Choose the refetch source table, preferring a matching write CTE.

    Only use the CTE alias if it advertises a ``sys_id`` column. Write steps
    with ``needs_returning=False`` republish their row-count projection as a
    ``{"count": N}`` pseudo-relation, which lacks the conflict schema that the
    refetch SELECT needs. In that case fall back to the real conflict table so
    the refetch reads the freshly updated row directly.
    """
    if update_ref_id is None:
        return conflict_table

    cte_ref = cte_refs.get(update_ref_id)
    if cte_ref is None:
        return conflict_table
    columns = getattr(cte_ref, "columns", None)
    if columns is not None and "sys_id" not in columns:
        return conflict_table
    return str(cte_ref.ref_id)


