def _append_permission_context_cte(
    query_spec: QuerySpec[Any] | _UpdateQuerySpec,
    ctx: CompilationContext,
    consumed_cte_refs: list[CteReference],
) -> None:
    context_ref = query_spec.permission_context_ref
