def _collect_auxiliary_ctes_from_consumed(
    consumed_cte_refs: Sequence[CteReference],
) -> list[tuple[str, Any]] | None:
    """Deduplicate consumed CTE references into an auxiliary_ctes list."""

    def _cte_body_from_auxiliary_query(ref_id: ServerPlanRefId, auxiliary_query: Any) -> Any:
        from impl.common.l2100_sql_grammar.domain.infra.stmt_compound_write import (
            SqlStatementBatch,
        )
        from impl.common.l2100_sql_grammar.domain.versioning.stmt_cte import (
            SqlBindExternalParams,
        )

        if isinstance(auxiliary_query, SqlBindExternalParams) and isinstance(
            auxiliary_query._inner,
            SqlStatementBatch,
        ):
            statement = _cte_body_from_auxiliary_query(ref_id, auxiliary_query._inner)
            return SqlBindExternalParams(
                statement,
                auxiliary_query._params,
                external_params_first=auxiliary_query._external_params_first,
            )
        if not isinstance(auxiliary_query, SqlStatementBatch):
            return auxiliary_query
        selected_index: int | None = None
        for index, label in enumerate(auxiliary_query.result_labels_per_stmt):
            if label == ref_id:
                selected_index = index
                break
        if selected_index is None:
            for index, label in enumerate(auxiliary_query.result_labels_per_stmt):
                if auxiliary_query.collect_results_per_stmt[index] and not (isinstance(label, str) and label.endswith("__fired_marker")):
                    selected_index = index
                    break
        if selected_index is None:
            selected_index = len(auxiliary_query.statements) - 1
        statement = auxiliary_query.statements[selected_index]
        if isinstance(statement, SqlStatementBatch):
            return _cte_body_from_auxiliary_query(ref_id, statement)
        params = auxiliary_query.params_per_stmt[selected_index]
        if params:
            statement = SqlBindExternalParams(
                statement,
                params,
                external_params_first=auxiliary_query.external_params_first_per_stmt[selected_index],
            )
        return statement

    auxiliary_ctes: list[tuple[str, Any]] = []
    seen_aliases: set[str] = set()

    def _auxiliary_definition_parts(aux_def: Any) -> tuple[str, Any]:
        if hasattr(aux_def, "base_name") and hasattr(aux_def, "query"):
            columns = tuple(str(column) for column in getattr(aux_def, "columns", ()) or ())
            if columns:
                return f"{aux_def.base_name}({', '.join(columns)})", aux_def.query
            return aux_def.base_name, aux_def.query
        if hasattr(aux_def, "_name") and hasattr(aux_def, "_query"):
            return str(aux_def._name), aux_def._query
        aux_name, aux_query = aux_def
        return aux_name, aux_query

    def _append_flattened_auxiliary(name: ServerPlanRefId, query: Any, *, root_ref_id: str) -> None:
        query = _cte_body_from_auxiliary_query(ServerPlanRefId(name), query)
        split_for_outer_cte = getattr(query, "split_for_outer_cte", None)
        if callable(split_for_outer_cte):
            split_result = split_for_outer_cte()
            if not isinstance(split_result, tuple) or len(split_result) != 2:
                msg = "split_for_outer_cte() must return definitions and a final query"
                raise TypeError(msg)
            inner_aux, query = split_result
            if not isinstance(inner_aux, (list, tuple)):
                msg = "split_for_outer_cte() definitions must be a sequence"
                raise TypeError(msg)
            for inner_def in inner_aux:
                inner_name, inner_query = _auxiliary_definition_parts(inner_def)
                if inner_name == root_ref_id:
                    continue
                _append_flattened_auxiliary(ServerPlanRefId(inner_name), inner_query, root_ref_id=root_ref_id)
            query = _cte_body_from_auxiliary_query(ServerPlanRefId(name), query)
        if name in seen_aliases:
            return
        seen_aliases.add(name)
        auxiliary_ctes.append((name, query))

    for cte_ref in consumed_cte_refs:
        auxiliary_query = cte_ref.auxiliary_query
        if auxiliary_query is None:
            continue
        if cte_ref.ref_id in seen_aliases:
            continue
        _append_flattened_auxiliary(
            cte_ref.ref_id,
            auxiliary_query,
            root_ref_id=cte_ref.ref_id,
        )
    return auxiliary_ctes if auxiliary_ctes else None


