def _sparse_sys_id_arg(sys_id: object) -> SqlGrammarValue | SqlRenderable:
    if hasattr(sys_id, "render"):
        return cast(SqlRenderable, sys_id)
    unwrapped_value = unwrap_sql_param_value(sys_id)
    return SqlGrammarValue(str(unwrapped_value))


def unwrap_sql_param_value(value: object) -> object:
    """Unwrap branded values to SQL-compatible parameters."""
    unwrap_to_sql = getattr(value, "unwrap_to_sql", None)
    unwrap_to_str = getattr(value, "unwrap_to_str", None)
    unwrap_to_int = getattr(value, "unwrap_to_int", None)
    if callable(unwrap_to_sql):
        return unwrap_to_sql()
    if callable(unwrap_to_str):
        return unwrap_to_str()
    if callable(unwrap_to_int):
        return unwrap_to_int()
    if isinstance(value, (str, int, float, bool, type(None))):
        return value
    return str(value)


def unwrap_sql_param_values(values: Sequence[object]) -> tuple[object, ...]:
    """Unwrap a sequence of runtime values to SQL-compatible parameters."""
    return tuple(unwrap_sql_param_value(value) for value in values)


def raw_rows_post_op(raw_result: RawResult, hydrator: object) -> list[dict[str, Any]]:
    """Return raw driver rows as plain dictionaries."""
    del hydrator
    return [dict(cast("Any", row)) for row in raw_result]


