def build_select_one_column_masking_select(
    model_cls: type[DatabaseObjectRow],
    column_masking: tuple[SqlColumnName, list[SqlColumnName]],
    *,
    session_id_str: SessionId | None,
    output_columns: Sequence[str] | None = None,
) -> SqlRenderable:
    """Build a ``SqlSelectList`` with CASE masking for private columns."""
    from impl.common.l2050_sql_types.sql_branded_types import (
        SqlAliasName,
    )
    from impl.common.l2070_server_plan.steps._compile_helpers import session_user_id_expr
    from impl.common.l2100_sql_grammar.tree.clauses import (
        SqlSelectAlias,
    )
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef
    from impl.common.l5200_sql_query.field_reference_policy import build_sql_field_reference_policy
    from l1000_schema.schema_def import get_db_column_name

    owner_field, private_columns = column_masking
    private_set = frozenset(private_columns)
    session_user_expr = session_user_id_expr(session_id_str) if session_id_str is not None else None
    policy = build_sql_field_reference_policy(
        get_db_column=lambda field_name: get_db_column_name(model_cls, DynamicFieldName(field_name)),
        table_alias=None,
        column_masking=(owner_field, private_columns),
        column_masking_user_grammar=session_user_expr,
    )

    field_by_db_column = {
        get_db_column_name(model_cls, DynamicFieldName(field_name)): field_name for field_name in model_cls.model_fields
    }
    db_columns = tuple(output_columns) if output_columns is not None else tuple(field_by_db_column)

    items: list[SqlRenderable] = []
    for db_col in db_columns:
        field_name = field_by_db_column.get(SqlColumnName(db_col))
        if field_name is not None and field_name in private_set and session_user_expr is not None:
            items.append(
                SqlSelectAlias(
                    policy.observable_field(field_name, db_col=db_col),
                    alias=SqlAliasName(db_col),
                ),
            )
        else:
            items.append(SqlColumnRef(SqlColumnName(db_col)))

    return SqlSelectList(items)


def effective_versioned_branch_id(
    *,
    ctx: CompilationContext,
    resolved_branch_id: str | None,
    branch_cte_ref: CteReference | None,
    branch_ref_id: str | None,
) -> SqlRenderable | None:
    """Return concrete branch id or a branch-id CTE field reference."""

    if resolved_branch_id is not None:
        return SqlParam(resolved_branch_id)
    if branch_cte_ref is not None:
        field_name = "branch_id"
        if branch_ref_id is not None:
            binding = resolve_sql_visible_ref(
                ctx,
                ServerPlanRefId(branch_ref_id),
                default_field="branch_id",
            )
            if binding is None or binding.binding.ref_id != branch_cte_ref.ref_id:
                raise ProgrammingError(f"Branch ref {branch_ref_id!r} does not identify its supplied CTE publication")
            field_name = binding.field_name
        return SqlCteFieldRef(ServerPlanRefId(branch_cte_ref.ref_id), SqlColumnName(field_name))
    if branch_ref_id is not None:
        from impl.common.l2070_server_plan.steps._compile_server_ref import lower_scalar_server_ref
        from l2070_batching.server_ref import ServerRefs

        return lower_scalar_server_ref(
            ServerRefs.from_ref_id(
                ServerPlanRefId(branch_ref_id),
                variant="scalar",
                type_hint=BranchId,
            ),
            ctx,
            default_field="branch_id",
        )
    return None


def validate_revision_scalar_publication(reference: CteReference) -> None:
    """Reject multiple known rows before a backend selects a revision scalar."""
    from impl.common.l2100_sql_grammar.domain.infra.stmt_cte_helpers import SqlPublishedRowsQuery

    query = reference.auxiliary_query
    if isinstance(query, SqlPublishedRowsQuery) and len(query.published_rows) > 1:
        raise ProgrammingError("Revision scalar publication requires at most one row")


def effective_versioned_revision_id(
    *,
    ctx: CompilationContext,
    resolved_revision_id: SqlRenderable | None,
    revision_cte_ref: CteReference | None,
    revision_ref_id: ServerPlanRefId | None,
) -> SqlRenderable | None:
    """Return concrete revision id, revision CTE field, or lowered revision server ref."""

    if resolved_revision_id is not None:
        return resolved_revision_id
    if revision_cte_ref is not None:
        field_name = "revision_id"
        if revision_ref_id is not None:
            binding = resolve_sql_visible_ref(
                ctx,
                revision_ref_id,
                default_field="revision_id",
            )
            if binding is None or binding.binding.ref_id != revision_cte_ref.ref_id:
                raise ProgrammingError(f"Revision ref {revision_ref_id!r} does not identify its supplied CTE publication")
            field_name = binding.field_name
        validate_revision_scalar_publication(revision_cte_ref)
        return SqlCteFieldRef(ServerPlanRefId(revision_cte_ref.ref_id), SqlColumnName(field_name))
    if revision_ref_id is not None:
        from impl.common.l2070_server_plan.steps._compile_server_ref import lower_scalar_server_ref
        from l2070_batching.server_ref import ServerRefs

        binding = resolve_sql_visible_ref(
            ctx,
            revision_ref_id,
            default_field="revision_id",
        )
        if binding is not None:
            validate_revision_scalar_publication(binding.binding)
        return lower_scalar_server_ref(
            ServerRefs.from_ref_id(
                revision_ref_id,
                variant="scalar",
                type_hint=RevisionId,
            ),
            ctx,
            default_field="revision_id",
        )
    return None


def _literal_tip_materialization_from_cte(
    cte_ref: CteReference | None,
    *,
    allow_absent_companion: bool = False,
) -> str | None:
    if cte_ref is None:
        return None
    from l7000_versioned_schema.read_source_policy import (
        MissingBranchPublication,
        published_tip_materialization,
    )

    policy = published_tip_materialization(cte_ref, allow_absent_companion=allow_absent_companion)
    return None if policy is MissingBranchPublication.MISSING else policy.value


def bind_staged_visibility_filter_to_branch(
    ctx: CompilationContext,
    branch_id: SqlRenderable | None,
) -> CompilationContext:
    """Bind a deferred staged-visibility filter to its resolved branch expression."""
    if ctx.staged_visibility_filter is not None or branch_id is None:
        return ctx

    visibility = ctx.staged_visibility
    if visibility is None:
        if not (ctx.prefer_tip_merged and not ctx.is_write_transaction and ctx.connection_id is not None):
            return ctx
        visibility = StagedVisibility.CONNECTION
    if not isinstance(visibility, StagedVisibility):
        msg = f"Unexpected staged visibility value in the compilation context: {visibility!r}"
        raise ProgrammingError(msg)
    if visibility is StagedVisibility.CONNECTION and ctx.connection_id is None:
        msg = "Connection-scoped staged visibility requires a connection ID"
        raise ProgrammingError(msg)

    domain = ctx.versioning_domain
    if domain is None:
        msg = "Deferred staged visibility requires a versioning domain in the compilation context"
        raise ProgrammingError(msg)

    from impl.common.l2100_sql_grammar.domain.versioning.staged_visibility_filter import (
        SqlStagedVisibilityFilter,
    )

    return replace(
        ctx,
        staged_visibility_filter=SqlStagedVisibilityFilter(
            visibility=visibility,
            staged_commit_id=ctx.staged_commit_id,
            connection_id=ctx.connection_id,
            branch_id=branch_id,
            staged_commits_table=get_table_name(domain.staged_commit_model),
        ),
    )


def prepare_versioned_compile_inputs(
    ctx: CompilationContext,
    *,
    resolved_branch_id: str | None,
    branch_cte_ref: CteReference | None,
    branch_ref_id: str | None,
    revision_cte_ref: CteReference | None = None,
    revision_ref_id: ServerPlanRefId | None = None,
    resolved_revision_id: SqlRenderable | None = None,
    require_revision_override: bool = False,
    query_spec: Any = None,
    step_name: str,
) -> VersionedCompileInputs:
    """Fold resolved branch/revision state into compile inputs."""

    branch_id_override = effective_versioned_branch_id(
        ctx=ctx,
        resolved_branch_id=resolved_branch_id,
        branch_cte_ref=branch_cte_ref,
        branch_ref_id=branch_ref_id,
    )

    revision_id_override = effective_versioned_revision_id(
        ctx=ctx,
        resolved_revision_id=resolved_revision_id,
        revision_cte_ref=revision_cte_ref,
        revision_ref_id=revision_ref_id,
    )
    effective_ctx = bind_staged_visibility_filter_to_branch(ctx, branch_id_override)
    lazy_tip_materialization = ctx.lazy_branch_tip_materialization
    if lazy_tip_materialization is not None and lazy_tip_materialization.ref_id is not None:
        from l7000_versioned_schema.read_source_policy import persisted_tip_materialization
        from l7000_versioned_schema.versioned_schema import BranchTipMaterialization

        persisted_tip = persisted_tip_materialization(ctx)
        tip_is_materialized = persisted_tip is BranchTipMaterialization.MATERIALIZED
        effective_ctx = replace(
            effective_ctx,
            branch_tip_materialized=tip_is_materialized,
        )
    else:
        branch_tip = _literal_tip_materialization_from_cte(branch_cte_ref)
        revision_tip = _literal_tip_materialization_from_cte(
            revision_cte_ref,
            allow_absent_companion=True,
        )
        tip_materialization = branch_tip or revision_tip
        if tip_materialization is not None:
            effective_ctx = replace(
                effective_ctx,
                branch_tip_materialized=tip_materialization == "materialized",
            )
        elif lazy_tip_materialization is not None:
            effective_ctx = replace(effective_ctx, branch_tip_materialized=False)

    from l7000_versioned_schema.read_source_policy import is_current_branch_read

    effective_revision_id = revision_id_override
    if (
        not require_revision_override
        and effective_ctx.explicit_revision_id is None
        and not effective_ctx.is_write_transaction
        and (effective_ctx.prefer_tip_strategy or is_current_branch_read(effective_ctx))
        and effective_ctx.branch_tip_materialized
    ):
        # A materialized read context may publish the branch tip revision id as data.
        # Treating that value as a historical override would force sparse ancestry
        # SQL even though the read is anchored at the current materialized tip.
        effective_revision_id = None

    if require_revision_override and effective_revision_id is None and not effective_ctx.prefer_tip_strategy:
        raise NotImplementedError(f"{step_name} requires a concrete revision_id override")

    return VersionedCompileInputs(
        effective_ctx=effective_ctx,
        branch_id_override=branch_id_override,
        revision_id_override=effective_revision_id,
    )


def compile_versioned_read_select_one_stmt(
    model_cls: type[DatabaseObjectRow],
    sparse_table_name: str,
    *,
    branch_id: object | None,
    branch_ref_id: str | None,
    revision_ref: ScalarServerRef[object] | None,
    revision_id: object | None,
    sys_id: ScalarServerRef[object],
    type_ids: list[str] | None,
    include_deleted: bool,
    ctx: CompilationContext,
    ancestor_cte_name: str = "_visible_ancestors",
    staged_table_name: str | None = None,
    tip_table_name: str | None = None,
    common_columns: Sequence[str] | None = None,
) -> SqlRenderable:
    """Compile read-path versioned ``select_one`` grammar from resolved inputs."""
    from impl.common.l2070_server_plan.steps._compile_server_ref import lower_scalar_server_ref
    from impl.common.l2070_server_plan.steps._versioned_routing import get_versioned_read_info
    from impl.common.l2100_sql_grammar.domain.versioning.stmt_sparse import (
        SqlSelectStarSparseAncestryVersioned,
    )
    from impl.common.l2100_sql_grammar.domain.versioning.stmt_versioned import SqlStagedTipUnionLookup
    from impl.common.l2100_sql_grammar.tree.clauses import SqlFrom
    from impl.common.l2100_sql_grammar.tree.expr_compound import SqlSubquery
    from l1100_exceptions import exceptions as db_exc

    if branch_id is None:
        raise db_exc.ProgrammingError(
            "branch_id not resolved — ResolveBranchForRevisionStep must execute before VersionedReadSelectOneStep",
        )
    branch_id_val: SqlGrammarValue | SqlRenderable
    if isinstance(branch_id, CteReference):
        real_cte = ctx.cte_refs.get(branch_ref_id or "")
        cte_alias = real_cte.ref_id if isinstance(real_cte, CteReference) else branch_id.ref_id
        branch_id_val = cast(
            "SqlRenderable",
            SqlSubquery(
                query=SqlSelect(
                    select=SqlSelectList([SqlColumnRef(SqlColumnName("branch_id"))]),
                    from_clause=SqlFrom(SqlTableIdent(SqlTableName(cte_alias))),
                    limit=1,
                ),
            ),
        )
    else:
        branch_id_val = _sparse_sys_id_arg(branch_id)

    from l7000_versioned_schema.read_source_policy import is_current_branch_read

    lowered_sys_id = lower_scalar_server_ref(sys_id, ctx)
    if revision_id is None and revision_ref is None and ctx.lazy_revision is not None:
        revision_ref = ctx.lazy_revision
    if (
        ctx.prefer_tip_strategy
        and ctx.branch_tip_materialized
        and not ctx.prefer_tip_merged
        and (is_current_branch_read(ctx) or ctx.selected_branch_policy_ref_id is not None)
        and not ctx.is_write_transaction
        and ctx.staged_commit_id is None
        and ctx.connection_id is None
        and getattr(ctx.txn, "_staged_commit_id", None) is None
    ):
        from impl.common.l2100_sql_grammar.tree.expr_compound import SqlCast
        from l1000_schema.typed_field import SqlCastTargetType

        info = get_versioned_read_info(model_cls)
        conditions: list[SqlRenderable] = [
            SqlBinaryOp(
                SqlColumnRef(SqlColumnName("branch_id")),
                BinaryOp.EQ,
                SqlParam(branch_id_val) if isinstance(branch_id_val, str) else branch_id_val,
            ),
            SqlBinaryOp(SqlColumnRef(SqlColumnName("sys_id")), BinaryOp.EQ, lowered_sys_id),
        ]
        if type_ids:
            conditions.append(SqlIn(SqlColumnRef(SqlColumnName("type_name")), tuple(SqlParam(value) for value in type_ids)))
        source_columns: list[SqlRenderable] = [SqlStar()]
        if tip_table_name is not None:
            source_columns = (
                [
                    SqlColumnRef(SqlColumnName(column))
                    for column in dict.fromkeys((*common_columns, "sys_revision_id"))
                    if column not in {"sys_staged_commit_id", "sys_deleted"}
                ]
                if common_columns is not None
                else [SqlStar()]
            )
        return SqlSelect(
            SqlSelectList(
                [
                    *source_columns,
                    SqlSelectAlias(
                        SqlCast(
                            SqlInlineLiteral(None),
                            SqlCastTargetType(base_type="UUID"),
                        ),
                        SqlAliasName("sys_staged_commit_id"),
                    ),
                    SqlSelectAlias(SqlInlineLiteral(False), SqlAliasName("sys_deleted")),
                ]
            ),
            from_=SqlTableName(tip_table_name or info.tip_table),
            where=sql_and(*conditions),
            limit=1,
        )

    prefer_tip_merged = ctx.prefer_tip_merged and ctx.branch_tip_materialized and revision_id is None and revision_ref is None
    if prefer_tip_merged:
        info = get_versioned_read_info(model_cls)
        columns = tuple(common_columns or info.common_columns)
        if include_deleted and "sys_deleted" not in columns:
            columns = (*columns, "sys_deleted")
        model_identity_column = str(get_db_column_name(model_cls, DynamicFieldName("sys_id")))
        lookup_source_columns = tuple("sys_id" if column == model_identity_column else column for column in columns)
        return SqlStagedTipUnionLookup(
            staged_table=SqlTableName(staged_table_name or info.staged_table),
            tip_table=SqlTableName(tip_table_name or info.tip_table),
            columns=columns,
            source_columns=lookup_source_columns,
            branch_id=branch_id_val,
            sys_id=lowered_sys_id,
            type_ids=type_ids,
            staged_visibility_filter=getattr(ctx, "staged_visibility_filter", None),
        )

    if revision_id is None and revision_ref is None:
        raise db_exc.ProgrammingError("revision_id not resolved — preprocess must run before compile")

    if revision_ref is not None and not (isinstance(revision_ref, ServerRef) and revision_ref.ref_id is None and revision_id is not None):
        revision_id_val = _sparse_sys_id_arg(lower_scalar_server_ref(revision_ref, ctx))
    else:
        revision_id_val = _sparse_sys_id_arg(revision_id)

    sys_id_condition: SqlRenderable = SqlBinaryOp(
        SqlColumnRef(SqlColumnName("sys_id")),
        BinaryOp.EQ,
        lowered_sys_id,
    )
    extra_where = sys_id_condition
    if type_ids:
        type_condition = SqlIn(
            SqlColumnRef(SqlColumnName("type_name")),
            tuple(SqlParam(type_name) for type_name in type_ids),
        )
        extra_where = sql_and(sys_id_condition, type_condition)
    return SqlSelectStarSparseAncestryVersioned(
        table=SqlTableName(sparse_table_name),
        revision_parents_table=SqlTableName("sys_revision_parents"),
        branch_id=branch_id_val,
        revision_id=revision_id_val,
        include_deleted=include_deleted,
        extra_where=extra_where,
        ancestor_cte_name=SqlCteName(ancestor_cte_name),
        limit=1,
        include_framework_aliases=not sparse_table_name.startswith("__poly_union_"),
    )


def compile_delete_many_grammar(
    model_cls: type[DatabaseObjectRow],
    sys_ids: Sequence[object],
    ctx: CompilationContext,
    *,
    returning: bool,
    returning_columns: Sequence[str] | None = None,
    resolved_user_id: PermissionUserIdSource = None,
    user_id_ref_id: ServerPlanRefId | None = None,
    permission_context_ref: ServerPlanRefId | None = None,
    permission_context_type: type[ResolvedSessionContext] | None = None,
) -> tuple[SqlDelete, tuple[object, ...]]:
    """Compile bulk delete grammar for literal ID lists, including empty lists."""
    table, where_clause, params = compile_delete_many_predicate(
        model_cls,
        sys_ids,
        ctx,
        resolved_user_id=resolved_user_id,
        user_id_ref_id=user_id_ref_id,
        permission_context_ref=permission_context_ref,
        permission_context_type=permission_context_type,
    )
    returning_items = None
    if returning:
        columns = tuple(
            returning_columns
            or tuple(get_db_column_name(model_cls, DynamicFieldName(field_name)) for field_name in model_cls.model_fields)
        )
        returning_items = tuple(SqlColumnRef(SqlColumnName(column)) for column in columns)
    grammar = SqlDelete(
        table=table,
        where=where_clause,
        returning=SqlReturningClause(returning_items) if returning_items is not None else None,
    )
    return grammar, params


def compile_delete_many_predicate(
    model_cls: type[DatabaseObjectRow],
    sys_ids: Sequence[object],
    ctx: CompilationContext,
    *,
    resolved_user_id: PermissionUserIdSource = None,
    user_id_ref_id: ServerPlanRefId | None = None,
    permission_context_ref: ServerPlanRefId | None = None,
    permission_context_type: type[ResolvedSessionContext] | None = None,
) -> tuple[SqlTableIdent, SqlConditionalClause, tuple[object, ...]]:
    """Build the shared table and predicate for bulk delete/readback operations."""
    from impl.common.l2070_server_plan.steps._compile_write import _check_write_compilable
    from l1000_schema.table_utils import get_table_name
    from impl.common.l2070_server_plan.steps._compile_helpers import (
        compile_dml_permission_filter,
    )

    _check_write_compilable(model_cls, ctx)

    params = unwrap_sql_param_values(sys_ids)
    table = SqlTableIdent(get_table_name(model_cls))
    if params:
        where_expr: SqlRenderable = SqlInInlineList(
            SqlColumnRef(SqlColumnName("sys_id")),
            params,
        )
        params = ()
    else:
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SQL_EXPR_ALWAYS_FALSE

        where_expr = SQL_EXPR_ALWAYS_FALSE
    permission_expr = compile_dml_permission_filter(
        model_cls,
        ctx,
        target_table_name=get_table_name(model_cls),
        action="delete",
        resolved_user_id=resolved_user_id,
        user_id_ref_id=user_id_ref_id,
        permission_context_ref=permission_context_ref,
        permission_context_type=permission_context_type,
    )
    if permission_expr is not None:
        where_expr = sql_and(where_expr, permission_expr)
    return table, SqlWhereClause(where_expr), params


def _build_pk_select_clause(pk_db_col: str, *, qualifier: str | None = None) -> SqlRenderable:
    """Build ``SELECT sys_id`` for ``UPDATE ... WHERE IN (subquery)``."""
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef

    return SqlSelectList([SqlColumnRef(SqlColumnName(pk_db_col), qualifier=qualifier)])


def _build_simple_from(table: str) -> SqlRenderable:
    """Build a simple ``FROM table`` clause."""
    from impl.common.l2100_sql_grammar.tree.clauses import SqlFrom, SqlTableAlias
    from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent

    return SqlFrom(SqlTableAlias(SqlTableIdent(SqlTableName(table))))


def build_update_where(
    query_spec: _UpdateQuerySpec,
    *,
    planning_catalog: PlanningCatalog | None,
) -> SqlConditionalClause | None:
    """Build UPDATE WHERE grammar, preserving LIMIT/ORDER BY semantics."""
    from impl.common.l2100_sql_grammar.tree.clauses import SqlForUpdateClause, SqlWhereClause
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef
    from impl.common.l2100_sql_grammar.tree.statements import SqlSelect
    from impl.common.l5200_sql_query.query_grammar import QueryGrammarBuilder
    from l1000_schema.schema_def import get_db_column_name
    from l1000_schema.table_utils import get_table_name

    from impl.common.l5200_sql_query.query_grammar import _apply_implicit_polymorphic_type_filter

    query_spec_for_grammar = cast(
        Any,
        _apply_implicit_polymorphic_type_filter(cast(Any, query_spec)),
    )
    has_limit = query_spec.limit is not None
    has_order = bool(query_spec.order_by)
    has_joins = bool(query_spec.joins)
    # UPDATE predicates need an explicit base-table qualifier whenever a join
    # introduces columns with the same names (for example request and
    # observation fence fields).
    builder = QueryGrammarBuilder(
        query_spec_for_grammar,
        table_alias=get_table_name(query_spec.model_cls) if has_joins else None,
        planning_catalog=planning_catalog,
    )

    if not has_limit and not has_order and not has_joins:
        where_clause: SqlConditionalClause | None = builder.build_where_clause()
        return where_clause

    pk_db_col = str(get_db_column_name(query_spec.model_cls, DynamicFieldName("sys_id")))
    target_table = get_table_name(query_spec.model_cls)
    pk_col = SqlColumnRef(
        SqlColumnName(pk_db_col),
        qualifier=target_table if has_joins else None,
    )
    # Ordered/limited updates are compiled through a primary-key subquery. The
    # lock clause must live on that candidate subquery: dropping it here allows
    # two PostgreSQL transactions to select and update the same candidate.
    # SQLite renders FOR UPDATE as a no-op and serializes write transactions.
    for_update = None
    if query_spec.for_update:
        for_update = SqlForUpdateClause(
            nowait=query_spec.for_update_nowait,
            skip_locked=query_spec.for_update_skip_locked,
        )
    subquery = SqlSelect(
        select=_build_pk_select_clause(pk_db_col, qualifier=target_table if has_joins else None),
        from_=builder._build_from_clause(),
        joins=(builder._build_join_clauses() if has_joins else ()),
        where=builder.build_where_clause(),
        order_by=builder._build_order_by_clause(),
        limit=query_spec.limit,
        offset=query_spec.offset,
        for_update=for_update,
    )
    return SqlWhereClause(SqlIn(pk_col, subquery))


def _expression_uses_joined_owner(value: object, model_cls: type[DatabaseObjectRow]) -> bool:
    """Return whether a typed assignment expression reads a joined model."""
    from l1000_schema.typed_field import Expression, Field

    if isinstance(value, Field):
        return value.owner is not None and value.owner is not model_cls
    if not isinstance(value, Expression):
        return False
    owner = getattr(value, "owner", None)
    if owner is not None and owner is not model_cls:
        return True
    nested = (value.left, value.right, value.value, *value.args)
    return any(_expression_uses_joined_owner(item, model_cls) for item in nested if item is not None)


def _joined_update_assignment_subquery(
    model_cls: type[DatabaseObjectRow],
    query_spec: _UpdateQuerySpec,
    source_value: object,
    *,
    planning_catalog: PlanningCatalog | None,
) -> SqlRenderable:
    """Select one joined source value correlated to the updated target row."""
    from impl.common.l2100_sql_grammar.tree.clauses import SqlFrom, SqlTableAlias, SqlWhereClause
    from impl.common.l2100_sql_grammar.tree.enums import BinaryOp
    from impl.common.l2100_sql_grammar.tree.expr_compound import SqlSubquery
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef
    from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp
    from impl.common.l2100_sql_grammar.tree.statements import SqlSelect
    from impl.common.l5200_sql_query.expression_grammar import ExpressionToGrammar
    from impl.common.l5200_sql_query.query_grammar import QueryGrammarBuilder, _apply_implicit_polymorphic_type_filter
    from l1000_schema.schema_def import get_db_column_name
    from l1000_schema.table_utils import get_table_name
    from l1000_schema.typed_field import Expression, Field

    if not isinstance(source_value, Expression | Field):
        msg = "joined update assignment requires a typed source expression"
        raise TypeError(msg)
    if not _expression_uses_joined_owner(source_value, model_cls):
        msg = "joined update assignment expression must read a joined model"
        raise ValueError(msg)

    inner_alias = f"{get_table_name(model_cls)}_assignment_source"
    grammar_spec = cast(Any, _apply_implicit_polymorphic_type_filter(cast(Any, query_spec)))
    builder = QueryGrammarBuilder(grammar_spec, table_alias=inner_alias, planning_catalog=planning_catalog)
    pk_db_col = str(get_db_column_name(model_cls, DynamicFieldName("sys_id")))
    correlation = SqlBinaryOp(
        SqlColumnRef(SqlColumnName(pk_db_col), qualifier=inner_alias),
        BinaryOp.EQ,
        SqlColumnRef(SqlColumnName(pk_db_col), qualifier=get_table_name(model_cls)),
    )
    base_where = builder.build_where_clause()
    condition = correlation if base_where is None else sql_and(base_where.condition, correlation)
    source_expr = Expression(field=source_value.name, owner=source_value.owner) if isinstance(source_value, Field) else source_value
    select = SqlSelect(
        select=SqlSelectList(
            [ExpressionToGrammar(model_cls, table_alias=inner_alias).convert(source_expr)],
        ),
        from_=SqlFrom(
            SqlTableAlias(
                SqlTableIdent(SqlTableName(get_table_name(model_cls))),
                SqlAliasName(inner_alias),
            ),
        ),
        joins=builder._build_join_clauses(),
        where=SqlWhereClause(condition),
        limit=1,
    )
    return SqlSubquery(select)


def _build_query_update_set_items(
    model_cls: type[DatabaseObjectRow],
    updates: dict[str, Any],
    *,
    query_spec: _UpdateQuerySpec | None,
    planning_catalog: PlanningCatalog | None,
    backend_type: BackendType | None,
) -> list[SqlSetItem]:
    """Build SET items for query-update helpers."""

    from impl.common.l2070_server_plan.steps._compile_helpers import cast_postgres_expr_for_db_column
    from impl.common.l2100_sql_grammar.tree.clauses import SqlSetItem
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlParam
    from impl.common.l2300_json_serialization import get_json_columns, serialize_json_fields
    from impl.common.l5200_sql_query.expression_grammar import ExpressionToGrammar
    from l1000_schema.schema_def import get_db_column_name
    from l1000_schema.typed_field import Expression, Field
    from vector_types import is_embedding_annotation

    expr_converter = ExpressionToGrammar(model_cls)
    json_columns = get_json_columns(model_cls)
    if planning_catalog is None:
        from l2070_batching.planning_catalog import build_write_metadata_plan

        write_plan = build_write_metadata_plan(model_cls)
    else:
        write_plan = planning_catalog.write_metadata_for_model(model_cls)
    set_items: list[SqlSetItem] = []
    for field_name, raw_value in updates.items():
        db_col = get_db_column_name(model_cls, DynamicFieldName(field_name))
        value = raw_value
        if isinstance(value, Field | Expression) and _expression_uses_joined_owner(value, model_cls):
            if query_spec is None or not query_spec.joins:
                msg = "joined source-field assignment requires a joined update query"
                raise ValueError(msg)
            set_items.append(
                SqlSetItem(
                    SqlColumnName(db_col),
                    _joined_update_assignment_subquery(
                        model_cls,
                        query_spec,
                        value,
                        planning_catalog=planning_catalog,
                    ),
                ),
            )
            continue
        if isinstance(value, Field):
            value = Expression(field=value.name, owner=value.owner)
        if isinstance(value, Expression):
            set_items.append(SqlSetItem(SqlColumnName(db_col), expr_converter.convert(value)))
            continue
        if isinstance(value, SqlRenderable):
            set_items.append(SqlSetItem(SqlColumnName(db_col), value))
            continue
        model_field = model_cls.model_fields.get(str(field_name))
        if field_name in json_columns:
            value = serialize_json_fields(model_cls, {field_name: value})[field_name]
        if model_field is not None and isinstance(value, bytes) and is_embedding_annotation(model_field.annotation):
            from l5200_vector_index.embedding_type import EmbeddingType

            value = EmbeddingType(value)
        sql_unwrapper = getattr(value, "unwrap_to_sql", None)
        string_unwrapper = getattr(value, "unwrap_to_str", None)
        if callable(sql_unwrapper):
            value = sql_unwrapper()
        elif callable(string_unwrapper):
            value = string_unwrapper()
        assignment = cast_postgres_expr_for_db_column(
            backend_type=backend_type,
            write_plan=write_plan,
            db_column=db_col,
            expr=SqlParam(value),
        )
        set_items.append(SqlSetItem(SqlColumnName(db_col), assignment))

    if hasattr(model_cls, "model_fields") and "updated_at" in model_cls.model_fields:
        updated_col = get_db_column_name(model_cls, DynamicFieldName("updated_at"))
        existing_cols = {str(item._column) for item in set_items}
        if updated_col not in existing_cols:
            set_items.append(SqlSetItem(SqlColumnName(updated_col), SqlParam(datetime.now(UTC))))

    if not set_items:
        raise ValueError("QueryUpdateStep: no columns to update")
    return set_items


def _require_unversioned_query_update_model(
    model_cls: type[DatabaseObjectRow],
    *,
    step_name: str,
) -> None:
    if hasattr(model_cls, "staged_commit_id"):
        msg = f"{step_name} must route versioned models through versioned update lowering"
        raise NotImplementedError(msg)


def _require_query_update_spec(
    query_spec: object,
    *,
    step_name: str,
) -> _UpdateQuerySpec:
    if _is_update_query_spec(query_spec):
        return query_spec
    msg = f"{step_name} requires a query spec with model/limit/order/filter fields"
    raise TypeError(msg)


def _query_update_user_binding_requires_auxiliary_cte(
    resolved_user_id: CteReference,
    ctx: CompilationContext,
) -> bool:
    """Return whether permission SQL still needs the user binding as a CTE."""
    from impl.common.l2100_sql_grammar.domain.infra.stmt_cte_helpers import (
        SqlPublishedRowsQuery,
    )

    return not (
        ctx.backend_profile.traits.permission_user_transport is PermissionUserTransport.MATERIALIZED_VALUE
        and isinstance(resolved_user_id.auxiliary_query, SqlPublishedRowsQuery)
    )


def _query_update_count_relation(update_stmt: Any, *, cte_name: SqlCteName) -> Any:
    from impl.common.l2050_sql_types.sql_branded_types import SqlAliasName, SqlTableName
    from impl.common.l2100_sql_grammar.domain.versioning.stmt_cte import SqlDmlWithReturningOne
    from impl.common.l2100_sql_grammar.tree.clauses import SqlSelectAlias, SqlSelectList
    from impl.common.l2100_sql_grammar.tree.enums import AggregateKind
    from impl.common.l2100_sql_grammar.tree.expr_compound import SqlAggregate
    from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
    from impl.common.l2100_sql_grammar.tree.statements import SqlCte, SqlSelect

    count_select = SqlSelect(
        select=SqlSelectList(
            [
                SqlSelectAlias(
                    SqlAggregate(AggregateKind.COUNT_STAR),
                    alias=SqlAliasName("count"),
                ),
            ],
        ),
        from_=SqlTableIdent(SqlTableName(cte_name)),
    )
    return SqlCte(
        [(cte_name, SqlDmlWithReturningOne(update_stmt))],
        count_select,
    )


def _query_update_count_batch(update_stmt: Any, *, count_expr_sql: str) -> Any:
    from impl.common.l2100_sql_grammar.domain.infra.stmt_compound_write import (
        SqlStatementBatch,
        SqlStatementBatchCategory,
    )
    from impl.common.l2100_sql_grammar.domain.infra.stmt_cte_helpers import SqlSelectExpressions
    from impl.common.l2100_sql_grammar.domain.infra.stmt_dml_simple import SqlRawExpression

    count_select = SqlSelectExpressions(
        [(SqlRawExpression(SqlGrammarText(count_expr_sql)), "count")],
        bigint_columns=frozenset({"count"}),
    )
    return SqlStatementBatch(
        [update_stmt, count_select],
        category=SqlStatementBatchCategory.ORDERED_SEMANTIC,
        needs_returning_per_stmt=[False, True],
        collect_results_per_stmt=[False, True],
    )


def _query_update_driver_rowcount_batch(update_stmt: Any) -> Any:
    """Publish the driver's affected-row count without a state-clobbering query."""
    from impl.common.l2100_sql_grammar.domain.infra.stmt_compound_write import (
        SqlStatementBatch,
        SqlStatementBatchCategory,
        SqlStatementKind,
    )

    return SqlStatementBatch(
        [update_stmt],
        category=SqlStatementBatchCategory.ORDERED_SEMANTIC,
        needs_returning_per_stmt=[False],
        collect_results_per_stmt=[True],
        statement_kinds_per_stmt=[SqlStatementKind.DML],
    )


def compile_query_update_step(
    model_cls: type[DatabaseObjectRow],
    query_spec: object | None,
    updates: dict[str, Any],
    ctx: CompilationContext,
    *,
    step_ref_id: ServerPlanRefId,
    resolved_user_id: PermissionUserIdSource,
    updated_rows_cte_name: SqlCteName | None = None,
) -> CompiledStep[int]:
    """Compile ``QueryUpdateStep`` while keeping step-local compile pure."""
    from impl.common.l2070_server_plan.steps._compile_helpers import (
        _combine_where,
        _has_server_ref_in_filters,
        _resolve_server_ref_filters_to_cte,
        attach_runtime_permission_grammar,
        materialize_permission_user_id,
    )
    from impl.common.l2100_sql_grammar.tree.clauses import SqlWhereClause
    from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
    from impl.common.l2100_sql_grammar.tree.statements import SqlUpdate
    from l1000_schema.table_utils import get_table_name
    from l2070_batching.output_shape import DeclaredResultRelation
    from l2070_batching.sql_column_type_hints import SqlColumnTypeHints

    _require_unversioned_query_update_model(model_cls, step_name="QueryUpdateStep")
    if isinstance(resolved_user_id, CteReference):
        resolved_user_id = materialize_permission_user_id(resolved_user_id, ctx)

    query_spec = deepcopy(query_spec)
    table = SqlTableIdent(get_table_name(model_cls))
    cte_where_exprs: list[Any] = []
    consumed_cte_refs: list[CteReference] = []
    if query_spec is not None:
        if _has_server_ref_in_filters(query_spec):
            cte_where_exprs = _resolve_server_ref_filters_to_cte(
                query_spec,
                ctx,
                table_alias=get_table_name(model_cls),
                consumed_cte_refs=consumed_cte_refs,
            )
        query_spec = attach_runtime_permission_grammar(
            query_spec,
            model_cls,
            ctx,
            resolved_user_id=resolved_user_id,
            action="update",
        )
        query_spec = _require_query_update_spec(query_spec, step_name="QueryUpdateStep")
        _append_permission_context_cte(query_spec, ctx, consumed_cte_refs)

    if isinstance(resolved_user_id, CteReference) and _query_update_user_binding_requires_auxiliary_cte(
        resolved_user_id,
        ctx,
    ):
        consumed_cte_refs.append(resolved_user_id)

    set_items = _build_query_update_set_items(
        model_cls,
        updates,
        query_spec=query_spec,
        planning_catalog=ctx.planning_catalog,
        backend_type=ctx.backend_type,
    )
    where_clause = build_update_where(query_spec, planning_catalog=ctx.planning_catalog) if query_spec is not None else None
    if cte_where_exprs:
        base_cond = where_clause.condition if where_clause is not None else None
        combined = _combine_where(base_cond, cte_where_exprs)
        where_clause = SqlWhereClause(combined) if combined else None
    assert not (where_clause is None and query_spec is not None and query_spec.filters), (
        "QueryUpdateStep: filters exist but WHERE clause was not compiled. This would produce UPDATE without WHERE — data corruption."
    )

    grammar = SqlUpdate(table=table, set_items=set_items, where=where_clause)
    result_transport = ctx.backend_profile.traits.dml_result_transport
    if result_transport is DmlResultTransport.STATEMENT_CHANGE_FUNCTION:
        grammar = _query_update_count_batch(grammar, count_expr_sql="changes()")
    elif result_transport is DmlResultTransport.DRIVER_ROWCOUNT:
        grammar = _query_update_driver_rowcount_batch(grammar)
    elif result_transport is DmlResultTransport.RETURNING_RELATION:
        grammar = _query_update_count_relation(
            grammar,
            cte_name=(
                updated_rows_cte_name
                if updated_rows_cte_name is not None
                else SqlCteName(safe_index_name(f"{str(table.name)}_updated_rows_{step_ref_id}"))
            ),
        )
    auxiliary_ctes = _collect_auxiliary_ctes_from_consumed(consumed_cte_refs)
    output_shape = output_shape_from_mappings(
        (("count", "count", False),),
        is_model_backed=False,
    )
    return CompiledStep(
        output_shape=output_shape,
        grammar=grammar,
        needs_returning=True,
        auxiliary_ctes=auxiliary_ctes,
        result_relation=DeclaredResultRelation.from_output_shape(output_shape),
        column_type_hints=SqlColumnTypeHints(bigint_columns=frozenset({"count"})),
        closed_post_op=scalar_column_post_op(
            "count",
            default_value=0,
            use_default_on_empty=True,
            scalar_coercion=ScalarCoercionKind.INT,
        ),
    )


def compile_query_update_returning_step(
    model_cls: type[DatabaseObjectRow],
    query_spec: object | None,
    updates: dict[str, Any],
    ctx: CompilationContext,
    *,
    resolved_user_id: PermissionUserIdSource,
    closed_post_op: CompiledPostOp,
    returning_projections: Sequence[object] | None = None,
    readback_query_spec: object | None = None,
    publication_ref_id: ServerPlanRefId,
    publication_contract: CtePublicationContract,
    permission_action: str = "update",
) -> CompiledStep[object]:
    """Compile ``QueryUpdateReturningStep`` while keeping step-local compile pure."""
    from impl.common.l2070_server_plan.steps._compile_helpers import (
        _combine_where,
        _has_server_ref_in_filters,
        _resolve_server_ref_filters_to_cte,
        attach_runtime_permission_grammar,
        materialize_permission_user_id,
    )
    from impl.common.l2100_sql_grammar.tree.clauses import SqlWhereClause
    from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
    from impl.common.l2100_sql_grammar.tree.statements import SqlUpdate
    from l1000_schema.table_utils import get_table_name
    from l2070_batching.output_shape import DeclaredResultRelation
    from l2070_batching.sql_column_type_hints import model_sql_column_type_hints

    _require_unversioned_query_update_model(model_cls, step_name="QueryUpdateReturningStep")
    if isinstance(resolved_user_id, CteReference):
        resolved_user_id = materialize_permission_user_id(resolved_user_id, ctx)

    query_spec = deepcopy(query_spec)
    table = SqlTableIdent(get_table_name(model_cls))
    cte_where_exprs: list[Any] = []
    consumed_cte_refs: list[CteReference] = []
    if query_spec is not None:
        if _has_server_ref_in_filters(query_spec):
            cte_where_exprs = _resolve_server_ref_filters_to_cte(
                query_spec,
                ctx,
                table_alias=get_table_name(model_cls),
                consumed_cte_refs=consumed_cte_refs,
            )
        query_spec = attach_runtime_permission_grammar(
            query_spec,
            model_cls,
            ctx,
            resolved_user_id=resolved_user_id,
            action=permission_action,
        )
        query_spec = _require_query_update_spec(query_spec, step_name="QueryUpdateReturningStep")
        _append_permission_context_cte(query_spec, ctx, consumed_cte_refs)
    if isinstance(resolved_user_id, CteReference) and _query_update_user_binding_requires_auxiliary_cte(
        resolved_user_id,
        ctx,
    ):
        consumed_cte_refs.append(resolved_user_id)
    set_items = _build_query_update_set_items(
        model_cls,
        updates,
        query_spec=query_spec,
        planning_catalog=ctx.planning_catalog,
        backend_type=ctx.backend_type,
    )
    where_clause = build_update_where(query_spec, planning_catalog=ctx.planning_catalog) if query_spec is not None else None
    if cte_where_exprs:
        base_cond = where_clause.condition if where_clause is not None else None
        combined = _combine_where(base_cond, cte_where_exprs)
        where_clause = SqlWhereClause(combined) if combined else None
    assert not (where_clause is None and query_spec is not None and query_spec.filters), (
        "QueryUpdateReturningStep: filters exist but WHERE clause was not compiled."
    )

    returning_items = _build_query_update_returning_items(model_cls, returning_projections)
    supports_returning = ctx.sql_render_dialect().supports_returning()
    grammar: SqlRenderable = SqlUpdate(
        table=table,
        set_items=set_items,
        where=where_clause,
        returning=SqlReturningClause(returning_items) if supports_returning else None,
    )
    sql_visible_publication_query: SqlRenderable | None = None
    if not supports_returning:
        from impl.common.l2100_sql_grammar.domain.infra.stmt_compound_write import (
            SqlStatementBatch,
            SqlStatementBatchCategory,
        )
        from impl.common.l2100_sql_grammar.tree.statements import SqlSelect

        readback_where = where_clause
        if readback_query_spec is not None:
            readback_spec = _require_query_update_spec(
                deepcopy(readback_query_spec),
                step_name="QueryUpdateReturningStep.readback",
            )
            readback_where = build_update_where(
                readback_spec,
                planning_catalog=ctx.planning_catalog,
            )
        readback = SqlSelect(
            select=returning_items,
            from_=table,
            where=readback_where,
        )
        grammar = SqlStatementBatch(
            [grammar, readback],
            category=SqlStatementBatchCategory.ORDERED_SEMANTIC,
            needs_returning_per_stmt=[False, True],
            collect_results_per_stmt=[False, True],
        )
        sql_visible_publication_query = readback
    auxiliary_ctes = _collect_auxiliary_ctes_from_consumed(consumed_cte_refs)
    output_shape = _query_update_returning_output_shape(model_cls, returning_projections)
    column_type_hints = model_sql_column_type_hints(model_cls, output_shape.cte_output_columns)
    if column_type_hints is None:
        msg = f"Could not resolve SQL column type hints for {model_cls.__name__} update-returning output."
        # Query-returning producers must publish complete SQL type hints.
        raise ProgrammingError(msg)
    __opa002_grammar_630 = grammar
    return CompiledStep(
        output_shape=output_shape,
        grammar=__opa002_grammar_630,
        needs_returning=True,
        compiled_sql_publication=compiled_sql_publication_from_query(
            ref_id=publication_ref_id,
            query=sql_visible_publication_query,
            contract=publication_contract,
        ),
        auxiliary_ctes=auxiliary_ctes,
        closed_post_op=closed_post_op,
        result_relation=DeclaredResultRelation.from_output_shape(output_shape),
        column_type_hints=column_type_hints,
    )


def query_update_returning_output_columns(
    model_cls: type[DatabaseObjectRow],
    returning_projections: Sequence[object] | None,
) -> tuple[str, ...]:
    """Return the DB columns an update-returning statement actually emits.

    Producers must declare exactly these columns so the publication contract and
    the rendered RETURNING list stay in agreement.
    """
    from l2070_batching.write_column_policy import physical_table_publication_columns

    if returning_projections is None:
        return tuple(physical_table_publication_columns(model_cls))
    output_columns: list[str] = []
    for projection in returning_projections:
        if isinstance(projection, AliasedField):
            output_columns.append(projection.alias)
        elif isinstance(projection, AliasedExpression):
            output_columns.append(projection.alias)
        elif isinstance(projection, Field):
            output_columns.append(get_db_column_name(model_cls, DynamicFieldName(projection.name)))
        elif isinstance(projection, Expression):
            msg = "Query update returning expression projections must be aliased to declare output shape."
            raise TypeError(msg)
        else:
            msg = f"Unsupported query update returning projection: {type(projection).__name__}"
            raise TypeError(msg)
    return tuple(output_columns)


def _query_update_returning_output_shape(
    model_cls: type[DatabaseObjectRow],
    returning_projections: Sequence[object] | None,
) -> CompiledOutputShape:
    from l2070_batching.output_shape import (
        CompiledOutputField,
        CompiledOutputShape,
        synthetic_output_field,
    )
    from l2070_batching.write_column_policy import physical_table_publication_columns

    if returning_projections is None:
        columns = physical_table_publication_columns(model_cls)
        field_by_db_column = {
            get_db_column_name(model_cls, DynamicFieldName(field_name)): field_name for field_name in model_cls.model_fields
        }
        return CompiledOutputShape(
            tuple(
                CompiledOutputField(
                    output_name=column,
                    output_column=column,
                    source_db_column=column,
                    model_field_name=field_by_db_column.get(SqlColumnName(column)),
                    owner_cls=model_cls,
                    role="query_update_returning",
                )
                for column in columns
            ),
        )
    output_columns: list[str] = []
    for projection in returning_projections:
        if isinstance(projection, AliasedField):
            output_columns.append(projection.alias)
        elif isinstance(projection, AliasedExpression):
            output_columns.append(projection.alias)
        elif isinstance(projection, Field):
            output_columns.append(get_db_column_name(model_cls, DynamicFieldName(projection.name)))
        elif isinstance(projection, Expression):
            msg = "Query update returning expression projections must be aliased to declare output shape."
            raise TypeError(msg)
        else:
            msg = f"Unsupported query update returning projection: {type(projection).__name__}"
            raise TypeError(msg)
    columns = tuple(output_columns)
    return CompiledOutputShape(tuple(synthetic_output_field(column, role="query_update_returning") for column in columns))


def _build_query_update_returning_items(
    model_cls: type[DatabaseObjectRow],
    returning_projections: Sequence[object] | None,
    *,
    qualifier: str | None = None,
) -> Sequence[SqlRenderable] | SqlRenderable:
    """Build the SQL RETURNING list for update-returning projections."""
    if returning_projections is None:
        from l2070_batching.write_column_policy import physical_table_publication_columns

        return tuple(SqlColumnRef(SqlColumnName(column), qualifier=qualifier) for column in physical_table_publication_columns(model_cls))

    from impl.common.l5200_sql_query.expression_grammar import ExpressionToGrammar

    converter = ExpressionToGrammar(model_cls)
    items: list[SqlRenderable] = []
    for projection in returning_projections:
        if isinstance(projection, AliasedField):
            db_column = get_db_column_name(model_cls, DynamicFieldName(projection.name))
            items.append(
                SqlSelectAlias(
                    SqlColumnRef(SqlColumnName(db_column), qualifier=qualifier),
                    SqlAliasName(projection.alias),
                ),
            )
        elif isinstance(projection, AliasedExpression):
            items.append(
                SqlSelectAlias(
                    converter.convert(projection.expression),
                    SqlAliasName(projection.alias),
                ),
            )
        elif isinstance(projection, Field):
            db_column = get_db_column_name(model_cls, DynamicFieldName(projection.name))
            items.append(SqlColumnRef(SqlColumnName(db_column), qualifier=qualifier))
        elif isinstance(projection, Expression):
            if projection.field is not None and projection.function is None and projection.operator is None:
                db_column = get_db_column_name(model_cls, DynamicFieldName(projection.field))
                items.append(SqlColumnRef(SqlColumnName(db_column), qualifier=qualifier))
            else:
                msg = "Bare expression projections must be aliased before update-returning lowering"
                raise ValueError(msg)
        else:
            msg = f"Unsupported update-returning projection: {type(projection).__name__}"
            raise TypeError(msg)
    if not items:
        msg = "update-returning projection list cannot be empty"
        raise ValueError(msg)
    return tuple(items)

