def test_require_permitted_row_uses_sql_visible_permission_relation() -> None:
    graph_id = SysId.new().unwrap_to_str()
    ctx = make_compilation_context(
        profile=make_backend_profile(BackendType.POSTGRES),
        session_id=_TEST_SESSION_ID,
        cte_refs={
            "visible_graph": cte_ref(
                ServerPlanRefId("visible_graph_cte"),
                columns=("sys_id", "name"),
                column_type_hints=SqlColumnTypeHints(text_columns=frozenset({"name"}), uuid_columns=frozenset({"sys_id"})),
            ),
        },
        txn=_guarded_conn_stub(),
    )
    step = RequirePermittedRowStep[dict[str, object]](
        ServerPlanRefId("permitted_graph"),
        config=_RequirePermittedRowConfig(
            source_ref=ServerPlanRefId("visible_graph"),
            error_message="graph hidden",
        ),
    )

    compiled = step.compile(ctx)

    assert compiled.runtime_ref_ids == ()
    sql, params = _render_compiled_sql(compiled)
    assert params == ()
    assert 'FROM "visible_graph_cte"' in sql
    assert '"sys_id"' in sql
    assert '"name"' in sql
    assert compiled.closed_post_op is not None
    result = compiled.closed_post_op(
        [{"sys_id": graph_id, "name": "visible"}],
        cast(Any, None),
    )
    assert result == {"sys_id": graph_id, "name": "visible"}
    assert UUID(str(result["sys_id"]))
    with pytest.raises(DbPermissionError, match="graph hidden"):
        compiled.closed_post_op([], cast(Any, None))


@pytest.mark.parametrize("visible", [False, True])
def test_permitted_row_executes_declared_projection(visible: bool) -> None:
    row = {"sys_id": SysId.new().unwrap_to_str(), "name": "00123"}
    hints = SqlColumnTypeHints(
        uuid_columns=frozenset({"sys_id"}),
        text_columns=frozenset({"name"}),
    )
    source = SqlExecutedRowsQuery(
        columns=("sys_id", "name"),
        rows=[row] if visible else [],
        type_hints=hints,
    )
    step = RequirePermittedRowStep[dict[str, object]](
        ServerPlanRefId("permitted"),
        config=_RequirePermittedRowConfig(
            source_ref=ServerPlanRefId("visible"),
            error_message="graph hidden",
        ),
    )
    compiled = step.compile(
        make_compilation_context(
            cte_refs={
                "visible": cte_ref(
                    ServerPlanRefId("visible_rows"),
                    columns=("sys_id", "name"),
                    column_type_hints=hints,
                    auxiliary_query=source,
                ),
            }
        )
    )
    assert compiled.grammar is not None
    sql, params = (
        SqlCte([("visible_rows", source)], compiled.grammar)
        .render(
            SqliteDialect(),
        )
        .to_sql(SqliteDialect())
    )
    connection = sqlite3.connect(":memory:")
    try:
        connection.row_factory = sqlite3.Row
        rows = [dict(result) for result in connection.execute(sql, params).fetchall()]
    finally:
        connection.close()
    assert compiled.closed_post_op is not None
    if visible:
        assert compiled.closed_post_op(rows, DictHydrator()) == row
    else:
        with pytest.raises(DbPermissionError, match="graph hidden"):
            compiled.closed_post_op(rows, DictHydrator())


