@pytest.mark.parametrize("action", ["update", "delete"])
@pytest.mark.parametrize("state", [QueryPermissionState.ATTACHED, QueryPermissionState.RESOLVED])
def test_mutation_action_recompiles_prior_read_authority(
    action: Literal["update", "delete"], state: QueryPermissionState,
) -> None:
    from impl.common.l2070_server_plan.steps._compile_helpers import attach_runtime_permission_grammar

    read_spec = replace(
        _query_spec(), model_cls=_ProtectedPermissionGuardrailBatch2Row,
        permission_state=state,
        permission_grammar=_permission_sql() if state is QueryPermissionState.ATTACHED else None,
    )
    denial = SqlParam(False)
    with patch(
        "impl.common.l7300_cross_branch.permission_expression_compiler.compile_permission_where_for_dml_with_user_expr",
        return_value=denial,
    ) as compile_mutation:
        result = attach_runtime_permission_grammar(
            read_spec, _ProtectedPermissionGuardrailBatch2Row, _ctx(),
            action=action, attach_column_masking=False,
        )
    compile_mutation.assert_called_once()
    assert compile_mutation.call_args.kwargs["action"] == action
    assert isinstance(result, QuerySpec)
    assert result.permission_grammar is denial


