        config=_VersionedSelectOneConfig(
            staged_table_name=SqlTableName("versioned_permission_guardrail_batch2_rows_staged"),
            tip_table_name=SqlTableName("versioned_permission_guardrail_batch2_rows_tip"),
            common_columns=tuple(SqlColumnName(column) for column in ("sys_id", "owner_id", "secret", "name")),
            branch_id=ctx.branch_id,
            user_id_ref_id=ServerPlanRefId("resolved_user"),
