def _return_value_relation_contract(
    value: object,
    columns: tuple[str, ...],
    column_type_hints: SqlColumnTypeHints,
) -> CteRelationContract:
    """Relation owner for literal return-value publication.

    Return values are not all model rows. This contract records the boundary
    that owns the SQL-visible columns: data-layer models keep their model
    relation, typed literal objects keep their concrete semantic type, scalar
    literals use the canonical ``__result`` row, and mapping literals are
    explicitly bounded by their captured keys.
    """
    sequence_model_cls = _homogeneous_base_model_sequence_model(value)
    if sequence_model_cls is not None:
        return CteRelationContract.semantic_row(
            cte_projection_row_model("ReturnValueSequenceCteRow", columns, column_type_hints),
        )
    if isinstance(value, DatabaseObjectRow):
        return CteRelationContract.semantic_row(
            cte_projection_row_model("ReturnValueModelCteRow", columns, column_type_hints),
        )
    if isinstance(value, BaseModel):
        return CteRelationContract.semantic_row(
            cte_projection_row_model("ReturnValueBaseModelCteRow", columns, column_type_hints),
        )
    if is_dataclass(value) and not isinstance(value, type):
        return CteRelationContract.semantic_row(type(value))
    if isinstance(value, Mapping):
        return CteRelationContract.literal_mapping(columns=columns)
    column_type_hints = _literal_v_type_hints(value).rename_column("v", "__result")
    return CteRelationContract.semantic_row(result_value_row_cls(column_type_hints))


