@dataclass(frozen=True, slots=True)
class RawPayloadBudgetFacts:
    inline_payload_bytes: int
    payload_byte_budget_chunk_count: int


def _rows_per_statement(
    backend_type: BackendType,
    col_count: int,
    row_count: int,
    *,
    fixed_param_headroom: int = 0,
    capacity: SqlStatementCapacity | None = None,
) -> int:
    """Return a backend-safe row chunk size for multi-row INSERT."""
    from impl.common.l2070_server_plan.param_budget import fused_sql_param_budget

    if col_count <= 0 or row_count <= 0:
        return row_count

    budget = fused_sql_param_budget(backend_type, capacity=capacity)
    if budget is not None:
        row_param_budget = max(1, budget - fixed_param_headroom)
        return max(1, row_param_budget // col_count)
    return row_count


def raw_payload_budget_facts[RowsItemT](
    rows: Sequence[tuple[RowsItemT, ...]],
    *,
    byte_budget: int | None = None,
) -> RawPayloadBudgetFacts:
    """Return byte-budget facts for literal raw rows in one pass."""
    if byte_budget is None:
        byte_budget = POSTGRES_RAW_WRITE_BYTE_BUDGET
    if not rows:
        return RawPayloadBudgetFacts(inline_payload_bytes=0, payload_byte_budget_chunk_count=0)

    from impl.common.l2070_server_plan.steps._payload_estimation import (
        estimate_rows_payload_bytes,
    )

    if byte_budget <= 0:
        return RawPayloadBudgetFacts(
            inline_payload_bytes=estimate_rows_payload_bytes(rows),
            payload_byte_budget_chunk_count=1,
        )

    chunk_count = 1
    current_bytes = 0
    total_bytes = 0
    for row in rows:
        row_bytes = estimate_rows_payload_bytes((row,))
        total_bytes += row_bytes
        if current_bytes and current_bytes + row_bytes > byte_budget:
            chunk_count += 1
            current_bytes = 0
        current_bytes += row_bytes
    return RawPayloadBudgetFacts(
        inline_payload_bytes=total_bytes,
        payload_byte_budget_chunk_count=chunk_count,
    )


def _chunk_rows_by_payload_byte_budget[RowsItemT](
    rows: Sequence[tuple[RowsItemT, ...]],
    *,
    byte_budget: int | None = None,
) -> list[list[tuple[Any, ...]]]:
    """Split literal raw rows by approximate inline payload bytes."""
    if byte_budget is None:
        byte_budget = POSTGRES_RAW_WRITE_BYTE_BUDGET
    if byte_budget <= 0 or not rows:
        return [list(rows)]

    from impl.common.l2070_server_plan.steps._payload_estimation import (
        estimate_rows_payload_bytes,
    )

    chunks: list[list[tuple[Any, ...]]] = []
    current: list[tuple[Any, ...]] = []
    current_bytes = 0
    for row in rows:
        row_bytes = estimate_rows_payload_bytes((row,))
        if current and current_bytes + row_bytes > byte_budget:
            chunks.append(current)
            current = []
            current_bytes = 0
        current.append(row)
        current_bytes += row_bytes
    if current:
        chunks.append(current)
    return chunks


def chunk_rows_for_raw_write_statement[RowsItemT](
    backend_type: BackendType,
    col_count: int,
    rows: Sequence[tuple[RowsItemT, ...]],
    *,
    bulk_transport: DmlBulkTransport,
    fixed_param_headroom: int = 0,
    capacity: SqlStatementCapacity | None = None,
) -> list[list[tuple[Any, ...]]]:
    """Split raw write rows by backend param and PostgreSQL payload-byte budgets."""
    if not rows:
        return []
    if capacity is None:
        rows_per_statement = _rows_per_statement(
            backend_type,
            col_count,
            len(rows),
            fixed_param_headroom=fixed_param_headroom,
        )
    else:
        rows_per_statement = _rows_per_statement(
            backend_type,
            col_count,
            len(rows),
            fixed_param_headroom=fixed_param_headroom,
            capacity=capacity,
        )
    param_chunk_size = max(1, rows_per_statement)
    param_chunks = [list(rows[start : start + param_chunk_size]) for start in range(0, len(rows), param_chunk_size)]

    if bulk_transport is not DmlBulkTransport.PAYLOAD_AWARE_BOUND_VALUES:
        return param_chunks
    chunks: list[list[tuple[Any, ...]]] = []
    for param_chunk in param_chunks:
        chunks.extend(_chunk_rows_by_payload_byte_budget(param_chunk))
    return chunks


def _postgres_unnest_row_chunks[RowsItemT](
    rows: Sequence[tuple[RowsItemT, ...]],
    payload_byte_budget_chunk_count: int | None,
) -> list[Sequence[tuple[Any, ...]]]:
    """Return row batches for the PostgreSQL UNNEST raw-write transport."""
    if payload_byte_budget_chunk_count is not None and payload_byte_budget_chunk_count <= 1:
        return [rows]
    return list(_chunk_rows_by_payload_byte_budget(rows))


def should_use_bound_values_transport[RowsItemT](
    backend_type: BackendType,
    col_count: int,
    rows: Sequence[tuple[RowsItemT, ...]],
    *,
    bulk_transport: DmlBulkTransport,
) -> bool:
    """Return whether PostgreSQL should bind byte-heavy raw rows as VALUES params."""
    if bulk_transport is not DmlBulkTransport.PAYLOAD_AWARE_BOUND_VALUES or col_count <= 0 or not rows:
        return False
    if len(rows) > _rows_per_statement(backend_type, col_count, len(rows)):
        return False

    from impl.common.l2070_server_plan.steps._payload_estimation import (
        estimate_rows_payload_bytes,
    )

    return estimate_rows_payload_bytes(rows) >= POSTGRES_VALUES_TRANSPORT_MIN_PAYLOAD_BYTES


def _normalize_db_columns(
    db_column_source: type[DatabaseObjectRow],
    columns: list[str],
    *,
    write_plan: WriteMetadataPlan | None = None,
) -> list[str]:
    from l1000_schema.schema_def import get_db_column_name

    if write_plan is not None:
        return [write_plan.field_to_db_column.get(column, column) for column in columns]
    model_fields = getattr(db_column_source, "model_fields", {})
    return [get_db_column_name(db_column_source, DynamicFieldName(column)) if column in model_fields else column for column in columns]


class InsertManyRawStep(MaybeSqlRelationPublisherStep[Any]):
    def is_raw_bulk_write(self: InsertManyRawStep) -> bool:
        return True

    """Step for bulk raw insert operations (column names + tuples, no model instances).

    When ``return_value`` is provided, this step carries the canonical ref_id
    for a versioned insert intent and returns the prepared Python model instance
    via ``post_op``. This allows ``ServerRef("step_N.sys_id")`` to resolve to
    this step's CTE column rather than a deferred ``ReturnValueStep``, keeping
    the entire insert-then-use chain in a single batch.
    """

    def __init__(
        self: InsertManyRawStep,
        ref_id: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        config: _InsertManyRawConfig,
    ) -> None:
        super().__init__(ref_id)
        self._model_cls = model_cls
        self._columns = list(config.columns)
        self._normalized_columns = tuple(config.normalized_columns) if config.normalized_columns is not None else None
        self._rows = list(config.rows)
        self._db_column_source = config.db_column_source or model_cls
        self._return_value = config.return_value
        self._staged_write = config.staged_write
        self._physical_return_row = config.physical_return_row
        self._after_refs = frozenset(str(ref_id) for ref_id in config.after_refs)
        self._raw_row_facts = config.raw_row_facts
        self._inline_payload_bytes = config.inline_payload_bytes
        self._payload_byte_budget_chunk_count = config.payload_byte_budget_chunk_count
        self._table_name = get_table_name(model_cls)

    def _initialize_transient_plan_state(self: InsertManyRawStep) -> None:
        super()._initialize_transient_plan_state()
        self._raw_optimizer_facts_cache: _RawOptimizerFactsCache | None = None
        self._write_plan_cache: _WritePlanCache | None = None
        self._insert_many_return_value_model_cls_cache: type[Any] | None = None
        self._insert_many_return_value_model_cls_cache_valid = False
        self._insert_many_semantic_publication_columns_cache: tuple[str, ...] | None = None
        self._insert_many_semantic_publication_columns_cache_valid = False
        self._insert_many_semantic_publication_type_hints_cache: SqlColumnTypeHints | None = None
        self._insert_many_semantic_publication_type_hints_cache_valid = False
        self._insert_many_cte_publication_contract_cache: CtePublicationContract | None = None
        self._insert_many_cte_publication_contract_cache_valid = False

    @property
    def level(self: InsertManyRawStep) -> int:
        return 0

    def step_tags(self: InsertManyRawStep) -> frozenset[str]:
        """Return tags identifying this step type."""
        return frozenset({"write", "insert", "bulk", "raw"})

    def is_read_only(self: InsertManyRawStep) -> bool:
        """Return False - this step modifies data."""
        return False

    def has_unbounded_params(self: InsertManyRawStep) -> bool:
        """True when the row list exceeds a safe batching threshold."""
        return len(self._rows) > _UNBOUNDED_PARAM_ROW_THRESHOLD

    def estimated_param_count(self: InsertManyRawStep) -> int | None:
        """Estimate placeholder count for one multi-row insert statement."""
        return len(self._rows) * len(self._columns)

    def supports_ordered_sql_statement_batch(self: InsertManyRawStep) -> bool:
        return True

    def supports_sql_batch_transport(self: InsertManyRawStep) -> bool:
        """Oversized PostgreSQL raw payloads must split before CTE fusion."""
        if self.has_explicit_return_value() and self.semantic_publication_columns() is None:
            return False
        if self._payload_byte_budget_chunk_count is None:
            facts = raw_payload_budget_facts(self._rows)
            self._payload_byte_budget_chunk_count = facts.payload_byte_budget_chunk_count
            if self._inline_payload_bytes is None:
                self._inline_payload_bytes = facts.inline_payload_bytes
        return self._payload_byte_budget_chunk_count <= 1

    def staged_inline_payload_bytes(self: InsertManyRawStep) -> int:
        """Estimate row payload size if this step is rewritten as a staged source."""
        if self._inline_payload_bytes is None:
            facts = raw_payload_budget_facts(self._rows)
            self._inline_payload_bytes = facts.inline_payload_bytes
            if self._payload_byte_budget_chunk_count is None:
                self._payload_byte_budget_chunk_count = facts.payload_byte_budget_chunk_count
        return self._inline_payload_bytes

    def result_cardinality(self: InsertManyRawStep) -> Cardinality:
        if self._staged_write is not None and self._return_value_model_cls() is not None:
            materialized = materialize_explicit_return_value(self._return_value)
            if isinstance(materialized, Sequence) and not isinstance(
                materialized,
                str | bytes | bytearray,
            ):
                return Cardinality.MANY
            return Cardinality.ONE
        return Cardinality.NONE

    def tables_read(self: InsertManyRawStep) -> frozenset[str]:
        """Insert FK reads are exposed through catalog-backed optimizer facts."""
        return frozenset()

    def tables_written(self: InsertManyRawStep) -> frozenset[str]:
        """Return the table name this step writes to."""
        return frozenset({self._table_name})

    def dependencies(self: InsertManyRawStep) -> frozenset[str]:
        """Return prerequisite refs carried by raw row cells."""
        return frozenset({*self.raw_row_facts().dependency_refs, *self._after_refs})

    def ordered_statement_sql_visible_dependencies(self: InsertManyRawStep) -> frozenset[str]:
        """Only row values, not ordering-only ``after_refs``, are ordered-batch SQL inputs."""
        return self.raw_row_facts().dependency_refs

    def raw_row_facts(self: InsertManyRawStep) -> RawRowFacts:
        """Return cached facts derived from the raw row payload."""
        if self._raw_row_facts is None:
            from impl.common.l2070_server_plan.steps import _raw_row_facts

            self._raw_row_facts = _raw_row_facts.build_raw_row_facts(self._rows)
        return self._raw_row_facts

    def planning_fingerprint(self: InsertManyRawStep) -> tuple[object, ...] | None:
        return (
            "planning",
            str(self.ref_id),
            *self.scheduling_fingerprint(),
        )

    def scheduling_fingerprint(self: InsertManyRawStep) -> tuple[object, ...]:
        from impl.common.l2070_server_plan.steps._raw_row_facts import raw_row_fingerprint

        return (
            type(self),
            self._model_cls,
            self._db_column_source,
            tuple(self._columns),
            self._normalized_columns,
            self._staged_write,
            self._after_refs,
            self._return_value is not _UNSET,
            raw_row_fingerprint(self.raw_row_facts()),
        )

    def staged_write_descriptor(self: InsertManyRawStep) -> PendingStagedWrite | None:
        return self._staged_write

    def internal_plan_transient_state_fields(self: InsertManyRawStep) -> frozenset[str]:
        return super().internal_plan_transient_state_fields() | {
            "_insert_many_cte_publication_contract_cache",
            "_insert_many_cte_publication_contract_cache_valid",
            "_insert_many_semantic_publication_columns_cache",
            "_insert_many_semantic_publication_columns_cache_valid",
            "_insert_many_semantic_publication_type_hints_cache",
            "_insert_many_semantic_publication_type_hints_cache_valid",
            "_insert_many_return_value_model_cls_cache",
            "_insert_many_return_value_model_cls_cache_valid",
            "_raw_optimizer_facts_cache",
            "_write_plan_cache",
        }

    def has_explicit_return_value(self: InsertManyRawStep) -> bool:
        return self._return_value is not _UNSET

    def publishes_executor_visible_binding(self: InsertManyRawStep) -> bool:
        return self.cte_publication_contract().publishes_relation

    def always_publishes_executor_visible_binding(self: InsertManyRawStep) -> bool:
        """Explicit-return raw inserts publish only when a SQL-visible consumer is live."""
        return False

    def publication_source_kind(self: InsertManyRawStep) -> PublicationSourceKind:
        return super().publication_source_kind()

    def _ensure_executor_publication_caches(self: InsertManyRawStep) -> None:
        if not hasattr(self, "_write_plan_cache"):
            self._write_plan_cache = None
        if not hasattr(self, "_insert_many_return_value_model_cls_cache"):
            self._insert_many_return_value_model_cls_cache = None
            self._insert_many_return_value_model_cls_cache_valid = False
        if not hasattr(self, "_insert_many_return_value_model_cls_cache_valid"):
            self._insert_many_return_value_model_cls_cache_valid = False
        if not hasattr(self, "_insert_many_semantic_publication_columns_cache"):
            self._insert_many_semantic_publication_columns_cache = None
            self._insert_many_semantic_publication_columns_cache_valid = False
        if not hasattr(self, "_insert_many_semantic_publication_columns_cache_valid"):
            self._insert_many_semantic_publication_columns_cache_valid = False
        if not hasattr(self, "_insert_many_semantic_publication_type_hints_cache"):
            self._insert_many_semantic_publication_type_hints_cache = None
            self._insert_many_semantic_publication_type_hints_cache_valid = False
        if not hasattr(self, "_insert_many_semantic_publication_type_hints_cache_valid"):
            self._insert_many_semantic_publication_type_hints_cache_valid = False
        if not hasattr(self, "_insert_many_cte_publication_contract_cache"):
            self._insert_many_cte_publication_contract_cache = CtePublicationContract.non_publishing()
            self._insert_many_cte_publication_contract_cache_valid = False
        if not hasattr(self, "_insert_many_cte_publication_contract_cache_valid"):
            self._insert_many_cte_publication_contract_cache_valid = False

    def _return_value_model_cls(self: InsertManyRawStep) -> type[Any] | None:
        self._ensure_executor_publication_caches()
        if self._insert_many_return_value_model_cls_cache_valid:
            return self._insert_many_return_value_model_cls_cache
        if self._return_value is _UNSET:
            self._insert_many_return_value_model_cls_cache = None
            self._insert_many_return_value_model_cls_cache_valid = True
            return None
        value = materialize_explicit_return_value(self._return_value)
        if isinstance(value, Sequence) and value and not isinstance(value, (str, bytes, bytearray)):
            model_cls = type(value[0])
            if hasattr(model_cls, "model_fields"):
                self._insert_many_return_value_model_cls_cache = model_cls
                self._insert_many_return_value_model_cls_cache_valid = True
                return model_cls
        model_cls = type(value)
        if hasattr(model_cls, "model_fields"):
            self._insert_many_return_value_model_cls_cache = model_cls
            self._insert_many_return_value_model_cls_cache_valid = True
            return model_cls
        self._insert_many_return_value_model_cls_cache = None
        self._insert_many_return_value_model_cls_cache_valid = True
        return None

    def cte_publication_contract(self: InsertManyRawStep) -> CtePublicationContract:
        self._ensure_executor_publication_caches()
        if self._insert_many_cte_publication_contract_cache_valid:
            assert self._insert_many_cte_publication_contract_cache is not None
            return self._insert_many_cte_publication_contract_cache
        if not self._rows:
            self._insert_many_cte_publication_contract_cache = CtePublicationContract.non_publishing()
            self._insert_many_cte_publication_contract_cache_valid = True
            return CtePublicationContract.non_publishing()
        columns = self.semantic_publication_columns()
        column_type_hints = self.semantic_publication_type_hints()
        if columns is None or column_type_hints is None:
            self._insert_many_cte_publication_contract_cache = CtePublicationContract.non_publishing()
            self._insert_many_cte_publication_contract_cache_valid = True
            return CtePublicationContract.non_publishing()
        model_cls = self._return_value_model_cls()
        if model_cls is None:
            self._insert_many_cte_publication_contract_cache = CtePublicationContract.non_publishing()
            self._insert_many_cte_publication_contract_cache_valid = True
            return CtePublicationContract.non_publishing()
        from l1000_schema.schema_def import get_db_column_name
        from l2070_batching.cte_contracts import projection_over_model_contract

        contract = projection_over_model_contract(
            columns=columns,
            column_type_hints=column_type_hints,
            source_model_cls=model_cls,
            projection_lineage=tuple((column, column) for column in columns),
            relation_role=self.cte_relation_role(),
            source_tables=self.tables_written(),
            optional_columns=(
                (
                    frozenset(columns)
                    - frozenset(get_db_column_name(model_cls, DynamicFieldName(field_name)) for field_name in model_cls.model_fields)
                )
                | (
                    (frozenset(columns) - frozenset(self._columns))
                    | (frozenset({"sys_revision_id", "sys_staged_commit_id"}) & set(columns))
                    if self._staged_write is not None
                    else frozenset()
                )
            ),
        )
        self._insert_many_cte_publication_contract_cache = contract
        self._insert_many_cte_publication_contract_cache_valid = True
        return contract

    def semantic_publication_columns(self: InsertManyRawStep) -> tuple[str, ...] | None:
        self._ensure_executor_publication_caches()
        if self._insert_many_semantic_publication_columns_cache_valid:
            return self._insert_many_semantic_publication_columns_cache
        model_cls = self._return_value_model_cls()
        if model_cls is None:
            self._insert_many_semantic_publication_columns_cache = None
            self._insert_many_semantic_publication_columns_cache_valid = True
            return None
        from l1000_schema.large_column import large_column_pointer_name
        from l2070_batching.write_column_policy import returnable_db_columns

        base_columns = tuple(
            column
            for column in returnable_db_columns(
                model_cls,
                excluded_fields=(),
                include_polymorphic=True,
            )
            if column != "branch_id" and not column.endswith("_hash32")
        )
        if self._staged_write is not None:
            from l1000_schema.schema_def import get_db_column_name

            base_columns = tuple(
                dict.fromkeys(
                    (
                        *base_columns,
                        *(
                            get_db_column_name(model_cls, DynamicFieldName(field_name))
                            for field_name in model_cls.model_fields
                            if get_db_column_name(model_cls, DynamicFieldName(field_name)) != "branch_id"
                            and not get_db_column_name(model_cls, DynamicFieldName(field_name)).endswith("_hash32")
                        ),
                    ),
                ),
            )
        large_column_pointer_columns = tuple(large_column_pointer_name(config.column) for config in get_large_column_configs(model_cls))
        columns = tuple(
            dict.fromkeys(
                (
                    *base_columns,
                    *large_column_pointer_columns,
                    "sys_revision_id",
                    "sys_staged_commit_id",
                    "sys_deleted",
                ),
            ),
        )
        self._insert_many_semantic_publication_columns_cache = columns
        self._insert_many_semantic_publication_columns_cache_valid = True
        return columns

    def semantic_publication_type_hints(self: InsertManyRawStep) -> SqlColumnTypeHints | None:
        self._ensure_executor_publication_caches()
        if self._insert_many_semantic_publication_type_hints_cache_valid:
            return self._insert_many_semantic_publication_type_hints_cache
        columns = self.semantic_publication_columns()
        model_cls = self._return_value_model_cls()
        if columns is None or model_cls is None:
            self._insert_many_semantic_publication_type_hints_cache = None
            self._insert_many_semantic_publication_type_hints_cache_valid = True
            return None
        model_hints = model_sql_column_type_hints(model_cls, columns)
        if model_hints is None:
            msg = f"{type(self).__name__} cannot publish without complete return-value SQL type hints."
            raise TypeError(msg)
        hints = combine_sql_column_type_hints(
            columns,
            model_hints,
            framework_physical_column_sql_column_type_hints(),
        )
        hints.require_complete(columns)
        self._insert_many_semantic_publication_type_hints_cache = hints
        self._insert_many_semantic_publication_type_hints_cache_valid = True
        return hints

    def executor_visible_published_rows(self: InsertManyRawStep) -> Sequence[Mapping[str, object]] | None:
        columns = self.semantic_publication_columns()
        if columns is None or self._return_value is _UNSET:
            return None
        materialized = materialize_explicit_return_value(self._return_value)
        from l1000_schema.schema_def import DatabaseObjectRow, get_db_column_name

        if not isinstance(materialized, DatabaseObjectRow):
            return None
        dumped = materialized.model_dump(mode="python")
        model_fields = getattr(type(materialized), "model_fields", {})
        row_by_column = {
            get_db_column_name(type(materialized), DynamicFieldName(field_name)) if field_name in model_fields else field_name: value
            for field_name, value in dumped.items()
        }
        return [{column: row_by_column.get(column) for column in columns}]

    def staged_write_inline_payload_bytes(self: InsertManyRawStep) -> int | None:
        if self._staged_write is None:
            return None
        return self.staged_inline_payload_bytes()

    def _raw_optimizer_facts(
        self: InsertManyRawStep,
        planning_catalog: PlanningCatalog | None,
    ) -> RawRowOptimizerFacts:
        cache = getattr(self, "_raw_optimizer_facts_cache", None)
        if cache is not None and cache.planning_catalog is planning_catalog:
            return cast("RawRowOptimizerFacts", cache.facts)
        facts = raw_optimizer_facts_for_raw_rows(
            self.ref_id,
            self._model_cls,
            self._normalized_columns or tuple(self._columns),
            self._rows,
            db_column_source=self._db_column_source,
            planning_catalog=planning_catalog,
        )
        self._raw_optimizer_facts_cache = _RawOptimizerFactsCache(planning_catalog, facts)
        return facts

    def _write_plan(self: InsertManyRawStep, ctx: CompilationContext) -> WriteMetadataPlan | None:
        self._ensure_executor_publication_caches()
        cache = self._write_plan_cache
        if cache is not None and cache.planning_catalog is ctx.planning_catalog and cache.db_column_source is self._db_column_source:
            return cache.write_plan
        write_plan = _write_plan_from_context(ctx, self._db_column_source)
        self._write_plan_cache = _WritePlanCache(
            planning_catalog=ctx.planning_catalog,
            db_column_source=self._db_column_source,
            write_plan=write_plan,
        )
        return write_plan

    def foreign_key_checks(
        self: InsertManyRawStep,
        planning_catalog: PlanningCatalog | None = None,
    ) -> frozenset[ForeignKeyCheckFact]:
        return self._raw_optimizer_facts(planning_catalog).foreign_key_checks

    def foreign_key_read_tables(
        self: InsertManyRawStep,
        planning_catalog: PlanningCatalog | None = None,
    ) -> frozenset[str]:
        return insert_fk_read_tables(self._model_cls, planning_catalog)

    def write_key_facts(
        self: InsertManyRawStep,
        planning_catalog: PlanningCatalog | None = None,
    ) -> frozenset[WriteKeyFact]:
        return self._raw_optimizer_facts(planning_catalog).write_key_facts

    def _gate_staged_symbolic_branch_source(
        self: InsertManyRawStep,
        source: SqlRenderable,
        *,
        db_columns: tuple[str, ...],
        row_facts: RawRowFacts,
    ) -> SqlRenderable:
        if self._staged_write is None or "branch_id" not in db_columns:
            return source
        branch_index = db_columns.index("branch_id")
        if not row_facts.columns[branch_index].has_symbolic_cells:
            return source

        from impl.common.l2050_sql_types.sql_branded_types import (
            SqlColumnName,
            SqlTableName,
        )
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlStar
        from impl.common.l2100_sql_grammar.tree.predicates import sql_is_not_null
        from impl.common.l2100_sql_grammar.tree.statements import (
            SqlCte,
            SqlCteDefinition,
            SqlSelect,
        )

        source_name = SqlTableName("__nera_staged_branch_rows")
        return SqlCte(
            (SqlCteDefinition(source_name, source),),
            SqlSelect(
                select_list=SqlStar(),
                from_=source_name,
                where=sql_is_not_null(SqlColumnRef(SqlColumnName("branch_id"))),
            ),
            recursive=False,
        )

    def compile(self: InsertManyRawStep, ctx: CompilationContext) -> CompiledStep[Any]:
        """Compile multi-row INSERT INTO table (cols) VALUES (...), (...)."""

        from impl.common.l2050_sql_types.backend_type import BackendType
        from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName, SqlTableName
        from uuid import UUID
        from impl.common.l2070_server_plan.steps._compile_helpers import (
            _ResolvedWriteRowPlan,
            filter_row_plans_to_existing_schema,
        )
        from impl.common.l2100_sql_grammar.domain.infra.stmt_compound_write import (
            SqlStatementBatch,
            SqlStatementBatchCategory,
        )
        from impl.common.l2100_sql_grammar.domain.infra.stmt_unnest_insert import SqlInsertFromUnnest
        from impl.common.l2100_sql_grammar.domain.versioning.identifier_fragments import SqlColumnRef
        from impl.common.l2100_sql_grammar.tree.clauses import (
            SqlColumnNameList,
            SqlOnConflict,
            SqlPlaceholderRows,
            SqlValuesSource,
        )
        from impl.common.l2100_sql_grammar.tree.enums import ConflictAction
        from impl.common.l2100_sql_grammar.tree.statements import SqlInsert, SqlSelect

        table = SqlTableName(self._table_name)
        db_source = self._db_column_source
        write_plan = self._write_plan(ctx)
        source_columns = tuple(self._columns)
        db_columns = tuple(_normalize_db_columns(db_source, self._columns, write_plan=write_plan))
        rows = list(self._rows)
        if ctx.backend_profile.traits.dml_parameter_transport is DmlParameterTransport.STRING_UUIDS:
            rows = [tuple(str(value) if isinstance(value, UUID) else value for value in row) for row in rows]

        if not rows:
            if self._return_value is not _UNSET:
                closed_post_op = literal_post_op(materialize_explicit_return_value(self._return_value))
            else:
                closed_post_op = literal_post_op(0)
            return CompiledStep(
                output_shape=None,
                result_relation=None,
                column_type_hints=None,
                closed_post_op=closed_post_op,
                needs_returning=False,
            )

        row_plans = [_ResolvedWriteRowPlan(columns=db_columns, values=tuple(row)) for row in rows]
        filtered_columns, filtered_row_plans = filter_row_plans_to_existing_schema(
            ctx.schema_column_cache,
            SqlTableName(self._table_name),
            db_columns,
            row_plans,
        )
        if not filtered_columns:
            msg = f"{type(self).__name__} has no writable columns after schema filtering for {self._table_name}"
            raise ValueError(msg)
        if filtered_columns != db_columns:
            keep_indexes = tuple(index for index, column in enumerate(db_columns) if column in filtered_columns)
            source_columns = tuple(source_columns[index] for index in keep_indexes)
            db_columns = filtered_columns
            rows = [tuple(row_plan.values) for row_plan in filtered_row_plans]
            from impl.common.l2070_server_plan.steps import _raw_row_facts

            row_facts = _raw_row_facts.build_raw_row_facts(rows)
        else:
            row_facts = self.raw_row_facts()

        col_list = SqlColumnNameList(
            [SqlColumnRef(SqlColumnName(c)) for c in db_columns],
        )
        staged_on_conflict: SqlOnConflict | None = None
        if self._staged_write is not None:
            conflict_columns = tuple(
                SqlColumnName(column) for column in ("branch_id", "sys_id", "sys_staged_commit_id") if column in db_columns
            )
            update_columns = tuple(
                SqlColumnName(column)
                for column in db_columns
                if column not in {str(conflict_column) for conflict_column in conflict_columns}
            )
            if conflict_columns and update_columns:
                staged_on_conflict = SqlOnConflict(
                    conflict_columns,
                    ConflictAction.DO_UPDATE,
                    update_columns=update_columns,
                )

        from l4000_permissions.permission_enforcement import get_query_permission_plan
        from l1300_session.session import SessionId
        from impl.common.l2070_server_plan.steps.runtime_ref_projection import _compile_permission_where
        from impl.common.l2100_sql_grammar.tree.clauses import SqlSelectList, SqlSubqueryTableRef
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlStar

        permission_plan = get_query_permission_plan(self._model_cls, action="insert")
        literal_session = ctx.session_id if isinstance(ctx.session_id, SessionId) else None
        filter_insert_rows = (
            permission_plan is not None
            and permission_plan.filter_rows
            and (literal_session is None or permission_plan.filters_session(literal_session))
        )

        def _permission_filtered_source(source: SqlRenderable) -> SqlRenderable:
            if not filter_insert_rows:
                return source
            source_alias = SqlTableName("raw_insert_source")
            where = _compile_permission_where(
                self._model_cls,
                ctx,
                table_alias=str(source_alias),
                action="insert",
            )
            if where is None:
                return source
            return SqlSelect(
                select=SqlSelectList([SqlStar()]),
                from_=SqlSubqueryTableRef(source, source_alias),
                where=where,
            )

        if ctx.backend_profile.traits.dml_bulk_transport is DmlBulkTransport.PAYLOAD_AWARE_BOUND_VALUES and rows:
            from impl.common.l2070_server_plan.steps._projected_row_source import (
                build_postgres_raw_bulk_rows,
                postgres_raw_bulk_column_types,
            )

            column_types = postgres_raw_bulk_column_types(
                db_source,
                source_columns,
                write_plan=write_plan,
            )
            if column_types is not None:
                row_source = build_postgres_raw_bulk_rows(
                    rows=rows,
                    db_columns=db_columns,
                    column_types=column_types,
                    ctx=ctx,
                    row_facts=row_facts,
                )
                if row_source.select_source is not None:
                    gated_source = self._gate_staged_symbolic_branch_source(
                        _permission_filtered_source(row_source.select_source),
                        db_columns=db_columns,
                        row_facts=row_facts,
                    )
                    grammar = SqlInsert(
                        table=table,
                        columns=col_list,
                        values=gated_source,
                    )
                    return _compiled_step_with_post_op(
                        ctx,
                        self._model_cls,
                        self._rows,
                        self._return_value,
                        grammar,
                        physical_return_row=self._physical_return_row,
                        physical_output_columns=tuple(str(column) for column in db_columns),
                        declared_output_columns=self.semantic_publication_columns(),
                        publication_ref_id=self.ref_id,
                        publication_contract=self.cte_publication_contract(),
                        auxiliary_ctes=_collect_dependency_auxiliary_ctes(
                            ctx,
                            self.ordered_statement_sql_visible_dependencies()
                            if ctx.backend_profile.traits.independent_read_transport is IndependentReadTransport.ORDERED_STATEMENTS
                            else self.sql_visible_dependencies(),
                        ),
                    )
                assert row_source.array_params is not None

                row_chunks = _postgres_unnest_row_chunks(
                    rows,
                    self._payload_byte_budget_chunk_count,
                )
                unnest_grammar: SqlRenderable
                if len(row_chunks) > 1:
                    statements: list[SqlInsertFromUnnest] = []
                    for chunk in row_chunks:
                        chunk_source = build_postgres_raw_bulk_rows(
                            rows=chunk,
                            db_columns=db_columns,
                            column_types=column_types,
                            ctx=ctx,
                            row_facts=row_facts,
                        )
                        assert chunk_source.array_params is not None
                        statements.append(
                            SqlInsertFromUnnest(
                                table=get_table_name(self._model_cls),
                                columns=db_columns,
                                column_types=chunk_source.column_types,
                                array_params=chunk_source.array_params,
                            ),
                        )
                    unnest_grammar = SqlStatementBatch(
                        statements,
                        category=SqlStatementBatchCategory.BUDGET_SPLIT,
                    )
                else:
                    unnest_grammar = SqlInsertFromUnnest(
                        table=get_table_name(self._model_cls),
                        columns=db_columns,
                        column_types=row_source.column_types,
                        array_params=row_source.array_params,
                    )
                return _compiled_step_with_post_op(
                    ctx,
                    self._model_cls,
                    rows,
                    self._return_value,
                    unnest_grammar,
                    physical_return_row=self._physical_return_row,
                    physical_output_columns=tuple(str(column) for column in db_columns),
                    declared_output_columns=self.semantic_publication_columns(),
                    publication_ref_id=self.ref_id,
                    publication_contract=self.cte_publication_contract(),
                )

        from impl.common.l2070_server_plan.steps._projected_row_source import (
            build_projected_row_select,
            has_symbolic_row_cells,
        )

        if has_symbolic_row_cells(rows, row_facts=row_facts):
            if ctx.backend_profile.traits.dml_bulk_transport is DmlBulkTransport.PAYLOAD_AWARE_BOUND_VALUES:
                msg = (
                    "SQL-native symbolic raw inserts require explicit bulk column SQL types; "
                    f"could not determine array types for columns {source_columns!r} "
                    f"on {self._db_column_source.__name__}."
                )
                raise ValueError(msg)
            symbolic_row_chunks = chunk_rows_for_raw_write_statement(
                ctx.backend_type,
                len(db_columns),
                rows,
                bulk_transport=ctx.backend_profile.traits.dml_bulk_transport,
                capacity=ctx.sql_statement_capacity,
            )
            if len(symbolic_row_chunks) > 1:
                symbolic_grammar: SqlRenderable = SqlStatementBatch(
                    [
                        SqlInsert(
                            table=table,
                            columns=col_list,
                            values=self._gate_staged_symbolic_branch_source(
                                _permission_filtered_source(
                                    build_projected_row_select(
                                        rows=chunk,
                                        db_columns=db_columns,
                                        ctx=ctx,
                                        row_facts=row_facts,
                                    ),
                                ),
                                db_columns=db_columns,
                                row_facts=row_facts,
                            ),
                            on_conflict=staged_on_conflict,
                        )
                        for chunk in symbolic_row_chunks
                    ],
                    category=SqlStatementBatchCategory.BUDGET_SPLIT,
                )
            else:
                symbolic_grammar = SqlInsert(
                    table=table,
                    columns=col_list,
                    values=self._gate_staged_symbolic_branch_source(
                        _permission_filtered_source(
                            build_projected_row_select(
                                rows=rows,
                                db_columns=db_columns,
                                ctx=ctx,
                                row_facts=row_facts,
                            ),
                        ),
                        db_columns=db_columns,
                        row_facts=row_facts,
                    ),
                    on_conflict=staged_on_conflict,
                )
            return _compiled_step_with_post_op(
                ctx,
                self._model_cls,
                rows,
                self._return_value,
                symbolic_grammar,
                physical_return_row=self._physical_return_row,
                physical_output_columns=tuple(str(column) for column in db_columns),
                declared_output_columns=self.semantic_publication_columns(),
                publication_ref_id=self.ref_id,
                publication_contract=self.cte_publication_contract(),
                auxiliary_ctes=_collect_dependency_auxiliary_ctes(
                    ctx,
                    self.ordered_statement_sql_visible_dependencies()
                    if ctx.backend_profile.traits.independent_read_transport is IndependentReadTransport.ORDERED_STATEMENTS
                    else self.sql_visible_dependencies(),
                ),
            )

        def _build_insert_stmt[RowBatchItemT](row_batch: list[tuple[RowBatchItemT, ...]]) -> tuple[SqlInsert, tuple[Any, ...]]:
            placeholder_rows = SqlPlaceholderRows(
                columns=len(db_columns),
                rows=len(row_batch),
            )
            params = tuple(value for row in row_batch for value in row)
            return (
                SqlInsert(
                    table=table,
                    columns=col_list,
                    values=SqlValuesSource(placeholder_rows),
                    on_conflict=staged_on_conflict,
                ),
                params,
            )

        grammar, compiled_params = _build_insert_stmt(rows)

        return _compiled_step_with_post_op(
            ctx,
            self._model_cls,
            rows,
            self._return_value,
            grammar,
            params=compiled_params,
            external_params_first=True,
            physical_return_row=self._physical_return_row,
            physical_output_columns=tuple(str(column) for column in db_columns),
            declared_output_columns=self.semantic_publication_columns(),
            publication_ref_id=self.ref_id,
            publication_contract=self.cte_publication_contract(),
        )


def _compiled_step_with_post_op[RowsItemT](
    ctx: CompilationContext,
    model_cls: type[DatabaseObjectRow],
    rows: list[tuple[RowsItemT, ...]],
    return_value: object,
    grammar: SqlRenderable,
    *,
    params: tuple[Any, ...] | None = None,
    external_params_first: bool = False,
    auxiliary_ctes: list[tuple[str, BatchSqlRenderable]] | None = None,
    physical_return_row: DatabaseObjectRow | None = None,
    physical_output_columns: tuple[str, ...] | None = None,
    declared_output_columns: tuple[str, ...] | None = None,
    publication_ref_id: ServerPlanRefId,
    publication_contract: CtePublicationContract,
) -> CompiledStep[Any]:
    sql_visible_publication_query: SqlRenderable | None = None
    if return_value is _UNSET:
        closed_post_op = literal_post_op(len(rows))
        if physical_output_columns is not None and "sys_id" in physical_output_columns and rows:
            from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName
            from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlParam
            from impl.common.l2100_sql_grammar.tree.expr_ops import SqlIn
            from impl.common.l2100_sql_grammar.domain.query.stmt_dynamic import SqlDynamicSelectStmt
            from l1000_schema.table_utils import get_table_name

            sys_id_index = physical_output_columns.index("sys_id")
            publication_columns = declared_output_columns or physical_output_columns
            sql_visible_publication_query = SqlDynamicSelectStmt(
                from_table=get_table_name(model_cls),
                columns=[SqlColumnName(column) for column in publication_columns],
                where_conditions=[
                    SqlIn(
                        SqlColumnRef(SqlColumnName("sys_id")),
                        [SqlParam(row[sys_id_index]) for row in rows],
                    ),
                ],
            )
    else:
        materialized_return_value = materialize_explicit_return_value(return_value)
        closed_post_op = literal_post_op(materialized_return_value)
        representative_value: object = (
            physical_return_row
            if physical_return_row is not None
            else (
                materialized_return_value[0]
                if isinstance(materialized_return_value, Sequence)
                and materialized_return_value
                and not isinstance(materialized_return_value, (str, bytes, bytearray))
                else materialized_return_value
            )
        )
        return_model_cls: type[DatabaseObjectRow] | None = (
            type(representative_value) if isinstance(representative_value, DatabaseObjectRow) else None
        )
        supports_returning = ctx.sql_render_dialect().supports_insert_returning()
        if return_model_cls is not None and supports_returning:
            from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName
            from impl.common.l2100_sql_grammar.domain.versioning.stmt_cte import SqlDmlWithReturningColumns
            from l2070_batching.output_shape import CompiledOutputShape, DeclaredResultRelation, synthetic_output_field
            from l2070_batching.sql_column_type_hints import model_sql_column_type_hints
            from l2070_batching.write_column_policy import returnable_db_columns

            if physical_return_row is not None:
                assert declared_output_columns is not None
                output_columns = declared_output_columns
            else:
                output_columns = tuple(
                    column
                    for column in returnable_db_columns(
                        return_model_cls,
                        excluded_fields=(),
                        include_polymorphic=True,
                    )
                    if column != "branch_id" and not column.endswith("_hash32")
                )
            output_shape = CompiledOutputShape(
                tuple(synthetic_output_field(column) for column in output_columns),
            )
            column_type_hints = model_sql_column_type_hints(return_model_cls, output_columns)
            assert column_type_hints is not None

            returning_grammar: SqlRenderable
            if physical_return_row is not None:
                from l1000_schema.schema_def import get_db_column_name
                from impl.common.l2050_sql_types.sql_branded_types import SqlAliasName
                from impl.common.l2100_sql_grammar.domain.versioning.stmt_cte import (
                    SqlDmlWithReturningProjection,
                )
                from impl.common.l2100_sql_grammar.tree.clauses import SqlSelectAlias
                from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlParam

                dumped = physical_return_row.model_dump(mode="python")
                model_fields = type(physical_return_row).model_fields
                values_by_column = {
                    get_db_column_name(type(physical_return_row), DynamicFieldName(field_name))
                    if field_name in model_fields
                    else field_name: value
                    for field_name, value in dumped.items()
                }
                physical_columns = set(physical_output_columns or ())
                returning_grammar = SqlDmlWithReturningProjection(
                    grammar,
                    tuple(
                        SqlSelectAlias(
                            SqlColumnRef(SqlColumnName(column)) if column in physical_columns else SqlParam(values_by_column.get(column)),
                            SqlAliasName(column),
                        )
                        for column in output_columns
                    ),
                )
            else:
                returning_grammar = SqlDmlWithReturningColumns(
                    grammar,
                    tuple(SqlColumnName(column) for column in output_columns),
                )
            compiled_params = params
            compiled_external_params_first = external_params_first
            if physical_return_row is not None and params:
                from impl.common.l2100_sql_grammar.domain.versioning.stmt_cte import SqlBindExternalParams

                returning_grammar = SqlBindExternalParams(
                    returning_grammar,
                    params,
                    external_params_first=external_params_first,
                )
                compiled_params = None
                compiled_external_params_first = False
            return CompiledStep(
                grammar=returning_grammar,
                params=compiled_params,
                needs_returning=True,
                external_params_first=compiled_external_params_first,
                auxiliary_ctes=auxiliary_ctes,
                closed_post_op=None if physical_return_row is not None else closed_post_op,
                output_shape=output_shape,
                result_relation=DeclaredResultRelation.from_output_shape(output_shape),
                column_type_hints=column_type_hints,
            )

    return CompiledStep(
        grammar=grammar,
        params=params,
        needs_returning=False,
        external_params_first=external_params_first,
        auxiliary_ctes=auxiliary_ctes,
        closed_post_op=closed_post_op,
        compiled_sql_publication=compiled_sql_publication_from_query(
            ref_id=publication_ref_id,
            query=sql_visible_publication_query,
            contract=publication_contract,
        ),
    )


