class _ResolveBranchIdByNameAnyWorkspaceStepCteRow(BaseModel):
    sys_id: BranchId


class ResolveBranchIdByNameAnyWorkspaceStep(SqlRelationPublisherStep[BranchId]):
    """L0: Resolve a branch ``sys_id`` by branch name without workspace filter.

    Used when the read path has a domain but no known ``workspace_id`` (for
    example, a non-versioned read transaction that issues a history query
    against a domain whose ``workspace_id`` attribute was never set on the
    domain class). The domain's branch table is already
    domain-scoped, so a unique lookup by ``name`` (with ``sys_deleted = false``)
    is well-defined as long as no two workspaces share a branch name in this
    domain.
    """

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        branch_table: SqlTableName,
        branch_name: ScalarServerRef[BranchName],
    ) -> None:
        super().__init__(ref_id)
        self._branch_table = branch_table
        self._branch_name = branch_name

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self) -> bool:
        return True

    def step_tags(self) -> frozenset[str]:
        return frozenset({"read", "scalar", "branch", "lookup"})

    def tables_read(self) -> frozenset[str]:
        return frozenset({str(self._branch_table)})

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def dependencies(self) -> frozenset[str]:
        return frozenset(str(dep) for dep in self._branch_name.dependencies())

    def cte_publication_contract(self: ResolveBranchIdByNameAnyWorkspaceStep) -> CtePublicationContract:
        columns = ("sys_id",)
        column_type_hints = _branch_id_type_hints("sys_id")
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
