@dataclass(frozen=True, slots=True)
class BootstrapTerminalStatementInventory:
    """Statement inventory for a fused bootstrap terminal."""

    items: tuple[BootstrapTerminalStatementInventoryItem, ...]

    @property
    def total_logical_statements(self: BootstrapTerminalStatementInventory) -> int:
        return sum(item.logical_statement_count for item in self.items)

    @property
    def total_physical_children(self: BootstrapTerminalStatementInventory) -> int:
        return sum(item.physical_child_count for item in self.items)

    @property
    def total_backend_statements(self: BootstrapTerminalStatementInventory) -> int:
        """Count terminal transport groups after structural DDL phase coalescing."""

        ddl_statement_count = sum(
            item.backend_statement_count for item in self.items if item.statement_kind is BootstrapTerminalStatementKind.DDL
        )
        non_ddl_statement_count = sum(
            item.backend_statement_count for item in self.items if item.statement_kind is not BootstrapTerminalStatementKind.DDL
        )
        # The closed bootstrap terminal renders every DDL child into at most
        # three grammar-owned transports: table bodies, non-FK DDL, and
        # deferred foreign keys. Work-product boundaries are proof ownership
        # boundaries, not additional database transports.
        ddl_transport_count = min(3, ddl_statement_count)
        return ddl_transport_count + non_ddl_statement_count

    @property
    def total_script_groups(self: BootstrapTerminalStatementInventory) -> int:
        """Count the grammar-owned DDL phase scripts, not proof bundles."""

        declared_groups = sum(item.script_group_count for item in self.items)
        return min(3, declared_groups)

    def counts_by_step_type(self: BootstrapTerminalStatementInventory) -> dict[str, int]:
        return _sum_by(self.items, lambda item: item.step_type)

    def counts_by_statement_kind(self: BootstrapTerminalStatementInventory) -> dict[str, int]:
        return _sum_by(self.items, lambda item: item.statement_kind.value)

    def counts_by_sql_family(self: BootstrapTerminalStatementInventory) -> dict[str, int]:
        return _sum_by(self.items, lambda item: item.sql_family)

    def counts_by_primitive_kind(self: BootstrapTerminalStatementInventory) -> dict[str, int]:
        return _sum_by(self.items, lambda item: item.primitive_kind or "unknown")

    def counts_by_ordering_layer(self: BootstrapTerminalStatementInventory) -> dict[str, int]:
        return _sum_by(self.items, lambda item: item.ordering_layer)

    def counts_by_object_classification(self: BootstrapTerminalStatementInventory) -> dict[str, int]:
        return _sum_by(self.items, lambda item: item.object_classification)

    def physical_object_owners(self: BootstrapTerminalStatementInventory) -> dict[str, tuple[str, ...]]:
        owners: dict[str, set[str]] = {}
        for item in self.items:
            if item.physical_object_owners:
                for physical_object, owner in item.physical_object_owners:
                    owners.setdefault(physical_object, set()).add(owner)
            else:
                owner = item.source_ref or item.primitive_kind or item.ref_id
                for physical_object in item.physical_objects:
                    owners.setdefault(physical_object, set()).add(owner)
        return {physical_object: tuple(sorted(item_owners)) for physical_object, item_owners in sorted(owners.items())}

    def duplicate_physical_object_owners(self: BootstrapTerminalStatementInventory) -> dict[str, tuple[str, ...]]:
        return {physical_object: owners for physical_object, owners in self.physical_object_owners().items() if len(owners) > 1}


