@pure_lazy
def _sum_by(
    items: tuple[BootstrapTerminalStatementInventoryItem, ...],
    key_fn: Callable[[BootstrapTerminalStatementInventoryItem], str],
) -> dict[str, int]:
    counts: dict[str, int] = {}
    for item in items:
        key = key_fn(item)
        counts[key] = counts.get(key, 0) + item.logical_statement_count
    return counts


@pure_lazy
def _ref_aliases(step: ServerPlanStep[Any]) -> set[str]:
    # A fused product also provides the refs of the products it absorbed: their statements
    # are inside it now, so a child that depends on one of those refs depends on this step.
    # Omitting them would leave the dependent with no provider, which does not read as an
    # error -- it reads as no edge at all, freeing the dependent to be ordered before the
    # writes it needs.
    raw_absorbed_refs: object = getattr(step, "absorbed_refs", frozenset())
    assert isinstance(raw_absorbed_refs, set | frozenset)
    assert all(isinstance(ref, str) for ref in raw_absorbed_refs)
    absorbed_refs: set[str] | frozenset[str] = raw_absorbed_refs
    aliases: set[str] = set()
    for ref in (str(step.ref_id), *absorbed_refs):
        base_ref_id = ref.split(".", 1)[0]
        aliases.update({ref, base_ref_id, f"{base_ref_id}.raw"})
    return aliases


@pure_lazy
def _dependency_aliases(step: ServerPlanStep[Any]) -> set[str]:
    aliases: set[str] = set()
    for dependency in step.dependencies():
        ref_id = str(dependency)
        base_ref_id = ref_id.split(".", 1)[0]
        aliases.update({ref_id, base_ref_id, f"{base_ref_id}.raw"})
    return aliases


@pure_lazy
def _table_dependency_aliases(table_name: SqlTableName) -> set[str]:
    if table_name.startswith("table:"):
        bare_name = table_name.split(":", 1)[1]
        return {table_name, bare_name}
    return {table_name, f"table:{table_name}"}


@pure_lazy
def _create_table_name_for_step(step: ServerPlanStep[Any]) -> str | None:
    stmt = getattr(step, "_stmt", None)
    table_name = _identifier_text(getattr(stmt, "_table", None))
    if table_name is not None and step.is_ddl_operation() and isinstance(stmt, SqlCreateTableDdl):
        return table_name
    written_tables = tuple(step.tables_written())
    if len(written_tables) == 1 and step.is_ddl_operation():
        return str(written_tables[0])
    for object_name in _physical_objects_for_statement(stmt):
        return object_name
    return None


@pure_lazy
def _referenced_table_names_for_step(step: ServerPlanStep[Any]) -> set[str]:
    stmt = getattr(step, "_stmt", None)
    if stmt is None:
        return set()
    body = getattr(stmt, "_body", None)
    constraints = getattr(stmt, "_constraints", None)
    if constraints is None:
        constraints = getattr(body, "_constraints", ())
    if not isinstance(constraints, tuple | list):
        constraints = ()
    structured_refs = {
        table_name for constraint in constraints if (table_name := _identifier_text(getattr(constraint, "_ref_table", None))) is not None
    }
    if structured_refs:
        return structured_refs
    referenced_tables = set(str(table_name) for table_name in step.tables_read())
    if referenced_tables:
        return referenced_tables
    return set()


@pure_lazy
def _topologically_order_children[ChildrenItemT](children: Sequence[ServerPlanStep[ChildrenItemT]]) -> tuple[ServerPlanStep[Any], ...]:
    """Stable-order terminal children by explicit in-terminal dependencies."""

    ordered_input = tuple(children)
    providers: dict[str, int] = {}
    table_create_providers: dict[str, int] = {}
    for index, child in enumerate(ordered_input):
        for alias in _ref_aliases(child):
            providers.setdefault(alias, index)
        created_table = _create_table_name_for_step(child)
        if created_table is not None:
            for table_alias in _table_dependency_aliases(SqlTableName(created_table)):
                table_create_providers.setdefault(table_alias, index)
    dependency_indexes: dict[int, set[int]] = {}
    reverse_edges: dict[int, set[int]] = {}
    for index, child in enumerate(ordered_input):
        deps = {
            provider_index
            for alias in _dependency_aliases(child)
            if (provider_index := providers.get(alias)) is not None and provider_index != index
        }
        deps.update(
            provider_index
            for referenced_table in _referenced_table_names_for_step(child)
            for referenced_alias in _table_dependency_aliases(SqlTableName(referenced_table))
            if (provider_index := table_create_providers.get(referenced_alias)) is not None and provider_index != index
        )
        dependency_indexes[index] = deps
        for dep_index in deps:
            reverse_edges.setdefault(dep_index, set()).add(index)

    # Among children that are equally ready, take schema before data. The dependency edges
    # already force a table's DDL ahead of writes into it; this decides the cases they leave
    # open, and it decides them the way the closed terminal is executed elsewhere -- Postgres
    # runs table bodies, then remaining DDL, then DML, then assertions. Emitting a DDL product
    # only because it happened to be declared between two DML products splits the DML into
    # separate transports for no reason, since DDL and DML cannot share one anyway.
    def _ready_sort_key(index: int) -> tuple[int, int]:
        return (0 if ordered_input[index].is_ddl_operation() else 1, index)

    ready = [index for index in range(len(ordered_input)) if not dependency_indexes[index]]
    result_indexes: list[int] = []
    while ready:
        index = ready.pop(0)
        result_indexes.append(index)
        for dependent_index in sorted(reverse_edges.get(index, ())):
            remaining = dependency_indexes[dependent_index]
            remaining.discard(index)
            if not remaining and dependent_index not in ready and dependent_index not in result_indexes:
                ready.append(dependent_index)
        ready.sort(key=_ready_sort_key)

    if len(result_indexes) != len(ordered_input):
        unresolved = [index for index in range(len(ordered_input)) if index not in result_indexes]
        result_indexes.extend(unresolved)
    return tuple(ordered_input[index] for index in result_indexes)


@pure_lazy
def _step_statement_kind(step: ServerPlanStep[Any]) -> BootstrapTerminalStatementKind:
    from l2070_batching.runtime_application import LifecycleOperationKind

    if step.lifecycle_operation_kind() is LifecycleOperationKind.DATABASE_COMMIT:
        return BootstrapTerminalStatementKind.TRANSACTION_CONTROL
    step_type = type(step).__name__
    if step.is_ddl_operation():
        return BootstrapTerminalStatementKind.DDL
    if step_type == "BootstrapSqlAssertionStep":
        return BootstrapTerminalStatementKind.ASSERTION
    if step_type == "StaticValueAfterDepsStep":
        return BootstrapTerminalStatementKind.STATIC
    if step_type == "GrammarEffectStep":
        return BootstrapTerminalStatementKind.DML
    if step.execution_role().value == "sql":
        return BootstrapTerminalStatementKind.RUNTIME
    return BootstrapTerminalStatementKind.NON_SQL


@pure_lazy
def _statement_sql_family(step: ServerPlanStep[Any]) -> str:
    step_type = type(step).__name__
    if step_type == "BootstrapSqlAssertionStep":
        assertion = getattr(step, "_assertion", None)
        kind = getattr(assertion, "kind", None)
        value = getattr(kind, "value", None)
        return f"assertion:{value}" if value is not None else "assertion"
    stmt = getattr(step, "_stmt", None)
    if stmt is None:
        return step_type
    logical_phase = getattr(stmt, "logical_phase", None)
    if isinstance(logical_phase, str) and logical_phase:
        return f"{type(stmt).__name__}:{logical_phase}"
    # DDL families come from the closed semantic hierarchy rather than
    # rendered SQL or class-name inference.
    if isinstance(stmt, SqlDdl):
        return f"{stmt.ddl_operation.value}:{stmt.ddl_object_kind.value}"
    phase = getattr(stmt, "bootstrap_statement_phase", None)
    if isinstance(phase, SqlBootstrapStatementPhase):
        return phase.value
    return type(stmt).__name__


@pure_lazy
def _statement_source_ref(step: ServerPlanStep[Any]) -> str | None:
    assertion = getattr(step, "_assertion", None)
    payload = getattr(assertion, "payload", None)
    source_ref = getattr(payload, "source_ref", None)
    if source_ref is not None:
        return str(source_ref)
    stmt = getattr(step, "_stmt", None)
    source_refs = getattr(stmt, "logical_source_refs", None)
    if source_refs:
        unique_refs = tuple(dict.fromkeys(str(source_ref) for source_ref in source_refs))
        return unique_refs[0] if len(unique_refs) == 1 else ",".join(unique_refs)
    return None


@pure_lazy
def _statement_primitive_kind(step: ServerPlanStep[Any]) -> str | None:
    ref_text = str(step.ref_id)
    if ref_text.startswith("schema:"):
        first, sep, rest = ref_text.partition(":")
        if not sep:
            return ref_text
        second, sep, _tail = rest.partition(":")
        return f"{first}:{second}" if not sep else f"{first}:{second}:{_tail.partition(':')[0]}"
    first, sep, _rest = ref_text.partition(":")
    if sep and first in {"data", "versioning", "metadata"}:
        return first
    return None


@pure_lazy
def _identifier_text(value: object) -> str | None:
    if value is None:
        return None
    for attr_name in ("name", "value", "_name", "_value"):
        attr_value = getattr(value, attr_name, None)
        if attr_value is not None and attr_value is not value:
            return _identifier_text(attr_value)
    text = str(value)
    if not text:
        return None
    return text.strip('"`[]')


@pure_lazy
def _physical_objects_for_statement(stmt_value: object) -> tuple[str, ...]:
    objects: list[str] = []
    table_name: str | None = None
    for attr_name in ("_table_name", "table_name", "_table", "table"):
        table_name = _identifier_text(getattr(stmt_value, attr_name, None))
        if table_name:
            break
    index_name: str | None = None
    for attr_name in ("_index_name", "index_name", "name", "_name"):
        index_name = _identifier_text(getattr(stmt_value, attr_name, None))
        if index_name:
            break
    trigger_name: str | None = None
    for attr_name in ("_trigger_name", "trigger_name"):
        trigger_name = _identifier_text(getattr(stmt_value, attr_name, None))
        if trigger_name:
            break
    object_kind = stmt_value.ddl_object_kind if isinstance(stmt_value, SqlDdl) else None
    if object_kind is SqlDdlObjectKind.TRIGGER and trigger_name:
        suffix = f":{table_name}" if table_name else ""
        objects.append(f"trigger:{trigger_name}{suffix}")
    elif object_kind is SqlDdlObjectKind.INDEX and index_name:
        suffix = f":{table_name}" if table_name else ""
        objects.append(f"index:{index_name}{suffix}")
    elif object_kind is SqlDdlObjectKind.TABLE and table_name:
        objects.append(f"table:{table_name}")
    return tuple(objects)


@pure_lazy
def _statement_physical_objects(
    step: ServerPlanStep[Any],
    kind: BootstrapTerminalStatementKind,
    *,
    written_tables: frozenset[str] | None = None,
) -> tuple[str, ...]:
    if kind is not BootstrapTerminalStatementKind.DDL:
        return ()
    stmt = getattr(step, "_stmt", None)
    objects: list[str] = []

    if stmt is not None:
        statements = getattr(stmt, "_statements", None) or getattr(stmt, "statements", None)
        if statements is not None:
            for child_stmt in statements:
                objects.extend(_physical_objects_for_statement(child_stmt))
        else:
            objects.extend(_physical_objects_for_statement(stmt))
    for table_name in written_tables if written_tables is not None else step.tables_written():
        objects.append(f"table:{table_name}")
    return tuple(sorted(dict.fromkeys(objects)))


@pure_lazy
def _statement_physical_object_owner_pairs(
    step: ServerPlanStep[Any],
    kind: BootstrapTerminalStatementKind,
    *,
    primitive_kind: str | None,
    source_ref: str | None,
    written_tables: frozenset[str] | None = None,
) -> tuple[tuple[str, str], ...]:
    if kind is not BootstrapTerminalStatementKind.DDL:
        return ()
    stmt = getattr(step, "_stmt", None)
    default_owner = source_ref or primitive_kind or str(step.ref_id)
    pairs: list[tuple[str, str]] = []
    if stmt is not None:
        statements = getattr(stmt, "_statements", None) or getattr(stmt, "statements", None)
        source_refs = tuple(str(ref) for ref in (getattr(stmt, "logical_source_refs", ()) or ()))
        if statements is not None:
            for index, child_stmt in enumerate(statements):
                owner = source_refs[index] if index < len(source_refs) else default_owner
                pairs.extend((physical_object, owner) for physical_object in _physical_objects_for_statement(child_stmt))
        else:
            pairs.extend((physical_object, default_owner) for physical_object in _physical_objects_for_statement(stmt))
    if not pairs:
        for table_name in written_tables if written_tables is not None else step.tables_written():
            pairs.append((f"table:{table_name}", default_owner))
    return tuple(dict.fromkeys(pairs))


@pure_lazy
def _statement_ordering_layer(
    kind: BootstrapTerminalStatementKind,
    sql_family: str,
    physical_objects: tuple[str, ...],
) -> str:
    if kind is not BootstrapTerminalStatementKind.DDL:
        return kind.value
    if any(physical_object.startswith("trigger:") for physical_object in physical_objects) or "trigger" in sql_family:
        return "trigger"
    if any(physical_object.startswith("index:") for physical_object in physical_objects) or "index" in sql_family:
        return "index"
    if any(physical_object.startswith("table:") for physical_object in physical_objects) or "table" in sql_family:
        return "table"
    return "ddl"


@pure_lazy
def _statement_object_classification(
    kind: BootstrapTerminalStatementKind,
    source_ref: str | None,
    primitive_kind: str | None,
    physical_objects: tuple[str, ...],
) -> str:
    if kind is not BootstrapTerminalStatementKind.DDL:
        return kind.value
    if not physical_objects:
        return "ddl_unclassified"
    if source_ref is not None or primitive_kind is not None:
        return "proof_required"
    return "internal"


@pure_lazy
def _logical_statement_count(step: ServerPlanStep[Any], kind: BootstrapTerminalStatementKind) -> int:
    physical_children = step.physical_group_children()
    if physical_children:
        return sum(_logical_statement_count(child, _step_statement_kind(child)) for child in physical_children)
    stmt = getattr(step, "_stmt", None)
    logical_count = getattr(stmt, "logical_statement_count", None)
    if isinstance(logical_count, int):
        return logical_count
    return 0 if kind in {BootstrapTerminalStatementKind.STATIC, BootstrapTerminalStatementKind.NON_SQL} else 1


@pure_lazy
def _backend_statement_count(step: ServerPlanStep[Any], kind: BootstrapTerminalStatementKind) -> int:
    if kind in {BootstrapTerminalStatementKind.STATIC, BootstrapTerminalStatementKind.NON_SQL}:
        return 0
    override = step.bootstrap_backend_statement_count_override()
    if override is not None:
        return override
    stmt = getattr(step, "_stmt", None)
    category = getattr(stmt, "category", None)
    category_value = getattr(category, "value", category)
    if category_value == "bootstrap_dml":
        return 1
    leaf_statement_count = getattr(stmt, "leaf_statement_count", None)
    if callable(leaf_statement_count):
        count = leaf_statement_count()
        if not isinstance(count, int):
            msg = "leaf_statement_count() must return an integer"
            raise TypeError(msg)
        return count
    logical_count = getattr(stmt, "logical_statement_count", None)
    if kind is BootstrapTerminalStatementKind.DDL and isinstance(logical_count, int):
        return 1
    return 1


@pure_lazy
def _script_group_count(step: ServerPlanStep[Any], kind: BootstrapTerminalStatementKind) -> int:
    if kind not in {BootstrapTerminalStatementKind.DDL, BootstrapTerminalStatementKind.DML}:
        return 0
    stmt = getattr(step, "_stmt", None)
    logical_count = getattr(stmt, "logical_statement_count", None)
    return 1 if isinstance(logical_count, int) and logical_count > 1 else 0


@pure_lazy
def _may_travel_inside_terminal_sql_group(step: ServerPlanStep[Any]) -> bool:
    """Whether a fused terminal SQL group may span this child.

    Two different questions get conflated easily here. ``supports_sql_batch_transport()`` asks whether
    SQL batching may carry a step's *own* statement, so a step with no SQL surface answers no. Spanning
    asks whether placing a step inside a group could change what the group observes, and a ``VIRTUAL``
    child issues nothing at all, so it cannot. The terminal carries one virtual dependency alias per
    proof ref, sitting between the products they alias; treating those as run boundaries would leave
    almost nothing groupable.
    """

    return step.execution_role() is StepExecutionRole.VIRTUAL or step.supports_sql_batch_transport()


@pure_lazy
def _fuse_bootstrap_dml_transports[ChildrenItemT](
    children: Sequence[ServerPlanStep[ChildrenItemT]],
) -> tuple[ServerPlanStep[Any], ...]:
    """Fuse consecutive bootstrap-DML products into one transport each.

    A backend without data-modifying CTEs cannot express the terminal's writes as a single
    statement, but it does not need to: one ``BOOTSTRAP_DML`` statement batch is one
    transport, executed as a run of prepared ``executemany`` groups inside a single call (see
    the SQLite native bootstrap-DML path in ``impl/sqlite/execution_support_service.py``).
    Left unfused, each product is instead its own transport, so a cold bootstrap issues one
    per seeded table -- for Sidekick that is over a hundred, against a terminal budget of a
    dozen, even though every one of them is redundant with the next.

    This is the right place for the collapse rather than the enqueue site. Work-product
    boundaries exist to carry proof ownership, and at enqueue time only the products already
    added are visible, so merging there means reaching backwards past intervening steps and
    relocating work behind dependencies that may not even be published yet. Here the children
    have been topologically ordered, so a *consecutive* run can always be fused: every
    dependency of a run member points at something ordered earlier, and everything ordered
    later keeps its edge because the fused product sits where the run began and answers for
    the refs it absorbed.

    A step that emits SQL ends the run, because moving writes across it would change what it
    observes. A ``VIRTUAL`` step does not: it publishes a planning value and issues nothing, so
    a run may continue past it and the virtual step is emitted once the run closes. That
    distinction is what makes the collapse worth doing at all -- the terminal carries hundreds
    of virtual dependency aliases, one per proof ref, and they sit between the products they
    alias.

    A product that depends on a deferred alias is the interesting case, and the common one:
    bootstrap threads consecutive mutations through these aliases, so treating such a
    dependency as a wall would leave almost nothing fused. The alias publishes no value, so the
    dependency is purely an ordering constraint on the writes behind it -- and when those writes
    are already in the run, the run can take the constraint over and answer for the alias ref
    itself. Only when the alias still awaits work that has not run does the product close the
    run instead: absorbing it there would leave the fused product depending on a step ordered
    after it, which surfaces as a dependency cycle when the batch is ordered rather than as
    anything pointing back to here.
    """
    # A ref no terminal child produces is satisfied before the terminal opens, so it never
    # constrains where inside the terminal a step may sit.
    terminal_provided_refs = {alias for child in children for alias in _ref_aliases(child)}

    fused: list[ServerPlanStep[Any]] = []
    open_run: ServerPlanStep[Any] | None = None
    deferred_aliases: dict[str, ServerPlanStep[Any]] = {}
    absorbed_aliases: dict[int, ServerPlanStep[Any]] = {}
    settled_refs: set[str] = set()

    def _close_run(boundary: str) -> None:
        nonlocal open_run
        if open_run is not None:
            settled_refs.update(open_run.bootstrap_dml_provided_refs())
            fused.append(open_run)
            open_run = None
        for alias in (*absorbed_aliases.values(), *dict.fromkeys(deferred_aliases.values())):
            settled_refs.update(_ref_aliases(alias))
            fused.append(alias)
        absorbed_aliases.clear()
        deferred_aliases.clear()

    def _absorbable_alias_refs(product: ServerPlanStep[Any]) -> frozenset[str] | None:
        """Alias refs the run may take over so ``product`` can join it, or None if it cannot."""
        assert open_run is not None
        blocking_refs = product.dependencies() & deferred_aliases.keys()
        if not blocking_refs:
            return frozenset()
        satisfied_refs = settled_refs | open_run.bootstrap_dml_provided_refs()
        for alias_ref in blocking_refs:
            alias_sources = deferred_aliases[alias_ref].dependencies()
            if any(source_ref in terminal_provided_refs and source_ref not in satisfied_refs for source_ref in alias_sources):
                return None
        return frozenset(blocking_refs)

    for child in children:
        if child.is_bootstrap_dml_work_product():
            if open_run is not None:
                alias_refs = _absorbable_alias_refs(child)
                if alias_refs is not None:
                    combined = open_run.absorbing_bootstrap_dml_ordering_aliases(alias_refs).combine_bootstrap_dml_work_product(child)
                    if combined is not None:
                        # An absorbed alias stops blocking under every name it goes by, not
                        # only the one this product happened to depend on. The alias step is
                        # still emitted when the run closes: it issues nothing, and deleting a
                        # step to speed up a merge is a larger claim than this needs to make.
                        absorbed_alias_steps = {id(deferred_aliases[alias_ref]) for alias_ref in alias_refs}
                        for alias_ref, alias_step in tuple(deferred_aliases.items()):
                            if id(alias_step) in absorbed_alias_steps:
                                del deferred_aliases[alias_ref]
                                absorbed_aliases.setdefault(id(alias_step), alias_step)
                        open_run = combined
                        continue
                _close_run("unsettled_alias_dependency")
            open_run = child
            continue
        if open_run is not None and child.execution_role() is StepExecutionRole.VIRTUAL:
            for alias in _ref_aliases(child):
                deferred_aliases[alias] = child
            continue
        _close_run(type(child).__name__)
        settled_refs.update(_ref_aliases(child))
        fused.append(child)
    _close_run("terminal_end")
    return tuple(fused)


@pure_lazy
def lower_bootstrap_terminal_work_products[ChildrenItemT](
    children: Sequence[ServerPlanStep[ChildrenItemT]],
    *,
    context: BootstrapTerminalLoweringContext,
) -> tuple[ServerPlanStep[Any], ...]:
    """Lower typed bootstrap work products into backend-native terminal children."""

    from impl.common.l2070_server_plan.codegen.data_modifying_cte import DataModifyingCteStrategy
    from l2070_batching.optimizer import OptimizationContext

    ordered_children = _topologically_order_children(children)
    if (
        context.backend_profile is not None
        and context.backend_profile.traits.bootstrap_terminal_transport is BootstrapTerminalTransport.COMPOUND_SEQUENCE
    ):
        opt_ctx = OptimizationContext(
            backend_type=context.backend_type,
            dialect=context.dialect,
            supports_data_modifying_ctes=context.supports_data_modifying_ctes,
            is_write_transaction=True,
            backend_profile=context.backend_profile,
            planning_catalog=context.planning_catalog,
        )
        sql_children = tuple(
            child
            for child in ordered_children
            if child.execution_role() is StepExecutionRole.SQL and "static_dependency" not in child.step_tags()
        )
        non_sql_children = tuple(
            child
            for child in ordered_children
            if child.execution_role() is not StepExecutionRole.SQL or "static_dependency" in child.step_tags()
        )
        compound_strategy = CompoundSequenceCodegen()
        if sql_children and compound_strategy.can_handle(sql_children, opt_ctx):
            return (
                PhysicalStatementGroup(
                    "bootstrap_sqlite_terminal_sql",
                    sql_children,
                    compound_strategy,
                ),
                *non_sql_children,
            )
        return ordered_children
    if (
        context.backend_profile is None
        or context.backend_profile.traits.bootstrap_terminal_transport is not BootstrapTerminalTransport.DATA_MODIFYING_CTE
        or not context.supports_data_modifying_ctes
    ):
        return ordered_children

    opt_ctx = OptimizationContext(
        backend_type=context.backend_type,
        dialect=context.dialect,
        supports_data_modifying_ctes=context.supports_data_modifying_ctes,
        is_write_transaction=True,
        backend_profile=context.backend_profile,
        planning_catalog=context.planning_catalog,
    )
    strategy = DataModifyingCteStrategy()
    lowered: list[ServerPlanStep[Any]] = []
    index = 0
    max_probe_width = 8
    while index < len(ordered_children):
        child = ordered_children[index]
        if not child.supports_sql_batch_transport() or child.requires_prior_step_boundary():
            lowered.append(child)
            index += 1
            continue
        boundary = index + 1
        if not child.is_bootstrap_dml_work_product():
            while (
                boundary < len(ordered_children)
                and ordered_children[boundary].supports_sql_batch_transport()
                and not ordered_children[boundary].requires_prior_step_boundary()
                and not ordered_children[boundary].is_bootstrap_dml_work_product()
            ):
                boundary += 1
        best_end: int | None = None
        probe_boundary = min(boundary, index + max_probe_width)
        for end in range(probe_boundary, index + 1, -1):
            if strategy.can_handle(ordered_children[index:end], opt_ctx):
                best_end = end
                break
        if best_end is None:
            lowered.append(child)
            index += 1
            continue
        lowered.append(
            PhysicalStatementGroup(
                f"bootstrap_dmc_{index}_{best_end - 1}",
                ordered_children[index:best_end],
                strategy,
            ),
        )
        index = best_end
    return tuple(lowered)


@pure_lazy
def collapse_bootstrap_terminal_static_publications[ChildrenItemT](
    children: Sequence[ServerPlanStep[ChildrenItemT]],
    *,
    application_tail_ref: ServerPlanRefId,
) -> tuple[ServerPlanStep[Any], ...]:
    """Replace planning-only static bridges with one terminal result publication."""
    tail_steps = [
        child for child in children if child.is_bootstrap_static_publication() and str(child.ref_id) == str(application_tail_ref)
    ]
    if len(tail_steps) != 1:
        available_tail_refs = tuple(str(child.ref_id) for child in children if child.is_bootstrap_static_publication())
        msg = (
            "bootstrap application terminal requires exactly one static tail publication "
            f"for {application_tail_ref!s}; found {len(tail_steps)}; "
            f"available={available_tail_refs!r}"
        )
        raise ValueError(msg)
    tail_step = tail_steps[0]
    for child in children:
        if not child.is_bootstrap_static_publication() or child is tail_step:
            continue
        lifecycle_effects = tuple(object.__getattribute__(child, "_lifecycle_effects"))
        if lifecycle_effects:
            msg = f"bootstrap static bridge {child.ref_id!s} carries lifecycle effects that cannot be collapsed"
            raise ValueError(msg)
    child_ref_ids = frozenset(str(child.ref_id) for child in children)
    external_dependency_ref_ids = tuple(
        sorted(
            {
                str(ref_id).split(".", 1)[0]
                for child in children
                for ref_id in child.dependencies()
                if str(ref_id).split(".", 1)[0] not in child_ref_ids
            },
        ),
    )
    external_dependency_aliases = tuple(
        BootstrapStaticDependencyStep(
            ServerPlanRefId(ref_id),
            source_refs=(),
        )
        for ref_id in external_dependency_ref_ids
    )
    dependency_aliases = tuple(
        BootstrapStaticDependencyStep(
            ServerPlanRefId(str(child.ref_id)),
            source_refs=tuple(
                ServerPlanRefId(str(ref_id)) for ref_id in child.dependencies() if str(ref_id).split(".", 1)[0] in child_ref_ids
            ),
        )
        for child in children
        if child.is_bootstrap_static_publication() and child is not tail_step
    )
    collapsed_tail = StaticValueAfterDepsStep(
        application_tail_ref,
        object.__getattribute__(tail_step, "_value"),
        source_refs=[],
        lifecycle_effects=tuple(object.__getattribute__(tail_step, "_lifecycle_effects")),
    )
    return (
        *external_dependency_aliases,
        *(child for child in children if not child.is_bootstrap_static_publication()),
        *dependency_aliases,
        collapsed_tail,
    )


_BOOTSTRAP_STATIC_DEPENDENCY_SCHEDULING_FACTS = StepSchedulingFacts(
    supports_sql_batch_transport=True,
    requires_runtime_sequential_batch=False,
    requires_materialized_inputs=False,
    requires_prior_step_boundary=False,
    has_unbounded_params=False,
    estimated_param_count=None,
    counts_as_sql_group_hint=None,
    emits_sql_for_accounting_hint=None,
    execution_role=StepExecutionRole.SQL,
    requires_prior_statement_visibility_after_writes=frozenset(),
)


class BootstrapStaticDependencyStep(ServerPlanStep[None]):
    """Planning-only alias that preserves a collapsed static dependency graph."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        source_refs: tuple[ServerPlanRefId, ...],
    ) -> None:
        super().__init__(ref_id)
        self._source_refs = source_refs
        self._dependency_refs = frozenset(str(source_ref) for source_ref in source_refs)

    @property
    def level(self) -> int:
        return 0

    def scheduling_facts(self) -> StepSchedulingFacts:
        return _BOOTSTRAP_STATIC_DEPENDENCY_SCHEDULING_FACTS

    def result_cardinality(self) -> Cardinality:
        return Cardinality.NONE

    def is_read_only(self) -> bool:
        return True

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def step_tags(self) -> frozenset[str]:
        return frozenset({"bootstrap", "static_dependency", "sql_noop"})

    def dependencies(self) -> frozenset[str]:
        return self._dependency_refs

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def consumes_executor_visible_dependencies(self) -> bool:
        return False

    def sql_visible_dependencies(self) -> frozenset[str]:
        return frozenset()

    def supports_sql_batch_transport(self) -> bool:
        return True

    def supports_ordered_sql_statement_batch(self) -> bool:
        return True

    def compile(self, ctx: CompilationContext) -> CompiledStep[None]:
        del ctx
        return CompiledStep()

    def internal_plan_state(self) -> PlanPayloadState:
        return {"_source_refs": self._source_refs}

    def internal_plan_ref_state(self) -> PlanPayloadState:
        return self.internal_plan_state()


class BootstrapApplicationTerminalStep(PhysicalStatementGroup):
    """Single executor terminal for lazy bootstrap application work."""

    def __init__[ChildrenItemT](
        self: BootstrapApplicationTerminalStep,
        ref_id: ServerPlanRefId | str,
        children: Sequence[ServerPlanStep[ChildrenItemT]],
        *,
        strategy: PhysicalRegionCodegen | None = None,
        expose_child_results: bool = False,
        exported_ordering_alias_refs: Sequence[ServerPlanRefId] = (),
        internal_ordering_dependency_refs: Sequence[ServerPlanRefId] = (),
        deferred_dependency_refs: Sequence[ServerPlanRefId] = (),
        result_ref: ServerPlanRefId | None = None,
    ) -> None:
        super().__init__(
            ref_id,
            _topologically_order_children(children),
            strategy or CompoundSequenceCodegen(),
            exported_ordering_alias_refs=exported_ordering_alias_refs,
            internal_ordering_dependency_refs=internal_ordering_dependency_refs,
            deferred_dependency_refs=deferred_dependency_refs,
        )
        result_step: ServerPlanStep[Any] | None = None
        if result_ref is not None:
            pending_result_steps = list(self.children)
            while pending_result_steps:
                candidate = pending_result_steps.pop()
                if candidate.ref_id == result_ref:
                    result_step = candidate
                    break
                pending_result_steps.extend(candidate.physical_group_children())
            if result_step is None:
                raise ValueError("A bootstrap terminal result must name one of its child outputs")
        selected_ref = result_ref if result_ref is not None else ref_id
        self._expose_child_results = expose_child_results
        self._terminal_result_ref = result_ref
        self.direct_batch_result_ref_id = None if expose_child_results else str(selected_ref)
        self._selected_result_cardinality = result_step.result_cardinality() if result_step is not None else Cardinality.MANY
        self._statement_inventory_cache: BootstrapTerminalStatementInventory | None = None
        child_scheduling_facts = tuple(child.scheduling_facts() for child in self.children)
        child_dependencies = tuple(child.dependencies() for child in self.children)
        child_reads = tuple(child.tables_read() for child in self.children)
        child_writes = tuple(child.tables_written() for child in self.children)
        terminal_scheduling_facts = StepSchedulingFacts(
            supports_sql_batch_transport=all(facts.supports_sql_batch_transport for facts in child_scheduling_facts),
            supports_ordered_sql_statement_batch=self.supports_ordered_sql_statement_batch(),
            requires_runtime_sequential_batch=any(facts.requires_runtime_sequential_batch for facts in child_scheduling_facts),
            requires_materialized_inputs=any(facts.requires_materialized_inputs for facts in child_scheduling_facts),
            requires_prior_step_boundary=any(facts.requires_prior_step_boundary for facts in child_scheduling_facts),
            has_unbounded_params=self.has_unbounded_params(),
            estimated_param_count=self.estimated_param_count(),
            counts_as_sql_group_hint=self.counts_as_sql_group_for_accounting(),
            emits_sql_for_accounting_hint=self.emits_sql_for_accounting(),
            execution_role=StepExecutionRole.SQL,
            requires_prior_statement_visibility_after_writes=(self.requires_prior_statement_visibility_after_writes()),
        )
        self._preparation_facts = BootstrapTerminalPreparationFacts(
            child_scheduling_facts=child_scheduling_facts,
            child_dependencies=child_dependencies,
            child_reads=child_reads,
            child_writes=child_writes,
            terminal_scheduling_facts=terminal_scheduling_facts,
            terminal_dependencies=PhysicalStatementGroup.dependencies(self),
            terminal_reads=frozenset().union(*child_reads),
            terminal_writes=frozenset().union(*child_writes),
        )
        for child in self.children:
            setattr(child, "_bootstrap_application_terminal_ref_id", str(ref_id))

    def is_bootstrap_application_terminal(self: BootstrapApplicationTerminalStep) -> bool:
        return True

    def scheduling_facts(self: BootstrapApplicationTerminalStep) -> StepSchedulingFacts:
        return self._preparation_facts.terminal_scheduling_facts

    def dependencies(self: BootstrapApplicationTerminalStep) -> frozenset[str]:
        return self._preparation_facts.terminal_dependencies

    def tables_read(self: BootstrapApplicationTerminalStep) -> frozenset[str]:
        return self._preparation_facts.terminal_reads

    def tables_written(self: BootstrapApplicationTerminalStep) -> frozenset[str]:
        return self._preparation_facts.terminal_writes

    def imported_dependency_refs(self: BootstrapApplicationTerminalStep) -> frozenset[ServerPlanRefId]:
        """Declare prerequisite ordering refs satisfied by earlier phases."""
        child_refs = {str(child.ref_id) for child in self.children}
        return frozenset(ServerPlanRefId(ref_id) for ref_id in self.dependencies() if str(ref_id) not in child_refs)

    def sql_imported_dependency_refs(self: BootstrapApplicationTerminalStep) -> frozenset[ServerPlanRefId]:
        """Bootstrap phase-order refs do not require SQL row publication."""
        return frozenset()

    def result_cardinality(self: BootstrapApplicationTerminalStep) -> Cardinality:
        return self._selected_result_cardinality

    def preserve_prebatched_group(self: BootstrapApplicationTerminalStep) -> bool:
        """Keep the signed bootstrap terminal as one executor-owned application unit."""
        return True

    def replace_physical_group(
        self: BootstrapApplicationTerminalStep,
        children: Sequence[ServerPlanStep[Any]],
        codegen: PhysicalRegionCodegen | None,
    ) -> BootstrapApplicationTerminalStep:
        """Replace terminal children without discarding terminal ownership."""
        return BootstrapApplicationTerminalStep(
            self.ref_id,
            children,
            strategy=self.physical_region_codegen() if codegen is None else codegen,
            expose_child_results=self._expose_child_results,
            exported_ordering_alias_refs=self.exported_ordering_alias_refs(),
            internal_ordering_dependency_refs=self.internal_ordering_dependency_refs(),
            deferred_dependency_refs=tuple(self.deferred_physical_dependency_refs()),
            result_ref=self._terminal_result_ref,
        )

    def __repr__(self: BootstrapApplicationTerminalStep) -> str:
        child_refs = [child.ref_id for child in self.children]
        return f"BootstrapApplicationTerminalStep(ref_id={self.ref_id!r}, children={child_refs})"

    def statement_inventory(self: BootstrapApplicationTerminalStep) -> BootstrapTerminalStatementInventory:
        """Return a diagnostic inventory of logical SQL work in this terminal."""

        if self._statement_inventory_cache is not None:
            return self._statement_inventory_cache
        items: list[BootstrapTerminalStatementInventoryItem] = []
        for index, child in enumerate(self.children):
            kind = _step_statement_kind(child)
            sql_family = _statement_sql_family(child)
            primitive_kind = _statement_primitive_kind(child)
            source_ref = _statement_source_ref(child)
            physical_objects = _statement_physical_objects(
                child,
                kind,
                written_tables=self._preparation_facts.child_writes[index],
            )
            items.append(
                BootstrapTerminalStatementInventoryItem(
                    ref_id=str(child.ref_id),
                    step_type=type(child).__name__,
                    statement_kind=kind,
                    sql_family=sql_family,
                    primitive_kind=primitive_kind,
                    source_ref=source_ref,
                    reads=tuple(sorted(self._preparation_facts.child_reads[index])),
                    writes=tuple(sorted(self._preparation_facts.child_writes[index])),
                    physical_objects=physical_objects,
                    physical_object_owners=_statement_physical_object_owner_pairs(
                        child,
                        kind,
                        primitive_kind=primitive_kind,
                        source_ref=source_ref,
                        written_tables=self._preparation_facts.child_writes[index],
                    ),
                    ordering_layer=_statement_ordering_layer(kind, sql_family, physical_objects),
                    object_classification=_statement_object_classification(
                        kind,
                        source_ref,
                        primitive_kind,
                        physical_objects,
                    ),
                    dependency_count=len(self._preparation_facts.child_dependencies[index]),
                    logical_statement_count=_logical_statement_count(child, kind),
                    physical_child_count=1,
                    backend_statement_count=_backend_statement_count(child, kind),
                    script_group_count=_script_group_count(child, kind),
                ),
            )
        self._statement_inventory_cache = BootstrapTerminalStatementInventory(tuple(items))
        return self._statement_inventory_cache

"""L0 steps for transaction commit and rollback lifecycle.

These steps are produced by lowering ``CommitIntent`` and ``RollbackIntent``.
Lifecycle ordering is explicit in the plan while the executor owns the runtime
side effects through structured IR.
"""

from __future__ import annotations


import logging
from collections.abc import Iterable, Mapping, Sequence
from dataclasses import dataclass, field
from datetime import UTC, datetime
from typing import TYPE_CHECKING, Any, Literal, Protocol, cast, runtime_checkable

from l2050_transaction.transaction import TransactionState
from l2070_batching.cardinality import Cardinality
from l2070_batching.compilation import (
    CompilationContext,
    CompiledStep,
    PipelineLifecycleEffect,
    PipelineLifecyclePhase,
    no_result_compiled_artifacts,
)
from l2070_batching.output_shape import CompiledOutputShape, DeclaredResultRelation, declared_zero_column_output_shape
from l2070_batching.post_op import literal_post_op
from l2070_batching.runtime_application import LifecycleOperationKind
from l2070_batching.versioned_planning_snapshot import VersionedWritePlanTarget
from l2070_batching.sql_column_type_hints import SqlColumnTypeHints
from l2070_batching.step import ServerPlanStep, StepExecutionRole, ContractedSqlProducerStep, NonPublishingStep
from l1400_types import ServerPlanRefId

if TYPE_CHECKING:
    from impl.common.l1000_cache.transaction import CacheTransaction, PreparedCacheCommit

# Transaction barrier: steps that declare tables_read/tables_written = {"*"}
# conflict with ALL other steps in the dependency-order optimizer, preventing
# reordering across transaction boundaries (COMMIT, ROLLBACK, finalization).
_BARRIER: frozenset[str] = frozenset({"*"})
_NO_RESULT_OUTPUT_SHAPE = declared_zero_column_output_shape()
_NO_RESULT_RELATION = DeclaredResultRelation.from_output_shape(_NO_RESULT_OUTPUT_SHAPE)
_NO_RESULT_TYPE_HINTS = SqlColumnTypeHints()
logger = logging.getLogger(__name__)


@dataclass(frozen=True, slots=True)
class _DatabaseCommitEffect(PipelineLifecycleEffect):
    phase: PipelineLifecyclePhase = field(
        default=PipelineLifecyclePhase.DATABASE_COMMIT,
        init=False,
    )


@dataclass(frozen=True, slots=True)
class _CommitFinalizeEffect(PipelineLifecycleEffect):
    prepared_ref: ServerPlanRefId | None = None
    phase: PipelineLifecyclePhase = field(
        default=PipelineLifecyclePhase.AFTER_COMMIT_LOCAL,
        init=False,
    )


@dataclass(frozen=True, slots=True)
class VersionedRollbackStateEffect(PipelineLifecycleEffect):
    phase: PipelineLifecyclePhase = field(
        default=PipelineLifecyclePhase.AFTER_PHYSICAL_RESULT,
        init=False,
    )


def apply_commit_finalize_effect(
    payload: object,
    transaction_owner: object | None,
    prepared_result: object | None = None,
) -> None:
    if not isinstance(payload, _CommitFinalizeEffect):
        msg = "COMMIT_FINALIZE effect payload has the wrong type"
        raise TypeError(msg)
    base_txn, owns_base = _resolve_runtime_base_txn(transaction_owner)
    if not owns_base or not isinstance(base_txn, _CommittableTransactionProtocol):
        return
    base_txn._state = TransactionState.COMMITTED
    from l2050_transaction.transaction import LazyWriteTransaction

    if isinstance(base_txn, LazyWriteTransaction):
        base_txn._notify_transaction_lifecycle_committed()
    cache_owner = transaction_owner if transaction_owner is not None else base_txn
    prepared = cast("PreparedCacheCommit | None", prepared_result)
    if prepared is not None:
        setattr(cache_owner, "_generation_bumps_flushed", True)
    _commit_cache_transaction_best_effort(cache_owner, prepared)


# ---------------------------------------------------------------------------
# Protocols for step dependencies (avoids importing higher-layer modules)
# ---------------------------------------------------------------------------


@runtime_checkable
class _SqlConnectionProtocol(Protocol):
    """Minimal interface for a SQL connection used by lifecycle steps."""

    def _commit(self: _SqlConnectionProtocol) -> None: ...
    def _rollback(self: _SqlConnectionProtocol, *, recreate_cursor: bool = False) -> None: ...
    def _mark_data_transaction_backend_committed(self: _SqlConnectionProtocol) -> None: ...
    def _finish_transaction_trace_safely(self: _SqlConnectionProtocol, *, context: str) -> None: ...
    async def commit_async(self: _SqlConnectionProtocol) -> None: ...
    async def rollback_async(self: _SqlConnectionProtocol) -> None: ...


@runtime_checkable
class _CommittableTransactionProtocol(Protocol):
    """Transaction that can be committed."""

    _state: object  # TransactionState enum


@runtime_checkable
class _CommitLifecycleHookProtocol(Protocol):
    """Transaction that owns backend-specific commit hooks."""

    def _serverplan_commit_sync(self: _CommitLifecycleHookProtocol) -> None: ...
    async def _serverplan_commit_async(self: _CommitLifecycleHookProtocol) -> None: ...


@runtime_checkable
class _RollbackableTransactionProtocol(Protocol):
    """Transaction that can be rolled back."""

    _state: object  # TransactionState enum


@runtime_checkable
class _CacheTransactionProtocol(Protocol):
    """Cache transaction surface used during commit/rollback finalization."""

    is_committed: bool
    is_rolled_back: bool

    def commit(self: _CacheTransactionProtocol, prepared: PreparedCacheCommit | None = None) -> None: ...
    def rollback(self: _CacheTransactionProtocol) -> None: ...


@runtime_checkable
class _CacheGenerationTagsProtocol(Protocol):
    """Optional cache transaction surface for generation split details."""

    def invalidation_tags(self: _CacheGenerationTagsProtocol) -> set[str]: ...
    def write_tags(self: _CacheGenerationTagsProtocol) -> set[str]: ...


@runtime_checkable
class _TaggedCacheTransactionProtocol(Protocol):
    """Cache transaction surface that reports which tags were touched."""

    def touched_tags(self: _TaggedCacheTransactionProtocol) -> object: ...


@runtime_checkable
class _CacheOwningTransactionProtocol(Protocol):
    """Transaction that exposes a cache transaction for lifecycle finalization."""

    @property
    def _cache_transaction(self: _CacheOwningTransactionProtocol) -> _CacheTransactionProtocol | None: ...


@runtime_checkable
class _RollbackLifecycleHookProtocol(Protocol):
    """Transaction that owns backend-specific rollback hooks."""

    def _serverplan_rollback_sync(self: _RollbackLifecycleHookProtocol) -> None: ...
    async def _serverplan_rollback_async(self: _RollbackLifecycleHookProtocol) -> None: ...


@runtime_checkable
class _SessionTimestampLifecycleProtocol(Protocol):
    """Transaction that can suppress/cache session timestamp lifecycle work."""

    def _serverplan_should_update_session_timestamp(
        self: _SessionTimestampLifecycleProtocol,
    ) -> bool: ...
    def _serverplan_mark_session_timestamp_updated(
        self: _SessionTimestampLifecycleProtocol,
    ) -> None: ...


@runtime_checkable
class _VersionedTransactionProtocol(Protocol):
    """Versioned transaction with state and staged_commit_id."""

    _state: object  # TransactionState enum
    _staged_commit_id: object | None


def _is_versioned_write_txn(txn: object) -> bool:
    return isinstance(txn, VersionedWritePlanTarget)


def _resolve_base_txn(
    ctx: CompilationContext,
) -> tuple[object | None, bool]:
    """Resolve the base transaction and whether this step owns it."""
    txn = ctx.txn
    if txn is None:
        return None, False
    if _is_versioned_write_txn(txn):
        base_txn = getattr(txn, "base_write_transaction", getattr(txn, "_base_txn", None))
        owns_base = bool(getattr(txn, "owns_base_transaction", getattr(txn, "_owns_base_txn", False)))
        return base_txn, owns_base
    return txn, True


def _resolve_runtime_base_txn(txn: object | None) -> tuple[object | None, bool]:
    """Resolve the runtime base transaction and whether this step owns it."""
    if txn is None:
        return None, False
    if _is_versioned_write_txn(txn):
        base_txn = getattr(txn, "base_write_transaction", getattr(txn, "_base_txn", None))
        owns_base = bool(getattr(txn, "owns_base_transaction", getattr(txn, "_owns_base_txn", False)))
        return base_txn, owns_base
    return txn, True


def _resolve_versioned_txn(
    ctx: CompilationContext,
) -> _VersionedTransactionProtocol | None:
    """Resolve the versioned wrapper transaction if present."""
    txn = ctx.txn
    if _is_versioned_write_txn(txn) and isinstance(txn, _VersionedTransactionProtocol):
        return txn
    return None


def _resolve_sql_connection(
    ctx: CompilationContext,
) -> _SqlConnectionProtocol | None:
    """Resolve the SQL connection that should perform base commit/rollback."""
    base_txn, owns_base = _resolve_base_txn(ctx)
    if not owns_base:
        return None
    if base_txn is None:
        return None
    conn = getattr(base_txn, "_conn", None)
    if isinstance(conn, _SqlConnectionProtocol):
        return conn
    if isinstance(base_txn, _SqlConnectionProtocol):
        return base_txn
    conn = ctx.sql_handle
    return conn if isinstance(conn, _SqlConnectionProtocol) else None


def _resolve_runtime_sql_connection(
    txn: object | None,
    sql_connection: object | None,
) -> _SqlConnectionProtocol | None:
    """Resolve the SQL connection that should perform runtime commit/rollback."""
    base_txn, owns_base = _resolve_runtime_base_txn(txn)
    if txn is None or not owns_base:
        return sql_connection if isinstance(sql_connection, _SqlConnectionProtocol) else None
    if base_txn is None:
        return None
    conn = getattr(base_txn, "_conn", None)
    if isinstance(conn, _SqlConnectionProtocol):
        return conn
    if isinstance(base_txn, _SqlConnectionProtocol):
        return base_txn
    return sql_connection if isinstance(sql_connection, _SqlConnectionProtocol) else None


def _resolve_cache_transaction(txn: object) -> _CacheTransactionProtocol | None:
    """Return the cache transaction exposed by ``txn`` if present."""
    if not isinstance(txn, _CacheOwningTransactionProtocol):
        return None
    return txn._cache_transaction


def _resolve_cache_lifecycle_owner(txn: object | None) -> object | None:
    """Return the transaction whose cache lifecycle should be finalized."""
    from l7200_versioned_transactions.versioned_transactions import (
        LazyVersionedWriteTransaction,
    )

    if txn is None:
        return None
    if _resolve_cache_transaction(txn) is not None:
        return txn
    if not isinstance(txn, LazyVersionedWriteTransaction):
        return None
    base_txn = txn.base_write_transaction
    if _resolve_cache_transaction(base_txn) is not None:
        cache_txn: object | None = base_txn
        return cache_txn
    return None


def _ensure_supported_cache_commit(
    cache_txn: object | None,
    *,
    backend_name: str,
) -> None:
    """Reject tagged cache commits in backends without generation persistence."""
    if cache_txn is None or not isinstance(cache_txn, _TaggedCacheTransactionProtocol):
        return
    if cache_txn.touched_tags():
        msg = (
            f"{backend_name} cache generation persistence is not implemented in this commit path. "
            "Tagged cache writes and invalidations must not be committed here."
        )
        raise NotImplementedError(msg)


def build_cache_commit_lifecycle_steps(
    *,
    ref_id: ServerPlanRefId,
    cache_txn: CacheTransaction,
    finalize_ref: str,
) -> list[ServerPlanStep[Any]]:
    """Build the shared cache-generation persistence tail for commit lifecycles."""
    from impl.common.l2070_server_plan.steps.cache_steps import (
        BuildPreparedCacheCommitStep,
        CacheMissingGenerationMode,
        CachePreparedRowKind,
        CollectTouchedCacheTagsStep,
        LoadReferencedCacheGenerationsStep,
        PersistPreparedCacheGenerationInsertsStep,
        PersistPreparedCacheGenerationUpdatesStep,
        PublishPreparedCacheGenerationRowsStep,
    )

    cache_tags_ref = f"{ref_id}_cache_tags"
    cache_load_ref = f"{ref_id}_cache_load"
    cache_prepare_ref = f"{ref_id}_cache_prepare"
    cache_insert_rows_ref = f"{ref_id}_cache_insert_rows"
    cache_update_rows_ref = f"{ref_id}_cache_update_rows"
    cache_insert_ref = f"{ref_id}_cache_insert"
    cache_update_ref = f"{ref_id}_cache_update"
    db_commit_ref = f"{ref_id}_db_commit"
    return [
        cast(
            ServerPlanStep[None],
            CollectTouchedCacheTagsStep(
                ServerPlanRefId(cache_tags_ref),
                cache_txn=cache_txn,
            ),
        ),
        cast(
            ServerPlanStep[None],
            LoadReferencedCacheGenerationsStep(
                ServerPlanRefId(cache_load_ref),
                tags_ref=ServerPlanRefId(cache_tags_ref),
                fill_mode=CacheMissingGenerationMode.EXACT_ONLY,
            ),
        ),
        cast(
            ServerPlanStep[None],
            BuildPreparedCacheCommitStep(
                ServerPlanRefId(cache_prepare_ref),
                cache_txn=cache_txn,
                generations_ref=ServerPlanRefId(cache_load_ref),
            ),
        ),
        cast(
            ServerPlanStep[None],
            PublishPreparedCacheGenerationRowsStep(
                ServerPlanRefId(cache_insert_rows_ref),
                cache_txn=cache_txn,
                generations_ref=ServerPlanRefId(cache_load_ref),
                row_kind=CachePreparedRowKind.INSERT,
            ),
        ),
        cast(
            ServerPlanStep[None],
            PublishPreparedCacheGenerationRowsStep(
                ServerPlanRefId(cache_update_rows_ref),
                cache_txn=cache_txn,
                generations_ref=ServerPlanRefId(cache_load_ref),
                row_kind=CachePreparedRowKind.UPDATE,
            ),
        ),
        PersistPreparedCacheGenerationUpdatesStep(
            ServerPlanRefId(cache_update_ref),
            rows_ref=ServerPlanRefId(cache_update_rows_ref),
        ),
        PersistPreparedCacheGenerationInsertsStep(
            ServerPlanRefId(cache_insert_ref),
            rows_ref=ServerPlanRefId(cache_insert_rows_ref),
            after_refs=(ServerPlanRefId(cache_update_ref),),
        ),
        RuntimeDatabaseCommitAfterDepsStep(
            ServerPlanRefId(db_commit_ref),
            source_refs=[ServerPlanRefId(cache_insert_ref), ServerPlanRefId(cache_update_ref)],
        ),
        CommitFinalizeAfterDepsStep(
            ServerPlanRefId(finalize_ref),
            source_refs=[ServerPlanRefId(db_commit_ref)],
            prepared_ref=ServerPlanRefId(cache_prepare_ref),
        ),
    ]


def _commit_cache_transaction_best_effort(
    txn: object,
    prepared: PreparedCacheCommit | None,
) -> None:
    """Commit local cache state without letting cache backend failures escape."""
    cache_owner = _resolve_cache_lifecycle_owner(txn)
    if cache_owner is None:
        return
    cache_txn = _resolve_cache_transaction(cache_owner)
    if cache_txn is None:
        return
    prepared = _fill_empty_cache_prepare_from_persisted_generations(
        cache_owner=cache_owner,
        cache_txn=cache_txn,
        prepared=prepared,
    )
    try:
        cache_txn.commit(prepared)
    except Exception:
        logger.warning("Cache finalization failed after commit", exc_info=True)


def _fill_empty_cache_prepare_from_persisted_generations(
    *,
    cache_owner: object,
    cache_txn: _CacheTransactionProtocol,
    prepared: PreparedCacheCommit | None,
) -> PreparedCacheCommit | None:
    """Recover prepared cache generations from persisted DB rows when CTE rows are not retained."""
    if not isinstance(cache_txn, _TaggedCacheTransactionProtocol):
        return prepared
    touched_tags_raw = cache_txn.touched_tags()
    if not isinstance(touched_tags_raw, Iterable):
        return prepared
    touched_tags = set(touched_tags_raw)
    if not touched_tags:
        return prepared
    if prepared is not None and (prepared.bumped_generations or prepared.write_generations):
        return prepared
    load_generation_values = getattr(cache_owner, "_load_generation_values", None)
    if not callable(load_generation_values):
        return prepared

    from impl.common.l1000_cache.transaction import PreparedCacheCommit

    loaded_raw = load_generation_values(touched_tags)
    if not isinstance(loaded_raw, Mapping):
        return prepared
    loaded = {str(tag): int(generation) for tag, generation in loaded_raw.items()}
    if isinstance(cache_txn, _CacheGenerationTagsProtocol):
        invalidation_tags = set(cache_txn.invalidation_tags())
        write_tags = set(cache_txn.write_tags())
    else:
        invalidation_tags = set()
        write_tags = set()
    return PreparedCacheCommit(
        bumped_generations={tag: loaded.get(tag, 0) for tag in invalidation_tags},
        write_generations={tag: loaded.get(tag, 0) for tag in write_tags},
        insert_generations={},
        update_generations={},
        prepared_at=datetime.now(UTC),
    )


def _rollback_cache_transaction_best_effort(txn: object) -> None:
    """Rollback local cache state without letting cache backend failures escape."""
    cache_owner = _resolve_cache_lifecycle_owner(txn)
    if cache_owner is None:
        return
    cache_txn = _resolve_cache_transaction(cache_owner)
    if cache_txn is None or cache_txn.is_committed or cache_txn.is_rolled_back:
        return
    try:
        cache_txn.rollback()
    except Exception:
        logger.warning("Cache rollback finalization failed", exc_info=True)


def execute_event_dispatch_runtime_sync(txn: object | None) -> None:
    """Dispatch queued events before the database commit barrier."""
    from l5000_subscriptions.deferred_dispatch import dispatch_queued_events

    base_txn, owns_base = _resolve_runtime_base_txn(txn)
    if not owns_base or base_txn is None:
        return
    try:
        dispatch_queued_events(cast(Any, base_txn))
    except Exception:
        execute_database_rollback_runtime_sync(txn, None)
        execute_cache_rollback_runtime(txn)
        raise


async def execute_event_dispatch_runtime_async(txn: object | None) -> None:
    """Async variant of queued event dispatch before commit."""
    from l5000_subscriptions.deferred_dispatch import dispatch_queued_events_async

    base_txn, owns_base = _resolve_runtime_base_txn(txn)
    if not owns_base or base_txn is None:
        return
    try:
        await dispatch_queued_events_async(cast(Any, base_txn))
    except Exception:
        await execute_database_rollback_runtime_async(txn, None)
        execute_cache_rollback_runtime(txn)
        raise


def execute_database_commit_runtime_sync(
    txn: object | None,
    sql_connection: object | None,
) -> None:
    """Execute the database commit barrier through runtime lifecycle ownership."""
    from l2070_batching.transaction_resources import TransactionTemporaryRelationOwner
    base_txn, owns_base = _resolve_runtime_base_txn(txn)
    conn = _resolve_runtime_sql_connection(txn, sql_connection)
    if not owns_base and conn is None:
        return
    if isinstance(conn, TransactionTemporaryRelationOwner):
        conn._release_transaction_temporary_relations()
    from l1400_types.type_surface_contracts import DatabaseIdentity
    from l5000_subscriptions.deferred_dispatch import commit_capture_scope_sync

    identity = getattr(conn, "database_identity", None)
    assert identity is None or isinstance(identity, str)
    with commit_capture_scope_sync(base_txn, DatabaseIdentity(identity) if identity is not None else None):
        if isinstance(base_txn, _CommitLifecycleHookProtocol):
            base_txn._serverplan_commit_sync()
        elif conn is not None:
            conn._commit()
        if isinstance(conn, TransactionTemporaryRelationOwner):
            conn._forget_transaction_temporary_relations()
        if conn is not None:
            conn._mark_data_transaction_backend_committed()
            conn._finish_transaction_trace_safely(context="serverplan_db_commit")


async def execute_database_commit_runtime_async(
    txn: object | None,
    sql_connection: object | None,
) -> None:
    """Async variant of the database commit barrier."""
    from l2070_batching.transaction_resources import TransactionTemporaryRelationOwner
    base_txn, owns_base = _resolve_runtime_base_txn(txn)
    conn = _resolve_runtime_sql_connection(txn, sql_connection)
    if not owns_base and conn is None:
        return
    if isinstance(conn, TransactionTemporaryRelationOwner):
        await conn._release_transaction_temporary_relations_async()
    from l1400_types.type_surface_contracts import DatabaseIdentity
    from l5000_subscriptions.deferred_dispatch import commit_capture_scope_async

    identity = getattr(conn, "database_identity", None)
    assert identity is None or isinstance(identity, str)
    async with commit_capture_scope_async(base_txn, DatabaseIdentity(identity) if identity is not None else None):
        if isinstance(base_txn, _CommitLifecycleHookProtocol):
            await base_txn._serverplan_commit_async()
        elif conn is not None:
            await conn.commit_async()
        if isinstance(conn, TransactionTemporaryRelationOwner):
            conn._forget_transaction_temporary_relations()
        if conn is not None:
            conn._mark_data_transaction_backend_committed()
            conn._finish_transaction_trace_safely(context="serverplan_db_commit_async")


def execute_database_rollback_runtime_sync(
    txn: object | None,
    sql_connection: object | None,
) -> None:
    """Execute the database rollback barrier through runtime lifecycle ownership."""
    from l2070_batching.transaction_resources import TransactionTemporaryRelationOwner
    base_txn, owns_base = _resolve_runtime_base_txn(txn)
    conn = _resolve_runtime_sql_connection(txn, sql_connection)
    if not owns_base and conn is None:
        return
    if isinstance(base_txn, _RollbackLifecycleHookProtocol):
        base_txn._serverplan_rollback_sync()
    elif conn is not None:
        conn._rollback(recreate_cursor=False)
    if isinstance(conn, TransactionTemporaryRelationOwner):
        conn._rollback_transaction_temporary_relations()


async def execute_database_rollback_runtime_async(
    txn: object | None,
    sql_connection: object | None,
) -> None:
    """Async variant of the database rollback barrier."""
    from l2070_batching.transaction_resources import TransactionTemporaryRelationOwner
    base_txn, owns_base = _resolve_runtime_base_txn(txn)
    conn = _resolve_runtime_sql_connection(txn, sql_connection)
    if not owns_base and conn is None:
        return
    if isinstance(base_txn, _RollbackLifecycleHookProtocol):
        await base_txn._serverplan_rollback_async()
    elif conn is not None:
        await conn.rollback_async()
    if isinstance(conn, TransactionTemporaryRelationOwner):
        await conn._rollback_transaction_temporary_relations_async()


def execute_cache_rollback_runtime(txn: object | None) -> None:
    """Best-effort cache rollback through executor-owned lifecycle order."""
    if txn is None:
        return
    _rollback_cache_transaction_best_effort(txn)


def execute_pending_lazy_ops_rollback_runtime(txn: object | None) -> None:
    """Cancel pending lazy ORM operations through executor-owned rollback order."""
    if txn is None:
        return
    cancel = getattr(txn, "_cancel_pending_ops", None)
    if callable(cancel):
        cancel()


def execute_rollback_finalize_runtime(txn: object | None) -> None:
    """Mark the owned base transaction rolled back at runtime."""
    base_txn, owns_base = _resolve_runtime_base_txn(txn)
    if not owns_base or not isinstance(base_txn, _RollbackableTransactionProtocol):
        return
    base_txn._state = TransactionState.ROLLED_BACK
    from l2050_transaction.transaction import LazyWriteTransaction

    if isinstance(base_txn, LazyWriteTransaction):
        for participant in base_txn.transaction_lifecycle_participants():
            participant.owning_transaction_rolled_back()


def execute_versioned_rollback_state_runtime(txn: object | None) -> None:
    """Mark the versioned wrapper rolled back and clear staged commit state."""
    if not isinstance(txn, _VersionedTransactionProtocol):
        return
    from l7200_versioned_transactions.versioned_transactions import LazyVersionedWriteTransaction

    if isinstance(txn, LazyVersionedWriteTransaction):
        txn._restore_connection_speculative_publish_facts()
    txn._state = TransactionState.ROLLED_BACK
    txn._staged_commit_id = None


