class SessionTimestampUpdateStep(NonPublishingStep[None]):
    """L0: Update sys_sessions timestamp via SqlUpdateSessionTimestamp grammar.

    Emitted as part of the commit lifecycle for storage-backed sessions.
    Compile is a no-op only for the schema bootstrap identity.
    """

    def __init__(
        self: SessionTimestampUpdateStep,
        ref_id: ServerPlanRefId,
        *,
        depends_on: frozenset[ServerPlanRefId] = frozenset(),
    ) -> None:
        super().__init__(ref_id)
        self._dependencies = depends_on

    def dependencies(self: SessionTimestampUpdateStep) -> frozenset[str]:
        return frozenset(str(ref_id) for ref_id in self._dependencies)

    def sql_visible_dependencies(self: SessionTimestampUpdateStep) -> frozenset[str]:
        """The dependency is ordering-only; timestamp SQL consumes no producer relation."""
        return frozenset()

    def without_ordering_only_dependency(
        self: SessionTimestampUpdateStep,
        dependency_ref: str,
    ) -> SessionTimestampUpdateStep | None:
        matching_ref = next(
            (ref_id for ref_id in self._dependencies if str(ref_id) == dependency_ref),
            None,
        )
        if matching_ref is None:
            return None
        return SessionTimestampUpdateStep(
            self.ref_id,
            depends_on=self._dependencies - {matching_ref},
        )

    @property
    def level(self: SessionTimestampUpdateStep) -> int:
        return 0

    def result_cardinality(self: SessionTimestampUpdateStep) -> Cardinality:
        return Cardinality.NONE

    def is_read_only(self: SessionTimestampUpdateStep) -> bool:
        return False

    def execution_role(self: SessionTimestampUpdateStep) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def step_tags(self: SessionTimestampUpdateStep) -> frozenset[str]:
        return frozenset({"write", "session", "timestamp", "grammar"})

    def is_session_timestamp_touch(self: SessionTimestampUpdateStep) -> bool:
        return True

    def tables_read(self: SessionTimestampUpdateStep) -> frozenset[str]:
        return frozenset({"sys_sessions"})

    def tables_written(self: SessionTimestampUpdateStep) -> frozenset[str]:
        return frozenset({"sys_sessions"})

    def supports_sql_batch_transport(self: SessionTimestampUpdateStep) -> bool:
        return False

    def supports_ordered_sql_statement_batch(self: SessionTimestampUpdateStep) -> bool:
        return True

    def allows_later_sql_transport(self: SessionTimestampUpdateStep) -> bool:
        return True

    def emits_sql_for_accounting(self: SessionTimestampUpdateStep) -> bool:
        return True

    def compile(self: SessionTimestampUpdateStep, ctx: CompilationContext) -> CompiledStep[None]:
        if ctx.session_id is None:
            return CompiledStep()

        from l1300_session.session import SessionId
        from impl.common.l2050_sql_types.sql_branded_types import SqlGrammarValue, SysIdValue
        from impl.common.l2100_sql_grammar.domain.versioning.stmt_session import (
            SqlUpdateSessionTimestamp,
        )

        from l2070_batching.lazy_session_source import session_sql_source_or_none

        timestamp_value = datetime.now(UTC).isoformat()

        # A resolved session is touched by the query that identifies it. There is
        # no ``SessionId`` to build here -- ``str()`` on the source would produce a
        # repr, which is what this used to do before the guard below existed --
        # and the sentinel short-circuit is skipped because neither sentinel can
        # be the answer to a resolver's query: the SQL gate refuses a resolved
        # session that is system-typed or carries no user.
        source = session_sql_source_or_none(ctx.session_id)
        if source is not None:
            grammar = SqlUpdateSessionTimestamp(
                SqlGrammarValue(timestamp_value),
                source.session_id_expression(ctx),
            )
            return CompiledStep(grammar=grammar)
        from l2070_batching.server_ref import ScalarServerRef

        if isinstance(ctx.session_id, ScalarServerRef):
            from impl.common.l2100_sql_grammar.protocols import SqlRenderable

            session_expression: SqlRenderable
            if ctx.uses_bound_transaction_principal:
                from impl.common.l2100_sql_grammar.domain.triggers._expressions_trigger import (
                    SqlTriggerSessionId,
                )

                session_expression = SqlTriggerSessionId()
            else:
                from impl.common.l2070_server_plan.steps._compile_server_ref import (
                    lower_scalar_server_ref,
                )

                session_expression = lower_scalar_server_ref(ctx.session_id, ctx)
            return CompiledStep(
                grammar=SqlUpdateSessionTimestamp(
                    SqlGrammarValue(timestamp_value),
                    session_expression,
                ),
            )

        session_id_obj = SessionId(str(ctx.session_id))
        if session_id_obj.is_schema_session():
            return CompiledStep()

        session_id_param = SysIdValue(session_id_obj.unwrap_to_sql())
        grammar = SqlUpdateSessionTimestamp(SqlGrammarValue(timestamp_value), session_id_param)
        return CompiledStep(grammar=grammar)

    def counts_as_sql_group_for_accounting(self: SessionTimestampUpdateStep) -> bool | None:
        return False


