_RAW_CREATE_TABLE_PATTERN = r'^\s*CREATE\s+(?:TEMPORARY\s+|TEMP\s+)?TABLE\s+(?:IF\s+NOT\s+EXISTS\s+)?"?(?P<table>[A-Za-z0-9_]+)"?'
_RAW_CREATE_TRIGGER_ON_PATTERN = (
    r'^\s*CREATE\s+(?:TEMPORARY\s+|TEMP\s+)?TRIGGER\s+(?:IF\s+NOT\s+EXISTS\s+)?"?[A-Za-z0-9_]+"\s+.*?\bON\s+"?(?P<table>[A-Za-z0-9_]+)"?'
)
_RAW_CREATE_INDEX_ON_PATTERN = (
    r'^\s*CREATE\s+(?:UNIQUE\s+)?INDEX\s+(?:IF\s+NOT\s+EXISTS\s+)?"?[A-Za-z0-9_]+"\s+\bON\s+"?(?P<table>[A-Za-z0-9_]+)"?'
)
_RAW_ALTER_TABLE_PATTERN = r'^\s*ALTER\s+TABLE\s+"?(?P<table>[A-Za-z0-9_]+)"?'
_RAW_REFERENCED_TABLE_PATTERN = r'\b(?:FROM|JOIN|REFERENCES)\s+"?(?P<table>[A-Za-z0-9_]+)"?'
_NO_RESULT_OUTPUT_SHAPE = declared_zero_column_output_shape()
_NO_RESULT_RELATION = DeclaredResultRelation.from_output_shape(_NO_RESULT_OUTPUT_SHAPE)
_NO_RESULT_TYPE_HINTS = SqlColumnTypeHints()
_COUNT_OUTPUT_SHAPE = CompiledOutputShape((synthetic_output_field("count", role="affected_count"),))
_COUNT_RESULT_RELATION = DeclaredResultRelation.from_output_shape(_COUNT_OUTPUT_SHAPE)
_COUNT_TYPE_HINTS = SqlColumnTypeHints(bigint_columns=frozenset({"count"}))


def _raw_sql_tables_for_ddl_effect(stmt: object) -> tuple[frozenset[str], frozenset[str]]:
    raw_sql = getattr(stmt, "_sql", None)
    if not isinstance(raw_sql, str):
        return frozenset(), frozenset()
    writes: set[str] = set()
    create_match = re.match(_RAW_CREATE_TABLE_PATTERN, raw_sql, re.IGNORECASE | re.DOTALL)
    if create_match is not None:
        writes.add(create_match.group("table"))
    reads = {match.group("table") for match in re.finditer(_RAW_REFERENCED_TABLE_PATTERN, raw_sql, re.IGNORECASE | re.DOTALL)}
    trigger_match = re.match(_RAW_CREATE_TRIGGER_ON_PATTERN, raw_sql, re.IGNORECASE | re.DOTALL)
    if trigger_match is not None:
        reads.add(trigger_match.group("table"))
    index_match = re.match(_RAW_CREATE_INDEX_ON_PATTERN, raw_sql, re.IGNORECASE | re.DOTALL)
    if index_match is not None:
        reads.add(index_match.group("table"))
    alter_match = re.match(_RAW_ALTER_TABLE_PATTERN, raw_sql, re.IGNORECASE | re.DOTALL)
    if alter_match is not None:
        reads.add(alter_match.group("table"))
    reads.difference_update(writes)
    return frozenset(reads), frozenset(writes)


