@pure_lazy
def _is_schema_ddl_stmt(stmt: SqlRenderable) -> bool:
    if isinstance(stmt, SqlDdlBase):
        return True
    cls_name = type(stmt).__name__
    if cls_name.startswith(("SqlCreate", "SqlAlter", "SqlDrop", "SqlTruncate")) or cls_name in {
        "SqlRenameIndex",
    }:
        return True
    raw_sql = getattr(stmt, "_sql", None)
    return isinstance(raw_sql, str) and raw_sql.lstrip().upper().startswith(("CREATE ", "ALTER ", "DROP ", "TRUNCATE "))


