class GrammarEffectStep(ServerPlanStep[int]):
    """Step for SQL grammar statements with an effect and no row result."""

    def __init__(
        self: GrammarEffectStep,
        ref_id: ServerPlanRefId,
        stmt: SqlRenderable,
        config: _GrammarExecuteConfig,
        params: tuple[Any, ...] | None = None,
    ) -> None:
        super().__init__(ref_id)
        self._stmt = stmt
        self._params = params
        reads = config.reads
        writes = config.writes
        if not reads and not writes:
            inferred_reads, inferred_writes = infer_reads_writes_from_stmt(stmt)
            reads = frozenset(SqlTableName(table_name) for table_name in inferred_reads)
            writes = frozenset(SqlTableName(table_name) for table_name in inferred_writes)
        self._reads = reads
        self._writes = writes
        self._read_table_names = frozenset(str(table_name) for table_name in reads)
        self._write_table_names = frozenset(str(table_name) for table_name in writes)
        self._after_refs = frozenset(str(ref_id) for ref_id in config.after_refs)
        self._is_schema_ddl = _is_schema_ddl_stmt(stmt)
        from impl.common.l2100_sql_grammar.domain.infra.stmt_compound_write import (
            SqlStatementBatch,
            SqlStatementBatchCategory,
        )

        self._is_executor_owned_statement_batch = isinstance(stmt, SqlStatementBatch) and stmt.category in {
            SqlStatementBatchCategory.REQUEST_BATCH_BOUNDARY,
            SqlStatementBatchCategory.BUDGET_SPLIT,
            SqlStatementBatchCategory.BOOTSTRAP_DML,
        }
        self._supports_batch_transport = config.supports_batch_transport
        self._requires_prior_boundary = config.requires_prior_boundary
        self._collect_row_count = config.collect_row_count
        self._external_params_first = config.external_params_first
        template_cache_key = getattr(stmt, "template_cache_key", None)
        if callable(template_cache_key):
            stmt_key: object = template_cache_key()
        else:
            signature_key = getattr(stmt, "signature_key", None)
            stmt_key = signature_key if signature_key is not None else type(stmt)
        self._static_fingerprint = (
            "grammar-effect.static-scheduling.v1",
            type(self).__module__,
            type(self).__qualname__,
            type(stmt).__module__,
            type(stmt).__qualname__,
            stmt_key,
            tuple(sorted(self._read_table_names)),
            tuple(sorted(self._write_table_names)),
            self._is_schema_ddl,
            self._is_executor_owned_statement_batch,
            self._external_params_first,
            self._collect_row_count,
        )

    @property
    def level(self: GrammarEffectStep) -> int:
        return 0

    def step_tags(self: GrammarEffectStep) -> frozenset[str]:
        """Return tags identifying this step type."""
        if self._is_schema_ddl:
            return frozenset({"write", "grammar", "effect", "ddl", "schema_change"})
        return frozenset({"write", "grammar", "effect"})

    def is_read_only(self: GrammarEffectStep) -> bool:
        """Return False - grammar effects may modify data."""
        return False

    def supports_sql_batch_transport(self: GrammarEffectStep) -> bool:
        """Schema DDL cannot be transported inside SQL CTE batches."""
        return not self._is_schema_ddl and not self._is_executor_owned_statement_batch and self._supports_batch_transport

    def supports_ordered_sql_statement_batch(self: GrammarEffectStep) -> bool:
        return self._is_executor_owned_statement_batch

    def requires_prior_step_boundary(self: GrammarEffectStep) -> bool:
        """DDL must execute as its own statement after any preamble SQL."""
        return self._is_schema_ddl or self._requires_prior_boundary

    def result_cardinality(self: GrammarEffectStep) -> Cardinality:
        """Return NONE - this step returns no result."""
        return Cardinality.NONE

    def prepared_template_cache_descriptor(
        self: GrammarEffectStep,
    ) -> PreparedTemplateCacheDescriptor | None:
        """Return the complete reusable grammar-template identity."""
        template_cache_key = getattr(self._stmt, "template_cache_key", None)
        if not callable(template_cache_key):
            return None
        template_key = template_cache_key()
        if not isinstance(template_key, Hashable):
            msg = "Grammar template_cache_key() must return a hashable value."
            raise TypeError(msg)
        return PreparedTemplateCacheDescriptor(
            namespace="grammar-effect",
            template_key=template_key,
            read_tables=tuple(sorted(self._read_table_names)),
            write_tables=tuple(sorted(self._write_table_names)),
            external_params_first=self._external_params_first,
        )

    def cte_publication_contract(self: GrammarEffectStep) -> CtePublicationContract:
        """Effects do not publish SQL rows."""
        return CtePublicationContract.non_publishing()

    def tables_read(self: GrammarEffectStep) -> frozenset[str]:
        """Return the precomputed table names this step reads from."""
        return self._read_table_names

    def tables_written(self: GrammarEffectStep) -> frozenset[str]:
        """Return the precomputed table names this step writes to."""
        return self._write_table_names

    def dependencies(self: GrammarEffectStep) -> frozenset[str]:
        return self._after_refs

    def sql_visible_dependencies(self: GrammarEffectStep) -> frozenset[str]:
        """Grammar effects consume ``after_refs`` only as completion ordering."""
        return frozenset()

    def imported_dependency_refs(self: GrammarEffectStep) -> frozenset[ServerPlanRefId]:
        return frozenset()

    def consumes_executor_visible_dependencies(self: GrammarEffectStep) -> bool:
        return False

    def static_scheduling_fingerprint(self: GrammarEffectStep) -> tuple[object, ...] | None:
        return self._static_fingerprint

    def internal_plan_ref_state(self: GrammarEffectStep) -> PlanPayloadState:
        return _internal_plan_state_without_stmt(self)

    def _compile_effect_grammar(
        self: GrammarEffectStep,
        ctx: CompilationContext,
        *,
        stmt: SqlRenderable,
        result_mode: GrammarEffectResultMode,
    ) -> CompiledStep[int]:
        from impl.common.l2070_server_plan.steps._grammar_bridge_provenance import (
            build_execute_bridge_manifest,
        )
        from impl.common.l2100_sql_grammar.domain.infra.stmt_compound_write import SqlStatementBatch

        provenance_manifest, allow_empty_manifest = build_execute_bridge_manifest(
            stmt=self._stmt,
            ctx=ctx,
            reads=self._reads,
            writes=self._writes,
            row_scope_kind="grammar-effect",
        )
        return CompiledStep(
            grammar=stmt,
            params=None if isinstance(stmt, SqlStatementBatch) else self._params,
            external_params_first=False if isinstance(stmt, SqlStatementBatch) else self._external_params_first,
            needs_returning=result_mode is GrammarEffectResultMode.RETURNING_RELATION,
            closed_post_op=_count_column_post_op(),
            output_shape=_COUNT_OUTPUT_SHAPE,
            result_relation=_COUNT_RESULT_RELATION,
            column_type_hints=_COUNT_TYPE_HINTS,
            provenance_manifest=provenance_manifest,
            allow_empty_provenance_manifest=allow_empty_manifest,
        )

    def compile(self: GrammarEffectStep, ctx: CompilationContext) -> CompiledStep[int]:
        """Compile this step to a CompiledStep for SQL backends."""
        stmt = self._stmt
        if not self._collect_row_count:
            from impl.common.l2070_server_plan.steps._grammar_bridge_provenance import (
                build_execute_bridge_manifest,
            )

            provenance_manifest, allow_empty_manifest = build_execute_bridge_manifest(
                stmt=stmt,
                ctx=ctx,
                reads=self._reads,
                writes=self._writes,
                row_scope_kind="grammar-effect",
            )
            return CompiledStep(
                grammar=stmt,
                params=self._params,
                external_params_first=self._external_params_first,
                output_shape=_NO_RESULT_OUTPUT_SHAPE,
                result_relation=_NO_RESULT_RELATION,
                column_type_hints=_NO_RESULT_TYPE_HINTS,
                provenance_manifest=provenance_manifest,
                allow_empty_provenance_manifest=allow_empty_manifest,
            )
        result_mode = GrammarEffectResultMode.ROW_COUNT
        if self._is_executor_owned_statement_batch:
            return self._compile_effect_grammar(
                ctx,
                stmt=stmt,
                result_mode=result_mode,
            )
        result_transport = ctx.backend_profile.traits.dml_result_transport
        if not self._is_schema_ddl and result_transport is DmlResultTransport.RETURNING_RELATION:
            ref_token = "".join(ch if ch.isalnum() else "_" for ch in str(self.ref_id)).strip("_") or "effect"
            stmt = _returning_count_relation(stmt, cte_name=SqlCteName(f"{ref_token}_rows"))
            result_mode = GrammarEffectResultMode.RETURNING_RELATION
        elif not self._is_schema_ddl and result_transport is DmlResultTransport.STATEMENT_CHANGE_FUNCTION:
            stmt = _returning_count_ordered_batch(
                stmt,
                params=self._params,
                external_params_first=self._external_params_first,
            )
            result_mode = GrammarEffectResultMode.RETURNING_RELATION
            compiled = self._compile_effect_grammar(
                ctx,
                stmt=stmt,
                result_mode=result_mode,
            )
            if self._params:
                return replace(compiled, params=None, external_params_first=False)
            return compiled
        return self._compile_effect_grammar(
            ctx,
            stmt=stmt,
            result_mode=result_mode,
        )


class BootstrapDmlWorkProductStep(GrammarEffectStep):
    """Typed ordered bootstrap-DML product that can absorb compatible producers."""

    def is_bootstrap_dml_work_product(self: BootstrapDmlWorkProductStep) -> bool:
        return True

    def compile(self: BootstrapDmlWorkProductStep, ctx: CompilationContext) -> CompiledStep[int]:
        """Preserve the closed executor-owned batch and its synthetic count transport."""
        return self._compile_effect_grammar(
            ctx,
            stmt=self._stmt,
            result_mode=GrammarEffectResultMode.ROW_COUNT,
        )

    def __init__(
        self: BootstrapDmlWorkProductStep,
        ref_id: ServerPlanRefId,
        stmt: SqlRenderable,
        config: _GrammarExecuteConfig,
        absorbed_refs: frozenset[str] = frozenset(),
    ) -> None:
        from impl.common.l2100_sql_grammar.domain.infra.stmt_compound_write import (
            SqlStatementBatch,
            SqlStatementBatchCategory,
        )

        if not isinstance(stmt, SqlStatementBatch) or stmt.category is not SqlStatementBatchCategory.BOOTSTRAP_DML:
            msg = "BootstrapDmlWorkProductStep requires a BOOTSTRAP_DML SqlStatementBatch"
            raise TypeError(msg)
        super().__init__(ref_id, stmt, config)
        self._absorbed_refs = absorbed_refs

    @property
    def absorbed_refs(self: BootstrapDmlWorkProductStep) -> frozenset[str]:
        """Refs of the products this step swallowed, which it now satisfies itself.

        A merge keeps the earlier product's ref and discards the later one's, so anything
        that still names the discarded ref is naming work this step now performs. Those
        edges have to be recognized rather than carried: an ordering pass resolves a
        vanished ref back to the step that absorbed it, and an unfiltered edge therefore
        reads as the step depending on itself -- reported as a dependency cycle among the
        batch's children, far from the merge that created it.
        """
        return self._absorbed_refs

    @property
    def provided_refs(self: BootstrapDmlWorkProductStep) -> frozenset[str]:
        """Every ref this product satisfies once it has run.

        Not just its own ref_id: it also answers for the products it absorbed and for the
        result labels and source refs its batch publishes, because those are how the rest of
        bootstrap names the writes inside it.
        """
        from impl.common.l2100_sql_grammar.domain.infra.stmt_compound_write import SqlStatementBatch

        batch = cast("SqlStatementBatch", self._stmt)
        return frozenset(
            {
                str(self.ref_id),
                *self._absorbed_refs,
                *batch.logical_source_refs,
                *(label for label in batch.result_labels_per_stmt if label),
            },
        )

    def bootstrap_dml_provided_refs(self: BootstrapDmlWorkProductStep) -> frozenset[str]:
        return self.provided_refs

    def absorbing_bootstrap_dml_ordering_aliases(
        self: BootstrapDmlWorkProductStep,
        aliases: frozenset[str],
    ) -> BootstrapDmlWorkProductStep:
        return self.absorbing_ordering_aliases(aliases)

    def absorbing_ordering_aliases(
        self: BootstrapDmlWorkProductStep,
        alias_refs: frozenset[str],
    ) -> BootstrapDmlWorkProductStep:
        """Take over the ordering guarantee of planning-only aliases naming this product's work.

        A collapsed static bridge publishes no value; it survives only to keep the shape of a
        dependency graph whose real edges point at the writes behind it. When those writes are
        all inside this product, the alias adds nothing this product does not already promise,
        so this product can answer for the alias ref directly.

        Doing so is what lets a run of products keep growing. Bootstrap threads consecutive
        mutations through such aliases, so without this the alias sits between two products and
        each one becomes its own transport -- while carrying the alias as a live dependency
        instead would make the fused product depend on a step that depends on it.

        The caller owns the precondition: absorb an alias only after checking that everything
        the alias depends on is already satisfied at this product's position.
        """
        config = _GrammarExecuteConfig(
            reads=self._reads,
            writes=self._writes,
            after_refs=frozenset(ServerPlanRefId(ref_id) for ref_id in self.dependencies() - alias_refs),
            external_params_first=self._external_params_first,
        )
        return BootstrapDmlWorkProductStep(
            self.ref_id,
            self._stmt,
            config,
            self._absorbed_refs | alias_refs,
        )

    def step_tags(self: BootstrapDmlWorkProductStep) -> frozenset[str]:
        return super().step_tags() | frozenset({"bootstrap", "work_product", "ordered_statement_batch"})

    def bootstrap_dml_combination_operand(
        self: BootstrapDmlWorkProductStep,
    ) -> BootstrapDmlCombinationOperand | None:
        from impl.common.l2100_sql_grammar.domain.infra.stmt_compound_write import SqlStatementBatch

        batch = cast("SqlStatementBatch", self._stmt)
        return BootstrapDmlCombinationOperand(
            ref_id=self.ref_id,
            statement=batch,
            absorbed_refs=self._absorbed_refs,
            dependencies=self.dependencies(),
            reads=frozenset(str(table) for table in self._reads),
            writes=frozenset(str(table) for table in self._writes),
            external_params_first=self._external_params_first,
        )

    def combine_bootstrap_dml_operand(
        self: BootstrapDmlWorkProductStep,
        operand: BootstrapDmlCombinationOperand,
    ) -> BootstrapDmlWorkProductStep | None:
        return self._combine_operand(operand)

    def combine_compatible(
        self: BootstrapDmlWorkProductStep,
        other: BootstrapDmlWorkProductStep,
    ) -> BootstrapDmlWorkProductStep | None:
        """Combine ordered products while retaining only external proof edges."""
        operand = other.bootstrap_dml_combination_operand()
        assert operand is not None
        return self._combine_operand(operand)

    def _combine_operand(
        self: BootstrapDmlWorkProductStep,
        operand: BootstrapDmlCombinationOperand,
    ) -> BootstrapDmlWorkProductStep:
        from impl.common.l2100_sql_grammar.domain.infra.stmt_compound_write import (
            SqlStatementBatch,
            SqlStatementBatchCategory,
        )

        left = cast("SqlStatementBatch", self._stmt)
        right = operand.statement
        absorbed_refs = self._absorbed_refs | operand.absorbed_refs | {str(operand.ref_id)}
        internal_refs = frozenset(
            {
                str(self.ref_id),
                *absorbed_refs,
                *left.logical_source_refs,
                *(label for label in left.result_labels_per_stmt if label is not None),
            }
        )
        combined_dependencies = (self.dependencies() | operand.dependencies) - internal_refs
        combined_phase = left.logical_phase if left.logical_phase == right.logical_phase else "bootstrap_dml:mixed"
        left_external_counts = left.external_param_counts_per_stmt
        right_external_counts = right.external_param_counts_per_stmt
        combined_external_counts = (
            None if left_external_counts is None or right_external_counts is None else (*left_external_counts, *right_external_counts)
        )
        combined = SqlStatementBatch(
            (*left.statements, *right.statements),
            category=SqlStatementBatchCategory.BOOTSTRAP_DML,
            params_per_stmt=(*left.params_per_stmt, *right.params_per_stmt),
            external_param_counts_per_stmt=combined_external_counts,
            external_params_first=(*left.external_params_first_per_stmt, *right.external_params_first_per_stmt),
            needs_returning_per_stmt=(*left.needs_returning_per_stmt, *right.needs_returning_per_stmt),
            collect_results_per_stmt=(*left.collect_results_per_stmt, *right.collect_results_per_stmt),
            savepoint_recovery_per_stmt=(*left.savepoint_recovery_per_stmt, *right.savepoint_recovery_per_stmt),
            result_labels_per_stmt=(*left.result_labels_per_stmt, *right.result_labels_per_stmt),
            logical_statement_count=left.leaf_statement_count() + right.leaf_statement_count(),
            logical_source_refs=(*left.logical_source_refs, *right.logical_source_refs),
            logical_phase=combined_phase,
        )
        config = _GrammarExecuteConfig(
            reads=self._reads | frozenset(SqlTableName(table) for table in operand.reads),
            writes=self._writes | frozenset(SqlTableName(table) for table in operand.writes),
            after_refs=frozenset(ServerPlanRefId(ref_id) for ref_id in combined_dependencies),
            external_params_first=self._external_params_first or operand.external_params_first,
        )
        return BootstrapDmlWorkProductStep(self.ref_id, combined, config, absorbed_refs)


class DdlEffectStep(ServerPlanStep[PlanEffect]):
    """Terminal step for schema DDL effects."""

    def is_ddl_operation(self: DdlEffectStep) -> bool:
        return True

    def __init__(
        self: DdlEffectStep,
        ref_id: ServerPlanRefId,
        stmt: SqlRenderable,
        after_refs: Iterable[ServerPlanRefId] = (),
    ) -> None:
        super().__init__(ref_id)
        self._stmt = stmt
        self._after_refs = frozenset(str(ref_id) for ref_id in after_refs)

    @property
    def level(self: DdlEffectStep) -> int:
        return 0

    def step_tags(self: DdlEffectStep) -> frozenset[str]:
        """Return tags identifying schema DDL effects."""
        return frozenset({"write", "grammar", "effect", "ddl", "schema_change"})

    def supports_sql_batch_transport(self: DdlEffectStep) -> bool:
        """Schema DDL must run as its own statement, not inside SQL fusion."""
        return False

    def supports_ordered_sql_statement_batch(self: DdlEffectStep) -> bool:
        """General DDL effects retain an explicit executor boundary."""
        return False

    def scheduling_fingerprint(self: DdlEffectStep) -> tuple[object, ...]:
        """Include statement shape because DDL batch safety depends on SQL text."""
        signature_key = getattr(self._stmt, "signature_key", None)
        if signature_key is not None:
            stmt_key: object = signature_key
        else:
            raw_sql = getattr(self._stmt, "_sql", None)
            if isinstance(raw_sql, str):
                stmt_key = ("raw_sql", raw_sql)
            else:
                stmt_key = (type(self._stmt).__module__, type(self._stmt).__qualname__)
        return (
            type(self).__qualname__,
            str(self.ref_id),
            tuple(sorted(self._after_refs)),
            stmt_key,
        )

    def requires_prior_step_boundary(self: DdlEffectStep) -> bool:
        """Prior steps must complete before schema changes execute."""
        return True

    def counts_as_sql_group_for_warning(self: DdlEffectStep) -> bool | None:
        """DDL emits SQL even though it is not SQL-batch transportable."""
        return True

    def emits_sql_for_accounting(self: DdlEffectStep) -> bool | None:
        """DDL is real SQL for execution accounting."""
        return True

    def execution_role(self: DdlEffectStep) -> StepExecutionRole:
        """DDL is SQL execution with schema-specific scheduling constraints."""
        return StepExecutionRole.SQL

    def is_read_only(self: DdlEffectStep) -> bool:
        """Return False - DDL mutates schema state."""
        return False

    def result_cardinality(self: DdlEffectStep) -> Cardinality:
        """Return NONE - DDL returns no row result."""
        return Cardinality.NONE

    def publishes_executor_visible_binding(self: DdlEffectStep) -> bool:
        """DDL effects are ordering dependencies, not SQL-visible row relations."""
        return False

    def tables_read(self: DdlEffectStep) -> frozenset[str]:
        """Return existing tables this schema DDL depends on."""
        inferred_reads, _inferred_writes = infer_reads_writes_from_stmt(self._stmt)
        raw_reads, _raw_writes = _raw_sql_tables_for_ddl_effect(self._stmt)
        existing_table_targets: set[str] = set()
        stmt_type_name = type(self._stmt).__name__
        if stmt_type_name.startswith("SqlCreateTrigger"):
            _trigger_reads, trigger_targets = infer_reads_writes_from_stmt(self._stmt)
            existing_table_targets.update(str(table_name) for table_name in trigger_targets)
        if stmt_type_name == "SqlCreateIndexStmt":
            index_table = getattr(self._stmt, "_table", None)
            table_name = getattr(index_table, "_name", None)
            if table_name is not None:
                existing_table_targets.add(str(table_name))
        add_column_target = getattr(self._stmt, "single_add_column_target", None)
        if callable(add_column_target):
            target = add_column_target()
            if target is not None:
                if not isinstance(target, tuple) or len(target) != 2:
                    msg = "single_add_column_target() must return a table/column pair"
                    raise TypeError(msg)
                table_ident, _column_name = target
                table_name = getattr(table_ident, "_name", None)
                if table_name is not None:
                    existing_table_targets.add(str(table_name))
        return inferred_reads | raw_reads | frozenset(existing_table_targets)

    def tables_written(self: DdlEffectStep) -> frozenset[str]:
        """Return schema tables created or mutated by this DDL effect."""
        if type(self._stmt).__name__ == "SqlDropTrigger":
            return frozenset()
        _inferred_reads, inferred_writes = infer_reads_writes_from_stmt(self._stmt)
        _raw_reads, raw_writes = _raw_sql_tables_for_ddl_effect(self._stmt)
        create_index_table_writes: set[str] = set()
        if type(self._stmt).__name__ == "SqlCreateIndexStmt":
            index_table = getattr(self._stmt, "_table", None)
            table_name = getattr(index_table, "_name", None)
            if table_name is not None:
                create_index_table_writes.add(str(table_name))
        add_column_target = getattr(self._stmt, "single_add_column_target", None)
        if callable(add_column_target):
            target = add_column_target()
            if target is not None:
                if not isinstance(target, tuple) or len(target) != 2:
                    msg = "single_add_column_target() must return a table/column pair"
                    raise TypeError(msg)
                table_ident, _column_name = target
                table_name = getattr(table_ident, "_name", None)
                if table_name is not None:
                    create_index_table_writes.add(str(table_name))
        return inferred_writes | raw_writes | frozenset(create_index_table_writes)

    def dependencies(self: DdlEffectStep) -> frozenset[str]:
        """Return prior DDL refs that must complete before this schema effect."""
        return self._after_refs

    def imported_dependency_refs(self: DdlEffectStep) -> frozenset[ServerPlanRefId]:
        """DDL predecessors are ordering effects, not imported row bindings."""
        return frozenset()

    def consumes_executor_visible_dependencies(self: DdlEffectStep) -> bool:
        return False

    def internal_plan_ref_state(self: DdlEffectStep) -> PlanPayloadState:
        return _internal_plan_state_without_stmt(self)

    def cte_publication_contract(self: DdlEffectStep) -> CtePublicationContract:
        return CtePublicationContract.non_publishing()

    def compile(self: DdlEffectStep, ctx: CompilationContext) -> CompiledStep[PlanEffect]:
        """Compile schema DDL as a standalone SQL statement."""
        from impl.common.l2070_server_plan.steps._grammar_bridge_provenance import (
            build_execute_bridge_manifest,
        )

        provenance_manifest, allow_empty_manifest = build_execute_bridge_manifest(
            stmt=self._stmt,
            ctx=ctx,
            reads=frozenset(),
            writes=frozenset(),
            row_scope_kind="ddl-effect",
        )
        return CompiledStep(
            grammar=self._stmt,
            closed_post_op=literal_post_op(PlanEffect(ref_id=str(self.ref_id))),
            output_shape=None,
            result_relation=None,
            column_type_hints=None,
            provenance_manifest=provenance_manifest,
            allow_empty_provenance_manifest=allow_empty_manifest,
            use_savepoint_recovery=False,
        )


class BootstrapDdlWorkProductStep(DdlEffectStep):
    """Typed terminal child for one closed, order-preserving bootstrap DDL bundle."""

    def __init__(
        self: BootstrapDdlWorkProductStep,
        ref_id: ServerPlanRefId,
        stmt: SqlRenderable,
        after_refs: Iterable[ServerPlanRefId] = (),
    ) -> None:
        if type(stmt).__name__ != "SqlDdlBundle":
            msg = "BootstrapDdlWorkProductStep requires a SqlDdlBundle"
            raise TypeError(msg)
        super().__init__(ref_id, stmt, after_refs)

    def step_tags(self: BootstrapDdlWorkProductStep) -> frozenset[str]:
        return super().step_tags() | frozenset({"bootstrap", "work_product", "ordered_statement_batch"})

    def supports_ordered_sql_statement_batch(self: BootstrapDdlWorkProductStep) -> bool:
        return True

    def supports_sql_batch_transport(self: BootstrapDdlWorkProductStep) -> bool:
        return False

    def requires_prior_step_boundary(self: BootstrapDdlWorkProductStep) -> bool:
        return True

    def compile(self: BootstrapDdlWorkProductStep, ctx: CompilationContext) -> CompiledStep[PlanEffect]:
        """Split PostgreSQL DDL leaves; other drivers execute their native bundle."""
        if ctx.backend_profile.traits.ddl_bundle_transport is DdlBundleTransport.NATIVE_BUNDLE:
            return super().compile(ctx)
        from impl.common.l2100_sql_grammar.domain.infra.stmt_compound_write import (
            SqlStatementBatch,
            SqlStatementBatchCategory,
            SqlStatementKind,
        )

        bundle = object.__getattribute__(self, "_stmt")
        statements = tuple(getattr(bundle, "statements"))
        source_refs = tuple(getattr(bundle, "logical_source_refs", ()))
        labels = source_refs if source_refs else tuple(str(self.ref_id) for _statement in statements)
        batch = SqlStatementBatch(
            statements,
            category=SqlStatementBatchCategory.ORDERED_SEMANTIC,
            params_per_stmt=tuple(None for _statement in statements),
            needs_returning_per_stmt=tuple(False for _statement in statements),
            collect_results_per_stmt=tuple(False for _statement in statements),
            savepoint_recovery_per_stmt=tuple(False for _statement in statements),
            result_labels_per_stmt=labels,
            statement_kinds_per_stmt=tuple(SqlStatementKind.DDL for _statement in statements),
            logical_statement_count=len(statements),
            logical_source_refs=labels,
            logical_phase=getattr(bundle, "logical_phase", None),
        )
        return replace(super().compile(ctx), grammar=batch)


