class TombstoneGrammarStep(GrammarEffectStep):
    """GrammarEffectStep variant that carries tombstone sys_ids in memory.

    Used by VersionedDeleteManyIntent so the StagingBypassOptimizer can
    intercept tombstone operations and bypass staging.
    """

    def __init__(
        self: TombstoneGrammarStep,
        ref_id: ServerPlanRefId,
        stmt: SqlRenderable,
        config: _TombstoneGrammarConfig,
    ) -> None:
        super().__init__(
            ref_id,
            stmt,
            config=_GrammarExecuteConfig(
                reads=config.reads,
                writes=config.writes,
            ),
        )
        self.tombstone_sys_ids = list(config.tombstone_sys_ids)
        self.tip_table = config.tip_table
        self.data_columns = list(config.data_columns)
        self.lazy_branch = config.lazy_branch
        self.staged_commit_id_raw = config.staged_commit_id_raw

    def build_staging_bypass_tombstone(
        self: TombstoneGrammarStep,
        staged_delete: StagingBypassStagedDelete,
        inline_staged_commit_ids: frozenset[StagedCommitId],
        *,
        include_generated_storage_columns: bool,
    ) -> ServerPlanStep[Any] | None:
        if self.staged_commit_id_raw not in inline_staged_commit_ids:
            return None
        written_tables = tuple(self.tables_written())
        if len(written_tables) != 1 or SqlTableName(written_tables[0]) != staged_delete.staged_table_name:
            return None
        if staged_delete.staged_commit_ids and not staged_delete.staged_commit_ids.issubset(inline_staged_commit_ids):
            return None

        from l1000_schema.table_registry import get_model_for_table
        from impl.common.l2070_server_plan.steps.commit_branch_steps import _normalize_branch_ref
        from impl.common.l2070_server_plan.steps.pending_tombstone_from_merged import (
            PendingTombstoneFromMergedStep,
            _PendingTombstoneFromMergedConfig,
        )

        tip_model = get_model_for_table(self.tip_table)
        if tip_model is None:
            return None
        return PendingTombstoneFromMergedStep(
            self.ref_id,
            config=_PendingTombstoneFromMergedConfig(
                staged_table_name=staged_delete.staged_table_name,
                tip_table_name=self.tip_table,
                staged_model=staged_delete.staged_model,
                tip_model=tip_model,
                data_columns=tuple(self.data_columns),
                lazy_branch=_normalize_branch_ref(self.lazy_branch),
                staged_commit_id=self.staged_commit_id_raw,
                sys_ids=tuple(self.tombstone_sys_ids),
                include_generated_storage_columns=include_generated_storage_columns,
                depends_on=frozenset(
                    {
                        *(ServerPlanRefId(dependency) for dependency in self.dependencies()),
                        *staged_delete.dependencies,
                    },
                ),
            ),
        )

    def cte_relation_role(self: TombstoneGrammarStep) -> str | None:
        return "count_only"

    def cte_publication_contract(self: TombstoneGrammarStep) -> CtePublicationContract:
        columns = ("count",)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=columns,
            column_type_hints=_COUNT_TYPE_HINTS,
            relation_contract=CteRelationContract.literal_mapping(columns=columns),
            relation_role=self.cte_relation_role(),
            source_tables=self.tables_written(),
        )

    def staged_write_descriptor(self: TombstoneGrammarStep) -> PendingStagedWrite | None:
        if len(self._writes) != 1:
            return None
        staged_table_name = next(iter(self._writes))
        return PendingStagedWrite(
            source_key=StagedSourceKey(
                staged_table_name=staged_table_name,
                branch_scope_token=opaque_scope_token(self.lazy_branch),
            ),
            staged_commit_id_raw=self.staged_commit_id_raw.unwrap_to_str(),
            write_kind="tombstone",
        )

    def compile(self: TombstoneGrammarStep, ctx: CompilationContext) -> CompiledStep[int]:
        """Compile tombstone writes and count inserted rows.

        PostgreSQL counts a DML ``RETURNING`` relation. SQLite and MariaDB
        read the server's affected-row function immediately after the DML.
        Both forms publish one canonical ``count`` relation.
        """
        from impl.common.l2070_server_plan.steps._grammar_bridge_provenance import (
            build_execute_bridge_manifest,
        )
        from impl.common.l2100_sql_grammar.domain.infra.stmt_compound_write import SqlStatementBatch

        supports_returning = ctx.sql_render_dialect().supports_returning()
        stmt = self._stmt

        if supports_returning:
            needs_returning = True
            if ctx.supports_data_modifying_ctes:
                ref_token = "".join(ch if ch.isalnum() else "_" for ch in str(self.ref_id)).strip("_") or "tombstone"
                stmt = _returning_count_relation(self._stmt, cte_name=SqlCteName(f"{ref_token}_rows"))
                closed_post_op = _count_column_post_op()
            else:
                stmt = _returning_count_ordered_batch(
                    self._stmt,
                    params=self._params,
                    external_params_first=self._external_params_first,
                )
                closed_post_op = _count_column_post_op()
            output_shape, result_relation, column_type_hints = _count_compiled_artifacts()
        else:
            stmt = _returning_count_ordered_batch(
                stmt,
                params=self._params,
                external_params_first=self._external_params_first,
            )
            needs_returning = True
            closed_post_op = _count_column_post_op()
            output_shape, result_relation, column_type_hints = _count_compiled_artifacts()

        provenance_manifest, allow_empty_manifest = build_execute_bridge_manifest(
            stmt=self._stmt,
            ctx=ctx,
            reads=self._reads,
            writes=self._writes,
            row_scope_kind="grammar-tombstone-effect",
        )
        return CompiledStep(
            grammar=stmt,
            params=None if isinstance(stmt, SqlStatementBatch) else self._params,
            needs_returning=needs_returning,
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
            external_params_first=self._external_params_first,
            closed_post_op=closed_post_op,
            provenance_manifest=provenance_manifest,
            allow_empty_provenance_manifest=allow_empty_manifest,
        )

