@dataclass(frozen=True, slots=True)
class _InsertManyConfig:
    pass


@dataclass(frozen=True, slots=True)
class _InsertManyStepConfig:
    """Optional compile-time payload for ``InsertManyStep``.

    ``literal_instances`` carries the already-prepared Python row instances
    when the caller knows the concrete batch at plan-construction time.
    ``InsertManyStep._instances`` continues to hold the symbolic
    ``ObjectSequenceServerRef`` (always present) for dependency tracking and
    runtime resolution; the literal slot is what compile/lowering use to
    generate the actual SQL batch without peeking into ServerRef literals.
    ``write_column_count`` is captured during lowering from ``PlanningCatalog``
    so batching budget checks do not need to consult runtime schema state.
    """

    literal_instances: tuple[Any, ...] | None = None
    write_column_count: int | None = None
    after_refs: frozenset[ServerPlanRefId] = frozenset()
    return_instances: tuple[Any, ...] | None = None
    supplemental_write_values: tuple[_SupplementalWriteValues, ...] | None = None


def _required_insert_many_column_type_hints(
    model_cls: type[DatabaseObjectRow[Any]],
    columns: tuple[str, ...],
) -> SqlColumnTypeHints:
    hints = model_sql_column_type_hints(model_cls, columns)
    if hints is None:
        msg = f"No SQL column type hints available for {model_cls.__name__}"
        raise TypeError(msg)
    return hints


def _insert_many_returning_columns(model_cls: type[DatabaseObjectRow[Any]]) -> tuple[str, ...]:
    from l2070_batching.write_column_policy import physical_table_publication_columns

    return physical_table_publication_columns(model_cls, include_shared_subtypes=False)


class InsertManyStep[T](SqlRelationPublisherStep[list[T]]):
    """ServerPlan step for inserting multiple records."""

    def __init__(
        self: InsertManyStep,
        ref_id: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow[Any]],
        instances: ObjectSequenceServerRef[Any],
        *,
        config: _InsertManyStepConfig | None = None,
    ) -> None:
        """Initialize InsertManyStep.

        Args:
            ref_id: Reference ID for this step's result
            model_cls: The DatabaseObjectRow subclass
            instances: Symbolic ObjectSequenceServerRef for the insert batch.
            config: Optional compile-time payload. When ``literal_instances``
                is set, compile/lowering use it directly instead of peeking at
                the symbolic ref's literal slot.
        """
        super().__init__(ref_id)
        self._model_cls: type[DatabaseObjectRow[Any]] = model_cls
        self._instances: ObjectSequenceServerRef[Any] = instances
        self._literal_instances: tuple[Any, ...] | None = config.literal_instances if config is not None else None
        self._write_column_count: int | None = config.write_column_count if config is not None else None
        self._after_refs: frozenset[ServerPlanRefId] = config.after_refs if config is not None else frozenset()
        self._return_instances: tuple[Any, ...] | None = config.return_instances if config is not None else None
        self._dependency_refs = self._compute_dependencies()
        self._supplemental_write_values = config.supplemental_write_values if config is not None else None

    @property
    def level(self: InsertManyStep) -> int:
        return 1

    def step_tags(self: InsertManyStep) -> frozenset[str]:
        """Return semantic tags for this step."""
        return frozenset({"write", "insert", "bulk"})

    def is_read_only(self: InsertManyStep) -> bool:
        """Return False - inserts modify data."""
        return False

    def has_unbounded_params(self: InsertManyStep) -> bool:
        """Treat only large insert batches as unbounded for fusion heuristics."""
        if self._literal_instances is None or self._write_column_count is None:
            return True
        threshold = int(_UNBOUNDED_PARAM_ROW_THRESHOLD)
        return len(self._literal_instances) > threshold

    def supports_sql_batch_transport(self) -> bool:
        return self._literal_instances is not None

    def requires_materialized_inputs(self) -> bool:
        return self._literal_instances is None

    def requires_prior_step_boundary(self) -> bool:
        return self._literal_instances is None

    def estimated_param_count(self: InsertManyStep) -> int | None:
        """Return a conservative upper bound for one physical insert batch."""
        if self._literal_instances is None or self._write_column_count is None:
            return None
        return len(self._literal_instances) * self._write_column_count

    def result_cardinality(self: InsertManyStep) -> Cardinality:
        """Return MANY - insert_many returns multiple rows."""
        return Cardinality.MANY

    def publishes_executor_visible_binding(self: InsertManyStep) -> bool:
        return True

    def always_publishes_executor_visible_binding(self: InsertManyStep) -> bool:
        return True

    def cte_publication_contract(self: InsertManyStep) -> CtePublicationContract:
        def _legacy_cte_output_columns() -> tuple[str, ...]:
            return _insert_many_returning_columns(self._model_cls)

        columns = _legacy_cte_output_columns()
        column_type_hints = model_sql_column_type_hints(self._model_cls, columns)
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        contract_columns = tuple(str(column) for column in columns)
        _contract_model_cls = cte_projection_row_model(
            f"{type(self).__name__}CteRow",
            contract_columns,
            column_type_hints,
        )
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=contract_columns,
            column_type_hints=column_type_hints,
            model_cls=_contract_model_cls,
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def tables_read(self: InsertManyStep) -> frozenset[str]:
        """Insert FK reads are exposed through catalog-backed optimizer facts."""
        return frozenset()

    def tables_written(self: InsertManyStep) -> frozenset[str]:
        """Return the table name this step writes to."""
        return frozenset({get_table_name(self._model_cls)})

    def foreign_key_checks(
        self: InsertManyStep,
        planning_catalog: PlanningCatalog | None = None,
    ) -> frozenset[ForeignKeyCheckFact]:
        from l2055_lazy_result.lazy_result import LazyResult

        if self._literal_instances is not None:
            return foreign_key_checks_for_instances(
                self._model_cls,
                self._literal_instances,
                planning_catalog,
            )
        if isinstance(self._instances, LazyResult):
            return foreign_key_checks_for_instances(
                self._model_cls,
                [self._instances],
                planning_catalog,
            )
        if not isinstance(self._instances, Sequence):
            return foreign_key_checks_for_instances(
                self._model_cls,
                [self._instances],
                planning_catalog,
            )
        return foreign_key_checks_for_instances(self._model_cls, self._instances, planning_catalog)

    def foreign_key_read_tables(
        self: InsertManyStep,
        planning_catalog: PlanningCatalog | None = None,
    ) -> frozenset[str]:
        return insert_fk_read_tables(self._model_cls, planning_catalog)

    def write_key_facts(
        self: InsertManyStep,
        planning_catalog: PlanningCatalog | None = None,
    ) -> frozenset[WriteKeyFact]:
        from l2055_lazy_result.lazy_result import LazyResult

        if self._literal_instances is not None:
            return write_key_facts_for_instances(
                self.ref_id,
                self._model_cls,
                self._literal_instances,
                planning_catalog,
            )
        if isinstance(self._instances, LazyResult):
            return write_key_facts_for_instances(
                self.ref_id,
                self._model_cls,
                [self._instances],
                planning_catalog,
            )
        if not isinstance(self._instances, Sequence):
            return write_key_facts_for_instances(
                self.ref_id,
                self._model_cls,
                [self._instances],
                planning_catalog,
            )
        return write_key_facts_for_instances(
            self.ref_id,
            self._model_cls,
            self._instances,
            planning_catalog,
        )

    def _compute_dependencies(self: InsertManyStep) -> frozenset[str]:
        from l2055_lazy_result.lazy_param import server_value_deps

        refs = {str(ref_id) for ref_id in self._after_refs}
        refs.update(server_value_deps(self._instances))
        if isinstance(self._instances, ObjectSequenceServerRef) and self._instances.ref_id is not None:
            refs.add(str(self._instances.ref_id))
        if self._literal_instances is not None:
            for instance in self._literal_instances:
                refs.update(collect_instance_deps(instance))
        return frozenset(ref for ref in refs if not ref.partition(".")[0].startswith("seed_"))

    def dependencies(self: InsertManyStep) -> frozenset[str]:
        """Return immutable dependency facts computed from the construction payload."""
        return self._dependency_refs

    def consumes_executor_visible_dependencies(self: InsertManyStep) -> bool:
        return bool(self.dependencies())

    def lower(self: InsertManyStep, ctx: LoweringContext) -> list[ServerPlanStep[Any]]:
        del ctx
        from impl.common.l2070_server_plan.steps.collect_results import StaticValueAfterDepsStep
        from impl.common.l2070_server_plan.steps.row_hydration import (
            MaterializeResolvedModelSequenceStep,
        )

        raw_ref = ServerPlanRefId(f"{self.ref_id}.raw")
        child_config = (
            _InsertManyStepConfig(
                literal_instances=self._literal_instances,
                write_column_count=self._write_column_count,
                after_refs=self._after_refs,
                return_instances=self._return_instances,
                supplemental_write_values=self._supplemental_write_values,
            )
            if self._literal_instances is not None
            else None
        )
        steps: list[ServerPlanStep[Any]] = [
            InsertManyRawResultStep(
                raw_ref,
                self._model_cls,
                self._instances,
                config=child_config,
            ),
        ]
        if self._literal_instances is not None:
            steps.append(
                StaticValueAfterDepsStep(
                    ServerPlanRefId(self.ref_id),
                    list(self._return_instances or self._literal_instances),
                    [str(raw_ref)],
                ),
            )
        else:
            steps.append(
                MaterializeResolvedModelSequenceStep(
                    self.ref_id,
                    source_ref=raw_ref,
                    model_cls=self._model_cls,
                    source_is_executor_owned=True,
                ),
            )
        return steps

    def compile(self: InsertManyStep, ctx: CompilationContext) -> CompiledStep:
        return cast(
            CompiledStep,
            compile_insert_many_raw_result_step(
                model_cls=self._model_cls,
                instances=self._instances,
                literal_instances=self._literal_instances,
                source_ref_id=self.ref_id,
                supplemental_write_values=self._supplemental_write_values,
                ctx=ctx,
                publication_ref_id=self.ref_id,
                publication_contract=self.cte_publication_contract(),
            ),
        )


def compile_insert_many_raw_result_step(
    *,
    model_cls: type[DatabaseObjectRow[Any]],
    instances: Sequence[Any] | ObjectSequenceServerRef[Any],
    literal_instances: tuple[Any, ...] | None = None,
    supplemental_write_values: tuple[_SupplementalWriteValues, ...] | None = None,
    ctx: CompilationContext,
    source_ref_id: ServerPlanRefId | None = None,
    publication_ref_id: ServerPlanRefId,
    publication_contract: CtePublicationContract,
) -> CompiledStep[list[object]]:
    """Compile the terminal raw-result bulk insert surface directly."""
    instances_source: Sequence[Any] | ObjectSequenceServerRef[Any]
    if literal_instances is not None:
        instances_source = list(literal_instances)
    elif isinstance(instances, ObjectSequenceServerRef):
        from impl.common.l2050_sql_types.sql_branded_types import SqlAliasName, SqlColumnName, SqlTableName
        from impl.common.l2070_server_plan.steps._compile_helpers import (
            cast_postgres_expr_for_db_column,
            filter_columns_to_existing_schema,
            get_write_metadata_plan_from_catalog,
        )
        from impl.common.l2070_server_plan.steps._query_helper_compile import (
            _collect_auxiliary_ctes_from_consumed,
        )
        from impl.common.l2070_server_plan.steps._auxiliary_ctes import collect_dependency_auxiliary_ctes
        from impl.common.l2100_sql_grammar.domain.infra.stmt_dml_simple import (
            SqlColumnListFragment,
            SqlInsertFromSelectStmt,
        )
        from impl.common.l2100_sql_grammar.domain.infra.stmt_compound_write import (
            SqlStatementBatch,
            SqlStatementBatchCategory,
        )
        from impl.common.l2100_sql_grammar.tree.clauses import (
            SqlJoin,
            SqlReturningClause,
            SqlSelectAlias,
            SqlSelectList,
            SqlTableAlias,
        )
        from impl.common.l2100_sql_grammar.tree.enums import BinaryOp, JoinKind
        from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef
        from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
        from impl.common.l2100_sql_grammar.tree.statements import SqlSelect
        from l1000_schema.table_utils import get_table_name
        from l2070_batching.compilation import CteReference

        source_ref = instances.ref_id
        source_binding = ctx.cte_refs.get(str(source_ref)) if source_ref is not None else None
        if not isinstance(source_binding, CteReference):
            msg = "InsertManyRawResultStep requires a lowering-time concrete instance sequence or a SQL-visible object-sequence CTE."
            raise ValueError(msg)
        write_plan = get_write_metadata_plan_from_catalog(ctx.planning_catalog, model_cls)
        if source_binding.columns is None:
            db_columns = [field_plan.db_column for field_plan in write_plan.field_plans]
        else:
            source_columns = set(source_binding.columns)
            db_columns = [field_plan.db_column for field_plan in write_plan.field_plans if field_plan.db_column in source_columns]
        if not db_columns:
            msg = f"InsertManyRawResultStep source {source_ref!r} does not expose writable columns for {model_cls.__name__}"
            raise ValueError(msg)
        column_refs = [SqlColumnRef(SqlColumnName(column_name)) for column_name in db_columns]
        select_columns = SqlColumnListFragment(
            [
                SqlSelectAlias(
                    cast_postgres_expr_for_db_column(
                        backend_type=ctx.backend_type,
                        write_plan=write_plan,
                        db_column=column_name,
                        expr=column_ref,
                    ),
                    alias=SqlAliasName(column_name),
                )
                for column_name, column_ref in zip(db_columns, column_refs, strict=True)
            ],
        )
        supports_returning = ctx.sql_render_dialect().supports_insert_returning()
        returning_columns = _insert_many_returning_columns_for_schema(model_cls, get_table_name(model_cls), ctx)
        output_shape, result_relation, column_type_hints = _insert_many_returning_shape(model_cls, returning_columns=returning_columns)
        returning_clause = (
            SqlReturningClause(
                [SqlColumnRef(SqlColumnName(column_name)) for column_name in returning_columns],
            )
            if supports_returning
            else None
        )
        output_shape, result_relation, column_type_hints = _insert_many_returning_shape(
            model_cls,
            returning_columns=returning_columns,
        )
        insert_stmt = SqlInsertFromSelectStmt(
            target=get_table_name(model_cls),
            columns=SqlColumnListFragment(column_refs),
            source=SqlTableName(source_binding.ref_id),
            select_columns=select_columns,
            returning=returning_clause,
        )
        if supports_returning:
            return CompiledStep(
                grammar=insert_stmt,
                needs_returning=True,
                auxiliary_ctes=collect_dependency_auxiliary_ctes(ctx, str(source_ref)),
                output_shape=output_shape,
                result_relation=result_relation,
                column_type_hints=column_type_hints,
                closed_post_op=row_dicts_post_op(),
            )
        target_alias = "inserted_target"
        source_alias = "inserted_source"
        sys_id_column = SqlColumnName("sys_id")
        readback_select = SqlSelect(
            select=SqlSelectList(
                [
                    SqlColumnRef(
                        SqlColumnName(column_name),
                        qualifier=target_alias,
                    )
                    for column_name in returning_columns
                ],
            ),
            from_=SqlTableAlias(
                SqlTableIdent(get_table_name(model_cls)),
                SqlAliasName(target_alias),
            ),
            joins=[
                SqlJoin(
                    join_type=JoinKind.INNER,
                    table=SqlTableAlias(
                        SqlTableIdent(SqlTableName(source_binding.ref_id)),
                        SqlAliasName(source_alias),
                    ),
                    condition=SqlBinaryOp(
                        SqlColumnRef(sys_id_column, qualifier=target_alias),
                        BinaryOp.EQ,
                        SqlColumnRef(sys_id_column, qualifier=source_alias),
                    ),
                ),
            ],
        )
        return CompiledStep(
            grammar=SqlStatementBatch(
                [insert_stmt, readback_select],
                category=SqlStatementBatchCategory.ORDERED_SEMANTIC,
                needs_returning_per_stmt=[False, True],
                collect_results_per_stmt=[False, True],
            ),
            needs_returning=True,
            compiled_sql_publication=compiled_repeatable_sql_publication(
                ref_id=publication_ref_id,
                query=readback_select,
                contract=publication_contract,
            ),
            auxiliary_ctes=collect_dependency_auxiliary_ctes(ctx, str(source_ref)),
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
            closed_post_op=row_dicts_post_op(),
        )
    else:
        instances_source = instances

    from l1000_schema.table_utils import get_table_name
    from impl.common.l2050_sql_types.sql_branded_types import SqlAliasName, SqlColumnName, SqlTableName
    from impl.common.l2070_server_plan.steps._projected_row_source import build_projected_row_select
    from impl.common.l2070_server_plan.steps._compile_helpers import (
        _ResolvedWriteRowPlan,
        _resolve_write_row_plan,
        filter_columns_to_existing_schema,
        filter_row_plans_to_existing_schema,
        get_write_metadata_plan_from_catalog,
    )
    from impl.common.l2070_server_plan.steps._compile_insert import (
        require_insert_columns_after_schema_filter,
    )
    from impl.common.l2070_server_plan.steps._prepare_instance import (
        prepare_instance_for_insert_lazy,
    )
    from impl.common.l2100_sql_grammar.domain.infra.stmt_compound_write import (
        SqlStatementBatch,
        SqlStatementBatchCategory,
    )
    from impl.common.l2100_sql_grammar.domain.infra.stmt_dml_simple import (
        SqlColumnListFragment,
        SqlInsertFromSelectStmt,
    )
    from impl.common.l2100_sql_grammar.domain.versioning.identifier_fragments import SqlColumnRef
    from impl.common.l2100_sql_grammar.protocols import SqlRenderable
    from impl.common.l2100_sql_grammar.tree.clauses import (
        SqlJoin,
        SqlColumnNameList,
        SqlPlaceholderRows,
        SqlReturningClause,
        SqlSelectList,
        SqlTableAlias,
        SqlValuesSource,
    )
    from impl.common.l2100_sql_grammar.tree.enums import BinaryOp, JoinKind
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef as SqlExprColumnRef
    from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp
    from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlStar
    from impl.common.l2100_sql_grammar.tree.statements import SqlInsert, SqlSelect

    table_name = get_table_name(model_cls)
    table = SqlTableName(table_name)

    prepared: list[Any] = [prepare_instance_for_insert_lazy(model_cls, inst) for inst in cast(Sequence[Any], instances_source)]
    if not prepared:
        return CompiledStep(closed_post_op=literal_array_post_op(()))
    from impl.common.l2070_server_plan.steps.intent_crud import _apply_trust_for_lowering

    prepared = [_apply_trust_for_lowering(ctx, model_cls, inst) for inst in prepared]

    write_plan = get_write_metadata_plan_from_catalog(ctx.planning_catalog, model_cls)
    supplemental_rows = supplemental_write_values
    if supplemental_rows is None:
        supplemental_rows = tuple(() for _instance in prepared)
    if len(supplemental_rows) != len(prepared):
        msg = "InsertManyStep supplemental write rows must match the prepared instance count"
        raise ValueError(msg)
    row_plans: list[_ResolvedWriteRowPlan] = []
    for inst, supplemental_values in zip(prepared, supplemental_rows, strict=True):
        row_plans.append(
            _resolve_write_row_plan(
                write_plan,
                inst,
                backend_type=ctx.backend_type,
                supplemental_values=supplemental_values,
            ),
        )
    canonical_columns = row_plans[0].columns
    for row_plan in row_plans[1:]:
        if row_plan.columns != canonical_columns:
            msg = (
                "InsertManyStep requires a uniform write column signature across all rows. "
                f"expected={canonical_columns!r}, actual={row_plan.columns!r}"
            )
            raise ValueError(msg)
    columns = list(canonical_columns)
    filtered_columns, row_plans = filter_row_plans_to_existing_schema(
        ctx.schema_column_cache,
        SqlTableName(table_name),
        columns,
        row_plans,
    )
    columns = list(filtered_columns)
    require_insert_columns_after_schema_filter(
        table_name=SqlTableName(table_name),
        columns=columns,
        operation="InsertManyStep",
    )

    col_list = SqlColumnNameList([SqlColumnRef(SqlColumnName(c)) for c in columns])

    supports_returning = (
        ctx.backend_profile.traits.dml_result_transport is DmlResultTransport.RETURNING_RELATION
        and ctx.sql_render_dialect().supports_returning()
    )
    returning_columns = filter_columns_to_existing_schema(
        ctx.schema_column_cache,
        SqlTableName(table_name),
        _insert_many_returning_columns(model_cls),
    )
    returning_clause = (
        SqlReturningClause([SqlColumnRef(SqlColumnName(column)) for column in returning_columns]) if supports_returning else None
    )
    json_columns: frozenset[str] = frozenset(field_plan.db_column for field_plan in write_plan.field_plans if field_plan.is_json)
    postgres_json_columns: frozenset[str] = frozenset()
    if ctx.backend_profile.traits.dml_parameter_transport is DmlParameterTransport.EXPLICIT_STORAGE_CASTS:
        from impl.common.l2300_json_serialization.json_serialization import get_json_columns

        type_hints = model_sql_column_type_hints(model_cls, tuple(columns))
        postgres_json_column_set = set(get_json_columns(model_cls))
        postgres_json_column_set.update(json_columns)
        if type_hints is not None:
            postgres_json_column_set.update(type_hints.jsonb_columns)
        postgres_json_columns = frozenset(postgres_json_column_set)

    def _insert_param(column: str, value: object) -> object:
        if ctx.backend_profile.traits.dml_parameter_transport is not DmlParameterTransport.EXPLICIT_STORAGE_CASTS:
            from l1000_schema.json_type import to_json_sql_param_value

            return to_json_sql_param_value(value, is_json_column=column in json_columns)
        if column not in postgres_json_columns or value is None:
            return value
        from impl.common.l2100_sql_params.runtime_bind_slot import SqlRuntimeBindSlot

        if isinstance(value, SqlRuntimeBindSlot):
            return replace(value, json_encoded=True)
        from impl.common.l2100_sql_params.sql_param_normalization import normalize_postgres_json_bind_value

        return normalize_postgres_json_bind_value(value)

    def _build_insert(
        row_batch: list[Any],
        *,
        returning: bool,
    ) -> tuple[SqlInsert, tuple[Any, ...]]:
        placeholder_rows = SqlPlaceholderRows(
            columns=len(columns),
            rows=len(row_batch),
        )
        params = tuple(
            _insert_param(column, value) for row_plan in row_batch for column, value in zip(columns, row_plan.values, strict=True)
        )
        return (
            SqlInsert(
                table=table,
                columns=col_list,
                values=SqlValuesSource(placeholder_rows),
                returning=returning_clause if returning else None,
            ),
            params,
        )

    output_shape = None
    result_relation = None
    returning_column_type_hints: SqlColumnTypeHints | None = None
    if supports_returning:
        output_shape, result_relation, returning_column_type_hints = _insert_many_returning_shape(
            model_cls,
            returning_columns=returning_columns,
        )
    else:
        output_shape, result_relation, returning_column_type_hints = _insert_many_returning_shape(
            model_cls,
            returning_columns=returning_columns,
        )

    if ctx.backend_profile.traits.dml_bulk_transport is DmlBulkTransport.PAYLOAD_AWARE_BOUND_VALUES and row_plans:
        from impl.common.l2070_server_plan.steps._projected_row_source import (
            build_postgres_raw_bulk_rows,
            postgres_raw_bulk_column_types,
        )
        from impl.common.l2050_sql_types.sql_branded_types import SqlTypeName
        from impl.common.l2100_sql_grammar.tree.insert_source import SqlInsertSelectSource
        from impl.common.l5200_sql_query.query_grammar import QueryGrammarBuilder
        from l2060_query_builder.plan_composition import param, query, unnest

        row_values = [tuple(row_plan.values) for row_plan in row_plans]
        column_types = postgres_raw_bulk_column_types(
            model_cls,
            columns,
            write_plan=write_plan,
        )
        if column_types is not None:
            row_source = build_postgres_raw_bulk_rows(
                rows=row_values,
                db_columns=columns,
                column_types=column_types,
                ctx=ctx,
            )
            if row_source.select_source is not None:
                grammar: Any = SqlInsert(
                    table=table,
                    columns=col_list,
                    values=row_source.select_source,
                    returning=returning_clause,
                )
            else:
                assert row_source.array_params is not None
                bulk_rows = unnest(
                    *(param(array_param) for array_param in row_source.array_params),
                    types=tuple(SqlTypeName(column_type) for column_type in row_source.column_types),
                    columns=tuple(columns),
                    alias="__bulk_src",
                )
                select_source = QueryGrammarBuilder(
                    query(bulk_rows).project(*(bulk_rows.column(column) for column in columns)).to_query_spec(),
                    compilation_context=ctx,
                ).build_select_stmt()
                grammar = SqlInsert(
                    table=table,
                    columns=col_list,
                    values=cast(SqlRenderable, SqlInsertSelectSource(select_source)),
                    returning=returning_clause,
                )
            closed_post_op = row_dicts_post_op()
            if not supports_returning:
                closed_post_op = literal_post_op(list(prepared))
            return CompiledStep(
                grammar=grammar,
                needs_returning=supports_returning,
                output_shape=output_shape,
                result_relation=result_relation,
                column_type_hints=returning_column_type_hints,
                closed_post_op=closed_post_op,
            )

    if not supports_returning:
        source_identity = source_ref_id or ServerPlanRefId(table_name)
        source_suffix = sha256(str(source_identity).encode()).hexdigest()[:12]
        source_cte_name = f"_nera_insert_many_{source_suffix}"
        source_db_columns = [*columns, *(column for column in returning_columns if column not in columns)]
        source_rows = [
            (
                *tuple(_insert_param(column, value) for column, value in zip(columns, row_plan.values, strict=True)),
                *(None for column in source_db_columns if column not in columns),
            )
            for row_plan in row_plans
        ]
        source_query = build_projected_row_select(
            rows=source_rows,
            db_columns=source_db_columns,
            ctx=ctx,
        )
        source_column_refs = [SqlExprColumnRef(SqlColumnName(column_name)) for column_name in columns]
        insert_stmt = SqlInsertFromSelectStmt(
            target=table,
            columns=SqlColumnListFragment(source_column_refs),
            source=SqlTableName(source_cte_name),
            select_columns=SqlColumnListFragment(source_column_refs),
        )
        target_alias = "inserted_target"
        source_alias = "inserted_source"
        sys_id_column = SqlColumnName("sys_id")
        readback_select = SqlSelect(
            select=SqlSelectList(
                [SqlExprColumnRef(SqlColumnName(column_name), qualifier=target_alias) for column_name in returning_columns],
            ),
            from_=SqlTableAlias(
                SqlTableIdent(table),
                SqlAliasName(target_alias),
            ),
            joins=[
                SqlJoin(
                    join_type=JoinKind.INNER,
                    table=SqlTableAlias(
                        SqlTableIdent(SqlTableName(source_cte_name)),
                        SqlAliasName(source_alias),
                    ),
                    condition=SqlBinaryOp(
                        SqlExprColumnRef(sys_id_column, qualifier=target_alias),
                        BinaryOp.EQ,
                        SqlExprColumnRef(sys_id_column, qualifier=source_alias),
                    ),
                ),
            ],
        )
        return CompiledStep(
            grammar=SqlStatementBatch(
                [insert_stmt, readback_select],
                category=SqlStatementBatchCategory.ORDERED_SEMANTIC,
                needs_returning_per_stmt=[False, True],
                collect_results_per_stmt=[False, True],
            ),
            needs_returning=True,
            compiled_sql_publication=compiled_repeatable_sql_publication(
                ref_id=publication_ref_id,
                query=readback_select,
                contract=publication_contract,
            ),
            auxiliary_ctes=[(source_cte_name, source_query)],
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=returning_column_type_hints,
            closed_post_op=row_dicts_post_op(),
        )

    grammar, params = _build_insert(row_plans, returning=supports_returning)

    closed_post_op = row_dicts_post_op()

    return CompiledStep(
        grammar=grammar,
        params=params,
        external_params_first=True,
        needs_returning=supports_returning,
        output_shape=output_shape,
        result_relation=result_relation,
        column_type_hints=returning_column_type_hints,
        closed_post_op=closed_post_op,
    )


def _insert_many_returning_shape(
    model_cls: type[DatabaseObjectRow[Any]],
    *,
    returning_columns: Sequence[str] | None = None,
) -> tuple[Any, Any, SqlColumnTypeHints]:
    from l1000_schema.schema_def import get_db_column_name
    from l2070_batching.output_shape import (
        CompiledOutputShape,
        DeclaredResultRelation,
        synthetic_output_field,
    )

    columns = tuple(returning_columns) if returning_columns is not None else _insert_many_returning_columns(model_cls)
    output_shape = CompiledOutputShape(tuple(synthetic_output_field(column) for column in columns))
    return (
        output_shape,
        DeclaredResultRelation.from_output_shape(output_shape),
        _required_insert_many_column_type_hints(model_cls, columns),
    )


def _insert_many_returning_columns_for_schema(
    model_cls: type[DatabaseObjectRow[Any]],
    table_name: SqlTableName,
    ctx: CompilationContext,
) -> tuple[str, ...]:
    """Returning columns restricted to columns the cached DB schema actually has.

    The model may declare columns that are not yet present in the database (e.g.
    during a rolling deploy where code lands before the migration). The INSERT
    column list is filtered against the executor-published schema cache, so the
    explicit ``RETURNING`` clause must be filtered identically; otherwise it would
    reference a column that does not exist and fail at execution.
    """
    from impl.common.l2070_server_plan.steps._compile_helpers import (
        filter_columns_to_existing_schema,
    )

    return filter_columns_to_existing_schema(
        ctx.schema_column_cache,
        table_name,
        _insert_many_returning_columns(model_cls),
    )


class InsertManyRawResultStep(InsertManyStep[object]):
    """Terminal raw-result variant for bulk inserts."""

    @property
    def level(self) -> int:
        return 0

    def step_tags(self) -> frozenset[str]:
        return frozenset({"write", "insert", "bulk", "raw"})

    def supports_sql_batch_transport(self) -> bool:
        return self._literal_instances is not None or not isinstance(self._instances, ObjectSequenceServerRef)

    def supports_ordered_sql_statement_batch(self) -> bool:
        return self.supports_sql_batch_transport()

    def requires_materialized_inputs(self) -> bool:
        return self._literal_instances is None and isinstance(self._instances, ObjectSequenceServerRef)

    def requires_prior_step_boundary(self) -> bool:
        return self._literal_instances is None and isinstance(self._instances, ObjectSequenceServerRef)

    def publishes_executor_visible_binding(self) -> bool:
        return True

    def always_publishes_executor_visible_binding(self) -> bool:
        return False

    def cte_publication_contract(self: InsertManyRawResultStep) -> CtePublicationContract:
        columns = getattr(self, "_compiled_publication_columns", None)
        if columns is None:
            columns = _insert_many_returning_columns(self._model_cls)
        column_type_hints = model_sql_column_type_hints(self._model_cls, columns)
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        contract_columns = tuple(str(column) for column in columns)
        _contract_model_cls = cte_projection_row_model(
            f"{type(self).__name__}CteRow",
            contract_columns,
            column_type_hints,
        )
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=contract_columns,
            column_type_hints=column_type_hints,
            model_cls=_contract_model_cls,
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def lower(self, ctx: LoweringContext) -> list[ServerPlanStep[Any]]:
        del ctx
        return [self]

    def compile(self, ctx: CompilationContext) -> CompiledStep[list[object]]:
        """Compile multi-row INSERT and return raw rows or prepared models."""
        compiled = compile_insert_many_raw_result_step(
            model_cls=self._model_cls,
            instances=self._instances,
            literal_instances=self._literal_instances,
            source_ref_id=self.ref_id,
            supplemental_write_values=self._supplemental_write_values,
            ctx=ctx,
            publication_ref_id=self.ref_id,
            publication_contract=self.cte_publication_contract(),
        )
        if compiled.output_shape is not None:
            self._compiled_publication_columns = compiled.output_shape.cte_output_columns
        return compiled

