_MISSING_FIELD = object()
_UNKNOWN_SERVER_REF_FIELD = object()
_NULL_KEY_CELL = object()
_UNKNOWN_KEY_CELL = object()
WRITE_KEY_FACT_STATS_ENV = "NERA_WRITE_KEY_FACT_STATS"


@dataclass(frozen=True, slots=True)
class RawRowOptimizerFacts:
    """Schema-dependent FK and write-key facts for one raw row payload."""

    foreign_key_checks: frozenset[ForeignKeyCheckFact]
    write_key_facts: frozenset[WriteKeyFact]


class _RawKeyTupleMemo:
    """Memoize key tuple extraction while computing raw row optimizer facts."""

    def __init__(
        self: _RawKeyTupleMemo,
        rows: Sequence[Sequence[object]],
        *,
        planning_catalog: PlanningCatalog | None,
    ) -> None:
        self._rows = rows
        self._planning_catalog = planning_catalog
        self._cache: dict[
            tuple[tuple[int, ...], type[DatabaseObjectRow[Any]] | None],
            tuple[frozenset[KeyTupleValue], bool],
        ] = {}
        self._matrix_cache: dict[type[DatabaseObjectRow[Any]] | None, "_RawKeyMatrix"] = {}

    def key_tuples(
        self: _RawKeyTupleMemo,
        positions: Sequence[int],
        *,
        coordinate_model_cls: type[DatabaseObjectRow[Any]] | None = None,
    ) -> tuple[frozenset[KeyTupleValue], bool]:
        key = (tuple(positions), coordinate_model_cls)
        cached = self._cache.get(key)
        if cached is not None:
            return cached
        matrix = self._matrix_for(coordinate_model_cls)
        result = matrix.key_tuples(positions)
        self._cache[key] = result
        return result

    def _matrix_for(
        self: _RawKeyTupleMemo,
        coordinate_model_cls: type[DatabaseObjectRow[Any]] | None,
    ) -> "_RawKeyMatrix":
        cached = self._matrix_cache.get(coordinate_model_cls)
        if cached is not None:
            return cached
        matrix = _RawKeyMatrix.build(
            self._rows,
            coordinate_model_cls=coordinate_model_cls,
            planning_catalog=self._planning_catalog,
        )
        self._matrix_cache[coordinate_model_cls] = matrix
        return matrix


@dataclass(frozen=True, slots=True)
class _RawKeyMatrix:
    """Per-cell key classification for repeated raw key tuple projections."""

    rows: tuple[tuple[object, ...], ...]

    @classmethod
    def build(
        cls,
        rows: Sequence[Sequence[object]],
        *,
        coordinate_model_cls: type[DatabaseObjectRow[Any]] | None,
        planning_catalog: PlanningCatalog | None,
    ) -> "_RawKeyMatrix":
        matrix_rows: list[tuple[object, ...]] = []
        for row in rows:
            matrix_row: list[object] = []
            for value in row:
                if value is None:
                    matrix_row.append(_NULL_KEY_CELL)
                    continue
                fact = _key_value_fact(
                    value,
                    coordinate_model_cls=coordinate_model_cls,
                    planning_catalog=planning_catalog,
                )
                matrix_row.append(fact if fact is not None else _UNKNOWN_KEY_CELL)
            matrix_rows.append(tuple(matrix_row))
        return cls(tuple(matrix_rows))

    def key_tuples(
        self: _RawKeyMatrix,
        positions: Sequence[int],
    ) -> tuple[frozenset[KeyTupleValue], bool]:
        key_positions = tuple(positions)
        key_tuples: set[KeyTupleValue] = set()
        has_unknown = False
        for row in self.rows:
            if any(position >= len(row) for position in key_positions):
                has_unknown = True
                continue
            key_values: list[KeyValueFact] = []
            skip_row = False
            for position in key_positions:
                cell = row[position]
                if cell is _NULL_KEY_CELL:
                    skip_row = True
                    break
                if cell is _UNKNOWN_KEY_CELL:
                    has_unknown = True
                    skip_row = True
                    break
                if not isinstance(cell, LiteralKeyValue | ServerRefKeyValue):
                    raise TypeError("Raw key matrix cell must be a KeyValueFact or sentinel")
                key_values.append(cell)
            if skip_row:
                continue
            key_tuples.add(KeyTupleValue(tuple(key_values)))
        return frozenset(key_tuples), has_unknown


def _model_type_hints_with_schema_context(
    model_cls: type[DatabaseObjectRow[Any]],
) -> dict[str, object]:
    from impl.common.l3000_schema_builder.schema_builder import _get_type_hints_with_schema_context

    return cast("dict[str, object]", _get_type_hints_with_schema_context(model_cls))


def _unwrap_optional(annotation: object) -> object:
    origin = get_origin(annotation)
    if origin is types.UnionType or origin is Union:
        args = get_args(annotation)
        non_none_args = [arg for arg in args if arg is not type(None)]
        if len(non_none_args) == 1:
            return non_none_args[0]
    return annotation


def _resolve_fk_target_table(
    source_model_cls: type[DatabaseObjectRow[Any]],
    target_model_cls: type[DatabaseObjectRow[Any]],
    target_column: str,
) -> str:
    from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName
    from impl.common.l3000_schema_builder.schema_builder import (
        resolve_versioned_foreign_key_target,
    )

    return str(
        resolve_versioned_foreign_key_target(
            source_model_cls,
            target_model_cls,
            SqlColumnName(target_column),
        ).table_name,
    )


def _field_fk_reference(
    model_cls: type[DatabaseObjectRow[Any]],
    field_name: str,
    field_info: FieldInfo,
    type_hints: dict[str, object],
    planning_catalog: PlanningCatalog | None = None,
) -> ForeignKeyConstraintReference | None:
    from impl.common.l3000_schema_builder.schema_builder import _resolve_references

    metadata = field_info.json_schema_extra if isinstance(field_info.json_schema_extra, dict) else {}
    if not metadata.get("_nera_column", False):
        return None
    if bool(metadata.get("primary_key", False)):
        return None

    annotation = type_hints.get(field_name, field_info.annotation)
    references_model, references_column = _resolve_references(annotation)
    fk_info = metadata.get("foreign_key")
    if isinstance(fk_info, _NoForeignKeySentinel):
        return None

    references_table_name: str | None = None
    if isinstance(fk_info, ForeignKey):
        if not fk_info.enforce_in_database:
            return None
        target_model = fk_info.target_model
        if isinstance(target_model, str):
            if target_model == model_cls.__name__:
                references_model = model_cls
            else:
                resolved_model = get_model_by_class_name(SchemaModelName(target_model))
                if resolved_model is not None:
                    references_model = resolved_model
                else:
                    references_table_name = target_model
        elif isinstance(target_model, type):
            references_model = target_model
        if isinstance(fk_info.target_column, str):
            references_column = fk_info.target_column
    elif isinstance(fk_info, AutoForeignKey) or fk_info is None:
        base_annotation = _unwrap_optional(annotation)
        origin_type = get_origin(base_annotation) or base_annotation
        if (
            isinstance(origin_type, type)
            and issubclass(origin_type, RowId)
            and origin_type is not RowId
            and (isinstance(fk_info, AutoForeignKey) or origin_type.__dict__.get("__auto_fk__", True))
        ):
            try:
                row_id_type = cast("type[RowId[Any]]", origin_type)
                resolved_target = row_id_type.resolve_target_table()
            except ValueError:
                resolved_target = None
            if isinstance(resolved_target, type):
                references_model = resolved_target
                references_column = DynamicFieldName("sys_id")

    target_table: str | None = references_table_name
    if (
        target_table is None
        and isinstance(references_model, type)
        and issubclass(references_model, DatabaseObjectRow)
        and isinstance(references_column, str)
    ):
        target_table = _resolve_fk_target_table(model_cls, references_model, references_column)
    if target_table is None or not isinstance(references_column, str):
        return None
    source_column = _field_to_db_column(model_cls, field_name, planning_catalog)
    target_column = _target_db_column(SqlTableName(target_table), references_column, planning_catalog)
    return ForeignKeyConstraintReference(
        source_field_names=(field_name,),
        source_table=get_table_name(model_cls),
        source_columns=(source_column,),
        target_table=target_table,
        target_columns=(target_column,),
    )


_FK_ANALYSIS: ContextVar[dict[tuple[int, int], tuple[
    type[DatabaseObjectRow[Any]], PlanningCatalog | None, tuple[ForeignKeyConstraintReference, ...],
]] | None] = ContextVar("read_only_fk_analysis", default=None)


@contextmanager
def read_only_fk_analysis_scope() -> Generator[None]:
    """Bound reuse of model constraints to one read-only optimizer pass."""
    token = _FK_ANALYSIS.set({})
    try:
        yield
    finally:
        _FK_ANALYSIS.reset(token)


def model_foreign_key_constraints(
    model_cls: type[DatabaseObjectRow[Any]],
    planning_catalog: PlanningCatalog | None = None,
) -> tuple[ForeignKeyConstraintReference, ...]:
    """Return DB-enforced FK constraints declared by a model."""
    cache = _FK_ANALYSIS.get()
    key = (id(model_cls), id(planning_catalog))
    if cache is not None:
        cached = cache.get(key)
        if cached is not None and cached[0] is model_cls and cached[1] is planning_catalog:
            return cached[2]
    result = _build_model_foreign_key_constraints(model_cls, planning_catalog)
    if cache is not None:
        cache[key] = (model_cls, planning_catalog, result)
    return result


def _build_model_foreign_key_constraints(
    model_cls: type[DatabaseObjectRow[Any]],
    planning_catalog: PlanningCatalog | None,
) -> tuple[ForeignKeyConstraintReference, ...]:
    references: list[ForeignKeyConstraintReference] = []
    type_hints = _model_type_hints_with_schema_context(model_cls)

    if has_table_config(model_cls):
        table_config = get_table_config(model_cls)
        foreign_keys = getattr(table_config, "foreign_keys", None)
        if foreign_keys is not None:
            source_table = get_table_name(model_cls)
            for constraint in foreign_keys:
                source_coordinates = tuple(
                    _source_field_and_db_column(model_cls, str(column), planning_catalog) for column in constraint.columns
                )
                references.append(
                    ForeignKeyConstraintReference(
                        source_field_names=tuple(field_name for field_name, _ in source_coordinates),
                        source_table=source_table,
                        source_columns=tuple(db_column for _, db_column in source_coordinates),
                        target_table=constraint.target_table,
                        target_columns=tuple(
                            _target_db_column(
                                constraint.target_table,
                                str(target_column),
                                planning_catalog,
                            )
                            for target_column in constraint.target_columns
                        ),
                    ),
                )

    for field_name, field_info in getattr(model_cls, "model_fields", {}).items():
        reference = _field_fk_reference(
            model_cls,
            field_name,
            field_info,
            type_hints,
            planning_catalog,
        )
        if reference is not None:
            references.append(reference)

    return tuple(references)


def insert_fk_read_tables(
    model_cls: type[DatabaseObjectRow[Any]],
    planning_catalog: PlanningCatalog | None = None,
) -> frozenset[str]:
    """Return physical tables an insert reads via DB-enforced FK checks."""
    return frozenset(reference.target_table for reference in model_foreign_key_constraints(model_cls, planning_catalog))


def _write_metadata_plan(
    model_cls: type[DatabaseObjectRow[Any]],
    planning_catalog: PlanningCatalog | None,
) -> WriteMetadataPlan | None:
    if planning_catalog is None:
        return None
    return planning_catalog.write_metadata.get(model_cls)


def _model_for_table_name(
    table_name: SqlTableName,
    planning_catalog: PlanningCatalog | None,
) -> type[DatabaseObjectRow[Any]] | None:
    if planning_catalog is None:
        return None
    table_shape = planning_catalog.tables_by_name.get(table_name)
    if table_shape is None or not issubclass(table_shape.model_cls, DatabaseObjectRow):
        return None
    return table_shape.model_cls


def _field_to_db_column(
    model_cls: type[DatabaseObjectRow[Any]],
    field_name: str,
    planning_catalog: PlanningCatalog | None,
) -> str:
    if field_name == "sys_id":
        return "sys_id"
    write_plan = _write_metadata_plan(model_cls, planning_catalog)
    if write_plan is not None:
        db_column = write_plan.field_to_db_column.get(field_name)
        if db_column is not None:
            return db_column
    return str(get_db_column_name(model_cls, DynamicFieldName(field_name)))


def _db_column_to_field(
    model_cls: type[DatabaseObjectRow[Any]],
    db_column: str,
    planning_catalog: PlanningCatalog | None,
) -> str | None:
    if db_column == "sys_id":
        return "sys_id"
    write_plan = _write_metadata_plan(model_cls, planning_catalog)
    if write_plan is not None:
        field_name = write_plan.db_column_to_field.get(db_column)
        if field_name is not None:
            return field_name
    for field_name in getattr(model_cls, "model_fields", {}):
        if get_db_column_name(model_cls, DynamicFieldName(str(field_name))) == db_column:
            return str(field_name)
    return None


def _source_field_and_db_column(
    model_cls: type[DatabaseObjectRow[Any]],
    source_name: str,
    planning_catalog: PlanningCatalog | None,
) -> tuple[str, str]:
    write_plan = _write_metadata_plan(model_cls, planning_catalog)
    if write_plan is not None:
        db_column = write_plan.field_to_db_column.get(source_name)
        if db_column is not None:
            return source_name, db_column
        field_name = write_plan.db_column_to_field.get(source_name)
        if field_name is not None:
            return field_name, source_name
    try:
        return source_name, get_db_column_name(model_cls, DynamicFieldName(source_name))
    except KeyError:
        field_name = _db_column_to_field(model_cls, source_name, planning_catalog)
        return (field_name if field_name is not None else source_name), source_name


def _target_db_column(
    target_table: SqlTableName,
    target_column: str,
    planning_catalog: PlanningCatalog | None,
) -> str:
    target_model_cls = _model_for_table_name(target_table, planning_catalog)
    if target_model_cls is None:
        return target_column
    write_plan = _write_metadata_plan(target_model_cls, planning_catalog)
    if write_plan is not None:
        db_column = write_plan.field_to_db_column.get(target_column)
        if db_column is not None:
            return db_column
        if target_column in write_plan.db_column_to_field:
            return target_column
    try:
        return str(get_db_column_name(target_model_cls, DynamicFieldName(target_column)))
    except KeyError:
        return target_column


def _unwrap_key_value(value: object) -> object:
    if isinstance(value, SysId):
        return value.unwrap_to_storage_key()
    unwrap_to_uuid = getattr(value, "unwrap_to_uuid", None)
    if callable(unwrap_to_uuid):
        return unwrap_to_uuid()
    unwrap_to_str = getattr(value, "unwrap_to_str", None)
    if callable(unwrap_to_str):
        return unwrap_to_str()
    unwrap_to_sql = getattr(value, "unwrap_to_sql", None)
    if callable(unwrap_to_sql):
        return unwrap_to_sql()
    unwrap_to_int = getattr(value, "unwrap_to_int", None)
    if callable(unwrap_to_int):
        return unwrap_to_int()
    return value


def _split_ref_id(ref_id: ServerPlanRefId) -> tuple[ServerPlanRefId, str | None]:
    base_ref, separator, field_path = ref_id.partition(".")
    if not separator:
        return ServerPlanRefId(base_ref), None
    return ServerPlanRefId(base_ref), field_path.split(".", 1)[0]


def _normalize_server_ref_field_name(
    field_name: str | None,
    coordinate_model_cls: type[DatabaseObjectRow[Any]] | None,
    planning_catalog: PlanningCatalog | None,
) -> str | None | object:
    if field_name is None:
        return None
    if coordinate_model_cls is None:
        return field_name
    write_plan = _write_metadata_plan(coordinate_model_cls, planning_catalog)
    if write_plan is not None:
        db_column = write_plan.field_to_db_column.get(field_name)
        if db_column is not None:
            return db_column
        if field_name in write_plan.db_column_to_field:
            return field_name
        return _UNKNOWN_SERVER_REF_FIELD
    try:
        return str(get_db_column_name(coordinate_model_cls, DynamicFieldName(field_name)))
    except KeyError:
        if _db_column_to_field(coordinate_model_cls, field_name, planning_catalog) is not None:
            return field_name
        return _UNKNOWN_SERVER_REF_FIELD


def _key_value_fact(
    value: object,
    *,
    coordinate_model_cls: type[DatabaseObjectRow[Any]] | None = None,
    planning_catalog: PlanningCatalog | None = None,
) -> KeyValueFact | None:
    from l2070_batching.server_ref import (
        ServerRef,
        inspect_server_value_shape_for_planning,
    )

    fact: KeyValueFact | None = None
    if value is not None and isinstance(value, ServerRef):
        shape = inspect_server_value_shape_for_planning(value, site="_insert_fk_reads._key_value_fact")
        if shape.symbolic_ref_id is not None:
            base_ref, field_name = _split_ref_id(ServerPlanRefId(shape.symbolic_ref_id))
            normalized_field_name = _normalize_server_ref_field_name(
                field_name,
                coordinate_model_cls,
                planning_catalog,
            )
            if normalized_field_name is not _UNKNOWN_SERVER_REF_FIELD:
                if normalized_field_name is not None and not isinstance(
                    normalized_field_name,
                    str,
                ):
                    raise TypeError("Normalized ServerRef field name must be str or None")
                field_name_for_fact: str | None = normalized_field_name
                fact = ServerRefKeyValue(base_ref, field_name_for_fact)
    elif value is not None:
        unwrapped_value = _unwrap_key_value(value)
        if isinstance(unwrapped_value, Hashable):
            fact = LiteralKeyValue(unwrapped_value)
    return fact


def _key_tuple_from_values(
    values: Sequence[object],
    *,
    coordinate_model_cls: type[DatabaseObjectRow[Any]] | None = None,
    planning_catalog: PlanningCatalog | None = None,
) -> KeyTupleValue | None:
    key_values: list[KeyValueFact] = []
    for value in values:
        fact = _key_value_fact(
            value,
            coordinate_model_cls=coordinate_model_cls,
            planning_catalog=planning_catalog,
        )
        if fact is None:
            return None
        key_values.append(fact)
    return KeyTupleValue(tuple(key_values))


def _instance_key_tuples(
    instances: Sequence[object],
    field_names: Sequence[str],
    *,
    coordinate_model_cls: type[DatabaseObjectRow[Any]] | None = None,
    planning_catalog: PlanningCatalog | None = None,
) -> tuple[frozenset[KeyTupleValue], bool]:
    key_tuples: set[KeyTupleValue] = set()
    has_unknown = False
    for instance in instances:
        if not isinstance(instance, DatabaseObjectRow):
            has_unknown = True
            continue
        instance_values = getattr(instance, "__dict__", {})
        values = tuple(instance_values.get(field_name, getattr(instance, field_name, _MISSING_FIELD)) for field_name in field_names)
        if any(value is _MISSING_FIELD for value in values):
            has_unknown = True
            continue
        if any(value is None for value in values):
            continue
        key_tuple = _key_tuple_from_values(
            values,
            coordinate_model_cls=coordinate_model_cls,
            planning_catalog=planning_catalog,
        )
        if key_tuple is None:
            has_unknown = True
            continue
        key_tuples.add(key_tuple)
    return frozenset(key_tuples), has_unknown


def foreign_key_checks_for_instances(
    model_cls: type[DatabaseObjectRow[Any]],
    instances: Sequence[object],
    planning_catalog: PlanningCatalog | None = None,
) -> frozenset[ForeignKeyCheckFact]:
    """Return FK checks performed for concrete model instance writes."""
    checks: set[ForeignKeyCheckFact] = set()
    for reference in model_foreign_key_constraints(model_cls, planning_catalog):
        target_model_cls = _model_for_table_name(SqlTableName(reference.target_table), planning_catalog)
        key_values, has_unknown = _instance_key_tuples(
            instances,
            reference.source_field_names,
            coordinate_model_cls=target_model_cls,
            planning_catalog=planning_catalog,
        )
        if not key_values and not has_unknown:
            continue
        checks.add(
            ForeignKeyCheckFact(
                source_table=reference.source_table,
                source_columns=reference.source_columns,
                target_table=reference.target_table,
                target_columns=reference.target_columns,
                key_values=key_values,
                has_unknown_key_values=has_unknown,
            ),
        )
    return frozenset(checks)


def foreign_key_checks_for_instance(
    model_cls: type[DatabaseObjectRow[Any]],
    instance: object,
    planning_catalog: PlanningCatalog | None = None,
) -> frozenset[ForeignKeyCheckFact]:
    """Return FK checks performed for one concrete model instance write."""
    return foreign_key_checks_for_instances(model_cls, [instance], planning_catalog)


def _raw_column_positions(
    columns: Sequence[str],
    *,
    db_column_source: type[DatabaseObjectRow[Any]],
    planning_catalog: PlanningCatalog | None = None,
) -> dict[str, int]:
    positions: dict[str, int] = {}
    for index, column in enumerate(columns):
        positions[column] = index
        _, db_column = _source_field_and_db_column(db_column_source, column, planning_catalog)
        positions[db_column] = index
    return positions


def _model_field_for_db_column(
    model_cls: type[DatabaseObjectRow[Any]],
    db_column: str,
    planning_catalog: PlanningCatalog | None = None,
) -> str | None:
    return _db_column_to_field(model_cls, db_column, planning_catalog)


def _model_fact_field_names(
    model_cls: type[DatabaseObjectRow[Any]],
    instances: Sequence[object],
    planning_catalog: PlanningCatalog | None = None,
) -> tuple[str, ...]:
    write_plan = _write_metadata_plan(model_cls, planning_catalog)
    if write_plan is not None:
        field_names = [field_plan.field_name for field_plan in write_plan.field_plans]
    else:
        field_names = [str(field_name) for field_name in getattr(model_cls, "model_fields", {})]
    if "sys_id" not in field_names and any(hasattr(instance, "sys_id") for instance in instances):
        field_names.insert(0, "sys_id")
    known_field_names: list[str] = []
    for field_name in field_names:
        values: list[object] = []
        for instance in instances:
            if not isinstance(instance, DatabaseObjectRow):
                break
            value = getattr(instance, field_name, None)
            if (
                value is None
                or _key_value_fact(
                    value,
                    coordinate_model_cls=model_cls,
                    planning_catalog=planning_catalog,
                )
                is None
            ):
                break
            values.append(value)
        else:
            if values:
                known_field_names.append(field_name)
    return tuple(known_field_names)


def _raw_key_tuples(
    rows: Sequence[Sequence[object]],
    positions: Sequence[int],
    *,
    coordinate_model_cls: type[DatabaseObjectRow[Any]] | None = None,
    planning_catalog: PlanningCatalog | None = None,
) -> tuple[frozenset[KeyTupleValue], bool]:
    key_tuples: set[KeyTupleValue] = set()
    has_unknown = False
    for row in rows:
        if any(position >= len(row) for position in positions):
            has_unknown = True
            continue
        values = tuple(row[position] for position in positions)
        if any(value is None for value in values):
            continue
        key_tuple = _key_tuple_from_values(
            values,
            coordinate_model_cls=coordinate_model_cls,
            planning_catalog=planning_catalog,
        )
        if key_tuple is None:
            has_unknown = True
            continue
        key_tuples.add(key_tuple)
    return frozenset(key_tuples), has_unknown


def _foreign_key_checks_for_raw_rows(
    model_cls: type[DatabaseObjectRow[Any]],
    *,
    positions: dict[str, int],
    references: Sequence[ForeignKeyConstraintReference],
    memo: _RawKeyTupleMemo,
    planning_catalog: PlanningCatalog | None = None,
) -> frozenset[ForeignKeyCheckFact]:
    checks: set[ForeignKeyCheckFact] = set()
    for reference in references:
        source_positions: list[int] = []
        missing_position = False
        for field_name, source_column in zip(
            reference.source_field_names,
            reference.source_columns,
            strict=True,
        ):
            position = positions.get(field_name)
            if position is None:
                position = positions.get(source_column)
            if position is None:
                missing_position = True
                break
            source_positions.append(position)
        if missing_position:
            checks.add(
                ForeignKeyCheckFact(
                    source_table=reference.source_table,
                    source_columns=reference.source_columns,
                    target_table=reference.target_table,
                    target_columns=reference.target_columns,
                    key_values=frozenset(),
                    has_unknown_key_values=True,
                ),
            )
            continue
        target_model_cls = _model_for_table_name(SqlTableName(reference.target_table), planning_catalog)
        key_values, has_unknown = memo.key_tuples(
            source_positions,
            coordinate_model_cls=target_model_cls,
        )
        if not key_values and not has_unknown:
            continue
        checks.add(
            ForeignKeyCheckFact(
                source_table=reference.source_table,
                source_columns=reference.source_columns,
                target_table=reference.target_table,
                target_columns=reference.target_columns,
                key_values=key_values,
                has_unknown_key_values=has_unknown,
            ),
        )
    return frozenset(checks)


def foreign_key_checks_for_raw_rows(
    model_cls: type[DatabaseObjectRow[Any]],
    columns: Sequence[str],
    rows: Sequence[Sequence[object]],
    *,
    db_column_source: type[DatabaseObjectRow[Any]] | None = None,
    planning_catalog: PlanningCatalog | None = None,
) -> frozenset[ForeignKeyCheckFact]:
    """Return FK checks performed for raw column/row writes."""
    column_source = db_column_source or model_cls
    positions = _raw_column_positions(
        columns,
        db_column_source=column_source,
        planning_catalog=planning_catalog,
    )
    references = model_foreign_key_constraints(model_cls, planning_catalog)
    return _foreign_key_checks_for_raw_rows(
        model_cls,
        positions=positions,
        references=references,
        memo=_RawKeyTupleMemo(rows, planning_catalog=planning_catalog),
        planning_catalog=planning_catalog,
    )


def write_key_facts_for_instances(
    ref_id: ServerPlanRefId,
    model_cls: type[DatabaseObjectRow[Any]],
    instances: Sequence[object],
    planning_catalog: PlanningCatalog | None = None,
) -> frozenset[WriteKeyFact]:
    """Return known key values written by concrete model instance writes."""
    facts: set[WriteKeyFact] = set()
    table_name = get_table_name(model_cls)
    all_field_names = _model_fact_field_names(model_cls, instances, planning_catalog)
    all_columns = tuple(_field_to_db_column(model_cls, field_name, planning_catalog) for field_name in all_field_names)
    if all_field_names:
        all_key_values, all_has_unknown = _instance_key_tuples(
            instances,
            all_field_names,
            coordinate_model_cls=model_cls,
            planning_catalog=planning_catalog,
        )
        if all_key_values or all_has_unknown:
            facts.add(
                WriteKeyFact(
                    producer_ref=ref_id,
                    table=table_name,
                    columns=all_columns,
                    key_values=all_key_values,
                    has_unknown_key_values=all_has_unknown,
                ),
            )
    for field_name in all_field_names:
        column = _field_to_db_column(model_cls, field_name, planning_catalog)
        key_values, has_unknown = _instance_key_tuples(
            instances,
            (field_name,),
            coordinate_model_cls=model_cls,
            planning_catalog=planning_catalog,
        )
        if not key_values and not has_unknown:
            continue
        facts.add(
            WriteKeyFact(
                producer_ref=ref_id,
                table=table_name,
                columns=(column,),
                key_values=key_values,
                has_unknown_key_values=has_unknown,
            ),
        )
    for reference in model_foreign_key_constraints(model_cls, planning_catalog):
        if reference.target_table != table_name:
            continue
        target_field_names: list[str] = []
        for target_column in reference.target_columns:
            target_field_name = _model_field_for_db_column(model_cls, target_column, planning_catalog)
            if target_field_name is None:
                break
            target_field_names.append(target_field_name)
        else:
            key_values, has_unknown = _instance_key_tuples(
                instances,
                tuple(target_field_names),
                coordinate_model_cls=model_cls,
                planning_catalog=planning_catalog,
            )
            if not key_values and not has_unknown:
                continue
            facts.add(
                WriteKeyFact(
                    producer_ref=ref_id,
                    table=table_name,
                    columns=reference.target_columns,
                    key_values=key_values,
                    has_unknown_key_values=has_unknown,
                ),
            )
    return frozenset(facts)


def write_key_facts_for_instance(
    ref_id: ServerPlanRefId,
    model_cls: type[DatabaseObjectRow[Any]],
    instance: object,
    planning_catalog: PlanningCatalog | None = None,
) -> frozenset[WriteKeyFact]:
    """Return known key values written by one model instance write."""
    return write_key_facts_for_instances(ref_id, model_cls, [instance], planning_catalog)


def _write_key_facts_for_raw_rows(
    ref_id: ServerPlanRefId,
    model_cls: type[DatabaseObjectRow[Any]],
    *,
    positions_by_db_column: dict[str, int],
    all_columns: Sequence[str],
    all_positions: Sequence[int],
    references: Sequence[ForeignKeyConstraintReference],
    memo: _RawKeyTupleMemo,
) -> frozenset[WriteKeyFact]:
    facts: set[WriteKeyFact] = set()
    table_name = get_table_name(model_cls)
    for db_column, position in positions_by_db_column.items():
        key_values, has_unknown = memo.key_tuples(
            (position,),
            coordinate_model_cls=model_cls,
        )
        if not key_values and not has_unknown:
            continue
        facts.add(
            WriteKeyFact(
                producer_ref=ref_id,
                table=table_name,
                columns=(db_column,),
                key_values=key_values,
                has_unknown_key_values=has_unknown,
            ),
        )

    if all_columns:
        all_key_values, all_has_unknown = memo.key_tuples(
            all_positions,
            coordinate_model_cls=model_cls,
        )
        if all_key_values or all_has_unknown:
            facts.add(
                WriteKeyFact(
                    producer_ref=ref_id,
                    table=table_name,
                    columns=tuple(all_columns),
                    key_values=all_key_values,
                    has_unknown_key_values=all_has_unknown,
                ),
            )

    key_columns: set[str] = {"sys_id"}
    for reference in references:
        if reference.target_table == table_name:
            key_columns.update(reference.target_columns)

    for key_column in key_columns:
        key_position = positions_by_db_column.get(key_column)
        if key_position is None:
            continue
        key_values, has_unknown = memo.key_tuples(
            (key_position,),
            coordinate_model_cls=model_cls,
        )
        if not key_values and not has_unknown:
            continue
        facts.add(
            WriteKeyFact(
                producer_ref=ref_id,
                table=table_name,
                columns=(key_column,),
                key_values=key_values,
                has_unknown_key_values=has_unknown,
            ),
        )
    for reference in references:
        if reference.target_table != table_name:
            continue
        target_positions: list[int] = []
        for target_column in reference.target_columns:
            target_position = positions_by_db_column.get(target_column)
            if target_position is None:
                break
            target_positions.append(target_position)
        else:
            key_values, has_unknown = memo.key_tuples(
                target_positions,
                coordinate_model_cls=model_cls,
            )
            if not key_values and not has_unknown:
                continue
            facts.add(
                WriteKeyFact(
                    producer_ref=ref_id,
                    table=table_name,
                    columns=reference.target_columns,
                    key_values=key_values,
                    has_unknown_key_values=has_unknown,
                ),
            )
    return frozenset(facts)


def write_key_fact_shape(fact: WriteKeyFact) -> str:
    if fact.columns == ("sys_id",):
        return "primary_key"
    if len(fact.columns) == 1:
        return "single_column"
    return "multi_column"


def _trace_write_key_fact_production(
    *,
    source: str,
    model_cls: type[DatabaseObjectRow[Any]],
    facts: frozenset[WriteKeyFact],
) -> None:
    if not os.getenv(WRITE_KEY_FACT_STATS_ENV):
        return
    counts: dict[str, int] = {}
    for fact in facts:
        shape = write_key_fact_shape(fact)
        counts[shape] = counts.get(shape, 0) + 1
    counts_part = " ".join(f"{shape}={count}" for shape, count in sorted(counts.items()))
    print(
        f"[WRITE_KEY_FACT_STATS] event=produced source={source} model={model_cls.__name__} total={len(facts)} {counts_part}",
        file=sys.stderr,
    )


def raw_optimizer_facts_for_raw_rows(
    ref_id: ServerPlanRefId,
    model_cls: type[DatabaseObjectRow[Any]],
    columns: Sequence[str],
    rows: Sequence[Sequence[object]],
    *,
    db_column_source: type[DatabaseObjectRow[Any]] | None = None,
    planning_catalog: PlanningCatalog | None = None,
) -> RawRowOptimizerFacts:
    """Return schema-dependent FK and write-key facts for raw row writes."""
    column_source = db_column_source or model_cls
    positions = _raw_column_positions(
        columns,
        db_column_source=column_source,
        planning_catalog=planning_catalog,
    )
    positions_by_db_column: dict[str, int] = {}
    all_columns: list[str] = []
    all_positions: list[int] = []
    for position, column in enumerate(columns):
        _, db_column = _source_field_and_db_column(column_source, column, planning_catalog)
        positions_by_db_column[db_column] = position
        all_columns.append(db_column)
        all_positions.append(position)
    references = model_foreign_key_constraints(model_cls, planning_catalog)
    memo = _RawKeyTupleMemo(rows, planning_catalog=planning_catalog)
    write_key_facts = _write_key_facts_for_raw_rows(
        ref_id,
        model_cls,
        positions_by_db_column=positions_by_db_column,
        all_columns=all_columns,
        all_positions=all_positions,
        references=references,
        memo=memo,
    )
    _trace_write_key_fact_production(
        source="raw_rows",
        model_cls=model_cls,
        facts=write_key_facts,
    )
    return RawRowOptimizerFacts(
        foreign_key_checks=_foreign_key_checks_for_raw_rows(
            model_cls,
            positions=positions,
            references=references,
            memo=memo,
            planning_catalog=planning_catalog,
        ),
        write_key_facts=write_key_facts,
    )


def write_key_facts_for_raw_rows(
    ref_id: ServerPlanRefId,
    model_cls: type[DatabaseObjectRow[Any]],
    columns: Sequence[str],
    rows: Sequence[Sequence[object]],
    *,
    db_column_source: type[DatabaseObjectRow[Any]] | None = None,
    planning_catalog: PlanningCatalog | None = None,
) -> frozenset[WriteKeyFact]:
    """Return known key values written by raw column/row writes."""
    return raw_optimizer_facts_for_raw_rows(
        ref_id,
        model_cls,
        columns,
        rows,
        db_column_source=db_column_source,
        planning_catalog=planning_catalog,
    ).write_key_facts

