def _clone_compilation_context(ctx: CompilationContext) -> CompilationContext:
    return replace(
        ctx,
        cte_refs=dict(ctx.cte_refs),
        write_cte_by_table={key: list(value) for key, value in ctx.write_cte_by_table.items()},
        overlay_cte_by_table=dict(ctx.overlay_cte_by_table),
        staged_source_cte_by_table=dict(ctx.staged_source_cte_by_table),
        pending_staged_source_ctes_by_table={key: list(value) for key, value in ctx.pending_staged_source_ctes_by_table.items()},
        _overlay_counter=list(ctx._overlay_counter),
    )


def _materialize_local_cte_definitions(
    definitions: Sequence[SqlCteDefinition],
    final_query: SqlRenderable,
    *,
    table_prefix: str,
) -> tuple[list[SqlRenderable], list[SqlTableName], SqlRenderable]:
    """Replace one local CTE chain with bounded temporary-table statements."""
    statements: list[SqlRenderable] = []
    temporary_tables: list[SqlTableName] = []
    materialized_aliases: list[SqlCteDefinition] = []
    deferred_definitions: list[SqlCteDefinition] = []
    for index, definition in enumerate(definitions):
        if definition.name == "active_edges":
            deferred_definitions.append(definition)
            continue
        dependency_table = SqlTableName(f"{table_prefix}_{index}")
        dependency_query = definition.query
        local_definitions = [*materialized_aliases, *deferred_definitions]
        if definition.recursive:
            local_definitions.append(definition)
            dependency_query = SqlSelect(
                SqlStar(),
                from_=SqlTableIdent(SqlTableName(definition.name)),
            )
        if local_definitions:
            dependency_query = SqlCte(
                tuple(local_definitions),
                dependency_query,
                recursive=definition.recursive,
            )
        statements.append(
            SqlCreateTemporaryTableAsSelect(
                dependency_table,
                dependency_query,
                transaction_owned=True,
            ),
        )
        temporary_tables.append(dependency_table)
        materialized_aliases.append(
            SqlCteDefinition(
                definition.name,
                SqlSelect(SqlStar(), from_=SqlTableIdent(dependency_table)),
                columns=definition.columns,
            ),
        )
    final_definitions = (*materialized_aliases, *deferred_definitions)
    resolved_final = SqlCte(final_definitions, final_query, recursive=False) if final_definitions else final_query
    return statements, temporary_tables, resolved_final


def _assertion_steps(
    intent: ExecutePersonalizedRandomWalkIntent[Any],
    program: GraphWalkRelationProgram,
    *,
    materialize_relations: bool,
) -> tuple[list[ServerPlanStep[Any]], tuple[ServerPlanRefId, ...]]:
    steps: list[ServerPlanStep[Any]] = []
    refs: list[ServerPlanRefId] = []
    for index, assertion in enumerate(program.required_assertions):
        assertion_ref = ServerPlanRefId(intent.ref_id + f"_assert_{index}")
        refs.append(assertion_ref)
        assertion_type = _MaterializedGraphWalkAssertionStep if materialize_relations else QueryAssertNoRowsStep
        steps.append(
            assertion_type(
                assertion_ref,
                assertion.query_spec.model_cls,
                query_spec=replace(assertion.query_spec, permission_state=QueryPermissionState.BYPASS),
                error_cls=ValueError,
                error_message=assertion.error_message,
            ),
        )
    return steps, tuple(refs)


class _MaterializedGraphWalkAssertionStep(QueryAssertNoRowsStep):
    """Evaluate a MariaDB graph-walk guard through bounded temporary relations."""

    def native_assertion_expansion(
        self: _MaterializedGraphWalkAssertionStep,
        optimization_ctx: object,
    ) -> tuple[ServerPlanStep[Any], ...] | None:
        del optimization_ctx
        return None

    def scheduling_effects(self: _MaterializedGraphWalkAssertionStep) -> frozenset[SchedulingEffect]:
        return frozenset({SchedulingEffect.REQUIRES_EXECUTOR_TEMPORARY_RELATION})

    def compile(self: _MaterializedGraphWalkAssertionStep, ctx: CompilationContext) -> CompiledStep[Any]:
        compiled = super().compile(ctx)
        grammar = _materialized_grammar(compiled)
        if not isinstance(grammar, SqlOuterCteSplitProtocol):
            return compiled
        definitions, final_query = grammar.split_for_outer_cte()
        if not definitions:
            return compiled

        digest = sha256(str(self.ref_id).encode()).hexdigest()[:12]
        statements, temporary_tables, final_query = _materialize_local_cte_definitions(
            tuple(tree_cte_definition(definition) for definition in definitions),
            final_query,
            table_prefix=f"tmp_gwa_{digest}",
        )
        assertion_index = len(statements)
        statements.append(final_query)
        statements.extend(SqlDropTemporaryTableIfExists(table) for table in reversed(temporary_tables))
        batch = SqlStatementBatch(
            [SqlDeclaredCteInputs(statement, frozenset()) for statement in statements],
            category=SqlStatementBatchCategory.DEPENDENCY_GRAPH,
            relationships=tuple(
                SqlStatementRelationship(
                    predecessor=index,
                    successor=index + 1,
                    kind=SqlStatementRelationshipKind.DATA_VISIBILITY,
                )
                for index in range(len(statements) - 1)
            ),
            needs_returning_per_stmt=[index == assertion_index for index in range(len(statements))],
            collect_results_per_stmt=[index == assertion_index for index in range(len(statements))],
            statement_kinds_per_stmt=[
                SqlStatementKind.ASSERTION if index == assertion_index else SqlStatementKind.DDL for index in range(len(statements))
            ],
        )
        for statement in batch.statements:
            fragment = statement.render(ctx.sql_render_dialect())
            sql, params = fragment.to_sql(ctx.sql_render_dialect())
            enforce_statement_capacity(
                rendered_sql_bytes=len(sql.encode("utf-8")),
                parameter_count=len(params),
                capacity=ctx.sql_statement_capacity,
            )
        return replace(
            compiled,
            grammar=batch,
            ir=None,
            params=None,
            auxiliary_ctes=None,
            needs_recursive_with=False,
        )


def _permission_refs(
    intent: ExecutePersonalizedRandomWalkIntent[Any],
    *extra: ServerPlanRefId,
) -> frozenset[ServerPlanRefId]:
    inputs = intent.inputs
    return frozenset(
        {
            inputs.node_relation_ref,
            inputs.edge_relation_ref,
            inputs.graph_guard_ref,
            inputs.snapshot_ref,
            inputs.permission_provenance_ref,
            *inputs.transition_relation_refs,
            *extra,
        },
    )


def _single_statement_program(intent: ExecutePersonalizedRandomWalkIntent[Any]) -> GraphWalkRelationProgram:
    request = intent.request
    seeds = request.seeds if isinstance(request, PersonalizedRandomWalkRequest) else ()
    policy = request.policy
    if isinstance(policy, FixedIterationPolicy):
        return build_guarded_fixed_iteration_program(
            fragment=intent.fragment,
            seeds=seeds,
            selectors=request.edge_selectors,
            restart_probability=request.restart_probability,
            iterations=policy.iterations,
            dangling_policy=request.dangling_policy,
            self_loop_policy=request.self_loop_policy,
            parallel_edge_policy=request.parallel_edge_policy,
        )
    return build_guarded_convergence_iteration_program(
        fragment=intent.fragment,
        seeds=seeds,
        selectors=request.edge_selectors,
        restart_probability=request.restart_probability,
        policy=policy,
        dangling_policy=request.dangling_policy,
        self_loop_policy=request.self_loop_policy,
        parallel_edge_policy=request.parallel_edge_policy,
    )


def _ordered_iteration_program(
    intent: ExecutePersonalizedRandomWalkIntent[Any],
    *,
    iteration: int,
    previous_rank_ref: ServerPlanRefId | None,
    final_iteration: bool,
) -> GraphWalkRelationProgram:
    request = intent.request
    seeds = request.seeds if isinstance(request, PersonalizedRandomWalkRequest) else ()
    policy = request.policy
    if isinstance(policy, FixedIterationPolicy):
        return build_guarded_ordered_fixed_iteration_program(
            fragment=intent.fragment,
            previous_rank_ref=previous_rank_ref,
            seeds=seeds,
            selectors=request.edge_selectors,
            restart_probability=request.restart_probability,
            iteration=iteration,
            dangling_policy=request.dangling_policy,
            self_loop_policy=request.self_loop_policy,
            parallel_edge_policy=request.parallel_edge_policy,
        )
    return build_guarded_ordered_convergence_iteration_program(
        fragment=intent.fragment,
        previous_rank_ref=previous_rank_ref,
        seeds=seeds,
        selectors=request.edge_selectors,
        restart_probability=request.restart_probability,
        policy=policy,
        iteration=iteration,
        final_iteration=final_iteration,
        dangling_policy=request.dangling_policy,
        self_loop_policy=request.self_loop_policy,
        parallel_edge_policy=request.parallel_edge_policy,
    )


def _statement_local_relation_names(
    query: QuerySpec[Any] | QuerySetSpec,
) -> frozenset[str]:
    if isinstance(query, QuerySetSpec):
        return frozenset(
            relation_name for branch in query.branches for relation_name in _statement_local_relation_names(branch.query_spec)
        )
    names: set[str] = set()
    for definition in query.ctes:
        names.add(definition.name)
        nested = definition.query
        if isinstance(nested, QuerySpec | QuerySetSpec):
            names.update(_statement_local_relation_names(nested))
    return frozenset(names)


def _without_common_relations(query: QuerySpec[Any]) -> QuerySpec[Any]:
    return replace(
        query,
        ctes=tuple(definition for definition in query.ctes if definition.name not in _COMMON_RELATION_NAMES),
    )


def _without_common_program(program: GraphWalkRelationProgram) -> GraphWalkRelationProgram:
    iterations = tuple(
        replace(
            relations,
            contribution_query=_without_common_relations(relations.contribution_query),
            incoming_query=_without_common_relations(relations.incoming_query),
            dangling_query=_without_common_relations(relations.dangling_query),
            rank_query=_without_common_relations(relations.rank_query),
            delta_query=_without_common_relations(relations.delta_query),
        )
        for relations in program.iterations
    )
    selected = program.selected_rank_query
    return replace(
        program,
        iterations=iterations,
        selected_rank_query=None if selected is None else _without_common_relations(selected),
    )


def _compiled_query(
    *,
    ref_id: ServerPlanRefId,
    query: QuerySpec[Any],
    ctx: CompilationContext,
    permission_dependency_refs: frozenset[ServerPlanRefId],
) -> tuple[CompiledStep[Sequence[dict[str, object]]], QueryExecuteStep[dict[str, object]]]:
    step = QueryExecuteStep(
        ref_id,
        query.model_cls,
        _QueryExecuteStepConfig(
            query_spec=replace(query, permission_state=QueryPermissionState.BYPASS),
            raw_mode=True,
            permission_dependency_refs=permission_dependency_refs,
        ),
    )
    return step.compile(ctx), step


def _materialized_grammar(compiled: CompiledStep[Any]) -> SqlRenderable:
    sql_ir = compiled.materialize_ir()
    if sql_ir is None:
        raise TypeError("The graph-walk physical candidate requires SQL IR.")
    grammar = sql_ir.grammar
    if grammar is None:
        raise TypeError("The graph-walk physical candidate requires SQL grammar.")
    return grammar


class _PhysicalGraphWalkStep(
    MaterializedDependentReadRegionStep[Sequence[dict[str, object]]],
):
    """Compile and admit one exact graph-walk physical candidate before execution."""

    def __init__(
        self: _PhysicalGraphWalkStep,
        intent: ExecutePersonalizedRandomWalkIntent[Any],
        *,
        assertion_refs: tuple[ServerPlanRefId, ...],
    ) -> None:
        super().__init__(intent.ref_id)
        self._intent = intent
        self._assertion_refs = assertion_refs

    @property
    def level(self: _PhysicalGraphWalkStep) -> int:
        return 0

    def tables_read(self: _PhysicalGraphWalkStep) -> frozenset[str]:
        return frozenset()

    def tables_written(self: _PhysicalGraphWalkStep) -> frozenset[str]:
        return frozenset()

    def is_read_only(self: _PhysicalGraphWalkStep) -> bool:
        return True

    def dependencies(self: _PhysicalGraphWalkStep) -> frozenset[ServerPlanRefId]:
        return _permission_refs(self._intent, *self._assertion_refs)

    def dependency_contract(self: _PhysicalGraphWalkStep) -> StepDependencyContract:
        """Keep validation batches ordered without importing them as SQL relations."""
        graph_contract = self._intent.dependency_contract()
        return replace(
            graph_contract,
            consumed_refs=graph_contract.consumed_refs
            | frozenset(
                ConsumedRef(ref, DependencySource.CONSTRUCTOR_DEPENDS_ON, frozenset({DependencyUse.ORDERING}))
                for ref in self._assertion_refs
            ),
            transport=TransportDependencyPolicy.NOT_TRANSPORTABLE,
        )

    def ordered_statement_sql_visible_dependencies(self: _PhysicalGraphWalkStep) -> frozenset[str]:
        """The closed walk batch owns its inputs and their SQL definitions."""
        return frozenset()

    def result_cardinality(self: _PhysicalGraphWalkStep) -> Cardinality:
        return Cardinality.ONE

    def publishes_decoded_value_as_executor_value(self: _PhysicalGraphWalkStep) -> bool:
        return True

    def runtime_result_is_terminal_scalar(self: _PhysicalGraphWalkStep) -> bool:
        return True

    def cte_publication_contract(self: _PhysicalGraphWalkStep) -> CtePublicationContract:
        return CtePublicationContract.non_publishing()

    def step_tags(self: _PhysicalGraphWalkStep) -> frozenset[str]:
        return frozenset({"read", "query", "execute", "graph", "algorithm", "personalized-random-walk"})

    def scheduling_effects(self: _PhysicalGraphWalkStep) -> frozenset[SchedulingEffect]:
        """Reserve transaction-local state for an admitted relational candidate."""
        return frozenset({SchedulingEffect.REQUIRES_EXECUTOR_TEMPORARY_RELATION})

    def _score_step(
        self: _PhysicalGraphWalkStep,
        program: GraphWalkRelationProgram,
    ) -> ServerPlanStep[Sequence[dict[str, object]]]:
        from impl.common.l2070_server_plan.steps.graph_walk_score import GraphWalkScoreStep

        intent = self._intent
        return GraphWalkScoreStep(
            intent.ref_id,
            node_model=intent.node_model,
            node_relation_ref=intent.inputs.node_relation_ref,
            program=program,
            result_limit=intent.result_limit,
            permission_dependency_refs=_permission_refs(intent),
            origin=intent.origin,
        )

    @staticmethod
    def _fits_statement(compiled: CompiledStep[Any], ctx: CompilationContext) -> bool:
        grammar = _materialized_grammar(compiled)
        sql, params = grammar.render(ctx.sql_render_dialect()).to_sql(ctx.sql_render_dialect())
        try:
            enforce_statement_capacity(
                rendered_sql_bytes=len(sql.encode("utf-8")),
                parameter_count=len(params),
                capacity=ctx.sql_statement_capacity,
            )
        except StatementCapacityExceededError:
            return False
        return True

    def compile_dependent_read_cte_relation(
        self: _PhysicalGraphWalkStep,
        ctx: CompilationContext,
    ) -> CompiledStep[Sequence[dict[str, object]]]:
        """Compile the statement-local candidate for enclosing physical-region admission."""
        statement_ctx = _clone_compilation_context(ctx)
        return self._score_step(_single_statement_program(self._intent)).compile(statement_ctx)

    def compile(
        self: _PhysicalGraphWalkStep,
        ctx: CompilationContext,
    ) -> CompiledStep[Sequence[dict[str, object]]]:
        policy = self._intent.request.policy
        single_iteration = isinstance(policy, FixedIterationPolicy) and policy.iterations == 1
        if ctx.backend_profile.traits.graph_walk_statement_transport is GraphWalkStatementTransport.BOUNDED_UNROLLED or (
            single_iteration and ctx.backend_profile.traits.supports_single_iteration_walk_statement
        ):
            statement_ctx = _clone_compilation_context(ctx)
            statement_candidate = self._score_step(_single_statement_program(self._intent)).compile(statement_ctx)
            if self._fits_statement(statement_candidate, ctx):
                return statement_candidate
        relational_candidate = self._compile_transaction_relation_candidate(ctx)
        if not isinstance(relational_candidate, CompiledStep):
            msg = "A closed graph-walk candidate must compile to one CompiledStep."
            raise TypeError(msg)
        return relational_candidate

    def _compile_transaction_relation_candidate(
        self: _PhysicalGraphWalkStep,
        ctx: CompilationContext,
        *,
        closure: _GraphWalkRegionClosure = _GraphWalkRegionClosure.CLOSED,
    ) -> CompiledStep[Sequence[dict[str, object]]] | MaterializedDependentReadRegion[Sequence[dict[str, object]]]:
        local_ctx = _clone_compilation_context(ctx)
        intent = self._intent
        policy = intent.request.policy
        count = policy.iterations if isinstance(policy, FixedIterationPolicy) else policy.max_iterations
        first_program = _ordered_iteration_program(
            intent,
            iteration=1,
            previous_rank_ref=None,
            final_iteration=count == 1,
        )
        definitions = {SqlCteName(definition.name): definition for definition in first_program.final_rank_query.ctes}
        missing = tuple(name for name in _COMMON_RELATION_NAMES if name not in definitions)
        if missing:
            raise ValueError(f"The graph-walk relation program is missing required relations: {missing!r}.")

        digest = sha256(str(intent.ref_id).encode()).hexdigest()[:12]
        statements: list[SqlRenderable] = []
        manifests: list[tuple[PermissionProvenanceManifestEntry, ...]] = []
        temporary_tables: list[SqlTableName] = []

        def add_index(
            table: SqlTableName,
            *,
            suffix: SqlTableName,
            columns: tuple[SqlColumnName, ...],
            unique: bool = False,
        ) -> None:
            statements.append(
                _SqlOperationLocalCreateIndex(
                    SqlIndexIdent(SqlIndexName(f"tmp_gw_{digest}_{suffix}_idx")),
                    SqlTableIdent(table),
                    tuple(SqlColumnIdent(column) for column in columns),
                    unique=unique,
                ),
            )

        def materialize_relation(
            semantic_name: SqlCteName,
            definition: QueryCteDefinition,
            *,
            suffix: SqlTableName,
            query: QuerySpec[Any] | None = None,
        ) -> None:
            physical_name = SqlTableName(f"tmp_gw_{digest}_{suffix}")
            relation_query = definition.query if query is None else query
            if not isinstance(relation_query, QuerySpec):
                raise ValueError(f"Graph-walk relation {semantic_name!r} must use a QuerySpec. It uses {type(relation_query).__name__}.")
            compiled, producer = _compiled_query(
                ref_id=ServerPlanRefId(f"{intent.ref_id}.{semantic_name}"),
                query=relation_query,
                ctx=local_ctx,
                permission_dependency_refs=_permission_refs(intent),
            )
            statements.append(
                SqlCreateTemporaryTableAsSelect(
                    physical_name,
                    _materialized_grammar(compiled),
                    transaction_owned=True,
                ),
            )
            manifests.append(compiled.provenance_manifest)
            temporary_tables.append(physical_name)
            contract = producer.cte_publication_contract()
            published_binding = CteReference(
                ServerPlanRefId(physical_name),
                source_tables=contract.source_tables,
                columns=contract.columns,
                column_type_hints=contract.column_type_hints,
                relation_role=contract.relation_role,
                ephemeral=False,
            )
            publish_cte_binding(local_ctx, published_binding, str(semantic_name))
            if semantic_name == "walk_restart":
                add_index(
                    physical_name,
                    suffix=SqlTableName("restart_node"),
                    columns=(SqlColumnName("node_id"),),
                    unique=True,
                )
            elif semantic_name == "walk_transitions":
                add_index(
                    physical_name,
                    suffix=SqlTableName("transition_source"),
                    columns=(SqlColumnName("source_node_id"),),
                )
                add_index(
                    physical_name,
                    suffix=SqlTableName("transition_target"),
                    columns=(SqlColumnName("target_node_id"),),
                )
            elif semantic_name == "walk_out_weights":
                add_index(
                    physical_name,
                    suffix=SqlTableName("out_source"),
                    columns=(SqlColumnName("source_node_id"),),
                    unique=True,
                )
            elif semantic_name == "walk_rank_0":
                add_index(
                    physical_name,
                    suffix=SqlTableName("rank0_node"),
                    columns=(SqlColumnName("node_id"),),
                    unique=True,
                )

        input_refs = (
            tuple(
                dict.fromkeys(
                    (
                        intent.inputs.node_relation_ref,
                        intent.inputs.edge_relation_ref,
                        *intent.inputs.transition_relation_refs,
                    ),
                ),
            )
            if closure is _GraphWalkRegionClosure.MATERIALIZED or ctx.backend_profile.traits.requires_graph_walk_input_materialization
            else ()
        )
        for input_index, input_ref in enumerate(input_refs):
            binding = local_ctx.cte_refs.get(str(input_ref))
            if binding is None:
                raise ValueError(f"Graph-walk input relation {input_ref!r} is not SQL-visible.")
            input_table = SqlTableName(f"tmp_gw_{digest}_input_{input_index}")
            input_query: SqlRenderable = SqlSelect(
                select=SqlSelectList(
                    tuple(SqlColumnRef(SqlColumnName(column)) for column in binding.columns),
                ),
                from_clause=SqlFrom(SqlTableIdent(SqlTableName(binding.ref_id))),
            )
            if binding.auxiliary_query is not None:
                auxiliary_query = binding.auxiliary_query
                if ctx.backend_profile.traits.requires_graph_walk_input_materialization and isinstance(
                    auxiliary_query, SqlOuterCteSplitProtocol
                ):
                    dependency_definitions, auxiliary_body = auxiliary_query.split_for_outer_cte()
                    dependency_statements, dependency_tables, input_query = _materialize_local_cte_definitions(
                        tuple(tree_cte_definition(definition) for definition in dependency_definitions),
                        auxiliary_body,
                        table_prefix=f"tmp_gw_{digest}_i{input_index}_d",
                    )
                    statements.extend(dependency_statements)
                    temporary_tables.extend(dependency_tables)
                else:
                    input_query = SqlCte(
                        (SqlCteDefinition(SqlCteName(binding.ref_id), auxiliary_query),),
                        input_query,
                        recursive=True,
                    )
            statements.append(
                SqlCreateTemporaryTableAsSelect(
                    input_table,
                    input_query,
                    transaction_owned=True,
                ),
            )
            temporary_tables.append(input_table)
            published_binding = CteReference(
                ServerPlanRefId(input_table),
                source_tables=binding.source_tables,
                columns=binding.columns,
                column_type_hints=binding.column_type_hints,
                relation_role=binding.relation_role,
                ephemeral=False,
            )
            publish_cte_binding(local_ctx, published_binding, str(input_ref))

        for name, suffix in (
            (SqlCteName("walk_restart"), SqlTableName("restart")),
            (SqlCteName("walk_transitions"), SqlTableName("transitions")),
            (SqlCteName("walk_out_weights"), SqlTableName("out")),
            (SqlCteName("walk_rank_0"), SqlTableName("rank0")),
            (
                SqlCteName("walk_required_invalid_weights"),
                SqlTableName("invalid"),
            ),
        ):
            definition = definitions[name]
            query_override: QuerySpec[Any] | None = None
            if name == "walk_required_invalid_weights":
                invalid_query = definition.query
                if not isinstance(invalid_query, QuerySpec):
                    msg = (
                        "Graph-walk invalid-weight validation must use a QuerySpec. "
                        f"Relation {name!r} uses {type(invalid_query).__name__}."
                    )
                    raise ValueError(msg)
                query_override = replace(invalid_query, ctes=())
            materialize_relation(
                name,
                definition,
                suffix=suffix,
                query=query_override,
            )

        prior_rank_ref: ServerPlanRefId | None = None
        active_rank_tables: dict[int, SqlTableName] = {}
        for iteration in range(1, count):
            program = _without_common_program(
                _ordered_iteration_program(
                    intent,
                    iteration=iteration,
                    previous_rank_ref=prior_rank_ref,
                    final_iteration=False,
                ),
            )
            rank_ref = ServerPlanRefId(f"{intent.ref_id}.rank_{iteration}")
            slot = iteration % 2
            rank_table = SqlTableName(f"tmp_gw_{digest}_rank_{slot}")
            replacing_existing_slot = slot in active_rank_tables
            if replacing_existing_slot:
                statements.append(SqlDelete(sql_table_expr(rank_table)))
            compiled, producer = _compiled_query(
                ref_id=rank_ref,
                query=program.final_rank_query,
                ctx=local_ctx,
                permission_dependency_refs=_permission_refs(intent),
            )
            rank_grammar = _materialized_grammar(compiled)
            if replacing_existing_slot:
                statements.append(SqlInsert(sql_table_expr(rank_table), source=rank_grammar))
            else:
                statements.append(
                    SqlCreateTemporaryTableAsSelect(
                        rank_table,
                        rank_grammar,
                        transaction_owned=True,
                    ),
                )
                temporary_tables.append(rank_table)
            manifests.append(compiled.provenance_manifest)
            contract = producer.cte_publication_contract()
            published_binding = CteReference(
                ServerPlanRefId(rank_table),
                source_tables=contract.source_tables,
                columns=contract.columns,
                column_type_hints=contract.column_type_hints,
                relation_role=contract.relation_role,
                ephemeral=False,
            )
            publish_cte_binding(local_ctx, published_binding, str(rank_ref))
            if not replacing_existing_slot:
                add_index(
                    rank_table,
                    suffix=SqlTableName(f"rank_{slot}_node"),
                    columns=(SqlColumnName("node_id"),),
                    unique=True,
                )
            active_rank_tables[slot] = rank_table
            prior_rank_ref = rank_ref

        final_program = _without_common_program(
            _ordered_iteration_program(
                intent,
                iteration=count,
                previous_rank_ref=prior_rank_ref,
                final_iteration=True,
            ),
        )
        final_compiled = self._score_step(final_program).compile(local_ctx)
        manifests.append(final_compiled.provenance_manifest)
        if closure is _GraphWalkRegionClosure.CLOSED:
            statements.append(_materialized_grammar(final_compiled))
            statements.extend(SqlDropTemporaryTableIfExists(table) for table in reversed(temporary_tables))
            final_index = len(statements) - len(temporary_tables) - 1
            batch = SqlStatementBatch(
                [SqlDeclaredCteInputs(statement, frozenset()) for statement in statements],
                category=SqlStatementBatchCategory.DEPENDENCY_GRAPH,
                relationships=tuple(
                    SqlStatementRelationship(
                        predecessor=index,
                        successor=index + 1,
                        kind=SqlStatementRelationshipKind.DATA_VISIBILITY,
                    )
                    for index in range(len(statements) - 1)
                ),
                needs_returning_per_stmt=[index == final_index for index in range(len(statements))],
                collect_results_per_stmt=[index == final_index for index in range(len(statements))],
            )
            for statement in batch.statements:
                fragment = statement.render(ctx.sql_render_dialect())
                sql, params = fragment.to_sql(ctx.sql_render_dialect())
                enforce_statement_capacity(
                    rendered_sql_bytes=len(sql.encode("utf-8")),
                    parameter_count=len(params),
                    capacity=ctx.sql_statement_capacity,
                )
            output_shape, result_relation, column_type_hints = final_compiled.require_sql_output_contract()
            return CompiledStep(
                grammar=batch,
                closed_post_op=final_compiled.closed_post_op,
                output_shape=output_shape,
                result_relation=result_relation,
                column_type_hints=column_type_hints,
                provenance_manifest=merge_permission_manifests(*manifests),
                allow_empty_provenance_manifest=final_compiled.allow_empty_provenance_manifest,
                use_savepoint_recovery=final_compiled.use_savepoint_recovery,
            )

        result_table = SqlTableName(f"tmp_gw_{digest}_result")
        statements.append(
            SqlCreateTemporaryTableAsSelect(
                result_table,
                _materialized_grammar(final_compiled),
                transaction_owned=True,
            ),
        )
        temporary_tables.append(result_table)
        output_shape, result_relation, column_type_hints = final_compiled.require_sql_output_contract()
        publication_grammar = SqlSelect(
            select=SqlSelectList(
                tuple(SqlColumnRef(SqlColumnName(column)) for column in output_shape.cte_output_columns),
            ),
            from_clause=SqlFrom(SqlTableIdent(result_table)),
        )
        publication = replace(
            final_compiled,
            grammar=publication_grammar,
            ir=None,
            params=None,
            auxiliary_ctes=None,
            needs_recursive_with=False,
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
            provenance_manifest=merge_permission_manifests(*manifests),
            compiled_sql_publication=NoCompiledSqlPublication(),
        )
        statement_program = _single_statement_program(intent)
        replaced_relation_names = set(
            _statement_local_relation_names(statement_program.final_rank_query),
        )
        if statement_program.selected_rank_query is not None:
            replaced_relation_names.update(
                _statement_local_relation_names(
                    statement_program.selected_rank_query,
                ),
            )
        for relations in statement_program.iterations:
            for iteration_query in (
                relations.contribution_query,
                relations.incoming_query,
                relations.dangling_query,
                relations.rank_query,
                relations.delta_query,
            ):
                replaced_relation_names.update(
                    _statement_local_relation_names(iteration_query),
                )
        replaced_statement_local_relations = frozenset(
            relation_name for relation_name in replaced_relation_names if relation_name.startswith("walk_")
        )
        product = MaterializedDependentReadRegion(
            setup_statements=tuple(statements),
            cleanup_statements=tuple(SqlDropTemporaryTableIfExists(table) for table in reversed(temporary_tables)),
            replaced_statement_local_relations=replaced_statement_local_relations,
            publication=publication,
        )
        return product

    def compile_materialized_dependent_read_region_relation(
        self: _PhysicalGraphWalkStep,
        ctx: CompilationContext,
    ) -> MaterializedDependentReadRegion[Sequence[dict[str, object]]]:
        """Materialize one graph relation for a complete dependent-read region."""
        compiled = self._compile_transaction_relation_candidate(
            ctx,
            closure=_GraphWalkRegionClosure.MATERIALIZED,
        )
        if not isinstance(compiled, MaterializedDependentReadRegion):
            msg = "A materialized graph-walk region must compile to a relation product."
            raise TypeError(msg)
        return compiled


def lower_personalized_random_walk_intent(
    intent: ExecutePersonalizedRandomWalkIntent[Any],
    ctx: LoweringContext,
) -> Sequence[ServerPlanStep[Any]]:
    """Lower one semantic walk; physical candidate admission occurs at compile time."""
    semantic_program = _single_statement_program(intent)
    assertion_steps, assertion_refs = _assertion_steps(
        intent,
        semantic_program,
        materialize_relations=ctx.backend_profile.traits.requires_graph_walk_input_materialization,
    )
    return [*assertion_steps, _PhysicalGraphWalkStep(intent, assertion_refs=assertion_refs)]

