def _validated_outer_cte_split(value: object) -> tuple[list[SqlCteDefinition], SqlRenderable]:
    if not isinstance(value, tuple) or len(value) != 2:
        raise TypeError("split_for_outer_cte() must return definitions and a final query")
    raw_definitions, query = value
    if not isinstance(raw_definitions, (list, tuple)):
        raise TypeError("split_for_outer_cte() definitions must be a sequence")
    definitions: list[SqlCteDefinition] = []
    for definition in raw_definitions:
        if isinstance(definition, SqlCteDefinition):
            definitions.append(definition)
            continue
        name = getattr(definition, "name", None)
        query_value = getattr(definition, "query", None)
        if not isinstance(name, str) or not isinstance(query_value, SqlRenderable):
            raise TypeError("split_for_outer_cte() returned an invalid CTE definition")
        definitions.append(SqlCteDefinition(name, query_value))
    if not isinstance(query, SqlRenderable):
        raise TypeError("split_for_outer_cte() final query must be SqlRenderable")
    return definitions, query


