def _query_spec_order_by(query_spec: QuerySpec[Any]) -> tuple[object, ...] | list[object]:
    return getattr(query_spec, "order_by", getattr(query_spec, "order_by_clauses", ()))


def _build_delete_where(
    query_spec: QuerySpec[Any],
    *,
    planning_catalog: PlanningCatalog | None,
    compilation_context: CompilationContext | None = None,
) -> SqlConditionalClause | None:
    from impl.common.l2070_server_plan.steps._query_helper_compile import (
        _build_pk_select_clause,
        _build_simple_from,
    )
    from impl.common.l2100_sql_grammar.tree.clauses import SqlConditionalClause, SqlWhereClause
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef
    from impl.common.l2100_sql_grammar.tree.expr_ops import SqlIn
    from impl.common.l2100_sql_grammar.tree.statements import SqlSelect
    from impl.common.l5200_sql_query.query_grammar import QueryGrammarBuilder
    from l1000_schema.schema_def import get_db_column_name
    from l1000_schema.table_utils import get_table_name

    from impl.common.l5200_sql_query.query_grammar import _apply_implicit_polymorphic_type_filter

    query_spec = _apply_implicit_polymorphic_type_filter(query_spec)
    builder = QueryGrammarBuilder(
        query_spec,
        planning_catalog=planning_catalog,
        compilation_context=compilation_context,
    )
    has_limit = _query_spec_limit_value(query_spec) is not None
    has_order = bool(_query_spec_order_by(query_spec))

    if not has_limit and not has_order:
        where_clause: SqlConditionalClause | None = builder.build_where_clause()
        return where_clause

    pk_db_col = str(get_db_column_name(query_spec.model_cls, DynamicFieldName("sys_id")))
    pk_col = SqlColumnRef(SqlColumnName(pk_db_col))
    subquery = SqlSelect(
        select=_build_pk_select_clause(pk_db_col),
        from_clause=_build_simple_from(get_table_name(query_spec.model_cls)),
        where=builder.build_where_clause(),
        order_by=builder._build_order_by_clause(),
        limit=_query_spec_limit_value(query_spec),
        offset=_query_spec_offset_value(query_spec),
    )
    return SqlWhereClause(SqlIn(pk_col, subquery))


def _apply_versioned_staged_branch_context(
    query_spec: QuerySpec[Any],
    ctx: CompilationContext,
) -> QuerySpec[Any]:
    table_name = get_table_name(query_spec.model_cls)
    if ctx.branch_id is None or not table_name.endswith("_staged"):
        return query_spec
    rewritten_filters: list[QueryFilter] = []
    changed = False
    for query_filter in query_spec.filters:
        if query_filter.column == "branch_id" and query_filter.expression is None and query_filter.operator == "=":
            rewritten_filters.append(
                QueryFilter(
                    column=query_filter.column,
                    operator=query_filter.operator,
                    value=BranchId(ctx.branch_id),
                    json_key=query_filter.json_key,
                ),
            )
            changed = True
            continue
        rewritten_filters.append(query_filter)
    if not changed:
        return query_spec
    return replace(query_spec, filters=rewritten_filters)


def _delete_count_post_op() -> CompiledPostOp:
    return scalar_column_post_op(
        "count",
        default_value=0,
        use_default_on_empty=True,
        scalar_coercion=ScalarCoercionKind.INT,
    )


def _count_then_delete_batch(
    *,
    table_name: SqlTableName,
    where_clause: SqlConditionalClause | None,
    delete_stmt: SqlRenderable,
) -> SqlRenderable:
    from impl.common.l2100_sql_grammar.domain.infra.stmt_compound_write import (
        SqlStatementBatch,
        SqlStatementBatchCategory,
    )
    from impl.common.l2100_sql_grammar.domain.infra.stmt_dml_simple import SqlCountQuery

    count_stmt = SqlCountQuery(SqlTableName(table_name), where=where_clause)
    return SqlStatementBatch(
        [count_stmt, delete_stmt],
        category=SqlStatementBatchCategory.ORDERED_SEMANTIC,
        needs_returning_per_stmt=[True, False],
        collect_results_per_stmt=[True, False],
    )


@dataclass(frozen=True)
