def _model_db_column_names(model_cls: type[DatabaseObjectRow]) -> tuple[str, ...]:
    from l2070_batching.write_column_policy import producer_publication_columns

    return producer_publication_columns(model_cls)


class QueryDeleteStep(MaybeSqlRelationPublisherStep[int]):
    def staging_bypass_staged_delete(self: QueryDeleteStep) -> StagingBypassStagedDelete | None:
        return StagingBypassStagedDelete(
            staged_table_name=SqlTableName(get_table_name(self._model_cls)),
            staged_model=self._model_cls,
            staged_commit_ids=frozenset(),
            dependencies=frozenset(ServerPlanRefId(dependency) for dependency in self.dependencies()),
        )

    """Step for executing query builder .delete() operations."""

    def __init__(
        self: QueryDeleteStep,
        ref_id: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        config: _QueryDeleteStepConfig,
    ) -> None:
        super().__init__(_ref_id(ref_id))
        self._model_cls = model_cls
        self._query_spec = config.query_spec
        self._after_refs = config.after_refs
        self._user_id_ref_id = config.user_id_ref_id
        self._cte_returning_columns = config.cte_returning_columns
        self._returns_deleted_rows = config.returns_deleted_rows
        self._returns_first_deleted_row = config.returns_first_deleted_row
        self._effect_only = config.effect_only
        self._preimage_ref_id = config.preimage_ref_id
        self._resolved_user_id: ResolvedPermissionUserId = None

    @property
    def level(self: QueryDeleteStep) -> int:
        return 0

    def step_tags(self: QueryDeleteStep) -> frozenset[str]:
        """Return tags identifying this step type."""
        return frozenset({"write", "query", "delete"})

    def is_read_only(self: QueryDeleteStep) -> bool:
        """Return False - this step modifies data."""
        return False

    def cte_relation_role(self: QueryDeleteStep) -> str | None:
        if self._returns_deleted_rows:
            return None
        return "count_only"

    def requires_materialized_inputs(self: QueryDeleteStep) -> bool:
        return self._query_spec is None or (self._query_spec is not None and self._query_spec.permission_context_ref is not None)

    def supports_sql_batch_transport(self: QueryDeleteStep) -> bool:
        return self._query_spec is not None

    def supports_ordered_sql_statement_batch(self: QueryDeleteStep) -> bool:
        return True

    def requires_prior_step_boundary(self: QueryDeleteStep) -> bool:
        return self._returns_deleted_rows or self.requires_materialized_inputs()

    def result_cardinality(self: QueryDeleteStep) -> Cardinality:
        """Return MANY only when runtime consumers expect deleted rows."""
        if self._returns_first_deleted_row:
            return Cardinality.ONE
        if self._returns_deleted_rows:
            return Cardinality.MANY
        return Cardinality.SCALAR

    def tables_read(self: QueryDeleteStep) -> frozenset[str]:
        """Query delete reads the table to evaluate the WHERE clause."""
        return frozenset({get_table_name(self._model_cls)})

    def tables_written(self: QueryDeleteStep) -> frozenset[str]:
        """Return the table name this step writes to."""
        return frozenset({get_table_name(self._model_cls)})

    def dependencies(self: QueryDeleteStep) -> frozenset[str]:
        """Return ref_ids this step depends on (from query_spec filters + lazy params + after_refs)."""
        deps: set[str] = {str(ref_id) for ref_id in self._after_refs}
        if self._query_spec is not None:
            from impl.common.l2070_server_plan.steps._resolve import collect_query_spec_deps

            deps.update(collect_query_spec_deps(self._query_spec))
        if self._user_id_ref_id is not None:
            deps.add(str(self._user_id_ref_id))
        return frozenset(deps)

    def sql_visible_dependencies(self: QueryDeleteStep) -> frozenset[str]:
        """Return dependencies that must be visible as SQL bindings."""
        deps: set[str] = set()
        if self._query_spec is not None:
            from impl.common.l2070_server_plan.steps._resolve import collect_query_spec_deps

            deps.update(collect_query_spec_deps(self._query_spec))
        if self._user_id_ref_id is not None:
            deps.add(str(self._user_id_ref_id))
        return frozenset(deps)

    def cte_publication_contract(self: QueryDeleteStep) -> CtePublicationContract:
        def _legacy_cte_output_columns() -> tuple[str, ...] | None:
            if not self._returns_deleted_rows:
                return ("count",)
            if self._cte_returning_columns is not None:
                return self._cte_returning_columns
            return _model_db_column_names(self._model_cls)

        columns = _legacy_cte_output_columns()

        def _legacy_cte_column_type_hints(columns: tuple[str, ...] | None) -> SqlColumnTypeHints:
            if not self._returns_deleted_rows:
                return SqlColumnTypeHints(bigint_columns=frozenset({"count"}))
            if columns is None:
                msg = f"{type(self).__name__} returning rows require concrete CTE columns"
                raise TypeError(msg)
            hints = model_sql_column_type_hints(self._model_cls, columns)
            if hints is None:
                msg = f"Could not resolve SQL column type hints for {self._model_cls.__name__} delete returning rows"
                raise TypeError(msg)
            return hints

        column_type_hints = _legacy_cte_column_type_hints(columns)
        if columns is None:
            if column_type_hints is not None and column_type_hints.has_any():
                msg = f"{type(self).__name__} declares SQL column type hints without an explicit cte_output_columns() contract."
                raise TypeError(msg)
            return CtePublicationContract.non_publishing()
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        _contract_model_cls = cte_projection_row_model(
            f"{type(self).__name__}CteRow",
            columns,
            column_type_hints,
        )
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=tuple(str(column) for column in columns),
            column_type_hints=column_type_hints,
            model_cls=_contract_model_cls,
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
            scalar_control_kind=(ScalarControlKind.AFFECTED_COUNT if not self._returns_deleted_rows else None),
            scalar_value_column=(LockedColumnName("count") if not self._returns_deleted_rows else None),
        )

    def always_publishes_executor_visible_binding(self: QueryDeleteStep) -> bool:
        """Deleted rows must stay SQL-visible: hydration of returning deletes
        reads them from the published binding after the delete statement ran."""
        return True

    def compile(self: QueryDeleteStep, ctx: CompilationContext) -> CompiledStep[int]:
        from impl.common.l2070_server_plan.steps._compile_helpers import (
            _combine_where,
            _has_server_ref_in_filters,
            _resolve_server_ref_filters_to_cte,
            attach_runtime_permission_grammar,
            materialize_permission_user_id,
        )
        from impl.common.l2100_sql_grammar.tree.clauses import SqlReturningClause, SqlWhereClause
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef
        from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
        from impl.common.l2100_sql_grammar.tree.statements import SqlDelete
        from l1000_schema.table_utils import get_table_name

        resolved_user_id: ResolvedPermissionUserId = self._resolved_user_id
        if resolved_user_id is None and self._user_id_ref_id is not None:
            resolved_user_id = _require_query_delete_user_cte(ctx, self._user_id_ref_id)
        permission_user_binding = resolved_user_id if isinstance(resolved_user_id, CteReference) else None
        resolved_user_id = materialize_permission_user_id(resolved_user_id, ctx)
        query_spec = replace(self._query_spec, filters=list(self._query_spec.filters)) if self._query_spec is not None else None
        cte_where_exprs: list[SqlRenderable] = []
        consumed_cte_refs: list[CteReference] = []
        if query_spec is not None:
            query_spec = _apply_versioned_staged_branch_context(query_spec, ctx)
            if _has_server_ref_in_filters(query_spec):
                cte_where_exprs = _resolve_server_ref_filters_to_cte(
                    query_spec,
                    ctx,
                    consumed_cte_refs=consumed_cte_refs,
