@pure_lazy
def _single_column_type_hints(column: str, source_type: str) -> SqlColumnTypeHints:
    if source_type == "JSONB":
        return SqlColumnTypeHints(jsonb_columns=frozenset({column}))
    if source_type == "UUID":
        return SqlColumnTypeHints(uuid_columns=frozenset({column}))
    if source_type == "TIMESTAMPTZ":
        return SqlColumnTypeHints(timestamptz_columns=frozenset({column}))
    if source_type == "DATE":
        return SqlColumnTypeHints(date_columns=frozenset({column}))
    if source_type == "BOOLEAN":
        return SqlColumnTypeHints(bool_columns=frozenset({column}))
    if source_type == "INTEGER":
        return SqlColumnTypeHints(integer_columns=frozenset({column}))
    if source_type == "BIGINT":
        return SqlColumnTypeHints(bigint_columns=frozenset({column}))
    if source_type == "DOUBLE PRECISION":
        return SqlColumnTypeHints(double_columns=frozenset({column}))
    if source_type == "TEXT":
        return SqlColumnTypeHints(text_columns=frozenset({column}))
    if source_type == "BYTEA":
        return SqlColumnTypeHints(bytea_columns=frozenset({column}))
    msg = f"Unsupported conditional literal SQL type {source_type!r}"
    raise TypeError(msg)


@pure_lazy
def _conditional_default_type_hints[IfTrueStepsItemT](
    if_true_steps: Sequence[ServerPlanStep[IfTrueStepsItemT]],
    result_ref: ServerPlanRefId,
) -> SqlColumnTypeHints | None:
    from l2070_batching.step import _cte_publication_contract_for_step

    for step in if_true_steps:
        if str(step.ref_id) != str(result_ref):
            continue
        contract = _cte_publication_contract_for_step(step)
        if contract is None:
            return None
        columns = contract.columns
        if len(columns) != 1:
            return None
        hints = contract.column_type_hints
        if hints is None:
            return None
        cast_target = hints.cast_target_for_column(columns[0])
        if cast_target is not None:
            return _single_column_type_hints(columns[0], cast_target.base_type)
    msg = (
        f"Cannot derive conditional default SQL type hints for result ref {result_ref!r}; "
        "the true branch result must publish one typed SQL-visible column."
    )
    raise TypeError(msg)


@pure_lazy
def _conditional_result_contract[IfTrueStepsItemT](
    if_true_steps: Sequence[ServerPlanStep[IfTrueStepsItemT]],
