class _UnarySqlExpr(SqlRenderOrderShapeMixin, SqlExprBase):
    __slots__ = ("_operand",)

    def __init__(self: _UnarySqlExpr, operand: SqlRenderable) -> None:
        self._operand = operand

    def render_order_shape_parts(self: _UnarySqlExpr, dialect: Any) -> SqlRenderOrderShapeParts:
        del dialect
        return (("operand", self._operand),)

    def render(self: _UnarySqlExpr, dialect: Any) -> SqlFragment:
        return SQL_NOT + SQL_OPEN_PAREN + self._operand.render(dialect) + SQL_CLOSE_PAREN


class _BinarySqlExpr(SqlRenderOrderShapeMixin, SqlExprBase):
    __slots__ = ("_left", "_operator", "_right")

    def __init__(self: _BinarySqlExpr, left: SqlRenderable, operator: str, right: SqlRenderable) -> None:
        self._left = left
        self._operator = operator
        self._right = right

    def render_order_shape_parts(self: _BinarySqlExpr, dialect: Any) -> SqlRenderOrderShapeParts:
        del dialect
        return (
            ("left", self._left),
            ("operator", SqlRenderOrderStructuralValue(self._operator)),
            ("right", self._right),
        )

    def render(self: _BinarySqlExpr, dialect: Any) -> SqlFragment:
        operator = SQL_BINARY_OPERATORS[self._operator]
        return SQL_OPEN_PAREN + self._left.render(dialect) + operator + self._right.render(dialect) + SQL_CLOSE_PAREN


