def _lower_lazy_boolean_expression[Owner: DatabaseObjectRow](
    expr: Expression[Any, Owner],
    ctx: CompilationContext,
) -> SqlRenderable:
    from impl.common.l2070_server_plan.steps._compile_server_ref import lower_scalar_source
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlParam
    from l2070_batching.server_ref import ScalarServerRef

    if expr.logical_op == "NOT" and expr.left is not None:
        return _UnarySqlExpr(_lower_lazy_boolean_expression(expr.left, ctx))
    if expr.logical_op in {"AND", "OR"} and expr.left is not None and expr.right is not None:
        return _BinarySqlExpr(
            _lower_lazy_boolean_expression(expr.left, ctx),
            expr.logical_op,
            _lower_lazy_boolean_expression(expr.right, ctx),
        )
    if expr.operator in {"=", "!=", "<>", "<", "<=", ">", ">="} and expr.left is not None:
        right = expr.right if expr.right is not None else Expression(value=expr.value)
        operator = expr.operator
        right_is_null = (
            isinstance(right, Expression)
            and right.value is None
            and right.left is None
            and right.right is None
            and right.logical_op is None
            and right.operator is None
        )
        if right_is_null and operator in {"=", "!=", "<>"}:
            operator = "IS" if operator == "=" else "IS NOT"
        return _BinarySqlExpr(
            _lower_lazy_boolean_expression(expr.left, ctx),
            operator,
            SqlParam(None) if right_is_null else _lower_lazy_boolean_expression(right, ctx),
        )
    if isinstance(expr.value, ScalarServerRef):
        return lower_scalar_source(expr.value, ctx, default_field="__result")
    if expr.value is not None:
        return SqlParam(expr.value)
    msg = "when_lazy() only supports lazy scalar bindings and boolean composition over them"
    raise TypeError(msg)


def _branch_requirement[StepsItemT](
    steps: Sequence[ServerPlanStep[StepsItemT]],
) -> StagedReadRequirement | None:
    requirements = [requirement for step in steps if (requirement := step.staged_read_descriptor()) is not None]
    if not requirements:
        return None
    first_scope = requirements[0].scope
    if any(requirement.scope != first_scope for requirement in requirements[1:]):
        return None
    source_keys = tuple(
        dict.fromkeys(source_key for requirement in requirements for source_key in requirement.source_keys),
    )
    from l2070_batching.staged_source import StagedReadRequirement

    return StagedReadRequirement(source_keys=source_keys, scope=first_scope)


