        return super().compile(ctx)

    def lower(self: OneSidedConditionalStep, ctx: LoweringContext) -> Sequence[ServerPlanStep[Any]]:
        return super().lower(ctx)

    def staged_read_descriptor(self: OneSidedConditionalStep) -> StagedReadRequirement | None:
        return _branch_requirement((*self.if_true_steps, *self.else_steps))

    def delegates_versioned_commit_effects(self: OneSidedConditionalStep) -> bool:
        """Let the exact branch producers own conditional staged-write effects."""
        return True

    def staged_commit_ids_for_effect(self: OneSidedConditionalStep) -> tuple[str, ...]:
        """Return the exact staged-commit identities owned by conditional branches."""
        return tuple(
            dict.fromkeys(
                staged_commit_id
                for child in (*self.if_true_steps, *self.else_steps)
                for staged_commit_id in child.staged_commit_ids_for_effect()
            ),
        )

    def provided_staged_sources(self: OneSidedConditionalStep) -> frozenset[str]:
        provided: set[str] = set()
        for child in (*self.if_true_steps, *self.else_steps):
            provided.update(child.provided_staged_sources())
        return frozenset(provided)


@pure_lazy
def build_one_sided_conditional[IfTrueStepsItemT](
    *,
    ref_id: ServerPlanRefId | str,
    condition_ref: ServerPlanRefId | str,
    if_true_steps: Sequence[ServerPlanStep[IfTrueStepsItemT]],
    result_ref: ServerPlanRefId | str | None = None,
    default_value: object | None = None,
    skip_if_ref: ServerPlanRefId | str | None = None,
    propagate_skip: bool = False,
    force_prior_step_boundary: bool = False,
    allow_ordered_output_transport: bool = False,
) -> OneSidedConditionalStep:
    """Build a canonical conditional for the former one-sided SQL gate shape."""
    resolved_ref_id = _ref_id(ref_id)
    resolved_result_ref = _ref_id(result_ref) if result_ref is not None else None
    else_steps: list[ServerPlanStep[Any]] = []
    output_bindings: dict[ServerPlanRefId, tuple[ServerPlanRefId, ServerPlanRefId]] = {}
    if resolved_result_ref is not None:
        else_ref = ServerPlanRefId(f"{resolved_ref_id}_default")
        result_contract = _conditional_result_contract(if_true_steps, resolved_result_ref)
        if result_contract is None:
            from impl.common.l2070_server_plan.steps.return_value import ReturnValueStep

            else_steps.append(ReturnValueStep(else_ref, default_value))
        elif result_contract.model_cls is None:
            msg = f"Conditional result ref {resolved_result_ref!s} publishes CTE columns without an explicit result-row model."
            raise TypeError(msg)
        elif len(result_contract.columns) > 1:
            else_steps.append(
                ConditionalNullRowStep(
                    else_ref,
                    columns=result_contract.columns,
                    type_hints=result_contract.column_type_hints,
                    model_cls=result_contract.model_cls,
                )
            )
        else:
            literal_type_hints = _conditional_default_type_hints(if_true_steps, resolved_result_ref)
            assert literal_type_hints is not None
            result_column = next(iter(result_contract.columns), None)
            if result_column is None:
                msg = f"Conditional result ref {resolved_result_ref!s} has no SQL-visible column."
                raise TypeError(msg)
            else_steps.append(
                ConditionalLiteralStep(
                    else_ref,
                    config=_ConditionalLiteralConfig(
                        default_value,
                        literal_type_hints,
                        result_column,
                        result_contract.model_cls,
                    ),
                ),
            )
        output_bindings[resolved_ref_id] = (resolved_result_ref, else_ref)

    return OneSidedConditionalStep(
        resolved_ref_id,
        condition_ref=_ref_id(condition_ref),
        if_true_steps=if_true_steps,
        else_steps=else_steps,
        output_bindings=output_bindings,
        skip_if_ref=_ref_id(skip_if_ref) if skip_if_ref is not None else None,
        propagate_skip=propagate_skip,
        force_prior_step_boundary=force_prior_step_boundary,
        allow_ordered_output_transport=allow_ordered_output_transport,
    )


__all__ = [
    "BooleanExpressionStep",
    "ConditionalLiteralStep",
    "OneSidedConditionalStep",
    "build_one_sided_conditional",
]

