class AppSessionAccessAdmissionStep(MaybeSqlRelationPublisherStep[SessionId | None]):
    """Publish a session only when mutable credential lifecycle state admits it."""

    def __init__(self, ref_id: ServerPlanRefId, facts: AppSessionAdmissionFacts) -> None:
        super().__init__(ref_id)
        self._facts = facts

    @property
    def admission_facts(self) -> AppSessionAdmissionFacts:
        """Return the immutable facts that the SQL admission query corroborates."""
        return self._facts

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.ONE

    def declares_consumed_rows_reduction(self) -> bool:
        return True

    def is_read_only(self) -> bool:
        return True

    def tables_read(self) -> frozenset[str]:
        from l1000_schema.table_utils import get_table_name

        return frozenset(
            {
                get_table_name(CapabilityTokenIssued),
                get_table_name(CapabilityTokenFamily),
                get_table_name(CapabilityTokenRevocation),
                get_table_name(User),
                get_table_name(UserSession),
                get_table_name(AuthPrincipalBinding),
            },
        )

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def step_tags(self) -> frozenset[str]:
        return frozenset({"read", "scalar", "authentication", "session"})

    def dependencies(self) -> frozenset[str]:
        return frozenset()

    def sql_visible_dependencies(self) -> frozenset[str]:
        return frozenset()

    def supports_sql_batch_transport(self) -> bool:
        return True

    def supports_ordered_sql_statement_batch(self) -> bool:
        return True

    def always_publishes_executor_visible_binding(self) -> bool:
        return True

    def cte_publication_contract(self) -> CtePublicationContract:
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=("session_id",),
            column_type_hints=SqlColumnTypeHints(uuid_columns=frozenset({"session_id"})),
            model_cls=_AppSessionAdmissionRow,
            relation_role=self.cte_relation_role(),
            optional_columns=frozenset({"session_id"}),
            source_tables=self.tables_read(),
        )

    def compile(self, ctx: CompilationContext) -> CompiledStep[SessionId | None]:
        del ctx
        from impl.common.l2050_sql_types.sql_branded_types import (
            SqlAliasName,
            SqlColumnName,
            SqlTableName,
        )
        from impl.common.l2100_sql_grammar.tree.clauses import (
            SqlDialectCurrentTimestampComparison,
            SqlSelectAlias,
            SqlSelectList,
            SqlWhereClause,
        )
        from impl.common.l2100_sql_grammar.tree.enums import BinaryOp, UnaryOp
        from impl.common.l2100_sql_grammar.tree.expr_compound import SqlFuncCall
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlParam
        from impl.common.l2100_sql_grammar.tree.expr_ops import (
            SqlBinaryOp,
            SqlExists,
            SqlIsNull,
            SqlUnaryOp,
            sql_and,
            sql_or,
        )
        from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
        from impl.common.l2100_sql_grammar.tree.statements import SqlSelect
        from l1000_schema.column_utils import get_db_column_name
        from l1000_schema.table_utils import get_table_name

        facts = self._facts

        def column(model: type[BaseModel], name: str) -> SqlColumnRef:
            return SqlColumnRef(SqlColumnName(get_db_column_name(model, DynamicFieldName(name))))

        def exists(model: type[BaseModel], condition: SqlRenderable) -> SqlExists:
            return SqlExists(
                SqlSelect(
                    select=SqlSelectList([column(model, "sys_id")]),
                    from_=SqlTableIdent(SqlTableName(get_table_name(model))),
                    where=SqlWhereClause(condition),
                    limit=1,
                ),
            )

        def optional_column_equals(
            model: type[BaseModel],
            name: str,
            expected: object | None,
        ) -> SqlRenderable:
            sql_column = column(model, name)
            if expected is None:
                return SqlIsNull(sql_column)
            return SqlBinaryOp(sql_column, BinaryOp.EQ, SqlParam(expected))

        issued_conditions: list[SqlRenderable] = [
            SqlBinaryOp(column(CapabilityTokenIssued, "sys_id"), BinaryOp.EQ, SqlParam(facts.token_id)),
            SqlBinaryOp(column(CapabilityTokenIssued, "family_id"), BinaryOp.EQ, SqlParam(facts.family_id)),
            optional_column_equals(CapabilityTokenIssued, "audience", facts.audience),
            optional_column_equals(CapabilityTokenIssued, "issuer_id", facts.issuer_id),
            optional_column_equals(CapabilityTokenIssued, "subject_id", facts.subject_id),
            optional_column_equals(CapabilityTokenIssued, "token_kind", "renewable_access"),
        ]
        binding_column = column(CapabilityTokenIssued, "binding_fingerprint_hash")
        if facts.expected_binding_hash is None:
            issued_conditions.append(SqlIsNull(binding_column))
        else:
            issued_conditions.append(
                SqlBinaryOp(binding_column, BinaryOp.EQ, SqlParam(facts.expected_binding_hash)),
            )

        family_active = sql_and(
            SqlBinaryOp(column(CapabilityTokenFamily, "sys_id"), BinaryOp.EQ, SqlParam(facts.family_id)),
            SqlIsNull(column(CapabilityTokenFamily, "revoked_at")),
            optional_column_equals(CapabilityTokenFamily, "issuer_id", facts.issuer_id),
            optional_column_equals(CapabilityTokenFamily, "subject_id", facts.subject_id),
        )
        token_revoked = exists(
            CapabilityTokenRevocation,
            SqlBinaryOp(
                column(CapabilityTokenRevocation, "token_id"),
                BinaryOp.EQ,
                SqlParam(facts.token_id),
            ),
        )
        action_allowed = (
            sql_or(
                *(
                    sql_or(
                        SqlBinaryOp(SqlParam(str(action)), BinaryOp.EQ, SqlParam("*")),
                        SqlBinaryOp(
                            SqlParam(str(action)),
                            BinaryOp.EQ,
                            SqlParam(str(facts.expected_action)),
                        ),
                    )
                    for action in facts.granted_actions
                ),
            )
            if facts.granted_actions
            else SqlParam(False)
        )

        conditions: list[SqlRenderable] = [
            SqlParam(facts.validation_error is None),
            SqlBinaryOp(SqlParam(facts.expiry), BinaryOp.GT, SqlFuncCall("CURRENT_TIMESTAMP", [])),
            SqlBinaryOp(
                SqlParam(str(facts.audience)),
                BinaryOp.EQ,
                SqlParam(str(facts.expected_audience)),
            ),
            action_allowed,
            exists(CapabilityTokenIssued, sql_and(*issued_conditions)),
            exists(CapabilityTokenFamily, family_active),
            SqlUnaryOp(UnaryOp.NOT, token_revoked),
        ]
        conditions.append(
            SqlBinaryOp(
                SqlParam(facts.principal_mode.value),
                BinaryOp.EQ,
                SqlParam(facts.expected_principal_mode.value),
            ),
        )
        if facts.principal_mode is AuthPrincipalMode.AUTHORITATIVE and facts.app_user_id is not None and facts.session_id is not None:
            live_user = sql_and(
                SqlBinaryOp(
                    column(User, "sys_id"),
                    BinaryOp.EQ,
                    SqlParam(facts.app_user_id),
                ),
                SqlBinaryOp(column(User, "active"), BinaryOp.EQ, SqlParam(True)),
            )
            live_session = sql_and(
                SqlBinaryOp(
                    column(UserSession, "sys_id"),
                    BinaryOp.EQ,
                    SqlParam(facts.session_id),
                ),
                SqlBinaryOp(
                    column(UserSession, "user_id"),
                    BinaryOp.EQ,
                    SqlParam(facts.app_user_id),
                ),
                SqlBinaryOp(
                    column(UserSession, "session_type"),
                    BinaryOp.EQ,
                    SqlParam("user"),
                ),
                SqlBinaryOp(
                    column(UserSession, "source"),
                    BinaryOp.EQ,
                    SqlParam("api"),
                ),
                SqlIsNull(column(UserSession, "parent_session_id")),
                SqlIsNull(column(UserSession, "effective_user_id")),
                SqlIsNull(column(UserSession, "closed_at")),
                sql_or(
                    SqlIsNull(column(UserSession, "expires_at")),
                    SqlBinaryOp(
                        column(UserSession, "expires_at"),
                        BinaryOp.GT,
                        SqlDialectCurrentTimestampComparison(),
                    ),
                ),
            )
            conditions.extend((exists(User, live_user), exists(UserSession, live_session)))
            if facts.identity_provider is not None and facts.subject_id is not None:
                live_binding = sql_and(
                    SqlBinaryOp(
                        column(AuthPrincipalBinding, "identity_provider"),
                        BinaryOp.EQ,
                        SqlParam(facts.identity_provider),
                    ),
                    SqlBinaryOp(
                        column(AuthPrincipalBinding, "subject_id"),
                        BinaryOp.EQ,
                        SqlParam(facts.subject_id),
                    ),
                    SqlBinaryOp(
                        column(AuthPrincipalBinding, "user_id"),
                        BinaryOp.EQ,
                        SqlParam(facts.app_user_id),
                    ),
                )
                conditions.append(exists(AuthPrincipalBinding, live_binding))
        if facts.expected_issuer_id is not None:
            conditions.append(
                SqlBinaryOp(
                    SqlParam(str(facts.issuer_id)),
                    BinaryOp.EQ,
                    SqlParam(str(facts.expected_issuer_id)),
                ),
            )
        if facts.expected_subject_id is not None:
            conditions.append(
                SqlBinaryOp(
                    SqlParam(str(facts.subject_id)),
                    BinaryOp.EQ,
                    SqlParam(str(facts.expected_subject_id)),
                ),
            )
        if facts.expected_session_source is not None:
            conditions.append(
                SqlBinaryOp(
                    SqlParam(facts.session_source),
                    BinaryOp.EQ,
                    SqlParam(facts.expected_session_source),
                ),
            )
        if facts.expected_auth_profile is not None:
            conditions.append(
                SqlBinaryOp(
                    SqlParam(facts.auth_profile),
                    BinaryOp.EQ,
                    SqlParam(facts.expected_auth_profile),
                ),
            )

        grammar = SqlSelect(
            select=SqlSelectList(
                [SqlSelectAlias(SqlParam(facts.session_id), SqlAliasName("session_id"))],
            ),
            where=SqlWhereClause(sql_and(*conditions)),
            limit=1,
        )
        output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(
            self.cte_publication_contract()
        )
        return CompiledStep(
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
            grammar=grammar,
            needs_returning=True,
            closed_post_op=scalar_column_post_op("session_id", use_default_on_empty=True),
        )


