class _InsertPrincipalExchangeRowStep(NonPublishingStep[None]):
    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        row: PrincipalProvisioningRow,
        after_refs: frozenset[ServerPlanRefId] = frozenset(),
        ignore_conflicts: bool = True,
    ) -> None:
        super().__init__(ref_id)
        self._row = row
        self._after_refs = after_refs
        self._ignore_conflicts = ignore_conflicts

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.NONE

    def is_read_only(self) -> bool:
        return False

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def step_tags(self) -> frozenset[str]:
        return frozenset({"write", "auth", "principal_provisioning"})

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        from l1000_schema.table_utils import get_table_name

        return frozenset({get_table_name(type(self._row))})

    def dependencies(self) -> frozenset[str]:
        return frozenset(str(ref_id) for ref_id in self._after_refs)

    def compile(self, ctx: CompilationContext) -> CompiledStep[None]:
        del ctx
        from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName
        from impl.common.l2100_sql_grammar.tree.clauses import (
            SqlColumnList,
            SqlValuesRow,
            SqlValuesSource,
        )
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlParam
        from impl.common.l2100_sql_grammar.tree.statements import SqlInsert
        from l1000_schema.schema_def import get_db_column_name
        from l1000_schema.table_utils import get_table_name

        row = self._row
        columns: tuple[str, ...]
        value_exprs: list[SqlParam]
        if isinstance(row, User):
            columns = (
                "sys_id",
                "type_name",
                "username",
                "email",
                "display_name",
                "active",
                "created_at",
                "updated_at",
            )
            value_exprs = [
                SqlParam(row.sys_id),
                SqlParam(row.type_name),
                SqlParam(row.username),
                SqlParam(row.email),
                SqlParam(row.display_name),
                SqlParam(row.active),
                SqlParam(row.created_at),
                SqlParam(row.updated_at),
            ]
        elif isinstance(row, UserSession):
            columns = (
                "sys_id",
                "created_at",
                "updated_at",
                "type_name",
                "session_type",
                "closed_at",
                "expires_at",
                "source",
                "parent_session_id",
                "user_id",
                "effective_user_id",
                "request_id",
                "description",
            )
            value_exprs = [
                SqlParam(row.sys_id),
                SqlParam(row.created_at),
                SqlParam(row.updated_at),
                SqlParam(row.type_name),
                SqlParam(row.session_type),
                SqlParam(row.closed_at),
                SqlParam(row.expires_at),
                SqlParam(row.source),
                SqlParam(row.parent_session_id),
                SqlParam(row.user_id),
                SqlParam(row.effective_user_id),
                SqlParam(row.request_id),
                SqlParam(row.description),
            ]
        elif isinstance(row, AuthPrincipalBinding):
            columns = ("sys_id", "identity_provider", "subject_id", "user_id", "created_at")
            value_exprs = [
                SqlParam(row.sys_id),
                SqlParam(row.identity_provider),
                SqlParam(row.subject_id),
                SqlParam(row.user_id),
                SqlParam(row.created_at),
            ]
