class ValidateProvisionedPrincipalStep(SqlRelationPublisherStep[bool]):
    """Require the persisted user/session rows to match one exchange identity."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        rows: PrincipalProvisioningRows,
        after_refs: frozenset[ServerPlanRefId],
    ) -> None:
        super().__init__(ref_id)
        self._rows = rows
        self._after_refs = after_refs

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self) -> bool:
        return True

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def step_tags(self) -> frozenset[str]:
        return frozenset({"auth", "principal_provisioning", "validation"})

    def tables_read(self) -> frozenset[str]:
        from l1000_schema.table_utils import get_table_name

        return frozenset(
            {
                get_table_name(User),
                get_table_name(UserSession),
                get_table_name(AuthPrincipalBinding),
            },
        )

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def dependencies(self) -> frozenset[str]:
        return frozenset(str(ref_id) for ref_id in self._after_refs)

    def requires_prior_statement_visibility_after_writes(self) -> frozenset[str]:
        return self.tables_read()

    def preprocess(self, resolved: ResolvedRefs) -> None:
        del resolved

    def cte_publication_contract(self) -> CtePublicationContract:
        from impl.common.l2070_server_plan.steps.sql_error_gate import (
            SqlAssertionResultRow,
            sql_assertion_column_type_hints,
            sql_assertion_output_shape,
        )

        output_shape = sql_assertion_output_shape()
        columns = output_shape.cte_output_columns
        assert columns is not None
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=tuple(str(column) for column in columns),
            column_type_hints=sql_assertion_column_type_hints(),
            model_cls=SqlAssertionResultRow,
            relation_role=self.cte_relation_role(),
            source_tables=self.tables_read(),
        )

    def compile(self, ctx: CompilationContext) -> CompiledStep[bool]:
        del ctx
        from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName, SqlTableName
        from impl.common.l2070_server_plan.steps.sql_error_gate import (
            rows_exist_assertion_query,
            sql_assertion_column_type_hints,
            sql_assertion_output_shape,
            sql_assertion_post_op,
        )
        from impl.common.l2100_sql_grammar.tree.clauses import (
            SqlDialectCurrentTimestampComparison,
            SqlSelectList,
            SqlWhereClause,
        )
        from impl.common.l2100_sql_grammar.tree.enums import BinaryOp
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlParam
        from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp, SqlExists, SqlIsNull, sql_and, sql_or
        from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
        from impl.common.l2100_sql_grammar.tree.statements import SqlSelect
        from l1000_schema.schema_def import get_db_column_name
        from l1000_schema.table_utils import get_table_name
        from l6520_auth.auth_types import PrincipalProvisioningError

        user = self._rows.user
        session = self._rows.session
        user_id_column = SqlColumnName(get_db_column_name(User, DynamicFieldName("sys_id")))
        active_column = SqlColumnName(get_db_column_name(User, DynamicFieldName("active")))
        session_id_column = SqlColumnName(get_db_column_name(UserSession, DynamicFieldName("sys_id")))
        session_user_column = SqlColumnName(get_db_column_name(UserSession, DynamicFieldName("user_id")))
        session_type_column = SqlColumnName(get_db_column_name(UserSession, DynamicFieldName("session_type")))
        session_source_column = SqlColumnName(get_db_column_name(UserSession, DynamicFieldName("source")))
        parent_session_column = SqlColumnName(
            get_db_column_name(UserSession, DynamicFieldName("parent_session_id")),
        )
        effective_user_column = SqlColumnName(
            get_db_column_name(UserSession, DynamicFieldName("effective_user_id")),
        )
        closed_column = SqlColumnName(get_db_column_name(UserSession, DynamicFieldName("closed_at")))
        expires_column = SqlColumnName(get_db_column_name(UserSession, DynamicFieldName("expires_at")))
        binding_provider_column = SqlColumnName(
            get_db_column_name(AuthPrincipalBinding, DynamicFieldName("identity_provider")),
        )
        binding_subject_column = SqlColumnName(
            get_db_column_name(AuthPrincipalBinding, DynamicFieldName("subject_id")),
        )
        binding_user_column = SqlColumnName(
            get_db_column_name(AuthPrincipalBinding, DynamicFieldName("user_id")),
        )

        user_exists = SqlExists(
            SqlSelect(
                select=SqlSelectList([SqlParam(1)]),
                from_=SqlTableIdent(SqlTableName(get_table_name(User))),
                where=SqlWhereClause(
                    sql_and(
                        SqlBinaryOp(SqlColumnRef(user_id_column), BinaryOp.EQ, SqlParam(user.sys_id)),
                        SqlBinaryOp(SqlColumnRef(active_column), BinaryOp.EQ, SqlParam(True)),
                    ),
                ),
                limit=1,
            ),
        )
        session_exists = SqlExists(
            SqlSelect(
                select=SqlSelectList([SqlParam(1)]),
                from_=SqlTableIdent(SqlTableName(get_table_name(UserSession))),
                where=SqlWhereClause(
                    sql_and(
                        SqlBinaryOp(SqlColumnRef(session_id_column), BinaryOp.EQ, SqlParam(session.sys_id)),
                        SqlBinaryOp(SqlColumnRef(session_user_column), BinaryOp.EQ, SqlParam(user.sys_id)),
                        SqlBinaryOp(SqlColumnRef(session_type_column), BinaryOp.EQ, SqlParam("user")),
                        SqlBinaryOp(
                            SqlColumnRef(session_source_column),
                            BinaryOp.EQ,
                            SqlParam(session.source),
                        ),
                        SqlIsNull(SqlColumnRef(parent_session_column)),
                        SqlIsNull(SqlColumnRef(effective_user_column)),
                        SqlIsNull(SqlColumnRef(closed_column)),
                        sql_or(
                            SqlIsNull(SqlColumnRef(expires_column)),
                            SqlBinaryOp(
                                SqlColumnRef(expires_column),
                                BinaryOp.GT,
                                SqlDialectCurrentTimestampComparison(),
                            ),
                        ),
                    ),
                ),
                limit=1,
            ),
        )
        binding_exists = SqlExists(
            SqlSelect(
                select=SqlSelectList([SqlParam(1)]),
                from_=SqlTableIdent(SqlTableName(get_table_name(AuthPrincipalBinding))),
                where=SqlWhereClause(
                    sql_and(
                        SqlBinaryOp(
                            SqlColumnRef(binding_provider_column),
                            BinaryOp.EQ,
                            SqlParam(self._rows.binding.identity_provider),
                        ),
                        SqlBinaryOp(
                            SqlColumnRef(binding_subject_column),
                            BinaryOp.EQ,
                            SqlParam(self._rows.binding.subject_id),
                        ),
                        SqlBinaryOp(
                            SqlColumnRef(binding_user_column),
                            BinaryOp.EQ,
                            SqlParam(user.sys_id),
                        ),
                    ),
                ),
                limit=1,
            ),
        )
        matching_rows = SqlSelect(
            select=SqlSelectList([SqlParam(1)]),
            where=SqlWhereClause(sql_and(user_exists, session_exists, binding_exists)),
        )
        message = "Persisted user, session, or external identity binding is missing, inactive, expired, or inconsistent"
        output_shape = sql_assertion_output_shape()
        return CompiledStep(
            grammar=rows_exist_assertion_query(matching_rows, error_message=message),
            needs_returning=True,
            closed_post_op=sql_assertion_post_op(message, exc_type=PrincipalProvisioningError),
            output_shape=output_shape,
            result_relation=DeclaredResultRelation.from_output_shape(output_shape),
            column_type_hints=sql_assertion_column_type_hints(),
        )


@pure_lazy
def build_principal_provisioning_steps(
    *,
    refs: tuple[
        ServerPlanRefId,
        ServerPlanRefId,
        ServerPlanRefId,
        ServerPlanRefId,
        ServerPlanRefId,
    ],
    rows: PrincipalProvisioningRows,
) -> tuple[
    NonPublishingStep[None],
    NonPublishingStep[None],
    NonPublishingStep[None],
    ValidateProvisionedPrincipalStep,
    NonPublishingStep[None],
]:
    """Build fixed-authority writes, validation, and success evidence."""
    user_ref, session_ref, binding_ref, validation_ref, event_ref = refs
    from impl.common.l2070_server_plan.steps._prepare_instance import (
        prepare_instance_for_insert_lazy,
    )

    prepared_user = prepare_instance_for_insert_lazy(User, rows.user)
    prepared_session = prepare_instance_for_insert_lazy(UserSession, rows.session)
    prepared_binding = prepare_instance_for_insert_lazy(AuthPrincipalBinding, rows.binding)
    prepared_event = prepare_instance_for_insert_lazy(
        AuthPrincipalSecurityEvent,
        AuthPrincipalSecurityEvent(
            event_type="auth.principal_exchange_succeeded",
            severity="info",
            user_id=str(rows.user.sys_id),
            occurred_at=rows.user.created_at,
            identity_provider=rows.binding.identity_provider,
            session_id=rows.session.sys_id,
            details={
                "identity_provider": rows.binding.identity_provider,
                "session_id": str(rows.session.sys_id),
            },
        ),
    )
    assert isinstance(prepared_user, User)
    assert isinstance(prepared_session, UserSession)
    assert isinstance(prepared_binding, AuthPrincipalBinding)
    assert isinstance(prepared_event, AuthPrincipalSecurityEvent)
    user = prepared_user
    session = prepared_session
    binding = prepared_binding
    event = prepared_event
    user_step = _InsertPrincipalExchangeRowStep(user_ref, row=user)
    binding_step = _InsertPrincipalExchangeRowStep(
        binding_ref,
        row=binding,
        after_refs=frozenset({user_ref}),
    )
    session_step = _InsertPrincipalExchangeRowStep(
        session_ref,
        row=session,
        after_refs=frozenset({user_ref}),
    )
    validation_step = ValidateProvisionedPrincipalStep(
        validation_ref,
        rows=rows,
        after_refs=frozenset({user_ref, binding_ref, session_ref}),
    )
    event_step = _InsertPrincipalExchangeRowStep(
        event_ref,
        row=event,
        after_refs=frozenset({validation_ref}),
        ignore_conflicts=False,
    )
    return user_step, binding_step, session_step, validation_step, event_step

