def _auxiliary_ctes_for_dependencies(
    ctx: CompilationContext,
    dependencies: frozenset[str],
) -> list[tuple[str, SqlRenderable]] | None:
    from l2070_batching.compilation import CteReference

    auxiliary_ctes: list[tuple[str, SqlRenderable]] = []
    seen: set[str] = set()
    for ref_id in sorted(dependencies):
        binding = ctx.cte_refs.get(ref_id)
        if not isinstance(binding, CteReference) or binding.auxiliary_query is None:
            continue
        if binding.ref_id in seen:
            continue
        seen.add(binding.ref_id)
        auxiliary_ctes.append((binding.ref_id, binding.auxiliary_query))
    return auxiliary_ctes or None


