@runtime_checkable
class NamedFieldRef(Protocol):
    """Structural field reference accepted by the public upsert API."""

    @property
    def name(self) -> str: ...


type UpsertFieldIdentifier = str | NamedFieldRef
type UpsertConflictValue = Expression[Any, DatabaseObjectRow] | NamedFieldRef


def select_large_column_conflict_storage[PhysicalValueT](
    model_cls: type[DatabaseObjectRow[SysId]],
    conflict_columns: Sequence[str] | None,
    *,
    physical_values: Mapping[str, PhysicalValueT] | None = None,
) -> list[str] | None:
    """Select the inline or pointer column that contains each candidate key."""
    if conflict_columns is None:
        return None
    pointer_by_content = {str(config.column): large_column_pointer_name(config.column) for config in get_large_column_configs(model_cls)}
    selected: list[str] = []
    for column in conflict_columns:
        pointer = pointer_by_content.get(column)
        if pointer is None or (physical_values is not None and physical_values.get(pointer) is None):
            selected.append(column)
        else:
            selected.append(pointer)
    return selected


def include_large_column_storage_conflicts(
    model_cls: type[DatabaseObjectRow[SysId]],
    conflict_columns: Sequence[str] | None,
) -> list[str] | None:
    """Include both members of each large-column storage pair in a match."""
    if conflict_columns is None:
        return None
    pointer_by_content = {str(config.column): large_column_pointer_name(config.column) for config in get_large_column_configs(model_cls)}
    expanded: list[str] = []
    for column in conflict_columns:
        expanded.append(column)
        pointer = pointer_by_content.get(column)
        if pointer is not None:
            expanded.append(pointer)
    return expanded


def _rewrite_expression_field(
    expression: Expression[Any, DatabaseObjectRow],
    *,
    source_field: str,
    target_field: str,
) -> Expression[Any, DatabaseObjectRow]:
    def _rewrite(value: Any) -> Any:
        if isinstance(value, Expression):
            return _rewrite_expression_field(
                value,
                source_field=source_field,
                target_field=target_field,
            )
        return value

    return Expression(
        field=target_field if expression.field == source_field else expression.field,
        operator=expression.operator,
        value=_rewrite(expression.value),
        left=None if expression.left is None else cast(Expression[Any, DatabaseObjectRow], _rewrite(expression.left)),
        right=None if expression.right is None else cast(Expression[Any, DatabaseObjectRow], _rewrite(expression.right)),
        logical_op=expression.logical_op,
        function=expression.function,
        args=tuple(_rewrite(arg) for arg in expression.args),
        owner=expression.owner,
        server_ref_dependencies=expression.server_ref_dependencies,
    )


def _is_literal(expression: Expression[Any, DatabaseObjectRow]) -> bool:
    return (
        expression.function is None
        and expression.field is None
        and expression.operator is None
        and expression.logical_op is None
        and expression.left is None
        and expression.right is None
        and not expression.args
    )


def _is_field_reference(expression: Expression[Any, DatabaseObjectRow], field_name: str) -> bool:
    return (
        expression.field == field_name
        and expression.function is None
        and expression.operator is None
        and expression.logical_op is None
        and expression.left is None
        and expression.right is None
        and not expression.args
    )


def _is_excluded_reference(expression: Expression[Any, DatabaseObjectRow], field_name: str) -> bool:
    return (
        expression.function == "EXCLUDED"
        and expression.operator is None
        and expression.logical_op is None
        and expression.left is None
        and expression.right is None
        and len(expression.args) == 1
        and isinstance(expression.args[0], Expression)
        and _is_field_reference(expression.args[0], field_name)
    )


def _assignment_error(
    model_cls: type[DatabaseObjectRow[SysId]],
    field_name: str,
    assignment: Expression[Any, DatabaseObjectRow],
) -> ValueError:
    shape = assignment.function or assignment.operator or "compound expression"
    return ValueError(
        f"Versioned upsert for {model_cls.__name__}.{field_name} cannot map {shape!r} "
        "to a large-column storage pair. Use the field itself, EXCLUDED(field), an inline literal, "
        "COALESCE, or IFNULL.",
    )


def include_large_column_pointer_updates(
    model_cls: type[DatabaseObjectRow[SysId]],
    on_conflict: Mapping[str, UpsertConflictValue] | None,
) -> dict[str, UpsertConflictValue] | None:
    """Map logical assignments according to ``VERSIONED_LARGE_COLUMN_UPSERTS.rst``."""
    if on_conflict is None:
        return None

    normalized = dict(on_conflict)
    for config in get_large_column_configs(model_cls):
        if config.column not in normalized:
            continue
        assignment = normalized[config.column]
        if isinstance(assignment, NamedFieldRef) and assignment.name == config.column:
            continue
        pointer_name = large_column_pointer_name(config.column)
        if isinstance(assignment, Expression):
            is_literal = _is_literal(assignment)
            is_excluded = _is_excluded_reference(assignment, config.column)
            has_valid_fallback_arity = (assignment.function == "COALESCE" and len(assignment.args) >= 2) or (
                assignment.function == "IFNULL" and len(assignment.args) == 2
            )
            is_candidate_first_fallback = (
                has_valid_fallback_arity
                and isinstance(assignment.args[0], Expression)
                and _is_excluded_reference(assignment.args[0], config.column)
                and isinstance(assignment.args[1], Expression)
                and (_is_field_reference(assignment.args[1], config.column) or _is_literal(assignment.args[1]))
                and all(isinstance(arg, Expression) and _is_literal(arg) for arg in assignment.args[2:])
            )
            is_existing_first_fallback = (
                has_valid_fallback_arity
                and len(assignment.args) == 2
                and isinstance(assignment.args[0], Expression)
                and _is_field_reference(assignment.args[0], config.column)
                and isinstance(assignment.args[1], Expression)
                and _is_excluded_reference(assignment.args[1], config.column)
            )
            if not (is_literal or is_excluded or is_candidate_first_fallback or is_existing_first_fallback):
                raise _assignment_error(model_cls, str(config.column), assignment)
            literal_expressions = (
                (assignment,)
                if is_literal
                else tuple(arg for arg in assignment.args[1:] if isinstance(arg, Expression) and _is_literal(arg))
            )
            for literal_expression in literal_expressions:
                literal_value = literal_expression.value
                if literal_value is None:
                    continue
                encoded, _is_binary = encode_large_column_value(literal_value, config.content_type)
                if len(encoded) >= config.spill_threshold_bytes:
                    raise ValueError(
                        f"Versioned upsert for {model_cls.__name__}.{config.column} cannot use a conflict literal "
                        f"of {len(encoded)} bytes. The spill threshold is {config.spill_threshold_bytes} bytes. "
                        "Use EXCLUDED(field) so the ServerPlan can schedule the content-store write.",
                    )
        if (
            isinstance(assignment, Expression)
            and (
                (assignment.function == "COALESCE" and len(assignment.args) >= 2)
                or (assignment.function == "IFNULL" and len(assignment.args) == 2)
            )
            and isinstance(assignment.args[0], Expression)
            and assignment.args[0].field == config.column
            and isinstance(assignment.args[1], Expression)
            and assignment.args[1].function == "EXCLUDED"
        ):
            normalized[config.column] = CASE(
                WHEN(field(pointer_name).is_not_null(), None),
                ELSE=assignment,
            )
        pointer_assignment: UpsertConflictValue
        if isinstance(assignment, Expression):
            if _is_literal(assignment):
                pointer_assignment = Expression(value=None)
            else:
                pointer_assignment = _rewrite_expression_field(
                    assignment,
                    source_field=str(config.column),
                    target_field=pointer_name,
                )
            args = assignment.args
            if (
                ((assignment.function == "COALESCE" and len(args) >= 2) or (assignment.function == "IFNULL" and len(args) == 2))
                and isinstance(args[0], Expression)
                and args[0].function == "EXCLUDED"
                and isinstance(args[1], Expression)
            ):
                excluded_content = args[0]
                excluded_pointer = _rewrite_expression_field(
                    excluded_content,
                    source_field=str(config.column),
                    target_field=pointer_name,
                )
                existing_pointer = (
                    _rewrite_expression_field(
                        args[1],
                        source_field=str(config.column),
                        target_field=pointer_name,
                    )
                    if args[1].field == config.column
                    else Expression(value=None)
                )
                pointer_assignment = CASE(
                    WHEN(excluded_content.is_not_null(), excluded_pointer),
                    WHEN(excluded_pointer.is_not_null(), excluded_pointer),
                    ELSE=existing_pointer,
                )
        else:
            pointer_assignment = Expression(value=None)
        normalized.setdefault(pointer_name, pointer_assignment)
    return normalized

