def create_admit_session_context_steps(
    ref_id: ServerPlanRefId,
    session_source: SessionId | ScalarServerRef[SessionId] | LazySessionSqlSource,
    *,
    validation_ref: ServerPlanRefId | None = None,
) -> AdmitSessionContextPlan:
    """Choose concrete admission steps at the lazy boundary."""
    if isinstance(session_source, SessionId) and (session_source.is_schema_session()):
        return AdmitSessionContextPlan(
            prerequisites=(),
            result_step=ProjectAdmittedSessionContextStep(
                ref_id,
                session_source,
                validation_ref=None,
            ),
        )
    if isinstance(session_source, ScalarServerRef):
        if validation_ref is None:
            raise TypeError("Deferred session context requires its authenticated validation ref")
        return AdmitSessionContextPlan(
            prerequisites=(),
            result_step=ProjectAdmittedSessionContextStep(
                ref_id,
                session_source,
                validation_ref=validation_ref,
            ),
        )
    validation_ref = ServerPlanRefId(f"{ref_id}.validation")
    return AdmitSessionContextPlan(
        prerequisites=(SessionValidationStep(validation_ref, session_id=session_source),),
        result_step=ProjectAdmittedSessionContextStep(
            ref_id,
            session_source,
            validation_ref=validation_ref,
        ),
    )


class ProjectAdmittedSessionContextStep(SqlRelationPublisherStep[ResolvedSessionContext]):
    """Publish canonical context columns from a validated session relation."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        session_id: SessionId | ScalarServerRef[SessionId] | LazySessionSqlSource,
        *,
        validation_ref: ServerPlanRefId | None,
    ) -> None:
        super().__init__(ref_id)
        self._session_id = session_id
        self._validation_ref = validation_ref

    @property
    def level(self: ProjectAdmittedSessionContextStep) -> int:
        return 0

    def result_cardinality(self: ProjectAdmittedSessionContextStep) -> Cardinality:
        return Cardinality.ONE

    def reading_the_validated_row(
        self: ProjectAdmittedSessionContextStep,
        session_validation_ref: ServerPlanRefId,
    ) -> ProjectAdmittedSessionContextStep:
        """Return this projection bound to the optimizer-selected validation row."""
        return ProjectAdmittedSessionContextStep(
            self.ref_id,
            self._session_id,
            validation_ref=session_validation_ref,
        )

    def is_read_only(self: ProjectAdmittedSessionContextStep) -> bool:
        return True

    def execution_role(self: ProjectAdmittedSessionContextStep) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def step_tags(self: ProjectAdmittedSessionContextStep) -> frozenset[str]:
        return frozenset({"read", "session_context", "admission", "sql_visible"})

    def dependencies(self: ProjectAdmittedSessionContextStep) -> frozenset[str]:
        if self._validation_ref is None:
            return frozenset()
        return frozenset({str(self._validation_ref)})

    def dependency_contract(self: ProjectAdmittedSessionContextStep) -> StepDependencyContract:
        if self._validation_ref is None:
            return StepDependencyContract.none(reason="built-in privileged session context")
        return StepDependencyContract.from_refs(
            self.dependencies(),
            source=DependencySource.DIRECT_FIELD,
            required_for=frozenset(
                {
                    DependencyUse.AUTH_SCOPE,
                    DependencyUse.ORDERING,
                    DependencyUse.SQL_VISIBLE,
                    DependencyUse.TRANSPORT_GRAPH,
                }
            ),
            transport=TransportDependencyPolicy.TRANSPORTABLE,
            reason="validated-session authority for admitted context",
        )

    def tables_read(self: ProjectAdmittedSessionContextStep) -> frozenset[str]:
        return frozenset()

    def tables_written(self: ProjectAdmittedSessionContextStep) -> frozenset[str]:
        return frozenset()

    def expected_result_type(self: ProjectAdmittedSessionContextStep) -> type[ResolvedSessionContext]:
        return ResolvedSessionContext

    @pure_lazy
    def cte_publication_contract(self: ProjectAdmittedSessionContextStep) -> CtePublicationContract:
        columns = tuple(ResolvedSessionContext.model_fields)
        type_hints = model_sql_column_type_hints(ResolvedSessionContext, columns)
        if type_hints is None:
            msg = "Could not resolve SQL type hints for ResolvedSessionContext"
            raise TypeError(msg)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=columns,
            column_type_hints=type_hints,
            model_cls=ResolvedSessionContext,
            relation_role="admitted_session_context",
            source_tables=frozenset({"sys_sessions"}) if self._validation_ref is not None else None,
        )

    def compile(
        self: ProjectAdmittedSessionContextStep,
        ctx: CompilationContext,
    ) -> CompiledStep[ResolvedSessionContext]:
        auxiliary_ctes: list[tuple[str, SqlRenderable]] | None = None
        if self._validation_ref is None:
            assert isinstance(self._session_id, SessionId)
            is_reserved = self._session_id.is_schema_session()
            select_items: list[SqlRenderable] = [
                SqlSelectAlias(SqlParam(self._session_id.unwrap_to_sql()), SqlAliasName("session_id")),
                SqlSelectAlias(SQL_EXPR_NULL, SqlAliasName("user_id")),
                SqlSelectAlias(SQL_EXPR_NULL, SqlAliasName("effective_user_id")),
                SqlSelectAlias(SqlParam("system" if is_reserved else "user"), SqlAliasName("session_type")),
                SqlSelectAlias(SqlParam(is_reserved), SqlAliasName("is_system_session")),
            ]
            grammar = SqlSelect(select=select_items)
        else:
            validation_cte = _require_sql_visible_source_cte(
                ctx,
                self._validation_ref,
                site_name=type(self).__name__,
                result_contract="project one admitted-session context row",
            )
            if validation_cte.auxiliary_query is not None:
                auxiliary_ctes = [
                    (validation_cte.ref_id, validation_cte.auxiliary_query),
                ]
            validated: ObjectServerRef[ValidatedSessionState | None] = ServerRefs.from_ref_id(
                self._validation_ref,
                variant="object",
            )
            session_id = lower_scalar_server_ref(validated.field("sys_id"), ctx)
            user_id = lower_scalar_server_ref(validated.field("user_id"), ctx)
            effective_user_id = lower_scalar_server_ref(
                validated.field("effective_user_id"),
                ctx,
            )
            observed_session_type = lower_scalar_server_ref(
                validated.field("session_type"),
                ctx,
            )
            reserved_session = SqlBinaryOp(
                session_id,
                BinaryOp.EQ,
                SqlParam(SessionId.schema().unwrap_to_sql()),
            )
            effective_session_type = SqlCase(
                [
                    (SqlIsNull(observed_session_type), SQL_EXPR_NULL),
                    (reserved_session, SqlParam("system")),
                ],
                else_=SqlParam("user"),
            )
            grammar = SqlSelect(
                select=(
                    SqlSelectAlias(session_id, SqlAliasName("session_id")),
                    SqlSelectAlias(user_id, SqlAliasName("user_id")),
                    SqlSelectAlias(effective_user_id, SqlAliasName("effective_user_id")),
                    SqlSelectAlias(effective_session_type, SqlAliasName("session_type")),
                    SqlSelectAlias(reserved_session, SqlAliasName("is_system_session")),
                ),
            )
        contract = self.cte_publication_contract()
        output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(contract)
        return CompiledStep(
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
            grammar=(SqlStatementLocalWith(auxiliary_ctes, grammar, recursive=True) if auxiliary_ctes else grammar),
            needs_returning=True,
            auxiliary_ctes=None,
            closed_post_op=exact_single_row_post_op(),
        )


type _ProjectedContextBinding = tuple[
    DynamicFieldName,
    ScalarServerRef[Any],
    DynamicFieldName | None,
]


@dataclass(frozen=True, slots=True)
class _ProjectSessionContextConfig[ContextT: ResolvedSessionContext]:
    context_type: type[ContextT]
    admitted_context: ObjectServerRef[ResolvedSessionContext]
    bindings: tuple[_ProjectedContextBinding, ...]


def _projected_binding_dependency_refs(
    bindings: tuple[_ProjectedContextBinding, ...],
) -> frozenset[ServerPlanRefId]:
    return frozenset(ref for _field_name, source, _admitted_field_name in bindings for ref in source.dependencies())


def _admitted_source_field_name(
    admitted_context: ObjectServerRef[ResolvedSessionContext],
    source: ScalarServerRef[Any],
) -> DynamicFieldName | None:
    admitted_ref_id = admitted_context.ref_id
    source_ref_id = source.ref_id
    if admitted_ref_id is None or source_ref_id is None:
        return None
    prefix = f"{admitted_ref_id}."
    if not source_ref_id.startswith(prefix):
        return None
    field_name = source_ref_id[len(prefix) :]
    if field_name not in ResolvedSessionContext.model_fields:
        return None
    return DynamicFieldName(field_name)


def create_project_session_context_step[ContextT: ResolvedSessionContext](
    ref_id: ServerPlanRefId,
    context_type: type[ContextT],
    *,
    admitted_context: ObjectServerRef[ResolvedSessionContext],
    bindings: tuple[SessionContextFieldBinding[Any, Any], ...],
) -> ProjectSessionContextIntent[ContextT]:
    """Create one typed-context projection intent at the lazy boundary."""
    binding_by_name = {binding.field.name: binding.source for binding in bindings}
    return ProjectSessionContextIntent[ContextT](
        ref_id,
        context_type,
        admitted_context,
        *(
            binding_by_name[DynamicFieldName(field_name)]
            for field_name in context_type.model_fields
            if field_name not in ResolvedSessionContext.model_fields and DynamicFieldName(field_name) in binding_by_name
        ),
    )


class ProjectSessionContextIntent[ContextT: ResolvedSessionContext](IntentStep[ContextT]):
    """Project canonical facts and application fields as one SQL relation."""

    intent_tags = frozenset({"read", "session_context", "projection", "intent"})
    intent_cardinality = Cardinality.ONE
    intent_read_only = True

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        context_type: type[ContextT],
        admitted_context: ObjectServerRef[ResolvedSessionContext],
        *binding_sources: ScalarServerRef[Any],
    ) -> None:
        super().__init__(ref_id)
        binding_fields = tuple(
            DynamicFieldName(field_name)
            for field_name in context_type.model_fields
            if field_name not in ResolvedSessionContext.model_fields
        )
        if binding_sources and len(binding_fields) != len(binding_sources):
            msg = "Session-context binding fields and sources must have equal length"
            raise ValueError(msg)
        self._context_type = context_type
        self._admitted_context = admitted_context
        self._binding_fields = binding_fields
        self._binding_sources = binding_sources

    def dependencies(self: ProjectSessionContextIntent[ContextT]) -> frozenset[str]:
        return frozenset(
            {
                *self._admitted_context.dependencies(),
                *(ref for source in self._binding_sources for ref in source.dependencies()),
            }
        )

    def expected_result_type(self: ProjectSessionContextIntent[ContextT]) -> type[ContextT]:
        return self._context_type

    def lower(
        self: ProjectSessionContextIntent[ContextT],
        ctx: LoweringContext,
    ) -> Sequence[ServerPlanStep[Any]]:
        del ctx
        projected_ref = ServerPlanRefId(f"{self.ref_id}.projected")
        assertion_ref = ServerPlanRefId(f"{self.ref_id}.required_fields")
        return (
            ProjectSessionContextStep[ContextT](
                projected_ref,
                _ProjectSessionContextConfig[ContextT](
                    context_type=self._context_type,
                    admitted_context=self._admitted_context,
                    bindings=tuple(
                        (
                            field_name,
                            source,
                            _admitted_source_field_name(self._admitted_context, source),
                        )
                        for field_name, source in zip(
                            self._binding_fields,
                            self._binding_sources,
                        )
                    ),
                ),
            ),
            SessionContextRequiredFieldsAssertionStep(
                assertion_ref,
                source_ref=projected_ref,
                required_fields=_required_session_context_fields(self._context_type),
            ),
            ValidatedSessionContextProjectionStep[ContextT](
                self.ref_id,
                context_type=self._context_type,
                source_ref=projected_ref,
                assertion_ref=assertion_ref,
            ),
        )


def _required_session_context_fields(
    context_type: type[ResolvedSessionContext],
) -> tuple[str, ...]:
    canonical_fields = frozenset(ResolvedSessionContext.model_fields)
    return tuple(
        field_name
        for field_name, field_info in context_type.model_fields.items()
        if field_name not in canonical_fields and not unwrap_optional(field_info.annotation)[1]
    )


class SessionContextRequiredFieldsAssertionStep(SqlRelationPublisherStep[None]):
    """Assert session-context cardinality and required values in SQL."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        source_ref: ServerPlanRefId,
        required_fields: tuple[str, ...],
    ) -> None:
        super().__init__(ref_id)
        self._source_ref = source_ref
        self._required_fields = required_fields

    @property
    def level(self: SessionContextRequiredFieldsAssertionStep) -> int:
        return 0

    def result_cardinality(self: SessionContextRequiredFieldsAssertionStep) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self: SessionContextRequiredFieldsAssertionStep) -> bool:
        return True

    def execution_role(self: SessionContextRequiredFieldsAssertionStep) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def supports_sql_batch_transport(self: SessionContextRequiredFieldsAssertionStep) -> bool:
        return True

    def dependencies(self: SessionContextRequiredFieldsAssertionStep) -> frozenset[str]:
        return frozenset({str(self._source_ref)})

    def imported_dependency_refs(
        self: SessionContextRequiredFieldsAssertionStep,
    ) -> frozenset[ServerPlanRefId]:
        return frozenset({self._source_ref})

    def consumes_executor_visible_dependencies(
        self: SessionContextRequiredFieldsAssertionStep,
    ) -> bool:
        return True

    def tables_read(self: SessionContextRequiredFieldsAssertionStep) -> frozenset[str]:
        return frozenset()

    def tables_written(self: SessionContextRequiredFieldsAssertionStep) -> frozenset[str]:
        return frozenset()

    def cte_publication_contract(
        self: SessionContextRequiredFieldsAssertionStep,
    ) -> CtePublicationContract:
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=("ok", "error_code", "message"),
            column_type_hints=sql_assertion_column_type_hints(),
            relation_contract=CteRelationContract.semantic_row(SqlAssertionResultRow),
            relation_role=self.cte_relation_role(),
        )

    def compile(
        self: SessionContextRequiredFieldsAssertionStep,
        ctx: CompilationContext,
    ) -> CompiledStep[None]:
        source = _require_sql_visible_source_cte(
            ctx,
            self._source_ref,
            site_name=type(self).__name__,
            result_contract="validate one typed session-context row",
        )
        source_table = SqlTableName(source.ref_id)
        total_count = SqlSubquery(
            SqlSelect(
                select=SqlAggregate(AggregateKind.COUNT_STAR),
                from_=source_table,
            )
        )
        valid_count: SqlRenderable = total_count
        if self._required_fields:
            valid_count = SqlSubquery(
                SqlSelect(
                    select=SqlAggregate(AggregateKind.COUNT_STAR),
                    from_=source_table,
                    where=sql_and(
                        *(
                            SqlIsNull(
                                SqlColumnRef(SqlColumnName(field_name)),
                                negated=True,
                            )
                            for field_name in self._required_fields
                        )
                    ),
                )
            )
        deferred_count = SqlSubquery(
            SqlSelect(
                select=SqlAggregate(AggregateKind.COUNT_STAR),
                from_=source_table,
                where=SqlIsNull(SqlColumnRef(SqlColumnName("session_type"))),
            )
        )
        predicate = sql_or(
            SqlBinaryOp(total_count, BinaryOp.EQ, SqlInlineLiteral(0)),
            sql_and(
                SqlBinaryOp(total_count, BinaryOp.EQ, SqlInlineLiteral(1)),
                sql_or(
                    SqlBinaryOp(deferred_count, BinaryOp.EQ, SqlInlineLiteral(1)),
                    SqlBinaryOp(valid_count, BinaryOp.EQ, SqlInlineLiteral(1)),
                ),
            ),
        )
        if self._required_fields:
            required_names = ", ".join(self._required_fields)
            message = f"Session context required field is unavailable: {required_names}"
        else:
            message = "Session context resolution did not produce exactly one row."
        output_shape = sql_assertion_output_shape()
        return CompiledStep(
            grammar=true_expression_assertion_query(
                predicate,
                error_message=message,
            ),
            needs_returning=True,
            auxiliary_ctes=([(source.ref_id, source.auxiliary_query)] if source.auxiliary_query is not None else None),
            closed_post_op=sql_assertion_post_op(message, exc_type=SecurityError),
            output_shape=output_shape,
            result_relation=DeclaredResultRelation.from_output_shape(output_shape),
            column_type_hints=sql_assertion_column_type_hints(),
        )


class ValidatedSessionContextProjectionStep[ContextT: ResolvedSessionContext](SqlRelationPublisherStep[ContextT]):
    """Publish a context row only after its SQL-owned assertion."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        context_type: type[ContextT],
        source_ref: ServerPlanRefId,
        assertion_ref: ServerPlanRefId,
    ) -> None:
        super().__init__(ref_id)
        self._context_type = context_type
        self._source_ref = source_ref
        self._assertion_ref = assertion_ref

    @property
    def level(self: ValidatedSessionContextProjectionStep[ContextT]) -> int:
        return 0

    def result_cardinality(self: ValidatedSessionContextProjectionStep[ContextT]) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self: ValidatedSessionContextProjectionStep[ContextT]) -> bool:
        return True

    def execution_role(self: ValidatedSessionContextProjectionStep[ContextT]) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def supports_sql_batch_transport(
        self: ValidatedSessionContextProjectionStep[ContextT],
    ) -> bool:
        return True

    def dependencies(
        self: ValidatedSessionContextProjectionStep[ContextT],
    ) -> frozenset[str]:
        return frozenset({str(self._source_ref), str(self._assertion_ref)})

    def imported_dependency_refs(
        self: ValidatedSessionContextProjectionStep[ContextT],
    ) -> frozenset[ServerPlanRefId]:
        return frozenset({self._source_ref})

    def consumes_executor_visible_dependencies(
        self: ValidatedSessionContextProjectionStep[ContextT],
    ) -> bool:
        return True

    def tables_read(self: ValidatedSessionContextProjectionStep[ContextT]) -> frozenset[str]:
        return frozenset()

    def tables_written(self: ValidatedSessionContextProjectionStep[ContextT]) -> frozenset[str]:
        return frozenset()

    @pure_lazy
    def cte_publication_contract(
        self: ValidatedSessionContextProjectionStep[ContextT],
    ) -> CtePublicationContract:
        columns = tuple(self._context_type.model_fields)
        type_hints = model_sql_column_type_hints(self._context_type, columns)
        if type_hints is None:
            msg = f"Cannot resolve SQL type hints for session context {self._context_type.__name__}"
            raise PermissionCompilationError(msg)
        type_hints.require_complete(columns)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=columns,
            column_type_hints=type_hints,
            model_cls=self._context_type,
            relation_role=self.cte_relation_role(),
        )

    def compile(
        self: ValidatedSessionContextProjectionStep[ContextT],
        ctx: CompilationContext,
    ) -> CompiledStep[ContextT]:
        source = _require_sql_visible_source_cte(
            ctx,
            self._source_ref,
            site_name=type(self).__name__,
            result_contract="publish one validated typed session-context row",
        )
        contract = self.cte_publication_contract()
        grammar = SqlSelect(
            select=tuple(SqlColumnRef(SqlColumnName(column)) for column in contract.columns),
            from_=SqlTableName(source.ref_id),
        )
        auxiliary_ctes = [(source.ref_id, source.auxiliary_query)] if source.auxiliary_query is not None else []
        output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(contract)
        closed_grammar: SqlRenderable = SqlStatementLocalWith(auxiliary_ctes, grammar, recursive=True) if auxiliary_ctes else grammar
        return CompiledStep(
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
            grammar=closed_grammar,
            needs_returning=True,
            closed_post_op=exact_single_row_post_op(),
            compiled_sql_publication=compiled_sql_publication_from_query(
                ref_id=self.ref_id,
                query=closed_grammar,
                contract=contract,
            ),
        )


class ProjectSessionContextStep[ContextT: ResolvedSessionContext](SqlRelationPublisherStep[ContextT]):
    """Publish one SQL-native typed context row from symbolic plan sources."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        config: _ProjectSessionContextConfig[ContextT],
    ) -> None:
        super().__init__(ref_id)
        self._context_type = config.context_type
        self._admitted_context = config.admitted_context
        if config.admitted_context.ref_id is None:
            msg = "Typed session-context projection requires a published admitted-context ref"
            raise PermissionCompilationError(msg)
        self._admitted_ref_id = config.admitted_context.ref_id
        self._bindings = config.bindings

    @property
    def level(self: ProjectSessionContextStep[ContextT]) -> int:
        return 0

    def result_cardinality(self: ProjectSessionContextStep[ContextT]) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self: ProjectSessionContextStep[ContextT]) -> bool:
        return True

    def requires_materialized_inputs(self: ProjectSessionContextStep[ContextT]) -> bool:
        return True

    def requires_prior_step_boundary(self: ProjectSessionContextStep[ContextT]) -> bool:
        return True

    def execution_role(self: ProjectSessionContextStep[ContextT]) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def step_tags(self: ProjectSessionContextStep[ContextT]) -> frozenset[str]:
        return frozenset({"read", "session_context", "projection", "sql_visible"})

    def dependencies(self: ProjectSessionContextStep[ContextT]) -> frozenset[str]:
        return frozenset(
            {
                *self._admitted_context.dependencies(),
                *_projected_binding_dependency_refs(self._bindings),
            }
        )

    def imported_dependency_refs(
        self: ProjectSessionContextStep[ContextT],
    ) -> frozenset[ServerPlanRefId]:
        return frozenset(ServerPlanRefId(ref) for ref in self.dependencies())

    def consumes_executor_visible_dependencies(
        self: ProjectSessionContextStep[ContextT],
    ) -> bool:
        return True

    def dependency_contract(self: ProjectSessionContextStep[ContextT]) -> StepDependencyContract:
        return StepDependencyContract.from_refs(
            self.dependencies(),
            source=DependencySource.DIRECT_FIELD,
            required_for=frozenset(
                {
                    DependencyUse.ORDERING,
                    DependencyUse.TRANSPORT_GRAPH,
                    DependencyUse.SQL_VISIBLE,
                }
            ),
            transport=TransportDependencyPolicy.TRANSPORTABLE,
            reason="typed session-context SQL projection sources",
        )

    def tables_read(self: ProjectSessionContextStep[ContextT]) -> frozenset[str]:
        return frozenset()

    def tables_written(self: ProjectSessionContextStep[ContextT]) -> frozenset[str]:
        return frozenset()

    def expected_result_type(self: ProjectSessionContextStep[ContextT]) -> type[ContextT]:
        return self._context_type

    @pure_lazy
    def cte_publication_contract(self: ProjectSessionContextStep[ContextT]) -> CtePublicationContract:
        columns = tuple(self._context_type.model_fields)
        type_hints = model_sql_column_type_hints(self._context_type, columns)
        if type_hints is None:
            msg = f"Cannot resolve SQL type hints for session context {self._context_type.__name__}"
            raise PermissionCompilationError(msg)
        try:
            type_hints.require_complete(columns)
        except ValueError as exc:
            msg = f"Session context {self._context_type.__name__} has incomplete SQL type hints: {exc}"
            raise PermissionCompilationError(msg) from exc
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=columns,
            column_type_hints=type_hints,
            model_cls=self._context_type,
            relation_role=self.cte_relation_role(),
        )

    def compile(self: ProjectSessionContextStep[ContextT], ctx: CompilationContext) -> CompiledStep[ContextT]:
        admitted_cte = _require_sql_visible_source_cte(
            ctx,
            self._admitted_ref_id,
            site_name=type(self).__name__,
            result_contract="project one typed admitted-session context row",
        )

        contract = self.cte_publication_contract()
        canonical_names = frozenset(ResolvedSessionContext.model_fields)
        binding_by_name = {field_name: (source, admitted_field_name) for field_name, source, admitted_field_name in self._bindings}
        application_names = set(self._context_type.model_fields) - canonical_names
        missing_names = application_names - binding_by_name.keys()
        if missing_names:
            missing = ", ".join(sorted(missing_names))
            msg = f"Typed session-context projection is missing declared field bindings: {missing}"
            raise PermissionCompilationError(msg)
        select_items: list[SqlRenderable] = []
        auxiliary_ctes: list[tuple[str, SqlRenderable]] = []
        if admitted_cte.auxiliary_query is not None:
            auxiliary_ctes.append((admitted_cte.ref_id, admitted_cte.auxiliary_query))
        for field_name in self._context_type.model_fields:
            expression: SqlRenderable
            if field_name in canonical_names:
                expression = SqlColumnRef(SqlColumnName(field_name))
            else:
                source, admitted_field_name = binding_by_name[DynamicFieldName(field_name)]
                if admitted_field_name is not None:
                    expression = SqlColumnRef(SqlColumnName(admitted_field_name))
                else:
                    scalar_binding = get_scalar_server_ref_binding(source, ctx)
                    expression = lower_scalar_server_ref(source, ctx)
                    if scalar_binding is not None and ctx.cte_refs is not None:
                        source_cte = ctx.cte_refs.get(str(scalar_binding.cte_name))
                        if isinstance(source_cte, CteReference) and source_cte.auxiliary_query is not None:
                            auxiliary_ctes.append((source_cte.ref_id, source_cte.auxiliary_query))
            cast_target = contract.column_type_hints.cast_target_for_column(field_name)
            if cast_target is not None:
                expression = SqlCast(expression, cast_target)
            select_items.append(SqlSelectAlias(expression, SqlAliasName(field_name)))

        grammar = SqlSelect(
            select=select_items,
            from_=SqlTableName(admitted_cte.ref_id),
        )
        output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(contract)
        return CompiledStep(
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
            grammar=(SqlStatementLocalWith(auxiliary_ctes, grammar, recursive=True) if auxiliary_ctes else grammar),
            needs_returning=True,
            auxiliary_ctes=None,
            closed_post_op=exact_single_row_post_op(),
        )

