def materialize_auth_tracked_token_validation(
    config_value: object,
    raw_result: RawResult,
    hydrator: Hydrator[Any] | None = None,
) -> AuthWorkflowClaims | AuthChallengeClaims:
    """Apply the closed tracked-token policy to final SQL validation facts."""
    if not isinstance(config_value, _ValidateAuthTrackedTokenTerminalConfig):
        msg = f"Tracked-token validation requires _ValidateAuthTrackedTokenTerminalConfig, got {type(config_value).__name__}."
        raise TypeError(msg)
    config = config_value
    from l2070_batching.hydrator import RuntimeHydrator
    from l6500_evidence.capability_tracking import (
        CapabilityTokenExpiredError,
        CapabilityTokenPermissionDeniedError,
        CapabilityTokenRevokedError,
        CapabilityTokenValidationError,
    )

    if config.token_validation_error is not None:
        raise CapabilityTokenValidationError(config.token_validation_error)
    if isinstance(hydrator, RuntimeHydrator):
        services = hydrator.runtime_services
        runtime = services.renewable_capability if services is not None else None
        if runtime is None:
            raise RuntimeError("Renewable capability runtime is required to validate tracked auth tokens")
        verified_claims = runtime.capability.verify_token(config.token)
        if verified_claims != config.claims:
            raise RuntimeError("Tracked auth claims changed between planning and execution")
    if config.claims.is_expired():
        raise CapabilityTokenExpiredError("Capability token has expired")
    if config.required_audience is not None and config.claims.audience != config.required_audience:
        raise CapabilityTokenPermissionDeniedError(
            required=f"audience {config.required_audience}",
            granted=f"audience {config.claims.audience or 'none'}",
        )
    row = dict(raw_result[0]) if raw_result else {}
    issued_exists = bool(row.get("issued_exists"))
    usage_limit_exceeded = bool(row.get("usage_limit_exceeded"))
    revocation_exists = bool(row.get("revocation_exists"))
    if not issued_exists:
        raise CapabilityTokenValidationError("Unknown token")
    if usage_limit_exceeded:
        raise CapabilityTokenValidationError("Token usage limit exceeded")
    if revocation_exists:
        raise CapabilityTokenRevokedError(config.claims.token_id)
    return _parse_tracked_claims(config)


def _auth_tracked_token_validation_stmt(
    config: _ValidateAuthTrackedTokenTerminalConfig,
) -> Any:
    from l1000_schema.table_utils import get_table_name
    from impl.common.l2050_sql_types.sql_branded_types import SqlAliasName, SqlColumnName, SqlTableName
    from impl.common.l2100_sql_grammar.domain.infra.stmt_cte_helpers import SqlSelectExpressions
    from impl.common.l2100_sql_grammar.tree.clauses import SqlSelectList, SqlWhereClause
    from impl.common.l2100_sql_grammar.tree.enums import BinaryOp
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlParam
    from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp, SqlExists, sql_and
    from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
    from impl.common.l2100_sql_grammar.tree.statements import SqlSelect

    issued_table = SqlTableIdent(get_table_name(CapabilityTokenIssued))
    revocation_table = SqlTableIdent(get_table_name(CapabilityTokenRevocation))
    token_id = config.claims.token_id

    issued_exists = SqlExists(
        SqlSelect(
            select=SqlSelectList([SqlParam(1)]),
            from_=issued_table,
            where=SqlWhereClause(
                SqlBinaryOp(SqlColumnRef(SqlColumnName("sys_id")), BinaryOp.EQ, SqlParam(token_id)),
            ),
            limit=1,
        ),
    )
    revocation_exists = SqlExists(
        SqlSelect(
            select=SqlSelectList([SqlParam(1)]),
            from_=revocation_table,
            where=SqlWhereClause(
                SqlBinaryOp(SqlColumnRef(SqlColumnName("token_id")), BinaryOp.EQ, SqlParam(token_id)),
            ),
            limit=1,
        ),
    )
    if config.check_usage and config.claims.max_uses is not None:
        usage_limit_exceeded: Any = SqlExists(
            SqlSelect(
                select=SqlSelectList([SqlParam(1)]),
                from_=issued_table,
                where=SqlWhereClause(
                    sql_and(
                        SqlBinaryOp(
                            SqlColumnRef(SqlColumnName("sys_id")),
                            BinaryOp.EQ,
                            SqlParam(token_id),
                        ),
                        SqlBinaryOp(
                            SqlColumnRef(SqlColumnName("uses_consumed")),
                            BinaryOp.GE,
                            SqlParam(config.claims.max_uses),
                        ),
                    ),
                ),
                limit=1,
            ),
        )
    else:
        usage_limit_exceeded = SqlParam(False)
    return SqlSelectExpressions(
        [
            (issued_exists, str(SqlAliasName("issued_exists"))),
            (revocation_exists, str(SqlAliasName("revocation_exists"))),
            (usage_limit_exceeded, str(SqlAliasName("usage_limit_exceeded"))),
        ],
    )


def _parse_tracked_claims(
    config: _ValidateAuthTrackedTokenTerminalConfig,
) -> AuthWorkflowClaims | AuthChallengeClaims:
    from l6520_auth.auth_lazy_plan_claims import (
        parse_challenge_claims_with_expected_workflow,
        parse_workflow_claims_with_expected_workflow,
    )

    if config.parse_mode is _TrackedTokenParseMode.WORKFLOW:
        return parse_workflow_claims_with_expected_workflow(
            config.claims,
            expected_workflow=config.expected_workflow,
        )
    if config.parse_mode is _TrackedTokenParseMode.CHALLENGE:
        return parse_challenge_claims_with_expected_workflow(
            config.claims,
            expected_workflow=config.expected_workflow,
        )
    msg = f"Unsupported tracked token parse mode {config.parse_mode!r}"
    raise TypeError(msg)


class _ValidateAuthTrackedTokenTerminalStepCteRow(BaseModel):
    issued_exists: bool
    revocation_exists: bool
    usage_limit_exceeded: bool


class _ValidateAuthTrackedTokenTerminalStep(
    SqlRelationPublisherStep[AuthWorkflowClaims | AuthChallengeClaims],
):
    """Terminal validation step for tracked auth tokens (workflow / challenge)."""

    def cte_publication_contract(self: _ValidateAuthTrackedTokenTerminalStep) -> CtePublicationContract:
        columns = ("issued_exists", "revocation_exists", "usage_limit_exceeded")
        column_type_hints = SqlColumnTypeHints(bool_columns=frozenset(columns))
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        _contract_model_cls = _ValidateAuthTrackedTokenTerminalStepCteRow
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=tuple(str(column) for column in columns),
            column_type_hints=column_type_hints,
            model_cls=_contract_model_cls,
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        config: _ValidateAuthTrackedTokenTerminalConfig,
    ) -> None:
        super().__init__(ref_id)
        self._config = config

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self) -> bool:
        return True

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def step_tags(self) -> frozenset[str]:
        return frozenset({"read", "auth", "tracked", "validate"})

    def tables_read(self) -> frozenset[str]:
        from l1000_schema.table_utils import get_table_name

        return frozenset(
            {
                get_table_name(CapabilityTokenIssued),
                get_table_name(CapabilityTokenRevocation),
            },
        )

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def dependencies(self) -> frozenset[str]:
        return frozenset()

    def compile(
        self,
        ctx: CompilationContext,
    ) -> CompiledStep[AuthWorkflowClaims | AuthChallengeClaims]:
        del ctx
        __opa002_grammar_395 = _auth_tracked_token_validation_stmt(self._config)
        output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(
            self.cte_publication_contract(),
        )
        return CompiledStep(
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
            grammar=__opa002_grammar_395,
            needs_returning=True,
            closed_post_op=auth_validate_tracked_token_post_op(
                config=self._config,
            ),
        )


