class _ReturnSignedAuthTokenAfterDepsStep(
    NonPublishingStep[IssuedAuthWorkflowToken | AuthChallenge],
):
    """Sign planner-owned auth claims after their tracking row succeeds."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        claims: TrackedCapabilityTokenClaims,
        result: IssuedAuthWorkflowToken | AuthChallenge,
        source_ref: ServerPlanRefId,
    ) -> None:
        super().__init__(ref_id)
        self._claims = claims
        self._result = result
        self._source_ref = source_ref

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self) -> bool:
        return True

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def is_executor_owned_runtime_step(self) -> bool:
        return True

    def publishes_decoded_value_as_executor_value(self) -> bool:
        return True

    def runtime_result_is_terminal_scalar(self) -> bool:
        return True

    def step_tags(self) -> frozenset[str]:
        return frozenset({"return_value", "auth", "sign"})

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def dependencies(self) -> frozenset[str]:
        return frozenset({str(self._source_ref)})

    def compile(self, ctx: CompilationContext) -> CompiledStep[IssuedAuthWorkflowToken | AuthChallenge]:
        del ctx
        return CompiledStep()

    def execute_runtime(
        self,
        _resolved: Mapping[str, object],
        hydrator: RuntimeHydrator[Any],
    ) -> IssuedAuthWorkflowToken | AuthChallenge:
        services = hydrator.runtime_services
        runtime = services.renewable_capability if services is not None else None
        if runtime is None:
            raise RuntimeError("Renewable capability runtime is required to sign tracked auth tokens")
        token = runtime.capability.issue_token(self._claims)
        if isinstance(self._result, IssuedAuthWorkflowToken):
            return IssuedAuthWorkflowToken(token=token, claims=self._result.claims)
        return AuthChallenge(token=token, claims=self._result.claims)


class AuthIssueWorkflowTokenIntent(_AuthLowerOnlyStep[IssuedAuthWorkflowToken]):
    """Issue a tracked workflow token: sign claims, INSERT issued record."""

    intent_tags = frozenset({"write", "auth", "tracked", "intent"})
