def _sql_cell(value: object) -> SqlCell:
    if value is None:
        return SQL_NULL
    if isinstance(value, str | int | float | bool | bytes | memoryview | Decimal | date | datetime | UUID):
        return value
    msg = f"Expected SQL cell value, got {type(value).__name__}"
    raise TypeError(msg)


def _content_store_param_int(value: object) -> int:
