    if isinstance(value, bytearray | memoryview):
        return bytes(value)
    msg = f"Expected binary content-store parameter, got {type(value).__name__}"
    raise TypeError(msg)


def _sql_row_cells(row: Mapping[str, object]) -> dict[str, SqlCell]:
    return {str(key): _sql_cell(value) for key, value in row.items()}


