def _sql_row_map(row: object) -> Mapping[str, object]:
    if isinstance(row, Mapping):
        return cast(Mapping[str, object], row)
    keys = getattr(row, "keys", None)
    if callable(keys):
        keyed_row = cast(_KeyedSqlRow, row)
        return {str(key): keyed_row[key] for key in keyed_row.keys()}
    msg = f"Expected SQL row mapping, got {type(row).__name__}"
    raise TypeError(msg)


def _decode_row_lookup[RowT](
    ref_id: ServerPlanRefId,
    raw_result: RawResult,
    row_decoder: RowDecoder[RowT],
) -> RowLookup[RowT]:
    if not raw_result:
        return MissingRow(ref_id=str(ref_id))
    return FoundRow(ref_id=str(ref_id), row=row_decoder(_sql_row_cells(_sql_row_map(raw_result[0]))))


def _row_codec_kind(row_decoder: RowDecoder[object]) -> str:
    if row_decoder is dict_sql_row:
        return "dict_sql_row"
    msg = f"Unsupported content-store row decoder: {row_decoder!r}"
    raise TypeError(msg)


def _row_codec_from_kind(kind: str) -> RowDecoder[object]:
    if kind == "dict_sql_row":
        return dict_sql_row
    msg = f"Unsupported content-store row decoder kind: {kind!r}"
    raise ValueError(msg)


