    def _get_transaction_plan_lazy(self) -> BaseServerPlan: ...

    def _add_intent_by_ref(
        self,
        ref_id: ServerPlanRefId,
    ) -> LazyResult[ContentStoreManifest[StoreRowT, ChunkRowT]]: ...


@pure_lazy
def content_store_manifest_lazy[StoreRowT, ChunkRowT](
    owner: _ContentStoreManifestPlanOwner[StoreRowT, ChunkRowT],
    *,
    store_table: SqlTableName,
    content_hash: str,
    store_row_decoder: RowDecoder[StoreRowT],
    chunk_row_decoder: RowDecoder[ChunkRowT],
) -> LazyResult[ContentStoreManifest[StoreRowT, ChunkRowT]]:
    """Publish one typed content-store manifest on the caller-owned plan."""
    plan = owner._get_transaction_plan_lazy()
    store_ref = ServerPlanRefId(plan._next_ref())
    plan.add_step(
        ContentStoreRowLookupStep[StoreRowT](
            store_ref,
            ContentStoreLookupConfig(
                store_table=store_table,
                content_hash=content_hash,
                row_decoder=store_row_decoder,
            ),
        ),
    )
    chunks_ref = ServerPlanRefId(plan._next_ref())
    plan.add_step(
        ContentChunkRowsLookupStep[ChunkRowT](
            chunks_ref,
            ContentStoreLookupConfig(
                store_table=store_table,
                content_hash=content_hash,
                row_decoder=chunk_row_decoder,
            ),
        ),
    )
    manifest_ref = ServerPlanRefId(plan._next_ref())
    plan.add_step(
        ContentStoreManifestLookupStep[StoreRowT, ChunkRowT](
            manifest_ref,
            ContentStoreManifestConfig(
                store_ref=store_ref,
                chunks_ref=chunks_ref,
            ),
        ),
    )
    return owner._add_intent_by_ref(manifest_ref)


def content_store_manifest_dict_rows(
    value: object,
) -> tuple[dict[str, object], list[dict[str, object]]] | None:
    """Project a resolved typed manifest to the legacy dictionary result shape."""
    assert isinstance(value, ContentStoreManifest)
    if not isinstance(value.store, FoundRow):
        return None
    return dict(value.store.row), [dict(row) for row in value.chunks]


