def _chunk_result_assignment_overrides(row: EmbeddingComputeChunkRow) -> Mapping[str, object]:
    from l5200_vector_index.embedding_type import EmbeddingType

    parsed_embedding = EmbeddingType(row.chunk_embedding_bytes)
    dimensions = parsed_embedding.dimensions
    if dimensions is None:
        msg = "chunk_embedding_bytes must encode dimensions"
        raise ValueError(msg)
    precision = parsed_embedding.precision.value
    updates: dict[str, object] = {}
    if row.dimensions is None:
        updates["dimensions"] = dimensions
    elif row.dimensions != dimensions:
        msg = f"EmbeddingComputeChunkRow.dimensions does not match chunk_embedding_bytes: expected {dimensions}, got {row.dimensions}"
        raise ValueError(msg)
    if row.precision is None:
        updates["precision"] = precision
    elif row.precision != precision:
        msg = f"EmbeddingComputeChunkRow.precision does not match chunk_embedding_bytes: expected {precision}, got {row.precision}"
        raise ValueError(msg)
    return updates


