def _materialize_provider_rows[T: DatabaseObjectRow[Any]](
    raw: RawResult,
    model_cls: type[T],
) -> list[T]:
    from impl.common.l5200_sql_query.row_converter import convert_row_to_model

    materialized: list[T] = []
    for row in raw:
        if isinstance(row, model_cls):
            materialized.append(row)
            continue
        if isinstance(row, Mapping):
            materialized.append(
                cast(
                    T,
                    convert_row_to_model(
                        model_cls,
                        dict(row),
                        conn=None,
                        hydrate_large_columns=False,
                    ),
                ),
            )
            continue
        msg = f"Expected dict or {model_cls.__name__}, got {type(row).__name__}"
        raise TypeError(msg)
    return materialized


