def _provider_write_chunk_size(
    model_cls: type[DatabaseObjectRow[Any]],
    row_count: int,
    *,
    ctx: LoweringContext,
) -> int:
    from impl.common.l2070_server_plan.steps._compile_helpers import get_write_metadata_plan_from_catalog

    column_count = len(get_write_metadata_plan_from_catalog(ctx.planning_catalog, model_cls).field_plans)
    row_cap = int(_rows_per_statement(ctx.backend_type, column_count, row_count))
    return max(1, row_cap)


def _lower_provider_write_batch[T: DatabaseObjectRow[Any]](
    *,
    ref_id: ServerPlanRefId,
    rows: Sequence[T],
    source_ref: ServerPlanRefId | None,
    model_cls: type[T],
    conflict_columns: Sequence[object],
    upsert_kind: _ProviderUpsertKind,
    ctx: LoweringContext,
    literal_assignment_overrides: Sequence[Mapping[str, object]] | None = None,
) -> Sequence[ServerPlanStep[Any]]:
    if source_ref is not None:
        return [
            _CteWrappedUpsertManyStep(
                ref_id,
                model_cls=model_cls,
                source_ref=source_ref,
                conflict_columns=conflict_columns,
                upsert_kind=upsert_kind,
            ),
        ]
    chunk_size = _provider_write_chunk_size(model_cls, len(rows), ctx=ctx)
    if not rows or len(rows) <= chunk_size:
        return [
            _GrammarWrappedUpsertManyStep(
                ref_id,
                model_cls=model_cls,
                instances=tuple(rows),
                literal_assignment_overrides=(tuple(literal_assignment_overrides) if literal_assignment_overrides is not None else ()),
                conflict_columns=conflict_columns,
                upsert_kind=upsert_kind,
            ),
        ]

    write_refs: list[ServerPlanRefId] = []
    steps: list[ServerPlanStep[Any]] = []
    for index, start in enumerate(range(0, len(rows), chunk_size)):
        chunk_ref = ServerPlanRefId(f"{ref_id}.chunk_{index}")
        write_refs.append(chunk_ref)
        steps.append(
            _GrammarWrappedUpsertManyStep(
                chunk_ref,
                model_cls=model_cls,
                instances=tuple(rows[start : start + chunk_size]),
                literal_assignment_overrides=(
                    tuple(literal_assignment_overrides[start : start + chunk_size]) if literal_assignment_overrides is not None else ()
                ),
                conflict_columns=conflict_columns,
                upsert_kind=upsert_kind,
            ),
        )
    steps.append(
        _FlattenListCollectStep(
            ref_id,
            _FlattenListCollectConfig(source_refs=tuple(write_refs)),
        ),
    )
    return steps


