def replay_actions_are_unconditional(model: type[DatabaseObjectRow]) -> bool:
    """Require explicit unconditional policy for every action used by replay."""
    for concrete in dict.fromkeys([model, *get_all_concrete_subtypes(model)]):
        if not has_permission_scheme(concrete):
            return False
        scheme = get_permission_scheme(concrete)
        if not all(
            scheme.get_policy_expression(concrete, action=action).function == "PERMISSION_TRUE"
            for action in ("read", "insert", "update", "delete")
        ):
            return False
    return True


def _replay_actions_are_unconditional_with_graph_inheritance(
    model: type[DatabaseObjectRow],
    domain: type[VersioningDomain],
) -> bool:
    """Resolve graph-member authority to an unconditional parent policy."""
    from l4000_permissions.graph_type_resolution import find_graph_types_for_model

    for concrete in dict.fromkeys([model, *get_all_concrete_subtypes(model)]):
        if not has_permission_scheme(concrete):
            return False
        scheme = get_permission_scheme(concrete)
        policy_models = (
            tuple(find_graph_types_for_model(domain, concrete)) if isinstance(scheme, GraphInheritedPermissionMarker) else (concrete,)
        )
        if not policy_models:
            return False
        for policy_model in policy_models:
            if not has_permission_scheme(policy_model):
                return False
            policy_scheme = get_permission_scheme(policy_model)
            if not all(
                policy_scheme.get_policy_expression(policy_model, action=action).function == "PERMISSION_TRUE"
                for action in ("read", "insert", "update", "delete")
            ):
                return False
    return True


def replay_permission_check_groups(
    model: type[DatabaseObjectRow],
    domain: type[VersioningDomain],
    *,
    split_actions: bool = True,
) -> tuple[tuple[frozenset[str], type[DatabaseObjectRow] | None, type | None], ...]:
    """Split replay predicates only when the backend needs bounded action plans."""
    action_groups = (
        tuple(frozenset({action}) for action in ("insert", "update", "delete", "read"))
        if split_actions
        else (frozenset({"insert", "update", "delete", "read"}),)
    )
    scheme = get_permission_scheme(model) if has_permission_scheme(model) else None
    if isinstance(scheme, GraphInheritedPermissionMarker):
        from l4000_permissions.graph_type_resolution import find_graph_types_for_model

        concrete_subtypes = tuple(dict.fromkeys(get_all_concrete_subtypes(model)))
        concrete_models = concrete_subtypes or (model,)
        return tuple(
            (checks, concrete, graph_type)
            for concrete in concrete_models
            for graph_type in find_graph_types_for_model(domain, concrete)
            if not replay_actions_are_unconditional(graph_type)
            for checks in action_groups
        )
    return tuple((checks, None, None) for checks in action_groups)


