class ReplayPolicyFamilyExistsStep(SqlRelationPublisherStep[bool]):
    """Publish whether a replay diff contains one concrete policy family."""

    def __init__(
        self: ReplayPolicyFamilyExistsStep,
        ref_id: ServerPlanRefId,
        *,
        model: type[DatabaseObjectRow],
        policy_model: type[DatabaseObjectRow] | None,
        graph_type: type | None,
