        self._policy_model = policy_model
        self._graph_type = graph_type
        self._diff_spec = diff_spec
        self._branch = branch
        self._after = after

    @property
    def level(self: ReplayPolicyFamilyExistsStep) -> int:
        return 0

    def dependencies(self: ReplayPolicyFamilyExistsStep) -> frozenset[str]:
        from impl.common.l2070_server_plan.steps.intent_diff_revert import _source_dependencies

        after = frozenset({str(self._after)}) if self._after is not None else frozenset()
        return after | _source_dependencies(self._branch)

    def dependency_contract(self: ReplayPolicyFamilyExistsStep) -> StepDependencyContract:
        return StepDependencyContract.from_refs(
            self.dependencies(),
            source=DependencySource.CONSTRUCTOR_DEPENDS_ON,
            required_for=frozenset({DependencyUse.ORDERING}),
            reason="Replay family probes run after prior permission gates.",
        )

    def sql_visible_dependencies(self: ReplayPolicyFamilyExistsStep) -> frozenset[str]:
        return frozenset()

    def executor_visible_dependencies(self: ReplayPolicyFamilyExistsStep) -> frozenset[str]:
        return frozenset()

    def declares_consumed_rows_reduction(self: ReplayPolicyFamilyExistsStep) -> bool:
        return True

    def result_cardinality(self: ReplayPolicyFamilyExistsStep) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self: ReplayPolicyFamilyExistsStep) -> bool:
        return True

    def execution_role(self: ReplayPolicyFamilyExistsStep) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def tables_read(self: ReplayPolicyFamilyExistsStep) -> frozenset[str]:
        return frozenset()

    def tables_written(self: ReplayPolicyFamilyExistsStep) -> frozenset[str]:
        return frozenset()

    def cte_publication_contract(self: ReplayPolicyFamilyExistsStep) -> CtePublicationContract:
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=("value",),
            column_type_hints=SqlColumnTypeHints(bool_columns=frozenset({"value"})),
            model_cls=_ReplayPolicyFamilyExistsRow,
            relation_role=self.cte_relation_role(),
            scalar_control_kind=ScalarControlKind.EXISTS,
            scalar_value_column=LockedColumnName("value"),
        )

    def compile(self: ReplayPolicyFamilyExistsStep, ctx: CompilationContext) -> CompiledStep[bool]:
        del ctx
        sparse_table = SqlTableName(derive_versioned_table_names(VersionedBaseTableName(str(get_table_name(self._model)))).sparse)
        row_filter: SqlRenderable = SqlParam(True)
        if self._graph_type is not None:
            graph_sparse_table = SqlTableName(
                derive_versioned_table_names(VersionedBaseTableName(str(get_table_name(self._graph_type)))).sparse
            )
            row_filter = SqlExists(
                SqlSelect(
                    [SqlParam(1)],
                    from_=SqlTableAlias(SqlTableIdent(graph_sparse_table), SqlAliasName("graph_scope")),
                    where=SqlBinaryOp(
                        SqlColumnRef(SqlColumnName("sys_id"), qualifier="graph_scope"),
                        BinaryOp.EQ,
                        SqlColumnRef(SqlColumnName("graph_sys_id"), qualifier="member_scope"),
                    ),
                )
            )
        if self._policy_model is not None and "type_name" in self._diff_spec.data_columns:
            row_filter = sql_and(
                row_filter,
                SqlIn(
                    SqlColumnRef(SqlColumnName("type_name"), qualifier="member_scope"),
                    [SqlParam(name) for name in polymorphic_type_name_aliases(self._policy_model)],
                ),
            )
        exists = SqlExists(
            SqlSelect(
                [SqlParam(1)],
                from_=SqlTableAlias(SqlTableIdent(sparse_table), SqlAliasName("member_scope")),
                where=row_filter,
            )
        )
        grammar = SqlSelect([SqlSelectAlias(exists, SqlAliasName("value"))])
        output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(
            self.cte_publication_contract()
        )
        return CompiledStep(
            grammar=grammar,
            needs_returning=True,
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
            closed_post_op=scalar_column_post_op(
                "value",
                default_value=False,
                use_default_on_empty=True,
                scalar_coercion=ScalarCoercionKind.BOOL,
            ),
        )


class ReplayPermissionStep(ReturnValueStep[None]):
    """Reject the complete replay if any changed row lacks required authority."""

    def __init__(
        self: ReplayPermissionStep,
        ref_id: ServerPlanRefId,
        *,
        model: type[DatabaseObjectRow],
        domain: type[VersioningDomain],
        diff_spec: _RevertDiffCteSpec,
        branch: object,
        session: PlanningSessionId | None,
        after: ServerPlanRefId | None,
        checks: frozenset[str] = frozenset({"insert", "update", "delete", "read"}),
        policy_model: type[DatabaseObjectRow] | None = None,
        graph_type: type | None = None,
    ) -> None:
        super().__init__(ref_id, None)
        self._model = model
        self._domain = domain
        self._diff_spec = diff_spec
        self._branch = branch
        self._session_source = session
        self._after = after
        self._checks = checks
        self._policy_model = policy_model
        self._graph_type = graph_type

    def dependencies(self: ReplayPermissionStep) -> frozenset[str]:
        from impl.common.l2070_server_plan.steps.intent_diff_revert import _source_dependencies

        after = frozenset({str(self._after)}) if self._after is not None else frozenset()
        return after | _source_dependencies(self._branch) | _source_dependencies(self._session_source)

    def execution_role(self: ReplayPermissionStep) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def supports_sql_batch_transport(self: ReplayPermissionStep) -> bool:
        return False

    def requires_runtime_sequential_batch(self: ReplayPermissionStep) -> bool:
        return True

    def compile(self: ReplayPermissionStep, ctx: CompilationContext) -> CompiledStep[None]:
        from impl.common.l2070_server_plan.steps.intent_diff_revert import _build_revert_diff_cte

        if self._session_source is None:
            raise ValueError("Revision replay requires an explicit actor session")
        ctx = replace(ctx, session_id=self._session_source, versioning_domain=self._domain)
        branch = lower_scalar_source(self._branch, ctx)
        diff = _build_revert_diff_cte(self._diff_spec, branch)
        session = compilation_session_id(ctx)
        if ctx.session_id is None:
            raise ValueError("Revision replay requires a resolved actor session")
        user = session_user_id_expr(ctx.session_id, ctx)
        scheme = get_permission_scheme(self._model) if has_permission_scheme(self._model) else None
        if scheme is None:
            definitions, _ = diff.split_for_outer_cte()
            ctes = [
                SqlCteDefinition(name=definition._name, query=definition._query, columns=tuple(definition._columns or ()))
                for definition in definitions
            ]
            changed = SqlSelect(
                select=[SqlParam(1)],
                from_=SqlTableIdent(SqlTableName("diff")),
                where=SqlBinaryOp(SqlColumnRef(SqlColumnName("change_type")), BinaryOp.NE, SqlParam("UNCHANGED")),
            )
            message = "Revision replay requires registered permission schemes"
            grammar: SqlRenderable = no_rows_assertion_query(SqlWith(ctes, changed, recursive=True), error_message=message)
            shape = sql_assertion_output_shape()
            return CompiledStep(
                output_shape=shape,
                result_relation=DeclaredResultRelation.from_output_shape(shape),
                grammar=grammar,
                needs_returning=True,
                column_type_hints=sql_assertion_column_type_hints(),
                closed_post_op=sql_assertion_post_op(message, exc_type=DbPermissionError),
            )
        concrete_models = (
            (self._policy_model,)
            if self._policy_model is not None
            else tuple(dict.fromkeys([self._model, *get_all_concrete_subtypes(self._model)]))
        )
        unconditional_actions = _replay_actions_are_unconditional_with_graph_inheritance(
            self._graph_type or self._policy_model or self._model,
            self._domain,
        )
        concrete_policies = tuple(get_query_permission_plan(model) for model in concrete_models)
        if unconditional_actions or (
            all(has_permission_scheme(model) for model in concrete_models)
            and all(plan is None or not plan.filter_reserved_sessions for plan in concrete_policies)
            and isinstance(session, SessionId)
            and (session.is_schema_session())
        ):
            shape = sql_assertion_output_shape()
            grammar = no_rows_assertion_query(
                SqlSelect(select=[SqlParam(1)], where=SqlParam(False)), error_message="Revision replay authorization"
            )
            return CompiledStep(
                output_shape=shape,
                result_relation=DeclaredResultRelation.from_output_shape(shape),
                grammar=grammar,
                needs_returning=True,
                column_type_hints=sql_assertion_column_type_hints(),
                closed_post_op=sql_assertion_post_op("Revision replay authorization", exc_type=DbPermissionError),
            )

        from impl.common.l2070_server_plan.steps.replay_graph_sources import current_replay_graph_sources

        graph_proposal_definitions: list[SqlCteDefinition] = []
        current_graph_sources: dict[type, SqlRenderable] = {}
        for index, (graph_model, graph_source) in enumerate(
            current_replay_graph_sources(
                ctx,
                domain=self._domain,
                model=self._model,
                branch=branch,
            ).items()
        ):
            if self._graph_type is not None and graph_model is not self._graph_type:
                continue
            name = SqlTableName(f"replay_graph_current_{index}")
            graph_proposal_definitions.append(SqlCteDefinition(str(name), graph_source))
            current_graph_sources[graph_model] = SqlSelect([SqlStar()], from_=SqlTableIdent(name))
        proposal_graph_sources: dict[type, SqlRenderable] | None = None

        def permission(alias: str, action: str, *, source: bool = False, old_source: bool = False) -> SqlRenderable:
            nonlocal proposal_graph_sources
            if scheme is None:
                return SqlParam(False)
            if action == "insert" and not source and proposal_graph_sources is None:
                from impl.common.l2070_server_plan.steps.replay_graph_sources import replay_graph_sources

                graph_sources = replay_graph_sources(
                    ctx,
                    domain=self._domain,
                    model=self._model,
                    branch=branch,
                    member_diff=diff,
                    current_sources=(None if self._graph_type is not None else current_graph_sources),
                )
                proposal_graph_sources = {}
                for index, (graph_model, graph_source) in enumerate(graph_sources.items()):
                    if self._graph_type is not None and graph_model is not self._graph_type:
                        continue
                    name = SqlTableName(f"replay_graph_parent_{index}")
                    graph_proposal_definitions.append(SqlCteDefinition(str(name), graph_source))
                    proposal_graph_sources[graph_model] = SqlSelect([SqlStar()], from_=SqlTableIdent(name))
            anchor = (
                PinnedRevisionPermissionAnchor(
                    self._domain,
                    lower_scalar_source(diff._old_revision_raw if old_source else self._diff_spec.to_revision, ctx),
                    lower_scalar_source(diff._old_branch_id_raw if old_source else self._diff_spec.diff_branch_id, ctx),
                )
                if source
                else BranchTipPermissionAnchor(
                    self._domain,
                    branch,
                    graph_sources=proposal_graph_sources if action == "insert" else current_graph_sources,
                )
            )
            query_versioned_scope: tuple[SqlRenderable | None, SqlRenderable | None]
            if isinstance(anchor, PinnedRevisionPermissionAnchor):
                query_versioned_scope = (anchor.branch_id_sql, anchor.revision_id_sql)
            else:
                query_versioned_scope = (anchor.branch_id_sql, None)
            permission_ctx = replace(ctx, query_versioned_scope=query_versioned_scope)
            predicates: list[SqlRenderable] = []
            for concrete in concrete_models:
                if not has_permission_scheme(concrete):
                    continue
                concrete_scheme = get_permission_scheme(concrete)
                policy_action = "update" if action == "insert" and isinstance(concrete_scheme, GraphInheritedPermissionMarker) else action
                predicate = compile_permission_where_with_user_expr(
                    concrete,
                    session,
                    user,
                    table_alias=alias,
                    action=policy_action,
                    domain=self._domain,
                    version_anchor=anchor,
                    session_id_sql=session_id_expr(ctx.session_id, ctx),
                    compilation_context=permission_ctx,
                )
                allowed: SqlRenderable = (
                    SqlFuncCall(SqlFunctionName("COALESCE"), [predicate, SqlParam(False)]) if predicate is not None else SqlParam(True)
                )
                concrete_policy = get_query_permission_plan(concrete)
                if concrete_policy is None or not concrete_policy.filter_reserved_sessions:
                    allowed = sql_or(
                        SqlIn(session_id_expr(ctx.session_id, ctx), [SqlParam(SessionId.schema())]), allowed
                    )
                if "type_name" in self._diff_spec.data_columns:
                    discriminator = SqlColumnRef(SqlColumnName("type_name"), qualifier=alias)
                    family: SqlRenderable = SqlIn(discriminator, [SqlParam(name) for name in polymorphic_type_name_aliases(concrete)])
                    if get_polymorphic_base_class(concrete) is concrete:
                        family = sql_or(SqlIsNull(discriminator), family)
                    allowed = sql_or(SqlNot(family), allowed) if self._policy_model is not None else sql_and(family, allowed)
                predicates.append(allowed)
            return sql_or(*predicates) if predicates else SqlParam(False)

        target_spec = QuerySpec(
            model_cls=self._model,
            select_columns=None,
            distinct=False,
            joins=[],
            filters=[],
            order_by=(),
            limit=None,
            offset=None,
            group_by=[],
            aggregations=[],
            having=[],
            window_functions=[],
            skip_permission_filtering=True,
        )
        target = compile_versioned_query(target_spec, self._model, ctx, branch_id_override=branch, raw_mode=True).grammar
        assert target is not None
        target_relation = SqlTableAlias(SqlTableIdent(SqlTableName("replay_target")), SqlAliasName("target"))
        identity = SqlBinaryOp(
            SqlColumnRef(SqlColumnName("sys_id"), qualifier="target"),
            BinaryOp.EQ,
            SqlColumnRef(SqlColumnName("sys_id"), qualifier="proposal"),
        )

        def target_allows(action: str) -> SqlRenderable:
            return SqlExists(
                SqlSelect(
                    select=[SqlParam(1)],
                    from_=target_relation,
                    where=sql_and(identity, permission("target", action)),
                )
            )

        proposal = SqlSelect(
            select=[
                SqlSelectAlias(branch, SqlAliasName("branch_id")),
                SqlColumnRef(SqlColumnName("sys_id")),
                SqlColumnRef(SqlColumnName("change_type")),
                *(
                    SqlSelectAlias(
                        SqlCase(
                            [
                                (
                                    SqlBinaryOp(SqlColumnRef(SqlColumnName("change_type")), BinaryOp.EQ, SqlParam("DELETED")),
                                    SqlColumnRef(SqlColumnName("old_" + column)),
                                )
                            ],
                            else_=SqlColumnRef(SqlColumnName("new_" + column)),
                        ),
                        SqlAliasName(column),
                    )
                    for column in self._diff_spec.data_columns
                ),
            ],
            from_=SqlTableIdent(SqlTableName("diff")),
        )
        kind = SqlColumnRef(SqlColumnName("change_type"), qualifier="proposal")
        target_exists = SqlExists(SqlSelect(select=[SqlParam(1)], from_=target_relation, where=identity))
        denied_checks: list[SqlRenderable] = []
        if "insert" in self._checks:
            denied_checks.extend(
                [
                    sql_and(SqlBinaryOp(kind, BinaryOp.EQ, SqlParam("ADDED")), SqlNot(permission("proposal", "insert"))),
                    sql_and(
                        SqlBinaryOp(kind, BinaryOp.EQ, SqlParam("MODIFIED")),
                        SqlNot(target_exists),
                        SqlNot(permission("proposal", "insert")),
                    ),
                ]
            )
        if "update" in self._checks:
            denied_checks.extend(
                [
                    sql_and(SqlBinaryOp(kind, BinaryOp.EQ, SqlParam("ADDED")), target_exists, SqlNot(target_allows("update"))),
                    sql_and(SqlBinaryOp(kind, BinaryOp.EQ, SqlParam("MODIFIED")), target_exists, SqlNot(target_allows("update"))),
                ]
            )
        if "delete" in self._checks:
            denied_checks.append(
                sql_and(SqlBinaryOp(kind, BinaryOp.EQ, SqlParam("DELETED")), target_exists, SqlNot(target_allows("delete")))
            )
        if "read" in self._checks:
            denied_checks.extend(
                [
                    sql_and(
                        SqlBinaryOp(kind, BinaryOp.EQ, SqlParam("DELETED")),
                        SqlNot(permission("proposal", "read", source=True, old_source=True)),
                    ),
                    sql_and(
                        SqlIn(kind, [SqlParam("ADDED"), SqlParam("MODIFIED")]),
                        SqlNot(permission("proposal", "read", source=True)),
                    ),
                ]
            )
        denied = sql_or(*denied_checks)
        definitions, _ = diff.split_for_outer_cte()
        ctes = [
            SqlCteDefinition(name=definition._name, query=definition._query, columns=tuple(definition._columns or ()))
            for definition in definitions
        ]
        message = "Revision replay requires source read and target write authority"
        ctes.extend(graph_proposal_definitions)
        ctes.extend([SqlCteDefinition("replay_target", target), SqlCteDefinition("replay_proposal", proposal)])
        proposal_relation = SqlTableAlias(SqlTableIdent(SqlTableName("replay_proposal")), SqlAliasName("proposal"))
        violations = SqlSelect(select=[SqlParam(1)], from_=proposal_relation, where=denied)
        replay_grammar: SqlRenderable = SqlWith(
            ctes,
            no_rows_assertion_query(violations, error_message=message),
            recursive=True,
        )
        shape = sql_assertion_output_shape()
        return CompiledStep(
            output_shape=shape,
            result_relation=DeclaredResultRelation.from_output_shape(shape),
            grammar=replay_grammar,
            needs_returning=True,
            column_type_hints=sql_assertion_column_type_hints(),
            closed_post_op=sql_assertion_post_op(message, exc_type=DbPermissionError),
        )

