@dataclass(frozen=True, slots=True)
class MergeClassification:
    """Result of merge-type classification (computed in SQL).

    ``needs_three_way`` is derived from the three primary
    merge-classification booleans.
    """

    is_fast_forward: bool
    is_up_to_date: bool
    is_diverged: bool
    needs_three_way: bool


def merge_classification_post_op() -> CompiledPostOp:
    """Materialize SQL merge classification booleans."""
    return CompiledPostOp.materialize(
        ResultMaterializationSpec(
            behavior=PostOpBehavior.TERMINAL_OBJECT,
            structured_result=StructuredResultSpec(
                result_cls=MergeClassification,
                fields=(
                    StructuredResultField(
                        "is_fast_forward",
                        "is_fast_forward",
                        ScalarCoercionKind.BOOL,
                        required=False,
                        default_value=False,
                    ),
                    StructuredResultField(
                        "is_up_to_date",
                        "is_up_to_date",
                        ScalarCoercionKind.BOOL,
                        required=False,
                        default_value=False,
                    ),
                    StructuredResultField(
                        "is_diverged",
                        "is_diverged",
                        ScalarCoercionKind.BOOL,
                        required=False,
                        default_value=False,
                    ),
                ),
                derived_bool_fields=(
                    StructuredDerivedBoolField(
                        "needs_three_way",
                        ("is_fast_forward", "is_up_to_date", "is_diverged"),
                    ),
                ),
            ),
        ),
    )


