            else frozenset({str(self._source.source_ref_id)})
        )
        return source_dependencies | (
            frozenset({str(self._source.branch_ref_id)}) if self._source.branch_ref_id is not None else frozenset()
        )

    def executor_visible_dependencies(self: Self) -> frozenset[str]:
        source_query = self._source.source_query
        return frozenset() if source_query is None else source_query.executor_visible_dependencies()

    def consumes_executor_visible_dependencies(self: Self) -> bool:
        source_query = self._source.source_query
        return source_query is not None and source_query.consumes_executor_visible_dependencies()

    def requires_materialized_inputs(self: Self) -> bool:
        source_query = self._source.source_query
        return source_query is not None and source_query.requires_materialized_inputs()

    def requires_prior_step_boundary(self: Self) -> bool:
        source_query = self._source.source_query
        return source_query is not None and source_query.requires_prior_step_boundary()

    def supports_ordered_materialized_input_dispatch(self: Self) -> bool:
        source_query = self._source.source_query
        return source_query is not None and source_query.supports_ordered_materialized_input_dispatch()

    def requires_prior_statement_visibility_after_writes(self: Self) -> frozenset[str]:
        source_query = self._source.source_query
        return frozenset() if source_query is None else source_query.requires_prior_statement_visibility_after_writes()

    def _stores(self: Self) -> tuple[tuple[str, str], ...]:
        source = self._source
        config = get_vector_config(source.model_cls, str(source.index_name))
        assert config is not None
        if config.content_store_strategy is ContentStoreStrategy.PER_MODEL:
            return tuple(dict.fromkeys((vectors, refs) for _, vectors, refs in self._owned_store_tables))
        table = vector_source_table_name(source.model_cls)
        return (
            (
                get_embedding_vector_table_name(table, strategy=config.content_store_strategy, field_name=str(source.index_name)),
                get_embedding_ref_table_name(table, strategy=config.content_store_strategy, field_name=str(source.index_name)),
            ),
        )

    def tables_read(self: Self) -> frozenset[str]:
        table = vector_source_table_name(self._source.model_cls)
        return frozenset(
            {
                table,
                get_usearch_index_table_name(table),
                "sys_usearch_artifact_members",
                "sys_embedding_metadata",
                *(self._source.source_query.tables_read() if self._source.source_query is not None else frozenset({table})),
                *(table for store in self._stores() for table in store),
            }
        )

    def tables_written(self: Self) -> frozenset[str]:
        return frozenset()

    def cte_publication_contract(self: Self) -> CtePublicationContract:
        if not issubclass(self._source.model_cls, VersionedObjectRow):
            return CtePublicationContract(
                publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
                columns=(
                    "object_id",
                    "branch_id",
                    "revision_id",
                    "native_key",
                    "chunk_id",
                    "chunk_metadata",
                ),
                column_type_hints=SqlColumnTypeHints(
                    uuid_columns=frozenset({"object_id", "branch_id", "revision_id", "chunk_id"}),
                    bigint_columns=frozenset({"native_key"}),
                    text_columns=frozenset({"chunk_metadata"}),
                ),
                relation_contract=CteRelationContract.semantic_row(_UnversionedEligibilityRow),
                relation_role="usearch_eligibility",
                source_tables=self.tables_read(),
            )
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=("object_id", "branch_id", "revision_id", "native_key"),
            column_type_hints=SqlColumnTypeHints(
                uuid_columns=frozenset({"object_id", "branch_id", "revision_id"}),
                bigint_columns=frozenset({"native_key"}),
            ),
            relation_contract=CteRelationContract.semantic_row(_CrossBranchUSearchEligibilityRow),
            relation_role="usearch_eligibility",
            source_tables=self.tables_read(),
        )

    def compile(self: Self, ctx: CompilationContext) -> CompiledStep[list[dict[str, object]]]:
        from impl.common.l2070_server_plan.steps._compile_versioned import _require_branch_sql_value
        from impl.common.l2100_sql_grammar.tree.clauses import SqlSubqueryTableRef
        from impl.common.l2100_sql_grammar.tree.expr_compound import SqlCast
        from l1000_schema.typed_field import parse_cast_target_type

        source = self._source
        source_is_published_relation = source.source_ref_id is not None
        if source.source_query is not None:
            compiled_source = source.source_query.compile(ctx)
            source_grammar = compiled_source.grammar
            assert source_grammar is not None
            source_auxiliary_ctes = compiled_source.auxiliary_ctes
            from impl.common.l2100_sql_grammar.domain.versioning.policy_dispatched_read import (
                SqlPolicyDispatchedRead,
            )

            if isinstance(source_grammar, SqlPolicyDispatchedRead):
                source_grammar = source_grammar.as_policy_dispatch_relation()
        else:
            from l2070_batching.compilation import CteReference

            assert source.source_ref_id is not None
            source_cte = ctx.cte_refs.get(str(source.source_ref_id))
            assert isinstance(source_cte, CteReference), "Native eligibility source must publish one SQL relation"
            source_grammar = SqlTableIdent(SqlTableName(source_cte.ref_id))
            source_auxiliary_ctes = () if source_cte.auxiliary_query is None else ((source_cte.ref_id, source_cte.auxiliary_query),)
        table = vector_source_table_name(source.model_cls)
        branch_ref = str(source.branch_ref_id) if source.branch_ref_id is not None else None
        is_versioned = issubclass(source.model_cls, VersionedObjectRow)
        branch_expression: SqlRenderable = SqlParam(None)
        if is_versioned:
            if source.branch_id is not None:
                branch_expression = SqlParam(source.branch_id)
            elif source.revision_id is not None:
                branch_expression = SqlParam(None)
            else:
                branch_id, branch_cte = _compile_branch_inputs(ctx, branch_ref)
                branch = _effective_branch_id(ctx, branch_id, branch_cte, branch_ref_id=branch_ref)
                branch_expression = _require_branch_sql_value(ctx, branch)
        s, r, v, a, m, metadata = (SqlAliasName(name) for name in ("visible", "ref", "vec", "artifact", "member", "metadata"))

        def column(alias: SqlAliasName, name: str) -> SqlColumnRef:
            return SqlColumnRef(SqlColumnName(name), qualifier=alias)

        def equals(left: SqlRenderable, right: SqlRenderable) -> SqlBinaryOp:
            return SqlBinaryOp(left, BinaryOp.EQ, right)

        from impl.common.l2070_server_plan.steps._permission_filter import get_column_masking_info
        from impl.common.l2070_server_plan.steps._compile_helpers import (
            session_id_expr,
            session_user_id_expr,
        )
        from l1000_schema.schema_def import get_db_column_name
        from l1300_session.session import SessionId
        from l5200_vector_index.embedding_content_hash import get_embedding_source_fields

        catalog_models = None if ctx.planning_catalog is None else ctx.planning_catalog.tables.keys()
        masking = get_column_masking_info(source.model_cls, None, catalog_models=catalog_models)
        owner_filter: SqlRenderable | None = None
        if masking is not None:
            owner_field, private_fields = masking
            source_fields = get_embedding_source_fields(source.model_cls, str(source.index_name))
            if not set(private_fields).isdisjoint(source_fields):
                owner_filter = (
                    SqlParam(False)
                    if ctx.session_id is None
                    else SqlBinaryOp(
                        (
                            SqlParam(True)
                            if ctx.system_authority is not None
                            else equals(
                                session_id_expr(ctx.session_id, ctx),
                                SqlParam(SessionId.schema()),
                            )
                        ),
                        BinaryOp.OR,
                        equals(
                            column(
                                s,
                                get_db_column_name(source.model_cls, DynamicFieldName(owner_field)),
                            ),
                            session_user_id_expr(ctx.session_id, ctx),
                        ),
                    )
                )
        from impl.common.l2070_server_plan.steps.search_compile_shared import (
            visible_embedding_content_digest,
        )
        from impl.common.l2100_sql_grammar.domain.infra.expr_primitives import SqlDigestSliceBigInt

        config = get_vector_config(source.model_cls, str(source.index_name))
        assert config is not None
        digest = visible_embedding_content_digest(source.model_cls, source.index_name, s, metadata)
        tip_ref_scope = sql_and(
            SqlIsNull(column(r, "revision_id")),
            equals(column(r, "branch_id"), branch_expression) if is_versioned else SqlIsNull(column(r, "branch_id")),
        )
        # Pending rows have no revision. Their branch-scoped refs become historical at commit.
        ref_scope = (
            sql_or(
                sql_and(
                    equals(column(r, "revision_id"), column(s, "sys_revision_id")),
                    SqlIsNull(column(r, "branch_id")),
                ),
                sql_and(SqlIsNull(column(s, "sys_revision_id")), tip_ref_scope),
            )
            if config.indexes_all_revisions
            else tip_ref_scope
        )
        queries: list[SqlRenderable] = []
        scopes = (False,) if config.indexes_all_revisions or not is_versioned else (False, True)
        stores = [(vector_table, ref_table, whole) for vector_table, ref_table in self._stores() for whole in scopes]
        for vector_table, ref_table, whole in stores:
            queries.append(
                SqlSelect(
                    select=SqlSelectList(
                        [
                            SqlSelectAlias(column(s, "sys_id"), SqlAliasName("object_id")),
                            SqlSelectAlias(branch_expression, SqlAliasName("branch_id")),
                            SqlSelectAlias(
                                column(s, "sys_revision_id") if is_versioned else SqlParam(None),
                                SqlAliasName("revision_id"),
                            ),
                            SqlSelectAlias(column(m, "native_key"), SqlAliasName("native_key")),
                            *(
                                []
                                if is_versioned
                                else [
                                    SqlSelectAlias(column(r, "chunk_id"), SqlAliasName("chunk_id")),
                                    SqlSelectAlias(
                                        SqlCast(
                                            column(r, "chunk_metadata"),
                                            parse_cast_target_type("TEXT"),
                                        ),
                                        SqlAliasName("chunk_metadata"),
                                    ),
                                ]
                            ),
                        ]
                    ),
                    from_=(
                        SqlTableAlias(source_grammar, s)
                        if is_versioned or source_is_published_relation
                        else SqlSubqueryTableRef(source_grammar, SqlTableName(str(s)))
                    ),
                    where=owner_filter,
                    joins=[
                        *(
                            []
                            if whole
                            else [
                                SqlJoin(
                                    JoinKind.INNER,
                                    SqlTableAlias(SqlTableIdent(SqlTableName(ref_table)), r),
                                    sql_and(
                                        equals(column(r, "source_id"), column(s, "sys_id")),
                                        equals(column(r, "source_table"), SqlParam(table)),
                                        equals(
                                            column(r, "field_name"),
                                            SqlParam(str(source.index_name)),
                                        ),
                                        ref_scope,
                                    ),
                                )
                            ]
                        ),
                        SqlJoin(
                            JoinKind.INNER,
                            SqlTableAlias(SqlTableIdent(SqlTableName("sys_embedding_metadata")), metadata),
                            sql_and(
                                equals(column(metadata, "table_name"), SqlParam(table)),
                                equals(column(metadata, "field_name"), SqlParam(str(source.index_name))),
                            ),
                        ),
                        SqlJoin(
                            JoinKind.INNER,
                            SqlTableAlias(SqlTableIdent(SqlTableName(vector_table)), v),
                            sql_and(
                                equals(
                                    column(v, "content_hash_short"),
                                    SqlDigestSliceBigInt(digest, 0) if whole else column(r, "content_hash_short"),
                                ),
                                equals(
                                    column(v, "content_hash_high"),
                                    SqlDigestSliceBigInt(digest, 8) if whole else column(r, "content_hash_high"),
                                ),
                                embedding_metadata_model_condition(v, metadata),
                            ),
                        ),
                        SqlJoin(
                            JoinKind.LEFT,
                            SqlTableAlias(SqlTableIdent(SqlTableName(get_usearch_index_table_name(table))), a),
                            sql_and(
                                equals(column(a, "field_name"), SqlParam(str(source.index_name))),
                                SqlIsNull(column(a, "branch_id")),
                                SqlIsNull(column(a, "revision_id")),
                            ),
                        ),
                        SqlJoin(
                            JoinKind.LEFT,
                            SqlTableAlias(SqlTableIdent(SqlTableName("sys_usearch_artifact_members")), m),
                            sql_and(
                                equals(column(m, "artifact_id"), column(a, "sys_id")),
                                equals(column(m, "embedding_vector_id"), column(v, "sys_id")),
                            ),
                        ),
                    ],
                )
            )
        if not queries:
            raise ValueError("Native eligibility requires registered embedding storage")
        shape, relation, hints = compiled_artifacts_from_cte_publication_contract(self.cte_publication_contract())
        return CompiledStep(
            output_shape=shape,
            result_relation=relation,
            column_type_hints=hints,
            grammar=bounded_usearch_eligibility(
                queries[0] if len(queries) == 1 else SqlUnionDistinct(tuple(queries)),
                self._limits,
                include_chunks=not is_versioned,
            ),
            needs_returning=True,
            closed_post_op=row_dicts_post_op(),
            auxiliary_ctes=source_auxiliary_ctes,
        )


def lower_single_branch_usearch(
    *,
    ref_id: ServerPlanRefId,
    model_cls: type[DatabaseObjectRow],
    query_spec: QuerySpec,
    ctx: LoweringContext,
    branch_ref_id: ServerPlanRefId | None,
    user_id_ref_id: ServerPlanRefId | None,
) -> list[ServerPlanStep[Any]]:
    from dataclasses import replace
    from impl.common.l2070_server_plan.search_prereq_utils import query_spec_requests_vector_chunks
    from l5200_vector_index.cross_branch_vector_provider import _coerce_sql_table_hnsw_query_vector

    index = query_spec.search_op.vector_index_name
    query = query_spec.search_op.vector_query_vec
    assert index is not None and query is not None
    source_ref = ServerPlanRefId(f"{ref_id}_visible")
    eligibility_ref = ServerPlanRefId(f"{ref_id}_eligible")
    artifact_ref = ServerPlanRefId(f"{ref_id}_artifact")
    spool_ref = ServerPlanRefId(f"{ref_id}_spool")
    revision_id = ctx.explicit_revision_id
    source_spec = replace(
        query_spec,
        search=SearchOp(mode="none"),
        limit=None,
        offset=0,
        order_by=[],
        select_columns=None,
    )
    if issubclass(model_cls, VersionedObjectRow):
        steps = build_versioned_query_from_spec_steps(
            ref_id=source_ref,
            model_cls=model_cls,
            config=_VersionedQueryFromSpecConfig(
                query_spec=source_spec,
                branch_id=ctx.branch_id,
                branch_ref_id=branch_ref_id,
                revision_id=RevisionId(revision_id) if revision_id is not None else None,
                user_id_ref_id=user_id_ref_id,
                raw_mode=True,
                prefer_current_tip=True,
                after_refs=(
                    frozenset({ctx.lazy_branch_tip_materialization.ref_id})
                    if not ctx.is_write_transaction
                    and ctx.lazy_branch_tip_materialization is not None
                    and ctx.lazy_branch_tip_materialization.ref_id is not None
                    else frozenset()
                ),
            ),
        )
        source_steps = steps[-1].lower(ctx)
    else:
        from impl.common.l2070_server_plan.steps.query_execute import (
            QueryExecuteStep,
            _QueryExecuteStepConfig,
        )

        steps = []
        source_steps = [
            QueryExecuteStep(
                source_ref,
                model_cls,
                _QueryExecuteStepConfig(query_spec=source_spec, user_id_ref_id=user_id_ref_id),
            )
        ]
    limits = get_usearch_request_limits()
    return [
        *steps[:-1],
        *source_steps[:-1],
        _SingleBranchUSearchEligibilityStep(
            eligibility_ref,
            source=_VisibleVectorSource(model_cls, SqlIndexName(index), source_steps[-1], branch_ref_id),
            limits=limits,
            planning_catalog=ctx.planning_catalog,
        ),
        _CrossBranchUSearchArtifactStep(artifact_ref, model_cls=model_cls, index_name=SqlIndexName(index), limits=limits),
        _usearch_native_spool_step(
            ctx,
            spool_ref,
            artifact_ref_id=artifact_ref,
            eligibility_ref_id=eligibility_ref,
            identity_scope=(
                _NativeIdentityScope.VERSIONED if issubclass(model_cls, VersionedObjectRow) else _NativeIdentityScope.UNVERSIONED
            ),
            query_vector=_CrossBranchUSearchQueryVector.for_index(
                model_cls, SqlIndexName(index), tuple(_coerce_sql_table_hnsw_query_vector(query))
            ),
            limits=limits,
        ),
        _CrossBranchUSearchSpoolReaderStep(
            ref_id,
            spool_ref_id=spool_ref,
            threshold=query_spec.search_op.vector_threshold,
            candidate_limit=None,
            unversioned=not issubclass(model_cls, VersionedObjectRow),
            include_chunks=query_spec_requests_vector_chunks(query_spec),
        ),
    ]

"""SelectOneRawStep: raw-row variant of ``SelectOneStep`` semantics."""

from __future__ import annotations

from dataclasses import dataclass, replace
from typing import TYPE_CHECKING, Any, cast

from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName, SqlCteStepName
from impl.common.l2060_query_spec.query_spec import QueryPermissionState
from l1000_schema.large_column import get_large_column_configs, large_column_pointer_name
from l1000_schema.column_utils import get_db_column_name
from l1100_exceptions.exceptions import ProgrammingError
from l1300_session.session import SessionId
from l1400_types import DynamicFieldName, ServerPlanRefId
from l2070_batching.cardinality import Cardinality
from l2070_batching.compilation import CompilationContext, CompiledStep, compiled_artifacts_from_cte_publication_contract
from l2070_batching.output_shape import DeclaredResultRelation
from l2070_batching.server_ref import ScalarServerRef as _ScalarServerRef
from l2070_batching.sql_column_type_hints import SqlColumnTypeHints, model_sql_column_type_hints
from l2070_batching.step import (
    ServerPlanStep,
    StaleCtePublicationContractError,
    ContractedSqlProducerStep,
    SqlRelationPublisherStep,
    CtePublicationContract,
)
from l2070_batching.write_column_policy import select_one_default_columns

if TYPE_CHECKING:
    from l4000_permissions.session_context import ResolvedSessionContext
    from impl.common.l2100_sql_grammar.protocols import SqlRenderable
    from l1000_schema.schema_def import DatabaseObjectRow
    from l1400_types import SysId
    from l2070_batching.compilation import CompilationContext, ResolvedRefs
    from l2070_batching.server_ref import ScalarServerRef


class SelectOneProjectionColumn(str):
    """Projection column name carried through select-one raw plan state."""


@dataclass(frozen=True, slots=True)
class SelectOneRawConfig:
    sys_id: ScalarServerRef[SysId]
    permission_grammar: SqlRenderable | None = None
    column_masking: tuple[SqlColumnName, list[SqlColumnName]] | None = None
    session_id_str: SessionId | None = None
    permission_bypass: bool = False
    after_refs: frozenset[ServerPlanRefId] = frozenset()
    projection_columns: tuple[SelectOneProjectionColumn, ...] | None = None


class SelectOneRawStep(SqlRelationPublisherStep[list[dict[str, Any]]]):
    """Select a single row by ``sys_id`` and return plain dict rows."""

    optimizer_projection_owned = True

    def __init__(
        self: SelectOneRawStep,
        ref_id: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        sys_id: object,
        *,
        permission_grammar: SqlRenderable | None = None,
        column_masking: tuple[SqlColumnName, list[SqlColumnName]] | None = None,
        session_id_str: SessionId | None = None,
        permission_state_override: QueryPermissionState | None = None,
        after_refs: frozenset[ServerPlanRefId] | None = None,
        projection_columns: tuple[SelectOneProjectionColumn, ...] | None = None,
        permission_context_ref: ServerPlanRefId | None = None,
        permission_context_type: type[ResolvedSessionContext] | None = None,
    ) -> None:
        super().__init__(ref_id)
        self._model_cls = model_cls
        self._sys_id = sys_id
        self._permission_grammar = permission_grammar
        self._column_masking = column_masking
        self._session_id_str = session_id_str
        self._permission_state_override = permission_state_override
        self._permission_bypass = permission_state_override is QueryPermissionState.BYPASS
        self._after_refs = after_refs or frozenset()
        self._permission_context_ref = permission_context_ref
        self._permission_context_type = permission_context_type
        if projection_columns is None:
            columns = list(select_one_default_columns(self._model_cls))
            from l2070_batching.planning_catalog import (
                READ_FLAVOR_QUERY_ROWS,
                build_read_metadata_plan,
            )

            columns.extend(build_read_metadata_plan(self._model_cls).projection_for(READ_FLAVOR_QUERY_ROWS).cte_output_columns)
        else:
            columns = [str(column) for column in projection_columns]
        seen: set[str] = set(columns)
        for config in get_large_column_configs(self._model_cls):
            db_column = large_column_pointer_name(config.column)
            if db_column in seen:
                continue
            seen.add(db_column)
            columns.append(db_column)
        self._cte_output_columns = tuple(dict.fromkeys(columns))
        hints = model_sql_column_type_hints(self._model_cls, self._cte_output_columns)
        if hints is None:
            msg = f"Could not resolve SQL column type hints for {self._model_cls.__name__}"
            raise TypeError(msg)
        self._cte_column_type_hints = hints
        self._cte_metadata_model_cls = self._model_cls

    @property
    def level(self: SelectOneRawStep) -> int:
        return 0

    def step_tags(self: SelectOneRawStep) -> frozenset[str]:
        return frozenset({"read", "select_one", "raw"})

    def is_read_only(self: SelectOneRawStep) -> bool:
        return True

    def supports_ordered_sql_statement_batch(self: SelectOneRawStep) -> bool:
        """Allow a read-after-write lookup in the backend's ordered request batch."""
        return True

    def result_cardinality(self: SelectOneRawStep) -> Cardinality:
        return Cardinality.ONE

    def tables_read(self: SelectOneRawStep) -> frozenset[str]:
        from l1000_schema.table_utils import get_table_name

        return frozenset({get_table_name(self._model_cls)})

    def tables_written(self: SelectOneRawStep) -> frozenset[str]:
        return frozenset()

    def requires_prior_statement_visibility_after_writes(self: SelectOneRawStep) -> frozenset[str]:
        return self.tables_read()

    def cte_publication_contract(self: SelectOneRawStep) -> CtePublicationContract:
        def _legacy_cte_output_columns() -> tuple[str, ...]:
            self._validate_planned_cte_metadata()
            return self._cte_output_columns

        base_columns = _legacy_cte_output_columns()
        if get_large_column_configs(self._model_cls):
            from impl.common.l2070_server_plan.steps.large_column_read import (
                _inline_large_column_output_shape,
            )
            from l2070_batching.output_shape import CompiledOutputShape, synthetic_output_field

            inline_shape = _inline_large_column_output_shape(
                CompiledOutputShape(
                    tuple(synthetic_output_field(column) for column in base_columns),
                ),
                self._model_cls,
                include_pointer_columns=True,
            )
            if inline_shape is None:
                msg = f"{type(self).__name__} could not derive inline large-column output shape."
                raise TypeError(msg)
            pointer_columns = tuple(
                str(large_column_pointer_name(config.column))
                for config in get_large_column_configs(self._model_cls)
                if str(large_column_pointer_name(config.column)) in base_columns
            )
            columns = tuple(dict.fromkeys((*inline_shape.cte_output_columns, *pointer_columns)))
        else:
            columns = base_columns

        def _legacy_cte_column_type_hints(columns: tuple[str, ...] | None) -> SqlColumnTypeHints:
            self._validate_planned_cte_metadata()
            if get_large_column_configs(self._model_cls):
                from impl.common.l2070_server_plan.steps.large_column_transport_contract import (
                    large_column_transport_type_hints,
                    selected_large_column_transport_columns,
                )
                from l1000_schema.large_column import large_column_pointer_name
                from l2070_batching.sql_column_type_hints import combine_sql_column_type_hints

                large_columns = selected_large_column_transport_columns(self._model_cls, base_columns)
                return combine_sql_column_type_hints(
                    columns or (),
                    self._cte_column_type_hints.filtered(set(base_columns)),
                    large_column_transport_type_hints(large_columns),
                )
            return self._cte_column_type_hints

        column_type_hints = _legacy_cte_column_type_hints(columns)
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        _contract_model_cls = self._model_cls
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        normalized_columns = tuple(str(column) for column in columns)
        from l2070_batching.cte_contracts import projection_over_model_contract

        return projection_over_model_contract(
            columns=normalized_columns,
            column_type_hints=column_type_hints,
            source_model_cls=_contract_model_cls,
            projection_lineage=tuple((column, column) for column in normalized_columns),
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
            optional_columns=frozenset(normalized_columns) - {"sys_id"},
            empty_result_allowed=True,
        )

    def semantic_publication_columns(self: SelectOneRawStep) -> tuple[str, ...] | None:
        if get_large_column_configs(self._model_cls):
            from impl.common.l2100_sql_grammar.domain.infra.stmt_inline_large_columns import (
                inline_large_column_transport_column_groups,
            )

            pointer_columns = {
                str(get_db_column_name(self._model_cls, DynamicFieldName(large_column_pointer_name(config.column))))
                for config in get_large_column_configs(self._model_cls)
            }
            contract_columns = set(self.cte_publication_contract().columns)
            inline_columns = {
                logical_column
                for logical_column, _pointer_column, transport_columns in inline_large_column_transport_column_groups(
                    self._model_cls,
                )
                if contract_columns.intersection(transport_columns)
            }
            return tuple(
                dict.fromkeys(
                    (
                        *(column for column in self._cte_output_columns if column not in pointer_columns),
                        *inline_columns,
                    ),
                ),
            )
        if not getattr(
            self._model_cls,
            "__polymorphic__",
            False,
        ):
            return None
        return tuple(
            str(get_db_column_name(self._model_cls, DynamicFieldName(field_name))) for field_name in self._model_cls.model_fields
        )

    def semantic_publication_type_hints(self: SelectOneRawStep) -> SqlColumnTypeHints | None:
        if get_large_column_configs(self._model_cls):
            columns = self.semantic_publication_columns()
            return model_sql_column_type_hints(self._model_cls, columns or ())
        columns = self.semantic_publication_columns()
        if columns is None:
            return None
        return model_sql_column_type_hints(self._model_cls, columns)

    def _validate_planned_cte_metadata(self: SelectOneRawStep) -> None:
        if self._model_cls is self._cte_metadata_model_cls:
            return
        msg = f"{type(self).__name__} planned CTE metadata is stale. The model source changed after step construction."
        raise StaleCtePublicationContractError(msg)

    def runtime_publication_transport_columns(self) -> frozenset[str]:
        return frozenset(str(large_column_pointer_name(config.column)) for config in get_large_column_configs(self._model_cls))

    def always_publishes_executor_visible_binding(self: SelectOneRawStep) -> bool:
        return True

    def dependencies(self: SelectOneRawStep) -> frozenset[str]:
        return frozenset(
            {
                *(tuple(str(dep) for dep in self._sys_id.dependencies()) if isinstance(self._sys_id, _ScalarServerRef) else ()),
                *tuple(str(dep) for dep in self._after_refs),
                *(() if self._permission_context_ref is None else (str(self._permission_context_ref),)),
            },
        )

    def sql_visible_dependencies(self: SelectOneRawStep) -> frozenset[str]:
        if not isinstance(self._sys_id, _ScalarServerRef):
            return frozenset()
        return frozenset(str(dep) for dep in self._sys_id.dependencies())

    def preprocess(self: SelectOneRawStep, resolved: ResolvedRefs) -> None:
        del resolved

    def compile(self: SelectOneRawStep, ctx: CompilationContext) -> CompiledStep[list[dict[str, Any]]]:
        if ctx.planning_catalog is None:
            msg = "SelectOneRawStep compile requires a PlanningCatalog."
            # Raw select lowering must use explicit planning metadata.
            raise ProgrammingError(msg)
        if self._permission_grammar is None and self._column_masking is None and self._permission_context_ref is None:
            from impl.common.l2070_server_plan.steps._compile_server_ref import (
                get_scalar_server_ref_binding,
                lower_scalar_server_ref,
            )
            from impl.common.l2070_server_plan.steps._auxiliary_ctes import (
                collect_dependency_auxiliary_ctes,
            )
            from impl.common.l2070_server_plan.steps.large_column_read import (
                build_select_one_query_spec,
                inline_large_column_query_post_op,
                wrap_compiled_sql_with_inline_large_columns,
            )
            from impl.common.l2050_sql_types.sql_branded_types import SqlCteName, SqlTableName
            from impl.common.l2100_sql_grammar.domain.infra.stmt_dml_simple import (
                SqlCteInSubqueryRef,
            )
            from impl.common.l2100_sql_grammar.tree.clauses import (
                SqlFrom,
                SqlSelectList,
                SqlWhereClause,
            )
            from impl.common.l2100_sql_grammar.tree.enums import BinaryOp
            from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlParam
            from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp, SqlIn
            from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
            from impl.common.l2100_sql_grammar.tree.statements import SqlSelect
            from l1000_schema.schema_def import get_db_column_name
            from l1000_schema.table_utils import get_table_name
            from l2070_batching.output_shape import CompiledOutputShape, synthetic_output_field

            sys_id_col = SqlColumnRef(SqlColumnName(get_db_column_name(self._model_cls, DynamicFieldName("sys_id"))))
            sys_id_binding = get_scalar_server_ref_binding(self._sys_id, ctx) if isinstance(self._sys_id, _ScalarServerRef) else None
            sys_id_predicate = (
                SqlIn(
                    sys_id_col,
                    SqlCteInSubqueryRef(
                        SqlCteStepName(sys_id_binding.cte_name),
                        SqlColumnName(sys_id_binding.field_name),
                        postgres_cast="::uuid",
                    ),
                )
                if sys_id_binding is not None
                else SqlBinaryOp(
                    sys_id_col,
                    BinaryOp.EQ,
                    (
                        lower_scalar_server_ref(self._sys_id, ctx)
                        if isinstance(self._sys_id, _ScalarServerRef)
                        else SqlParam(self._sys_id)
                    ),
                )
            )
            source_table_name = SqlTableName(get_table_name(self._model_cls))
            multitable_auxiliary_ctes: list[tuple[str, SqlRenderable]] = []
            read_shape = ctx.planning_catalog.read_metadata_for_model(self._model_cls)
            from l2070_batching.planning_catalog import READ_FLAVOR_QUERY_ROWS

            projection = read_shape.projection_for(READ_FLAVOR_QUERY_ROWS)
            output_columns = tuple(dict.fromkeys(field.cte_output_column for field in projection.fields))
            if read_shape.multitable_source_models:
                from impl.common.l2100_sql_grammar.domain.polymorphism.multitable_cte import (
                    build_multitable_polymorphic_cte_definition,
                    build_multitable_polymorphic_cte_name,
                )

                cte_name = build_multitable_polymorphic_cte_name(source_table_name)
                cte_definition = build_multitable_polymorphic_cte_definition(
                    self._model_cls,
                    read_shape.multitable_source_models,
                    cte_name=SqlCteName(cte_name),
                    read_projection=projection,
                )
                if cte_definition is not None:
                    source_table_name = SqlTableName(cte_name)
                    output_columns = tuple(dict.fromkeys(field.cte_output_column for field in projection.fields))
                    multitable_auxiliary_ctes.append(cte_definition)
            if get_large_column_configs(self._model_cls):
                from l1000_schema.large_column import large_column_pointer_name

                output_columns = tuple(
                    dict.fromkeys(
                        (
                            *output_columns,
                            *(
                                str(get_db_column_name(self._model_cls, DynamicFieldName(large_column_pointer_name(config.column))))
                                for config in get_large_column_configs(self._model_cls)
                            ),
                        ),
                    ),
                )
            grammar = SqlSelect(
                select=SqlSelectList(
                    [SqlColumnRef(SqlColumnName(column)) for column in output_columns],
                ),
                from_clause=SqlFrom(SqlTableIdent(source_table_name)),
                where=SqlWhereClause(sys_id_predicate),
                limit=1,
            )
            query_spec = build_select_one_query_spec(
                self._model_cls,
                sys_id=self._sys_id,
                permission_grammar=None,
                permission_state_override=self._permission_state_override,
                permission_context_ref=self._permission_context_ref,
                permission_context_type=self._permission_context_type,
            )
            output_shape = CompiledOutputShape(
                tuple(synthetic_output_field(column) for column in output_columns),
            )
            from l2070_batching.sql_column_type_hints import combine_sql_column_type_hints

            hint_sources = tuple(
                hints
                for source_model in (self._model_cls, *read_shape.multitable_source_models)
                if (hints := model_sql_column_type_hints(source_model, output_shape.cte_output_columns)) is not None
            )
            column_type_hints = combine_sql_column_type_hints(
                output_shape.cte_output_columns,
                *hint_sources,
            )
            column_type_hints.require_complete(output_shape.cte_output_columns)
            self._cte_output_columns = output_shape.cte_output_columns
            self._cte_column_type_hints = column_type_hints
            self._cte_publication_contract_cache_valid = False
            self._publication_contract_cache_valid = False
            compiled: CompiledStep[Any] = CompiledStep(
                grammar=grammar,
                needs_returning=True,
                auxiliary_ctes=(
                    *multitable_auxiliary_ctes,
                    *(collect_dependency_auxiliary_ctes(ctx, self.sql_visible_dependencies()) or ()),
                ),
                output_shape=output_shape,
                result_relation=DeclaredResultRelation.from_output_shape(output_shape),
                column_type_hints=column_type_hints,
                closed_post_op=inline_large_column_query_post_op(
                    model_cls=self._model_cls,
                    query_spec=query_spec,
                    result_mode="many",
                    raw_mode=True,
                    projected_columns=(None if get_large_column_configs(self._model_cls) else output_columns),
                ),
            )
            return cast(
                "CompiledStep[list[dict[str, Any]]]",
                wrap_compiled_sql_with_inline_large_columns(
                    compiled,
                    model_cls=self._model_cls,
                ),
            )
        from impl.common.l2070_server_plan.steps._query_helper_compile import (
            build_select_one_column_masking_select,
        )
        from impl.common.l2070_server_plan.steps.large_column_read import build_select_one_query_spec
        from impl.common.l2070_server_plan.steps.query_execute_raw import (
            QueryExecuteRawStep,
            _QueryExecuteRawStepConfig,
        )
        from impl.common.l2100_sql_grammar.tree.statements import SqlSelect
        from impl.common.l2200_sql_dialect.sql_connection import AttributedSqlRenderable

        query_spec = build_select_one_query_spec(
            self._model_cls,
            sys_id=self._sys_id,
            permission_grammar=self._permission_grammar,
            permission_state_override=self._permission_state_override,
            permission_context_ref=self._permission_context_ref,
            permission_context_type=self._permission_context_type,
        )
        compiled = QueryExecuteRawStep[list[dict[str, Any]]](
            self.ref_id,
            self._model_cls,
            _QueryExecuteRawStepConfig(
                query_spec=query_spec,
                hydrate_large_columns=True,
            ),
        ).compile(ctx)
        fallback_grammar: SqlRenderable | None = compiled.grammar
        prerender_info = None
        if isinstance(fallback_grammar, AttributedSqlRenderable):
            prerender_info = fallback_grammar.prerender_info
            fallback_grammar = fallback_grammar.inner
        if not isinstance(fallback_grammar, SqlSelect):
            return cast("CompiledStep[list[dict[str, Any]]]", compiled)
        stmt = fallback_grammar
        compiled_columns = compiled.output_shape.cte_output_columns if compiled.output_shape is not None else self._cte_output_columns
        self._cte_output_columns = tuple(compiled_columns)
        if compiled.column_type_hints is not None:
            self._cte_column_type_hints = compiled.column_type_hints
        self._cte_publication_contract_cache_valid = False
        self._publication_contract_cache_valid = False
        select_list: SqlRenderable
        if self._column_masking is None:
            from impl.common.l2100_sql_grammar.tree.clauses import SqlSelectList
            from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef

            select_list = SqlSelectList(
                [SqlColumnRef(SqlColumnName(column)) for column in compiled_columns],
            )
        else:
            select_list = build_select_one_column_masking_select(
                self._model_cls,
                self._column_masking,
                session_id_str=self._session_id_str,
                output_columns=compiled_columns,
            )
        masked_stmt = SqlSelect(
            select=select_list,
            from_clause=stmt._from,
            joins=stmt._joins,
            where=stmt._where,
            group_by=stmt._group_by,
            having=stmt._having,
            order_by=stmt._order_by,
            limit=stmt._limit,
            offset=stmt._offset,
            for_update=stmt._for_update,
            distinct=stmt._distinct,
            as_of=stmt._as_of,
        )
        masked_grammar = (
            AttributedSqlRenderable(inner=masked_stmt, prerender_info=prerender_info) if prerender_info is not None else masked_stmt
        )
        contract = self.cte_publication_contract()
        output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(
            contract,
        )
        return cast(
            "CompiledStep[list[dict[str, Any]]]",
            replace(
                compiled,
                grammar=masked_grammar,
                output_shape=output_shape,
                result_relation=result_relation,
                column_type_hints=column_type_hints,
            ),
        )

