_SQL_PAIR_EXISTS_PREFIX = SqlFragment.static(
    "SELECT COUNT(*) AS pair_count FROM sys_fts_content_hashes WHERE hash_short = ",
)
_SQL_AND_HASH_HIGH = SqlFragment.static(" AND hash_high = ")
_SQL_UPSERT_COLLISION_PREFIX = SqlFragment.static(
    "INSERT INTO sys_fts_collision_shorts (sys_id, hash_short, collision_count, first_seen_at, last_seen_at) SELECT ",
)
_SQL_UPSERT_COLLISION_MIDDLE = SqlFragment.static(
    ", hash_short, COUNT(DISTINCT hash_high), CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM sys_fts_content_hashes WHERE hash_short = ",
)
_SQL_UPSERT_COLLISION_SUFFIX = SqlFragment.static(
    " GROUP BY hash_short HAVING COUNT(DISTINCT hash_high) > 1 "
    "ON CONFLICT(hash_short) DO UPDATE SET "
    "collision_count = excluded.collision_count, "
    "last_seen_at = excluded.last_seen_at",
)
_SQL_UPSERT_COLLISION_MYSQL_SUFFIX = SqlFragment.static(
    " GROUP BY hash_short HAVING COUNT(DISTINCT hash_high) > 1 "
    "ON DUPLICATE KEY UPDATE "
    "collision_count = VALUES(collision_count), "
    "last_seen_at = VALUES(last_seen_at)"
)
_SQL_DISTINCT_COUNT_PREFIX = SqlFragment.static(
    "SELECT COUNT(DISTINCT hash_high) AS collision_count FROM sys_fts_content_hashes WHERE hash_short = ",
)
_SQL_COLLISION_SHORTS = SqlFragment.static("SELECT hash_short FROM sys_fts_collision_shorts")
_SQL_COLLISION_STATS = SqlFragment.static(
    "SELECT COUNT(*) AS total_collision_shorts, "
    "COALESCE(SUM(collision_count), 0) AS total_colliding_hashes, "
    "COALESCE(MAX(collision_count), 0) AS max_collision_depth "
    "FROM sys_fts_collision_shorts",
)


