class _SqlFtsPairExists(SqlRenderable):
    def __init__(self: _SqlFtsPairExists, hash_short: SqlParam, hash_high: SqlParam) -> None:
        self._hash_short = hash_short
        self._hash_high = hash_high

    def render(self: _SqlFtsPairExists, dialect: SqlDialect) -> SqlFragment:
        return _SQL_PAIR_EXISTS_PREFIX + self._hash_short.render(dialect) + _SQL_AND_HASH_HIGH + self._hash_high.render(dialect)


class _SqlFtsUpsertCollisionShort(SqlRenderable):
    def __init__(
        self: _SqlFtsUpsertCollisionShort,
        hash_short: SqlParam,
        collision_sys_id: SqlParam,
    ) -> None:
        self._hash_short = hash_short
        self._collision_sys_id = collision_sys_id

    def render(self: _SqlFtsUpsertCollisionShort, dialect: SqlDialect) -> SqlFragment:
        suffix = _SQL_UPSERT_COLLISION_MYSQL_SUFFIX if dialect.uses_on_duplicate_key_syntax() else _SQL_UPSERT_COLLISION_SUFFIX
        return (
            _SQL_UPSERT_COLLISION_PREFIX
            + self._collision_sys_id.render(dialect)
            + _SQL_UPSERT_COLLISION_MIDDLE
            + self._hash_short.render(dialect)
            + suffix
        )


class _SqlFtsDistinctCount(SqlRenderable):
    def __init__(self: _SqlFtsDistinctCount, hash_short: SqlParam) -> None:
        self._hash_short = hash_short

    def render(self: _SqlFtsDistinctCount, dialect: SqlDialect) -> SqlFragment:
        return _SQL_DISTINCT_COUNT_PREFIX + self._hash_short.render(dialect)


class _SqlFtsCollisionShorts(SqlRenderable):
    def render(self: _SqlFtsCollisionShorts, dialect: SqlDialect) -> SqlFragment:
        del dialect
        return _SQL_COLLISION_SHORTS


class _SqlFtsCollisionStats(SqlRenderable):
    def render(self: _SqlFtsCollisionStats, dialect: SqlDialect) -> SqlFragment:
        del dialect
        return _SQL_COLLISION_STATS


