    queued: bool = False


@dataclass(slots=True)
class _HookPostCommitEffect(PipelineLifecycleEffect):
    hook_registry: HookRegistry
    payload: _HookEffectRuntimePayload | None
    run_state: _HookEffectRunState
    ran: bool = False
    phase: PipelineLifecyclePhase = field(
        default=PipelineLifecyclePhase.AFTER_COMMIT_LOCAL,
        init=False,
    )

    def apply(self) -> None:
        if self.ran or self.run_state.ran:
            return
        self.ran = True
        self.run_state.ran = True
        if self.payload is None:
            return
        self.hook_registry.run_write_effect(
            self.payload.model,
            self.payload.effect_name,
            self.payload.values,
        )


def _hook_registry_from_txn(txn: object | None) -> HookRegistry | None:
    plan = getattr(txn, "_plan", None)
    if plan is None:
        plan_scope_plan = getattr(txn, "plan_scope_plan", None)
        if callable(plan_scope_plan):
            plan = plan_scope_plan()
    hook_registry = getattr(plan, "_auto_api_hook_registry", None)
    return hook_registry if isinstance(hook_registry, HookRegistry) else None


@dataclass(frozen=True, slots=True)
class _HookPostCommitEffectFactory:
    model: type[DatabaseObjectRow]
    effect_name: HookEffectName
    run_state: _HookEffectRunState
    hook_registry: HookRegistry | None

    def __call__(self, result: object, runtime_txn: object | None) -> Sequence[_HookPostCommitEffect]:
        if result is None:
            return ()
        values = tuple(cast(Sequence[Any], result))
        if not values:
            return ()
        if not self.run_state.queued or self.run_state.ran:
            self.run_state.queued = True
            self.run_state.ran = False
        hook_registry = self.hook_registry or _hook_registry_from_txn(runtime_txn)
        if hook_registry is None:
            return ()
        payload = _HookEffectRuntimePayload(self.model, self.effect_name, values)
        return (_HookPostCommitEffect(hook_registry, payload, self.run_state),)


def lower_write_effect_steps(
    *,
    ctx: LoweringContext,
    ref_prefix: ServerPlanRefId,
    hook_registry: HookRegistry | None,
    model_cls: type[DatabaseObjectRow],
    operation: WriteOperation,
    old_row_ref: ServerPlanRefId | None,
    new_row_ref: ServerPlanRefId | None,
    old_row_literal: object | None = None,
    new_row_literal: object | None = None,
    after_refs: frozenset[ServerPlanRefId] = frozenset(),
) -> tuple[ServerPlanStep[Any], ...]:
    """Lower registered write effects into plan steps.

    The public hook API produces ``RowSource`` / ``ValueSource`` objects. This
    function is the boundary where those public handles become internal plan refs.
    """
    if hook_registry is None:
        return ()
    descriptors = hook_registry.get_write_effects(model_cls)
    if not descriptors:
        return ()
    steps: list[ServerPlanStep[Any]] = []
    for index, descriptor in enumerate(descriptors):
        value_source = descriptor.dependencies_for(operation)
        compiler = _HookSourceCompiler(
            ctx=ctx,
            ref_prefix=ServerPlanRefId(f"{ref_prefix}.hook_{index}"),
            old_row_ref=old_row_ref,
            new_row_ref=new_row_ref,
        )
        select_steps = compiler.lower_selects(value_source)
        literal_row_map: dict[RowSource[Any], object | None] = {
            RowSource(kind="old", model=model_cls): old_row_literal,
            RowSource(kind="new", model=model_cls): new_row_literal,
        }
        if not select_steps and not compiler.row_ref_map:
            literal_values = _eval_sequence(value_source, {}, literal_row_map, {})
            steps.append(
                RunLiteralPostCommitEffectsStep(
                    ServerPlanRefId(f"{ref_prefix}.hook_{index}.effect"),
                    model=descriptor.model,
                    effect_name=HookEffectName(descriptor.name),
                    values=literal_values,
                    hook_registry=hook_registry,
                ),
            )
            continue
        collect_ref = ServerPlanRefId(f"{ref_prefix}.hook_{index}.values")
        run_ref = ServerPlanRefId(f"{ref_prefix}.hook_{index}.effect")
        steps.extend(select_steps)
        steps.append(
            CollectHookEffectValuesStep(
                collect_ref,
                source=value_source,
                row_ref_map=compiler.row_ref_map,
                literal_row_map=literal_row_map,
                after_refs=after_refs | frozenset(ServerPlanRefId(step.ref_id) for step in select_steps),
            ),
        )
        steps.append(
            RunPostCommitEffectsStep(
                run_ref,
                model=descriptor.model,
                effect_name=HookEffectName(descriptor.name),
                values_ref=collect_ref,
                hook_registry=hook_registry,
            ),
        )
    return tuple(steps)


class _HookSourceCompiler:
    def __init__(
        self: _HookSourceCompiler,
        *,
        ctx: LoweringContext,
        ref_prefix: ServerPlanRefId,
        old_row_ref: ServerPlanRefId | None,
        new_row_ref: ServerPlanRefId | None,
    ) -> None:
        self._ctx = ctx
        self._ref_prefix = str(ref_prefix)
        self._old_row_ref = old_row_ref
        self._new_row_ref = new_row_ref
        self.row_ref_map: dict[RowSource[Any], ServerPlanRefId] = {}
        self._select_steps: list[ServerPlanStep[Any]] = []

    def lower_selects(self: _HookSourceCompiler, source: SequenceSource[Any]) -> tuple[ServerPlanStep[Any], ...]:
        self._visit_sequence(source)
        return tuple(self._select_steps)

    def _visit_sequence(self: _HookSourceCompiler, source: SequenceSource[Any]) -> None:
        for value in source.values:
            self._visit_value(value)
        for child in source.sequences:
            self._visit_sequence(child)
        for change in source.changes:
            self._visit_value(change.old_value)
            self._visit_value(change.new_value)

    def _visit_value(self: _HookSourceCompiler, source: ValueSource[Any]) -> None:
        if source.row is not None:
            self._visit_row(source.row)
        for child in source.sources:
            self._visit_value(child)

    def _visit_row(self: _HookSourceCompiler, source: RowSource[Any]) -> ServerPlanRefId | None:
        existing_ref = self.row_ref_map.get(source)
        if existing_ref is not None:
            return existing_ref
        if source.kind == "old":
            if self._old_row_ref is None:
                return None
            self.row_ref_map[source] = self._old_row_ref
            return self._old_row_ref
        if source.kind == "new":
            if self._new_row_ref is None:
                return None
            self.row_ref_map[source] = self._new_row_ref
            return self._new_row_ref
        if source.kind != "select_one":
            return None
        if source.id_source is None:
            msg = "select_one row source requires id_source"
            raise ValueError(msg)
        source_ref = ServerPlanRefId(f"{self._ref_prefix}.select_{len(self._select_steps)}")
        id_ref = self._compile_scalar_ref(source.id_source)
        self._select_steps.extend(
            SelectOneIntent(
                source_ref,
                source.model,
                cast(ScalarServerRef[SysId], id_ref),
                _SelectOneConfig(permission_bypass=True),
            ).lower(self._ctx),
        )
        self.row_ref_map[source] = source_ref
        return source_ref

    def _compile_scalar_ref(self: _HookSourceCompiler, source: ValueSource[Any]) -> ScalarServerRef[Any]:
        if source.kind == "literal":
            return ServerRefs.scalar(source.value)
        if source.kind == "field" and source.row is not None and source.field_name is not None:
            row_ref = self._visit_row(source.row)
            if row_ref is None:
                msg = f"Cannot compile hook field source {source.field_name!r} without a row ref"
                raise ValueError(msg)
            return cast(
                ScalarServerRef[Any],
                ServerRefs.from_ref_id(ServerPlanRefId(f"{row_ref}.{source.field_name}"), variant="scalar"),
            )
        msg = f"Hook value source {source.kind!r} cannot be compiled as a SQL scalar ref"
        raise NotImplementedError(msg)


class CollectHookEffectValuesStep(NonPublishingStep[tuple[Any, ...]]):
    """Collect resolved public hook sources into ordinary Python values."""

    def __init__(
        self: CollectHookEffectValuesStep,
        ref_id: ServerPlanRefId,
        *,
        source: SequenceSource[Any],
        row_ref_map: Mapping[RowSource[Any], ServerPlanRefId],
        literal_row_map: Mapping[RowSource[Any], object | None] | None = None,
        after_refs: frozenset[ServerPlanRefId] = frozenset(),
    ) -> None:
        super().__init__(ref_id)
        self._source = source
        self._row_ref_map = dict(row_ref_map)
        self._literal_row_map = {} if literal_row_map is None else dict(literal_row_map)
        self._after_refs = after_refs

