def _eval_sequence(
    source: SequenceSource[Any] | _HookSequenceSourceSpec,
    row_ref_map: _RowSourceRuntimeMap[ServerPlanRefId],
    literal_row_map: _RowSourceRuntimeMap[object],
    runtime_refs: Mapping[str, object],
) -> tuple[Any, ...]:
    if source.kind == "values":
        return _distinct_present(_eval_value(value, row_ref_map, literal_row_map, runtime_refs) for value in source.values)
    if source.kind == "concat":
        concatenated_values: list[Any] = []
        for child in source.sequences:
            concatenated_values.extend(_eval_sequence(child, row_ref_map, literal_row_map, runtime_refs))
        return tuple(concatenated_values)
    if source.kind == "distinct":
        if not source.sequences:
            return ()
        return _distinct_present(_eval_sequence(source.sequences[0], row_ref_map, literal_row_map, runtime_refs))
    if source.kind == "changed_values":
        changed_values: list[Any] = []
        for change in source.changes:
            old_value = _eval_value(change.old_value, row_ref_map, literal_row_map, runtime_refs)
            new_value = _eval_value(change.new_value, row_ref_map, literal_row_map, runtime_refs)
            if old_value == new_value:
                continue
            if old_value is None:
                changed_values.append(new_value)
            elif new_value is None:
                changed_values.append(old_value)
            else:
                changed_values.extend((old_value, new_value))
        return _distinct_present(changed_values)
    msg = f"Unsupported hook sequence source {source.kind!r}"
    raise NotImplementedError(msg)


def _coerce_literal_row_map(value: object) -> _RowSourceRuntimeMap[object]:
    if isinstance(value, Mapping):
        return cast("Mapping[str, object]", value)
    if isinstance(value, tuple):
        assert all(isinstance(item, tuple) and len(item) == 2 and isinstance(item[0], str) for item in value)
        return {item[0]: item[1] for item in value if isinstance(item, tuple) and len(item) == 2 and isinstance(item[0], str)}
    return {}


def _eval_value(
    source: ValueSource[Any] | _HookValueSourceSpec,
    row_ref_map: _RowSourceRuntimeMap[ServerPlanRefId],
    literal_row_map: _RowSourceRuntimeMap[object],
    runtime_refs: Mapping[str, object],
) -> Any:
    if source.kind == "literal":
        return source.value
    if source.kind == "coalesce":
        for child in source.sources:
            value = _eval_value(child, row_ref_map, literal_row_map, runtime_refs)
            if value is not None:
                return value
        return None
    if source.kind == "field" and source.row is not None and source.field_name is not None:
        row_ref = _lookup_row_mapping(row_ref_map, source.row)
        row = None
        if row_ref is not None:
            row = _coerce_one_row(_runtime_ref_value(runtime_refs, str(row_ref)))
        if row is None:
            row = _lookup_row_mapping(literal_row_map, source.row)
        if row is None:
            return None
        if isinstance(row, Mapping):
            return row.get(source.field_name)
        return getattr(row, source.field_name, None)
    msg = f"Unsupported hook value source {source.kind!r}"
    raise NotImplementedError(msg)


def _lookup_row_mapping[T](
    mapping: Mapping[RowSource[Any], T] | Mapping[str, T],
    source: RowSource[Any] | _HookRowSourceSpec,
) -> T | None:
    row_mapping = cast("Mapping[RowSource[Any], T]", mapping)
    if isinstance(source, RowSource):
        value = row_mapping.get(source)
        if value is not None:
            return value
    str_mapping = cast("Mapping[str, T]", mapping)
    return str_mapping.get(_row_source_lookup_key(source))


def _safe_row_source_map[T](mapping: Mapping[RowSource[Any], T]) -> dict[str, T]:
    return {_row_source_key(source): value for source, value in mapping.items()}


def _row_source_lookup_key(source: RowSource[Any] | _HookRowSourceSpec) -> str:
    if isinstance(source, _HookRowSourceSpec):
        return source.row_key
    return _row_source_key(source)


def _row_source_key(source: RowSource[Any]) -> str:
    if source.kind in {"old", "new"}:
        row_kind: str = source.kind
        return row_kind
    if source.kind == "select_one":
        return f"select:{abs(hash(source))}"
    return f"unknown:{abs(hash(source))}"


def _sequence_source_spec(source: SequenceSource[Any]) -> _HookSequenceSourceSpec:
    return _HookSequenceSourceSpec(
        kind=source.kind,
        values=tuple(_value_source_spec(value) for value in source.values),
        sequences=tuple(_sequence_source_spec(sequence) for sequence in source.sequences),
        changes=tuple(
            _HookChangeSourceSpec(
                field_name=change.field_name,
                old_value=_value_source_spec(change.old_value),
                new_value=_value_source_spec(change.new_value),
            )
            for change in source.changes
        ),
    )


def _value_source_spec(source: ValueSource[Any]) -> _HookValueSourceSpec:
    return _HookValueSourceSpec(
        kind=source.kind,
        row=_row_source_spec(source.row) if source.row is not None else None,
        field_name=source.field_name,
        value=source.value,
        sources=tuple(_value_source_spec(child) for child in source.sources),
    )


def _row_source_spec(source: RowSource[Any]) -> _HookRowSourceSpec:
    return _HookRowSourceSpec(
        kind=source.kind,
        model_cls=source.model,
        row_key=_row_source_key(source),
    )


def _runtime_ref_value(runtime_refs: Mapping[str, object], row_ref: str) -> object | None:
    exact = runtime_refs.get(row_ref)
    if exact is not None:
        return exact
    prefix = row_ref + "."
    for ref_id, value in runtime_refs.items():
        if ref_id.startswith(prefix):
            return value
    return None


def _coerce_one_row(value: object) -> object | None:
    if value is None:
        return None
    if isinstance(value, Sequence) and not isinstance(value, str | bytes | bytearray):
        return value[0] if value else None
    return value


def _distinct_present(values: Iterable[Any]) -> tuple[Any, ...]:
    ordered: list[Any] = []
    seen: set[Any] = set()
    for value in values:
        if value is None:
            continue
        key = value
        if isinstance(value, list | dict | set):
            key = repr(value)
        if key in seen:
            continue
        seen.add(key)
        ordered.append(value)
    return tuple(ordered)

"""Runtime fallback steps for optional ServerPlan values."""

from __future__ import annotations

from collections.abc import Mapping, Sequence

from impl.common.l5200_sql_query.row_converter import convert_row_to_model
from l1000_schema.schema_def import DatabaseObjectRow
from l1000_schema.table_utils import get_table_name
from l1400_types import CursorPage, KeysetPage, ServerPlanRefId
from l2070_batching.cardinality import Cardinality
from l2070_batching.compilation import CompiledStep, ResolvedRefs
from l2070_batching.step import NonPublishingStep, PlanPayloadState, StepExecutionRole


class RuntimeFallbackInvariantError(RuntimeError):
    """Raised when generic runtime composition receives invalid inputs."""


def _model_plan_state(model_cls: type[DatabaseObjectRow] | None) -> str | None:
    if model_cls is None:
        return None
    return get_table_name(model_cls)


def _optional_single_value(value: object, *, allow_sequence_unwrap: bool) -> object | None:
    if isinstance(value, Mapping):
        return value
    if isinstance(value, Sequence) and not isinstance(value, (str, bytes, bytearray)):
        if not allow_sequence_unwrap:
            msg = "Optional fallback received a sequence but sequence unwrapping is disabled"
            raise RuntimeFallbackInvariantError(msg)
        if len(value) > 1:
            msg = "Optional fallback cannot unwrap a multi-row sequence"
            raise RuntimeFallbackInvariantError(msg)
        return value[0] if value else None
    if isinstance(value, (str, bytes, bytearray)):
        return value
    try:
        length = len(value)  # type: ignore[arg-type]
    except TypeError:
        return value
    if not hasattr(value, "__getitem__"):
        return value
    return value[0] if length else None  # type: ignore[index]


class OptionalFallbackStep(NonPublishingStep[object | None]):
    """Return a primary optional value, falling back when it is missing."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        primary_ref: ServerPlanRefId,
        fallback_ref: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow] | None = None,
        after_refs: tuple[ServerPlanRefId, ...] = (),
        allow_sequence_unwrap: bool = False,
    ) -> None:
        super().__init__(ref_id)
        self._primary_ref = str(primary_ref)
        self._fallback_ref = str(fallback_ref)
        self._model_cls = model_cls
        self._after_refs = tuple(str(ref_id) for ref_id in after_refs)
        self._allow_sequence_unwrap = allow_sequence_unwrap

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self) -> bool:
        return True

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def step_tags(self) -> frozenset[str]:
        return frozenset({"runtime_fallback", "typed_terminal_projection"})

    def is_executor_owned_runtime_step(self) -> bool:
        return True

    def publishes_decoded_value_as_executor_value(self) -> bool:
        return True

    def runtime_result_is_terminal_scalar(self) -> bool:
        return True

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def dependencies(self) -> frozenset[str]:
        return frozenset({self._primary_ref, self._fallback_ref, *self._after_refs})

    def internal_plan_state(self) -> PlanPayloadState:
        return {
            "ref_id": self.ref_id,
            "_primary_ref": self._primary_ref,
            "_fallback_ref": self._fallback_ref,
            "_model_table": _model_plan_state(self._model_cls),
            "_after_refs": self._after_refs,
            "_allow_sequence_unwrap": self._allow_sequence_unwrap,
        }

    def internal_plan_ref_state(self) -> PlanPayloadState:
        return self.internal_plan_state()

    def compile(self, ctx: object) -> CompiledStep[object | None]:
        del ctx
        return CompiledStep()

    def execute_runtime(self, resolved: ResolvedRefs) -> object | None:
        primary = _optional_single_value(
            resolved.get(self._primary_ref),
            allow_sequence_unwrap=self._allow_sequence_unwrap,
        )
        if primary is not None:
            return self._hydrate(primary)
        fallback = _optional_single_value(
            resolved.get(self._fallback_ref),
            allow_sequence_unwrap=self._allow_sequence_unwrap,
        )
        return self._hydrate(fallback)

    def _hydrate(self, value: object | None) -> object | None:
        if value is None:
            return None
        if self._model_cls is not None and isinstance(value, Mapping):
            return convert_row_to_model(self._model_cls, dict(value))
        return value


class SequenceFallbackStep(NonPublishingStep[list[object]]):
    """Return a non-empty primary sequence, falling back when it is empty."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        primary_ref: ServerPlanRefId,
        fallback_ref: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow] | None = None,
        after_refs: tuple[ServerPlanRefId, ...] = (),
    ) -> None:
        super().__init__(ref_id)
        self._primary_ref = str(primary_ref)
        self._fallback_ref = str(fallback_ref)
        self._model_cls = model_cls
        self._after_refs = tuple(str(ref_id) for ref_id in after_refs)

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.MANY

    def is_read_only(self) -> bool:
        return True

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def step_tags(self) -> frozenset[str]:
        return frozenset({"runtime_fallback", "typed_terminal_projection"})

    def is_executor_owned_runtime_step(self) -> bool:
        return True

    def publishes_decoded_value_as_executor_value(self) -> bool:
        return True

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def dependencies(self) -> frozenset[str]:
        return frozenset({self._primary_ref, self._fallback_ref, *self._after_refs})

    def internal_plan_state(self) -> PlanPayloadState:
        return {
            "ref_id": self.ref_id,
            "_primary_ref": self._primary_ref,
            "_fallback_ref": self._fallback_ref,
            "_model_table": _model_plan_state(self._model_cls),
            "_after_refs": self._after_refs,
        }

    def internal_plan_ref_state(self) -> PlanPayloadState:
        return self.internal_plan_state()

    def compile(self, ctx: object) -> CompiledStep[list[object]]:
        del ctx
        return CompiledStep()

    def execute_runtime(self, resolved: ResolvedRefs) -> list[object]:
        primary = self._as_list(resolved.get(self._primary_ref))
        if primary:
            return primary
        return self._as_list(resolved.get(self._fallback_ref))

    def _as_list(self, value: object) -> list[object]:
        if value is None:
            return []
        page_results = getattr(value, "results", None)
        if isinstance(page_results, Sequence) and not isinstance(page_results, (str, bytes, bytearray)):
            return [self._hydrate(item) for item in page_results]
        if isinstance(value, Mapping):
            mapping_results = value.get("results")
            if isinstance(mapping_results, Sequence) and not isinstance(
                mapping_results,
                (str, bytes, bytearray),
            ):
                return [self._hydrate(item) for item in mapping_results]
        if isinstance(value, Sequence) and not isinstance(value, (str, bytes, bytearray)):
            return [self._hydrate(item) for item in value]
        msg = f"Sequence fallback expected a sequence, got {type(value).__name__}"
        raise RuntimeFallbackInvariantError(msg)

    def _hydrate(self, value: object) -> object:
        if self._model_cls is not None and isinstance(value, Mapping):
            return convert_row_to_model(self._model_cls, dict(value))
        return value


