        del ctx
        return CompiledStep()

    def execute_runtime(self, resolved: ResolvedRefs) -> object | None:
        primary = resolved.get(self._primary_ref)
        if primary is not None:
            if isinstance(primary, Sequence) and not isinstance(primary, (str, bytes, bytearray)):
                msg = f"Scalar fallback primary {self._primary_ref!r} resolved to a sequence"
                raise RuntimeFallbackInvariantError(msg)
            return primary
        fallback = resolved.get(self._fallback_ref)
