class DependencyBarrierStep(NonPublishingStep[object | None]):
    """Publish an optional source value after prerequisite refs have resolved."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        source_ref: ServerPlanRefId | None = None,
        after_refs: tuple[ServerPlanRefId, ...],
    ) -> None:
        super().__init__(ref_id)
        self._source_ref = str(source_ref) if source_ref is not None else None
        self._after_refs = tuple(str(ref_id) for ref_id in after_refs)
        dependency_refs = set(self._after_refs)
        if self._source_ref is not None:
            dependency_refs.add(self._source_ref)
        self._dependencies = frozenset(dependency_refs)
        if self._source_ref is None and not self._after_refs:
            msg = "DependencyBarrierStep requires source_ref or after_refs"
            raise RuntimeFallbackInvariantError(msg)

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self) -> bool:
        return True

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.VIRTUAL if self._source_ref is None else StepExecutionRole.APPLY

    def step_tags(self) -> frozenset[str]:
        return frozenset({"runtime_fallback", "typed_terminal_projection"})

    def is_executor_owned_runtime_step(self) -> bool:
        return self._source_ref is not None

    def supports_sql_batch_transport(self) -> bool:
        return self._source_ref is None

    def supports_ordered_sql_statement_batch(self) -> bool:
        return self._source_ref is None

    def ordered_statement_sql_visible_dependencies(self) -> frozenset[str]:
        return frozenset()

    def emits_sql_for_accounting(self) -> bool | None:
        return False

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def dependencies(self) -> frozenset[str]:
        return self._dependencies

    def internal_plan_state(self) -> PlanPayloadState:
        return {
            "ref_id": self.ref_id,
            "_source_ref": self._source_ref,
            "_after_refs": self._after_refs,
            "_dependencies": self._dependencies,
        }

    def internal_plan_ref_state(self) -> PlanPayloadState:
        return self.internal_plan_state()

    def compile(self, ctx: object) -> CompiledStep[object | None]:
        del ctx
        return CompiledStep()

    def execute_runtime(self, resolved: ResolvedRefs) -> object | None:
        if self._source_ref is None:
            return None
        if self._source_ref not in resolved:
            msg = f"Dependency barrier source did not resolve: {self._source_ref!r}"
            raise RuntimeFallbackInvariantError(msg)
        return resolved[self._source_ref]


class RowsetMergeByIdentityStep(NonPublishingStep[object]):
    """Merge local and remote rowsets by ``sys_id`` with checked duplicate invariants."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        local_ref: ServerPlanRefId,
        remote_ref: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow] | None = None,
        after_refs: tuple[ServerPlanRefId, ...] = (),
        identity_attrs: tuple[str, ...] = ("sys_id",),
        tombstone_attr: str = "",
        ordering_mode: str = "remote_then_local",
        order_by_attr: str = "",
        pagination_mode: str = "not_paginated",
    ) -> None:
        super().__init__(ref_id)
        if not identity_attrs:
            msg = "RowsetMergeByIdentityStep requires at least one identity attr"
            raise RuntimeFallbackInvariantError(msg)
        if ordering_mode not in {"remote_then_local", "local_order", "query_order", "rank_desc"}:
            msg = f"Unsupported rowset merge ordering mode: {ordering_mode!r}"
            raise RuntimeFallbackInvariantError(msg)
        if pagination_mode not in {"forbid_after_slice", "overfetch_then_slice", "not_paginated"}:
            msg = f"Unsupported rowset merge pagination mode: {pagination_mode!r}"
            raise RuntimeFallbackInvariantError(msg)
        if pagination_mode == "forbid_after_slice":
            msg = "Rowset merge cannot run after independently sliced inputs"
            raise RuntimeFallbackInvariantError(msg)
        if ordering_mode in {"query_order", "rank_desc"} and not order_by_attr:
            msg = "query_order rowset merge requires order_by_attr"
            raise RuntimeFallbackInvariantError(msg)
        self._local_ref = str(local_ref)
        self._remote_ref = str(remote_ref)
        self._model_cls = model_cls
        self._after_refs = tuple(str(ref_id) for ref_id in after_refs)
        self._identity_attrs = identity_attrs
        self._tombstone_attr = tombstone_attr
        self._ordering_mode = ordering_mode
        self._order_by_attr = order_by_attr
        self._pagination_mode = pagination_mode

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.MANY

    def is_read_only(self) -> bool:
        return True

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def is_executor_owned_runtime_step(self) -> bool:
        return True

    def publishes_decoded_value_as_executor_value(self) -> bool:
        return True

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def dependencies(self) -> frozenset[str]:
        return frozenset({self._local_ref, self._remote_ref, *self._after_refs})

    def internal_plan_state(self) -> PlanPayloadState:
        return {
            "ref_id": self.ref_id,
            "_local_ref": self._local_ref,
            "_remote_ref": self._remote_ref,
            "_model_table": _model_plan_state(self._model_cls),
            "_after_refs": self._after_refs,
            "_identity_attrs": self._identity_attrs,
            "_tombstone_attr": self._tombstone_attr,
            "_ordering_mode": self._ordering_mode,
            "_order_by_attr": self._order_by_attr,
            "_pagination_mode": self._pagination_mode,
        }

    def internal_plan_ref_state(self) -> PlanPayloadState:
        return self.internal_plan_state()

    def compile(self, ctx: object) -> CompiledStep[object]:
        del ctx
        return CompiledStep()

    def execute_runtime(self, resolved: ResolvedRefs) -> object:
        remote_value = resolved.get(self._remote_ref)
        local_value = resolved.get(self._local_ref)
        remote_rows = self._indexed_rows("remote", remote_value)
        local_rows = self._indexed_rows("local", local_value)
        if self._ordering_mode == "local_order":
            merged = {identity: row for identity, row in local_rows.items() if not self._is_tombstone(row)}
            for identity, row in remote_rows.items():
                merged.setdefault(identity, row)
        else:
            merged = dict(remote_rows)
            for identity, row in local_rows.items():
                if self._is_tombstone(row):
                    merged.pop(identity, None)
                    continue
                merged[identity] = row
        rows = list(merged.values())
        if self._ordering_mode == "query_order":
            rows.sort(key=lambda row: str(self._read_attr(row, self._order_by_attr)))
        elif self._ordering_mode == "rank_desc":
            rows.sort(key=lambda row: self._numeric_order_value(row, self._order_by_attr), reverse=True)
        page = self._page_like(remote_value) or self._page_like(local_value)
        if page is not None:
            return self._page_with_rows(page, rows)
        return rows

    def _indexed_rows(self, label: str, value: object) -> dict[object, object]:
        rows = self._as_list(value)
        indexed: dict[object, object] = {}
        for row in rows:
            hydrated = self._hydrate(row)
            identity = self._row_identity(hydrated)
            if identity in indexed:
                msg = f"{label} rowset contains duplicate identity {identity!r}"
                raise RuntimeFallbackInvariantError(msg)
            indexed[identity] = hydrated
        return indexed

    def _as_list(self, value: object) -> list[object]:
        if value is None:
            return []
        page_results = getattr(value, "results", None)
        if isinstance(page_results, Sequence) and not isinstance(page_results, (str, bytes, bytearray)):
            return list(page_results)
        if isinstance(value, Mapping):
            mapping_results = value.get("results")
            if isinstance(mapping_results, Sequence) and not isinstance(
                mapping_results,
                (str, bytes, bytearray),
            ):
                return list(mapping_results)
        if isinstance(value, Sequence) and not isinstance(value, (str, bytes, bytearray)):
            return list(value)
        msg = f"Rowset merge expected a sequence, got {type(value).__name__}"
        raise RuntimeFallbackInvariantError(msg)

    def _hydrate(self, value: object) -> object:
        if self._model_cls is not None and isinstance(value, Mapping):
            return convert_row_to_model(self._model_cls, dict(value))
        return value

    def _row_identity(self, row: object) -> tuple[object, ...]:
        return tuple(self._read_required_attr(row, attr) for attr in self._identity_attrs)

    def _is_tombstone(self, row: object) -> bool:
        if not self._tombstone_attr:
            return False
        return bool(self._read_attr(row, self._tombstone_attr))

    @staticmethod
    def _read_attr(row: object, attr: str) -> object:
        if isinstance(row, Mapping):
            return row.get(attr)
        return getattr(row, attr, None)

    @classmethod
    def _numeric_order_value(cls, row: object, attr: str) -> float:
        value = cls._read_attr(row, attr)
        if isinstance(value, int | float):
            return float(value)
        if isinstance(value, str):
            try:
                return float(value)
            except ValueError:
                return 0.0
        return 0.0

    @classmethod
    def _read_required_attr(cls, row: object, attr: str) -> object:
        if isinstance(row, Mapping):
            if attr not in row:
                msg = f"Rowset merge mapping row is missing identity attr {attr!r}"
                raise RuntimeFallbackInvariantError(msg)
            return row[attr]
        value = getattr(row, attr, None)
        if value is None:
            msg = f"Rowset merge row {type(row).__name__} is missing identity attr {attr!r}"
            raise RuntimeFallbackInvariantError(msg)
        return value

    @staticmethod
    def _page_like(value: object) -> object | None:
        if isinstance(value, KeysetPage | CursorPage):
            return value
        if isinstance(value, Mapping) and "results" in value and "has_more" in value:
            if "next_key" in value or "cursor" in value:
                return value
        return None

    @staticmethod
    def _page_with_rows(page: object, rows: list[object]) -> object:
        if isinstance(page, KeysetPage):
            return KeysetPage(results=rows, next_key=page.next_key, has_more=page.has_more)
        if isinstance(page, CursorPage):
            return CursorPage(results=rows, cursor=page.cursor, has_more=page.has_more)
        if isinstance(page, Mapping):
            if "next_key" in page:
                return KeysetPage(
                    results=rows,
                    next_key=_tuple_or_none(page.get("next_key")),
                    has_more=bool(page.get("has_more")),
                )
            if "cursor" in page:
                return CursorPage(
                    results=rows,
                    cursor=page.get("cursor"),
                    has_more=bool(page.get("has_more")),
                )
        msg = f"Unsupported page-shaped rowset merge value {type(page).__name__}"
        raise RuntimeFallbackInvariantError(msg)


def _tuple_or_none(value: object) -> tuple[object, ...] | None:
    if value is None:
        return None
    if isinstance(value, tuple):
        return value
    if isinstance(value, list):
        return tuple(value)
    return (value,)

