class DeleteReturningStep(SqlRelationPublisherStep[dict[str, Any] | None]):
    """L0: Delete by sys_id, returning the deleted row as a dict.

    Compiles to ``DELETE FROM table WHERE sys_id = ? RETURNING *``.
    """

    def __init__(
        self: DeleteReturningStep,
        ref_id: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        sys_id: ScalarServerRef[SysId],
        config: _DeleteReturningConfig,
    ) -> None:
        super().__init__(ref_id)
        self._model_cls = model_cls
        self._sys_id = sys_id
        self._resolved_id: Any = _UNRESOLVED_ID
        self._returning_columns = config.returning_columns
        self._resolved_sys_id: object | None = None

    @property
    def level(self: DeleteReturningStep) -> int:
        return 0

    def step_tags(self: DeleteReturningStep) -> frozenset[str]:
        return frozenset({"write", "delete", "returning"})

    def is_read_only(self: DeleteReturningStep) -> bool:
        return False

    def result_cardinality(self: DeleteReturningStep) -> Cardinality:
        return Cardinality.ONE

    def tables_read(self: DeleteReturningStep) -> frozenset[str]:
        return frozenset()

    def tables_written(self: DeleteReturningStep) -> frozenset[str]:
        from l1000_schema.table_utils import get_table_name

        return frozenset({get_table_name(self._model_cls)})

    def dependencies(self: DeleteReturningStep) -> frozenset[str]:
        ref_id_part = self._sys_id.ref_id
        if ref_id_part:
            return frozenset({ref_id_part.split(".", 1)[0]})
        return frozenset()

    def cte_publication_contract(self: DeleteReturningStep) -> CtePublicationContract:
        def _legacy_cte_output_columns() -> tuple[str, ...]:
            if self._returning_columns is not None:
                return tuple(self._returning_columns)
            return _model_db_column_names(self._model_cls)

        columns = _legacy_cte_output_columns()
        column_type_hints = _returning_column_type_hints(self._model_cls, columns)
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        _contract_model_cls = self._model_cls
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=tuple(str(column) for column in columns),
            column_type_hints=column_type_hints,
            model_cls=_contract_model_cls,
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def preprocess(self: DeleteReturningStep, resolved: ResolvedRefs) -> None:
        del resolved

    def compile(self: DeleteReturningStep, ctx: CompilationContext) -> CompiledStep[dict[str, Any] | None]:
        if self._sys_id.ref_id is not None:
            return _compile_runtime_gated_delete_returning(self, ctx)

        from impl.common.l2070_server_plan.steps._compile_write import (
            compile_delete_grammar,
            compile_delete_predicate,
        )

        supports_returning = ctx.sql_render_dialect().supports_returning()
        if not supports_returning:
            from impl.common.l2100_sql_grammar.domain.infra.stmt_compound_write import (
                SqlStatementBatch,
                SqlStatementBatchCategory,
            )
            from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlStar
            from impl.common.l2100_sql_grammar.tree.statements import SqlDelete, SqlSelect
            from l2070_batching.output_shape import DeclaredResultRelation

            table, where_clause = compile_delete_predicate(self._model_cls, self._sys_id, ctx)
            select_deleted_row = SqlSelect(
                select=SqlStar(),
                from_=table,
                where=where_clause,
            )
            delete_row = SqlDelete(table=table, where=where_clause, returning=None)
            output_shape = _returning_output_shape(_model_db_column_names(self._model_cls))
            column_type_hints = self.cte_publication_contract().column_type_hints
            column_type_hints.require_complete(output_shape.cte_output_columns)
            return CompiledStep(
                grammar=SqlStatementBatch(
                    [select_deleted_row, delete_row],
                    category=SqlStatementBatchCategory.ORDERED_SEMANTIC,
                    needs_returning_per_stmt=[True, False],
                    collect_results_per_stmt=[True, False],
                ),
                needs_returning=True,
                output_shape=output_shape,
                result_relation=DeclaredResultRelation.from_output_shape(output_shape),
                column_type_hints=column_type_hints,
                closed_post_op=optional_single_row_post_op(),
            )

        output_shape = _returning_output_shape(self.cte_publication_contract().columns)
        from l2070_batching.output_shape import DeclaredResultRelation

        result_relation = DeclaredResultRelation.from_output_shape(output_shape)
        ir = compile_delete_grammar(
            self._model_cls,
            self._sys_id,
            ctx,
            output_shape=output_shape,
            result_relation=result_relation,
        )
        assert ir is not None

        if not ir.needs_returning:
            __opa002_grammar_239 = ir.grammar
            output_shape, result_relation, column_type_hints = no_result_compiled_artifacts()
            return CompiledStep(
                output_shape=output_shape,
                result_relation=result_relation,
                column_type_hints=column_type_hints,
                grammar=__opa002_grammar_239,
                params=ir.params,
                needs_returning=False,
                closed_post_op=literal_post_op(None),
            )
        column_type_hints = self.cte_publication_contract().column_type_hints
        column_type_hints.require_complete(output_shape.cte_output_columns)
        return CompiledStep(
            grammar=ir.grammar,
            params=ir.params,
            needs_returning=True,
            output_shape=output_shape,
            result_relation=DeclaredResultRelation.from_output_shape(output_shape),
            column_type_hints=column_type_hints,
            closed_post_op=optional_single_row_post_op(),
        )


