    def preprocess(self: DeleteManyReturningStep, resolved: ResolvedRefs) -> None:
        pass

    def compile(
        self: DeleteManyReturningStep,
        ctx: CompilationContext,
    ) -> CompiledStep[list[dict[str, Any]]]:
        from impl.common.l2070_server_plan.steps._query_helper_compile import (
            compile_delete_many_grammar,
            compile_delete_many_predicate,
        )

        resolved_user_id = resolved_permission_user_id_from_ref(self._user_id_ref_id, ctx)
        supports_returning = ctx.sql_render_dialect().supports_returning()
        grammar: SqlRenderable
        compiled_params: tuple[Any, ...] | None
        sql_visible_publication_query: SqlRenderable | None = None
        if supports_returning:
            contract = self.cte_publication_contract()
            if self.has_unbounded_params():
                from impl.common.l2100_sql_grammar.domain.infra.stmt_compound_write import (
                    SqlStatementBatch,
                    SqlStatementBatchCategory,
                )

                statements: list[SqlRenderable] = []
                params_per_stmt: list[tuple[Any, ...] | None] = []
                for start in range(0, len(self._sys_ids), _UNBOUNDED_PARAM_ROW_THRESHOLD):
                    chunk_grammar, chunk_params = compile_delete_many_grammar(
                        self._model_cls,
                        self._sys_ids[start : start + _UNBOUNDED_PARAM_ROW_THRESHOLD],
                        ctx,
                        returning=True,
                        returning_columns=contract.columns,
                        resolved_user_id=resolved_user_id,
                        user_id_ref_id=self._user_id_ref_id,
                        permission_context_ref=self._permission_context_ref,
                        permission_context_type=self._permission_context_type,
                    )
                    statements.append(chunk_grammar)
                    params_per_stmt.append(chunk_params or None)
                grammar = SqlStatementBatch(
                    statements,
                    category=SqlStatementBatchCategory.BUDGET_SPLIT,
                    params_per_stmt=params_per_stmt,
                    external_params_first=[True] * len(statements),
                    needs_returning_per_stmt=[True] * len(statements),
                    collect_results_per_stmt=[True] * len(statements),
                )
                compiled_params = None
            else:
                delete_grammar, params = compile_delete_many_grammar(
                    self._model_cls,
                    self._sys_ids,
                    ctx,
                    returning=True,
                    returning_columns=contract.columns,
                    resolved_user_id=resolved_user_id,
                    user_id_ref_id=self._user_id_ref_id,
                    permission_context_ref=self._permission_context_ref,
                    permission_context_type=self._permission_context_type,
                )
                grammar = delete_grammar
                compiled_params = params
        else:
            from impl.common.l2100_sql_grammar.domain.infra.stmt_compound_write import (
                SqlStatementBatch,
                SqlStatementBatchCategory,
            )
            from hashlib import sha256

            from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef
            from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
            from impl.common.l2100_sql_grammar.tree.statements import (
                SqlCreateTemporaryTableAs,
                SqlDelete,
                SqlDropTemporaryTableIfExists,
                SqlSelect,
            )
            from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName, SqlTableName

            table, where_clause, params = compile_delete_many_predicate(
                self._model_cls,
                self._sys_ids,
                ctx,
                resolved_user_id=resolved_user_id,
                user_id_ref_id=self._user_id_ref_id,
                permission_context_ref=self._permission_context_ref,
                permission_context_type=self._permission_context_type,
            )
            contract = self.cte_publication_contract()
            temp_suffix = sha256(f"{self.ref_id}".encode()).hexdigest()[:16]
            temp_table = SqlTableIdent(SqlTableName(f"__nera_delete_{temp_suffix}"))
            capture_deleted_rows = SqlSelect(
                select=tuple(SqlColumnRef(SqlColumnName(column)) for column in contract.columns),
                from_=table,
                where=where_clause,
            )
            select_deleted_rows = SqlSelect(
                select=tuple(SqlColumnRef(SqlColumnName(column)) for column in contract.columns),
                from_=temp_table,
            )
            delete_rows = SqlDelete(table=table, where=where_clause, returning=None)
            grammar = SqlStatementBatch(
                [
                    SqlDropTemporaryTableIfExists(temp_table),
                    SqlCreateTemporaryTableAs(temp_table, capture_deleted_rows),
                    delete_rows,
                    select_deleted_rows,
                ],
                category=SqlStatementBatchCategory.ORDERED_SEMANTIC,
                params_per_stmt=[None, params or None, params or None, None],
                external_params_first=[True, True, True, True],
                needs_returning_per_stmt=[False, False, False, True],
                collect_results_per_stmt=[False, False, False, True],
            )
            compiled_params = None
            sql_visible_publication_query = select_deleted_rows
        auxiliary_ctes: list[tuple[str, SqlRenderable]] | None = None
        from l2070_batching.compilation import CteReference
        from l2070_batching.output_shape import DeclaredResultRelation

        if isinstance(resolved_user_id, CteReference) and resolved_user_id.auxiliary_query is not None:
            auxiliary_ctes = [(resolved_user_id.ref_id, resolved_user_id.auxiliary_query)]
        context_auxiliary_ctes = collect_permission_context_auxiliary_ctes(
            ctx,
            self._permission_context_ref,
            operation="Delete returning",
        )
        if context_auxiliary_ctes is not None:
            auxiliary_ctes = [*(auxiliary_ctes or []), *context_auxiliary_ctes]
        output_columns = self.cte_publication_contract().columns
        output_shape = _returning_output_shape(output_columns)
        column_type_hints = self.cte_publication_contract().column_type_hints
        column_type_hints.require_complete(output_shape.cte_output_columns)

        return CompiledStep(
            grammar=grammar,
            params=compiled_params,
            external_params_first=True,
            needs_returning=True,
            auxiliary_ctes=auxiliary_ctes,
            output_shape=output_shape,
            result_relation=DeclaredResultRelation.from_output_shape(output_shape),
            column_type_hints=column_type_hints,
            closed_post_op=row_dicts_post_op(),
            compiled_sql_publication=compiled_sql_publication_from_query(
                ref_id=self.ref_id,
                query=sql_visible_publication_query,
                contract=self.cte_publication_contract(),
            ),
        )

"""Canonical search payload contract and projection steps."""

from __future__ import annotations

from collections.abc import Mapping, Sequence
from dataclasses import dataclass, replace
from typing import TYPE_CHECKING, Any, NewType, cast

from l2070_batching.cardinality import Cardinality
from l2070_batching.compilation import BatchPostprocessReductionContract, CompilationContext, CompiledStep, RawResult
from l2070_batching.post_op import CompiledPostOp
from l2070_batching.post_op_specs import (
    PostOpBehavior,
    ResultMaterializationSpec,
    TerminalMaterializerKind,
)
from l2070_batching.step import NonPublishingStep, ServerPlanStep, StepExecutionRole
from l1400_types import ServerPlanRefId

if TYPE_CHECKING:
    from l2060_query_builder.query_builder import SearchMeta
    from l2070_batching.hydrator import Hydrator

SearchScoreKey = NewType("SearchScoreKey", str)
type TerminalResolvedValues = Mapping[str, object]
_SEARCH_INTERNAL_TRANSPORT_COLUMNS = frozenset(
    {
        "__fts_object_rn",
        "__fts_revision_rn",
        "__requested_revision_id",
        "__requested_revision_ordinal",
    },
)


@dataclass(frozen=True, slots=True)
class SearchPayload[T]:
    """Canonical lazy search payload before public-shape projection."""

    results: Sequence[T]
    meta: Sequence[Any]


def require_search_payload(value: object) -> SearchPayload[Any]:
    """Require the canonical search payload shape."""
    if isinstance(value, SearchPayload):
        return value
    msg = f"Expected SearchPayload, got {type(value).__name__}"
    raise TypeError(msg)


def _post_process_extract_search_meta_rows(
    ref_id: ServerPlanRefId,
    source_ref: str,
    score_key: str | None,
    raw: RawResult,
    _hydrator: Hydrator,
    runtime_refs: Mapping[str, object],
) -> dict[str, object]:
    from l2060_query_builder.query_builder import SearchMeta
    from impl.common.l5350_hybrid_search.hybrid_search_builder import pop_search_meta

    raw_payload: object = raw if raw else runtime_refs.get(source_ref, [])
    if (
        isinstance(raw_payload, Sequence)
        and len(raw_payload) == 1
        and isinstance(raw_payload[0], Mapping)
        and set(raw_payload[0]) == {"__executor_value__"}
    ):
        raw_payload = raw_payload[0]["__executor_value__"]
    if isinstance(raw_payload, Mapping) and ref_id in raw_payload:
        return dict(cast(Mapping[str, object], raw_payload))
    results: list[Any] = []
    meta: list[SearchMeta] = []

    if isinstance(raw_payload, SearchPayload):
        for index, row in enumerate(raw_payload.results):
            existing_meta = raw_payload.meta[index] if index < len(raw_payload.meta) else SearchMeta()
            search_meta = cast(SearchMeta, existing_meta)
            if isinstance(row, Mapping):
                row_value: Any = dict(cast(Mapping[str, Any], row))
                for column in _SEARCH_INTERNAL_TRANSPORT_COLUMNS:
                    row_value.pop(column, None)
                if score_key is not None and getattr(search_meta, "vector_score", None) is None:
                    raw_score = row_value.pop(score_key, None)
                    if raw_score is not None:
                        search_meta = replace(search_meta, vector_score=float(raw_score))
            else:
                row_value = row
            results.append(row_value)
            meta.append(search_meta)
        payload = SearchPayload(results=list(results), meta=list(meta))
        return {
            ref_id: payload,
            f"{ref_id}.rows": list(results),
            f"{ref_id}.meta": list(meta),
        }

    for row in cast(Sequence[object], raw_payload):
        if not isinstance(row, Mapping):
            results.append(row)
            meta.append(SearchMeta())
            continue
        row_dict = dict(cast(Mapping[str, Any], row))
        search_meta = pop_search_meta(row_dict)
        for column in _SEARCH_INTERNAL_TRANSPORT_COLUMNS:
            row_dict.pop(column, None)
        if score_key is not None and getattr(search_meta, "vector_score", None) is None:
            raw_score = row_dict.pop(score_key, None)
            if raw_score is not None:
                search_meta = replace(search_meta, vector_score=float(raw_score))
        results.append(row_dict)
        meta.append(search_meta)
    payload = SearchPayload(results=list(results), meta=list(meta))
    return {
        ref_id: payload,
        f"{ref_id}.rows": list(results),
        f"{ref_id}.meta": list(meta),
    }


def _post_process_materialize_search_payload(
    rows_ref: ServerPlanRefId,
    meta_ref: str,
    raw: RawResult,
    _hydrator: Hydrator,
    runtime_refs: Mapping[str, object],
) -> SearchPayload[Any]:
    if (
        len(raw) == 1
        and isinstance(raw[0], Mapping)
        and set(raw[0]) == {"__executor_value__"}
        and isinstance(raw[0]["__executor_value__"], SearchPayload)
    ):
        return cast(SearchPayload[Any], raw[0]["__executor_value__"])
    parent_ref = _dependency_ref_for_runtime_subref(ServerPlanRefId(rows_ref))
    parent_payload = runtime_refs.get(parent_ref, None)
    if isinstance(parent_payload, SearchPayload):
        return parent_payload
    if isinstance(parent_payload, Mapping):
        parent_mapping = cast(Mapping[str, object], parent_payload)
        if rows_ref in parent_mapping and meta_ref in parent_mapping:
            return SearchPayload(
                results=list(cast(Sequence[Any], parent_mapping[rows_ref])),
                meta=list(cast(Sequence[Any], parent_mapping[meta_ref])),
            )
    return SearchPayload(
        results=list(cast(Sequence[Any], runtime_refs[rows_ref])),
        meta=list(cast(Sequence[Any], runtime_refs[meta_ref])),
    )


def _post_process_project_search_payload_results(
    source_ref: str,
    raw_result: RawResult,
    _hydrator: Hydrator,
    runtime_refs: Mapping[str, object],
) -> Sequence[Any]:
    if len(raw_result) == 1 and isinstance(raw_result[0], Mapping) and set(raw_result[0]) == {"__executor_value__"}:
        value = raw_result[0]["__executor_value__"]
        if isinstance(value, SearchPayload):
            return list(value.results)
        if isinstance(value, Sequence) and not isinstance(value, (str, bytes, bytearray)):
            return list(value)
    try:
        source_value = runtime_refs[source_ref]
        if isinstance(source_value, Sequence) and not isinstance(source_value, (str, bytes, bytearray)):
            return list(source_value)
        payload = require_search_payload(source_value)
    except TypeError as exc:
        available_refs = ", ".join(sorted(runtime_refs))
        msg = f"{exc} for source ref {source_ref!r}; available refs: {available_refs}"
        raise TypeError(msg) from exc
    results = list(payload.results)
    if results and isinstance(results[0], dict):
        merged: list[Any] = []
        meta_seq = list(payload.meta)
        for index, row in enumerate(results):
            row_dict = dict(cast(Mapping[str, Any], row))
            fts_meta = meta_seq[index] if index < len(meta_seq) else None
            if "_fts_rank" not in row_dict:
                row_dict["_fts_rank"] = getattr(fts_meta, "fts_rank", None)
            merged.append(row_dict)
        return merged
    return results


def _post_process_project_search_payload_with_meta(
    source_ref: str,
    raw_result: RawResult,
    _hydrator: Hydrator,
    runtime_refs: Mapping[str, object],
) -> tuple[Sequence[Any], Sequence[Any]]:
    if len(raw_result) == 1 and isinstance(raw_result[0], Mapping) and set(raw_result[0]) == {"__executor_value__"}:
        value = raw_result[0]["__executor_value__"]
        if isinstance(value, SearchPayload):
            return list(value.results), list(value.meta)
        if isinstance(value, tuple) and len(value) == 2:
            rows, meta = cast(tuple[Sequence[Any], Sequence[Any]], value)
            return list(rows), meta
    payload = require_search_payload(runtime_refs[source_ref])
    return list(payload.results), list(payload.meta)


def _project_search_rows_with_meta(raw: RawResult) -> tuple[list[Any], list[Any]]:
    from l2060_query_builder.query_builder import SearchMeta
    from impl.common.l5350_hybrid_search.hybrid_search_builder import pop_search_meta

    rows: list[Any] = []
    meta: list[Any] = []
    for row in raw:
        if not isinstance(row, Mapping):
            rows.append(row)
            meta.append(SearchMeta())
            continue
        row_dict = dict(cast(Mapping[str, Any], row))
        search_meta = pop_search_meta(row_dict)
        if "_fts_rank" not in row_dict:
            row_dict["_fts_rank"] = getattr(search_meta, "fts_rank", None)
        rows.append(row_dict)
        meta.append(search_meta)
    return rows, meta


def _dependency_ref_for_runtime_subref(ref_id: ServerPlanRefId) -> str:
    """Map a published runtime subref back to the producing plan step."""
    return ref_id.rsplit(".", 1)[0] if "." in ref_id else ref_id


def _runtime_ref_aliases(ref_id: ServerPlanRefId) -> tuple[str, ...]:
    normalized = ref_id.replace(".", "_")
    return (ref_id,) if normalized == ref_id else (ref_id, normalized)


class ExtractSearchMetaRowsStep(NonPublishingStep[dict[str, object]]):
    """Extract mutable row dicts and ``SearchMeta`` from a search payload or raw row list."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        source_ref: ServerPlanRefId,
        score_key: SearchScoreKey | None = None,
    ) -> None:
        super().__init__(ref_id)
        self._source_ref = source_ref
        self._score_key = score_key
        self._payload: tuple[list[dict[str, Any]], list[SearchMeta]] = ([], [])

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self) -> bool:
        return True

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def is_executor_owned_runtime_step(self) -> bool:
        return True

    def supports_sql_batch_transport(self) -> bool:
        return False

    def batch_result_alias_labels(self) -> tuple[str, ...]:
        """Declare every executor-owned alias emitted by payload splitting."""
        base_ref = ServerPlanRefId(self.ref_id)
        aliases = (
            *_runtime_ref_aliases(ServerPlanRefId(f"{base_ref}.rows")),
            *_runtime_ref_aliases(ServerPlanRefId(f"{base_ref}.meta")),
        )
        return tuple(dict.fromkeys(aliases))

    def batch_result_labels(self) -> tuple[str, ...]:
        # Alias identities have plan lifetime and downstream consumers must not
        # rediscover them from the runtime mapping returned by execute_runtime.
        return (str(self.ref_id), *self.batch_result_alias_labels())

    def consumes_executor_visible_dependencies(self) -> bool:
        return True

    def executor_visible_published_rows(
        self: ExtractSearchMetaRowsStep,
    ) -> None:
        """Runtime-only search payload assembly; upstream rows are executor-resolved."""
        return None

    def emits_sql_for_accounting(self) -> bool:
        return False

    def expands_results(self) -> bool:
        return True

    def step_tags(self) -> frozenset[str]:
        return frozenset({"read", "query", "search", "extract", "meta", "runtime_projection", "terminal_projection"})

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def dependencies(self) -> frozenset[str]:
        return frozenset({str(self._source_ref)})

    def compile(
        self,
        ctx: CompilationContext,
    ) -> CompiledStep[dict[str, object]]:
        del ctx
        return CompiledStep()

    def execute_runtime(self, resolved: TerminalResolvedValues) -> dict[str, object]:
        source_ref = str(self._source_ref)
        score_key = None if self._score_key is None else str(self._score_key)
        payload = _post_process_extract_search_meta_rows(
            ServerPlanRefId(self.ref_id),
            source_ref,
            score_key,
            (),
            cast("Hydrator", None),
            resolved,
        )
        expanded: dict[str, object] = {}
        for key, value in payload.items():
            for alias in _runtime_ref_aliases(ServerPlanRefId(key)):
                expanded[alias] = value
        return expanded


