                    exc_type=ValueError,
                    default_message="UpdateMany existence gate failed.",
                ),
            ),
        ),
    )


@dataclass(frozen=True, slots=True)
class _UpdateManyStepConfig:
    instances: object
    after_refs: frozenset[ServerPlanRefId] = frozenset()
    permission_context_ref: ServerPlanRefId | None = None
    permission_context_type: type[ResolvedSessionContext] | None = None


class UpdateManyStep[T](ServerPlanStep[list[T]]):
    """Execute a bulk update from a concrete or deferred row sequence."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        config: _UpdateManyStepConfig,
    ) -> None:
        super().__init__(ref_id)
        self._model_cls = model_cls
        self._instances = config.instances
        self._after_refs = config.after_refs
        self._permission_context_ref = config.permission_context_ref
        self._permission_context_type = config.permission_context_type

    @property
    def level(self) -> int:
        return 1

    def step_tags(self) -> frozenset[str]:
        return frozenset({"write", "update", "bulk"})

    def is_read_only(self) -> bool:
        return False

    def result_cardinality(self) -> Cardinality:
        return Cardinality.MANY

    def publishes_executor_visible_binding(self) -> bool:
        """The lowered raw bulk update step owns executor-visible publication."""
        return False

    def always_publishes_executor_visible_binding(self) -> bool:
        """Author-level bulk update wrappers do not publish their own ref."""
        return False

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset({get_table_name(self._model_cls)})

    def dependencies(self) -> frozenset[str]:
        from impl.common.l2070_server_plan.steps._resolve import collect_instances_deps
        from l2055_lazy_result.lazy_param import server_value_deps

        deps = {str(ref_id) for ref_id in self._after_refs}
        if self._permission_context_ref is not None:
            deps.add(str(self._permission_context_ref))
        deps.update(server_value_deps(self._instances))
        if not isinstance(self._instances, ObjectSequenceServerRef):
            deps.update(collect_instances_deps(cast("Sequence[object]", self._instances)))
        return frozenset(deps)

    def lower(self, ctx: LoweringContext) -> list[ServerPlanStep[Any]]:
        from impl.common.l2070_server_plan.steps.row_hydration import MaterializeResolvedModelSequenceStep
        from impl.common.l2070_server_plan.steps.update import (
            SelectedRowsUpdateRawResultStep,
            _SelectedRowsUpdateStepConfig,
        )
        from l2070_batching.server_ref import ServerRefs

        raw_ref = f"{self.ref_id}_raw.raw"
        if isinstance(self._instances, ObjectSequenceServerRef):
            source_ref = self._instances.ref_id
            if source_ref is None:
                msg = "UpdateManyStep requires a symbolic selected row ref for deferred bulk update"
                raise RuntimeError(msg)
            from l1000_schema.large_column import get_large_column_configs
            from impl.common.l2070_server_plan.steps.large_column_read import (
                get_large_column_ref_ownership,
            )

            selected_ref = ServerPlanRefId(source_ref)
            if get_large_column_configs(self._model_cls):
                ownership = get_large_column_ref_ownership(ctx, selected_ref)
                if ownership is None:
                    msg = f"Large-column deferred update source {selected_ref!s} has no hydrated authority ref"
                    raise RuntimeError(msg)
                selected_ref = ownership.raw_ref
            raw_step = cast(
                "ServerPlanStep[Any]",
                SelectedRowsUpdateRawResultStep(
                    ServerPlanRefId(raw_ref),
                    self._model_cls,
                    _SelectedRowsUpdateStepConfig(
                        instance=ServerRefs.from_ref_id(
                            selected_ref,
                            variant="object",
                            type_hint=self._model_cls,
                        ),
                        selected_rows_ref=selected_ref,
                        patch_updates={},
                        apply_update_rules=True,
                        permission_context_ref=self._permission_context_ref,
                        permission_context_type=self._permission_context_type,
                    ),
                ),
            )
            result_step: ServerPlanStep[Any] = MaterializeResolvedModelSequenceStep(
                self.ref_id,
                source_ref=ServerPlanRefId(raw_ref),
                model_cls=self._model_cls,
                source_is_executor_owned=not bool(get_large_column_configs(self._model_cls)),
                inline_large_columns=bool(get_large_column_configs(self._model_cls)),
            )
            return [raw_step, result_step]
        return [
            cast(
                "ServerPlanStep[Any]",
                UpdateManyRawResultStep(
                    self.ref_id,
                    self._model_cls,
                    _UpdateManyStepConfig(
                        instances=self._instances,
                        after_refs=self._after_refs,
                        permission_context_ref=self._permission_context_ref,
                        permission_context_type=self._permission_context_type,
                    ),
                ),
            ),
        ]

    def compile(self, ctx: CompilationContext) -> CompiledStep[list[T]]:
        del ctx
        raise NotImplementedError(f"{type(self).__name__} must be lowered before compile()")


def _allows_permission_filtered_update_results(
    model_cls: type[DatabaseObjectRow],
    ctx: CompilationContext,
) -> bool:
    """Return whether fewer RETURNING rows can mean permission-filtered updates."""
    from l4000_permissions.permission_enforcement import (
        _try_get_permission_scheme,
        get_query_permission_plan,
    )

    scheme = _try_get_permission_scheme(model_cls)
    if scheme is None:
        return False
    if ctx.session_id is None:
        return True
    permission_plan = get_query_permission_plan(
        model_cls,
        action="update",
    )
    if permission_plan is None:
        return False
    if isinstance(ctx.session_id, SessionId):
        return permission_plan.filters_session(ctx.session_id)
    return permission_plan.filter_rows


def _coerce_update_many_sys_id(value: object) -> str:
    try:
        unwrap_to_str = object.__getattribute__(value, "unwrap_to_str")
    except AttributeError:
        unwrap_to_str = None
    if callable(unwrap_to_str):
        return str(unwrap_to_str())
    return str(value)


def _require_concrete_update_many_instances(instances_source: object) -> list[DatabaseObjectRow]:
    if isinstance(instances_source, ObjectSequenceServerRef):
        msg = (
            "UpdateManyRawResultStep requires a lowering-time concrete instance sequence. "
            "Bulk updates that still depend on prior refs must lower through an explicit "
            "prerequisite/materialization step before SQL compilation."
        )
        raise RuntimeError(msg)
    return list(cast(Sequence[DatabaseObjectRow], instances_source))


def _require_child_update_grammar(compiled: CompiledStep[Any]) -> SqlRenderable:
    if compiled.grammar is not None:
        return compiled.grammar
    msg = "UpdateManyStep requires SQL grammars for child updates"
    raise RuntimeError(msg)


def _compound_row_label(row: object) -> str | None:
    if not isinstance(row, dict):
        return None
    label = row.get("__compound_step__")
    return label if isinstance(label, str) else None


def _strip_compound_row_label(row: object) -> object:
    if not isinstance(row, dict) or "__compound_step__" not in row:
        return row
    stripped = dict(row)
    del stripped["__compound_step__"]
    return stripped


def _select_existing_update_many_ids(
    model_cls: type[DatabaseObjectRow],
    sys_ids: Sequence[object],
) -> SqlRenderable:
    from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName, SqlTableName
    from impl.common.l2100_sql_grammar.tree.clauses import (
        SqlFrom,
        SqlSelectList,
        SqlTableAlias,
        SqlWhereClause,
    )
    from impl.common.l2100_sql_grammar.domain.infra.stmt_conditions import SqlColumnInPlaceholders
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef
    from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
    from impl.common.l2100_sql_grammar.tree.statements import SqlSelect

    sys_id_column = SqlColumnRef(SqlColumnName("sys_id"))
    return cast(
        "SqlRenderable",
        SqlSelect(
            select=SqlSelectList([sys_id_column]),
            from_clause=SqlFrom(SqlTableAlias(SqlTableIdent(get_table_name(model_cls)))),
            where=SqlWhereClause(SqlColumnInPlaceholders(sys_id_column, len(sys_ids))),
        ),
    )


def _update_many_output_shape(model_cls: type[DatabaseObjectRow]) -> CompiledOutputShape:
    return CompiledOutputShape(
