                source_db_column=get_db_column_name(model_cls, DynamicFieldName(field_name)),
                model_field_name=field_name,
                owner_cls=model_cls,
            )
            for field_name in model_cls.model_fields
        ),
    )


class UpdateManyRawResultStep(UpdateManyStep[object]):
    """Terminal raw-result variant for bulk updates."""

    @property
    def level(self) -> int:
        return 0

    def supports_sql_batch_transport(self) -> bool:
        return False

    def requires_prior_step_boundary(self) -> bool:
        return True

    def cte_publication_contract(self: UpdateManyRawResultStep) -> CtePublicationContract:
        from impl.common.l2070_server_plan.steps.sql_error_gate import (
            sql_assertion_column_type_hints,
            sql_assertion_output_shape,
        )

        row_output_shape = _update_many_output_shape(self._model_cls)
        columns = (
            *sql_assertion_output_shape().cte_output_columns,
            *row_output_shape.cte_output_columns,
        )
        row_hints = model_field_sql_column_type_hints(
            self._model_cls,
            {field.model_field_name: field.output_column for field in row_output_shape.fields if field.model_field_name is not None},
        )
        column_type_hints = combine_sql_column_type_hints(
            columns,
            sql_assertion_column_type_hints(),
            row_hints,
        )
        assertion_columns = frozenset(sql_assertion_output_shape().cte_output_columns)
        source_tables = self.tables_written() or self.tables_read() or None
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=columns,
            column_type_hints=column_type_hints,
            relation_contract=CteRelationContract.projection_over_model(
                source_model_cls=self._model_cls,
                projection_lineage=tuple(
                    (
                        column,
                        f"assertion:{column}" if column in assertion_columns else column,
                    )
                    for column in columns
                ),
            ),
            relation_role=self.cte_relation_role(),
            source_tables=(frozenset(str(table) for table in source_tables) if source_tables is not None else None),
        )

    def always_publishes_executor_visible_binding(self) -> bool:
        return False

    def publishes_executor_visible_binding(self) -> bool:
        return False

    def semantic_publication_columns(self) -> tuple[str, ...]:
        return tuple(str(field_name) for field_name in self._model_cls.model_fields)

    def semantic_publication_type_hints(self) -> SqlColumnTypeHints:
        return model_field_sql_column_type_hints(
            self._model_cls,
            {str(field_name): str(field_name) for field_name in self._model_cls.model_fields},
        )

    def step_tags(self) -> frozenset[str]:
        return frozenset({"write", "update", "bulk", "raw"})

    def lower(self, ctx: LoweringContext) -> list[ServerPlanStep[Any]]:
        del ctx
        return [self]

    def compile(self, ctx: CompilationContext) -> CompiledStep[list[object]]:
        instances_source = self._instances
        instances = _require_concrete_update_many_instances(instances_source)
        if not instances:
            from impl.common.l2100_sql_grammar.domain.infra.stmt_noop import SqlNoOpStatement

            __opa002_grammar_361 = SqlNoOpStatement()
            contract = self.cte_publication_contract()
            assert contract is not None
            output_shape = output_shape_from_cte_publication_contract(contract)
            return cast(
                CompiledStep[list[object]],
                CompiledStep(
                    output_shape=output_shape,
                    result_relation=DeclaredResultRelation.from_output_shape(output_shape),
                    column_type_hints=contract.column_type_hints,
                    grammar=__opa002_grammar_361,
                    closed_post_op=literal_post_op([]),
                ),
            )

        from impl.common.l2070_server_plan.steps.update import UpdateRawResultStep
        from impl.common.l2100_sql_grammar.domain.infra.stmt_compound_write import (
            SqlStatementBatch,
            SqlStatementBatchCategory,
        )

        grammars: list[Any] = []
        params_per_stmt: list[tuple[Any, ...]] = []
        external_params_first_per_stmt: list[bool] = []
        needs_returning_per_stmt: list[bool] = []
        savepoint_recovery_per_stmt: list[bool] = []
        needs_returning = True
        for idx, instance in enumerate(instances):
            compiled = UpdateRawResultStep(
                ServerPlanRefId(f"{self.ref_id}_item_{idx}"),
                self._model_cls,
                _UpdateStepConfig(
                    instance=instance,
                    permission_context_ref=self._permission_context_ref,
                    permission_context_type=self._permission_context_type,
                ),
            ).compile(ctx)
            grammars.append(_require_child_update_grammar(compiled))
            params_per_stmt.append(tuple(compiled.params or ()))
            external_params_first_per_stmt.append(compiled.external_params_first)
            needs_returning_per_stmt.append(compiled.needs_returning)
            savepoint_recovery_per_stmt.append(compiled.use_savepoint_recovery)
            needs_returning = needs_returning and compiled.needs_returning

        from impl.common.l2070_server_plan.steps._query_helper_compile import unwrap_sql_param_values

        requested_sys_ids = [instance.sys_id for instance in instances]
        result_labels_per_stmt: list[str | None] = [_UPDATED_ROW_LABEL] * len(grammars)
        from impl.common.l2070_server_plan.steps.sql_error_gate import (
            row_count_equals_assertion_query,
        )

        grammars.insert(
            0,
            row_count_equals_assertion_query(
                _select_existing_update_many_ids(self._model_cls, requested_sys_ids),
                len(instances),
                error_message=(f"Cannot update one or more {self._model_cls.__name__} rows: expected {len(instances)} existing rows"),
            ),
        )
        params_per_stmt.insert(0, unwrap_sql_param_values(requested_sys_ids))
        external_params_first_per_stmt.insert(0, False)
        needs_returning_per_stmt.insert(0, True)
        savepoint_recovery_per_stmt.insert(0, True)
        result_labels_per_stmt = [_EXISTING_ROW_LABEL, *result_labels_per_stmt]

        grammar = SqlStatementBatch(
            grammars,
            category=SqlStatementBatchCategory.REQUEST_BATCH_BOUNDARY,
            params_per_stmt=params_per_stmt,
            external_params_first=external_params_first_per_stmt,
            needs_returning_per_stmt=needs_returning_per_stmt,
            result_labels_per_stmt=result_labels_per_stmt,
            savepoint_recovery_per_stmt=savepoint_recovery_per_stmt,
        ).flatten_for_executor()

        auxiliary_ctes = collect_permission_context_auxiliary_ctes(
            ctx,
            self._permission_context_ref,
            operation="Update many",
        )

        if needs_returning:
            assertion_ref_id = f"{self.ref_id}.existence_assertion"
            rows_ref_id = f"{self.ref_id}.updated_rows"
            contract = self.cte_publication_contract()
            assert contract is not None
            from impl.common.l2070_server_plan.steps.sql_error_gate import (
                sql_assertion_column_type_hints,
                sql_assertion_output_shape,
            )

            assertion_output_shape = sql_assertion_output_shape()
            row_output_shape = _update_many_output_shape(self._model_cls)
            row_result_relation = DeclaredResultRelation.from_output_shape(row_output_shape)
            output_shape = CompiledOutputShape(
                (
                    *assertion_output_shape.fields,
                    *row_output_shape.fields,
                ),
            )
            column_type_hints = combine_sql_column_type_hints(
                output_shape.cte_output_columns,
                sql_assertion_column_type_hints(),
                contract.column_type_hints,
            )
            return CompiledStep(
                grammar=grammar,
                needs_returning=True,
                auxiliary_ctes=auxiliary_ctes,
                external_params_first=False,
                batch_result_plan=BatchResultExecutionPlan(
                    splitter_name="CompoundSequenceCodegen",
                    child_results=(
                        BatchChildResultSpec(
                            ref_id=assertion_ref_id,
                            expands_results=False,
                            closed_post_op=update_many_existence_assertion_post_op(),
                            dependency_ref_ids=(),
                            split_labels=(_EXISTING_ROW_LABEL,),
                        ),
                        BatchChildResultSpec(
                            ref_id=rows_ref_id,
                            expands_results=False,
                            closed_post_op=CompiledPostOp.materialize(
                                ResultMaterializationSpec(
                                    behavior=PostOpBehavior.TERMINAL_ARRAY,
                                    model_cls=self._model_cls,
                                    input_relation=row_result_relation,
                                ),
                            ),
                            dependency_ref_ids=(assertion_ref_id,),
                            split_labels=(_UPDATED_ROW_LABEL,),
                        ),
                    ),
                ),
                direct_batch_result_ref_id=rows_ref_id,
                output_shape=output_shape,
                result_relation=DeclaredResultRelation.from_output_shape(output_shape),
                column_type_hints=column_type_hints,
            )

        captured = list(instances)

        __opa002_grammar_455 = grammar
        contract = self.cte_publication_contract()
        assert contract is not None
        output_shape = output_shape_from_cte_publication_contract(contract)
        return CompiledStep(
            output_shape=output_shape,
            result_relation=DeclaredResultRelation.from_output_shape(output_shape),
            column_type_hints=contract.column_type_hints,
            grammar=__opa002_grammar_455,
            needs_returning=False,
            auxiliary_ctes=auxiliary_ctes,
            external_params_first=False,
            closed_post_op=literal_post_op(cast(list[object], captured)),
        )

