class StagedDeltaPayloadUnavailableError(ValueError):
    """A finalized staged upload has no materializable payload."""


def staged_delta_reentry_resource_budget(
    finalized_size: int,
    minimum_chunk_size: int,
) -> PythonReentryResourceBudget:
    """Return the signed size-relative policy for one staged payload."""
    return PythonReentryResourceBudget(
        max_input_bytes=max(1, finalized_size),
        max_output_bytes=max(1, finalized_size * 2 + 65536),
        max_output_rows=max(3, (finalized_size // minimum_chunk_size) * 2 + 3),
    )


@dataclass(frozen=True, slots=True)
class PreparedStagedDeltaStorage:
    """A zero-or-one canonical graph for a staged upload."""

    rows: tuple[ContentDeltaStorageRows, ...]

    def __post_init__(self: PreparedStagedDeltaStorage) -> None:
        if len(self.rows) > 1:
            raise ValueError("A staged delta preparation can contain at most one graph.")


@dataclass(frozen=True, slots=True)
class StagedPayloadMaterialization:
    """Typed metadata required to restore one authored staged value."""

    payload_ref: ServerPlanRefId
    column: ContentColumnName
    content_type: LargeColumnKind


def _execute_staged_delta_reentry(
    operation: PythonReentryOperationId,
    request: StagedFieldDeltaPreparationRequest,
) -> ContentDeltaStorageRows:
    """Dispatch one typed request through the closed operation registry."""
    match operation:
        case PythonReentryOperationId.STAGED_FIELD_DELTA_PREPARE_V1:
            implementation_path = PythonReentryImplementationPath(
                f"{prepare_staged_field_delta_storage.__module__}.{prepare_staged_field_delta_storage.__qualname__}",
            )
            assert_python_reentry_implementation_allowed(operation, implementation_path)
            return prepare_staged_field_delta_storage(request)
        case _:
            msg = f"Python re-entry operation {operation.value!r} has no staged delta handler."
            raise ValueError(msg)


class PrepareStagedDeltaStorageStep(NonPublishingStep[PreparedStagedDeltaStorage]):
    """Run the signed CPU-only delta preparation over one staged payload."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        manifest_ref: ServerPlanRefId,
        payload_ref: ServerPlanRefId,
        request: StagedFieldDeltaPreparationRequest,
        reentry: PythonReentrySpec,
    ) -> None:
        super().__init__(ref_id)
        if reentry.application_ref != ref_id or reentry.input_refs != (manifest_ref, payload_ref):
            raise ValueError("The Python re-entry refs do not match the staged delta step.")
        input_models = (StagedFieldStream, StagedFieldStreamPayload)
        expected_relations: list[RelationContract] = []
        for input_model in input_models:
            columns = producer_publication_columns(input_model)
            hints = model_sql_column_type_hints(input_model, columns)
            if hints is None:
                raise TypeError(f"{input_model.__name__} has no SQL relation type hints.")
            expected_relations.append(RelationContract(columns=columns, column_type_hints=hints))
        if reentry.input_relation_names != tuple(model.__name__ for model in input_models) or reentry.input_relations != tuple(
            expected_relations,
        ):
            raise ValueError("The staged delta inputs do not match the signed Python re-entry relations.")
        expected_budget = staged_delta_reentry_resource_budget(
            request.expected_size,
            request.config.min_chunk_size,
        )
        if reentry.budget != expected_budget:
            msg = f"Python re-entry operation {reentry.operation.value!r} exceeds its signed resource policy."
            raise ValueError(msg)
        self._manifest_ref = manifest_ref
        self._payload_ref = payload_ref
        self._request = request
        self._reentry = reentry

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.ONE

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def is_executor_owned_runtime_step(self) -> bool:
        return True

    def supports_sql_batch_transport(self) -> bool:
        return False

    def requires_prior_step_boundary(self) -> bool:
        return True

    def dependencies(self) -> frozenset[str]:
        return frozenset({str(self._manifest_ref), str(self._payload_ref)})

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def compile(self, ctx: CompilationContext) -> CompiledStep[PreparedStagedDeltaStorage]:
        del ctx
        return CompiledStep()

    def execute_runtime(self, resolved: ResolvedRefs) -> PreparedStagedDeltaStorage:
        assert_python_reentry_operation_allowed(self._reentry.operation)
        manifest = resolved.get(str(self._manifest_ref))
        payload_row = resolved.get(str(self._payload_ref))
        if self._request.executing_session_id != self._request.owner_session_id:
            raise StagedFieldAuthorizationError("The current session does not own the finalized staged upload.")
        if manifest is None:
            return PreparedStagedDeltaStorage(rows=())
        if not isinstance(manifest, StagedFieldStream):
            raise StagedFieldError("The staged upload manifest is unavailable.")
        if manifest.owner_session_id != self._request.owner_session_id:
            raise StagedFieldAuthorizationError("The current session does not own the finalized staged upload.")
        if (
            manifest.sys_id != self._request.upload_id
            or manifest.storage_kind is not StagedFieldStorageKind.ORDINARY
            or str(manifest.table_key) != str(self._request.source_table)
            or manifest.row_id != self._request.row_sys_id
            or str(manifest.column_key) != str(self._request.source_column)
            or manifest.state is not StagedFieldStreamState.FINALIZED
            or manifest.expected_size != self._request.expected_size
            or manifest.actual_sha256 != self._request.expected_sha256
        ):
            raise StagedFieldError("The finalized staged upload does not match the insert candidate.")
        if not isinstance(payload_row, StagedFieldStreamPayload) or payload_row.payload is None:
            payload_type = type(payload_row).__name__
            msg = f"The finalized staged upload payload is unavailable (resolved type: {payload_type})."
            raise StagedDeltaPayloadUnavailableError(msg)
        if payload_row.sys_id != self._request.upload_id:
            raise StagedFieldError("The finalized staged payload identity does not match its manifest.")
        payload = bytes(payload_row.payload)
        if len(payload) > self._reentry.budget.max_input_bytes:
            msg = f"Python re-entry operation {self._reentry.operation.value!r} exceeds its signed input budget."
            raise ValueError(msg)
        payload_sha256 = hashlib.sha256(payload).hexdigest()
        if (
            len(payload) != self._request.expected_size
            or payload_sha256 != self._request.expected_sha256
            or (payload_row.content_hash is not None and payload_row.content_hash != self._request.expected_sha256)
        ):
            raise StagedFieldError("The finalized staged payload does not match its manifest.")
        request = StagedFieldDeltaPreparationRequest(
            upload_id=self._request.upload_id,
            owner_session_id=self._request.owner_session_id,
            executing_session_id=self._request.executing_session_id,
            source_table=self._request.source_table,
            source_column=self._request.source_column,
            row_sys_id=self._request.row_sys_id,
            expected_size=self._request.expected_size,
            expected_sha256=self._request.expected_sha256,
            content_value_id=self._request.content_value_id,
            payload=payload,
            config=self._request.config,
            revision_id=self._request.revision_id,
        )
        prepared = _execute_staged_delta_reentry(self._reentry.operation, request)
        output_rows = 1 + len(prepared.chunks) + len(prepared.ranges)
        output_bytes = len(prepared.content_value.manifest_payload) + sum(len(row.payload) for row in prepared.chunks)
        if output_rows > self._reentry.budget.max_output_rows or output_bytes > self._reentry.budget.max_output_bytes:
            msg = f"Python re-entry operation {self._reentry.operation.value!r} exceeds its signed output budget."
            raise ValueError(msg)
        return PreparedStagedDeltaStorage(rows=(prepared,))


_RowT = TypeVar("_RowT", ContentValue, ContentDedupChunk, ContentChunkRange)
_RowKind = Literal["content_value", "chunks", "ranges"]
_EXPECTED_MODEL_BY_ROW_KIND: dict[_RowKind, type[DatabaseObjectRow]] = {
    "content_value": ContentValue,
    "chunks": ContentDedupChunk,
    "ranges": ContentChunkRange,
}


_ModelT = TypeVar("_ModelT", bound=DatabaseObjectRow)


class FlattenStagedDeltaInsertResultsStep(NonPublishingStep[list[_ModelT]], Generic[_ModelT]):
    """Concatenate ordered per-candidate results from one staged batch."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        source_refs: tuple[ServerPlanRefId, ...],
        model_cls: type[_ModelT],
    ) -> None:
        super().__init__(ref_id)
        self._source_refs = source_refs
        self._model_cls = model_cls

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.MANY

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def is_executor_owned_runtime_step(self) -> bool:
        return True

    def supports_sql_batch_transport(self) -> bool:
        return False

    def requires_prior_step_boundary(self) -> bool:
        return True

    def dependencies(self) -> frozenset[str]:
        return frozenset(str(ref) for ref in self._source_refs)

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def compile(self, ctx: CompilationContext) -> CompiledStep[list[_ModelT]]:
        del ctx
        return CompiledStep()

    def execute_runtime(self, resolved: ResolvedRefs) -> list[_ModelT]:
        flattened: list[_ModelT] = []
        for ref in self._source_refs:
            rows = resolved.get(str(ref))
            if not isinstance(rows, Sequence) or isinstance(rows, (str, bytes, bytearray, memoryview)):
                raise TypeError("A staged delta batch child did not return a row sequence.")
            for row in rows:
                if not isinstance(row, self._model_cls):
                    raise TypeError(f"A staged delta batch child returned a row other than {self._model_cls.__name__}.")
                flattened.append(row)
        return flattened


class MaterializeStagedDeltaInsertResultStep(NonPublishingStep[list[_ModelT]], Generic[_ModelT]):
    """Restore the authored payload only on rows inserted by the owner write."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        owner_ref: ServerPlanRefId,
        payloads: tuple[StagedPayloadMaterialization, ...],
        after_refs: tuple[ServerPlanRefId, ...],
        model_cls: type[_ModelT],
    ) -> None:
        super().__init__(ref_id)
        self._owner_ref = owner_ref
        self._payloads = payloads
        self._after_refs = after_refs
        self._model_cls = model_cls

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.MANY

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def is_executor_owned_runtime_step(self) -> bool:
        return True

    def supports_sql_batch_transport(self) -> bool:
        return False

    def requires_prior_step_boundary(self) -> bool:
        return True

    def dependencies(self) -> frozenset[str]:
        refs = (self._owner_ref, *(payload.payload_ref for payload in self._payloads), *self._after_refs)
        return frozenset(str(ref) for ref in refs)

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def compile(self, ctx: CompilationContext) -> CompiledStep[list[_ModelT]]:
        del ctx
        return CompiledStep()

    def execute_runtime(self, resolved: ResolvedRefs) -> list[_ModelT]:
        owner_result = resolved.get(str(self._owner_ref))
        if owner_result is None:
            return []
        if isinstance(owner_result, self._model_cls) or isinstance(owner_result, Mapping):
            owner_rows: Sequence[object] = (owner_result,)
        elif isinstance(owner_result, Sequence) and not isinstance(owner_result, (str, bytes, bytearray, memoryview)):
            owner_rows = owner_result
        else:
            raise TypeError("The staged delta owner result is not a row sequence.")
        if not owner_rows:
            return []
        authored_values: dict[str, bytes | str] = {}
        for payload in self._payloads:
            payload_row = resolved.get(str(payload.payload_ref))
            if not isinstance(payload_row, StagedFieldStreamPayload) or payload_row.payload is None:
                raise StagedDeltaPayloadUnavailableError("The finalized staged upload payload is unavailable.")
            payload_bytes = bytes(payload_row.payload)
            if payload.content_type == "text":
                try:
                    authored_values[str(payload.column)] = payload_bytes.decode("utf-8")
                except UnicodeDecodeError as exc:
                    msg = f"The staged text payload for {payload.column!r} is not valid UTF-8."
                    raise StagedFieldError(msg) from exc
            else:
                authored_values[str(payload.column)] = payload_bytes
        materialized: list[_ModelT] = []
        for owner_row in owner_rows:
            if isinstance(owner_row, Mapping):
                from impl.common.l5200_sql_query.row_converter import convert_row_to_model

                owner_row = convert_row_to_model(self._model_cls, dict(owner_row))
            if not isinstance(owner_row, self._model_cls):
                raise TypeError(f"The staged delta owner result contains a row other than {self._model_cls.__name__}.")
            materialized_row = BaseModel.model_copy(owner_row, update=authored_values)
            if not isinstance(materialized_row, self._model_cls):
                raise TypeError("The staged delta result changed model type during materialization.")
            materialized.append(materialized_row)
        return materialized


class ProjectPreparedDeltaRowsStep(ServerPlanStep[list[_RowT]], Generic[_RowT]):
    """Publish one typed relation from prepared delta-storage rows."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        prepared_ref: ServerPlanRefId,
        model_cls: type[_RowT],
        row_kind: _RowKind,
        reentry: PythonReentrySpec,
    ) -> None:
        super().__init__(ref_id)
        self._prepared_ref = prepared_ref
        self._model_cls: type[_RowT] = model_cls
        self._row_kind = row_kind
        if _EXPECTED_MODEL_BY_ROW_KIND.get(row_kind) is not model_cls:
            raise ValueError("The staged delta row kind does not match its output model.")
        if prepared_ref != reentry.application_ref:
            raise ValueError("The projection source does not match the Python re-entry application reference.")
        if ref_id not in reentry.output_refs:
            raise ValueError("The projection ref is not declared by the Python re-entry spec.")
        output_index = reentry.output_refs.index(ref_id)
        declared_relation = reentry.output_relations[output_index]
        actual_columns = producer_publication_columns(model_cls)
        actual_hints = model_sql_column_type_hints(model_cls, actual_columns)
        if (
            reentry.output_relation_names[output_index] != model_cls.__name__
            or actual_hints is None
            or declared_relation
            != type(declared_relation)(
                columns=actual_columns,
                column_type_hints=actual_hints,
            )
        ):
            raise ValueError("The projection relation does not match the signed Python re-entry output.")
        self._reentry = reentry

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.MANY

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def is_executor_owned_runtime_step(self) -> bool:
        return True

    def supports_sql_batch_transport(self) -> bool:
        return False

    def requires_prior_step_boundary(self) -> bool:
        return True

    def dependencies(self) -> frozenset[str]:
        return frozenset({str(self._prepared_ref)})

    def consumes_executor_visible_dependencies(self) -> bool:
        return True

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def cte_publication_contract(self) -> CtePublicationContract:
        columns = producer_publication_columns(self._model_cls)
        hints = model_sql_column_type_hints(self._model_cls, columns)
        if hints is None:
            raise TypeError(f"{self._model_cls.__name__} has no SQL type hints.")
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=columns,
            column_type_hints=hints,
            model_cls=self._model_cls,
            relation_contract=CteRelationContract.model(self._model_cls),
            relation_role="python_reentry_rows",
            source_tables=None,
        )

    def publication_source_kind(self) -> PublicationSourceKind:
        return PublicationSourceKind.RUNTIME_SEMANTIC_VALUE

    def semantic_publication_columns(self) -> tuple[str, ...]:
        return self.cte_publication_contract().columns

    def semantic_publication_type_hints(self) -> SqlColumnTypeHints:
        return self.cte_publication_contract().column_type_hints

    def semantic_publication_relation_contract(self) -> CteRelationContract:
        return CteRelationContract.model(self._model_cls)

    def _python_reentry_spec(self) -> PythonReentrySpec:
        return self._reentry

    def publishes_executor_visible_binding(self) -> bool:
        return True

    def always_publishes_executor_visible_binding(self) -> bool:
        return True

    def executor_visible_published_rows(self) -> Sequence[dict[str, object]] | None:
        return None

    def compile(self, ctx: CompilationContext) -> CompiledStep[list[_RowT]]:
        del ctx
        output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(
            self.cte_publication_contract(),
        )
        return CompiledStep(
            executor_ref_ids=(str(self._prepared_ref),),
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
        )

    def execute_runtime(self, resolved: ResolvedRefs) -> list[_RowT]:
        prepared = resolved.get(str(self._prepared_ref))
        if not isinstance(prepared, PreparedStagedDeltaStorage):
            raise TypeError("The staged delta preparation result is unavailable.")
        if not prepared.rows:
            return []
        prepared_rows = prepared.rows[0]
        if self._row_kind == "content_value":
            rows: Sequence[ContentValue | ContentDedupChunk | ContentChunkRange] = (prepared_rows.content_value,)
        elif self._row_kind == "chunks":
            rows = prepared_rows.chunks
        else:
            rows = prepared_rows.ranges
        projected: list[_RowT] = []
        for row in rows:
            if not isinstance(row, self._model_cls):
                raise TypeError("The staged delta projection contains an unexpected row type.")
            projected.append(row)
        return projected

