def _as_scalar_revision_ref(
    value: RevisionId | ScalarServerRef[RevisionId] | None,
) -> ScalarServerRef[RevisionId] | None:
    return cast("ScalarServerRef[RevisionId] | None", value) if isinstance(value, ScalarServerRef) else None


def _scalar_to_str(value: object) -> str:
    unwrap_to_str = getattr(value, "unwrap_to_str", None)
    if callable(unwrap_to_str):
        return str(unwrap_to_str())
    return str(value)


def _require_commit_branch_projection_branch_input(
    *,
    literal_branch_id: str | None,
    branch_ref_id: str | None,
) -> None:
    if literal_branch_id is not None or branch_ref_id is not None:
        return
    msg = "Commit-branch context projection requires either a branch ref id or literal branch id"
    raise RuntimeError(msg)


def _cte_visible_columns(cte_ref: CteReference) -> tuple[str, ...]:
    if cte_ref.columns:
        return cte_ref.columns
    auxiliary_columns = getattr(cte_ref.auxiliary_query, "published_columns", None)
    if isinstance(auxiliary_columns, tuple):
        return auxiliary_columns
    return ()


