def runtime_verify_branch_tip_match_compiled_step(
    *,
    ctx: CompilationContext,
    fetch_ref: ServerPlanRefId,
    expected_tip_source: RevisionId | ScalarServerRef[RevisionId],
) -> CompiledStep[bool]:
    """Compile a SQL-visible branch-tip comparison."""
    from impl.common.l2050_sql_types.sql_branded_types import (
        SqlAliasName,
        SqlColumnName,
        SqlTableName,
    )
    from impl.common.l2070_server_plan.steps._compile_server_ref import lower_scalar_source
    from impl.common.l2070_server_plan.steps._runtime_replanning_error import (
        raise_missing_cte_fallback_forbidden,
    )
    from impl.common.l2100_sql_grammar.tree.clauses import SqlSelectAlias, SqlSelectList
    from impl.common.l2100_sql_grammar.tree.enums import BinaryOp
    from impl.common.l2100_sql_grammar.tree.expr_compound import SqlSubquery
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef
    from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp
    from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
    from impl.common.l2100_sql_grammar.tree.statements import SqlSelect

    expected_shape = (
        inspect_server_value_shape_for_planning(
            expected_tip_source,
            site="runtime_verify_branch_tip_match_compiled_step",
        )
        if isinstance(expected_tip_source, ScalarServerRef)
        else None
    )
    expected_ref_id = None if expected_shape is None else expected_shape.symbolic_ref_id
    fetch_cte = ctx.cte_refs.get(str(fetch_ref))
    if not isinstance(fetch_cte, CteReference):
        raise_missing_cte_fallback_forbidden(
            site_name="runtime_verify_branch_tip_match_compiled_step",
            trigger=f"fetch ref {fetch_ref!r} has no SQL-visible rowset",
            blocked_path="Commit branch tip verification cannot read Python FetchBranchResult runtime refs.",
            result_contract="branch tip verification must compare SQL-visible fetch and expected-tip facts.",
            implementation_requirements=(
                "Publish fetched branch tip as a SQL-visible CTE.",
                "Lower expected tip sources to SQL scalar expressions.",
            ),
        )
    fetch_columns = _cte_visible_columns(fetch_cte)
    if "current_tip_revision_id" in fetch_columns:
        tip_column = "current_tip_revision_id"
    elif "_branch_tip" in fetch_columns:
        tip_column = "_branch_tip"
    else:
        tip_column = "tip_revision_sys_id"
    current_tip_expr = SqlSubquery(
        SqlSelect(
            select=SqlSelectList([SqlColumnRef(SqlColumnName(tip_column))]),
            from_=SqlTableIdent(SqlTableName(fetch_cte.ref_id)),
            limit=1,
        ),
    )
    expected_expr = lower_scalar_source(expected_tip_source, ctx)

    __opa002_grammar_181 = SqlSelect(
        select=SqlSelectList(
            [
                SqlSelectAlias(
                    SqlBinaryOp(current_tip_expr, BinaryOp.EQ, expected_expr),
                    SqlAliasName("__matches"),
                ),
            ],
        ),
    )
    output_shape = CompiledOutputShape((synthetic_output_field("__matches", role="commit_branch_tip_match"),))
    column_type_hints = SqlColumnTypeHints(bool_columns=frozenset({"__matches"}))
    return CompiledStep(
        output_shape=output_shape,
        grammar=__opa002_grammar_181,
        needs_returning=True,
        result_relation=DeclaredResultRelation.from_output_shape(output_shape),
        column_type_hints=column_type_hints,
        closed_post_op=scalar_column_post_op(
            "__matches",
            default_value=False,
            use_default_on_empty=True,
            scalar_coercion=ScalarCoercionKind.BOOL,
        ),
        auxiliary_ctes=[(fetch_cte.ref_id, fetch_cte.auxiliary_query)] if fetch_cte.auxiliary_query is not None else None,
        allow_empty_provenance_manifest=True,
    )


def runtime_build_commit_branch_ctx_compiled_step(
    *,
    ctx: CompilationContext,
    fetch_ref: ServerPlanRefId,
    branch_ref_id: str | None,
    literal_branch_id: BranchId | None,
    new_revision_id: RevisionId,
    inline_staged_commit_ids: Sequence[StagedCommitId],
) -> CompiledStep[CommitBranchCtx]:
    from impl.common.l2050_sql_types.sql_branded_types import SqlAliasName, SqlColumnName, SqlTableName
    from impl.common.l2070_server_plan.steps._runtime_replanning_error import (
        raise_missing_cte_fallback_forbidden,
    )
    from impl.common.l2100_sql_grammar._expressions_all import NULL
    from impl.common.l2100_sql_grammar.domain.infra.stmt_dml_simple import SqlRawExpression
    from impl.common.l2100_sql_grammar.domain.versioning.stmt_cte import SqlUnionAll
    from impl.common.l2100_sql_grammar.tree.clauses import SqlSelectAlias, SqlSelectList, SqlTableAlias
    from impl.common.l2100_sql_grammar.tree.expr_compound import SqlCast, SqlSubquery
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlParam
    from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
    from impl.common.l2100_sql_grammar.tree.statements import SqlSelect
    from l1000_schema.json_type import JSONType
    from l1000_schema.typed_field import SqlCastTargetType

    fetch_cte = ctx.cte_refs.get(str(fetch_ref))
    if not isinstance(fetch_cte, CteReference):
        raise_missing_cte_fallback_forbidden(
            site_name="runtime_build_commit_branch_ctx_compiled_step",
            trigger=f"fetch ref {fetch_ref!r} has no SQL-visible rowset",
            blocked_path="Commit-branch context cannot be built from Python FetchBranchResult runtime refs.",
            result_contract="commit-branch context must compile from the SQL-visible branch fetch relation.",
            implementation_requirements=(
                "Publish the commit branch fetch step as a SQL-visible CTE before building CommitBranchCtx.",
                "Import cross-group branch refs as executor-published typed CTE bindings before compiling the batch.",
                "Do not return an uncontracted placeholder CompiledStep for contracted SQL producers.",
            ),
        )
    branch_expr: object
    branch_auxiliary_cte: tuple[str, object] | None = None
    _require_commit_branch_projection_branch_input(
        literal_branch_id=None if literal_branch_id is None else str(literal_branch_id),
        branch_ref_id=branch_ref_id,
    )
    if literal_branch_id is not None:
        branch_expr = SqlParam(str(literal_branch_id))
    elif branch_ref_id is not None:
        branch_cte = ctx.cte_refs.get(branch_ref_id)
        branch_field_name: str | None = None
        if not isinstance(branch_cte, CteReference):
            base_ref, separator, field_path = branch_ref_id.partition(".")
            base_cte = ctx.cte_refs.get(base_ref) if separator else None
            if isinstance(base_cte, CteReference) and field_path and "." not in field_path:
                branch_cte = base_cte
                branch_field_name = field_path
        if not isinstance(branch_cte, CteReference):
            raise_missing_cte_fallback_forbidden(
                site_name="runtime_build_commit_branch_ctx_compiled_step",
                trigger=f"branch ref {branch_ref_id!r} has no SQL-visible branch rowset",
                blocked_path="Commit-branch context cannot project branch id from Python runtime refs.",
                result_contract="commit-branch branch id must compile from a SQL-visible scalar fact.",
                implementation_requirements=(
                    "Publish symbolic branch ids as SQL-visible scalar CTEs.",
                    "Use terminal Python only to hydrate CommitBranchCtx from SQL rows.",
                ),
            )
        branch_column = branch_field_name or (branch_cte.columns[0] if branch_cte.columns else "branch_id")
        branch_expr = SqlSubquery(
            SqlSelect(
                select=SqlSelectList([SqlColumnRef(SqlColumnName(branch_column))]),
                from_=SqlTableIdent(SqlTableName(branch_cte.ref_id)),
                limit=1,
            ),
        )
        if branch_cte.auxiliary_query is not None:
            branch_auxiliary_cte = (branch_cte.ref_id, branch_cte.auxiliary_query)
    else:
        raise AssertionError("commit branch projection requires a literal branch id or SQL-visible branch ref")

    fetch_columns = _cte_visible_columns(fetch_cte)
    fetch_alias = SqlAliasName("commit_fetch")
    jsonb_cast_target = SqlCastTargetType(base_type="JSONB")
    current_tip_expr: object
    if "current_tip_revision_id" in fetch_columns:
        current_tip_expr = SqlColumnRef(SqlColumnName("current_tip_revision_id"), qualifier=fetch_alias)
    elif "_branch_tip" in fetch_columns:
        current_tip_expr = SqlColumnRef(SqlColumnName("_branch_tip"), qualifier=fetch_alias)
    elif fetch_columns:
        current_tip_expr = NULL
    else:
        current_tip_expr = SqlRawExpression(
            "(COALESCE(to_jsonb(\"commit_fetch\")->>'current_tip_revision_id', to_jsonb(\"commit_fetch\")->>'_branch_tip'))::uuid",
        )
    if "staged_commit_ids" in fetch_columns:
        staged_commit_expr: object = SqlCast(
            SqlColumnRef(SqlColumnName("staged_commit_ids"), qualifier=fetch_alias),
            jsonb_cast_target,
        )
    elif "staged_commit_id" in fetch_columns:
        staged_commit_expr = SqlRawExpression(
            'to_jsonb(ARRAY["commit_fetch"."staged_commit_id"::text])',
        )
    else:
        staged_commit_expr = NULL
    staged_commit_alias = "staged_commit_ids"
    fetch_select = SqlSelect(
        select=SqlSelectList(
            [
                SqlSelectAlias(branch_expr, SqlAliasName("branch_id")),
                SqlSelectAlias(
                    cast(Any, current_tip_expr),
                    SqlAliasName("current_tip_revision_id"),
                ),
                SqlSelectAlias(
                    cast(Any, staged_commit_expr),
                    SqlAliasName(staged_commit_alias),
                ),
                SqlSelectAlias(SqlParam(new_revision_id), SqlAliasName("new_revision_id")),
            ],
        ),
        from_=SqlTableAlias(SqlTableIdent(SqlTableName(fetch_cte.ref_id)), fetch_alias),
    )
    selects: list[SqlSelect] = [fetch_select]
    for staged_commit_id in inline_staged_commit_ids:
        inline_staged_expr = SqlCast(SqlParam(JSONType([str(staged_commit_id)])), jsonb_cast_target)
        selects.append(
            SqlSelect(
                select=SqlSelectList(
                    [
                        SqlSelectAlias(branch_expr, SqlAliasName("branch_id")),
                        SqlSelectAlias(NULL, SqlAliasName("current_tip_revision_id")),
                        SqlSelectAlias(cast(Any, inline_staged_expr), SqlAliasName(staged_commit_alias)),
                        SqlSelectAlias(SqlParam(new_revision_id), SqlAliasName("new_revision_id")),
                    ],
                ),
            ),
        )

    auxiliary_ctes: list[tuple[str, object]] = []
    if fetch_cte.auxiliary_query is not None:
        auxiliary_ctes.append((fetch_cte.ref_id, fetch_cte.auxiliary_query))
    if branch_auxiliary_cte is not None and branch_auxiliary_cte not in auxiliary_ctes:
        auxiliary_ctes.append(branch_auxiliary_cte)

    from l2070_batching.sql_column_type_hints import SqlColumnTypeHints

    compiled_hints = SqlColumnTypeHints(
        uuid_columns=frozenset({"branch_id", "current_tip_revision_id", "new_revision_id"}),
        jsonb_columns=frozenset({staged_commit_alias}),
    )
    output_shape = CompiledOutputShape(
        tuple(
            synthetic_output_field(column_name, role="commit_branch_ctx")
            for column_name in (
                "branch_id",
                "current_tip_revision_id",
                staged_commit_alias,
                "new_revision_id",
            )
        ),
    )

    output_shape = CompiledOutputShape(
        tuple(
            synthetic_output_field(column_name, role="commit_branch_ctx")
            for column_name in (
                "branch_id",
                "current_tip_revision_id",
                staged_commit_alias,
                "new_revision_id",
            )
        ),
    )

    return CompiledStep(
        grammar=selects[0] if len(selects) == 1 else SqlUnionAll(selects),
        needs_returning=True,
        closed_post_op=commit_branch_context_post_op(),
        output_shape=output_shape,
        result_relation=DeclaredResultRelation.from_output_shape(output_shape),
        column_type_hints=compiled_hints,
        auxiliary_ctes=auxiliary_ctes or None,
        allow_empty_provenance_manifest=True,
    )


