def _vector_maintenance_after_provider_apply(
    ctx: LoweringContext,
    *,
    ref_id: ServerPlanRefId,
    after_ref: ServerPlanRefId,
) -> tuple[list[ServerPlanStep[Any]], frozenset[ServerPlanRefId]]:
    from impl.common.l2070_server_plan.intent_vector_index_maintenance import (
        ProviderResolvedVectorIndexMaintenanceIntent,
    )
    from l1450_index_policy_contracts.vector_maintenance import VectorIndexMaintenanceOperation
    from l5200_vector_index.vector_config import get_vector_indexes

    catalog = ctx.planning_catalog
    if catalog is None:
        raise RuntimeError("embedding provider apply requires the planning catalog")
    steps: list[ServerPlanStep[Any]] = []
    completion_refs: set[ServerPlanRefId] = set()
    for model_cls in catalog.tables:
        if not isinstance(model_cls, type) or not issubclass(model_cls, DatabaseObjectRow):
            continue
        for index_name in get_vector_indexes(model_cls):
            maintenance_ref = ServerPlanRefId(f"{ref_id}.maintain_{len(completion_refs)}")
            completion_refs.add(maintenance_ref)
            intent = ProviderResolvedVectorIndexMaintenanceIntent(
                maintenance_ref,
                VectorIndexMaintenanceOperation.REBUILD,
                model_cls=model_cls,
                object_id=ServerRefs.scalar(SysId.new()),
                index=SqlIndexName(index_name),
                after_refs=frozenset({after_ref}),
            )
            steps.extend(intent.lower(ctx))
    return steps, frozenset(completion_refs)


def _provider_staging_columns(model_cls: type[DatabaseObjectRow[Any]]) -> tuple[str, ...]:
    return tuple(
        field_name
        for field_name in model_cls.model_fields
        if field_name not in {"created_at", "updated_at"}
    )


