        __opa002_grammar_168 = grammar
        output_shape = _embedding_validation_output_shape()
        return CompiledStep(
            output_shape=output_shape,
            result_relation=DeclaredResultRelation.from_output_shape(output_shape),
            column_type_hints=_embedding_validation_column_type_hints(),
            grammar=__opa002_grammar_168,
