class ApplyEmbeddingComputeReadyWholeResultsStep(_EmbeddingComputeApplyLoweringStep[None]):
    """Read ready whole-document staging rows and persist via visible embedding lowerings."""

    _tags = frozenset({"write", "embedding_compute_apply"})
    _cardinality = Cardinality.NONE
    _is_read_only = False

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        config: _ApplyEmbeddingComputeReadyWholeResultsConfig,
    ) -> None:
        super().__init__(ref_id)
        self._config = config

    def lower(self, ctx: LoweringContext) -> Sequence[ServerPlanStep[Any]]:
        from l5175_chunking.chunk_model import ChunkId
        from l5195_embedding_compute_tables import EmbeddingComputeRequestRow
        from l5200_vector_index.content_addressable_models import EmbeddingRef, EmbeddingVector

        token = self._config.apply_ready_token
        validate_ref = ServerPlanRefId(f"{self.ref_id}.validate_vectors")
        delete_ref = ServerPlanRefId(f"{self.ref_id}.delete_refs")
        vector_ref = ServerPlanRefId(f"{self.ref_id}.upsert_vectors")
        insert_ref = ServerPlanRefId(f"{self.ref_id}.insert_refs")
        result_table = get_table_name(EmbeddingComputeResultRow)
        request_table = get_table_name(EmbeddingComputeRequestRow)
        vector_table = get_table_name(EmbeddingVector)
        ref_table = get_table_name(EmbeddingRef)
        validate_dependency = frozenset({validate_ref})
        steps: list[ServerPlanStep[Any]] = [
            _ValidateReadyWholeEmbeddingVectorsStep(
                validate_ref,
                config=_ValidateReadyWholeEmbeddingVectorsConfig(apply_ready_token=token),
            ),
            GrammarEffectStep(
                delete_ref,
                SqlDeleteReadyWholeEmbeddingRefs(
                    result_table=result_table,
                    ref_table=ref_table,
                    ready_status=EMBEDDING_COMPUTE_RESULT_STATUS_READY,
                    request_kind=EMBEDDING_REQUEST_KIND_WHOLE,
                    apply_ready_token=token,
                    whole_document_chunk_id=str(ChunkId.whole_document()),
                ),
                _GrammarExecuteConfig(
                    reads=frozenset({result_table}),
                    writes=frozenset({ref_table}),
                    after_refs=validate_dependency,
                ),
            ),
            GrammarEffectStep(
                vector_ref,
                SqlUpsertReadyWholeEmbeddingVectors(
                    result_table=result_table,
                    request_table=request_table,
                    vector_table=vector_table,
                    ready_status=EMBEDDING_COMPUTE_RESULT_STATUS_READY,
                    request_kind=EMBEDDING_REQUEST_KIND_WHOLE,
                    apply_ready_token=token,
                ),
                _GrammarExecuteConfig(
                    reads=frozenset({result_table, request_table}),
                    writes=frozenset({vector_table}),
                    after_refs=validate_dependency,
                ),
            ),
            GrammarEffectStep(
                insert_ref,
                SqlInsertReadyWholeEmbeddingRefs(
                    result_table=result_table,
                    request_table=request_table,
                    ref_table=ref_table,
                    ready_status=EMBEDDING_COMPUTE_RESULT_STATUS_READY,
                    request_kind=EMBEDDING_REQUEST_KIND_WHOLE,
                    apply_ready_token=token,
                    whole_document_chunk_id=str(ChunkId.whole_document()),
                ),
                _GrammarExecuteConfig(
                    reads=frozenset({result_table, request_table}),
                    writes=frozenset({ref_table}),
                    after_refs=frozenset({delete_ref, vector_ref}),
                ),
            ),
        ]
        maintenance_steps, completion_refs = _vector_maintenance_after_provider_apply(
            ctx,
            ref_id=self.ref_id,
            after_ref=insert_ref,
        )
        steps.extend(maintenance_steps)
        steps.append(
            BarrierStep(
                ServerPlanRefId(self.ref_id),
                depends_on=completion_refs or frozenset({insert_ref}),
            )
        )
        return steps


