class ApplyEmbeddingComputeChunkBatchStep(_EmbeddingComputeApplyLoweringStep[None]):
    """Persist one chunk staging batch directly through SQL terminals."""

    _tags = frozenset({"write", "embedding_compute_apply"})
    _cardinality = Cardinality.NONE
    _is_read_only = False

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        config: _ApplyEmbeddingComputeChunkBatchConfig,
    ) -> None:
        super().__init__(ref_id)
        self._config = config

    def lower(self, ctx: LoweringContext) -> Sequence[ServerPlanStep[Any]]:
        from l5200_vector_index.content_addressable_models import EmbeddingRef, EmbeddingVector
        from l5200_vector_index.embedding_metadata import EmbeddingMetadata

        token = self._config.provider_batch_token
        validate_ref = ServerPlanRefId(f"{self.ref_id}.validate_vectors")
        delete_ref = ServerPlanRefId(f"{self.ref_id}.delete_refs")
        vector_ref = ServerPlanRefId(f"{self.ref_id}.upsert_vectors")
        insert_ref = ServerPlanRefId(f"{self.ref_id}.insert_refs")
        chunk_table = get_table_name(EmbeddingComputeChunkRow)
        metadata_table = get_table_name(EmbeddingMetadata)
        vector_table = get_table_name(EmbeddingVector)
        ref_table = get_table_name(EmbeddingRef)
        validate_dependency = frozenset({validate_ref})
        steps: list[ServerPlanStep[Any]] = [
            _ValidateChunkBatchEmbeddingVectorsStep(
                validate_ref,
                config=_ValidateChunkBatchEmbeddingVectorsConfig(provider_batch_token=token),
            ),
            GrammarEffectStep(
                delete_ref,
                SqlDeleteChunkBatchEmbeddingRefs(
                    chunk_table=chunk_table,
                    ref_table=ref_table,
                    provider_batch_token=token,
                ),
                _GrammarExecuteConfig(
                    reads=frozenset({chunk_table}),
                    writes=frozenset({ref_table}),
                    after_refs=validate_dependency,
                ),
            ),
            GrammarEffectStep(
                vector_ref,
                SqlUpsertChunkBatchEmbeddingVectors(
                    chunk_table=chunk_table,
                    metadata_table=metadata_table,
                    vector_table=vector_table,
                    provider_batch_token=token,
                ),
                _GrammarExecuteConfig(
                    reads=frozenset({chunk_table, metadata_table}),
                    writes=frozenset({vector_table}),
                    after_refs=validate_dependency,
                ),
            ),
            GrammarEffectStep(
                insert_ref,
                SqlInsertChunkBatchEmbeddingRefs(
                    chunk_table=chunk_table,
                    metadata_table=metadata_table,
                    ref_table=ref_table,
                    provider_batch_token=token,
                ),
                _GrammarExecuteConfig(
                    reads=frozenset({chunk_table, metadata_table}),
                    writes=frozenset({ref_table}),
                    after_refs=frozenset({delete_ref, vector_ref}),
                ),
            ),
        ]
        maintenance_steps, completion_refs = _vector_maintenance_after_provider_apply(
            ctx,
            ref_id=self.ref_id,
            after_ref=insert_ref,
        )
        steps.extend(maintenance_steps)
        steps.append(
            BarrierStep(
                ServerPlanRefId(self.ref_id),
                depends_on=completion_refs or frozenset({insert_ref}),
            )
        )
        return steps


