class QueryUpdateStep(SqlRelationPublisherStep[int]):
    """Step for executing query builder .update() operations."""

    def __init__(
        self: QueryUpdateStep,
        ref_id: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        config: _QueryUpdateStepConfig,
    ) -> None:
        """Initialize QueryUpdateStep.

        Args:
            ref_id: Unique identifier for this step
            model_cls: The DatabaseObjectRow subclass to update
            query_spec: The QuerySpec object with filters
            updates: Dictionary of field updates to apply
            after_refs: Extra dependency ref_ids (ordering constraints)
        """
        super().__init__(ref_id)
        self._model_cls = model_cls
        self._query_spec = config.query_spec
        self._updates = config.updates
        self._after_refs = config.after_refs
        self._user_id_ref_id = config.user_id_ref_id
        self._resolved_user_id: ResolvedPermissionUserId = None
        self._query_dependencies_cache: frozenset[str] | None = None
        self._cte_publication_contract_cache: CtePublicationContract | None = None

    @property
    def level(self: QueryUpdateStep) -> int:
        return 0

    def step_tags(self: QueryUpdateStep) -> frozenset[str]:
        """Return tags identifying this step type."""
        return frozenset({"write", "query", "update"})

    def is_read_only(self: QueryUpdateStep) -> bool:
        """Return False - this step modifies data."""
        return False

    def result_cardinality(self: QueryUpdateStep) -> Cardinality:
        """Return SCALAR - this step returns a row count."""
        return Cardinality.SCALAR

    def cte_relation_role(self: QueryUpdateStep) -> str:
        return "count_only"

    def cte_publication_contract(self: QueryUpdateStep) -> CtePublicationContract:
        if self._cte_publication_contract_cache is not None:
            return self._cte_publication_contract_cache
        columns = ("count",)
        column_type_hints = SqlColumnTypeHints(bigint_columns=frozenset({"count"}))
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        _contract_model_cls = _QueryUpdateStepCteRow
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        contract = CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=tuple(str(column) for column in columns),
            column_type_hints=column_type_hints,
            model_cls=_contract_model_cls,
            relation_contract=CteRelationContract.semantic_row(_contract_model_cls),
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )
        self._cte_publication_contract_cache = contract
        return contract

    def always_publishes_executor_visible_binding(self: QueryUpdateStep) -> bool:
        return True

    def tables_read(self: QueryUpdateStep) -> frozenset[str]:
        """Query update reads the table to evaluate the WHERE clause."""
        return frozenset({get_table_name(self._model_cls)})

    def tables_written(self: QueryUpdateStep) -> frozenset[str]:
        """Return the table name this step writes to."""
        return frozenset({get_table_name(self._model_cls)})

    def requires_materialized_inputs(self: QueryUpdateStep) -> bool:
        return (
            bool(self._after_refs)
            or self._user_id_ref_id is not None
            or self._query_spec is not None
            and _has_server_ref_in_filters(self._query_spec)
        )

    def ordered_transport_inlines_dependencies(self: QueryUpdateStep) -> bool:
        return True

    def requires_prior_step_boundary(self: QueryUpdateStep) -> bool:
        return False

    def dependencies(self: QueryUpdateStep) -> frozenset[str]:
        """Return ref_ids this step depends on (from query_spec filters + after_refs)."""
        deps: set[str] = {str(ref_id) for ref_id in self._after_refs}
        deps.update(self.sql_visible_dependencies())
        if self._user_id_ref_id is not None:
            deps.add(str(self._user_id_ref_id))
        return frozenset(deps)

    def lower(self: QueryUpdateStep, ctx: LoweringContext) -> list[ServerPlanStep[Any]]:
        from impl.common.l2070_server_plan.steps._versioned_staging import (
            build_large_column_spill_steps,
            prepare_large_column_spill_plan_from_tuples,
        )
        from l1000_schema.large_column import get_large_column_configs, large_column_pointer_name
        from l1000_schema.typed_field import Expression, Field
        from l2070_batching.sql_renderable import SqlRenderable

        spill_steps: list[ServerPlanStep[Any]] = []
        effective_updates = dict(self._updates)
        for config in get_large_column_configs(self._model_cls):
            column = str(config.column)
            if column not in effective_updates:
                continue
            value = effective_updates[column]
            if isinstance(value, (Expression, Field, SqlRenderable)):
                continue
            pointer = large_column_pointer_name(ContentColumnName(column))
            if value is None:
                effective_updates[pointer] = None
                continue
            rows, spill_plan = prepare_large_column_spill_plan_from_tuples(
                self._model_cls,
                [column, pointer],
                [(value, None)],
                backend_type=ctx.backend_type,
            )
            rewritten = rows[0]
            effective_updates[column] = rewritten[0]
            effective_updates[pointer] = rewritten[1]
            if spill_plan.rows:
                spill_steps.extend(
                    build_large_column_spill_steps(
                        self._model_cls,
                        spill_plan,
                        write_ref_id=ServerPlanRefId(f"{self.ref_id}.{column}.spill"),
                    ),
                )
        if not spill_steps and effective_updates == self._updates:
            return [self]
        self._updates = effective_updates
        self._after_refs = frozenset(
            (*self._after_refs, *(ServerPlanRefId(step.ref_id) for step in spill_steps)),
        )
        return [*spill_steps, self]

    def sql_visible_dependencies(self: QueryUpdateStep) -> frozenset[str]:
        """Return query dependencies; lowering may add separate ordering refs."""
        if self._query_dependencies_cache is not None:
            return self._query_dependencies_cache
        deps: set[str] = set()
        if self._query_spec is not None:
            from impl.common.l2070_server_plan.steps._resolve import collect_query_spec_deps

            deps.update(collect_query_spec_deps(self._query_spec))
        result = frozenset(deps)
        self._query_dependencies_cache = result
        return result

    def compile(self: QueryUpdateStep, ctx: CompilationContext) -> CompiledStep[int]:
        """Compile UPDATE table SET ... WHERE ... to SQL grammar."""
        from impl.common.l2050_sql_types.sql_branded_types import SqlCteName
        from impl.common.l2070_server_plan.steps._query_helper_compile import (
            compile_query_update_step,
        )
        from l1000_schema.table_utils import bounded_identifier_with_suffix

        from l2070_batching.output_shape import (
            CompiledOutputShape,
            DeclaredResultRelation,
            synthetic_output_field,
        )

        compiled = compile_query_update_step(
            self._model_cls,
            self._query_spec,
            self._updates,
            ctx,
            step_ref_id=self.ref_id,
            resolved_user_id=(
                self._resolved_user_id
                if self._resolved_user_id is not None
                else resolved_permission_user_id_from_ref(self._user_id_ref_id, ctx)
            ),
            updated_rows_cte_name=SqlCteName(
                bounded_identifier_with_suffix(
                    SchemaObjectName(str(self.ref_id)),
                    SchemaObjectSuffix("_updated_rows"),
                ),
            ),
        )
        contract = self.cte_publication_contract()
        output_shape = CompiledOutputShape(
            tuple(synthetic_output_field(column) for column in contract.columns),
        )
        return replace(
            compiled,
            output_shape=output_shape,
            result_relation=DeclaredResultRelation.from_output_shape(output_shape),
            column_type_hints=contract.column_type_hints,
        )


class QueryUpdateReturningStep[T](ServerPlanStep[list[T]]):
    """Execute a query builder .update_returning() operation — returns updated rows."""

    def __init__(
        self: QueryUpdateReturningStep,
        ref_id: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        config: _QueryUpdateReturningStepConfig,
    ) -> None:
        super().__init__(ref_id)
        self._model_cls = model_cls
        self._query_spec = config.query_spec
        self._updates = config.updates
        self._after_refs = config.after_refs
        self._allow_ordered_statement_batch = config.allow_ordered_statement_batch
        self._user_id_ref_id = config.user_id_ref_id
        self._returning_projections = config.returning_projections
        self._closed_post_op = config.closed_post_op
        self._readback_query_spec = config.readback_query_spec
        self._permission_action = config.permission_action
        self._resolved_user_id: ResolvedPermissionUserId = None

    @property
    def level(self: QueryUpdateReturningStep) -> int:
        return 1

    def step_tags(self: QueryUpdateReturningStep) -> frozenset[str]:
        return frozenset({"write", "query", "update", "returning"})

    def result_cardinality(self: QueryUpdateReturningStep) -> Cardinality:
        return Cardinality.MANY

    def publishes_executor_visible_binding(self: QueryUpdateReturningStep) -> bool:
        """The lowered raw update step owns executor-visible publication."""
        return False

    def always_publishes_executor_visible_binding(self: QueryUpdateReturningStep) -> bool:
        """Author-level update-returning wrappers do not publish their own ref."""
        return False

    def tables_read(self: QueryUpdateReturningStep) -> frozenset[str]:
        """Query update reads the table to evaluate the WHERE clause."""
        return frozenset({get_table_name(self._model_cls)})

    def tables_written(self: QueryUpdateReturningStep) -> frozenset[str]:
        return frozenset({get_table_name(self._model_cls)})

    def requires_materialized_inputs(self: QueryUpdateReturningStep) -> bool:
        return self._user_id_ref_id is not None or (self._query_spec is not None and _has_server_ref_in_filters(self._query_spec))

    def requires_prior_step_boundary(self: QueryUpdateReturningStep) -> bool:
        # PostgreSQL data-modifying CTEs share one statement snapshot. An UPDATE
        # ordered after another write must therefore start a new statement to
        # observe the dependency's effects on the base table.
        return bool(self._after_refs) or self.requires_materialized_inputs()

    def requires_prior_statement_visibility_after_writes(
        self: QueryUpdateReturningStep,
    ) -> frozenset[str]:
        if not self._after_refs:
            return frozenset()
        return self.tables_written()

    def dependencies(self: QueryUpdateReturningStep) -> frozenset[str]:
        deps: set[str] = {str(ref_id) for ref_id in self._after_refs}
        if self._query_spec is not None:
            from impl.common.l2070_server_plan.steps._resolve import collect_query_spec_deps

            deps.update(collect_query_spec_deps(self._query_spec))
        if self._user_id_ref_id is not None:
            deps.add(str(self._user_id_ref_id))
        return frozenset(deps)

    def sql_visible_dependencies(self: QueryUpdateReturningStep) -> frozenset[str]:
        deps: set[str] = set()
        if self._query_spec is not None:
            from impl.common.l2070_server_plan.steps._resolve import collect_query_spec_deps

            deps.update(collect_query_spec_deps(self._query_spec))
        return frozenset(deps)

    def lower(self: QueryUpdateReturningStep, ctx: LoweringContext) -> list[ServerPlanStep[Any]]:
        del ctx
        updates = dict(self._updates)
        from l1000_schema.large_column import get_large_column_configs, large_column_pointer_name

        for config in get_large_column_configs(self._model_cls):
            if config.column in updates and updates[config.column] is None:
                updates[large_column_pointer_name(config.column)] = None
        return [
            QueryUpdateReturningRawStep(
                self.ref_id,
                self._model_cls,
                _QueryUpdateReturningStepConfig(
                    query_spec=self._query_spec,
                    updates=updates,
                    after_refs=self._after_refs,
                    allow_ordered_statement_batch=self._allow_ordered_statement_batch,
                    user_id_ref_id=self._user_id_ref_id,
                    returning_projections=self._returning_projections,
                    closed_post_op=CompiledPostOp.materialize(
                        ResultMaterializationSpec(
                            behavior=PostOpBehavior.TERMINAL_ARRAY,
                            model_cls=self._model_cls,
                        ),
                    ),
                    readback_query_spec=self._readback_query_spec,
                    permission_action=self._permission_action,
                ),
            ),
        ]

    def compile(self: QueryUpdateReturningStep, ctx: CompilationContext) -> CompiledStep:
        del ctx
        raise NotImplementedError(f"{type(self).__name__} must be lowered before compile()")


class QueryUpdateReturningRawStep(QueryUpdateReturningStep[dict[str, Any]]):
    """Terminal raw-row variant of query update returning."""

    raw_access_authorized = True

    @property
    def level(self) -> int:
        return 0

    def step_tags(self) -> frozenset[str]:
        return frozenset({"write", "query", "update", "returning", "raw"})

    def cte_publication_contract(self: QueryUpdateReturningRawStep) -> CtePublicationContract:
        from impl.common.l2070_server_plan.steps._query_helper_compile import (
            query_update_returning_output_columns,
        )

        columns = query_update_returning_output_columns(
            self._model_cls,
            self._returning_projections,
        )
        column_type_hints = model_sql_column_type_hints(self._model_cls, columns)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        _contract_model_cls = cte_projection_row_model(
            f"{type(self).__name__}CteRow",
            tuple(str(column) for column in columns),
            column_type_hints,
        )
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=tuple(str(column) for column in columns),
            column_type_hints=column_type_hints,
            model_cls=_contract_model_cls,
            relation_contract=CteRelationContract.semantic_row(_contract_model_cls),
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def affected_count_source_contract(self: QueryUpdateReturningRawStep) -> AffectedCountSourceContract:
        return AffectedCountSourceContract(
            sql_ref=self.ref_id,
            producer_ref=self.ref_id,
            scheduling_dependency_ref=self.ref_id,
            representation=AffectedCountSourceRepresentation.ROW_RELATION,
            ordered_statement_mode=AffectedCountOrderedStatementMode.DRIVER_COUNT,
        )

    def always_publishes_executor_visible_binding(self) -> bool:
        return True

    def supports_sql_batch_transport(self) -> bool:
        return True

    def supports_ordered_sql_statement_batch(self) -> bool:
        return self._allow_ordered_statement_batch

    def publishes_executor_visible_binding(self) -> bool:
        return True

    def lower(self, ctx: LoweringContext) -> list[ServerPlanStep[Any]]:
        del ctx
        return [self]

    def compile(self, ctx: CompilationContext) -> CompiledStep:
        """Compile UPDATE table SET ... WHERE ... RETURNING * to SQL grammar."""
        from impl.common.l2070_server_plan.steps._query_helper_compile import (
            compile_query_update_returning_step,
        )
        from l2070_batching.post_op import row_dicts_post_op
        from l2070_batching.output_shape import (
            CompiledOutputShape,
            DeclaredResultRelation,
            synthetic_output_field,
        )

        compiled = compile_query_update_returning_step(
            self._model_cls,
            self._query_spec,
            self._updates,
            ctx,
            resolved_user_id=(
                self._resolved_user_id
                if self._resolved_user_id is not None
                else resolved_permission_user_id_from_ref(self._user_id_ref_id, ctx)
            ),
            closed_post_op=self._closed_post_op or row_dicts_post_op(),
            returning_projections=self._returning_projections,
            readback_query_spec=self._readback_query_spec,
            publication_ref_id=self.ref_id,
            publication_contract=self.cte_publication_contract(),
            permission_action=self._permission_action,
        )
        contract = self.cte_publication_contract()
        if contract is None:
            return compiled
        output_shape = CompiledOutputShape(
            tuple(synthetic_output_field(column) for column in contract.columns),
        )
        # Preserve all compiled transport artifacts while applying the producer
        # publication contract.
        return compiled.with_output_contract(
            output_shape=output_shape,
            column_type_hints=contract.column_type_hints,
            result_relation=DeclaredResultRelation.from_output_shape(output_shape),
        )

"""Intents and steps for finding object branch/revision history.

Each Intent is an L4 step whose ``lower()`` produces L0 grammar steps.
All I/O happens inside the pipeline executor; ``lower()`` is pure computation.
"""

from __future__ import annotations
from l2070_batching.sql_column_type_hints import SqlColumnTypeHints
