def _stringify_scalar(value: object) -> str:
    unwrap = getattr(value, "unwrap_to_str", None)
    if callable(unwrap):
        return str(unwrap())
    return str(value)


def _row_column_values(raw: RawResult, column: str) -> list[str]:
    values: list[str] = []
    for row in raw:
        row_dict = dict(row) if not isinstance(row, dict) else row
        value = row_dict.get(column)
        if value is not None:
            values.append(str(value))
    return values


def _non_deleted_condition() -> Any:
    from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName
    from impl.common.l2100_sql_grammar.tree.enums import BinaryOp
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlParam
    from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp, SqlIsNull, sql_or

    deleted_col = SqlColumnRef(SqlColumnName("sys_deleted"))
    return sql_or(
        SqlIsNull(deleted_col),
        SqlBinaryOp(deleted_col, BinaryOp.EQ, SqlParam(False)),
    )


def _current_only_conditions(current_only: bool) -> list[Any]:
    if not current_only:
        return []

    from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef
    from impl.common.l2100_sql_grammar.tree.expr_ops import SqlIsNull

    return [
        SqlIsNull(SqlColumnRef(SqlColumnName("sys_valid_to_revision_id"))),
        _non_deleted_condition(),
    ]


def _branch_filter_conditions(branch_id_value: str | None) -> list[Any]:
    if branch_id_value is None:
        return []

    from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName
    from impl.common.l2100_sql_grammar.tree.enums import BinaryOp
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlParam
    from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp

    return [
        SqlBinaryOp(
            SqlColumnRef(SqlColumnName("branch_id")),
            BinaryOp.EQ,
            SqlParam(branch_id_value),
        ),
    ]


def _deleted_filter_conditions(include_deleted: bool) -> list[Any]:
    if include_deleted:
        return []
    return [_non_deleted_condition()]


