# Pattern matching step references like "step_0", "step_0.sys_id", or "step_0.sys_id.unwrap_to_str"
_STEP_REF_PATTERN = re.compile(r"^step_\d+(?:\.[a-zA-Z_][a-zA-Z0-9_]*)*$")

# Exact builtin instances cannot define dependency_ref_id; subclasses still can.
_BUILTIN_LEAF_TYPES: frozenset[type[object]] = frozenset(
    {str, int, float, bool, bytes, type(None), date, datetime, time, timedelta, Decimal}
)
_BUILTIN_NON_CARRIER_TYPES: frozenset[type[object]] = _BUILTIN_LEAF_TYPES | frozenset(
    {bytearray, memoryview, dict, list, tuple, set, frozenset}
)


def _resolved_dict(resolved: ResolvedRefs) -> dict[str, Any]:
    """Extract dict from ResolvedRefs for value resolution."""
    out = getattr(resolved, "_data", resolved)
    if isinstance(out, dict):
        return out
    return {}


# ---------------------------------------------------------------------------
# Resolution helpers (migrated from _sequential_dispatch.py)
# ---------------------------------------------------------------------------


def resolve_value(value: Any, resolved: ResolvedRefs) -> Any:
    """Resolve a value that may be a ServerRef or a string step reference.

    If the value is a ServerRef, look up its resolved value.
    If the value is a string matching the step reference pattern
    (e.g. ``"step_0"`` or ``"step_0.sys_id"``), resolve it from
    the ``resolved`` dict.
    """
    resolved_dict = _resolved_dict(resolved)
    if isinstance(value, ScalarSequenceServerRef) and value.ref_id is not None and value.field_identity is not None:
        return value
    if isinstance(value, ServerRef):
        ref_id = value.ref_id
        if ref_id is None:
            return value
        return resolve_ref_id(ServerPlanRefId(ref_id), resolved_dict)
    if isinstance(value, str) and _STEP_REF_PATTERN.match(value):
        return resolve_ref_id(ServerPlanRefId(value), resolved_dict)
    return value


def resolve_ref_id(ref_id: ServerPlanRefId, resolved: dict[str, Any]) -> Any:
    """Resolve a ref_id (possibly with field access) to its value."""
    parts = ref_id.split(".")

    if len(parts) == 1:
        # Simple ref like "step_0"
        return resolved[ref_id]
    # Field access like "step_0.sys_id"
    base_ref = parts[0]
    obj = resolved[base_ref]
    # If the base object is None, field access should also return None
    # This handles the case where first_later() returned no match
    if obj is None:
        return None
    for field_name in parts[1:]:
        # Map field access over list items if obj is a list
        # (e.g., [item.sys_id for item in items])
        obj = [getattr(item, field_name) for item in obj if item is not None] if isinstance(obj, list) else getattr(obj, field_name)
        if obj is None:
            return None
        # Call unwrap_to_str etc. when the result is a callable (method)
        if isinstance(obj, list):
            obj = [x() if callable(x) and not isinstance(x, type) else x for x in obj]
        elif callable(obj) and not isinstance(obj, type):
            obj = obj()
    return obj


def apply_filter_operator(
    q: Any,
    model_cls: type[DatabaseObjectRow],
    field_name: str,
    operator: str,
    value: Any,
) -> Any:
    """Apply a filter with the given operator to the query.

    Raises:
        InjectionAttemptError: If the operator is not in the allowed set
    """
    # Get the field descriptor from the model class
    # Use helper to handle polymorphic inheritance (issue #1044)
    field_descriptor = get_model_field(model_cls, DynamicFieldName(field_name))
    field_expr: Field[Any, Any] = field(field_descriptor)

    # Handle list values: when a ServerRef resolves to a list
    # (e.g., from execute_later().sys_id), automatically use IN
    # operator instead of = for equality checks
    new_q = q
    if operator == "=" and isinstance(value, list):
        # Empty list means no matches possible
        new_q = new_q.filter(field_expr == None).filter(field_expr != None) if not value else new_q.filter(IN(field_expr, tuple(value)))
    elif operator == "=":
        new_q = new_q.filter(field_expr == value)
    elif operator == "!=" and isinstance(value, list):
        # Excluding an empty relation is the identity predicate. Non-empty
        # relation exclusions use NOT IN rather than scalar list comparison.
        new_q = new_q if not value else new_q.filter(~IN(field_expr, tuple(value)))
    elif operator == "!=":
        new_q = new_q.filter(field_expr != value)
    elif operator == "<":
        new_q = new_q.filter(field_expr < value)
    elif operator == "<=":
        new_q = new_q.filter(field_expr <= value)
    elif operator == ">":
        new_q = new_q.filter(field_expr > value)
    elif operator == ">=":
        new_q = new_q.filter(field_expr >= value)
    elif operator == "IN":
        new_q = new_q.filter(IN(field_expr, value))
    elif operator == "NOT IN":
        new_q = new_q.filter(~IN(field_expr, value))
    elif operator == "LIKE":
        from l1000_schema.typed_field import LIKE

        new_q = new_q.filter(LIKE(field_expr, value))
    elif operator == "JSON_ARRAY_CONTAINS_REF":
        # This operator must be lowered into SQL EXISTS expressions by
        # _resolve_json_array_contains_ref_filters() or
        # _resolve_json_array_contains_literal_filters() before any legacy
        # execute() fallback path runs.
        msg = "JSON_ARRAY_CONTAINS_REF is not supported in the legacy resolve query path. Use the SQL-lowered ServerPlan path instead."
        raise NotImplementedError(msg)
    else:
        # Security: Reject unknown operators to prevent injection
        from l1100_exceptions.security import InjectionAttemptError

        msg = f"Invalid filter operator: {operator!r}"
        raise InjectionAttemptError(
            msg,
            injection_type="sql_operator",
            attempted_value=operator,
        )

    return new_q


def apply_query_spec_to_query(
    q: Any,
    query_spec: Any,
    model_cls: type[DatabaseObjectRow],
    resolved: ResolvedRefs,
) -> Any:
    """Apply QuerySpec filters, order_by, limit, offset to a query builder.

    Uses apply_filter_operator and resolve_value from _sequential_dispatch
    (transitional — will be replaced when old dispatch is deleted in Phase 6).

    This is the execute() fallback path for non-SQL backends or simple queries.
    Advanced features (joins, group_by, aggregations, FTS, vector, etc.) go
    through the compile() path (SQL grammar), not this fallback.
    """

    UNSUPPORTED_IN_FALLBACK = [
        "joins",
        "group_by",
        "aggregations",
        "having",
        "window_functions",
        "fts_query",
        "vector_index_name",
    ]
    for attr in UNSUPPORTED_IN_FALLBACK:
        if hasattr(query_spec, attr) and getattr(query_spec, attr):
            msg = f"QuerySpec.{attr} requires SQL compilation (compile() path), not execute() fallback"
            raise NotImplementedError(msg)

    if hasattr(query_spec, "distinct") and query_spec.distinct:
        q = q.distinct()

    if hasattr(query_spec, "select_columns") and query_spec.select_columns:
        q = q.select(*query_spec.select_columns)

    if query_spec.filters:
        for f in query_spec.filters:
            if f.expression is not None:
                q = q.filter(f.expression)
                continue
            if f.column is None or f.operator is None:
                continue
            resolved_val = resolve_value(f.value, resolved)
            op = f.operator
            col = f.column
            from l1000_schema.typed_field import Expression

            if op in (
                "LIKE",
                "ILIKE",
                "REGEXP",
                "IREGEXP",
                "IN",
                "!=",
                ">",
                ">=",
                "<",
                "<=",
            ):
                q = q.filter(Expression(field=col, operator=op, value=resolved_val))
            else:
                q = apply_filter_operator(q, model_cls, col, op, resolved_val)

    if query_spec.order_by:
        for column, direction in query_spec.order_by:
            q = q.order_by(column, direction=direction)

    if query_spec.limit is not None:
        q = q.limit(query_spec.limit)

    if query_spec.offset is not None:
        q = q.offset(query_spec.offset)

    return q


def _resolve_value_recursive(value: Any, resolved: ResolvedRefs) -> Any:
    """Recursively resolve ServerRef values in nested structures."""
    if isinstance(value, ScalarSequenceServerRef) and value.ref_id is not None and value.field_identity is not None:
        # Every schema-typed runtime list remains symbolic through physical
        # compilation. Terminal binding resolves its request-local seed.
        return value
    if isinstance(value, ServerRef):
        return resolved.resolve_server_ref(value)
    if isinstance(value, list):
        new_list = [_resolve_value_recursive(v, resolved) for v in value]
        return new_list if any(n is not o for n, o in zip(new_list, value, strict=True)) else value
    if isinstance(value, dict):
        new_dict = {k: _resolve_value_recursive(v, resolved) for k, v in value.items()}
        return new_dict if any(new_dict[k] is not value[k] for k in value) else value
    if isinstance(value, BaseModel):
        return resolve_instance_refs(value, resolved)
    return value


def resolve_instance_refs(instance: BaseModel, resolved: ResolvedRefs) -> Any:
    """Resolve ServerRef fields in a Pydantic model instance.

    Scans all fields on the instance for ServerRef values and resolves
    them via ``resolved.resolve_server_ref()``.  Returns a new instance
    (via ``model_copy``) if any fields were resolved, or the original
    instance if nothing changed.

    Args:
        instance: Pydantic model instance (may contain ServerRef field values)
        resolved: ResolvedRefs providing resolve_server_ref()

    Returns:
        Instance with all ServerRef fields replaced by concrete values
    """
    updates: dict[str, Any] = {}
    for field_name in type(instance).model_fields:
        value = getattr(instance, field_name)
        new_val = _resolve_value_recursive(value, resolved)
        if new_val is not value:
            updates[field_name] = new_val
    if updates:
        if hasattr(instance, "model_copy"):
            return instance.model_copy(update=updates)
        return instance
    return instance


def _collect_dependency_refs_from_payload(
    value: object,
    refs: set[str],
    seen: dict[int, object] | None = None,
    *,
    preserve_dotted_refs: bool = False,
) -> None:
    with intent_build_context_lazy():
        _collect_dependency_refs_from_payload_in_context(
            value,
            refs,
            seen,
            preserve_dotted_refs=preserve_dotted_refs,
        )


def _collect_dependency_refs_from_payload_in_context(
    value: object,
    refs: set[str],
    seen: dict[int, object] | None,
    *,
    preserve_dotted_refs: bool,
) -> None:
    if seen is None:
        seen = {}
    stack: list[object] = [value]
    visited: dict[int, object] = {}
    type_kinds: dict[type[object], PayloadKind] = {}
    while stack:
        current = stack.pop()
        current_id = id(current)
        if type(current) in _BUILTIN_LEAF_TYPES or current_id in seen or current_id in visited:
            continue
        visited[current_id] = current
        if type(current) not in _BUILTIN_NON_CARRIER_TYPES and isinstance(current, _SqlDependencyRefCarrier):
            ref_text = str(current.dependency_ref_id())
            refs.add(ref_text if preserve_dotted_refs else ref_text.split(".", 1)[0])
            continue
        current_type = type(current)
        kind = type_kinds.get(current_type)
        if kind is None:
            kind = classify_payload(current)
            type_kinds[current_type] = kind
        if kind == "expression":
            refs.update(getattr(current, "server_ref_dependencies", ()) or ())
        if kind == "server_ref":
            assert isinstance(current, ServerRef)
            ref_id = current.ref_id
            if ref_id is None:
                continue
            ref_text = str(ref_id)
            base_ref = ref_text.split(".", 1)[0]
            if base_ref.startswith("seed_"):
                found_seed, seed_value = read_seeded_constant_from_ctx(None, ServerPlanRefId(ref_text))
                if not found_seed:
                    found_seed, seed_value = read_seeded_constant_from_ctx(None, ServerPlanRefId(base_ref))
                if found_seed:
                    stack.append(seed_value)
                continue
            refs.add(ref_text if preserve_dotted_refs else base_ref)
            continue
        if kind in {"string", "server_plan_ref_id", "leaf", "opaque_carrier", "unsupported"}:
            continue

        if kind == "expression" or payload_kind_needs_identity_guard(kind):
            value_id = id(current)
            if value_id in seen:
                continue
            # Retain temporary payloads so Python cannot recycle a visited identity.
            seen[value_id] = current

        stack.extend(traversable_payload_children_for_kind(current, kind))


def _collect_deps_recursive(
    value: Any,
    refs: set[str],
    seen: dict[int, object] | None = None,
) -> None:
    """Backward-compatible alias for payload-contract-backed dependency walking."""
    _collect_dependency_refs_from_payload(value, refs, seen)


def _query_cte_source_names(value: object, seen: set[int] | None = None) -> set[str]:
    """Collect CTE relation sources from a nested query program."""

    from impl.common.l2060_query_spec.query_source import (
        AliasedSource,
        CteSource,
        DerivedQuerySource,
    )

    visited = set() if seen is None else seen
    value_id = id(value)
    if value_id in visited:
        return set()
    visited.add(value_id)
    names: set[str] = set()

    def _add_source(source: object) -> None:
        while isinstance(source, AliasedSource):
            source = source.source
        if isinstance(source, CteSource):
            names.add(str(source.cte_name))
        elif isinstance(source, DerivedQuerySource):
            names.update(_query_cte_source_names(source.query, visited))

    _add_source(getattr(value, "source", None))
    for join in getattr(value, "joins", ()) or ():
        _add_source(getattr(join, "target_source", None))
    for definition in getattr(value, "ctes", ()) or ():
        names.update(_query_cte_source_names(definition.query, visited))
    for branch in getattr(value, "branches", ()) or ():
        names.update(_query_cte_source_names(branch.query_spec, visited))
    return names


def _defined_query_cte_names(value: object, seen: set[int] | None = None) -> set[str]:
    """Collect statement-local CTE names that cannot be ServerPlan dependencies."""

    visited = set() if seen is None else seen
    value_id = id(value)
    if value_id in visited:
        return set()
    visited.add(value_id)
    names: set[str] = set()
    from impl.common.l2060_query_spec.query_source import AliasedSource, DerivedQuerySource

    source = getattr(value, "source", None)
    while isinstance(source, AliasedSource):
        source = source.source
    if isinstance(source, DerivedQuerySource):
        names.update(_defined_query_cte_names(source.query, visited))
    for definition in getattr(value, "ctes", ()) or ():
        names.add(str(definition.name))
        names.update(_defined_query_cte_names(definition.query, visited))
    for branch in getattr(value, "branches", ()) or ():
        names.update(_defined_query_cte_names(branch.query_spec, visited))
    return names


def collect_query_spec_deps(spec: Any) -> frozenset[str]:
    """Collect dependency ref_ids from ServerRef values in query-spec state."""
    from impl.common.l2070_server_plan.steps._compile_helpers import _expression_ast_value

    refs: set[str] = set(getattr(spec, "server_ref_dependencies", ()) or ())
    # Retain visited objects to prevent identity reuse during the structural walk.
    seen: dict[int, object] = {}
    refs.update(_query_cte_source_names(spec))
    from impl.common.l2060_query_spec.query_source import AliasedSource, CteSource

    source = getattr(spec, "source", None)
    while isinstance(source, AliasedSource):
        source = source.source
    if isinstance(source, CteSource):
        refs.add(str(source.cte_name))
    if isinstance(spec, ServerRef):
        _collect_dependency_refs_from_payload(spec, refs, seen, preserve_dotted_refs=True)
        return frozenset(refs)
    dependency_values: list[object] = [spec]
    filters = getattr(spec, "filters", None) or []
    for f in filters:
        refs.update(getattr(f, "server_ref_dependencies", ()) or ())
        expression_filter = _expression_ast_value(f)
        if expression_filter is not None:
            dependency_values.append(expression_filter)
            continue
        value = getattr(f, "value", None)
        if value is not None:
            dependency_values.append(value)
        expr = getattr(f, "expression", None)
        if expr is not None:
            expression_value = _expression_ast_value(expr)
            dependency_values.append(expression_value if expression_value is not None else expr)
    for col in getattr(spec, "select_columns", None) or ():
        expression = getattr(col, "expression", None)
        candidate = expression if expression is not None else col
        expression_value = _expression_ast_value(candidate)
        dependency_values.append(expression_value if expression_value is not None else candidate)
    for aggregation in getattr(spec, "aggregations", None) or ():
        for attr_name in ("expression", "source_expression"):
            expression = getattr(aggregation, attr_name, None)
            if expression is None:
                continue
            expression_value = _expression_ast_value(expression)
            dependency_values.append(expression_value if expression_value is not None else expression)
    for expression in getattr(spec, "having", None) or ():
        expression_value = _expression_ast_value(expression)
        dependency_values.append(expression_value if expression_value is not None else expression)
    branch_filter = getattr(spec, "branch_filter", None)
    if branch_filter is not None:
        dependency_values.append(branch_filter)
    revision_filter = getattr(spec, "revision_filter", None)
    if revision_filter is not None:
        dependency_values.append(revision_filter)
    _collect_dependency_refs_from_payload(dependency_values, refs, seen, preserve_dotted_refs=True)
    permission_context_ref = getattr(spec, "permission_context_ref", None)
    if permission_context_ref is not None:
        refs.add(str(permission_context_ref))
    refs.difference_update(_defined_query_cte_names(spec))
    return frozenset(refs)


def collect_instances_deps(instances: Iterable[object]) -> frozenset[str]:
    """Collect model dependencies in one walk without retaining mutable row state."""
    refs: set[str] = set()
    models = [instance for instance in instances if isinstance(instance, BaseModel)]
    _collect_dependency_refs_from_payload(models, refs)
    return frozenset(refs)


def collect_instance_deps(instance: DatabaseObjectRow | Any) -> frozenset[str]:
    """Collect dependency ref_ids from ServerRef fields in a model instance.

    Extracts the **base** ref_id (before any dot) from each ServerRef,
    since dependency ordering operates on step ref_ids, not field paths.

    If ``instance`` is a LazyResult (not yet resolved), returns an empty
    frozenset — lazy dependencies are tracked separately via lazy_param_deps.
    """
    from l2055_lazy_result.lazy_result import LazyResult

    if isinstance(instance, LazyResult):
        return frozenset()
    if isinstance(instance, BaseModel):
        dumped_refs: set[str] = set()
        _collect_dependency_refs_from_payload(instance, dumped_refs)
        return frozenset(dumped_refs)
    return frozenset()

