def _resolve_cte_name(ctx: CompilationContext, ref_id: ServerPlanRefId) -> str:
    """Map a logical step ref to the concrete batched CTE alias when present."""

    if ctx.cte_refs is None:
        return ref_id
    mapped = ctx.cte_refs.get(ref_id)
    if mapped is None:
        return ref_id
    return mapped.ref_id


def _resolve_cte_binding(ctx: CompilationContext, ref_id: ServerPlanRefId) -> CteReference | None:
    if ctx.cte_refs is None:
        return None
    direct = ctx.cte_refs.get(ref_id)
    return direct if isinstance(direct, CteReference) else None


def _resolve_cte_name_for_source(ctx: CompilationContext, ref_id: ServerPlanRefId, binding: CteReference) -> str:
    direct = ctx.cte_refs.get(ref_id) if ctx.cte_refs is not None else None
    if direct is binding:
        return _resolve_cte_name(ctx, ref_id)
    return binding.ref_id


def _has_cte_binding(ctx: CompilationContext, ref_id: ServerPlanRefId) -> bool:
    return ctx.cte_refs is not None and ref_id in ctx.cte_refs


@dataclass(frozen=True, slots=True)
class _ProjectScalarFieldConfig[T]:
    source_ref: ServerPlanRefId
    field_name: str
    dependency_ref: ServerPlanRefId | None = None
    source_model_cls: type[DatabaseObjectRow[Any]] | None = None
    scalar_coercion: ScalarCoercionKind = ScalarCoercionKind.NONE
    sequence: bool = False


@pure_lazy
def _source_model_for_scalar_projection[StepsItemT](
    source_ref: ServerPlanRefId,
    steps: Sequence[ServerPlanStep[StepsItemT]],
) -> type[DatabaseObjectRow[Any]] | None:
    candidate_refs = [str(source_ref)]
    hydrated_marker = ".hydrated"
    if hydrated_marker in str(source_ref):
        candidate_refs.append(str(source_ref).split(hydrated_marker, 1)[0])

    for candidate_ref in candidate_refs:
        for step in steps:
            if str(step.ref_id) != candidate_ref:
                continue
            contract = step.cte_publication_contract()
            if contract is not None:
                relation_contract = contract.relation_contract
                source_model_cls = None if relation_contract is None else relation_contract.source_model_cls
                if isinstance(source_model_cls, type) and issubclass(source_model_cls, DatabaseObjectRow):
                    return source_model_cls
                contract_model_cls = contract.model_cls
                if isinstance(contract_model_cls, type) and issubclass(contract_model_cls, DatabaseObjectRow):
                    return contract_model_cls
            published_model_cls = getattr(step, "published_model_cls", None)
            if isinstance(published_model_cls, type):
                return published_model_cls
            if callable(published_model_cls):
                resolved_model_cls = published_model_cls()
                if isinstance(resolved_model_cls, type):
                    return resolved_model_cls
            return None

    return None


@pure_lazy
def _scalar_coercion_from_source_contract[StepsItemT](
    source_ref: ServerPlanRefId,
    field_name: str,
    steps: Sequence[ServerPlanStep[StepsItemT]],
) -> ScalarCoercionKind:
    candidate_refs = [str(source_ref)]
    if ".hydrated" in str(source_ref):
        candidate_refs.append(str(source_ref).split(".hydrated", 1)[0])
    for candidate_ref in candidate_refs:
        for step in steps:
            if str(step.ref_id) != candidate_ref:
                continue
            hints = step.cte_publication_contract().column_type_hints
            if field_name in hints.bool_columns:
                return ScalarCoercionKind.BOOL
            if field_name in (hints.integer_columns | hints.bigint_columns):
                return ScalarCoercionKind.INT
            if field_name in hints.text_columns:
                return ScalarCoercionKind.STR
    return ScalarCoercionKind.NONE


@pure_lazy
def project_scalar_field_config_from_steps[StepsItemT](
    *,
    source_ref: ServerPlanRefId,
    field_name: str,
    steps: Sequence[ServerPlanStep[StepsItemT]],
    scalar_coercion: ScalarCoercionKind = ScalarCoercionKind.NONE,
) -> _ProjectScalarFieldConfig[object]:
    if scalar_coercion is ScalarCoercionKind.NONE:
        scalar_coercion = {
            "branch_id": ScalarCoercionKind.BRANCH_ID,
            "revision_id": ScalarCoercionKind.REVISION_ID,
            "tip_revision_id": ScalarCoercionKind.REVISION_ID,
            "workspace_id": ScalarCoercionKind.WORKSPACE_ID,
            "user_id": ScalarCoercionKind.USER_ID,
            "tip_materialization": ScalarCoercionKind.BRANCH_TIP_MATERIALIZATION,
            "branchpoint_materialization": ScalarCoercionKind.BRANCHPOINT_MATERIALIZATION,
        }.get(field_name, scalar_coercion)
    if scalar_coercion is ScalarCoercionKind.NONE:
        scalar_coercion = _scalar_coercion_from_source_contract(
            source_ref,
            field_name,
            steps,
        )
    source_step = next(
        (step for step in steps if step.ref_id == source_ref),
        None,
    )
    publication_ref = source_step.sequence_result_source_ref() if source_step is not None else source_ref
    return _ProjectScalarFieldConfig(
        source_ref=publication_ref,
        field_name=field_name,
        dependency_ref=source_ref,
        source_model_cls=_source_model_for_scalar_projection(source_ref, steps),
        scalar_coercion=scalar_coercion,
    )


def _scalar_projection_annotation(
    *,
    source_ref: ServerPlanRefId,
    field_name: str,
    source_model_cls: type[DatabaseObjectRow[Any]] | None,
    scalar_coercion: ScalarCoercionKind,
) -> object:
    if scalar_coercion is ScalarCoercionKind.BOOL:
        return bool | None
    if scalar_coercion is ScalarCoercionKind.INT:
        return int | None
    if scalar_coercion in {
        ScalarCoercionKind.STR,
        ScalarCoercionKind.BRANCH_TIP_MATERIALIZATION,
        ScalarCoercionKind.BRANCHPOINT_MATERIALIZATION,
    }:
        return str | None
    if scalar_coercion in {
        ScalarCoercionKind.SYS_ID,
        ScalarCoercionKind.BRANCH_ID,
        ScalarCoercionKind.REVISION_ID,
        ScalarCoercionKind.WORKSPACE_ID,
        ScalarCoercionKind.USER_ID,
        ScalarCoercionKind.QUEUE_MESSAGE_ID,
    }:
        return UUID | None
    if field_name == "sys_id" or field_name.endswith("_id"):
        return SysId | None
    if source_model_cls is not None and field_name in source_model_cls.model_fields:
        annotation = source_model_cls.model_fields[field_name].annotation
        if isinstance(annotation, TypeVar):
            annotation = annotation.__bound__
        if annotation is not None and annotation is not Any and annotation is not object:
            return annotation
    if ".hydrated" in str(source_ref):
        return bytes | None
    return object


def _scalar_projection_model_cls(
    *,
    ref_id: ServerPlanRefId,
    source_ref: ServerPlanRefId,
    field_name: str,
    source_model_cls: type[DatabaseObjectRow[Any]] | None,
    scalar_coercion: ScalarCoercionKind,
) -> type[BaseModel]:
    class_name = "ProjectedScalarField_" + "".join(char if char.isalnum() else "_" for char in f"{str(ref_id)}_{field_name}")
    annotation = _scalar_projection_annotation(
        source_ref=source_ref,
        field_name=field_name,
        source_model_cls=source_model_cls,
        scalar_coercion=scalar_coercion,
    )
    namespace: dict[str, object] = {
        "model_config": ConfigDict(extra="forbid"),
        "__annotations__": {field_name: annotation},
        field_name: Field(default=None),
    }
    model_cls: type[BaseModel] = type(class_name, (BaseModel,), namespace)
    return model_cls


class ProjectScalarFieldStep[T](SqlRelationPublisherStep[T | list[T | None] | None]):
    """Project one scalar field from a prior resolved row or raw-row CTE."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        config: _ProjectScalarFieldConfig[T],
    ) -> None:
        super().__init__(ref_id)
        self._source_ref = config.source_ref
        self._dependency_ref = config.dependency_ref
        self._field_name = config.field_name
        self._source_model_cls = config.source_model_cls
        self._scalar_coercion = config.scalar_coercion
        self._sequence = config.sequence
        self._projection_model_cls = _scalar_projection_model_cls(
            ref_id=ref_id,
            source_ref=self._source_ref,
            field_name=self._field_name,
            source_model_cls=self._source_model_cls,
            scalar_coercion=self._scalar_coercion,
        )

    @property
    def level(self) -> int:
        return 0

    def step_tags(self) -> frozenset[str]:
        return frozenset({"read", "project", "scalar"})

    def is_read_only(self) -> bool:
        return True

    def execution_role(self) -> StepExecutionRole:
        if ".hydrated" in str(self._source_ref):
            return StepExecutionRole.APPLY
        return StepExecutionRole.SQL

    def emits_sql_for_accounting(self) -> bool | None:
        return ".hydrated" not in str(self._source_ref)

    def is_executor_owned_runtime_step(self) -> bool:
        return ".hydrated" in str(self._source_ref)

    def requires_prior_step_boundary(self) -> bool:
        return self._dependency_ref is not None or ".hydrated" in str(self._source_ref)

    def can_resolve_before_sql_execution(self) -> bool:
        return ".hydrated" in str(self._source_ref)

    def supports_sql_batch_transport(self) -> bool:
        return self._dependency_ref is None and ".hydrated" not in str(self._source_ref)

    def consumes_executor_visible_dependencies(self) -> bool:
        return True

    def result_cardinality(self) -> Cardinality:
        return Cardinality.MANY if self._sequence else Cardinality.ONE

    def declares_consumed_rows_reduction(self) -> bool:
        return not self._sequence

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def dependencies(self) -> frozenset[str]:
        source_ref = str(self._dependency_ref or self._source_ref)
        if ".hydrated" in source_ref:
            source_ref = source_ref.split(".hydrated", 1)[0]
        return frozenset({source_ref})

    def cte_publication_contract(self: ProjectScalarFieldStep) -> CtePublicationContract:
        columns = (self._field_name,)

        def _legacy_cte_column_type_hints(columns: tuple[str, ...] | None) -> SqlColumnTypeHints:
            column = self._field_name
            if self._source_model_cls is not None:
                model_hints = model_sql_column_type_hints(self._source_model_cls, (column,))
                if model_hints is not None and model_hints.has_any():
                    return model_hints
            if self._scalar_coercion is ScalarCoercionKind.BOOL:
                return SqlColumnTypeHints(bool_columns=frozenset({column}))
            if self._scalar_coercion is ScalarCoercionKind.INT:
                return SqlColumnTypeHints(bigint_columns=frozenset({column}))
            if self._scalar_coercion is ScalarCoercionKind.STR:
                return SqlColumnTypeHints(text_columns=frozenset({column}))
            if self._scalar_coercion in {
                ScalarCoercionKind.SYS_ID,
                ScalarCoercionKind.BRANCH_ID,
                ScalarCoercionKind.REVISION_ID,
                ScalarCoercionKind.WORKSPACE_ID,
                ScalarCoercionKind.USER_ID,
                ScalarCoercionKind.QUEUE_MESSAGE_ID,
            }:
                return SqlColumnTypeHints(uuid_columns=frozenset({column}))
            if self._scalar_coercion in {
                ScalarCoercionKind.BRANCH_TIP_MATERIALIZATION,
                ScalarCoercionKind.BRANCHPOINT_MATERIALIZATION,
            }:
                return SqlColumnTypeHints(text_columns=frozenset({column}))
            if column == "sys_id" or column.endswith("_id"):
                return SqlColumnTypeHints(uuid_columns=frozenset({column}))
            if ".hydrated" in str(self._source_ref):
                return SqlColumnTypeHints(bytea_columns=frozenset({column}))
            return SqlColumnTypeHints()

        column_type_hints = _legacy_cte_column_type_hints(columns)
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        _contract_model_cls = self._projection_model_cls
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        relation_contract = (
            CteRelationContract.projection_over_model(
                source_model_cls=self._source_model_cls,
                projection_lineage=((self._field_name, self._field_name),),
            )
            if self._source_model_cls is not None
            else CteRelationContract.semantic_row(self._projection_model_cls)
        )
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=tuple(str(column) for column in columns),
            column_type_hints=column_type_hints,
            model_cls=_contract_model_cls,
            relation_contract=relation_contract,
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def compile(self, ctx: CompilationContext) -> CompiledStep[T | list[T | None] | None]:
        closed_post_op = (
            scalar_column_list_post_op(
                self._field_name,
                scalar_coercion=self._scalar_coercion,
            )
            if self._sequence
            else scalar_column_post_op(
                self._field_name,
                default_value=None,
                use_default_on_empty=True,
                scalar_coercion=self._scalar_coercion,
            )
        )
        if ".hydrated" in str(self._source_ref):
            output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(
                self.cte_publication_contract(),
            )
            return CompiledStep(
                output_shape=output_shape,
                result_relation=result_relation,
                column_type_hints=column_type_hints,
            )
        binding = _resolve_cte_binding(ctx, self._source_ref)
        if binding is not None:
            source_column = (
                get_db_column_name(self._source_model_cls, DynamicFieldName(self._field_name))
                if self._source_model_cls is not None
                else self._field_name
            )
            if source_column not in binding.columns:
                msg = (
                    f"Cannot project {self._source_ref!r}.{self._field_name}: SQL-visible source "
                    f"{binding.ref_id!r} publishes columns {binding.columns!r}"
                )
                raise ValueError(msg)
            cte_name = _resolve_cte_name_for_source(ctx, self._source_ref, binding)
            __opa002_grammar_173 = (
                SqlSelect(
                    select=SqlSelectList(
                        [
                            SqlSelectAlias(
                                SqlColumnRef(SqlColumnName(source_column)),
                                SqlAliasName(self._field_name),
                            ),
                        ]
                    ),
                    from_=SqlTableIdent(SqlTableName(cte_name)),
                )
                if self._sequence
                else SqlSelectExpressions(
                    [
                        (
                            SqlCteFieldRef(
                                SqlCteStepName(cte_name),
                                SqlColumnName(source_column),
                            ),
                            self._field_name,
                        ),
                    ],
                )
            )
            output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(
                self.cte_publication_contract(),
            )
            return CompiledStep(
                output_shape=output_shape,
                result_relation=result_relation,
                column_type_hints=column_type_hints,
                grammar=__opa002_grammar_173,
                needs_returning=True,
                closed_post_op=closed_post_op,
                auxiliary_ctes=[(cte_name, binding.auxiliary_query)] if binding.auxiliary_query is not None else None,
            )
        try:
            projected_expr = lower_projected_ref_field(self._source_ref, self._field_name, ctx)
        except (NotImplementedError, RuntimeError) as exc:
            _raise_non_sql_field_projection_fallback_forbidden(
                self._source_ref,
                self._field_name,
            )
            raise AssertionError("unreachable") from exc
        __opa002_grammar_201 = SqlSelectExpressions(
            [
                (
                    projected_expr,
                    self._field_name,
                ),
            ],
        )
        output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(
            self.cte_publication_contract(),
        )
        return CompiledStep(
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
            grammar=__opa002_grammar_201,
            needs_returning=True,
            closed_post_op=closed_post_op,
        )

    def execute_runtime(self, resolved: ResolvedRefs) -> T | list[T | None] | None:
        source_key = str(self._source_ref)
        source: object = resolved.get(source_key, None)
        if source is None and ".hydrated" in source_key:
            source = resolved.get(source_key.split(".hydrated", 1)[0], None)

        def _project(item: object) -> T | None:
            if isinstance(item, BaseModel):
                value = getattr(item, self._field_name, None)
            elif isinstance(item, Mapping):
                value = item.get(self._field_name)
            else:
                return None
            return cast("T | None", coerce_scalar_value(value, self._scalar_coercion))

        if self._sequence:
            items = source if isinstance(source, Sequence) and not isinstance(source, str | bytes | bytearray) else ()
            return [_project(item) for item in items]
        if isinstance(source, Sequence) and not isinstance(source, str | bytes | bytearray):
            source = source[0] if source else None
        return _project(source)


def _raise_non_sql_field_projection_fallback_forbidden(
    source_ref: ServerPlanRefId,
    field_name: str,
) -> None:
    msg = (
        "ProjectScalarFieldStep requires executor-published SQL-visible bindings; "
        f"cannot project {source_ref!r}.{field_name} from materialized Python state"
    )
    raise NotImplementedError(msg)

