_BULK_SOURCE_ALIAS = "__bulk_src"
_SQL_CAST_OPEN = SqlFragment.static("CAST(")
_SQL_AS = SqlFragment.static(" AS ")
_SQL_CLOSE_PAREN = SqlFragment.static(")")
SchemaAnnotation = type | types.UnionType | types.GenericAlias | ForwardRef


@dataclass(frozen=True, slots=True)
class _LiteralColumn:
    db_column: str
    sql_type: str
    values: tuple[object, ...]


@dataclass(frozen=True, slots=True)
