@dataclass(frozen=True, slots=True)
class _TypedProjection(SqlRenderable):
    expr: SqlRenderable
    sql_type: str

    def render(self: _TypedProjection, dialect: SqlDialect) -> SqlFragment:
        return (
            _SQL_CAST_OPEN
            + self.expr.render(dialect)
            + _SQL_AS
            + SqlTypeIdent(SqlTypeName(self.sql_type)).render(dialect)
            + _SQL_CLOSE_PAREN
        )


def _literal_cell_value(value: object) -> object:
    shape = raw_cell_fact(value)
    if shape.symbolic_key is not None or shape.param_value is no_literal_sentinel():
        msg = "Symbolic row cells cannot be bound as PostgreSQL array parameters"
        raise TypeError(msg)
    return unwrap_literal_sql_value(shape.param_value)


def _postgres_array_value(sql_type: str, value: object) -> object:
    value = _literal_cell_value(value)
    sql_type_upper = sql_type.upper()
    if sql_type_upper.startswith("BIT") and isinstance(value, bytes):
        return "".join(f"{byte:08b}" for byte in value)
    if sql_type_upper.startswith("VECTOR"):
        if isinstance(value, bytes):
            from l5200_vector_index.embedding_type import EmbeddingType

            value = EmbeddingType(value)
        unwrap_sql_bind = getattr(value, "unwrap_sql_bind", None)
        coordinates = unwrap_sql_bind(BackendType.POSTGRES) if callable(unwrap_sql_bind) else value
        if isinstance(coordinates, str):
            if coordinates.startswith("[") and coordinates.endswith("]"):
                return "[" + ", ".join(item.strip() for item in coordinates[1:-1].split(",")) + "]"
            return coordinates
        if isinstance(coordinates, list | tuple):
            return "[" + ",".join(repr(float(item)) for item in coordinates) + "]"
    if sql_type_upper == "UUID" and value is not None:
        if isinstance(value, UUID):
            return value
        unwrap_to_uuid = getattr(value, "unwrap_to_uuid", None)
        if callable(unwrap_to_uuid):
            return unwrap_to_uuid()
        try:
            return UUID(str(value))
        except (TypeError, ValueError):
            return value
    if sql_type_upper != "JSONB" or value is None:
        return value
    from impl.common.l2100_sql_params.sql_param_normalization import normalize_postgres_json_bind_value

    return normalize_postgres_json_bind_value(value)


def has_symbolic_row_cells(
    rows: Sequence[Sequence[object]],
    *,
    row_facts: RawRowFacts | None = None,
) -> bool:
    """Return True when any raw row cell needs SQL-side symbolic lowering."""
    facts = row_facts or build_raw_row_facts(rows)
    return facts.has_symbolic_cells


def _default_field_for_symbolic_cell(value: object, db_column: str) -> str:
    from l1200_versioned_ids import BranchId, RevisionId, StagedCommitId
    from l1400_types import WorkspaceId

    if not isinstance(value, ServerRef):
        return "sys_id"
    if value._type_hint in {BranchId, RevisionId, StagedCommitId, WorkspaceId}:
        return db_column
    return "sys_id"


def _lower_typed_projected_row_cell(
    value: object,
    ctx: CompilationContext,
    *,
    db_column: str,
    sql_type: str | None,
) -> SqlRenderable:
    if sql_type is not None and (sql_type.upper() == "JSONB" or sql_type.upper().startswith("VECTOR")):
        shape = raw_cell_fact(value)
        if shape.symbolic_key is None and shape.param_value is not no_literal_sentinel():
            return SqlParam(_postgres_array_value(sql_type, value))
        lowered = lower_scalar_row_cell(value, ctx, default_field=_default_field_for_symbolic_cell(value, db_column))
        if isinstance(lowered, SqlParam):
            from dataclasses import replace

            from impl.common.l2100_sql_params.runtime_bind_slot import SqlRuntimeBindSlot

            if isinstance(lowered.value, SqlRuntimeBindSlot):
                return SqlParam(replace(lowered.value, json_encoded=True))
        return lowered
    return lower_scalar_row_cell(value, ctx, default_field=_default_field_for_symbolic_cell(value, db_column))


