def _postgres_array_sql_type_for_field(
    field_name: str,
    field_info: Any,
    *,
    resolved_hints: dict[str, SchemaAnnotation],
    dialect: SqlDialect,
) -> str | None:
    from impl.common.l3000_schema_builder.schema_builder import _get_sql_type, embedding_column_sql_type
    from l1000_schema.json_type import is_json_column, is_json_field_for_planning
    from l1400_types.type_surface_contracts import RawSqlText, UnknownVectorDimensions, VectorDimensions
    from vector_types import is_embedding_annotation

    metadata = field_info.json_schema_extra if isinstance(field_info.json_schema_extra, dict) else {}
    override_sql_type = metadata.get("sql_type")
    if isinstance(override_sql_type, str):
        return override_sql_type
    annotation = resolved_hints.get(field_name, field_info.annotation)
    if is_json_field_for_planning(field_info) or is_json_column(annotation):
        return "JSONB"
    if annotation is None:
        return None
    sql_type: str = _get_sql_type(annotation, dialect)
    if is_embedding_annotation(annotation):
        dimensions_value = metadata.get("embedding_dimensions")
        dimensions = (
            VectorDimensions(dimensions_value)
            if isinstance(dimensions_value, int) and not isinstance(dimensions_value, bool)
            else UnknownVectorDimensions()
        )
        return embedding_column_sql_type(
            DynamicFieldName(field_name),
            dimensions,
            RawSqlText(sql_type),
            dialect,
        )
    return sql_type


def postgres_raw_bulk_column_types(
    model_cls: type[DatabaseObjectRow],
    columns: Sequence[str],
    *,
    write_plan: WriteMetadataPlan | None = None,
) -> tuple[str, ...] | None:
    """Return PostgreSQL array SQL types for raw write columns."""
    from impl.common.l2200_sql_dialect.sql_dialect import POSTGRES_DIALECT
    from impl.common.l3000_schema_builder.schema_builder import (
        _get_type_hints_with_schema_context,
    )
    from l1000_schema.schema_def import get_db_column_name

    from l2070_batching.write_column_policy import (
        collect_physical_table_fields,
        field_owner_class,
    )

    fields_by_column: dict[str, tuple[str, Any, dict[str, SchemaAnnotation]]] = {}
    hints_by_owner: dict[type[Any], dict[str, SchemaAnnotation]] = {}

    def field_entry(
        field_name: str,
        field_info: Any,
    ) -> tuple[str, Any, dict[str, SchemaAnnotation]]:
        owner_cls = field_owner_class(model_cls, field_name)
        resolved_hints = hints_by_owner.get(owner_cls)
        if resolved_hints is None:
            resolved_hints = {
                str(field_name): annotation for field_name, annotation in _get_type_hints_with_schema_context(owner_cls).items()
            }
            hints_by_owner[owner_cls] = resolved_hints
        return field_name, field_info, resolved_hints

    physical_fields = collect_physical_table_fields(model_cls)
    if write_plan is not None:
        for field_plan in write_plan.field_plans:
            field_info = physical_fields.get(field_plan.field_name)
            if field_info is None:
                continue
            entry = field_entry(field_plan.field_name, field_info)
            fields_by_column.setdefault(field_plan.field_name, entry)
            fields_by_column.setdefault(field_plan.db_column, entry)
    else:
        for field_name, field_info in physical_fields.items():
            owner_cls = field_owner_class(model_cls, field_name)
            db_column_name = get_db_column_name(owner_cls, DynamicFieldName(field_name))
            entry = field_entry(field_name, field_info)
            fields_by_column.setdefault(field_name, entry)
            fields_by_column.setdefault(db_column_name, entry)

    column_types: list[str] = []
    for column_name in columns:
        if column_name == "sys_fts_content_hash":
            column_types.append("TEXT")
            continue
        if column_name in {"sys_fts_hash_short", "sys_fts_hash_high"}:
            column_types.append("BIGINT")
            continue
        selected_field_entry = fields_by_column.get(column_name)
        if selected_field_entry is None:
            return None
        field_name, field_info, resolved_hints = selected_field_entry
        sql_type = _postgres_array_sql_type_for_field(
            field_name,
            field_info,
            resolved_hints=resolved_hints,
            dialect=POSTGRES_DIALECT,
        )
        if sql_type is None:
            return None
        column_types.append(sql_type)
    return tuple(column_types)


def _serialized_json_raw_cell(value: object) -> object:
    shape = raw_cell_fact(value)
    if shape.symbolic_key is not None or shape.param_value is no_literal_sentinel():
        return value
    literal = unwrap_literal_sql_value(shape.param_value)
    if isinstance(literal, str) and not isinstance(literal, TransportDecodedJsonString):
        return SerializedJsonText(literal)
    return value


def build_postgres_raw_bulk_rows(
    *,
    rows: Sequence[Sequence[object]],
    db_columns: Sequence[str],
    column_types: Sequence[str],
    ctx: CompilationContext,
    row_facts: RawRowFacts | None = None,
) -> PostgresRawBulkRows:
    """Build PostgreSQL row-source inputs for raw bulk write grammar."""
    facts = row_facts or build_raw_row_facts(rows)
    if facts.has_symbolic_cells:
        # Symbolic projections compile immediately; literal arrays normalize at render time.
        rows = tuple(
            tuple(
                _serialized_json_raw_cell(value) if sql_type.upper() == "JSONB" else value
                for sql_type, value in zip(column_types, row, strict=True)
            )
            for row in rows
        )
        return PostgresRawBulkRows(
            column_types=tuple(column_types),
            array_params=None,
            select_source=build_postgres_projected_row_select(
                rows=rows,
                db_columns=db_columns,
                column_types=column_types,
                ctx=ctx,
                row_facts=facts,
            ),
        )
    column_count = len(db_columns)
    if len(column_types) != column_count:
        msg = "db_columns and column_types must have the same length"
        raise ValueError(msg)
    if any(len(row) != column_count for row in rows):
        msg = "Each raw row must match the target column count"
        raise ValueError(msg)
    return PostgresRawBulkRows(
        column_types=tuple(column_types),
        array_params=tuple(
            SqlRowColumnArrayParam(
                rows,
                idx,
                normalizer=lambda value, sql_type=column_types[idx]: _postgres_array_value(
                    sql_type,
                    _serialized_json_raw_cell(value) if sql_type.upper() == "JSONB" else value,
                ),
            )
            for idx in range(column_count)
        ),
        select_source=None,
    )


def build_postgres_projected_row_select(
    *,
    rows: Sequence[Sequence[object]],
    db_columns: Sequence[str],
    column_types: Sequence[str],
    ctx: CompilationContext,
    row_facts: RawRowFacts | None = None,
) -> SqlSelect:
    """Build a PostgreSQL SELECT row source from literal arrays and SQL expressions."""
    if not rows:
        msg = "build_postgres_projected_row_select requires at least one row"
        raise ValueError(msg)
    if len(db_columns) != len(column_types):
        msg = "db_columns and column_types must have the same length"
        raise ValueError(msg)
    column_count = len(db_columns)
    if any(len(row) != column_count for row in rows):
        msg = "Each raw row must match the target column count"
        raise ValueError(msg)
    facts = row_facts or build_raw_row_facts(rows)
    if facts.column_count != column_count:
        msg = "Raw row facts do not match the target column count"
        raise ValueError(msg)

    literal_columns: list[_LiteralColumn] = []
    expression_columns: dict[str, _ExpressionColumn] = {}
    for idx, (db_column, sql_type) in enumerate(zip(db_columns, column_types, strict=True)):
        column_fact = facts.columns[idx]
        if not column_fact.has_symbolic_cells:
            literal_columns.append(
                _LiteralColumn(
                    db_column=db_column,
                    sql_type=sql_type,
                    values=tuple(_postgres_array_value(sql_type, row[idx]) for row in rows),
                ),
            )
            continue
        if column_fact.symbolic_key is None or column_fact.mixed_symbolic:
            msg = (
                "SQL-native bulk row projection requires each symbolic column to use one "
                f"uniform server-side scalar expression; column {db_column!r} mixes "
                "literal and symbolic values or uses different symbolic refs."
            )
            raise TypeError(msg)
        expression_columns[db_column] = _ExpressionColumn(
            db_column=db_column,
            expr=lower_scalar_row_cell(
                rows[0][idx],
                ctx,
                default_field=_default_field_for_symbolic_cell(rows[0][idx], db_column),
            ),
        )

    if literal_columns:
        from_source: SqlRenderable = SqlUnnestTableRef(
            alias=_BULK_SOURCE_ALIAS,
            columns=[column.db_column for column in literal_columns],
            column_types=[column.sql_type for column in literal_columns],
            array_params=[column.values for column in literal_columns],
        )
    else:
        from_source = SqlGenerateSeriesTableRef(
            alias=_BULK_SOURCE_ALIAS,
            row_count=len(rows),
        )

    select_items: list[SqlRenderable] = []
    literal_column_names = {column.db_column for column in literal_columns}
    for db_column, sql_type in zip(db_columns, column_types, strict=True):
        expression_column = expression_columns.get(db_column)
        if expression_column is not None:
            expr = expression_column.expr
        elif db_column in literal_column_names:
            expr = SqlColumnRef(
                SqlColumnName(db_column),
                qualifier=_BULK_SOURCE_ALIAS,
            )
        else:
            msg = f"No projected expression was built for bulk row column {db_column!r}"
            raise AssertionError(msg)
        select_items.append(SqlSelectAlias(_TypedProjection(expr, sql_type), SqlAliasName(db_column)))

    return SqlSelect(
        select_list=SqlItemList(select_items),
        from_=from_source,
    )


def build_projected_row_select(
    *,
    rows: Sequence[Sequence[object]],
    db_columns: Sequence[str],
    ctx: CompilationContext,
    row_facts: RawRowFacts | None = None,
    column_types: Sequence[str | None] | None = None,
    json_columns: frozenset[str] = frozenset(),
) -> SqlRenderable:
    """Build a backend-neutral SELECT source for raw rows with symbolic cells.

    SQLite and MySQL-family backends cannot bind a CTE ref inside a compact
    ``VALUES (?, ?)`` placeholder matrix. Representing each row as a SELECT arm
    keeps literal cells as bind params and symbolic cells as SQL expressions.
    """
    del row_facts
    if not rows:
        msg = "build_projected_row_select requires at least one row"
        raise ValueError(msg)
    column_count = len(db_columns)
    if any(len(row) != column_count for row in rows):
        msg = "Each raw row must match the target column count"
        raise ValueError(msg)
    if column_types is not None and len(column_types) != column_count:
        msg = "db_columns and column_types must have the same length"
        raise ValueError(msg)

    arms: list[SqlSelect] = []
    for row in rows:
        select_items: list[SqlSelectAlias] = []
        for idx, db_column in enumerate(db_columns):
            value = row[idx]
            if db_column in json_columns:
                shape = raw_cell_fact(value)
                if shape.symbolic_key is None and shape.param_value is not no_literal_sentinel():
                    select_items.append(
                        SqlSelectAlias(
                            SqlParam(to_json_sql_param_value(_literal_cell_value(value), is_json_column=True)),
                            SqlAliasName(db_column),
                        )
                    )
                    continue
            column_type = column_types[idx] if column_types is not None else None
            projected_cell = (
                _TypedProjection(
                    _lower_typed_projected_row_cell(
                        row[idx],
                        ctx,
                        db_column=db_column,
                        sql_type=column_type,
                    ),
                    column_type,
                )
                if column_type is not None
                else lower_scalar_row_cell(row[idx], ctx)
            )
            select_items.append(
                SqlSelectAlias(
                    projected_cell,
                    SqlAliasName(db_column),
                ),
            )
        arms.append(SqlSelect(select_list=SqlItemList(select_items)))

    if len(arms) == 1:
        return arms[0]

    from impl.common.l2100_sql_grammar.tree.clauses import SqlSetOp

    return SqlSetOp(SetOpKind.UNION_ALL, arms)

"""Semantic staged-row replacement intent.

The generic meaning is:

* remove any existing staged rows for ``(branch_id, staged_commit_id, sys_id)``
* insert the provided replacement staged rows

Generic SQL backends lower this to delete + insert.
Backend-specific executors may override lowering to a more efficient physical
shape, such as PostgreSQL raw upsert.
"""

