def _post_process_sum_resolved_ints(
    source_refs: tuple[ServerPlanRefId, ...],
    _raw_result: RawResult,
    _hydrator: Hydrator,
    runtime_refs: Mapping[str, object],
) -> int:
    def _coerce_count(value: object) -> int:
        if isinstance(value, int):
            return value
        if isinstance(value, str | bytes | bytearray):
            return int(value)
        msg = f"Expected int-like runtime ref count, got {type(value).__name__}"
        raise TypeError(msg)

    total = 0
    for ref_id in source_refs:
        value = runtime_refs.get(str(ref_id), 0)
        count = _coerce_count(value)
        total += count
    return total


