class ReplaceStagedRowsIntent(IntentStep[Any]):
    """L4 intent for replacing rows within one staged-commit scope."""

    intent_tags = frozenset({"write", "staged_replace", "versioned", "intent"})
    intent_cardinality = Cardinality.SCALAR

    @property
    def level(self: ReplaceStagedRowsIntent) -> int:
        """Internal semantic replacement lowers below public CRUD intents."""
        return 3

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        config: _ReplaceStagedRowsConfig,
    ) -> None:
        super().__init__(ref_id)
        payload = config
        self.staged_model = payload.staged_model
        self.branch_id = payload.branch_id
        self.literal_branch_id = payload.literal_branch_id
        self.staged_commit_id_raw = str(payload.staged_commit_id)
        self.branch_scope_token = payload.branch_scope_token
        self.sys_ids = list(payload.sys_ids)
        self.columns = [str(column) for column in payload.columns]
        self.rows = list(payload.rows)
        self.db_column_source = payload.db_column_source
        self.raw_row_facts = payload.raw_row_facts
        self.return_value = payload.return_value
        self.change_detection_columns = tuple(payload.change_detection_columns)
        self.after_refs = frozenset(payload.after_refs)
        self.isolate_from_sql_batch = payload.isolate_from_sql_batch

    def tables_written(self: ReplaceStagedRowsIntent) -> frozenset[str]:
        from l1000_schema.table_utils import get_table_name

        return frozenset({get_table_name(self.staged_model)})

    def lower(self: ReplaceStagedRowsIntent, ctx: LoweringContext) -> list[ServerPlanStep[Any]]:
        if ctx.backend_profile.traits.versioned_staging_transport is VersionedStagingTransport.SAME_STATEMENT_RELATION:
            from impl.common.l2070_server_plan.param_budget import fused_sql_param_budget

            return lower_replace_staged_rows_postgres(
                self,
                max_params_per_upsert=fused_sql_param_budget(ctx.backend_type) or 32767,
            )
        return lower_replace_staged_rows_generic(self, ctx=ctx)


