def lower_replace_staged_rows_generic(
    intent: ReplaceStagedRowsIntent,
    *,
    ctx: LoweringContext | None = None,
) -> list[ServerPlanStep[Any]]:
    """Lower staged-row replacement to delete + insert."""
    if intent.change_detection_columns:
        msg = "change-detection staged replacement requires PostgreSQL raw upsert lowering"
        raise NotImplementedError(msg)
    steps: list[ServerPlanStep[Any]] = []
    write_after_refs = set(intent.after_refs)
    staged_write = PendingStagedWrite(
        source_key=StagedSourceKey(
            staged_table_name=get_table_name(intent.staged_model),
            branch_scope_token=intent.branch_scope_token,
        ),
        staged_commit_id_raw=intent.staged_commit_id_raw,
        write_kind="replace",
    )

    if intent.sys_ids:
        delete_spec = build_delete_staged_spec(
            intent.staged_model,
            intent.literal_branch_id or intent.branch_id,
            intent.staged_commit_id_raw,
            intent.sys_ids,
        )
        # ``staged_commit_id`` is globally unique and already scopes the replace
        # to one branch transaction. Keeping a symbolic branch predicate here
        # duplicates the same guard while forcing its CTE into both statements
        # of SQLite's ordered delete/insert sequence.
        delete_spec = replace(
            delete_spec,
            filters=[query_filter for query_filter in delete_spec.filters if query_filter.column != "branch_id"],
        )
        if not intent.rows:
            fallback_value = 0 if intent.return_value is _UNSET else intent.return_value
            return [
                QueryDeleteStep(
                    ServerPlanRefId(f"{intent.ref_id}_delete_staged"),
                    intent.staged_model,
                    _QueryDeleteStepConfig(
                        query_spec=delete_spec,
                        after_refs=intent.after_refs,
                        effect_only=True,
                    ),
                ),
                ReturnValueStep(intent.ref_id, fallback_value),
            ]
        delete_ref = ServerPlanRefId(f"{intent.ref_id}_delete_staged")
        steps.append(
            QueryDeleteStep(
                delete_ref,
                intent.staged_model,
                _QueryDeleteStepConfig(
                    query_spec=delete_spec,
                    after_refs=intent.after_refs,
                    effect_only=True,
                ),
            ),
        )

    if not intent.rows:
        fallback_value = 0 if intent.return_value is _UNSET else intent.return_value
        return [ReturnValueStep(intent.ref_id, fallback_value)]

    rows_per_stmt = len(intent.rows) if ctx is None else _rows_per_statement(ctx.backend_type, len(intent.columns), len(intent.rows))
    if 0 < rows_per_stmt < len(intent.rows):
        chunk_refs: list[str] = []
        for idx, start in enumerate(range(0, len(intent.rows), rows_per_stmt)):
            chunk_ref = f"{intent.ref_id}_chunk_{idx}"
            chunk_refs.append(chunk_ref)
            steps.append(
                InsertManyRawStep(
                    ServerPlanRefId(chunk_ref),
                    intent.staged_model,
                    config=_InsertManyRawConfig(
                        columns=tuple(intent.columns),
                        rows=tuple(intent.rows[start : start + rows_per_stmt]),
                        db_column_source=intent.db_column_source,
                        raw_row_facts=None,
                        staged_write=staged_write,
                        after_refs=frozenset(write_after_refs),
                    ),
                ),
            )
        if intent.return_value is _UNSET:
            steps.append(
                _SumResolvedIntsStep(
                    ServerPlanRefId(intent.ref_id),
                    config=_SumResolvedIntsConfig(
                        source_refs=tuple(ServerPlanRefId(ref_id) for ref_id in chunk_refs),
                    ),
                ),
            )
        else:
            steps.append(
                _ResolvedValueStep(
                    ServerPlanRefId(intent.ref_id),
                    config=_ResolvedValueConfig(
                        source_refs=tuple(ServerPlanRefId(ref_id) for ref_id in chunk_refs),
                        value=intent.return_value,
                    ),
                ),
            )
        return steps

    if intent.return_value is _UNSET:
        steps.append(
            InsertManyRawStep(
                ServerPlanRefId(intent.ref_id),
                intent.staged_model,
                config=_InsertManyRawConfig(
                    columns=tuple(intent.columns),
                    rows=tuple(intent.rows),
                    db_column_source=intent.db_column_source,
                    raw_row_facts=intent.raw_row_facts,
                    staged_write=staged_write,
                    after_refs=frozenset(write_after_refs),
                ),
            ),
        )
    else:
        steps.append(
            InsertManyRawStep(
                ServerPlanRefId(intent.ref_id),
                intent.staged_model,
                config=_InsertManyRawConfig(
                    columns=tuple(intent.columns),
                    rows=tuple(intent.rows),
                    db_column_source=intent.db_column_source,
                    raw_row_facts=intent.raw_row_facts,
                    return_value=intent.return_value,
                    staged_write=staged_write,
                    after_refs=frozenset(write_after_refs),
                ),
            ),
        )
    return steps


def lower_replace_staged_rows_postgres(
    intent: ReplaceStagedRowsIntent,
    *,
    max_params_per_upsert: int,
) -> list[ServerPlanStep[Any]]:
    """Lower staged-row replacement to chunked raw upsert for PostgreSQL."""
    if not intent.rows:
        return lower_replace_staged_rows_generic(intent)

    params_per_row = len(intent.columns)
    chunk_size = len(intent.rows) if params_per_row <= 0 else max(1, max_params_per_upsert // params_per_row)

    if chunk_size >= len(intent.rows):
        # Keep the canonical top-level ref on the physical write step when
        # PostgreSQL can lower the semantic replace to a single raw upsert.
        _pw = PendingStagedWrite(
            source_key=StagedSourceKey(
                staged_table_name=get_table_name(intent.staged_model),
                branch_scope_token=intent.branch_scope_token,
            ),
            staged_commit_id_raw=intent.staged_commit_id_raw,
            write_kind="replace",
        )
        if intent.return_value is _UNSET:
            return [
                UpsertManyRawStep(
                    intent.ref_id,
                    intent.staged_model,
                    _UpsertManyRawStepConfig(
                        columns=list(intent.columns),
                        rows=list(intent.rows),
                        conflict_columns=list(_REPLACE_STAGED_ROWS_CONFLICT_COLUMNS),
                        change_detection_columns=intent.change_detection_columns,
                        db_column_source=intent.db_column_source,
                        raw_row_facts=intent.raw_row_facts,
                        staged_write=_pw,
                        after_refs=intent.after_refs,
                        isolate_from_sql_batch=intent.isolate_from_sql_batch,
                    ),
                ),
            ]
        return [
            UpsertManyRawStep(
                intent.ref_id,
                intent.staged_model,
                _UpsertManyRawStepConfig(
                    columns=list(intent.columns),
                    rows=list(intent.rows),
                    conflict_columns=list(_REPLACE_STAGED_ROWS_CONFLICT_COLUMNS),
                    change_detection_columns=intent.change_detection_columns,
                    db_column_source=intent.db_column_source,
                    raw_row_facts=intent.raw_row_facts,
                    return_value=intent.return_value,
                    staged_write=_pw,
                    after_refs=intent.after_refs,
                    isolate_from_sql_batch=intent.isolate_from_sql_batch,
                ),
            ),
        ]

    chunk_refs: list[str] = []
    steps: list[ServerPlanStep[Any]] = []
    for idx, start in enumerate(range(0, len(intent.rows), chunk_size)):
        chunk_ref = f"{intent.ref_id}_chunk_{idx}"
        chunk_refs.append(chunk_ref)
        steps.append(
            UpsertManyRawStep(
                ServerPlanRefId(chunk_ref),
                intent.staged_model,
                _UpsertManyRawStepConfig(
                    columns=list(intent.columns),
                    rows=list(intent.rows[start : start + chunk_size]),
                    conflict_columns=list(_REPLACE_STAGED_ROWS_CONFLICT_COLUMNS),
                    change_detection_columns=intent.change_detection_columns,
                    db_column_source=intent.db_column_source,
                    staged_write=PendingStagedWrite(
                        source_key=StagedSourceKey(
                            staged_table_name=get_table_name(intent.staged_model),
                            branch_scope_token=intent.branch_scope_token,
                        ),
                        staged_commit_id_raw=intent.staged_commit_id_raw,
                        write_kind="replace",
                    ),
                    after_refs=intent.after_refs,
                    isolate_from_sql_batch=intent.isolate_from_sql_batch,
                ),
            ),
        )

    # Chunk refs are physical-only. Rebind the canonical ref exactly once at the
    # physical lowering boundary so downstream steps keep the semantic ref_id.
    terminal_step: ServerPlanStep[Any]
    if intent.return_value is _UNSET:
        terminal_step = _SumResolvedIntsStep(
            ServerPlanRefId(intent.ref_id),
            config=_SumResolvedIntsConfig(
                source_refs=tuple(ServerPlanRefId(ref_id) for ref_id in chunk_refs),
            ),
        )
    else:
        terminal_step = _ResolvedValueStep(
            ServerPlanRefId(intent.ref_id),
            config=_ResolvedValueConfig(
                source_refs=tuple(ServerPlanRefId(ref_id) for ref_id in chunk_refs),
                value=intent.return_value,
            ),
        )
    steps.append(terminal_step)
    return steps

