    error_message: str,
    error_message_expr: SqlRenderable | None = None,
) -> SqlSelect:
    return SqlSelect(
        select=SqlSelectList(
            [
                SqlSelectAlias(ok_expr, SqlAliasName("ok")),
                SqlSelectAlias(
                    SqlInlineLiteral(AssertionResultCode.ERROR.value),
                    SqlAliasName("error_code"),
                ),
                SqlSelectAlias(error_message_expr or SqlInlineLiteral(error_message), SqlAliasName("message")),
            ],
        ),
        from_=SqlWrappedSubquery(source_query, alias=source_alias),
    )


def _assertion_select(
    ok_expr: SqlRenderable,
    *,
    error_message: str,
    error_code: AssertionResultCode = AssertionResultCode.ERROR,
) -> SqlSelect:
    return SqlSelect(
        select=SqlSelectList(
            [
                SqlSelectAlias(ok_expr, SqlAliasName("ok")),
                SqlSelectAlias(
                    SqlInlineLiteral(error_code.value),
                    SqlAliasName("error_code"),
                ),
                SqlSelectAlias(SqlInlineLiteral(error_message), SqlAliasName("message")),
            ],
        ),
    )


def scalar_optimistic_lock_assertion_query(
    scalar_query: SqlRenderable,
    expected_expr: SqlRenderable,
    *,
    error_message: str,
    missing_ok: bool = True,
) -> SqlSelect:
    """Project a scalar lookup and expected expression into an optimistic-lock assertion row."""

    matches_expected = SqlBinaryOp(
        SqlSubquery(scalar_query),
        BinaryOp.EQ,
        expected_expr,
    )
    return _assertion_select(
        SqlCoalesceExpr(matches_expected, SqlInlineLiteral(missing_ok)),
        error_message=error_message,
    )


