def invalid_fk_rows_assertion_query(
    invalid_rows_query: SqlRenderable,
    *,
    error_message: str,
) -> SqlSelect:
    """Assert an invalid-FK rowset is empty and include one offending row in the error."""
    source_alias = SqlAliasName("__invalid_fk_rows")
    count_column = SqlColumnName("invalid_count")
    child_column = SqlColumnName("child_sys_id")
    target_column = SqlColumnName("target_value")
    branch_column = SqlColumnName("branch_id")
    aggregate_query = SqlSelect(
        select=SqlSelectList(
            [
                SqlSelectAlias(SqlAggregate(AggregateKind.COUNT_STAR), SqlAliasName(str(count_column))),
                SqlSelectAlias(
                    SqlAggregate(
                        AggregateKind.MIN,
                        SqlCast(
                            SqlColumnRef(child_column, qualifier=source_alias),
                            SqlCastTargetType(base_type="TEXT"),
                        ),
                    ),
                    SqlAliasName(str(child_column)),
                ),
                SqlSelectAlias(
                    SqlAggregate(
                        AggregateKind.MIN,
                        SqlCast(
                            SqlColumnRef(target_column, qualifier=source_alias),
                            SqlCastTargetType(base_type="TEXT"),
                        ),
                    ),
                    SqlAliasName(str(target_column)),
                ),
                SqlSelectAlias(
                    SqlAggregate(
                        AggregateKind.MIN,
                        SqlCast(
                            SqlColumnRef(branch_column, qualifier=source_alias),
                            SqlCastTargetType(base_type="TEXT"),
                        ),
                    ),
                    SqlAliasName(str(branch_column)),
                ),
            ],
        ),
        from_=SqlWrappedSubquery(invalid_rows_query, alias=source_alias),
    )
    aggregate_alias = SqlAliasName("__invalid_fk_gate")
    ok_expr = SqlBinaryOp(
        SqlColumnRef(count_column, qualifier=aggregate_alias),
        BinaryOp.EQ,
        SqlInlineLiteral(0),
    )
    detail_expr: SqlRenderable = SqlInlineLiteral(
        f"{error_message}; reasons=missing,wrong_type,cross_graph; child_sys_id=",
    )
    for separator, column in (
        ("; target_value=", child_column),
        ("; branch_id=", target_column),
        ("", branch_column),
    ):
        detail_expr = SqlBinaryOp(detail_expr, BinaryOp.CONCAT, SqlColumnRef(column, qualifier=aggregate_alias))
        if separator:
            detail_expr = SqlBinaryOp(detail_expr, BinaryOp.CONCAT, SqlInlineLiteral(separator))
    return _assertion_query(
        aggregate_query,
        source_alias=aggregate_alias,
        ok_expr=ok_expr,
        error_message=error_message,
        error_message_expr=detail_expr,
    )


