def non_null_column_assertion_query(
    source_query: SqlRenderable,
    *,
    column: str,
    error_message: str,
) -> SqlSelect:
    """Project a source query into a non-null-column assertion row."""

    source_alias = SqlAliasName("__nonnull_gate")
    ok_expr = SqlIsNull(
