    )


def authorization_gate_assertion_query(
    gate_expr: SqlRenderable,
    *,
    error_message: str,
) -> SqlSelect:
    """Project an authorization gate expression into a policy-denial assertion row.

    ``gate_expr`` is the gate ref lowered to SQL -- a scalar subquery over the CTE
    that computed it. It is non-NULL exactly when the caller is authorized, so the
    assertion is simply that it is not NULL.

    This differs from the other assertions here only in the code it emits.
    ``POLICY_DENIED`` is what lets the post-op raise a permission error rather than
    a generic one, which is the entire reason a route can map the failure to 403
    without asking the database who the caller is a second time.

    .. seealso::

        * ``impl.common.l2070_server_plan.steps.authorization_gate`` - the step
        * ``docs/guides/auto_api_serverplan_1rtt.rst`` - the round-trip budget
    """
    return _assertion_select(
        SqlIsNull(gate_expr, negated=True),
        error_message=error_message,
        error_code=AssertionResultCode.POLICY_DENIED,
    )


def true_expression_assertion_query(
    predicate: SqlRenderable,
