def column_in_assertion_query(
    source_query: SqlRenderable,
    *,
    column: str,
    values: Sequence[str],
    error_message: str,
) -> SqlSelect:
    """Project a source row into an assertion that a column value is in a closed set."""
    values = tuple(values)

    source_alias = SqlAliasName("__in_gate")
    ok_expr = SqlIn(
        SqlColumnRef(SqlColumnName(column), qualifier=source_alias),
        tuple(SqlInlineLiteral(value) for value in values),
    )
    return _assertion_query(
        source_query,
        source_alias=source_alias,
        ok_expr=ok_expr,
        error_message=error_message,
    )


