def sql_assertion_post_op(
    error_message: str,
    *,
    exc_type: type[Exception] = ValueError,
    allow_empty: bool = False,
) -> CompiledPostOp:
    """Raise only from the SQL-produced assertion row."""

    return CompiledPostOp.assert_result(
        ResultAssertionSpec(
            mappings=(
                AssertionExceptionMapping(
                    code=AssertionResultCode.ERROR,
                    exc_type=exc_type,
                    default_message=error_message,
                ),
            ),
            allow_empty_result=allow_empty,
        ),
    )


def authorization_gate_post_op(
    error_message: str,
    *,
    exc_type: type[Exception],
) -> CompiledPostOp:
    """Raise ``exc_type`` from a policy-denial assertion row.

    Only ``POLICY_DENIED`` is mapped. An assertion row carrying any other code did
    not come from an authorization gate, and reporting it as a permission failure
    would tell the caller they were refused when they were not.
    """

    return CompiledPostOp.assert_result(
        ResultAssertionSpec(
            mappings=(
                AssertionExceptionMapping(
                    code=AssertionResultCode.POLICY_DENIED,
                    exc_type=exc_type,
                    default_message=error_message,
                ),
            ),
        ),
    )


def expected_count_assertion_post_op(
    error_message: str,
    *,
    exc_type: type[Exception] = ValueError,
) -> CompiledPostOp:
    """Raise the selected error from the SQL expected-count assertion row."""

    return sql_assertion_post_op(error_message, exc_type=exc_type)

