def _require_stage_tombstone_condition_cte(
    ctx: CompilationContext,
    condition_ref_id: ServerPlanRefId,
) -> CteReference:
    condition_binding = ctx.cte_refs.get(condition_ref_id)
    if isinstance(condition_binding, CteReference):
        return condition_binding
    msg = f"Stage tombstone condition {condition_ref_id!r} has no explicit SQL-visible binding."
    raise TypeError(msg)


class StagedTombstoneConflictScope(Enum):
    CURRENT_STAGED_COMMIT = "current_staged_commit"
    ANY_STAGED_ROW = "any_staged_row"


class _StageTombstoneStepCteRow(BaseModel):
    result: bool = Field(json_schema_extra={"db_column": "__result"})


class StageTombstoneStep(SqlRelationPublisherStep[bool]):
    """Insert a staged tombstone directly from an explicit condition row ref."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        condition_ref_id: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        staged_model: type[DatabaseObjectRow],
        staged_table_name: SqlTableName,
        lazy_branch: ScalarServerRef[BranchId],
        staged_commit_id_raw: StagedCommitId,
        branch_scope_token: BranchScopeToken,
        literal_branch: BranchId | None = None,
        conflict_scope: StagedTombstoneConflictScope = StagedTombstoneConflictScope.CURRENT_STAGED_COMMIT,
        after_refs: frozenset[ServerPlanRefId] = frozenset(),
    ) -> None:
        super().__init__(ref_id)
        self._condition_ref_id = condition_ref_id
        self._model_cls = model_cls
        self._staged_model = staged_model
        self._staged_table_name = staged_table_name
        self._lazy_branch = lazy_branch
        self._literal_branch = literal_branch
        self._staged_commit_id_raw = staged_commit_id_raw
        self._branch_scope_token = branch_scope_token
        self._conflict_scope = conflict_scope
        self._after_refs = after_refs

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.SCALAR

    def is_read_only(self) -> bool:
        return False

    def supports_sql_batch_transport(self) -> bool:
        return True

    def cte_publication_contract(self: StageTombstoneStep) -> CtePublicationContract:
        columns = ("__result",)
        column_type_hints = SqlColumnTypeHints(bool_columns=frozenset({"__result"}))
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        _contract_model_cls = _StageTombstoneStepCteRow
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=tuple(str(column) for column in columns),
            column_type_hints=column_type_hints,
            model_cls=_contract_model_cls,
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
            empty_result_allowed=True,
        )

    def always_publishes_executor_visible_binding(self) -> bool:
        return True

    def step_tags(self) -> frozenset[str]:
        return frozenset({"write", "insert", "tombstone", "grammar"})

    def is_tombstone_operation(self) -> bool:
        return True

    def dependencies(self) -> frozenset[str]:
        branch_deps = frozenset() if self._literal_branch is not None else self._lazy_branch.dependencies()
        return frozenset({str(self._condition_ref_id)}) | branch_deps | frozenset(str(ref) for ref in self._after_refs)

    def sql_visible_dependencies(self) -> frozenset[str]:
        branch_deps = frozenset() if self._literal_branch is not None else self._lazy_branch.dependencies()
        return frozenset({str(self._condition_ref_id)}) | branch_deps

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset({str(self._staged_table_name)})

    def staged_write_descriptor(self) -> PendingStagedWrite | None:
        return PendingStagedWrite(
            source_key=StagedSourceKey(
                staged_table_name=str(self._staged_table_name),
                branch_scope_token=self._branch_scope_token,
            ),
            staged_commit_id_raw=self._staged_commit_id_raw.unwrap_to_str(),
            write_kind="tombstone",
        )

    def provided_staged_sources(self) -> frozenset[str]:
        return frozenset({str(self._staged_table_name)})

    def compile(self, ctx: CompilationContext) -> CompiledStep[bool]:
        from impl.common.l2070_server_plan.steps.intent_versioning_extended import (
            _supports_returning_clause,
            _versioned_data_db_columns,
        )

        supports_returning = _supports_returning_clause(ctx)
        common_columns = _versioned_data_db_columns(
            self._staged_model,
            excluded_fields=("staged_commit_id", "deleted", *_GRAPH_HASH32_FIELD_NAMES),
            include_generated_storage_columns=include_generated_storage_columns(ctx),
        )
        if include_generated_storage_columns(ctx):
            from l1000_schema.large_column import get_large_column_configs, large_column_pointer_name

            for config in get_large_column_configs(self._model_cls):
                pointer_column = large_column_pointer_name(config.column)
                if pointer_column not in common_columns:
                    common_columns.append(pointer_column)
        branch_column = (
            get_db_column_name(self._staged_model, DynamicFieldName("branch_id"))
            if "branch_id" in self._staged_model.model_fields
            else None
        )
        staged_commit_col = get_db_column_name(self._staged_model, DynamicFieldName("staged_commit_id"))
        deleted_col = get_db_column_name(self._staged_model, DynamicFieldName("deleted"))
        target_columns = [*common_columns, staged_commit_col, deleted_col]
        conflict_columns = (
            (branch_column, "sys_id", staged_commit_col) if branch_column is not None else ("branch_id", "sys_id", staged_commit_col)
        )

        # Resolve the condition CTE as the SELECT source. If it is empty
        # (the referenced object does not exist), the INSERT naturally
        # produces zero rows -- this is the structural gate that replaces
        # the prior VALUES-with-scalar-subqueries form which was forcing
        # NULLs on non-existent rows.
        condition_binding = _require_stage_tombstone_condition_cte(ctx, self._condition_ref_id)
        source_table = SqlTableName(condition_binding.ref_id)
        source_alias = SqlAliasName("src")
        staged_alias = SqlAliasName("existing_staged")
        condition_columns = set(condition_binding.columns or ())
        branch_expr: SqlRenderable
        if self._literal_branch is not None:
            branch_expr = SqlParam(self._literal_branch.unwrap_to_str())
        else:
            branch_shape = inspect_server_value_shape_for_planning(
                self._lazy_branch,
                site=f"{type(self).__name__}.compile.branch",
            )
            if branch_shape.symbolic_ref_id is not None:
                found_seed, seed_value = read_seeded_constant_from_ctx(
                    ctx,
                    ServerPlanRefId(branch_shape.symbolic_ref_id),
                )
                if found_seed and isinstance(seed_value, BranchId):
                    branch_expr = SqlParam(seed_value.unwrap_to_str())
                else:
                    branch_expr = lower_scalar_server_ref(self._lazy_branch, ctx, default_field="branch_id")
            else:
                branch_expr = lower_scalar_server_ref(self._lazy_branch, ctx, default_field="branch_id")

        model_identity_column = str(get_db_column_name(self._model_cls, DynamicFieldName("sys_id")))

        def source_column_for_target(target_column: str) -> str:
            if target_column == "sys_id" and model_identity_column in condition_columns:
                return model_identity_column
            if target_column == "sys_revision_id" and "sys_valid_from_revision_id" in condition_columns:
                return "sys_valid_from_revision_id"
            if target_column.startswith("sys_"):
                semantic_column = target_column.removeprefix("sys_")
                if semantic_column in condition_columns:
                    return semantic_column
            if target_column in condition_columns:
                return target_column
            return target_column

        select_exprs: list[SqlRenderable] = []
        for column in common_columns:
            if branch_column is not None and column == branch_column:
                select_exprs.append(branch_expr)
            else:
                source_column = source_column_for_target(column)
                if source_column in condition_columns:
                    select_exprs.append(
                        SqlColumnRef(SqlColumnName(source_column), str(source_alias)),
                    )
                else:
                    select_exprs.append(SqlParam(None))
        select_exprs.append(SqlParam(self._staged_commit_id_raw.unwrap_to_str()))
        select_exprs.append(SqlParam(True))
        select_expr_by_target_col = {
            target_col: select_expr for target_col, select_expr in zip(target_columns, select_exprs, strict=True)
        }
        distinct_on = (
            [SqlPostgresUuidCast(select_expr_by_target_col[col]) for col in conflict_columns]
            if all(col in select_expr_by_target_col for col in conflict_columns)
            else None
        )
        source_sys_id = SqlColumnRef(
            SqlColumnName(source_column_for_target("sys_id")),
            str(source_alias),
        )
        where_expr: SqlRenderable = SqlBooleanLiteral(True)
        if branch_column is not None and self._conflict_scope is StagedTombstoneConflictScope.ANY_STAGED_ROW:
            where_expr = SqlExists(
                SqlSelect(
                    select=SqlSelectList([SqlParam(1)]),
                    from_clause=SqlFrom(SqlTableAlias(SqlTableIdent(self._staged_table_name), staged_alias)),
                    where=SqlWhereClause(
                        sql_and(
                            *(
                                SqlBinaryOp(
                                    SqlColumnRef(SqlColumnName(conflict_columns[0]), str(staged_alias)),
                                    BinaryOp.EQ,
                                    branch_expr,
                                ),
                                SqlBinaryOp(
                                    SqlColumnRef(SqlColumnName("sys_id"), str(staged_alias)),
                                    BinaryOp.EQ,
                                    source_sys_id,
                                ),
                            ),
                        ),
                    ),
                ),
                negated=True,
            )

        stmt = SqlInsertFromSelect(
            target_table=self._staged_table_name,
            target_columns=target_columns,
            source_table=source_table,
            select_exprs=select_exprs,
            where=where_expr,
            returning=(
                SqlReturningClause(
                    SqlSelectAlias(
                        SqlIntegerLiteral(1),
                        SqlAliasName("__result"),
                    ),
                )
                if supports_returning
                else None
            ),
            conflict_columns=conflict_columns,
            update_columns=(deleted_col,),
            distinct=True,
            distinct_on=distinct_on,
            source_alias=source_alias,
        )

        auxiliary_ctes: list[tuple[str, object]] = []
        if condition_binding.auxiliary_query is not None:
            auxiliary_ctes.append((condition_binding.ref_id, condition_binding.auxiliary_query))
        branch_ref_id = getattr(self._lazy_branch, "ref_id", None)
        if branch_ref_id is not None:
            branch_base_ref, _, _ = branch_ref_id.partition(".")
            branch_binding = ctx.cte_refs.get(branch_base_ref)
            if (
                isinstance(branch_binding, CteReference)
                and branch_binding.auxiliary_query is not None
                and all(existing_ref != branch_binding.ref_id for existing_ref, _ in auxiliary_ctes)
            ):
                auxiliary_ctes.append((branch_binding.ref_id, branch_binding.auxiliary_query))

        contract = self.cte_publication_contract()
        from l2070_batching.output_shape import CompiledOutputShape, DeclaredResultRelation, synthetic_output_field

        output_shape = CompiledOutputShape(
            tuple(synthetic_output_field(column) for column in contract.columns),
        )
        if supports_returning:
            __opa002_grammar_298 = stmt
            return CompiledStep(
                output_shape=output_shape,
                result_relation=DeclaredResultRelation.from_output_shape(output_shape),
                grammar=__opa002_grammar_298,
                column_type_hints=contract.column_type_hints,
                needs_returning=True,
                closed_post_op=scalar_column_post_op(
                    "__result",
                    default_value=False,
                    use_default_on_empty=True,
                    scalar_coercion=ScalarCoercionKind.BOOL,
                ),
                auxiliary_ctes=auxiliary_ctes or None,
            )

        # Backends without RETURNING (MariaDB/DoltDB) use the non-inline
        # result path where ``_DynamicVersionedDeleteResultStep`` consults
        # the existence check ref to decide the overall delete outcome;
        # the tombstone step's own boolean is AND-ed in and therefore a
        # conservative ``True`` is correct.
        result_stmt = SqlSelect(
            select=SqlSelectList(
                [SqlSelectAlias(SqlIntegerLiteral(1), SqlAliasName("__result"))],
            ),
        )
        grammar = SqlStatementBatch(
            [stmt, result_stmt],
            category=SqlStatementBatchCategory.ORDERED_SEMANTIC,
            needs_returning_per_stmt=[False, False],
            collect_results_per_stmt=[False, True],
            statement_kinds_per_stmt=[SqlStatementKind.DML, SqlStatementKind.UNSPECIFIED],
        )
        return CompiledStep(
            output_shape=output_shape,
            result_relation=DeclaredResultRelation.from_output_shape(output_shape),
            grammar=grammar,
            column_type_hints=contract.column_type_hints,
            closed_post_op=literal_post_op(True),
            auxiliary_ctes=auxiliary_ctes or None,
        )


