class _DeltaCleanupStep(NonPublishingStep[None]):
    """Common execution contract for one delta cleanup statement."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        after_refs: frozenset[ServerPlanRefId],
    ) -> None:
        super().__init__(ref_id)
        self._after_refs = after_refs

    @property
    def level(self) -> int:
        return 0

    def dependencies(self) -> frozenset[str]:
        return frozenset(str(ref) for ref in self._after_refs)

    def sql_visible_dependencies(self) -> frozenset[str]:
        return frozenset()

    def is_read_only(self) -> bool:
        return False

    def supports_sql_batch_transport(self) -> bool:
        return False

    def requires_prior_step_boundary(self) -> bool:
        return True

    def result_cardinality(self) -> Cardinality:
        return Cardinality.NONE

    def step_tags(self) -> frozenset[str]:
        return frozenset({"write", "delta-storage", "cleanup"})

    def _grammar(self) -> SqlRenderable:
        raise NotImplementedError

    def compile(self, ctx: CompilationContext) -> CompiledStep[None]:
        from impl.common.l2070_server_plan.steps.content_store import _content_store_plan_effect_post_op
        from l2070_batching.compilation import no_result_compiled_artifacts

        del ctx
        output_shape, result_relation, column_type_hints = no_result_compiled_artifacts()
        return CompiledStep(
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
            grammar=self._grammar(),
            closed_post_op=_content_store_plan_effect_post_op(self.ref_id),
        )


