class _DeltaOrphanCleanupStep(_DeltaCleanupStep):
    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        source_table: SqlTableName,
        source_column: ContentColumnName,
        pointer_column: SqlColumnName,
        after_refs: frozenset[ServerPlanRefId],
        owner_tables: tuple[SqlTableName, ...] | None = None,
    ) -> None:
        super().__init__(ref_id, after_refs=after_refs)
        if owner_tables is not None and not owner_tables:
            raise ValueError("owner_tables must not be empty")
        if owner_tables is not None and len(set(owner_tables)) != len(owner_tables):
            raise ValueError("owner_tables must not contain duplicates")
        self._source_table = source_table
        self._source_column = source_column
        self._pointer_column = pointer_column
        self._owner_tables = (source_table,) if owner_tables is None else owner_tables

    def tables_read(self) -> frozenset[str]:
        return frozenset(
            {
                *(str(table) for table in self._owner_tables),
                "sys_content_values",
                "sys_content_chunk_ranges",
            },
        )


