def _build_bounded_delta_storage_upsert_steps(
    *,
    ref_id: ServerPlanRefId,
    model_cls: type[DatabaseObjectRow],
    columns: Sequence[SqlColumnName],
    rows: list[SqlParamTuple],
    conflict_columns: Sequence[SqlColumnName],
    after_refs: frozenset[ServerPlanRefId],
    on_conflict: dict[object, object] | None = None,
) -> list[ServerPlanStep[Any]]:
    """Split internal delta writes before they reach physical SQL grouping.

    The conservative bound keeps every generated statement valid before the
    backend-specific capacity check in ``param_budget.py``.
    """
    from l2070_batching.statement_capacity import CONSERVATIVE_SQL_STATEMENT_CAPACITY

    if not columns:
        msg = "Delta storage upsert batching requires at least one SQL column."
        raise ValueError(msg)
    rows_per_step = max(1, CONSERVATIVE_SQL_STATEMENT_CAPACITY.max_bind_parameters // len(columns))
    chunks = [rows[start : start + rows_per_step] for start in range(0, len(rows), rows_per_step)]
    steps: list[ServerPlanStep[Any]] = []
    for index, chunk in enumerate(chunks):
        chunk_ref = ref_id if index == len(chunks) - 1 else ServerPlanRefId(f"{ref_id}.chunk_{index}")
        steps.append(
            _DeltaStorageUpsertStep(
                chunk_ref,
                model_cls,
                _UpsertManyRawStepConfig(
                    columns=[str(column) for column in columns],
                    rows=chunk,
                    conflict_columns=tuple(conflict_columns),
                    on_conflict=on_conflict,
                    return_value=len(rows) if chunk_ref == ref_id else len(chunk),
                    after_refs=after_refs,
                ),
            ),
        )
    return steps


def build_delta_orphan_cleanup_steps(
    *,
    ref_prefix: ServerPlanRefId,
    model_cls: type[DatabaseObjectRow],
    configs: Sequence[LargeColumnConfig],
    after_ref: ServerPlanRefId,
    owner_tables: tuple[SqlTableName, ...] | None = None,
) -> tuple[list[ServerPlanStep[Any]], frozenset[ServerPlanRefId]]:
    """Build ordered cleanup for content values that have no owner pointer.

    The order implements the lifecycle in ``docs/design/LARGE_COLUMN_DELTA_STORAGE.rst``.
    Reference counts must decrease before cascading range deletion removes the evidence.
    """
    steps: list[ServerPlanStep[Any]] = []
    cleanup_after_refs = frozenset({after_ref})
    source_table = SqlTableName(get_table_name(model_cls))
    for config in configs:
        if config.delta_storage is None or not config.delta_storage.enabled:
            continue
        column = ContentColumnName(config.column)
        decrement_ref = ServerPlanRefId(f"{ref_prefix}.{column}.delta_decrement_orphans")
        delete_ref = ServerPlanRefId(f"{ref_prefix}.{column}.delta_delete_orphans")
        prune_ref = ServerPlanRefId(f"{ref_prefix}.{column}.delta_prune")
        steps.extend(
            (
                DeltaDecrementOrphanChunkReferencesStep(
                    decrement_ref,
                    source_table=source_table,
                    source_column=column,
                    pointer_column=SqlColumnName(large_column_pointer_name(column)),
                    after_refs=cleanup_after_refs,
                    owner_tables=owner_tables,
                ),
                DeltaDeleteOrphanContentValuesStep(
                    delete_ref,
                    source_table=source_table,
                    source_column=column,
                    pointer_column=SqlColumnName(large_column_pointer_name(column)),
                    after_refs=frozenset({decrement_ref}),
                    owner_tables=owner_tables,
                ),
                DeltaDeleteUnreferencedChunksStep(
                    prune_ref,
                    after_refs=frozenset({delete_ref}),
                ),
            ),
        )
        cleanup_after_refs = frozenset({prune_ref})
    return steps, cleanup_after_refs


def build_content_chunk_range_upsert_steps(
    ref_id: ServerPlanRefId,
    rows: Sequence[ContentChunkRange],
    *,
    after_refs: frozenset[ServerPlanRefId] = frozenset(),
) -> list[ServerPlanStep[Any]]:
    """Build concrete steps that write content chunk range metadata."""
    return _build_bounded_delta_storage_upsert_steps(
        ref_id=ref_id,
        model_cls=ContentChunkRange,
        columns=_CONTENT_CHUNK_RANGE_COLUMNS,
        rows=[_range_row_tuple(row) for row in rows],
        conflict_columns=(SqlColumnName("content_value_id"), SqlColumnName("ordinal")),
        after_refs=after_refs,
    )


def build_content_value_upsert_steps(
