    rows: Sequence[ContentValue],
    *,
    after_refs: frozenset[ServerPlanRefId] = frozenset(),
) -> list[ServerPlanStep[Any]]:
    """Build concrete steps that write logical delta content values."""
    return _build_bounded_delta_storage_upsert_steps(
        ref_id=ref_id,
        model_cls=ContentValue,
        columns=_CONTENT_VALUE_COLUMNS,
        rows=[_content_value_tuple(row) for row in rows],
        conflict_columns=(
