def build_content_dedup_chunk_upsert_steps(
    ref_id: ServerPlanRefId,
    rows: Sequence[ContentDedupChunk],
    *,
    after_refs: frozenset[ServerPlanRefId] = frozenset(),
) -> list[ServerPlanStep[Any]]:
    """Build concrete steps that write unique dedup chunk payloads."""
    rows_by_ref_count: dict[int, list[ContentDedupChunk]] = {}
    for row in rows:
        rows_by_ref_count.setdefault(row.ref_count, []).append(row)
    steps: list[ServerPlanStep[Any]] = []
    groups = sorted(rows_by_ref_count.items())
    for index, (ref_count, grouped_rows) in enumerate(groups):
        step_ref = ref_id if index == len(groups) - 1 else ServerPlanRefId(f"{ref_id}_refs_{ref_count}")
        ref_count_field = field(ContentDedupChunk.ref_count)
        conflict_update: dict[object, object] = {}
        conflict_update[ref_count_field] = ref_count_field + EXCLUDED(ref_count_field)
        steps.extend(
            _build_bounded_delta_storage_upsert_steps(
                ref_id=step_ref,
                model_cls=ContentDedupChunk,
                columns=_CONTENT_DEDUP_CHUNK_COLUMNS,
                rows=[_dedup_chunk_tuple(row) for row in grouped_rows],
                conflict_columns=(SqlColumnName("chunk_hash_short"), SqlColumnName("chunk_hash_high")),
                on_conflict=conflict_update,
                after_refs=after_refs,
            ),
        )
    return steps


def _range_row_tuple(row: ContentChunkRange) -> SqlParamTuple:
    return validate_sql_param_tuple(
        (
            row.sys_id.unwrap_to_sql(),
            row.content_value_id.unwrap_to_sql(),
            row.ordinal,
            row.byte_offset,
            row.byte_length,
            None if row.weak_hash is None else int(row.weak_hash),
            int(row.chunk_hash_short),
            int(row.chunk_hash_high),
            row.created_at,
        )
    )


def _content_value_tuple(row: ContentValue) -> SqlParamTuple:
    return validate_sql_param_tuple(
        (
            row.sys_id.unwrap_to_sql(),
            str(row.source_table),
            str(row.source_column),
            row.row_sys_id.unwrap_to_sql(),
            None if row.revision_id is None else row.revision_id.unwrap_to_sql(),
            row.original_size,
            int(row.content_hash_short),
            int(row.content_hash_high),
            row.manifest_format,
            row.chunking_mode,
            row.weak_hash_algorithm,
            row.strong_hash_algorithm,
            row.avg_chunk_size,
            row.min_chunk_size,
            row.max_chunk_size,
            bytes(row.manifest_payload),
            row.created_at,
        )
    )


def _dedup_chunk_tuple(row: ContentDedupChunk) -> SqlParamTuple:
    return validate_sql_param_tuple(
        (
            row.sys_id.unwrap_to_sql(),
            int(row.chunk_hash_short),
