if TYPE_CHECKING:
    from l2070_batching.compilation import CompilationContext, CompiledStep, ResolvedRefs
    from impl.common.l2100_sql_grammar.domain.versioning.stmt_two_way_diff import SqlTwoWayDiffCte
    from impl.common.l2100_sql_grammar.protocols import SqlRenderable


@dataclass(frozen=True, slots=True)
class _ApplyTwoWayDiffConfig:
    old_revision_raw: str
    new_revision_raw: str
    source_branch_id_raw: str
    target_branch_id_raw: str
    old_branch_id_raw: str
    new_result_revision_raw: str
    sparse_table: SqlTableName
    data_columns: tuple[SqlColumnName, ...]
    revision_table: SqlTableName
    revision_parents_table: SqlTableName
    tip_table: SqlTableName | None = None
    after_refs: tuple[ServerPlanRefId, ...] = ()


def _build_two_way_diff_cte(
    *,
    old_revision_raw: str | SqlRenderable,
    new_revision_raw: str | SqlRenderable,
    sparse_table: SqlTableName,
    branch_id_raw: object,
    data_columns: tuple[SqlColumnName, ...],
    revision_table: SqlTableName,
    revision_parents_table: SqlTableName,
    old_branch_id_raw: object,
) -> SqlTwoWayDiffCte:
    from impl.common.l2100_sql_grammar.domain.versioning.stmt_two_way_diff import SqlTwoWayDiffCte

    old_revision_value = SqlGrammarValue(old_revision_raw) if isinstance(old_revision_raw, str) else old_revision_raw
    new_revision_value = SqlGrammarValue(new_revision_raw) if isinstance(new_revision_raw, str) else new_revision_raw
    return SqlTwoWayDiffCte(
        old_revision_raw=old_revision_value,
