"""Large column spill steps for content store.

Before an INSERT or UPDATE on a model with large column support, column
values exceeding the spill threshold must be moved to the content store.
The original column value is replaced with a content hash pointer.

These are PRE-WRITE steps: they must execute before the INSERT/UPDATE so
that the row data contains content hashes instead of large payloads.

The encoding, compression, and hashing are performed during step
construction (by the lowering phase that creates this step). The steps
only hold pre-computed grammar for content-store writes.

``BatchedLargeColumnSpillStep`` is preferred over individual
``LargeColumnSpillStep`` instances when multiple values are spilled in
a single insert_many call, reducing N SQL round-trips to 1.

On PostgreSQL, batched spills compile to a refcount-only ``UPDATE`` followed
by an insert-missing statement. That avoids payload-bearing conflict updates
for hashes that already exist, reducing WAL/TOAST churn while preserving the
single-upsert shape for other backends.
"""

from __future__ import annotations

import hashlib
from dataclasses import dataclass
from typing import TYPE_CHECKING

from impl.common.l2050_sql_types.sql_branded_types import SqlGrammarKind
from impl.common.l2070_server_plan.param_budget import rows_per_fused_sql_statement
from l1400_types import ServerPlanRefId
from l2070_batching.backend_profile import ContentStoreIdentifierTransport, ContentStoreMutationTransport
from l2070_batching.cardinality import Cardinality
from l2070_batching.compilation import CompiledStep
from l2070_batching.scheduling_effects import SchedulingEffect
from l2070_batching.step import ServerPlanStep, ContractedSqlProducerStep, NonPublishingStep

