_CONTENT_STORE_UPSERT_PARAMS_PER_ROW = 10
_CONTENT_STORE_FTS_UPSERT_PARAMS_PER_ROW = 2
type _ContentStoreBatchRow = tuple[ContentHashValue, int, bool, bytes, int, int, str, int, int]
type _ContentStoreBatchRenderedRow = tuple[
    ContentHashValue,
    int,
    bool,
    bytes,
    int,
    int,
    str,
    int,
    int,
    int,
]
type _ContentStoreBatchInputRow = _ContentStoreBatchRow | _ContentStoreBatchRenderedRow


def _compile_content_store_table_name(table_name: SqlTableName, ctx: CompilationContext) -> SqlTableName:
    has_tight_identifier_limit = (
        ctx.backend_profile.traits.content_store_identifier_transport is ContentStoreIdentifierTransport.SHORT_HASHED
    )
    if not has_tight_identifier_limit:
        return table_name
    store_name = str(table_name)
    max_identifier_length = ctx.backend_profile.traits.content_store_identifier_max_length
    if max_identifier_length is None:
        msg = "Short-hashed content-store transport requires an identifier length limit."
        raise TypeError(msg)
    max_base_length = max_identifier_length - len("_chunks")
    if len(store_name.encode()) <= max_base_length:
        return table_name
    from impl.common.l2050_sql_types.sql_branded_types import SqlTableName

    digest = hashlib.sha1(store_name.encode("utf-8")).hexdigest()[:12]
    prefix_bytes = store_name.encode()[: max_base_length - len(digest) - 1]
    return SqlTableName(f"{prefix_bytes.decode(errors='ignore')}_{digest}")


