class LargeColumnSpillStep(NonPublishingStep[None]):
    """Spill large column values to content store before write.

    This is a pre-write step (must execute before the INSERT/UPDATE).
    It inserts (or bumps ref_count on) content store entries for large
    column values, using ``SqlContentStoreUpsert`` grammar.

    The lowering phase that creates this step is responsible for:

    1. Checking each column value against the spill threshold.
    2. Encoding and compressing the payload.
    3. Computing the content hash (SHA-256 of uncompressed payload).
    4. Replacing the column value with the content hash in the row data.
    5. Creating one ``LargeColumnSpillStep`` per spilled column.

    Attributes:
        _store_table: Content store table name (e.g., ``"products_content_store"``).
        _content_hash: SHA-256 hash of the original uncompressed content.
        _size_bytes: Size of the stored (possibly compressed) payload.
        _is_binary: Whether the payload is binary content.
        _payload: The encoded (and possibly compressed) payload bytes.
        _total_chunks: Number of chunks (0 for single-record storage).
        _chunk_size: Size of each chunk in bytes (0 if not chunked).
        _compression_algorithm: Compression algorithm name (e.g., ``"zstd"``, ``"none"``).
        _compression_level: Compression level used.
        _original_size: Original uncompressed size (0 if not compressed).
        _write_ref_id: ref_id of the write step that depends on this spill.
    """

    def __init__(
        self: LargeColumnSpillStep,
        ref_id: ServerPlanRefId,
        store_table: SqlTableName,
        config: _LargeColumnSpillConfig,
    ) -> None:
        super().__init__(ref_id)
        self._store_table: SqlTableName = store_table
        self._content_hash = config.content_hash
        self._size_bytes = config.size_bytes
        self._is_binary = config.is_binary
        self._payload = config.payload
        self._write_ref_id = config.write_ref_id
        self._total_chunks = config.total_chunks
        self._chunk_size = config.chunk_size
        self._compression_algorithm = config.compression_algorithm
        self._compression_level = config.compression_level
        self._original_size = config.original_size

    @property
    def level(self: LargeColumnSpillStep) -> int:
        return 0

    def is_read_only(self: LargeColumnSpillStep) -> bool:
        return False  # INSERTs into content store

    def result_cardinality(self: LargeColumnSpillStep) -> Cardinality:
        return Cardinality.NONE

    def step_tags(self: LargeColumnSpillStep) -> frozenset[str]:
        return frozenset({"large_column", "pre_write", "grammar"})

    def tables_read(self: LargeColumnSpillStep) -> frozenset[str]:
        """Content store spill does not read tables."""
        return frozenset()

    def tables_written(self: LargeColumnSpillStep) -> frozenset[str]:
        return frozenset({str(self._store_table)})

    def compile(self: LargeColumnSpillStep, ctx: CompilationContext) -> CompiledStep[None]:
        """Compile to a content store upsert grammar.

        Produces ``SqlContentStoreUpsert`` which handles dialect-aware
        INSERT ... ON CONFLICT/DUPLICATE KEY UPDATE for the content store.
        """
        from impl.common.l2100_sql_grammar.domain.infra.stmt_content_store import (
            SqlContentStoreUpsert,
        )

        store_table = _compile_content_store_table_name(self._store_table, ctx)
        grammar = SqlContentStoreUpsert(
            table=store_table,
            content_hash=self._content_hash,
            size_bytes=self._size_bytes,
            is_binary=self._is_binary,
            payload=self._payload,
            total_chunks=self._total_chunks,
            chunk_size=self._chunk_size,
            compression_algorithm=self._compression_algorithm,
            compression_level=self._compression_level,
            original_size=self._original_size,
        )

        return CompiledStep(grammar=grammar)


class BatchedLargeColumnSpillStep(NonPublishingStep[None]):
    """Batch-spill multiple large column values in a single SQL statement.

    Equivalent to N ``LargeColumnSpillStep`` instances. Non-PostgreSQL
    backends compile to one multi-row ``SqlBatchedContentStoreUpsert``.
    PostgreSQL compiles to a compound write: a payload-free
    ``SqlBatchedContentStoreRefCountUpdate`` for existing hashes, then
    ``SqlPostgresBatchedContentStoreInsertMissing`` for rows not already
    present.
    """

    def __init__(
        self: BatchedLargeColumnSpillStep,
        ref_id: ServerPlanRefId,
        store_table: SqlTableName,
        config: _BatchedLargeColumnSpillConfig,
    ) -> None:
        """Each row tuple is (content_hash, size_bytes, is_binary, payload,
        total_chunks, chunk_size, compression_algorithm, compression_level,
        original_size)."""
        super().__init__(ref_id)
        self._store_table: SqlTableName = store_table
        self._rows = config.rows
        self._write_ref_id = config.write_ref_id

    @property
    def level(self: BatchedLargeColumnSpillStep) -> int:
        return 0

    def is_read_only(self: BatchedLargeColumnSpillStep) -> bool:
        return False

    def result_cardinality(self: BatchedLargeColumnSpillStep) -> Cardinality:
        return Cardinality.NONE

    def step_tags(self: BatchedLargeColumnSpillStep) -> frozenset[str]:
        return frozenset({"large_column", "pre_write", "grammar"})

    def scheduling_effects(self: BatchedLargeColumnSpillStep) -> frozenset[SchedulingEffect]:
        return frozenset({SchedulingEffect.SQL_GROUP_BOUNDARY_AFTER})

    def supports_sql_batch_transport(self: BatchedLargeColumnSpillStep) -> bool:
        return False

    def supports_ordered_sql_statement_batch(self: BatchedLargeColumnSpillStep) -> bool:
        return True

    def tables_read(self: BatchedLargeColumnSpillStep) -> frozenset[str]:
        return frozenset()

    def tables_written(self: BatchedLargeColumnSpillStep) -> frozenset[str]:
        return frozenset({str(self._store_table)})

    def has_unbounded_params(self: BatchedLargeColumnSpillStep) -> bool:
        return False

    def estimated_param_count(self: BatchedLargeColumnSpillStep) -> int | None:
        return len(self._rows) * _CONTENT_STORE_UPSERT_PARAMS_PER_ROW

    def compile(
        self: BatchedLargeColumnSpillStep,
        ctx: CompilationContext,
    ) -> CompiledStep[None]:
        from impl.common.l2100_sql_grammar.domain.infra.stmt_compound_write import (
            SqlStatementBatch,
            SqlStatementBatchCategory,
        )
        from impl.common.l2100_sql_grammar.domain.infra.stmt_content_store import (
            SqlBatchedContentStoreUpsert,
            SqlBatchedContentStoreRefCountUpdate,
            SqlPostgresBatchedContentStoreInsertMissing,
        )

        if not self._rows:
            return CompiledStep()

        rows_per_stmt = rows_per_fused_sql_statement(
            ctx.backend_type,
            _CONTENT_STORE_UPSERT_PARAMS_PER_ROW,
            len(self._rows),
            capacity=ctx.sql_statement_capacity,
        )
        rows_per_stmt = max(rows_per_stmt, 1)
        store_table = _compile_content_store_table_name(self._store_table, ctx)
        if ctx.backend_profile.traits.content_store_mutation_transport is ContentStoreMutationTransport.REFCOUNT_THEN_INSERT:
            statements = []
            for start in range(0, len(self._rows), rows_per_stmt):
                rows = self._rows[start : start + rows_per_stmt]
                statements.extend(
                    [
                        SqlBatchedContentStoreRefCountUpdate(
                            table=store_table,
                            rows=[(row[0], row[9] if len(row) == 10 else 1) for row in rows],
                        ),
                        SqlPostgresBatchedContentStoreInsertMissing(
                            table=store_table,
                            rows=rows,
                        ),
                    ],
                )
            return CompiledStep(
                grammar=SqlStatementBatch(
                    statements,
                    category=SqlStatementBatchCategory.BUDGET_SPLIT,
                ),
            )

        if rows_per_stmt <= 0 or rows_per_stmt >= len(self._rows):
            return CompiledStep(
                grammar=SqlBatchedContentStoreUpsert(
                    table=store_table,
                    rows=self._rows,
                ),
            )

        statements = [
            SqlBatchedContentStoreUpsert(
                table=store_table,
                rows=self._rows[start : start + rows_per_stmt],
            )
            for start in range(0, len(self._rows), rows_per_stmt)
        ]
        return CompiledStep(
            grammar=SqlStatementBatch(
                statements,
                category=SqlStatementBatchCategory.BUDGET_SPLIT,
            ),
        )


