_MISSING_FILTER_VALUE = object()


def _query_spec_cte_output_columns(
    query_spec: QuerySpec[DatabaseObjectRow],
    model_cls: type[DatabaseObjectRow],
) -> tuple[str, ...]:
    from l1000_schema.schema_def import get_db_column_name
    from l1000_schema.typed_field import AliasedExpression, AliasedField, Expression, Field
    from l2070_batching.write_column_policy import returnable_db_columns

    if query_spec.select_columns is None:
        return returnable_db_columns(model_cls)
    columns: list[str] = []
    for projection in query_spec.select_columns or ():
        if isinstance(projection, AliasedField | AliasedExpression):
            columns.append(projection.alias)
        elif isinstance(projection, Field):
            owner = getattr(projection, "owner", None) or model_cls
            columns.append(str(get_db_column_name(owner, DynamicFieldName(projection.name))))
        elif isinstance(projection, Expression) and projection.field is not None:
            columns.append(str(get_db_column_name(model_cls, DynamicFieldName(projection.field))))
        else:
            alias = getattr(projection, "alias", None)
            if isinstance(alias, str):
                columns.append(alias)
    return tuple(dict.fromkeys(columns))


@dataclass(frozen=True)
class _QueryExecuteRawStepConfig:
    query_spec: QuerySpec[DatabaseObjectRow] | None
    user_id_ref_id: ServerPlanRefId | None = None
    hydrate_large_columns: bool = False
    permission_action: PermissionAction | None = None


def _is_select_one_raw_query_shape(
    query_spec: object,
    model_cls: type[DatabaseObjectRow],
) -> bool:
    from l1000_schema.schema_def import get_db_column_name

    is_simple_select_one_shape = (
        getattr(query_spec, "model_cls", None) is model_cls
        and getattr(query_spec, "select_columns", None) is None
        and not getattr(query_spec, "distinct", False)
        and not getattr(query_spec, "joins", None)
        and not getattr(query_spec, "order_by", None)
        and getattr(query_spec, "offset", None) is None
        and not getattr(query_spec, "group_by", None)
        and not getattr(query_spec, "aggregations", None)
        and not getattr(query_spec, "having", None)
        and not getattr(query_spec, "window_functions", None)
        and getattr(query_spec, "limit", None) in {1, 2}
    )
    if not is_simple_select_one_shape:
        return False

    filters = getattr(query_spec, "filters", None) or ()
    if len(filters) != 1:
        return False

    sys_id_names = {"sys_id", get_db_column_name(model_cls, DynamicFieldName("sys_id"))}
    filter_item = filters[0]
    expr = getattr(filter_item, "expression", None)
    if expr is not None:
        return getattr(expr, "field", None) in sys_id_names and getattr(expr, "operator", None) == "="

    return getattr(filter_item, "column", None) in sys_id_names and getattr(filter_item, "operator", None) == "="


def _select_one_raw_filter_value(query_spec: object) -> object:
    filters = getattr(query_spec, "filters", None) or ()
    if len(filters) != 1:
        return _MISSING_FILTER_VALUE

    filter_item = filters[0]
    expr = getattr(filter_item, "expression", None)
    if expr is not None:
        return getattr(expr, "value", _MISSING_FILTER_VALUE)
    return getattr(filter_item, "value", _MISSING_FILTER_VALUE)


def _extract_select_one_raw_sys_id(
    query_spec: object,
    model_cls: type[DatabaseObjectRow],
) -> ScalarServerRef[SysId] | None:
    from l2070_batching.server_ref import ScalarServerRef, ServerRefs

    if not _is_select_one_raw_query_shape(query_spec, model_cls):
        return None

    value = _select_one_raw_filter_value(query_spec)
    if value is _MISSING_FILTER_VALUE or isinstance(value, list):
        return None
    if isinstance(value, ScalarServerRef):
        return cast("ScalarServerRef[SysId]", value)
    return cast("ScalarServerRef[SysId]", ServerRefs.scalar(value))


def _normalize_raw_select_one_sys_id_filter(
    query_spec: QuerySpec[DatabaseObjectRow] | None,
    model_cls: type[DatabaseObjectRow],
) -> QuerySpec[DatabaseObjectRow] | None:
    from l1000_schema.typed_field import Expression
    from l2060_query_builder.query_contracts import QueryFilter
    from l1400_types import SysId

    if query_spec is None or not _is_select_one_raw_query_shape(query_spec, model_cls):
        return query_spec
    filters: list[QueryFilter] = list(getattr(query_spec, "filters", ()) or ())
    if len(filters) != 1:
        return query_spec
    filter_item = filters[0]
    expression = getattr(filter_item, "expression", None)
    if expression is not None:
        value = getattr(expression, "value", _MISSING_FILTER_VALUE)
        if not isinstance(value, SysId):
            return query_spec
        normalized_expression = Expression(
            field=getattr(expression, "field", None),
            operator=getattr(expression, "operator", None),
            value=value.unwrap_to_str(),
            left=getattr(expression, "left", None),
            right=getattr(expression, "right", None),
            logical_op=getattr(expression, "logical_op", None),
            function=getattr(expression, "function", None),
            args=getattr(expression, "args", None),
            owner=getattr(expression, "owner", None),
            server_ref_dependencies=tuple(getattr(expression, "server_ref_dependencies", ()) or ()),
        )
        filters[0] = QueryFilter(expression=normalized_expression)
        return replace(query_spec, filters=filters)
    value = getattr(filter_item, "value", _MISSING_FILTER_VALUE)
    if not isinstance(value, SysId):
        return query_spec
    filters[0] = QueryFilter(
        column=filter_item.column,
        operator=filter_item.operator,
        value=value.unwrap_to_str(),
        json_key=filter_item.json_key,
    )
    return replace(query_spec, filters=filters)


class QueryExecuteRawStep[T](SqlRelationPublisherStep[Sequence[T]]):
    """Execute a query spec and return plain dict rows."""

    def __init__(
        self: QueryExecuteRawStep,
        ref_id: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        config: _QueryExecuteRawStepConfig,
    ) -> None:
        super().__init__(ref_id)
        self._model_cls = model_cls
        self._query_spec = config.query_spec
        self._user_id_ref_id = config.user_id_ref_id
        self._hydrate_large_columns = config.hydrate_large_columns
        self._permission_action = config.permission_action
        self._compiled_cte_output_columns: tuple[str, ...] | None = None
        self._compiled_cte_column_type_hints: SqlColumnTypeHints | None = None

    @property
    def level(self: QueryExecuteRawStep) -> int:
        return 0

    def step_tags(self: QueryExecuteRawStep) -> frozenset[str]:
        return frozenset({"read", "query", "execute", "raw"})

    def is_read_only(self: QueryExecuteRawStep) -> bool:
        return True

    def result_cardinality(self: QueryExecuteRawStep) -> Cardinality:
        return Cardinality.MANY

    def raw_terminal_result_columns(self: QueryExecuteRawStep) -> tuple[str, ...] | None:
        if self._compiled_cte_output_columns is not None:
            return self._compiled_cte_output_columns
        if self._query_spec is None or self._query_spec.select_columns is None:
            return None
        from impl.common.l2070_server_plan.steps.query_execute import (
            _query_spec_selected_output_columns,
        )

        columns = tuple(
            output_name
            for output_name, _db_column, _is_binary in _query_spec_selected_output_columns(
                self._model_cls,
                self._query_spec,
            )
        )
        return columns

    def tables_read(self: QueryExecuteRawStep) -> frozenset[str]:
        from l1000_schema.table_utils import get_table_name

        return frozenset({get_table_name(self._model_cls)})

    def tables_written(self: QueryExecuteRawStep) -> frozenset[str]:
        return frozenset()

    def cte_publication_contract(self: QueryExecuteRawStep) -> CtePublicationContract:
        def _legacy_cte_output_columns() -> tuple[str, ...]:
            if self._query_spec is not None and (
                getattr(self._query_spec, "group_by", None)
                or getattr(self._query_spec, "aggregations", None)
                or getattr(self._query_spec, "window_functions", None)
            ):
                from impl.common.l2070_server_plan.steps.query_execute import (
                    _query_spec_computed_output_columns,
                )

                computed_columns = _query_spec_computed_output_columns(
                    self._model_cls,
                    self._query_spec,
                )
                return tuple(db_column for _output_name, db_column, _is_binary in computed_columns)
            if self._query_spec is not None and getattr(self._query_spec, "select_columns", None) is not None:
                from impl.common.l2070_server_plan.steps.query_execute import (
                    _query_spec_selected_output_columns,
                )

                return tuple(
                    output_name
                    for output_name, _db_column, _is_binary in _query_spec_selected_output_columns(
                        self._model_cls,
                        self._query_spec,
                    )
                )
            from l1000_schema.schema_def import get_db_column_name
            from l2070_batching.write_column_policy import collect_polymorphic_fields


            return tuple(
                get_db_column_name(self._model_cls, DynamicFieldName(field_name))
                for field_name in collect_polymorphic_fields(self._model_cls)
            )

        base_columns = _legacy_cte_output_columns()
        if self._compiled_cte_output_columns is not None:
            columns = self._compiled_cte_output_columns
        elif self._hydrate_large_columns:
            from impl.common.l2070_server_plan.steps.large_column_transport_contract import (
                selected_large_column_transport_columns,
            )

            large_columns = selected_large_column_transport_columns(self._model_cls, base_columns)
            columns = tuple(dict.fromkeys((*base_columns, *large_columns)))
        else:
            columns = base_columns

        def _legacy_cte_column_type_hints(columns: tuple[str, ...] | None) -> SqlColumnTypeHints:
            if not columns:
                return SqlColumnTypeHints()
            if self._hydrate_large_columns:
                from impl.common.l2070_server_plan.steps.large_column_transport_contract import (
                    large_column_transport_type_hints,
                    selected_large_column_transport_columns,
                )
                from impl.common.l2070_server_plan.steps.query_execute import _query_spec_column_type_hints
                from l2070_batching.sql_column_type_hints import combine_sql_column_type_hints

                large_columns = selected_large_column_transport_columns(self._model_cls, base_columns)
                base_hints = (
                    SqlColumnTypeHints()
                    if not base_columns
                    else _query_spec_column_type_hints(
                        self._model_cls,
                        self._query_spec,
                        base_columns,
                    )
                )
                return combine_sql_column_type_hints(
                    columns,
                    base_hints,
                    large_column_transport_type_hints(large_columns),
                )
            from impl.common.l2070_server_plan.steps.query_execute import _query_spec_column_type_hints

            return _query_spec_column_type_hints(self._model_cls, self._query_spec, columns)

        column_type_hints = (
            self._compiled_cte_column_type_hints
            if self._compiled_cte_column_type_hints is not None
            else _legacy_cte_column_type_hints(columns)
        )
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        _contract_model_cls = self._model_cls
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=tuple(str(column) for column in columns),
            column_type_hints=column_type_hints,
            model_cls=_contract_model_cls,
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def dependencies(self: QueryExecuteRawStep) -> frozenset[str]:
        deps: set[str] = set()
        if self._user_id_ref_id is not None:
            deps.add(str(self._user_id_ref_id))
        if self._query_spec is None:
            return frozenset(deps)
        from impl.common.l2070_server_plan.steps._resolve import collect_query_spec_deps

        deps.update(collect_query_spec_deps(self._query_spec))
        return frozenset(deps)

    def compile(self: QueryExecuteRawStep, ctx: CompilationContext) -> CompiledStep[Sequence[T]]:
        from l2070_batching.post_op import raw_rows_post_op
        from impl.common.l2070_server_plan.steps.query_execute import compile_sql_query_execute_step

        resolved_user_id = ctx.cte_refs.get(self._user_id_ref_id) if self._user_id_ref_id is not None else None
        compiled = compile_sql_query_execute_step(
            self._model_cls,
            _normalize_raw_select_one_sys_id_filter(self._query_spec, self._model_cls),
            ctx,
            raw_mode=True,
            resolved_user_id=resolved_user_id,
            closed_post_op=raw_rows_post_op(),
            step_name=type(self).__name__,
            force_hydrate_large_columns=self._hydrate_large_columns,
            permission_action=self._permission_action,
        )
        if compiled.output_shape is None:
            from l2070_batching.output_shape import (
                CompiledOutputShape,
                DeclaredResultRelation,
                synthetic_output_field,
            )

            contract = self.cte_publication_contract()
            output_shape = CompiledOutputShape(
                tuple(synthetic_output_field(column) for column in contract.columns),
            )
            compiled = replace(
                compiled,
                output_shape=output_shape,
                column_type_hints=contract.column_type_hints,
                result_relation=DeclaredResultRelation.from_output_shape(output_shape),
            )
            assert compiled.output_shape is not None
            assert compiled is not None
        self._compiled_cte_output_columns = compiled.output_shape.cte_output_columns
        self._compiled_cte_column_type_hints = compiled.column_type_hints
        self._cte_publication_contract_cache_valid = False
        self._publication_contract_cache_valid = False
        return cast("CompiledStep[Sequence[T]]", compiled)

