CLOSED_POST_OP_STRICT = True


class AllowOnDemandMaterialization(StrEnum):
    """Whether policy gates may use on-demand materialization."""

    NO = "no"
    YES = "yes"


def _materialization_filter_values(
    supported_materializations: frozenset[IndexMaterializationMode],
) -> list[str] | None:
    values: set[str] = set()
    if IndexMaterializationMode.DENSE_TIP in supported_materializations:
        values.add(BranchTipMaterialization.MATERIALIZED.value)
    if IndexMaterializationMode.SPARSE_CURRENT in supported_materializations:
        values.add(BranchTipMaterialization.TIPLESS.value)
    if len(values) == 2:
        return None
    return sorted(values)


def _policy_branch_query_spec(
    branch_context: ResolvedBranchIndexContext,
    decision: IndexPolicyDecision,
    *,
    filter_current_materialization: bool = False,
) -> QuerySpec[Any]:
    filters = [
        QueryFilter(
            expression=Expression(field="sys_id", operator="=", value=branch_context.branch_id),
        ),
    ]
    if decision.branch_filter.expression is not None:
        filters.append(QueryFilter(expression=decision.branch_filter.expression))
    if (
        decision.required_materialization
        in {
            IndexMaterializationMode.DENSE_TIP,
            IndexMaterializationMode.SPARSE_CURRENT,
        }
        or filter_current_materialization
    ):
        materialization_values = _materialization_filter_values(decision.supported_materializations)
        if materialization_values is not None:
            filters.append(
                QueryFilter(
                    expression=Expression(
                        field="tip_materialization",
                        operator="IN",
                        value=materialization_values,
                    ),
                ),
            )
    return QuerySpec(
        model_cls=branch_context.branch_model_cls,
        select_columns=None,
        distinct=False,
        joins=[],
        filters=filters,
        order_by=[],
        limit=1,
        offset=None,
        group_by=[],
        aggregations=[],
        having=[],
        window_functions=[],
        table=get_table_name(branch_context.branch_model_cls),
    )


def _policy_assertion_post_op(decision: IndexPolicyDecision, branch_context: ResolvedBranchIndexContext) -> CompiledPostOp:
    default_message = decision.reason or f"{decision.family.value} index policy excludes branch {branch_context.branch_id!r}"
    return CompiledPostOp.assert_result(
        ResultAssertionSpec(
            mappings=(
                AssertionExceptionMapping(
                    code=AssertionResultCode.POLICY_DENIED,
                    exc_type=BranchIndexPolicyError,
                    default_message=default_message,
                ),
            ),
            empty_result_code=AssertionResultCode.POLICY_DENIED,
        ),
    )


def _static_denial_post_op(decision: IndexPolicyDecision, branch_context: ResolvedBranchIndexContext) -> CompiledPostOp:
    if decision.required_materialization is not None:
        msg = decision.reason or (
            f"{decision.family.value} index policy requires "
            f"{decision.required_materialization.value} for branch {branch_context.branch_id!r}"
        )
        return static_exception_post_op(BranchIndexMaterializationError, msg)
    msg = decision.reason or f"{decision.family.value} index policy denies workload"
    return static_exception_post_op(BranchIndexPolicyError, msg)


class BranchIndexPolicyAssertStep(MaybeSqlRelationPublisherStep[None]):
    """Fail closed when an expensive-index policy cannot serve a branch."""

    def cte_publication_contract(self: BranchIndexPolicyAssertStep) -> CtePublicationContract:
        if not self._decision.allowed:
            return CtePublicationContract.non_publishing()
        output_shape = sql_assertion_output_shape()
        columns = output_shape.cte_output_columns
        column_type_hints = sql_assertion_column_type_hints()
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        _contract_model_cls = SqlAssertionResultRow
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=tuple(str(column) for column in columns),
            column_type_hints=column_type_hints,
            model_cls=_contract_model_cls,
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        decision: IndexPolicyDecision,
        branch_context: ResolvedBranchIndexContext,
    ) -> None:
        super().__init__(ref_id)
        self._decision = decision
        self._branch_context = branch_context

    @property
    def level(self) -> int:
        return 0

    def step_tags(self) -> frozenset[str]:
        return frozenset({"read", "index_policy", "branch_assert", self._decision.family.value})

    def is_read_only(self) -> bool:
        return True

    def result_cardinality(self) -> Cardinality:
        return Cardinality.ONE

    def supports_sql_batch_transport(self) -> bool:
        return True

    def tables_read(self) -> frozenset[str]:
        return frozenset({get_table_name(self._branch_context.branch_model_cls)})

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def dependencies(self) -> frozenset[str]:
        if isinstance(self._branch_context.branch_id, ServerRef):
            return frozenset(str(dep) for dep in self._branch_context.branch_id.dependencies())
        return frozenset()

    def compile(self, ctx: CompilationContext) -> CompiledStep[None]:
        if not self._decision.allowed:
            return CompiledStep(
                output_shape=None,
                result_relation=None,
                column_type_hints=None,
                closed_post_op=_static_denial_post_op(self._decision, self._branch_context),
            )
        query_spec = _policy_branch_query_spec(self._branch_context, self._decision)
        compiled = QueryExecuteRawStep[list[dict[str, Any]]](
            self.ref_id,
            self._branch_context.branch_model_cls,
            _QueryExecuteRawStepConfig(query_spec=query_spec),
        ).compile(ctx)
        output_shape = sql_assertion_output_shape()
        assert compiled.grammar is not None

        return cast(
            "CompiledStep[None]",
            CompiledStep(
                grammar=rows_exist_assertion_query(
                    compiled.grammar,
                    error_message=(
                        self._decision.reason
                        or f"{self._decision.family.value} index policy excludes branch {self._branch_context.branch_id!r}"
                    ),
                ),
                params=compiled.params,
                needs_returning=True,
                external_params_first=compiled.external_params_first,
                provenance_manifest=compiled.provenance_manifest,
                allow_empty_provenance_manifest=compiled.allow_empty_provenance_manifest,
                use_savepoint_recovery=compiled.use_savepoint_recovery,
                auxiliary_ctes=compiled.auxiliary_ctes,
                needs_recursive_with=compiled.needs_recursive_with,
                closed_post_op=sql_assertion_post_op(
                    self._decision.reason
                    or f"{self._decision.family.value} index policy excludes branch {self._branch_context.branch_id!r}",
                    exc_type=BranchIndexPolicyError,
                ),
                output_shape=output_shape,
                result_relation=DeclaredResultRelation.from_output_shape(output_shape),
                column_type_hints=sql_assertion_column_type_hints(),
            ),
        )


class BranchIndexPolicyRuntimeDecisionStep(MaybeSqlRelationPublisherStep[None]):
    """Resolve and enforce branch-aware policy after hydrating the branch row."""

    def cte_publication_contract(self: BranchIndexPolicyRuntimeDecisionStep) -> CtePublicationContract:
        if self._backend_type is None:
            return CtePublicationContract.non_publishing()
        output_shape = sql_assertion_output_shape()
        columns = output_shape.cte_output_columns
        column_type_hints = sql_assertion_column_type_hints()
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        _contract_model_cls = SqlAssertionResultRow
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=tuple(str(column) for column in columns),
            column_type_hints=column_type_hints,
            model_cls=_contract_model_cls,
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        adapter: FamilyPolicyAdapter,
        family: IndexFamily,
        workload: IndexWorkload,
        model_cls: type[DatabaseObjectRow[Any]],
        branch_context: ResolvedBranchIndexContext,
        backend_type: object | None,
        allow_on_demand_materialization: AllowOnDemandMaterialization = AllowOnDemandMaterialization.NO,
    ) -> None:
        super().__init__(ref_id)
        self._adapter = adapter
        self._family = family
        self._workload = workload
        self._model_cls = model_cls
        self._branch_context = branch_context
        self._backend_type = backend_type
        self._allow_on_demand_materialization = allow_on_demand_materialization

    @property
    def level(self) -> int:
        return 0

    def step_tags(self) -> frozenset[str]:
        return frozenset({"read", "index_policy", "branch_resolve_assert", self._family.value})

    def is_read_only(self) -> bool:
        return True

    def result_cardinality(self) -> Cardinality:
        return Cardinality.ONE

    def supports_sql_batch_transport(self) -> bool:
        return True

    def tables_read(self) -> frozenset[str]:
        return frozenset({get_table_name(self._branch_context.branch_model_cls)})

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def dependencies(self) -> frozenset[str]:
        if isinstance(self._branch_context.branch_id, ServerRef):
            return frozenset(str(dep) for dep in self._branch_context.branch_id.dependencies())
        return frozenset()

    def compile(self, ctx: CompilationContext) -> CompiledStep[None]:
        request = IndexPolicyRequest(
            family=self._family,
            workload=self._workload,
            model_cls=self._model_cls,
            branch_context=self._branch_context.to_public_request_context(),
            backend_type=self._backend_type,
            allow_on_demand_materialization=(self._allow_on_demand_materialization is AllowOnDemandMaterialization.YES),
        )
        decision = self._adapter.evaluate(request)
        if not decision.allowed:
            return CompiledStep(
                output_shape=None,
                result_relation=None,
                column_type_hints=None,
                closed_post_op=_static_denial_post_op(decision, self._branch_context),
            )
        query_spec = _policy_branch_query_spec(
            self._branch_context,
            decision,
            filter_current_materialization=self._workload
            in {
                IndexWorkload.CURRENT_BRANCH_READ,
                IndexWorkload.WRITE_MAINTENANCE,
            },
        )
        compiled = QueryExecuteRawStep[list[dict[str, Any]]](
            self.ref_id,
            self._branch_context.branch_model_cls,
            _QueryExecuteRawStepConfig(query_spec=query_spec),
        ).compile(ctx)
        output_shape = sql_assertion_output_shape()
        assert compiled.grammar is not None
        return cast(
            "CompiledStep[None]",
            CompiledStep(
                grammar=rows_exist_assertion_query(
                    compiled.grammar,
                    error_message=(
                        decision.reason or f"{decision.family.value} index policy excludes branch {self._branch_context.branch_id!r}"
                    ),
                ),
                params=compiled.params,
                needs_returning=True,
                external_params_first=compiled.external_params_first,
                provenance_manifest=compiled.provenance_manifest,
                allow_empty_provenance_manifest=compiled.allow_empty_provenance_manifest,
                use_savepoint_recovery=compiled.use_savepoint_recovery,
                auxiliary_ctes=compiled.auxiliary_ctes,
                needs_recursive_with=compiled.needs_recursive_with,
