        self._connection_id_value = config.connection_id_value
        self._session_id_raw = config.session_id_raw
        self._after_refs = config.after_refs
        self._source_ref = config.source_ref
        self._timestamp: datetime | None = None
        self._requires_source_boundary = False

    @property
    def level(self: EnsureStagedCommitStep) -> int:
