    def requires_prior_step_boundary(self: EnsureStagedCommitStep) -> bool:
        return self._requires_source_boundary

    def requires_materialized_inputs(self: EnsureStagedCommitStep) -> bool:
        return self._requires_source_boundary

    def configure_backend_scheduling(
        self: EnsureStagedCommitStep,
        profile: ServerPlanBackendProfile,
    ) -> None:
        """Apply the profile-owned source materialization boundary."""
        self._requires_source_boundary = bool(self._source_ref is not None and profile.traits.requires_staged_ensure_source_boundary)

    def estimated_param_count(self: EnsureStagedCommitStep) -> int | None:
        return 5

    def step_tags(self: EnsureStagedCommitStep) -> frozenset[str]:
        return frozenset({"write", "insert", "staged_commit", "idempotent"})

    def tables_read(self: EnsureStagedCommitStep) -> frozenset[str]:
        return frozenset()

    def tables_written(self: EnsureStagedCommitStep) -> frozenset[str]:
        return frozenset({get_table_name(self._domain.staged_commit_model)})

    def cte_publication_contract(self: EnsureStagedCommitStep) -> CtePublicationContract:
        columns = ("sys_id", "branch_id", "connection_id", "timestamp", "session_id")
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=columns,
            column_type_hints=SqlColumnTypeHints(
                uuid_columns=frozenset({"sys_id", "branch_id"}),
                timestamptz_columns=frozenset({"timestamp"}),
                text_columns=frozenset({"connection_id", "session_id"}),
            ),
            model_cls=_EnsureStagedCommitStepCteRow,
            source_tables=self.tables_written(),
            empty_result_allowed=True,
        )

    def dependencies(self: EnsureStagedCommitStep) -> frozenset[str]:
        own_dependencies = {str(ref) for ref in self._after_refs}
        if self._source_ref is not None:
            own_dependencies.add(str(self._source_ref))
        dependencies = getattr(self._lazy_branch, "dependencies", None)
        if not callable(dependencies):
            return frozenset(own_dependencies)
        typed_dependencies = cast(Callable[[], frozenset[str]], dependencies)
        return typed_dependencies() | frozenset(own_dependencies)

    def supports_ordered_sql_statement_batch(self: EnsureStagedCommitStep) -> bool:
        return True

    def ordered_transport_inlines_dependencies(self: EnsureStagedCommitStep) -> bool:
        return True

    def supports_ordered_materialized_input_dispatch(self: EnsureStagedCommitStep) -> bool:
        """The ordered request inlines the staged source dependency."""
        return True

    def sql_visible_dependencies(self: EnsureStagedCommitStep) -> frozenset[str]:
        dependencies = getattr(self._lazy_branch, "dependencies", None)
        branch_dependencies = cast(Callable[[], frozenset[str]], dependencies)() if callable(dependencies) else frozenset()
        source_dependencies = {str(self._source_ref)} if self._source_ref is not None else set()
        return branch_dependencies | frozenset(source_dependencies)

    def preprocess(self: EnsureStagedCommitStep, resolved: object) -> None:
        del resolved
        self._timestamp = datetime.now(UTC)

    def compile(
        self: EnsureStagedCommitStep,
        ctx: CompilationContext,
    ) -> CompiledStep[None]:
        from l1000_schema.schema_def import get_db_column_name
        from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName, SqlTableName
        from impl.common.l2100_sql_grammar.domain.infra.stmt_upsert import SqlInsertOrIgnore
        from impl.common.l2100_sql_grammar.domain.infra.stmt_dml_simple import SqlScalarSubquery
        from impl.common.l2100_sql_grammar.domain.versioning.stmt_cte import SqlDmlWithReturningColumns
        from impl.common.l2100_sql_grammar.domain.versioning.identifier_fragments import SqlColumnRef
        from impl.common.l2100_sql_grammar.tree.clauses import (
            SqlColumnList,
            SqlOnConflict,
            SqlSelectList,
        )
        from impl.common.l2100_sql_grammar.tree.enums import ConflictAction
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlParam
        from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
        from impl.common.l2100_sql_grammar.tree.statements import SqlCte, SqlInsert, SqlSelect
        from l2070_batching.compilation import CteReference

        staged_commit_model = self._domain.staged_commit_model
        table = get_table_name(staged_commit_model)

        py_columns = ["sys_id", "branch_id", "connection_id", "timestamp", "session_id"]
        timestamp = self._timestamp if self._timestamp is not None else datetime.now(UTC)

        db_columns: list[str] = []
        for c in py_columns:
            if c in getattr(staged_commit_model, "model_fields", {}):
                db_columns.append(get_db_column_name(staged_commit_model, DynamicFieldName(c)))
            else:
                db_columns.append(c)

        col_list = SqlColumnList(
            [SqlColumnRef(SqlColumnName(c)) for c in db_columns],
        )
        branch_expr: SqlRenderable = lower_versioned_branch_source(
            self._lazy_branch,
            ctx,
            site=f"{type(self).__name__}.compile",
        )
        from impl.common.l2070_server_plan.steps._auxiliary_ctes import (
            collect_dependency_auxiliary_ctes,
        )

        auxiliary_ctes = collect_dependency_auxiliary_ctes(ctx, self.dependencies()) or []

        if ctx.backend_profile.traits.requires_statement_local_merge_cte_ownership:
            branch_dependency_names = {
                alias
                for dependency in versioned_branch_dependencies(self._lazy_branch)
                for alias in (dependency, dependency.split(".", 1)[0])
            }
            branch_auxiliary_ctes = [(name, query) for name, query in auxiliary_ctes if name in branch_dependency_names]
            if branch_auxiliary_ctes:
                branch_expr = SqlScalarSubquery(
                    SqlCte(
                        branch_auxiliary_ctes,
                        SqlSelect(select=SqlSelectList([branch_expr])),
                    ),
                )

        value_exprs = [
            SqlParam(self._staged_commit_id_raw.unwrap_to_str()),
            branch_expr,
            SqlParam(self._connection_id_value),
            SqlParam(timestamp),
            SqlParam(self._session_id_raw),
        ]
        mariadb_conflict = (
            SqlOnConflict(
                columns=(SqlColumnName(db_columns[0]),),
                action=ConflictAction.DO_UPDATE,
                update_columns=(SqlColumnName(db_columns[0]),),
            )
            if ctx.backend_profile.traits.staged_commit_ensure_transport is StagedCommitEnsureTransport.NOOP_DUPLICATE_UPDATE
            else None
        )

        if self._source_ref is not None:
            source_binding = _require_conditional_staged_commit_source_cte(ctx, self._source_ref)
            source_query = source_binding.auxiliary_query
            if source_query is None:
                assert source_binding.ephemeral, f"Conditional staged commit source {self._source_ref} has no replayable SQL relation"
                source_relation: SqlRenderable = SqlTableIdent(
                    SqlTableName(source_binding.ref_id),
                )
            else:
                source_definitions, source_body = flatten_auxiliary_query_for_outer_cte(source_query)
                source_definition_names = {name for name, _query in source_definitions}
                auxiliary_ctes = [
                    (name, query)
                    for name, query in auxiliary_ctes
                    if name != source_binding.ref_id and name not in source_definition_names
                ]
                auxiliary_ctes.extend(source_definitions)
                if ctx.backend_profile.traits.requires_statement_local_merge_cte_ownership:
                    auxiliary_ctes.append((source_binding.ref_id, SqlOwnedCteScope(source_query)))
                    source_relation = SqlTableIdent(SqlTableName(source_binding.ref_id))
                else:
                    from impl.common.l2100_sql_grammar.tree.clauses import SqlSubqueryTableRef

                    source_relation = SqlSubqueryTableRef(
                        source_body,
                        SqlTableName("staged_commit_source"),
                    )
            grammar: SqlRenderable = SqlInsert(
                table=table,
                columns=col_list,
                values=SqlSelect(
                    select=SqlSelectList(value_exprs),
                    from_=source_relation,
                    limit=1,
                ),
                on_conflict=mariadb_conflict,
                or_ignore=mariadb_conflict is None,
            )
        elif mariadb_conflict is not None:
            grammar = SqlInsert(
                table=table,
                columns=col_list,
                values=SqlSelect(select=SqlSelectList(value_exprs)),
                on_conflict=mariadb_conflict,
            )
        else:
            grammar = SqlInsertOrIgnore(
                table=table,
                columns=col_list,
                values=value_exprs,
            )

        returning_columns = tuple(SqlColumnName(column) for column in db_columns)
        __opa002_grammar_186 = SqlDmlWithReturningColumns(grammar, returning_columns)
        output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(
            self.cte_publication_contract(),
        )
        return CompiledStep(
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
            grammar=__opa002_grammar_186,
            auxiliary_ctes=auxiliary_ctes or None,
            needs_returning=True,
            closed_post_op=literal_post_op(None),
        )


def build_ensure_staged_commit_step(
    ref_id: ServerPlanRefId,
    domain: type[VersioningDomain],
    lazy_branch: VersionedBranchSource,
    *,
    staged_commit_id_raw: object,
    connection_id_raw: object | None,
    session_id_raw: object,
    after_refs: frozenset[ServerPlanRefId] = frozenset(),
    source_ref: ServerPlanRefId | None = None,
) -> EnsureStagedCommitStep:
    """Build the staged-commit step without exposing its private config payload."""

    return EnsureStagedCommitStep(
        ref_id,
        domain,
        lazy_branch,
        config=_EnsureStagedCommitConfig(
            staged_commit_id_raw=StagedCommitId(str(staged_commit_id_raw)),
            connection_id_value=ConnectionId(str(connection_id_raw)) if connection_id_raw is not None else None,
            session_id_raw=SessionId(str(session_id_raw)),
            after_refs=after_refs,
            source_ref=source_ref,
        ),
    )

