class ValidateExistsStep(SqlRelationPublisherStep[bool]):
    """L0: execute a COUNT query and raise if count == 0."""

    __slots__ = ("_error_message", "_exception_cls", "_stmt")

    def __init__(
        self: ValidateExistsStep,
        ref_id: ServerPlanRefId,
        stmt: SqlRenderable,
        error_message: ValidationErrorMessage,
        exception_cls: type[Exception] = ValueError,
    ) -> None:
        super().__init__(ref_id)
        self._stmt = stmt
        self._error_message = error_message
        self._exception_cls = exception_cls

    @property
    def level(self: ValidateExistsStep) -> int:
        return 0

    def step_tags(self: ValidateExistsStep) -> frozenset[str]:
        return frozenset({"read", "grammar", "validate"})

