        return StepExecutionRole.SQL

    def result_cardinality(self: ValidateExistsStep) -> Cardinality:
        return Cardinality.ONE

    def requires_assertion_statement_transport(self: ValidateExistsStep) -> bool:
        return True

    def prevents_sql_owned_database_commit(self: ValidateExistsStep) -> bool:
        """Keep commit outside SQL until the assertion result is decoded."""
        return True

    def _native_assertion_aborts_before_commit(
        self: ValidateExistsStep,
        backend_profile: ServerPlanBackendProfile,
    ) -> bool:
        return backend_profile.traits.native_count_assertion_aborts_before_commit

    def native_assertion_error(self: ValidateExistsStep) -> Exception:
        """Preserve the configured exception for native assertion transport."""
        return self._exception_cls(str(self._error_message))

    def tables_read(self: ValidateExistsStep) -> frozenset[str]:
        return frozenset()

    def tables_written(self: ValidateExistsStep) -> frozenset[str]:
        return frozenset()

    def dependencies(self: ValidateExistsStep) -> frozenset[str]:
        return frozenset()

    def preprocess(self: ValidateExistsStep, resolved: ResolvedRefs) -> None:
        pass

    def internal_plan_ref_state(self: ValidateExistsStep) -> PlanPayloadState:
        return self.internal_plan_ref_state_excluding("_stmt")

    def cte_publication_contract(self: ValidateExistsStep) -> CtePublicationContract:
        output_shape = sql_assertion_output_shape()
        column_type_hints = sql_assertion_column_type_hints()
        columns = output_shape.cte_output_columns
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        contract_columns = tuple(str(column) for column in columns)
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=contract_columns,
            column_type_hints=column_type_hints,
            relation_contract=CteRelationContract.semantic_row(SqlAssertionRow),
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def compile(self: ValidateExistsStep, ctx: CompilationContext) -> CompiledStep[bool]:
        del ctx
        return _compile_exists_assertion(
            self._stmt,
            self._error_message,
            self._exception_cls,
        )


