@dataclass(frozen=True)
class _PendingTombstoneFromMergedConfig:
    staged_table_name: SqlTableName
    tip_table_name: SqlTableName
    staged_model: type[DatabaseObjectRow]
    tip_model: type[DatabaseObjectRow]
    data_columns: Sequence[str]
    lazy_branch: ScalarServerRef[BranchId]
    staged_commit_id: StagedCommitId
    sys_ids: Sequence[SysId]
    include_generated_storage_columns: bool = False
    depends_on: frozenset[ServerPlanRefId] = frozenset()


def _merged_data_columns(
    *,
    staged_model: type[DatabaseObjectRow],
    tip_model: type[DatabaseObjectRow],
    requested_columns: Sequence[str],
    include_generated_storage_columns: bool = False,
) -> tuple[str, ...]:
    excluded_field_names = frozenset(
        {
            "branch_id",
            "sys_id",
            "revision_id",
            "staged_commit_id",
            "deleted",
        },
    )
    if include_generated_storage_columns:
        staged_source_columns = returnable_db_columns(
            staged_model,
            excluded_fields=tuple(excluded_field_names),
            include_polymorphic=False,
        )
        tip_source_columns = returnable_db_columns(
            tip_model,
            excluded_fields=tuple(excluded_field_names),
            include_polymorphic=False,
        )
    else:
        staged_source_columns = tuple(
            plan.db_column
            for plan in versioned_data_field_plans(
                staged_model,
                excluded_fields=tuple(excluded_field_names),
                include_polymorphic=False,
            )
        )
        tip_source_columns = tuple(
            plan.db_column
            for plan in versioned_data_field_plans(
                tip_model,
                excluded_fields=tuple(excluded_field_names),
                include_polymorphic=False,
            )
        )

    staged_columns: list[str] = []
    staged_column_set: set[str] = set()
    for db_column in staged_source_columns:
        if db_column not in staged_column_set:
            staged_columns.append(db_column)
            staged_column_set.add(db_column)
    for db_column in _collect_large_column_pointer_db_columns(staged_model):
        if db_column not in staged_column_set:
            staged_columns.append(db_column)
            staged_column_set.add(db_column)

    tip_column_set: set[str] = set()
    for db_column in tip_source_columns:
        tip_column_set.add(db_column)
    tip_column_set.update(_collect_large_column_pointer_db_columns(tip_model))

    merged_columns: list[str] = []
    for column_name in [*requested_columns, *staged_columns]:
        if column_name in tip_column_set and column_name not in merged_columns:
            merged_columns.append(column_name)
    return tuple(merged_columns)


class PendingTombstoneFromMergedStep(SqlRelationPublisherStep[int]):
    """Expose delete-many tombstones as a logical staged source."""

    def __init__(
        self: PendingTombstoneFromMergedStep,
        ref_id: ServerPlanRefId,
        *,
        config: _PendingTombstoneFromMergedConfig,
    ) -> None:
        super().__init__(ref_id)
        self._staged_table_name = config.staged_table_name
        self._tip_table_name = config.tip_table_name
        self._staged_model = config.staged_model
        self._tip_model = config.tip_model
        self._data_columns = _merged_data_columns(
            staged_model=config.staged_model,
            tip_model=config.tip_model,
            requested_columns=config.data_columns,
            include_generated_storage_columns=config.include_generated_storage_columns,
        )
        self._lazy_branch = config.lazy_branch
        self._staged_commit_id = config.staged_commit_id
        self._sys_ids = tuple(config.sys_ids)
        self._dependencies = frozenset(str(ref_id) for ref_id in config.depends_on)

    @property
    def level(self: PendingTombstoneFromMergedStep) -> int:
        return 0

    def result_cardinality(self: PendingTombstoneFromMergedStep) -> Cardinality:
        return Cardinality.SCALAR

    def is_read_only(self: PendingTombstoneFromMergedStep) -> bool:
        return True

    def step_tags(self: PendingTombstoneFromMergedStep) -> frozenset[str]:
        return frozenset({"read", "grammar", "staged_source", "tombstone"})

    def is_tombstone_operation(self: PendingTombstoneFromMergedStep) -> bool:
        return True

    def tables_read(self: PendingTombstoneFromMergedStep) -> frozenset[str]:
        return frozenset({str(self._staged_table_name), str(self._tip_table_name)})

    def tables_written(self: PendingTombstoneFromMergedStep) -> frozenset[str]:
        return frozenset()

    def dependencies(self: PendingTombstoneFromMergedStep) -> frozenset[str]:
        return self._dependencies

    def cte_publication_contract(self: PendingTombstoneFromMergedStep) -> CtePublicationContract:
        def _legacy_cte_output_columns() -> tuple[str, ...]:
            staged_commit_col = get_db_column_name(self._staged_model, DynamicFieldName("staged_commit_id"))
            deleted_col = get_db_column_name(self._staged_model, DynamicFieldName("deleted"))
            return ("branch_id", "sys_id", staged_commit_col, deleted_col, *self._data_columns)

        columns = _legacy_cte_output_columns()

        def _legacy_cte_column_type_hints(columns: tuple[str, ...]) -> SqlColumnTypeHints:
            hints = model_sql_column_type_hints(self._staged_model, columns)
            if hints is None:
                msg = f"Could not resolve SQL column type hints for {self._staged_model.__name__}"
                raise TypeError(msg)
            return combine_sql_column_type_hints(
                columns,
                hints,
                framework_physical_column_sql_column_type_hints(),
            )

        column_type_hints = _legacy_cte_column_type_hints(columns)
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        contract_columns = tuple(str(column) for column in columns)
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=contract_columns,
            column_type_hints=column_type_hints,
            relation_contract=CteRelationContract.table_projection(
                source_table=str(self._staged_table_name),
                projection_lineage=tuple((column, column) for column in contract_columns),
            ),
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def provided_staged_sources(self: PendingTombstoneFromMergedStep) -> frozenset[str]:
        return frozenset({self._staged_table_name}) if self._sys_ids else frozenset()

    def _resolve_staged_source(self: PendingTombstoneFromMergedStep, ctx: CompilationContext) -> str:
        from impl.common.l2070_server_plan.steps.commit_branch_steps import _resolve_staged_source

        return _resolve_staged_source(SqlTableName(self._staged_table_name), ctx)

    def compile(self: PendingTombstoneFromMergedStep, ctx: CompilationContext) -> CompiledStep[int]:
        if not self._sys_ids:
            output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(
                self.cte_publication_contract(),
            )
            return CompiledStep(
                output_shape=output_shape,
                result_relation=result_relation,
                column_type_hints=column_type_hints,
                closed_post_op=literal_post_op(0),
            )

        sys_id_col = get_db_column_name(self._staged_model, DynamicFieldName("sys_id"))
        branch_col = get_db_column_name(self._staged_model, DynamicFieldName("branch_id"))
        staged_commit_col = get_db_column_name(self._staged_model, DynamicFieldName("staged_commit_id"))
        revision_col = get_db_column_name(self._staged_model, DynamicFieldName("revision_id"))
        deleted_col = get_db_column_name(self._staged_model, DynamicFieldName("deleted"))
        merged_alias = SqlAliasName("merged_src")
        merged_data_columns = list(dict.fromkeys([branch_col, sys_id_col, *self._data_columns]))

        merged = SqlVersionedMergedCte(
            tip_table=self._tip_table_name,
            staged_table=SqlTableName(self._resolve_staged_source(ctx)),
            read_projection=catalog_versioned_merged_projection(
                self._staged_model,
                tuple(SqlColumnName(column) for column in merged_data_columns),
            ),
            branch_id=self._lazy_branch,
            staged_commit_id=self._staged_commit_id,
            branch_column=SqlColumnName(branch_col),
            staged_commit_id_column=SqlColumnName(staged_commit_col),
            revision_id_column=SqlColumnName(revision_col),
            deleted_column=SqlColumnName(deleted_col),
            include_deleted=False,
        )

        select_items = [
            SqlColumnRef(SqlColumnName(branch_col), qualifier=merged_alias),
            SqlColumnRef(SqlColumnName(sys_id_col), qualifier=merged_alias),
            SqlSelectAlias(
                SqlCast(
                    SqlParam(self._staged_commit_id),
                    SqlCastTargetType(base_type="UUID"),
                ),
                alias=SqlAliasName(staged_commit_col),
            ),
            SqlSelectAlias(SqlBooleanLiteral(True), alias=SqlAliasName(deleted_col)),
            *[SqlColumnRef(SqlColumnName(column_name), qualifier=merged_alias) for column_name in self._data_columns],
        ]
        stmt = SqlSelect(
            select=SqlSelectList(select_items),
            from_clause=SqlFrom(
                SqlWrappedSubquery(merged, alias=merged_alias),
            ),
            where=SqlWhereClause(
                SqlInListParam(
                    SqlColumnRef(SqlColumnName(sys_id_col), qualifier=merged_alias),
                    self._sys_ids,
                ),
            ),
        )

        __opa002_grammar_258 = stmt
        output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(
            self.cte_publication_contract(),
        )
        return CompiledStep(
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
            grammar=__opa002_grammar_258,
            needs_returning=True,
            closed_post_op=CompiledPostOp.materialize(
                ResultMaterializationSpec(
                    behavior=PostOpBehavior.TERMINAL_SCALAR,
                ),
            ),
        )


