@pure_lazy
def _snake_case_graphql_name(value: str) -> str:
    with_underscores = re.sub(r"(?<!^)(?=[A-Z])", "_", value)
    return with_underscores.replace("-", "_").lower()


def _snake_case_graphql_name_static(value: str) -> str:
    with_underscores = re.sub(r"(?<!^)(?=[A-Z])", "_", value)
    return with_underscores.replace("-", "_").lower()


@pure_lazy
def _accepted_wire_names(value: str) -> tuple[str, ...]:
    names = (value, value[:1].lower() + value[1:] if value else value, _snake_case_graphql_name(value))
    return tuple(dict.fromkeys(name for name in names if name))


def _accepted_wire_names_static(value: str) -> tuple[str, ...]:
    names = (
        value,
        value[:1].lower() + value[1:] if value else value,
        _snake_case_graphql_name_static(value),
    )
    return tuple(dict.fromkeys(name for name in names if name))


@pure_lazy
def accepted_graphql_model_api_names(raw_model_name: str) -> tuple[str, ...]:
    """Return API-name spellings that can correspond to one GraphQL type name."""
    return _accepted_wire_names(raw_model_name)


@pure_lazy
def accepted_graphql_field_api_names(raw_field_name: str) -> tuple[str, ...]:
    """Return API-name spellings that can correspond to one GraphQL field name."""
    return _accepted_wire_names(raw_field_name)


def _eq(column: str, value: object) -> SqlBinaryOp:
    return SqlBinaryOp(SqlColumnRef(SqlColumnName(column)), BinaryOp.EQ, SqlParam(value))


def _name_match_expr(names: Sequence[str]) -> SqlBinaryOp:
    return cast("SqlBinaryOp", sql_or(*(_eq("binding_name", name) for name in names)))


def _raw_model_static_targets_model(model_cls: type[DatabaseObjectRow[Any]], raw_model_name: str) -> bool:
    raw_names = set(_accepted_wire_names_static(raw_model_name))
    static_names = {
        *_accepted_wire_names_static(model_cls.__name__),
        *_accepted_wire_names_static(get_model_api_name(model_cls)),
    }
    return bool(raw_names & static_names)


def _binding_exists_expr(
    *,
    semantic_id: str,
    binding_kind: str,
    names: Sequence[str],
) -> SqlExists:
    select_one = SqlSelect(
        select=SqlSelectList(SqlLiteral(1)),
        from_=_NAMING_TABLE,
        where=sql_and(
            _eq("semantic_id", semantic_id),
            _eq("binding_kind", binding_kind),
            _eq("active", True),
            _name_match_expr(names),
        ),
    )
    return SqlExists(select_one)


def _field_match_expr(model_cls: type[DatabaseObjectRow[Any]], field_name: str, raw_key: str) -> SqlExists:
    static_names = (
        get_field_api_name(model_cls, DynamicFieldName(field_name)),
        field_name,
        *get_field_api_aliases(model_cls, DynamicFieldName(field_name)),
    )
    names = tuple(dict.fromkeys((*accepted_graphql_field_api_names(raw_key), *static_names)))
    return _binding_exists_expr(
        semantic_id=get_field_semantic_id(model_cls, DynamicFieldName(field_name)),
        binding_kind="field",
        names=names,
    )


def _raw_key_can_target_field(
    model_cls: type[DatabaseObjectRow[Any]],
    field_name: str,
    raw_key: str,
) -> bool:
    if _raw_key_static_targets_field(model_cls, field_name, raw_key):
        return True
    raw_snake = _snake_case_graphql_name(raw_key)
    field_snake = _snake_case_graphql_name(field_name)
    return raw_snake.endswith(f"_{field_snake}") or field_snake.endswith(f"_{raw_snake}")


def _raw_key_static_targets_field(
    model_cls: type[DatabaseObjectRow[Any]],
    field_name: str,
    raw_key: str,
) -> bool:
    raw_names = set(accepted_graphql_field_api_names(raw_key))
    static_names = {
        get_field_api_name(model_cls, DynamicFieldName(field_name)),
        field_name,
        *get_field_api_aliases(model_cls, DynamicFieldName(field_name)),
    }
    return bool(raw_names & static_names)


def _default_value_for_field(
    model_cls: type[DatabaseObjectRow[Any]],
    field_name: str,
) -> object | None:
    model_fields = model_cls.model_fields
    if field_name == "sys_id":
        sys_id: object = SysId.new()
        return sys_id
    if field_name in {"created_at", "updated_at"}:
        timestamp: object = datetime.now(UTC)
        return timestamp
    if getattr(model_cls, "__polymorphic__", False):
        if field_name == "type_name":
            type_name: object = canonical_polymorphic_type_name(model_cls)
            return type_name
        type_id = getattr(model_cls, "__polymorphic_type_id__", None)
        if field_name == "type_id" and isinstance(type_id, int):
            return type_id
    field_info = model_fields[field_name]
    default_factory = getattr(field_info, "default_factory", None)
    if callable(default_factory):
        return cast("object | None", default_factory())
    default_value = getattr(field_info, "default", PydanticUndefined)
    if default_value is not PydanticUndefined:
        default_object: object | None = default_value
        return default_object
    return None


class GraphQLNamingCreateProjectionStep(SqlRelationPublisherStep[DatabaseObjectRow[Any]]):
    """Publish one SQL-visible create row selected by persisted API naming metadata."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        model_cls: type[DatabaseObjectRow[Any]],
        projection: GraphQLNamingCreateProjection,
        session_id: SessionId | None,
    ) -> None:
        super().__init__(ref_id)
        self._model_cls = model_cls
        self._projection = projection
        self._session_id = session_id

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.ONE

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def step_tags(self) -> frozenset[str]:
        return frozenset({"auto_api", "graphql", "naming", "projection", "sql_visible"})

    def is_read_only(self) -> bool:
        return True

    def tables_read(self) -> frozenset[str]:
        return frozenset({"sys_api_name_bindings"})

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def cte_relation_role(self) -> str:
        return "auto_api_graphql_named_create_row"

    def cte_publication_contract(self: GraphQLNamingCreateProjectionStep) -> CtePublicationContract:
        columns = tuple(self._db_columns())
        column_type_hints = model_field_sql_column_type_hints(
            self._model_cls, {field_name: get_db_column_name(self._model_cls, DynamicFieldName(field_name)) for field_name in self._ordered_fields()}
        )
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        _contract_model_cls = self._model_cls
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=tuple(str(column) for column in columns),
            column_type_hints=column_type_hints,
            model_cls=_contract_model_cls,
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def _ordered_fields(self) -> tuple[str, ...]:
        writable_fields = [field_plan.field_name for field_plan in versioned_data_field_plans(self._model_cls)]
        staged_fields = set(self._model_cls.model_fields)
        if getattr(self._model_cls, "__polymorphic__", False):
            for field_name in ("type_name", "type_id"):
                if field_name in staged_fields and field_name not in writable_fields:
                    writable_fields.append(field_name)
        return tuple(["sys_id", *writable_fields])

    def _db_columns(self) -> tuple[str, ...]:
        return tuple(get_db_column_name(self._model_cls, DynamicFieldName(field_name)) for field_name in self._ordered_fields())

    def _field_value_expr(self, field_name: GraphQLModelFieldName) -> SqlCase | SqlParam:
        unwrapped_field_name = str(field_name)
        whens = [
            (
                (
                    SqlLiteral(True)
                    if _raw_key_static_targets_field(self._model_cls, unwrapped_field_name, raw_key)
                    else _field_match_expr(self._model_cls, unwrapped_field_name, raw_key)
                ),
                SqlParam(raw_value),
            )
            for raw_key, raw_value in self._projection.input_values
            if _raw_key_can_target_field(self._model_cls, unwrapped_field_name, raw_key)
        ]
        default_value = _default_value_for_field(self._model_cls, unwrapped_field_name)
        if not whens:
            return SqlParam(default_value)
        return SqlCase(whens=whens, else_=SqlParam(default_value))

    def compile(self, ctx: CompilationContext) -> CompiledStep[DatabaseObjectRow[Any]]:
        model_predicate = (
            SqlLiteral(True)
            if _raw_model_static_targets_model(self._model_cls, self._projection.raw_model_name)
            else _binding_exists_expr(
                semantic_id=get_model_semantic_id(self._model_cls),
                binding_kind="type",
                names=self._projection.model_accept_names,
            )
        )
        aliases = [
            SqlSelectAlias(
                self._field_value_expr(GraphQLModelFieldName(field_name)),
                SqlAliasName(db_column),
            )
            for field_name, db_column in zip(self._ordered_fields(), self._db_columns(), strict=True)
        ]
        projected = SqlSelect(select=SqlSelectList(aliases), where=model_predicate)
        from impl.common.l2070_server_plan.steps.runtime_ref_projection import _compile_permission_where

        source_alias = SqlTableName("graphql_create_source")
        permission_where = _compile_permission_where(
            self._model_cls,
            ctx,
            table_alias=str(source_alias),
            action="insert",
        )
        __opa002_grammar_307 = (
            projected
            if permission_where is None
            else SqlSelect(
                select=SqlSelectList([SqlStar()]),
                from_=SqlSubqueryTableRef(projected, source_alias),
                where=permission_where,
            )
        )
        output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(
            self.cte_publication_contract(),
        )
        return CompiledStep(
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
            grammar=__opa002_grammar_307,
            needs_returning=True,
            closed_post_op=row_dicts_post_op(),
        )


@pure_lazy
def graphql_naming_create_row_lazy(
    txn: AsyncWriteTransaction,
    *,
    model_cls: type[DatabaseObjectRow[Any]],
    raw_model_name: str,
    input_values: Mapping[str, object],
) -> LazyResult[DatabaseObjectRow[Any]]:
    """Publish a create-row ref selected by persisted GraphQL naming metadata."""
    from l2050_transaction.lazy_mixin import enqueue_lazy_plan_intent, next_lazy_plan_ref

    session_id = getattr(txn, "_session_id", None)
    step = GraphQLNamingCreateProjectionStep(
        ServerPlanRefId(next_lazy_plan_ref(txn)),
        model_cls=model_cls,
        projection=GraphQLNamingCreateProjection(
            raw_model_name=raw_model_name,
            input_values=tuple(input_values.items()),
            model_accept_names=accepted_graphql_model_api_names(raw_model_name),
        ),
        session_id=session_id if isinstance(session_id, SessionId) else None,
    )
    result: LazyResult[DatabaseObjectRow[Any]] = enqueue_lazy_plan_intent(txn, step)
    return result

