@pure_lazy
def _executor_published_mysql_scalar(
    binding: ScalarServerRefBinding,
    ctx: CompilationContext,
) -> tuple[bool, object | None]:
    """Read one declared literal publication without resolving runtime plan state."""
    # MySQL scalar inlining is valid only for an explicit SqlPublishedRowsQuery;
    # runtime-semantic rows must remain behind exact executor-owned refs.
    if ctx.backend_profile.traits.published_scalar_transport is not PublishedScalarTransport.INLINE_SINGLE_ROW:
        return False, None
    cte_ref = ctx.cte_refs.get(binding.cte_name)
    if cte_ref is None:
        return False, None
    from impl.common.l2100_sql_grammar.domain.infra.stmt_cte_helpers import (
        SqlPublishedRowsQuery,
    )

    auxiliary_query = cte_ref.auxiliary_query
    if not isinstance(auxiliary_query, SqlPublishedRowsQuery):
        return False, None
    rows = auxiliary_query.published_rows_readonly
    if not rows:
        # A scalar subquery over an explicitly empty relation evaluates to NULL.
        # Inline that exact value on MySQL instead of referencing a statement-local
        # CTE that has no row to publish across the physical boundary.
        return True, None
    if len(rows) != 1 or binding.field_name not in rows[0]:
        return False, None
    return True, rows[0][binding.field_name]


@dataclass(frozen=True, slots=True)
class ScalarServerRefBinding:
    cte_name: str
    field_name: str


@pure_lazy
def get_scalar_server_ref_binding[T](
    ref: ScalarServerRef[T],
    ctx: CompilationContext,
    *,
    default_field: str = "sys_id",
) -> ScalarServerRefBinding | None:
    """Return the current CTE binding for ``ref`` if one exists."""
    shape: PlanningServerValueShape = inspect_server_value_shape_for_planning(
        ref,
        site="get_scalar_server_ref_binding",
    )
    ref_id = shape.symbolic_ref_id
    if ref_id is None:
        return None
    scalar_projection = ctx.scalar_projection_bindings.get(ServerPlanRefId(ref_id))
    binding = resolve_sql_visible_ref(
        ctx,
        ServerPlanRefId(ref_id),
        default_field=default_field,
    )
    if scalar_projection is not None:
        scalar_column = scalar_projection.scalar_value_column
        if scalar_column is None:
            msg = f"Scalar projection {scalar_projection.ref_id!r} has no declared scalar value column."
            raise TypeError(msg)
        return ScalarServerRefBinding(
            cte_name=scalar_projection.ref_id,
            field_name=scalar_column.to_row_key(),
        )
    if binding is None:
        return None
    return ScalarServerRefBinding(
        cte_name=binding.cte_name,
        field_name=binding.field_name,
    )


@pure_lazy
def lower_scalar_server_ref[T](
    ref: ScalarServerRef[T],
    ctx: CompilationContext,
    *,
    default_field: str = "sys_id",
) -> SqlRenderable:
    """Lower a scalar ``ServerRef`` into a SQL expression."""
    if not isinstance(ref, ServerRef):
        return SqlParam(unwrap_literal_sql_value(ref))
    shape: PlanningServerValueShape = inspect_server_value_shape_for_planning(
        ref,
        site="lower_scalar_server_ref",
    )
    if shape.symbolic_ref_id is None:
        msg = "ScalarServerRef without ref_id cannot be lowered"
        raise TypeError(msg)
    ref_id = shape.symbolic_ref_id
    payload = dict(server_ref_named_payload_items(ref))
    type_hint = payload.get("_type_hint")
    if ".raw." in str(ref_id) and (type_hint is bytes or type_hint is bytearray):
        msg = f"raw large-column scalar ref {ref_id!s} is not a valid SQL filter source"
        raise RuntimeError(msg)
    binding = get_scalar_server_ref_binding(
        ref,
        ctx,
        default_field=default_field,
    )
    if binding is not None:
        return lower_sql_visible_scalar_binding(binding, ctx)
    ref_id_str = str(ref_id)
    found_seed, seed_value = read_seeded_constant_from_ctx(ctx, ServerPlanRefId(ref_id_str))
    if not found_seed and ref_id_str.startswith("seed_"):
        found_seed, seed_value = read_seeded_constant_from_ctx(None, ServerPlanRefId(ref_id_str))
    if found_seed:
        return lower_scalar_source(seed_value, ctx, default_field=default_field)
    raise_missing_cte_fallback_forbidden(
        site_name="lower_scalar_server_ref",
        trigger=f"compile-time lowering for {ref_id!r} without a published CTE binding",
        blocked_path="planner-time resolution of unresolved ScalarServerRef values",
        result_contract=(
            "scalar refs must lower from literal values, explicit CTE-published fields, or executor-published SQL-visible bindings"
        ),
        implementation_requirements=(
            "Publish the needed scalar as an explicit upstream SQL-visible ref before compile().",
            "Have the executor republish completed cross-group values into ctx.cte_refs as typed bindings.",
            "Do not reintroduce preprocess-owned scalar caches or nested replanning.",
        ),
    )
    raise AssertionError("unreachable")


@pure_lazy
def lower_sql_visible_scalar_binding(
    binding: ScalarServerRefBinding,
    ctx: CompilationContext,
) -> SqlRenderable:
    """Lower a producer-owned scalar through its published transport."""
    found_published_scalar, published_scalar = _executor_published_mysql_scalar(binding, ctx)
    if found_published_scalar:
        return SqlParam(unwrap_literal_sql_value(published_scalar))
    return SqlCteFieldRef(SqlCteStepName(binding.cte_name), SqlColumnName(binding.field_name))


@pure_lazy
def lower_scalar_source(
    value: object,
    ctx: CompilationContext,
    *,
    default_field: str = "sys_id",
) -> SqlRenderable:
    """Lower a scalar source value or ``ScalarServerRef`` into SQL."""
    from impl.common.l2100_sql_grammar.domain.infra.stmt_unnest_insert import SqlArrayParam
    from l2055_lazy_result.lazy_result import LazyResult

    if isinstance(value, SqlParam):
        nested = value.value
        return lower_scalar_source(nested, ctx, default_field=default_field) if isinstance(nested, SqlParam) else value
    if isinstance(value, SqlRenderable):
        return value
    if isinstance(value, SqlArrayParam):
        return SqlParam(value)
    if isinstance(value, ScalarServerRef):
        return lower_scalar_server_ref(value, ctx, default_field=default_field)
    if isinstance(value, LazyResult):
        shape = inspect_server_value_shape_for_planning(
            value,
            site="lower_scalar_source",
        )
        if shape.symbolic_ref_id is not None:
            return lower_scalar_server_ref(
                ServerRefs.from_ref_id(
                    shape.symbolic_ref_id,
                    variant="scalar",
                    type_hint=object,
                ),
                ctx,
                default_field=default_field,
            )
        if getattr(getattr(value, "_state", None), "name", None) == "RESOLVED":
            return SqlParam(unwrap_literal_sql_value(object.__getattribute__(value, "_value")))
        msg = "LazyResult scalar sources must publish a scalar ref before SQL lowering"
        raise TypeError(msg)
    ref_id = getattr(value, "ref_id", None)
    if isinstance(ref_id, str):
        scalar_projection = ctx.scalar_projection_bindings.get(ServerPlanRefId(ref_id))
        if scalar_projection is not None:
            scalar_column = scalar_projection.scalar_value_column
            if scalar_column is None:
                msg = f"Scalar projection {scalar_projection.ref_id!r} has no declared scalar value column."
                raise TypeError(msg)
            return SqlCteFieldRef(
                SqlCteStepName(scalar_projection.ref_id),
                scalar_column.to_sql_column_name(),
            )
        binding = resolve_sql_visible_ref(
            ctx,
            ServerPlanRefId(ref_id),
            default_field=default_field,
        )
        if binding is not None:
            return SqlCteFieldRef(SqlCteStepName(binding.cte_name), SqlColumnName(binding.field_name))
    scalar_value: Any = value
    return SqlParam(unwrap_literal_sql_value(scalar_value))


@pure_lazy
def lower_scalar_row_cell(
    value: object,
    ctx: CompilationContext,
    *,
    default_field: str = "sys_id",
) -> SqlRenderable:
    """Lower one bulk-row scalar cell into SQL."""
    return _lower_scalar_row_cell_lazy(value, ctx, default_field=default_field, unwrap_depth=0)


def _lower_scalar_row_cell_lazy(
    value: object,
    ctx: CompilationContext,
    *,
    default_field: str,
    unwrap_depth: int,
) -> SqlRenderable:
    """Lower a scalar cell while bounding recursive wrapper unwrapping."""
    from impl.common.l2100_sql_params.runtime_bind_slot import SqlRuntimeBindSlot
    from l2055_lazy_result.lazy_result import LazyResult

    if unwrap_depth > 16:
        msg = "Scalar row cell literal unwrapping exceeded the maximum recursion depth"
        raise TypeError(msg)
    if isinstance(value, LazyResult):
        shape = inspect_server_value_shape_for_planning(
            value,
            site="lower_scalar_row_cell",
        )
        if shape.symbolic_ref_id is not None:
            ref = ServerRefs.from_ref_id(
                shape.symbolic_ref_id,
                variant="scalar",
                type_hint=object,
            )
            return lower_scalar_server_ref(ref, ctx, default_field=default_field)
        msg = "LazyResult row cells must publish a scalar ref before SQL lowering"
        raise TypeError(msg)
    if isinstance(value, SqlRuntimeBindSlot):
        if value.field_name is None:
            # A slot without a field projection is an external scalar bind.
            # Bulk write rows must preserve it as a parameter so the same
            # compiled grammar can be rebound for each request.
            return SqlParam(value)
        return lower_projected_ref_field_lazy(ServerPlanRefId(value.ref_id), value.field_name, ctx)
    if isinstance(value, ScalarServerRef):
        shape = inspect_server_value_shape_for_planning(
            value,
            site="lower_scalar_row_cell",
        )
        if shape.symbolic_ref_id is not None:
            return lower_scalar_server_ref(value, ctx, default_field=default_field)
        msg = "ScalarServerRef row cell without ref_id cannot be lowered"
        raise TypeError(msg)
    duck_ref_id = duck_server_ref_id(value)
    if duck_ref_id is not None:
        ref = ServerRefs.from_ref_id(
            str(duck_ref_id),
            variant="scalar",
            type_hint=object,
        )
        return lower_scalar_server_ref(ref, ctx, default_field=default_field)
    if isinstance(value, ServerRef):
        msg = "Bulk row cells require scalar refs; project object or sequence refs before insert"
        raise TypeError(msg)
    scalar_value = unwrap_literal_sql_value(value)
    if scalar_value is not value:
        return _lower_scalar_row_cell_lazy(
            scalar_value,
            ctx,
            default_field=default_field,
            unwrap_depth=unwrap_depth + 1,
        )
    if ctx.backend_profile.traits.dml_parameter_transport is DmlParameterTransport.EXPLICIT_STORAGE_CASTS and isinstance(
        scalar_value, UUID
    ):
        return SqlCast(SqlParam(scalar_value), _UUID_CAST_TARGET)
    return SqlParam(scalar_value)


def lower_projected_ref_field_lazy(
    ref_id: ServerPlanRefId,
    field_name: str,
    ctx: CompilationContext,
) -> SqlRenderable:
    """Lower ``field_name`` from an arbitrary step ref without ``ServerRef`` validation."""
    binding = resolve_sql_visible_ref(
        ctx,
        ref_id,
        field_name=field_name,
    )
    if binding is not None:
        return SqlCteFieldRef(
            SqlCteStepName(binding.cte_name),
            SqlColumnName(binding.field_name),
        )
    projection_ref = ServerPlanRefId(f"{ref_id}.{field_name}")
    found_seed, seed_value = read_seeded_constant_from_ctx(ctx, projection_ref)
    if found_seed:
        return lower_scalar_source(seed_value, ctx, default_field=field_name)
    raise_missing_cte_fallback_forbidden(
        site_name="lower_projected_ref_field",
        trigger=f"compile-time lowering for {ref_id!r}.{field_name}",
        blocked_path="planner-time resolution of unresolved projected step fields",
        result_contract=(
            "projected ref fields must lower from explicit CTE-published columns or executor-published SQL-visible bindings"
        ),
        implementation_requirements=(
            "Publish the needed field as an explicit upstream SQL-visible ref before compile().",
            "Have the executor republish completed cross-group values into ctx.cte_refs as typed bindings.",
            "Do not reintroduce preprocess-owned field caches or nested replanning.",
        ),
    )
    raise AssertionError("unreachable")


def lower_projected_ref_field(
    ref_id: ServerPlanRefId,
    field_name: str,
    ctx: CompilationContext,
) -> SqlRenderable:
    return lower_projected_ref_field_lazy(ref_id, field_name, ctx)

