    def preprocess(self, resolved: ResolvedRefs) -> None:
        del resolved

    def compile(self, ctx: CompilationContext) -> CompiledStep[list[dict[str, Any]]]:
        symbolic_ctx = replace(ctx, materialized_pipeline=MaterializedPipeline())

        from impl.common.l2050_sql_types.sql_branded_types import SqlAliasName, SqlColumnName, SqlTableName
        from impl.common.l2060_query_spec.query_spec import QuerySpec
        from impl.common.l2070_server_plan.steps._compile_helpers import (
            attach_runtime_permission_grammar,
            compile_query_grammar,
            extract_columns_and_values_from_plan,
            filter_columns_and_values_to_existing_schema,
            get_write_metadata_plan_from_catalog,
        )
        from impl.common.l2070_server_plan.steps._compile_insert import (
            require_insert_columns_after_schema_filter,
        )
        from impl.common.l2070_server_plan.steps._compile_server_ref import (
            lower_scalar_server_ref,
        )
        from impl.common.l2070_server_plan.steps._prepare_instance import (
            prepare_instance_for_insert_lazy,
        )
        from impl.common.l2100_sql_grammar.domain.infra.stmt_cte_helpers import (
            SqlSelectExpressions,
        )
        from impl.common.l2100_sql_grammar.domain.infra.stmt_dml_simple import (
            SqlInsertFromSelectStmt,
            SqlWrappedSubquery,
        )
        from impl.common.l2100_sql_grammar.protocols import SqlRenderable
        from impl.common.l2100_sql_grammar.tree.clauses import (
            SqlColumnNameList,
            SqlItemList,
            SqlReturningClause,
        )
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlParam, SqlStar
        from impl.common.l2100_sql_grammar.tree.expr_ops import SqlExists
        from l2070_batching.server_ref import ScalarServerRef

        effective_spec = cast(
            "QuerySpec[DatabaseObjectRow[Any]]",
            attach_runtime_permission_grammar(
                self._query_spec,
                self._model_cls,
                symbolic_ctx,
                action="read",
            ),
        )
        compiled_lookup = compile_query_grammar(
            effective_spec,
            self._model_cls,
            symbolic_ctx,
            is_count=False,
            needs_returning=False,
        )

        prepared_instance = prepare_instance_for_insert_lazy(self._model_cls, self._instance)
        write_plan = get_write_metadata_plan_from_catalog(ctx.planning_catalog, self._model_cls)
        columns, values = extract_columns_and_values_from_plan(
            write_plan,
            prepared_instance,
            backend_type=ctx.backend_type,
        )
        filtered_columns, filtered_values = filter_columns_and_values_to_existing_schema(
            ctx.schema_column_cache,
            get_table_name(self._model_cls),
            columns,
            values,
        )
        columns = list(filtered_columns)
        values = list(filtered_values)
        table_name = get_table_name(self._model_cls)
        require_insert_columns_after_schema_filter(
            table_name=SqlTableName(table_name),
            columns=columns,
            operation="GuardedInsertStep",
        )
        payload_alias = SqlAliasName("guarded_insert_payload")
        payload_items: list[tuple[SqlRenderable, str]] = []
        for column, value in zip(columns, values, strict=True):
            expr: SqlRenderable = lower_scalar_server_ref(value, symbolic_ctx) if isinstance(value, ScalarServerRef) else SqlParam(value)
            expr = _cast_guarded_insert_payload_expr(self._model_cls, column, expr, ctx)
            payload_items.append((expr, column))

        insert_columns = SqlColumnNameList([SqlColumnName(column) for column in columns])
        insert_source = SqlWrappedSubquery(
            SqlSelectExpressions(payload_items),
            alias=payload_alias,
        )
        insert_select_columns = SqlItemList(
            [SqlColumnRef(SqlColumnName(column), qualifier=payload_alias) for column in columns],
        )
        insert_where = SqlExists(
            cast("SqlRenderable", compiled_lookup.grammar),
            negated=True,
        )
        grammar: SqlRenderable = SqlInsertFromSelectStmt(
            target=SqlTableName(table_name),
            columns=insert_columns,
            source=insert_source,
            select_columns=insert_select_columns,
            where=insert_where,
            returning=SqlReturningClause(SqlStar()),
        )
        supports_returning = ctx.sql_render_dialect().supports_returning()
        if not supports_returning:
            from impl.common.l2100_sql_grammar.domain.infra.stmt_compound_write import (
                SqlStatementBatch,
                SqlStatementBatchCategory,
            )
            from impl.common.l2100_sql_grammar.tree.clauses import SqlWhereClause
            from impl.common.l2100_sql_grammar.tree.expr_ops import BinaryOp, SqlBinaryOp
            from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
            from impl.common.l2100_sql_grammar.tree.statements import SqlSelect

            sys_id_index = columns.index("sys_id")
            readback = SqlSelect(
                select=SqlStar(),
                from_=SqlTableIdent(SqlTableName(table_name)),
                where=SqlWhereClause(
                    SqlBinaryOp(
                        SqlColumnRef(SqlColumnName("sys_id")),
                        BinaryOp.EQ,
                        payload_items[sys_id_index][0],
                    ),
                ),
            )
            insert_without_returning = SqlInsertFromSelectStmt(
                target=SqlTableName(table_name),
                columns=insert_columns,
                source=insert_source,
                select_columns=insert_select_columns,
                where=insert_where,
                returning=None,
            )
            grammar = SqlStatementBatch(
                [insert_without_returning, readback],
                category=SqlStatementBatchCategory.ORDERED_SEMANTIC,
                needs_returning_per_stmt=[False, True],
                collect_results_per_stmt=[False, True],
            )
        __opa002_grammar_313 = grammar
        contract = self.cte_publication_contract()
        from l2070_batching.output_shape import CompiledOutputShape, DeclaredResultRelation, synthetic_output_field

        output_shape = CompiledOutputShape(
            tuple(synthetic_output_field(column) for column in contract.columns),
        )
        return CompiledStep(
            output_shape=output_shape,
            result_relation=DeclaredResultRelation.from_output_shape(output_shape),
            grammar=__opa002_grammar_313,
            params=compiled_lookup.params,
            needs_returning=True,
            column_type_hints=contract.column_type_hints,
            external_params_first=compiled_lookup.external_params_first,
            runtime_ref_ids=compiled_lookup.runtime_ref_ids,
            auxiliary_ctes=compiled_lookup.auxiliary_ctes,
            closed_post_op=row_dicts_post_op(),
        )

