from __future__ import annotations

from collections.abc import Awaitable, Callable, Iterable, Mapping, Sequence
from dataclasses import dataclass
from typing import Any, Literal, cast

from impl.common.l2050_sql_types.sql_branded_types import ContentHashValue, SqlColumnName, SqlTableName
from impl.common.l2070_server_plan.steps.large_column_read import (
    _coerce_bytes,
