def _mapping_row_dicts(rows: Sequence[object]) -> list[dict[str, object]]:
    normalized: list[dict[str, object]] = []
    for row in rows:
        if isinstance(row, Mapping):
            normalized.append(dict(row))
            continue
        keys = getattr(row, "keys", None)
        if callable(keys):
            key_values = keys()
            if not isinstance(key_values, Iterable):
                raise TypeError("Row keys() must return an iterable")
            row_values = cast("Any", row)
            normalized.append({str(key): row_values[key] for key in key_values})
            continue
        msg = f"Large-column restore expected mapping row, got {type(row).__name__}"
        raise TypeError(msg)
    return normalized


from l2070_batching.compilation import CompilationContext, CompiledStep, ResolvedRefs
from l2070_batching.payload_state import PlanPayloadValue
from l2070_batching.step import NonPublishingStep, StepExecutionRole

LargeColumnRestoreContentType = Literal["binary", "text"]


@dataclass(frozen=True, slots=True)
class LargeColumnInlineRestoreResult:
    """Summary of executor-owned inline restoration work."""

    restored_rows: int
    incomplete_rows: int


class LargeColumnInlineRestoreStep(NonPublishingStep[LargeColumnInlineRestoreResult]):
    """Restore spilled large-column payloads after removing a large-column flag."""

    def __init__(
        self: LargeColumnInlineRestoreStep,
        ref_id: ServerPlanRefId,
        *,
        table_name: SqlTableName,
        value_column: SqlColumnName,
        pointer_column: SqlColumnName,
        content_type: LargeColumnRestoreContentType,
        batch_limit: int = 1000,
    ) -> None:
        super().__init__(ref_id)
        self._table_name = table_name
        self._value_column = value_column
        self._pointer_column = pointer_column
        self._content_type = content_type
        self._batch_limit = batch_limit

    @property
    def level(self: LargeColumnInlineRestoreStep) -> int:
        return 0

    def step_tags(self: LargeColumnInlineRestoreStep) -> frozenset[str]:
        return frozenset({"schema", "large_column", "restore", "write"})

    def execution_role(self: LargeColumnInlineRestoreStep) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def is_executor_owned_runtime_step(self: LargeColumnInlineRestoreStep) -> bool:
        return True

    def supports_sql_batch_transport(self: LargeColumnInlineRestoreStep) -> bool:
        return False

    def requires_runtime_sequential_batch(self: LargeColumnInlineRestoreStep) -> bool:
        return True

    def result_cardinality(self: LargeColumnInlineRestoreStep) -> Cardinality:
        return Cardinality.ONE

    def dependencies(self: LargeColumnInlineRestoreStep) -> frozenset[str]:
        return frozenset()

    def tables_read(self: LargeColumnInlineRestoreStep) -> frozenset[str]:
        return frozenset({str(self._table_name), str(self._store_table_name()), str(self._chunks_table_name())})

    def tables_written(self: LargeColumnInlineRestoreStep) -> frozenset[str]:
        return frozenset({str(self._table_name)})

    def internal_plan_state(self: LargeColumnInlineRestoreStep) -> Mapping[str, PlanPayloadValue]:
        return cast(
            "Mapping[str, PlanPayloadValue]",
            {
                "table": str(self._table_name),
                "value_column": str(self._value_column),
                "pointer_column": str(self._pointer_column),
                "content_type": self._content_type,
                "batch_limit": self._batch_limit,
            },
        )

    def internal_plan_ref_state(self: LargeColumnInlineRestoreStep) -> Mapping[str, PlanPayloadValue]:
        return self.internal_plan_state()

    def compile(self: LargeColumnInlineRestoreStep, ctx: CompilationContext) -> CompiledStep[LargeColumnInlineRestoreResult]:
        del ctx
        return CompiledStep()

    def execute_runtime(
        self: LargeColumnInlineRestoreStep,
        resolved: ResolvedRefs,
        hydrator: object,
    ) -> LargeColumnInlineRestoreResult | Awaitable[LargeColumnInlineRestoreResult]:
        del resolved
        sql_conn = getattr(hydrator, "sql_conn", None)
        if sql_conn is None:
            msg = "Large-column inline restore requires an executor-bound SQL connection."
            raise RuntimeError(msg)
        from l2000_connection.connection import AsyncDatabaseConnection

        if isinstance(sql_conn, AsyncDatabaseConnection):
            return self._run_async(sql_conn)
        from impl.common.l2070_server_plan.execution_context import allow_direct_sql_in_step_execution

        with allow_direct_sql_in_step_execution():
            return self._run_blocking(sql_conn)

    def _store_table_name(self: LargeColumnInlineRestoreStep) -> SqlTableName:
        return SqlTableName(f"{self._table_name}_content_store")

    def _chunks_table_name(self: LargeColumnInlineRestoreStep) -> SqlTableName:
        return SqlTableName(f"{self._store_table_name()}_chunks")

    def _run_blocking(self: LargeColumnInlineRestoreStep, sql_conn: object) -> LargeColumnInlineRestoreResult:
        execute_direct = getattr(sql_conn, "_execute_direct_internal", None)
        if not callable(execute_direct):
            msg = f"{type(sql_conn).__name__} does not provide _execute_direct_internal()."
            raise RuntimeError(msg)
        restored_rows = 0
        incomplete_rows = 0
        while True:
            rows = execute_direct(self._candidate_scan(), fetch_mode="all")
            if not rows:
                break
            if not isinstance(rows, Sequence):
                raise TypeError("Large-column candidate scan must return a row sequence")
            restored_in_batch = self._restore_rows_blocking(execute_direct, rows)
            restored_rows += restored_in_batch
            incomplete_rows += max(0, len(rows) - restored_in_batch)
            if restored_in_batch == 0 or len(rows) < self._batch_limit:
                break
        return LargeColumnInlineRestoreResult(restored_rows=restored_rows, incomplete_rows=incomplete_rows)

    async def _run_async(
        self: LargeColumnInlineRestoreStep,
        sql_conn: object,
    ) -> LargeColumnInlineRestoreResult:
        from impl.common.l2070_server_plan.execution_context import allow_direct_sql_in_step_execution

        execute_direct_async = cast("Callable[..., Awaitable[object]]", getattr(sql_conn, "_execute_direct_internal_async"))
        with allow_direct_sql_in_step_execution():
            return await self._run_with_direct_executor_async(execute_direct_async)

    async def _run_with_direct_executor_async(
        self: LargeColumnInlineRestoreStep,
        execute_direct_async: Callable[..., Awaitable[object]],
    ) -> LargeColumnInlineRestoreResult:
        restored_rows = 0
        incomplete_rows = 0
        while True:
            rows = cast(
                "list[Mapping[str, object]]",
                await execute_direct_async(self._candidate_scan(), fetch_mode="all"),
            )
            if not rows:
                break
            restored_in_batch = await self._restore_rows_async(execute_direct_async, rows)
            restored_rows += restored_in_batch
            incomplete_rows += max(0, len(rows) - restored_in_batch)
            if restored_in_batch == 0 or len(rows) < self._batch_limit:
                break
        return LargeColumnInlineRestoreResult(restored_rows=restored_rows, incomplete_rows=incomplete_rows)

    def _candidate_scan(self: LargeColumnInlineRestoreStep) -> SqlLargeColumnInlineRestoreCandidateScan:
        return SqlLargeColumnInlineRestoreCandidateScan(
            self._table_name,
            self._value_column,
            self._pointer_column,
            limit=self._batch_limit,
        )

    def _restore_rows_blocking(self: LargeColumnInlineRestoreStep, execute_direct: object, rows: object) -> int:
        if not isinstance(rows, Sequence) or isinstance(rows, str | bytes | bytearray):
            msg = f"Large-column restore expected row sequence, got {type(rows).__name__}"
            raise TypeError(msg)
        row_dicts = _mapping_row_dicts(rows)
        store_rows, chunk_rows = self._load_rows_blocking(execute_direct, row_dicts)
        payloads = self._payloads_by_hash(store_rows, chunk_rows)
        restored = 0
        for row_dict in row_dicts:
            content_hash = str(row_dict[str(self._pointer_column)])
            if content_hash not in payloads:
                continue
            cast("Any", execute_direct)(
                SqlLargeColumnInlineRestoreUpdate(
                    self._table_name,
                    self._value_column,
                    payload=payloads[content_hash],
                    sys_id=row_dict["sys_id"],
                ),
                fetch_mode="none",
            )
            restored += 1
        return restored

    async def _restore_rows_async(
        self: LargeColumnInlineRestoreStep,
        execute_direct_async: Callable[..., Awaitable[object]],
        rows: object,
    ) -> int:
        if not isinstance(rows, Sequence) or isinstance(rows, str | bytes | bytearray):
            msg = f"Large-column restore expected row sequence, got {type(rows).__name__}"
            raise TypeError(msg)
        row_dicts = _mapping_row_dicts(rows)
        store_rows, chunk_rows = await self._load_rows_async(execute_direct_async, row_dicts)
        payloads = self._payloads_by_hash(store_rows, chunk_rows)
        restored = 0
        for row_dict in row_dicts:
            content_hash = str(row_dict[str(self._pointer_column)])
            if content_hash not in payloads:
                continue
            await cast("Any", execute_direct_async)(
                SqlLargeColumnInlineRestoreUpdate(
                    self._table_name,
                    self._value_column,
                    payload=payloads[content_hash],
                    sys_id=row_dict["sys_id"],
                ),
                fetch_mode="none",
            )
            restored += 1
        return restored

    def _load_rows_blocking(
        self: LargeColumnInlineRestoreStep,
        execute_direct: object,
        row_dicts: list[dict[str, object]],
    ) -> tuple[list[Mapping[str, object]], list[Mapping[str, object]]]:
        content_hashes = tuple(ContentHashValue(str(row[str(self._pointer_column)])) for row in row_dicts)
        store_rows = cast(
            "list[Mapping[str, object]]",
            cast("Any", execute_direct)(
                SqlContentStoreSelectManyTemplate(self._store_table_name(), content_hashes),
                fetch_mode="all",
            ),
        )
        chunk_rows = cast(
            "list[Mapping[str, object]]",
            cast("Any", execute_direct)(
                SqlContentChunksSelectManyTemplate(self._store_table_name(), content_hashes),
                fetch_mode="all",
            ),
        )
        return store_rows, chunk_rows

    async def _load_rows_async(
        self: LargeColumnInlineRestoreStep,
        execute_direct_async: Callable[..., Awaitable[object]],
        row_dicts: list[dict[str, object]],
    ) -> tuple[list[Mapping[str, object]], list[Mapping[str, object]]]:
        content_hashes = tuple(ContentHashValue(str(row[str(self._pointer_column)])) for row in row_dicts)
        store_rows = cast(
            "list[Mapping[str, object]]",
            await cast("Any", execute_direct_async)(
                SqlContentStoreSelectManyTemplate(self._store_table_name(), content_hashes),
                fetch_mode="all",
            ),
        )
        chunk_rows = cast(
            "list[Mapping[str, object]]",
            await cast("Any", execute_direct_async)(
                SqlContentChunksSelectManyTemplate(self._store_table_name(), content_hashes),
                fetch_mode="all",
            ),
        )
        return store_rows, chunk_rows

    def _payloads_by_hash(
        self: LargeColumnInlineRestoreStep,
        store_rows: list[Mapping[str, object]],
        chunk_rows: list[Mapping[str, object]],
    ) -> dict[str, object]:
        chunks_by_hash: dict[str, list[dict[str, Any]]] = {}
        for chunk_row in chunk_rows:
            chunk_dict = dict(chunk_row)
            chunks_by_hash.setdefault(str(chunk_dict["content_hash"]), []).append(chunk_dict)
        payloads: dict[str, object] = {}
        for store_row in store_rows:
            store_dict = dict(store_row)
            content_hash = str(store_dict["content_hash"])
            total_chunks = _coerce_int(store_dict["total_chunks"])
            if total_chunks > 0:
                stored_content = _reassemble_chunk_payload(
                    content_hash=content_hash,
                    total_chunks=total_chunks,
                    chunk_rows=chunks_by_hash.get(content_hash, []),
                    compression_algorithm=str(store_dict["compression_algorithm"]),
                )
            else:
                stored_content = _coerce_bytes(store_dict["payload"])
            payloads[content_hash] = _decode_large_column_payload(
                content_hash=content_hash,
                config_content_type=self._content_type,
                is_binary=bool(store_dict["is_binary"]),
                stored_content=stored_content,
                compression_algorithm=str(store_dict["compression_algorithm"]),
                compression_level=_coerce_int(store_dict["compression_level"]),
                original_size=_coerce_int(store_dict["original_size"]),
            )
        return payloads

