@runtime_checkable
class _SupportsRuntimeVectorValidationAsync(Protocol):
    def _validate_runtime_query_vector_dimensions_async(
        self,
        *,
        model_type: type[DatabaseObjectRow],
        index_name: SqlIndexName,
        query_vector: object,
    ) -> Awaitable[None]: ...


def _vector_index_has_schema_pinned_dimensions(
    model_cls: type[DatabaseObjectRow],
    index_name: SqlIndexName,
) -> bool:
    """True when index config or column spec fixes native/target dimensions (no DB needed)."""
    from l5200_vector_index.vector_config import get_vector_config, resolve_vector_column_spec

    config = get_vector_config(model_cls, index_name)
    if config is None:
        return False
    column_spec = resolve_vector_column_spec(model_cls, config)
    if column_spec is not None:
        allowed = {d for d in (column_spec.dimensions, column_spec.target_dimensions) if d is not None}
    else:
        allowed = {d for d in (config.dimensions, config.target_dimensions) if d is not None}
    return bool(allowed)


def _run_runtime_validation_after_static_check(
    candidate_txn: object | None,
    *,
    model_cls: type[object],
    index_name: SqlIndexName,
    query_vector: object,
) -> None:
    from l1000_schema.table_utils import get_table_name
    from l1100_exceptions.exceptions import VectorDimensionMismatchError
    from l5200_vector_index.vector_config import _query_vector_length

    if candidate_txn is None:
        return
    metadata_txn = getattr(candidate_txn, "_base_txn", None)
    if metadata_txn is None and hasattr(candidate_txn, "query"):
        metadata_txn = candidate_txn
    if metadata_txn is None:
        return
    metadata_cache = getattr(metadata_txn, "_embedding_metadata_read_cache", None)
    metadata = None
    if isinstance(metadata_cache, dict):
        metadata = metadata_cache.get((get_table_name(cast(Any, model_cls)), index_name))
    if metadata is None or metadata.dimensions is None:
        return
    actual_dimensions = _query_vector_length(query_vector)
    if actual_dimensions is None or actual_dimensions == metadata.dimensions:
        return
    raise VectorDimensionMismatchError(
        expected_dimensions=metadata.dimensions,
        actual_dimensions=actual_dimensions,
    )


def run_vector_query_runtime_validation_sync(
    txn: object | None,
    model_cls: type[DatabaseObjectRow],
    index_name: SqlIndexName,
    query_vector: object,
) -> None:
    """Validate query vector dimensions (static config + optional runtime metadata)."""
    from l5200_vector_index.vector_config import validate_query_vector_dimensions

    validate_query_vector_dimensions(
        cast(Any, model_cls),
        index_name,
        query_vector,
    )
    if _vector_index_has_schema_pinned_dimensions(model_cls, index_name):
        return
    _run_runtime_validation_after_static_check(
        txn,
        model_cls=model_cls,
        index_name=index_name,
        query_vector=query_vector,
    )


async def run_vector_query_runtime_validation_async(
    txn: object | None,
    model_cls: type[DatabaseObjectRow],
    index_name: SqlIndexName,
    query_vector: object,
) -> None:
    """Async parity for :func:`run_vector_query_runtime_validation_sync`."""
    from l5200_vector_index.vector_config import validate_query_vector_dimensions

    validate_query_vector_dimensions(
        cast(Any, model_cls),
        index_name,
        query_vector,
    )
    if _vector_index_has_schema_pinned_dimensions(model_cls, index_name):
        return
    if isinstance(txn, _SupportsRuntimeVectorValidationAsync):
        await txn._validate_runtime_query_vector_dimensions_async(
            model_type=cast(Any, model_cls),
            index_name=index_name,
            query_vector=query_vector,
        )
        return
    _run_runtime_validation_after_static_check(
        txn,
        model_cls=model_cls,
        index_name=index_name,
        query_vector=query_vector,
    )


def run_vector_query_runtime_validation_for_query_spec(
    txn: object | None,
    model_cls: type[DatabaseObjectRow],
    query_spec: object,
) -> None:
    """Run vector validation when ``query_spec`` carries vector index + query vector."""
    if (inputs := _query_spec_vector_validation_inputs(query_spec)) is not None:
        run_vector_query_runtime_validation_sync(txn, model_cls, *inputs)


def _vector_dimension_validation_post_op() -> CompiledPostOp:
    return CompiledPostOp.materialize(
        ResultMaterializationSpec(
            behavior=PostOpBehavior.EXCEPTION_ONLY,
            assertion_from_row=vector_dimension_validation_assertion_spec(
                message="Vector dimensions do not match configured index dimensions",
            ),
        ),
    )


def _no_result_output_shape() -> CompiledOutputShape:
    return declared_zero_column_output_shape()


def _vector_dimension_validation_output_shape() -> CompiledOutputShape:
    return CompiledOutputShape(
        tuple(
            synthetic_output_field(column, role="vector_dimension_validation")
            for column in ("ok", "expected_dimensions", "actual_dimensions")
        ),
    )


def _vector_dimension_validation_type_hints() -> SqlColumnTypeHints:
    return SqlColumnTypeHints(
        bigint_columns=frozenset({"ok", "expected_dimensions", "actual_dimensions"}),
    )


class VectorQueryRuntimeValidationStep(NonPublishingStep[None]):
    """Validate vector query dimensions at execution time before search results are consumed."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        model_cls: type[DatabaseObjectRow],
        query_spec: object,
    ) -> None:
        super().__init__(ref_id)
        self._model_cls = model_cls
        self._query_spec = query_spec

    @property
    def level(self) -> int:
        return 0

    def step_tags(self) -> frozenset[str]:
        return frozenset({"read", "vector", "validation"})

    def is_read_only(self) -> bool:
        return True

    def tables_read(self) -> frozenset[str]:
        from l1000_schema.table_utils import get_table_name

        return frozenset({get_table_name(self._model_cls)})

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def result_cardinality(self) -> Cardinality:
        return Cardinality.NONE

    def supports_sql_batch_transport(self) -> bool:
        """Transport validation with its dependent search without publishing a CTE binding."""
        return True

    def compile(self, ctx: CompilationContext) -> CompiledStep[None]:
        from impl.common.l2100_sql_grammar.domain.infra.stmt_noop import SqlNoOpStatement

        inputs = _query_spec_vector_validation_inputs(self._query_spec)
        if inputs is None:
            __opa002_grammar_196 = SqlNoOpStatement()
            return CompiledStep(
                output_shape=_no_result_output_shape(),
                result_relation=DeclaredResultRelation.from_output_shape(_no_result_output_shape()),
                column_type_hints=SqlColumnTypeHints(),
                grammar=__opa002_grammar_196,
                needs_returning=False,
                closed_post_op=literal_post_op(None),
            )

        index_name, query_vector = inputs
        run_vector_query_runtime_validation_sync(None, self._model_cls, SqlIndexName(index_name), query_vector)
        if _vector_index_has_schema_pinned_dimensions(self._model_cls, SqlIndexName(index_name)):
            __opa002_grammar_205 = SqlNoOpStatement()
            return CompiledStep(
                output_shape=_no_result_output_shape(),
                result_relation=DeclaredResultRelation.from_output_shape(_no_result_output_shape()),
                column_type_hints=SqlColumnTypeHints(),
                grammar=__opa002_grammar_205,
                needs_returning=False,
                closed_post_op=literal_post_op(None),
            )

        from impl.common.l2050_sql_types.sql_branded_types import SqlAliasName, SqlColumnName, SqlOperatorType, SqlTableName
        from impl.common.l2100_sql_grammar.domain.infra.stmt_conditions import SqlComparisonParam
        from impl.common.l2100_sql_grammar.tree.clauses import SqlFrom, SqlSelectAlias, SqlSelectList, SqlTableAlias, SqlWhereClause
        from impl.common.l2100_sql_grammar.tree.enums import BinaryOp
        from impl.common.l2100_sql_grammar.tree.expr_compound import SqlCase
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlParam
        from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp, SqlIsNull, sql_and, sql_or
        from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
        from impl.common.l2100_sql_grammar.tree.statements import SqlSelect
        from l1000_schema.table_utils import get_table_name
        from l5200_vector_index.vector_config import _query_vector_length
        from l5200_vector_index.embedding_metadata import EmbeddingMetadata

        actual_dimensions = _query_vector_length(query_vector)
        if actual_dimensions is None:
            __opa002_grammar_226 = SqlNoOpStatement()
            return CompiledStep(
                output_shape=_no_result_output_shape(),
                result_relation=DeclaredResultRelation.from_output_shape(_no_result_output_shape()),
                column_type_hints=SqlColumnTypeHints(),
                grammar=__opa002_grammar_226,
                needs_returning=False,
                closed_post_op=literal_post_op(None),
            )
        table_name = get_table_name(self._model_cls)
        metadata_table_name = get_table_name(EmbeddingMetadata)
        expected_dimensions = SqlColumnRef(SqlColumnName("dimensions"))
        actual_dimensions_param = SqlParam(actual_dimensions)
        ok_expr = SqlCase(
            [
                (
                    sql_or(
                        SqlIsNull(expected_dimensions),
                        SqlBinaryOp(expected_dimensions, BinaryOp.EQ, actual_dimensions_param),
                    ),
                    SqlParam(1),
                ),
            ],
            else_=SqlParam(0),
        )
        grammar = SqlSelect(
            select=SqlSelectList(
                [
                    SqlSelectAlias(ok_expr, SqlAliasName("ok")),
                    SqlSelectAlias(expected_dimensions, SqlAliasName("expected_dimensions")),
                    SqlSelectAlias(actual_dimensions_param, SqlAliasName("actual_dimensions")),
                ],
            ),
            from_clause=SqlFrom(SqlTableAlias(SqlTableIdent(SqlTableName(metadata_table_name)))),
            where=SqlWhereClause(
                sql_and(
                    SqlComparisonParam(
                        SqlColumnRef(SqlColumnName("table_name")),
                        SqlOperatorType("="),
                        table_name,
                    ),
                    SqlComparisonParam(
                        SqlColumnRef(SqlColumnName("field_name")),
                        SqlOperatorType("="),
                        index_name,
                    ),
                ),
            ),
        )

        __opa002_grammar_272 = grammar
        output_shape = _vector_dimension_validation_output_shape()
        return CompiledStep(
            output_shape=output_shape,
            result_relation=DeclaredResultRelation.from_output_shape(output_shape),
            column_type_hints=_vector_dimension_validation_type_hints(),
            grammar=__opa002_grammar_272,
            needs_returning=True,
            closed_post_op=_vector_dimension_validation_post_op(),
        )


async def run_vector_query_runtime_validation_for_query_spec_async(
    txn: object | None,
    model_cls: type[DatabaseObjectRow],
    query_spec: object,
) -> None:
    """Async variant of :func:`run_vector_query_runtime_validation_for_query_spec`."""
    if (inputs := _query_spec_vector_validation_inputs(query_spec)) is not None:
        await run_vector_query_runtime_validation_async(txn, model_cls, SqlIndexName(inputs[0]), inputs[1])


def _query_spec_vector_validation_inputs(query_spec: object) -> tuple[SqlIndexName, object] | None:
    """Return vector validation inputs when a query spec carries them."""
    from impl.common.l2060_query_spec.query_spec import search_op_from_query_spec

    search_op = search_op_from_query_spec(query_spec)
    index_name = search_op.vector_index_name
    query_vector = search_op.vector_query_vec
    if index_name is None or query_vector is None:
        return None
    if not isinstance(index_name, str) or not index_name:
        return None
    return SqlIndexName(index_name), query_vector

