from l2070_batching.cardinality import Cardinality
from l2070_batching.compilation import CompiledStep, CompilationContext
from l2070_batching.conditional_step import (
    AssertionTransportContract,
    AssertRaiseCondition,
    AssertStep,
    ConditionPredicate,
    ConditionalBranchRole,
    ConditionalOutputBindings,
    ConditionalSkipGate,
    ConditionalSkipPropagation,
    ConditionalStep,
    NO_CONDITIONAL_SKIP,
    SubPlan,
)
from l2070_batching.payload_state import PlanPayloadState
from l2070_batching.step import CtePublicationContract, NonPublishingStep, ServerPlanStep, StepExecutionRole


class SqlAssertStep(AssertStep):
    """Stop an ordered SQL request before later work when a guard fails."""

    @classmethod
    def from_semantic(cls: type[SqlAssertStep], step: AssertStep) -> SqlAssertStep:
        contract = step.native_assertion_contract()
        assert contract is not None
        return cls.from_contract(contract)

    @classmethod
    def from_contract(cls: type[SqlAssertStep], contract: AssertionTransportContract) -> SqlAssertStep:
        if re.fullmatch(r"[A-Za-z0-9_.:-]{1,100}", str(contract.ref_id)) is None:
            raise ValueError("Native assertion identity must be an unambiguous signal label")
        return cls(
            contract.ref_id,
            predicate_ref=contract.predicate_ref,
            error=contract.error,
            skip_gate=contract.skip_gate,
            raise_condition=contract.raise_condition,
            after_refs=contract.after_refs,
        )

    def native_assertion_contract(self: SqlAssertStep) -> None:
        return None

    def native_assertion_error(self: SqlAssertStep) -> Exception:
        return self._resolved_error()

    def is_runtime_assertion(self: SqlAssertStep) -> bool:
        return False

    def execution_role(self: SqlAssertStep) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def is_executor_owned_runtime_step(self: SqlAssertStep) -> bool:
        return False

    def declares_consumed_rows_reduction(self: SqlAssertStep) -> bool:
        return False

    def emits_sql_for_accounting(self: SqlAssertStep) -> bool:
        return True

    def counts_as_sql_group_for_accounting(self: SqlAssertStep) -> bool:
        return True

    def requires_assertion_statement_transport(self: SqlAssertStep) -> bool:
        return True

    def is_session_gate_exempt(self: SqlAssertStep) -> bool:
        """The predicate producer owns application-session admission."""
        return True

    def compile(self: SqlAssertStep, ctx: CompilationContext) -> CompiledStep[None]:
        from impl.common.l2070_server_plan.steps._auxiliary_ctes import collect_dependency_auxiliary_ctes
        from impl.common.l2070_server_plan.steps._compile_server_ref import lower_scalar_source
        from impl.common.l2100_sql_grammar.domain.infra.stmt_cte_helpers import SqlNativePredicateAssertion, SqlSelectExpressions
        from impl.common.l2100_sql_grammar.domain.versioning.stmt_versioned_upsert import SqlCoalesceExpr
        from impl.common.l2100_sql_grammar.tree.enums import BinaryOp, UnaryOp
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlParam
        from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp, SqlUnaryOp
        from impl.common.l2100_sql_grammar.protocols import SqlRenderable
        from l2070_batching.post_op import literal_post_op

        predicate: SqlRenderable = SqlCoalesceExpr(
            lower_scalar_source(self.predicate_ref, ctx, default_field="__result"),
            SqlParam(False),
        )
        if self._resolved_raise_condition() is AssertRaiseCondition.WHEN_TRUE:
            predicate = SqlUnaryOp(UnaryOp.NOT, predicate)
        if self.skip_if_ref is not None:
            skip = SqlCoalesceExpr(
                lower_scalar_source(self.skip_if_ref, ctx, default_field="__result"),
                SqlParam(False),
            )
            predicate = SqlBinaryOp(skip, BinaryOp.OR, predicate)
        from l2070_batching.compilation import no_result_compiled_artifacts

        output_shape, result_relation, column_type_hints = no_result_compiled_artifacts()
        return CompiledStep(
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
            grammar=SqlNativePredicateAssertion(
                SqlSelectExpressions([(predicate, "value")]),
                message="NERA_ASSERTION:" + str(self.ref_id),
            ),
            closed_post_op=literal_post_op(None),
            auxiliary_ctes=collect_dependency_auxiliary_ctes(ctx, self.dependencies()),
        )


class SqlQueryAssertStep(SqlAssertStep):
    """Native query assertion with a plan-safe typed error descriptor."""

    def __init__(
        self: SqlQueryAssertStep,
        ref_id: ServerPlanRefId,
        *,
        predicate_ref: ConditionPredicate,
        error_cls: type[Exception],
        error_message: str,
        ordering_tables: frozenset[str],
    ) -> None:
        NonPublishingStep.__init__(self, ref_id)
        self._initialize_assertion(
            predicate_ref=predicate_ref,
            skip_gate=NO_CONDITIONAL_SKIP,
            raise_condition=AssertRaiseCondition.WHEN_FALSE,
            after_refs=(),
        )
        self._ordering_tables = ordering_tables
        self._error_cls = error_cls
        self._error_message = error_message

    def native_assertion_error(self: SqlQueryAssertStep) -> Exception:
        return self._error_cls(self._error_message)

    def tables_read(self: SqlQueryAssertStep) -> frozenset[str]:
        """Keep predicate observation ordered through assertion consumption."""
        return self._ordering_tables

    def internal_plan_ref_state(self: SqlQueryAssertStep) -> PlanPayloadState:
        return {
            "ref_id": self.ref_id,
            "predicate_ref": self.predicate_ref,
            "_predicate_ref_id": self._resolved_predicate_ref_id(),
            "_skip_if_ref_id": self._resolved_skip_if_ref_id(),
            "_skip_gate": self._skip_gate,
            "_after_refs": self._after_refs,
            "_ordering_tables": self._ordering_tables,
            "_raise_condition": self._resolved_raise_condition(),
            "_error_message": self._error_message,
        }


@dataclass(frozen=True, slots=True)
class SqlConditionalProgram:
    """The physical branch products and preserved semantic contracts."""

    predicate_ref: ConditionPredicate
    skip_gate: ConditionalSkipGate
    then_steps: tuple[ServerPlanStep[Any], ...]
    else_steps: tuple[ServerPlanStep[Any], ...]
    output_bindings: ConditionalOutputBindings
    skip_propagation: ConditionalSkipPropagation
    branch_role: ConditionalBranchRole
    publication_contract: CtePublicationContract
    same_plan_write_transport: SamePlanWriteTransport = SamePlanWriteTransport.DATA_MODIFYING_CTE
    allow_ordered_output_transport: bool = False


class SqlConditionalStep(ConditionalStep):
    """A terminal SQL conditional produced by backend physical lowering."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        program: SqlConditionalProgram,
    ) -> None:
        self._physical_publication_contract = program.publication_contract
        self._same_plan_write_transport = program.same_plan_write_transport
        self._allow_ordered_output_transport = program.allow_ordered_output_transport
        super().__init__(
            ref_id,
            predicate_ref=program.predicate_ref,
            then_plan=SubPlan(program.then_steps),
            else_plan=SubPlan(program.else_steps),
            output_bindings=program.output_bindings,
            skip_gate=program.skip_gate,
            skip_propagation=program.skip_propagation,
            branch_role=program.branch_role,
            allow_ordered_output_transport=program.allow_ordered_output_transport,
        )

    @classmethod
    def from_semantic[ThenStepsItemT, ElseStepsItemT](
        cls,
        step: ConditionalStep,
        *,
        then_steps: Sequence[ServerPlanStep[ThenStepsItemT]],
        else_steps: Sequence[ServerPlanStep[ElseStepsItemT]],
        same_plan_write_transport: SamePlanWriteTransport = SamePlanWriteTransport.DATA_MODIFYING_CTE,
    ) -> SqlConditionalStep:
        """Create the physical step without weakening semantic contracts."""
        return cls(
            step.ref_id,
            program=SqlConditionalProgram(
                predicate_ref=step.predicate_ref,
                skip_gate=step.skip_gate,
                then_steps=tuple(then_steps),
                else_steps=tuple(else_steps),
                output_bindings=step.output_bindings,
                skip_propagation=step.skip_propagation,
                branch_role=step.branch_role,
                publication_contract=step.cte_publication_contract(),
                same_plan_write_transport=same_plan_write_transport,
                allow_ordered_output_transport=step.allows_ordered_output_transport(),
            ),
        )

    @property
    def level(self: SqlConditionalStep) -> int:
        return 0

    def execution_role(self: SqlConditionalStep) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def result_cardinality(self: SqlConditionalStep) -> Cardinality:
        return Cardinality.ONE if self.output_bindings else Cardinality.NONE

    def cte_publication_contract(self: SqlConditionalStep) -> CtePublicationContract:
        return self._physical_publication_contract

    def always_publishes_executor_visible_binding(self: SqlConditionalStep) -> bool:
        return self.cte_publication_contract().publishes_relation

    def _output_bindings_require_materialization(self: SqlConditionalStep) -> bool:
        children = {
            str(step.ref_id): step
            for step in (*self.then_plan.steps, *self.else_plan.steps)
        }
        for then_ref, else_ref in self.output_bindings.values():
            then_child = children.get(str(then_ref))
            else_child = children.get(str(else_ref))
            if then_child is None or else_child is None:
                return True
            for child in (then_child, else_child):
                if (
                    child._requires_materialized_conditional_output()
                    and not child._is_transport_safe_conditional_default()
                ):
                    return True
        return False

    def supports_ordered_sql_statement_batch(self: SqlConditionalStep) -> bool:
        """Keep safe opted-in outputs in one ordered request.

        See ``docs/design/ORDERED_STATEMENT_COALESCER_ARCHITECTURE.rst`` and
        ``docs/design/NER1689_MARIADB_GRAPH_BOOTSTRAP.rst``.
        """
        if not self.output_bindings:
            return True
        return (
            self._allow_ordered_output_transport
            and self._same_plan_write_transport is SamePlanWriteTransport.ORDERED_STATEMENTS
            and not self._output_bindings_require_materialization()
        )

    def exports_statement_local_relation(self: SqlConditionalStep) -> bool:
        return bool(self.output_bindings)

    def requires_standalone_physical_request(self: SqlConditionalStep) -> bool:
        """Materialize outputs unless ordered transport owns their result frame."""
        return bool(self.output_bindings) and not self.supports_ordered_sql_statement_batch()

    def requires_materialized_inputs(self: SqlConditionalStep) -> bool:
        branch_steps = (*self.then_plan.steps, *self.else_plan.steps)
        branch_refs = frozenset(
            str(ref_id) for step in branch_steps for ref_id in (step.ref_id, *step.additional_batch_binding_ref_ids())
        )
        return any(step.requires_materialized_inputs() and bool(step.dependencies() - branch_refs) for step in branch_steps)

    def supports_sql_batch_transport(self: SqlConditionalStep) -> bool:
        if self.output_bindings:
            return False
        return all(
            child.supports_sql_batch_transport() or self._internal_materializer(child)
            for child in (*self.then_plan.steps, *self.else_plan.steps)
        )

    def _internal_materializer(self: SqlConditionalStep, child: ServerPlanStep[Any]) -> bool:
        """Closed hydration can follow the conditional's complete SQL request."""
        if child.execution_role() is not StepExecutionRole.APPLY or not child.allows_later_sql_transport():
            return False
        produced = {str(step.ref_id) for step in (*self.then_plan.steps, *self.else_plan.steps)}
        return all(dependency.partition(".")[0] in produced for dependency in child.dependencies())

    def requires_prior_step_boundary(self: SqlConditionalStep) -> bool:
        return any(
            child.requires_prior_step_boundary() and not self._internal_materializer(child)
            for child in (*self.then_plan.steps, *self.else_plan.steps)
        )

    def require_sql_physical_conditional(self: SqlConditionalStep) -> None:
        return None

    def compile(self: SqlConditionalStep, ctx: CompilationContext) -> CompiledStep[None]:
        from impl.common.l2070_server_plan.steps._conditional_compile import compile_sql_conditional_step

        return compile_sql_conditional_step(self, ctx)

