def _session_ref_auxiliary_ctes(
    lowered_session_id: object,
    ctx: CompilationContext,
) -> tuple[tuple[str, SqlRenderable], ...] | None:
    """Carry the CTE definition when the session id lowers to another step's publication.

    A session ref published by an earlier executor group is only visible to this
    statement if its definition travels with it.
    """

    from impl.common.l2100_sql_grammar.domain.infra.stmt_dml_simple import SqlCteFieldRef

    if not isinstance(lowered_session_id, SqlCteFieldRef):
        return None
    cte_name = str(object.__getattribute__(lowered_session_id, "_cte_name"))
    binding = ctx.cte_refs.get(cte_name)
    if binding is None or binding.auxiliary_query is None:
        return None
    return ((cte_name, binding.auxiliary_query),)


class SessionUserIdStep(MaybeSqlRelationPublisherStep[UserId | None]):
    """Resolve ``session_id`` to ``user_id`` via ``sys_sessions``.

    Emits ``SELECT user_id FROM sys_sessions WHERE sys_id = ? LIMIT 1``.
    Downstream steps consume this via ``ResolvedRefs`` in ``preprocess()``.

    The session arrives either as a reference to a value another step produced or
    as the query that finds it, and the difference shows up in three methods
    rather than one: ``compile`` lowers it differently, ``dependencies`` has
    nothing to wait for in the second case, and ``tables_read`` has to include
    what the inlined query reads. Missing any of the three is a scheduling bug
    rather than a compile error -- an under-declared read can be ordered before a
    write to the same table -- so they are kept next to each other below.

    ``session_validation_ref`` changes where the column comes from, not what it
    is. When the flush validates the session, the preamble has already selected
    the whole row -- ``user_id`` included -- so this step projects that relation
    instead of asking ``sys_sessions`` for a column it just read (NER-879). The
    ref is supplied by ``SessionValidationOptimizer``, which is the only place
    that knows whether this flush emits validation; a step cannot decide it for
    itself, because naming a relation a later flush does not publish is a SQL
    error rather than a missed optimisation.
    """

    def __init__(
        self: SessionUserIdStep,
        ref_id: ServerPlanRefId,
        session_id: ScalarServerRef[SessionId] | LazySessionSqlSource,
        *,
        after_refs: frozenset[ServerPlanRefId] = frozenset(),
        session_validation_ref: ServerPlanRefId | None = None,
        bound_principal: bool = False,
    ) -> None:
        super().__init__(ref_id)
        self._session_id = session_id
        self._after_refs = after_refs
        self._session_validation_ref = session_validation_ref
        self._bound_principal = bound_principal

    def reading_the_validated_row(
        self: SessionUserIdStep,
        session_validation_ref: ServerPlanRefId,
    ) -> SessionUserIdStep:
        """This same step, sourced from the validated row rather than the table.

        A copy rather than a mutation because plan steps are treated as immutable
        once built, and a copy under the same ``ref_id`` is substitutable for the
        original: it publishes the same column, with the same contract, to the
        same consumers.
        """
        return SessionUserIdStep(
            self.ref_id,
            self._session_id,
            after_refs=self._after_refs,
            session_validation_ref=session_validation_ref,
        )

    def _reading_bound_principal(self: SessionUserIdStep) -> SessionUserIdStep:
        """Read the transaction-local principal after initialization."""
        return SessionUserIdStep(
            self.ref_id,
            self._session_id,
            after_refs=self._after_refs,
            bound_principal=True,
        )

    def _binding_transaction_principal(
        self: SessionUserIdStep,
        session_validation_ref: ServerPlanRefId,
    ) -> SessionUserIdStep:
        """Read principal state rather than a cross-statement validation CTE."""
        del session_validation_ref
        return self._reading_bound_principal()

    @property
    def level(self: SessionUserIdStep) -> int:
        return 0

    def result_cardinality(self: SessionUserIdStep) -> Cardinality:
        return Cardinality.ONE

    def declares_consumed_rows_reduction(self: SessionUserIdStep) -> bool:
        return True

    def is_read_only(self: SessionUserIdStep) -> bool:
        return True

    def tables_read(self: SessionUserIdStep) -> frozenset[str]:
        source = session_sql_source_or_none(self._session_id)
        if source is not None:
            return frozenset({"sys_sessions"}) | source.tables_read()
        return frozenset({"sys_sessions"})

    def tables_written(self: SessionUserIdStep) -> frozenset[str]:
        return frozenset()

    def step_tags(self: SessionUserIdStep) -> frozenset[str]:
        return frozenset({"read", "scalar", "resolve", "session"})

    def dependencies(self: SessionUserIdStep) -> frozenset[str]:
        after = frozenset(str(ref) for ref in self._after_refs)
        if self._session_validation_ref is not None:
            # The validated relation is added to, not substituted for, whatever
            # the identifier depended on. Compile no longer reads the identifier,
            # but the step that publishes it is still in the plan and dropping the
            # edge would leave its publication with no declared consumer.
            return after | {str(self._session_validation_ref)} | self._identifier_dependencies()
        return self._identifier_dependencies() | after

    def _identifier_dependencies(self: SessionUserIdStep) -> frozenset[str]:
        if self._bound_principal:
            return frozenset()
        if is_lazy_session_source(self._session_id):
            # No dependency on the resolver: it is not a step in this plan, its
            # query travels inside this statement, and declaring a dependency on
            # a ref nothing publishes is rejected by the publication liveness
            # checker rather than merely ignored.
            return frozenset()
        return self._session_id.dependencies()

    def sql_visible_dependencies(self: SessionUserIdStep) -> frozenset[str]:
        return self._identifier_dependencies()

    def always_publishes_executor_visible_binding(self: SessionUserIdStep) -> bool:
        """Keep the scalar available to later SQL permission lookups."""
        return True

    def requires_prior_step_boundary(self: SessionUserIdStep) -> bool:
        return bool(self._after_refs)

    def supports_sql_batch_transport(self: SessionUserIdStep) -> bool:
        return True

    def supports_ordered_sql_statement_batch(self: SessionUserIdStep) -> bool:
        return True

    def cte_publication_contract(self: SessionUserIdStep) -> CtePublicationContract:
        columns = ("user_id",)
        column_type_hints = SqlColumnTypeHints(uuid_columns=frozenset({"user_id"}))
        if columns is None:
            if column_type_hints is not None and column_type_hints.has_any():
                msg = f"{type(self).__name__} declares SQL column type hints without an explicit cte_output_columns() contract."
                raise TypeError(msg)
            return CtePublicationContract.non_publishing()
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        _contract_model_cls = _SessionUserIdStepCteRow
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=tuple(str(column) for column in columns),
            column_type_hints=column_type_hints,
            model_cls=_contract_model_cls,
            relation_role=self.cte_relation_role(),
            optional_columns=frozenset({"user_id"}),
            source_tables=_contract_source_tables,
        )

    def compile(self: SessionUserIdStep, ctx: CompilationContext) -> CompiledStep[UserId | None]:
        from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName, SqlTableName
        from impl.common.l2070_server_plan.steps._compile_server_ref import lower_scalar_server_ref
        from impl.common.l2100_sql_grammar.domain.query.stmt_dynamic import SqlDynamicSelectStmt
        from impl.common.l2100_sql_grammar.tree.enums import BinaryOp
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef
        from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp

        from impl.common.l2070_server_plan.steps.session_validation import (
            auxiliary_ctes_for_validated_row,
            build_session_projection_from_validated_row,
            validated_session_relation,
        )

        grammar: SqlRenderable
        auxiliary_ctes: list[tuple[str, object]] | None = None
        validated = validated_session_relation(ctx, self._session_validation_ref)
        if (
            self._bound_principal
            and ctx.backend_profile.traits.session_context_transport is SessionContextTransport.SESSION_VARIABLES
        ):
            from impl.common.l2100_sql_grammar.domain.infra.stmt_cte_helpers import (
                SqlSelectExpressions,
            )
            from impl.common.l2100_sql_grammar.domain.infra.stmt_session_context import (
                SqlMysqlBoundUserId,
            )

            grammar = SqlSelectExpressions([(SqlMysqlBoundUserId(), "user_id")])
        elif validated is not None:
            grammar = build_session_projection_from_validated_row(validated, (SqlColumnName("user_id"),))
            auxiliary_ctes = auxiliary_ctes_for_validated_row(validated)
        else:
            session_rhs: SqlRenderable
            if self._bound_principal:
                from impl.common.l2100_sql_grammar.domain.triggers._expressions_trigger import (
                    SqlTriggerSessionId,
                )

                session_rhs = SqlTriggerSessionId()
            else:
                session_rhs = (
                    self._session_id.session_id_expression(ctx)
                    if is_lazy_session_source(self._session_id)
                    else lower_scalar_server_ref(self._session_id, ctx)
                )
            auxiliary_ctes = list(
                _session_ref_auxiliary_ctes(session_rhs, ctx) or (),
            )
            where_cond = SqlBinaryOp(
                SqlColumnRef(SqlColumnName("sys_id")),
                BinaryOp.EQ,
                session_rhs,
            )
            grammar = SqlDynamicSelectStmt(
                from_table=SqlTableName("sys_sessions"),
                columns=(SqlColumnName("user_id"),),
                where_conditions=[where_cond],
                limit=1,
            )

        __opa002_grammar_108 = grammar
        output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(
            self.cte_publication_contract(),
        )
        return CompiledStep(
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
            grammar=__opa002_grammar_108,
            needs_returning=True,
            auxiliary_ctes=auxiliary_ctes,
            closed_post_op=scalar_column_post_op(
                "user_id",
                use_default_on_empty=True,
                scalar_coercion=ScalarCoercionKind.USER_ID,
            ),
        )

