    def compile(self: GrammarRowStep, ctx: CompilationContext) -> CompiledStep[T | None]:
        """Compile this step to a CompiledStep for SQL backends."""

        if self._result_mode is GrammarRowResultMode.HYDRATE_ONE and self._model_cls is None:
            msg = "GrammarRowResultMode.HYDRATE_ONE requires model_cls"
