def _delete_count_post_op() -> CompiledPostOp:
    return scalar_column_post_op(
        "count",
        default_value=0,
        use_default_on_empty=True,
        scalar_coercion=ScalarCoercionKind.INT,
    )


def _delete_count_relation(delete_stmt: Any, *, cte_name: SqlCteName) -> Any:
    from impl.common.l2050_sql_types.sql_branded_types import SqlAliasName, SqlTableName
    from impl.common.l2100_sql_grammar.domain.versioning.stmt_cte import SqlDmlWithReturningOne
    from impl.common.l2100_sql_grammar.tree.clauses import SqlSelectList
    from impl.common.l2100_sql_grammar.tree.enums import AggregateKind
    from impl.common.l2100_sql_grammar.tree.expr_compound import SqlAggregate
    from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
    from impl.common.l2100_sql_grammar.tree.statements import SqlCte, SqlSelect
    from impl.common.l2100_sql_grammar.tree.clauses import SqlSelectAlias

    count_select = SqlSelect(
        select=SqlSelectList(
            [
                SqlSelectAlias(
                    SqlAggregate(AggregateKind.COUNT_STAR),
                    alias=SqlAliasName("count"),
                )
            ]
        ),
        from_=SqlTableIdent(SqlTableName(cte_name)),
    )
    return SqlCte(
        [(cte_name, SqlDmlWithReturningOne(delete_stmt))],
        count_select,
    )


def _delete_count_batch(
    table_name: SqlTableName,
    delete_stmt: Any,
    where_clause: Any,
    params: tuple[object, ...],
    *,
    statement_local_ctes: tuple[tuple[str | ServerPlanRefId, Any], ...] = (),
) -> Any:
    from impl.common.l2050_sql_types.sql_branded_types import SqlAliasName, SqlTableName
    from impl.common.l2100_sql_grammar.domain.infra.stmt_compound_write import (
        SqlStatementBatch,
        SqlStatementBatchCategory,
    )
    from impl.common.l2100_sql_grammar.tree.clauses import SqlSelectAlias, SqlSelectList
    from impl.common.l2100_sql_grammar.tree.enums import AggregateKind
    from impl.common.l2100_sql_grammar.tree.expr_compound import SqlAggregate
    from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
    from impl.common.l2100_sql_grammar.tree.statements import SqlSelect, SqlStatementLocalWith

    count_select = SqlSelect(
        select=SqlSelectList(
            [
                SqlSelectAlias(
                    SqlAggregate(AggregateKind.COUNT_STAR),
                    alias=SqlAliasName("count"),
                ),
            ],
        ),
        from_=SqlTableIdent(SqlTableName(table_name)),
        where=where_clause,
    )
    statements = [count_select, delete_stmt]
    if statement_local_ctes:
        statements = [SqlStatementLocalWith(statement_local_ctes, statement, recursive=True) for statement in statements]
    return SqlStatementBatch(
        statements,
        category=SqlStatementBatchCategory.ORDERED_SEMANTIC,
        params_per_stmt=[params, params],
        external_params_first=[True, True],
        needs_returning_per_stmt=[True, False],
        collect_results_per_stmt=[True, False],
    )


@dataclass(frozen=True, slots=True)
class _DeleteManyConfig:
    after_refs: frozenset[ServerPlanRefId] = frozenset()
    user_id_ref_id: ServerPlanRefId | None = None


class _DeleteManyStepCteRow(BaseModel):
    count: int


class DeleteManyStep[T](SqlRelationPublisherStep[int]):
    """Step for deleting multiple model instances by sys_id list.

    Compiles to a SQL delete and returns the SQL-visible deleted-row count.
    Returns the count of deleted rows.
    """

    def __init__[SysIdsItemT](
        self: DeleteManyStep,
        ref_id: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        sys_ids: list[SysIdsItemT],
        *,
        config: _DeleteManyConfig | None = None,
    ) -> None:
        super().__init__(ref_id)
        resolved_config = config or _DeleteManyConfig()
        self._model_cls = model_cls
        self._sys_ids = sys_ids
        self._after_refs = resolved_config.after_refs
        self._user_id_ref_id = resolved_config.user_id_ref_id

    @property
    def level(self: DeleteManyStep) -> int:
        return 0

    def step_tags(self: DeleteManyStep) -> frozenset[str]:
        return frozenset({"write", "delete", "bulk"})

    def is_read_only(self: DeleteManyStep) -> bool:
        return False

    def cte_relation_role(self: DeleteManyStep) -> str | None:
        return "count_only"

    def cte_publication_contract(self: DeleteManyStep) -> CtePublicationContract:
        columns = ("count",)
        column_type_hints = SqlColumnTypeHints(bigint_columns=frozenset({"count"}))
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        _contract_model_cls = _DeleteManyStepCteRow
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=tuple(str(column) for column in columns),
            column_type_hints=column_type_hints,
            model_cls=_contract_model_cls,
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def has_unbounded_params(self: DeleteManyStep) -> bool:
        return len(self._sys_ids) > _UNBOUNDED_PARAM_ROW_THRESHOLD

    def supports_sql_batch_transport(self: DeleteManyStep) -> bool:
        return not self.has_unbounded_params()

    def estimated_param_count(self: DeleteManyStep) -> int | None:
        return len(self._sys_ids)

    def result_cardinality(self: DeleteManyStep) -> Cardinality:
        return Cardinality.SCALAR

    def tables_read(self: DeleteManyStep) -> frozenset[str]:
        """Delete does not read any tables."""
        return frozenset()

    def tables_written(self: DeleteManyStep) -> frozenset[str]:
        from l1000_schema.table_utils import get_table_name

        return frozenset({get_table_name(self._model_cls)})

    def dependencies(self: DeleteManyStep) -> frozenset[str]:
        deps = {str(ref_id) for ref_id in self._after_refs}
        if self._user_id_ref_id is not None:
            deps.add(str(self._user_id_ref_id))
        return frozenset(deps)

    def preprocess(self: DeleteManyStep, resolved: ResolvedRefs) -> None:
        pass

    def compile(self: DeleteManyStep, ctx: CompilationContext) -> CompiledStep[int]:
        """Compile DELETE WHERE sys_id IN (?, ...) with SQL count projection."""
        from impl.common.l2070_server_plan.steps._query_helper_compile import (
            compile_delete_many_grammar,
        )
        from l1000_schema.table_utils import get_table_name

        resolved_user_id = resolved_permission_user_id_from_ref(self._user_id_ref_id, ctx)
        use_returning_relation = ctx.supports_data_modifying_ctes
        compiled_grammar, params = compile_delete_many_grammar(
            self._model_cls,
            self._sys_ids,
            ctx,
            returning=use_returning_relation,
            returning_columns=("sys_id",),
            resolved_user_id=resolved_user_id,
            user_id_ref_id=self._user_id_ref_id,
        )
        grammar: SqlRenderable = compiled_grammar
        compiled_params: tuple[Any, ...] | None = params
        auxiliary_ctes: list[tuple[str, Any]] | None = None
        from l2070_batching.compilation import CteReference

        if isinstance(resolved_user_id, CteReference) and resolved_user_id.auxiliary_query is not None:
            auxiliary_ctes = [(resolved_user_id.ref_id, resolved_user_id.auxiliary_query)]
        if use_returning_relation:
            grammar = _delete_count_relation(grammar, cte_name=SqlCteName(f"{self.ref_id}_deleted"))
            compiled_params = params
        else:
            if self.has_unbounded_params():
                from impl.common.l2100_sql_grammar.domain.infra.stmt_compound_write import (
                    SqlStatementBatch,
                    SqlStatementBatchCategory,
                )

                chunk_batches: list[Any] = []
                for start in range(0, len(self._sys_ids), _UNBOUNDED_PARAM_ROW_THRESHOLD):
                    chunk_grammar, chunk_params = compile_delete_many_grammar(
                        self._model_cls,
                        self._sys_ids[start : start + _UNBOUNDED_PARAM_ROW_THRESHOLD],
                        ctx,
                        returning=False,
                        returning_columns=("sys_id",),
                        resolved_user_id=resolved_user_id,
                        user_id_ref_id=self._user_id_ref_id,
                    )
                    chunk_batches.append(
                        _delete_count_batch(
                            get_table_name(self._model_cls),
                            chunk_grammar,
                            getattr(chunk_grammar, "_where", None),
                            chunk_params,
                        ),
                    )
                grammar = SqlStatementBatch(
                    chunk_batches,
                    category=SqlStatementBatchCategory.BUDGET_SPLIT,
                )
            else:
                grammar = _delete_count_batch(
                    get_table_name(self._model_cls),
                    grammar,
                    getattr(grammar, "_where", None),
                    params,
                )
            compiled_params = None

        __opa002_grammar_245 = grammar
        output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(
            self.cte_publication_contract(),
        )
        return CompiledStep(
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
            grammar=__opa002_grammar_245,
            params=compiled_params,
            external_params_first=True,
            needs_returning=use_returning_relation,
            auxiliary_ctes=auxiliary_ctes,
            closed_post_op=_delete_count_post_op(),
        )


