def _hydrate_session_lookup_row(raw_result: RawResult) -> SessionLookupRow | None:
    """Convert the raw session lookup row into Python values."""
    from impl.common.l2070_server_plan.steps.session_validation import (
        _coerce_validated_user_id,
        convert_session_row_db_to_python,
    )

    if not raw_result:
        return None
    first = raw_result[0]
    row = dict(first)
    from impl.common.l2070_server_plan.steps.session_validation import _session_lookup_columns

    required_columns = {str(column) for column in _session_lookup_columns()}
    missing_columns = sorted(required_columns - row.keys())
    if missing_columns:
        from l1100_exceptions.exceptions import ProgrammingError

        raise ProgrammingError(
            "session lookup row missing SQL columns: " + ", ".join(missing_columns),
        )
    converted: dict[str, Any] = convert_session_row_db_to_python(row)
    for key in ("sys_id", "session_type", "user_id", "effective_user_id", "sys_closed_at", "expires_at"):
        if key in row and key not in converted:
            converted[key] = row[key]
    converted["user_id"] = _coerce_validated_user_id(converted.get("user_id"))
    converted["effective_user_id"] = _coerce_validated_user_id(converted.get("effective_user_id"))
    return cast("SessionLookupRow", converted)


class LookupSessionContextStep(SqlRelationPublisherStep[SessionLookupRow | None]):
    """Load the canonical session row for semantic context resolution."""

    def cte_publication_contract(self: LookupSessionContextStep) -> CtePublicationContract:
        from impl.common.l2070_server_plan.steps.session_validation import _session_lookup_columns
        from l1300_session.session import UserSession
        from l2070_batching.sql_column_type_hints import model_sql_column_type_hints

        columns = tuple(str(column) for column in _session_lookup_columns())
        column_type_hints = model_sql_column_type_hints(UserSession, columns)
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        contract_columns = tuple(str(column) for column in columns)
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=contract_columns,
            column_type_hints=column_type_hints,
            relation_contract=CteRelationContract.semantic_row(SessionLookupRow),
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def __init__(
        self: LookupSessionContextStep,
        ref_id: ServerPlanRefId,
        *,
        session_id: ScalarServerRef[SessionId] | LazySessionSqlSource,
        session_validation_ref: ServerPlanRefId | None = None,
    ) -> None:
        """A reference to the session, or the query that identifies it.

        The second arrives from a plan opened by ``authenticated_session_lazy``.
        Both end up on the right of ``sys_id = ...`` below; they differ in that a
        reference names a CTE column published by an earlier statement, while the
        query is inlined into this one, which is what keeps the plan to a single
        round trip.

        ``session_validation_ref`` makes both moot when this flush validates the
        session: the row this step wants is the row validation selected, and the
        columns are the same list, so it projects that relation instead of
        reading ``sys_sessions`` a second time (NER-879). A write path lowers two
        of these steps -- one per permission check -- so on that path the ref is
        the difference between three reads of the session row and one.
        """
        super().__init__(ref_id)
        self._session_id = session_id
        self._session_validation_ref = session_validation_ref

    def reading_the_validated_row(
        self: LookupSessionContextStep,
        session_validation_ref: ServerPlanRefId,
    ) -> LookupSessionContextStep:
        """This same step, sourced from the validated row rather than the table.

        Substitutable for the original under the same ``ref_id``: same columns,
        same publication contract, same post-op, so consumers cannot tell which
        of the two they were given.
        """
        return LookupSessionContextStep(
            self.ref_id,
            session_id=self._session_id,
            session_validation_ref=session_validation_ref,
        )

    @property
    def level(self: LookupSessionContextStep) -> int:
        return 0

    def result_cardinality(self: LookupSessionContextStep) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self: LookupSessionContextStep) -> bool:
        return True

    def execution_role(self: LookupSessionContextStep) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def step_tags(self: LookupSessionContextStep) -> frozenset[str]:
        return frozenset({"session_context_resolution", "grammar", "read"})

    def is_session_context_resolution(self: LookupSessionContextStep) -> bool:
        return True

    def tables_read(self: LookupSessionContextStep) -> frozenset[str]:
        if is_lazy_session_source(self._session_id):
            # The resolver's relation is read by this statement too, since its
            # query is inlined here, and the scheduler needs to know that.
            return frozenset({"sys_sessions"}) | self._session_id.tables_read()
        return frozenset({"sys_sessions"})

    def tables_written(self: LookupSessionContextStep) -> frozenset[str]:
        return frozenset()

    def dependencies(self: LookupSessionContextStep) -> frozenset[str]:
        identifier = self._identifier_dependencies()
        if self._session_validation_ref is not None:
            # Added to rather than substituted for the identifier's dependency:
            # compile stops reading the identifier, but the step publishing it is
            # still in the plan and its publication needs a declared consumer.
            return identifier | {str(self._session_validation_ref)}
        return identifier

    def _identifier_dependencies(self: LookupSessionContextStep) -> frozenset[str]:
        if is_lazy_session_source(self._session_id):
            # Nothing to wait for: the resolver is not a step in this plan, so a
            # dependency on it would name a ref no step publishes, which the
            # publication liveness checker rejects outright.
            return frozenset()
        return self._session_id.dependencies()

    def counts_as_sql_group_for_accounting(self: LookupSessionContextStep) -> bool | None:
        return False

    def compile(self: LookupSessionContextStep, ctx: CompilationContext) -> CompiledStep[SessionLookupRow | None]:
        from impl.common.l2070_server_plan.steps._compile_server_ref import lower_scalar_server_ref
        from impl.common.l2070_server_plan.steps.session_validation import (
            _session_lookup_columns,
            auxiliary_ctes_for_validated_row,
            build_session_lookup_stmt,
            build_session_projection_from_validated_row,
            validated_session_relation,
        )

        auxiliary_ctes: list[tuple[str, object]] | None = None
        validated = validated_session_relation(ctx, self._session_validation_ref)
        if validated is not None:
            # The privilege predicate below is not lost by taking this branch:
            # the relation being projected is the output of the same lookup, built
            # by the same builder, with ``require_authenticated_row`` already
            # applied for a resolved session. Re-applying it here would be
            # filtering rows that were already filtered.
            grammar = build_session_projection_from_validated_row(validated, _session_lookup_columns())
            auxiliary_ctes = auxiliary_ctes_for_validated_row(validated)
        # A resolved session must additionally be a user session that names a
        # user: the caller chooses which row the resolver returns, so the refusal
        # of a privileged row has to travel in the same statement as the lookup.
        # See ``build_session_lookup_stmt`` for why a concrete session needs no
        # such predicate.
        elif is_lazy_session_source(self._session_id):
            grammar = build_session_lookup_stmt(
                self._session_id.session_id_expression(ctx),
                require_authenticated_row=True,
            )
        else:
            grammar = build_session_lookup_stmt(lower_scalar_server_ref(self._session_id, ctx))

        __opa002_grammar_109 = grammar
        output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(
            self.cte_publication_contract(),
        )
        return CompiledStep(
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
            grammar=__opa002_grammar_109,
            needs_returning=True,
            auxiliary_ctes=auxiliary_ctes,
            closed_post_op=session_lookup_row_post_op(),
        )


class ResolveSessionContextIntent(IntentStep[SessionLookupRow | None]):
    """Resolve session lookup state as one semantic lazy result."""

    intent_tags = frozenset({"session_context_resolve", "intent"})
    intent_read_only = True

    def __init__(
        self: ResolveSessionContextIntent,
        ref_id: ServerPlanRefId,
        *,
        session_id: ScalarServerRef[SessionId],
    ) -> None:
        super().__init__(ref_id)
        self._session_id = session_id

    def lower(self: ResolveSessionContextIntent, ctx: LoweringContext) -> Sequence[ServerPlanStep[Any]]:
        del ctx
        return [LookupSessionContextStep(self.ref_id, session_id=self._session_id)]


class ResolveLazySessionContextIntent(IntentStep[SessionLookupRow | None]):
    """Resolve the authenticated-session SQL source owned by lowering context."""

    intent_tags = frozenset({"session_context_resolve", "intent"})
    intent_read_only = True

    def lower(
        self: ResolveLazySessionContextIntent,
        ctx: LoweringContext,
    ) -> Sequence[ServerPlanStep[Any]]:
        source = session_sql_source_or_none(ctx.session_id)
        assert source is not None, "Lazy session context resolution requires LazySessionSqlSource"
        return [LookupSessionContextStep(self.ref_id, session_id=source)]

