            embedding=serialize_embedding([float(i + 1), 1.0, 0.0, 0.0]),
            embedding_precision=EmbeddingPrecision.FLOAT32,
        )
        for i in range(start, start + count)
    ]


def _refs(vectors: Sequence[USearchEmbeddingVectorRow]) -> list[USearchContentHash]:
    return [
        USearchContentHash(
            content_hash_short=row.content_hash_short,
            content_hash_high=row.content_hash_high,
        )
        for row in vectors
    ]


def _initial(count: int) -> tuple[USearchIndexBlobBase, USearchVectorIndex]:
    vectors = _vectors(count)
    return _step()._build_instance(_refs(vectors), vectors)


@pytest.mark.parametrize("ancestor_count", [32, 256, 1024])
@pytest.mark.parametrize("warm", [False, True])
def test_single_append_serializes_only_the_new_run(ancestor_count: int, warm: bool) -> None:
    """One appended vector must not serialize all retained vectors."""
    prior, index = _initial(ancestor_count)
    members = _usearch_artifact_member_rows(prior, index)
    delta = _vectors(1, start=ancestor_count)
    independent, _ = _step()._build_instance(_refs(delta), delta)
    step = _step()
    if warm:
        _publish_cached_usearch_index(step._target, prior, index)
    result, _ = step._build_instance(
        _refs(delta), delta, prior, existing_members=members,
    )
    # Allow bounded envelope and publication metadata, not ancestor-sized payloads.
    assert len(result.index_blob) <= len(independent.index_blob) + 4096
    assert prior.blob_sha256 == sha256(prior.index_blob).hexdigest()


def test_append_does_not_restore_ancestor_payload(monkeypatch: pytest.MonkeyPatch) -> None:
    """Cold-cache append needs metadata, not an ancestor native index."""
    from impl.common.l2070_server_plan import intent_vector_index_maintenance as maintenance

    prior, index = _initial(32)
    members = _usearch_artifact_member_rows(prior, index)
    restored_bytes: list[int] = []
    original = maintenance._usearch_index_from_blob_instance

    def observe(
        *, target: _EmbeddingWriteTarget, config: VectorIndexConfig, instance: object,
    ) -> USearchVectorIndex:
        restored_bytes.append(len(prior.index_blob))
        return original(target=target, config=config, instance=instance)

    monkeypatch.setattr(maintenance, "_usearch_index_from_blob_instance", observe)
    delta = _vectors(1, start=32)
