    assert sum(restored_bytes) == 0


@pytest.mark.parametrize("changed_identity", [False, True])
def test_initial_run_rejects_conflicting_content_rows(changed_identity: bool) -> None:
    original = _vectors(1)[0]
    conflict = original.model_copy(update={
