@pytest.mark.parametrize("changed_identity", [False, True])
def test_same_content_identity_cannot_change_its_vector(changed_identity: bool) -> None:
    """A canonical content collision must not replace an immutable coordinate."""
    vector = _vectors(1)[0]
    prior, index = _step()._build_instance(_refs([vector]), [vector])
    members = _usearch_artifact_member_rows(prior, index)
    changed = vector.model_copy(update={
