@pytest.mark.parametrize("fault", [
    "missing", "extra", "count", "digest", "version", "dimensions", "truncated",
])
def test_invalid_legacy_authority_cannot_be_published_as_a_run(fault: str) -> None:
    """Migration must validate payload and complete membership together."""
    prior, index = _initial(3)
    prior.storage_format = "legacy-blob-v1"
    members = _usearch_artifact_member_rows(prior, index)
    if fault == "missing":
        members = members[:-1]
    elif fault == "extra":
        members = (*members, members[0].model_copy(update={
            "native_key": 19, "embedding_vector_id": EmbeddingVectorId.new(),
        }))
        prior.next_native_key = 20
    elif fault == "count":
        prior.num_nodes += 1
    elif fault == "digest":
        prior.blob_sha256 = "0" * 64
    elif fault == "version":
        prior.usearch_version = "999.0.0"
    elif fault == "dimensions":
        prior.dimensionality = 8
    else:
        prior.index_blob = prior.index_blob[:7]
        prior.blob_sha256 = sha256(prior.index_blob).hexdigest()
    before = prior.model_dump()
    delta = _vectors(1, start=50)
    with pytest.raises((NativeSearchIntegrityError, ValueError)):
        _step()._build_instance(_refs(delta), delta, prior, existing_members=members)
    assert prior.model_dump() == before


