    assert result.next_native_key == prior.next_native_key


def test_legacy_migration_preserves_noncontiguous_keys_and_high_water_mark() -> None:
    vectors = _vectors(3)
    prior, index = _step()._build_instance(_refs(vectors), vectors)
    prior.storage_format = "legacy-blob-v1"
    assert index._index is not None
    expected = {str(row.embedding_vector_id): key for row, key in zip(vectors, (7, 42, 99))}
    for identity, old_key in tuple(index._id_to_key.items()):
        index._index.rename(old_key, expected[identity])
    index._id_to_key = dict(expected)
    index._key_to_id = {key: identity for identity, key in expected.items()}
    index._next_key = 150
    payload = bytes(index._index.save())
    prior.index_blob = len(payload).to_bytes(8, "little") + payload
    prior.blob_sha256 = sha256(prior.index_blob).hexdigest()
    prior.next_native_key = 150
    members = _usearch_artifact_member_rows(prior, index)
    delta = _vectors(1, start=200)
    result, loaded = _step()._build_instance(
        _refs(delta), delta, prior, existing_members=members,
    )
    for identity, key in expected.items():
        assert loaded._id_to_key[identity] == key
    assert loaded._id_to_key[str(delta[0].embedding_vector_id)] == 150
    assert result.next_native_key == 151
    assert result.sys_id == prior.sys_id


@pytest.mark.parametrize("changed_payload", [False, True])
def test_legacy_members_without_digests_require_verified_vector_migration(changed_payload: bool) -> None:
    from l5200_vector_index.usearch_runs import prepare_usearch_run

    vectors = _vectors(2)
    prior, index = _step()._build_instance(_refs(vectors), vectors)
    prior.storage_format = "legacy-blob-v1"
    legacy_members = tuple(member.model_copy(update={
        "content_hash_short": None, "content_hash_high": None, "embedding_sha256": "",
    }) for member in _usearch_artifact_member_rows(prior, index))
    expected_keys = dict(index._id_to_key)
    step = _step()
    step._membership_mode = USearchMembershipMode.COMPLETE
    supplied = list(vectors)
    if changed_payload:
        supplied[0] = vectors[0].model_copy(update={
            "embedding": serialize_embedding([0.0, 0.0, 1.0, 0.0]),
        })
        with pytest.raises(NativeSearchIntegrityError):
            step._build_instance(_refs(supplied), supplied, prior, existing_members=legacy_members)
        return
    result, restored = step._build_instance(_refs(supplied), supplied, prior, existing_members=legacy_members)
    run, members = prepare_usearch_run(result, _usearch_artifact_member_rows(result, restored))
    assert restored._id_to_key == expected_keys
    assert run.member_count == 2
    assert {member.embedding_sha256 for member in members} == {sha256(row.embedding).hexdigest() for row in vectors}

