            payload = resolved.get(f"{self._source_ref}.payload_materialized")
        if payload is None:
            return []
        if isinstance(payload, SearchPayload):
            rows = list(payload.results)
            meta = list(payload.meta)
        elif isinstance(payload, tuple) and len(payload) == 2:
            rows, meta = cast("tuple[list[object], list[SearchMeta]]", payload)
        elif payload is None:
            rows = []
            meta = []
        else:
            rows = cast("list[object]", payload)
            meta = []
        legacy_rows: FtsLegacySearchRows = []
        total = len(rows)
        for index, row in enumerate(rows):
            if isinstance(row, DatabaseObjectRow):
                row_dict = row.model_dump(mode="python")
            else:
                row_dict = dict(cast("dict[str, object]", row))
            fts_meta = meta[index] if index < len(meta) else None
            rank = getattr(fts_meta, "fts_rank", None)
            if rank is None:
                rank = row_dict.get("_fts_rank", row_dict.get("__fts_rank", float(total - index)))
            row_dict["_fts_rank"] = rank
            legacy_rows.append(row_dict)
        return legacy_rows


@dataclass(frozen=True, slots=True)
class _FtsKeysetPageConfig:
    source_ref: ServerPlanRefId
    limit: FtsKeysetLimit
    after: tuple[float, object] | None


class FtsKeysetPageStep(NonPublishingStep[KeysetPage[FTSSearchResult]]):
    """Convert backend FTS payload rows into a keyset page."""

    def __init__(
        self: FtsKeysetPageStep,
        ref_id: ServerPlanRefId,
        config: _FtsKeysetPageConfig,
    ) -> None:
        super().__init__(ref_id)
        self._source_ref = config.source_ref
        self._limit = config.limit
        self._after = config.after

    @property
    def level(self: FtsKeysetPageStep) -> int:
        return 0

    def result_cardinality(self: FtsKeysetPageStep) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self: FtsKeysetPageStep) -> bool:
        return True

    def execution_role(self: FtsKeysetPageStep) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def step_tags(self: FtsKeysetPageStep) -> frozenset[str]:
        return frozenset({"fts", "terminal_projection", "keyset_page"})

    def counts_as_sql_group_for_accounting(self: FtsKeysetPageStep) -> bool | None:
        return False

    def runtime_result_is_terminal_scalar(self: FtsKeysetPageStep) -> bool:
        return True

    def dependencies(self: FtsKeysetPageStep) -> frozenset[str]:
        return frozenset({str(self._source_ref)})

    def tables_read(self: FtsKeysetPageStep) -> frozenset[str]:
        return frozenset()

    def tables_written(self: FtsKeysetPageStep) -> frozenset[str]:
        return frozenset()

    def compile(self: FtsKeysetPageStep, ctx: CompilationContext) -> CompiledStep[KeysetPage[FTSSearchResult]]:
        del ctx
        return CompiledStep()

    def execute_runtime(self: FtsKeysetPageStep, resolved: ResolvedRefs) -> KeysetPage[FTSSearchResult]:
        page = fts_payload_to_keyset_page(
            cast("FtsSearchPayloadRows", resolved[str(self._source_ref)]),
            limit=self._limit,
            after=self._after,
        )
        if not isinstance(page, KeysetPage):
            msg = f"Expected FTS keyset page, got {type(page).__name__}"
            raise TypeError(msg)
        return page


@pure_lazy
