"""Maintain incident postings after sparse edge windows change."""

from __future__ import annotations

from impl.common.l2050_sql_types.sql_branded_types import SqlAliasName, SqlColumnName, SqlTableName
from impl.common.l2070_server_plan.steps._compile_server_ref import lower_scalar_server_ref
from impl.common.l2070_server_plan.steps._auxiliary_ctes import collect_dependency_auxiliary_ctes
from impl.common.l2100_sql_grammar.domain.versioning.incident_posting_maintenance import (
    POSTING_TABLE,
    insert_incident_window_postings,
    replace_incident_window_postings,
)
from impl.common.l2100_sql_grammar.domain.versioning.stmt_cte import SqlUnionAll
from impl.common.l2100_sql_grammar.domain.versioning.physical_keys import SqlBranchPhysicalKeyScalar, SqlRevisionPhysicalKeyScalar
from impl.common.l2100_sql_grammar.domain.infra.stmt_compound_write import (
    SqlStatementBatch,
    SqlStatementBatchCategory,
    SqlStatementRelationship,
    SqlStatementRelationshipKind,
)
from impl.common.l2100_sql_grammar.tree.clauses import SqlColumnNameList
from impl.common.l2100_sql_grammar.tree.enums import BinaryOp
from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnAlias, SqlColumnRef, SqlParam
from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp, sql_and
from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
from impl.common.l2100_sql_grammar.tree.statements import SqlDelete, SqlInsert, SqlSelect
from l1200_versioned_ids import BranchId, RevisionId
from l1400_types import ServerPlanRefId
from l2070_batching.cardinality import Cardinality
from l2070_batching.compilation import CompilationContext, CompiledStep
from l2070_batching.post_op import literal_post_op
from l2070_batching.output_shape import DeclaredResultRelation, declared_zero_column_output_shape
from l2070_batching.sql_column_type_hints import SqlColumnTypeHints
from l2070_batching.server_ref import ScalarServerRef, inspect_server_value_shape_for_planning
from l2070_batching.step import NonPublishingStep


class MaintainIncidentPostingsStep(NonPublishingStep[None]):
    """Replace only sparse windows opened or closed by this revision."""

    def __init__(
        self: MaintainIncidentPostingsStep,
        ref_id: ServerPlanRefId,
        *,
        sparse_table: SqlTableName,
        edge_table: SqlTableName,
        branch_ref: ScalarServerRef[BranchId],
        revision_ref: ScalarServerRef[RevisionId],
        depends_on: frozenset[ServerPlanRefId],
    ) -> None:
        super().__init__(ref_id)
        self._sparse_table = sparse_table
        self._edge_table = edge_table
        self._branch_ref = branch_ref
        self._revision_ref = revision_ref
        self._dependencies = depends_on

    @property
    def level(self: MaintainIncidentPostingsStep) -> int:
        return 0

    def result_cardinality(self: MaintainIncidentPostingsStep) -> Cardinality:
        return Cardinality.NONE

    def is_read_only(self: MaintainIncidentPostingsStep) -> bool:
        return False

    def dependencies(self: MaintainIncidentPostingsStep) -> frozenset[str]:
        return frozenset(str(ref) for ref in self._dependencies) | self._scalar_input_dependencies()

    def _scalar_input_dependencies(self: MaintainIncidentPostingsStep) -> frozenset[str]:
        return frozenset(
            dependency
            for value in (self._branch_ref, self._revision_ref)
            for dependency in inspect_server_value_shape_for_planning(
                value,
                site="MaintainIncidentPostingsStep.dependencies",
            ).dependency_refs
        )

    def tables_read(self: MaintainIncidentPostingsStep) -> frozenset[str]:
        return frozenset({str(self._sparse_table), "sys_branch_physical_keys", "sys_revision_physical_keys"})

    def tables_written(self: MaintainIncidentPostingsStep) -> frozenset[str]:
        return frozenset({str(POSTING_TABLE)})

    def compile(self: MaintainIncidentPostingsStep, ctx: CompilationContext) -> CompiledStep[None]:
        branch = SqlBranchPhysicalKeyScalar(lower_scalar_server_ref(self._branch_ref, ctx))
        revision = SqlRevisionPhysicalKeyScalar(lower_scalar_server_ref(self._revision_ref, ctx))
        windows = SqlUnionAll(
            [
                SqlSelect(
                    select=[
                        *(
                            SqlColumnRef(SqlColumnName(name))
                            for name in (
                                "branch_id",
                                "sys_id",
                                "graph_sys_id",
                                "source_sys_id",
                                "target_sys_id",
                                "sys_deleted",
                            )
                        ),
                        SqlColumnAlias(SqlColumnRef(SqlColumnName("sys_valid_from_seq")), SqlAliasName("valid_from_seq")),
                        SqlColumnAlias(SqlColumnRef(SqlColumnName("sys_valid_to_seq")), SqlAliasName("valid_to_seq")),
                    ],
                    from_=SqlTableIdent(self._sparse_table),
                    where=sql_and(
                        SqlBinaryOp(SqlColumnRef(SqlColumnName("branch_ord")), BinaryOp.EQ, branch),
                        SqlBinaryOp(SqlColumnRef(SqlColumnName(changed_column)), BinaryOp.EQ, revision),
                    ),
                )
                for changed_column in ("sys_valid_from_seq", "sys_valid_to_seq")
            ]
        )
        output_shape = declared_zero_column_output_shape()
        return CompiledStep(
            grammar=replace_incident_window_postings(
                windows, edge_table=self._edge_table, joined_delete=ctx.backend_profile.traits.incident_window_joined_delete
            ),
            output_shape=output_shape,
            result_relation=DeclaredResultRelation.from_output_shape(output_shape),
            column_type_hints=SqlColumnTypeHints(),
            auxiliary_ctes=collect_dependency_auxiliary_ctes(ctx, self._scalar_input_dependencies()),
            closed_post_op=literal_post_op(None),
        )


class RebuildIncidentPostingsStep(NonPublishingStep[None]):
    """Explicitly rebuild one physical edge family on one branch.

    The caller owns the write transaction and must serialize graph publication
    on this branch. Readers never invoke this repair operation.
    """

    def __init__(
        self: RebuildIncidentPostingsStep,
        ref_id: ServerPlanRefId,
        *,
        sparse_table: SqlTableName,
        edge_table: SqlTableName,
        branch_ref: ScalarServerRef[BranchId],
        depends_on: frozenset[ServerPlanRefId] = frozenset(),
    ) -> None:
        super().__init__(ref_id)
        self._sparse_table = sparse_table
        self._edge_table = edge_table
        self._branch_ref = branch_ref
        self._dependencies = depends_on

    @property
    def level(self: RebuildIncidentPostingsStep) -> int:
        return 0

    def result_cardinality(self: RebuildIncidentPostingsStep) -> Cardinality:
        return Cardinality.NONE

    def is_read_only(self: RebuildIncidentPostingsStep) -> bool:
        return False

    def dependencies(self: RebuildIncidentPostingsStep) -> frozenset[str]:
        return frozenset(str(ref) for ref in self._dependencies) | frozenset(
            inspect_server_value_shape_for_planning(
                self._branch_ref,
                site="RebuildIncidentPostingsStep.dependencies",
            ).dependency_refs
        )

    def tables_read(self: RebuildIncidentPostingsStep) -> frozenset[str]:
        return frozenset({str(self._sparse_table)})

    def tables_written(self: RebuildIncidentPostingsStep) -> frozenset[str]:
        return frozenset({str(POSTING_TABLE), "sys_graph_incident_posting_coverage"})

    def compile(self: RebuildIncidentPostingsStep, ctx: CompilationContext) -> CompiledStep[None]:
        branch = lower_scalar_server_ref(self._branch_ref, ctx)
        branch_predicate = SqlBinaryOp(SqlColumnRef(SqlColumnName("branch_id")), BinaryOp.EQ, branch)
        windows = SqlSelect(
            select=[
                *(
                    SqlColumnRef(SqlColumnName(name))
                    for name in (
                        "branch_id",
                        "sys_id",
                        "graph_sys_id",
                        "source_sys_id",
                        "target_sys_id",
                        "sys_deleted",
                    )
                ),
                SqlColumnAlias(SqlColumnRef(SqlColumnName("sys_valid_from_seq")), SqlAliasName("valid_from_seq")),
                SqlColumnAlias(SqlColumnRef(SqlColumnName("sys_valid_to_seq")), SqlAliasName("valid_to_seq")),
            ],
            from_=SqlTableIdent(self._sparse_table),
            where=branch_predicate,
        )
        family_predicate = sql_and(
            branch_predicate,
            SqlBinaryOp(SqlColumnRef(SqlColumnName("edge_table_name")), BinaryOp.EQ, SqlParam(str(self._edge_table))),
        )
        delete = SqlDelete(SqlTableIdent(POSTING_TABLE), where=family_predicate)
        coverage_table = SqlTableName("sys_graph_incident_posting_coverage")
        delete_coverage = SqlDelete(SqlTableIdent(coverage_table), where=family_predicate)
        insert_coverage = SqlInsert(
            SqlTableIdent(coverage_table),
            columns=SqlColumnNameList(tuple(SqlColumnName(name) for name in ("sys_id", "branch_id", "edge_table_name"))),
            source=SqlSelect(
                select=[
                    SqlColumnAlias(branch, SqlAliasName("sys_id")),
                    SqlColumnAlias(branch, SqlAliasName("branch_id")),
                    SqlColumnAlias(SqlParam(str(self._edge_table)), SqlAliasName("edge_table_name")),
                ]
            ),
        )
        output_shape = declared_zero_column_output_shape()
        return CompiledStep(
            output_shape=output_shape,
            result_relation=DeclaredResultRelation.from_output_shape(output_shape),
            column_type_hints=SqlColumnTypeHints(),
            grammar=SqlStatementBatch(
                [
                    delete,
                    delete_coverage,
                    insert_incident_window_postings(windows, edge_table=self._edge_table),
                    insert_coverage,
                ],
                category=SqlStatementBatchCategory.DEPENDENCY_GRAPH,
                relationships=(
                    SqlStatementRelationship(0, 2, SqlStatementRelationshipKind.DATA_VISIBILITY),
                    SqlStatementRelationship(1, 3, SqlStatementRelationshipKind.DATA_VISIBILITY),
                    SqlStatementRelationship(2, 3, SqlStatementRelationshipKind.SUCCESS_GATE),
                ),
                collect_results_per_stmt=[False, False, False, False],
            ),
            auxiliary_ctes=collect_dependency_auxiliary_ctes(ctx, self.dependencies()),
            closed_post_op=literal_post_op(None),
        )

"""SQL-owned alias-aware table schema-history lookup."""

from __future__ import annotations

from l1400_types.type_surface_contracts import SchemaFingerprintHash

from l1400_types.type_surface_contracts import OptimizerAccessTableName, OptimizerStepTag

from collections.abc import Sequence

from pydantic import BaseModel

from l1000_schema.json_type import JsonValue
from l1400_types import DynamicFieldName, ServerPlanRefId
from l2070_batching.cardinality import Cardinality
from l2070_batching.compilation import (
    CompilationContext,
    CompiledStep,
    CteReference,
    ResultBoundLifecycleEffects,
    compiled_artifacts_from_cte_publication_contract,
)
from l2070_batching.cte_contracts import CtePublicationContract, CteRelationContract
from l2070_batching.post_op import (
    CompiledPostOp,
    PostOpBehavior,
    ResultMaterializationSpec,
    ScalarCoercionKind,
    StructuredResultField,
    StructuredResultSpec,
    scalar_column_post_op,
)
from l2070_batching.sql_column_type_hints import SqlColumnTypeHints
from l2070_batching.step import SqlRelationPublisherStep, StepExecutionRole
from impl.common.l2070_server_plan.steps.cache_steps import PopulateLocalCacheEffect
from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName, SqlCteStepName, SqlTableName
from impl.common.l2100_sql_grammar.domain.infra.schema_history import SqlSchemaHistoryLookup
from impl.common.l2100_sql_grammar.domain.infra.stmt_cte_helpers import SqlSelectExpressions
from impl.common.l2100_sql_grammar.domain.infra.stmt_dml_simple import SqlCteFieldRef
from l3200_metadata.table_schema_history import CachedSchemaSnapshot, SCHEMA_HISTORY_CACHE_NAME


class SchemaHistoryGlobalSchemaHash(str):
    """Global schema hash carried through schema-history plan state."""


class _SchemaHistoryLookupRow(BaseModel):
    columns: JsonValue
    version: int


class _SchemaHistoryColumnsRow(BaseModel):
    columns: JsonValue


class _SchemaHistoryVersionRow(BaseModel):
    version: int


def _schema_history_snapshot_post_op() -> CompiledPostOp:
    return CompiledPostOp.materialize(
        ResultMaterializationSpec(
            behavior=PostOpBehavior.TERMINAL_OBJECT,
            structured_result=StructuredResultSpec(
                result_cls=CachedSchemaSnapshot,
                allow_empty=True,
                return_empty_value=True,
                empty_value=None,
                fields=(
                    StructuredResultField("columns", "columns", ScalarCoercionKind.JSON),
                    StructuredResultField("version", "version", ScalarCoercionKind.INT),
                ),
            ),
        ),
    )


class SchemaHistoryLookupStep(SqlRelationPublisherStep[CachedSchemaSnapshot | None]):
    """Publish one alias-aware schema snapshot as a SQL-visible relation."""

    def __init__(
        self: SchemaHistoryLookupStep,
        ref_id: ServerPlanRefId,
        *,
        global_schema_hash: SchemaHistoryGlobalSchemaHash,
        table_name: SqlTableName,
    ) -> None:
        super().__init__(ref_id)
        self._global_schema_hash = global_schema_hash
        self._table_name = table_name

    @property
    def level(self: SchemaHistoryLookupStep) -> int:
        return 0

    def result_cardinality(self: SchemaHistoryLookupStep) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self: SchemaHistoryLookupStep) -> bool:
        return True

    def execution_role(self: SchemaHistoryLookupStep) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def step_tags(self: SchemaHistoryLookupStep) -> frozenset[OptimizerStepTag]:
        return frozenset(
            OptimizerStepTag(value) for value in ('read', 'metadata', 'schema_history')
        )

    def dependencies(self: SchemaHistoryLookupStep) -> frozenset[ServerPlanRefId]:
        return frozenset()

    def tables_read(self: SchemaHistoryLookupStep) -> frozenset[OptimizerAccessTableName]:
        return frozenset(
            OptimizerAccessTableName(value) for value in ('sys_table_schema_history', 'sys_schema_rename_history')
        )

    def tables_written(self: SchemaHistoryLookupStep) -> frozenset[OptimizerAccessTableName]:
        return frozenset()

    def cte_publication_contract(self: SchemaHistoryLookupStep) -> CtePublicationContract:
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=("columns", "version"),
            column_type_hints=SqlColumnTypeHints(
                jsonb_columns=frozenset({"columns"}),
                bigint_columns=frozenset({"version"}),
            ),
            model_cls=_SchemaHistoryLookupRow,
            relation_contract=CteRelationContract.semantic_row(_SchemaHistoryLookupRow),
            relation_role=self.cte_relation_role(),
            source_tables=self.tables_read(),
            empty_result_allowed=True,
        )

    def compile(self: SchemaHistoryLookupStep, ctx: CompilationContext) -> CompiledStep[CachedSchemaSnapshot | None]:
        del ctx
        output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(
            self.cte_publication_contract(),
        )
        return CompiledStep(
            grammar=SqlSchemaHistoryLookup(
                global_schema_hash=SchemaFingerprintHash(self._global_schema_hash),
                table_name=self._table_name,
            ),
            needs_returning=True,
            closed_post_op=_schema_history_snapshot_post_op(),
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
            lifecycle_effects=(ResultBoundLifecycleEffects(self._cache_effects_from_result),),
        )

    def _cache_effects_from_result(
        self: SchemaHistoryLookupStep,
        result: object,
    ) -> tuple[PopulateLocalCacheEffect, ...]:
        if result is None:
            return ()
        if not isinstance(result, CachedSchemaSnapshot):
            msg = f"Expected CachedSchemaSnapshot, got {type(result).__name__}"
            raise TypeError(msg)
        from l3200_metadata.table_schema_history_cache import get_schema_history_cache

        get_schema_history_cache()
        return (
            PopulateLocalCacheEffect(
                cache_name=SCHEMA_HISTORY_CACHE_NAME,
                key=f"{self._global_schema_hash}:{self._table_name}",
                value=result,
                tags=(f"global:{self._global_schema_hash}", f"table:{self._table_name}"),
                ttl_seconds=None,
                tag_generations={},
            ),
        )


class SchemaHistoryValueProjectionStep(SqlRelationPublisherStep[object | None]):
    """Project one typed scalar from a SQL-visible schema snapshot."""

    def __init__(
        self: SchemaHistoryValueProjectionStep,
        ref_id: ServerPlanRefId,
        *,
        source_ref: ServerPlanRefId,
        field_name: DynamicFieldName,
    ) -> None:
        super().__init__(ref_id)
        if field_name not in {"columns", "version"}:
            msg = f"Unsupported schema-history field {field_name!r}"
            raise ValueError(msg)
        self._source_ref = source_ref
        self._field_name = field_name

    @property
    def level(self: SchemaHistoryValueProjectionStep) -> int:
        return 0

    def result_cardinality(self: SchemaHistoryValueProjectionStep) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self: SchemaHistoryValueProjectionStep) -> bool:
        return True

    def execution_role(self: SchemaHistoryValueProjectionStep) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def step_tags(self: SchemaHistoryValueProjectionStep) -> frozenset[OptimizerStepTag]:
        return frozenset(
            OptimizerStepTag(value) for value in ('read', 'metadata', 'schema_history', 'projection')
        )

    def dependencies(self: SchemaHistoryValueProjectionStep) -> frozenset[ServerPlanRefId]:
        return frozenset({self._source_ref})

    def declares_consumed_rows_reduction(self: SchemaHistoryValueProjectionStep) -> bool:
        return True

    def tables_read(self: SchemaHistoryValueProjectionStep) -> frozenset[OptimizerAccessTableName]:
        return frozenset()

    def tables_written(self: SchemaHistoryValueProjectionStep) -> frozenset[OptimizerAccessTableName]:
        return frozenset()

    def cte_publication_contract(self: SchemaHistoryValueProjectionStep) -> CtePublicationContract:
        is_columns = self._field_name == "columns"
        model_cls = _SchemaHistoryColumnsRow if is_columns else _SchemaHistoryVersionRow
        hints = (
            SqlColumnTypeHints(jsonb_columns=frozenset({"columns"}))
            if is_columns
            else SqlColumnTypeHints(bigint_columns=frozenset({"version"}))
        )
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=(self._field_name,),
            column_type_hints=hints,
            model_cls=model_cls,
            relation_contract=CteRelationContract.semantic_row(model_cls),
            relation_role=self.cte_relation_role(),
            empty_result_allowed=True,
        )

    def compile(self: SchemaHistoryValueProjectionStep, ctx: CompilationContext) -> CompiledStep[object | None]:
        binding = ctx.cte_refs.get(str(self._source_ref))
        if not isinstance(binding, CteReference):
            msg = f"Schema history source {self._source_ref!r} is not SQL-visible"
            raise ValueError(msg)
        grammar = SqlSelectExpressions(
            [
                (
                    SqlCteFieldRef(SqlCteStepName(binding.ref_id), SqlColumnName(self._field_name)),
                    self._field_name,
                ),
            ],
        )
        contract = self.cte_publication_contract()
        output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(contract)
        return CompiledStep(
            grammar=grammar,
            needs_returning=True,
            closed_post_op=scalar_column_post_op(
                self._field_name,
                default_value=None,
                use_default_on_empty=True,
                scalar_coercion=(ScalarCoercionKind.JSON if self._field_name == "columns" else ScalarCoercionKind.INT),
            ),
