def _expect_row_list[T](value: object, model_cls: type[T]) -> list[T]:
    if not isinstance(value, list):
        msg = f"Expected list[{model_cls.__name__}] from legacy embedding reconciliation"
        raise TypeError(msg)
    for row in value:
        if not isinstance(row, model_cls):
            msg = f"Expected {model_cls.__name__} row, got {type(row).__name__}"
            raise TypeError(msg)
    return value


def missing_legacy_embedding_metadata_rows(
    legacy_rows: Sequence[_LegacyEmbeddingMetadataLike],
    existing_rows: Sequence[_LegacyEmbeddingMetadataLike],
    embedding_metadata_model: type[ApplicationObjectRow[SysId]],
) -> list[ApplicationObjectRow[SysId]]:
    """Build canonical rows absent from the existing metadata relation."""
    existing_keys = {(str(row.table_name), str(row.field_name)) for row in existing_rows}
    rows: list[ApplicationObjectRow[SysId]] = []
    for legacy_row in legacy_rows:
        key = (legacy_row.table_name, legacy_row.field_name)
        if key in existing_keys:
            continue
        rows.append(
            embedding_metadata_model(
                table_name=legacy_row.table_name,
                field_name=legacy_row.field_name,
                algorithm_established=legacy_row.algorithm_established,
                provider=legacy_row.provider,
                model=legacy_row.model,
                model_version=legacy_row.model_version,
                dimensions=legacy_row.dimensions,
                next_sequence_id=legacy_row.next_sequence_id,
                next_expected_sequence=legacy_row.next_expected_sequence,
                last_queued_at=legacy_row.last_queued_at,
                last_queued_sequence=legacy_row.last_queued_sequence,
                last_applied_at=legacy_row.last_applied_at,
                last_applied_sequence=legacy_row.last_applied_sequence,
                content_hash_nonce=legacy_row.content_hash_nonce,
            ),
        )
    return rows


