                get_table_name(self._legacy_model),
                get_table_name(self._embedding_metadata_model),
            },
        )

    def tables_written(self: MissingLegacyEmbeddingMetadataRowsStep) -> frozenset[str]:
        return frozenset()

    def cte_publication_contract(self: MissingLegacyEmbeddingMetadataRowsStep) -> CtePublicationContract:
        columns = tuple(
            get_db_column_name(self._embedding_metadata_model, DynamicFieldName(field_name)) for field_name in self._embedding_metadata_model.model_fields
        )
        column_type_hints = model_sql_column_type_hints(
            self._embedding_metadata_model,
            columns,
        )
        if column_type_hints is None:
            msg = "Could not resolve SQL column type hints for legacy embedding metadata rows"
            raise TypeError(msg)
        contract_columns = tuple(str(column) for column in columns)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=contract_columns,
            column_type_hints=column_type_hints,
            model_cls=cte_projection_row_model(
                f"{type(self).__name__}CteRow",
                contract_columns,
                column_type_hints,
            ),
            relation_contract=CteRelationContract.projection_over_model(
                source_model_cls=self._embedding_metadata_model,
                projection_lineage=tuple((column, column) for column in contract_columns),
            ),
            relation_role=self.cte_relation_role(),
        )

    def semantic_publication_columns(self: MissingLegacyEmbeddingMetadataRowsStep) -> tuple[str, ...]:
        return self.cte_publication_contract().columns

    def semantic_publication_type_hints(
        self: MissingLegacyEmbeddingMetadataRowsStep,
    ) -> SqlColumnTypeHints:
        return self.cte_publication_contract().column_type_hints

    def executor_visible_published_rows(
        self: MissingLegacyEmbeddingMetadataRowsStep,
    ) -> Sequence[Mapping[str, object]] | None:
        return None

    def compile(
        self: MissingLegacyEmbeddingMetadataRowsStep,
        ctx: CompilationContext,
    ) -> CompiledStep[list[ApplicationObjectRow[SysId]]]:
        del ctx
        from impl.common.l2050_sql_types.sql_branded_types import SqlAliasName, SqlColumnName, SqlTableName
        from impl.common.l2100_sql_grammar.tree.clauses import SqlSelectList, SqlTableAlias
        from impl.common.l2100_sql_grammar.tree.enums import BinaryOp
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnAlias, SqlColumnRef, SqlParam
        from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp, SqlExists, sql_and
        from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
        from impl.common.l2100_sql_grammar.tree.statements import SqlSelect

        legacy_alias = SqlAliasName("legacy")
        existing_alias = SqlAliasName("existing")
        select_items = [
            SqlColumnAlias(
                SqlColumnRef(
                    SqlColumnName(get_db_column_name(self._legacy_model, DynamicFieldName(field_name))),
                    qualifier=legacy_alias,
                )
                if field_name in self._legacy_model.model_fields
                else SqlParam(None),
                SqlAliasName(SqlColumnName(get_db_column_name(self._embedding_metadata_model, DynamicFieldName(field_name)))),
            )
            for field_name in self._embedding_metadata_model.model_fields
        ]

        existing_match = SqlSelect(
            select=SqlSelectList([SqlParam(1)]),
            from_clause=SqlTableAlias(
                SqlTableIdent(SqlTableName(get_table_name(self._embedding_metadata_model))),
                existing_alias,
            ),
            where=sql_and(
                SqlBinaryOp(
                    SqlColumnRef(SqlColumnName("table_name"), qualifier=existing_alias),
                    BinaryOp.EQ,
                    SqlColumnRef(SqlColumnName("table_name"), qualifier=legacy_alias),
                ),
                SqlBinaryOp(
                    SqlColumnRef(SqlColumnName("field_name"), qualifier=existing_alias),
                    BinaryOp.EQ,
                    SqlColumnRef(SqlColumnName("field_name"), qualifier=legacy_alias),
                ),
            ),
        )
        grammar = SqlSelect(
            select=SqlSelectList(select_items),
            from_clause=SqlTableAlias(
                SqlTableIdent(SqlTableName(get_table_name(self._legacy_model))),
                legacy_alias,
            ),
            where=SqlExists(existing_match, negated=True),
        )
        output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(
            self.cte_publication_contract(),
        )
        return CompiledStep(
            grammar=grammar,
            needs_returning=True,
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
        )


