def auxiliary_cte_name(definition: SqlCteDefinitionInput) -> str:
    return str(definition.name) if isinstance(definition, SqlCteDefinition) else definition[0]


def merge_auxiliary_ctes(
    *groups: Sequence[SqlCteDefinitionInput] | None,
) -> list[SqlCteDefinitionInput] | None:
    merged: list[SqlCteDefinitionInput] = []
    seen: set[str] = set()
    for group in groups:
        if not group:
            continue
        for definition in group:
            name = auxiliary_cte_name(definition)
            if name in seen:
                continue
            seen.add(name)
            merged.append(definition)
    return merged or None


def visible_embedding_content_digest(
    model_cls: type[DatabaseObjectRow], index_name: SqlIndexName,
    source_alias: SqlAliasName, metadata_alias: SqlAliasName,
) -> SqlRenderable:
    from impl.common.l2050_sql_types.sql_branded_types import SqlJsonPath
    from impl.common.l2070_server_plan.steps.embedding_auto_queue_intent import (
        _build_hash_payload_expr,
    )
    from impl.common.l2100_sql_grammar.domain.infra.expr_primitives import SqlSaltedSha256Digest
    from impl.common.l2100_sql_grammar.tree.expr_json import JsonAccessKind, SqlJsonAccess
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef
    from l1000_schema.dynamic_field_utils import is_dynamic_property_field
    from l1000_schema.schema_def import get_db_column_name
    from l5200_vector_index.embedding_content_hash import get_embedding_source_fields

    source_fields = get_embedding_source_fields(model_cls, index_name)
    field_exprs: list[SqlRenderable] = []
    for field_name in source_fields:
        if is_dynamic_property_field(model_cls, DynamicFieldName(field_name)):
            field_exprs.append(SqlJsonAccess(
                JsonAccessKind.GET_TEXT,
                SqlColumnRef(SqlColumnName("properties"), qualifier=source_alias),
                SqlJsonPath(f"$.{field_name}"),
            ))
        else:
            field_exprs.append(
                SqlColumnRef(
                    SqlColumnName(get_db_column_name(model_cls, DynamicFieldName(field_name))),
                    qualifier=source_alias,
                )
            )
    return SqlSaltedSha256Digest(
        SqlColumnRef(SqlColumnName("content_hash_nonce"), qualifier=metadata_alias),
        _build_hash_payload_expr(
            fields=source_fields, index_name=index_name, field_exprs=field_exprs
        ),
    )


def sql_table_hnsw_query_vector(spec: QuerySpec[DatabaseObjectRow]) -> list[float] | None:
    raw_query_vec = spec.search_op.vector_query_vec
    if raw_query_vec is None:
        return None
    normalized = cast("list[float] | None", normalize_sql_table_hnsw_query_vector(raw_query_vec))
    if normalized is None or spec.search_op.vector_index_name is None:
        return normalized
    from l5200_vector_index.vector_config import get_vector_config

    config = get_vector_config(spec.model_cls, spec.search_op.vector_index_name)
    if config is None or config.target_dimensions is None:
        return normalized
    return normalized[: config.target_dimensions]


def sql_table_hnsw_projected_hamming_query(
    *,
    model_cls: type[DatabaseObjectRow],
    index_name: SqlIndexName,
    spec: QuerySpec[DatabaseObjectRow],
) -> SqlTableHnswProjectedHammingQuery | None:
    from l5200_vector_index.vector_config import get_vector_config
    from l5200_vector_index.vector_projection import VectorRepresentationKind

    payload = spec.search_op.vector_query_payload
    query_binary = getattr(payload, "projected_value", None) if payload is not None else None
    if query_binary is None:
        return None
    representation_id = getattr(payload, "projected_representation_id", None)
    config = get_vector_config(model_cls, index_name)
    if config is None:
        msg = f"No vector index {index_name!r} on {model_cls.__name__}"
        raise ValueError(msg)
    representation = next(
        (candidate for candidate in config.available_representations if candidate.representation_id == representation_id),
        None,
    )
    if representation is None:
        msg = f"Projected representation {representation_id!r} is not configured for {model_cls.__name__}.{index_name}"
        raise ValueError(msg)
    if representation.kind is not VectorRepresentationKind.BIT_HAMMING:
        msg = f"SQLTableHNSW projected search requires bit_hamming representation, got {representation.kind.value}"
        raise NotImplementedError(msg)
    binary_dimensions = int(representation.dimensions)
    actual_bits = len(query_binary) * 8
    if actual_bits != binary_dimensions:
        msg = f"Projected query code must be {binary_dimensions} bits; got {actual_bits} bits."
        raise ValueError(msg)
    return SqlTableHnswProjectedHammingQuery(
        query_binary=bytes(query_binary),
        binary_dimensions=binary_dimensions,
    )


def embedding_metadata_model_condition(
    vector_alias: SqlAliasName,
    metadata_alias: SqlAliasName,
) -> SqlRenderable:
    """Match normalized model references, or legacy metadata without a model reference."""
    from impl.common.l2100_sql_grammar.tree.enums import BinaryOp
    from impl.common.l2100_sql_grammar.tree.expr_compound import SqlCase, SqlFuncCall
    from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlParam
    from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp, SqlIsNull, sql_and, sql_or

    def column(alias: SqlAliasName, name: str) -> SqlColumnRef:
        return SqlColumnRef(SqlColumnName(name), qualifier=alias)

    metadata_ref = column(metadata_alias, "model_ref_id")
    model = column(metadata_alias, "model")
    provider = column(metadata_alias, "provider")
    legacy_id = SqlCase(
        whens=[(SqlIsNull(provider), model)],
        else_=SqlFuncCall("CONCAT", [provider, SqlParam(":"), model]),
    )
    return sql_or(
        sql_and(
            SqlIsNull(metadata_ref, negated=True),
            SqlBinaryOp(column(vector_alias, "model_ref_id"), BinaryOp.EQ, metadata_ref),
        ),
        sql_and(
            SqlIsNull(metadata_ref),
            sql_or(
                SqlIsNull(model),
                SqlBinaryOp(column(vector_alias, "model_id"), BinaryOp.EQ, legacy_id),
            ),
        ),
    )


def vector_source_table_name(model_cls: type[DatabaseObjectRow]) -> str:
    from l1000_schema.table_registry import get_table_config
    from l1000_schema.table_utils import get_table_name

    source_versioned_model = get_table_config(model_cls).source_versioned_model
    if isinstance(source_versioned_model, type):
        source_table: str = get_table_name(source_versioned_model)
        return source_table
    table_name: str = get_table_name(model_cls)
    return table_name


