class DeleteStep[TResult](NonPublishingStep[TResult]):
    """Step for deleting model instances by sys_id."""

    def __init__(
        self: DeleteStep,
        ref_id: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        sys_id: ScalarServerRef[SysId],
        *,
        config: _DeleteStepConfig | None = None,
    ) -> None:
        """Initialize DeleteStep.

        Args:
            ref_id: Unique identifier for this step
            model_cls: The DatabaseObjectRow subclass to delete from
            sys_id: The sys_id to delete (may be a ServerRef before preprocessing)
        """
        super().__init__(ref_id)
        resolved_config = config or _DeleteStepConfig()
        self._model_cls = model_cls
        self._sys_id = sys_id
        self._resolved_id: Any | None = None
        self._user_id_ref_id = resolved_config.user_id_ref_id
        self._resolved_user_id: ResolvedPermissionUserId = None
        self._delete_inputs_ref = resolved_config.delete_inputs_ref

    @property
    def level(self: DeleteStep) -> int:
        return 1

    def step_tags(self: DeleteStep) -> frozenset[str]:
        """Return tags identifying this step type."""
        return frozenset({"write", "delete"})

    def is_read_only(self: DeleteStep) -> bool:
        """Return False - this step modifies data."""
        return False

    def result_cardinality(self: DeleteStep) -> Cardinality:
        """Return NONE - this step returns no result."""
        return Cardinality.NONE

    def requires_runtime_sequential_batch(self: DeleteStep) -> bool:
        return bool(
            _planning_dependency_refs(
                self._sys_id,
                site=f"{type(self).__name__}.requires_runtime_sequential_batch",
            ),
        )

    def tables_read(self: DeleteStep) -> frozenset[str]:
        """Delete does not read any tables."""
        return frozenset()

    def tables_written(self: DeleteStep) -> frozenset[str]:
        """Return the table name this step writes to."""
        from l1000_schema.table_utils import get_table_name

        return frozenset({get_table_name(self._model_cls)})

    def dependencies(self: DeleteStep) -> frozenset[str]:
        deps: set[str] = set()
        if self._user_id_ref_id is not None:
            deps.add(str(self._user_id_ref_id))
        deps.update(
            _base_dependency_refs(
                self._sys_id,
                site=f"{type(self).__name__}.dependencies",
            ),
        )
        return frozenset(deps)

    def lower(self: DeleteStep, ctx: LoweringContext) -> list[ServerPlanStep[Any]]:
        del ctx
        from impl.common.l2070_server_plan.steps.row_hydration import ResolveDeletedCountResultStep

        raw_ref = f"{self.ref_id}.raw"
        delete_inputs_ref = f"{self.ref_id}.delete_inputs"
        steps: list[ServerPlanStep[Any]] = []
        if self._user_id_ref_id is not None or self.dependencies():
            steps.append(
                _ResolveDeleteInputsStep(
                    ServerPlanRefId(delete_inputs_ref),
                    sys_id=self._sys_id,
                    config=_ResolveDeleteInputsConfig(user_id_ref_id=self._user_id_ref_id),
                ),
            )
        steps.extend(
            [
                DeleteRawResultStep(
                    ServerPlanRefId(raw_ref),
                    self._model_cls,
                    self._sys_id,
                    config=_DeleteStepConfig(
                        user_id_ref_id=self._user_id_ref_id,
                        delete_inputs_ref=ServerPlanRefId(delete_inputs_ref) if steps else None,
                    ),
                ),
                ResolveDeletedCountResultStep(
                    self.ref_id,
                    source_ref=ServerPlanRefId(raw_ref),
                ),
            ],
        )
        return steps

    def compile(self: DeleteStep, ctx: CompilationContext) -> CompiledStep[TResult]:
        del ctx
        raise NotImplementedError("DeleteStep lowers to DeleteRawResultStep + ResolveDeletedCountResultStep")


class _ResolveDeleteInputsStep(NonPublishingStep[_ResolvedDeleteInputs]):
    """Resolve delete target inputs from explicit runtime refs."""

    __slots__ = ("_sys_id", "_user_id_ref_id")

    def __init__(
