    allow_write_transaction: bool = False,
    allow_statement_policy_dispatch: bool = False,
) -> CompiledStep[T] | None:
    """Close each consumer over one policy-selected physical source."""
    exact_historical_dispatch = ctx.explicit_revision_id is not None and tip_revision_ref_id is not None
    supports_dispatch = (
        ctx.backend_profile.traits.supports_graph_statement_policy_dispatch
        if allow_write_transaction
        else ctx.backend_profile.traits.supports_statement_policy_dispatch
    )
    if (ctx.is_write_transaction and not allow_write_transaction) or (
        ctx.explicit_revision_id is not None and (not exact_historical_dispatch or not allow_write_transaction)
    ):
        return None
    if ctx.selected_branch_policy_ref_id is not None:
        if policy_ref_id is not None and policy_ref_id != ctx.selected_branch_policy_ref_id:
            raise ValueError("A policy alternative cannot consume an independent policy owner")
        return None
    policy = ctx.lazy_branch_tip_materialization if policy_ref_id is None else ScalarServerRef(None, policy_ref_id)
    if policy is None:
        return None
    policy_shape = inspect_server_value_shape_for_planning(policy, site="branch policy compilation")
    if policy_shape.has_literal_value and not exact_historical_dispatch:
        from l7000_versioned_schema.versioned_schema import BranchTipMaterialization

        if not isinstance(policy_shape.literal_value, BranchTipMaterialization):
            raise ValueError("Branch policy must contain a valid enum")
        materialized_policy = policy_shape.literal_value is BranchTipMaterialization.MATERIALIZED
        return compile_alternative(
            replace(
                ctx,
                branch_tip_materialized=materialized_policy,
                lazy_branch_tip_materialization=None,
                prefer_tip_strategy=materialized_policy,
                selected_branch_policy_ref_id=policy.ref_id,
            )
        )
    if not allow_statement_policy_dispatch:
        return None
    if policy.ref_id is None:
        raise ValueError("Missing exact policy owner")
    binding = resolve_sql_visible_ref(
        ctx,
        policy.ref_id,
        default_field="tip_materialization",
    )
    if binding is None:
        raise ValueError(f"Missing exact policy owner for {policy.ref_id}")
    if isinstance(binding.binding.auxiliary_query, SqlPublishedRowsQuery):
        from l7000_versioned_schema.read_source_policy import published_tip_materialization
        from l7000_versioned_schema.versioned_schema import BranchTipMaterialization

        materialized_policy = published_tip_materialization(binding.binding) is BranchTipMaterialization.MATERIALIZED
        if exact_historical_dispatch:
            assert tip_revision_ref_id is not None
            tip_binding = resolve_sql_visible_ref(
                ctx,
                tip_revision_ref_id,
                default_field="tip_revision_id",
            )
            if tip_binding is None:
                raise ValueError(f"Missing persisted tip revision owner for {tip_revision_ref_id}")
            tip_query = tip_binding.binding.auxiliary_query
            if not isinstance(tip_query, SqlPublishedRowsQuery) or len(tip_query.published_rows) != 1:
                if not supports_dispatch:
                    raise ValueError("Exact historical routing requires one persisted branch row")
            else:
                tip_revision = tip_query.published_rows[0].get(tip_binding.field_name)
                if tip_revision is None:
                    raise ValueError("Persisted branch row is missing its tip revision")
                materialized_policy = materialized_policy and str(tip_revision) == str(ctx.explicit_revision_id)
                return compile_alternative(
                    replace(
                        ctx,
                        branch_tip_materialized=materialized_policy,
                        lazy_branch_tip_materialization=None,
                        prefer_tip_strategy=materialized_policy,
                        selected_branch_policy_ref_id=policy.ref_id,
                    )
                )
        else:
            return compile_alternative(
                replace(
                    ctx,
                    branch_tip_materialized=materialized_policy,
                    lazy_branch_tip_materialization=None,
                    prefer_tip_strategy=materialized_policy,
                    selected_branch_policy_ref_id=policy.ref_id,
                )
            )
    if not supports_dispatch:
        if exact_historical_dispatch:
            raise ValueError("Exact historical routing requires SQL-visible persisted branch metadata")
        return None
    materialized = compile_alternative(
        replace(
            ctx,
            branch_tip_materialized=True,
            lazy_branch_tip_materialization=None,
            prefer_tip_strategy=True,
            selected_branch_policy_ref_id=policy.ref_id,
        )
    )
    tipless = compile_alternative(
        replace(
            ctx,
            branch_tip_materialized=False,
            lazy_branch_tip_materialization=None,
            prefer_tip_strategy=False,
            selected_branch_policy_ref_id=policy.ref_id,
        )
    )
    if materialized.output_shape != tipless.output_shape or materialized.column_type_hints != tipless.column_type_hints:
        raise TypeError("Policy alternatives require identical result contracts")

    def scoped_query(alternative: CompiledStep[T]) -> SqlRenderable:
        if alternative.grammar is None:
            raise TypeError("Policy alternatives require SQL grammar")
        if alternative.params:
            raise TypeError("Policy alternatives require grammar-owned parameters")
        definitions = tuple(
            definition if isinstance(definition, SqlCteDefinition) else SqlCteDefinition(*definition)
            for definition in alternative.auxiliary_ctes or ()
        )
        return (
            SqlCte(definitions, alternative.grammar, recursive=alternative.needs_recursive_with) if definitions else alternative.grammar
        )

    policy_expr: SqlRenderable = SqlColumnRef(SqlColumnName(binding.field_name))
    if exact_historical_dispatch:
        assert tip_revision_ref_id is not None
        tip_binding = resolve_sql_visible_ref(
            ctx,
            tip_revision_ref_id,
            default_field="tip_revision_id",
        )
        if tip_binding is None:
            raise ValueError(f"Missing persisted tip revision owner for {tip_revision_ref_id}")
        if tip_binding.cte_name != binding.cte_name:
            raise ValueError("Branch policy and tip revision must share one persisted owner")
        materialized_policy_expr = SqlBinaryOp(
            policy_expr,
            BinaryOp.EQ,
            SqlParam("materialized"),
        )
        exact_tip = SqlBinaryOp(
            SqlParam(str(ctx.explicit_revision_id)),
            BinaryOp.EQ,
            SqlColumnRef(SqlColumnName(tip_binding.field_name)),
        )
        policy_expr = SqlCase(
            (
                (SqlBinaryOp(materialized_policy_expr, BinaryOp.AND, exact_tip), SqlParam("materialized")),
                (materialized_policy_expr, SqlParam("tipless")),
            ),
            else_=policy_expr,
        )
    policy_query = SqlSelect(
        policy_expr,
        from_=SqlTableName(binding.cte_name),
    )
    branch_identity_column = next((column for column in ("branch_id", "sys_id") if column in binding.binding.columns), None)
    branch_query = SqlSelect(
        SqlColumnRef(SqlColumnName(branch_identity_column or binding.field_name)),
        from_=SqlTableName(binding.cte_name),
    )
    definitions = (
        (SqlCteDefinition(binding.cte_name, binding.binding.auxiliary_query),) if binding.binding.auxiliary_query is not None else ()
    )
    return replace(
        materialized,
        grammar=SqlPolicyDispatchedRead(
            policy_query=SqlCte(definitions, policy_query) if definitions else policy_query,
            branch_query=SqlCte(definitions, branch_query) if definitions and branch_query is not None else branch_query,
            policy_owner=(ServerPlanRefId(binding.binding.ref_id), SqlColumnName(binding.field_name)),
            materialized_query=scoped_query(materialized),
            tipless_query=scoped_query(tipless),
        ),
        auxiliary_ctes=None,
        needs_recursive_with=False,
    )

"""GrammarRowsStep: terminal step for SQL grammar rows."""

from __future__ import annotations

from dataclasses import dataclass
from enum import StrEnum
from typing import TYPE_CHECKING, Any

from l2070_batching.cardinality import Cardinality
from l2070_batching.compilation import CompiledStep
from l2070_batching.output_shape import CompiledOutputShape, DeclaredResultRelation, synthetic_output_field
from l2070_batching.payload_state import PlanPayloadState
from l2070_batching.post_op import (
    CompiledPostOp,
    PostOpBehavior,
    ResultMaterializationSpec,
    raw_rows_post_op,
)
from l2070_batching.sql_column_type_hints import SqlColumnTypeHints
from l2070_batching.sql_renderable import SqlRenderable
from l2070_batching.step import ServerPlanStep, StepExecutionRole, NonPublishingStep
from l1400_types import ServerPlanRefId
from impl.common.l2070_server_plan.steps._grammar_bridge_provenance import (
    infer_read_tables_from_stmt,
)

if TYPE_CHECKING:
    from l1000_schema.schema_def import DatabaseObjectRow
    from l2070_batching.compilation import CompilationContext, ResolvedRefs


class GrammarRowsResultMode(StrEnum):
    RAW_ROWS = "raw_rows"
    HYDRATE_MANY = "hydrate_many"


def _raw_select_columns(stmt: SqlRenderable) -> tuple[str, ...] | None:
    sql = getattr(stmt, "_sql", None)
    if not isinstance(sql, str):
        return None
    stripped = sql.strip()
    upper = stripped.upper()
    if not upper.startswith("SELECT "):
        return None
    from_index = upper.find(" FROM ")
    if from_index <= len("SELECT "):
        return None
    select_list = stripped[len("SELECT ") : from_index]
    columns: list[str] = []
    for raw_part in select_list.split(","):
        part = raw_part.strip()
        if not part:
            return None
        upper_part = part.upper()
        if " AS " in upper_part:
            part = part[upper_part.rfind(" AS ") + len(" AS ") :].strip()
        elif part == "*" or part.endswith(".*"):
            return None
        elif "." in part:
            part = part.rsplit(".", 1)[-1].strip()
        elif " " in part:
            return None
        columns.append(part.strip('"`[]'))
    return tuple(columns)


def _terminal_grammar_artifacts(stmt: SqlRenderable) -> tuple[CompiledOutputShape, DeclaredResultRelation, SqlColumnTypeHints]:
    from impl.common.l2100_sql_grammar.projection_introspection import (
        extract_statement_projection,
    )

    prerender_info = getattr(stmt, "_query_prerender_info", None)
    prerender_columns = getattr(prerender_info, "result_columns", None)
    if isinstance(prerender_columns, tuple) and prerender_columns:
        return _declared_terminal_grammar_artifacts(prerender_columns)

    declared_projection = getattr(stmt, "terminal_projection_columns", None)
    if callable(declared_projection):
        declared_columns = declared_projection()
        if isinstance(declared_columns, tuple) and declared_columns:
            return _declared_terminal_grammar_artifacts(declared_columns)

    projection = extract_statement_projection(stmt)
    if projection is None or projection.has_star or projection.unresolved or projection.source == "no_returning":
        raw_columns = _raw_select_columns(stmt)
        if raw_columns is not None:
            columns = raw_columns
        else:
            msg = f"Cannot infer terminal grammar projection for {type(stmt).__name__}"
            raise ValueError(msg)
    else:
        columns = tuple(str(column) for column in projection.columns)
    return _declared_terminal_grammar_artifacts(columns)


def _declared_terminal_grammar_artifacts(
    columns: tuple[str, ...],
) -> tuple[CompiledOutputShape, DeclaredResultRelation, SqlColumnTypeHints]:
    """Build terminal row contracts from an explicit backend metadata projection."""
    output_shape = CompiledOutputShape(
        tuple(synthetic_output_field(column, role="terminal_grammar") for column in columns),
    )
    return (
        output_shape,
        DeclaredResultRelation.from_output_shape(output_shape),
        SqlColumnTypeHints(text_columns=frozenset(columns)),
    )


@dataclass(frozen=True, slots=True)
class _GrammarRowsConfig:
    deps: frozenset[ServerPlanRefId] = frozenset()
    batchable: bool = True
    external_params_first: bool = False
    result_mode: GrammarRowsResultMode = GrammarRowsResultMode.RAW_ROWS


class GrammarRowsStep[T](NonPublishingStep[list[T]]):
    """Terminal step that obtains rows from SQL grammar.

    Supports finite closed result modes only. Custom decoding belongs in
    domain-specific builders or lazy-result transforms outside terminal post-op.
    """

    def __init__(
        self: GrammarRowsStep,
        ref_id: ServerPlanRefId,
        stmt: SqlRenderable,
        params: tuple[Any, ...] | None = None,
        model_cls: type[DatabaseObjectRow] | None = None,
        config: _GrammarRowsConfig = _GrammarRowsConfig(),
    ) -> None:
        super().__init__(ref_id)
        self._stmt = stmt
        self._params = params
        self._model_cls = model_cls
        self._deps = config.deps
        self._batchable = config.batchable
        self._external_params_first = config.external_params_first
        self._result_mode = config.result_mode
        self._read_tables = infer_read_tables_from_stmt(stmt)

    @property
    def level(self: GrammarRowsStep) -> int:
        return 0

    def step_tags(self: GrammarRowsStep) -> frozenset[str]:
        return frozenset({"read", "grammar", "rows"})

    def is_read_only(self: GrammarRowsStep) -> bool:
        return True

    def execution_role(self: GrammarRowsStep) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def publishes_executor_visible_binding(self: GrammarRowsStep) -> bool:
        # Grammar rows are a terminal result decoded at runtime (e.g. by
        # DecodeGrammarRowsStep.materialize); no later step consumes them as a
        # SQL-visible CTE, and an arbitrary grammar carries no declarable
        # column contract.
        return False

    def supports_sql_batch_transport(self: GrammarRowsStep) -> bool:
        return self._batchable

    def after_prerequisite_validation_boundary(self: GrammarRowsStep[T]) -> ServerPlanStep[Any]:
        return self.without_batching()

    def without_batching(self: GrammarRowsStep[T]) -> GrammarRowsStep[T]:
        """Return a copy that opts out of batching."""
        return GrammarRowsStep(
            ref_id=self.ref_id,
            stmt=self._stmt,
            params=self._params,
            model_cls=self._model_cls,
            config=_GrammarRowsConfig(
                deps=self._deps,
                batchable=False,
                external_params_first=self._external_params_first,
                result_mode=self._result_mode,
            ),
        )

    def result_cardinality(self: GrammarRowsStep) -> Cardinality:
        return Cardinality.MANY

    def tables_read(self: GrammarRowsStep) -> frozenset[str]:
        return frozenset(self._read_tables)

    def tables_written(self: GrammarRowsStep) -> frozenset[str]:
        """Fetch-all is read-only; no tables written."""
        return frozenset()

    def dependencies(self: GrammarRowsStep) -> frozenset[str]:
        return self._deps

    def sql_visible_dependencies(self: GrammarRowsStep) -> frozenset[str]:
        return frozenset()

    def requires_prior_statement_visibility_after_writes(
        self: GrammarRowsStep,
    ) -> frozenset[str]:
        return self.tables_read()

    def preprocess(self: GrammarRowsStep, resolved: ResolvedRefs) -> None:
        pass

    def internal_plan_ref_state(self: GrammarRowsStep) -> PlanPayloadState:
        return self.internal_plan_ref_state_excluding("_stmt")

    def compile(self: GrammarRowsStep, ctx: CompilationContext) -> CompiledStep:
        from impl.common.l2070_server_plan.steps._grammar_bridge_provenance import (
            build_select_bridge_manifest,
        )

        __opa002_grammar_162 = self._stmt
        output_shape, result_relation, column_type_hints = _terminal_grammar_artifacts(
            __opa002_grammar_162,
        )
        if self._result_mode is GrammarRowsResultMode.HYDRATE_MANY:
            if self._model_cls is None:
                msg = "GrammarRowsResultMode.HYDRATE_MANY requires model_cls"
                raise ValueError(msg)

            closed_post_op = CompiledPostOp.materialize(
                ResultMaterializationSpec(
                    behavior=PostOpBehavior.TERMINAL_ARRAY,
                    model_cls=self._model_cls,
                    input_relation=result_relation,
                ),
            )
        else:
            closed_post_op = raw_rows_post_op()

        provenance_manifest, allow_empty_manifest = build_select_bridge_manifest(
            stmt=self._stmt,
            ctx=ctx,
            row_scope_kind="grammar-rows",
            model_cls=self._model_cls,
            read_tables=self._read_tables,
        )
        return CompiledStep(
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
            grammar=__opa002_grammar_162,
            params=self._params,
            external_params_first=self._external_params_first,
            needs_returning=True,
            closed_post_op=closed_post_op,
            provenance_manifest=provenance_manifest,
            allow_empty_provenance_manifest=allow_empty_manifest,
        )

"""Cached facts for raw row-valued ServerPlan steps."""

from __future__ import annotations

from collections.abc import Sequence
from dataclasses import dataclass

from impl.common.l2070_server_plan.steps._server_ref_identity import duck_server_ref_id
from impl.common.l2100_sql_params.runtime_bind_slot import SqlRuntimeBindSlot
from l1000_schema.json_type import JSONType, unwrap_json_value
from l2055_lazy_result.lazy_result import LazyResult
from l2055_lazy_result.lazy_seq import LazySeq
from l2070_batching.server_ref import (
    ServerRef,
    _dependency_ref_for_symbolic_ref,
    inspect_server_value_shape_for_planning,
    unwrap_literal_sql_value,
)
from l2070_batching.seeded_constants import read_seeded_constant_from_ctx
from l1400_types import ServerPlanRefId

LAZY_KEY = "lazy"
LAZY_SEQ_KEY = "lazy_seq"
RUNTIME_SLOT_KEY = "runtime_slot"
SERVER_REF_KEY = "server_ref"
_NO_LITERAL = object()
_MAX_RAW_CELL_UNWRAP_DEPTH = 16
_PLAIN_LITERAL_CELL_TYPES = {
    type(None),
    bool,
    bytes,
    float,
    int,
    str,
}


@dataclass(frozen=True, slots=True)
class RawCellFact:
    """Classification for one raw row cell."""

    param_value: object
    symbolic_key: tuple[str, str] | None
    dependency_refs: frozenset[str]
    has_deferred_bind_slot: bool = False


@dataclass(frozen=True, slots=True)
class RawColumnFact:
    """Symbolic classification for one raw row column."""

    symbolic_key: tuple[str, str] | None
    mixed_symbolic: bool
    has_deferred_bind_slot: bool

    @property
    def has_symbolic_cells(self: RawColumnFact) -> bool:
        return self.symbolic_key is not None or self.mixed_symbolic


@dataclass(frozen=True, slots=True)
class RawRowFacts:
    """Cached optimizer/lowering facts for raw row payloads."""

    row_count: int
    column_count: int
    dependency_refs: frozenset[str]
    columns: tuple[RawColumnFact, ...]

    @property
    def has_symbolic_cells(self: RawRowFacts) -> bool:
        return any(column.has_symbolic_cells for column in self.columns)

    @property
    def has_runtime_bind_slots(self: RawRowFacts) -> bool:
        return any(column.has_deferred_bind_slot for column in self.columns)


def raw_cell_fact(value: object) -> RawCellFact:
    """Return dependency and symbolic-lowering facts for one raw cell."""
    return _raw_cell_fact(value, unwrap_depth=0)


def _raw_cell_fact(value: object, *, unwrap_depth: int) -> RawCellFact:
    """Return dependency and symbolic-lowering facts while bounding wrapper unwrapping."""
    if unwrap_depth > _MAX_RAW_CELL_UNWRAP_DEPTH:
        msg = "Raw row cell value unwrapping exceeded the maximum recursion depth"
        raise TypeError(msg)
    if isinstance(value, JSONType):
        inner_fact = _raw_cell_fact(unwrap_json_value(value), unwrap_depth=unwrap_depth + 1)
        if inner_fact.symbolic_key is not None:
            return inner_fact
    if isinstance(value, SqlRuntimeBindSlot):
        ref_id = str(value.ref_id)
        symbolic_ref = f"{ref_id}.{value.field_name}" if value.field_name is not None else ref_id
        return RawCellFact(
            param_value=_NO_LITERAL,
            symbolic_key=(RUNTIME_SLOT_KEY, symbolic_ref),
            dependency_refs=frozenset({ref_id}),
            has_deferred_bind_slot=True,
        )
    if isinstance(value, LazyResult | LazySeq | ServerRef):
        shape = inspect_server_value_shape_for_planning(
            value,
            site="raw_cell_fact",
        )
        if shape.symbolic_ref_id is not None:
            ref_id = str(shape.symbolic_ref_id)
            if ref_id.startswith("seed_"):
                found_seed, seed_value = read_seeded_constant_from_ctx(None, ServerPlanRefId(ref_id))
                if found_seed and seed_value is not value:
                    return _raw_cell_fact(seed_value, unwrap_depth=unwrap_depth + 1)
            if isinstance(value, LazySeq):
                key_kind = LAZY_SEQ_KEY
            elif isinstance(value, LazyResult):
                key_kind = LAZY_KEY
            else:
                key_kind = SERVER_REF_KEY
            return RawCellFact(
                param_value=_NO_LITERAL,
                symbolic_key=(key_kind, ref_id),
                dependency_refs=frozenset() if ref_id.startswith("seed_") else shape.dependency_refs,
            )
        if isinstance(value, LazyResult) and getattr(getattr(value, "_state", None), "name", None) == "RESOLVED":
            resolved_value = object.__getattribute__(value, "_value")
            return _raw_cell_fact(resolved_value, unwrap_depth=unwrap_depth + 1)
        if isinstance(value, ServerRef) and value._type_hint is type(None):
            return RawCellFact(
                param_value=None,
                symbolic_key=None,
                dependency_refs=frozenset(),
            )
        type_hint = value._type_hint if isinstance(value, ServerRef) else None
        msg = f"Raw row ServerRef values must carry symbolic ref ids, got type_hint={type_hint!r}"
        raise TypeError(msg)
    duck_ref_id = duck_server_ref_id(value)
    if duck_ref_id is not None:
        return RawCellFact(
            param_value=_NO_LITERAL,
            symbolic_key=(SERVER_REF_KEY, duck_ref_id),
            dependency_refs=(
                frozenset() if duck_ref_id.startswith("seed_") else frozenset({_dependency_ref_for_symbolic_ref(ServerPlanRefId(duck_ref_id))})
            ),
        )
    unwrapped_value = unwrap_literal_sql_value(value)
    if unwrapped_value is not value:
        return _raw_cell_fact(unwrapped_value, unwrap_depth=unwrap_depth + 1)
    return RawCellFact(
        param_value=value,
        symbolic_key=None,
        dependency_refs=frozenset(),
    )


def build_raw_row_facts(rows: Sequence[Sequence[object]]) -> RawRowFacts:
    """Build cached facts with one pass over a raw row payload."""
    row_count = len(rows)
    if row_count == 0:
        return RawRowFacts(
            row_count=0,
            column_count=0,
            dependency_refs=frozenset(),
            columns=(),
        )

    column_count = len(rows[0])
    if _all_plain_literal_cells(rows, column_count):
        return RawRowFacts(
            row_count=row_count,
            column_count=column_count,
            dependency_refs=frozenset(),
            columns=tuple(
                RawColumnFact(
                    symbolic_key=None,
                    mixed_symbolic=False,
                    has_deferred_bind_slot=False,
                )
                for _ in range(column_count)
            ),
        )

    dependency_refs: set[str] = set()
    symbolic_keys: list[tuple[str, str] | None] = [None] * column_count
    literal_seen: list[bool] = [False] * column_count
    mixed_symbolic: list[bool] = [False] * column_count
    has_deferred_bind_slot: list[bool] = [False] * column_count

    for row in rows:
        if len(row) != column_count:
            msg = "Each raw row must match the first row's column count"
            raise ValueError(msg)
        for idx, value in enumerate(row):
            fact = raw_cell_fact(value)
            dependency_refs.update(fact.dependency_refs)
            if fact.has_deferred_bind_slot:
                has_deferred_bind_slot[idx] = True
            key = fact.symbolic_key
            if key is None:
                literal_seen[idx] = True
                if symbolic_keys[idx] is not None:
                    mixed_symbolic[idx] = True
                continue
            if literal_seen[idx]:
                mixed_symbolic[idx] = True
            existing_key = symbolic_keys[idx]
            if existing_key is None:
                symbolic_keys[idx] = key
            elif existing_key != key:
                mixed_symbolic[idx] = True

    return RawRowFacts(
        row_count=row_count,
        column_count=column_count,
        dependency_refs=frozenset(dependency_refs),
        columns=tuple(
            RawColumnFact(
                symbolic_key=symbolic_keys[idx],
                mixed_symbolic=mixed_symbolic[idx],
                has_deferred_bind_slot=has_deferred_bind_slot[idx],
            )
            for idx in range(column_count)
        ),
    )


def _all_plain_literal_cells(rows: Sequence[Sequence[object]], column_count: int) -> bool:
    for row in rows:
        if len(row) != column_count:
            msg = "Each raw row must match the first row's column count"
            raise ValueError(msg)
        if any(type(value) not in _PLAIN_LITERAL_CELL_TYPES for value in row):
            return False
    return True


def raw_row_fingerprint(facts: RawRowFacts) -> tuple[object, ...]:
    """Return the value-independent raw row shape used by planning caches."""
    return (
        facts.row_count,
        facts.column_count,
        tuple(sorted(facts.dependency_refs)),
        tuple(
            (
                column.symbolic_key,
                column.mixed_symbolic,
                column.has_deferred_bind_slot,
            )
            for column in facts.columns
        ),
    )


def no_literal_sentinel() -> object:
    """Return the sentinel used for non-literal raw cell facts."""
    return _NO_LITERAL

