)


type WorkspaceNonceValue = bytes | None


def _row_value(row: object, column_name: SqlColumnName) -> object:
    if isinstance(row, Mapping):
        return row.get(column_name)
    mapping = getattr(row, "_mapping", None)
    if isinstance(mapping, Mapping):
        return mapping.get(column_name)
    get_item = getattr(row, "__getitem__", None)
    if callable(get_item):
        try:
            return get_item(column_name)
        except (KeyError, IndexError, TypeError, AttributeError):
            pass
    return getattr(row, column_name, None)


def materialize_workspace_nonce(spec: WorkspaceNonceDecoderSpec, raw: RawResult) -> WorkspaceNonceValue:
    if not raw:
        if spec.require_row:
            msg = "No FTS secret exists for this workspace"
            raise ValueError(msg)
        return None
    value = _row_value(raw[0], SqlColumnName(spec.column_name))
    if not isinstance(value, bytes):
        msg = f"Workspace secret materialization requires canonical bytes, got {type(value).__name__}."
        raise TypeError(msg)
    if len(value) < 16:
        msg = f"Workspace secret nonce must contain at least 16 bytes, got {len(value)}."
        raise ValueError(msg)
    return value


@dataclass(frozen=True, slots=True)
class _WorkspaceNonceProjectConfig:
    source_ref: ServerPlanRefId
    require_row: bool = False
    materialize_source: bool = False


class _WorkspaceNonceProjectStepCteRow(BaseModel):
    fts_nonce: bytes


class WorkspaceNonceProjectStep(SqlRelationPublisherStep[WorkspaceNonceValue]):
    """Project a normalized workspace FTS nonce from SQL-visible rows."""

    def __init__(
        self: WorkspaceNonceProjectStep,
        ref_id: ServerPlanRefId,
        config: _WorkspaceNonceProjectConfig,
    ) -> None:
        super().__init__(ref_id)
        self._source_ref = config.source_ref
        self._require_row = config.require_row
        self._materialize_source = config.materialize_source

    @property
    def level(self: WorkspaceNonceProjectStep) -> int:
        return 0

    def result_cardinality(self: WorkspaceNonceProjectStep) -> Cardinality:
        return Cardinality.ONE

    def declares_consumed_rows_reduction(self: WorkspaceNonceProjectStep) -> bool:
        return True

    def is_read_only(self: WorkspaceNonceProjectStep) -> bool:
        return True

    def execution_role(self: WorkspaceNonceProjectStep) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def requires_materialized_inputs(self: WorkspaceNonceProjectStep) -> bool:
        return self._materialize_source

    def requires_prior_step_boundary(self: WorkspaceNonceProjectStep) -> bool:
        return self._materialize_source

    def step_tags(self: WorkspaceNonceProjectStep) -> frozenset[str]:
        return frozenset({"read", "projection", "workspace_nonce", "sql_visible"})

    def dependencies(self: WorkspaceNonceProjectStep) -> frozenset[str]:
        return frozenset({str(self._source_ref)})

    def imported_dependency_refs(self: WorkspaceNonceProjectStep) -> frozenset[ServerPlanRefId]:
        return frozenset({self._source_ref})

    def consumes_executor_visible_dependencies(self: WorkspaceNonceProjectStep) -> bool:
        return True

    def tables_read(self: WorkspaceNonceProjectStep) -> frozenset[str]:
        return frozenset()

    def tables_written(self: WorkspaceNonceProjectStep) -> frozenset[str]:
        return frozenset()

    def cte_publication_contract(self: WorkspaceNonceProjectStep) -> CtePublicationContract:
        columns = ("fts_nonce",)
        column_type_hints = SqlColumnTypeHints(bytea_columns=frozenset({"fts_nonce"}))
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        _contract_model_cls = _WorkspaceNonceProjectStepCteRow
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=tuple(str(column) for column in columns),
            column_type_hints=column_type_hints,
            model_cls=_contract_model_cls,
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def compile(self: WorkspaceNonceProjectStep, ctx: CompilationContext) -> CompiledStep[WorkspaceNonceValue]:
        source_cte = ctx.cte_refs.get(str(self._source_ref))
        if not isinstance(source_cte, CteReference):
            raise_missing_cte_fallback_forbidden(
                site_name=type(self).__name__,
                trigger=(
                    f"workspace nonce source {self._source_ref!s} has no published CTE binding; "
                    f"available CTE refs={tuple(sorted(str(ref) for ref in ctx.cte_refs))!r}"
                ),
                blocked_path="workspace nonce projection cannot read a Python runtime ref during SQL compilation.",
                result_contract="workspace nonce projection must consume an explicit SQL-visible nonce rowset.",
                implementation_requirements=(
                    "Ensure the upstream nonce producer publishes a SQL-visible CTE binding before this step compiles.",
                    "Keep nonce extraction in SQL instead of reconstructing it from runtime refs.",
                ),
            )
        auxiliary_ctes = [(source_cte.ref_id, source_cte.auxiliary_query)] if source_cte.auxiliary_query is not None else None
        __opa002_grammar_142 = SqlDynamicSelectStmt(
            from_table=SqlTableName(source_cte.ref_id),
            columns=[SqlColumnName("fts_nonce")],
            limit=1,
        )
        output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(
            self.cte_publication_contract(),
        )
        return CompiledStep(
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
            grammar=__opa002_grammar_142,
            needs_returning=True,
            auxiliary_ctes=auxiliary_ctes,
            closed_post_op=CompiledPostOp.materialize(
                ResultMaterializationSpec(
                    behavior=PostOpBehavior.TERMINAL_OBJECT,
                    domain_decoder=workspace_nonce_decoder(require_row=self._require_row),
                ),
            ),
        )


@pure_lazy
def workspace_nonce_project_lazy[T](
    txn: ReadTransactionLazyMixin,
    source: LazyResult[T],
    *,
    require_row: bool = False,
    materialize_source: bool = False,
) -> LazyResult[WorkspaceNonceValue]:
    dependencies = tuple(sorted(source.dependencies()))
    if len(dependencies) != 1:
        msg = "workspace nonce projection requires exactly one SQL-visible source dependency"
        raise TypeError(msg)
    ref_id = ServerPlanRefId(next_lazy_plan_ref(txn))
    return enqueue_lazy_plan_intent(
        txn,
        WorkspaceNonceProjectStep(
            ref_id,
            _WorkspaceNonceProjectConfig(
                source_ref=ServerPlanRefId(dependencies[0]),
                require_row=require_row,
                materialize_source=materialize_source,
            ),
        ),
    )

"""SQL-visible insert authorization for a proposed literal row."""

from __future__ import annotations

from dataclasses import replace
from typing import TYPE_CHECKING

from l1000_schema.schema_def import DatabaseObjectRow, get_table_name
from l1400_types import ServerPlanRefId
from l2070_batching.backend_profile import ServerPlanBackendProfile
from l1100_exceptions.exceptions import PermissionCompilationError, PermissionError as DbPermissionError
from l4000_permissions.permission_registry import has_permission_scheme
from l2070_batching.compilation import (
    CompilationContext,
    CompiledStep,
    compiled_artifacts_from_cte_publication_contract,
)
from l2070_batching.step import CtePublicationContract, CteRelationContract, StepExecutionRole
from impl.common.l2070_server_plan.steps.return_value import ReturnValueStep
from impl.common.l2070_server_plan.steps.runtime_ref_projection import (
    runtime_object_write_permission_literal_assertion_compiled_step,
    runtime_object_sequence_write_permission_assertion_compiled_step,
    runtime_object_write_permission_passthrough_assertion_compiled_step,
)

if TYPE_CHECKING:
    from l4000_permissions.session_context import ResolvedSessionContext

from impl.common.l2070_server_plan.steps.sql_error_gate import (
    SqlAssertionResultRow,
    sql_assertion_column_type_hints,
    sql_assertion_output_shape,
)


class InsertPermissionAssertionStep(ReturnValueStep[None]):
    """Require insert authority without relying on legacy object-write flags."""

    def __init__(
        self: InsertPermissionAssertionStep,
        ref_id: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        instance: DatabaseObjectRow | None = None,
        *,
        source_ref: ServerPlanRefId | None = None,
        source_is_sequence: bool = False,
        permission_context_ref: ServerPlanRefId | None = None,
        permission_context_type: type[ResolvedSessionContext] | None = None,
    ) -> None:
        super().__init__(ref_id, None)
        if (instance is None) == (source_ref is None):
            raise ValueError("Insert authorization requires exactly one proposed-row source")
        self._model_cls = model_cls
        self._instance = instance
        self._source_ref = source_ref
        self._source_is_sequence = source_is_sequence
        self._permission_context_ref = permission_context_ref
        self._permission_context_type = permission_context_type

    @property
    def model_cls(self: InsertPermissionAssertionStep) -> type[DatabaseObjectRow]:
        """Return the model whose proposed rows require insert authority."""
        return self._model_cls

    def proposed_insert_table(self: InsertPermissionAssertionStep) -> str:
        """Identify the authorization target without claiming a physical write."""
        return get_table_name(self._model_cls)

    def dependencies(self: InsertPermissionAssertionStep) -> frozenset[str]:
        return frozenset(str(ref) for ref in (self._source_ref, self._permission_context_ref) if ref is not None)

    def imported_dependency_refs(self: InsertPermissionAssertionStep) -> frozenset[ServerPlanRefId]:
        return frozenset(ref for ref in (self._source_ref, self._permission_context_ref) if ref is not None)

    def consumes_executor_visible_dependencies(self: InsertPermissionAssertionStep) -> bool:
        return self._source_ref is not None

    def execution_role(self: InsertPermissionAssertionStep) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def is_executor_owned_runtime_step(self: InsertPermissionAssertionStep) -> bool:
        return False

    def is_runtime_assertion(self: InsertPermissionAssertionStep) -> bool:
        return False

    def requires_assertion_statement_transport(self: InsertPermissionAssertionStep) -> bool:
        return True

    def _native_assertion_aborts_before_commit(
        self: InsertPermissionAssertionStep,
        backend_profile: ServerPlanBackendProfile,
    ) -> bool:
        del backend_profile
        return True

    def native_assertion_error(self: InsertPermissionAssertionStep) -> Exception:
        from l4000_permissions.permission_enforcement import _try_get_permission_scheme

        scheme = _try_get_permission_scheme(self._model_cls)
        if scheme is not None and type(scheme).__name__ == "SystemOnlyScheme":
            return DbPermissionError(
                f"Cannot write to {self._model_cls.__name__}: SystemOnlyScheme requires system session",
            )
        return DbPermissionError(f"{self._model_cls.__name__} object write denied")

    def supports_sql_batch_transport(self: InsertPermissionAssertionStep) -> bool:
        return True

    def allows_later_sql_transport(self: InsertPermissionAssertionStep) -> bool:
        return True

    def supports_ordered_sql_statement_batch(self: InsertPermissionAssertionStep) -> bool:
        return True

    def ordered_statement_sql_visible_dependencies(
        self: InsertPermissionAssertionStep,
    ) -> frozenset[str]:
        return self.dependencies()

    def requires_materialized_inputs(self: InsertPermissionAssertionStep) -> bool:
        return False

    def cte_publication_contract(self: InsertPermissionAssertionStep) -> CtePublicationContract:
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=tuple(str(column) for column in sql_assertion_output_shape().cte_output_columns),
            column_type_hints=sql_assertion_column_type_hints(),
            model_cls=SqlAssertionResultRow,
            relation_contract=CteRelationContract.semantic_row(SqlAssertionResultRow),
            relation_role=self.cte_relation_role(),
            source_tables=None,
        )

    def compile(self: InsertPermissionAssertionStep, ctx: CompilationContext) -> CompiledStep[None]:
        if (
            self._model_cls.__module__ == "l6500_evidence.capability_models"
            and self._model_cls.__name__
            in {
                "CapabilitySecurityEvent",
                "CapabilityTokenFamily",
                "CapabilityTokenIssued",
                "CapabilityTokenRevocation",
                "CapabilityTokenUsage",
            }
            and ctx.capability_lifecycle_admin_authority is not None
        ):
            output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(
                self.cte_publication_contract(),
            )
            return CompiledStep(
                output_shape=output_shape,
                result_relation=result_relation,
                column_type_hints=column_type_hints,
                closed_post_op=self._validated_literal_post_op_for_value(),
            )
        if not has_permission_scheme(self._model_cls):
            raise PermissionCompilationError("Insert authorization requires a registered permission scheme")
        if self._source_ref is not None and self._source_is_sequence:
            compiled = runtime_object_sequence_write_permission_assertion_compiled_step(
                str(self._source_ref),
                ctx=ctx,
                permission_context_ref=self._permission_context_ref,
                permission_context_type=self._permission_context_type,
                model_cls=self._model_cls,
                action="insert",
            )
        elif self._source_ref is not None:
            compiled = runtime_object_write_permission_passthrough_assertion_compiled_step(
                str(self._source_ref),
                ctx=ctx,
                permission_context_ref=self._permission_context_ref,
                permission_context_type=self._permission_context_type,
                model_cls=self._model_cls,
                action="insert",
            )
        else:
            assert self._instance is not None
            compiled = runtime_object_write_permission_literal_assertion_compiled_step(
                self._instance,
                ctx=ctx,
                result_ref_id=str(self.ref_id),
                permission_context_ref=self._permission_context_ref,
                permission_context_type=self._permission_context_type,
                model_cls=self._model_cls,
                action="insert",
            )
        assert compiled.grammar is not None
        if not ctx.backend_profile.traits.requires_insert_assertion_transport_query:
            return compiled
        from impl.common.l2100_sql_grammar.domain.infra.expr_assertion import (
            SqlAssertionTransportQuery,
        )

        return replace(
            compiled,
            grammar=SqlAssertionTransportQuery(
                compiled.grammar,
                label=f"insert_permission:{self.ref_id}",
            ),
        )

"""Data-layer-only execution reproduction for sparse publication scan amplification."""
from __future__ import annotations

import sqlite3
from uuid import UUID
from dataclasses import replace

import pytest

from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName, SqlIndexName, SqlTableName
from impl.common.l2070_server_plan.steps.edge_constraint_steps import (
    CheckDanglingEdgesBatchStep, _BatchedDanglingEdgeEntry, _BatchedDanglingEdgeValidationConfig,
)
from impl.common.l2070_server_plan.steps.tests.test_publication_candidate_execution import (
    EDGE_COLUMNS, NODE_COLUMNS, STAGED_COLUMNS, _create, _execute, _insert,
)
from impl.common.l2070_server_plan.tests.testkit import make_backend_profile, make_compilation_context
from impl.common.l2100_sql_grammar.tree.identifiers import SqlQuotedIdentifier, SqlTableIdent
from impl.common.l2100_sql_grammar.tree.statements import SqlCreateIndex
from l1200_versioned_ids import BranchId, RevisionId, StagedCommitId
from l1400_types import BackendType, RowId, ServerPlanRefId
from impl.common.l2200_sql_dialect.sql_dialect import SqliteDialect
from l2070_batching.server_ref import ServerRefs
from l2070_batching.staged_source import BranchScopeToken, PublishScopeDescriptor


def exercise_sparse_publication_validation_work_is_selected_endpoint_bounded(
    unrelated_rows: int, missing_endpoint: bool, change: str, growth_axis: str,
    selected_edge_count: int,
) -> None:
    branch, revision, selected = BranchId.new(), RevisionId.new(), StagedCommitId.new()
    b, r, s = str(branch), str(revision), str(selected)
    sparse_columns = (*EDGE_COLUMNS, "sys_valid_from_revision_id", "sys_valid_to_revision_id", "sys_deleted")
    node_columns = (
        "branch_id", "sys_id", "graph_sys_id",
        "sys_valid_from_seq", "sys_valid_to_seq", "sys_deleted",
    )
    conn = sqlite3.connect(":memory:")
    try:
        _create(conn, "sys_revision_physical_keys", ("sys_id", "revision_sys_id"))
        _insert(conn, "sys_revision_physical_keys", ("sys_id", "revision_sys_id"), [("1", r)])
        _create(conn, "sys_revision_parents", ("revision_sys_id", "parent_revision_sys_id"))
        for name, columns in (("edges_sparse", sparse_columns), ("edges_staged", STAGED_COLUMNS),
                              ("nodes_sparse", node_columns), ("nodes_staged", NODE_COLUMNS)):
            _create(conn, name, columns)
            index_columns = ("branch_id", "sys_staged_commit_id") if name.endswith("_staged") else ("branch_id", "sys_id")
            _execute(conn, SqlCreateIndex(
                SqlQuotedIdentifier(SqlIndexName(name + "_lookup")), SqlTableIdent(SqlTableName(name)),
                tuple(SqlQuotedIdentifier(SqlColumnName(c)) for c in index_columns),
            ))
        for endpoint in ("source_sys_id", "target_sys_id"):
            _execute(conn, SqlCreateIndex(
                SqlQuotedIdentifier(SqlIndexName("sparse_" + endpoint)), SqlTableIdent(SqlTableName("edges_sparse")),
                tuple(SqlQuotedIdentifier(SqlColumnName(c)) for c in ("branch_id", "graph_sys_id", endpoint, "sys_id")),
            ))
            _execute(conn, SqlCreateIndex(
                SqlQuotedIdentifier(SqlIndexName("sparse_any_graph_" + endpoint)),
                SqlTableIdent(SqlTableName("edges_sparse")),
                tuple(SqlQuotedIdentifier(SqlColumnName(c)) for c in (endpoint, "sys_id")),
            ))
        _insert(conn, "nodes_sparse", node_columns, [
            (b, node, "graph", "1", None, 0) for node in ("source", "target")
            if not missing_endpoint or node != "source"
        ] + [
            (b, f"node-{i}", "graph", "1", None, 0)
            for i in range(unrelated_rows if growth_axis in {"nodes", "both"} else 0)
        ])
        _insert(conn, "edges_sparse", sparse_columns, [
            (b, f"edge-{i}", "graph", f"node-{i}", "target", "Contains", r, None, 0)
            for i in range(unrelated_rows if growth_axis in {"edges", "both"} else 0)
        ])
        if growth_axis == "foreign-staging":
            foreign = str(StagedCommitId.new())
            _insert(conn, "nodes_staged", NODE_COLUMNS, [
                (b, f"foreign-node-{i}", "graph", foreign, i, 1)
                for i in range(unrelated_rows)
            ])
            _insert(conn, "edges_staged", STAGED_COLUMNS, [
                (b, f"foreign-edge-{i}", "graph", "source", "target", "Contains", foreign, i, 0)
                for i in range(unrelated_rows)
            ])
        if change in {"update", "delete-node", "delete-edge"}:
            _insert(conn, "edges_sparse", sparse_columns, [
                (b, f"selected-edge-{i}", "graph", "old-source" if change == "update" else "source", "target", "Contains", r, None, 0)
                for i in range(selected_edge_count)
            ])
        if change != "delete-node":
            _insert(conn, "edges_staged", STAGED_COLUMNS, [
                (b, f"selected-edge-{i}", "graph", "source", "target", "Contains", s, i, int(change == "delete-edge"))
                for i in range(selected_edge_count)
            ])
        else:
            _insert(conn, "nodes_staged", NODE_COLUMNS, [(b, "source", "graph", s, 0, 1)])
        if change == "foreign-delete":
            _insert(conn, "nodes_staged", NODE_COLUMNS, [(b, "source", "graph", str(StagedCommitId.new()), 0, 1)])
        selected_commits: tuple[str, ...] = (s,)
        if change == "node-tombstone":
            newer = str(StagedCommitId.new())
            selected_commits = (s, newer)
            _insert(conn, "nodes_staged", NODE_COLUMNS, [
                (b, "source", "graph", s, 0, 0), (b, "source", "graph", newer, 1, 1),
            ])
        scope = PublishScopeDescriptor(kind="explicit", branch_scope_token=BranchScopeToken("sparse-repro"), staged_commit_ids=selected_commits)
        step = CheckDanglingEdgesBatchStep(
            ServerPlanRefId("sparse_repro"), lazy_branch=ServerRefs.scalar(branch),
            config=_BatchedDanglingEdgeValidationConfig(
                entries=(_BatchedDanglingEdgeEntry(
                    edge_sparse_table=SqlTableName("edges_sparse"), edge_staged_table=SqlTableName("edges_staged"),
                    edge_base_table=SqlTableName("edges"), publish_scope=scope,
                ),),
                node_sparse_tables=(SqlTableName("nodes_sparse"),),
                node_staged_tables=(SqlTableName("nodes_staged"),), revision_id_raw=revision,
            ),
        )
        compiled = step.compile(replace(make_compilation_context(make_backend_profile(BackendType.SQLITE)), branch_tip_materialized=True))
        assert compiled.grammar is not None
        instructions = 0

        def progress() -> int:
            nonlocal instructions
            instructions += 100
            return 0

        conn.set_progress_handler(progress, 100)
        try:
            rows = _execute(conn, compiled.grammar).fetchall()
        finally:
            conn.set_progress_handler(None, 0)
        invalid = change in {"delete-node", "node-tombstone"} or (missing_endpoint and change != "delete-edge")
        expected = [("edges", "dangling", "source", "target")] if invalid else []
        assert rows == expected
        print({"growth_axis": growth_axis, "unrelated_rows": unrelated_rows, "sqlite_instructions": instructions, "selected_edges": selected_edge_count})
        work_bound = 50_000 + 5_000 * (selected_edge_count - 1)
        if instructions > work_bound:
            dialect = SqliteDialect()
            sql, params = (dialect.render_explain_prefix(False, None) + compiled.grammar.render(dialect)).to_sql(dialect)
            print(conn.execute(sql, tuple(str(p) if isinstance(p, RowId | UUID | BranchId | RevisionId | StagedCommitId) else p for p in params)).fetchall())
        assert instructions <= work_bound, "Publication work must scale with selected edges, not unrelated rows"
    finally:
        conn.close()


@pytest.mark.parametrize("unrelated_rows", [0, 1024, 8192])
@pytest.mark.parametrize("growth_axis", ["nodes", "edges", "both", "foreign-staging"])
@pytest.mark.parametrize("missing_endpoint", [False, True])
@pytest.mark.parametrize("change", ["insert", "update", "delete-node", "delete-edge", "foreign-delete", "node-tombstone"])
def test_sparse_publication_validation_work_is_selected_endpoint_bounded(
    unrelated_rows: int,
    missing_endpoint: bool,
    change: str,
    growth_axis: str,
) -> None:
    for selected_edge_count in (1, 16, 128):
        exercise_sparse_publication_validation_work_is_selected_endpoint_bounded(
            unrelated_rows, missing_endpoint, change, growth_axis, selected_edge_count,
        )

"""LargeColumnRefCountStep: post-write step for content store ref counts.

After a DELETE or UPDATE that changes a large column value, the reference
count on the old content hash must be adjusted. For DELETE, the old hash's
ref_count is decremented. For UPDATE where the content changed, the old
hash is decremented and the new hash is incremented (the increment is
handled by ``LargeColumnSpillStep``).

This step runs after the main write completes, so the old row data is
available for extracting the previous content hashes.

Grammar classes used:

* ``SqlContentStoreRefCountUpdate`` — adjusts ref_count by a delta
* ``SqlDeleteContentStoreByRefCount`` — garbage collects entries with
  ref_count <= 0 (optional, can be deferred to background cleanup)
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import TYPE_CHECKING

from impl.common.l2050_sql_types.sql_branded_types import ContentHashValue, SqlTableName
from impl.common.l2070_server_plan.param_budget import rows_per_fused_sql_statement
from l1400_types import ServerPlanRefId
from l2070_batching.backend_profile import ContentStoreMutationTransport
from l2070_batching.cardinality import Cardinality
from l2070_batching.compilation import CompiledStep
from l2070_batching.step import ServerPlanStep, StepExecutionRole, ContractedSqlProducerStep, NonPublishingStep

if TYPE_CHECKING:
    from l2070_batching.compilation import CompilationContext

_CONTENT_STORE_REFCOUNT_UPDATE_PARAMS_PER_ROW = 2


@dataclass(frozen=True)
class _LargeColumnRefCountConfig:
    content_hash: ContentHashValue
    delta: int
    write_ref_id: ServerPlanRefId


@dataclass(frozen=True)
class _BatchedLargeColumnRefCountConfig:
    rows: list[tuple[ContentHashValue, int]]
    depends_on: frozenset[ServerPlanRefId]


def _coalesce_refcount_rows(
    rows: list[tuple[ContentHashValue, int]],
) -> list[tuple[ContentHashValue, int]]:
    """Collapse duplicate hashes and remove zero-delta work before SQL compilation."""
    deltas_by_hash: dict[ContentHashValue, int] = {}
    for content_hash, delta in rows:
        deltas_by_hash[content_hash] = deltas_by_hash.get(content_hash, 0) + delta
    return [(content_hash, delta) for content_hash, delta in deltas_by_hash.items() if delta != 0]


class LargeColumnRefCountStep(NonPublishingStep[None]):
    """Decrement large column reference counts after delete/update.

    After a write that removes or replaces a large column value, the old
    content hash's ref_count in the content store must be decremented.
    Uses ``SqlContentStoreRefCountUpdate`` grammar.

    The lowering phase that creates this step extracts the old content
    hashes from the row being deleted/updated and creates one step per
    hash that needs ref_count adjustment.

    Attributes:
        _store_table: Content store table name.
        _content_hash: The content hash whose ref_count is being adjusted.
        _delta: Amount to add to ref_count (negative for decrement).
        _write_ref_id: ref_id of the preceding write step this depends on.
    """

    def __init__(
        self: LargeColumnRefCountStep,
        ref_id: ServerPlanRefId,
        store_table: SqlTableName,
        config: _LargeColumnRefCountConfig,
    ) -> None:
        super().__init__(ref_id)
        self._store_table: SqlTableName = store_table
        self._content_hash = config.content_hash
        self._delta = config.delta
        self._write_ref_id = config.write_ref_id

    @property
    def level(self: LargeColumnRefCountStep) -> int:
        return 0

    def is_read_only(self: LargeColumnRefCountStep) -> bool:
        return False  # UPDATEs content store ref_count

    def result_cardinality(self: LargeColumnRefCountStep) -> Cardinality:
        return Cardinality.NONE

    def execution_role(self: LargeColumnRefCountStep) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def step_tags(self: LargeColumnRefCountStep) -> frozenset[str]:
        return frozenset({"large_column", "refcount", "grammar"})

    def dependencies(self: LargeColumnRefCountStep) -> frozenset[str]:
        return frozenset({str(self._write_ref_id)})

    def tables_read(self: LargeColumnRefCountStep) -> frozenset[str]:
        """Ref count adjustment does not read tables."""
        return frozenset()

    def tables_written(self: LargeColumnRefCountStep) -> frozenset[str]:
        return frozenset({str(self._store_table)})

    def compile(self: LargeColumnRefCountStep, ctx: CompilationContext) -> CompiledStep[None]:
        """Compile to a content store ref_count update grammar.

        Produces ``SqlContentStoreRefCountUpdate`` which handles
        dialect-aware UPDATE of the ref_count column.
        """
        from impl.common.l2100_sql_grammar.domain.infra.stmt_content_store import (
            SqlContentStoreRefCountUpdate,
        )

        grammar = SqlContentStoreRefCountUpdate(
            table=self._store_table,
            content_hash=self._content_hash,
            count=self._delta,
        )

        return CompiledStep(grammar=grammar)


class BatchedLargeColumnRefCountStep(NonPublishingStep[None]):
    """Adjust many content-store ref counts in batched PostgreSQL statements."""

    def __init__(
        self: BatchedLargeColumnRefCountStep,
        ref_id: ServerPlanRefId,
        store_table: SqlTableName,
        config: _BatchedLargeColumnRefCountConfig,
    ) -> None:
        super().__init__(ref_id)
        self._store_table = store_table
        self._rows = config.rows
        self._depends_on = config.depends_on

    @property
    def level(self: BatchedLargeColumnRefCountStep) -> int:
        return 0

    def is_read_only(self: BatchedLargeColumnRefCountStep) -> bool:
        return False

    def result_cardinality(self: BatchedLargeColumnRefCountStep) -> Cardinality:
        return Cardinality.NONE

    def execution_role(self: BatchedLargeColumnRefCountStep) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def step_tags(self: BatchedLargeColumnRefCountStep) -> frozenset[str]:
        return frozenset({"large_column", "refcount", "grammar"})

    def dependencies(self: BatchedLargeColumnRefCountStep) -> frozenset[str]:
        return self._depends_on

    def tables_read(self: BatchedLargeColumnRefCountStep) -> frozenset[str]:
        return frozenset()

    def tables_written(self: BatchedLargeColumnRefCountStep) -> frozenset[str]:
        return frozenset({str(self._store_table)})

    def has_unbounded_params(self: BatchedLargeColumnRefCountStep) -> bool:
        return False

    def estimated_param_count(self: BatchedLargeColumnRefCountStep) -> int | None:
        return len(_coalesce_refcount_rows(self._rows)) * _CONTENT_STORE_REFCOUNT_UPDATE_PARAMS_PER_ROW

    def compile(
        self: BatchedLargeColumnRefCountStep,
        ctx: CompilationContext,
    ) -> CompiledStep[None]:
        if ctx.backend_profile.traits.content_store_mutation_transport is not ContentStoreMutationTransport.REFCOUNT_THEN_INSERT:
            msg = "BatchedLargeColumnRefCountStep requires refcount-then-insert transport"
            raise ValueError(msg)

        from impl.common.l2100_sql_grammar.domain.infra.stmt_compound_write import (
            SqlStatementBatch,
            SqlStatementBatchCategory,
        )
        from impl.common.l2100_sql_grammar.domain.infra.stmt_content_store import (
            SqlBatchedContentStoreRefCountUpdate,
        )

        rows = _coalesce_refcount_rows(self._rows)
        if not rows:
            return CompiledStep()

        rows_per_stmt = rows_per_fused_sql_statement(
            ctx.backend_type,
            _CONTENT_STORE_REFCOUNT_UPDATE_PARAMS_PER_ROW,
            len(rows),
            capacity=ctx.sql_statement_capacity,
        )
        if 0 < rows_per_stmt < len(rows):
            statements = [
                SqlBatchedContentStoreRefCountUpdate(
                    table=self._store_table,
                    rows=rows[start : start + rows_per_stmt],
                )
                for start in range(0, len(rows), rows_per_stmt)
            ]
            return CompiledStep(
                grammar=SqlStatementBatch(
                    statements,
                    category=SqlStatementBatchCategory.BUDGET_SPLIT,
                ),
            )

        return CompiledStep(
            grammar=SqlBatchedContentStoreRefCountUpdate(
                table=self._store_table,
                rows=rows,
            ),
        )

"""Raw-row variant of ``SelectOneByQueryStep``."""

from __future__ import annotations

from dataclasses import replace
from typing import TYPE_CHECKING, Any, cast

from l1000_schema.table_utils import get_table_name
from l2070_batching.cardinality import Cardinality
from l2070_batching.compilation import CompiledStep, compiled_artifacts_from_cte_publication_contract
from l2070_batching.sql_column_type_hints import SqlColumnTypeHints
from l2070_batching.step import (
    CtePublicationContract,
    ContractedSqlProducerStep,
    ServerPlanStep,
    SqlRelationPublisherStep,
    cte_projection_row_model,
)
from l1400_types import ServerPlanRefId

if TYPE_CHECKING:
    from l1000_schema.schema_def import DatabaseObjectRow
    from l2070_batching.compilation import CompilationContext
    from impl.common.l2060_query_spec.query_spec import QuerySpec


class SelectOneByQueryRawStep(SqlRelationPublisherStep[dict[str, Any] | None]):
    """Execute a query spec and return the first raw row or ``None``."""

    def __init__(
        self: SelectOneByQueryRawStep,
        ref_id: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        query_spec: QuerySpec[Any],
        *,
        user_id_ref_id: ServerPlanRefId | None = None,
    ) -> None:
        super().__init__(ref_id)
        self._model_cls = model_cls
        self._query_spec = query_spec
        self._user_id_ref_id = user_id_ref_id
        self._compiled_output_columns: tuple[str, ...] | None = None
        self._compiled_column_type_hints: SqlColumnTypeHints | None = None

    @property
    def level(self: SelectOneByQueryRawStep) -> int:
        return 0

    def step_tags(self: SelectOneByQueryRawStep) -> frozenset[str]:
        return frozenset({"read", "select_one", "query", "raw"})

    def is_read_only(self: SelectOneByQueryRawStep) -> bool:
        return True

    def result_cardinality(self: SelectOneByQueryRawStep) -> Cardinality:
        return Cardinality.ONE

    def tables_read(self: SelectOneByQueryRawStep) -> frozenset[str]:
        return frozenset({get_table_name(self._model_cls)})

    def tables_written(self: SelectOneByQueryRawStep) -> frozenset[str]:
        return frozenset()

    def cte_publication_contract(self: SelectOneByQueryRawStep) -> CtePublicationContract:
        def _legacy_cte_output_columns() -> tuple[str, ...]:
            if self._compiled_output_columns is not None:
                return self._compiled_output_columns
            from impl.common.l2070_server_plan.steps.query_execute import (
                _query_spec_cte_output_columns,
            )

            return _query_spec_cte_output_columns(self._model_cls, self._query_spec)

        columns = _legacy_cte_output_columns()

        def _legacy_cte_column_type_hints(columns: tuple[str, ...] | None) -> SqlColumnTypeHints:
            assert columns is not None
            if self._compiled_column_type_hints is not None:
                return self._compiled_column_type_hints
            from impl.common.l2070_server_plan.steps.query_execute import (
                _query_spec_column_type_hints,
            )

            return _query_spec_column_type_hints(self._model_cls, self._query_spec, columns)

        column_type_hints = _legacy_cte_column_type_hints(columns)
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        from impl.common.l2070_server_plan.steps.query_execute import (
            _needs_inline_large_column_hydration,
        )

        if _needs_inline_large_column_hydration(self._model_cls, self._query_spec, raw_mode=True):
            from impl.common.l2070_server_plan.steps.large_column_read import (
                _inline_large_column_output_shape,
                inline_large_column_sql_column_type_hints,
            )
            from l2070_batching.output_shape import CompiledOutputShape, synthetic_output_field
            from l2070_batching.sql_column_type_hints import combine_sql_column_type_hints

            inline_shape = _inline_large_column_output_shape(
                CompiledOutputShape(tuple(synthetic_output_field(column) for column in columns)),
                self._model_cls,
                include_pointer_columns=False,
            )
            if inline_shape is None:
                msg = f"{type(self).__name__} could not derive inline large-column output shape."
                raise TypeError(msg)
            base_columns = columns
            columns = inline_shape.cte_output_columns
            column_type_hints = combine_sql_column_type_hints(
                columns,
                column_type_hints.filtered(set(base_columns)),
                inline_large_column_sql_column_type_hints(self._model_cls),
            ).require_complete(columns)
        _contract_model_cls = cte_projection_row_model(
            f"{self._model_cls.__name__}SelectOneByQueryRawRow",
            columns,
            column_type_hints,
        )
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=tuple(str(column) for column in columns),
            column_type_hints=column_type_hints,
            model_cls=_contract_model_cls,
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
            empty_result_allowed=True,
        )

    def always_publishes_executor_visible_binding(self: SelectOneByQueryRawStep) -> bool:
        return True

    def dependencies(self: SelectOneByQueryRawStep) -> frozenset[str]:
        deps = {str(self._user_id_ref_id)} if self._user_id_ref_id is not None else set()
        from impl.common.l2070_server_plan.steps._resolve import collect_query_spec_deps

        deps.update(collect_query_spec_deps(self._query_spec))
        return frozenset(deps)

    def compile(self: SelectOneByQueryRawStep, ctx: CompilationContext) -> CompiledStep[dict[str, Any] | None]:
        from impl.common.l2070_server_plan.steps.query_execute import (
            _build_query_first_raw_post_op,
            compile_sql_query_execute_step,
        )
        from impl.common.l2070_server_plan.steps.query_execute_raw import (
            _normalize_raw_select_one_sys_id_filter,
        )

        query_spec = self._query_spec
        if getattr(query_spec, "limit", None) is None:
            query_spec = replace(query_spec, limit=1)
        resolved_user_id = ctx.cte_refs.get(self._user_id_ref_id) if self._user_id_ref_id is not None else None
        compiled = compile_sql_query_execute_step(
            self._model_cls,
            _normalize_raw_select_one_sys_id_filter(query_spec, self._model_cls),
            ctx,
            raw_mode=True,
            resolved_user_id=resolved_user_id,
            closed_post_op=_build_query_first_raw_post_op(
                strict_one=False,
            ),
            step_name=type(self).__name__,
        )
        if compiled.output_shape is not None and compiled.column_type_hints is not None:
            compiled_columns = compiled.output_shape.cte_output_columns
            if any(column.startswith("__nera_inline_large_column__") for column in compiled_columns):
                self._compiled_output_columns = compiled_columns
                self._compiled_column_type_hints = compiled.column_type_hints
                self._cte_publication_contract_cache_valid = False
                self._publication_contract_cache_valid = False
                return cast("CompiledStep[dict[str, Any] | None]", compiled)
        output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(
            self.cte_publication_contract(),
        )
        return cast(
            "CompiledStep[dict[str, Any] | None]",
            replace(
                compiled,
                output_shape=output_shape,
                result_relation=result_relation,
                column_type_hints=column_type_hints,
            ),
        )

"""Steps that wire plan results back to LazyRow / PendingDelete caches.

When commit_lazy() flushes pending lazy ORM operations into the plan,
the SQL steps produce results that need to be stored back into the
in-memory LazyRow / PendingDelete objects so that post-commit attribute
access works without hitting the (now-committed) transaction.
"""

from __future__ import annotations

from collections.abc import Sequence
from dataclasses import dataclass, field
from typing import TYPE_CHECKING, Any, NewType

from l2070_batching.cardinality import Cardinality
from l2070_batching.compilation import (
    CompiledStep,
    PipelineLifecycleEffect,
    PipelineLifecyclePhase,
    ResolvedRefs,
    ResultBoundLifecycleEffects,
)
from l2070_batching.runtime_services import ServerPlanRuntimeServices
from l2070_batching.step import ServerPlanStep, StepExecutionRole, NonPublishingStep
from l1400_types import ServerPlanRefId

LazyCacheTargetKey = NewType("LazyCacheTargetKey", str)


@dataclass(frozen=True, slots=True)
class PopulateLazyRowCacheEffect(PipelineLifecycleEffect):
    target_key: LazyCacheTargetKey
    value: object | None
    phase: PipelineLifecyclePhase = field(
        default=PipelineLifecyclePhase.AFTER_COMMIT_LOCAL,
        init=False,
    )

    def apply(self: PopulateLazyRowCacheEffect, runtime_services: ServerPlanRuntimeServices) -> None:
        target = runtime_services.pop_lazy_cache_target(self.target_key)
        value = self.value
        try:
            populate_value = object.__getattribute__(target, "populate_lazy_cache_value")
        except AttributeError:
            populate_value = None
        if callable(populate_value):
            populate_value(value)
            return
        if isinstance(value, dict):
            model_cls = getattr(target, "_model_cls", None)
            if isinstance(model_cls, type):
                from impl.common.l5200_sql_query.row_converter import convert_row_to_model

                value = convert_row_to_model(model_cls, dict(value))
        object.__setattr__(target, "_cached", value)
        object.__setattr__(target, "_loaded", True)
        object.__setattr__(target, "_not_found", value is None)
        object.__setattr__(target, "_pending_updates", None)


@dataclass(frozen=True, slots=True)
class PopulatePendingDeleteCacheEffect(PipelineLifecycleEffect):
    target_key: LazyCacheTargetKey
    value: object
    phase: PipelineLifecyclePhase = field(
        default=PipelineLifecyclePhase.AFTER_COMMIT_LOCAL,
        init=False,
    )

    def apply(self: PopulatePendingDeleteCacheEffect, runtime_services: ServerPlanRuntimeServices) -> None:
        target = runtime_services.pop_lazy_cache_target(self.target_key)
        object.__setattr__(target, "_result", self.value)
        object.__setattr__(target, "_loaded", True)


def _value_from_materialized_rows(result: object, default_value: object) -> object:
    if not isinstance(result, Sequence) or isinstance(result, str | bytes | bytearray):
        return result
    if not result:
        return default_value
    first_row = result[0]
    if not isinstance(first_row, dict):
        return first_row
    if len(first_row) == 1:
        return next(iter(first_row.values()))
    return first_row


class PopulateLazyRowCacheStep(NonPublishingStep[None]):
    """L0: Read a resolved update result and populate a LazyRow's cache.

    After the update step executes, this step reads the result (T | None)
    and stores it into the LazyRow's _cached / _loaded / _not_found fields.
    No SQL is generated.
    """

    def __init__(
        self: PopulateLazyRowCacheStep,
        ref_id: ServerPlanRefId,
        source_ref: ServerPlanRefId,
        target_key: LazyCacheTargetKey,
        *,
        preserve_sequence: bool = False,
    ) -> None:
        super().__init__(ref_id)
        self._source_ref = source_ref
        self._target_key = target_key
        self._preserve_sequence = preserve_sequence

    @property
    def level(self: PopulateLazyRowCacheStep) -> int:
        return 0

    def result_cardinality(self: PopulateLazyRowCacheStep) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self: PopulateLazyRowCacheStep) -> bool:
        return True

    def execution_role(self: PopulateLazyRowCacheStep) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def publishes_executor_visible_binding(self: PopulateLazyRowCacheStep) -> bool:
        return False

    def consumes_executor_visible_dependencies(self: PopulateLazyRowCacheStep) -> bool:
        return True

    def step_tags(self: PopulateLazyRowCacheStep) -> frozenset[str]:
        return frozenset({"apply", "lazy_row_cache", "runtime_projection"})

    def tables_read(self: PopulateLazyRowCacheStep) -> frozenset[str]:
        return frozenset()

    def tables_written(self: PopulateLazyRowCacheStep) -> frozenset[str]:
        return frozenset()

    def dependencies(self: PopulateLazyRowCacheStep) -> frozenset[str]:
        return frozenset({self._source_ref})

    def compile(self: PopulateLazyRowCacheStep, ctx: object) -> CompiledStep[None]:
        del ctx
        return CompiledStep(
            lifecycle_effects=(ResultBoundLifecycleEffects(self._lifecycle_effects_from_result),),
        )

    def execute_runtime(self: PopulateLazyRowCacheStep, resolved: ResolvedRefs) -> object:
        return resolved.get(str(self._source_ref))

    def _lifecycle_effects_from_result(
        self: PopulateLazyRowCacheStep,
        result: object,
    ) -> Sequence[PopulateLazyRowCacheEffect]:
        effect = PopulateLazyRowCacheEffect(
            target_key=self._target_key,
            value=result if self._preserve_sequence else _value_from_materialized_rows(result, None),
        )
        return (effect,)


class PopulatePendingDeleteCacheStep(NonPublishingStep[None]):
