@dataclass(frozen=True, slots=True)
class _VectorKeysetPageConfig:
    source_ref: ServerPlanRefId
    limit: VectorKeysetLimit
    after: tuple[float, object] | tuple[float, object, object] | None


class VectorKeysetPageStep(NonPublishingStep[KeysetPage[Any]]):
    """Build a vector keyset page from an already-materialized score result."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        config: _VectorKeysetPageConfig,
    ) -> None:
        super().__init__(ref_id)
        self._source_ref = config.source_ref
        self._limit = config.limit
        self._after = config.after

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        # The page is one opaque terminal value, not a one-row relation.  ONE
        # asks the executor to hydrate/unbox its contents and loses the
        # KeysetPage wrapper before the legacy API receives it.
        return Cardinality.SCALAR

    def is_read_only(self) -> bool:
        return True

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def step_tags(self) -> frozenset[str]:
        return frozenset({"read", "vector", "keyset", "terminal_projection"})

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def dependencies(self) -> frozenset[str]:
        return frozenset({str(self._source_ref)})

    def runtime_result_is_terminal_scalar(self) -> bool:
        return True

    def compile(self, ctx: CompilationContext) -> CompiledStep[KeysetPage[Any]]:
        del ctx
        return CompiledStep()

    def execute_runtime(self, resolved: ResolvedRefs) -> KeysetPage[Any]:
        rows = list(cast("list[Any]", resolved.get(str(self._source_ref)) or []))
        return _build_vector_keyset_page(rows, self._limit, self._after)

    async def execute_runtime_async(
        self,
        resolved: ResolvedRefs,
        hydrator: RuntimeHydrator[Any],
    ) -> KeysetPage[Any]:
        del hydrator
        return self.execute_runtime(resolved)

    def async_runtime_callback(self) -> AsyncRuntimeCallback:
        return self.execute_runtime_async


@pure_lazy
def _build_vector_keyset_page(
    results: list[Any],
    limit: VectorKeysetLimit,
    after: tuple[float, object] | tuple[float, object, object] | None,
) -> KeysetPage[Any]:
    if limit < 0:
        msg = "limit must be non-negative"
        raise ValueError(msg)
    if limit == 0:
        return KeysetPage(results=[], next_key=None, has_more=False)

    results.sort(key=lambda result: (-float(result.score), str(result.sys_id)))
    if after is not None:
        after_score = float(after[0])
        after_sys_id = str(after[-1])
        results = [
            result
            for result in results
            if (float(result.score) < after_score) or (float(result.score) == after_score and str(result.sys_id) > after_sys_id)
        ]

    page_results = results[:limit]
    has_more = len(results) > limit
    next_key = None
    if has_more and page_results:
        last = page_results[-1]
        next_key = (last.score, last.sys_id)
    return KeysetPage(results=page_results, next_key=next_key, has_more=has_more)


@pure_lazy
def resolve_row_backed_vector_query_lazy[T](
    txn: ReadTransactionLazyMixin,
    query: T,
) -> LazyResult[T]:
    plan = txn._get_transaction_plan_lazy()
    resolvable_query = cast(_ResolvableRowBackedVectorQuery, query)
    return cast(
        "LazyResult[T]",
        txn._add_intent(
            ResolveRowBackedVectorQueryStep(
                ServerPlanRefId(plan._next_ref()),
                config=_ResolveRowBackedVectorQueryConfig(query=resolvable_query),
            )
        ),
    )


@pure_lazy
def vector_keyset_page_lazy[T](
    txn: ReadTransactionLazyMixin,
    source: LazyResult[list[T]],
    *,
    limit: VectorKeysetLimit,
    after: tuple[float, object] | tuple[float, object, object] | None,
) -> LazyResult[KeysetPage[T]]:
    source_ref = object.__getattribute__(source, "_step_ref_id")
    if source_ref is None:
        return cast("LazyResult[KeysetPage[T]]", LazyResult.of(_build_vector_keyset_page([], limit, after)))
    plan = txn._get_transaction_plan_lazy()
    return cast(
        "LazyResult[KeysetPage[T]]",
        txn._add_intent(
            VectorKeysetPageStep(
                ServerPlanRefId(plan._next_ref()),
                config=_VectorKeysetPageConfig(
                    source_ref=ServerPlanRefId(source_ref),
                    limit=limit,
                    after=after,
                ),
            )
        ),
    )

