def _scalar_coercion_from_coerce(coerce: Callable[[object], object] | None) -> ScalarCoercionKind:
    if coerce is None:
        return ScalarCoercionKind.NONE
    if coerce is str:
        return ScalarCoercionKind.STR
    if coerce is int:
        return ScalarCoercionKind.INT
    if getattr(coerce, "__name__", None) == "_coerce_sys_id":
        return ScalarCoercionKind.SYS_ID
    if getattr(coerce, "__name__", None) == "_coerce_int":
        return ScalarCoercionKind.INT
    if coerce is RevisionId or getattr(coerce, "__name__", None) == "_coerce_revision_id":
        return ScalarCoercionKind.REVISION_ID
    msg = f"Unsupported closed runtime scalar coercion: {coerce!r}"
    raise TypeError(msg)


def _single_column_select(ctx: CompilationContext, source_ref: str, column: str) -> SqlDynamicSelectStmt:
    cte_ref = ctx.cte_refs.get(source_ref)
    if not isinstance(cte_ref, CteReference):
        msg = f"{source_ref!r} must be SQL-visible before scalar runtime projection."
        raise RuntimeError(msg)
    return SqlDynamicSelectStmt(
        SqlTableName(cte_ref.ref_id),
        columns=[SqlColumnName(column)],
        limit=1,
    )


def _single_column_output_shape(column: str) -> CompiledOutputShape:
    return CompiledOutputShape((synthetic_output_field(column),))


def _single_column_type_hints(ctx: CompilationContext, source_ref: str, column: str) -> SqlColumnTypeHints:
    cte_ref = ctx.cte_refs.get(source_ref)
    if isinstance(cte_ref, CteReference) and cte_ref.column_type_hints is not None:
        column_type_hints = cte_ref.column_type_hints
        matching_types = sum(column in typed_columns for typed_columns in column_type_hints.as_tuple())
        if matching_types == 1:
            return column_type_hints.filtered({column})
    if column == "sys_id" or column.endswith("_id"):
        return SqlColumnTypeHints(uuid_columns=frozenset({column}))
    return SqlColumnTypeHints(text_columns=frozenset({column}))


def _coerce_runtime_scalar(value: object, coercion: ScalarCoercionKind) -> object:
    if coercion is ScalarCoercionKind.NONE:
        return value
    if coercion is ScalarCoercionKind.STR:
        return str(value)
    if coercion is ScalarCoercionKind.INT:
        if isinstance(value, str | bytes | bytearray):
            return int(value)
        if isinstance(value, SupportsInt):
            return int(value.__int__())
        msg = f"Cannot coerce {type(value).__name__} to int."
        raise TypeError(msg)
    if coercion is ScalarCoercionKind.SYS_ID:
        return value if isinstance(value, SysId) else SysId(str(value))
    if coercion is ScalarCoercionKind.REVISION_ID:
        return value if isinstance(value, RevisionId) else RevisionId(str(value))
    msg = f"Unsupported runtime scalar coercion: {coercion}"
    raise TypeError(msg)

