class DecodeGrammarRowLookupStep(NonPublishingStep[object]):
    """Decode one optional grammar row through an explicit runtime step."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        source_ref: ServerPlanRefId,
        lookup_ref_id: GrammarLookupRefId,
        row_decoder: RowDecoder[object],
    ) -> None:
        super().__init__(ref_id)
        self._source_ref = str(source_ref)
        self._lookup_ref_id = lookup_ref_id
        self._row_decoder = row_decoder

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self) -> bool:
        return True

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.VIRTUAL

    def supports_sql_batch_transport(self) -> bool:
        return False

    def step_tags(self) -> frozenset[str]:
        return frozenset({"grammar", "runtime_projection", "row_lookup"})

    def counts_as_sql_group_for_accounting(self) -> bool | None:
        return False

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def dependencies(self) -> frozenset[str]:
        return frozenset({self._source_ref})

    def internal_plan_state(self) -> PlanPayloadState:
        return {
            "_source_ref": self._source_ref,
            "_lookup_ref_id": self._lookup_ref_id,
        }

    def internal_plan_ref_state(self) -> PlanPayloadState:
        return self.internal_plan_state()

    def compile(self, ctx: CompilationContext) -> CompiledStep[object]:
        del ctx
        msg = f"{type(self).__name__} requires a SQL-visible grammar row lookup projection"
        raise RuntimeError(msg)

    def materialize(self, resolved: ResolvedRefs) -> object:
