    BootstrapExpectedRowCount,
    BootstrapRowContentAssertion,
    BootstrapRowSetRequirement,
    BootstrapSqlAssertion,
)


@pytest.mark.parametrize("member_count", [0, 1, 2])
@pytest.mark.parametrize("expected_count", [0, 1, 2])
def test_row_content_admission_requires_exact_scoped_membership(
    db_connection: SyncDatabaseConnection,
    member_count: int,
    expected_count: int,
    system_session_id: SessionId,
) -> None:
    session = db_connection.session(system_session_id)
    anchor = session.write(
        fn=lambda txn: txn.insert(
            ImmutableBinaryRow,
            ImmutableBinaryRow(label="anchor", digest="fixed", payload=b"anchor"),
        )
    )
    for index in range(member_count):
        session.write(
            fn=lambda txn: txn.insert(
                ImmutableBinaryRow,
                ImmutableBinaryRow(label="generation", digest=str(index), payload=b"member"),
            )
        )
    session.write(
        fn=lambda txn: txn.insert(
            ImmutableBinaryRow,
            ImmutableBinaryRow(label="other-generation", digest="unrelated", payload=b"other"),
        )
    )
    table = SqlTableName(get_table_name(ImmutableBinaryRow))
    ref = ServerPlanRefId("generation-membership")
    assertion = BootstrapSqlAssertion(
        kind=BootstrapAssertionKind.ROW_CONTENT_MATCHES,
        severity=BootstrapAssertionSeverity.HARD_FAILURE,
        payload=BootstrapRowContentAssertion(
            table_name=table,
            row_id=anchor.sys_id,
            expected_values=((SqlColumnName("label"), "anchor"),),
            source_ref=ref,
            row_set_requirements=(
                BootstrapRowSetRequirement(
                    table_name=table,
                    predicates=((SqlColumnName("label"), "generation"),),
                    expected_count=BootstrapExpectedRowCount(expected_count),
                ),
            ),
        ),
    )
    step = BootstrapSqlAssertionStep(ref, assertion)
    assert step.tables_read() == frozenset({str(table)})

    def execute(txn: SyncReadTransaction) -> None:
        plan = txn._get_lazy_plan()
        result_ref = ServerPlanRefId(plan._next_ref())
        plan.add_step(BootstrapSqlAssertionStep(result_ref, assertion))
        resolve_terminal_sync(txn, "serverplan_test", txn._publish_pending_lazy_ref(result_ref, expected_type=type(None)))

    if member_count == expected_count:
        session.read(fn=execute)
    else:
        with pytest.raises(ProgrammingError, match="row_content_matches"):
            session.read(fn=execute)
    assert session.read(fn=lambda txn: txn.query(ImmutableBinaryRow).count()) == member_count + 2


@pytest.mark.parametrize("replacement", [False, True])
def test_failed_membership_publication_does_not_leave_an_activation_row(
    db_connection: SyncDatabaseConnection,
    replacement: bool,
    system_session_id: SessionId,
) -> None:
    row = ImmutableBinaryRow(label="activation", digest="fixed", payload=b"activation")
    table = SqlTableName(get_table_name(ImmutableBinaryRow))
    requirement = BootstrapRowSetRequirement(
        table_name=table,
        predicates=((SqlColumnName("label"), "missing-generation"),),
        expected_count=BootstrapExpectedRowCount(4),
    )
    session = db_connection.session(system_session_id)
    previous = None
    if replacement:
        previous = session.write(
            fn=lambda txn: txn.insert(
                ImmutableBinaryRow,
                ImmutableBinaryRow(
                    sys_id=row.sys_id,
                    label="previous",
                    digest="old",
                    payload=b"previous",
                ),
            )
        )
    with pytest.raises(ProgrammingError, match="row_content_matches"):
        with db_connection.schema_transaction(SessionId.schema()) as schema:
            if previous is None:
                resolve_terminal_sync(
                    schema,
                    "serverplan_test",
                    schema.ensure_bootstrap_immutable_row_lazy(
                        BootstrapImmutableRowPrimitivePayload.from_row(
                            ImmutableBinaryRow,
                            row,
                            immutable_fields=("label", "digest", "payload"),
                            row_set_requirements=(requirement,),
                        ),
                    ),
                )
            else:
                resolve_terminal_sync(
                    schema,
                    "serverplan_test",
                    schema.replace_bootstrap_immutable_row_lazy(
                        BootstrapImmutableRowPrimitivePayload.from_row(
                            ImmutableBinaryRow,
                            row,
                            immutable_fields=("label", "digest", "payload"),
                            row_set_requirements=(requirement,),
                        ),
                        previous_declaration=BootstrapImmutableRowPrimitivePayload.from_row(
                            ImmutableBinaryRow,
                            previous,
                            immutable_fields=("label", "digest", "payload"),
                        ),
                    ),
                )
    assert session.read(fn=lambda txn: txn.select_one(ImmutableBinaryRow, row.sys_id)) == previous


