@pytest.mark.parametrize(
    "fault",
    [
        None,
        "grow",
        "retire",
        "unselected_grow",
        "same_size_digest",
        "membership_digest",
        "projection",
    ],
)
def test_compaction_capture_transports_only_matching_selected_payloads_and_keys(
    db_connection: SyncVersionedDatabaseConnection, fault: str | None, system_session_id: SessionId
) -> None:
    _, branch = create_test_revision(
        db_connection,
        USearchScopeDomain,
        workspace_id=WorkspaceId.default(),
        session_id=SessionId.schema(),
    )
    for number in range(3):
        _write_document(
            db_connection,
            branch,
            connection_id=ConnectionId(f"compaction-input-{number}"),
            title=f"input-{number}",
            embedding=[float(number + 1), 1.0],
        )

    def authority(txn: SyncReadTransaction) -> tuple[USearchIndexBlobBase, list[USearchRun]]:
        return txn.query(USearchScopeIndex).execute()[0], sorted(
            txn.query(USearchRun).execute(),
            key=lambda run: run.published_epoch,
        )

    header, runs = db_connection.session(SessionId.schema()).read(fn=authority)
    byte_limit = sum(len(run.payload) for run in runs[:2])
    policy = USearchCompactionPolicy(
        level_zero_run_trigger=2,
        output_run_bytes=byte_limit,
        max_compaction_bytes=byte_limit,
    )

    def metadata_plan(txn: SyncReadTransaction) -> dict[str, object]:
        return plan_usearch_compaction_metadata(txn, USearchScopeIndex, header.sys_id)

    metadata = execute_read_plan_workflow(
        db_connection,
        SyncReadPlanWorkflow[dict[str, object]](
            session_id=SessionId.schema(),
            build=metadata_plan,
        ),
    )
    selection = select_compaction_from_metadata(
        metadata,
        artifact_id=header.sys_id,
        policy=policy,
        cursors={},
    )
    assert selection is not None
    assert {run.run_id for run in selection.input_runs} == {run.sys_id for run in runs[:2]}
    if fault is not None:
        changed = runs[-1] if fault == "unselected_grow" else runs[0]
        if fault == "retire":
            changed = changed.model_copy(update={"retired_epoch": header.artifact_epoch + 1})
        elif fault == "membership_digest":
            changed = changed.model_copy(update={"membership_sha256": "0" * 64})
        elif fault == "projection":
            changed = changed.model_copy(update={"projection_identity": "prefix:3:2"})
        else:
            payload = (
                changed.payload[:-1] + bytes([changed.payload[-1] ^ 1]) if fault == "same_size_digest" else changed.payload + bytes(4096)
            )
            changed = changed.model_copy(update={"payload": payload, "payload_sha256": sha256(payload).hexdigest()})

        def mutate(txn: SyncWriteTransaction) -> None:
            txn.update(USearchRun, changed)

        db_connection.session(SessionId.schema()).write(fn=mutate)

    def input_plan(txn: SyncReadTransaction) -> dict[str, object]:
        return plan_usearch_compaction_inputs(txn, selection, policy)

    captured = execute_read_plan_workflow(
        db_connection,
        SyncReadPlanWorkflow[dict[str, object]](
            session_id=SessionId.schema(),
            build=input_plan,
        ),
    )
    selected_rows = captured["runs"]
    keys = captured["keys"]
    assert isinstance(selected_rows, list)
    assert isinstance(keys, list)
    assert all(isinstance(run, USearchRun) for run in selected_rows)
    expected = runs[:2] if fault in {None, "unselected_grow"} else runs[1:2]
    assert {run.sys_id for run in selected_rows} == {run.sys_id for run in expected}
    assert sum(len(run.payload) for run in selected_rows) <= byte_limit
    for row in keys:
        assert isinstance(row, dict)
        assert set(row) == {"run_id", "native_key"}
    assert {str(row["run_id"]) for row in keys} == {str(run.sys_id) for run in expected}
    assert len(keys) == len(expected)
    outputs = build_usearch_compaction_outputs(captured, selection, policy)
    if fault in {None, "unselected_grow"}:
        assert outputs is not None
        assert [key for output in outputs for key in output.keys] == sorted(run.first_native_key for run in selection.input_runs)

        def original_members(txn: SyncReadTransaction) -> list[USearchRunMember]:
            selected_ids = {run.run_id for run in selection.input_runs}
            return [member for member in txn.query(USearchRunMember).execute() if member.run_id in selected_ids]

        members = db_connection.session(SessionId.schema()).read(fn=original_members)
        replacements = prepare_compaction_publication_rows(selection, policy, outputs, members)
        assert sum(run.member_count for run, _ in replacements) == len(members)
        assert {member.embedding_vector_id for _, group in replacements for member in group} == {
            member.embedding_vector_id for member in members
        }
    else:
        assert outputs is None

"""ConditionalValidationStep: validate row existence with SQL-owned assertions."""

from __future__ import annotations

from dataclasses import dataclass
from typing import TYPE_CHECKING, Any

from l2070_batching.cardinality import Cardinality
from l2070_batching.compilation import (
    CompiledStep,
    compiled_artifacts_from_cte_publication_contract,
    explicit_output_shape_tombstone,
    output_shape_from_cte_publication_contract,
)
from l2070_batching.output_shape import DeclaredResultRelation
from l2070_batching.payload_state import PlanPayloadState
from impl.common.l2070_server_plan.steps.sql_error_gate import (
    SqlAssertionResultRow,
    sql_assertion_column_type_hints,
    sql_assertion_output_shape,
    rows_exist_assertion_query,
    sql_assertion_post_op,
)
from l2070_batching.post_op import optional_single_row_post_op
from l2070_batching.sql_renderable import SqlRenderable
from l2070_batching.step import (
    ServerPlanStep,
    StepExecutionRole,
    ContractedSqlProducerStep,
    SqlRelationPublisherStep,
    CtePublicationContract,
)
from l1400_types import ServerPlanRefId

if TYPE_CHECKING:
    from l2070_batching.compilation import CompilationContext, ResolvedRefs


@dataclass(frozen=True, slots=True)
class _ConditionalValidationConfig:
    error_cls: type[Exception] = RuntimeError
    error_message: str = "Validation failed"
    required: bool = True
    params: tuple[Any, ...] | None = None


class ConditionalValidationStep(SqlRelationPublisherStep[dict[str, Any] | None]):
    """Fetch an optional row or raise from a SQL assertion when required.

    If ``required`` is true, SQL computes whether a row exists and publishes the
    validation fact as an assertion relation.

    Used for session validation, branch state checks, etc.
    """

    def __init__(
        self: ConditionalValidationStep,
        ref_id: ServerPlanRefId,
        stmt: SqlRenderable,
        config: _ConditionalValidationConfig | None = None,
    ) -> None:
        super().__init__(ref_id)
        resolved_config = config or _ConditionalValidationConfig()
        self._stmt = stmt
        self._error_cls = resolved_config.error_cls
        self._error_message = resolved_config.error_message
        self._required = resolved_config.required
        self._params = resolved_config.params

    @property
    def level(self: ConditionalValidationStep) -> int:
        return 0

    def step_tags(self: ConditionalValidationStep) -> frozenset[str]:
        """Return tags identifying this step type."""
        return frozenset({"infrastructure", "validation"})

    def counts_as_sql_group_for_accounting(self: ConditionalValidationStep) -> bool | None:
        """Validation always executes the configured SQL statement."""
        return True

    def is_read_only(self: ConditionalValidationStep) -> bool:
        """This step only reads data."""
        return True

    def execution_role(self: ConditionalValidationStep) -> StepExecutionRole:
        """Validation executes a SQL grammar statement."""
        return StepExecutionRole.SQL

    def result_cardinality(self: ConditionalValidationStep) -> Cardinality:
        """Returns a single row or None."""
        return Cardinality.ONE

    def tables_read(self: ConditionalValidationStep) -> frozenset[str]:
        """Grammar steps don't declare table dependencies."""
        return frozenset()

    def tables_written(self: ConditionalValidationStep) -> frozenset[str]:
        """Validation is read-only; no tables written."""
        return frozenset()

    def dependencies(self: ConditionalValidationStep) -> frozenset[str]:
        """Grammar steps don't have ServerRef dependencies."""
        return frozenset()

    def preprocess(self: ConditionalValidationStep, resolved: ResolvedRefs) -> None:
        """No preprocessing needed for grammar steps."""

    def internal_plan_ref_state(self: ConditionalValidationStep) -> PlanPayloadState:
        return self.internal_plan_ref_state_excluding("_stmt")

    def cte_publication_contract(self: ConditionalValidationStep) -> CtePublicationContract:
        output_shape = sql_assertion_output_shape()
        column_type_hints = sql_assertion_column_type_hints()
        columns = output_shape.cte_output_columns
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        _contract_model_cls = SqlAssertionResultRow
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=tuple(str(column) for column in columns),
            column_type_hints=column_type_hints,
            model_cls=_contract_model_cls,
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def compile(
        self: ConditionalValidationStep,
        ctx: CompilationContext,
    ) -> CompiledStep[dict[str, Any] | None]:
        """Compile to a CompiledStep for SQL backends."""

        if not self._required:
            __opa002_grammar_140 = self._stmt
            output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(
                self.cte_publication_contract(),
            )
            return CompiledStep(
                output_shape=output_shape,
                result_relation=result_relation,
                column_type_hints=column_type_hints,
                grammar=__opa002_grammar_140,
                params=self._params,
                needs_returning=True,
                closed_post_op=optional_single_row_post_op(),
            )

        output_shape = sql_assertion_output_shape()
        return CompiledStep(
            grammar=rows_exist_assertion_query(
                self._stmt,
                error_message=self._error_message,
            ),
            params=self._params,
            needs_returning=True,
            closed_post_op=sql_assertion_post_op(
                self._error_message,
                exc_type=self._error_cls,
            ),
            output_shape=output_shape,
            result_relation=DeclaredResultRelation.from_output_shape(output_shape),
            column_type_hints=sql_assertion_column_type_hints(),
        )

