class _DependencyRow(DatabaseObjectRow[SysId]):
    value: int


@dataclass(frozen=True)
class _SharedFilterSpec:
    filters: list[Expression[bool, _DependencyRow]]


def test_query_dependency_collection_visits_shared_filter_payloads_once() -> None:
    predicate = Expression[int, _DependencyRow](field="value") == ServerRefs.from_ref_id(
        ServerPlanRefId("step_1"),
        variant="scalar",
    )
    spec = _SharedFilterSpec(filters=[predicate, predicate])
    classified_predicates = 0
    classify = _resolve.classify_payload

    def tracked(value: object, *, type_cache: dict[type[object], PayloadKind | None] | None = None) -> PayloadKind:
        nonlocal classified_predicates
        if value is predicate:
            classified_predicates += 1
        return classify(value, type_cache=type_cache)

    with (
        patch.object(_resolve, "classify_payload", tracked),
        patch.object(_resolve, "_collect_dependency_refs_from_payload", wraps=_resolve._collect_dependency_refs_from_payload) as walk,
    ):
        assert _resolve.collect_query_spec_deps(spec) == frozenset({"step_1"})
    assert walk.call_count == 1
    assert classified_predicates == 1
    spec.filters[:] = [
        Expression[int, _DependencyRow](field="value")
        == ServerRefs.from_ref_id(
            ServerPlanRefId("step_2"),
            variant="scalar",
        )
    ]
    assert _resolve.collect_query_spec_deps(spec) == frozenset({"step_2"})


