class JsonObjectRowResultStep[T: BaseModel](SqlRelationPublisherStep[T]):
    """Build one typed JSON-object result from declared source-row columns."""

    def __init__(
        self: JsonObjectRowResultStep,
        ref_id: ServerPlanRefId,
        *,
        source_ref: ServerPlanRefId,
        projection: tuple[tuple[str, str], ...],
        model_cls: type[T],
    ) -> None:
        super().__init__(ref_id)
        if not projection or len({public for public, _source in projection}) != len(projection):
            raise ValueError("JSON row projections require distinct public fields")
        self.source_ref = source_ref
        self.projection = projection
        self.model_cls = model_cls

    @property
    def level(self: JsonObjectRowResultStep[T]) -> int:
        return 0

    def sql_snapshot_source_ref(self: JsonObjectRowResultStep[T]) -> ServerPlanRefId:
        return self.source_ref

    def dependencies(self: JsonObjectRowResultStep[T]) -> frozenset[str]:
        return frozenset({str(self.source_ref)})

    def sql_visible_dependencies(self: JsonObjectRowResultStep[T]) -> frozenset[str]:
        return frozenset({str(self.source_ref)})

    def step_tags(self: JsonObjectRowResultStep[T]) -> frozenset[str]:
        return frozenset({"read", "projection", "grammar"})

    def is_read_only(self: JsonObjectRowResultStep[T]) -> bool:
        return True

    def execution_role(self: JsonObjectRowResultStep[T]) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def supports_sql_batch_transport(self: JsonObjectRowResultStep[T]) -> bool:
        return True

    def supports_ordered_sql_statement_batch(self: JsonObjectRowResultStep[T]) -> bool:
        return True

    def requires_sql_consumed_rows_relation(self: JsonObjectRowResultStep[T]) -> bool:
        return True

    def result_cardinality(self: JsonObjectRowResultStep[T]) -> Cardinality:
        return Cardinality.ONE

    def tables_read(self: JsonObjectRowResultStep[T]) -> frozenset[str]:
        return frozenset()

    def tables_written(self: JsonObjectRowResultStep[T]) -> frozenset[str]:
        return frozenset()

    def cte_publication_contract(self: JsonObjectRowResultStep[T]) -> CtePublicationContract:
        columns = ("content", "structured_content")
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=columns,
            column_type_hints=SqlColumnTypeHints(jsonb_columns=frozenset(columns)),
            model_cls=self.model_cls,
            relation_role=self.cte_relation_role(),
            source_tables=None,
            relation_contract=CteRelationContract.semantic_row(self.model_cls),
        )

    def compile(self: JsonObjectRowResultStep[T], ctx: CompilationContext) -> CompiledStep[T]:
        structured_arguments: list[SqlRenderable] = []
        for public_name, source_name in self.projection:
            structured_arguments.extend(
                (
                    SqlParam(public_name),
                    lower_scalar_server_ref(
                        ServerRefs.from_ref_id(
                            ServerPlanRefId(f"{self.source_ref}.{source_name}"),
                            variant="scalar",
                            type_hint=object,
                        ),
                        ctx,
                    ),
                )
            )
        columns = ("content", "structured_content")
        grammar = SqlSelect(
            select=SqlSelectList(
                (
                    SqlSelectAlias(SqlJsonBuild(SqlFunctionName("JSON_BUILD_ARRAY"), []), SqlAliasName("content")),
                    SqlSelectAlias(
                        SqlJsonBuild(SqlFunctionName("JSON_BUILD_OBJECT"), structured_arguments),
                        SqlAliasName("structured_content"),
                    ),
                )
            )
        )
        shape = output_shape_for_synthetic_columns(columns)
        return CompiledStep(
            grammar=grammar,
            needs_returning=True,
            closed_post_op=CompiledPostOp.materialize(
                ResultMaterializationSpec(
                    behavior=PostOpBehavior.TERMINAL_OBJECT,
                    structured_result=StructuredResultSpec(
                        result_cls=self.model_cls,
                        fields=tuple(
                            StructuredResultField(
                                output_name=column,
                                source_column=column,
                                scalar_coercion=ScalarCoercionKind.JSON,
                            )
                            for column in columns
                        ),
                    ),
                )
            ),
            output_shape=shape,
            result_relation=DeclaredResultRelation.from_output_shape(shape),
            column_type_hints=SqlColumnTypeHints(jsonb_columns=frozenset(columns)),
            auxiliary_ctes=collect_dependency_auxiliary_ctes(ctx, self.dependencies()),
        )

