class USearchMatchingMembersStep(SqlRelationPublisherStep[list[dict[str, object]]]):
    """Join the incoming vector relation before transporting membership rows."""

    def __init__(
        self: Self, ref_id: ServerPlanRefId, *, artifact_table: SqlTableName,
        blob_ref: ServerPlanRefId, vectors_ref: ServerPlanRefId,
    ) -> None:
        super().__init__(ref_id)
        self._artifact_table = artifact_table
        self._blob_ref = blob_ref
        self._vectors_ref = vectors_ref
        self._limits = get_usearch_request_limits()

    @property
    def level(self: Self) -> int:
        return 0

    def result_cardinality(self: Self) -> Cardinality:
        return Cardinality.MANY

    def is_read_only(self: Self) -> bool:
        return True

    def execution_role(self: Self) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def dependencies(self: Self) -> frozenset[str]:
        return frozenset({str(self._blob_ref), str(self._vectors_ref)})

    def tables_read(self: Self) -> frozenset[str]:
        return frozenset({self._artifact_table, "sys_usearch_artifact_members"})

    def tables_written(self: Self) -> frozenset[str]:
        return frozenset()

    def cte_publication_contract(self: Self) -> CtePublicationContract:
        columns = tuple(get_db_column_name(USearchArtifactMember, DynamicFieldName(name))
                        for name in USearchArtifactMember.model_fields)
        hints = model_sql_column_type_hints(USearchArtifactMember, columns)
        assert hints is not None, "USearch membership requires declared SQL column types"
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=columns,
            column_type_hints=hints,
            relation_contract=CteRelationContract.semantic_row(USearchArtifactMember),
            relation_role="usearch_matching_members", source_tables=self.tables_read(),
        )

    def compile(self: Self, ctx: CompilationContext) -> CompiledStep[list[dict[str, object]]]:
        blob = resolve_sql_visible_relation(ctx, self._blob_ref)
        vectors = resolve_sql_visible_relation(ctx, self._vectors_ref)
        assert isinstance(blob, CteReference) and isinstance(vectors, CteReference), (
            "USearch matching membership requires SQL-visible artifact and vector relations"
        )
        assert vectors.columns is not None, (
            "USearch incoming vectors require a declared column shape"
        )
        vector_id = "embedding_vector_id" if "embedding_vector_id" in vectors.columns else "sys_id"
        assert vector_id in vectors.columns, (
            "USearch incoming vectors require canonical vector identities"
        )
        member = SqlAliasName("canonical_member")
        head = SqlAliasName("canonical_head")
        incoming = SqlAliasName("incoming_vector")

        def col(name: str, alias: SqlAliasName) -> SqlColumnRef:
            return SqlColumnRef(SqlColumnName(name), alias)

        matches = SqlExists(SqlSelect(
            select=SqlSelectList([SqlParam(1)]),
            from_=SqlTableAlias(SqlTableIdent(SqlTableName(vectors.ref_id)), incoming),
            where=sql_or(
                SqlBinaryOp(col("embedding_vector_id", member), BinaryOp.EQ, col(vector_id, incoming)),
                sql_and(
                    SqlBinaryOp(col("content_hash_short", member), BinaryOp.EQ, col("content_hash_short", incoming)),
                    SqlBinaryOp(col("content_hash_high", member), BinaryOp.EQ, col("content_hash_high", incoming)),
                ),
            ),
        ))
        contract = self.cte_publication_contract()
        grammar = SqlSelect(
            select=SqlSelectList([
                SqlSelectAlias(col(name, member), SqlAliasName(name)) for name in contract.columns
            ]),
            from_=SqlTableAlias(SqlTableIdent(SqlTableName("sys_usearch_artifact_members")), member),
            joins=[SqlJoin(
                JoinKind.INNER, SqlTableAlias(SqlTableIdent(SqlTableName(blob.ref_id)), head),
                SqlBinaryOp(col("artifact_id", member), BinaryOp.EQ, col("sys_id", head)),
            )],
            where=sql_or(
                SqlBinaryOp(col("storage_format", head), BinaryOp.NE, SqlParam("immutable-runs-v1")),
                matches,
            ),
            limit=self._limits.max_eligibility_rows + 1,
        )
        auxiliary: list[tuple[str, SqlRenderable]] = []
        for binding in (blob, vectors):
            if binding.auxiliary_query is not None:
                auxiliary.append((binding.ref_id, binding.auxiliary_query))
        output, relation, hints = compiled_artifacts_from_cte_publication_contract(contract)
        return CompiledStep(
            grammar=grammar, output_shape=output, result_relation=relation, column_type_hints=hints,
            auxiliary_ctes=tuple(auxiliary), needs_returning=True, closed_post_op=row_dicts_post_op(),
        )

"""Shared helpers for threading dependency CTE definitions into terminal SQL."""

from __future__ import annotations

from collections.abc import Iterable
from typing import Any

from impl.common.l2070_server_plan.steps._sql_visible_refs import (
    resolve_sql_visible_auxiliary_binding,
)
from impl.common.l2100_sql_grammar.sql_fragment import SqlFragment
from impl.common.l2200_sql_dialect.sql_dialect import SqlDialect
from l1400_types import ServerPlanRefId
from l2070_batching.compilation import CompilationContext, CteReference
from l2070_batching.sql_renderable import SqlRenderable


class SqlOwnedCteScope(SqlRenderable):
    """Keep a complete nested CTE query inside one published CTE owner."""

    __slots__ = ("_inner",)

    def __init__(self, inner: SqlRenderable) -> None:
        self._inner = inner

    def render(self, dialect: SqlDialect) -> SqlFragment:
        return self._inner.render(dialect)

    def policy_dispatch_dependency_queries(self) -> tuple[SqlRenderable, ...]:
        """Expose the owned query without flattening its publication scope."""
        return (self._inner,)


def flatten_auxiliary_query_for_outer_cte(
    query: SqlRenderable,
) -> tuple[list[tuple[str, SqlRenderable]], SqlRenderable]:
    """Move nested CTE definitions into the statement that consumes them."""
    split_for_outer_cte = getattr(query, "split_for_outer_cte", None)
    if not callable(split_for_outer_cte):
        return [], query
    split_result = split_for_outer_cte()
    if not isinstance(split_result, tuple) or len(split_result) != 2:
        raise TypeError("split_for_outer_cte() must return definitions and a final query")
    raw_definitions, body = split_result
    if not isinstance(raw_definitions, (list, tuple)):
        raise TypeError("split_for_outer_cte() definitions must be a sequence")
    if not isinstance(body, SqlRenderable):
        raise TypeError("split_for_outer_cte() final query must be SQL-renderable")

    definitions: list[tuple[str, SqlRenderable]] = []
    for raw_definition in raw_definitions:
        name, definition_query = _auxiliary_definition_parts(raw_definition)
        nested_definitions, definition_body = flatten_auxiliary_query_for_outer_cte(definition_query)
        definitions.extend(nested_definitions)
        definitions.append((name, definition_body))
    return definitions, body


def _auxiliary_definition_parts(definition: object) -> tuple[str, SqlRenderable]:
    base_name = getattr(definition, "base_name", None)
    public_query = getattr(definition, "query", None)
    private_name = getattr(definition, "_name", None)
    private_query = getattr(definition, "_query", None)
    if base_name is not None and public_query is not None:
        columns = tuple(str(column) for column in getattr(definition, "columns", ()) or ())
        name = str(base_name)
        if columns:
            name = f"{name}({', '.join(columns)})"
        query = public_query
    elif private_name is not None and private_query is not None:
        name = str(private_name)
        query = private_query
    elif isinstance(definition, tuple) and len(definition) == 2:
        name, query = definition
    else:
        raise TypeError("CTE definition must provide a name and SQL-renderable query")
    if not isinstance(query, SqlRenderable):
        raise TypeError("CTE definition query must be SQL-renderable")
    return str(name), query


def _flatten_ref_ids(ref_ids_or_groups: Iterable[str | Iterable[str]]) -> list[str]:
    ref_ids: list[str] = []
    for item in ref_ids_or_groups:
        if isinstance(item, str):
            ref_ids.append(item)
        else:
            ref_ids.extend(item)
    return ref_ids


def collect_dependency_auxiliary_ctes(
    ctx: CompilationContext,
    *ref_ids_or_groups: str | Iterable[str],
) -> list[tuple[str, SqlRenderable]] | None:
    """Collect auxiliary CTE definitions needed by terminal statements.

    Single-step strategies do not automatically emit CTE bindings from
    ``ctx.cte_refs``; callers must explicitly surface the auxiliary query for
    each CTE they reference so the dependency is present in the WITH clause.
    """

    if ctx.cte_refs is None:
        return None
    auxiliary_ctes: list[tuple[str, SqlRenderable]] = []
    seen_aliases: set[str] = set()

    for ref_id in _flatten_ref_ids(ref_ids_or_groups):
        branded_ref_id = ServerPlanRefId(ref_id)
        binding_with_aux = resolve_auxiliary_cte_binding(ctx, branded_ref_id)
        if binding_with_aux is None:
            continue
        if binding_with_aux.ref_id in seen_aliases:
            continue
        seen_aliases.add(binding_with_aux.ref_id)
        auxiliary_query = binding_with_aux.auxiliary_query
        if auxiliary_query is None:
            continue
        auxiliary_ctes.append((binding_with_aux.ref_id, auxiliary_query))
    return auxiliary_ctes or None


def collect_permission_context_auxiliary_ctes(
    ctx: CompilationContext,
    permission_context_ref: ServerPlanRefId | None,
    *,
    operation: str,
) -> list[tuple[str, SqlRenderable]] | None:
    """Validate and collect the typed permission-context relation for a terminal statement."""
    if permission_context_ref is None:
        return None
    if ctx.cte_refs is None:
        msg = f"{operation} requires permission context ref {permission_context_ref!r}, but no CTE refs exist"
        raise TypeError(msg)
    context_cte = ctx.cte_refs.get(permission_context_ref)
    if not isinstance(context_cte, CteReference):
        msg = f"{operation} permission context ref {permission_context_ref!r} is not a SQL-visible CTE relation"
        raise TypeError(msg)
    if context_cte.auxiliary_query is None:
        return None
    return [(context_cte.ref_id, context_cte.auxiliary_query)]


def resolve_auxiliary_cte_binding(
    ctx: CompilationContext,
    ref_id: ServerPlanRefId,
) -> CteReference | None:
    """Resolve a replayable SQL binding, including materialized rowsets."""
    binding = resolve_sql_visible_auxiliary_binding(ctx, ref_id)
    if binding is not None:
        return binding
    exact_alias_bindings = {
        id(candidate): candidate
        for candidate in ctx.cte_refs.values()
        if candidate.ref_id == str(ref_id) and candidate.auxiliary_query is not None
    }
    if len(exact_alias_bindings) == 1:
        return next(iter(exact_alias_bindings.values()))
    return None

