    non_materialized: list[RevisionId]


def partition_from_materialization_flags(
    revision_ids: Sequence[RevisionId],
    materialized_flags: Sequence[bool],
) -> VersionedFtsMaterializationPartition:
    materialized: list[RevisionId] = []
    non_materialized: list[RevisionId] = []
    for revision_id, is_materialized in zip(revision_ids, materialized_flags, strict=True):
        if is_materialized:
            materialized.append(revision_id)
        else:
            non_materialized.append(revision_id)
    return VersionedFtsMaterializationPartition(
        materialized=materialized,
        non_materialized=non_materialized,
    )


