        ref_id: ServerPlanRefId,
        *,
        revision_ids: Sequence[RevisionId],
        materialized_ref_ids: Sequence[ServerPlanRefId],
    ) -> None:
        super().__init__(ref_id)
        self._revision_ids: FtsRevisionPartitionRows = tuple(revision_ids)
        self._materialized_ref_ids = tuple(str(ref_id) for ref_id in materialized_ref_ids)

