        return frozenset({"fts", "versioned", "materialization", "partition", "virtual"})

    def tables_read(self: PartitionRevisionIdsByMaterializationStep) -> frozenset[str]:
        return frozenset()

    def tables_written(self: PartitionRevisionIdsByMaterializationStep) -> frozenset[str]:
        return frozenset()

    def dependencies(self: PartitionRevisionIdsByMaterializationStep) -> frozenset[str]:
        return frozenset(self._materialized_ref_ids)

