            provenance_manifest=provenance_manifest,
            allow_empty_provenance_manifest=allow_empty_manifest,
            use_savepoint_recovery=False,
        )


class DropTriggersIntent(IntentStep[None]):
    """Schema-level intent for dropping a group of triggers."""

    intent_tags = frozenset({"write", "schema", "ddl", "drop_trigger", "intent"})
    intent_cardinality = Cardinality.NONE
    intent_read_only = False

    def __init__(
        self: DropTriggersIntent,
        ref_id: ServerPlanRefId,
        *,
        config: DropTriggersConfig,
    ) -> None:
        super().__init__(ref_id)
        self._config = config

    def lower(self: DropTriggersIntent, ctx: LoweringContext) -> list[ServerPlanStep[Any]]:
        if ctx.backend_profile.traits.trigger_drop_transport is TriggerDropTransport.SPLIT_TARGETS and len(self._config.targets) > 1:
            return [
                DropTriggerStep(
                    self.ref_id if idx == 0 else ServerPlanRefId(f"{self.ref_id}__{idx}"),
                    config=DropTriggersConfig(
                        targets=(target,),
                        if_exists=self._config.if_exists,
                    ),
                )
                for idx, target in enumerate(self._config.targets)
            ]
        return [
            DropTriggerStep(
                self.ref_id,
                config=self._config,
            ),
        ]

