class ProjectedModelResultStep[T: BaseModel](SqlRelationPublisherStep[T]):
    """Hydrate declared fields without filtering or reshaping source rows."""

    def __init__(
        self: ProjectedModelResultStep,
        ref_id: ServerPlanRefId,
        *,
        source_ref: ServerPlanRefId,
        model_cls: type[T],
        columns: tuple[str, ...],
        json_columns: frozenset[str],
    ) -> None:
        super().__init__(ref_id)
        if not columns or len(set(columns)) != len(columns) or not set(columns) <= model_cls.model_fields.keys():
            raise ValueError("Model projections require distinct declared fields")
        if not json_columns <= set(columns):
            raise ValueError("JSON hints require projected fields")
        self.source_ref = source_ref
        self.model_cls = model_cls
        self.columns = columns
        self.json_columns = json_columns
        self._column_type_hints = combine_sql_column_type_hints(
            columns,
            SqlColumnTypeHints(jsonb_columns=json_columns),
            model_field_sql_column_type_hints(model_cls, {column: column for column in columns if column not in json_columns}),
        )

    @property
    def level(self: ProjectedModelResultStep[T]) -> int:
        return 0

    def dependencies(self: ProjectedModelResultStep[T]) -> frozenset[str]:
        return frozenset({str(self.source_ref)})

    def step_tags(self: ProjectedModelResultStep[T]) -> frozenset[str]:
        return frozenset({"read", "projection", "grammar"})

    def is_read_only(self: ProjectedModelResultStep[T]) -> bool:
        return True

    def execution_role(self: ProjectedModelResultStep[T]) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def supports_sql_batch_transport(self: ProjectedModelResultStep[T]) -> bool:
        return True

    def supports_ordered_sql_statement_batch(self: ProjectedModelResultStep[T]) -> bool:
        return True

    def result_cardinality(self: ProjectedModelResultStep[T]) -> Cardinality:
        return Cardinality.ONE

    def tables_read(self: ProjectedModelResultStep[T]) -> frozenset[str]:
        return frozenset()

    def tables_written(self: ProjectedModelResultStep[T]) -> frozenset[str]:
        return frozenset()

    def cte_publication_contract(self: ProjectedModelResultStep[T]) -> CtePublicationContract:
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=self.columns,
            column_type_hints=self._column_type_hints,
            model_cls=self.model_cls,
            relation_role=self.cte_relation_role(),
            source_tables=None,
            relation_contract=CteRelationContract.semantic_row(self.model_cls),
        )

    def _select(self: ProjectedModelResultStep[T], ctx: CompilationContext) -> SqlSelect:
        selections = [
            SqlSelectAlias(
                lower_scalar_server_ref(
                    ServerRefs.from_ref_id(ServerPlanRefId(f"{self.source_ref}.{column}"), variant="scalar", type_hint=object), ctx
                ),
                SqlAliasName(column),
            )
            for column in self.columns
        ]
        return SqlSelect(select=SqlSelectList(selections))

    def compile(self: ProjectedModelResultStep[T], ctx: CompilationContext) -> CompiledStep[T]:
        shape = output_shape_for_synthetic_columns(self.columns)
        return CompiledStep(
            grammar=self._select(ctx),
            needs_returning=True,
            closed_post_op=CompiledPostOp.materialize(
                ResultMaterializationSpec(
                    behavior=PostOpBehavior.TERMINAL_OBJECT,
                    structured_result=StructuredResultSpec(
                        result_cls=self.model_cls,
                        fields=tuple(
                            StructuredResultField(
                                output_name=column,
                                source_column=column,
                                scalar_coercion=ScalarCoercionKind.JSON if column in self.json_columns else ScalarCoercionKind.NONE,
                            )
                            for column in self.columns
                        ),
                    ),
                )
            ),
            output_shape=shape,
            result_relation=DeclaredResultRelation.from_output_shape(shape),
            column_type_hints=self._column_type_hints,
            auxiliary_ctes=collect_dependency_auxiliary_ctes(ctx, self.dependencies()),
        )

"""Instance preparation for compiled write steps.

When compile() produces SQL grammar directly, the instances haven't gone through
the full write preparation pipeline (which normally sets type_name, sys_id,
timestamps, etc.). This module extracts the minimal preparation logic needed
for the compiled path.
"""

from __future__ import annotations

from datetime import UTC, datetime
from typing import TYPE_CHECKING, Any

from l1050_polymorphism.type_filter_helper import (
    canonical_polymorphic_type_name,
    collect_deprecated_polymorphic_type_names,
)
from l2055_lazy_result.purity import pure_lazy

if TYPE_CHECKING:
    from l1000_schema.schema_def import DatabaseObjectRow


def _is_deprecated_polymorphic_fallback(
    model_cls: type[DatabaseObjectRow],
    instance: DatabaseObjectRow,
) -> bool:
    """Return whether a base instance represents a deprecated concrete subtype."""
    if type(instance) is not model_cls:
        return False
    actual_type_name = getattr(instance, "type_name", None)
    if actual_type_name is None:
        return False

    deprecated_type_names = collect_deprecated_polymorphic_type_names(model_cls)
    return isinstance(actual_type_name, str) and actual_type_name in deprecated_type_names


def prepare_instance_for_insert_lazy(
    model_cls: type[DatabaseObjectRow],
    instance: DatabaseObjectRow,
) -> DatabaseObjectRow:
    """Prepare deterministic insert metadata for compiled write steps."""
    updates: dict[str, Any] = {}

    if hasattr(model_cls, "__polymorphic__") and model_cls.__polymorphic__:
        instance_type: type[DatabaseObjectRow] = type(instance)
        if hasattr(instance, "type_name"):
            canonical_type_name = canonical_polymorphic_type_name(instance_type)
            if getattr(instance, "type_name") != canonical_type_name:
                updates["type_name"] = canonical_type_name

    missing_runtime_defaults: list[str] = []
    if "sys_id" in model_cls.model_fields and getattr(instance, "sys_id", None) is None:
        missing_runtime_defaults.append("sys_id")

    from l9600_graphs.graph import Graph

    if issubclass(model_cls, Graph) and getattr(instance, "graph_id", None) is None:
        graph_id = getattr(instance, "sys_id", None)
        if graph_id is None:
            missing_runtime_defaults.append("graph_id")
        else:
            updates["graph_id"] = graph_id
    if "created_at" in model_cls.model_fields and getattr(instance, "created_at", None) is None:
        missing_runtime_defaults.append("created_at")
    if "updated_at" in model_cls.model_fields and getattr(instance, "updated_at", None) is None:
        missing_runtime_defaults.append("updated_at")
    if missing_runtime_defaults:
        fields = ", ".join(missing_runtime_defaults)
        msg = f"Compiled lazy insert requires pre-populated runtime defaults: {fields}"
        raise ValueError(msg)

    if "sys_fts_content_hash" in model_cls.model_fields and getattr(instance, "sys_fts_content_hash", None) is None:
        from l5100_fts.fts_config import compute_fts_content_hash, get_fts_config

        fts_config: Any = get_fts_config(model_cls)
        if fts_config is not None:
            updates["sys_fts_content_hash"] = compute_fts_content_hash(instance, fts_config)

    if updates:
        return instance.model_copy(update=updates)
    return instance


def prepare_instance_for_insert(
    model_cls: type[DatabaseObjectRow],
    instance: DatabaseObjectRow,
) -> DatabaseObjectRow:
    """Prepare deterministic insert metadata outside a lazy call chain."""
    return prepare_instance_for_insert_lazy(model_cls, instance)


def prepare_instance_for_upsert_lazy(
    model_cls: type[DatabaseObjectRow],
    instance: DatabaseObjectRow,
) -> DatabaseObjectRow:
    """Prepare deterministic upsert metadata for compiled write steps."""
    return prepare_instance_for_insert_lazy(model_cls, instance)


def prepare_instance_for_upsert(
    model_cls: type[DatabaseObjectRow],
    instance: DatabaseObjectRow,
) -> DatabaseObjectRow:
    """Prepare deterministic upsert metadata outside a lazy call chain."""
    return prepare_instance_for_upsert_lazy(model_cls, instance)


def prepare_instance_for_update(
    model_cls: type[DatabaseObjectRow],
    instance: DatabaseObjectRow,
) -> DatabaseObjectRow:
    """Prepare an instance for UPDATE compilation."""
    updates: dict[str, Any] = {}

    if hasattr(model_cls, "__polymorphic__") and model_cls.__polymorphic__:
        if _is_deprecated_polymorphic_fallback(model_cls, instance):
            if "updated_at" in model_cls.model_fields:
                return instance.model_copy(update={"updated_at": datetime.now(UTC)})
            return instance

        instance_type: type[DatabaseObjectRow] = type(instance)
        if hasattr(instance, "type_name"):
            canonical_type_name = canonical_polymorphic_type_name(instance_type)
            actual_type_name = getattr(instance, "type_name", None)
            allowed_type_names = {None, canonical_type_name, instance_type.__name__}
            if actual_type_name not in allowed_type_names:
                msg = f"Cannot change type_name for polymorphic update: {actual_type_name!r} != {canonical_type_name!r}"
                raise ValueError(msg)
            updates["type_name"] = canonical_type_name

    if "sys_fts_content_hash" in model_cls.model_fields:
        from l5100_fts.fts_config import compute_fts_content_hash, get_fts_config

        fts_config: Any = get_fts_config(model_cls)
        if fts_config is not None:
            updates["sys_fts_content_hash"] = compute_fts_content_hash(instance, fts_config)

    if "updated_at" in model_cls.model_fields:
        updates["updated_at"] = datetime.now(UTC)

    if updates:
        return instance.model_copy(update=updates)
    return instance

"""SQL-visible literal row producers for bootstrap contract refs."""

from __future__ import annotations

from collections.abc import Mapping
from datetime import date, datetime
from typing import Any
from uuid import UUID

from impl.common.l2100_sql_grammar.domain.infra.stmt_cte_helpers import SqlSelectExpressions
from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlParam
from l1400_types import DynamicFieldName, ServerPlanRefId
from l2070_batching.cardinality import Cardinality
