from l2070_batching.post_op import literal_post_op
from l2070_batching.sql_column_type_hints import SqlColumnTypeHints
from l2070_batching.step import (
    CtePublicationContract,
    CteRelationContract,
    SqlRelationPublisherStep,
    StepExecutionRole,
)


def _literal_row_type_hints(values: Mapping[str, object]) -> SqlColumnTypeHints:
    text_columns: set[str] = set()
    bool_columns: set[str] = set()
    integer_columns: set[str] = set()
    bigint_columns: set[str] = set()
    double_columns: set[str] = set()
    uuid_columns: set[str] = set()
    timestamptz_columns: set[str] = set()
    date_columns: set[str] = set()
    bytea_columns: set[str] = set()
    jsonb_columns: set[str] = set()
    for column, value in values.items():
        if isinstance(value, bool):
            bool_columns.add(column)
        elif isinstance(value, int):
            bigint_columns.add(column)
        elif isinstance(value, float):
            double_columns.add(column)
        elif isinstance(value, UUID):
            uuid_columns.add(column)
        elif isinstance(value, datetime):
            timestamptz_columns.add(column)
        elif isinstance(value, date):
            date_columns.add(column)
        elif isinstance(value, bytes | bytearray | memoryview):
            bytea_columns.add(column)
        elif isinstance(value, str) or value is None:
            text_columns.add(column)
        else:
            jsonb_columns.add(column)
    return SqlColumnTypeHints(
        jsonb_columns=frozenset(jsonb_columns),
        uuid_columns=frozenset(uuid_columns),
        timestamptz_columns=frozenset(timestamptz_columns),
        date_columns=frozenset(date_columns),
        bool_columns=frozenset(bool_columns),
        integer_columns=frozenset(integer_columns),
        bigint_columns=frozenset(bigint_columns),
        double_columns=frozenset(double_columns),
        text_columns=frozenset(text_columns),
        bytea_columns=frozenset(bytea_columns),
    )


class BootstrapContractSeedStep(SqlRelationPublisherStep[dict[str, object]]):
    """Publish a precomputed bootstrap contract row as a one-row SQL CTE."""

    def __init__(
        self: BootstrapContractSeedStep,
        ref_id: ServerPlanRefId,
        values: Mapping[DynamicFieldName, object],
        *,
        dependency_refs: tuple[ServerPlanRefId, ...] = (),
    ) -> None:
        if not values:
            msg = "Bootstrap contract seed rows must publish at least one column."
            raise TypeError(msg)
        super().__init__(ref_id)
        self._values = {str(field_name): value for field_name, value in values.items()}
        self._dependency_refs = tuple(dependency_refs)

    @property
    def level(self: BootstrapContractSeedStep) -> int:
        return 0

    def result_cardinality(self: BootstrapContractSeedStep) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self: BootstrapContractSeedStep) -> bool:
        return True

    def execution_role(self: BootstrapContractSeedStep) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def bootstrap_backend_statement_count_override(self: BootstrapContractSeedStep) -> int | None:
        return 0

    def step_tags(self: BootstrapContractSeedStep) -> frozenset[str]:
        return frozenset({"bootstrap", "contract_seed", "literal_row"})

    def dependencies(self: BootstrapContractSeedStep) -> frozenset[str]:
        return frozenset(str(ref_id) for ref_id in self._dependency_refs)

    def tables_read(self: BootstrapContractSeedStep) -> frozenset[str]:
        return frozenset()

    def tables_written(self: BootstrapContractSeedStep) -> frozenset[str]:
        return frozenset()

    def cte_publication_contract(self: BootstrapContractSeedStep) -> CtePublicationContract:
        columns = tuple(self._values)
        column_type_hints = _literal_row_type_hints(self._values)
        column_type_hints.require_complete(columns)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=columns,
            column_type_hints=column_type_hints,
            relation_contract=CteRelationContract.literal_mapping(columns=columns),
            relation_role=self.cte_relation_role(),
        )

    def compile(self: BootstrapContractSeedStep, ctx: CompilationContext) -> CompiledStep[dict[str, object]]:
        del ctx
        contract = self.cte_publication_contract()
        output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(
            contract,
        )
        return CompiledStep(
            grammar=SqlSelectExpressions(
                [(SqlParam(value), column) for column, value in self._values.items()],
            ),
            needs_returning=True,
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
            closed_post_op=literal_post_op(dict(self._values)),
        )


__all__ = ["BootstrapContractSeedStep"]

"""Catalog-backed projection construction for versioned merged reads.

The catalog owns overlay identity at the ServerPlan boundary. See
``docs/design/architecture_linter_rules/serverplan/versioned_merged_identity.md``.
"""

from __future__ import annotations

from collections.abc import Sequence
from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName
from impl.common.l2100_sql_grammar.base import GrammarException
from impl.common.l2100_sql_grammar.domain.versioning.stmt_versioned import (
    VersionedMergedReadProjection,
    VersionedOverlayIdentity,
)
from l1000_schema.schema_def import DatabaseObjectRow
from l2055_lazy_result.purity import pure_lazy
from l2070_batching.planning_catalog import (
    READ_FLAVOR_QUERY_ROWS,
    VersionedReadProjection,
    build_read_metadata_plan_for_sources,
    build_read_metadata_plan_lazy,
)

_GENERATED_MERGED_SUPPORT_COLUMNS: tuple[SqlColumnName, ...] = (SqlColumnName("branch_id"),)


@pure_lazy
def versioned_merged_projection_from_catalog(
    read_projection: VersionedReadProjection,
    *,
    selected_columns: Sequence[SqlColumnName] | None = None,
    selected_source_columns: Sequence[SqlColumnName] | None = None,
    support_source_columns: Sequence[SqlColumnName] = (),
    use_cte_output_columns: bool = False,
) -> VersionedMergedReadProjection:
    """Build one merged projection from a typed catalog projection."""
    identity_fields = tuple(field for field in read_projection.fields if field.field_name == "sys_id")
    if len(identity_fields) != 1:
        identity_names = tuple(field.field_name for field in identity_fields)
        msg = (
            "Versioned merged catalog projection requires exactly one sys_id field. "
            f"Found {len(identity_fields)} fields: {identity_names!r}."
        )
        raise GrammarException(msg)
    identity_field = identity_fields[0]

    versioning_metadata_sources = frozenset(
        {"revision_id", "sys_revision_id", "staged_commit_id", "sys_staged_commit_id", "sys_deleted"},
    )
    merged_data_fields = tuple(field for field in read_projection.data_fields if field.db_column not in versioning_metadata_sources)
    source_by_name: dict[SqlColumnName, SqlColumnName] = {}
    for field in read_projection.fields:
        source_column = SqlColumnName("sys_id" if field.field_name == "sys_id" else field.db_column)
        source_by_name[SqlColumnName(field.db_column)] = source_column
        source_by_name[SqlColumnName(field.cte_output_column)] = source_column
        source_by_name[source_column] = source_column
    for support_column in (*_GENERATED_MERGED_SUPPORT_COLUMNS, *support_source_columns):
        source_by_name[support_column] = support_column

    if selected_columns is None:
        output_columns = tuple(
            SqlColumnName(field.cte_output_column if use_cte_output_columns else field.db_column) for field in merged_data_fields
        )
        resolved_sources = tuple(
            SqlColumnName("sys_id" if field.field_name == "sys_id" else field.db_column) for field in merged_data_fields
        )
    else:
        output_columns = tuple(selected_columns)
        if selected_source_columns is None:
            unknown = tuple(column for column in output_columns if column not in source_by_name)
            if unknown:
                msg = (
                    f"Versioned merged catalog projection has unknown output columns: {unknown!r}. "
                    f"Declared support columns: {tuple(support_source_columns)!r}."
                )
                raise GrammarException(msg)
            resolved_sources = tuple(source_by_name[column] for column in output_columns)
        else:
            requested_sources = tuple(selected_source_columns)
            if len(requested_sources) != len(output_columns):
                msg = "Versioned merged catalog projection source/output column lengths must match."
                raise GrammarException(msg)
            source_resolution = {
                **source_by_name,
                **{source: source for source in source_by_name.values()},
            }
            unknown = tuple(column for column in requested_sources if column not in source_resolution)
            if unknown:
                msg = f"Versioned merged catalog projection has unknown source columns: {unknown!r}."
                raise GrammarException(msg)
            resolved_sources = tuple(source_resolution[column] for column in requested_sources)

    return VersionedMergedReadProjection(
        data_columns=output_columns,
        overlay_identity=VersionedOverlayIdentity(SqlColumnName(identity_field.field_name)),
        source_columns=resolved_sources,
    )


@pure_lazy
def catalog_versioned_merged_projection(
    model_cls: type[DatabaseObjectRow],
    columns: Sequence[SqlColumnName],
    *,
    source_columns: Sequence[SqlColumnName] | None = None,
    source_models: Sequence[type[DatabaseObjectRow]] = (),
    support_source_columns: Sequence[SqlColumnName] = (),
) -> VersionedMergedReadProjection:
    """Build a query-row merged projection from catalog-owned identity and sources."""
    read_metadata = (
        build_read_metadata_plan_for_sources(model_cls, source_models) if source_models else build_read_metadata_plan_lazy(model_cls)
    )
    read_projection = read_metadata.projection_for(READ_FLAVOR_QUERY_ROWS)
    return versioned_merged_projection_from_catalog(
        read_projection,
        selected_columns=columns,
        selected_source_columns=source_columns,
        support_source_columns=support_source_columns,
    )

from __future__ import annotations

from abc import abstractmethod
