from impl.common.l2060_query_spec.mutation_spec import (
    DeleteSpec,
    InsertFromQuerySpec,
    InsertSpec,
    MutationSpec,
    UpdateSpec,
)
from impl.common.l2060_query_spec.query_source import query_source_table_name
