def _mutation_tables_read(spec: MutationSpec) -> frozenset[str]:
    tables: set[str] = set()
    if isinstance(spec, InsertFromQuerySpec):
        source = spec.source_query.source
        if source is not None:
            tables.add(str(query_source_table_name(source)))
    if isinstance(spec, (UpdateSpec, DeleteSpec)):
        for join in spec.joins:
            target_source = getattr(join, "target_source", None)
            if target_source is not None:
                tables.add(str(query_source_table_name(target_source)))
    return frozenset(tables)


class MutationSpecStep(MaybeSqlRelationPublisherStep[Any]):
    """Terminal ServerPlan bridge for query-builder mutation specs."""

    __slots__ = ("_mutation_spec",)

    def __init__(self, ref_id: ServerRefs | str, mutation_spec: MutationSpec) -> None:
        super().__init__(str(ref_id))
        self._mutation_spec = mutation_spec

    @property
    def level(self: MutationSpecStep) -> int:
        return 0

    def step_tags(self: MutationSpecStep) -> frozenset[str]:
        tags = {"write", "mutation_spec"}
        if isinstance(self._mutation_spec, (InsertSpec, InsertFromQuerySpec)):
            tags.add("insert")
        elif isinstance(self._mutation_spec, UpdateSpec):
            tags.add("update")
        elif isinstance(self._mutation_spec, DeleteSpec):
            tags.add("delete")
        return frozenset(tags)

    def is_read_only(self: MutationSpecStep) -> bool:
        return False

    def result_cardinality(self: MutationSpecStep) -> Cardinality:
        return Cardinality.NONE if not self._mutation_spec.returning else Cardinality.MANY

    def tables_read(self: MutationSpecStep) -> frozenset[str]:
        return _mutation_tables_read(self._mutation_spec)

    def tables_written(self: MutationSpecStep) -> frozenset[str]:
        return frozenset({str(query_source_table_name(self._mutation_spec.target))})

    def cte_publication_contract(self: MutationSpecStep) -> CtePublicationContract:
        def _legacy_cte_output_columns() -> tuple[str, ...] | None:
            if not self._mutation_spec.returning:
                return None
            return tuple(str(column) for column in self._mutation_spec.returning)

        columns = _legacy_cte_output_columns()

        def _legacy_cte_column_type_hints(columns: tuple[str, ...] | None) -> SqlColumnTypeHints | None:
            if not self._mutation_spec.returning:
                return None
            return SqlColumnTypeHints()

        column_type_hints = _legacy_cte_column_type_hints(columns)
        if columns is None:
            if column_type_hints is not None and column_type_hints.has_any():
                msg = f"{type(self).__name__} declares SQL column type hints without an explicit cte_output_columns() contract."
                raise TypeError(msg)
            return CtePublicationContract.non_publishing()
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        contract_columns = tuple(str(column) for column in columns)
        target_table = str(query_source_table_name(self._mutation_spec.target))
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=contract_columns,
            column_type_hints=column_type_hints,
            relation_contract=CteRelationContract.table_projection(
                source_table=target_table,
                projection_lineage=tuple((column, column) for column in contract_columns),
            ),
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def compile(self: MutationSpecStep, ctx: CompilationContext) -> CompiledStep[Any]:
        contract = self.cte_publication_contract()
        output_shape = output_shape_from_cte_publication_contract(contract) if contract is not None else None
        return CompiledStep(
            output_shape=output_shape,
            result_relation=DeclaredResultRelation.from_output_shape(output_shape) if output_shape is not None else None,
            column_type_hints=contract.column_type_hints if contract is not None else None,
            grammar=compile_mutation_spec(self._mutation_spec, compilation_context=ctx),
            needs_returning=bool(self._mutation_spec.returning),
        )

