class _ReplacePostings(NonPublishingStep[None]):
    def __init__(self: _ReplacePostings, windows: tuple[dict[str, object], ...]) -> None:
        super().__init__(ServerPlanRefId("replace_incident_postings"))
        self.windows = windows

    @property
    def level(self: _ReplacePostings) -> int:
        return 0

    def result_cardinality(self: _ReplacePostings) -> Cardinality:
        return Cardinality.NONE

    def tables_read(self: _ReplacePostings) -> frozenset[str]:
        return frozenset()

    def tables_written(self: _ReplacePostings) -> frozenset[str]:
        return frozenset({"sys_graph_incident_postings"})

    def is_read_only(self: _ReplacePostings) -> bool:
        return False

    def compile(self: _ReplacePostings, ctx: CompilationContext) -> CompiledStep[None]:
        windows = SqlUnionAll([SqlSelect(select=[
            SqlColumnAlias(SqlParam(value, cast_type=(
                SqlTypeName("UUID") if name in {"branch_id", "graph_sys_id", "sys_id", "source_sys_id", "target_sys_id"}
                else SqlTypeName("BOOLEAN") if name == "sys_deleted" else SqlTypeName("BIGINT")
            ) if ctx.backend_profile.traits.backend_type is BackendType.POSTGRES else None), SqlAliasName(name))
            for name, value in row.items()
        ]) for row in self.windows])
        return CompiledStep(grammar=replace_incident_window_postings(windows, edge_table=SqlTableName("sample_edges"),
            joined_delete=ctx.backend_profile.traits.backend_type is BackendType.MARIADB),
            closed_post_op=literal_post_op(None), allow_empty_provenance_manifest=True)


@pytest.mark.parametrize("rollback", [False, True])
def test_window_replacement_preserves_history_and_rolls_back(db_connection: SyncDatabaseConnection, rollback: bool, system_session_id: SessionId) -> None:
    branch, graph, edge, source, old_target, new_target = BranchId.new(), SysId.new(), SysId.new(), SysId.new(), SysId.new(), SysId.new()
    original: dict[str, object] = dict(branch_id=branch, graph_sys_id=graph, sys_id=edge,
        source_sys_id=source, target_sys_id=old_target, valid_from_seq=1, valid_to_seq=None, sys_deleted=False)

    def publish(rows: tuple[dict[str, object], ...], fail: bool) -> None:
        def write(txn: SyncWriteTransaction) -> None:
            plan = txn.plan()
            assert isinstance(plan, BaseServerPlan)
            plan.add_step(_ReplacePostings(rows))
            plan.execute()
            if fail:
                raise RuntimeError("injected posting maintenance failure")
        db_connection.session(SessionId.schema()).write(fn=write)

    def snapshot() -> set[tuple[object, ...]]:
        columns = ("direction", "endpoint_sys_id", "bucket_level", "bucket_number", "valid_from_seq", "valid_to_seq")
        rows = fetchall_raw_sql_for_tests(db_connection, SqlSelect(select=SqlStar(), from_=SqlTableIdent(SqlTableName("sys_graph_incident_postings"))))
        return {tuple(str(row[column]) if column == "endpoint_sys_id" else row[column] for column in columns) for row in rows}

    publish((original,), False)
    before = snapshot()
    changed = (original | {"valid_to_seq": 8}, original | {"valid_from_seq": 8, "target_sys_id": new_target})
    if rollback:
        with pytest.raises(RuntimeError, match="injected posting maintenance failure"):
            publish(changed, True)
        assert snapshot() == before
    else:
        publish(changed, False)
        after = snapshot()
        assert after != before
        assert {row[4:] for row in after} == {(1, 8), (8, None)}
        assert {row[1] for row in after if row[0] == 1 and row[4] == 1} == {str(old_target)}
        assert {row[1] for row in after if row[0] == 1 and row[4] == 8} == {str(new_target)}
        publish((changed[1] | {"valid_to_seq": 12}, original | {"valid_from_seq": 12, "sys_deleted": True}), False)
        assert {row[4:] for row in snapshot()} == {(1, 8), (8, 12)}

