def snapshot_table(source_ref: ServerPlanRefId) -> SqlTableIdent:
    return SqlTableIdent(
        SqlTableName("_nera_json_" + sha256(str(source_ref).encode()).hexdigest()[:20])
    )


def capture_compiled_json[T](
    compiled: CompiledStep[T],
    source_ref: ServerPlanRefId,
    contract: CtePublicationContract,
) -> CompiledStep[T]:
    table = snapshot_table(source_ref)
    stored = SqlSelect(select=SqlSelectList([SqlStar()]), from_=table)
    return replace(
        compiled,
        grammar=stored,
        params=None,
        auxiliary_ctes=None,
        compiled_sql_publication=compiled_sql_publication_from_query(
            ref_id=source_ref,
            query=stored,
            contract=contract,
        ),
    )


class CaptureJsonStep[T](NonPublishingStep[int]):
    """Materialize a query after its resource reset and before dependent reads.

    Separate plan operations expose resource lifetime to the optimizer, rather
    than hiding order in a statement batch. See
    ``docs/design/serverplan_linter_rules/SPQ-053.md``.
    """

    def __init__(
        self: Self,
        ref_id: ServerPlanRefId,
        *,
        source: QueryExecuteStep[T],
        source_ref: ServerPlanRefId,
        after_ref: ServerPlanRefId,
    ) -> None:
        if not source.is_read_only():
            raise ValueError("JSON snapshot capture requires a read-only query producer")
        super().__init__(ref_id)
        self.source = source
        self.source_ref = source_ref
        self.after_ref = after_ref

    @property
    def level(self: CaptureJsonStep[T]) -> int:
        return 0

    def is_read_only(self: CaptureJsonStep[T]) -> bool:
        return False

    def result_cardinality(self: CaptureJsonStep[T]) -> Cardinality:
        return Cardinality.NONE

    def dependencies(self: CaptureJsonStep[T]) -> frozenset[str]:
        return self.source.dependencies() | frozenset({self.after_ref})

    def tables_read(self: CaptureJsonStep[T]) -> frozenset[str]:
        return self.source.tables_read()

    def tables_written(self: CaptureJsonStep[T]) -> frozenset[str]:
        return frozenset({snapshot_table(self.source_ref).name})

    def compile(self: CaptureJsonStep[T], ctx: CompilationContext) -> CompiledStep[int]:
        compiled = self.source.compile(ctx)
        query = compiled.grammar
        if query is None:
            raise ValueError("JSON capture requires a SQL query")
        if compiled.auxiliary_ctes:
            query = SqlCte(compiled.auxiliary_ctes, query)
        output_shape, result_relation, column_type_hints = no_result_compiled_artifacts()
        return CompiledStep(
            grammar=SqlCreateTemporaryTableAs(snapshot_table(self.source_ref), query),
            params=compiled.params,
            closed_post_op=literal_post_op(0),
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
            allow_empty_provenance_manifest=True,
        )


class DropCapturedJsonIntent(IntentStep[int]):
    """Release the captured relation after the final SQL result consumes it."""

    intent_tags = frozenset({"write", "intent", "cleanup"})

    def __init__(
        self: DropCapturedJsonIntent,
        ref_id: ServerPlanRefId,
        *,
        source_ref: ServerPlanRefId,
        after_ref: ServerPlanRefId,
    ) -> None:
        super().__init__(ref_id)
        self.source_ref = source_ref
        self.after_ref = after_ref

    def dependencies(self: DropCapturedJsonIntent) -> frozenset[str]:
        return frozenset({self.source_ref, self.after_ref})

    def lower(self: DropCapturedJsonIntent, ctx: LoweringContext) -> list[ServerPlanStep[int]]:
        return [
            GrammarEffectStep(
                self.ref_id,
                SqlDropTemporaryTableIfExists(snapshot_table(self.source_ref)),
                _GrammarExecuteConfig(
                    reads=frozenset(),
                    writes=frozenset(),
                    after_refs=frozenset({self.source_ref, self.after_ref}),
                ),
            )
        ]

