class SelectOneStep[T](NonPublishingStep[T | None]):
    """Step for selecting a single record by sys_id.

    Uses ``ServerRef`` for the sys_id parameter, which handles:
    * Literal values (direct SQL parameter)
    * ServerRef dependencies (CTE subquery in batch compilation)
    * LazyResult deferred values (resolved during preprocess)
    """

    def __init__(
        self: SelectOneStep,
        ref_id: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        sys_id: object,
        *,
        permission_grammar: SqlRenderable | None = None,
        column_masking: tuple[SqlColumnName, list[SqlColumnName]] | None = None,
        session_id_str: SessionId | None = None,
        permission_state_override: QueryPermissionState | None = None,
        permission_context_ref: ServerPlanRefId | None = None,
        permission_context_type: type[ResolvedSessionContext] | None = None,
    ) -> None:
        super().__init__(ref_id)
        self._model_cls = model_cls
        self._sys_id = sys_id
        self._permission_grammar = permission_grammar
        self._column_masking = column_masking
        self._session_id_str = session_id_str
        self._permission_state_override = permission_state_override
        self._permission_context_ref = permission_context_ref
        self._permission_context_type = permission_context_type

    @property
    def level(self: SelectOneStep) -> int:
        return 1

    def step_tags(self: SelectOneStep) -> frozenset[str]:
        return frozenset({"read", "select_one"})

    def is_read_only(self: SelectOneStep) -> bool:
        return True

    def result_cardinality(self: SelectOneStep) -> Cardinality:
        return Cardinality.ONE

    def tables_read(self: SelectOneStep) -> frozenset[str]:
        from l1000_schema.table_utils import get_table_name

        return frozenset({get_table_name(self._model_cls)})

    def cte_rewritable_read_tables(self: SelectOneStep) -> frozenset[str]:
        if self._permission_grammar is not None:
            return frozenset()
        return self.tables_read()

    def tables_written(self: SelectOneStep) -> frozenset[str]:
        return frozenset()

    def publication_source_ref(self: SelectOneStep) -> ServerPlanRefId:
        """Return the raw relation that owns source-row presence after lowering."""
        return ServerPlanRefId(f"{self.ref_id}.raw")

    def dependencies(self: SelectOneStep) -> frozenset[str]:
        dependencies = set[str]()
        if isinstance(self._sys_id, ServerRef):
            dependencies.update(str(dep) for dep in self._sys_id.dependencies())
        if self._permission_context_ref is not None:
            dependencies.add(str(self._permission_context_ref))
        return frozenset(dependencies)

    def lower(self: SelectOneStep, ctx: LoweringContext) -> list[ServerPlanStep[Any]]:
        from impl.common.l2070_server_plan.steps.large_column_read import build_select_one_query_spec
        from impl.common.l2070_server_plan.steps.row_hydration import HydrateFirstResolvedRowStep
        from impl.common.l2070_server_plan.steps.select_one_by_query_raw import SelectOneByQueryRawStep

        raw_ref = ServerPlanRefId(f"{self.ref_id}.raw")
        query_spec = build_select_one_query_spec(
            self._model_cls,
            sys_id=self._sys_id,
            permission_grammar=self._permission_grammar,
            permission_state_override=self._permission_state_override,
            permission_context_ref=self._permission_context_ref,
            permission_context_type=self._permission_context_type,
            planning_catalog=ctx.planning_catalog,
        )
        return [
            SelectOneByQueryRawStep(
                raw_ref,
                self._model_cls,
                query_spec,
            ),
            HydrateFirstResolvedRowStep(
                self.ref_id,
                source_ref=raw_ref,
                model_cls=self._model_cls,
            ),
        ]

    def compile(self: SelectOneStep, ctx: CompilationContext) -> CompiledStep[T | None]:
        del ctx
        raise NotImplementedError(f"{type(self).__name__} must be lowered before compile()")

    def _combine_where(self: SelectOneStep, base_condition: SqlRenderable) -> SqlRenderable:
        """Append permission filtering to a base WHERE condition."""
        from impl.common.l2070_server_plan.steps._query_helper_compile import combine_select_one_where

        return combine_select_one_where(base_condition, self._permission_grammar)

