        self._session_source = session_source
        self._rule = rule
        self._after_refs = tuple(after_refs)

    @property
    def level(self: SqlSessionAdmissionAssertStep) -> int:
        return 0

    def step_tags(self: SqlSessionAdmissionAssertStep) -> frozenset[str]:
        return frozenset({"infrastructure", "session_validation", "assertion", "grammar"})

    def execution_role(self: SqlSessionAdmissionAssertStep) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def result_cardinality(self: SqlSessionAdmissionAssertStep) -> Cardinality:
        return Cardinality.NONE

    def is_read_only(self: SqlSessionAdmissionAssertStep) -> bool:
        return False

    def supports_sql_batch_transport(self: SqlSessionAdmissionAssertStep) -> bool:
        return True

    def requires_assertion_statement_transport(self: SqlSessionAdmissionAssertStep) -> bool:
        return True

    def is_session_gate_exempt(self: SqlSessionAdmissionAssertStep) -> bool:
        return True

    def tables_read(self: SqlSessionAdmissionAssertStep) -> frozenset[str]:
        source = session_sql_source_or_none(self._session_source)
        return frozenset({"sys_sessions"}) | (source.tables_read() if source is not None else frozenset())

    def tables_written(self: SqlSessionAdmissionAssertStep) -> frozenset[str]:
        return frozenset()

    def requires_prior_statement_visibility_after_writes(
        self: SqlSessionAdmissionAssertStep,
    ) -> frozenset[str]:
        return self.tables_read()

    def dependencies(self: SqlSessionAdmissionAssertStep) -> frozenset[str]:
        return frozenset(str(ref_id) for ref_id in self._after_refs)

    def native_assertion_error(self: SqlSessionAdmissionAssertStep) -> Exception:
        reason, detail = {
            SessionAdmissionRule.EXISTS: ("not_found", "does not exist"),
            SessionAdmissionRule.OPEN: ("closed", "is closed"),
            SessionAdmissionRule.NOT_EXPIRED: ("expired", "has expired"),
            SessionAdmissionRule.USER_IDENTITY: (
                "missing_user_id", "is not a system session but carries no user",
            ),
        }[self._rule]
        source = self._session_source
        session_id = source if isinstance(source, SessionId) else None
        display = f"Session {session_id}" if session_id is not None else "Resolved session"
        return SessionValidationError(f"{display} {detail}", session_id=session_id, reason=reason)

    def compile(self: SqlSessionAdmissionAssertStep, ctx: CompilationContext) -> CompiledStep[None]:
        gate = build_session_admission_rule_query(
            session_id_sql(self._session_source, ctx),
            rule=self._rule,
            require_authenticated_row=not isinstance(self._session_source, SessionId),
        )
        output_shape, result_relation, column_type_hints = no_result_compiled_artifacts()
        return CompiledStep(
            grammar=SqlNativePredicateAssertion(
                SqlSelectExpressions([(SqlExists(gate), "value")]),
                message="NERA_ASSERTION:" + str(self.ref_id),
            ),
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
            closed_post_op=literal_post_op(None),
            auxiliary_ctes=collect_dependency_auxiliary_ctes(ctx, self.dependencies()),
        )

"""Helpers for splitting oversized literal ``IN`` query specs."""

from __future__ import annotations

from collections.abc import Sequence
from dataclasses import replace
from typing import Any

from l2060_query_builder.query_contracts import QueryFilter
from l1000_schema.typed_field import Expression
from impl.common.l2050_sql_types.backend_type import BackendType


def _literal_in_chunk_size(backend_type: object) -> int:
    """Return a conservative per-statement literal ``IN`` value budget."""
    from impl.common.l2070_server_plan.param_budget import fused_sql_param_budget
    from impl.common.l2070_server_plan.steps.insert_many_raw import _UNBOUNDED_PARAM_ROW_THRESHOLD

    budget = fused_sql_param_budget(backend_type) if isinstance(backend_type, BackendType) else None
    if budget is None:
        return _UNBOUNDED_PARAM_ROW_THRESHOLD
    return max(1, min(_UNBOUNDED_PARAM_ROW_THRESHOLD, budget))


def _is_literal_in_filter(filter_obj: object) -> bool:
    if not isinstance(filter_obj, QueryFilter):
        return False
    if filter_obj.expression is not None:
        expression = filter_obj.expression
        return str(expression.operator).upper() == "IN" and isinstance(expression.value, list | tuple)
    if filter_obj.column is None:
        return False
    return str(filter_obj.operator).upper() == "IN" and isinstance(filter_obj.value, list | tuple)


def _literal_in_filter_values(filter_obj: QueryFilter) -> Sequence[object]:
    if filter_obj.expression is not None:
        value = filter_obj.expression.value
    else:
        value = filter_obj.value
    if not isinstance(value, list | tuple):
        msg = "Literal IN filter values must be a list or tuple."
        raise TypeError(msg)
    return value


def _replace_literal_in_filter_values(filter_obj: QueryFilter, values: Sequence[object]) -> QueryFilter:
    if filter_obj.expression is None:
        return QueryFilter(
            column=filter_obj.column,
            operator=filter_obj.operator,
            value=list(values),
            json_key=filter_obj.json_key,
        )

    expression = filter_obj.expression
    return QueryFilter(
        expression=Expression(
            field=expression.field,
            operator=expression.operator,
            value=list(values),
            left=expression.left,
            right=expression.right,
            logical_op=expression.logical_op,
            function=expression.function,
            args=expression.args,
            owner=expression.owner,
            server_ref_dependencies=expression.server_ref_dependencies,
        ),
    )


def _chunk_values(values: Sequence[object], chunk_size: int) -> list[tuple[object, ...]]:
    return [tuple(values[start : start + chunk_size]) for start in range(0, len(values), chunk_size)]


def split_query_spec_on_oversized_literal_in(
    query_spec: Any,
    *,
    backend_type: object,
    preserve_read_semantics: bool,
) -> list[Any] | None:
    """Split a query spec with one oversized simple literal ``IN`` filter.

    Read splitting is intentionally conservative because ORDER BY, LIMIT,
    DISTINCT, aggregation, joins, and search operators need whole-query
    semantics. Write/delete splitting can preserve semantics for a plain
    conjunction of filters because each chunk deletes a disjoint key subset.
    """
    if query_spec is None:
        return None
    if preserve_read_semantics and (
        getattr(query_spec, "distinct", False)
        or getattr(query_spec, "joins", None)
        or getattr(query_spec, "order_by", None)
        or getattr(query_spec, "limit", None) is not None
        or getattr(query_spec, "offset", None) not in (None, 0)
        or getattr(query_spec, "group_by", None)
        or getattr(query_spec, "aggregations", None)
        or getattr(query_spec, "having", None)
        or getattr(query_spec, "window_functions", None)
        or query_spec.search_op.fts_query is not None
        or query_spec.search_op.vector_query_vec is not None
    ):
        return None

    filters: list[object] = list(getattr(query_spec, "filters", ()) or ())
    chunk_size = _literal_in_chunk_size(backend_type)
    oversized_filters = [
        (idx, filter_obj)
        for idx, filter_obj in enumerate(filters)
        if isinstance(filter_obj, QueryFilter)
        and _is_literal_in_filter(filter_obj)
        and len(_literal_in_filter_values(filter_obj)) > chunk_size
    ]
    if len(oversized_filters) != 1:
        return None

    index, oversized_filter = oversized_filters[0]
    chunks = _chunk_values(_literal_in_filter_values(oversized_filter), chunk_size)
    if len(chunks) <= 1:
        return None

    split_specs: list[Any] = []
    for chunk in chunks:
        chunk_filters = list(filters)
        chunk_filters[index] = _replace_literal_in_filter_values(oversized_filter, chunk)
        split_specs.append(replace(query_spec, filters=chunk_filters))
    return split_specs

