class ResultPredicateAssertionStep(SqlRelationPublisherStep[bool]):
    """Assert a SQL boolean without reading its value into Python first."""

    def __init__(
        self: ResultPredicateAssertionStep,
        ref_id: ServerPlanRefId,
        *,
        predicate_ref: ServerPlanRefId,
        error_cls: type[Exception],
        message: str,
        expected: bool = True,
    ) -> None:
        super().__init__(ref_id)
        self.predicate_ref = predicate_ref
        self.error_cls = error_cls
        self.message = message
        self.expected = expected

    @property
    def level(self: ResultPredicateAssertionStep) -> int:
        return 0

    def dependencies(self: ResultPredicateAssertionStep) -> frozenset[str]:
        return frozenset({str(self.predicate_ref)})

    def is_read_only(self: ResultPredicateAssertionStep) -> bool:
        return True

    def step_tags(self: ResultPredicateAssertionStep) -> frozenset[str]:
        return frozenset({"read", "grammar", "assertion"})

    def supports_sql_batch_transport(self: ResultPredicateAssertionStep) -> bool:
        return True

    def supports_ordered_sql_statement_batch(self: ResultPredicateAssertionStep) -> bool:
        return True

    def requires_assertion_statement_transport(self: ResultPredicateAssertionStep) -> bool:
        return True

    def prevents_sql_owned_database_commit(self: ResultPredicateAssertionStep) -> bool:
        """Keep commit outside SQL until the assertion result is decoded."""
        return True

    def native_assertion_error(self: ResultPredicateAssertionStep) -> Exception:
        """Preserve the typed validation error when MariaDB aborts the request."""
        return self.error_cls(self.message)

    def execution_role(self: ResultPredicateAssertionStep) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def result_cardinality(self: ResultPredicateAssertionStep) -> Cardinality:
        return Cardinality.ONE

    def tables_read(self: ResultPredicateAssertionStep) -> frozenset[str]:
        return frozenset()

    def tables_written(self: ResultPredicateAssertionStep) -> frozenset[str]:
        return frozenset()

    def preprocess(self: ResultPredicateAssertionStep, resolved: ResolvedRefs) -> None:
        del resolved

    def cte_publication_contract(self: ResultPredicateAssertionStep) -> CtePublicationContract:
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=("ok", "error_code", "message"),
            column_type_hints=sql_assertion_column_type_hints(),
            model_cls=SqlAssertionResultRow,
            relation_role=self.cte_relation_role(),
            source_tables=None,
            relation_contract=CteRelationContract.semantic_row(SqlAssertionResultRow),
        )

    def compile(self: ResultPredicateAssertionStep, ctx: CompilationContext) -> CompiledStep[bool]:
        predicate = lower_scalar_server_ref(
            ServerRefs.from_ref_id(
                self.predicate_ref,
                variant="scalar",
                type_hint=bool,
            ),
            ctx,
        )
        if not self.expected:
            predicate = sql_not(predicate)
        shape = sql_assertion_output_shape()
        return CompiledStep(
            grammar=true_expression_assertion_query(predicate, error_message=self.message),
            needs_returning=True,
            closed_post_op=sql_assertion_post_op(self.message, exc_type=self.error_cls),
            output_shape=shape,
            result_relation=DeclaredResultRelation.from_output_shape(shape),
            column_type_hints=sql_assertion_column_type_hints(),
            auxiliary_ctes=collect_dependency_auxiliary_ctes(ctx, self.dependencies()),
        )

