"""Incomplete native storage must not silently remove eligible source rows."""

from __future__ import annotations

from hashlib import sha256
from typing import Literal

import pytest

from conform.bootstrap_families.search import SEARCH_V1
from conform.l5200_vector_index.test_usearch_cross_branch_all_revisions import (
    TEST_BOOTSTRAP_CONTRIBUTORS,
    TEST_BOOTSTRAP_TABLES as _SOURCE_TABLES,
    TEST_BOOTSTRAP_VERSIONING_DOMAINS,
    USearchScopeDocument,
    USearchScopeDomain,
    USearchScopeIndex,
    _write_document,
)
from data_layer.connection import ConnectionId
from data_layer.exceptions import NativeSearchIntegrityError
from data_layer.session import SessionId
from data_layer.transaction import SyncReadTransaction, SyncWriteTransaction
from data_layer.types import WorkspaceId
from data_layer.versioned_schema import SyncVersionedDatabaseConnection
from data_layer_testing.versioning.revision_helpers import create_test_revision
from l5200_vector_index.hnsw_models import USearchArtifactMember

TEST_BOOTSTRAP_FAMILY = SEARCH_V1
TEST_BOOTSTRAP_TABLES = (*_SOURCE_TABLES, USearchArtifactMember)


@pytest.mark.parametrize("single_branch", [False, True])
@pytest.mark.parametrize(
    "fault",
    ["member", "artifact", "digest", "payload", "epoch", "metric", "dimensions", "unknown_key"],
)
def test_missing_native_storage_fails_instead_of_returning_a_partial_result(
    db_connection: SyncVersionedDatabaseConnection,
    single_branch: bool,
    fault: Literal["member", "artifact", "digest", "payload", "epoch", "metric", "dimensions", "unknown_key"],
    system_session_id: SessionId,
) -> None:
    _, branch = create_test_revision(
        db_connection,
        USearchScopeDomain,
        workspace_id=WorkspaceId.default(),
        session_id=system_session_id,
    )
    for index, vector in enumerate(([1.0, 0.0], [0.0, 1.0])):
        _write_document(
            db_connection,
            branch,
            connection_id=ConnectionId(f"missing-native-{index}"),
            title=f"document-{index}",
            embedding=vector,
        )

    def read(txn: SyncReadTransaction) -> list[USearchScopeDocument]:
        if single_branch:
            return list(txn.query(USearchScopeDocument).vector_search("content", [1.0, 0.0], k=2).execute())
        return list(
            txn.cross_branch(USearchScopeDocument, WorkspaceId.default())
            .vector_search(
                "content",
                [1.0, 0.0],
                k=2,
            )
            .execute()
        )

    def execute() -> list[USearchScopeDocument]:
        if single_branch:
            return db_connection.read_version(
                session_id=system_session_id,
                domain=USearchScopeDomain,
                branch=branch,
                fn=read,
            )
        return db_connection.session(system_session_id).read(fn=read)

    assert len(execute()) == 2

    def remove(txn: SyncWriteTransaction) -> None:
        if fault in {"member", "unknown_key"}:
            members = list(txn.query(USearchArtifactMember).execute())
            assert len(members) == 2
            if fault == "member":
                txn.delete_by_id(USearchArtifactMember, members[0].sys_id)
            else:
                members[0].native_key = 999
                txn.update(USearchArtifactMember, members[0])
            return
        artifacts = list(txn.query(USearchScopeIndex).execute())
        assert len(artifacts) == 1
        artifact = artifacts[0]
        if fault == "artifact":
            txn.delete_by_id(USearchScopeIndex, artifact.sys_id)
            return
        if fault == "digest":
            artifact.blob_sha256 = "0" * 64
        elif fault == "payload":
            artifact.index_blob = b"invalid"
            artifact.blob_sha256 = sha256(artifact.index_blob).hexdigest()
        elif fault == "epoch":
            artifact.artifact_epoch = 0
        elif fault == "metric":
            artifact.metric_type = "ip"
        else:
            artifact.dimensionality += 1
        txn.update(USearchScopeIndex, artifact)

    db_connection.session(system_session_id).write(fn=remove)
    with pytest.raises(NativeSearchIntegrityError):
        execute()

