from l5200_vector_index.index_implementations.usearch_index import USearchVectorIndex


@pytest.mark.parametrize(
    "fault", [
        "duplicate-key", "duplicate-vector", "invalid-key", "foreign-artifact", "invalid-vector",
        "invalid-counter", "regressed-counter",
    ],
)
def test_restore_rejects_inconsistent_membership_without_mutating_index(
    fault: Literal[
        "duplicate-key", "duplicate-vector", "invalid-key", "foreign-artifact", "invalid-vector",
        "invalid-counter", "regressed-counter",
    ],
) -> None:
    artifact = USearchIndexBlobBase(
        field_name="content", index_blob=b"", dimensionality=2, next_native_key=9,
    )
    first_vector = EmbeddingVectorId.new()
    first = USearchArtifactMember(
        artifact_id=artifact.sys_id, native_key=1, embedding_vector_id=first_vector,
    )
    second = USearchArtifactMember(
        artifact_id=artifact.sys_id,
        native_key=1 if fault == "duplicate-key" else 2,
        embedding_vector_id=first_vector
        if fault == "duplicate-vector"
        else EmbeddingVectorId.new(),
    )
    if fault == "invalid-key":
        second.native_key = 0
    elif fault == "foreign-artifact":
        second.artifact_id = SysId.new()
    if fault == "invalid-counter":
        artifact.next_native_key = 0
    elif fault == "regressed-counter":
        artifact.next_native_key = 2
    members = [first.model_dump(mode="python"), second.model_dump(mode="python")]
    if fault == "invalid-vector":
        members[1]["embedding_vector_id"] = "invalid-identity"
    index = USearchVectorIndex(SqlTableName("restore_documents"), "content")
    index._id_to_key = {str(first_vector): 7}
    index._key_to_id = {7: str(first_vector)}
    index._next_key = 8

    with pytest.raises(NativeSearchIntegrityError, match="membership"):
        _restore_usearch_artifact_members(index, artifact, members)

    assert index._id_to_key == {str(first_vector): 7}
    assert index._key_to_id == {7: str(first_vector)}
    assert index._next_key == 8


