@dataclass(frozen=True, slots=True)
class EmbeddingAlgorithmFilter:
    """Optional provider/model guard for destructive embedding cleanup."""

    value: str | None

    @classmethod
    def none(cls) -> EmbeddingAlgorithmFilter:
        return cls(None)

    @classmethod
    def parse(cls, algorithm: str | None) -> EmbeddingAlgorithmFilter:
        if algorithm is None:
            return cls.none()
        if "/" not in algorithm:
            msg = "Embedding algorithm filter must be formatted as 'provider/model'"
            raise ValueError(msg)
        return cls(algorithm)

    def matches(self, metadata: object) -> bool:
        if self.value is None:
            return True
        current = _metadata_algorithm(metadata)
        return current == self.value


def _metadata_value(metadata: object, field_name: str) -> object:
    if isinstance(metadata, Mapping):
        return metadata.get(field_name)
    return getattr(metadata, field_name)


def _metadata_algorithm(metadata: object) -> str:
    provider = _metadata_value(metadata, "provider")
    model = _metadata_value(metadata, "model")
    return f"{provider}/{model}" if provider else str(model)


class ValidateEmbeddingAlgorithmDeleteStep(NonPublishingStep[bool]):
    """Validate optional algorithm filter before destructive embedding cleanup."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        metadata_ref: ServerPlanRefId,
        algorithm_filter: EmbeddingAlgorithmFilter,
    ) -> None:
        super().__init__(ref_id)
        self._metadata_ref = metadata_ref
        self._algorithm_filter = algorithm_filter

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self) -> bool:
        return True

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def consumes_executor_visible_dependencies(self) -> bool:
        return True

    def is_executor_owned_runtime_step(self) -> bool:
        return True

    def step_tags(self) -> frozenset[str]:
        return frozenset({"vector_index", "embedding_metadata", "algorithm_delete_validation", "runtime_projection"})

    def counts_as_sql_group_for_warning(self) -> bool | None:
        return False

    def supports_sql_batch_transport(self) -> bool:
        return False

    def requires_materialized_inputs(self) -> bool:
        return True

    def dependencies(self) -> frozenset[str]:
        return frozenset({str(self._metadata_ref)})

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def compile(self, ctx: CompilationContext) -> CompiledStep[bool]:
        del ctx
        return CompiledStep()

    def execute_runtime(self, resolved: ResolvedRefs) -> bool:
        algorithm_filter = self._algorithm_filter
        if algorithm_filter.value is None:
            return True
        metadata = resolved.get(str(self._metadata_ref))
        if metadata is None:
            msg = "Cannot verify algorithm filter without embedding metadata"
            raise ValueError(msg)
        established = _metadata_value(metadata, "algorithm_established")
        if not established:
            msg = "Embedding algorithm not established"
            raise ValueError(msg)
        if not algorithm_filter.matches(metadata):
            msg = f"Algorithm mismatch: expected {algorithm_filter.value}, found {_metadata_algorithm(metadata)}"
            raise ValueError(msg)
        return True

