    SqlRelationPublisherStep,
)


class SubscriptionWriterStep(SqlRelationPublisherStep[list[dict[str, JsonValue]]]):
    """Publish the exact source and author associated with a session."""

    def __init__(
        self: SubscriptionWriterStep,
        ref_id: ServerPlanRefId,
        session_id: ScalarServerRef[SessionId] | LazySessionSqlSource,
    ) -> None:
        super().__init__(ref_id)
        self._session_id = session_id

    @property
    def level(self: SubscriptionWriterStep) -> int:
        return 0

    def result_cardinality(self: SubscriptionWriterStep) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self: SubscriptionWriterStep) -> bool:
        return True

    def tables_read(self: SubscriptionWriterStep) -> frozenset[str]:
        extra = (
            self._session_id.tables_read()
            if is_lazy_session_source(self._session_id)
            else frozenset()
        )
        return frozenset({"sys_sessions"}) | extra

    def tables_written(self: SubscriptionWriterStep) -> frozenset[str]:
        return frozenset()

    def dependencies(self: SubscriptionWriterStep) -> frozenset[str]:
        return (
            frozenset()
            if is_lazy_session_source(self._session_id)
            else self._session_id.dependencies()
        )

    def cte_publication_contract(self: SubscriptionWriterStep) -> CtePublicationContract:
        columns = ("sys_id", "source", "session_type", "user_id")
        hints = model_sql_column_type_hints(UserSession, columns)
        assert hints is not None
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=columns,
            column_type_hints=hints,
            relation_contract=CteRelationContract.semantic_row(SubscriptionWriter),
            source_tables=self.tables_read(),
        )

    def compile(
        self: SubscriptionWriterStep, ctx: CompilationContext
    ) -> CompiledStep[list[dict[str, JsonValue]]]:
        source = self._session_id
        rhs = (
            source.session_id_expression(ctx)
            if is_lazy_session_source(source)
            else lower_scalar_server_ref(source, ctx)
        )
        contract = self.cte_publication_contract()
        output_shape, result_relation, hints = compiled_artifacts_from_cte_publication_contract(
            contract
        )
        return CompiledStep(
            grammar=build_session_lookup_stmt(
                rhs,
                columns=tuple(SqlColumnName(column) for column in contract.columns),
            ),
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=hints,
            needs_returning=True,
            closed_post_op=row_dicts_post_op(),
        )

"""Shared staged-source CTE resolution helpers."""

from __future__ import annotations

from collections.abc import Mapping

from l2070_batching.compilation import CompilationContext
from typing import TYPE_CHECKING

if TYPE_CHECKING:
    from impl.common.l2050_sql_types.sql_branded_types import SqlTableName
    from l2070_batching.publication_selection import PublicationSelectionContract
    from l2070_batching.staged_source import PublishScopeDescriptor


def _lookup_table_key(mapping: Mapping[str, str], table_name: object) -> str | None:
    if not mapping:
        return None
    table_name_str = str(table_name)
    direct = mapping.get(table_name_str)
    if direct is not None:
        return direct
    for source_table, source_cte in mapping.items():
        if str(source_table) == table_name_str:
            return source_cte
    return None


def _source_cte_is_addressable(source_name: str, ctx: CompilationContext) -> bool:
    cte_ref = ctx.cte_refs.get(str(source_name))
    if cte_ref is None:
        cte_ref = next(
            (candidate for candidate in ctx.cte_refs.values() if str(candidate.ref_id) == str(source_name)),
            None,
        )
    return cte_ref is not None and not (str(cte_ref.ref_id).startswith("published_") and cte_ref.auxiliary_query is None)


def resolve_staged_source(
    table_name: SqlTableName, ctx: CompilationContext,
    *, selection: PublicationSelectionContract | None = None,
    scope: PublishScopeDescriptor | None = None,
) -> str:
    """Resolve an exact publication selection or a same-statement write source."""
    if selection is not None:
        if selection.identity.source_table != table_name:
            raise ValueError("Publication selection belongs to a different source table")
        selected = ctx.publication_selections.get(selection.identity)
        if selected is None:
            raise ValueError("Publication selection has no SQL producer in this pipeline")
        if not selection.columns <= frozenset(selected.columns):
            raise ValueError("Publication selection consumer requires undeclared columns")
        return str(selected.ref_id)
    requirement = ctx.staged_read_requirement_stack[-1] if ctx.staged_read_requirement_stack else None
    if scope is None and requirement is not None and any(key.staged_table_name == table_name for key in requirement.source_keys):
        scope = requirement.scope
    if scope is not None:
        matches = [binding for identity, binding in ctx.publication_selections.items()
                   if identity.source_table == table_name and identity.scope == scope]
        if len(matches) > 1:
            raise ValueError("Staged consumer has an ambiguous publication selection owner")
        if matches:
            return str(matches[0].ref_id)
    logical_source = _lookup_table_key(ctx.staged_source_cte_by_table, table_name)
    if logical_source is not None and _source_cte_is_addressable(logical_source, ctx):
        binding = ctx.cte_refs.get(logical_source)
        if binding is not None:
            return str(binding.ref_id)
        return logical_source
    overlay = _lookup_table_key(ctx.overlay_cte_by_table, table_name)
    if overlay is not None and _source_cte_is_addressable(overlay, ctx):
        return overlay
    return table_name


def is_latest_wins_staged_source(staged_table: str, ctx: CompilationContext) -> bool:
    """Return whether ``staged_table`` names a latest-wins staged overlay CTE."""
    latest_wins_sources = (
        *ctx.staged_source_cte_by_table.items(),
        *ctx.overlay_cte_by_table.items(),
    )
    staged_table_str = str(staged_table)
    if any(str(binding.ref_id) == staged_table_str for binding in ctx.publication_selections.values()):
        return True
    return any(str(source_table).endswith("_staged") and cte_name == staged_table_str for source_table, cte_name in latest_wins_sources)

