class SchemaRowsStep[T](MaybeSqlRelationPublisherStep[list[T]]):
    """Row-returning schema/admin read that must execute as a standalone statement."""

    def cte_publication_contract(self: SchemaRowsStep) -> CtePublicationContract:
        return CtePublicationContract.non_publishing()

    def __init__(
        self: SchemaRowsStep,
        ref_id: ServerPlanRefId,
        stmt: SqlRenderable,
        *,
        params: SqlParamTuple | None = None,
        columns: tuple[SqlColumnName, ...] | None = None,
    ) -> None:
        super().__init__(ref_id)
        self._stmt = stmt
        self._params = params
        self._columns = columns

    @property
    def level(self: SchemaRowsStep) -> int:
        return 0

    def step_tags(self: SchemaRowsStep) -> frozenset[OptimizerStepTag]:
        return frozenset((OptimizerStepTag(value) for value in ('read', 'schema', 'admin', 'rows')))

    def is_read_only(self: SchemaRowsStep) -> bool:
        return True

    def execution_role(self: SchemaRowsStep) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def supports_sql_batch_transport(self: SchemaRowsStep) -> bool:
        return False

    def requires_prior_step_boundary(self: SchemaRowsStep) -> bool:
        return True

    def counts_as_sql_group_for_accounting(self: SchemaRowsStep) -> bool | None:
        return False

    def emits_sql_for_accounting(self: SchemaRowsStep) -> bool | None:
        return True

    def result_cardinality(self: SchemaRowsStep) -> Cardinality:
        return Cardinality.MANY

    def tables_read(self: SchemaRowsStep) -> frozenset[OptimizerAccessTableName]:
        return frozenset()

    def tables_written(self: SchemaRowsStep) -> frozenset[OptimizerAccessTableName]:
        return frozenset()

    def internal_plan_ref_state(self: SchemaRowsStep) -> PlanPayloadState:
        return self.internal_plan_ref_state_excluding("_stmt")

    def compile(self: SchemaRowsStep[T], ctx: CompilationContext) -> CompiledStep[list[T]]:
        from impl.common.l2070_server_plan.steps.grammar_fetchall import (
            _declared_terminal_grammar_artifacts,
            _terminal_grammar_artifacts,
        )

        __opa002_grammar_87 = self._stmt
        output_shape, result_relation, column_type_hints = (
            _terminal_grammar_artifacts(__opa002_grammar_87)
            if self._columns is None
            else _declared_terminal_grammar_artifacts(self._columns)
        )
        return CompiledStep(
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
            grammar=__opa002_grammar_87,
            params=self._params,
            needs_returning=True,
            closed_post_op=raw_rows_post_op(),
            allow_empty_provenance_manifest=True,
            use_savepoint_recovery=False,
        )

"""Runtime rowset reconciliation tests."""

from __future__ import annotations

import pytest

from impl.common.l2070_server_plan.steps.runtime_fallback import (
    RowsetMergeByIdentityStep,
    RuntimeFallbackInvariantError,
)
from l1400_types import CursorPage, CursorToken, KeysetPage, ServerPlanRefId
from l2070_batching.compilation import ResolvedRefs


def _merge_step(tombstone_attr: str = "deleted") -> RowsetMergeByIdentityStep:
    return RowsetMergeByIdentityStep(
        ServerPlanRefId("merged"),
        local_ref=ServerPlanRefId("local"),
        remote_ref=ServerPlanRefId("remote"),
        tombstone_attr=tombstone_attr,
    )


def test_rowset_merge_remote_then_local_local_wins_and_tombstones_remote_rows() -> None:
    step = _merge_step(tombstone_attr="deleted")

    result = step.execute_runtime(
        ResolvedRefs(
            {
                "remote": [
                    {"sys_id": "shared", "name": "remote shared"},
                    {"sys_id": "remote-only", "name": "remote only"},
                    {"sys_id": "deleted-remotely-visible", "name": "remote deleted target"},
                ],
                "local": [
                    {"sys_id": "shared", "name": "local shared", "deleted": False},
                    {"sys_id": "local-only", "name": "local only", "deleted": False},
                    {"sys_id": "deleted-remotely-visible", "deleted": True},
                ],
            },
        ),
    )

    assert result == [
        {"sys_id": "shared", "name": "local shared", "deleted": False},
        {"sys_id": "remote-only", "name": "remote only"},
        {"sys_id": "local-only", "name": "local only", "deleted": False},
    ]


def test_rowset_merge_rejects_duplicate_identities_before_reconciliation() -> None:
    step = _merge_step()

    with pytest.raises(RuntimeFallbackInvariantError, match="remote rowset contains duplicate identity"):
        step.execute_runtime(
            ResolvedRefs(
                {
                    "remote": [
                        {"sys_id": "duplicate", "name": "first"},
                        {"sys_id": "duplicate", "name": "second"},
                    ],
                    "local": [],
                },
            ),
        )


def test_rowset_merge_preserves_keyset_page_metadata() -> None:
    step = _merge_step(tombstone_attr="deleted")
    remote_page = KeysetPage(
        results=[{"sys_id": "remote", "name": "remote"}],
        next_key=("remote",),
        has_more=True,
    )

    result = step.execute_runtime(
        ResolvedRefs(
            {
                "remote": remote_page,
                "local": [{"sys_id": "local", "name": "local", "deleted": False}],
            },
        ),
    )

    assert isinstance(result, KeysetPage)
    assert result.next_key == ("remote",)
    assert result.has_more is True
    assert result.results == [
        {"sys_id": "remote", "name": "remote"},
        {"sys_id": "local", "name": "local", "deleted": False},
    ]


def test_rowset_merge_preserves_cursor_page_metadata() -> None:
    step = _merge_step()
    remote_page = CursorPage(
        results=[{"sys_id": "remote", "name": "remote"}],
        cursor=CursorToken("next-cursor"),
        has_more=True,
    )

    result = step.execute_runtime(
        ResolvedRefs(
            {
                "remote": remote_page,
                "local": [{"sys_id": "local", "name": "local"}],
            },
        ),
    )

    assert isinstance(result, CursorPage)
    assert str(result.cursor) == "next-cursor"
    assert result.has_more is True
    assert result.results == [
        {"sys_id": "remote", "name": "remote"},
        {"sys_id": "local", "name": "local"},
    ]

"""AnalyzeTableStep: explicit planner-statistics maintenance after bulk writes.

After bulk insert operations, table statistics may become stale. This step is a
visible scheduling marker; utility statements that can implicitly commit must
not run through the normal SQL step lane.
"""

from __future__ import annotations

from collections.abc import Callable, Sequence
from dataclasses import dataclass, field
from typing import TYPE_CHECKING, cast

from l2070_batching.cardinality import Cardinality
from l2070_batching.compilation import CompiledStep, PipelineLifecycleEffect, PipelineLifecyclePhase
from l2070_batching.step import ServerPlanStep, StepExecutionRole, NonPublishingStep
from l1400_types import ServerPlanRefId
from impl.common.l2050_sql_types.sql_branded_types import SqlTableName

if TYPE_CHECKING:
    from l2070_batching.compilation import CompilationContext
    from l2050_transaction.transaction import WriteTransaction


def _queue_table_for_analyze(table_name: SqlTableName, row_count: AnalyzeRowCount, txn: object | None) -> None:
    from _internal import get_transaction_connection

    if txn is None:
        return
    get_conn = cast(Callable[["WriteTransaction"], object], get_transaction_connection)
    conn = get_conn(cast("WriteTransaction", txn))
    queue_table_for_analyze = getattr(conn, "queue_table_for_analyze", None)
    if callable(queue_table_for_analyze):
        typed_queue = cast(Callable[[str, int], None], queue_table_for_analyze)
        typed_queue(str(table_name), int(row_count))


class AnalyzeRowCount(int):
    """Branded row-count hint for planner-statistics queueing."""

    __slots__ = ()


@dataclass(frozen=True, slots=True)
class AnalyzeTableQueuedEffect(PipelineLifecycleEffect):
    table_name: SqlTableName
    row_count: AnalyzeRowCount
    phase: PipelineLifecyclePhase = field(
        default=PipelineLifecyclePhase.AFTER_COMMIT_LOCAL,
        init=False,
    )


class AnalyzeTableStep(NonPublishingStep[None]):
    """Run explicit ANALYZE maintenance after bulk writes."""

    def __init__(
        self: AnalyzeTableStep,
        ref_id: ServerPlanRefId,
        table_name: SqlTableName,
        row_count: AnalyzeRowCount,
        write_ref_id: ServerPlanRefId,
    ) -> None:
        super().__init__(ref_id)
        self._table_name: SqlTableName = table_name
        self._row_count: AnalyzeRowCount = row_count
        self._write_ref_id: ServerPlanRefId = write_ref_id

    @property
    def level(self: AnalyzeTableStep) -> int:
        return 0

    def is_read_only(self: AnalyzeTableStep) -> bool:
        return True

    def result_cardinality(self: AnalyzeTableStep) -> Cardinality:
        return Cardinality.NONE

    def execution_role(self: AnalyzeTableStep) -> StepExecutionRole:
        return StepExecutionRole.VIRTUAL

    def tables_read(self: AnalyzeTableStep) -> frozenset[str]:
        return frozenset()

    def tables_written(self: AnalyzeTableStep) -> frozenset[str]:
        return frozenset()

    def step_tags(self: AnalyzeTableStep) -> frozenset[str]:
        return frozenset({"analyze", "maintenance", "queued"})

    def dependencies(self: AnalyzeTableStep) -> frozenset[str]:
        return frozenset({self._write_ref_id})

    def compile(self: AnalyzeTableStep, ctx: CompilationContext) -> CompiledStep[None]:
        """Do not emit utility SQL through the normal SQL execution lane."""
        del ctx
        return CompiledStep(
            lifecycle_effects=(AnalyzeTableQueuedEffect(self._table_name, self._row_count),),
        )

