TEST_BOOTSTRAP_FAMILY = SEARCH_V1


@pytest.mark.parametrize("single_branch", [False, True])
@pytest.mark.parametrize(
    "dimension", [PhysicalLimit.NATIVE_ARTIFACT_BYTES, PhysicalLimit.NATIVE_ELIGIBILITY_ROWS]
)
def test_sql_bounds_inputs_before_native_preparation(
    db_connection: SyncVersionedDatabaseConnection,
    monkeypatch: pytest.MonkeyPatch,
    single_branch: bool,
    dimension: PhysicalLimit,
    system_session_id: SessionId,
) -> None:
    original = _CrossBranchUSearchNativeSpoolStep._prepare_spool
    observed: list[bool] = []

    def inspect_inputs(
        self: _CrossBranchUSearchNativeSpoolStep,
        resolved: ResolvedRefs,
    ) -> _PreparedCrossBranchUSearchSpool:
        eligible = resolved.require(self._eligibility_ref_id, list, site="bounded eligibility test")
        artifacts = resolved.require(self._artifact_ref_id, list, site="bounded artifact test")
        assert len(eligible) <= self._limits.max_eligibility_rows + 1
        run_selection = any(
            isinstance(artifact, Mapping) and artifact.get("run_manifest") is not None
            for artifact in artifacts
        )
        assert len(artifacts) <= (self._limits.max_eligibility_rows + 1 if run_selection else 2)
        sizes: list[int] = []
        for artifact in artifacts:
            assert isinstance(artifact, Mapping)
            size = artifact["blob_bytes"]
            assert isinstance(size, int)
            sizes.append(size)
        transported_bytes = sum(sizes)
        for artifact in artifacts:
            assert isinstance(artifact, Mapping)
            size = artifact["blob_bytes"]
            assert isinstance(size, int)
            if (transported_bytes if run_selection else size) > self._limits.max_artifact_bytes:
                assert artifact["index_blob"] is None
                if run_selection:
                    manifest = artifact["run_manifest"]
                    if isinstance(manifest, str):
                        manifest = json.loads(manifest)
                    assert manifest == {}
                observed.append(True)
            else:
                assert isinstance(artifact["index_blob"], bytes | bytearray | memoryview)
        if len(eligible) > self._limits.max_eligibility_rows:
            observed.append(True)
        return original(self, resolved)

    monkeypatch.setattr(_CrossBranchUSearchNativeSpoolStep, "_prepare_spool", inspect_inputs)
    _exercise_limits(db_connection, dimension, single_branch, system_session_id)
    assert observed

