"""Commit metadata follows active logical types, not retained Python subclasses."""
from __future__ import annotations

from typing import Literal

import pytest

from impl.common.l2070_server_plan.steps.intent_transaction import _commit_branch_domain_metadata
from l1050_polymorphism.type_filter_helper import get_all_concrete_subtypes
from l1050_polymorphism.type_registry import get_type_registry
from l1400_types import SysId
from l7000_versioned_schema.versioned_schema import VersionedObjectRow, VersioningDomain
from l9600_graphs.dynamic_types import (
    DynamicEdgeBase, DynamicTypeKind, DynamicTypeRegistry, DynamicTypeSchema, DynamicTypeSchemaId,
)
from l9600_graphs.graph import GraphId


@pytest.mark.parametrize("invalidation", ["none", "one", "all"])
@pytest.mark.parametrize("evolve", [False, True])
def test_commit_metadata_tracks_current_dynamic_shape(
    invalidation: Literal["none", "one", "all"], evolve: bool,
) -> None:
    declared_models: list[type[VersionedObjectRow[SysId]]] = [DynamicEdgeBase]

    class Domain(VersioningDomain, abstract=True):
        @classmethod
        def all_versioned_models(cls: type[Domain]) -> tuple[type[VersionedObjectRow[SysId]], ...]:
            return tuple(declared_models)

    schema_id = DynamicTypeSchemaId.new()
    schema = DynamicTypeSchema(
        sys_id=schema_id,
        graph_sys_id=GraphId.new(), kind=DynamicTypeKind.EDGE,
        type_name="CommitShape_" + str(schema_id).replace("-", ""),
        field_definitions={"label": {"type": "str"}},
    )
    registry = DynamicTypeRegistry()
    first = registry.materialize_edge_type(schema)
    current = first
    type_registry = get_type_registry(DynamicEdgeBase)
    original_id = type_registry.get_type_id(first)
    initial, _, _ = _commit_branch_domain_metadata(Domain)
    assert any(first in entry[1] for entry in initial)

    try:
        if invalidation == "one":
            assert registry.invalidate(first.__name__)
        elif invalidation == "all":
            assert registry.invalidate_all() == 1
        if evolve:
            schema = schema.model_copy(update={
                "field_definitions": {"label": {"type": "str"}, "amount": {"type": "int"}},
            })
        current = registry.materialize_edge_type(schema)
        assert type_registry.get_type_id(current) == original_id
        if evolve:
            assert current is not first

        declared_models.extend((first, current))
        refreshed, _, _ = _commit_branch_domain_metadata(Domain)
        matching = [
            model for entry in refreshed for model in entry[1]
            if model.__name__ == current.__name__
        ]
        assert matching == [current]
    finally:
        # Leave one registered class even when the regression assertion fails.
        if first is not current and first in get_all_concrete_subtypes(DynamicEdgeBase):
            type_registry.replace(first, current)

"""Compile-time SQL lowering helpers for versioned branch sources."""

from __future__ import annotations

from impl.common.l2070_server_plan.steps._compile_server_ref import lower_scalar_server_ref
from impl.common.l2070_server_plan.steps._versioned_staging import VersionedBranchSource
from impl.common.l2100_sql_grammar.protocols import SqlRenderable
from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlParam
from l2070_batching.compilation import CompilationContext, LoweringContext
from l2070_batching.seeded_constants import read_seeded_constant_from_ctx
from l2070_batching.server_ref import ScalarServerRef
from l2070_batching.server_ref import inspect_server_value_shape_for_planning
from l1200_versioned_ids import BranchId
from l1400_types import ServerPlanRefId


def _compile_context_seed_branch(branch: VersionedBranchSource, ctx: CompilationContext) -> BranchId | None:
    if not isinstance(branch, ScalarServerRef):
        return None
    shape = inspect_server_value_shape_for_planning(
        branch,
        site="_compile_context_seed_branch",
    )
    ref_id = shape.symbolic_ref_id
    if ref_id is None or not str(ref_id).startswith("seed_"):
        return None
    found_seed, _seed_value = read_seeded_constant_from_ctx(ctx, ServerPlanRefId(ref_id))
    if found_seed or ctx.branch_id is None:
        return None
    unwrap = getattr(ctx.branch_id, "unwrap_to_str", None)
    return BranchId(str(unwrap() if callable(unwrap) else ctx.branch_id))


def lower_versioned_branch_source(
    branch: VersionedBranchSource,
    ctx: CompilationContext | LoweringContext,
    *,
    site: str,
) -> SqlRenderable:
    """Lower a versioned branch source into a SQL expression.

    Literal branch refs become bound parameters. CTE-backed branch refs become
    field references to the upstream branch CTE's ``branch_id`` column.
    """
    if isinstance(branch, BranchId):
        return SqlParam(branch)
    if isinstance(ctx, LoweringContext):
        msg = f"{site} requires a literal branch_id during lowering"
        raise RuntimeError(msg)
    context_seed_branch = _compile_context_seed_branch(branch, ctx)
    if context_seed_branch is not None:
        return SqlParam(context_seed_branch)
    try:
        return lower_scalar_server_ref(branch, ctx, default_field="branch_id")
    except (TypeError, NotImplementedError) as exc:
        msg = f"{site} requires a literal or CTE-backed branch_id"
        raise RuntimeError(msg) from exc


def versioned_branch_dependencies(branch: VersionedBranchSource) -> frozenset[str]:
    """Return direct ServerPlan dependencies for a branch source."""
    if isinstance(branch, ScalarServerRef):
        return inspect_server_value_shape_for_planning(
            branch,
            site="versioned_branch_dependencies",
        ).dependency_refs
    return frozenset()

