class NativeSpoolCleanupStep(NonPublishingStep[None]):
    """Delete one executor-owned scope after its SQL consumers finish."""

    def __init__(
        self: Self,
        ref_id: ServerPlanRefId,
        *,
        table: SqlTableName,
        scope_id: ServerPlanRefId,
        after_refs: tuple[ServerPlanRefId, ...],
    ) -> None:
        super().__init__(ref_id)
        self._table = table
        self._scope_id = scope_id
        self._after_refs = after_refs

    @property
    def level(self: Self) -> int:
        return 0

    def execution_role(self: Self) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def result_cardinality(self: Self) -> Cardinality:
        return Cardinality.NONE

    def is_read_only(self: Self) -> bool:
        return False

    def is_session_gate_exempt(self: Self) -> bool:
        return True

    def dependencies(self: Self) -> frozenset[str]:
        return frozenset(str(ref) for ref in self._after_refs)

    def sql_visible_dependencies(self: Self) -> frozenset[str]:
        return frozenset()

    def tables_read(self: Self) -> frozenset[str]:
        return frozenset({str(self._table)})

    def tables_written(self: Self) -> frozenset[str]:
        return frozenset({str(self._table)})

    def step_tags(self: Self) -> frozenset[str]:
        return frozenset({"write", "temporary", "native_spool_cleanup"})

    def compile(self: Self, ctx: CompilationContext) -> CompiledStep[None]:
        del ctx
        return CompiledStep(
            grammar=SqlDelete(
                SqlTableIdent(self._table),
                where=SqlWhereClause(
                    SqlBinaryOp(
                        SqlColumnRef(SqlColumnName("scope_id")),
                        BinaryOp.EQ,
                        SqlParam(str(self._scope_id)),
                    )
                ),
            ),
            output_shape=None,
            result_relation=None,
            column_type_hints=None,
        )

