    assert "docs.raw_rows" in builder.dependencies()
    assert "docs.hydrated_rows" not in builder.dependencies()

"""Resolution helpers for SQL-visible symbolic ServerPlan refs."""

from __future__ import annotations

from dataclasses import dataclass

from l2055_lazy_result.purity import pure_lazy
from l2070_batching.compilation import CompilationContext, CteReference

from l1400_types import ServerPlanRefId


@dataclass(frozen=True, slots=True)
class SqlVisibleRefBinding:
    """A CTE binding plus the field that should be projected from it."""

    cte_name: str
    field_name: str
    binding: CteReference


@pure_lazy
def resolve_sql_visible_ref(
    ctx: CompilationContext,
    ref_id: ServerPlanRefId,
    *,
    default_field: str = "sys_id",
    field_name: str | None = None,
) -> SqlVisibleRefBinding | None:
    """Resolve an exact producer-registered SQL-visible binding."""

    direct = ctx.cte_refs.get(ref_id)
    if not isinstance(direct, CteReference):
        return None
    return SqlVisibleRefBinding(
        cte_name=direct.ref_id,
        field_name=_direct_field_name(direct, default_field=default_field, field_name=field_name),
        binding=direct,
    )


def resolve_sql_visible_relation(
    ctx: CompilationContext,
    ref_id: ServerPlanRefId,
) -> CteReference | None:
    """Resolve an exact producer-owned relation binding."""
    direct = ctx.cte_refs.get(ref_id)
    return direct if isinstance(direct, CteReference) else None


def resolve_sql_visible_auxiliary_binding(ctx: CompilationContext, ref_id: ServerPlanRefId) -> CteReference | None:
    """Resolve the auxiliary CTE needed before a SQL-visible ref can be used."""

    return resolve_sql_visible_relation(ctx, ref_id)


def cte_binding_with_auxiliary_query(ctx: CompilationContext, binding: CteReference) -> CteReference | None:
    if binding.auxiliary_query is not None:
        return binding
    alias_binding = ctx.cte_refs.get(binding.ref_id)
    if isinstance(alias_binding, CteReference) and alias_binding.auxiliary_query is not None:
        return alias_binding
    for candidate in ctx.cte_refs.values():
        if isinstance(candidate, CteReference) and candidate.ref_id == binding.ref_id and candidate.auxiliary_query is not None:
            return candidate
    return None


@pure_lazy
def _direct_field_name(binding: CteReference, *, default_field: str, field_name: str | None) -> str:
    if field_name is not None:
        return field_name
    if binding.scalar_value_column is not None:
        return binding.scalar_value_column.to_row_key()
    if binding.columns is not None and len(binding.columns) == 1:
        return binding.columns[0]
    if binding.columns is not None and default_field not in binding.columns:
        msg = f"CTE binding {binding.ref_id!r} does not declare field {default_field!r}."
        raise ValueError(msg)
    return default_field

"""SQLite CTE-body legality helpers for ServerPlan composition."""

from __future__ import annotations

from typing import cast

from impl.common.l2100_sql_grammar.protocols import SqlRenderable


def sqlite_allows_cte_body(grammar: SqlRenderable) -> bool:
    """Return whether ``grammar`` can legally appear as a SQLite CTE body."""
    from impl.common.l2100_sql_grammar.domain.infra.dml_wrapper import SqlDmlWrapper, SqlDmlWrapperKind
    from impl.common.l2100_sql_grammar.domain.infra.stmt_compound_write import SqlStatementBatch
    from impl.common.l2100_sql_grammar.domain.infra.stmt_dml_simple import (
        SqlBatchInsertOnConflictDoNothing,
    )
    from impl.common.l2100_sql_grammar.domain.infra.stmt_upsert import (
        SqlBatchUpsertStmt,
        SqlInsertOrIgnore,
        SqlUpsertDescriptor,
    )
    from impl.common.l2100_sql_grammar.domain.versioning.stmt_cte import (
        SqlBindExternalParams,
        SqlDmlReturningWrapper,
        SqlInsertWithCte,
        SqlSelectWithCte,
    )
    from impl.common.l2100_sql_grammar.domain.versioning.stmt_insert_select import SqlInsertFromSelect
    from impl.common.l2100_sql_grammar.tree.statements import SqlCte, SqlDelete, SqlInsert, SqlSelect, SqlUpdate

    if isinstance(grammar, SqlDmlWrapper):
        return grammar.wrapper_kind in {
            SqlDmlWrapperKind.SELECT_EXISTS_SUBQUERY,
            SqlDmlWrapperKind.SELECT_COUNT_SUBQUERY,
            SqlDmlWrapperKind.SELECT_STAR_FROM_SOURCE,
            SqlDmlWrapperKind.IDENTITY,
        } and sqlite_allows_cte_body(grammar._inner)
    if isinstance(grammar, SqlBindExternalParams):
        return sqlite_allows_cte_body(grammar._inner)
    if isinstance(grammar, SqlSelectWithCte):
        return all(sqlite_allows_cte_body(cte._query) for cte in grammar._with_clause._ctes) and sqlite_allows_cte_body(
            grammar._select,
        )
    if isinstance(grammar, SqlCte):
        return all(
            sqlite_allows_cte_body(cast("SqlRenderable", query)) for _name, query in grammar._definitions
        ) and sqlite_allows_cte_body(
            grammar._final_query,
        )
    if isinstance(grammar, SqlSelect):
        return True
    if isinstance(grammar, SqlStatementBatch):
        return False
    if isinstance(
        grammar,
        (
            SqlDmlReturningWrapper,
            SqlInsertWithCte,
            SqlInsert,
            SqlUpdate,
            SqlDelete,
            SqlInsertFromSelect,
            SqlUpsertDescriptor,
            SqlBatchUpsertStmt,
            SqlInsertOrIgnore,
            SqlBatchInsertOnConflictDoNothing,
        ),
    ):
        return False

    return True

