"""Embedding worker terminal projection steps owned by ServerPlan."""

from __future__ import annotations

from collections.abc import Sequence
from typing import cast

from l1400_types import ServerPlanRefId
from l2070_batching.cardinality import Cardinality
from l2070_batching.compilation import CompilationContext, CompiledStep, ResolvedRefs
from l2070_batching.post_op import PostOpBehavior
from l2070_batching.step import ServerPlanStep, StepExecutionRole, NonPublishingStep


type EmbeddingWorkerTerminalResult[T] = T


class EmbeddingWorkerResultStep[T](NonPublishingStep[EmbeddingWorkerTerminalResult[T]]):
    """Project embedding-worker owned runtime payloads into public result shapes."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        source_ref: ServerPlanRefId,
        behavior: PostOpBehavior,
    ) -> None:
        super().__init__(ref_id)
        self._source_ref = source_ref
        self._behavior = behavior

    @property
    def level(self: EmbeddingWorkerResultStep[T]) -> int:
        return 0

    def result_cardinality(self: EmbeddingWorkerResultStep[T]) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self: EmbeddingWorkerResultStep[T]) -> bool:
        return True

    def execution_role(self: EmbeddingWorkerResultStep[T]) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def step_tags(self: EmbeddingWorkerResultStep[T]) -> frozenset[str]:
        return frozenset({"embedding_worker", "result", "virtual"})

    def tables_read(self: EmbeddingWorkerResultStep[T]) -> frozenset[str]:
        return frozenset()

    def tables_written(self: EmbeddingWorkerResultStep[T]) -> frozenset[str]:
        return frozenset()

    def dependencies(self: EmbeddingWorkerResultStep[T]) -> frozenset[str]:
        return frozenset({str(self._source_ref)})

    def compile(
        self: EmbeddingWorkerResultStep[T],
        ctx: CompilationContext,
    ) -> CompiledStep[EmbeddingWorkerTerminalResult[T]]:
        del ctx
        return CompiledStep()

    def execute_runtime(
        self: EmbeddingWorkerResultStep[T],
        resolved: ResolvedRefs,
    ) -> EmbeddingWorkerTerminalResult[T]:
        value = resolved.get(str(self._source_ref))
        if self._behavior is PostOpBehavior.TERMINAL_ARRAY:
            if value is None:
                return cast(T, [])
            if isinstance(value, Sequence) and not isinstance(value, str | bytes | bytearray):
                return cast(T, list(value))
            return cast(T, [value])
        return cast(T, value)

"""SQL-visible scalar literal publication helpers."""

from __future__ import annotations

from typing import Any
from uuid import UUID

from l1000_schema.typed_field import SqlCastTargetType
from l2070_batching.compilation import CompiledStep
from l2070_batching.output_shape import CompiledOutputShape, DeclaredResultRelation, synthetic_output_field
from l2070_batching.sql_column_type_hints import SqlColumnTypeHints
from impl.common.l2050_sql_types.sql_branded_types import SqlAliasName
from impl.common.l2100_sql_grammar.tree.clauses import SqlSelectAlias, SqlSelectList
from impl.common.l2100_sql_grammar.protocols import SqlRenderable
from impl.common.l2100_sql_grammar.tree.expr_compound import SqlCast
from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlParam
from impl.common.l2100_sql_grammar.tree.statements import SqlSelect


def _literal_column_type_hints(alias: str, value: object) -> SqlColumnTypeHints:
    if isinstance(value, bool):
        return SqlColumnTypeHints(bool_columns=frozenset({alias}))
    if isinstance(value, int):
        return SqlColumnTypeHints(integer_columns=frozenset({alias}))
    if isinstance(value, UUID):
        return SqlColumnTypeHints(uuid_columns=frozenset({alias}))
    if isinstance(value, bytes | bytearray | memoryview):
        return SqlColumnTypeHints(bytea_columns=frozenset({alias}))
    if isinstance(value, str):
        return SqlColumnTypeHints(text_columns=frozenset({alias}))
    return SqlColumnTypeHints(jsonb_columns=frozenset({alias}))


def compile_scalar_literal(
    alias: str,
    value: object,
    *,
    column_type_hints: SqlColumnTypeHints | None = None,
) -> CompiledStep[Any]:
    """Compile a scalar literal as a one-column SQL-visible result."""
    hints = column_type_hints or _literal_column_type_hints(alias, value)
    value_expression: SqlRenderable = SqlParam(value)
    if alias in hints.uuid_columns:
        value_expression = SqlCast(value_expression, SqlCastTargetType(base_type="UUID"))
    grammar = SqlSelect(
        select=SqlSelectList([SqlSelectAlias(value_expression, SqlAliasName(alias))]),
    )
    output_shape = CompiledOutputShape((synthetic_output_field(alias),))
    return CompiledStep(
        grammar=grammar,
        needs_returning=True,
        output_shape=output_shape,
        result_relation=DeclaredResultRelation.from_output_shape(output_shape),
        column_type_hints=hints,
    )

