"""Shared transport contracts for inline large-column SQL rowsets."""

from __future__ import annotations

from typing import TYPE_CHECKING

from l2070_batching.sql_column_type_hints import SqlColumnTypeHints
from collections.abc import Sequence

if TYPE_CHECKING:
    from l1000_schema.schema_def import DatabaseObjectRow


def selected_large_column_transport_columns(
    model_cls: type[DatabaseObjectRow],
    selected_columns: Sequence[str],
) -> tuple[str, ...]:
    """Return helper transport columns needed for the selected large-column fields."""
    selected_columns = tuple(selected_columns)

    from impl.common.l2100_sql_grammar.domain.infra.stmt_inline_large_columns import (
        inline_large_column_transport_column_groups,
    )

    groups = inline_large_column_transport_column_groups(model_cls)
    if not selected_columns:
        return tuple(column for _logical_column, _pointer_column, transport_columns in groups for column in transport_columns)
    selected = set(selected_columns)
    return tuple(
        column
        for logical_column, pointer_column, transport_columns in groups
        if logical_column in selected or pointer_column in selected
        for column in transport_columns
    )


def large_column_transport_type_hints(columns: Sequence[str]) -> SqlColumnTypeHints:
    """Return complete type hints for inline large-column helper columns."""
    columns = tuple(columns)

    text_columns: set[str] = set()
    bool_columns: set[str] = set()
    integer_columns: set[str] = set()
    bytea_columns: set[str] = set()
    for column in columns:
        if column.endswith("__is_binary"):
            bool_columns.add(column)
        elif (
            column.endswith("__total_chunks")
            or column.endswith("__compression_level")
            or column.endswith("__original_size")
            or column.endswith("__delta_original_size")
        ):
            integer_columns.add(column)
        elif column.endswith("__payload"):
            bytea_columns.add(column)
        else:
            text_columns.add(column)
    return SqlColumnTypeHints(
        text_columns=frozenset(text_columns),
        bool_columns=frozenset(bool_columns),
        integer_columns=frozenset(integer_columns),
        bytea_columns=frozenset(bytea_columns),
    )

