def bounded_usearch_eligibility(
    query: SqlRenderable, limits: USearchRequestLimits, *, include_chunks: bool = False,
) -> SqlSelect:
    """Transport at most the configured rows and one overflow sentinel."""
    alias = SqlAliasName("bounded_native_eligibility")
    return SqlSelect(
        select=SqlSelectList(
            [
                SqlColumnRef(SqlColumnName(column), alias)
                for column in (
                    "object_id", "branch_id", "revision_id", "native_key",
                    *(("chunk_id", "chunk_metadata") if include_chunks else ()),
                )
            ]
        ),
        from_=SqlTableAlias(query, alias),
        limit=limits.max_eligibility_rows + 1,
    )


def usearch_artifact_bytes() -> SqlFuncCall:
    """Measure binary bytes in SQL without transporting the artifact."""
    return SqlFuncCall(SqlFunctionName("LENGTH"), [SqlColumnRef(SqlColumnName("index_blob"))])


def bounded_usearch_artifact_blob(limits: USearchRequestLimits) -> SqlCase:
    """Suppress an oversized BLOB while retaining its byte count for the error."""
    return SqlCase(
        [
            (
                SqlBinaryOp(
                    usearch_artifact_bytes(), BinaryOp.GT, SqlParam(limits.max_artifact_bytes)
                ),
                SqlParam(None),
            )
        ],
        else_=SqlColumnRef(SqlColumnName("index_blob")),
    )

"""Shared SQL gate helpers for conditional ServerPlan compilation."""

from __future__ import annotations

from typing import TYPE_CHECKING

from l2070_batching.compilation import CteReference

from impl.common.l2100_sql_grammar.base import SqlRenderable
from impl.common.l2100_sql_grammar.domain.versioning.stmt_conditional_gate import (
    SqlNegatedCondition,
)
from impl.common.l2100_sql_grammar.tree.expr_ops import sql_and

if TYPE_CHECKING:
    from l2070_batching.compilation import CompilationContext


def build_sql_gate_condition(
    predicate: SqlRenderable,
    skip: SqlRenderable | None,
    *,
    negate_predicate: bool,
) -> SqlRenderable:
    """Compose the predicate used by a conditional gate CTE."""
    primary: SqlRenderable = SqlNegatedCondition(predicate) if negate_predicate else predicate
    if skip is None:
        return primary
    return sql_and(primary, SqlNegatedCondition(skip))


def condition_column_name(condition_cte: CteReference) -> str:
    """Return the explicitly declared scalar predicate column."""
    column = condition_cte.scalar_value_column
    if column is None:
        msg = (
            f"Conditional CTE {condition_cte.ref_id!r} has no declared scalar value column; "
            f"columns={condition_cte.columns!r}, control_kind={condition_cte.scalar_control_kind!r}, "
            f"scope={condition_cte.scope!r}, auxiliary_type={type(condition_cte.auxiliary_query).__name__}."
        )
        raise TypeError(msg)
    return column.to_row_key()


def resolve_conditional_condition_binding(
    condition_ref: str,
    ctx: "CompilationContext",
) -> tuple[CteReference, str] | None:
    """Resolve the SQL-visible predicate binding for ``condition_ref``."""

    direct = ctx.cte_refs.get(condition_ref)
    if isinstance(direct, CteReference):
        return direct, condition_column_name(direct)
    base_ref, has_projection, field_path = condition_ref.partition(".")
    if not has_projection or "." in field_path:
        return None
    projected = ctx.cte_refs.get(base_ref)
    if isinstance(projected, CteReference):
        return projected, field_path
    return None

