"""Approximate payload sizing helpers for staged inline SQL gating decisions."""

from __future__ import annotations

from collections.abc import Sequence
from typing import Protocol, runtime_checkable


@runtime_checkable
class _StrUnwrappable(Protocol):
    def unwrap_to_str(self: _StrUnwrappable) -> str: ...


@runtime_checkable
class _IntUnwrappable(Protocol):
    def unwrap_to_int(self: _IntUnwrappable) -> int: ...


def estimate_scalar_payload_bytes(value: object) -> int:
    """Approximate serialized size for inline row payload budgeting."""
    if value is None:
        size = 1
    elif isinstance(value, _StrUnwrappable):
        size = len(value.unwrap_to_str().encode("utf-8"))
    elif isinstance(value, _IntUnwrappable):
        size = 8
    elif isinstance(value, bytes):
        size = len(value)
    elif isinstance(value, str):
        size = len(value.encode("utf-8"))
    elif isinstance(value, bool):
        size = 1
    elif isinstance(value, int | float):
        size = 8
    else:
        size = len(str(value).encode("utf-8"))
    return size


def estimate_rows_payload_bytes(rows: Sequence[tuple[object, ...]]) -> int:
    """Approximate serialized size for a sequence of inline rows."""
    return sum(estimate_scalar_payload_bytes(value) for row in rows for value in row)

