from typing import Any, TypeVar

from l1000_schema.schema_def import DatabaseObjectRow

T = TypeVar("T")


def materialize_explicit_return_value(value: T) -> T:
    """Mirror raw insert/upsert explicit return-value semantics."""
    if isinstance(value, DatabaseObjectRow):
        try:
            copied = value.model_copy(deep=True)
        except AttributeError as exc:
            if "__pydantic_extra__" not in str(exc):
                raise
            model_cls = type(value)
            field_values: dict[str, Any] = {
                field_name: object.__getattribute__(value, field_name)
                for field_name in model_cls.model_fields
                if hasattr(value, field_name)
            }
            copied = model_cls.model_validate(field_values)
        if not isinstance(copied, type(value)):
            msg = f"model_copy returned unexpected type: {type(copied)!r}"
            raise TypeError(msg)
        return copied
    return value

