from __future__ import annotations

from l2055_lazy_result.purity import pure_lazy


@pure_lazy
def duck_server_ref_id(value: object) -> str | None:
    """Return a symbolic ref id from ServerRef-like values that lost precise typing."""

    value_type = type(value)
    if value_type.__module__ == "l2055_lazy_result.lazy_result" and value_type.__name__ == "LazyResult":
        return None
    try:
        ref_id = object.__getattribute__(value, "ref_id")
    except AttributeError:
        ref_id = None
    if (
        value_type.__module__ == "l2070_batching.server_ref"
        and value_type.__name__.endswith("ServerRef")
        and isinstance(ref_id, str)
        and ref_id
    ):
        return str(ref_id)
    return None

