        ResultMaterializationSpec(
            behavior=PostOpBehavior.EXCEPTION_ONLY,
            domain_decoder=DomainPostOpDecoderSpec(
                DomainPostOpDecoderKind.RENEWABLE_REFRESH_REPLAY_VALIDATION,
                RenewableRefreshReplayValidationDecoderSpec(config=config),
            ),
        ),
    )


