def walk_one(value):
    if value is None or isinstance(value, (int, str, type)):
        return value
    if isinstance(value, Expr):
        for attr_name in EXPR_FIELDS:
            walk_one(getattr(value, attr_name))
        return value
    if isinstance(value, dict):
        for key, item in value.items():
            walk_one(key)
            walk_one(item)
        return value
    if is_dataclass(value):
        for field in fields(value):
            walk_one(getattr(value, field.name))
        return value
    raise TypeError(f'Unsupported payload shape: {type(value).__name__}')

def walk_two(value):
    if value is None or isinstance(value, (int, str, type)):
        return value
    if isinstance(value, Filter):
        for attr_name in FILTER_FIELDS:
            walk_two(getattr(value, attr_name))
        return value
    if isinstance(value, tuple | list | set | frozenset):
        for item in value:
            walk_two(item)
        return value
    if isinstance(value, Step):
        for item in value.internal_plan_ref_state().values():
            walk_two(item)
        return value
    raise TypeError(f'Unsupported payload shape: {type(value).__name__}')

