        kind = "unsupported"
    elif value_type is str:
        kind = "string"
    elif issubclass(value_type, tuple):
        kind = "tuple"
    elif issubclass(value_type, list):
        kind = "list"
    elif issubclass(value_type, set):
        kind = "set"
    elif issubclass(value_type, frozenset):
        kind = "frozenset"
    elif issubclass(value_type, dict) or value_type is types.MappingProxyType:
        kind = "dict"
    elif issubclass(value_type, type):
        kind = "opaque_carrier"
    elif value_type.__name__ in _OPAQUE_TYPE_NAMES or _is_strategy_type_name(SqlTypeName(value_type.__name__)):
        kind = "opaque_carrier"
    elif issubclass(value_type, ServerPlanRefId):
        kind = "server_plan_ref_id"
    elif issubclass(value_type, BranchScopeToken):
        kind = "opaque_carrier"
    elif issubclass(value_type, BaseException):
        kind = "opaque_carrier"
    elif issubclass(value_type, (str, *_SCALAR_LEAF_TYPES)):
        kind = "leaf"
    elif issubclass(
        value_type,
        (SessionHandlePayloadOpaqueMarker, ConnectionPayloadOpaqueMarker),
    ):
        kind = "opaque_carrier"
    elif issubclass(value_type, _FUNCTION_OPAQUE_TYPES):
        kind = "opaque_carrier"
    elif issubclass(value_type, LazySessionSqlSource):
        # Opaque, and specifically not traversable. It wraps a step, but that step
        # is not in the plan -- it was lifted out at bind time so its query could
        # travel inside other statements -- so its ref id is not part of the
        # plan's namespace. Traversal here exists to rewrite internal refs when a
        # plan is cloned, and rewriting this one would rename something nothing
        # refers to.
        kind = "opaque_carrier"
    elif issubclass(value_type, SqlRenderable):
        kind = "opaque_carrier"
    elif issubclass(value_type, Field):
        kind = "opaque_carrier"
    elif issubclass(value_type, JSONType):
        kind = "opaque_carrier"
    elif issubclass(value_type, Expression):
        kind = "expression"
    elif issubclass(value_type, QueryFilter):
        kind = "query_filter"
    elif issubclass(value_type, AliasedExpression):
        kind = "aliased_expression"
    elif issubclass(value_type, JoinClause):
        kind = "join_clause"
    elif issubclass(value_type, ServerPlanStep):
        kind = "step"
    elif issubclass(value_type, ServerRef):
        kind = "server_ref"
    elif isinstance(getattr(value_type, "__plan_payload_fields__", None), tuple):
        kind = "custom_named_state"
    elif issubclass(value_type, BaseModel):
        kind = "base_model"
    elif is_dataclass(value_type):
        kind = "dataclass"
    return kind


_PAYLOAD_TYPE_CACHE: WeakLocalMetadataCache[type[object], tuple[tuple[object, ...], PayloadKind | None]] = WeakLocalMetadataCache(
    name="serverplan:payload_type_classification",
    invalidation_policy=LocalMetadataInvalidationPolicy.IMMUTABLE_KEY_METADATA,
)


@pure_lazy
def _payload_type_shape_for_planning(value_type: type[object]) -> tuple[object, ...]:
    """Return only classification inputs that can change after class creation."""
    return (
        value_type.__name__,
        getattr(value_type, "__plan_payload_fields__", None),
        is_dataclass(value_type),
        issubclass(value_type, tuple),
        issubclass(value_type, list),
        issubclass(value_type, set),
        issubclass(value_type, frozenset),
        issubclass(value_type, dict),
        issubclass(value_type, ServerPlanRefId),
        issubclass(value_type, BranchScopeToken),
        issubclass(value_type, BaseException),
        issubclass(value_type, _SCALAR_LEAF_TYPES),
        issubclass(value_type, (SessionHandlePayloadOpaqueMarker, ConnectionPayloadOpaqueMarker)),
        issubclass(value_type, _FUNCTION_OPAQUE_TYPES),
        issubclass(value_type, LazySessionSqlSource),
        issubclass(value_type, SqlRenderable),
        issubclass(value_type, Field),
        issubclass(value_type, JSONType),
        issubclass(value_type, Expression),
        issubclass(value_type, QueryFilter),
        issubclass(value_type, AliasedExpression),
        issubclass(value_type, JoinClause),
        issubclass(value_type, ServerPlanStep),
        issubclass(value_type, ServerRef),
        issubclass(value_type, BaseModel),
    )


@pure_lazy
def _cached_payload_type_for_planning(value_type: type[object]) -> PayloadKind | None:
    shape = _payload_type_shape_for_planning(value_type)
    cached = _PAYLOAD_TYPE_CACHE.get_for_key(value_type)
    if cached is not None and cached[0] == shape:
        return cached[1]
    kind = _classify_payload_type(value_type)
    _PAYLOAD_TYPE_CACHE.set_for_key(value_type, (shape, kind))
    return kind


_cached_payload_type = _cached_payload_type_for_planning


@pure_lazy
def classify_payload(
    value: object,
    *,
    type_cache: dict[type[object], PayloadKind | None] | None = None,
) -> PayloadKind:
    value_type = type(value)
    if value_type in (type(None), bool, int, float, bytes):
        return "leaf"
    if value_type is str:
        return "string"
    if value_type is tuple:
        return "tuple"
    if value_type is list:
        return "list"
    if value_type is set:
        return "set"
    if value_type is frozenset:
        return "frozenset"
    if value_type is dict:
        return "dict"
    if value_type is Expression:
        return "expression"
    if value_type is QueryFilter:
        return "query_filter"
    if value_type is AliasedExpression:
        return "aliased_expression"
    if value_type is JoinClause:
        return "join_clause"
    if type_cache is None:
        cached_kind = _cached_payload_type_for_planning(value_type)
    elif value_type in type_cache:
        cached_kind = type_cache[value_type]
    else:
        cached_kind = _cached_payload_type_for_planning(value_type)
        type_cache[value_type] = cached_kind
    return "unsupported" if cached_kind is None else cached_kind


@pure_lazy
def payload_category(value: object) -> PayloadCategory:
    kind = classify_payload(value)
    if kind in {"leaf"}:
        return "leaf"
    if kind in {"opaque_carrier"}:
        return "opaque_carrier"
    if kind == "unsupported":
        return "unsupported"
    return "traversable"


@pure_lazy
def _named_attr_items(value: object, names: tuple[str, ...]) -> tuple[tuple[str, PlanPayloadValue], ...]:
    return tuple((name, cast(PlanPayloadValue, object.__getattribute__(value, name))) for name in names)


@pure_lazy
def _server_ref_named_state_items(value: ServerRef[object]) -> tuple[tuple[str, PlanPayloadValue], ...]:
    return cast("tuple[tuple[str, PlanPayloadValue], ...]", server_ref_named_payload_items(value))


@pure_lazy
def _server_ref_traversable_state_items(value: ServerRef[object]) -> tuple[tuple[str, PlanPayloadValue], ...]:
    return cast("tuple[tuple[str, PlanPayloadValue], ...]", server_ref_traversable_payload_items(value))


@pure_lazy
def named_payload_items(value: object) -> tuple[tuple[str, PlanPayloadValue], ...]:
    return _named_payload_items_for_kind(value, classify_payload(value))


@pure_lazy
def _named_payload_items_for_kind(
    value: object,
    kind: PayloadKind,
) -> tuple[tuple[str, PlanPayloadValue], ...]:
    if kind == "expression":
        return _named_attr_items(value, _EXPRESSION_STATE_FIELDS)
    if kind == "query_filter":
        return _named_attr_items(value, _QUERY_FILTER_STATE_FIELDS)
    if kind == "aliased_expression":
        return _named_attr_items(value, _ALIASED_EXPRESSION_STATE_FIELDS)
    if kind == "join_clause":
        return _named_attr_items(value, _JOIN_CLAUSE_STATE_FIELDS)
    if kind == "base_model":
        assert isinstance(value, BaseModel)
        items: list[tuple[str, PlanPayloadValue]] = []
        for name in cached_model_fields(type(value)):
            try:
                items.append((name, cast(PlanPayloadValue, object.__getattribute__(value, name))))
            except AttributeError:
                continue
        return tuple(items)
    if kind == "dataclass":
        assert is_dataclass(value)
        return tuple((field.name, cast(PlanPayloadValue, object.__getattribute__(value, field.name))) for field in fields(value))
    if kind == "custom_named_state":
        field_names = getattr(type(value), "__plan_payload_fields__")
        assert isinstance(field_names, tuple)
        return _named_attr_items(value, field_names)
    if kind == "step":
        assert isinstance(value, ServerPlanStep)
        return tuple(value.internal_plan_state().items())
    if kind == "server_ref":
        assert isinstance(value, ServerRef)
        return _server_ref_named_state_items(value)
    msg = f"Payload kind {kind!r} does not expose named state"
    raise TypeError(msg)


@pure_lazy
def payload_has_named_state(value: object) -> bool:
    return classify_payload(value) in _NAMED_STATE_KINDS


@pure_lazy
def payload_kind_has_named_state(kind: PayloadKind) -> bool:
    return kind in _NAMED_STATE_KINDS


@pure_lazy
def payload_kind_needs_identity_guard(kind: PayloadKind) -> bool:
    return kind in _IDENTITY_GUARD_KINDS


@pure_lazy
def traversable_named_payload_items(value: object) -> tuple[tuple[str, PlanPayloadValue], ...]:
    return _traversable_named_payload_items_for_kind(value, classify_payload(value))


@pure_lazy
def _traversable_named_payload_items_for_kind(
    value: object,
    kind: PayloadKind,
) -> tuple[tuple[str, PlanPayloadValue], ...]:
    if kind == "step":
        assert isinstance(value, ServerPlanStep)
        return tuple(value.internal_plan_ref_state().items())
    if kind == "server_ref":
        assert isinstance(value, ServerRef)
        return _server_ref_traversable_state_items(value)
    if kind in _NAMED_STATE_KINDS:
        return _named_payload_items_for_kind(value, kind)
    msg = f"Payload kind {kind!r} does not expose traversable named state"
    raise TypeError(msg)


@pure_lazy
def sequence_payload_items(value: object) -> tuple[PlanPayloadValue, ...]:
    kind = classify_payload(value)
    if kind in {"tuple", "list", "set", "frozenset"}:
        assert isinstance(value, tuple | list | set | frozenset)
        return tuple(cast(PlanPayloadValue, item) for item in value)
    msg = f"Payload kind {kind!r} is not a sequence container"
    raise TypeError(msg)


@pure_lazy
def mapping_payload_items(value: object) -> tuple[tuple[PlanPayloadValue, PlanPayloadValue], ...]:
    kind = classify_payload(value)
    if kind != "dict":
        msg = f"Payload kind {kind!r} is not a mapping container"
        raise TypeError(msg)
    assert isinstance(value, (dict, types.MappingProxyType))
    return tuple((cast(PlanPayloadValue, key), cast(PlanPayloadValue, item)) for key, item in value.items())


@pure_lazy
def payload_needs_identity_guard(value: object) -> bool:
    return classify_payload(value) in _IDENTITY_GUARD_KINDS


@pure_lazy
def traversable_payload_children_for_kind(value: object, kind: PayloadKind) -> tuple[object, ...]:
    """Return payload children without classifying an already classified value again."""
    if kind in {"string", "server_plan_ref_id", "leaf", "opaque_carrier"}:
        return ()
    if kind == "step":
        assert isinstance(value, ServerPlanStep)
        return tuple(value.internal_plan_ref_state().values())
    if kind == "server_ref":
        assert isinstance(value, ServerRef)
        return tuple(child for _name, child in _server_ref_traversable_state_items(value))
    if kind == "expression":
        return tuple(child for _name, child in _named_attr_items(value, _EXPRESSION_STATE_FIELDS))
    if kind == "query_filter":
        return tuple(child for _name, child in _named_attr_items(value, _QUERY_FILTER_STATE_FIELDS))
    if kind == "aliased_expression":
        return tuple(child for _name, child in _named_attr_items(value, _ALIASED_EXPRESSION_STATE_FIELDS))
    if kind == "join_clause":
        return tuple(child for _name, child in _named_attr_items(value, _JOIN_CLAUSE_STATE_FIELDS))
    if kind == "base_model":
        assert isinstance(value, BaseModel)
        children: list[object] = []
        for name in cached_model_fields(type(value)):
            try:
                children.append(cast(object, object.__getattribute__(value, name)))
            except AttributeError:
                continue
        return tuple(children)
    if kind == "dataclass":
        assert is_dataclass(value)
        return tuple(cast(object, object.__getattribute__(value, field.name)) for field in fields(value))
    if kind == "custom_named_state":
        field_names = getattr(type(value), "__plan_payload_fields__")
        assert isinstance(field_names, tuple)
        return tuple(child for _name, child in _named_attr_items(value, field_names))
    if kind in {"tuple", "list", "set", "frozenset"}:
        assert isinstance(value, tuple | list | set | frozenset)
        return tuple(value)
    if kind == "dict":
        assert isinstance(value, (dict, types.MappingProxyType))
        children = []
        for key, item in value.items():
            children.extend((key, item))
        return tuple(children)
    msg = f"Payload kind {kind!r} does not expose traversable children: {type(value).__module__}.{type(value).__qualname__}"
    raise TypeError(msg)


@pure_lazy
def traversable_payload_children(value: object) -> tuple[object, ...]:
    return traversable_payload_children_for_kind(value, classify_payload(value))


@pure_lazy
def rewrite_internal_ref_text(text: str, ref_id_map: dict[str, str] | Mapping[str, str]) -> str:
    rewritten_exact = ref_id_map.get(text)
    if rewritten_exact is not None:
        return rewritten_exact
    base_ref, separator, suffix = text.partition(".")
    rewritten_base = ref_id_map.get(base_ref)
    if rewritten_base is None:
        return text
    return f"{rewritten_base}.{suffix}" if separator else rewritten_base


@pure_lazy
def is_internal_plan_ref_text(value: str) -> bool:
    base_ref = value.partition(".")[0]
    for prefix in _INTERNAL_PLAN_REF_PREFIXES:
        suffix = base_ref.removeprefix(prefix)
        if suffix == base_ref:
            continue
        numeric_prefix = suffix.split("_", 1)[0]
        if numeric_prefix.isdecimal():
            return True
    return False


@pure_lazy
def _replace_payload_placeholder(
    current: object,
    placeholder: object,
    replacement: object,
    seen: set[int],
    *,
    unsupported_context: str,
) -> object:
    if current is placeholder:
        return replacement
    kind = classify_payload(current)
    if kind in {"leaf", "opaque_carrier", "string", "server_plan_ref_id"}:
        return current

    if payload_needs_identity_guard(current):
        current_id = id(current)
        if current_id in seen:
            return current
        seen.add(current_id)

    if payload_has_named_state(current):
        for attr_name, attr_value in traversable_named_payload_items(current):
            object.__setattr__(
                current,
                attr_name,
                _replace_payload_placeholder(
                    attr_value,
                    placeholder,
                    replacement,
                    seen,
                    unsupported_context=unsupported_context,
                ),
            )
        return current
    if kind == "tuple":
        assert isinstance(current, tuple)
        rewritten_tuple = tuple(
            _replace_payload_placeholder(
                item,
                placeholder,
                replacement,
                seen,
                unsupported_context=unsupported_context,
            )
            for item in sequence_payload_items(current)
        )
        return current if rewritten_tuple == current else rewritten_tuple
    if kind == "list":
        assert isinstance(current, list)
        for index, item in enumerate(sequence_payload_items(current)):
            current[index] = _replace_payload_placeholder(
                item,
                placeholder,
                replacement,
                seen,
                unsupported_context=unsupported_context,
            )
        return current
    if kind == "set":
        assert isinstance(current, set)
        rewritten_set_items = {
            _replace_payload_placeholder(
                item,
                placeholder,
                replacement,
                seen,
                unsupported_context=unsupported_context,
            )
            for item in sequence_payload_items(current)
        }
        if rewritten_set_items != current:
            current.clear()
            current.update(rewritten_set_items)
        return current
    if kind == "frozenset":
        assert isinstance(current, frozenset)
        rewritten_frozenset = frozenset(
            _replace_payload_placeholder(
                item,
                placeholder,
                replacement,
                seen,
                unsupported_context=unsupported_context,
            )
            for item in sequence_payload_items(current)
        )
        return current if rewritten_frozenset == current else rewritten_frozenset
    if kind == "dict":
        assert isinstance(current, (dict, types.MappingProxyType))
        rewritten_items: list[tuple[object, object]] = [
            (
                _replace_payload_placeholder(
                    key,
                    placeholder,
                    replacement,
                    seen,
                    unsupported_context=unsupported_context,
                ),
                _replace_payload_placeholder(
                    item,
                    placeholder,
                    replacement,
                    seen,
                    unsupported_context=unsupported_context,
                ),
            )
            for key, item in mapping_payload_items(current)
        ]
        if isinstance(current, types.MappingProxyType):
            if any(
                new_key is not key or new_value is not value
                for (new_key, new_value), (key, value) in zip(rewritten_items, current.items(), strict=True)
            ):
                raise TypeError("Cannot replace a cyclic payload placeholder through a readonly mapping")
            return current
        current.clear()
        current.update(rewritten_items)
        return current
    msg = f"Unsupported {unsupported_context} payload shape: {type(current).__name__}"
    raise TypeError(msg)


@pure_lazy
def _transform_payload(
    value: object,
    memo: dict[int, object],
    *,
    type_kinds: dict[type[object], PayloadKind],
    rewrite_text: Callable[[str], str] | None = None,
    unsupported_context: str,
) -> object:
    value_type = type(value)
    kind = type_kinds.get(value_type)
    if kind is None:
        kind = classify_payload(value)
        type_kinds[value_type] = kind
    if kind == "string":
        assert type(value) is str
        return value if rewrite_text is None else rewrite_text(value)
    if kind == "server_plan_ref_id":
        current_text = str(value)
        rewritten = current_text if rewrite_text is None else rewrite_text(current_text)
        return value if rewritten == current_text else ServerPlanRefId(rewritten)
    if kind in {"leaf", "opaque_carrier"}:
        return value

    current_id: int | None = None
    if payload_kind_needs_identity_guard(kind):
        current_id = id(value)
        if current_id in memo:
            return memo[current_id]

    if payload_kind_has_named_state(kind):
        state_items = _named_payload_items_for_kind(value, kind)
        if kind == "custom_named_state" and is_dataclass(value):
            state_items = tuple(
                (field.name, cast(PlanPayloadValue, object.__getattribute__(value, field.name))) for field in fields(value)
            )
            traversable_items = _named_payload_items_for_kind(value, kind)
        else:
            traversable_items = _traversable_named_payload_items_for_kind(value, kind) if kind in {"step", "server_ref"} else state_items
        traversable_attr_names = {attr_name for attr_name, _attr_value in traversable_items}
        if isinstance(value, BaseModel):
            if current_id is not None:
                memo[current_id] = value
            updates: dict[str, object] = {}
            for attr_name, attr_value in state_items:
                if attr_name not in traversable_attr_names:
                    continue
                updates[attr_name] = _transform_payload(
                    attr_value,
                    memo,
                    type_kinds=type_kinds,
                    rewrite_text=rewrite_text,
                    unsupported_context=unsupported_context,
                )
            cloned_model = value.model_copy(update=updates)
            if current_id is not None:
                memo[current_id] = cloned_model
            return cloned_model
        cloned_value = object.__new__(type(value))
        if current_id is not None:
            memo[current_id] = cloned_value
        for attr_name, attr_value in state_items:
            next_value = (
                _transform_payload(
                    attr_value,
                    memo,
                    type_kinds=type_kinds,
                    rewrite_text=rewrite_text,
                    unsupported_context=unsupported_context,
                )
                if attr_name in traversable_attr_names
                else attr_value
            )
            if isinstance(value, CteSource) and attr_name == "cte_name" and rewrite_text is not None:
                next_value = SqlTableName(rewrite_text(str(value.cte_name)))
            object.__setattr__(cloned_value, attr_name, next_value)
        if isinstance(cloned_value, ServerPlanStep):
            assert isinstance(value, ServerPlanStep)
            cloned_value._initialize_transient_plan_state()
            for field_name in value.internal_plan_preserved_transient_state_fields():
                if hasattr(value, field_name):
                    object.__setattr__(cloned_value, field_name, getattr(value, field_name))
        return cloned_value
    if kind == "tuple":
        tuple_placeholder: list[object] = []
        assert current_id is not None
        memo[current_id] = tuple_placeholder
        rewritten_tuple = tuple(
            _transform_payload(
                item,
                memo,
                type_kinds=type_kinds,
                rewrite_text=rewrite_text,
                unsupported_context=unsupported_context,
            )
            for item in sequence_payload_items(value)
        )
        resolved_tuple = cast(
            "tuple[object, ...]",
            _replace_payload_placeholder(
                rewritten_tuple,
                tuple_placeholder,
                rewritten_tuple,
                set(),
                unsupported_context=unsupported_context,
            ),
        )
        memo[current_id] = resolved_tuple
        return resolved_tuple
    if kind == "list":
        rewritten_list: list[object] = []
        assert current_id is not None
        memo[current_id] = rewritten_list
        rewritten_list.extend(
            _transform_payload(
                item,
                memo,
                type_kinds=type_kinds,
                rewrite_text=rewrite_text,
                unsupported_context=unsupported_context,
            )
            for item in sequence_payload_items(value)
        )
        return rewritten_list
    if kind == "set":
        rewritten_set: set[object] = set()
        assert current_id is not None
        memo[current_id] = rewritten_set
        rewritten_set.update(
            _transform_payload(
                item,
                memo,
                type_kinds=type_kinds,
                rewrite_text=rewrite_text,
                unsupported_context=unsupported_context,
            )
            for item in sequence_payload_items(value)
        )
        return rewritten_set
    if kind == "frozenset":
        frozenset_placeholder: set[object] = set()
        assert current_id is not None
        memo[current_id] = frozenset_placeholder
        rewritten_frozenset = frozenset(
            _transform_payload(
                item,
                memo,
                type_kinds=type_kinds,
                rewrite_text=rewrite_text,
                unsupported_context=unsupported_context,
            )
            for item in sequence_payload_items(value)
        )
        resolved_frozenset = cast(
            "frozenset[object]",
            _replace_payload_placeholder(
                rewritten_frozenset,
                frozenset_placeholder,
                rewritten_frozenset,
                set(),
                unsupported_context=unsupported_context,
            ),
        )
        memo[current_id] = resolved_frozenset
        return resolved_frozenset
    if kind == "dict":
        rewritten_dict: dict[object, object] = {}
        rewritten_mapping = types.MappingProxyType(rewritten_dict) if isinstance(value, types.MappingProxyType) else rewritten_dict
        assert current_id is not None
        memo[current_id] = rewritten_mapping
        rewritten_dict.update(
            (
                _transform_payload(
                    key,
                    memo,
                    type_kinds=type_kinds,
                    rewrite_text=rewrite_text,
                    unsupported_context=unsupported_context,
                ),
                _transform_payload(
                    item,
                    memo,
                    type_kinds=type_kinds,
                    rewrite_text=rewrite_text,
                    unsupported_context=unsupported_context,
                ),
            )
            for key, item in mapping_payload_items(value)
        )
        return rewritten_mapping
    msg = f"Unsupported {unsupported_context} payload shape: {type(value).__name__}"
    raise TypeError(msg)


@pure_lazy
def clone_payload_graph(value: T, memo: dict[int, object] | None = None) -> T:
    current_memo = {} if memo is None else memo
    return cast(
        T,
        _transform_payload(
            value,
            current_memo,
            type_kinds={},
            unsupported_context="prerequisite",
        ),
    )


@pure_lazy
def rewrite_internal_plan_refs_payload(value: T, ref_id_map: Mapping[str, str]) -> T:
    def _rewrite_text(current: str) -> str:
        if not is_internal_plan_ref_text(current):
            return current
        return rewrite_internal_ref_text(current, ref_id_map)

    return cast(
        T,
        _transform_payload(
            value,
            {},
            type_kinds={},
            rewrite_text=_rewrite_text,
            unsupported_context="plan-ref rewrite",
        ),
    )


@pure_lazy
def rewrite_exact_plan_refs_payload(value: T, ref_id_map: Mapping[str, str]) -> T:
    """Rewrite exact namespaced refs and their dotted projections in a typed payload."""

    def _rewrite_text(current: str) -> str:
        direct = ref_id_map.get(current)
        if direct is not None:
            return direct
        probe = current
        while "." in probe:
            probe, _, _projection = probe.rpartition(".")
            mapped = ref_id_map.get(probe)
            if mapped is not None:
                return f"{mapped}{current[len(probe) :]}"
        return current

    return cast(
        T,
        _transform_payload(
            value,
            {},
            type_kinds={},
            rewrite_text=_rewrite_text,
            unsupported_context="exact plan-ref rewrite",
        ),
    )


@pure_lazy
def collect_internal_seed_ref_texts(value: object) -> frozenset[str]:
    seed_refs: set[str] = set()
    seen: set[int] = set()

    def _collect(current: object) -> None:
        kind = classify_payload(current)
        if kind == "string":
            assert type(current) is str
            base_ref = current.partition(".")[0]
            if is_internal_plan_ref_text(base_ref) and base_ref.startswith("seed_"):
                seed_refs.add(base_ref)
            return
        if kind == "server_plan_ref_id":
            _collect(str(current))
            return
        if kind in {"leaf", "opaque_carrier"}:
            return
        if payload_needs_identity_guard(current):
            current_id = id(current)
            if current_id in seen:
                return
            seen.add(current_id)
        for child in traversable_payload_children(current):
            _collect(child)

    _collect(value)
    return frozenset(seed_refs)

