def _closure_seeded_constants[StepsItemT](
    plan: BaseServerPlan,
    closure_ref_ids: set[str],
    steps: Sequence[ServerPlanStep[StepsItemT]],
) -> tuple[dict[str, Any], dict[str, SqlColumnTypeHints]]:
    """Collect seeded constants and their declared SQL hints for an exported closure."""
    seeded: dict[str, Any] = {}
    seeded_sql_hints: dict[str, SqlColumnTypeHints] = {}
    required_seed_refs = {ref_id for ref_id in closure_ref_ids if is_prerequisite_seed_ref_id(ServerPlanRefId(ref_id))}
    for step in steps:
        required_seed_refs.update(_collect_internal_seed_ref_texts(step))
    for ref_id in sorted(required_seed_refs):
        if not is_prerequisite_seed_ref_id(ServerPlanRefId(ref_id)):
            continue
        typed_ref_id = ServerPlanRefId(ref_id)
        if typed_ref_id in plan.seeded_constants:
            seeded[ref_id] = plan.seeded_constants[typed_ref_id]
            declared_hints = plan.seeded_constants.declared_sql_hints_for(ref_id)
            if declared_hints is not None:
                seeded_sql_hints[ref_id] = declared_hints
            continue
        found, value = read_seeded_constant_from_ctx(None, ServerPlanRefId(ref_id))
        if found:
            seeded[ref_id] = value
            planless_hints = read_planless_seeded_sql_hints(ServerPlanRefId(ref_id))
            if planless_hints is not None:
                seeded_sql_hints[ref_id] = planless_hints
    return seeded, seeded_sql_hints


def _localize_planless_seed_refs(
    plan: BaseServerPlan,
    step: ServerPlanStep[Any],
) -> ServerPlanStep[Any]:
    """Rewrite planless ``seed_*`` refs into plan-local seeded constants."""
    ref_id_map: dict[str, str] = {}
    seed_ref_ids = {
        prerequisite_base_ref_id(ServerPlanRefId(dependency_ref))
        for dependency_ref in step.dependencies()
        if is_prerequisite_seed_ref_id(ServerPlanRefId(dependency_ref))
    }
    seed_ref_ids.update(_collect_internal_seed_ref_texts(step))
    for base_ref in sorted(seed_ref_ids):
        typed_ref = ServerPlanRefId(base_ref)
        if typed_ref in plan.seeded_constants or base_ref in ref_id_map:
            continue
        found, value = read_seeded_constant_from_ctx(None, ServerPlanRefId(base_ref))
        if not found:
            continue
        localized_seed = plan._allocate_ref_id("seed")
        plan.seeded_constants[localized_seed] = value
        planless_hints = read_planless_seeded_sql_hints(ServerPlanRefId(base_ref))
        if planless_hints is not None:
            plan.seeded_constants.declare_sql_hints(localized_seed, planless_hints)
        ref_id_map[base_ref] = str(localized_seed)
    if not ref_id_map:
        return step
    return cast("ServerPlanStep[Any]", _rewrite_internal_plan_refs(step, ref_id_map))


