    if (
        _is_read_or_write_transaction(txn)
        or _is_schema_transaction_plan_target(txn)
        or _is_versioned_transaction_plan_target(txn)
        or _is_handle_plan_target(txn)
    ):
        return txn._session_id
    msg = f"BaseServerPlan requires a transaction target with a session id, got {type(txn).__name__}"
    raise TypeError(msg)


def _backend_profile_for_plan_target(
    target: PlanTarget,
) -> ServerPlanBackendProfile:
    profile = _plan_target_attr(target, "backend_profile")
    if profile is not _MISSING_PLAN_TARGET_ATTR:
        return cast(ServerPlanBackendProfile, profile)
    conn = _plan_target_attr(target, "_conn")
    if conn is _MISSING_PLAN_TARGET_ATTR:
        msg = f"Cannot resolve ServerPlan backend profile for {type(target).__name__}"
        raise TypeError(msg)
    from impl.common.l2070_server_plan.backend_profiles import resolve_connection_backend_profile

    return resolve_connection_backend_profile(cast("_DatabaseConnectionCore", conn))


def _graph_traversal_revision_prerequisite(
    txn: object,
) -> tuple[object | None, ServerPlanRefId | None]:
    """Return the explicit revision prerequisite already published on ``txn``.

    Handles three shapes produced by the versioned read transaction layer:

    * SQL-backed ``SqlSyncVersionedReadTransactionBase`` stores a concrete
      ``_revision_id`` directly on ``txn.__dict__``.
    * ``_LazySyncVersionedReadTransaction`` stores a lazy-like object on
      ``_lazy_revision``.
    * Batched/pending lazy values carry a symbolic
      ``_step_ref_id`` pointing at an upstream plan step that will
      publish the revision through a CTE; that ref is threaded through
      as the symbolic ``ServerPlanRefId``.
    """
    revision_id = txn._revision_id if isinstance(txn, _RevisionIdCarrier) else None
    lazy_revision = txn._lazy_revision if isinstance(txn, _LazyRevisionCarrier) else None
    revision_ref_id: ServerPlanRefId | None = None
    if lazy_revision is not None:
        dependency_refs = tuple(lazy_param_deps(lazy_revision))
        if len(dependency_refs) == 1:
            revision_ref_id = ServerPlanRefId(dependency_refs[0])
        elif len(dependency_refs) > 1:
            msg = f"Expected at most one lazy revision dependency, got {dependency_refs!r}"
            raise RuntimeError(msg)
    return revision_id, revision_ref_id


class BaseServerPlan(ServerPlan):
    """Base implementation of ServerPlan using the ServerPlanStep pipeline.

    Plan building methods (select_one, insert, query, etc.) construct
    ServerPlanStep objects directly. On execute(), steps are executed
    via the pipeline (SqlBackendExecutor for SQL backends).

    Attributes:
        _txn: The transaction to execute operations on
        _session_id: Session ID for session validation batching
        _steps: List of plan steps to execute
        _returns: Mapping of result names to ref_ids
        _next_ref_id: Counter for generating unique ref IDs
    """

    @classmethod
    def from_executable_plan(
        cls,
        *,
        transaction: PlanTarget,
        executable_plan: ExecutablePlan,
    ) -> BaseServerPlan:
        """Bind one compiled execution product to transaction authority."""
        if executable_plan.semantic_fingerprint != executable_plan.semantic_plan.fingerprint:
            msg = "Executable plan semantic fingerprint changed before runtime binding"
            raise ValueError(msg)
        return cls.from_semantic_plan(
            transaction=transaction,
            semantic_plan=executable_plan.semantic_plan,
            backend_profile=executable_plan.backend_profile,
        )

    @classmethod
    def from_semantic_plan(
        cls,
        *,
        transaction: PlanTarget,
        semantic_plan: SemanticPlan,
        backend_profile: ServerPlanBackendProfile,
    ) -> BaseServerPlan:
        """Bind one frozen semantic graph to a transaction-owned runtime plan."""
        builder = SemanticPlanBuilder(
            namespace=semantic_plan.namespace,
            generation=semantic_plan.generation,
            legacy_ref_ids=semantic_plan.legacy_ref_ids,
        )
        builder.replace_steps(semantic_plan.steps)
        for seed in semantic_plan.seeds:
            if seed.structural:
                builder.seeded_constants[seed.ref_id] = seed.value
                if seed.sql_hints is not None:
                    builder.seeded_constants.declare_sql_hints(seed.ref_id, seed.sql_hints)
            else:
                builder.add_runtime_input(
                    seed.ref_id,
                    seed.value,
                    sql_hints=seed.sql_hints,
                )
        for binding in semantic_plan.returns:
            builder.add_return(binding.name, binding.ref_id)
        if semantic_plan.legacy_ref_ids:
            ordinals = (
                int(tail)
                for ref_id in (
                    *(step.ref_id for step in semantic_plan.steps),
                    *(seed.ref_id for seed in semantic_plan.seeds),
                )
                if (tail := str(ref_id).rpartition("_")[2]).isdecimal()
            )
            builder.reserve_legacy_ref_ordinal(max(ordinals, default=-1) + 1)
        plan = cls(
            transaction,
            backend_profile=backend_profile,
            semantic_plan_builder=builder,
        )
        if _is_versioned_transaction_plan_target(transaction):
            plan.bind_versioning_domain(transaction.domain)
        for binding in semantic_plan.returns:
            plan.return_result(
                str(binding.name),
                ScalarServerRef[Any](None, binding.ref_id),
            )
        if builder.freeze().fingerprint != semantic_plan.fingerprint:
            msg = "Runtime adapter changed the semantic plan fingerprint"
            raise ValueError(msg)
        return plan

    def __init__(
        self: BaseServerPlan,
        txn: PlanTarget,
        session_id: SessionId | None = None,
        *,
        backend_profile: ServerPlanBackendProfile | None = None,
        semantic_plan_builder: SemanticPlanBuilder | None = None,
        runtime_services: ServerPlanRuntimeServices | None = None,
    ) -> None:
        """Initialize the server plan.

        Args:
            txn: The transaction that owns this plan
            session_id: Session ID for session validation batching (if None, extracted from txn)
        """
        if (
            not _is_read_or_write_transaction(txn)
            and not _is_schema_transaction_plan_target(txn)
            and not _is_versioned_transaction_plan_target(txn)
            and not _is_handle_plan_target(txn)
        ):
            msg = f"BaseServerPlan requires a transaction target, got {type(txn).__name__}"
            raise TypeError(msg)
        target = txn
        self._txn: PlanTarget = target
        self._terminal_lifecycle_selected = False
        # Extract session_id from transaction if not explicitly provided
        self._session_id: SessionId | None
        if session_id is not None:
            self._session_id = session_id
        else:
            self._session_id = _session_id_for_plan_target(target)
        if semantic_plan_builder is None:
            semantic_plan_builder = SemanticPlanBuilder.legacy_generation(
                namespace=PlanNamespaceId("server-plan"),
                generation=PlanGenerationId("active"),
            )
        self._semantic_plan_builder = semantic_plan_builder
        self._steps = semantic_plan_builder._execution_step_storage()
        self._step_ref_ids = semantic_plan_builder._execution_ref_storage()
        self._has_write_step = False
        self._returns: dict[str, str] = {}
        self._return_variants: dict[str, ServerRefVariant] = {}
        self._return_type_hints: dict[str, type[Any]] = {}
        self._last_rtt_audit: ServerPlanRttAudit | None = None
        self._flush_ctx: PlanFlushContext = PlanFlushContext(self)
        self._auto_api_hook_registry: Any | None = None
        self._versioned_read_context_binding: VersionedReadContextBinding | None = None
        self._explicit_versioning_domain: type[VersioningDomain] | None = None
        self._preserve_across_flush_ref_ids: frozenset[str] = frozenset()
        self._preserve_across_flush_steps: dict[str, ServerPlanStep[Any]] = {}
        self._outer_lazy_plan_steps: tuple[ServerPlanStep[Any], ...] = ()
        self._runtime_services = runtime_services or bind_runtime_services_for_plan_target(target)
        self._captured_hook_runtime_services: ServerPlanRuntimeServices = ServerPlanRuntimeServices()
        self._prepared_physical_execution: object | None = None
        self._prepared_runtime_values: dict[str, object] = {}
        self._branch_route_guard: BranchRouteProofStep | None = None
        self._system_authority_fingerprint_only = False
        self._query_mutation_guard: QueryMutationGuard | None = None
        if backend_profile is None:
            backend_profile = _backend_profile_for_plan_target(target)
        self._backend_profile: ServerPlanBackendProfile = backend_profile
        self.seeded_constants = semantic_plan_builder.seeded_constants

    def _bind_query_mutation_guard(
        self,
        guard: QueryMutationGuard,
    ) -> None:
        """Bind one explicit pre-plan gate for query-builder mutations."""
        if self._query_mutation_guard is not None and self._query_mutation_guard != guard:
            raise RuntimeError("Query mutation guard is already bound for this plan")
        self._query_mutation_guard = guard

    def _apply_query_mutation_guard(
        self,
        model_cls: type[DatabaseObjectRow],
        operation: QueryMutationOperation,
    ) -> None:
        """Run the bound mutation gate before a mutation enters the semantic plan."""
        if self._query_mutation_guard is not None:
            self._query_mutation_guard(model_cls, operation)

    def mark_system_authority_fingerprint_only(self: BaseServerPlan) -> None:
        """Permanently prevent execution of a pre-issuance fingerprint plan."""
        self._system_authority_fingerprint_only = True

    def compose_branch_route_guard(
        self: BaseServerPlan,
        candidate: BranchRouteProofStep,
    ) -> tuple[BranchRouteProofStep, bool]:
        """Merge branch-route assumptions under one request-owned proof."""
        existing = self._branch_route_guard
        if existing is None:
            self._branch_route_guard = candidate
            return candidate, True
        existing.absorb(candidate)
        return existing, False

    @property
    def mutation_ordering_refs(self: BaseServerPlan) -> frozenset[ServerPlanRefId]:
        """Return transaction-owned ordering refs for write intents."""
        from l2050_transaction.transaction import LazyWriteTransaction

        if not isinstance(self._txn, LazyWriteTransaction):
            return frozenset()
        return self._txn._mutation_ordering_refs

    def request_sql_relation_publication(self: BaseServerPlan, ref_id: ServerPlanRefId) -> None:
        """Tell the producer that a later step names its result rows in SQL."""
        target = str(ref_id)
        steps_by_ref = {str(step.ref_id): step for step in self._steps}
        while target:
            step = steps_by_ref.get(target)
            if step is not None:
                step.require_sql_relation_publication()
                return
            target, _, _ = target.rpartition(".")

