    def export_ref_closure(
        self: BaseServerPlan,
        refs: Sequence[ServerPlanRefId | str],
    ) -> RuntimePrerequisiteBinding:
        """Export a closed prerequisite step graph for import into another plan."""
        requested_ref_ids = {str(ref) for ref in refs}
        root_ref_ids = {prerequisite_base_ref_id(ServerPlanRefId(ref_id)) for ref_id in requested_ref_ids}
        closure_ref_ids = self._expand_ref_closure(root_ref_ids)
        steps_by_ref = {str(step.ref_id): step for step in self._steps}
        steps = tuple(step for step in self._steps if str(step.ref_id) in closure_ref_ids)
        projections = self._prerequisite_projections(requested_ref_ids, steps_by_ref)
        binding = self._versioned_read_context_binding_for_prerequisites(projections)
        seeded_constants, seeded_sql_hints = _closure_seeded_constants(self, closure_ref_ids, steps)
        fragment = PlanPrerequisiteFragment(
            closure=OwnedPrerequisiteClosure(
                step_specs=tuple(OwnedPrerequisiteStepSpec.from_step(step) for step in steps),
            ),
            ref_ids=frozenset(closure_ref_ids),
            seeded_constants=seeded_constants,
            seeded_sql_hints=seeded_sql_hints,
            projections=projections,
            versioned_read_context=binding,
        )
        return RuntimePrerequisiteBinding(
            fragment=fragment,
            resolution_sink=self._flush_ctx,
        )

    def export_transportable_intent_closure(
        self: BaseServerPlan,
        returns: Mapping[str, ServerPlanRefId | str],
    ) -> object:
        """Export a closed remote intent graph for named return refs."""
        from impl.remote.intent_codec import serialize_intent_step
        from impl.remote.protocol import RemoteIntentGraph
        from l2070_batching.intent_step import IntentStep

        requested_ref_ids = {str(ref) for ref in returns.values()}
        root_ref_ids = {ref_id.split(".", 1)[0] for ref_id in requested_ref_ids}
        transport_steps = self._transport_export_steps()
        closure_ref_ids = self._expand_transport_ref_closure(root_ref_ids, steps=transport_steps)
        steps_by_ref = {str(step.ref_id): step for step in transport_steps}
        missing = tuple(sorted(ref_id for ref_id in closure_ref_ids if ref_id not in steps_by_ref))
        if missing:
            msg = f"Remote intent closure contains missing producer refs: {missing!r}"
            raise DependencyContractError(msg)
        nodes = []
        for step in transport_steps:
            ref_id = str(step.ref_id)
            if ref_id not in closure_ref_ids:
                continue
            if not isinstance(step, IntentStep):
                msg = (
                    f"Remote intent closure requires non-intent step {ref_id!r} "
                    f"({type(step).__name__}); add an explicit transport adapter"
                )
                raise DependencyContractError(msg)
            try:
                contract = step.dependency_contract()
            except DependencyContractError:
                contract = None
            if contract is not None and contract.transport is not TransportDependencyPolicy.TRANSPORTABLE:
                msg = f"Remote intent closure requires non-transportable step {ref_id!r} ({type(step).__name__})"
                raise DependencyContractError(msg)
            nodes.append(serialize_intent_step(step))
        return RemoteIntentGraph(
            intents=nodes,
            returns={name: str(ref) for name, ref in returns.items()},
        )

    def _transport_export_steps(self: BaseServerPlan) -> tuple[ServerPlanStep[Any], ...]:
        """Return steps visible to remote intent export, including nested-flush outers."""
        steps: list[ServerPlanStep[Any]] = []
        seen: set[str] = set()
        for step in (
            *self._outer_lazy_plan_steps,
            *tuple(self._steps),
        ):
            ref_id = str(step.ref_id)
            if ref_id in seen:
                continue
            seen.add(ref_id)
            steps.append(step)
        return tuple(steps)

    def import_prerequisites(
        self: BaseServerPlan,
        binding: RuntimePrerequisiteBinding,
    ) -> RuntimeImportedPrerequisites:
        """Import prerequisite steps and bind their runtime result sink."""
        fragment = binding.fragment
        ref_id_map: dict[str, str] = {}
        for step_spec in fragment.closure.step_specs:
            original_ref_id = str(step_spec.template_step.ref_id)
            if is_prerequisite_step_ref_id(ServerPlanRefId(original_ref_id)):
                ref_id_map[original_ref_id] = str(self._allocate_ref_id("step"))
        for seed_ref_id in fragment.seeded_constants:
            if is_prerequisite_seed_ref_id(ServerPlanRefId(seed_ref_id)):
                ref_id_map[seed_ref_id] = str(self._allocate_ref_id("seed"))
        remapped_seeded_constants = {
            _rewrite_internal_ref_text(str(seed_ref_id), ref_id_map): value for seed_ref_id, value in fragment.seeded_constants.items()
        }
        self.seeded_constants.update(remapped_seeded_constants)
        for seed_ref_id, seed_hints in fragment.seeded_sql_hints.items():
            self.seeded_constants.declare_sql_hints(
                _rewrite_internal_ref_text(str(seed_ref_id), ref_id_map),
                seed_hints,
            )
        returned_ref_names: dict[str, str] = {}
        for step_spec in fragment.closure.step_specs:
            original_ref_id = str(step_spec.template_step.ref_id)
            step = cast(
                "ServerPlanStep[Any]",
                _rewrite_internal_plan_refs(step_spec.materialize_step(), ref_id_map),
            )
            ref_id = str(step.ref_id)
            return_name = prerequisite_return_name(ServerPlanRefId(original_ref_id))
            if ref_id in self._step_ref_ids:
                if return_name in self._returns:
                    returned_ref_names[original_ref_id] = return_name
                continue
            if not step.is_lazy_projection() or step.publication_contract().transport is not None:
                self.add_step(step)
                self.return_result(return_name, scalar_ref_for_prerequisite(ServerPlanRefId(ref_id)))
                returned_ref_names[original_ref_id] = return_name
        remapped_versioned_read_context: VersionedReadContextBinding | None = None
        remapped_projections = cast(
            "dict[str, PlanPrerequisiteProjection]",
            _rewrite_internal_plan_refs(fragment.projections, ref_id_map),
        )
        if fragment.versioned_read_context is not None:
            remapped_versioned_read_context = cast(
                "VersionedReadContextBinding",
                _rewrite_internal_plan_refs(fragment.versioned_read_context, ref_id_map),
            )
            self.bind_versioned_read_context(remapped_versioned_read_context)
        imported_fragment = ImportedPrerequisiteFragment(
            ref_ids=fragment.ref_ids,
            returned_ref_names=returned_ref_names,
            projections=remapped_projections,
            versioned_read_context=remapped_versioned_read_context,
        )
        return RuntimeImportedPrerequisites(
            fragment=imported_fragment,
            resolution_sink=binding.resolution_sink,
        )

    def _expand_ref_closure(self: BaseServerPlan, initial_ref_ids: set[str]) -> set[str]:
        steps_by_ref = {str(step.ref_id): step for step in self._steps}
        expanded = set(initial_ref_ids)
        pending = list(initial_ref_ids)
        while pending:
            ref_id = pending.pop()
            step = steps_by_ref.get(ref_id)
            if step is None:
                continue
            for dependency_ref in step.dependencies():
                dependency_text = str(dependency_ref)
                dependency = (
                    dependency_text if dependency_text in steps_by_ref else prerequisite_base_ref_id(ServerPlanRefId(dependency_text))
                )
                if dependency in expanded:
                    continue
                expanded.add(dependency)
                pending.append(dependency)
        return expanded

    def _expand_transport_ref_closure(
        self: BaseServerPlan,
        initial_ref_ids: set[str],
        *,
        steps: Sequence[ServerPlanStep[Any]] | None = None,
    ) -> set[str]:
        candidate_steps = self._steps if steps is None else steps
        steps_by_ref = {str(step.ref_id): step for step in candidate_steps}
        expanded = set(initial_ref_ids)
        pending = list(initial_ref_ids)
        while pending:
            ref_id = pending.pop()
            step = steps_by_ref.get(ref_id)
            if step is None:
                continue
            try:
                dependency_refs = step.dependency_contract().refs_required_for(DependencyUse.TRANSPORT_GRAPH)
            except DependencyContractError:
                dependency_refs = step.dependencies()
            for dependency_ref in dependency_refs:
                dependency_text = str(dependency_ref)
                dependency = dependency_text if dependency_text in steps_by_ref else dependency_text.split(".", 1)[0]
                if dependency in expanded:
                    continue
                expanded.add(dependency)
                pending.append(dependency)
        return expanded

    def _reserve_ref_ids(self: BaseServerPlan, ref_ids: frozenset[str]) -> None:
        for ref_id in ref_ids:
            if not is_prerequisite_step_ref_id(ServerPlanRefId(ref_id)):
                continue
            suffix = ref_id.removeprefix("step_")
            if suffix.isdecimal():
                self._semantic_plan_builder.reserve_legacy_ref_ordinal(int(suffix) + 1)

    def _prerequisite_projections[StepsByRefItemT](
        self: BaseServerPlan,
        requested_ref_ids: set[str],
        steps_by_ref: dict[str, ServerPlanStep[StepsByRefItemT]],
    ) -> dict[str, PlanPrerequisiteProjection]:
        projections: dict[str, PlanPrerequisiteProjection] = {}
        for ref_id in requested_ref_ids:
            direct_projection = PlanPrerequisiteProjection.from_projected_ref_id(ref_id)
            if direct_projection is not None:
                projections[ref_id] = direct_projection
                continue
            step = steps_by_ref.get(ref_id)
            if not isinstance(step, PrerequisiteProjectionContract):
                continue
            projection = PlanPrerequisiteProjection.from_projection_kind(
                projected_ref_id=ref_id,
                source_ref_id=step.prerequisite_source_ref_id(),
                kind=step.prerequisite_projection_kind(),
            )
            if projection is None:
                continue
            projections[ref_id] = projection
        return projections

    def _versioned_read_context_binding_for_prerequisites(
        self: BaseServerPlan,
        projections: dict[str, PlanPrerequisiteProjection],
    ) -> VersionedReadContextBinding | None:
        revision_projection: PlanPrerequisiteProjection | None = None
        branch_projection: PlanPrerequisiteProjection | None = None
        tip_materialization_projection: PlanPrerequisiteProjection | None = None
        for projection in projections.values():
            if projection.role == "read_ctx_revision":
                revision_projection = projection
            elif projection.role == "read_ctx_branch":
                branch_projection = projection
            elif projection.role == "read_ctx_tip_materialization":
                tip_materialization_projection = projection
        if revision_projection is not None and branch_projection is None:
            branch_projection = PlanPrerequisiteProjection(
                projected_ref_id=f"{revision_projection.source_ref_id}.branch_id",
                source_ref_id=revision_projection.source_ref_id,
                field_name="branch_id",
                role="read_ctx_branch",
            )
        source_projection = revision_projection or branch_projection
        if source_projection is not None and tip_materialization_projection is None:
            tip_materialization_projection = PlanPrerequisiteProjection(
                projected_ref_id=f"{source_projection.source_ref_id}.tip_materialization",
                source_ref_id=source_projection.source_ref_id,
                field_name="tip_materialization",
                role="read_ctx_tip_materialization",
            )
        if revision_projection is None and branch_projection is None and tip_materialization_projection is None:
            return None
        return VersionedReadContextBinding(
            revision_projection=revision_projection,
            tip_revision_projection=revision_projection,
            branch_projection=branch_projection,
            tip_materialization_projection=tip_materialization_projection,
        )

    def _txn_for_graph_traversal(self: BaseServerPlan) -> object:
        txn = self._txn
        if _is_versioned_transaction_plan_target(txn):
            return txn
        if not _is_read_or_write_transaction(txn):
            msg = "Graph traversal plan steps require a read or write transaction owner"
            raise TypeError(msg)
        return txn

    def bind_runtime_seed_values[ValuesItemT](
        self: BaseServerPlan,
        values: Mapping[ValuesItemT, object],
    ) -> None:
