    def runtime_seed_values_snapshot(self: BaseServerPlan) -> dict[str, object]:
        """Copy invocation values for an executor-owned prepared physical plan."""
        return {str(ref): value for ref, value in self.seeded_constants.items()}

    def preserve_ref_across_flush_lazy(self: BaseServerPlan, ref_id: ServerPlanRefId) -> None:
        """Keep one semantic producer and its dependency closure for later flushes."""
        steps_by_ref = {str(step.ref_id): step for step in self._steps}
        pending = [str(ref_id)]
        preserved = set(self._preserve_across_flush_ref_ids)
        while pending:
            candidate = pending.pop()
            producer_ref = candidate
            while producer_ref not in steps_by_ref and "." in producer_ref:
                producer_ref = producer_ref.rsplit(".", 1)[0]
            producer = steps_by_ref.get(producer_ref)
            if producer is None or producer_ref in preserved:
                continue
            preserved.add(producer_ref)
            self._preserve_across_flush_steps.setdefault(
                producer_ref,
                clone_payload_graph(producer),
            )
            pending.extend(producer.dependencies())
        if str(ref_id) not in preserved:
            msg = f"Cannot preserve unknown semantic producer {ref_id!r} across flushes"
            raise RuntimeError(msg)
        self._preserve_across_flush_ref_ids = frozenset(preserved)

    def reset(self: BaseServerPlan, *, preserve_across_flush: bool = True) -> None:
        """Clear queued batch state while preserving reusable context only after success."""
        preserve_refs = set(self._preserve_across_flush_ref_ids) if preserve_across_flush else set()
        if preserve_refs:
            self._semantic_plan_builder.replace_steps(
                tuple(
                    clone_payload_graph(self._preserve_across_flush_steps.get(str(step.ref_id), step))
                    for step in self._steps
                    if str(step.ref_id) in preserve_refs
                ),
            )
            self._semantic_plan_builder.clear_returns()
        else:
            self._semantic_plan_builder.clear_steps()
        if not preserve_across_flush:
            self._preserve_across_flush_ref_ids = frozenset()
            self._preserve_across_flush_steps.clear()
        self._has_write_step = False
        self._returns.clear()
        self._return_variants.clear()
        self._return_type_hints.clear()
        self._prepared_physical_execution = None
        self._prepared_runtime_values.clear()
        self._branch_route_guard = None
        if not preserve_refs:
            self.seeded_constants.clear_unguarded_for_plan_reset()

    def add_vector_rebuild_intent(
        self: BaseServerPlan,
        *,
        model_cls: type[DatabaseObjectRow[SysId]],
        index: str,
        backend_kind_override: VectorBackendKind | None = None,
        source_ids: Sequence[SysId] | None = None,
    ) -> ServerPlanRefId:
        """Add a semantic vector-index rebuild intent and return its ref id."""
        from impl.common.l2050_sql_types.sql_branded_types import SqlIndexName
        from impl.common.l2070_server_plan.intent_vector_index_maintenance import (
            VectorIndexMaintenanceIntent,
            VectorIndexMaintenanceOperation,
        )
        from l2070_batching.server_ref import ServerRefs

        if backend_kind_override is None:
            msg = "add_vector_rebuild_intent() requires an explicit backend kind"
            raise ValueError(msg)
        if source_ids:
            msg = (
                "Selected-source vector rebuilds no longer compile from literal source_ids. "
                "Publish an explicit prerequisite ref set before enqueuing maintenance."
            )
            raise RuntimeError(msg)
        step_ref = self.add_step(
            VectorIndexMaintenanceIntent(
                ref_id=self._next_ref(),
                operation=VectorIndexMaintenanceOperation.REBUILD,
                model_cls=model_cls,
                object_id=ServerRefs.scalar(SysId.new()),
                index=SqlIndexName(index),
                after_refs=frozenset(),
                backend_kind=backend_kind_override,
            ),
        )
        return step_ref.ref_id

    def _init_rtt_audit(self: BaseServerPlan, *, mode: str) -> None:
        steps: dict[str, ServerPlanStepRttAudit] = {}
        for step in self._steps:
            step_type_name = type(step).__name__
            step_type = StepType(step_type_name) if step_type_name in StepType._value2member_map_ else StepType.GRAMMAR_EXECUTE
            rw = "READ" if step.is_read_only() else "WRITE"
            steps[step.ref_id] = ServerPlanStepRttAudit(
                ref_id=step.ref_id,
                step_type=step_type,
                rw=rw,
                round_trips=0,
            )
        self._last_rtt_audit = ServerPlanRttAudit(
            mode=mode,
            total_round_trips=0,
            driver_round_trips=0,
            portable_min_db_statements=0,
            backend_attainable_min_db_statements=0,
            actual_db_statements_executed=0,
            by_operation_kind={},
            by_rw={},
            steps=steps,
        )

    def _record_rtt(
        self: BaseServerPlan,
        *,
        operation_kind: str,
        rw: str,
        step_ref_id: str | None = None,
    ) -> None:
        """Record a single backend round-trip, without inspecting SQL."""
        if self._last_rtt_audit is None:
            return

        by_operation_kind = dict(self._last_rtt_audit.by_operation_kind)
        by_operation_kind[operation_kind] = by_operation_kind.get(operation_kind, 0) + 1

        by_rw = dict(self._last_rtt_audit.by_rw)
        by_rw[rw] = by_rw.get(rw, 0) + 1

        steps = dict(self._last_rtt_audit.steps)
        if step_ref_id is not None and step_ref_id in steps:
            prev = steps[step_ref_id]
            steps[step_ref_id] = ServerPlanStepRttAudit(
                ref_id=prev.ref_id,
                step_type=prev.step_type,
                rw=prev.rw,
                round_trips=prev.round_trips + 1,
            )

        self._last_rtt_audit = ServerPlanRttAudit(
            mode=self._last_rtt_audit.mode,
            total_round_trips=self._last_rtt_audit.total_round_trips + 1,
            driver_round_trips=self._last_rtt_audit.driver_round_trips + 1,
            portable_min_db_statements=self._last_rtt_audit.portable_min_db_statements + 1,
            backend_attainable_min_db_statements=self._last_rtt_audit.backend_attainable_min_db_statements + 1,
            actual_db_statements_executed=self._last_rtt_audit.actual_db_statements_executed + 1,
            by_operation_kind=by_operation_kind,
            by_rw=by_rw,
            steps=steps,
        )

    def select_many[T: DatabaseObjectRow](
        self: BaseServerPlan,
        model_cls: type[T],
        ids: Sequence[SysId] | ScalarSequenceServerRef[SysId],
    ) -> ObjectSequenceServerRef[T]:
        """Queue a multi-select operation."""
        from impl.common.l2070_server_plan.steps.intent_query import SelectManyIntent

        ref_id = self._next_ref()
        ctx = LazyBuilderContext(self)
        ids_ref = (
            ids
            if isinstance(ids, ScalarSequenceServerRef)
            else cast(
                ScalarSequenceServerRef[SysId],
                ctx.ref_for(tuple(ids), variant="scalar_sequence", type_hint=SysId),
            )
        )
        step = SelectManyIntent(ref_id, model_cls, ids_ref)
        return self._add_server_step(step, model_cls, variant="object_sequence")

