    def traverse_out[N: DatabaseObjectRow](
        self: BaseServerPlan,
        graph_id: SysId,
        start_node_id: SysId,
        node_type: type[N],
        edge_type: type[DatabaseObjectRow[SysId]],
        graph_type: type[DatabaseObjectRow[SysId]],
        max_depth: int = 1,
    ) -> GraphTraversalBuilder[N]:
        """Queue a graph traversal following outgoing edges."""
        revision_id, revision_ref_id = _graph_traversal_revision_prerequisite(
            self._txn_for_graph_traversal(),
        )
        return BaseGraphTraversalBuilder(
            plan=self,
            graph_id=graph_id,
            revision_id=revision_id,
            revision_ref_id=revision_ref_id,
            start_node_id=start_node_id,
            start_node_ref=None,
            start_node_ids_ref=None,
            node_type=node_type,
            edge_type=edge_type,
            graph_type=graph_type,
            direction="out",
            max_depth=max_depth,
        )

