            self._txn_for_graph_traversal(),
        )
        return BaseGraphTraversalBuilder(
            plan=self,
            graph_id=graph_id,
            revision_id=revision_id,
            revision_ref_id=revision_ref_id,
            start_node_id=None,
            start_node_ref=start_node_ref,
            start_node_ids_ref=None,
            node_type=node_type,
            edge_type=edge_type,
            graph_type=graph_type,
            direction="out",
            max_depth=max_depth,
        )

    def traverse_in_from_ref[N: DatabaseObjectRow](
        self: BaseServerPlan,
        graph_id: SysId,
        start_node_ref: ScalarServerRef[SysId],
