    # Cache generation operations

    def load_cache_generations(
        self: BaseServerPlan,
        tags: Sequence[str],
    ) -> ScalarServerRef[dict[str, int]]:
        """Load generation counters for the specified tags."""
        from impl.common.l2070_server_plan.steps.cache_steps import (
            CacheMissingGenerationMode,
            CacheTag,
            LoadLiteralCacheGenerationsStep,
        )

        ref_id = self._next_ref()
        step = LoadLiteralCacheGenerationsStep(
            ref_id,
            tags=tuple(CacheTag(tag) for tag in tags),
            fill_mode=CacheMissingGenerationMode.FILL_MISSING,
        )
        return cast(
            "ScalarServerRef[dict[str, int]]",
            self._add_server_step(step, dict, variant="scalar"),
        )

    # Cross-branch queries

    def query_cross_branch(
        self: BaseServerPlan,
        cross_branch_spec: CrossBranchQuerySpec,
    ) -> ObjectSequenceServerRef[Any]:
        """Queue a cross-branch query (including FTS).

        Cross-branch queries search across all branch tips in a workspace.
        This includes FTS (full-text search) when fts_query is set in the spec.

        Args:
            cross_branch_spec: CrossBranchQuerySpec with query configuration

        Returns:
            ServerRef to the list of results
        """
        from impl.common.l2070_server_plan.steps.cross_branch import (
            CrossBranchExecuteStep,
            _CrossBranchExecuteConfig,
        )

        if cross_branch_spec.versioning_domain is None:
            model_domain = next(
                (
                    cls.__dict__["__versioning_domain__"]
                    for cls in cross_branch_spec.model_cls.__mro__
                    if "__versioning_domain__" in cls.__dict__
                ),
                None,
            )
            if model_domain is not None:
                cross_branch_spec = replace(
                    cross_branch_spec,
                    versioning_domain=model_domain,
                )

        ref_id = self._next_ref()
        step = CrossBranchExecuteStep(
            ref_id,
            cross_branch_spec.model_cls,
            branch_spec=cross_branch_spec,
            config=_CrossBranchExecuteConfig(),
        )
        return self._add_server_step(step, cross_branch_spec.model_cls, variant="object_sequence")

    # Result management

    def return_result(
        self: BaseServerPlan,
        name: str,
        ref: ServerRef[Any],
    ) -> None:
        """Mark a server-side reference to be returned to the client.

        Args:
            name: Name for the result (must be non-empty and unique)
            ref: ServerRef to return

        Raises:
            ValueError: If name is empty, already used, or ref is invalid
        """
        if not name or not name.strip():
            msg = "return_result name cannot be empty"
            raise ValueError(msg)
        # Validate ServerRef references an existing step
        ref_id = ref.ref_id
        if ref_id is None:
            msg = "ServerRef has no ref_id"
            raise ValueError(msg)
        existing_ref_id = self._returns.get(name)
        if existing_ref_id is not None:
            existing_variant = self._return_variants.get(name)
            if existing_ref_id == ref_id and (existing_variant is None or existing_variant == ref.variant):
                self._return_variants.setdefault(name, ref.variant)
                type_hint = ref._type_hint
                if isinstance(type_hint, type):
                    self._return_type_hints.setdefault(name, type_hint)
                return
            msg = f"Duplicate return_result name: '{name}' is already bound to '{existing_ref_id}', not '{ref_id}'."
            raise ValueError(msg)
        base_ref = prerequisite_base_ref_id(ServerPlanRefId(ref_id))
        if base_ref not in self.owned_step_ref_ids():
            msg = f"ServerRef '{ref_id}' references non-existent step or seed '{base_ref}'. Add the producer before returning it."
            raise ValueError(msg)
        self._returns[name] = ref_id
        if str(ref_id) == base_ref and not name.startswith(("__internal_", "__prereq_")):
            self._semantic_plan_builder.add_return(name, ServerPlanRefId(ref_id))
        self._return_variants[name] = ref.variant
        type_hint = ref._type_hint
        if isinstance(type_hint, type):
            self._return_type_hints[name] = type_hint

    def returned_ref_bindings(self: BaseServerPlan) -> tuple[tuple[str, ServerPlanRefId], ...]:
        """Return immutable named publication bindings for template compilation."""
        return tuple((name, ServerPlanRefId(ref_id)) for name, ref_id in self._returns.items())

    def bind_session_id(self: BaseServerPlan, session_id: SessionId | None) -> None:
        """Bind a concrete request session or clear symbolic physical identity."""
        self._session_id = session_id

    def physical_template_environment(
        self: BaseServerPlan,
        *,
        excluded_seed_prefixes: Sequence[str],
        include_seed_values: bool,
    ) -> PhysicalTemplateEnvironment:
        """Return immutable physical-template identity owned by this plan."""
        excluded_seed_prefixes = tuple(excluded_seed_prefixes)
        profile = self._backend_profile
        traits = profile.traits
        structural = repr(
            (
                traits.backend_type.value,
                type(traits.dialect).__qualname__,
                traits.batch_execution_mode.value,
                traits.reads_observe_prior_writes_within_batch,
                traits.supports_data_modifying_ctes,
                traits.has_native_fts,
                traits.has_database_triggers,
                traits.has_returning_clause,
                traits.fts_mode.value,
                traits.vector_mode.value,
                traits.versioning_mode.value,
                traits.eventing_mode.value,
                traits.sql_list_transport.value,
                traits.runtime_list_max_items,
                traits.runtime_list_max_payload_bytes,
                tuple(sorted(capability.value for capability in profile.capabilities)),
                tuple(f"{type(strategy).__module__}.{type(strategy).__qualname__}" for strategy in profile.batching_strategies),
            ),
        )
        seeded = tuple(
            sorted(
                (
                    str(ref_id),
                    type(value).__module__,
                    type(value).__qualname__,
                    repr(value) if include_seed_values else None,
                )
                for ref_id, value in self.seeded_constants.items()
                if not str(ref_id).startswith(excluded_seed_prefixes)
            ),
        )
        return PhysicalTemplateEnvironment(
            structural_fingerprint=structural,
            seeded_fingerprint=seeded,
            session_id=self._session_id,
        )

    # Execution

    def _create_backend_executor(self: BaseServerPlan, is_write: bool) -> BackendExecutor:
        """Create the backend executor for pipeline execution.

        Subclasses or backend-specific plans can override to use a
        specialized executor (e.g., SqliteBackendExecutor).
        """
        from impl.common.l2070_server_plan.backend_profiles import (
            create_backend_executor_for_profile,
        )

        if isinstance(self._txn, _BackendExecutorProvider):
            executor = self._txn._backend_executor_for_plan(
                is_write_transaction=is_write,
                session_id=self._session_id,
            )
            if executor is not None:
                return executor

        return create_backend_executor_for_profile(
            self._txn,
            profile=self._backend_profile,
            is_write_transaction=is_write,
            session_id=self._session_id,
        )

    def _prepare_pipeline_execution(
        self: BaseServerPlan,
    ) -> tuple[BackendExecutor, LoweringContext, list[PlanOptimizer], Hydrator]:
        """Shared setup for sync/async pipeline execution."""
        from l2070_batching.hydrator import ModelHydrator

        include_staged_working_set = bool(
            self._versioned_read_context_binding is not None and self._versioned_read_context_binding.include_staged_working_set
        )
        is_write: bool = self._has_write_step or include_staged_working_set
        executor = self._create_backend_executor(is_write)
        executor_lowering_ctx = executor.get_lowering_context()
        lowering_ctx: LoweringContext = replace(
            executor_lowering_ctx,
            auto_api_hook_registry=self._auto_api_hook_registry,
            owner_plan=self,
            is_write_transaction=(is_write or isinstance(self._txn, VersionedWritePlanTarget)),
            is_versioned=(
                _is_versioned_transaction_plan_target(self._txn)
                or self._versioned_read_context_binding is not None
                or self._explicit_versioning_domain is not None
            ),
            versioning_domain=(self._explicit_versioning_domain or executor_lowering_ctx.versioning_domain),
        )
        if self._versioned_read_context_binding is not None:
            binding = self._versioned_read_context_binding
            lowering_ctx = replace(
                lowering_ctx,
                branch_table=binding.branch_table or lowering_ctx.branch_table,
                versioning_domain=binding.versioning_domain or lowering_ctx.versioning_domain,
                prefer_tip_strategy=binding.prefer_tip_strategy,
                prefer_tip_merged=binding.prefer_tip_merged,
                lazy_branch_tip_materialization=(
                    lowering_ctx.lazy_branch_tip_materialization
                    if binding.revision_id == "current"
                    else binding.tip_materialization_server_ref()
                ),
                branch_tip_materialized=(lowering_ctx.branch_tip_materialized if binding.revision_id == "current" else False),
            )
            if binding.revision_id is not None:
                lowering_ctx = replace(lowering_ctx, explicit_revision_id=binding.revision_id)
            if binding.tip_materialization is not None:
                from l7000_versioned_schema.versioned_schema import BranchTipMaterialization

                lowering_ctx = replace(
                    lowering_ctx,
                    branch_tip_materialized=(binding.tip_materialization is BranchTipMaterialization.MATERIALIZED),
                )
            revision_ref = binding.revision_server_ref()
            if revision_ref is not None:
                lowering_ctx = replace(lowering_ctx, lazy_revision=revision_ref)
            branch_ref = binding.branch_server_ref()
            if branch_ref is not None:
                lowering_ctx = replace(lowering_ctx, lazy_branch=branch_ref)
            tip_materialization_ref = binding.tip_materialization_server_ref()
            if tip_materialization_ref is not None:
                lowering_ctx = replace(
                    lowering_ctx,
                    lazy_branch_tip_materialization=tip_materialization_ref,
                )
        return (
            executor,
            lowering_ctx,
            list(self._backend_profile.pass_registry.ordered_pipeline()),
            ModelHydrator(),
        )

    def _publish_final_pipeline_receipt(
        self: BaseServerPlan,
        pipeline_result: PipelineResult,
    ) -> None:
        """Replace provisional accounting with the closed native-scope receipt."""
        del self
        from l2070_batching.execution_receipt import BackendExecutionReceipt
        from l2070_batching.flush_counter import get_flush_tracker, replace_last_flush_execution_receipt

        receipt = pipeline_result.execution_receipt
        if receipt.flush_count == 0:
            return
        tracker = get_flush_tracker()
        previous = None if tracker is None or not tracker.execution_receipts else tracker.execution_receipts[-1]
        replace_last_flush_execution_receipt(
            BackendExecutionReceipt(
                driver_round_trips=receipt.flush_count,
                sql_statement_count=receipt.statement_count,
                sql_group_count=receipt.sql_group_count,
                result_set_count=0 if previous is None else previous.result_set_count,
                transaction_control_count=receipt.transaction_control_count,
                results=() if previous is None else previous.results,
            ),
        )

    def _set_pipeline_rtt_audit(
        self: BaseServerPlan,
        receipt: NativePipelineExecutionReceipt,
        *,
        portable_min_db_statements: int,
        backend_attainable_min_db_statements: int,
    ) -> None:
        """Publish typed transport accounting for a completed or failed pipeline request."""
        self._init_rtt_audit(mode="new_pipeline")
        assert self._last_rtt_audit is not None
        driver_round_trips = receipt.flush_count
        self._last_rtt_audit = ServerPlanRttAudit(
            mode="new_pipeline",
            total_round_trips=driver_round_trips,
            driver_round_trips=driver_round_trips,
            portable_min_db_statements=portable_min_db_statements,
            backend_attainable_min_db_statements=backend_attainable_min_db_statements,
            actual_db_statements_executed=receipt.statement_count,
            by_operation_kind={
                "driver_round_trip": driver_round_trips,
                "portable_min_db_statement": portable_min_db_statements,
                "backend_attainable_min_db_statement": backend_attainable_min_db_statements,
                "actual_db_statement": receipt.statement_count,
                "sql_group": receipt.sql_group_count,
                "transaction_control": receipt.transaction_control_count,
            },
            # The pipeline executor currently reports physical execution volume,
            # not a trustworthy read/write split. Leave ``by_rw`` empty instead
            # of fabricating READ-only attribution.
            by_rw={},
            steps=self._last_rtt_audit.steps,
        )

    def _set_failed_pipeline_rtt_audit(
        self: BaseServerPlan,
        error: BatchResultCompletionRequired,
    ) -> None:
        """Retain transport facts when result decoding reports a terminal failure."""
        receipt = error.pipeline_execution_receipt()
        if receipt is None:
            return
        minimum = receipt.transaction_control_count + (1 if receipt.statement_count else 0)
        self._set_pipeline_rtt_audit(
            receipt,
            portable_min_db_statements=minimum,
            backend_attainable_min_db_statements=minimum,
        )

    def _finalize_pipeline_result(self: BaseServerPlan, pipeline_result: PipelineResult) -> PlanResults:
        """Shared post-processing: RTT audit + result resolution."""
        receipt = pipeline_result.execution_receipt
        batching = pipeline_result.batching_metrics
        self._set_pipeline_rtt_audit(
            receipt,
            portable_min_db_statements=(batching.portable_min_db_statements + receipt.transaction_control_count),
            backend_attainable_min_db_statements=(batching.backend_attainable_min_db_statements + receipt.transaction_control_count),
        )
        return self._resolve_returns(pipeline_result.resolved)

    def _resolve_returns[ResolvedItemT](self: BaseServerPlan, resolved: dict[str, ResolvedItemT]) -> PlanResults:
        """Map named returns to resolved values, handling dotted attribute paths."""
        results: dict[str, Any] = {}
        normalized_raw_terminal_ref_ids = frozenset(str(step.ref_id) for step in self._steps if step.normalizes_raw_terminal_transport())

        def _shape_return_value(name: str, value: Any) -> Any:
            search_meta_columns = {
                "_fts_rank",
                "__fts_rank",
                "_vector_score",
                "__vector_score",
                "_rrf_score",
                "__rrf_score",
                "__fts_rrf_rank",
                "__vector_rrf_rank",
            }

            def _object_row_payload(item: Mapping[str, object]) -> dict[str, object]:
                return {key: val for key, val in item.items() if key not in search_meta_columns}

            def _normalize_raw_transport(item: object) -> object:
                if isinstance(item, Mapping):
                    return {str(key): _normalize_raw_transport(value) for key, value in item.items()}
                if isinstance(item, list):
                    return [_normalize_raw_transport(value) for value in item]
                if isinstance(item, tuple):
                    return tuple(_normalize_raw_transport(value) for value in item)
                if isinstance(item, UUID):
                    return str(item)
                if isinstance(item, datetime | date | time):
                    return item.isoformat()
                if isinstance(item, Decimal):
                    return int(item) if item == item.to_integral_value() else float(item)
                return item

            def _tuple_or_none(item: object) -> tuple[object, ...] | None:
                if item is None:
                    return None
                if isinstance(item, tuple):
                    return item
                if isinstance(item, list):
                    return tuple(item)
                return (item,)

            def _cursor_token_or_none(item: object) -> Any:
                from l1400_types import CursorToken

                if item is None or isinstance(item, CursorToken):
                    return item
                if isinstance(item, str):
                    return CursorToken(item)
                msg = f"Cursor page cursor must be str, CursorToken, or None; got {type(item).__name__}"
                raise TypeError(msg)

            def _shape_page_mapping(
                page: Mapping[str, object],
                type_hint: type[Any],
            ) -> Any:
                from impl.common.l5200_sql_query.row_converter import convert_row_to_model
                from l1400_types import CursorPage, KeysetPage

                page_results = page.get("results")
                if not isinstance(page_results, list):
                    return page
                hydrated_results = [
                    convert_row_to_model(
                        type_hint,
                        _object_row_payload(item),
                    )
                    if isinstance(item, Mapping)
                    else item
                    for item in page_results
                ]
                if "next_key" in page:
                    return KeysetPage(
                        results=hydrated_results,
                        next_key=_tuple_or_none(page.get("next_key")),
                        has_more=bool(page.get("has_more")),
                    )
                if "cursor" in page:
                    return CursorPage(
                        results=hydrated_results,
                        cursor=_cursor_token_or_none(page.get("cursor")),
                        has_more=bool(page.get("has_more")),
                    )
                return page

            variant = self._return_variants.get(name)
            if variant == "object":
                while isinstance(value, list):
                    if not value:
                        value = None
                        break
                    value = value[0]
            if variant in {"object_sequence", "scalar_sequence"} and not isinstance(value, list):
                value = [value]
            return_ref = self._returns.get(name)
            if return_ref in normalized_raw_terminal_ref_ids:
                return _normalize_raw_transport(value)
            if variant == "object_sequence" and isinstance(value, list):
                type_hint = self._return_type_hints.get(name)
                if type_hint is not None:
                    if type_hint is dict:
                        return [_normalize_raw_transport(item) for item in value]
                    from impl.common.l5200_sql_query.row_converter import convert_row_to_model

                    return [
                        convert_row_to_model(
                            type_hint,
                            dict(item),
                            select_columns=[str(column_name) for column_name in item],
                        )
                        if isinstance(item, Mapping)
                        else item
                        for item in value
                    ]
            if variant == "object" and isinstance(value, Mapping):
                type_hint = self._return_type_hints.get(name)
                if type_hint is not None:
                    if type_hint is dict:
                        normalized = _normalize_raw_transport(value)
                        assert isinstance(normalized, dict)
                        return normalized
                    from impl.common.l5200_sql_query.row_converter import convert_row_to_model

                    return convert_row_to_model(
                        type_hint,
                        _object_row_payload(value),
                        select_columns=[str(column_name) for column_name in value],
                    )
            if (
                variant == "object_sequence"
                and isinstance(value, list)
                and len(value) == 1
                and isinstance(value[0], Mapping)
                and "results" in value[0]
                and ("next_key" in value[0] or "cursor" in value[0])
            ):
                type_hint = self._return_type_hints.get(name)
                if type_hint is not None:
                    return _shape_page_mapping(value[0], type_hint)
            if variant == "object_sequence" and isinstance(value, list):
                type_hint = self._return_type_hints.get(name)
                if type_hint is not None:
                    if type_hint is dict:
                        return [_normalize_raw_transport(item) for item in value]
                    from impl.common.l5200_sql_query.row_converter import convert_row_to_model

                    return [
                        convert_row_to_model(
                            type_hint,
                            _object_row_payload(item),
                            select_columns=[str(column_name) for column_name in item if column_name not in search_meta_columns],
                        )
                        if isinstance(item, Mapping)
                        else item
                        for item in value
                    ]
            if variant == "object" and isinstance(value, Mapping):
                type_hint = self._return_type_hints.get(name)
                if type_hint is not None:
                    if type_hint is dict:
                        normalized = _normalize_raw_transport(value)
                        assert isinstance(normalized, dict)
                        return normalized
                    from impl.common.l5200_sql_query.row_converter import convert_row_to_model

                    payload = _object_row_payload(value)
                    return convert_row_to_model(
                        type_hint,
                        payload,
                        select_columns=[str(column_name) for column_name in payload],
                    )
            from l1400_types import CursorPage, KeysetPage

            type_hint = self._return_type_hints.get(name)
            if (
                type_hint is not None
                and not issubclass(type_hint, BaseModel)
                and value is not None
                and not isinstance(value, Mapping | list | KeysetPage | CursorPage)
                and not isinstance(value, type_hint)
            ):
                from pydantic import TypeAdapter

                return TypeAdapter(type_hint).validate_python(value)
            if variant == "object_sequence" and isinstance(value, KeysetPage | CursorPage):
                type_hint = self._return_type_hints.get(name)
                if type_hint is not None:
                    from impl.common.l5200_sql_query.row_converter import convert_row_to_model

                    page_results = value.results
                    hydrated_results = [
                        convert_row_to_model(
                            type_hint,
                            _object_row_payload(item),
                            select_columns=[str(column_name) for column_name in item],
                        )
                        if isinstance(item, Mapping)
                        else item
                        for item in page_results
                    ]
                    if isinstance(value, KeysetPage):
                        return KeysetPage(
                            results=hydrated_results,
                            next_key=value.next_key,
                            has_more=value.has_more,
                        )
                    if isinstance(value, CursorPage):
                        return CursorPage(
                            results=hydrated_results,
                            cursor=value.cursor,
                            has_more=value.has_more,
                        )
            return value

        def _resolve_dotted_return(ref_id: ServerPlanRefId) -> Any:
            base, *attrs = ref_id.split(".")
            if base not in resolved:
                return None
            val: Any = resolved[base]
            for attr in attrs:

                def _get_attr_or_key(item: Any) -> Any:
                    if isinstance(item, Mapping):
                        if attr not in item:
                            raise AttributeError(attr)
                        return item[attr]
                    try:
                        getter = attrgetter(attr)
                        return getter(item)
                    except AttributeError:
                        raise AttributeError(attr)

                val = [_get_attr_or_key(item) for item in val] if isinstance(val, list) else _get_attr_or_key(val)
                if isinstance(val, list):
                    val = [x() if callable(x) and not isinstance(x, type) else x for x in val]
                elif callable(val) and not isinstance(val, type):
                    val = val()
            return val

        from l1000_schema.schema_def import DatabaseObjectRow

        commit_branch_ref = self._returns.get("__commit_branch__")
        published_revision_id: Any = resolved.get(commit_branch_ref) if commit_branch_ref is not None else None
        if published_revision_id is None:
            published_revision_id = next(
                (
                    value
                    for ref_id, value in reversed(tuple(resolved.items()))
                    if ref_id.endswith(".new_revision_id") and value is not None
                ),
                None,
            )

        if published_revision_id is None:
            from impl.common.l2070_server_plan.steps.versioning_intent_steps import (
                VersionedReadCtx,
            )

            published_revision_id = next(
                (value.revision_id for value in reversed(tuple(resolved.values())) if isinstance(value, VersionedReadCtx)),
                None,
            )

        def _attach_published_revision(value: Any) -> Any:
            if published_revision_id is None:
                return value
            if isinstance(value, DatabaseObjectRow):
                if "revision_id" in value.__class__.model_fields and value.__dict__.get("revision_id") is None:
                    return value.model_copy(update={"revision_id": published_revision_id})
                return value
            if isinstance(value, list):
                return [_attach_published_revision(item) for item in value]
            return value

        for name, ref_id in self._returns.items():
            if ref_id in resolved:
                value = resolved[ref_id]
                if isinstance(value, ServerRef) and "." in ref_id:
                    dotted_value = _resolve_dotted_return(ServerPlanRefId(ref_id))
                    if dotted_value is not None:
                        value = dotted_value
                shaped_value = _shape_return_value(name, value)
                results[name] = shaped_value if name.startswith("__") else _attach_published_revision(shaped_value)
            elif "." in ref_id:
                val = _resolve_dotted_return(ServerPlanRefId(ref_id))
                if val is not None:
                    shaped_value = _shape_return_value(name, val)
                    results[name] = shaped_value if name.startswith("__") else _attach_published_revision(shaped_value)
        return PlanResults(results)

    def _build_initial_resolved_from_seeded_constants(
        self: BaseServerPlan,
    ) -> dict[str, Any]:
        """Materialise ``plan.seeded_constants`` into the ``ResolvedRefs`` seed.

        Per #2372 §3.4, step-level code must not access ``seeded_constants``
        directly; the executor bridges them into ``resolved`` once at pipeline
        start so preprocess / post-process read them through the same surface
        as runtime-produced step results.
        """
        return {str(ref_id): value for ref_id, value in self.seeded_constants.items()}

    def _build_initial_seed_sql_hints(self: BaseServerPlan) -> dict[str, SqlColumnTypeHints]:
        """Producer-declared SQL hints accompanying the initial resolved seed."""
        return self.seeded_constants.declared_sql_hints_snapshot()

    def _execute_new_pipeline(self: BaseServerPlan) -> PlanResults:
        """Execute via the new ServerPlanStep pipeline.

        Sync variant: delegates to the shared pipeline runner, translating
        executor-level exceptions back into their original errors. The
        sync/async dispatch split here is intentional (async cannot call
        ``run_pipeline``; sync cannot ``await run_pipeline_async``) but the
        body is kept to the minimum so SPQ-001 sees it as a thin wrapper.
        """
        from l2070_batching.executor import run_executable_pipeline

        with self._translate_pipeline_errors():
            with seeded_constants_scope(cast("Mapping[str, Any]", self.seeded_constants)):
                (
                    executable_plan,
                    backend,
                    pipeline,
                    hydrator,
                    lowering_ctx,
                    initial_resolved,
                    runtime_services,
                    initial_seed_sql_hints,
                ) = self._pipeline_runner_args()
                try:
                    pipeline_result = run_executable_pipeline(
                        executable_plan,
                        backend,
                        tuple(pipeline),
                        hydrator,
                        lowering_ctx,
                        initial_resolved,
                        runtime_services,
                        initial_seed_sql_hints=initial_seed_sql_hints,
                    )
                except BatchResultCompletionRequired as error:
                    self._set_failed_pipeline_rtt_audit(error)
                    raise
                except Exception:
                    receipt = backend.native_pipeline_execution_receipt(None, sql_group_count=0)
                    minimum = receipt.transaction_control_count + (1 if receipt.statement_count else 0)
                    self._set_pipeline_rtt_audit(
                        receipt,
                        portable_min_db_statements=minimum,
                        backend_attainable_min_db_statements=minimum,
                    )
                    raise
                pipeline_result = replace(
                    pipeline_result,
                    execution_receipt=backend.native_pipeline_execution_receipt(
                        pipeline_result.accounting,
                        sql_group_count=pipeline_result.execution_receipt.sql_group_count,
                    ),
                )
                self._publish_final_pipeline_receipt(pipeline_result)
                return self._finalize_pipeline_result(pipeline_result)

    async def _execute_new_pipeline_async(self: BaseServerPlan) -> PlanResults:
        """Async variant of _execute_new_pipeline.

        Mirrors ``_execute_new_pipeline`` with ``await`` on the async runner.
        See that method's docstring for why the sync/async split is
        unavoidable at this seam.
        """
        from l2070_batching.executor import run_executable_pipeline_async

        if self._prepared_physical_execution is not None:
            resolved = await self.execute_prepared_physical_step_async(
                self._prepared_physical_execution,
            )
            assert isinstance(resolved, PipelineResult)
            self._publish_final_pipeline_receipt(resolved)
            return self._finalize_pipeline_result(resolved)

        with self._translate_pipeline_errors():
            with seeded_constants_scope(cast("Mapping[str, Any]", self.seeded_constants)):
                (
                    executable_plan,
                    backend,
                    pipeline,
                    hydrator,
                    lowering_ctx,
                    initial_resolved,
                    runtime_services,
                    initial_seed_sql_hints,
                ) = self._pipeline_runner_args()
                failed_error: Exception | None = None
                try:
                    pipeline_result = await run_executable_pipeline_async(
                        executable_plan,
                        backend,
                        tuple(pipeline),
                        hydrator,
                        lowering_ctx,
                        initial_resolved,
                        runtime_services,
                        initial_seed_sql_hints=initial_seed_sql_hints,
                    )
                except Exception as error:
                    failed_error = error
                    raise
                finally:
                    if isinstance(failed_error, BatchResultCompletionRequired):
                        self._set_failed_pipeline_rtt_audit(failed_error)
                    elif failed_error is not None:
                        receipt = backend.native_pipeline_execution_receipt(None, sql_group_count=0)
                        minimum = receipt.transaction_control_count + (1 if receipt.statement_count else 0)
                        self._set_pipeline_rtt_audit(
                            receipt,
                            portable_min_db_statements=minimum,
                            backend_attainable_min_db_statements=minimum,
                        )
                pipeline_result = replace(
                    pipeline_result,
                    execution_receipt=backend.native_pipeline_execution_receipt(
                        pipeline_result.accounting,
                        sql_group_count=pipeline_result.execution_receipt.sql_group_count,
                    ),
                )
                self._publish_final_pipeline_receipt(pipeline_result)
                return self._finalize_pipeline_result(pipeline_result)

    async def execute_prepared_physical_step_async(
        self: BaseServerPlan,
        compiled: object,
    ) -> object:
        """Execute one already-lowered, already-compiled physical batch."""
        from l2070_batching.compilation import CompiledStep
        from l2070_batching.executor import PipelineResult, PlanExecutor, PreparedPhysicalProgram
        from l2070_batching.flush_counter import record_flush

        if not isinstance(compiled, CompiledStep | PreparedPhysicalProgram):
            raise TypeError("Prepared physical execution requires CompiledStep or PreparedPhysicalProgram")
        (
            _steps,
            backend,
            _pipeline,
            hydrator,
            _lowering_ctx,
            initial_resolved,
            runtime_services,
            _initial_seed_sql_hints,
        ) = self._pipeline_runner_args()
        executor = PlanExecutor(
            backend,
            hydrator,
            runtime_services=runtime_services,
            lowering_context=_lowering_ctx,
        )
        with seeded_constants_scope(cast("Mapping[str, Any]", self.seeded_constants)):
            resolved = await executor.execute_prepared_physical_async(
                compiled,
                initial_resolved,
            )
        accounting = executor.last_accounting()
        flush_label = "prepared physical template"
        if isinstance(compiled, PreparedPhysicalProgram):
            step_types = tuple(type(step).__name__ for step in compiled.optimized_steps)
            if "DatabaseCommitAfterDepsStep" in step_types:
                flush_label = f"{flush_label}: DatabaseCommitAfterDepsStep"
        execution_receipt = executor.native_pipeline_execution_receipt(sql_group_count=1)
        from l2070_batching.execution_receipt import BackendExecutionReceipt

        backend_receipt = BackendExecutionReceipt(
            driver_round_trips=execution_receipt.flush_count,
            sql_statement_count=execution_receipt.statement_count,
            sql_group_count=execution_receipt.sql_group_count,
            result_set_count=0,
            transaction_control_count=execution_receipt.transaction_control_count,
            results=(),
        )
        record_flush(
            1,
            label=flush_label,
            execution_receipt=backend_receipt,
        )
        from l2070_batching.diagnostics import PipelineDiagnosticRecord, record_pipeline_diagnostic

        batching_metrics = executor.last_batching_metrics()
        record_pipeline_diagnostic(
            PipelineDiagnosticRecord(
                input_step_count=1,
                optimized_step_count=1,
                sql_step_ir_count=execution_receipt.statement_count,
                sql_execution_group_count=execution_receipt.sql_group_count,
                input_step_summary=flush_label,
                optimized_step_summary=flush_label,
                execution_receipt=backend_receipt,
                selected_strategies=["prepared_physical_template"],
                portable_min_db_statements=batching_metrics.portable_min_db_statements,
                backend_attainable_min_db_statements=batching_metrics.backend_attainable_min_db_statements,
                actual_db_statements_executed=execution_receipt.statement_count,
                driver_round_trips=execution_receipt.flush_count,
                unfused_statements=batching_metrics.unfused_statements,
                backend_ceiling_gap=batching_metrics.backend_ceiling_gap,
                avoidable_deopt_gap=batching_metrics.avoidable_deopt_gap,
            ),
        )
        return PipelineResult(
            resolved=resolved,
            optimized_step_count=1,
            accounting=accounting,
            batching_metrics=batching_metrics,
            execution_receipt=execution_receipt,
        )

    def bind_prepared_physical_execution(
        self: BaseServerPlan,
        compiled: object,
        returns: Mapping[str, str],
        runtime_values: Mapping[str, object] | None = None,
    ) -> None:
        """Bind a cached physical program to the normal transaction boundary."""
        from l2070_batching.compilation import CompiledStep
        from l2070_batching.executor import PreparedPhysicalProgram

        if not isinstance(compiled, CompiledStep | PreparedPhysicalProgram):
            raise TypeError("Prepared physical execution requires CompiledStep or PreparedPhysicalProgram")
        self._prepared_physical_execution = compiled
        self._prepared_runtime_values = dict(runtime_values or {})
        self._returns = dict(returns)

    def _record_commit_safety_failure(self: BaseServerPlan, error: BaseException) -> None:
        from l1100_exceptions.exceptions import (
            CommitPlanningBudgetExceededError,
            ConcurrentBranchCommitInProgressError,
            StatementCapacityExceededError,
            StatementTimeoutError,
        )
        from l2070_batching.diagnostics import (
            CommitSafetyFailureOutcome,
            record_commit_safety_failure,
        )

        if not any(step.owns_database_commit() for step in self._steps):
            return
        if isinstance(error, CommitPlanningBudgetExceededError):
            outcome = CommitSafetyFailureOutcome.PLANNING_REJECTION
        elif isinstance(error, StatementCapacityExceededError):
            outcome = CommitSafetyFailureOutcome.HARD_LIMIT_REJECTION
        elif isinstance(error, ConcurrentBranchCommitInProgressError):
            outcome = CommitSafetyFailureOutcome.ADMISSION_REJECTION
        elif isinstance(error, StatementTimeoutError):
            outcome = CommitSafetyFailureOutcome.STATEMENT_TIMEOUT
        else:
            return
        record_commit_safety_failure(outcome)

    @contextmanager
    def _translate_pipeline_errors(self: BaseServerPlan) -> Generator[None]:
        """Translate ``StepExecutionError`` / ``BatchExecutionError`` back to
        their original errors so callers see API-layer exceptions rather than
        executor-internal wrappers."""
        from l2070_batching.optimizer_diagnostics import (
            build_optimizer_internal_error,
            is_optimizer_internal_failure,
        )

        # The session-table translation runs before the optimizer-internal
        # classification in both branches. The failing statement is
        # optimizer-generated, so it would otherwise be reported as an internal
        # planner defect, when in fact the database is simply missing the table
        # every session must be looked up in -- a condition the caller can act
        # on and the planner cannot.
        try:
            yield
        except (StepExecutionError, BatchExecutionError) as e:
            original = e.original_error
            self._record_commit_safety_failure(original)
            if isinstance(original, BatchResultCompletionRequired):
                self._set_failed_pipeline_rtt_audit(original)
            wrapper_cause = None if e.__cause__ is original else e.__cause__
            if _is_schema_transaction_plan_target(self._txn) and isinstance(original, DatabaseError):
                raise original from wrapper_cause
            self._reraise_missing_session_table_as_validation_failure(original)
            if is_optimizer_internal_failure(
                original,
                include_declared_missing_relations=self._requires_declared_missing_relation_diagnostics(),
            ):
                raise build_optimizer_internal_error(self, original) from original
            raise original from wrapper_cause
        except AssertionError as e:
            raise build_optimizer_internal_error(self, e) from e
        except Exception as e:
            self._record_commit_safety_failure(e)
            if isinstance(e, BatchResultCompletionRequired):
                self._set_failed_pipeline_rtt_audit(e)
            self._reraise_missing_session_table_as_validation_failure(e)
            if is_optimizer_internal_failure(
                e,
                include_declared_missing_relations=self._requires_declared_missing_relation_diagnostics(),
            ):
                raise build_optimizer_internal_error(self, e) from e
            raise

    def _requires_declared_missing_relation_diagnostics(self: BaseServerPlan) -> bool:
        """Keep diagnostics when a read-only database lacks application schema."""
        connection = _plan_target_attr(self._txn, "_conn")
        return isinstance(connection, _ReadOnlyConnection) and connection.read_only is True

    def _reraise_missing_session_table_as_validation_failure(
        self: BaseServerPlan,
        original: BaseException,
    ) -> None:
        """Report an absent session table as a session failure, not a SQL failure.

        Session validation happens inside the plan, so when ``sys_sessions``
        does not exist the caller would otherwise see the backend's "no such
        table" error. That is accurate and useless: the caller asked to act
        under a session, and what they need to know is that the session could
        not be established. Translating here rather than in one backend's
        transaction entry keeps the diagnosis identical across backends, which
        is the reason session validation is a plan step in the first place.

        Only the schema bootstrap identity is exempt. An absent session table
        during schema bootstrap is a schema problem, and relabelling it would
        hide the real cause. Every other identity requires storage validation.
        """
        from l1100_exceptions.exceptions import TableNotFoundError
        from l1100_exceptions.security import SessionValidationError
        from l1300_session.session import Session
        from l1000_schema.table_utils import get_table_name

        if not isinstance(original, TableNotFoundError):
            return
        session_id = self._session_id
        if session_id is None or session_id.is_schema_session():
            return
        table_name = get_table_name(Session)
        if table_name not in str(original):
            return
        raise SessionValidationError(
            f"{table_name} does not exist",
            session_id=session_id,
            reason="not_found",
        ) from original

    def _compile_semantic_execution_input(self: BaseServerPlan) -> ExecutablePlan:
        """Freeze, authorize, and compile the active semantic generation."""
        semantic_plan = self._semantic_plan_builder.freeze()
        authority = system_authority_for_plan_target(self._txn)
        if authority is not None:
            from l1300_session.system_authority_service import (
                SystemAuthorityError,
                ValidatedSystemAuthority,
            )

            if not isinstance(authority, ValidatedSystemAuthority):
                raise SystemAuthorityError(
                    f"Unsupported validated system authority type: {type(authority).__name__}",
                )
            from l2070_batching.semantic_plan import (
                authority_application_fingerprint,
                authority_preissuance_fingerprint,
            )

            expected = str(authority.scope.semantic_plan_digest)
            if expected.startswith("preissuance-v1:"):
                actual = "preissuance-v1:" + authority_preissuance_fingerprint(
                    semantic_plan,
                    excluded_ref_ids=authority.infrastructure_ref_ids,
                )
            else:
                actual = authority_application_fingerprint(
                    semantic_plan,
                    excluded_ref_ids=authority.infrastructure_ref_ids,
                )
            if actual != expected:
                raise SystemAuthorityError(
                    f"System authority semantic plan binding does not match the executed plan: expected {expected!r}, got {actual!r}.",
                )
        return compile_semantic_plan(
            semantic_plan,
            backend_profile=self._backend_profile,
        )

    def _pipeline_runner_args(
        self: BaseServerPlan,
    ) -> tuple[
        ExecutablePlan,
        BackendExecutor,
        Sequence[PlanOptimizer],
        Hydrator[Any],
        LoweringContext,
        dict[str, Any],
        ServerPlanRuntimeServices,
        dict[str, SqlColumnTypeHints],
    ]:
        """Build the argument tuple for the pipeline runner (sync and async).

        Splitting preparation out of ``_execute_new_pipeline{,_async}`` keeps
        both dispatchers at the same small statement count, which SPQ-001
        treats as thin wrappers rather than duplicated sync/async bodies.
        """
        executable_plan = self._compile_semantic_execution_input()
        backend, lowering_ctx, pipeline, hydrator = self._prepare_pipeline_execution()
        initial_resolved = self._build_initial_resolved_from_seeded_constants()
        initial_resolved.update(self._prepared_runtime_values)
        runtime_services = self._runtime_services
        if runtime_services.auto_api_hook_registry is None and self._captured_hook_runtime_services.auto_api_hook_registry is not None:
            runtime_services = self._captured_hook_runtime_services
        return (
            executable_plan,
            backend,
            pipeline,
            hydrator,
            lowering_ctx,
            initial_resolved,
            runtime_services,
            self._build_initial_seed_sql_hints(),
        )

    def _check_transaction_active(self: BaseServerPlan) -> None:
        """Raise RuntimeError if the transaction is no longer active."""
        txn = self._txn
        if _is_read_or_write_transaction(txn):
            txn._check_active()
        elif _is_versioned_transaction_plan_target(txn):
            txn._check_active()

    def mark_terminal_lifecycle_selected(self: BaseServerPlan) -> None:
        """Record that this plan owns its transaction's terminal lifecycle."""
        self._terminal_lifecycle_selected = True

    def _check_transaction_executable(self: BaseServerPlan) -> None:
        """Permit execution of this plan's already-selected terminal lifecycle."""
        txn = self._txn
        if _is_versioned_transaction_plan_target(txn) and self._terminal_lifecycle_selected and (txn.is_committed or txn.is_rolled_back):
            return
        self._check_transaction_active()

    @contextmanager
    def _execution_scope(self: BaseServerPlan, *, sink: str) -> Generator[None]:
        from impl.common.l2070_server_plan.execution_context import _enter_step_execution
        from impl.common.l2070_server_plan.plan_lifecycle import active_plan_scope
        from l2055_lazy_result.purity import (
            assert_imperative_execution_allowed,
            assert_no_eager_terminal_in_lazy_context,
        )

        assert_no_eager_terminal_in_lazy_context(operation=sink, is_pending=True)
        assert_imperative_execution_allowed(sink=sink, is_pending=True)
        with active_plan_scope(self), _enter_step_execution():
            yield

    def owned_step_ref_ids(self: BaseServerPlan) -> frozenset[ServerPlanRefId]:
        """Return immutable plan-owned step, lowered, and seed identities."""
        owned = {ServerPlanRefId(ref_id) for ref_id in self._step_ref_ids}
        owned.update(ServerPlanRefId(ref_id) for ref_id in self.seeded_constants)
        pending = [*self._steps, *self._semantic_plan_builder.steps_snapshot()]
        while pending:
            step = pending.pop()
            owned.update(step.declared_lowered_ref_ids())
            children = step.result_owned_children()
            owned.update(ServerPlanRefId(child.ref_id) for child in children)
            pending.extend(children)
        return frozenset(owned)

    def owned_steps_snapshot(self: BaseServerPlan) -> tuple[ServerPlanStep, ...]:
        """Return immutable references to the currently registered plan steps."""
        steps = [*self._steps, *self._semantic_plan_builder.steps_snapshot()]
        unique: dict[ServerPlanRefId, ServerPlanStep] = {}
        pending = list(steps)
        while pending:
            step = pending.pop(0)
            unique[ServerPlanRefId(step.ref_id)] = step
            pending.extend(step.result_owned_children())
        return tuple(unique.values())

    def _speculative_publication_correction_recipe(
        self: BaseServerPlan,
        envelope: SpeculativePublicationCorrectionEnvelope,
        completed: Mapping[str, object],
    ) -> SpeculativePublicationCorrectionRecipe:
        """Return the one immutable publication recipe retained by this plan."""
        intents = tuple(step for step in self._steps if isinstance(step, SpeculativePublicationSourceContract))
        if len(intents) != 1:
            msg = "A speculative publication correction requires exactly one commit intent"
            raise RuntimeError(msg)
        return SpeculativePublicationCorrectionRecipe.from_intent(
            intents[0],
            seeded=self.seeded_constants,
            authoritative_current_tip_revision_id=envelope.current_tip_revision_id,
            completed=completed,
        )

    def _build_speculative_publication_correction_plan(
        self: BaseServerPlan,
        recipe: SpeculativePublicationCorrectionRecipe,
        envelope: SpeculativePublicationCorrectionEnvelope,
    ) -> BaseServerPlan:
        """Rebuild the corrected publication and its affected semantic continuation."""
        correction_plan = self._create_fresh()
        correction_plan.seeded_constants.update(self.seeded_constants)
        correction_plan._explicit_versioning_domain = self._explicit_versioning_domain
        correction_plan._versioned_read_context_binding = self._versioned_read_context_binding

        publication_index = next(
            (index for index, step in enumerate(self._steps) if step.ref_id == recipe.ref_id),
            None,
        )
        if publication_index is None:
            raise RuntimeError("The publication correction recipe does not belong to this plan")
        prefix_steps = self._steps[:publication_index]
        prefix_refs = {str(step.ref_id) for step in prefix_steps}
        prefix_hints = dict(recipe.completed_sql_hints)
        for step in prefix_steps:
            hints = step.cte_publication_contract().column_type_hints
            if hints is not None and hints.has_any():
                prefix_hints.setdefault(str(step.ref_id), hints)
        for ref_id, value in recipe.completed_bindings:
            root_ref = ref_id.partition(".")[0]
            if not any(root_ref == prefix or root_ref.startswith(prefix + "_") for prefix in prefix_refs):
                continue
            correction_plan.seeded_constants[ServerPlanRefId(ref_id)] = value
            binding_hints = prefix_hints.get(ref_id, prefix_hints.get(root_ref))
            if binding_hints is not None and isinstance(value, Mapping):
                correction_plan.seeded_constants.declare_sql_hints(
                    ref_id,
                    binding_hints.filtered(set(value)).require_complete(tuple(value)),
                )

        from impl.common.l2070_server_plan.steps.collect_results import StaticValueAfterDepsStep

        authoritative_ref = ServerPlanRefId(f"{recipe.ref_id}__authoritative_correction")
        authoritative_recipe = replace(recipe, ref_id=authoritative_ref)
        correction_plan.add_step(authoritative_recipe.build_intent(envelope))
        correction_plan.add_step(
            StaticValueAfterDepsStep(
                recipe.ref_id,
                recipe.revision_id,
                frozenset({str(authoritative_ref)}),
                publish_literal_relation=True,
            )
        )
        for original in self._steps[publication_index + 1 :]:
            restored = copy(original)
            restored._publication_gate_requirement = None
            correction_plan.add_step(restored)

        continuation_roots = {
            str(recipe.ref_id),
            *(str(step.ref_id) for step in self._steps[publication_index + 1 :]),
        }
        for name, ref_id in self._returns.items():
            if ref_id.partition(".")[0] not in continuation_roots:
                continue
            correction_plan._returns[name] = ref_id
            variant = self._return_variants.get(name)
            if variant is not None:
                correction_plan._return_variants[name] = variant
            type_hint = self._return_type_hints.get(name)
            if type_hint is not None:
                correction_plan._return_type_hints[name] = type_hint
            if not name.startswith(("__internal_", "__prereq_")):
                correction_plan._semantic_plan_builder.add_return(name, ServerPlanRefId(ref_id))
        return correction_plan

    def _merge_speculative_first_request_results(
        self: BaseServerPlan,
        miss: ExecutorOwnedSpeculationMiss,
        correction_results: PlanResults,
    ) -> PlanResults:
        """Preserve caller-visible values completed before a speculation miss."""
        first_request_resolved = dict(miss.first_request_resolved())
        for ref_id in self._returns.values():
            root_ref = ref_id.partition(".")[0]
            if root_ref in first_request_resolved:
                continue
            for suffix in ("write", "raw"):
                candidate_ref = f"{root_ref}.{suffix}"
                if candidate_ref in first_request_resolved:
                    first_request_resolved[root_ref] = first_request_resolved[candidate_ref]
                    break
        first_request_results = self._resolve_returns(first_request_resolved).as_dict()
        merged = first_request_results
        merged.update(correction_results.as_dict())
        missing_returns = tuple(name for name in self._returns if name not in merged)
        if missing_returns:
            msg = f"Speculation correction lost declared plan returns {missing_returns!r}"
            raise RuntimeError(msg)
        return PlanResults(merged)

    def _replace_speculative_publication_facts(
        self: BaseServerPlan,
        recipe: SpeculativePublicationCorrectionRecipe,
        envelope: SpeculativePublicationCorrectionEnvelope,
    ) -> None:
        """Replace selected connection facts with authoritative guard evidence."""
        txn = self._txn
        if not isinstance(txn, _SpeculativePublicationFactTarget):
            raise TypeError("Speculative publication correction requires a typed fact ledger")
        touched, non_insert, deleted = recipe.corrected_fact_sets(envelope)
        touched_names = frozenset(SqlTableName(name) for name in touched)
        non_insert_names = frozenset(SqlTableName(name) for name in non_insert)
        deleted_names = frozenset(SqlTableName(name) for name in deleted)
        txn._replace_exact_connection_speculative_publish_facts(
            envelope.selected_staged_commit_ids,
            touched_table_names=touched_names,
            non_insert_table_names=non_insert_names,
            deleted_table_names=deleted_names,
        )
        if recipe.scope_kind == "connection_scoped":
            txn._record_missing_connection_scoped_speculative_publish_facts(
                envelope.selected_staged_commit_ids,
                touched_table_names=touched_names,
                non_insert_table_names=non_insert_names,
                deleted_table_names=deleted_names,
            )

    def _append_speculative_publication_rtt_audit(
        self: BaseServerPlan,
        correction_plan: BaseServerPlan,
        *,
        first_request_receipt: NativePipelineExecutionReceipt | None = None,
    ) -> None:
        """Append one correction request to plan and flush accounting."""
        correction = correction_plan.get_rtt_audit()
        if correction is None:
            return
        first = self._last_rtt_audit
        if first is None:
            self._last_rtt_audit = correction
            return

        def _sum_counts(left: Mapping[str, int], right: Mapping[str, int]) -> dict[str, int]:
            combined = dict(left)
            for key, value in right.items():
                combined[key] = combined.get(key, 0) + value
            return combined

        steps = dict(first.steps)
        for ref_id, correction_step in correction.steps.items():
            prior_step = steps.get(ref_id)
            steps[ref_id] = (
                correction_step
                if prior_step is None
                else ServerPlanStepRttAudit(
                    ref_id=prior_step.ref_id,
                    step_type=prior_step.step_type,
                    rw=prior_step.rw,
                    round_trips=prior_step.round_trips + correction_step.round_trips,
                )
            )
        self._last_rtt_audit = ServerPlanRttAudit(
            mode="speculative_publication_correction",
            total_round_trips=first.total_round_trips + correction.total_round_trips,
            driver_round_trips=first.driver_round_trips + correction.driver_round_trips,
            portable_min_db_statements=(first.portable_min_db_statements + correction.portable_min_db_statements),
            backend_attainable_min_db_statements=(
                first.backend_attainable_min_db_statements + correction.backend_attainable_min_db_statements
            ),
            actual_db_statements_executed=(first.actual_db_statements_executed + correction.actual_db_statements_executed),
            by_operation_kind=_sum_counts(first.by_operation_kind, correction.by_operation_kind),
            by_rw=_sum_counts(first.by_rw, correction.by_rw),
            steps=steps,
        )
        if first_request_receipt is not None:
            from l2070_batching.execution_receipt import BackendExecutionReceipt
            from l2070_batching.flush_counter import (
                get_flush_tracker,
                replace_last_flush_execution_receipt,
            )

            tracker = get_flush_tracker()
            if tracker is not None and len(tracker.execution_receipts) == 1:
                current = tracker.execution_receipts[-1]
                replace_last_flush_execution_receipt(
                    BackendExecutionReceipt(
                        driver_round_trips=(first_request_receipt.flush_count + correction.driver_round_trips),
                        sql_statement_count=(first_request_receipt.statement_count + correction.actual_db_statements_executed),
                        sql_group_count=(first_request_receipt.sql_group_count + correction.by_operation_kind.get("sql_group", 0)),
                        result_set_count=current.result_set_count,
                        transaction_control_count=(
                            first_request_receipt.transaction_control_count + correction.by_operation_kind.get("transaction_control", 0)
                        ),
                        results=current.results,
                        application_results=current.application_results,
                    ),
                )

    def _execute_speculative_publication_correction(
        self: BaseServerPlan,
        recipe: SpeculativePublicationCorrectionRecipe,
        envelope: SpeculativePublicationCorrectionEnvelope,
    ) -> PlanResults:
        """Execute one isolated correction on the current transaction and connection."""
        correction_plan = self._build_speculative_publication_correction_plan(recipe, envelope)
        try:
            return correction_plan._execute_new_pipeline()
        finally:
            self._append_speculative_publication_rtt_audit(correction_plan)

    async def _execute_speculative_publication_correction_async(
        self: BaseServerPlan,
        recipe: SpeculativePublicationCorrectionRecipe,
        envelope: SpeculativePublicationCorrectionEnvelope,
    ) -> PlanResults:
        """Execute one isolated asynchronous correction on the current transaction and connection."""
        correction_plan = self._build_speculative_publication_correction_plan(recipe, envelope)
        try:
            return await correction_plan._execute_new_pipeline_async()
        finally:
            self._append_speculative_publication_rtt_audit(correction_plan)

    def _execute_now(self: BaseServerPlan) -> PlanResults:
        if self._system_authority_fingerprint_only or (
            isinstance(self._txn, _SystemAuthorityPlanningTarget) and self._txn._system_authority_planning_only
        ):
            raise RuntimeError("System-authority fingerprint plans cannot execute")
        with self._execution_scope(sink="BaseServerPlan.execute()"):
            if not self._steps:
                return self._resolve_returns(self._build_initial_resolved_from_seeded_constants())
            try:
                return self._execute_new_pipeline()
            except ExecutorOwnedSpeculationMiss as miss:
                try:
                    corrected = miss.correction_adapter().correct_sync(self, miss)
                    if not isinstance(corrected, PlanResults):
                        raise TypeError("Speculation correction must return PlanResults")
                    return corrected
                except ExecutorOwnedSpeculationMiss as repeated_miss:
                    raise RuntimeError(miss.repeated_miss_message()) from repeated_miss

    async def _execute_impl_async(self: BaseServerPlan) -> PlanResults:
        if self._system_authority_fingerprint_only or (
            isinstance(self._txn, _SystemAuthorityPlanningTarget) and self._txn._system_authority_planning_only
        ):
            raise RuntimeError("System-authority fingerprint plans cannot execute")
        with self._execution_scope(sink="BaseServerPlan.execute_async()"):
            if not self._steps and self._prepared_physical_execution is None:
                return self._resolve_returns(self._build_initial_resolved_from_seeded_constants())
            try:
                return await self._execute_new_pipeline_async()
            except ExecutorOwnedSpeculationMiss as miss:
                try:
                    corrected = await miss.correction_adapter().correct_async(self, miss)
                    if not isinstance(corrected, PlanResults):
                        raise TypeError("Speculation correction must return PlanResults")
                    return corrected
                except ExecutorOwnedSpeculationMiss as repeated_miss:
                    raise RuntimeError(miss.repeated_miss_message()) from repeated_miss

    @pure_lazy
    def execute_lazy(self: BaseServerPlan) -> LazyResult[PlanResults]:
        """Return a lazy terminal for executing the entire plan."""
        return _ServerPlanExecutionLazyContext(self).queue_single(
            LazyOperation[PlanResults](
                op="execute",
                payload=LazyQueryPayload(self),
            ),
        )

    @legacy_sync
    def execute(self: BaseServerPlan) -> PlanResults:
        """Execute the entire plan via the new ServerPlanStep pipeline."""
        raise AssertionError("legacy_sync should delegate to execute_lazy()")

    @legacy_async
    async def execute_async(self: BaseServerPlan) -> PlanResults:
        """Execute the plan asynchronously via the new ServerPlanStep pipeline."""
        raise AssertionError("legacy_async should delegate to execute_lazy()")

    def _create_fresh(self: BaseServerPlan) -> BaseServerPlan:
        """Create a fresh plan with the same txn and session_id."""
        fresh = BaseServerPlan(
            self._txn,
            session_id=self._session_id,
            backend_profile=self._backend_profile,
        )
        fresh._runtime_services = self._runtime_services
        return fresh

    def _next_ref(self: BaseServerPlan) -> ServerPlanRefId:
        """Generate the next step reference ID."""
        return self._semantic_plan_builder.allocate_ref(kind="step")

    def _allocate_ref_id(self: BaseServerPlan, kind: str) -> ServerPlanRefId:
        """Monotonic ref-id allocator shared across step / seed / output kinds.

        Invoked by :func:`_internal.ref_allocation.allocate_ref_id`. Exists
        to ensure a single counter is used across all ref kinds within a plan
        so ref-ids never collide across kinds (§12.14).
        """
        return self._semantic_plan_builder.allocate_ref(kind=kind)

