    def _add_server_step(
        self: BaseServerPlan,
        step: ServerPlanStep,
        model_cls: type[Any] | None = None,
        *,
        variant: ServerRefVariant,
    ) -> ServerRef[Any]: ...

    @overload
    def _add_server_step(
        self: BaseServerPlan,
        step: ServerPlanStep,
        model_cls: type[Any] | None = None,
    ) -> ServerRef[Any]: ...

    def _add_server_step(
        self: BaseServerPlan,
        step: ServerPlanStep,
        model_cls: type[R] | None = None,
        *,
        variant: ServerRefVariant = "scalar",
    ) -> ServerRef[Any]:
        """Add a pre-constructed ServerPlanStep to the plan.

        Args:
            step: The step to add (must have ref_id set)
            model_cls: Model class for the ServerRef (for type inference)

        Returns:
            ServerRef to reference this step's result
        """
        step = _localize_planless_seed_refs(self, cast("ServerPlanStep[Any]", step))
        projected_values = step.literal_projection_values()

        for field_name, value in projected_values.items():
            projection_ref = ServerPlanRefId(f"{step.ref_id}.{field_name}")
            self.seeded_constants[projection_ref] = value
        self._semantic_plan_builder.add_step(step)
        if not step.is_read_only():
            self._has_write_step = True
        return ServerRefs.from_step(self, step.ref_id, variant=variant, type_hint=model_cls)

    def pending_observation_refs(self: BaseServerPlan) -> frozenset[ServerPlanRefId]:
        """Capture producers that a subsequently queued terminal must observe."""
        return frozenset(step.ref_id for step in self._steps)

    def add_resolved_runtime_input(self: BaseServerPlan, value: object) -> ServerPlanRefId:
        """Bind an earlier flush result as runtime input to the next flush."""
        ref_id = self._semantic_plan_builder.allocate_ref(kind="seed")
        self._semantic_plan_builder.add_runtime_input(ref_id, value)
        return ref_id

    def _seed_speculation_correction_prefix(
        self: BaseServerPlan,
        source: BaseServerPlan,
        completed: Mapping[str, Any],
        *,
        omitted_refs: frozenset[str],
    ) -> None:
        """Import completed bindings into an isolated speculation correction."""
        self.seeded_constants.update(source.seeded_constants)
        raw_hints = completed.get("__batch_sql_hints_by_ref_id")
        for ref_id, value in completed.items():
            if ref_id == "__batch_sql_hints_by_ref_id" or ref_id.partition(".")[0] in omitted_refs:
                continue
            self.seeded_constants[ServerPlanRefId(ref_id)] = value
        if not isinstance(raw_hints, dict):
            return
        for ref_id, hints in raw_hints.items():
            value = completed.get(ref_id)
            if not isinstance(ref_id, str) or ref_id.partition(".")[0] in omitted_refs:
                continue
            columns: tuple[str, ...] = ()
            if isinstance(value, dict):
                columns = tuple(value)
            elif isinstance(value, list) and value and isinstance(value[0], dict):
                columns = tuple(value[0])
                for column, column_value in value[0].items():
                    self.seeded_constants[ServerPlanRefId(f"{ref_id}.{column}")] = column_value
            if columns:
                self.seeded_constants.declare_sql_hints(
                    ref_id,
                    hints.filtered(set(columns)).require_complete(columns),
                )

    def producer_result_cardinality(self: BaseServerPlan, ref_id: ServerPlanRefId) -> Cardinality | None:
        """Return the cardinality for a plan-owned producer."""
        producer = self.producer_step(ref_id)
        return None if producer is None else producer.result_cardinality()

    def producer_step(self: BaseServerPlan, ref_id: ServerPlanRefId) -> ServerPlanStep[Any] | None:
        """Return the plan-owned producer for an exact symbolic ref."""
        return next((step for step in self._steps if step.ref_id == ref_id), None)

    def producer_dependency_closure(
        self: BaseServerPlan,
        ref_ids: frozenset[ServerPlanRefId],
    ) -> frozenset[ServerPlanRefId]:
        """Return the structural producer closure for plan-owned refs."""
        return frozenset(ServerPlanRefId(ref_id) for ref_id in self._expand_ref_closure({str(ref_id) for ref_id in ref_ids}))

    def add_filtered_projection_intent[T: DatabaseObjectRow, TValue](
        self: BaseServerPlan,
        model_cls: type[T],
        predicate: Expression[bool, T],
        selected_field: Field[TValue, T],
    ) -> StepRef[Sequence[T]]:
        """Publish a filtered field projection without an execution terminal."""
        query = self.query(model_cls).filter(predicate)
        query_spec = replace(
            query.to_query_spec(),
            select_columns=[selected_field],
            select_column_tables=(None,),
            preserve_non_join_projection=True,
        )
        return self.add_projection_query_intent(model_cls, query_spec)

    def add_projection_query_intent[T: DatabaseObjectRow](
        self: BaseServerPlan,
        model_cls: type[T],
        query_spec: object,
    ) -> StepRef[Sequence[T]]:
        """Publish a projection query as a typed plan-owned intent."""
        from impl.common.l2070_server_plan.steps.intent_query import (
            QueryExecuteIntent,
            _QueryExecuteConfig,
        )

        step = QueryExecuteIntent(
            ref_id=ServerPlanRefId(self._next_ref()),
            model_cls=model_cls,
            config=_QueryExecuteConfig(
                query_spec=query_spec,
                raw_mode=True,
                after_refs=self.pending_observation_refs(),
            ),
        )
        return self.add_step(step)

    def add_step[R](
        self: BaseServerPlan,
        step: ServerPlanStep[R],
    ) -> StepRef[R]:
        """Add a typed step to the plan.

        Returns a ``StepRef[R]`` that preserves the step's result type.
        This is the preferred API for plan-centric builders.

        Raises RuntimeError if the transaction is no longer active.
        """
        if not (_is_read_or_write_transaction(self._txn) and self._txn.is_cancelled and step.permits_cancelled_transaction_execution()):
            self._check_transaction_active()
        step = cast("ServerPlanStep[R]", _localize_planless_seed_refs(self, cast("ServerPlanStep[Any]", step)))
        try:
            hook_registry = object.__getattribute__(step, "_hook_registry")
        except AttributeError:
            hook_registry = None
        if hook_registry is not None:
            self.set_auto_api_hook_registry(hook_registry)
            self._captured_hook_runtime_services = self._runtime_services
            step = copy(step)
            object.__setattr__(step, "_hook_registry", None)
        self._semantic_plan_builder.add_step(step)
        if not step.is_read_only():
            self._has_write_step = True
        return StepRef(self, step.ref_id)

    def publish_lazy_result(self: BaseServerPlan, ref_id: ServerPlanRefId | str) -> LazyResult[Any]:
        """Publish a lazy terminal bound to an existing step ref."""
        return self._flush_ctx.publish_lazy_result(ServerPlanRefId(ref_id))

    # Grammar lazy terminals live in impl.common.l2070_server_plan.plan_helpers.


class _ServerPlanExecutionLazyContext(ExecutionContext):
    """Resolve deferred ``BaseServerPlan.execute_lazy()`` terminals."""

    def __init__(
        self: _ServerPlanExecutionLazyContext,
        plan: BaseServerPlan,
    ) -> None:
        self._plan = plan

    def queue_single[T](
        self: _ServerPlanExecutionLazyContext,
        operation: LazyOperation[T],
        pre_populated: T | None = None,
    ) -> LazyResult[T]:
        return LazyResult(operation, self, pre_populated)

    def queue_sequence(
        self: _ServerPlanExecutionLazyContext,
        operation: LazyOperation[list[Any]],
    ) -> NoReturn:
        del operation
        msg = "server plan execution lazy context only supports LazyResult terminals"
        raise NotImplementedError(msg)

    def execute_sync(
        self: _ServerPlanExecutionLazyContext,
        result: LazyResult[PlanResults] | LazySeq[PlanResults],
    ) -> None:
        lazy_result = _require_server_plan_execution_lazy_result(result)
        _validate_base_server_plan_operation(lazy_result._operation, self._plan)
        lazy_result._set_resolved(self._plan._execute_now())

    async def execute_async(
        self: _ServerPlanExecutionLazyContext,
        result: LazyResult[PlanResults] | LazySeq[PlanResults],
    ) -> None:
        lazy_result = _require_server_plan_execution_lazy_result(result)
        _validate_base_server_plan_operation(lazy_result._operation, self._plan)
        lazy_result._set_resolved(await self._plan._execute_impl_async())


def _require_server_plan_execution_lazy_result(
    result: LazyResult[PlanResults] | LazySeq[PlanResults],
) -> LazyResult[PlanResults]:
    if isinstance(result, LazyResult):
        return result
    msg = f"Expected LazyResult for server plan execution, got {type(result).__name__}"
    raise TypeError(msg)


def _validate_base_server_plan_operation(
    operation: LazyOperation[PlanResults],
    expected_plan: BaseServerPlan,
) -> None:
    payload = operation.payload
    if not isinstance(payload, LazyQueryPayload):
        msg = f"Expected LazyQueryPayload for ServerPlan execution, got {type(payload).__name__}"
        raise TypeError(msg)
    plan = _require_base_server_plan(payload.query_spec)
    if plan is not expected_plan:
        msg = "ServerPlan execution payload does not match its lazy context"
        raise RuntimeError(msg)


def _require_base_server_plan(value: object) -> BaseServerPlan:
    if isinstance(value, BaseServerPlan):
        return value
    msg = f"Expected BaseServerPlan, got {type(value).__name__}"
    raise TypeError(msg)


