class BaseGraphTraversalBuilder(GraphTraversalBuilder[T]):  # pyright: ignore[reportInvalidTypeArguments]
    """Base implementation of GraphTraversalBuilder for ServerPlan."""

    def __init__(
        self,
        plan: BaseServerPlan,
        graph_id: SysId,
        revision_id: object | None,
        revision_ref_id: ServerPlanRefId | None,
        start_node_id: SysId | None,
        start_node_ref: ScalarServerRef[SysId] | None,
        start_node_ids_ref: ScalarSequenceServerRef[SysId] | None,
        node_type: type[T],
        edge_type: type[Any],
        graph_type: type[Any],
        direction: str,
        max_depth: int,
    ) -> None:
        """Initialize the traversal builder."""
        self._plan = plan
        self._graph_id = graph_id
        self._revision_id = revision_id
        self._revision_ref_id = revision_ref_id
        self._start_node_id = start_node_id
        self._start_node_ref = start_node_ref
        self._start_node_ids_ref = start_node_ids_ref
        self._node_type = node_type
        self._edge_type = edge_type
        self._graph_type = graph_type
        self._direction = direction
        self._max_depth = max_depth
        self._min_depth: int = 1
        self._limit: int | None = None
        self._filter_exprs: list[Expression] = []

    def filter(
        self: BaseGraphTraversalBuilder[T],
        expression: Expression,
    ) -> BaseGraphTraversalBuilder[T]:
        """Add a filter on traversal results."""
        self._filter_exprs.append(expression)
        return self

    def min_depth(
        self: BaseGraphTraversalBuilder[T],
        depth: int,
    ) -> BaseGraphTraversalBuilder[T]:
        """Set minimum traversal depth."""
        self._min_depth = depth
        return self

    def limit(
        self: BaseGraphTraversalBuilder[T],
        count: int,
    ) -> BaseGraphTraversalBuilder[T]:
        """Limit number of results."""
        self._limit = count
        return self

    def execute_later(self: BaseGraphTraversalBuilder[T]) -> ObjectSequenceServerRef[T]:
        """Queue traversal for plan execution."""
        from impl.common.l9700_sql_graph_query.steps.graph_traverse import (
            GraphTraversalApiStep,
            _GraphTraversalApiConfig,
        )

        ref_id = self._plan._next_ref()
        step = GraphTraversalApiStep(
            ref_id,
            _GraphTraversalApiConfig(
                graph_id=self._graph_id,
                revision_id=self._revision_id,
                revision_ref_id=self._revision_ref_id,
                start_node_id=self._start_node_id,
                start_node_ref=self._start_node_ref,
                start_node_ids_ref=self._start_node_ids_ref,
                node_type=self._node_type,
                edge_type=self._edge_type,
                graph_type=self._graph_type,
                direction=self._direction,
                max_depth=self._max_depth,
                min_depth=self._min_depth,
                limit=self._limit,
                filter_exprs=list(self._filter_exprs),
            ),
            requires_visibility_guard=True,
        )
        return self._plan._add_server_step(step, self._node_type, variant="object_sequence")

