@pure_lazy
def prerequisite_base_ref_id(ref_id: ServerPlanRefId) -> str:
    """Return the producing base ref for a prerequisite-facing ref id."""
    return ref_id.split(".", 1)[0]


def is_prerequisite_step_ref_id(ref_id: ServerPlanRefId) -> bool:
    """Return whether a prerequisite ref id names a planner step result."""
    return prerequisite_base_ref_id(ref_id).startswith("step_")


def is_prerequisite_seed_ref_id(ref_id: ServerPlanRefId) -> bool:
    """Return whether a prerequisite ref id names a seeded constant."""
    return prerequisite_base_ref_id(ref_id).startswith("seed_")


@dataclass(frozen=True, slots=True)
class PlanPrerequisiteProjection:
    """Projection exported from an imported prerequisite ref."""

    projected_ref_id: str
    source_ref_id: str
    field_name: str
    role: str

    @classmethod
    def from_projected_ref_id(cls, projected_ref_id: str) -> PlanPrerequisiteProjection | None:
        """Build a projection from an explicit dotted ref id."""
        if "." not in projected_ref_id:
            return None
        source_ref_id, field_name = projected_ref_id.split(".", 1)
        return cls(
            projected_ref_id=projected_ref_id,
            source_ref_id=source_ref_id,
            field_name=field_name,
            role=_projection_role_for_field_name(field_name),
        )

    @classmethod
    def from_projection_kind(
        cls,
        *,
        projected_ref_id: str,
        source_ref_id: str,
        kind: str,
    ) -> PlanPrerequisiteProjection | None:
        """Build a projection from a semantic prerequisite projection kind."""
        field_name = _projection_field_name(kind)
        if field_name is None:
            return None
        return cls(
            projected_ref_id=projected_ref_id,
            source_ref_id=source_ref_id,
            field_name=field_name,
            role=kind,
        )

    def scalar_ref(self) -> ScalarServerRef[Any]:
        """Return the ServerRef used by consumers of this projection."""
        return ScalarServerRef[Any](
